          <div style="font-size:11px;color:${totalSel ? '#fca5a5' : '#64748b'};font-weight:${totalSel ? '700' : '400'}">
            ${totalSel ? `${totalSel} item${totalSel !== 1 ? 's' : ''} seleccionado${totalSel !== 1 ? 's' : ''}` : 'Selecciona items para continuar'}
          </div>
