    if (fab.style.display === 'none' || !fab.style.display) {
      // reaparece con "pop" (minimizar el pedido → burbuja flotante)
      fab.classList.remove('fab-pop'); void fab.offsetWidth; fab.classList.add('fab-pop');
    }
