  async function _renderProvPedidos() {
    const id = S.provSelId;
    const cont = $('provTabPedidos');
    if (!cont) return;
    cont.innerHTML = `
      <div class="flex items-center justify-between mb-3">
        <h4 class="font-semibold text-sm text-slate-300">🛒 Pedidos de compra</h4>
        <button class="btn-primary text-xs px-3 py-1.5" onclick="MOS.abrirModalPedido('${id}')">+ Nuevo pedido</button>
      </div>
      <div id="listPedidos" class="text-sm text-slate-400"></div>
    `;
    // Render desde cache primero
    if (S.provPedidos[id]) {
      renderPedidos(S.provPedidos[id]);
    } else {
      $('listPedidos').textContent = 'Cargando...';
      try {
        const r = await API.get('getPedidos', { idProveedor: id });
        S.provPedidos[id] = Array.isArray(r) ? r : (r && r.data) || [];
        renderPedidos(S.provPedidos[id]);
      } catch(e) {
        $('listPedidos').innerHTML = `<p class="text-red-400">Error: ${e.message}</p>`;
      }
    }
  }

  function renderPagos(pagos) {
    const el = $('listPagos');
    if (!el) return;
    if (!pagos.length) { el.innerHTML = '<p class="text-slate-600">Sin pagos registrados</p>'; return; }
    const total = pagos.reduce((s, p) => s + parseFloat(p.monto || 0), 0);
    el.innerHTML = `<p class="text-xs text-slate-500 mb-2">Total: <span class="text-indigo-400 font-semibold">${fmtMoney(total)}</span></p>` +
      pagos.slice(-5).reverse().map(p => `
        <div class="flex justify-between items-center gap-2 py-1.5 border-b border-slate-800/50">
          <div class="min-w-0 flex-1">
            <span class="text-slate-300 text-xs">${fmtDate(p.fecha)}</span>
            ${p.numeroFactura ? `<span class="text-slate-500 ml-2 text-xs truncate">${p.numeroFactura}</span>` : ''}
          </div>
          <span class="font-semibold text-green-400 text-sm whitespace-nowrap shrink-0">${fmtMoney(p.monto)}</span>
        </div>
      `).join('');
  }

  function renderPedidos(pedidos) {
    const el = $('listPedidos');
    if (!el) return;
    if (!pedidos.length) { el.innerHTML = '<p class="text-slate-600">Sin pedidos registrados</p>'; return; }
    el.innerHTML = pedidos.slice(-5).reverse().map(p => {
      const badge = p.estado === 'BORRADOR' ? 'badge-gray' : p.estado === 'CONFIRMADO' ? 'badge-blue' : 'badge-green';
      return `<div class="flex justify-between items-center gap-2 py-1.5 border-b border-slate-800/50">
        <div class="min-w-0 flex-1">
          <div class="text-slate-300 text-xs truncate">${p.idPedido}</div>
          <div class="text-slate-500 text-[10px]">${fmtDate(p.fechaCreacion)}</div>
        </div>
        <div class="flex flex-col items-end gap-0.5 shrink-0">
          <span class="text-slate-300 text-sm whitespace-nowrap">${fmtMoney(p.montoEstimado)}</span>
          <span class="badge ${badge} text-[10px]">${p.estado}</span>
        </div>
      </div>`;
    }).join('');
  }

  // ── MODALS ──────────────────────────────────────────────────
  function openModal(id)  { const el = $(id); if (el) { el.classList.remove('hidden'); el.classList.add('open'); } }
  function closeModal(id) { const el = $(id); if (el) { el.classList.remove('open'); el.classList.add('hidden'); } }

  // ════════════════════════════════════════════════════════════
  // [v2.41.83] ADMIN AUTH MODAL — UNIVERSAL (las 3 apps usan esto)
  //
  // Uso:
  //   const auth = await pedirAuth({
  //     accion:        'VETAR_LIQUIDACION',
  //     refDocumento:  'idPersonal|fecha',
  //     contexto:      'Vetar día de Javier · 2026-05-19',
  //     tier:          2,                  // opcional; lo infiere del catálogo
  //     allowCache:    true                // default true
  //   });
  //   if (!auth) return; // user canceló o falló
  //   // → auth = { clave, validadoPor, idPersonal, nombre, rol, cacheHit }
  // ════════════════════════════════════════════════════════════
  const _AAM_CACHE_KEY = 'mos_admin_auth_cache_v1';
  const _AAM_TIER_TTL  = { 1: 10 * 60 * 1000, 2: 5 * 60 * 1000, 3: 0 };
  let _aamState = null;  // { resolve, accion, refDocumento, tier, value, t0 }
  let _aamCatalogo = null; // {ACCION: {tier, label}}

  function _aamLoadCatalogo() {
    if (_aamCatalogo) return Promise.resolve(_aamCatalogo);
    return API.get('getAuthCatalogo', {}).then(r => {
      // [v2.42.04 fix] API.get devuelve d.data — r ya es el catálogo, no envuelto
      _aamCatalogo = r || {};
      return _aamCatalogo;
    }).catch(() => ({}));
  }

  function _aamCacheGet(accion, tier) {
    if (!tier || _AAM_TIER_TTL[tier] === 0) return null;
    try {
      const raw = localStorage.getItem(_AAM_CACHE_KEY);
      if (!raw) return null;
      const cache = JSON.parse(raw);
      const entry = cache[accion];
      if (!entry) return null;
      if (Date.now() > entry.expires) {
        delete cache[accion];
        localStorage.setItem(_AAM_CACHE_KEY, JSON.stringify(cache));
        return null;
      }
      return entry;
    } catch(_) { return null; }
  }
  function _aamCacheSet(accion, tier, auth) {
    const ttl = _AAM_TIER_TTL[tier] || 0;
    if (!ttl) return;
    try {
      const raw = localStorage.getItem(_AAM_CACHE_KEY);
      const cache = raw ? JSON.parse(raw) : {};
      cache[accion] = {
        clave: auth.clave,
        validadoPor: auth.validadoPor,
        idPersonal: auth.idPersonal,
        nombre: auth.nombre,
        rol: auth.rol,
        tier: tier,
        expires: Date.now() + ttl
      };
      localStorage.setItem(_AAM_CACHE_KEY, JSON.stringify(cache));
    } catch(_){}
  }

  async function pedirAuth(opts) {
    opts = opts || {};
    const accion = String(opts.accion || 'GENERICA').toUpperCase();
    const allowCache = opts.allowCache !== false;
    await _aamLoadCatalogo();
    const catEntry = _aamCatalogo[accion] || { tier: 2, label: opts.accion };
    const tier = parseInt(opts.tier, 10) || catEntry.tier || 2;

    // ── Verificar cache ──
    if (allowCache) {
      const hit = _aamCacheGet(accion, tier);
      if (hit) {
        // Auditar cache_hit en bg (fire-and-forget)
        try {
          API.post('verificarClaveAdmin', {
            clave: hit.clave,
            accion: accion,
            refDocumento: opts.refDocumento || '',
            appOrigen: 'MOS',
            detalle: opts.contexto || '',
            tier: tier,
            cache_hit: 1,
            tiempo_verify_ms: 0,
            deviceId: (S.session && S.session.deviceId) || ''
          }).catch(() => {});
        } catch(_){}
        return Object.assign({}, hit, { cacheHit: true });
      }
    }

    return new Promise(resolve => {
      _aamState = {
        resolve, accion, tier,
        refDocumento: opts.refDocumento || '',
        contexto:     opts.contexto || '',
        value:        '',
        t0:           Date.now(),
        allowCache
      };
      _aamMostrar(catEntry.label || opts.accion, opts.contexto || '', tier);
    });
  }
  function _aamMostrar(label, contexto, tier) {
    const tit = document.getElementById('aamTitle');
    const sub = document.getElementById('aamSubtitle');
    const ctx = document.getElementById('aamContext');
    const sess = document.getElementById('aamSessionName');
    const tierBadge = document.getElementById('aamTierBadge');
    const msg = document.getElementById('aamMessage');
    if (tit) tit.textContent = label || 'Autorización requerida';
    if (sub) sub.textContent = 'Acción protegida · 8 dígitos';
    if (ctx) ctx.textContent = contexto || '';
    if (sess) sess.textContent = ((S.session && S.session.nombre) || '—') + ' (' + ((S.session && S.session.rol) || '?') + ')';
    if (tierBadge) {
      const tierLbl = tier === 1 ? 'Tier 1 · cache 10 min'
                    : tier === 2 ? 'Tier 2 · cache 5 min'
                    : 'Tier 3 · sin cache';
      tierBadge.textContent = tierLbl;
    }
    if (msg) { msg.className = 'aam-message hidden'; msg.textContent = ''; }
    _aamState.value = '';
    _aamRenderDots();
    const box = document.querySelector('#modalAdminAuth .aam-box');
    if (box) { box.classList.remove('shake', 'success'); }
    openModal('modalAdminAuth');
    try { _evalSfx && _evalSfx('open'); } catch(_){}
    // Focus hidden input para keyboard input
    setTimeout(() => {
      const inp = document.getElementById('aamHiddenInput');
      if (inp) inp.focus();
    }, 80);
    // Listener ESC
    document.addEventListener('keydown', _aamEscHandler, true);
  }
  function _aamEscHandler(e) {
    if (!_aamState) return;
    if (e.key === 'Escape') {
      e.stopImmediatePropagation();
      _aamCancelar();
    }
  }
  function _aamRenderDots() {
    const dots = document.querySelectorAll('#aamDots .aam-dot');
    const v = (_aamState && _aamState.value) || '';
    dots.forEach((d, i) => {
      d.classList.remove('filled', 'error', 'success');
      if (i < v.length) d.classList.add('filled');
    });
  }
  function _aamPress(digit) {
    if (!_aamState) return;
    if (_aamState.value.length >= 8) return;
    _aamState.value += String(digit);
    _aamRenderDots();
    try { _evalSfx && _evalSfx('tap'); } catch(_){}
    try { if (navigator.vibrate) navigator.vibrate(15); } catch(_){}
    if (_aamState.value.length === 8) {
      // Auto-confirmar al 8º dígito
      setTimeout(_aamConfirmar, 120);
    }
  }
  function _aamDelete() {
    if (!_aamState) return;
    if (!_aamState.value.length) return;
    _aamState.value = _aamState.value.slice(0, -1);
    _aamRenderDots();
    try { _evalSfx && _evalSfx('tap'); } catch(_){}
  }
  function _aamOnKey(e) {
    if (!_aamState) return;
    if (e.key === 'Backspace') { e.preventDefault(); _aamDelete(); return; }
    if (e.key === 'Enter') { e.preventDefault(); _aamConfirmar(); return; }
    if (/^[0-9]$/.test(e.key)) { e.preventDefault(); _aamPress(e.key); return; }
  }
  async function _aamConfirmar() {
    if (!_aamState) return;
    if (_aamState.value.length !== 8) {
      _aamMostrarError('Ingresa 8 dígitos');
      return;
    }
    const ico = document.getElementById('aamLockIcon');
    if (ico) ico.classList.add('spin');
    const t0 = _aamState.t0;
    const tiempo_verify_ms = Date.now() - t0;
    try {
      const r = await API.post('verificarClaveAdmin', {
        clave: _aamState.value,
        accion: _aamState.accion,
        refDocumento: _aamState.refDocumento,
        appOrigen: 'MOS',
        detalle: _aamState.contexto,
        tier: _aamState.tier,
        cache_hit: 0,
        tiempo_verify_ms: tiempo_verify_ms,
        deviceId: (S.session && S.session.deviceId) || ''
      });
      // [v2.42.00 fix] API.post devuelve d.data directamente — NO hay r.data anidado.
      // Bug histórico: el modal siempre mostraba "Clave incorrecta" porque buscaba
      // r.data.autorizado cuando r ya ERA el data desempaquetado.
      const d = r || {};
      if (ico) ico.classList.remove('spin');
      if (!d.autorizado) {
        _aamMostrarError(d.error || 'Clave incorrecta');
        return;
      }
      // Éxito
      try { _evalSfx && _evalSfx('success'); } catch(_){}
      try { if (navigator.vibrate) navigator.vibrate([20, 30, 40]); } catch(_){}
      document.querySelectorAll('#aamDots .aam-dot').forEach(dot => dot.classList.add('success'));
      const box = document.querySelector('#modalAdminAuth .aam-box');
      if (box) box.classList.add('success');
      const auth = {
        clave:       _aamState.value,
        validadoPor: d.validadoPor,
        idPersonal:  d.idPersonal,
        nombre:      d.nombre,
        rol:         d.rol,
        cacheHit:    false
      };
      if (_aamState.allowCache) {
        _aamCacheSet(_aamState.accion, _aamState.tier, auth);
      }
      const resolveFn = _aamState.resolve;
      setTimeout(() => {
        closeModal('modalAdminAuth');
        document.removeEventListener('keydown', _aamEscHandler, true);
        _aamState = null;
        resolveFn(auth);
      }, 500);
    } catch(e) {
      if (ico) ico.classList.remove('spin');
      _aamMostrarError('Error: ' + (e.message || e));
    }
  }
  // ════════════════════════════════════════════════════════════════════
  // [v2.42.04] HELPERS genéricos para reemplazar confirm/prompt nativos.
  // Cumplen regla feedback-modales-optimistas-modernos: backdrop blur,
  // animación scale entrada, beep al abrir, paleta MOS (slate + accent).
  // Drop-in:
  //    if (!confirm('texto')) return     →    if (!await _modalConfirm('texto')) return
  //    const v = prompt('label', def)    →    const v = await _modalPrompt('label', def)
  // Devuelven Promise — la función caller debe ser async.
  // ════════════════════════════════════════════════════════════════════
  function _modalConfirm(msg, opts) {
    opts = opts || {};
    return new Promise((resolve) => {
      const _esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
      const accent  = opts.danger ? 'danger' : (opts.warning ? 'warn' : 'primary');
      const icoMap  = { danger: '⚠', warn: '🟡', primary: '❓' };
      const titulo  = opts.titulo || (opts.danger ? 'Confirmar acción' : '¿Continuar?');
      const okTxt   = opts.okText || (opts.danger ? 'Sí, continuar' : 'Aceptar');
      const cancelTxt = opts.cancelText || 'Cancelar';
      const backdrop = document.createElement('div');
      backdrop.className = 'mos-modal-generic-backdrop';
      backdrop.innerHTML = `
        <div class="mos-modal-generic mos-modal-generic-${accent}" role="dialog" aria-modal="true">
          <div class="mos-modal-generic-head">
            <span class="mos-modal-generic-ico">${icoMap[accent]}</span>
            <strong>${_esc(titulo)}</strong>
            <button class="mos-modal-generic-close" data-cancel aria-label="Cerrar">✕</button>
          </div>
          <div class="mos-modal-generic-body">${(msg || '').split('\n\n').map(p => '<p>' + _esc(p).replace(/\n/g, '<br>') + '</p>').join('')}</div>
          <div class="mos-modal-generic-foot">
            <button class="mos-modal-generic-btn mos-modal-generic-btn-ghost" data-cancel>${_esc(cancelTxt)}</button>
            <button class="mos-modal-generic-btn mos-modal-generic-btn-ok mos-modal-generic-btn-${accent}" data-ok>${_esc(okTxt)}</button>
          </div>
        </div>`;
      const cerrar = (val) => {
        backdrop.classList.remove('is-open');
        setTimeout(() => { try { backdrop.remove(); } catch(_){} }, 200);
        resolve(val);
      };
      backdrop.addEventListener('click', (ev) => {
        const t = ev.target;
        if (t === backdrop || (t.closest && t.closest('[data-cancel]'))) cerrar(false);
        else if (t.closest && t.closest('[data-ok]')) {
          try { _finBeep?.(opts.danger ? 'warn' : 'success'); } catch(_){}
          cerrar(true);
        }
      });
      document.body.appendChild(backdrop);
      requestAnimationFrame(() => backdrop.classList.add('is-open'));
      try { _finBeep?.('tap'); } catch(_){}
      setTimeout(() => { try { backdrop.querySelector('[data-ok]')?.focus(); } catch(_){} }, 220);
    });
  }

  function _modalPrompt(label, defaultValue, opts) {
    opts = opts || {};
    return new Promise((resolve) => {
      const _esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
      const titulo = opts.titulo || 'Ingresar dato';
      const okTxt  = opts.okText || 'Aceptar';
      const ph     = opts.placeholder || '';
      const isLong = opts.textarea === true;
      const inputHtml = isLong
        ? `<textarea class="mos-modal-generic-input" rows="3" maxlength="${opts.maxlength || 240}" placeholder="${_esc(ph)}">${_esc(defaultValue || '')}</textarea>`
        : `<input type="${opts.inputType || 'text'}" inputmode="${opts.inputMode || ''}" maxlength="${opts.maxlength || ''}" class="mos-modal-generic-input" value="${_esc(defaultValue || '')}" placeholder="${_esc(ph)}" />`;
      const backdrop = document.createElement('div');
      backdrop.className = 'mos-modal-generic-backdrop';
      backdrop.innerHTML = `
        <div class="mos-modal-generic mos-modal-generic-primary" role="dialog" aria-modal="true">
          <div class="mos-modal-generic-head">
            <span class="mos-modal-generic-ico">✏</span>
            <strong>${_esc(titulo)}</strong>
            <button class="mos-modal-generic-close" data-cancel>✕</button>
          </div>
          <div class="mos-modal-generic-body">
            <label class="mos-modal-generic-label">${_esc(label || '')}</label>
            ${inputHtml}
          </div>
          <div class="mos-modal-generic-foot">
            <button class="mos-modal-generic-btn mos-modal-generic-btn-ghost" data-cancel>Cancelar</button>
            <button class="mos-modal-generic-btn mos-modal-generic-btn-ok mos-modal-generic-btn-primary" data-ok>${_esc(okTxt)}</button>
          </div>
        </div>`;
      const cerrar = (val) => {
        backdrop.classList.remove('is-open');
        setTimeout(() => { try { backdrop.remove(); } catch(_){} }, 200);
        resolve(val);
      };
      const getVal = () => {
        const i = backdrop.querySelector('.mos-modal-generic-input');
        return i ? String(i.value || '') : '';
      };
      backdrop.addEventListener('click', (ev) => {
        const t = ev.target;
        if (t === backdrop || (t.closest && t.closest('[data-cancel]'))) cerrar(null);
        else if (t.closest && t.closest('[data-ok]')) {
          try { _finBeep?.('success'); } catch(_){}
          cerrar(getVal());
        }
      });
      backdrop.addEventListener('keydown', (ev) => {
        if (ev.key === 'Enter' && !isLong) {
          try { _finBeep?.('success'); } catch(_){}
          cerrar(getVal());
        } else if (ev.key === 'Escape') cerrar(null);
      });
      document.body.appendChild(backdrop);
      requestAnimationFrame(() => backdrop.classList.add('is-open'));
      try { _finBeep?.('tap'); } catch(_){}
      setTimeout(() => {
        try { backdrop.querySelector('.mos-modal-generic-input')?.focus(); } catch(_){}
        try { backdrop.querySelector('.mos-modal-generic-input')?.select(); } catch(_){}
      }, 220);
    });
  }

  function _aamMostrarError(txt) {
    try { _evalSfx && _evalSfx('error'); } catch(_){}
    try { if (navigator.vibrate) navigator.vibrate([60, 50, 60]); } catch(_){}
    const msg = document.getElementById('aamMessage');
    if (msg) {
      msg.className = 'aam-message error';
      msg.textContent = '⚠ ' + txt;
    }
    document.querySelectorAll('#aamDots .aam-dot').forEach(dot => dot.classList.add('error'));
    const box = document.querySelector('#modalAdminAuth .aam-box');
    if (box) {
      box.classList.add('shake');
      setTimeout(() => box.classList.remove('shake'), 420);
    }
    setTimeout(() => {
      if (_aamState) {
        _aamState.value = '';
        _aamRenderDots();
        _aamState.t0 = Date.now(); // reset timer
      }
    }, 600);
  }
  function _aamCancelar() {
    if (!_aamState) return;
    const resolveFn = _aamState.resolve;
    closeModal('modalAdminAuth');
    document.removeEventListener('keydown', _aamEscHandler, true);
    _aamState = null;
    try { _evalSfx && _evalSfx('tap'); } catch(_){}
    resolveFn(null);
  }
  function _aamUsarCache() { /* placeholder — el cache se aplica antes del modal */ }

  function openEcoModal(app) {
    const eco = S._ecoData;
    const titleEl = $('ecoModalTitle');
    const bodyEl  = $('ecoModalBody');
    if (!titleEl || !bodyEl) return;

    // Si aún no llegaron datos (primera carga), esperar y reintentar
    if (!eco) {
      titleEl.textContent = app === 'wh' ? 'warehouseMos' : 'MosExpress';
      bodyEl.innerHTML = `<div class="flex items-center gap-3 py-4 text-slate-400 text-sm">
        <span class="dot-loading" style="width:10px;height:10px"></span>Cargando datos...</div>`;
      openModal('modalEcosistema');
      // Reintentar en 2s por si la llamada GAS aún está en vuelo
      setTimeout(() => {
        if (S._ecoData && $('modalEcosistema')?.classList.contains('open')) {
          closeModal('modalEcosistema');
          openEcoModal(app);
        }
      }, 2000);
      return;
    }

    const _fmt = n => new Intl.NumberFormat('es-PE', { minimumFractionDigits: 2 }).format(n || 0);
    const _dot = c => `<span class="inline-block w-2.5 h-2.5 rounded-full ${c === 'green' ? 'bg-green-400' : c === 'yellow' ? 'bg-yellow-400' : c === 'red' ? 'bg-red-400' : 'bg-slate-500'}"></span>`;

    // Paleta de colores para zonas (se repite si hay muchas)
    const ZONA_PALETA = [
      { bg: 'bg-indigo-900/60',  border: 'border-indigo-500/40',  badge: 'bg-indigo-500/20 text-indigo-300',  dot: 'bg-indigo-400' },
      { bg: 'bg-emerald-900/50', border: 'border-emerald-500/40', badge: 'bg-emerald-500/20 text-emerald-300', dot: 'bg-emerald-400' },
      { bg: 'bg-amber-900/40',   border: 'border-amber-500/40',   badge: 'bg-amber-500/20 text-amber-300',    dot: 'bg-amber-400'  },
      { bg: 'bg-rose-900/40',    border: 'border-rose-500/40',    badge: 'bg-rose-500/20 text-rose-300',      dot: 'bg-rose-400'   },
      { bg: 'bg-cyan-900/40',    border: 'border-cyan-500/40',    badge: 'bg-cyan-500/20 text-cyan-300',      dot: 'bg-cyan-400'   },
    ];

    if (app === 'me') {
      const d = eco.me;
      titleEl.innerHTML = `🛒 MosExpress &nbsp;${_dot(d?.color)}`;
      if (!d || d.error) {
        bodyEl.innerHTML = `<p class="text-red-400 text-sm">${d?.error || 'Sin datos'}</p>`;
      } else {
        // ── KPIs globales ──
        let html = `
          <div class="grid grid-cols-2 gap-3 mb-5">
            <div class="bg-slate-800 rounded-xl p-3">
              <div class="text-2xl font-bold text-white">${d.ventasHoy}</div>
              <div class="text-xs text-slate-400 mt-0.5">Ventas hoy</div>
            </div>
            <div class="bg-slate-800 rounded-xl p-3">
              <div class="text-2xl font-bold text-white">S/ ${_fmt(d.totalHoy)}</div>
              <div class="text-xs text-slate-400 mt-0.5">Total hoy · ${d.ultimaVenta}</div>
            </div>
          </div>`;

        // ── Zonas ──
        const zonas = d.zonas || [];
        if (zonas.length) {
          html += `<div class="text-xs text-slate-400 uppercase tracking-widest font-semibold mb-2">Por zona</div>
          <div class="space-y-2 mb-5">`;
          zonas.forEach((z, idx) => {
            const pal = ZONA_PALETA[idx % ZONA_PALETA.length];
            html += `
            <div class="rounded-xl border ${pal.bg} ${pal.border} p-3">
              <div class="flex items-center justify-between mb-2">
                <div class="flex items-center gap-2">
                  <span class="w-2 h-2 rounded-full ${pal.dot} inline-block"></span>
                  <span class="text-sm font-semibold text-slate-100">${z.zona}</span>
                </div>
                <span class="text-xs px-2 py-0.5 rounded-full ${pal.badge}">${z.ventas} venta${z.ventas !== 1 ? 's' : ''}</span>
              </div>
              <div class="flex items-center justify-between">
                <span class="text-lg font-bold text-white">S/ ${_fmt(z.total)}</span>
                <span class="text-xs text-slate-400">${z.ultimaVenta}</span>
              </div>
            </div>`;
          });
          html += `</div>`;
        }

        // ── Personal del día ──
        const personal = d.personal || [];
        const activos  = personal.filter(p => p.estado === 'activo');
        const cerrados = personal.filter(p => p.estado === 'cerrado');

        html += `<div class="text-xs text-slate-400 uppercase tracking-widest font-semibold mb-2">
          Personal hoy <span class="ml-1 text-slate-500 normal-case">(${personal.length} turno${personal.length !== 1 ? 's' : ''})</span>
        </div>`;

        if (!personal.length) {
          html += `<p class="text-xs text-slate-500 py-2">Sin registros hoy</p>`;
        } else {
          html += `<div class="space-y-1.5">`;
          // Activos primero
          personal.forEach(p => {
            const zonaPal = ZONA_PALETA[zonas.findIndex(z => z.zona === p.zona) % ZONA_PALETA.length] || ZONA_PALETA[0];
            const esActivo = p.estado === 'activo';
            html += `
            <div class="flex items-center gap-2.5 rounded-lg px-3 py-2 ${esActivo ? 'bg-slate-700/60' : 'bg-slate-800/40'}">
              <span class="inline-block w-2 h-2 rounded-full flex-shrink-0 ${esActivo ? 'bg-green-400' : 'bg-slate-500'}"></span>
              <div class="flex-1 min-w-0">
                <div class="text-sm text-slate-100 font-medium truncate">${p.nombre}</div>
                <div class="text-xs text-slate-400">${p.estacion}${p.zona && p.zona !== '—' ? ' · <span class="' + zonaPal.badge.split(' ')[1] + '">' + p.zona + '</span>' : ''}</div>
              </div>
              <div class="text-right flex-shrink-0">
                ${esActivo
                  ? `<span class="text-xs text-green-400 font-medium">Activo</span><div class="text-xs text-slate-500">desde ${p.desde}</div>`
                  : `<span class="text-xs text-slate-500">Cerró ${p.hasta || '—'}</span><div class="text-xs text-slate-600">abrió ${p.desde}</div>`
                }
              </div>
            </div>`;
          });
          html += `</div>`;
        }

        bodyEl.innerHTML = html;
      }
    } else {
      const d = eco.wh;
      titleEl.innerHTML = `🏭 warehouseMos &nbsp;${_dot(d?.color)}`;
      if (!d || d.error) {
        bodyEl.innerHTML = `<p class="text-red-400 text-sm">${d?.error || 'Sin datos'}</p>`;
      } else {
        const sesion = d.sesionActiva
          ? `<span class="text-green-300">${d.sesionActiva.usuario} (${d.sesionActiva.rol}) · desde ${d.sesionActiva.desde}</span>`
          : '<span class="text-slate-500">Ninguna activa</span>';
        bodyEl.innerHTML = `
          <div class="grid grid-cols-3 gap-3 mb-4">
            <div class="bg-slate-800 rounded-xl p-3">
              <div class="text-2xl font-bold text-white">${d.entradasHoy}</div>
              <div class="text-xs text-slate-400 mt-0.5">Entradas hoy</div>
            </div>
            <div class="bg-slate-800 rounded-xl p-3">
              <div class="text-2xl font-bold text-white">${d.salidasHoy}</div>
              <div class="text-xs text-slate-400 mt-0.5">Salidas hoy</div>
            </div>
            <div class="bg-slate-800 rounded-xl p-3">
              <div class="text-2xl font-bold ${d.stockCritico > 0 ? 'text-red-400' : 'text-white'}">${d.stockCritico}</div>
              <div class="text-xs text-slate-400 mt-0.5">Stock crítico</div>
            </div>
          </div>
          <div class="mb-1 text-xs text-slate-400 uppercase tracking-widest font-semibold">Última guía</div>
          <p class="text-sm text-slate-200 mb-4">${d.ultimaGuia || '—'}</p>
          <div class="mb-1 text-xs text-slate-400 uppercase tracking-widest font-semibold">Sesión activa</div>
          <p class="text-sm mb-0">${sesion}</p>`;
      }
    }
    openModal('modalEcosistema');
  }


  // [BLOCK 9 · 2026-08-12] saveConfig() y testConnection() ELIMINADAS junto con el modal #modalConfig que
  // las invocaba (index.html). Leían el input #cfgGasUrl y llamaban a API.setUrl(), que es un no-op desde
  // que la URL de GAS quedó fija en código; además referenciaban #bannerNoUrl, un banner que ya no existe.
  // Nada más las llamaba (solo los dos onclick del modal retirado). La Configuración viva es la vista `config`.

  // ── Product modal — helpers ────────────────────────────────
  let _prodTipo = 'normal';

  function setProdTipo(tipo, fromUser) {
    // tipo: 'normal' | 'envasable' | 'derivado' | 'presentacion'
    _prodTipo = tipo;
    // [424] pintar el botón activo del selector segmentado
    try {
      document.querySelectorAll('#modalProducto .prod-tipo-btn[data-tipo]').forEach(b => {
        b.classList.toggle('active', b.getAttribute('data-tipo') === tipo);
      });
    } catch (_) {}
    // Sincronizar checkboxes ocultos (compat con código que aún los lee)
    const cbPres = $('cbEsPresentacion');
    const cbDer  = $('cbEsDerivado');
    const cbEnv  = $('cbEsEnvasable');
    if (cbPres) cbPres.checked = (tipo === 'presentacion');
    if (cbDer)  cbDer.checked  = (tipo === 'derivado');
    if (cbEnv)  cbEnv.checked  = (tipo === 'envasable');
    // Mostrar / ocultar secciones
    $('prodSecDerivado')?.classList.toggle('hidden', tipo !== 'derivado');
    $('prodSecPresentacion')?.classList.toggle('hidden', tipo !== 'presentacion');
    if (tipo === 'derivado')     { _poblarEnvasablesSelect(); _prodDerivadoPreview(); }
    if (tipo === 'presentacion') _poblarBasesSelect();
    // [424] un GRANEL se compra por kilo → sugerir KGM (solo si el usuario lo eligió
    // y la unidad está en el default NIU; no pisa una elección deliberada previa).
    if (tipo === 'envasable' && fromUser) {
      const u = $('prodUnidad');
      if (u && (!u.value || u.value === 'NIU')) {
        u.value = 'KGM';
        const um = $('prodUnidadMedida'); if (um) um.value = 'KGM';
        try { toast('Granel: unidad puesta en KGM (kilo) — cámbiala si vendes por unidad', 'info'); } catch (_) {}
      }
    }
  }

  // [424] Extrae el peso implícito del nombre (500GR→0.5, 1KG→1, 5K→5, 250 GR→0.25).
  // Devuelve kilos o null. Sirve para el guardián y para sugerir la porción/precio.
  // [dueño 2026-07-14] Acepta KG/KGS/KILO/KILOS/K (kilos) y GR/GRS/G (gramos). El "K" o "KG"
  // deben ir pegados al número (5K, 5KG) para no confundir con palabras (PACK no lleva dígito antes).
  function _pesoDesdeNombre(nombre) {
    const s = String(nombre || '').toUpperCase();
    let m = s.match(/([0-9]+(?:[.,][0-9]+)?)\s*(?:KILOS?|KGS?|K)\b/);
    if (m) return parseFloat(m[1].replace(',', '.'));
    m = s.match(/([0-9]+(?:[.,][0-9]+)?)\s*GR?S?\b/);
    if (m) return parseFloat(m[1].replace(',', '.')) / 1000;
    return null;
  }

  // ═══════════════════════════════════════════════════════════════════════════════════════════
  // [pres-v1] PRESENTACIONES — helpers puros (nombre compuesto · código por factor · contenido auto).
  // La presentación = FACTOR sobre un producto NIU: pack (×N, factor>1) o fracción (÷N, factor<1).
  // Nombre = "BASE (del padre) · DESCRIPTOR". Código = prefijo + sufijo derivado del factor (uniforme,
  // parseable). Sin DOM: testeable en node. NO tocan dinero (solo arman etiquetas/códigos sugeridos).
  // ═══════════════════════════════════════════════════════════════════════════════════════════
  var _PRES_PACKS = { 2: 'Dúo', 3: 'Tripack', 6: 'Sixpack', 12: 'Docena' };
  var _PRES_FRACC = { 2: 'Media', 3: 'Tercio', 4: 'Cuarto', 6: 'Sexto', 8: 'Octavo' };

  // ¿el factor es una fracción exacta 1/N? → devuelve N, si no null.
  function _presDenominador(factor) {
    var f = parseFloat(factor) || 0;
    if (f <= 0 || f >= 1) return null;
    var inv = 1 / f, n = Math.round(inv);
    return (n >= 2 && Math.abs(inv - n) < 1e-6) ? n : null;
  }

  // [742] Etiqueta de peso para un factor sobre granel (base = 1 kg): 0.06 → "60gr" · 1.5 → "1.5kg".
  function _presPesoLbl(factor) {
    var f = parseFloat(factor) || 0;
    if (!(f > 0)) return '';
    if (f >= 1) return String(Math.round(f * 1000) / 1000).replace(/\.?0+$/, '') + 'kg';
    return Math.round(f * 1000) + 'gr';
  }
  // Descriptor sugerido a partir del factor (editable por el usuario). '' si es un factor "raro".
  // [742] esPeso=true (padre granel, fracción) → el descriptor ES el peso ("60gr"), no "1/60":
  // para un granel que se vende por kilo, la porción se piensa en gramos, no en divisores.
  function _presDescriptorSugerido(factor, esPeso) {
    var f = parseFloat(factor) || 0;
    if (esPeso && f > 0 && f < 1) return _presPesoLbl(f);
    if (f > 1 && Number.isInteger(f)) return _PRES_PACKS[f] || ('Pack x' + f);
    var n = _presDenominador(f);
    if (n) return _PRES_FRACC[n] || ('1/' + n);
    return esPeso ? _presPesoLbl(f) : '';
  }

  // Sufijo de código derivado del factor: pack ×N → "X"+N · fracción 1/N → "D"+N · otro → "F"+factor×1000.
  // Uniforme y unívoco (un factor ⇒ un sufijo). Ej: 3→X3 · 0.125→D8 · 0.25→D4 · 1.5→F1500.
  function _presCodigoSufijo(factor) {
    var f = parseFloat(factor) || 0;
    if (f <= 0) return '';
    if (f >= 1 && Number.isInteger(f)) return 'X' + f;
    var n = _presDenominador(f);
    if (n) return 'D' + n;
    return 'F' + Math.round(f * 1000);
  }

  // Formatea kg a etiqueta legible: >=1kg → "1.5 kg" (sin ceros) · <1kg → "250 g".
  function _presFmtContenidoKg(kg) {
    if (!(kg > 0)) return '';
    if (kg >= 1) return String(Math.round(kg * 1000) / 1000).replace(/\.?0+$/, '') + ' kg';
    return Math.round(kg * 1000) + ' g';
  }

  // Contenido de la presentación: pack → "3 un" · fracción → magnitud física del padre × factor ("250 g").
  // '' si es fracción y el padre no tiene magnitud parseable en el nombre.
  function _presContenidoAuto(padreDesc, factor) {
    var f = parseFloat(factor) || 0;
    if (f <= 0) return '';
    // [632 · feedback dueño con el chuño] pack sobre un GRANEL: el contenido son KILOS,
    // no unidades — "Pack x25 (25 kg)", jamás "(25 un)".
    var esGranelPadre = !!(_satState && _satState.padreGranel);
    if (f > 1) return (Number.isInteger(f) ? f : (Math.round(f * 100) / 100)) + (esGranelPadre ? ' kg' : ' un');
    // [742] un GRANEL se vende por kilo: su magnitud base ES 1 kg aunque el nombre no la
    // diga — antes acá salía '' y el modal pedía "escribe el contenido en el descriptor".
    var kgBase = esGranelPadre ? 1 : _pesoDesdeNombre(padreDesc);
    if (!kgBase) return '';
    return _presFmtContenidoKg(kgBase * f);
  }

  // Nombre compuesto: "BASE · DESCRIPTOR (CONTENIDO)". El " · " es también el punto de corte del adhesivo.
  function _presNombreCompuesto(padreDesc, descriptor, contenido) {
    var base = String(padreDesc == null ? '' : padreDesc).toUpperCase().replace(/\s+/g, ' ').trim();
    var d = String(descriptor == null ? '' : descriptor).trim();
    if (!d) return base;
    if (contenido) d = d + ' (' + contenido + ')';
    return base ? (base + ' · ' + d) : d;
  }

  // [424] Preview del derivado + GUARDIÁN contra el nombre. NUNCA bloquea (el nombre
  // también puede estar mal tipeado, decisión del dueño) — solo avisa en ámbar/rojo.
  function _prodDerivadoPreview() {
    if (_prodTipo !== 'derivado') return;
    const porcion = parseFloat($('prodFactorConvBase')?.value) || 0;
    const baseVal = $('prodCodigoProductoBase')?.value || '';
    const hint = $('prodPorcionHint');
    const prevWrap = $('prodDerivadoPreview');
    const prevTxt  = $('prodDerivadoPreviewTxt');
    const padre = (S.productos || []).find(p => (p.skuBase || p.idProducto) === baseVal);
    const unidadBase = padre ? _normalizarUnidad(padre.unidad || padre.Unidad || 'KGM') : 'kg';
    const uLbl = unidadBase === 'KGM' ? 'kg' : unidadBase;

    // Preview del efecto
    if (prevWrap && prevTxt) {
      if (porcion > 0 && padre) {
        prevTxt.innerHTML = `1 unidad consumirá <b class="text-emerald-300">${porcion} ${uLbl}</b> de <b>${_escapeHtml(padre.descripcion || baseVal)}</b>`;
        prevWrap.classList.remove('hidden');
      } else { prevWrap.classList.add('hidden'); }
    }
    // Guardián: porción vs peso del nombre (solo aviso)
    if (hint) {
      const peso = _pesoDesdeNombre($('prodDescripcion')?.value);
      if (porcion > 0 && peso != null && peso > 0) {
        const dif = Math.abs(porcion - peso) / peso;
        if (dif <= 0.02) {
          hint.textContent = `✓ Coincide con el nombre (≈${peso} ${uLbl})`;
          hint.style.color = '#34d399'; hint.classList.remove('hidden');
        } else {
          const factorX = porcion > peso ? (porcion / peso) : (peso / porcion);
          hint.textContent = `⚠ El nombre sugiere ≈${peso} ${uLbl}, pero pusiste ${porcion}. ${factorX >= 9 && factorX <= 11 ? '¿Te faltó/sobró un 0?' : 'Revisa que no sea un error de dedo.'} (puedes guardar igual)`;
          hint.style.color = '#fca5a5'; hint.classList.remove('hidden');
        }
      } else { hint.classList.add('hidden'); }
    }
  }

  // [catálogo v4 · limpieza] onTipoCheck/onEnvasableCheck ELIMINADOS: código muerto —
  // los checkboxes legacy están ocultos y todo lo maneja setProdTipo desde v2.43.486.

  function _esEnvasable(p) {
    const v = p.esEnvasable;
    return v === 1 || v === '1' || v === true || v === 'true' || v === 'Sí';
  }

  // Normaliza unidades legacy a códigos SUNAT (consistencia con prodUnidadMedida)
  // Aceptamos códigos SUNAT directos: NIU, KGM, LTR, BG, BX, PR, PK, ZZ
  // Mapeamos legacy: UNIDAD→NIU, KG→KGM, LITRO→LTR, BOLSA/SOBRE/SACO→BG, CAJA→BX
  const _UNIDAD_LEGACY_MAP = {
    'UNIDAD': 'NIU', 'UND': 'NIU', 'U': 'NIU', '': 'NIU',
    'KG': 'KGM', 'KILO': 'KGM', 'KILOGRAMO': 'KGM',
    'LITRO': 'LTR', 'LT': 'LTR', 'L': 'LTR',
    'BOLSA': 'BG', 'SOBRE': 'BG', 'SACO': 'BG',
    'CAJA': 'BX',
    'PAR': 'PR',
    'PAQUETE': 'PK', 'PACK': 'PK',
    'SERVICIO': 'ZZ'
  };
  function _normalizarUnidad(u) {
    if (!u) return 'NIU';
    const up = String(u).trim().toUpperCase();
    return _UNIDAD_LEGACY_MAP[up] || up;  // si ya es SUNAT, lo deja igual
  }
  // Display de unidad con ícono — ⚖️ para KGM (granel), × para el resto
  function _unidadDisplay(u) {
    const norm = _normalizarUnidad(u);
    return norm === 'KGM' ? `⚖️ ${norm}` : `× ${norm}`;
  }

  // Producto activo si estado NO es explícitamente 0/'0'/false.
  // Importante: Sheets convierte '0' en número 0; el check viejo usaba !p.estado,
  // que con estado=0 (número) daba true incorrectamente — producto se veía activo.
  function _isProdActivo(p) {
    if (!p) return false;
    const e = p.estado;
    if (e === 0 || e === '0' || e === false) return false;
    if (typeof e === 'string' && e.toLowerCase() === 'false') return false;
    return true;
  }

  function _poblarEnvasablesSelect() {
    const sel = $('prodCodigoProductoBase');
    if (!sel) return;
    const cur = sel.value;
    const items = S.productos.filter(p => _esEnvasable(p));
    if (!items.length) {
      sel.innerHTML = '<option value="">— sin productos envasables registrados —</option>';
      toast('No hay productos marcados como Envasable aún', 'error');
      return;
    }
    sel.innerHTML = '<option value="">— seleccionar envasable —</option>'
      + items.map(p => { const val = p.skuBase || p.idProducto; return `<option value="${val}"${cur===val?' selected':''}>${p.descripcion||p.idProducto}</option>`; }).join('');
    if (cur) sel.value = cur;
    // [424] al elegir el granel: hereda tributarios Y refresca el preview
    sel.onchange = () => { _heredarTributariosDeBase(sel.value); try { _prodDerivadoPreview(); } catch(_){} };
  }

  function _poblarBasesSelect() {
    const sel = $('prodSkuBase');
    if (!sel) return;
    const cur = sel.value;
    const bases = S.productos.filter(p => !p.skuBase || p.skuBase === p.idProducto);
    sel.innerHTML = '<option value="">— seleccionar producto base —</option>'
      + bases.map(p => `<option value="${p.idProducto}"${cur===p.idProducto?' selected':''}>${p.descripcion||p.idProducto}</option>`).join('');
    if (cur) sel.value = cur;
    sel.onchange = () => _heredarTributariosDeBase(sel.value);
  }

  // Hereda Tipo_IGV, IGV%, Cod_Tributo, Cod_SUNAT, Unidad_Medida del producto padre seleccionado
  // (presentación o derivado). Editable después si se requiere.
  function _heredarTributariosDeBase(idBase) {
    if (!idBase) return;
    const padre = (S.productos || []).find(p =>
      p.idProducto === idBase || p.skuBase === idBase
    );
    if (!padre) return;
    // Migrar legacy gravado/exonerado/inafecto → 1/2/3
    const tipoLegacy = { 'gravado': '1', 'exonerado': '2', 'inafecto': '3' };
    const tipoVal = tipoLegacy[String(padre.Tipo_IGV || '').toLowerCase()] || (padre.Tipo_IGV ? String(padre.Tipo_IGV) : '1');
    if ($('prodTipoIGV'))     $('prodTipoIGV').value     = tipoVal;
    if ($('prodCodTributo'))  $('prodCodTributo').value  = padre.Cod_Tributo || (tipoVal === '1' ? '1000' : tipoVal === '2' ? '9997' : '9998');
    if ($('prodIGV'))         $('prodIGV').value         = (padre.IGV_Porcentaje !== undefined && padre.IGV_Porcentaje !== '') ? padre.IGV_Porcentaje : (tipoVal === '1' ? 18 : 0);
    if ($('prodCodSUNAT'))    $('prodCodSUNAT').value    = padre.Cod_SUNAT || '10000000';
    if ($('prodUnidadMedida')) $('prodUnidadMedida').value = padre.Unidad_Medida || 'NIU';
    // [640] categoría: ya no se copia — la asigna la IA (herencia server-side del líder)
    if ($('prodMarca') && !$('prodMarca').value && padre.marca) {
      $('prodMarca').value = padre.marca;
    }
    _actualizarResumenSunat();
    toast('🧬 Datos tributarios heredados de "' + (padre.descripcion || padre.idProducto) + '" — editables si requiere', 'info');
  }

  // ── [catálogo v4] códigos autogenerados con PREFIJO por tipo ──────────
  // N- canónico · WH- derivado · P- presentación. Alfanuméricos base36 →
  // JAMÁS compiten con un EAN numérico de fábrica futuro.
  function _genCodigoPrefijo(pref) {
    const ts   = Date.now().toString(36).toUpperCase().slice(-5);
    const rand = Math.floor(Math.random() * 1296).toString(36).toUpperCase().padStart(2, '0');
    return pref + ts + rand;
  }

  // ¿El código está libre LOCALMENTE? (productos cargados + equivalencias en equivMap)
  // Cierra el gap histórico: la validación vieja NO miraba equivalencias.
  function _cbConflictoLocal(val, ignorarIdProducto) {
    const v = String(val || '').trim().toUpperCase();
    if (!v) return null;
    const dupProd = (S.productos || []).find(p =>
      p.codigoBarra && String(p.codigoBarra).trim().toUpperCase() === v
      && String(p.idProducto) !== String(ignorarIdProducto || ''));
    if (dupProd) return { tipo: 'producto', descripcion: dupProd.descripcion, id: dupProd.idProducto };
    const em = S.equivMap || {};
    for (const sku of Object.keys(em)) {
      const lista = em[sku] || [];
      for (const cb of lista) {
        if (String(cb).trim().toUpperCase() === v) {
          const dueño = (S.productos || []).find(p => (p.skuBase || p.idProducto) === sku);
          return { tipo: 'equivalencia', descripcion: (dueño?.descripcion || sku), id: sku };
        }
      }
    }
    return null;
  }

  // Genera un código con prefijo GARANTIZADO libre: local instantáneo +
  // confirmación server (RPC codigo_barra_disponible, SQL 426 — productos Y equivalencias).
  async function genCodigoUnico(pref) {
    for (let i = 0; i < 4; i++) {
      const cb = _genCodigoPrefijo(pref);
      if (_cbConflictoLocal(cb)) continue;
      try {
        const r = await API.post('codigoBarraDisponible', { codigoBarra: cb });
        if (r && r.disponible === false) continue;
      } catch (_) { /* server no disponible → el guard de BD (426) es la red final */ }
      return cb;
    }
    return _genCodigoPrefijo(pref);   // 4 colisiones seguidas ≈ imposible; el trigger BD respalda
  }

  // [pres-v1] Slug corto y determinista del padre para el código legible: primeras consonantes de las
  // 2 primeras palabras (cap 6) + dígitos (cap 4). Ej: "CHAMPIÑONES LATA 393GR" → "CHMLT393".
  function _presSlugPadre(padreDesc) {
    var s = String(padreDesc == null ? '' : padreDesc).toUpperCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
    s = s.replace(/[^A-Z0-9 ]/g, ' ');
    var palabras = s.split(/\s+/).filter(Boolean), letras = '', nums = '';
    for (var i = 0; i < palabras.length; i++) {
      var w = palabras[i];
      var digs = w.replace(/[^0-9]/g, ''); if (digs) nums += digs;
      var soloL = w.replace(/[^A-Z]/g, '');
      if (soloL && letras.length < 6) {
        var cons = soloL.charAt(0) + soloL.slice(1).replace(/[AEIOU]/g, '');
        letras += cons.slice(0, 3);
      }
    }
    return (letras.slice(0, 6) + nums.slice(0, 4)) || 'PRES';
  }

  // [pres-v1] Código legible de presentación: P-<slug>-<sufijoFactor>, ≤13 chars (límite scannable CODE128 en el
  // adhesivo 50mm — mismo rango que los WH- que ya imprimen bien). Colisión: 1 char base36 en el slug (no alarga).
  // Ej: tripack → P-CHMLT39-X3 · octavo → P-MRGSL2-D8. Fallback aleatorio si todo choca.
  var _PRES_B36 = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ';
  async function _presGenCodigo(padreDesc, factor) {
    var MAX = 13, suf = _presCodigoSufijo(factor), slugF = _presSlugPadre(padreDesc);
    var budget = Math.max(3, MAX - 3 - suf.length);
    var libre = async function (cand) {
      if (_cbConflictoLocal(cand)) return false;
      try { var r = await API.post('codigoBarraDisponible', { codigoBarra: cand }); if (r && r.disponible === false) return false; } catch (_) { /* guard BD 426 respalda */ }
      return true;
    };
    var cand = 'P-' + slugF.slice(0, budget) + (suf ? ('-' + suf) : '');
    if (await libre(cand)) return cand;
    var slugBase = slugF.slice(0, Math.max(2, budget - 1));
    for (var k = 0; k < _PRES_B36.length; k++) {
      cand = 'P-' + slugBase + _PRES_B36[k] + (suf ? ('-' + suf) : '');
      if (await libre(cand)) return cand;
    }
    return await genCodigoUnico('P-');
  }

  // Si silencioso=true: solo regenera (uso interno, ej. al guardar con campo vacío).
  // Si silencioso=false (click del botón): confirma antes de sobrescribir si hay contenido.
  async function prodAutogenBarcode(silencioso) {
    const cb = $('prodCodigoBarra');
    if (!cb) return;
    const actual = String(cb.value || '').trim();
    if (!silencioso && actual) {
      if (!await _modalConfirm(`El código actual "${actual}" será reemplazado por uno automático.\n\n¿Continuar?`, { warning: true, titulo: 'Autogenerar código' })) {
        return;
      }
    }
    // Prefijo según el tipo elegido en el modal (N- canónico/granel · WH- derivado · P- presentación)
    const pref = _prodTipo === 'derivado' ? 'WH-' : _prodTipo === 'presentacion' ? 'P-' : 'N-';
    cb.value = await genCodigoUnico(pref);
    prodValidarCodigoBarra();
  }

  // Validación en vivo: local (productos + equivalencias) al instante,
  // + confirmación server debounced 450ms (cruza AMBAS tablas completas).
  let _cbValidTimer = null;
  function prodValidarCodigoBarra() {
    const inp = $('prodCodigoBarra');
    const fb  = $('prodCodigoBarraFeedback');
    if (!inp || !fb) return true;
    const val   = inp.value.trim();
    const curId = $('prodId')?.value || '';
    if (!val) {
      fb.className = 'hidden text-xs mt-1';
      inp.classList.remove('!border-red-500');
      return true;
    }
    const conf = _cbConflictoLocal(val, curId);
    if (conf) {
      fb.textContent = conf.tipo === 'equivalencia'
        ? `⚠ Ya es código EQUIVALENTE de: ${conf.descripcion}`
        : `⚠ Ya existe en: ${conf.descripcion} (${conf.id})`;
      fb.className   = 'text-xs mt-1 text-red-400';
      inp.classList.add('!border-red-500');
      return false;
    }
    fb.textContent = '✓ Disponible';
    fb.className   = 'text-xs mt-1 text-green-400';
    inp.classList.remove('!border-red-500');
    // Confirmación server silenciosa (equivalencias fuera del snapshot local, otros equipos, etc.)
    clearTimeout(_cbValidTimer);
    _cbValidTimer = setTimeout(async () => {
      try {
        const r = await API.post('codigoBarraDisponible', { codigoBarra: val, ignorarIdProducto: curId });
        if (r && r.disponible === false && $('prodCodigoBarra')?.value.trim() === val) {
          const c = r.conflicto || {};
          fb.textContent = c.tipo === 'equivalencia'
            ? `⚠ Ya es código EQUIVALENTE de: ${c.descripcion || c.id}`
            : `⚠ Ya existe en: ${c.descripcion || c.id}`;
          fb.className = 'text-xs mt-1 text-red-400';
          inp.classList.add('!border-red-500');
        }
      } catch (_) {}
    }, 450);
    return true;
  }

  function prodToggleEstado() {
    const hidden = $('prodEstado');
    const btn    = $('prodEstadoToggle');
    if (!hidden || !btn) return;
    const activo = hidden.value !== '1';
    hidden.value = activo ? '1' : '0';
    btn.classList.toggle('on', activo);
    btn.querySelector('.prod-toggle-lbl').textContent = activo ? 'Activo' : 'Inactivo';
  }

  function prodToggleCosto() {
    const row = $('prodCostoRow');
    const ch  = $('costoChevron');
    if (!row) return;
    const wasHidden = row.classList.toggle('hidden');
    if (ch) ch.textContent = wasHidden ? '▶' : '▼';
  }

  function prodCalcMargen() {
    const v    = parseFloat($('prodPrecioVenta')?.value)  || 0;
    const c    = parseFloat($('prodPrecioCosto')?.value)  || 0;
    const bar  = $('prodMargenBar');
    const lbl  = $('prodMargenLabel');
    const fill = $('prodMargenFill');
    if (!bar) return;
    if (v > 0 && c > 0 && v >= c) {
      const m = (v - c) / v * 100;
      bar.classList.remove('hidden');
      if (lbl)  lbl.textContent  = m.toFixed(1) + '%';
      if (fill) { fill.style.width = Math.min(m, 100) + '%'; fill.style.background = m > 30 ? '#22c55e' : m > 15 ? '#f59e0b' : '#ef4444'; }
    } else {
      bar.classList.add('hidden');
    }
  }

  function prodOnRange() {
    const minEl = $('prodStockMinRange');
    const maxEl = $('prodStockMaxRange');
    if (!minEl || !maxEl) return;
    let min = parseInt(minEl.value), max = parseInt(maxEl.value);
    if (min > max) { if (document.activeElement === minEl) { minEl.value = max; min = max; } else { maxEl.value = min; max = min; } }
    if ($('prodStockMin')) $('prodStockMin').value = min;
    if ($('prodStockMax')) $('prodStockMax').value = max;
    if ($('stockMinLabel')) $('stockMinLabel').textContent = min;
    if ($('stockMaxLabel')) $('stockMaxLabel').textContent = max;
    const rMax = parseInt(minEl.max) || 500;
    const fill = $('prodRangeFill');
    if (fill) { fill.style.left = (min/rMax*100)+'%'; fill.style.width = ((max-min)/rMax*100)+'%'; }
  }

  function _setStockSlider(min, max) {
    const minEl = $('prodStockMinRange');
    const maxEl = $('prodStockMaxRange');
    if (minEl) minEl.value = min;
    if (maxEl) maxEl.value = max;
    if ($('prodStockMin')) $('prodStockMin').value = min;
    if ($('prodStockMax')) $('prodStockMax').value = max;
    if ($('stockMinLabel')) $('stockMinLabel').textContent = min;
    if ($('stockMaxLabel')) $('stockMaxLabel').textContent = max;
    const rMax = minEl ? parseInt(minEl.max) : 500;
    const fill = $('prodRangeFill');
    if (fill) { fill.style.left = (min/rMax*100)+'%'; fill.style.width = ((max-min)/rMax*100)+'%'; }
  }

  function prodToggleSunat() {
    const sec = $('prodSecSunat');
    const ch  = $('sunatChevron');
    if (!sec) return;
    const h = sec.classList.toggle('hidden');
    if (ch) ch.textContent = h ? '⚙️ ajustar' : '▴ ocultar';
  }

  // Cuando cambia Tipo IGV: autorrellenar los campos relacionados (Cod_Tributo, IGV%)
  function prodOnTipoIGVChange() {
    const tipo = $('prodTipoIGV')?.value || '1';
    if (tipo === '1') {
      $('prodCodTributo').value = '1000';
      $('prodIGV').value = '18';
    } else if (tipo === '2') {
      $('prodCodTributo').value = '9997';
      $('prodIGV').value = '0';
    } else if (tipo === '3') {
      $('prodCodTributo').value = '9998';
      $('prodIGV').value = '0';
    }
    _actualizarResumenSunat();
  }
  function _actualizarResumenSunat() {
    const tipo = $('prodTipoIGV')?.value;
    const igv = $('prodIGV')?.value || '0';
    const r = $('sunatResumen'); if (!r) return;
    let txt = '—';
    if (tipo === '1') txt = 'Gravado ' + igv + '%';
    else if (tipo === '2') txt = 'Exonerado';
    else if (tipo === '3') txt = 'Inafecto';
    r.textContent = txt;
    r.className = (tipo === '1') ? 'text-emerald-400 font-normal' : 'text-amber-400 font-normal';
  }

  // [RONDA 5 · directriz código limpio] PURGADO: editor embebido de tramos (seg*, _segState,
  // modal #modalSegmento) y toggles equiv del modal producto — reemplazados por los modales
  // del ＋ contextual (Tramo con lista/borrar · Equivalente con lista/toggle). ~470 líneas.
  // ── LOG de cambios de productos (master) ──────────────────
  // Estado del log (UI compacta)
  let _logProdState = {
    fecha: null,             // 'YYYY-MM-DD' (local) o '' = sin filtro de fecha
    sinFiltroFecha: false,   // true cuando user clickea "ver todo"
    filtroBuscar: '',
    filtroUsuario: '',
    filtroAccion: '',
    diasConActividad: new Set(),
    calMes: null,
  };

  // Convierte un timestamp ISO a 'YYYY-MM-DD' en HORA LOCAL del browser.
  // Crítico: comparar contra today() que también es local. Sin esto, los
  // cambios hechos al final del día PE caen en UTC del día siguiente y
  // desaparecen del filtro "hoy".
  function _logFechaLocal(ts) {
    if (!ts) return '';
    const d = new Date(ts);
    if (isNaN(d.getTime())) return '';
    return d.getFullYear() + '-' +
           String(d.getMonth() + 1).padStart(2, '0') + '-' +
           String(d.getDate()).padStart(2, '0');
  }

  async function abrirLogProductos() {
    openModal('modalLogProductos');
    // Inicializar fecha = hoy si no hay
    if (!_logProdState.fecha) {
      _logProdState.fecha = today();
    }
    _logProdActualizarFechaUI();
    await refreshLogProductos();
    // Atajos teclado ←/→
    if (!_logProdState._kbd) {
      _logProdState._kbd = e => {
        const modal = document.getElementById('modalLogProductos');
        if (!modal || modal.classList.contains('hidden')) return;
        // Si está enfocado un input/select, no interceptar
        const tag = (document.activeElement?.tagName || '').toLowerCase();
        if (tag === 'input' || tag === 'select' || tag === 'textarea') return;
        if (e.key === 'ArrowLeft')  { e.preventDefault(); _logProdFechaOffset(-1); }
        if (e.key === 'ArrowRight') { e.preventDefault(); _logProdFechaOffset(+1); }
      };
      document.addEventListener('keydown', _logProdState._kbd);
    }
  }

  function _logProdActualizarFechaUI() {
    const lbl = $('logFechaLabel');
    if (lbl) {
      if (_logProdState.sinFiltroFecha) {
        lbl.textContent = 'Todos';
      } else {
        const f = _logProdState.fecha;
        const hoy = today();
        const d = new Date(f + 'T00:00:00');
        const txt = d.toLocaleDateString('es-PE', { day:'2-digit', month:'short' });
        lbl.textContent = (f === hoy) ? `Hoy · ${txt}` : txt;
      }
    }
    // Marcar iconos activos según filtros
    const ic = (id, on) => {
      const b = $(id); if (!b) return;
      b.classList.toggle('active', !!on);
      const dot = b.querySelector('.log-icon-dot');
      if (dot) dot.classList.toggle('hidden', !on);
    };
    ic('logIconUsuario', !!_logProdState.filtroUsuario);
    ic('logIconAccion',  !!_logProdState.filtroAccion);
    ic('logIconBuscar',  !!_logProdState.filtroBuscar);
    // Mostrar botón limpiar si hay algún filtro
    const limpiar = $('logBtnLimpiar');
    const hay = !!(_logProdState.filtroBuscar || _logProdState.filtroUsuario || _logProdState.filtroAccion || _logProdState.sinFiltroFecha);
    if (limpiar) limpiar.classList.toggle('hidden', !hay);
  }

  async function refreshLogProductos(force) {
    const cont = $('logProductosList');
    if (!cont) return;
    // Render INMEDIATO desde cache si existe (TTL 60s)
    const cache = S._logProdCache;
    if (!force && cache && Array.isArray(cache.data) && (Date.now() - cache.ts) < 60 * 1000) {
      _logProdConstruirIndices(cache.data);
      _logProdFiltrar();
    } else {
      cont.innerHTML = '<div class="text-center py-6 text-slate-500 text-sm">Cargando log...</div>';
    }
    try {
      const data = await API.get('getProductosEditadosRecientes', { limit: 200 });
      S._logProdCache = { ts: Date.now(), data };
      if (!Array.isArray(data) || !data.length) {
        cont.innerHTML = '<div class="text-center py-8 text-slate-500 text-sm italic">Sin ediciones registradas todavía</div>';
        return;
      }
      _logProdConstruirIndices(data);
      _logProdFiltrar();
    } catch(e) {
      if (!cache) cont.innerHTML = '<div class="text-center py-6 text-red-400 text-sm">Error: ' + e.message + '</div>';
    }
  }

  // Construye el índice de días con actividad (en hora LOCAL) y dropdown usuarios
  function _logProdConstruirIndices(data) {
    const dias = new Set();
    const usuarios = new Set();
    data.forEach(p => {
      const hist = Array.isArray(p.historial) ? p.historial : [];
      hist.forEach(e => {
        const f = _logFechaLocal(e.ts);
        if (f) dias.add(f);
        if (e.usuario) usuarios.add(String(e.usuario).trim());
      });
    });
    _logProdState.diasConActividad = dias;
    _logProdState.usuariosDisponibles = Array.from(usuarios).sort();
    const sel = $('logFiltroUsuario');
    if (sel) {
      const cur = sel.value;
      sel.innerHTML = '<option value="">Todos</option>' +
        _logProdState.usuariosDisponibles.map(u => `<option value="${u}">${u}</option>`).join('');
      sel.value = cur;
    }
  }

  function _logProdFechaOffset(delta) {
    // Si estaba en "todos", al navegar volvemos a fecha hoy ± delta
    if (_logProdState.sinFiltroFecha) {
      _logProdState.sinFiltroFecha = false;
      _logProdState.fecha = today();
    }
    const f = _logProdState.fecha || today();
    // Construir fecha LOCAL evitando UTC drift
    const [yy, mm, dd] = f.split('-').map(Number);
    const d = new Date(yy, mm - 1, dd);
    d.setDate(d.getDate() + delta);
    const newFecha = d.getFullYear() + '-' +
                     String(d.getMonth() + 1).padStart(2, '0') + '-' +
                     String(d.getDate()).padStart(2, '0');
    _logProdState.fecha = newFecha;
    _logProdActualizarFechaUI();
    _logProdFiltrar();
    _logProdSlide(delta < 0 ? 'left' : 'right');
  }
  function _logProdIrHoy() {
    _logProdState.fecha = today();
    _logProdState.sinFiltroFecha = false;
    _logProdActualizarFechaUI();
    _logProdFiltrar();
  }
  function _logProdVerTodo() {
    _logProdState.sinFiltroFecha = true;
    _logProdActualizarFechaUI();
    _logProdFiltrar();
  }
  function _logProdLimpiarFiltros() {
    _logProdState.filtroBuscar = '';
    _logProdState.filtroUsuario = '';
    _logProdState.filtroAccion = '';
    _logProdState.sinFiltroFecha = false;
    if (!_logProdState.fecha) _logProdState.fecha = today();
    const inp = $('logFiltroBuscar'); if (inp) inp.value = '';
    const su = $('logFiltroUsuario'); if (su) su.value = '';
    const sa = $('logFiltroAccion');  if (sa) sa.value = '';
    // Si la barra estaba en modo búsqueda, volver al modo normal
    const bar = $('logBarraBuscar');
    const norm = $('logBarraNormal');
    if (bar && !bar.classList.contains('hidden')) {
      bar.classList.add('hidden');
      norm?.classList.remove('hidden');
    }
    _logProdActualizarFechaUI();
    _logProdFiltrar();
  }
  function _logProdLimpiarBuscar() {
    const inp = $('logFiltroBuscar');
    if (inp) { inp.value = ''; inp.focus(); }
    _logProdState.filtroBuscar = '';
    _logProdActualizarFechaUI();
    _logProdFiltrar();
  }
  function _logProdToggleBusqueda() {
    const bar = $('logBarraBuscar');
    const norm = $('logBarraNormal');
    if (!bar || !norm) return;
    const abriendo = bar.classList.contains('hidden');
    bar.classList.toggle('hidden', !abriendo);
    norm.classList.toggle('hidden', abriendo);
    if (abriendo) {
      setTimeout(() => $('logFiltroBuscar')?.focus(), 50);
    }
  }
  // Popover unificado: usuario / acción
  function _logProdAbrirFiltro(tipo, anchorBtn) {
    const pop = $('logFiltroPopover');
    if (!pop) return;
    if (!pop.classList.contains('hidden') && pop.dataset.tipo === tipo) {
      pop.classList.add('hidden');
      return;
    }
    pop.dataset.tipo = tipo;
    let html = '';
    if (tipo === 'usuario') {
      const cur = _logProdState.filtroUsuario;
      const usuarios = _logProdState.usuariosDisponibles || [];
      html = '<div class="log-popover-title">Usuario</div>';
      html += `<div class="log-popover-opt ${!cur ? 'selected' : ''}" onclick="MOS._logProdSetFiltro('usuario','')">
        <div class="log-popover-opt-radio"></div><span>Todos</span>
      </div>`;
      usuarios.forEach(u => {
        const safe = u.replace(/'/g, "\\'");
        html += `<div class="log-popover-opt ${cur === u ? 'selected' : ''}" onclick="MOS._logProdSetFiltro('usuario','${safe}')">
          <div class="log-popover-opt-radio"></div><span>👤 ${u}</span>
        </div>`;
      });
    } else if (tipo === 'accion') {
      const cur = _logProdState.filtroAccion;
      const opts = [
        ['', 'Todas las acciones'],
        ['crear', '🆕 Crear'],
        ['editar', '✏️ Editar'],
        ['precio', '💰 Cambio de precio'],
        ['codigo', '🔢 Corrección código'],
        ['equivalencia', '🔗 Equivalencia']
      ];
      html = '<div class="log-popover-title">Tipo de acción</div>';
      opts.forEach(([v, lbl]) => {
        html += `<div class="log-popover-opt ${cur === v ? 'selected' : ''}" onclick="MOS._logProdSetFiltro('accion','${v}')">
          <div class="log-popover-opt-radio"></div><span>${lbl}</span>
        </div>`;
      });
    }
    pop.innerHTML = html;
    // Posicionar bajo el botón
    const r = anchorBtn.getBoundingClientRect();
    pop.style.left = Math.max(8, Math.min(window.innerWidth - 290, r.left)) + 'px';
    pop.style.top  = (r.bottom + 6) + 'px';
    pop.classList.remove('hidden');
    // Cerrar al click fuera
    setTimeout(() => {
      const closer = e => {
        if (!pop.contains(e.target) && !anchorBtn.contains(e.target)) {
          pop.classList.add('hidden');
          document.removeEventListener('click', closer);
        }
      };
      document.addEventListener('click', closer);
    }, 50);
  }
  function _logProdSetFiltro(tipo, valor) {
    if (tipo === 'usuario') _logProdState.filtroUsuario = valor;
    if (tipo === 'accion')  _logProdState.filtroAccion = valor;
    const sel = $(tipo === 'usuario' ? 'logFiltroUsuario' : 'logFiltroAccion');
    if (sel) sel.value = valor;
    $('logFiltroPopover')?.classList.add('hidden');
    _logProdActualizarFechaUI();
    _logProdFiltrar();
  }

  function _logProdFiltrar() {
    const data = S._logProdCache?.data || [];
    if (!Array.isArray(data) || !data.length) return;

    // Recoger filtros desde DOM (puede haberlos cambiado el user)
    _logProdState.filtroBuscar  = ($('logFiltroBuscar')?.value || '').trim().toLowerCase();

    // Una sola vista: agrupada por canónico, filtrada por fecha activa
    _logProdRenderPorProducto(data);
    _logProdActualizarFechaUI();
  }

  function _logProdSlide(dir) {
    const cont = $('logProductosList');
    if (!cont) return;
    const cls = dir === 'left' ? 'fin-slide-out-right' : 'fin-slide-out-left';
    cont.classList.add(cls);
    setTimeout(() => cont.classList.remove(cls), 280);
  }

  // ── Filtra una entrada según los filtros activos ──
  function _logProdEntradaCoincide(entrada) {
    // Filtro fecha (hora local)
    if (!_logProdState.sinFiltroFecha && _logProdState.fecha) {
      const fLocal = _logFechaLocal(entrada.ts);
      if (fLocal !== _logProdState.fecha) return false;
    }
    if (_logProdState.filtroUsuario) {
      const u = String(entrada.usuario || '').trim();
      if (u !== _logProdState.filtroUsuario) return false;
    }
    if (_logProdState.filtroAccion) {
      const a = String(entrada.accion || '').toLowerCase();
      const src = String(entrada.source || '').toLowerCase();
      const filt = _logProdState.filtroAccion;
      if (filt === 'crear' && a !== 'crear') return false;
      if (filt === 'editar' && a !== 'editar' && a !== 'editar (auto)') return false;
      if (filt === 'precio' && !src.includes('precio')) return false;
      if (filt === 'codigo' && !src.includes('codigo')) return false;
      if (filt === 'equivalencia' && !src.includes('equiv')) return false;
    }
    return true;
  }
  function _logProdProductoCoincide(p) {
    if (_logProdState.filtroBuscar) {
      const q = _logProdState.filtroBuscar;
      const txt = (p.descripcion + ' ' + (p.skuBase || '') + ' ' + (p.codigoBarra || '')).toLowerCase();
      if (!txt.includes(q)) return false;
    }
    return true;
  }

  // ── Vista única: agrupada por canónico, filtrada por fecha activa ──
  function _logProdRenderPorProducto(data) {
    _logProdRender(data);
    const cont = $('logProductosList');
    const cant = cont ? cont.querySelectorAll('.log-card').length : 0;
    const cantEl = $('logCantResultados');
    if (cantEl) {
      cantEl.textContent = cant > 0 ? `${cant} ⚡` : '0';
      // Pulso al actualizar
      cantEl.style.transition = 'color 0.4s';
      cantEl.style.color = cant > 0 ? '#a5b4fc' : '#64748b';
      setTimeout(() => { cantEl.style.color = '#94a3b8'; }, 400);
    }
    const sub = $('logModalSubtitle');
    if (sub) {
      const fechaTxt = _logProdState.sinFiltroFecha ? 'todo el historial'
        : (_logProdState.fecha === today() ? 'hoy' : _logProdState.fecha);
      sub.textContent = `${cant} producto${cant !== 1 ? 's' : ''} con cambios · ${fechaTxt}`;
    }
    if (!cant && cont) {
      const haceFiltro = !!(_logProdState.filtroBuscar || _logProdState.filtroUsuario || _logProdState.filtroAccion);
      const linkVerTodo = !_logProdState.sinFiltroFecha && !haceFiltro
        ? `<button onclick="MOS._logProdVerTodo()" class="text-indigo-400 hover:text-indigo-300 text-xs mt-2 underline">Ver todo el historial →</button>`
        : '';
      cont.innerHTML = `<div class="text-center py-10 text-slate-500 text-sm italic">
        Sin cambios ${haceFiltro ? 'con esos filtros' : (_logProdState.sinFiltroFecha ? '' : 'este día')}
        <div>${linkVerTodo}</div>
      </div>`;
    }
  }

  // ── Vista por día: agrupado por hora ──

  // ── DATEPICKER ──
  function _logProdAbrirCalendario(btn) {
    const dp = $('logDatepicker');
    if (!dp) return;
    if (!dp.classList.contains('hidden')) {
      dp.classList.add('hidden');
      return;
    }
    // Posicionar bajo el botón
    const r = btn.getBoundingClientRect();
    dp.style.left = (r.left) + 'px';
    dp.style.top  = (r.bottom + 6) + 'px';
    // Mes inicial = mes de la fecha seleccionada
    const f = _logProdState.fecha || today();
    const d = new Date(f + 'T00:00:00');
    _logProdState.calMes = { y: d.getFullYear(), m: d.getMonth() };
    _logProdRenderCalendario();
    dp.classList.remove('hidden');
    // Click fuera cierra
    setTimeout(() => {
      const closer = e => {
        if (!dp.contains(e.target) && e.target.id !== 'logFechaBtn' && !btn.contains(e.target)) {
          dp.classList.add('hidden');
          document.removeEventListener('click', closer);
        }
      };
      document.addEventListener('click', closer);
    }, 50);
  }
  function _logProdCalNavMes(delta) {
    if (!_logProdState.calMes) return;
    let { y, m } = _logProdState.calMes;
    m += delta;
    if (m < 0)   { m = 11; y--; }
    if (m > 11)  { m = 0;  y++; }
    _logProdState.calMes = { y, m };
    _logProdRenderCalendario();
  }
  function _logProdRenderCalendario() {
    const grid = $('logCalGrid');
    const lbl  = $('logCalMesAnio');
    if (!grid || !_logProdState.calMes) return;
    const { y, m } = _logProdState.calMes;
    const meses = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
    if (lbl) lbl.textContent = `${meses[m]} ${y}`;
    // Primer día del mes
    const primero = new Date(y, m, 1);
    let primerDow = primero.getDay(); // 0=dom..6=sab
    primerDow = primerDow === 0 ? 6 : primerDow - 1; // L=0..D=6
    const ultimo = new Date(y, m + 1, 0).getDate();
    const hoy = today();
    const sel = _logProdState.fecha;
    const dias = _logProdState.diasConActividad;
    let html = '';
    for (let i = 0; i < primerDow; i++) html += '<button class="log-cal-day empty"></button>';
    for (let dia = 1; dia <= ultimo; dia++) {
      const f = `${y}-${String(m + 1).padStart(2, '0')}-${String(dia).padStart(2, '0')}`;
      const cls = ['log-cal-day'];
      if (dias.has(f)) cls.push('has-activity');
      if (f === hoy)   cls.push('today');
      if (f === sel)   cls.push('selected');
      html += `<button class="${cls.join(' ')}" onclick="MOS._logProdElegirFecha('${f}')">${dia}</button>`;
    }
    grid.innerHTML = html;
  }
  function _logProdElegirFecha(f) {
    _logProdState.fecha = f;
    _logProdActualizarFechaUI();
    const dp = $('logDatepicker');
    if (dp) dp.classList.add('hidden');
    _logProdFiltrar();
  }

  // Agrupa productos por skuBase. El representante es el canónico
  // (factorConversion=1 sin codigoProductoBase). Las presentaciones quedan
  // como sub-productos cuyas entradas se mezclan en el historial combinado
  // del grupo, etiquetadas con el origen.
  function _logProdAgruparPorCanonico(data) {
    const grupos = {};
    data.forEach(p => {
      const key = String(p.skuBase || p.codigoProductoBase || p.idProducto || '');
      if (!key) return;
      if (!grupos[key]) grupos[key] = { canonico: null, miembros: [], historial: [] };
      const esCanonico = !p.codigoProductoBase && (parseFloat(p.factorConversion) === 1 || !p.factorConversion);
      if (esCanonico) grupos[key].canonico = p;
      grupos[key].miembros.push(p);
      const hist = Array.isArray(p.historial) ? p.historial : [];
      hist.forEach(e => {
        grupos[key].historial.push(Object.assign({}, e, {
          _origenIdProducto: p.idProducto,
          _origenDescripcion: p.descripcion,
          _origenEsCanonico: esCanonico,
          _origenFactor: p.factorConversion
        }));
      });
    });
    Object.keys(grupos).forEach(k => {
      // Si no hay canónico identificado, usar el miembro con factor más bajo
      if (!grupos[k].canonico) {
        grupos[k].canonico = grupos[k].miembros.slice().sort((a, b) =>
          (parseFloat(a.factorConversion) || 1) - (parseFloat(b.factorConversion) || 1)
        )[0];
      }
      grupos[k].historial.sort((a, b) => new Date(b.ts || 0).getTime() - new Date(a.ts || 0).getTime());
    });
    return grupos;
  }

  function _logProdRender(data) {
    const cont = $('logProductosList');
    if (!cont || !Array.isArray(data)) return;
    const grupos = _logProdAgruparPorCanonico(data);
    // Ordenar grupos por timestamp del último cambio descendente
    const claves = Object.keys(grupos).sort((a, b) => {
      const ta = grupos[a].historial[0]?.ts ? new Date(grupos[a].historial[0].ts).getTime() : 0;
      const tb = grupos[b].historial[0]?.ts ? new Date(grupos[b].historial[0].ts).getTime() : 0;
      return tb - ta;
    });

    cont.innerHTML = claves.map(key => {
      const g = grupos[key];
      const c = g.canonico;
      // Filtro de búsqueda: aplica al GRUPO (cualquier miembro coincide).
      // Esto permite buscar "TRIPACK" y aún ver el grupo del canónico ACONCAGUA.
      const grupoCoincide = g.miembros.some(_logProdProductoCoincide);
      if (!grupoCoincide) return '';
      // Filtrar entradas individuales con _logProdEntradaCoincide
      const histFiltrado = g.historial.filter(_logProdEntradaCoincide);
      if (!histFiltrado.length) return '';
      const ult = histFiltrado[0];
      const f = ult.ts ? new Date(ult.ts) : null;
      const fmt = f ? f.toLocaleString('es-PE', { day:'2-digit', month:'short', hour:'2-digit', minute:'2-digit' }) : '—';
      const mins = f ? Math.floor((Date.now() - f.getTime()) / 60000) : Infinity;
      let badge = '';
      if (mins < 5)         badge = `<span class="log-badge log-badge-live">🟢 hace ${mins}m</span>`;
      else if (mins < 60)   badge = `<span class="log-badge log-badge-recent">hace ${mins}m</span>`;
      else if (mins < 1440) badge = `<span class="log-badge log-badge-hours">hace ${Math.floor(mins/60)}h</span>`;
      else                  badge = `<span class="log-badge log-badge-old">hace ${Math.floor(mins/1440)}d</span>`;
      const safeId = String(c.idProducto || '').replace(/'/g, '&#39;');
      const numPresentaciones = g.miembros.filter(m => !!m.codigoProductoBase || (parseFloat(m.factorConversion) > 1)).length;
      const tipoChip = numPresentaciones > 0
        ? `<span class="text-[9px] uppercase font-bold text-emerald-300">CANÓNICO + ${numPresentaciones} pres.</span>`
        : `<span class="text-[9px] uppercase font-bold text-emerald-300">CANÓNICO</span>`;

      const entries = histFiltrado.slice(0, 12).map(e => {
        const fe = e.ts ? new Date(e.ts).toLocaleString('es-PE', { day:'2-digit', month:'short', year:'2-digit', hour:'2-digit', minute:'2-digit' }) : '—';
        // Chip de origen: si la entrada viene de una presentación, indicar cuál
        const origenChip = e._origenEsCanonico
          ? `<span class="log-origen log-origen-canonico" title="Cambio en el producto canónico">📦 base</span>`
          : `<span class="log-origen log-origen-presentacion" title="Cambio en la presentación">📐 ${e._origenDescripcion || 'presentación'}${e._origenFactor ? ' · f=' + e._origenFactor : ''}</span>`;
        let cuerpo = '';
        if (e.accion === 'crear') {
          cuerpo = `<span class="log-action log-action-crear">🆕 creó</span> ${e.descripcion || ''}${e.codigoBarra ? ' · cód ' + e.codigoBarra : ''}${e.precioVenta ? ' · S/ ' + parseFloat(e.precioVenta).toFixed(2) : ''}`;
        } else if (Array.isArray(e.cambios) && e.cambios.length) {
          cuerpo = '<span class="log-action log-action-editar">✏️ editó</span> ' + e.cambios.map(c =>
            `<span class="log-cambio"><strong>${c.campo}</strong>: <span class="log-antes">${_logFmtVal(c.antes)}</span> → <span class="log-despues">${_logFmtVal(c.despues)}</span></span>`
          ).join(' · ');
        } else {
          cuerpo = `<span class="log-action log-action-editar">✏️ ${e.accion || 'cambio'}</span>`;
        }
        if (e.motivo) cuerpo += ` <span class="log-motivo">— ${e.motivo}</span>`;
        const evIdSafe = String(e._origenIdProducto || '').replace(/'/g, '&#39;');
        return `<div class="log-entry">
          <div class="log-entry-head">
            <span class="log-usuario">👤 ${e.usuario || 'desconocido'}</span>
            ${origenChip}
            <span class="log-source">${e.source || ''}</span>
            <span class="log-fecha">${fe}</span>
          </div>
          <div class="log-entry-body">${cuerpo}</div>
          ${!e._origenEsCanonico && evIdSafe ? `<button onclick="event.stopPropagation();MOS.closeModal('modalLogProductos');MOS.abrirModalProducto('${evIdSafe}')" class="log-entry-link">→ abrir presentación</button>` : ''}
        </div>`;
      }).join('');

      return `<div class="log-card">
        <div class="log-card-head" onclick="MOS._logToggleCard(this)">
          <div class="flex-1 min-w-0">
            <div class="log-card-title">${c.descripcion || '—'} <span class="log-toggle">▾</span></div>
            <div class="log-card-meta">
              ${tipoChip}
              <span class="text-[10px] text-slate-500">${c.skuBase || '—'}</span>
              <span class="text-[10px] text-amber-400 font-bold">S/ ${parseFloat(c.precioVenta || 0).toFixed(2)}</span>
              <span class="text-[10px] text-slate-500">· ${histFiltrado.length} cambio${histFiltrado.length !== 1 ? 's' : ''}</span>
            </div>
            <div class="log-card-last">
              Último: ${ult.usuario || '—'} · ${fmt}${!ult._origenEsCanonico ? ' · en ' + (ult._origenDescripcion || 'presentación') : ''}
            </div>
          </div>
          ${badge}
        </div>
        <div class="log-card-entries hidden">
          ${entries}
          <button onclick="MOS.closeModal('modalLogProductos');MOS.abrirModalProducto('${safeId}')" class="log-btn-edit">✏️ Abrir canónico</button>
        </div>
      </div>`;
    }).filter(Boolean).join('');
  }

  function _logFmtVal(v) {
    if (v === null || v === undefined || v === '') return '<em class="text-slate-600">vacío</em>';
    const s = String(v);
    return s.length > 40 ? s.substring(0, 40) + '...' : s;
  }

  function _logToggleCard(headEl) {
    const card = headEl?.closest('.log-card');
    if (!card) return;
    card.querySelector('.log-card-entries')?.classList.toggle('hidden');
    const t = card.querySelector('.log-toggle');
    if (t) t.textContent = card.querySelector('.log-card-entries').classList.contains('hidden') ? '▾' : '▴';
  }

  // ── Product modal — abrir ─────────────────────────────────
  function abrirModalProducto(id, opts) {
    opts = opts || {};
    try { _opsBeep && _opsBeep('tac'); } catch(_){}
    // [v2.43.54] Aplicar halo de categoría al modal box (efecto premium)
    setTimeout(() => {
      const prod = id && Array.isArray(S.productos) ? S.productos.find(p => p.idProducto === id) : null;
      const box = document.querySelector('#modalProducto .modal-box, #productModal .modal-box');
      if (box && prod) _aplicarHaloCategoria(box, prod);
    }, 50);
    // [v2.43.3] Si llamaron con focusPolitica, scroll + expandir sección política
    // tras 250ms (después de renderizar el modal). Ahorra 3 taps al cajero.
    if (opts.focusPolitica) {
      setTimeout(() => {
        try {
          const sec = document.querySelector('[id*="Politica"],[data-section="politica"],.prod-sec-politica,#prodSecPolitica');
          if (sec && sec.classList.contains('hidden')) {
            (typeof prodTogglePolitica === 'function') && prodTogglePolitica();
          }
          if (sec) sec.scrollIntoView({ behavior: 'smooth', block: 'center' });
          _opsBeep?.('tac');
        } catch(_){}
      }, 280);
    }
    // Reset
    ['prodDescripcion','prodCodigoBarra','prodMarca','prodPrecioVenta','prodPrecioCosto',
     'prodFactorConvBase','prodFactor','prodIGV','prodCodSUNAT'].forEach(i => { const el=$(i); if(el) el.value=''; });
    $('prodId').value = '';
    $('prodEstado').value = '1';
    const toggle = $('prodEstadoToggle');
    if (toggle) { toggle.classList.add('on'); toggle.querySelector('.prod-toggle-lbl').textContent = 'Activo'; }
    const fb = $('prodCodigoBarraFeedback');
    if (fb) { fb.className = 'hidden text-xs mt-1'; fb.textContent = ''; }
    $('prodCodigoBarra')?.classList.remove('!border-red-500');
    $('prodCostoRow')?.classList.add('hidden');
    const ch = $('costoChevron'); if (ch) ch.textContent = '▶';
    $('prodMargenBar')?.classList.add('hidden');
    _setStockSlider(0, 0);
    setProdTipo('normal');
    // [RONDA 5 · purga] reset de sección equiv embebida eliminado
    // [RONDA 5 · purga] reset de sección equiv embebida eliminado
    // [RONDA 5 · purga] reset de sección equiv embebida eliminado
    // [RONDA 5 · purga] reset de sección equiv embebida eliminado
    // [RONDA 5 · purga] reset de sección equiv embebida eliminado
    $('prodSecSunat')?.classList.add('hidden');
    const sch = $('sunatChevron'); if (sch) sch.textContent = '⚙️ avanzado';

    // [catálogo v4] CREAR = solo canónico (toggle envasable); EDITAR = barra completa
    // de tipos (los satélites existentes se siguen editando aquí). Derivado/presentación
    // NUEVOS nacen del ＋ contextual del card, no de este modal.
    $('prodTipoBar')?.classList.toggle('hidden', !id);
    $('prodEnvasableRow')?.classList.toggle('hidden', !!id);
    $('prodEnvasableSw')?.classList.remove('on');
    // [597] toggle insumo: visible al crear (como envasable); en edición se decide más abajo por tipo
    $('prodInsumoRow')?.classList.toggle('hidden', !!id);
    $('prodInsumoSw')?.classList.remove('on');

    if (id) {
      const p = S.productos.find(x => x.idProducto === id);
      if (!p) return;
      $('modalProdTitle').textContent = 'Editar Producto';
      $('prodId').value          = p.idProducto;
      $('prodDescripcion').value = p.descripcion   || '';
      $('prodCodigoBarra').value = p.codigoBarra   || '';
      $('prodMarca').value       = p.marca         || '';
      // [640] chip de categoría automática (IA): muestra cat > sub del producto
      if ($('prodCategoriaChip')) {
        const cia = p.categoriaIa && typeof p.categoriaIa === 'object' ? p.categoriaIa : null;
        $('prodCategoriaChip').innerHTML = cia
          ? `<b style="color:#cfe1ff">${_escapeHtml(cia.categoria || '')}</b><span style="opacity:.6">›</span>${_escapeHtml(cia.subcategoria || '')}`
          : (p.idCategoria ? `<b style="color:#cfe1ff">${_escapeHtml(p.idCategoria)}</b>` : '🤖 se asigna sola al guardar');
      }
      // Migración: valores legacy (KG, LITRO, BOLSA, etc.) → códigos SUNAT
      // El campo Unidad_Medida (SUNAT autoritativo) prima sobre unidad
      const _unidadProd = _normalizarUnidad(p.Unidad_Medida || p.unidad) || 'NIU';
      $('prodUnidad').value      = _unidadProd;
      $('prodUnidadMedida').value = _unidadProd; // hidden sincronizado

      // Estado
      const activo = _isProdActivo(p);
      $('prodEstado').value = activo ? '1' : '0';
      if (toggle) { toggle.classList.toggle('on', activo); toggle.querySelector('.prod-toggle-lbl').textContent = activo ? 'Activo' : 'Inactivo'; }

      // Precios
      $('prodPrecioVenta').value = p.precioVenta || '';
      if (p.precioCosto) {
        $('prodPrecioCosto').value = p.precioCosto;
        $('prodCostoRow')?.classList.remove('hidden');
        if (ch) ch.textContent = '▼';
      }
      prodCalcMargen();

      // Stock
      _setStockSlider(parseFloat(p.stockMinimo)||0, parseFloat(p.stockMaximo)||0);

      // SUNAT con migración legacy gravado→1, exonerado→2, inafecto→3
      const tipoIgvLegacy = { 'gravado': '1', 'exonerado': '2', 'inafecto': '3' };
      const tipoIgvVal = String(p.Tipo_IGV || '1').toLowerCase();
      $('prodTipoIGV').value     = tipoIgvLegacy[tipoIgvVal] || (p.Tipo_IGV ? String(p.Tipo_IGV) : '1');
      $('prodCodTributo').value  = p.Cod_Tributo     || '1000';
      $('prodIGV').value         = (p.IGV_Porcentaje !== undefined && p.IGV_Porcentaje !== '') ? p.IGV_Porcentaje : 18;
      // prodUnidadMedida ya se sincronizó arriba con prodUnidad (campo unificado)
      $('prodCodSUNAT').value    = p.Cod_SUNAT       || '10000000';
      _actualizarResumenSunat();

      // Determinar tipo correctamente según el modelo de datos:
      // - Envasable (granel): esEnvasable = 1
      // - Derivado (envasado del granel): tiene codigoProductoBase
      // - Presentación (variante del base, ej tripack): factorConversion > 1
      // - Normal/Base (canónico): factor = 1 o vacío, sin codigoProductoBase
      // OJO: skuBase y idProducto siempre son distintos en formato (IDPRO vs LEV),
      // por eso NO sirven como criterio para distinguir base de presentación.
      let tipo = 'normal';
      const factor = parseFloat(p.factorConversion);
      if (_esEnvasable(p)) {
        tipo = 'envasable';
      } else if (p.codigoProductoBase && String(p.codigoProductoBase).trim()) {
        tipo = 'derivado';
      } else if (factor && factor > 0 && factor !== 1) {
        tipo = 'presentacion';
      }
      // else: factor=1 o vacío + sin codigoProductoBase = base/normal/canónico
      setProdTipo(tipo);
      // [RONDA 4] la barra de tipos NO se muestra ni en edición (el tipo NO se cambia
      // tocando botones — dibujo §04): el título dice QUÉ estás editando, con su ícono.
      $('prodTipoBar')?.classList.add('hidden');
      $('modalProdTitle').textContent = 'Editar · ' + (
        tipo === 'envasable'    ? '⚗️ Granel envasable' :
        tipo === 'derivado'     ? '🥄 Derivado' :
        tipo === 'presentacion' ? '🧱 Presentación' : '🔵 Canónico');

      // [fix dueño 2026-07-14] Convertir Canónico ⇄ Granel envasable también al EDITAR (antes el toggle
      // solo aparecía al CREAR → un producto ya creado no se podía volver envasable). Solo aplica a
      // canónico/envasable; derivado/presentación no se convierten a granel desde aquí.
      const _envConvertible = (tipo === 'normal' || tipo === 'envasable');
      $('prodEnvasableRow')?.classList.toggle('hidden', !_envConvertible);
      $('prodEnvasableSw')?.classList.toggle('on', tipo === 'envasable');
      // [597] insumo: editable en canónico/granel (un derivado/presentación no es insumo de otros)
      $('prodInsumoRow')?.classList.toggle('hidden', !_envConvertible);
      $('prodInsumoSw')?.classList.toggle('on', String(p.esInsumo) === '1');

      if (tipo === 'derivado') {
        $('prodCodigoProductoBase').value = p.codigoProductoBase || '';
        $('prodFactorConvBase').value     = p.factorConversionBase || '';
        try { _prodDerivadoPreview(); } catch(_){}   // [424]
      }
      if (tipo === 'presentacion') {
        $('prodSkuBase').value = p.skuBase || '';
        $('prodFactor').value  = p.factorConversion || '';
      }

      // Equivalencias
      // [RONDA 5] la sección de equivalencias SALIÓ del modal producto (redundante con
      // el ＋ del card, dibujo §02/§04): agregar Y gestionar (activar/desactivar) viven
      // en el modal 🏷️ Equivalente del ＋ contextual.
      $('modalEquivSection')?.classList.add('hidden');
      _loadEquivModal(p.skuBase || p.idProducto);

      // Política de precios (override del producto si tiene)
      const tieneOverride = !!(p.modoVenta && String(p.modoVenta).trim());
      $('prodPoliticaOverride').checked = tieneOverride;
      if (tieneOverride) {
        $('prodModoVenta').value = String(p.modoVenta).toUpperCase();
        $('prodMargenPct').value = (p.margenPct !== '' && p.margenPct !== undefined && p.margenPct !== null) ? p.margenPct : '';
        $('prodPrecioTope').value = (parseFloat(p.precioTope) > 0) ? p.precioTope : '';
      } else {
        $('prodModoVenta').value = 'MARGEN';
        $('prodMargenPct').value = '';
        $('prodPrecioTope').value = '';
      }
      _prodOnPoliticaOverride();
      _prodActualizarPoliticaEfectiva();
    } else {
      $('modalProdTitle').textContent = 'Nuevo Producto';
      // [RONDA 5 · gap dibujo §04] el código nace PRE-GENERADO (N- validado contra
      // productos+equivalencias); el botón queda como "Regenerar" y 📷 lo reemplaza
      prodAutogenBarcode(true);
      // Defaults autorrelleno (típico abarrote: gravado 18%)
      $('prodUnidad').value       = 'NIU';
      $('prodUnidadMedida').value = 'NIU';
      $('prodTipoIGV').value      = '1';   // 1 = Gravado
      $('prodCodTributo').value   = '1000';
      $('prodIGV').value          = '18';
      $('prodCodSUNAT').value     = '10000000';
      _actualizarResumenSunat();
      // Política: por default heredar
      $('prodPoliticaOverride').checked = false;
      $('prodModoVenta').value = 'MARGEN';
      $('prodMargenPct').value = '';
      $('prodPrecioTope').value = '';
      _prodOnPoliticaOverride();
      _prodActualizarPoliticaEfectiva();
    }
    // [v2.41.97] Cargar segmentos del producto + mostrar sección si KGM
    try {
      // [RONDA 5 · purga] segCargarParaProducto / segActualizarVisibilidad eliminados
      // (los tramos viven en el modal ＋Tramo). Se quitó también el bloque residual que
      // escribía en _segState (variable ya purgada → ReferenceError).
    } catch(_) {}
    openModal('modalProducto');
  }

  // ── Modal producto: política de precios ───────────────────
  function prodTogglePolitica() {
    const sec = $('prodSecPolitica');
    const ch  = $('politicaChevron');
    if (!sec) return;
    const oculta = sec.classList.contains('hidden');
    sec.classList.toggle('hidden');
    if (ch) ch.textContent = oculta ? '▼' : '▶';
  }

  function _prodOnPoliticaOverride() {
    const on = $('prodPoliticaOverride')?.checked;
    $('prodPoliticaCampos')?.classList.toggle('hidden', !on);
    if (on) _prodOnModoChange();
  }

  function _prodOnModoChange() {
    const modo = $('prodModoVenta')?.value;
    $('prodMargenWrap')?.classList.toggle('hidden', modo === 'FIJO' || modo === 'LIBRE');
    $('prodTopeWrap')?.classList.toggle('hidden', modo !== 'COMPETITIVO');
  }

  function _prodActualizarPoliticaEfectiva() {
    // [640] la categoría ya NO define política: el margen es por producto (o default 25%)
    const el = $('prodPoliticaEfectiva');
    if (!el) return;
    const override = $('prodPoliticaOverride')?.checked;
    if (override) {
      const modo = $('prodModoVenta')?.value || 'MARGEN';
      const margen = parseFloat($('prodMargenPct')?.value);
      const detalle = (modo === 'MARGEN' || modo === 'COMPETITIVO') && !isNaN(margen)
        ? `${modo} ${margen}%` : modo;
      el.innerHTML = `Política efectiva: <span class="text-amber-400 font-semibold">${detalle}</span> <span class="text-slate-600">(de este producto)</span>`;
    } else {
      el.innerHTML = `Política efectiva: <span class="text-slate-400">MARGEN 25% <span class="text-slate-600">(default — defínela por producto si quieres otra)</span></span>`;
    }
  }

  // Carga y renderiza equivalencias dentro del modal
  async function _loadEquivModal(skuBase) {
    const list = $('equivList');
    if (!list) return;
    list.innerHTML = '<div class="text-xs text-slate-600 italic py-1 px-1">Cargando...</div>';
    try {
      const rows = (await API.get('getEquivalencias', { skuBase })) || [];
      // Actualizar equivMap también
      S.equivMap[skuBase] = rows.filter(r => String(r.activo) === '1').map(r => r.codigoBarra).filter(Boolean);
      // [RONDA 5 · purga] _renderEquivList eliminado — _loadEquivModal solo refresca S.equivMap
    } catch(e) {
      list.innerHTML = `<div class="text-xs text-red-400 py-1 px-1">Error: ${e.message}</div>`;
    }
  }

  // [RONDA 5 · purga] equivalencias embebidas (render/add/crear) eliminado.
  function _actualizarVisualProducto(idProducto, activo) {
    // Toggle button
    const toggle = document.querySelector(`.toggle-sw[data-pid="${idProducto}"]`);
    if (toggle) {
      toggle.classList.toggle('on', activo);
      toggle.title = activo ? 'Apagar' : 'Prender';
    }
    // Si es presentación: pres-chip
    const presChip = document.querySelector(`.pres-chip[data-pres-id="${idProducto}"]`);
    if (presChip) {
      presChip.classList.toggle('pres-inactive', !activo);
    }
    // Si es base: cat-card
    const catCard = document.querySelector(`.cat-card[data-cat-id="${idProducto}"]`);
    if (catCard) {
      catCard.classList.toggle('cat-inactive', !activo);
    }
  }

  // [v2.41.95] Set de IDs con toggle en flight — protege el optimistic UI
  // contra el polling silencioso de catálogo que corre cada 60s. Sin esto,
  // si el polling corre entre el optimistic y la confirmación del POST,
  // sobrescribe con el estado viejo y el producto "vuelve a activarse".
  const _togglesEnVuelo = new Set();
  // También: timestamp por idProducto para que el refresh ignore por X seg
  // tras un toggle, incluso si el POST ya respondió (Sheets puede tardar
  // hasta unos segundos en reflejar el cambio en lecturas posteriores).
  const _togglesRecientes = new Map(); // idProducto → timestamp
  const _TOGGLE_PROTECCION_MS = 8000; // 8s post-POST

  function _toggleEstaProtegido(idProducto) {
    if (_togglesEnVuelo.has(idProducto)) return true;
    const ts = _togglesRecientes.get(idProducto);
    if (ts && (Date.now() - ts) < _TOGGLE_PROTECCION_MS) return true;
    return false;
  }
  function _marcarToggleReciente(idProducto) {
    _togglesRecientes.set(idProducto, Date.now());
    // Cleanup automático tras la protección
    setTimeout(() => _togglesRecientes.delete(idProducto), _TOGGLE_PROTECCION_MS + 1000);
  }

  // ── Toggle estado activo/inactivo de producto ────────────────
  // esBase=true: si apagas → flip visual + confirmación. Si prendes → cascada directa.
  // esBase=false: solo toggle local (presentación independiente).
  async function toggleProductoActivo(idProducto, esBase) {
    const p = S.productos.find(x => x.idProducto === idProducto);
    if (!p) return;
    const activoActual = _isProdActivo(p);

    if (esBase && activoActual) {
      // Apagar base con confirmación: flip visual inmediato + abrir modal
      _actualizarVisualProducto(idProducto, false);
      _pedirApagarBase(idProducto);
      return;
    }

    const nuevoEstado = activoActual ? '0' : '1';

    // OPTIMISTIC: actualizar UI primero
    p.estado = nuevoEstado;
    _actualizarVisualProducto(idProducto, nuevoEstado === '1');
    _togglesEnVuelo.add(idProducto); // proteger del polling
    // Toast más claro con flash visual del cambio
    toast(nuevoEstado === '1' ? '🟢 Activado · ' + (p.descripcion || idProducto).substring(0, 30)
                              : '⚫ Apagado · ' + (p.descripcion || idProducto).substring(0, 30),
          'ok', 1800);

    // Si es base prendiendo, cascadear visualmente a las presentaciones del grupo
    if (esBase && nuevoEstado === '1') {
      const skuBase = p.skuBase || idProducto;
      S.productos.forEach(pp => {
        if ((pp.skuBase || pp.idProducto) === skuBase && pp.idProducto !== idProducto) {
          if (!_isProdActivo(pp)) {
            pp.estado = '1';
            _actualizarVisualProducto(pp.idProducto, true);
            _togglesEnVuelo.add(pp.idProducto);
          }
        }
      });
    }

    // POST en background sin bloquear UI
    try {
      const res = await API.post('actualizarProducto', { _source: 'MOS_TOGGLE', idProducto, estado: nuevoEstado });
      if (res && res.ok === false) {
        throw new Error(res.error || 'GAS rechazó el cambio');
      }
      if (esBase && nuevoEstado === '1') {
        // Prender hijos en backend (presentaciones + equivalencias)
        _prenderHijos(p).catch(() => {});
      }
      // Marcar como reciente para que el polling siga respetando este cambio
      _marcarToggleReciente(idProducto);
      if (esBase && nuevoEstado === '1') {
        const skuBase = p.skuBase || idProducto;
        S.productos.forEach(pp => {
          if ((pp.skuBase || pp.idProducto) === skuBase) _marcarToggleReciente(pp.idProducto);
        });
      }
    } catch(e) {
      // Revertir en caso de error
      p.estado = activoActual ? '1' : '0';
      _actualizarVisualProducto(idProducto, activoActual);
      toast('⚠ No se pudo guardar: ' + (e.message || e), 'error');
    } finally {
      _togglesEnVuelo.delete(idProducto);
    }
  }

  // [628 · decisión 5] Los DOS interruptores de cada ítem del catálogo — apagar producto
  // y canal GO (MosGo) — son EXCLUSIVOS del MASTER: los demás admins no los ven siquiera.
  // [2.43.674 · feedback dueño] Nada de moto ni fondo multicolor: pill sobria "GO" —
  // encendida: violeta sólido MosGo con texto blanco; apagada: borde punteado gris.
  function _togglesMosgoHtml(prod, sm) {
    if (!_esMasterSession() || !prod) return '';
    const go = String(prod.canalMayoreo) === '1';
    // [2.43.679] por CLASES (.go-pill/.on) para poder actualizar el botón EN SITIO
    // al togglear — antes se repintaba el catálogo completo y parpadeaba todo.
    return `<button type="button" class="go-pill${sm ? ' sm' : ''}${go ? ' on' : ''}" data-go="${prod.idProducto}"
              onclick="event.stopPropagation();MOS.toggleMosgo('${prod.idProducto}')"
              title="${go ? 'Se vende en MosGo — tocar para quitarlo (ME no se toca)'
                          : 'Vender en MosGo (ME no se toca)'}">GO</button>`;
  }

  // [2.43.679] Prende/apaga las pills GO de un producto EN SITIO (aparece en 1 o más
  // renders de la misma card) — cero re-render, cero parpadeo.
  function _pintarGo(idProducto, on) {
    document.querySelectorAll('[data-go="' + idProducto + '"]').forEach(b => {
      b.classList.toggle('on', !!on);
      b.title = on ? 'Se vende en MosGo — tocar para quitarlo (ME no se toca)'
                   : 'Vender en MosGo (ME no se toca)';
    });
  }

  // [628] Interruptor del canal MosGo. ON enciende también el catálogo (todo lo de MosGo
  // se vende en ME — decisión 1); OFF apaga AMBOS en cascada (decisión 3). El guard
  // MASTER real vive server-side en mos.catalogo_toggle_mosgo (SOLO_MASTER).
  async function toggleMosgo(idProducto) {
    if (!_esMasterSession()) { toast('Solo Master', 'error'); return; }
    const p = S.productos.find(x => x.idProducto === idProducto);
    if (!p) return;
    const cb = String(p.codigoBarra || '').trim();
    if (!cb) { toast('⚠ Este ítem no tiene código de barras — MosGo vende por código', 'error'); return; }
    const on = String(p.canalMayoreo) !== '1';
    const goPrevio = p.canalMayoreo;
    // [633] INDEPENDENCIA TOTAL (decisión final del dueño): el GO gobierna SOLO MosGo y
    // el toggle de prendido gobierna SOLO ME. Ninguno toca al otro — "así no combinamos".
    p.canalMayoreo = on ? '1' : '0';
    _togglesEnVuelo.add(idProducto);
    // [2.43.679] SOLO se pinta el botón tocado — repintar el catálogo entero hacía
    // parpadear todas las cards (animación de entrada) en cada toque.
    _pintarGo(idProducto, on);
    toast(on ? '🚀 Visible en MosGo' : '⚪ Fuera de MosGo', 'ok', 2000);
    try {
      await API.post('toggleMosgo', { codigoBarra: cb, on });
      _marcarToggleReciente(idProducto);
    } catch (e) {
      p.canalMayoreo = goPrevio;
      _pintarGo(idProducto, String(goPrevio) === '1');
      toast('⚠ No se pudo guardar: ' + (e.message || e), 'error');
    } finally {
      _togglesEnVuelo.delete(idProducto);
    }
  }

  async function _prenderHijos(baseProd) {
    const skuBase = baseProd.skuBase || baseProd.idProducto;
    const presentaciones = S.productos.filter(p =>
      (p.skuBase || p.idProducto) === skuBase && p.idProducto !== baseProd.idProducto
    );
    await Promise.all(presentaciones.map(async pp => {
      if (_isProdActivo(pp)) return;
      await API.post('actualizarProducto', { _source: 'MOS_TOGGLE_CASCADA', idProducto: pp.idProducto, estado: '1' });
      pp.estado = '1';
    }));
    try {
      const equivs = await API.get('getEquivalencias', { skuBase });
      const inactivas = (equivs || []).filter(e => {
        const v = e.activo;
        return !(v === '1' || v === 1 || v === true || String(v).toLowerCase() === 'true');
      });
      await Promise.all(inactivas.map(e =>
        API.post('actualizarEquivalencia', { _source: 'MOS_TOGGLE_CASCADA', idEquiv: e.idEquiv, activo: '1' })
      ));
    } catch(_) {}
  }

  function _pedirApagarBase(idProducto) {
    const p = S.productos.find(x => x.idProducto === idProducto);
    if (!p) return;
    const skuBase = p.skuBase || idProducto;
    const presentaciones = S.productos.filter(pp =>
      (pp.skuBase || pp.idProducto) === skuBase && pp.idProducto !== idProducto
    );
    $('apagarBaseId').value = idProducto;
    $('apagarBaseSku').value = skuBase;
    $('apagarBaseTitle').textContent = p.descripcion || idProducto;
    $('apagarBasePresCount').textContent = presentaciones.length;
    $('apagarBasePresList').innerHTML = presentaciones.length > 0
      ? presentaciones.map(pp => `<li>— ${pp.descripcion || pp.idProducto}</li>`).join('')
      : '<li class="italic">— sin presentaciones —</li>';
    $('apagarBaseEqCount').textContent = '…';
    $('apagarBaseEqList').innerHTML = '<li class="italic">— cargando —</li>';
    const modal = $('modalApagarBase');
    modal.dataset.equivs = '[]';
    openModal('modalApagarBase');

    API.get('getEquivalencias', { skuBase }).then(equivs => {
      const activas = (equivs || []).filter(e => {
        const v = e.activo;
        return v === '1' || v === 1 || v === true || String(v).toLowerCase() === 'true';
      });
      $('apagarBaseEqCount').textContent = activas.length;
      $('apagarBaseEqList').innerHTML = activas.length > 0
        ? activas.map(e => `<li>— ▌${e.codigoBarra}${e.descripcion ? ' (' + e.descripcion + ')' : ''}</li>`).join('')
        : '<li class="italic">— sin equivalencias activas —</li>';
      modal.dataset.equivs = JSON.stringify(activas.map(e => e.idEquiv));
    }).catch(() => {
      $('apagarBaseEqCount').textContent = '?';
      $('apagarBaseEqList').innerHTML = '<li class="italic text-red-400">— error al cargar —</li>';
    });
  }

  async function confirmarApagarBase() {
    const idProducto = $('apagarBaseId').value;
    const skuBase    = $('apagarBaseSku').value;
    const equivIds   = JSON.parse($('modalApagarBase').dataset.equivs || '[]');
    if (!idProducto) return;

    const productos = S.productos.filter(pp =>
      (pp.skuBase || pp.idProducto) === skuBase || pp.idProducto === idProducto
    );

    // OPTIMISTIC: marcar todos como apagados visualmente y cerrar modal de inmediato
    productos.forEach(pp => {
      pp.estado = '0';
      _actualizarVisualProducto(pp.idProducto, false);
    });
    closeModal('modalApagarBase');
    toast('Apagado ' + productos.length + ' producto(s) ✓', 'ok');

    // Marcador de "no revertir" en el modal (la confirmación procedió)
    $('modalApagarBase').dataset.confirmado = '1';

    // POST en background
    try {
      await Promise.all(productos.map(pp =>
        API.post('actualizarProducto', { _source: 'MOS_TOGGLE_CASCADA', idProducto: pp.idProducto, estado: '0' })
      ));
      await Promise.all(equivIds.map(idEquiv =>
        API.post('actualizarEquivalencia', { _source: 'MOS_TOGGLE_CASCADA', idEquiv, activo: '0' })
      ));
    } catch(e) {
      toast('Error de sincronización: ' + e.message, 'error');
    }
  }

  // Cerrar modal apagar base SIN confirmar → revertir flip visual del toggle base
  function cerrarApagarBaseRevertir() {
    const modal = $('modalApagarBase');
    if (modal && modal.dataset.confirmado !== '1') {
      const idProducto = $('apagarBaseId').value;
      if (idProducto) _actualizarVisualProducto(idProducto, true);
    }
    if (modal) delete modal.dataset.confirmado;
    closeModal('modalApagarBase');
  }

  // [RONDA 5 · purga] toggleEquivActivo eliminado.
  function _prodTipoDe(p) {
    if (!p) return 'normal';
    if (p.codigoProductoBase && String(p.codigoProductoBase).trim()) return 'derivado';
    const f = parseFloat(p.factorConversion);
    if (f && f !== 1) return 'presentacion';
    if (_esEnvasable(p)) return 'envasable';
    return 'normal';
  }

  // Matriz del ＋ (los porqués del dibujo van como subtítulo de cada opción)
  function abrirPlusContextual(idProducto, ev) {
    try { ev && ev.stopPropagation(); } catch(_){}
    _cerrarPlusCtx();
    const p = S.productos.find(x => x.idProducto === idProducto);
    if (!p) return;
    const tipo = _prodTipoDe(p);
    // [782] FIN DE LA BIFURCACIÓN (hallazgo del dueño, caso ají panca EXTRA): el TRAMO
    // es cosa de productos que se venden PESADOS (unidad KGM — lo único que ME mira
    // para cobrarlos), NO del toggle envasable (que solo habilita derivados). Antes un
    // granel KGM sin envasable no podía crear tramos, y un envasable no-KGM podía
    // crear tramos que el POS jamás cobraría.
    const esKgm = (typeof _normalizarUnidad === 'function'
      ? _normalizarUnidad(p.unidad || p.unidadMedida) : String(p.unidad || '').toUpperCase()) === 'KGM';
    const ops = [];
    if (tipo === 'envasable') {
      // [629 · regla del saco] El granel AHORA sí lleva presentación — siempre de PRECIO
      // FIJO (se cobra la etiqueta; el stock descuenta factor × kg del canónico). El
      // candado viejo del menú quedó obsoleto junto con el del modal.
      ops.push({ k:'derivado',     ic:'🥄', t:'Derivado',     d:'fracción envasada del granel (250gr, 500gr…)' });
      ops.push({ k:'presentacion', ic:'📦', t:'Presentación FIJA', d:'saco/pack con precio de etiqueta (descuenta factor × kg)' });
      if (esKgm) ops.push({ k:'tramo', ic:'📊', t:'Tramo', d:'precio por rango de peso (descuento por volumen)' });
      ops.push({ k:'equivalente',  ic:'🏷️', t:'Equivalente',  d:'otro código de barra del mismo producto' });
    } else if (tipo === 'presentacion') {
      // [fix rev M3 · money-safe] el modelo de equivalencias cuelga del sku_base del GRUPO:
      // un "equivalente del pack" resolvería al CANÓNICO → se cobraría 1 unidad en vez del
      // pack (12x menos). Hasta que exista equivalencia-por-producto, un pack NO admite satélites.
      toast('🧱 Un pack no admite satélites: su 2do código NO puede ser equivalente (apuntaría al canónico y se cobraría como 1 unidad). Agrégalo desde el canónico si corresponde.', 'error');
      return;
    } else { // canónico normal o derivado
      ops.push({ k:'presentacion', ic:'🧱', t:'Presentación', d:'pack ×N o fracción ÷N (precio propio)' });
      // [782] canónico KGM sin envasable (ej. ají panca EXTRA): se vende pesado → SÍ lleva tramos
      if (esKgm && tipo === 'normal') ops.push({ k:'tramo', ic:'📊', t:'Tramo', d:'precio por rango de peso (se cobra al pesar)' });
      ops.push({ k:'equivalente',  ic:'🏷️', t:'Equivalente',  d:'otro código de barra' });
    }
    const html = `<div id="plusCtxMenu" class="fixed z-[95] overflow-hidden cat-pop-std"
        style="min-width:250px">
      <div class="px-3 py-2 text-[10px] font-bold uppercase tracking-wider" style="color:#93a4c2;border-bottom:1px solid #1e293b">
        ＋ agregar a · <span style="color:#34d399">${_escapeHtml((p.descripcion||'').slice(0,28))}</span></div>
      ${ops.map(o => `<button onclick="MOS._cerrarPlusCtx();MOS.abrirModalSatelite('${o.k}','${_escapeHtml(idProducto)}')"
          class="w-full flex items-start gap-2.5 px-3 py-2.5 text-left hover:bg-slate-800/60" style="border-bottom:1px solid #0e1626">
        <span class="text-lg leading-none mt-0.5">${o.ic}</span>
        <span class="min-w-0"><span class="block text-[13px] font-bold text-slate-100">${o.t}</span>
        <span class="block text-[10.5px] text-slate-500">${o.d}</span></span></button>`).join('')}
    </div>`;
    document.body.insertAdjacentHTML('beforeend', html);
    const menu = document.getElementById('plusCtxMenu');
    const r = ev?.target?.closest('button')?.getBoundingClientRect();
    if (r && menu) {
      const mw = 260, mh = menu.offsetHeight || 200;
      let x = Math.min(r.left, window.innerWidth - mw - 8);
      let y = (r.bottom + mh + 8 > window.innerHeight) ? (r.top - mh - 6) : (r.bottom + 6);
      menu.style.left = Math.max(8, x) + 'px';
      menu.style.top  = Math.max(8, y) + 'px';
    }
    setTimeout(() => document.addEventListener('click', _cerrarPlusCtx, { once: true }), 30);
  }
  function _cerrarPlusCtx() { document.getElementById('plusCtxMenu')?.remove(); }

  // ═══ [v5 §10] MODAL CURVAS · click al PRECIO → precio·costo·margen bidireccional ═══
  // Costo del satélite = SIEMPRE derivado del canónico × factor (fcb derivado, factor pack).
  function _costoDerivado(p) {
    const propio = parseFloat(p.precioCosto) || 0;
    const fcb = parseFloat(p.factorConversionBase) || 0;
    const fc  = parseFloat(p.factorConversion) || 1;
    if (!p.codigoProductoBase && fc === 1) return propio;          // canónico: su costo
    // padre canónico del grupo (derivado → codigoProductoBase; pack → skuBase)
    const U = s => String(s || '').trim().toUpperCase();
    const ref = p.codigoProductoBase ? U(p.codigoProductoBase) : U(p.skuBase || '');
    const padre = (S.productos || []).find(x =>
      (U(x.skuBase || x.idProducto) === ref || U(x.idProducto) === ref)
      && (parseFloat(x.factorConversion) || 1) === 1
      && !(x.codigoProductoBase && String(x.codigoProductoBase).trim()));
    const costoPadre = parseFloat(padre?.precioCosto) || 0;
    if (costoPadre <= 0) return propio;                            // sin costo del padre → el propio (o 0)
    return +(costoPadre * (p.codigoProductoBase ? fcb : fc)).toFixed(4);
  }

  const _r1 = v => Math.round((parseFloat(v) || 0) * 10) / 10;     // redondeo 1 decimal (regla del dueño)

  async function abrirModalPrecioCurvas(idProducto) {
    const p = S.productos.find(x => x.idProducto === idProducto);
    if (!p) return;
    // [H8] El editor de precios del CATALOGO es EL MISMO del Paso 2 (modo catalogo): precio<->margen
    // bidireccional + satelites con toggle + curva cartesiana con click-a-registro. Al guardar,
    // publica y graba el margen de contrato (mismo comportamiento que el viejo modal §10).
    const costo = _costoDerivado(p);
    _paso2Abrir([{ idCanonico: idProducto, costoNuevo: costo, costoAnterior: costo }], null, { modo: "catalogo", titulo: p.descripcion || idProducto });
  }

  // [RONDA 3] EDITAR POR TIPO (lógica del dueño): tocar un derivado abre el modal
  // de derivado (prellenado), una presentación el suyo; el canónico/granel abre el
  // modal completo. "Edición avanzada" (stock/costo/política) → modal completo.
  function abrirEditarProducto(id) {
    const p = S.productos.find(x => x.idProducto === id);
    if (!p) { toast('Producto no encontrado', 'error'); return; }
    const tipo = _prodTipoDe(p);
    const U = s => String(s || '').trim().toUpperCase();
    let padre = null;
    if (tipo === 'derivado') {
      padre = S.productos.find(x =>
        (U(x.skuBase || x.idProducto) === U(p.codigoProductoBase) || U(x.idProducto) === U(p.codigoProductoBase))
        && x.idProducto !== p.idProducto);
    } else if (tipo === 'presentacion') {
      padre = S.productos.find(x =>
        (x.skuBase || x.idProducto) === (p.skuBase || '')
        && x.idProducto !== p.idProducto
        && (parseFloat(x.factorConversion) || 1) === 1
        && !(x.codigoProductoBase && String(x.codigoProductoBase).trim()));
    }
    if ((tipo === 'derivado' || tipo === 'presentacion') && padre) {
      abrirModalSatelite(tipo, padre.idProducto, p);
      return;
    }
    abrirModalProducto(id);   // canónico/granel (o satélite sin padre resoluble)
  }

  // ── Modal satélite: un body enfocado por tipo ──────────────────────
  const _SAT_CAM = (inputId) => `<button type="button" class="btn-cam-scan" onclick="MOS.scanCodigo({inputId:'${inputId}'})" title="Escanear con la cámara">
    <svg viewBox="0 0 24 24"><path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z"/><circle cx="12" cy="13" r="4"/></svg></button>`;

  async function abrirModalSatelite(tipo, idPadre, editarProd) {
    const padre = S.productos.find(x => x.idProducto === idPadre);
    if (!padre) { toast('Producto padre no encontrado', 'error'); return; }
    _satState = { tipo, padre, editar: editarProd || null };
    const tit = $('satTitulo'), ctx = $('satContexto'), her = $('satHerencia'), body = $('satBody'), btn = $('satGuardarBtn');
    // [783] RESET del botón compartido: editar un tramo lo deja "Sin cambios que guardar"
    // (disabled) y al reabrir el modal para algo NUEVO quedaba muerto (caso CHARQUI).
    if (btn) { btn.disabled = false; btn.style.opacity = ''; btn.style.cursor = ''; }
    const tipoPadre = _prodTipoDe(padre);
    const igvTxt = (padre.Tipo_IGV || padre.tipoIGV) === '2' ? 'Exonerado' : (padre.Tipo_IGV || padre.tipoIGV) === '3' ? 'Inafecto' : 'IGV 18%';
    ctx.textContent = 'desde · ' + (padre.descripcion || idPadre) + (tipoPadre === 'envasable' ? ' (granel)' : '');
    her.classList.add('hidden');

    if (tipo === 'derivado') {
      tit.textContent = '🥄 Nuevo derivado';
      her.classList.remove('hidden');
      her.textContent = `Hereda del granel: ${igvTxt} · categoría ${padre.idCategoria || '—'} — no se vuelve a pedir`;
      body.innerHTML = `
        <div><label class="lbl">Nombre <span class="text-rose-400">*</span></label>
          <input id="satNombre" class="inp w-full" placeholder="Ej: ${_escapeHtml((padre.descripcion||'').replace(/GRANEL/i,'').trim())} 250GR" oninput="MOS._satDerivadoPreview()">
          <div id="satNombreHint" class="text-[11px] mt-1"></div></div>
        <div><label class="lbl">Porción del granel por unidad (kg) <span class="text-rose-400">*</span></label>
          <input id="satPorcion" class="inp w-full" type="number" step="0.001" min="0.001" placeholder="0.250" oninput="MOS._satPorcionInput()">
          <div id="satPorcionHint" class="text-[11px] mt-1 text-slate-500">Cualquier tamaño · ej: 250gr = 0.250 · 5kg = 5 · 25kg = 25</div></div>
        <div class="grid grid-cols-2 gap-3">
          <div><label class="lbl">Precio venta <span class="text-rose-400">*</span></label>
            <input id="satPrecio" class="inp w-full" type="number" step="0.10" min="0.10" placeholder="0.00" oninput="MOS._satPrecioInput()">
            <div id="satPrecioHint" class="text-[10px] mt-1 text-slate-500"></div></div>
          <div><label class="lbl">Código <span class="text-[9px]" style="color:#34d399">auto WH-</span></label>
            <div class="flex gap-1.5"><input id="satCodigo" class="inp flex-1 font-mono text-xs" oninput="MOS._satValidarCodigo()">
            ${_SAT_CAM('satCodigo')}</div><div id="satCodigoFb" class="text-[10px] mt-1"></div></div>
        </div>
        <div><label class="lbl">🛍 Envase <span class="text-[9px] text-slate-500 font-normal">bolsa/insumo que consume al envasarse · opcional</span></label>
          <div class="relative">
            <input id="satEnvase" class="inp w-full" placeholder="Escribe para filtrar… ej 4.5*5 o celofan" autocomplete="off"
                   oninput="MOS._satEnvaseFiltra()" onfocus="MOS._satEnvaseFiltra()" onblur="MOS._satEnvaseCierra()">
            <div id="satEnvaseOps" class="hidden absolute z-50 left-0 right-0 mt-1 rounded-lg overflow-auto"
                 style="max-height:180px;background:#0e1626;border:1px solid #28344c;box-shadow:0 12px 28px rgba(0,0,0,.5)"></div>
          </div>
          <div id="satEnvaseHint" class="text-[10px] mt-1"></div></div>`;
      // [RONDA 3] modo EDICIÓN: prellenar + guardar cambios (sin autogenerar código)
      if (editarProd) {
        tit.textContent = '🥄 Editar derivado';
        btn.textContent = 'Guardar cambios';
        body.insertAdjacentHTML('beforeend', `<button type="button" class="w-full text-[11px] text-slate-500 hover:text-slate-300 py-1"
          onclick="MOS.cerrarModalSatelite();MOS.abrirModalProducto('${editarProd.idProducto}')">⚙️ Edición avanzada (stock, costo, política…)</button>`);
        openModal('modalSatelite');
        $('satNombre').value  = editarProd.descripcion || '';
        $('satPorcion').value = parseFloat(editarProd.factorConversionBase) || '';
        $('satPrecio').value  = parseFloat(editarProd.precioVenta) || '';
        $('satCodigo').value  = editarProd.codigoBarra || '';
        // [dueño 2026-07-14] EDICIÓN: la porción y el precio ya vienen del producto → NO auto-sugerir encima
        // (pero los avisos "precio bajo / peso no coincide" sí se muestran).
        _satPorcionManual = true; _satPrecioManual = true;
        _satEnvaseInit(editarProd.envaseSku || '');   // [597] envase actual del derivado
        _satDerivadoPreview();
        return;
      }
      btn.textContent = 'Crear derivado';
      openModal('modalSatelite');
      _satEnvaseInit('');   // [597] envase: nace pendiente (el hint avisa)
      // [dueño 2026-07-14] B: pre-llenar el nombre con la FAMILIA del padre (sin "GRANEL"), cursor al final,
      // para que el usuario solo agregue el gramaje (250GR / 5KG). C+A (peso→porción→precio) se auto-sugieren
      // vía _satDerivadoPreview a medida que escribe. Flags manuales en false: aún no tocó porción/precio.
      _satPorcionManual = false; _satPrecioManual = false;
      { const _fam = String(padre.descripcion || '').replace(/\bGRANEL\b/ig, '').replace(/\s+/g, ' ').trim();
        const _n = $('satNombre');
        if (_n) { _n.value = _fam ? _fam + ' ' : '';
          setTimeout(() => { try { _n.focus(); _n.setSelectionRange(_n.value.length, _n.value.length); } catch (_) {} }, 250); } }
      try { _satDerivadoPreview(); } catch (_) {}
      // [fix rev B1] guardia anti-carrera: si cerraron/cambiaron el modal durante el
      // roundtrip del generador, NO pisar el input del modal nuevo
      { const st = _satState; const cb = await genCodigoUnico('WH-');
        if (_satState === st && $('satCodigo')) $('satCodigo').value = cb; }
      return;
    }

    if (tipo === 'presentacion') {
      // [629 · regla del saco] El candado "granel no lleva presentación" se REEMPLAZA:
      // ahora un granel SÍ puede tener presentación, pero SIEMPRE de PRECIO FIJO — se
      // cobra la etiqueta (ME 2.8.249 la trata como unidad) y el stock descuenta
      // factor × kg del canónico vía mos._venta_canonico. Sin el flag, ME ignoraría el
      // precio y cobraría por kg (el bug del pack ×25 de nakamito a S/200 en vez de 155).
      _satState.padreGranel = (tipoPadre === 'envasable');
      tit.textContent = editarProd ? '🧱 Editar presentación' : '🧱 Nueva presentación';
      her.classList.remove('hidden');
      her.textContent = _satState.padreGranel
        ? `PRECIO FIJO sobre granel: se cobra la etiqueta y descuenta factor × kg del stock · hereda ${igvTxt}`
        : `Hereda ${igvTxt} · categoría ${padre.idCategoria || '—'} del producto padre`;
      // [pres-v1] Picker de 2 familias (Pack ×N / Fracción ÷N). El nombre se compone (BASE · DESCRIPTOR) y el
      // código refleja el factor (P-<slug>-X{N}/D{N}). Reemplaza el input "min 2" (que bloqueaba fracciones).
      body.innerHTML = `
        <div><label class="lbl">Tipo <span class="text-rose-400">*</span></label>
          <div class="flex gap-2 mb-2">
            <button type="button" id="presFamPack" class="flex-1 py-2 rounded-lg text-xs font-bold border" onclick="MOS._presSetFamilia('pack')">🧱 Pack (×N)</button>
            <button type="button" id="presFamFrac" class="flex-1 py-2 rounded-lg text-xs font-bold border" onclick="MOS._presSetFamilia('frac')">✂️ Fracción (÷N)</button>
            ${_satState.padreGranel ? `<button type="button" id="presFamPeso" class="flex-1 py-2 rounded-lg text-xs font-bold border" onclick="MOS._presSetFamilia('peso')">⚖️ Por peso</button>` : ''}
          </div>
          <div id="presChips" class="flex flex-wrap gap-1.5"></div>
          <input id="presOtro" type="number" step="0.001" min="0" class="inp w-full hidden mt-1.5" oninput="MOS._presOtroInput()"></div>
        <div><label class="lbl">Descriptor <span class="text-rose-400">*</span></label>
          <input id="presDescriptor" class="inp w-full" placeholder="Tripack / Octavo…" oninput="MOS._presRecomponer()">
          <div id="presContenido" class="text-[11px] mt-1 text-slate-400"></div></div>
        <div><label class="lbl">Nombre <span class="text-[9px] text-slate-500">se compone solo · editable</span></label>
          <input id="satNombre" class="inp w-full" oninput="MOS._presNombreManual()"></div>
        <div class="grid grid-cols-2 gap-3">
          <div><label class="lbl">Precio <span class="text-rose-400">*</span></label>
            <input id="satPrecio" class="inp w-full" type="number" step="0.10" min="0.10" placeholder="0.00" oninput="MOS._presPrecioManual()">
            <div id="satPrecioHint" class="text-[10px] mt-1 text-slate-500"></div></div>
          <div><label class="lbl">Código <span class="text-[9px]" style="color:#34d399">auto P-</span></label>
            <div class="flex gap-1.5"><input id="satCodigo" class="inp flex-1 font-mono text-xs" oninput="MOS._satValidarCodigo()">
            ${_SAT_CAM('satCodigo')}</div><div id="satCodigoFb" class="text-[10px] mt-1"></div></div>
        </div>`;
      btn.textContent = editarProd ? 'Guardar cambios' : 'Crear presentación';
      if (editarProd) {
        body.insertAdjacentHTML('beforeend', `<button type="button" class="w-full text-[11px] text-slate-500 hover:text-slate-300 py-1"
          onclick="MOS.cerrarModalSatelite();MOS.abrirModalProducto('${editarProd.idProducto}')">⚙️ Edición avanzada (stock, costo, política…)</button>`);
      }
      openModal('modalSatelite');
      await _presInit(editarProd);
      return;
    }

    if (tipo === 'tramo') {
      // tramos = segmentos_precio del grupo: {min,max (gramos), ajustePct} sobre el precio canónico
      let segs = [];
      try {
        const raw = padre.segmentos_precio || padre.segmentosPrecio || '';
        segs = typeof raw === 'string' && raw ? JSON.parse(raw) : (Array.isArray(raw) ? raw : []);
      } catch(_) { segs = []; }
      _satState.segs = Array.isArray(segs) ? segs : [];
      const _segEd = (typeof editarProd === 'string' && editarProd) ? (_satState.segs || []).find(s => String(s.id) === String(editarProd)) : null;
      _satState.editSegId = _segEd ? String(_segEd.id) : null;
      const pc = parseFloat(padre.precioVenta) || 0;
      tit.textContent = _segEd ? '📊 Editar tramo' : '📊 Nuevo tramo de precio';
      her.classList.remove('hidden');
      her.textContent = `Los tramos viven por grupo (sku_base) · precio canónico S/ ${pc.toFixed(2)}/kg`;
      body.innerHTML = `
        <div class="flex items-center gap-2 mb-1">
          <label class="lbl" style="margin:0">Unidad del rango</label>
          <select id="satTramoUm" class="inp" style="width:auto;padding:4px 8px;font-size:12px" onchange="MOS._satTramoPreview()">
            <option value="g">gramos</option><option value="kg">kilos</option>
          </select>
          <span class="text-[10px] text-slate-500">· los límites <b>[</b> incluyen y <b>(</b> excluyen — toca para alternar</span>
        </div>
        <div class="grid grid-cols-2 gap-3">
          <div><label class="lbl">Desde <span class="text-rose-400">*</span></label>
            <div class="flex gap-1.5 items-center">
              <button type="button" id="satMinIncl" data-incl="1" class="inp" style="width:34px;padding:8px 0;text-align:center;font-weight:800;color:#34d399"
                      title="[ incluye este peso · ( lo excluye" onclick="MOS._satBracket(this)">[</button>
              <input id="satDesde" class="inp flex-1" type="number" step="any" min="0" placeholder="0" oninput="MOS._satTramoPreview()">
            </div></div>
          <div><label class="lbl">Hasta <span class="text-rose-400">*</span></label>
            <div class="flex gap-1.5 items-center">
              <input id="satHasta" class="inp flex-1" type="number" step="any" min="0" placeholder="100" oninput="MOS._satTramoPreview()">
              <button type="button" id="satMaxIncl" data-incl="0" class="inp" style="width:34px;padding:8px 0;text-align:center;font-weight:800;color:#fbbf24"
                      title="] incluye este peso · ) lo excluye" onclick="MOS._satBracket(this)">)</button>
            </div></div>
        </div>
        <div><label class="lbl">Ajuste sobre el canónico (%) <span class="text-rose-400">*</span></label>
          <input id="satAjuste" class="inp w-full" type="number" step="0.5" placeholder="+10" oninput="MOS._satTramoPreview()">
          <div id="satTramoHint" class="text-[11px] mt-1 text-slate-500">Ej: +10 → cobras S/ ${(pc*1.10).toFixed(2)}/kg en ese rango</div></div>
        <div><label class="lbl">Vista de la escalera</label>
          <div id="satEscalera" class="flex gap-1 mt-1"></div></div>
        <div><label class="lbl">Tramos existentes del grupo</label>
          <div id="satTramosLista" class="space-y-1.5 mt-1"></div></div>`;
      btn.textContent = _segEd ? 'Guardar cambios' : 'Guardar tramo';
      if (_segEd) _satTramoCargarEnForm(_segEd);
      openModal('modalSatelite');
      _satTramoPreview();
      _satTramosListaRender();
      return;
    }

    if (tipo === 'equivalente') {
      tit.textContent = '🏷️ Nuevo equivalente';
      her.classList.remove('hidden');
      her.textContent = 'Solo agrega OTRO código que apunta al mismo producto — sin precio ni IGV propios';
      body.innerHTML = `
        <div><label class="lbl">Código de barras equivalente <span class="text-rose-400">*</span></label>
          <div class="text-[10.5px] text-slate-500 mb-1.5">El del proveedor/caja — se escanea o escribe, NUNCA se genera</div>
          <div class="flex gap-1.5"><input id="satCodigo" class="inp flex-1 font-mono" placeholder="escanear o escribir…" oninput="MOS._satValidarCodigo()">
          ${_SAT_CAM('satCodigo')}</div><div id="satCodigoFb" class="text-[10px] mt-1"></div></div>
        <div><label class="lbl">Nota (opcional)</label>
          <input id="satNota" class="inp w-full" placeholder="Ej: código del proveedor nuevo"></div>
        <div><label class="lbl">Equivalentes existentes del grupo</label>
          <div id="satEquivLista" class="space-y-1.5 mt-1"><div class="rot-chip rot-skel" style="width:100%;min-height:34px;border-radius:10px"></div></div></div>`;
      btn.textContent = 'Agregar equivalente';
      openModal('modalSatelite');
      _satEquivListaRender();
      setTimeout(() => $('satCodigo')?.focus(), 250);
      return;
    }
  }

  function cerrarModalSatelite() { _satState = null; closeModal('modalSatelite'); }

  // Guardián porción-vs-nombre del derivado (reusa _pesoDesdeNombre: avisa, no bloquea)
  // [RONDA 7] Palabras clave del nombre de un producto (sin GRANEL ni el gramaje):
  // "NUEZ PELADA PREMIUM GRANEL" → [NUEZ, PELADA, PREMIUM]. Sirve para validar que
  // el derivado herede la FAMILIA del padre (evita el copy-paste que dejó "ECONOMICO"
  // en derivados de "PREMIUM").
  function _familiaNombre(desc) {
    return String(desc || '').toUpperCase()
      .replace(/\bGRANEL\b/g, ' ')
      .replace(/\d+\s*(?:GR|GRS|G|KG|KGS|KILO|KILOS|ML|LT|L)\b/g, ' ')
      .replace(/[^A-ZÑÁÉÍÓÚ ]/g, ' ')
      .split(/\s+/).filter(w => w.length >= 3);
  }
  // Devuelve las palabras del padre que FALTAN en el nombre del hijo.
  function _satNombreFaltantes() {
    const padre = _satState?.padre;
    const nombre = $('satNombre')?.value || '';
    if (!padre || !nombre.trim()) return [];
    const fam = _familiaNombre(padre.descripcion);
    const nomU = ' ' + nombre.toUpperCase() + ' ';
    return fam.filter(w => nomU.indexOf(w) < 0);
  }

  // [dueño 2026-07-14] Flags: el usuario tocó la porción/precio a mano → dejar de auto-sugerir encima.
  let _satPorcionManual = false, _satPrecioManual = false;
  function _satPorcionInput() { _satPorcionManual = true; _satDerivadoPreview(); }
  function _satPrecioInput()  { _satPrecioManual  = true; _satDerivadoPreview(); }
  function _satFmtPorcion(kg) { const v = Math.round(kg * 1000) / 1000; return String(v); }

  // Modal ＋Derivado inteligente: (C) el peso del nombre (250GR/5KG) sugiere la PORCIÓN;
  // (A) porción × precio del granel padre sugiere el PRECIO; ambas se auto-rellenan mientras el
  // usuario no las edite. Si las edita, se respetan y solo se AVISA abajo (precio bajo / peso ≠ nombre).
  function _satDerivadoPreview() {
    const padre  = _satState?.padre;
    const nHint  = $('satNombreHint');
    const pHint  = $('satPorcionHint');
    const prHint = $('satPrecioHint');
    const nombre = $('satNombre')?.value || '';
    const precPadre = padre ? (parseFloat(padre.precioVenta) || 0) : 0;

    // ── nombre: familia del padre ──
    if (nHint) {
      const falt = _satNombreFaltantes();
      if (nombre.trim() && falt.length) {
        nHint.innerHTML = `<span style="color:#fbbf24">⚠ El nombre no incluye "${falt.join(' ')}" del granel padre — ¿copiaste de otro producto?</span>`;
      } else if (nombre.trim()) {
        nHint.innerHTML = `<span style="color:#34d399">✓ Nombre coherente con el granel padre</span>`;
      } else { nHint.textContent = ''; }
    }

    // ── C: peso del nombre → auto-sugerir PORCIÓN (si no la tocaron) ──
    const pesoNom = (typeof _pesoDesdeNombre === 'function') ? _pesoDesdeNombre(nombre) : null;
    const porcEl = $('satPorcion');
    if (porcEl && !_satPorcionManual && pesoNom && pesoNom > 0) porcEl.value = _satFmtPorcion(pesoNom);
    const porcion = parseFloat(porcEl?.value) || 0;

    // ── A: porción × precio del granel padre → auto-sugerir PRECIO (si no lo tocaron) ──
    const sugPrecio = (precPadre > 0 && porcion > 0) ? Math.round(precPadre * porcion * 100) / 100 : 0;
    const preEl = $('satPrecio');
    if (preEl && !_satPrecioManual && sugPrecio > 0) preEl.value = sugPrecio.toFixed(2);
    const precioActual = parseFloat(preEl?.value) || 0;

    // ── porción hint: peso del nombre vs porción ──
    if (pHint) {
      if (porcion > 0 && pesoNom && Math.abs(pesoNom - porcion) > 0.001) {
        pHint.innerHTML = `<span style="color:#fbbf24">⚠ El nombre sugiere ${pesoNom} kg pero la porción es ${porcion} — verifica (el nombre suele decir la verdad)</span>`;
      } else if (porcion > 0 && pesoNom) {
        pHint.innerHTML = `<span style="color:#34d399">✓ Coincide con el nombre (${pesoNom} kg)</span>`;
      } else {
        pHint.textContent = 'Cualquier tamaño · ej: 250gr = 0.250 · 5kg = 5 · 25kg = 25';
      }
    }

    // ── precio hint: sugerencia + aviso si el manual queda muy por debajo del granel equivalente ──
    if (prHint) {
      if (sugPrecio > 0) {
        const base = `S/${precPadre.toFixed(2)}/kg × ${porcion} = S/${sugPrecio.toFixed(2)}`;
        if (_satPrecioManual && precioActual > 0 && precioActual < sugPrecio * 0.7) {
          prHint.innerHTML = `<span style="color:#fca5a5">⚠ Muy por debajo: el granel equivalente vale ~S/${sugPrecio.toFixed(2)} (${base})</span>`;
        } else if (_satPrecioManual) {
          prHint.innerHTML = `<span style="color:#94a3b8">Sugerido ${base}</span>`;
        } else {
          prHint.innerHTML = `<span style="color:#34d399">Sugerido: ${base}</span>`;
        }
      } else { prHint.textContent = ''; }
    }
  }

  // [dueño 2026-07-14] Valida la porción del derivado SIN tope superior — se puede envasar CUALQUIER tamaño
  // (250gr, 5kg, 25kg…). Único requisito: > 0. El mensaje va DENTRO del modal (el toast quedaba detrás y no se
  // veía). Devuelve true si es válida; si no, pinta el hint en rojo y enfoca el campo.
  function _satPorcionValida(porcion) {
    if (porcion > 0) return true;
    const hint = $('satPorcionHint');
    if (hint) hint.innerHTML = '<span style="color:#fca5a5">⚠ Ingresa la porción del granel por unidad (kg), mayor a 0. Ej: 5kg = 5</span>';
    try { $('satPorcion')?.focus(); } catch (_) {}
    return false;
  }

  // ═══ [pres-v1] Handlers del PICKER de presentación (pack ×N / fracción ÷N) ═══
  // (reemplaza al viejo _satSugerirPrecioPack + input satAgrupa "min 2", que no admitía fracciones)
  const _PRES_FAM_ON = 'background:#0f2f22;border-color:#34d399;color:#eafff5';
  const _PRES_FAM_OFF = 'background:transparent;border-color:#334155;color:#94a3b8';
  async function _presInit(editarProd) {
    const padre = _satState.padre;
    _satState.presNombreManual = false; _satState.presDescManual = false;
    if (editarProd) {
      const f = parseFloat(editarProd.factorConversion) || 0;
      _satState.presFactor = f;
      _satState.presFamilia = (f > 0 && f < 1) ? (_satState.padreGranel ? 'peso' : 'frac') : 'pack';
      _presRenderFamilia();
      const nm = $('satNombre'); if (nm) nm.value = editarProd.descripcion || '';
      const pi = $('satPrecio'); if (pi) pi.value = parseFloat(editarProd.precioVenta) || '';
      const ci = $('satCodigo'); if (ci) ci.value = editarProd.codigoBarra || '';
      const cont = $('presContenido'); const c = _presContenidoAuto(padre.descripcion, f);
      if (cont) cont.textContent = c ? ('Contenido: ' + c) : '';
      _satState.presNombreManual = true;   // en edición respetamos el nombre existente
      return;
    }
    // [742] un padre GRANEL casi siempre quiere porciones por peso → esa familia arranca elegida
    _satState.presFamilia = _satState.padreGranel ? 'peso' : 'pack'; _satState.presFactor = 0;
    _presRenderFamilia();
  }
  function _presSetFamilia(fam) {
    _satState.presFamilia = fam;
    const o = $('presOtro'); if (o) o.classList.add('hidden');
    _presRenderFamilia();
  }
  function _presRenderFamilia() {
    const fam = _satState.presFamilia || 'pack';
    const bP = $('presFamPack'), bF = $('presFamFrac'), bW = $('presFamPeso');
    if (bP) bP.style.cssText = (fam === 'pack' ? _PRES_FAM_ON : _PRES_FAM_OFF);
    if (bF) bF.style.cssText = (fam === 'frac' ? _PRES_FAM_ON : _PRES_FAM_OFF);
    if (bW) bW.style.cssText = (fam === 'peso' ? _PRES_FAM_ON : _PRES_FAM_OFF);
    _presRenderChips(fam);
  }
  function _presRenderChips(fam) {
    const cont = $('presChips'); if (!cont) return;
    // [742] familia PESO (solo padres granel): se piensa en GRAMOS y el factor sale solo
    // (60gr sobre base 1 kg → factor 0.06). Antes había que saber que 60gr = "÷16.67".
    const modelos = fam === 'pack'
      ? [[2, 'Dúo'], [3, 'Tripack'], [6, 'Sixpack'], [12, 'Docena']]
      : fam === 'peso'
        ? [[0.05, '50gr'], [0.1, '100gr'], [0.25, '250gr'], [0.5, '500gr']]
        : [[0.5, 'Media'], [1 / 3, 'Tercio'], [0.25, 'Cuarto'], [0.125, 'Octavo']];
    const cur = parseFloat(_satState.presFactor) || 0;
    let html = modelos.map(function (mm) {
      const f = mm[0], lbl = mm[1];
      const activo = cur && Math.abs(cur - f) < 1e-6;
      const et = fam === 'pack' ? ('×' + f) : (fam === 'peso' ? ('×' + f + ' kg') : ('÷' + Math.round(1 / f)));
      const st = activo ? 'background:#0f2f22;border-color:#34d399;color:#eafff5' : 'background:#1e293b;border-color:#334155;color:#cbd5e1';
      return `<button type="button" class="px-2.5 py-1 rounded-full text-xs font-bold border" style="${st}" onclick="MOS._presSetModelo(${f})">${lbl} <span class="opacity-60">${et}</span></button>`;
    }).join('');
    html += `<button type="button" class="px-2.5 py-1 rounded-full text-xs font-bold border" style="background:#1e293b;border-color:#334155;color:#cbd5e1" onclick="MOS._presMostrarOtro()">Otro…</button>`;
    cont.innerHTML = html;
  }
  function _presMostrarOtro() {
    const o = $('presOtro'); if (!o) return;
    o.classList.remove('hidden');
    o.placeholder = (_satState.presFamilia === 'pack') ? 'Nº de unidades (ej 5)'
                  : (_satState.presFamilia === 'peso') ? 'Gramos (ej 60)'
                  : 'Divisor (ej 8 = octavo)';
    o.value = ''; try { o.focus(); } catch (_) {}
  }
  function _presOtroInput() {
    const n = parseFloat($('presOtro')?.value) || 0;
    if (n <= 0) return;
    // [742] en PESO se teclean GRAMOS → factor = gr/1000 (base granel = 1 kg)
    const factor = (_satState.presFamilia === 'pack') ? n
                 : (_satState.presFamilia === 'peso') ? (n / 1000)
                 : (1 / n);
    _presAplicar(factor);
  }
  async function _presSetModelo(factor) {
    const o = $('presOtro'); if (o) o.classList.add('hidden');
    await _presAplicar(factor);
  }
  // Núcleo: fija el factor y actualiza descriptor(sugerido)/contenido/nombre/precio-ref/código.
  async function _presAplicar(factor) {
    const padre = _satState.padre;
    _satState.presFactor = factor;
    _presRenderChips(_satState.presFamilia);
    const esFrac = (factor > 0 && factor < 1);
    // [742] sobre un GRANEL toda fracción se describe por PESO ("60gr"), venga de la
    // familia peso o de un divisor tecleado en Otro — jamás "1/60".
    const esPeso = !!_satState.padreGranel && esFrac;
    const di = $('presDescriptor');
    if (di && !_satState.presDescManual) di.value = _presDescriptorSugerido(factor, esPeso);
    const contenido = _presContenidoAuto(padre.descripcion, factor);
    const cont = $('presContenido');
    if (cont) {
      if (contenido && esFrac) cont.textContent = 'Contenido: ' + contenido + ' · baja el stock del padre en ' + (Math.round(factor * 10000) / 10000) + ' kg (verás decimales)';   // [punto 17] aviso stock decimal
      else if (contenido) cont.textContent = 'Contenido: ' + contenido;
      else if (esFrac) cont.textContent = '⚠ El padre no tiene magnitud (kg/gr) en el nombre — escribe el contenido en el descriptor';
      else cont.textContent = '';
    }
    if (!_satState.presNombreManual) {
      // [742] si el descriptor YA es el peso ("60gr"), no repetir el contenido en el nombre
      const nm = $('satNombre'); if (nm) nm.value = _presNombreCompuesto(padre.descripcion, di ? di.value : '', esPeso ? '' : contenido);
    }
    const precioPadre = parseFloat(padre.precioVenta) || 0;
    const ph = $('satPrecioHint'), pi = $('satPrecio');
    if (precioPadre > 0 && factor > 0) {
      const sug = Math.round(precioPadre * factor * 100) / 100;
      const fLbl = Math.round(factor * 10000) / 10000;   // [742] antes salía ×0.016666666666666666
      if (ph) ph.innerHTML = `Ref: ${factor > 1 ? (fLbl + '×') : ('×' + fLbl)} S/${precioPadre.toFixed(2)} = <b style="color:#34d399">S/ ${sug.toFixed(2)}</b> · pones el tuyo${esPeso ? ` <span style="color:#94a3b8">(${_presPesoLbl(factor)} de 1 kg)</span>` : ''}`;
      // Actualiza la sugerencia al cambiar de modelo, salvo que el usuario ya haya tecleado su precio.
      if (pi && (!pi.value || _satState.presPrecioAuto)) { pi.value = sug.toFixed(2); _satState.presPrecioAuto = true; }
    }
    const st = _satState;
    const cb = await _presGenCodigo(padre.descripcion, factor);
    if (_satState === st && $('satCodigo')) { $('satCodigo').value = cb; try { _satValidarCodigo(); } catch (_) {} }
  }
  function _presRecomponer() {
    _satState.presDescManual = true;
    if (_satState.presNombreManual) return;
    const padre = _satState.padre;
    const f = parseFloat(_satState.presFactor) || 0;
    // [742] granel + fracción: el descriptor lleva el peso → no duplicarlo como contenido
    const contenido = (_satState.padreGranel && f > 0 && f < 1) ? '' : _presContenidoAuto(padre.descripcion, f);
    const nm = $('satNombre'); if (nm) nm.value = _presNombreCompuesto(padre.descripcion, $('presDescriptor')?.value || '', contenido);
  }
  function _presNombreManual() { _satState.presNombreManual = true; }
  function _presPrecioManual() { _satState.presPrecioAuto = false; }   // el usuario tecleó su precio → no pisarlo

  // [RONDA 6] alternar bracket abierto/cerrado ([ incluye · ( excluye)
  function _satBracket(btn) {
    const esMin = btn.id === 'satMinIncl';
    const incl = btn.dataset.incl !== '1';
    btn.dataset.incl = incl ? '1' : '0';
    btn.textContent = esMin ? (incl ? '[' : '(') : (incl ? ']' : ')');
    _satTramoPreview();
    try { _opsBeep && _opsBeep('tac'); } catch(_){}
  }
  function _satTramoG(v) {   // valor del input → gramos según la unidad elegida
    const kg = ($('satTramoUm')?.value === 'kg');
    return isNaN(v) ? v : (kg ? v * 1000 : v);
  }

  // [728] Firma del formulario para saber si hay cambios reales (botón honesto).
  function _satTramoFirma() {
    return [$('satDesde') && $('satDesde').value, $('satHasta') && $('satHasta').value,
            $('satAjuste') && $('satAjuste').value, $('satTramoUm') && $('satTramoUm').value,
            $('satMinIncl') && $('satMinIncl').dataset.incl, $('satMaxIncl') && $('satMaxIncl').dataset.incl].join('|');
  }
  function _satTramoDirtyUpd() {
    const st = _satState; if (!st || st.tipo !== 'tramo' || !st.editSegId) return;
    const b = $('satGuardarBtn'); if (!b) return;
    const sucio = _satTramoFirma() !== (st.editFirma || '');
    b.disabled = !sucio;
    b.textContent = sucio ? 'Guardar cambios' : 'Sin cambios que guardar';
    b.style.opacity = sucio ? '' : '.5';
    b.style.cursor = sucio ? '' : 'not-allowed';
  }
  function _satTramoPreview() {
    const st = _satState; if (!st || st.tipo !== 'tramo') return;
    _satTramoDirtyUpd();
    const pc = parseFloat(st.padre.precioVenta) || 0;
    const desde = _satTramoG(parseFloat($('satDesde')?.value));
    const hasta = _satTramoG(parseFloat($('satHasta')?.value));
    const aj    = parseFloat($('satAjuste')?.value);
    const hint = $('satTramoHint');
    if (hint && !isNaN(aj)) hint.innerHTML = `${aj >= 0 ? '+' : ''}${aj}% → cobras <b style="color:#34d399">S/ ${(pc * (1 + aj/100)).toFixed(2)}/kg</b> en ese rango`;
    // escalera: tramos existentes + el nuevo (resaltado)
    const esc = $('satEscalera'); if (!esc) return;
    const todos = (st.segs || []).slice();
    const nuevoValido = !isNaN(desde) && !isNaN(hasta) && hasta > desde && !isNaN(aj);
    if (nuevoValido) todos.push({ min: desde, max: hasta, ajustePct: aj, _nuevo: true });
    todos.sort((a,b) => (a.min||0) - (b.min||0));
    if (!todos.length) { esc.innerHTML = '<div class="text-[11px] text-slate-600">⬚ sin tramos aún — todo al canónico</div>'; return; }
    esc.innerHTML = todos.map(s => {
      const precio = pc * (1 + (parseFloat(s.ajustePct)||0)/100);
      const lbl = (s.minIncl !== false ? '[' : '(') + _segFmtPeso(s.min || 0) + '–' + _segFmtPeso(s.max) + (s.maxIncl ? ']' : ')');   // [dedup]
      return `<div class="flex-1 text-center rounded-md py-1.5 px-0.5" style="font-size:9.5px;font-family:monospace;
        ${s._nuevo ? 'background:rgba(52,211,153,.15);border:1px solid #34d399;color:#34d399' : 'background:#0e1626;border:1px solid #28344c;color:#93a4c2'}">
        ${lbl}<br><b>S/${precio.toFixed(2)}</b>${s._nuevo ? ' ←' : ''}</div>`;
    }).join('');
  }

  // [catálogo v4 · RONDA 2] gestión de tramos EN el modal ＋tramo (la sección del
  // modal producto se eliminó): lista con borrar por tramo, persistencia inmediata.
  function _satTramosListaRender() {
    const cont = $('satTramosLista');
    const st = _satState;
    if (!cont || !st || st.tipo !== 'tramo') return;
    const pc = parseFloat(st.padre.precioVenta) || 0;
    const segs = (st.segs || []).slice().sort((a, b) => (a.min || 0) - (b.min || 0));
    if (!segs.length) { cont.innerHTML = '<div class="text-[11px] text-slate-600">⬚ sin tramos aún — todo al precio canónico</div>'; return; }
    cont.innerHTML = segs.map(s => {
      const aj = parseFloat(s.ajustePct) || 0;
      const lbl = (s.minIncl !== false ? '[' : '(') + _segFmtPeso(s.min || 0) + ' – ' + _segFmtPeso(s.max) + (s.maxIncl ? ']' : ')');   // [dedup]
      return `<div class="flex items-center gap-2 rounded-lg px-3 py-2" style="background:#0e1626;border:1px solid #28344c">
        <span class="text-[11px] font-mono text-slate-300">${lbl}</span>
        <span class="text-[11px] font-bold" style="color:${aj >= 0 ? '#34d399' : '#fbbf24'}">${aj >= 0 ? '+' : ''}${aj}% → S/ ${(pc*(1+aj/100)).toFixed(2)}/kg</span>
        <button class="cat-btn sm" style="margin-left:auto" title="Editar este tramo" onclick="MOS._satTramoEditar('${String(s.id || '').replace(/'/g,'')}')">✏</button>
        <button class="cat-btn cat-btn-trash sm" title="Eliminar tramo"
                onclick="MOS._satTramoEliminar('${String(s.id || '').replace(/'/g,'')}')">${_svgIcon('trash')}</button>
      </div>`;
    }).join('');
  }
  function _satTramoCargarEnForm(seg) {
    if (!seg) return;
    _satState.editSegId = String(seg.id);
    const minG = +seg.min || 0, maxG = +seg.max || 0;
    const enKg = minG % 1000 === 0 && maxG % 1000 === 0 && maxG >= 1000;
    const um = $('satTramoUm'); if (um) um.value = enKg ? 'kg' : 'g';
    const div = enKg ? 1000 : 1;
    const d = $('satDesde'); if (d) d.value = minG / div;
    const hh = $('satHasta'); if (hh) hh.value = maxG / div;
    const a = $('satAjuste'); if (a) a.value = parseFloat(seg.ajustePct) || 0;
    const bi = $('satMinIncl'); if (bi) { const inc = seg.minIncl !== false; bi.dataset.incl = inc ? '1' : '0'; bi.textContent = inc ? '[' : '('; }
    const bx = $('satMaxIncl'); if (bx) { const inc = !!seg.maxIncl; bx.dataset.incl = inc ? '1' : '0'; bx.textContent = inc ? ']' : ')'; }
    const t = $('satTitulo'); if (t) t.textContent = '📊 Editar tramo';
    _satState.editFirma = _satTramoFirma();
    const b = $('satGuardarBtn'); if (b) { b.disabled = true; b.textContent = 'Sin cambios que guardar'; b.style.opacity = '.5'; b.style.cursor = 'not-allowed'; }
    try { _satTramoPreview(); } catch(_) {}
  }
  function _satTramoEditar(idSeg) {
    const st = _satState; if (!st || st.tipo !== 'tramo') return;
    const seg = (st.segs || []).find(s => String(s.id) === String(idSeg));
    if (!seg) { toast('Tramo no encontrado', 'error'); return; }
    _satTramoCargarEnForm(seg);
    try { if ($('satDesde')) $('satDesde').focus(); } catch(_) {}
  }
  async function _satTramoEliminar(idSeg) {
    const st = _satState;
    if (!st || st.tipo !== 'tramo' || !idSeg) return;
    if (!await _modalConfirm('¿Eliminar este tramo? El rango volverá al precio canónico.', { warning: true, titulo: 'Eliminar tramo' })) return;
    const nuevos = (st.segs || []).filter(s => String(s.id) !== String(idSeg));
    try {
      await API.post('actualizarSegmentosPrecio', {
        _source: 'MOS_MODAL_SATELITE',
        skuBase: st.padre.skuBase || st.padre.idProducto,
        idProducto: st.padre.idProducto, segmentos: nuevos
      });
      st.segs = nuevos;
      // reflejar en memoria local para que el card pinte la escalera actualizada
      const raw = JSON.stringify(nuevos);
      (S.productos || []).forEach(p => {
        if ((p.skuBase || p.idProducto) === (st.padre.skuBase || st.padre.idProducto)) p.segmentos_precio = raw;
      });
      toast('📊 Tramo eliminado ✓', 'ok');
      _satTramosListaRender(); _satTramoPreview();
      renderCatalogo();
    } catch (e) { toast('Error: ' + e.message, 'error'); }
  }

  // [RONDA 5] gestión de equivalentes EN el modal ＋equivalente (la sección embebida
  // del modal producto se ocultó — redundante con el ＋ del dibujo): lista + toggle activo.
  async function _satEquivListaRender() {
    const cont = $('satEquivLista');
    const st = _satState;
    if (!cont || !st || st.tipo !== 'equivalente') return;
    const sku = st.padre.skuBase || st.padre.idProducto;
    try {
      const lista = await API.get('getEquivalencias', { skuBase: sku });
      if (_satState !== st || !$('satEquivLista')) return;   // modal cambió durante el fetch
      const arr = Array.isArray(lista) ? lista : (lista?.equivalencias || []);
      if (!arr.length) { cont.innerHTML = '<div class="text-[11px] text-slate-600">⬚ sin equivalentes aún</div>'; return; }
      cont.innerHTML = arr.map(e => `
        <div class="flex items-center gap-2 rounded-lg px-3 py-2" style="background:#0e1626;border:1px solid #28344c${e.activo === false || e.activo === '0' ? ';opacity:.55' : ''}">
          <span class="text-[11px] font-mono text-slate-300">▌${_escapeHtml(e.codigoBarra || '')}</span>
          <span class="text-[10px] text-slate-500 truncate">${_escapeHtml(e.descripcion || '')}</span>
          <button type="button" class="toggle-sw sm ${e.activo === false || e.activo === '0' ? '' : 'on'}" style="margin-left:auto"
                  title="${e.activo === false || e.activo === '0' ? 'Reactivar' : 'Desactivar'}"
                  onclick="MOS._satEquivToggle('${_escapeHtml(e.idEquiv || '')}', ${e.activo === false || e.activo === '0' ? 'true' : 'false'})">
            <span class="toggle-sw-knob"></span></button>
        </div>`).join('');
    } catch (_) { cont.innerHTML = '<div class="text-[11px] text-red-400">No se pudo cargar la lista</div>'; }
  }
  async function _satEquivToggle(idEquiv, nuevoActivo) {
    const st = _satState;
    if (!st || !idEquiv) return;
    const sku = st.padre.skuBase || st.padre.idProducto;
    try {
      await API.post('actualizarEquivalencia', { _source: 'MOS_MODAL_SATELITE', idEquiv, activo: nuevoActivo ? '1' : '0' });
      toast(nuevoActivo ? '🏷️ Equivalente reactivado' : '🏷️ Equivalente desactivado', 'ok');
      await _loadEquivModal(sku);        // refresca chips del card
      _satEquivListaRender();
      renderCatalogo();
    } catch (e) { toast('Error: ' + e.message, 'error'); }
  }

  // Validación en vivo del código del satélite (local + server, ambas tablas)
  let _satValidTimer = null;
  function _satValidarCodigo() {
    const inp = $('satCodigo'), fb = $('satCodigoFb');
    if (!inp || !fb) return true;
    const val = inp.value.trim();
    if (!val) { fb.textContent = ''; return false; }
    const conf = _cbConflictoLocal(val, _satState?.editar?.idProducto);
    if (conf) {
      fb.innerHTML = `<span class="text-red-400">⚠ Ya ${conf.tipo === 'equivalencia' ? 'es equivalente de' : 'existe en'}: ${_escapeHtml(conf.descripcion || '')}</span>`;
      return false;
    }
    fb.innerHTML = '<span class="text-green-400">✓ Disponible</span>';
    clearTimeout(_satValidTimer);
    _satValidTimer = setTimeout(async () => {
      try {
        const r = await API.post('codigoBarraDisponible', { codigoBarra: val });
        if (r && r.disponible === false && $('satCodigo')?.value.trim() === val) {
          const c = r.conflicto || {};
          fb.innerHTML = `<span class="text-red-400">⚠ Ya ${c.tipo === 'equivalencia' ? 'es equivalente de' : 'existe en'}: ${_escapeHtml(c.descripcion || c.id || '')}</span>`;
        }
      } catch(_){}
    }, 450);
    return true;
  }

  // Guardar según el tipo — optimista, cero GAS
  let _satGuardando = false;
  async function guardarSatelite() {
    if (_satGuardando || !_satState) return;
    const { tipo, padre } = _satState;
    const skuPadre = padre.skuBase || padre.idProducto;

    // herencia tributaria del padre (regla del dibujo: no se vuelve a pedir)
    const her = {
      Tipo_IGV:       padre.Tipo_IGV || padre.tipoIGV || '1',
      Cod_Tributo:    padre.Cod_Tributo || padre.codTributo || '1000',
      IGV_Porcentaje: (padre.IGV_Porcentaje ?? padre.igvPorcentaje ?? 18),
      Cod_SUNAT:      padre.Cod_SUNAT || padre.codSUNAT || '',
      idCategoria:    padre.idCategoria || ''
    };

    if (tipo === 'derivado' || tipo === 'presentacion') {
      const editar  = _satState.editar;
      const nombre  = ($('satNombre')?.value || '').trim();
      const precio  = parseFloat($('satPrecio')?.value) || 0;
      const codigo  = ($('satCodigo')?.value || '').trim();
      if (!nombre)      { toast('⚠ El nombre es requerido', 'error'); return; }
      if (precio <= 0)  { toast('⚠ El precio es requerido (> 0)', 'error'); return; }
      if (!codigo)      { toast('⚠ El código es requerido', 'error'); return; }
      if (_cbConflictoLocal(codigo, editar?.idProducto)) { toast('⚠ Ese código ya existe (producto o equivalente)', 'error'); return; }
      // [RONDA 7] validador de NOMBRE: si el hijo no hereda la familia del padre
      // (ej. copy-paste que dejó "ECONOMICO" en un "PREMIUM") → confirmar, no bloquear
      const _faltNom = (typeof _satNombreFaltantes === 'function') ? _satNombreFaltantes() : [];
      if (_faltNom.length && !await _modalConfirm(
            `El nombre "${nombre}" NO incluye "${_faltNom.join(' ')}" del granel padre "${padre.descripcion}".\n\n¿Seguro? (los derivados deben heredar la familia del padre para no confundirse en el POS).`,
            { warning: true, titulo: '⚠ Nombre no coincide con el padre' })) {
        $('satNombre')?.focus(); return;
      }

      // [RONDA 3] EDICIÓN: patch parcial vía actualizarProducto (atómico + historial)
      if (editar) {
        const patch = { _source: 'MOS_MODAL_SATELITE_EDIT', idProducto: editar.idProducto,
                        descripcion: nombre, precioVenta: precio, codigoBarra: codigo };
        if (tipo === 'derivado') {
          const porcion = parseFloat($('satPorcion')?.value) || 0;
          if (!_satPorcionValida(porcion)) return;   // sin tope superior: cualquier tamaño de envasado
          patch.factorConversionBase = porcion;
          patch.envaseSku = _satEnvaseSel;   // [597] '' = pendiente (la RPC lo vacía a null) · 'SIN_ENVASE' · sku
        } else {
          const f = parseFloat(_satState.presFactor) || 0;
          if (!(f > 0) || f === 1) { toast('⚠ Elige un tipo: pack ×N o fracción ÷N', 'error'); return; }
          // [pres-v1 · punto 7] cambiar el factor cambia LO QUE ES la presentación (y su código). Si ya tiene
          // ventas, distorsiona la rotación histórica → mejor crear una NUEVA y archivar esta. Aviso, no bloquea.
          const fOrig = parseFloat(editar.factorConversion) || 0;
          if (Math.abs(f - fOrig) > 1e-6 && !await _modalConfirm(
                `Cambiar el factor (${fOrig} → ${f}) cambia lo que ES esta presentación y su código. Si ya tiene ventas, es mejor CREAR UNA NUEVA y desactivar esta (para no distorsionar la rotación histórica del padre).\n\n¿Continuar igual?`,
                { warning: true, titulo: '⚠ Cambio de factor' })) { return; }
          patch.factorConversion = f;
        }
        _satGuardando = true;
        cerrarModalSatelite();
        toast('Guardando cambios…', 'info');
        try {
          await API.post('actualizarProducto', patch);
          toast((tipo === 'derivado' ? '🥄 Derivado' : '🧱 Presentación') + ' actualizado ✓', 'ok');
          S.loaded['catalogo'] = false;
          await loadCatalogo(true);
          _pulseCatalogoCard(padre.idProducto);
        } catch (e) { toast('Error: ' + e.message, 'error'); }
        finally { _satGuardando = false; }
        return;
      }

      const params = {
        _source: 'MOS_MODAL_SATELITE', descripcion: nombre, codigoBarra: codigo,
        precioVenta: precio, marca: padre.marca || '', estado: '1',
        stockMinimo: 0, stockMaximo: 0, precioCosto: '', unidad: 'NIU', Unidad_Medida: 'NIU',
        modoVenta: '', margenPct: '', precioTope: '', ...her
      };
      if (tipo === 'derivado') {
        const porcion = parseFloat($('satPorcion')?.value) || 0;
        if (!_satPorcionValida(porcion)) return;   // sin tope superior: cualquier tamaño de envasado
        params.esEnvasable = '0';
        params.codigoProductoBase   = skuPadre;
        params.factorConversionBase = porcion;
        params.factorConversion = ''; params.mermaEsperadaPct = '';
        if (_satEnvaseSel) params.envaseSku = _satEnvaseSel;   // [597] envase elegido ('' pendiente = no mandar)
      } else {
        const f = parseFloat(_satState.presFactor) || 0;
        if (!(f > 0) || f === 1) { toast('⚠ Elige un tipo: pack ×N o fracción ÷N', 'error'); return; }
        params.esEnvasable = '0';
        params.skuBase = skuPadre;
        params.factorConversion = f;
        params.codigoProductoBase = ''; params.factorConversionBase = ''; params.mermaEsperadaPct = '';
        // [629 · regla del saco] Presentación sobre GRANEL = SIEMPRE precio fijo: ME cobra
        // la etiqueta y el stock descuenta factor × kg del canónico.
        if (_satState.padreGranel) params.precioFijo = '1';
        // [629 · guardarraíl escalera] El escalón grande debe salir MÁS BARATO por unidad/kilo
        // que comprar suelto — si no, casi siempre es un dedazo. AVISA, nunca bloquea.
        const _pvPadre = parseFloat(padre.precioVenta) || 0;
        if (f > 1 && _pvPadre > 0) {
          const _porU = precio / f;
          if (_porU > _pvPadre + 1e-9 && !await _modalConfirm(
              `Este escalón sale a ${fmtMoney(_porU)} por ${_satState.padreGranel ? 'kilo' : 'unidad'}, MÁS CARO que comprar suelto (${fmtMoney(_pvPadre)}). Al cliente no le conviene — ¿es a propósito?\n\n(×${f} a ${fmtMoney(precio)} vs suelto ${fmtMoney(_pvPadre * f)})`,
              { warning: true, titulo: '⚠ El escalón no ahorra' })) {
            $('satPrecio')?.focus(); return;
          }
        }
      }
      _satGuardando = true;
      cerrarModalSatelite();
      toast(tipo === 'derivado' ? 'Creando derivado…' : 'Creando presentación…', 'info');
      try {
        const r = await API.post('crearProducto', params);
        toast((tipo === 'derivado' ? '🥄 Derivado' : '🧱 Presentación') + ' creado ✓', 'ok');
        S.loaded['catalogo'] = false;
        await loadCatalogo(true);
        const tid = (r && r.idProducto) || '';
        if (tid) _pulseCatalogoCard(tipo === 'presentacion' ? padre.idProducto : tid);
      } catch(e) { toast('Error: ' + e.message, 'error'); }
      finally { _satGuardando = false; }
      return;
    }

    if (tipo === 'tramo') {
      // [RONDA 6] unidad g/kg + brackets abierto/cerrado elegidos por el usuario
      const desde = _satTramoG(parseFloat($('satDesde')?.value));
      const hasta = _satTramoG(parseFloat($('satHasta')?.value));
      const aj    = parseFloat($('satAjuste')?.value);
      const minIncl = $('satMinIncl')?.dataset.incl === '1';
      const maxIncl = $('satMaxIncl')?.dataset.incl === '1';
      if (isNaN(desde) || desde < 0)        { toast('⚠ Desde es requerido', 'error'); return; }
      if (isNaN(hasta) || hasta <= desde)   { toast('⚠ Hasta debe ser mayor que Desde', 'error'); return; }
      if (isNaN(aj))                        { toast('⚠ El ajuste % es requerido', 'error'); return; }
      const _edId = _satState.editSegId || null;
      const solapa = (_satState.segs || []).some(s => String(s.id) !== String(_edId) && desde < (s.max ?? Infinity) && hasta > (s.min || 0));
      if (solapa) { toast('⚠ El tramo se solapa con uno existente — elimínalo de la lista de abajo y créalo de nuevo', 'error'); return; }
      const nuevo = { id: _edId || ('SEG' + Date.now()), min: desde, max: hasta, minIncl, maxIncl, ajustePct: aj };
      const segs = _edId ? (_satState.segs || []).map(s => String(s.id) === String(_edId) ? nuevo : s) : (_satState.segs || []).concat([nuevo]);
      _satGuardando = true;
      cerrarModalSatelite();
      toast('Guardando tramo…', 'info');
      try {
        await API.post('actualizarSegmentosPrecio', {
          _source: 'MOS_MODAL_SATELITE',
          skuBase: skuPadre, idProducto: padre.idProducto, segmentos: segs
        });
        toast(_edId ? '📊 Tramo actualizado ✓ — mira la escalera del card' : '📊 Tramo guardado ✓', 'ok');
        S.loaded['catalogo'] = false;
        await loadCatalogo(true);
        _pulseCatalogoCard(padre.idProducto);
      } catch(e) { toast('Error: ' + e.message, 'error'); }
      finally { _satGuardando = false; }
      return;
    }

    if (tipo === 'equivalente') {
      const codigo = ($('satCodigo')?.value || '').trim();
      const nota   = ($('satNota')?.value || '').trim();
      if (!codigo) { toast('⚠ Escanea o escribe el código', 'error'); return; }
      const conf = _cbConflictoLocal(codigo);
      if (conf) { toast(`⚠ Ese código ya ${conf.tipo === 'equivalencia' ? 'es equivalente de' : 'existe en'}: ${conf.descripcion}`, 'error'); return; }
      _satGuardando = true;
      cerrarModalSatelite();
      toast('Agregando equivalente…', 'info');
      try {
        await API.post('crearEquivalencia', {
          _source: 'MOS_MODAL_SATELITE',
          skuBase: skuPadre, codigoBarra: codigo, descripcion: nota || ('Equivalente de ' + (padre.descripcion || skuPadre))
        });
        toast('🏷️ Equivalente agregado ✓', 'ok');
        await _loadEquivModal(skuPadre);
        renderCatalogo();
        _pulseCatalogoCard(padre.idProducto);
      } catch(e) { toast('Error: ' + e.message, 'error'); }
      finally { _satGuardando = false; }
      return;
    }
  }

  // ═══ [597] SELECTOR DE ENVASE del modal derivado (insumo que consume al envasarse) ═══
  // _satEnvaseSel: '' = pendiente · 'SIN_ENVASE' = no lleva · 'LEVxxxx' = sku_base del insumo.
  // Se guarda el sku_base (el codigo de barras / nombre pueden cambiar; el sku_base jamás).
  let _satEnvaseSel = '';
  function _envaseInsumoDe(sku) {
    const U = s => String(s || '').trim().toUpperCase();
    return (S.productos || []).find(x => U(x.skuBase) === U(sku) && String(x.esInsumo) === '1')
        || (S.productos || []).find(x => U(x.skuBase) === U(sku)
              && !(x.codigoProductoBase && String(x.codigoProductoBase).trim())
              && (parseFloat(x.factorConversion) || 1) === 1);
  }
  function _satEnvaseInit(valor) {
    _satEnvaseSel = String(valor || '').trim();
    const inp = $('satEnvase'); if (!inp) return;
    if (_satEnvaseSel === 'SIN_ENVASE') inp.value = 'Sin envase (no usa)';
    else if (_satEnvaseSel) { const i = _envaseInsumoDe(_satEnvaseSel); inp.value = i ? (i.descripcion || _satEnvaseSel) : _satEnvaseSel; }
    else inp.value = '';
    _satEnvaseHint();
  }
  function _satEnvaseFiltra() {
    const inp = $('satEnvase'), ops = $('satEnvaseOps'); if (!inp || !ops) return;
    // si el texto ya no coincide con la selección → queda sin seleccionar (el hint lo dice)
    const selTxt = _satEnvaseSel === 'SIN_ENVASE' ? 'Sin envase (no usa)'
      : _satEnvaseSel ? ((_envaseInsumoDe(_satEnvaseSel) || {}).descripcion || _satEnvaseSel) : '';
    if ((inp.value || '').trim() !== String(selTxt).trim()) _satEnvaseSel = '';
    const q = (inp.value || '').trim().toUpperCase().replace(/X/g, '*');
    const insumos = (S.productos || [])
      .filter(p => String(p.esInsumo) === '1' && _isProdActivo(p))
      .sort((a, b) => String(a.descripcion || '').localeCompare(String(b.descripcion || ''), 'es', { numeric: true }));
    const li = insumos.filter(p => !q
      || String(p.descripcion || '').toUpperCase().replace(/X/g, '*').indexOf(q) >= 0
      || String(p.skuBase || '').toUpperCase().indexOf(q) >= 0);
    let html = '';
    if (!q) html += `
      <button type="button" class="w-full text-left px-3 py-2 text-xs text-slate-500 italic hover:bg-slate-800/60" style="border-bottom:1px solid #16223a"
              onmousedown="event.preventDefault();MOS._satEnvaseSet('')">— dejar pendiente (elegir después) —</button>
      <button type="button" class="w-full text-left px-3 py-2 text-xs text-slate-400 hover:bg-slate-800/60" style="border-bottom:1px solid #16223a"
              onmousedown="event.preventDefault();MOS._satEnvaseSet('SIN_ENVASE')">🚫 Sin envase (no usa bolsa)</button>`;
    html += li.map(p => `
      <button type="button" class="w-full text-left px-3 py-2 text-xs text-slate-200 hover:bg-slate-800/60 flex justify-between gap-2"
              onmousedown="event.preventDefault();MOS._satEnvaseSet('${_escapeHtml(String(p.skuBase || ''))}')">
        <span>🛍 ${_escapeHtml(p.descripcion || p.skuBase || '')}</span>
        <span class="text-slate-500 font-mono text-[10px]">${_escapeHtml(String(p.skuBase || ''))}</span></button>`).join('');
    if (!li.length && q) html += `<div class="px-3 py-2 text-xs text-slate-500">Sin insumos que coincidan — márcalos con 🧷 Insumo al editar el producto</div>`;
    ops.innerHTML = html;
    ops.classList.remove('hidden');
    _satEnvaseHint();
  }
  function _satEnvaseSet(sku) { _satEnvaseInit(sku); $('satEnvaseOps')?.classList.add('hidden'); }
  function _satEnvaseCierra() { setTimeout(() => $('satEnvaseOps')?.classList.add('hidden'), 150); _satEnvaseHint(); }
  function _satEnvaseHint() {
    const h = $('satEnvaseHint'); if (!h) return;
    if (_satEnvaseSel === 'SIN_ENVASE') h.innerHTML = '<span class="text-slate-400">Guardará: sin envase (no consume bolsa al envasarse)</span>';
    else if (_satEnvaseSel) { const i = _envaseInsumoDe(_satEnvaseSel);
      h.innerHTML = '<span style="color:#34d399">✓ ' + _escapeHtml((i && i.descripcion) || _satEnvaseSel) + ' · ' + _escapeHtml(_satEnvaseSel) + '</span>'; }
    else h.innerHTML = '<span class="text-amber-400">Pendiente — el catálogo mostrará "🛍 elegir bolsa…"</span>';
  }

  // Toggle "es granel envasable" del modal +producto EN CREACIÓN (dibujo §04)
  function prodToggleEnvasable() {
    const sw = $('prodEnvasableSw');
    const on = !sw?.classList.contains('on');
    sw?.classList.toggle('on', on);
    setProdTipo(on ? 'envasable' : 'normal', true);
  }

  // [597] Toggle "insumo de envasado" — independiente del tipo (no cambia el tipo del producto)
  function prodToggleInsumo() {
    const sw = $('prodInsumoSw');
    sw?.classList.toggle('on', !sw?.classList.contains('on'));
  }

  async function guardarProducto() {
    const desc = ($('prodDescripcion')?.value || '').trim();
    // Validaciones de campos OBLIGATORIOS
    if (!desc) {
      toast('⚠ La descripción es requerida', 'error');
      $('prodDescripcion')?.focus();
      return;
    }
    let codigoBarra = ($('prodCodigoBarra')?.value || '').trim();
    // Si no hay codigoBarra, autogenerar uno con prefijo en el momento (no permitir vacío)
    if (!codigoBarra) {
      // [catálogo v4] prodAutogenBarcode ahora es async (valida contra productos +
      // equivalencias en el server) → AWAIT obligatorio o el value se lee vacío
      await prodAutogenBarcode(true); // silencioso: el campo está vacío, no hay que confirmar
      codigoBarra = ($('prodCodigoBarra')?.value || '').trim();
      if (!codigoBarra) {
        toast('⚠ El código de barras es requerido', 'error');
        $('prodCodigoBarra')?.focus();
        return;
      }
      toast('Código de barras autogenerado: ' + codigoBarra, 'info');
    }
    const precioVenta = parseFloat($('prodPrecioVenta')?.value);
    if (!precioVenta || precioVenta <= 0) {
      toast('⚠ El precio de venta es requerido (> 0)', 'error');
      $('prodPrecioVenta')?.focus();
      return;
    }

    const overridePolitica = !!$('prodPoliticaOverride')?.checked;
    const params = {
      idProducto:    $('prodId')?.value     || undefined,
      descripcion:   desc,
      codigoBarra:   $('prodCodigoBarra')?.value  || '',
      marca:         $('prodMarca')?.value        || '',
      // [640] idCategoria ya NO se envía: la asigna la IA server-side (espejo de categoria_ia)
      unidad:        $('prodUnidad')?.value       || 'NIU',
      precioVenta:   parseFloat($('prodPrecioVenta')?.value) || 0,
      precioCosto:   $('prodPrecioCosto')?.value  ? parseFloat($('prodPrecioCosto').value) : '',
      stockMinimo:   parseInt($('prodStockMin')?.value)  || 0,
      stockMaximo:   parseInt($('prodStockMax')?.value)  || 0,
      estado:        $('prodEstado')?.value       || '1',
      Tipo_IGV:      $('prodTipoIGV')?.value      || '',
      Cod_Tributo:   $('prodCodTributo')?.value   || '',
      IGV_Porcentaje:$('prodIGV')?.value          ? parseFloat($('prodIGV').value) : '',
      Unidad_Medida: $('prodUnidadMedida')?.value || 'NIU',
      Cod_SUNAT:     $('prodCodSUNAT')?.value     || '',
      // Política override (vacío = default MARGEN 25%; la política vive por producto)
      modoVenta:     overridePolitica ? ($('prodModoVenta')?.value || '') : '',
      margenPct:     overridePolitica && $('prodMargenPct')?.value ? parseFloat($('prodMargenPct').value) : '',
      precioTope:    overridePolitica && $('prodPrecioTope')?.value ? parseFloat($('prodPrecioTope').value) : ''
    };

    // Campos según tipo
    if (_prodTipo === 'envasable') {
      params.esEnvasable = '1'; params.codigoProductoBase = ''; params.factorConversion = ''; params.factorConversionBase = ''; params.mermaEsperadaPct = '';
    } else if (_prodTipo === 'derivado') {
      params.esEnvasable = '0';
      params.codigoProductoBase  = $('prodCodigoProductoBase')?.value || '';
      params.factorConversionBase= $('prodFactorConvBase')?.value ? parseFloat($('prodFactorConvBase').value) : '';
      params.mermaEsperadaPct    = '';   // [424] merma eliminada del modal (nunca se usa)
      params.factorConversion = '';
    } else if (_prodTipo === 'presentacion') {
      params.esEnvasable = '0';
      // Solo mandar skuBase si el input tiene valor — evita borrar el SKU existente
      const skuVal = ($('prodSkuBase')?.value || '').trim();
      if (skuVal) params.skuBase = skuVal;
      params.factorConversion = $('prodFactor')?.value  ? parseFloat($('prodFactor').value) : '';
      params.codigoProductoBase = ''; params.factorConversionBase = ''; params.mermaEsperadaPct = '';
    } else { // normal (base): factorConversion = 1
      params.esEnvasable = '0'; params.codigoProductoBase = ''; params.factorConversionBase = ''; params.mermaEsperadaPct = '';
      // Solo asignar factorConversion=1 al CREAR (sin idProducto). En edición no se toca para no romper data.
      if (!params.idProducto) params.factorConversion = 1;
    }

    // [597] insumo de envasado: solo se manda si el toggle está visible (derivado/presentación
    // en edición lo ocultan → no mandar la clave = la RPC conserva el valor actual, sin clobber)
    const _insRow = $('prodInsumoRow');
    if (_insRow && !_insRow.classList.contains('hidden')) {
      params.esInsumo = $('prodInsumoSw')?.classList.contains('on') ? '1' : '0';
    }

    // BLOQUEO: si codigoBarra duplicado, no permitir guardar
    if (!prodValidarCodigoBarra()) {
      toast('El código de barras ya pertenece a otro producto. No se puede guardar.', 'error');
      $('prodCodigoBarra')?.focus();
      return;
    }

    // OPTIMISTIC FLOW: cerrar modal de inmediato + pulse visual al guardarse
    const isEdit = !!params.idProducto;
    params._source = 'MOS_MODAL_PRODUCTO';
    closeModal('modalProducto');
    toast(isEdit ? 'Actualizando…' : 'Creando producto…', 'info');

    try {
      const action = isEdit ? 'actualizarProducto' : 'crearProducto';
      const r = await API.post(action, params);
      toast(isEdit ? 'Producto actualizado ✓' : 'Producto creado ✓', 'ok');
      // [RONDA 5 · purga] Los tramos (segmentos_precio) se persisten directo desde el modal ＋Tramo.
      // (Se eliminó el bloque residual que leía _segState —variable ya purgada— y lanzaba ReferenceError
      //  al editar, cayendo al catch con un toast de error espurio y saltándose el refresco.)
      // Refresh catálogo
      S.loaded['catalogo'] = false;
      await loadCatalogo(true);
      // Pulse en la card del producto creado/editado
      const targetId = (r && r.idProducto) || params.idProducto || '';
      if (targetId) _pulseCatalogoCard(targetId);
    } catch(e) {
      toast('Error: ' + e.message, 'error');
      // Revertir abriendo el modal de nuevo con los datos para corregir
      // (no implementado por simplicidad — el usuario puede reintentar manualmente)
    }
  }

  // Hace scroll a la card del producto y le aplica un pulso visual breve
  function _pulseCatalogoCard(idProducto) {
    setTimeout(() => {
      const eid = CSS.escape(idProducto);
      const card = document.getElementById('fc-' + eid);
      if (!card) return;
      // Scroll suave
      card.scrollIntoView({ behavior: 'smooth', block: 'center' });
      // Aplicar clase de pulso
      card.classList.remove('cat-card-pulse');
      void card.offsetWidth;  // force reflow
      card.classList.add('cat-card-pulse');
      // Quitarla cuando termine
      setTimeout(() => card.classList.remove('cat-card-pulse'), 2200);
    }, 200);
  }

  // [catálogo v4 · limpieza] abrirModalPrecio + publicarPrecio ELIMINADOS: código muerto
  // (cero callers desde que modalPrecioRapido los reemplazó). La cascada usa guardarPrecioRapido.

  // Proveedor modal
  function abrirModalProveedor(id) {
    ['Id','Nombre','Ruc','Tel','Email','FormaPago','Plazo','Categoria','Banco','Cuenta','DiaPedido','DiaEntrega','DiaPago'].forEach(c => {
      const el = $('prov' + c);
      if (!el) return;
      if (el.tagName === 'SELECT') el.value = '';
      else el.value = '';
    });
    if (id) {
      const p = S.proveedores.find(x => x.idProveedor === id);
      if (!p) return;
      $('modalProvTitle').textContent = 'Editar Proveedor';
      $('provId').value         = p.idProveedor;
      $('provNombre').value     = p.nombre || '';
      $('provRuc').value        = p.ruc || '';
      $('provTel').value        = p.telefono || '';
      $('provEmail').value      = p.email || '';
      $('provFormaPago').value  = p.formaPago || 'CONTADO';
      $('provPlazo').value      = p.plazoCredito || '';
      $('provCategoria').value  = p.categoriaProducto || '';
      $('provBanco').value      = p.banco || '';
      $('provCuenta').value     = p.numeroCuenta || '';
      if ($('provDiaPedido'))  $('provDiaPedido').value  = (p.diaPedido  || '').toUpperCase();
      if ($('provDiaEntrega')) $('provDiaEntrega').value = (p.diaEntrega || '').toUpperCase();
      if ($('provDiaPago'))    $('provDiaPago').value    = (p.diaPago    || '').toUpperCase();
    } else {
      $('modalProvTitle').textContent = 'Nuevo Proveedor';
      $('provId').value = '';
      $('provFormaPago').value = 'CONTADO';
    }
    openModal('modalProveedor');
  }

  async function guardarProveedor() {
    const params = {
      idProveedor:      $('provId')?.value || undefined,
      nombre:           $('provNombre')?.value || '',
      ruc:              $('provRuc')?.value || '',
      telefono:         $('provTel')?.value || '',
      email:            $('provEmail')?.value || '',
      formaPago:        $('provFormaPago')?.value || 'CONTADO',
      plazoCredito:     $('provPlazo')?.value || 0,
      categoriaProducto:$('provCategoria')?.value || '',
      banco:            $('provBanco')?.value || '',
      numeroCuenta:     $('provCuenta')?.value || '',
      diaPedido:        $('provDiaPedido')?.value  || '',
      diaEntrega:       $('provDiaEntrega')?.value || '',
      diaPago:          $('provDiaPago')?.value    || ''
    };
    if (!params.nombre) { toast('El nombre es requerido', 'error'); return; }
    const isEdit = !!params.idProveedor;
    // OPTIMISTA: actualizar lista local + cerrar modal de inmediato
    const backup = (S.proveedores || []).map(p => ({ ...p }));
    if (isEdit) {
      const idx = (S.proveedores || []).findIndex(p => p.idProveedor === params.idProveedor);
      if (idx >= 0) {
        S.proveedores[idx] = { ...S.proveedores[idx],
          nombre: params.nombre, ruc: params.ruc, telefono: params.telefono,
          email: params.email, formaPago: params.formaPago, plazoCredito: params.plazoCredito,
          categoriaProducto: params.categoriaProducto, banco: params.banco, numeroCuenta: params.numeroCuenta,
          diaPedido: params.diaPedido, diaEntrega: params.diaEntrega, diaPago: params.diaPago
        };
      }
    }
    let tmpId = '';
    if (!isEdit) {
      // Insert provisional con id temporal (se reconcilia con el id real al volver el backend).
      tmpId = 'TMP_' + Date.now();
      S.proveedores = [{ idProveedor: tmpId, estado: '1', _tmp: true, ...params }, ...(S.proveedores || [])];
    }
    closeModal('modalProveedor');
    renderProveedores();
    if (S.pv2 && S.pv2.prov && S.pv2.prov.idProveedor === params.idProveedor) { try { _renderProvProductos(); } catch(_){} }   // [v2.43.592] refresh v2
    // Efecto suave de adición (sin parpadeo): pulse en la card recién insertada.
    if (!isEdit) {
      try { if (navigator.vibrate) navigator.vibrate([20, 30, 40]); } catch (_) {}
      requestAnimationFrame(() => {
        const card = document.querySelector('[data-prov-card="' + tmpId + '"]');
        if (card) { card.classList.add('prov-card-nuevo'); setTimeout(() => card.classList.remove('prov-card-nuevo'), 900); }
      });
    }
    toast(isEdit ? 'Proveedor actualizado' : 'Proveedor creado', 'ok');
    // Sync en background (fire-and-forget con reconciliación quirúrgica, sin re-render global que parpadee)
    try {
      const action = isEdit ? 'actualizarProveedor' : 'crearProveedor';
      const r = await API.post(action, params);
      // Si fue creación: reemplazar el id temporal por el id real EN SITIO (sin recargar toda la lista,
      // así no se pierde el orden optimista ni se produce flash). API.post devuelve data directo.
      if (!isEdit) {
        const realId = r && (r.idProveedor || (r.data && r.data.idProveedor));
        const rec = (S.proveedores || []).find(p => p.idProveedor === tmpId);
        if (rec) { if (realId) rec.idProveedor = realId; delete rec._tmp; }
        if (S.provSelId === tmpId && realId) S.provSelId = realId;
        renderProveedores();
      }
    } catch (e) {
      // Revertir en error
      S.proveedores = backup;
      if (S.provSelId === tmpId) S.provSelId = null;
      renderProveedores();
      toast('Error de sincronización: ' + e.message, 'error');
    }
  }

  // Pago modal
  function abrirModalPago(idProveedor) {
    $('pagoIdProveedor').value = idProveedor;
    $('pagoMonto').value  = '';
    $('pagoFactura').value = '';
    $('pagoFecha').value  = today();
    $('pagoObs').value    = '';
    openModal('modalPago');
  }

  async function guardarPago() {
    const params = {
      idProveedor:    $('pagoIdProveedor')?.value,
      monto:          $('pagoMonto')?.value,
      numeroFactura:  $('pagoFactura')?.value || '',
      fecha:          $('pagoFecha')?.value || today(),
      observacion:    $('pagoObs')?.value || ''
    };
    if (!params.monto || parseFloat(params.monto) <= 0) { toast('Ingresa un monto válido', 'error'); return; }
    // OPTIMISTA: cerrar modal + insertar pago temporal en cache
    const id = params.idProveedor;
    S.provPagos = S.provPagos || {};
    const tmpPago = {
      idPago:        'PAG_TMP_' + Date.now(),
      idProveedor:   id,
      monto:         parseFloat(params.monto),
      fecha:         params.fecha,
      numeroFactura: params.numeroFactura,
      estado:        'PAGADO',
      observacion:   params.observacion,
      _tmp:          true
    };
    const backup = (S.provPagos[id] || []).slice();
    S.provPagos[id] = [tmpPago, ...(S.provPagos[id] || [])];
    closeModal('modalPago');
    if (S.provSelId === id && S.provTab === 'info') _renderProvInfo();
    toast('Pago registrado: ' + fmtMoney(params.monto), 'ok');
    try {
      await API.post('registrarPago', params);
      // Refresh real
      const r = await API.get('getPagos', { idProveedor: id });
      S.provPagos[id] = Array.isArray(r) ? r : (r && r.data) || [];
      if (S.provSelId === id && S.provTab === 'info') _renderProvInfo();
    } catch (e) {
      S.provPagos[id] = backup;
      if (S.provSelId === id && S.provTab === 'info') _renderProvInfo();
      toast('Error de sincronización: ' + e.message, 'error');
    }
  }

  // ── PEDIDO MODAL ────────────────────────────────────────────
  let _pedidoState = { items: [], idProveedor: null };

  async function abrirModalPedido(idProveedor) {
    if (!idProveedor) return;
    _pedidoState = { items: [], idProveedor: idProveedor };
    const prov = (S.proveedores || []).find(p => p.idProveedor === idProveedor);
    $('pedidoIdProveedor').value = idProveedor;
    $('pedidoProveedorNombre').textContent = prov ? prov.nombre : idProveedor;
    $('pedidoBuscar').value = '';
    $('pedidoBuscarRes').style.display = 'none';
    $('pedidoFechaEst').value = '';
    $('pedidoNotas').value = '';
    _renderPedidoItems();
    // Si vino con producto sugerido (desde insight), pre-cargar
    if (S._pedidoSugerido) {
      _pedidoState.items.push({
        skuBase:     S._pedidoSugerido.skuBase || S._pedidoSugerido.idProducto,
        codigoBarra: S._pedidoSugerido.codigoBarra || '',
        descripcion: S._pedidoSugerido.descripcion || '',
        cantidad:    1,
        precio:      S._pedidoSugerido.precioReferencia || 0
      });
      S._pedidoSugerido = null;
      _renderPedidoItems();
    }
    openModal('modalPedido');
  }

  function cerrarModalPedido() { closeModal('modalPedido'); }

  let _pedidoBuscarTimer = null;
  async function pedidoBuscarItem() {
    clearTimeout(_pedidoBuscarTimer);
    _pedidoBuscarTimer = setTimeout(async () => {
      const q = ($('pedidoBuscar').value || '').trim();
      const resBox = $('pedidoBuscarRes');
      if (!q) { resBox.style.display = 'none'; return; }
      try {
        const items = await API.get('getProveedorProductos', { idProveedor: _pedidoState.idProveedor });
        const lista = Array.isArray(items) ? items : (items && items.data) || [];
        const qn = _norm(q);
        const palabras = qn.split(/\s+/).filter(Boolean);
        const filtered = lista.filter(pp => {
          const hay = _norm((pp.descripcion || '') + ' ' + (pp.skuBase || '') + ' ' + (pp.codigoBarra || ''));
          return palabras.every(w => hay.indexOf(w) >= 0);
        }).slice(0, 8);
        if (!filtered.length) {
          resBox.innerHTML = '<div class="pn-result text-slate-500 italic">Sin coincidencias</div>';
          resBox.style.display = 'block';
          return;
        }
        resBox.innerHTML = filtered.map(pp => {
          const safeDesc = (pp.descripcion || pp.skuBase).replace(/'/g, "\\'");
          return `<div class="pn-result" onclick="MOS.pedidoAgregarItem('${pp.skuBase}', '${pp.codigoBarra || ''}', '${safeDesc}', ${pp.precioReferencia || 0})">
            <div class="text-slate-200 font-medium text-sm">${pp.descripcion || pp.skuBase}</div>
            <div class="text-slate-500 text-xs flex justify-between"><span style="font-family:monospace">${pp.skuBase}</span><span class="text-amber-400">${fmtMoney(pp.precioReferencia || 0)}</span></div>
          </div>`;
        }).join('');
        resBox.style.display = 'block';
      } catch(_){}
    }, 200);
  }

  function pedidoAgregarItem(sku, cb, desc, precio) {
    const existe = _pedidoState.items.find(it => it.skuBase === sku);
    if (existe) { existe.cantidad++; }
    else _pedidoState.items.push({ skuBase: sku, codigoBarra: cb, descripcion: desc, cantidad: 1, precio: parseFloat(precio) || 0 });
    $('pedidoBuscar').value = '';
    $('pedidoBuscarRes').style.display = 'none';
    _renderPedidoItems();
  }

  function pedidoQuitarItem(idx) {
    _pedidoState.items.splice(idx, 1);
    _renderPedidoItems();
  }

  function pedidoCambiarQty(idx, qty) {
    const q = Math.max(0, parseInt(qty) || 0);
    if (q === 0) { _pedidoState.items.splice(idx, 1); }
    else _pedidoState.items[idx].cantidad = q;
    _renderPedidoItems();
  }

  function _renderPedidoItems() {
    const list = $('pedidoItemsList');
    const cnt = $('pedidoItemsCount');
    if (!list) return;
    if (cnt) cnt.textContent = '(' + _pedidoState.items.length + ')';
    if (!_pedidoState.items.length) {
      list.innerHTML = '<div class="text-xs text-slate-600 italic text-center py-3">Sin items aún. Busca productos arriba.</div>';
      $('pedidoTotal').value = 'S/ 0.00';
      return;
    }
    let total = 0;
    list.innerHTML = _pedidoState.items.map((it, i) => {
      const sub = _money((it.cantidad || 0) * (it.precio || 0));
      total = _money(total + sub);
      return `<div class="flex items-center gap-2 p-2 rounded" style="background:#0d1526">
        <div class="min-w-0 flex-1">
          <div class="text-sm text-slate-200 truncate">${it.descripcion}</div>
          <div class="text-[10px] text-slate-500 font-mono">${it.skuBase} · ${fmtMoney(it.precio)}</div>
        </div>
        <input type="number" min="0" step="1" class="inp text-xs" style="width:60px;text-align:center" value="${it.cantidad}" onchange="MOS.pedidoCambiarQty(${i}, this.value)">
        <div class="text-xs text-amber-400 font-semibold whitespace-nowrap" style="width:60px;text-align:right">${fmtMoney(sub)}</div>
        <button onclick="MOS.pedidoQuitarItem(${i})" class="text-rose-400 text-base p-1" title="Quitar">×</button>
      </div>`;
    }).join('');
    $('pedidoTotal').value = fmtMoney(total);
  }

  async function guardarPedido() {
    if (!_pedidoState.idProveedor) { toast('Falta proveedor', 'error'); return; }
    if (!_pedidoState.items.length) { toast('Agrega al menos 1 item', 'error'); return; }
    const total = _pedidoState.items.reduce((s, it) => s + (it.cantidad || 0) * (it.precio || 0), 0);
    try {
      await API.post('crearPedido', {
        idProveedor:    _pedidoState.idProveedor,
        items:          _pedidoState.items,
        montoEstimado:  total,
        fechaEstimada:  $('pedidoFechaEst').value || '',
        notas:          $('pedidoNotas').value || '',
        usuario:        S.session?.nombre || ''
      });
      toast('Pedido borrador creado ✓', 'ok');
      closeModal('modalPedido');
      // Refrescar pedidos del proveedor si la vista está abierta
      if (S.provSelId === _pedidoState.idProveedor && S.provTab === 'pedidos') {
        S.provPedidos[_pedidoState.idProveedor] = null;
        _renderProvPedidos();
      }
    } catch(e) {
      toast('Error: ' + e.message, 'error');
    }
  }

  // ── Selector de proveedor desde insight de almacén ──
  async function _almGenerarPedidoFromInsight(idProducto, descripcion, skuBase, codigoBarra) {
    try {
      const r = await API.get('getProveedoresQueVenden', { skuBase: skuBase || idProducto, codigoBarra: codigoBarra || '' });
      const provs = (r && r.data) ? r.data : (r || []);
      if (!provs.length) {
        toast('Este producto no tiene proveedores registrados. Agrégalo en Proveedores → Productos.', 'error');
        return;
      }
      // Guardar producto sugerido para pre-cargar en el modal
      S._pedidoSugerido = {
        idProducto, descripcion, skuBase: skuBase || idProducto, codigoBarra: codigoBarra || '',
        precioReferencia: provs[0].precioReferencia
      };
      if (provs.length === 1) {
        // Directo al modal de pedido
        await abrirModalPedido(provs[0].idProveedor);
        return;
      }
      // Mostrar selector
      $('selProvProducto').textContent = descripcion || idProducto;
      $('selProvList').innerHTML = provs.map(p => `
        <div class="card-sm p-3 cursor-pointer hover:border-amber-500/40 transition-colors" onclick="MOS._almPickProveedor('${p.idProveedor}')">
          <div class="flex items-center justify-between gap-2">
            <div class="min-w-0 flex-1">
              <div class="text-sm font-semibold text-slate-200 truncate">${p.nombreProveedor}</div>
              <div class="text-xs text-slate-500">mín ${p.minimoCompra || 0} · ${p.diasEntrega || 0}d entrega</div>
            </div>
            <div class="text-amber-400 text-sm font-bold whitespace-nowrap shrink-0">${fmtMoney(p.precioReferencia)}</div>
          </div>
        </div>
      `).join('');
      openModal('modalSelProveedor');
    } catch(e) {
      toast('Error: ' + e.message, 'error');
    }
  }
  async function _almPickProveedor(idProveedor) {
    closeModal('modalSelProveedor');
    await abrirModalPedido(idProveedor);
  }
  function cerrarSelProveedor() { closeModal('modalSelProveedor'); }

  // ── CONFIGURACIÓN ────────────────────────────────────────────
  let cfgData = { zonas: [], estaciones: [], impresoras: [], personal: [], personalMOS: [], series: [], dispositivos: [], taxonomia: [], personalMaster: [] };

  // ════════════════════════════════════════════════════════
  // CONFIGURACIÓN — sistema cache + prefetch + auto-refresh
  // (mismo patrón que Almacén)
  // ════════════════════════════════════════════════════════
  const CFG_CACHE_PFX = 'mos_cfg_';
  const CFG_CACHE_TTL = 30 * 60 * 1000; // 30 min

  function _cfgLoadCache(key) {
    try {
      const raw = localStorage.getItem(CFG_CACHE_PFX + key);
      if (!raw) return null;
      const p = JSON.parse(raw);
      if (Date.now() - (p.ts || 0) > CFG_CACHE_TTL) return null;
      return p.data;
    } catch { return null; }
  }
  function _cfgSaveCache(key, data) {
    try { localStorage.setItem(CFG_CACHE_PFX + key, JSON.stringify({ ts: Date.now(), data })); } catch {}
  }

  // Hidrata cfgData desde localStorage (instantáneo)
  function _cfgHidratarTodos() {
    const z = _cfgLoadCache('zonas');        if (z) cfgData.zonas        = z;
    const e = _cfgLoadCache('estaciones');   if (e) cfgData.estaciones   = e;
    const i = _cfgLoadCache('impresoras');   if (i) cfgData.impresoras   = i;
    const p = _cfgLoadCache('personal');     if (p) cfgData.personal     = p;
    const m = _cfgLoadCache('personalMOS');  if (m) cfgData.personalMOS  = m;
    const b = _cfgLoadCache('bloqueosME');   if (b) cfgData.bloqueosME   = b;
    const s = _cfgLoadCache('series');       if (s) cfgData.series       = s;
    const d = _cfgLoadCache('dispositivos'); if (d) cfgData.dispositivos = d;
    const tx = _cfgLoadCache('taxonomia');   if (tx) cfgData.taxonomia   = tx;
    const f = _cfgLoadCache('config');       if (f) cfgData.config       = f;
    return !!(z || e || i || p || m || b || s || d || tx || f);
  }

  // Prefetch al login: descarga TODO en paralelo y cachea (corre en background)
  function _cfgPrefetch() {
    setTimeout(() => {
      if (!S.session) return;
      iconBusy('config', true);
      const tasks = [
        API.get('getZonas', {}).then(r => { if (r) { cfgData.zonas = r; _cfgSaveCache('zonas', r); } }).catch(() => {}),
        API.get('getEstaciones', {}).then(r => { if (r) { cfgData.estaciones = r; _cfgSaveCache('estaciones', r); } }).catch(() => {}),
        API.get('getImpresoras', {}).then(r => { if (r) { cfgData.impresoras = r; _cfgSaveCache('impresoras', r); } }).catch(() => {}),
        API.get('getPersonalMaster', { appOrigen: 'warehouseMos' }).then(r => { if (r) { cfgData.personal = r; _cfgSaveCache('personal', r); } }).catch(() => {}),
        API.get('getPersonalMaster', { appOrigen: 'MOS' }).then(r => { if (r) { cfgData.personalMOS = r; _cfgSaveCache('personalMOS', r); } }).catch(() => {}),
        API.get('getVendedoresMEBloqueados', {}).then(r => { if (r) { cfgData.bloqueosME = r; _cfgSaveCache('bloqueosME', r); } }).catch(() => {}),
        API.get('getSeries', {}).then(r => { if (r) { cfgData.series = r; _cfgSaveCache('series', r); } }).catch(() => {}),
        API.get('getDispositivos', {}).then(r => { if (r) { cfgData.dispositivos = _dispAplicarShield(r); _cfgSaveCache('dispositivos', cfgData.dispositivos); } }).catch(() => {}),
        // [786] mapa amo/esclavo (principal/extensión) por dispositivo → chip en la tarjeta.
        API.get('getRolesAmoEsclavo', {}).then(r => { if (r && typeof r === 'object') cfgData.rolesAmoEsclavo = r; }).catch(() => {}),
        // [635] solicitudes de extensión de horario → sección A de Infraestructura
        API.get('getAlertasExtensionHorario', {}).then(r => { if (r) cfgData.alertasHorario = r; }).catch(() => {}),
        API.get('getTaxonomia', {}).then(r => { if (Array.isArray(r)) { cfgData.taxonomia = r; _cfgSaveCache('taxonomia', r); } }).catch(() => {}),
        API.get('getConfig', {}).then(r => { if (r) { cfgData.config = r; _cfgSaveCache('config', r); } }).catch(() => {})
      ];
      Promise.all(tasks).finally(() => {
        iconBusy('config', false);
        S._cfgPrecargado = true;
        // Si el usuario ya está viendo configuración, re-renderizar
        if (S.view === 'config') renderCfgTab(S.cfgTab || 'infra');
      });
    }, 1500);
  }

  // Auto-refresh global cada 60s mientras módulo configuración visible
  let _cfgAutoTimer = null;
  function _cfgIniciarAutoRefresh() {
    if (_cfgAutoTimer) clearInterval(_cfgAutoTimer);
    _cfgAutoTimer = setInterval(() => {
      if (!S.session || S.view !== 'config') return;
      if (document.visibilityState !== 'visible') return;
      _cfgRefreshSilencioso();
    }, 60 * 1000);
  }
  function _cfgDetenerAutoRefresh() {
    if (_cfgAutoTimer) { clearInterval(_cfgAutoTimer); _cfgAutoTimer = null; }
  }
  // Refresh silencioso — solo recarga lo que afecta la pestaña activa
  async function _cfgRefreshSilencioso() {
    iconBusy('config', true);
    try {
      const tab = S.cfgTab || 'infra';
      const tasks = [];
      // Datos compartidos (siempre)
      tasks.push(API.get('getZonas', {}).then(r => { if (r) { cfgData.zonas = r; _cfgSaveCache('zonas', r); } }).catch(() => {}));
      tasks.push(API.get('getEstaciones', {}).then(r => { if (r) { cfgData.estaciones = r; _cfgSaveCache('estaciones', r); } }).catch(() => {}));
      // Por pestaña
      if (tab === 'infra') {
        tasks.push(API.get('getImpresoras', {}).then(r => { if (r) { cfgData.impresoras = r; _cfgSaveCache('impresoras', r); } }).catch(() => {}));
        tasks.push(API.get('getDispositivos', {}).then(r => { if (r) { cfgData.dispositivos = _dispAplicarShield(r); _cfgSaveCache('dispositivos', cfgData.dispositivos); } }).catch(() => {}));
        tasks.push(API.get('getRolesAmoEsclavo', {}).then(r => { if (r && typeof r === 'object') cfgData.rolesAmoEsclavo = r; }).catch(() => {}));   // [786] chip amo/esclavo
        tasks.push(API.get('getAlertasExtensionHorario', {}).then(r => { if (r) cfgData.alertasHorario = r; }).catch(() => {}));   // [635]
        tasks.push(API.get('getSeries', {}).then(r => { if (r) { cfgData.series = r; _cfgSaveCache('series', r); } }).catch(() => {}));
      }
      if (tab === 'personal') {
        tasks.push(API.get('getPersonalMaster', { appOrigen: 'warehouseMos' }).then(r => { if (r) { cfgData.personal = r; _cfgSaveCache('personal', r); } }).catch(() => {}));
        tasks.push(API.get('getPersonalMaster', { appOrigen: 'MOS' }).then(r => { if (r) { cfgData.personalMOS = r; _cfgSaveCache('personalMOS', r); } }).catch(() => {}));
        tasks.push(API.get('getVendedoresMEBloqueados', {}).then(r => { if (r) { cfgData.bloqueosME = r; _cfgSaveCache('bloqueosME', r); } }).catch(() => {}));
        tasks.push(API.get('getDispositivos', {}).then(r => { if (r) { cfgData.dispositivos = _dispAplicarShield(r); _cfgSaveCache('dispositivos', cfgData.dispositivos); } }).catch(() => {}));
      }
      if (tab === 'categorias') {
        tasks.push(API.get('getTaxonomia', {}).then(r => { if (Array.isArray(r)) { cfgData.taxonomia = r; _cfgSaveCache('taxonomia', r); } }).catch(() => {}));
      }
      await Promise.all(tasks);
      // Re-render solo si la pestaña sigue activa
      if (S.view === 'config') renderCfgTab(S.cfgTab || 'infra');
    } finally {
      iconBusy('config', false);
    }
  }

  async function loadConfig() {
    S.cfgTab = S.cfgTab || 'infra';
    // [v2.43.32] Pre-carga horarios en background (no espera) — para que al
    // abrir el tab Personal o el modal, ya estén disponibles instantáneos.
    if (!S._horariosAppsCache) {
      _cargarHorariosApps(true).catch(() => {});
    }
    // [v2.43.37] Pre-cargar rotación semanal WH para el catálogo.
    // Esto hace que al entrar a Catálogo el sparkline aparezca instantáneo.
    if (!S._rotacionSemanalCache) {
      _cargarRotacionSemanal(true).catch(() => {});
    }
    // 1) Hidratar inmediato desde cache (zero spinner para usuarios recurrentes)
    const huboCache = _cfgHidratarTodos();
    if (huboCache) renderCfgTab(S.cfgTab);
    // 2) Si ya se prefetcheó al login, no reabrir red — lo nuevo viene del auto-refresh
    if (S._cfgPrecargado) {
      _cfgIniciarAutoRefresh();
      return;
    }
    // 3) Primera vez: pedir fresh en paralelo (con loading icon)
    iconBusy('config', true);
    try {
      const [zonRes, estRes, impRes, persRes, persMOSRes, bloqMERes, serRes, dispRes, catRes, cfgRes] = await Promise.allSettled([
        API.get('getZonas', {}),
        API.get('getEstaciones', {}),
        API.get('getImpresoras', {}),
        API.get('getPersonalMaster', { appOrigen: 'warehouseMos' }),
        API.get('getPersonalMaster', { appOrigen: 'MOS' }),
        API.get('getVendedoresMEBloqueados', {}),
        API.get('getSeries', {}),
        API.get('getDispositivos', {}),
        API.get('getTaxonomia', {}),
        API.get('getConfig', {})
      ]);
      const _set = (k, res) => {
        if (res.status === 'fulfilled') {
          cfgData[k] = res.value || (k === 'config' ? {} : []);
          _cfgSaveCache(k, cfgData[k]);
        } else if (cfgData[k] === undefined) {
          cfgData[k] = (k === 'config' ? {} : []);
        }
      };
      _set('zonas', zonRes);
      _set('estaciones', estRes);
      _set('impresoras', impRes);
      _set('personal', persRes);
      _set('personalMOS', persMOSRes);
      _set('bloqueosME', bloqMERes);
      _set('series', serRes);
      _set('dispositivos', dispRes);
      _set('taxonomia', catRes);
      _set('config', cfgRes);
      S._cfgPrecargado = true;
      renderCfgTab(S.cfgTab);
    } finally {
      iconBusy('config', false);
      _cfgIniciarAutoRefresh();
    }
  }

  function setCfgTab(tab) {
    S.cfgTab = tab;
    const tabs = ['infra','personal','categorias','notifs','bancarios','ia','yape'];   // [852] +IA · [858] +Yapes
    tabs.forEach(t => {
      const btn = $('cfgTab' + t.charAt(0).toUpperCase() + t.slice(1));
      if (btn) btn.classList.toggle('active', t === tab);
      const panel = $('cfgPanel' + t.charAt(0).toUpperCase() + t.slice(1));
      if (panel) panel.classList.toggle('hidden', t !== tab);
    });
    renderCfgTab(tab);
  }

  function renderCfgTab(tab) {
    if (tab === 'infra')        _arrancarRefreshInfra();
    else                        _detenerRefreshInfra();
    if (tab === 'personal')     _arrancarRefreshPersonal();
    else                        _detenerRefreshPersonal();
    switch (tab) {
      case 'infra':        renderInfra(); break;
      case 'personal':     renderPersonal();     break;
      case 'categorias':   renderCategorias();   break;
      case 'notifs':       renderNotifsPanel();  break;
      case 'bancarios':    renderBancarios();    break;
      case 'ia':           renderIaPanel();      break;   // [852] consumo de IA
      case 'yape':         renderYapeCard();     break;   // [858] captura de Yapes
    }
  }

  // ── Tarjeta de presentación: modal de números WhatsApp (+51 fijo, solo 9 dígitos) ──
  // Guardado: se prepende '51' (Perú) → se almacena 51XXXXXXXXX (formato wa.me). En pantalla solo los 9 dígitos.
  function abrirTarjetaModal() { openModal('modalTarjetaWA'); cargarTarjetaWA(); }
  function _twaLocal(v) {       // 51XXXXXXXXX -> XXXXXXXXX (oculta placeholder de ceros)
    v = String(v || '').replace(/\D/g, '');
    if (v.slice(0, 2) === '51' && v.length >= 11) v = v.slice(2);
    return /^0*$/.test(v) ? '' : v;
  }
  // [Lote3-A · A2-MOS] estado de la última carga: si falló, NO se puede guardar a
  // ciegas (guardar con campos vacíos BORRARÍA los números en producción). _twaOrig
  // guarda lo cargado para detectar si un número con valor se está vaciando.
  let _twaCargaOk = false;
  let _twaOrig = { com: '', prov: '', marca: '' };
  async function cargarTarjetaWA() {
    _twaCargaOk = false;
    const sb = $('btnTwaSave'); if (sb) { sb.disabled = false; sb.title = ''; }
    try {
      const d = await API.get('getTarjetaWA', {});   // d = { TARJETA_WA_COMERCIAL, TARJETA_WA_COMPRAS, TARJETA_MARCA }
      const com = _twaLocal(d && d.TARJETA_WA_COMERCIAL);
      const prov = _twaLocal(d && d.TARJETA_WA_COMPRAS);
      const mar = (d && d.TARJETA_MARCA) || '';
      const c = $('twaComercial'); if (c) c.value = com;
      const p = $('twaCompras');   if (p) p.value = prov;
      const m = $('twaMarca');     if (m) m.value = mar;
      _twaOrig = { com, prov, marca: mar };
      _twaCargaOk = true;
    } catch (_) {
      // Carga falló → bloquear Guardar (reabrir el modal con red reintenta).
      if (sb) { sb.disabled = true; sb.title = 'No se pudo cargar — reabre con conexión'; }
      toast('No se pudo cargar la tarjeta. Reintenta con conexión antes de guardar.', 'warn');
    }
  }
  function _twaFeedbackOk(btn) {
    try {
      const ctx = new (window.AudioContext || window.webkitAudioContext)();
      const o = ctx.createOscillator(), g = ctx.createGain();
      o.connect(g); g.connect(ctx.destination); o.type = 'sine';
      o.frequency.setValueAtTime(660, ctx.currentTime);
      o.frequency.exponentialRampToValueAtTime(990, ctx.currentTime + 0.12);
      g.gain.setValueAtTime(0.25, ctx.currentTime);
      g.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.18);
      o.start(); o.stop(ctx.currentTime + 0.19);
    } catch (_) {}
    try { if (navigator.vibrate) navigator.vibrate([30, 40, 30]); } catch (_) {}
    if (btn) {
      btn.disabled = false; btn.innerHTML = '✓ ¡Guardado!';
      btn.style.background = 'linear-gradient(135deg,#059669,#047857)';
      setTimeout(() => { btn.innerHTML = '💾 Guardar'; btn.style.background = 'linear-gradient(135deg,#4f46e5,#7c3aed)'; }, 1600);
    }
  }
  async function guardarTarjetaWA() {
    const btn = $('btnTwaSave');
    // [Lote3-A · A2-MOS] no guardar si la carga falló: los inputs no reflejan el
    // estado real → guardar los borraría. Forzar reabrir con red.
    if (!_twaCargaOk) { toast('Reabre el modal con conexión antes de guardar (la carga falló)', 'error'); return; }
    const dig = id => (($(id) || {}).value || '').replace(/\D/g, '');
    const comLocal = dig('twaComercial'), provLocal = dig('twaCompras');
    const marca = (($('twaMarca') || {}).value || '').trim();
    if (comLocal && comLocal.length !== 9)  { toast('El número de clientes debe tener 9 dígitos', 'error'); return; }
    if (provLocal && provLocal.length !== 9) { toast('El número de proveedores debe tener 9 dígitos', 'error'); return; }
    // [Lote3-A · A2-MOS] si un número que TENÍA valor quedó vacío, confirmar (borrado accidental)
    const vaciaCom = _twaOrig.com && !comLocal;
    const vaciaProv = _twaOrig.prov && !provLocal;
    if (vaciaCom || vaciaProv) {
      const cuales = [vaciaCom ? 'clientes' : '', vaciaProv ? 'proveedores' : ''].filter(Boolean).join(' y ');
      const ok = await _modalConfirm('Vas a dejar SIN número de WhatsApp de ' + cuales + '.\n\nLas tarjetas impresas ya no tendrán a quién enviar. ¿Continuar?', { warning: true, titulo: 'Borrar número' });
      if (!ok) return;
    }
    const full = n => n ? ('51' + n) : '';
    if (btn) { btn.disabled = true; btn.innerHTML = '⏳ Guardando…'; }
    try {
      // [Lote3-A · A1-MOS] r = data desempaquetado = { comercial, compras, marca, supabaseOk }.
      // supabaseOk=false → CONFIG_MOS se guardó pero mos.config (lo que leen las tarjetas
      // del POS) NO → antes el toast decía "¡Listo!" igual y el POS imprimía el número viejo.
      const r = await API.post('guardarTarjetaWA', { comercial: full(comLocal), compras: full(provLocal), marca });
      if (r && r.supabaseOk === false) {
        toast('⚠ Guardado en MOS pero NO llegó a las tarjetas del POS. Reintenta con red.', 'error');
        if (btn) { btn.disabled = false; btn.innerHTML = '💾 Guardar'; }
        return;   // NO cerrar el modal: el cambio no está completo
      }
      // refrescar el snapshot original (lo guardado es ahora la verdad)
      _twaOrig = { com: comLocal, prov: provLocal, marca };
      _twaFeedbackOk(btn);
      toast('¡Listo! Las tarjetas ya usan los números nuevos ✅', 'ok');
      setTimeout(() => closeModal('modalTarjetaWA'), 900);
    } catch (e) {
      toast((e && e.message) || 'No se pudo guardar', 'error');
      if (btn) { btn.disabled = false; btn.innerHTML = '💾 Guardar'; }
    }
  }

  // ════════════════════════════════════════════════════════════
  // NOTIFICACIONES — pestaña Configuraciones (solo Master edita)
  // ════════════════════════════════════════════════════════════
  const _notifState = {
    items: [],
    filtroOrigen: 'all',
    filtroEstado: 'all',
    log: [],
    expandido: {},
    cargado: false
  };
  const NOTIF_ROLES_DISP = [
    { key: 'MASTER',     label: 'Master',     cls: 'master' },
    { key: 'ADMIN',      label: 'Admin',      cls: 'admin' },
    { key: 'CAJERO',     label: 'Cajeros',    cls: 'cajero' },
    { key: 'VENDEDOR',   label: 'Vendedores', cls: 'cajero' },
    { key: 'ALMACENERO', label: 'Almaceneros',cls: 'almacen' },
    { key: 'ENVASADOR',  label: 'Envasadores',cls: 'almacen' }
  ];

  function _notifIsMaster() {
    const rol = String(S.session?.rol || '').toUpperCase();
    return rol === 'MASTER';
  }

  async function renderNotifsPanel() {
    const cont = $('notifsList');
    if (!cont) return;
    // Mostrar permiso badge
    const badge = $('notifsPermisoBadge');
    if (badge) {
      if (_notifIsMaster()) {
        badge.textContent = '✓ Modo edición Master';
        badge.style.color = '#34d399';
      } else {
        badge.textContent = 'Solo Master puede editar (estás en modo lectura)';
        badge.style.color = '#fbbf24';
      }
    }
    if (!_notifState.cargado) {
      cont.innerHTML = `<div class="text-center py-12 text-slate-500 text-sm">
        <div class="inline-block animate-spin">⏳</div> Cargando catálogo...
      </div>`;
      try {
        const res = await API.get('getNotificacionesConfig', {});
        _notifState.items = Array.isArray(res) ? res : ((res && res.data) || []);
        _notifState.cargado = true;
      } catch(e) {
        cont.innerHTML = `<div class="text-center py-12 text-rose-400 text-sm">⚠ Error: ${e.message || e}</div>`;
        return;
      }
    }
    _renderNotifs();
  }

  async function refreshNotifs(ev) {
    if (ev && typeof _evalRipple === 'function') _evalRipple(ev);
    _notifState.cargado = false;
    if (typeof _evalSfx === 'function') _evalSfx('tap');
    await renderNotifsPanel();
  }

  function notifSetFiltro(origen, ev) {
    _notifState.filtroOrigen = origen;
    document.querySelectorAll('#notifsFilterBar [data-f]').forEach(b =>
      b.classList.toggle('active', b.dataset.f === origen));
    if (typeof _evalSfx === 'function') _evalSfx('switch');
    _renderNotifs();
  }
  function notifSetEstado(estado, ev) {
    _notifState.filtroEstado = estado;
    document.querySelectorAll('#notifsFilterBar [data-e]').forEach(b =>
      b.classList.toggle('active', b.dataset.e === estado));
    if (typeof _evalSfx === 'function') _evalSfx('switch');
    _renderNotifs();
  }

  function _notifFiltrar(items) {
    return items.filter(it => {
      if (_notifState.filtroOrigen !== 'all' && String(it.origen).toUpperCase() !== _notifState.filtroOrigen) return false;
      const activa = !!it.activa;
      if (_notifState.filtroEstado === 'ON'  && !activa) return false;
      if (_notifState.filtroEstado === 'OFF' &&  activa) return false;
      return true;
    });
  }

  function _renderNotifs() {
    const cont = $('notifsList');
    if (!cont) return;
    const items = _notifFiltrar(_notifState.items || []);
    if (!items.length) {
      cont.innerHTML = `<div class="text-center py-10 text-slate-500 text-sm">
        <div class="text-3xl mb-2 opacity-50">🔕</div>
        Sin notificaciones que coincidan con el filtro
      </div>`;
      return;
    }
    // Agrupar por origen
    const grupos = { MOS: [], ME: [], WH: [] };
    items.forEach(it => {
      const o = String(it.origen).toUpperCase();
      (grupos[o] || (grupos[o] = [])).push(it);
    });
    const titulos = { MOS: '🎯 MOS · Sistema y administración', ME: '🛒 MosExpress · POS', WH: '🏭 warehouseMos · Almacén' };
    let html = '';
    let idx = 0;
    ['MOS','ME','WH'].forEach(o => {
      const arr = grupos[o] || [];
      if (!arr.length) return;
      html += `<div class="text-[10px] font-bold uppercase tracking-wider text-slate-400 mt-3 mb-2 px-1">${titulos[o]}</div>`;
      arr.forEach(it => { html += _notifCard(it, idx++); });
    });
    cont.innerHTML = html;
  }

  function _notifCard(n, idx) {
    const isOn = !!n.activa;
    const expandido = !!_notifState.expandido[n.idNotif];
    const silenciada = n.silenciada_hasta && new Date(n.silenciada_hasta).getTime() > Date.now();
    const prioridad = String(n.prioridad || 'normal').toLowerCase();
    const cardCls = [
      'notif-card',
      !isOn ? 'silenciada' : '',
      prioridad === 'alta' ? 'alta' : '',
      expandido ? 'expanded' : ''
    ].filter(Boolean).join(' ');
    const silenciaTxt = silenciada ? `<span class="text-[10px] text-amber-400 ml-1">🔕 hasta ${new Date(n.silenciada_hasta).toLocaleString('es-PE', { day:'2-digit', month:'short', hour:'2-digit', minute:'2-digit' })}</span>` : '';
    const rolesSet = new Set(String(n.audiencia_roles || '').split(',').map(s => s.trim().toUpperCase()).filter(Boolean));
    const usuariosExtra = String(n.audiencia_usuarios || '').split(',').map(s => s.trim()).filter(Boolean);

    const chipsRoles = NOTIF_ROLES_DISP.map(r => {
      const on = rolesSet.has(r.key);
      return `<span class="notif-rol-chip ${r.cls}${on ? ' on' : ''}"
                onclick="MOS._notifToggleRol('${n.idNotif}', '${r.key}', event)">${r.label}</span>`;
    }).join(' ');

    // Body SIEMPRE renderizado — se oculta/muestra con CSS (sin reflow ni parpadeo)
    return `
      <div class="${cardCls}" style="--i:${Math.min(idx,18)}" data-id="${n.idNotif}">
        <div class="flex items-center gap-3 cursor-pointer" onclick="MOS._notifToggleExpand('${n.idNotif}', event)">
          <span style="font-size:22px">${n.icono || '🔔'}</span>
          <div class="flex-1 min-w-0">
            <div class="flex items-center gap-2 flex-wrap">
              <span class="font-semibold text-slate-100 text-sm truncate">${n.titulo}</span>
              ${prioridad === 'alta' ? '<span class="text-[9px] text-rose-400 font-bold">🚨 ALTA</span>' : ''}
              ${silenciaTxt}
            </div>
            <div class="text-[11px] text-slate-500 mt-0.5">${n.descripcion || ''}</div>
            <div class="flex items-center gap-1 mt-1 flex-wrap">
              ${Array.from(rolesSet).slice(0,3).map(r => `<span class="text-[9px] text-slate-500">· ${r}</span>`).join('')}
              ${usuariosExtra.length ? `<span class="text-[9px] text-emerald-400">+${usuariosExtra.length} usuario(s) extra</span>` : ''}
            </div>
          </div>
          <div class="notif-toggle ${isOn ? 'on' : ''}"
               onclick="event.stopPropagation();MOS._notifToggleActiva('${n.idNotif}', event)"
               title="${isOn ? 'Activa' : 'Silenciada'}"></div>
          <span class="notif-card-chevron">▸</span>
        </div>
        <div class="notif-card-body space-y-3">
          <div>
            <div class="text-[10px] uppercase tracking-wider text-slate-500 font-bold mb-1.5">👥 Audiencia por rol</div>
            <div class="flex flex-wrap gap-1.5">${chipsRoles}</div>
          </div>
          <div>
            <div class="text-[10px] uppercase tracking-wider text-slate-500 font-bold mb-1.5">➕ Usuarios específicos (extra)</div>
            <input type="text" class="inp text-xs"
                   id="notifExtra_${n.idNotif}"
                   placeholder="Nombres separados por coma (ej: Carlos, Jorgenis)"
                   value="${usuariosExtra.join(', ').replace(/"/g, '&quot;')}"
                   onchange="MOS._notifSetExtra('${n.idNotif}', this.value)">
          </div>
          <div class="grid grid-cols-2 gap-3">
            <div>
              <div class="text-[10px] uppercase tracking-wider text-slate-500 font-bold mb-1.5">⚡ Prioridad</div>
              <div class="flex gap-1">
                ${['baja','normal','alta'].map(p => {
                  const on = prioridad === p ? ' on ' + p + '-on' : ' ' + p + '-on';
                  return `<span class="notif-priority-pill${on}" onclick="MOS._notifSetPrioridad('${n.idNotif}', '${p}', event)">${p.toUpperCase()}</span>`;
                }).join('')}
              </div>
            </div>
            <div>
              <div class="text-[10px] uppercase tracking-wider text-slate-500 font-bold mb-1.5">🚫 Excluir origen</div>
              <label class="flex items-center gap-2 text-xs cursor-pointer">
                <input type="checkbox" ${n.excluir_origen ? 'checked' : ''}
                       style="width:14px;height:14px;accent-color:#fbbf24;cursor:pointer"
                       onchange="MOS._notifSetExcluir('${n.idNotif}', this.checked)">
                <span class="text-slate-300">Quien dispara no recibe</span>
              </label>
            </div>
          </div>
          <div>
            <div class="text-[10px] uppercase tracking-wider text-slate-500 font-bold mb-1.5">🔕 Silenciar temporal</div>
            <div class="flex gap-1 flex-wrap">
              <button onclick="MOS._notifSilenciar('${n.idNotif}','1h', event)"     class="btn-ghost btn-ripple text-[10px] px-2 py-1">1 hora</button>
              <button onclick="MOS._notifSilenciar('${n.idNotif}','manana', event)" class="btn-ghost btn-ripple text-[10px] px-2 py-1">Mañana 8am</button>
              <button onclick="MOS._notifSilenciar('${n.idNotif}','lunes', event)"  class="btn-ghost btn-ripple text-[10px] px-2 py-1">Lunes 7am</button>
              ${silenciada ? `<button onclick="MOS._notifSilenciar('${n.idNotif}','', event)" class="btn-ghost btn-ripple text-[10px] px-2 py-1" style="color:#34d399;border-color:rgba(34,197,94,.4)">↺ Quitar silencio</button>` : ''}
            </div>
          </div>
          <div class="flex gap-2 flex-wrap pt-2 border-t border-slate-800">
            <button onclick="MOS._notifRestaurarDefault('${n.idNotif}', event)" class="btn-ghost btn-ripple text-xs flex-1">↺ Restaurar default</button>
            <button onclick="MOS._notifProbar('${n.idNotif}', event)" class="btn-primary btn-ripple text-xs flex-1">🧪 Probar a mí</button>
          </div>
        </div>
      </div>`;
  }

  // ── Handlers ──
  function _notifToggleExpand(id, ev) {
    if (ev && ev.target.closest('.notif-toggle, input, button, .notif-rol-chip')) return;
    const nuevo = !_notifState.expandido[id];
    _notifState.expandido[id] = nuevo;
    if (typeof _evalSfx === 'function') _evalSfx(nuevo ? 'expand' : 'collapse');
    // Toggle SOLO la clase de esa card → CSS hace la animación, sin re-render
    const card = document.querySelector(`.notif-card[data-id="${id}"]`);
    if (card) card.classList.toggle('expanded', nuevo);
  }
  // Mutación quirúrgica: actualiza solo los nodos visibles afectados de UNA card
  function _notifPatchCard(id) {
    const it = _notifState.items.find(x => x.idNotif === id);
    if (!it) return;
    const card = document.querySelector(`.notif-card[data-id="${id}"]`);
    if (!card) return;
    const isOn = !!it.activa;
    const silenciada = it.silenciada_hasta && new Date(it.silenciada_hasta).getTime() > Date.now();
    card.classList.toggle('silenciada', !isOn);
    card.classList.toggle('alta', String(it.prioridad || 'normal').toLowerCase() === 'alta');
    const toggle = card.querySelector('.notif-toggle');
    if (toggle) toggle.classList.toggle('on', isOn);
  }

  async function _notifToggleActiva(id, ev) {
    if (!_notifIsMaster()) { toast('Solo Master puede editar', 'error'); if (typeof _evalSfx === 'function') _evalSfx('error'); return; }
    const it = _notifState.items.find(x => x.idNotif === id);
    if (!it) return;
    const nuevoEstado = !it.activa;
    it.activa = nuevoEstado;
    if (typeof _evalSfx === 'function') _evalSfx(nuevoEstado ? 'add' : 'remove');
    if (ev && typeof _evalRipple === 'function') _evalRipple(ev);
    _notifPatchCard(id);  // mutación quirúrgica, sin re-render global
    try {
      await API.post('actualizarNotifConfig', { idNotif: id, activa: nuevoEstado, actualizado_por: S.session?.nombre || 'admin' });
      toast(`${nuevoEstado ? '✓ Activada' : '🔕 Silenciada'} · ${it.titulo}`, 'ok');
    } catch(e) {
      it.activa = !nuevoEstado;
      _notifPatchCard(id);
      toast('Error: ' + e.message, 'error');
      if (typeof _evalSfx === 'function') _evalSfx('error');
    }
  }
  async function _notifToggleRol(id, rol, ev) {
    if (!_notifIsMaster()) { toast('Solo Master puede editar', 'error'); if (typeof _evalSfx === 'function') _evalSfx('error'); return; }
    const it = _notifState.items.find(x => x.idNotif === id);
    if (!it) return;
    const rolesSet = new Set(String(it.audiencia_roles || '').split(',').map(s => s.trim().toUpperCase()).filter(Boolean));
    if (rolesSet.has(rol)) rolesSet.delete(rol); else rolesSet.add(rol);
    const nuevoCsv = Array.from(rolesSet).join(',');
    it.audiencia_roles = nuevoCsv;
    if (typeof _evalSfx === 'function') _evalSfx('tap');
    // Toggle solo el chip clickeado (no re-render)
    const card = document.querySelector(`.notif-card[data-id="${id}"]`);
    const chip = card?.querySelector(`.notif-rol-chip[onclick*="'${rol}'"]`);
    if (chip) chip.classList.toggle('on', rolesSet.has(rol));
    try {
      await API.post('actualizarNotifConfig', { idNotif: id, audiencia_roles: nuevoCsv, actualizado_por: S.session?.nombre || 'admin' });
    } catch(e) { toast('Error: ' + e.message, 'error'); }
  }
  async function _notifSetExtra(id, valor) {
    if (!_notifIsMaster()) return;
    const csv = String(valor || '').split(',').map(s => s.trim()).filter(Boolean).join(',');
    const it = _notifState.items.find(x => x.idNotif === id);
    if (it) it.audiencia_usuarios = csv;
    try {
      await API.post('actualizarNotifConfig', { idNotif: id, audiencia_usuarios: csv, actualizado_por: S.session?.nombre || 'admin' });
      if (typeof _evalSfx === 'function') _evalSfx('add');
    } catch(e) { toast('Error: ' + e.message, 'error'); }
  }
  async function _notifSetPrioridad(id, prio, ev) {
    if (!_notifIsMaster()) return;
    const it = _notifState.items.find(x => x.idNotif === id);
    if (!it) return;
    it.prioridad = prio;
    if (typeof _evalSfx === 'function') _evalSfx('switch');
    // Mutación quirúrgica: solo cambia clases del card + pills
    _notifPatchCard(id);
    const card = document.querySelector(`.notif-card[data-id="${id}"]`);
    if (card) {
      card.querySelectorAll('.notif-priority-pill').forEach(pill => {
        const txt = (pill.textContent || '').trim().toLowerCase();
        pill.classList.toggle('on', txt === prio);
      });
    }
    try {
      await API.post('actualizarNotifConfig', { idNotif: id, prioridad: prio, actualizado_por: S.session?.nombre || 'admin' });
    } catch(e) { toast('Error: ' + e.message, 'error'); }
  }
  async function _notifSetExcluir(id, val) {
    if (!_notifIsMaster()) return;
    const it = _notifState.items.find(x => x.idNotif === id);
    if (it) it.excluir_origen = val;
    if (typeof _evalSfx === 'function') _evalSfx('tap');
    try {
      await API.post('actualizarNotifConfig', { idNotif: id, excluir_origen: val, actualizado_por: S.session?.nombre || 'admin' });
    } catch(e) { toast('Error: ' + e.message, 'error'); }
  }
  async function _notifSilenciar(id, preset, ev) {
    if (!_notifIsMaster()) return;
    let hastaIso = '';
    if (preset === '1h')     hastaIso = new Date(Date.now() + 3600*1000).toISOString();
    if (preset === 'manana') {
      const d = new Date(); d.setDate(d.getDate() + 1); d.setHours(8, 0, 0, 0);
      hastaIso = d.toISOString();
    }
    if (preset === 'lunes') {
      const d = new Date();
      const dia = d.getDay() || 7;
      d.setDate(d.getDate() + (8 - dia)); d.setHours(7, 0, 0, 0);
      hastaIso = d.toISOString();
    }
    const it = _notifState.items.find(x => x.idNotif === id);
    if (it) it.silenciada_hasta = hastaIso;
    if (typeof _evalSfx === 'function') _evalSfx(hastaIso ? 'switch' : 'success');
    if (ev && typeof _evalRipple === 'function') _evalRipple(ev);
    // Para silenciar/quitar mantenemos re-render (cambia texto del badge silenciada)
    _renderNotifs();
    try {
      await API.post('actualizarNotifConfig', { idNotif: id, silenciada_hasta: hastaIso, actualizado_por: S.session?.nombre || 'admin' });
      toast(hastaIso ? `🔕 Silenciada` : `✓ Reactivada`, 'ok');
    } catch(e) { toast('Error: ' + e.message, 'error'); }
  }
  async function _notifRestaurarDefault(id, ev) {
    if (!_notifIsMaster()) return;
    if (ev && typeof _evalRipple === 'function') _evalRipple(ev);
    try {
      await API.post('restaurarNotifDefault', { idNotif: id, actualizado_por: S.session?.nombre || 'admin' });
      _notifState.cargado = false;
      if (typeof _evalSfx === 'function') _evalSfx('pop');
      toast('↺ Restaurada al default', 'ok');
      renderNotifsPanel();
    } catch(e) { toast('Error: ' + e.message, 'error'); }
  }
  async function _notifProbar(id, ev) {
    if (ev && typeof _evalRipple === 'function') _evalRipple(ev);
    try {
      await API.post('probarNotificacion', { idNotif: id, soloAMi: true, miUsuario: S.session?.nombre || '' });
      if (typeof _evalSfx === 'function') _evalSfx('success');
      try {
        const r = ev?.target?.getBoundingClientRect();
        if (r && typeof _evalConfetti === 'function') _evalConfetti(r.left + r.width/2, r.top + r.height/2, '#a78bfa');
      } catch(_){}
      toast('🧪 Push de prueba enviada · revisa tu device', 'ok');
    } catch(e) {
      if (typeof _evalSfx === 'function') _evalSfx('error');
      toast('Error: ' + e.message, 'error');
    }
  }

  // ── Historial ──
  async function abrirNotifLog() {
    if (typeof _evalSfx === 'function') _evalSfx('open');
    // Llenar select de notifIds
    const sel = $('notifLogFiltroId');
    if (sel) {
      sel.innerHTML = '<option value="">Todas</option>' +
        (_notifState.items || []).map(n => `<option value="${n.idNotif}">${n.icono || ''} ${n.titulo}</option>`).join('');
    }
    openModal('modalNotifLog');
    refreshNotifLog();
  }
  async function refreshNotifLog(ev) {
    if (ev && typeof _evalRipple === 'function') _evalRipple(ev);
    const body = $('notifLogBody');
    if (!body) return;
    body.innerHTML = `<div class="text-center text-xs text-slate-500 py-8"><div class="inline-block animate-spin">⏳</div> Cargando...</div>`;
    const params = { limit: 100 };
    const idF = $('notifLogFiltroId')?.value || '';
    const desde = $('notifLogDesde')?.value || '';
    if (idF) params.idNotif = idF;
    if (desde) params.desde = desde;
    try {
      const res = await API.get('getNotifLog', params);
      const rows = Array.isArray(res) ? res : ((res && res.data) || []);
      _notifState.log = rows;
      if (!rows.length) {
        body.innerHTML = `<div class="text-center py-10 text-slate-500 text-sm">
          <div class="text-3xl mb-2 opacity-50">📭</div>
          Sin notificaciones en el rango
        </div>`;
        return;
      }
      body.innerHTML = rows.map((r, i) => {
        const ts = new Date(r.ts).toLocaleString('es-PE', { day:'2-digit', month:'short', hour:'2-digit', minute:'2-digit', second:'2-digit' });
        const esError = String(r.estado || '').toUpperCase() === 'ERROR' || String(r.estado).indexOf('silenc') >= 0;
        return `<div class="notif-log-row${esError ? ' error' : ''}" style="--i:${Math.min(i,18)};animation-delay:${Math.min(i,18)*20}ms">
          <div class="flex items-center justify-between gap-2 mb-1">
            <span class="text-xs font-semibold text-slate-200 truncate">${r.titulo || '—'}</span>
            <span class="text-[10px] text-slate-500 shrink-0">${ts}</span>
          </div>
          <div class="text-[10px] text-slate-500 mb-1">${(r.cuerpo || '').substring(0, 120)}</div>
          <div class="flex items-center gap-2 flex-wrap text-[10px]">
            <span class="font-mono text-slate-600">${r.idNotif || ''}</span>
            ${r.entregadas > 0 ? `<span class="text-emerald-400">✓ ${r.entregadas} entregadas</span>` : ''}
            ${r.errores > 0 ? `<span class="text-rose-400">⚠ ${r.errores} error${r.errores!==1?'es':''}</span>` : ''}
            ${r.estado && r.estado !== 'OK' ? `<span class="text-amber-400">${r.estado}</span>` : ''}
            <button onclick="MOS._notifReenviar('${r.idLog}', event)"
                    class="text-[10px] px-2 py-0.5 rounded ml-auto"
                    style="background:rgba(99,102,241,.1);color:#a5b4fc;border:1px solid rgba(99,102,241,.3)">🔄 Reenviar</button>
          </div>
        </div>`;
      }).join('');
    } catch(e) {
      body.innerHTML = `<div class="text-center text-xs text-rose-400 py-8">⚠ Error: ${e.message || e}</div>`;
    }
  }
  async function _notifReenviar(idLog, ev) {
    if (ev && typeof _evalRipple === 'function') _evalRipple(ev);
    try {
      await API.post('reenviarNotificacion', { idLog });
      if (typeof _evalSfx === 'function') _evalSfx('success');
      toast('🔄 Reenviada', 'ok');
      refreshNotifLog();
    } catch(e) {
      if (typeof _evalSfx === 'function') _evalSfx('error');
      toast('Error: ' + e.message, 'error');
    }
  }

  // Estado en vivo de impresoras (PrintNode). Mapa printNodeId → {online, computer}.
  // Lo llena _refrescarEstadoImpresoras; lo consume _renderInfraEstacion.
  let _impPNEstado = {};
  let _impPNCargado = false;
  async function _refrescarEstadoImpresoras(reRender) {
    try {
      const r = await API.get('getPrintNodePrinters', {});
      const lista = Array.isArray(r) ? r : ((r && r.data) || []);
      if (!Array.isArray(lista)) return;
      const prev = _impPNEstado;
      const nuevo = {};
      let hayCaidaNueva = false;
      lista.forEach(p => {
        // [v2.41.81] Indexamos por printNodeId (string) — para SIN_ID el id
        // viene null, así que usamos un id sintético por idEstacion para no
        // colisionar. El render mira pnSt por printNodeId, si no hay key,
        // cae al SIN_ID por defecto.
        const pid = p.printNodeId ? String(p.printNodeId) : '';
        if (!pid) return; // SIN_ID no se indexa, el frontend lo detecta solo
        nuevo[pid] = {
          // Retro-compat
          online:   p.state === 'ONLINE',
          computer: p.computer || '',
          nombre:   p.nombre || '',
          // [v2.41.81] Diagnóstico semántico nuevo
          state:    p.state    || 'UNKNOWN',
          reason:   p.reason   || '',
          icon:     p.icon     || '',
          color:    p.color    || '',
          computerState:    p.computerState    || '',
          printerStateRaw:  p.printerStateRaw  || ''
        };
        // Detectar transición ONLINE → no-ONLINE para alerta sonora
        if (_impPNCargado && prev[pid] && prev[pid].state === 'ONLINE' && p.state !== 'ONLINE') {
          hayCaidaNueva = true;
        }
      });
      _impPNEstado = nuevo;
      _impPNCargado = true;
      if (hayCaidaNueva) {
        try { _evalSfx && _evalSfx('error'); } catch(_){}
        try {
          const caidas = lista.filter(p => p.state !== 'ONLINE' && p.printNodeId)
                              .map(p => `${p.nombre || p.printNodeId} (${p.reason || p.state})`)
                              .join(', ');
          toast('🖨 Impresora con problema: ' + caidas, 'error', 6000);
        } catch(_){}
      }
      if (reRender && S.cfgTab === 'infra') { try { renderInfra(); } catch(_){} }
    } catch(_) { /* tolerar — PrintNode puede tardar o no responder */ }
  }

  // Auto-refresh dinámico de dispositivos (cada 30s mientras Infra esté visible)
  let _intervalInfra = null;
  function _arrancarRefreshInfra() {
    // Carga inicial del estado de impresoras + sonido si al ABRIR ya hay caídas
    _refrescarEstadoImpresoras(true).then(() => {
      if (S.cfgTab === 'infra') {
        const offline = Object.values(_impPNEstado).filter(e => !e.online);
        if (offline.length) {
          try { _evalSfx && _evalSfx('error'); } catch(_){}
        }
      }
    });
    if (_intervalInfra) return;
    _intervalInfra = setInterval(async () => {
      if (S.cfgTab !== 'infra' || document.hidden) return;
      try {
        const data = await API.get('getDispositivos', {});
        if (Array.isArray(data)) {
          // Detectar cambios para no re-renderizar inútilmente
          const prevJson = JSON.stringify(cfgData.dispositivos || []);
          // [v2.43.348 fix] aplicar el shield optimista también en el poll de 15s — sin esto un poll
          // dentro de la ventana de aprobación traía el estado viejo (PENDIENTE) y el card parpadeaba.
          const _shielded = _dispAplicarShield(data);
          const newJson = JSON.stringify(_shielded);
          if (prevJson !== newJson) {
            cfgData.dispositivos = _shielded;
            renderInfra();
          }
        }
      } catch(_) { /* tolerar */ }
    }, 15 * 1000); // cada 15s para sentir tiempo real
    // [FIX 500x OPT-1] capturar los 2 timers (antes anónimos → fugados en cada entrar/salir de Infra).
    // Estado de impresoras PrintNode cada 25s mientras Infra esté abierto
    _intervalInfraPrinters = setInterval(() => {
      if (S.cfgTab !== 'infra' || document.hidden) return;
      _refrescarEstadoImpresoras(true);
    }, 25 * 1000);
    // Re-render local cada 10s para que los "hace Xs" se actualicen sin esperar fetch
    _intervalInfraRender = setInterval(() => {
      if (S.cfgTab !== 'infra' || document.hidden) return;
      try { renderInfra(); } catch(_) {}
    }, 10 * 1000);
  }
  let _intervalInfraPrinters = null, _intervalInfraRender = null;
  function _detenerRefreshInfra() {
    if (_intervalInfra) { clearInterval(_intervalInfra); _intervalInfra = null; }
    if (_intervalInfraPrinters) { clearInterval(_intervalInfraPrinters); _intervalInfraPrinters = null; }
    if (_intervalInfraRender) { clearInterval(_intervalInfraRender); _intervalInfraRender = null; }
  }

  // Auto-refresh Personal cada 30s (Ultima_Conexion + dispositivos para online ME)
  let _intervalPersonal = null;
  function _arrancarRefreshPersonal() {
    if (_intervalPersonal) return;
    _intervalPersonal = setInterval(async () => {
      if (S.cfgTab !== 'personal' || document.hidden) return;
      try {
        const [personRes, mosRes, dispRes] = await Promise.allSettled([
          API.get('getPersonalMaster', { appOrigen: 'warehouseMos' }),
          API.get('getPersonalMaster', { appOrigen: 'MOS' }),
          API.get('getDispositivos', {})
        ]);
        let cambios = false;
        // [v2.43.36] Helper: preservar mutaciones optimistas pendientes.
        // Si el operador acaba de guardar un horario custom y la API aún no
        // confirmó, NO queremos que el polling pise el cambio con datos viejos.
        // Reglas:
        //   - Si la fila vieja tiene _horCustomPendiente=true → conservar
        //     horarioCustom local + flag en la fila nueva (no pisar mientras
        //     se está guardando)
        const preservarPendientes = (oldArr, newArr) => {
          const oldByid = {};
          (oldArr || []).forEach(x => {
            if (x._horCustomPendiente) oldByid[String(x.idPersonal)] = x;
          });
          (newArr || []).forEach(n => {
            const old = oldByid[String(n.idPersonal)];
            if (old) {
              n.horarioCustom = old.horarioCustom;
              n._horCustomPendiente = true;
            }
          });
          return newArr;
        };
        if (personRes.status === 'fulfilled') {
          const newJson = JSON.stringify(personRes.value || []);
          if (JSON.stringify(cfgData.personal || []) !== newJson) {
            cfgData.personal = preservarPendientes(cfgData.personal, personRes.value || []);
            cambios = true;
          }
        }
        if (mosRes.status === 'fulfilled') {
          const newJson = JSON.stringify(mosRes.value || []);
          if (JSON.stringify(cfgData.personalMOS || []) !== newJson) {
            cfgData.personalMOS = preservarPendientes(cfgData.personalMOS, mosRes.value || []);
            cambios = true;
          }
        }
        if (dispRes.status === 'fulfilled') {
          const _shieldedP = _dispAplicarShield(dispRes.value || []);   // [v2.43.348 fix] shield en poll de Personal
          const newJson = JSON.stringify(_shieldedP);
          if (JSON.stringify(cfgData.dispositivos || []) !== newJson) {
            cfgData.dispositivos = _shieldedP;
            cambios = true;
          }
        }
        if (cambios) renderPersonal();
      } catch(_) {}
    }, 30 * 1000);
  }
  function _detenerRefreshPersonal() {
    if (_intervalPersonal) { clearInterval(_intervalPersonal); _intervalPersonal = null; }
  }

  // ── TUTORIAL TICKETS (módulo Cajas) ──────────────────────
  const _TUT_TIC_TOTAL = 8;
  let _tutTicSlide = 1;
  function tutTicketsOpen() { _tutTicSlide = 1; _tutTicRender(); openModal('modalTutTickets'); }
  function tutTicketsClose() { closeModal('modalTutTickets'); }
  function tutTicketsNext() { if (_tutTicSlide < _TUT_TIC_TOTAL) { _tutTicSlide++; _tutTicRender(); } else tutTicketsClose(); }
  function tutTicketsPrev() { if (_tutTicSlide > 1) { _tutTicSlide--; _tutTicRender(); } }
  function tutTicketsGoto(n) {
    n = parseInt(n) || 1;
    if (n < 1 || n > _TUT_TIC_TOTAL) return;
    _tutTicSlide = n; _tutTicRender();
  }
  function _tutTicRender() {
    document.querySelectorAll('#modalTutTickets .tut-slide').forEach(el => {
      el.classList.toggle('active', parseInt(el.dataset.tslide) === _tutTicSlide);
    });
    document.querySelectorAll('#tutTicDots .tut-dot').forEach((el, i) => {
      el.classList.toggle('active', i + 1 === _tutTicSlide);
    });
    const bar = $('tutTicProgressBar');
    if (bar) bar.style.width = (_tutTicSlide * 100 / _TUT_TIC_TOTAL).toFixed(2) + '%';
    const lbl = $('tutTicSlideLabel');
    if (lbl) lbl.textContent = `Slide ${_tutTicSlide} de ${_TUT_TIC_TOTAL}`;
    const btnPrev = $('tutTicBtnPrev'); if (btnPrev) btnPrev.disabled = _tutTicSlide === 1;
    const btnNext = $('tutTicBtnNext'); if (btnNext) btnNext.textContent = (_tutTicSlide === _TUT_TIC_TOTAL) ? 'Cerrar ✓' : 'Siguiente →';
    const body = $('tutTicBody'); if (body) body.scrollTop = 0;
  }

  // ── TUTORIAL flotante en catálogo ────────────────────────
  const _TUT_TOTAL = 8;
  let _tutSlide = 1;

  function tutorialOpen() {
    _tutSlide = 1;
    _tutRender();
    openModal('modalTutorial');
  }
  function tutorialClose() { closeModal('modalTutorial'); }
  function tutorialNext() {
    if (_tutSlide < _TUT_TOTAL) { _tutSlide++; _tutRender(); }
    else tutorialClose();
  }
  function tutorialPrev() {
    if (_tutSlide > 1) { _tutSlide--; _tutRender(); }
  }
  function tutorialGoto(n) {
    n = parseInt(n) || 1;
    if (n < 1 || n > _TUT_TOTAL) return;
    _tutSlide = n;
    _tutRender();
  }
  function _tutRender() {
    document.querySelectorAll('#modalTutorial .tut-slide').forEach(el => {
      el.classList.toggle('active', parseInt(el.dataset.slide) === _tutSlide);
    });
    document.querySelectorAll('#tutDots .tut-dot').forEach((el, i) => {
      el.classList.toggle('active', i + 1 === _tutSlide);
    });
    const bar = $('tutProgressBar');
    if (bar) bar.style.width = (_tutSlide * 100 / _TUT_TOTAL).toFixed(2) + '%';
    const lbl = $('tutSlideLabel');
    if (lbl) lbl.textContent = `Slide ${_tutSlide} de ${_TUT_TOTAL}`;
    const btnPrev = $('tutBtnPrev');
    if (btnPrev) btnPrev.disabled = _tutSlide === 1;
    const btnNext = $('tutBtnNext');
    if (btnNext) btnNext.textContent = (_tutSlide === _TUT_TOTAL) ? 'Cerrar ✓' : 'Siguiente →';
    // Scroll body al inicio
    const body = $('tutBody');
    if (body) body.scrollTop = 0;
  }

  // ── Pestaña Configuración → Evaluación ─────────────────


  // ── CATEGORÍAS · Taxonomía IA (640) ─────────────────────
  // El margen por categoría MURIÓ (decisión dueño): este panel ya no configura precios,
  // es la GUÍA VIVA de la taxonomía — 23+ categorías / 108+ subcategorías con descripción,
  // ejemplos reales y conteos. Se AUTO-alimenta: si la IA detecta un dominio nuevo
  // (p.ej. HERRAMIENTAS) al crear/editar un producto, aparece aquí solo, con chip 🤖.
  let _catQ = '';
  let _catQTimer = null;
  let _catAbierta = null;   // categoría expandida (acordeón)
  const _TAX_EMOJI = { ABARROTES:'🌾', ACEITES:'🫒', BEBIDAS:'🥤', CONFITERIA:'🍬', CONSERVAS:'🥫', DECORATIVOS:'🎀', DESCARTABLES:'🥡', ENDULZANTES:'🍯', ENERGIZANTES:'⚡', ESPECIAS:'🌶️', GALLETAS_SNACKS:'🍪', GRANEL:'🥜', INFUSIONES:'🍵', INSUMOS_REPOSTERIA:'🧁', LACTEOS:'🥛', LIMPIEZA:'🧼', MENESTRAS:'🫘', OTROS:'📦', PRODUCTOS_CHINOS:'🥢', REPOSTERIA:'🎂', SALSAS:'🥣', VINAGRES:'🧴', VINOS_LICORES:'🍷' };
  function catBuscar(v) {
    _catQ = String(v || '').trim().toLowerCase();
    clearTimeout(_catQTimer);
    _catQTimer = setTimeout(() => {
      _renderCategoriasCards($('catGridContainer'), cfgData.taxonomia || []);
      const s = $('catSearchInp');
      if (s) { s.focus(); try { s.setSelectionRange(s.value.length, s.value.length); } catch (_) {} }
    }, 320);
  }
  function catToggle(cat) {
    _catAbierta = (_catAbierta === cat) ? null : cat;
    if (typeof _evalSfx === 'function') _evalSfx('open');
    _renderCategoriasCards($('catGridContainer'), cfgData.taxonomia || []);
  }
  async function renderCategorias(skipFetch) {
    const cont = $('catGridContainer');
    if (!cont) return;
    const cached = cfgData.taxonomia || [];
    if (cached.length > 0) _renderCategoriasCards(cont, cached);
    else cont.innerHTML = `<div class="col-span-full text-center py-8 text-slate-500 text-sm"><div class="inline-block animate-spin">⏳</div> Cargando...</div>`;
    if (!skipFetch) {
      try {
        const r = await API.get('getTaxonomia', {});
        if (Array.isArray(r)) { cfgData.taxonomia = r; _cfgSaveCache('taxonomia', r); }
        _renderCategoriasCards(cont, cfgData.taxonomia || []);
      } catch(e) {
        if (!cached.length) cont.innerHTML = `<div class="col-span-full text-center py-8 text-rose-400 text-sm">Error: ${e.message}</div>`;
      }
    }
  }

  // ¿la subcategoría matchea el buscador?
  function _taxSubHit(s) {
    return (String(s.subcategoria||'') + ' ' + String(s.descripcion||'') + ' ' + String(s.ejemplos||'')).toLowerCase().includes(_catQ);
  }
  // Tono estable por categoría (para el tile del emoji y los acentos)
  function _taxHue(cid) {
    let h = 0; const s = String(cid || '');
    for (let i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) % 360;
    return h;
  }
  function _renderCategoriasCards(cont, rows) {
    const bar = $('catCmdBar');
    const nSubs = rows.reduce((a, c) => a + (c.subcategorias || []).length, 0);
    const nProd = rows.reduce((a, c) => a + (Number(c.productos) || 0), 0);
    if (bar) {
      bar.innerHTML = `<div class="cmd">
        <div class="stat"><div><div class="big tnum">${rows.length}</div><div class="cap">categorías</div></div></div>
        <div class="stat"><div><div class="big tnum">${nSubs}</div><div class="cap">subcategorías</div></div></div>
        <div class="stat"><div><div class="big tnum">${nProd.toLocaleString()}</div><div class="cap">productos</div></div></div>
        <div class="cmd-right">
          <input id="catSearchInp" class="search" placeholder="🔎 categoría, subcategoría o ejemplo…" value="${_escapeHtml(_catQ)}" oninput="MOS.catBuscar(this.value)">
          <span class="taxchip-ia" title="La IA clasifica cada producto al crearlo o editarlo. Si detecta un dominio nuevo (p.ej. herramientas), la categoría se registra sola.">🤖 auto-alimentada por IA</span>
        </div>
      </div>`;
    }
    cont.className = 'grid2 taxgrid';
    const vis = _catQ
      ? rows.filter(c => (String(c.nombre||'') + ' ' + String(c.categoria||'') + ' ' + String(c.descripcion||'')).toLowerCase().includes(_catQ)
                      || (c.subcategorias || []).some(_taxSubHit))
      : rows;
    if (!vis.length) {
      cont.innerHTML = `<div style="grid-column:1/-1;text-align:center;padding:36px 0;color:#5f7290;font-size:13px">
        <div style="font-size:28px;opacity:.5;margin-bottom:8px">🏷️</div>${_catQ ? 'Sin resultados para "' + _escapeHtml(_catQ) + '"' : 'No se pudo cargar la taxonomía — reintenta en unos segundos'}</div>`;
      return;
    }
    const maxProd = Math.max(1, ...vis.map(c => Number(c.productos) || 0));
    cont.innerHTML = vis.map(c => {
      const cid = String(c.categoria || '');
      const emoji = _TAX_EMOJI[cid] || '🆕';
      const hue = _taxHue(cid);
      const esAuto = /🤖/.test(String(c.descripcion || ''));
      const abierta = (_catAbierta === cid) || (_catQ && (c.subcategorias || []).some(_taxSubHit) && !(String(c.nombre||'').toLowerCase().includes(_catQ)));
      const subs = (c.subcategorias || []);
      const subsVis = (abierta && _catQ) ? subs.filter(s => _taxSubHit(s) || String(c.nombre||'').toLowerCase().includes(_catQ)) : subs;
      const desc = String(c.descripcion || '').replace(/\s*\(.*margen.*\)\s*/i, '');
      const nP = Number(c.productos) || 0;
      // chips de las 3 subcategorías más pobladas (vista colapsada)
      const top3 = subs.slice(0, 3).map(s =>
        `<span class="taxmini">${_escapeHtml(s.subcategoria)} <b class="tnum">${Number(s.productos) || 0}</b></span>`).join('')
        + (subs.length > 3 ? `<span class="taxmini taxmini-mas">+${subs.length - 3}</span>` : '');
      let subHtml = '';
      if (abierta) {
        const maxSub = Math.max(1, ...subs.map(s => Number(s.productos) || 0));
        subHtml = `<div class="taxsubs" onclick="event.stopPropagation()">` + subsVis.map(s => {
          const n = Number(s.productos) || 0;
          return `<div class="taxsub" style="--th:${hue}">
            <div class="taxsub-top">
              <span class="taxsub-n">${_escapeHtml(s.subcategoria)}</span>
              ${s.auto ? '<span class="taxchip-ia sm">🤖 nueva</span>' : ''}
              <span class="taxsub-c tnum">${n}</span>
            </div>
            <div class="taxbar"><i style="width:${Math.max(3, Math.round(n / maxSub * 100))}%"></i></div>
            ${s.descripcion ? `<div class="taxsub-d">${_escapeHtml(s.descripcion)}</div>` : ''}
            ${s.ejemplos ? `<div class="taxsub-e" title="${_escapeHtml(s.ejemplos)}">🛒 ${_escapeHtml(s.ejemplos)}</div>` : ''}
          </div>`;
        }).join('') + `</div>`;
      }
      return `<div class="catcard taxcard${abierta ? ' tax-open' : ''}" style="--th:${hue}${abierta ? ';grid-column:1/-1' : ''}" onclick="MOS.catToggle('${_escAttrJs(cid)}')">
        <div class="taxhead">
          <span class="taxemoji">${emoji}</span>
          <div style="flex:1;min-width:0">
            <div class="ct" style="overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${_escapeHtml(c.nombre || cid)}${esAuto ? ' <span class="taxchip-ia sm">🤖 nueva</span>' : ''}</div>
            <div class="taxsubcnt">${subs.length} subcategorías</div>
          </div>
          <div class="taxnum"><b class="tnum">${nP.toLocaleString()}</b><span>productos</span></div>
          <span class="taxcaret${abierta ? ' up' : ''}">▾</span>
        </div>
        <div class="taxbar big"><i style="width:${Math.max(2, Math.round(nP / maxProd * 100))}%"></i></div>
        <div class="cdesc" style="white-space:normal">${_escapeHtml(desc.slice(0, 150))}</div>
        ${abierta ? '' : `<div class="taxminis">${top3}</div>`}
        ${subHtml}
      </div>`;
    }).join('');
  }

  // [rev.687] CRUD de categorías eliminado (Config→Categorías es la taxonomía IA, solo lectura)

  // ── Integridad / Auditoría de PRODUCTOS_MASTER + EQUIVALENCIAS ───
  async function renderIntegridad(skipFetch) {
    const cont = $('auditAlertas');
    const resumenEl = $('auditResumen');
    if (!cont || !resumenEl) return;
    if (!skipFetch) resumenEl.innerHTML = '<span class="text-slate-500">Cargando…</span>';
    try {
      const r = await API.get('getAuditoriaIntegridad', {});
      const data = (r && r.data) ? r.data : r;
      const alertas = (data && data.alertas) || [];
      const ultimaLimpia = data && data.ultimaAuditoriaLimpia;

      if (!alertas.length) {
        resumenEl.innerHTML = `
          <div class="flex items-start gap-3">
            <div class="text-2xl">✅</div>
            <div class="flex-1">
              <div class="text-sm font-semibold text-green-400">Catálogo íntegro</div>
              <div class="text-xs text-slate-500 mt-0.5">${ultimaLimpia ? 'Última auditoría limpia: ' + new Date(ultimaLimpia).toLocaleString() : 'Sin alertas activas. Corre una auditoría para verificar.'}</div>
            </div>
          </div>`;
        cont.innerHTML = '';
        return;
      }
      const criticas = alertas.filter(a => a.urgencia === 'CRITICA').length;
      const altas    = alertas.filter(a => a.urgencia === 'ALTA').length;
      resumenEl.innerHTML = `
        <div class="flex items-start gap-3">
          <div class="text-2xl">${criticas > 0 ? '🚨' : '⚠️'}</div>
          <div class="flex-1">
            <div class="text-sm font-semibold ${criticas > 0 ? 'text-rose-400' : 'text-amber-400'}">${alertas.length} alertas activas</div>
            <div class="text-xs text-slate-500 mt-0.5">${criticas} críticas · ${altas} altas · ${alertas.length - criticas - altas} medias/info</div>
          </div>
        </div>`;
      cont.innerHTML = alertas.map(a => {
        const colorBorder = a.urgencia === 'CRITICA' ? 'border-rose-500/40' : a.urgencia === 'ALTA' ? 'border-amber-500/40' : 'border-slate-700';
        const colorTipo   = a.urgencia === 'CRITICA' ? 'text-rose-400' : a.urgencia === 'ALTA' ? 'text-amber-400' : 'text-slate-400';
        let detalleExtra = '';
        // MOD_NO_AUTORIZADA → mostrar accion, tabla, source, params, contexto auditoría
        if (a.tipo === 'MOD_NO_AUTORIZADA' && a.datos) {
          const d = a.datos;
          let paramsObj = {};
          try { paramsObj = typeof d.params === 'string' ? JSON.parse(d.params) : (d.params || {}); } catch(_) { paramsObj = {}; }
          const idProd = paramsObj.idProducto || paramsObj.codigoBarra || paramsObj.idEquiv || '—';
          const camposEditados = Object.keys(paramsObj).filter(k => k !== '_source' && k !== '_audit' && k !== 'idProducto' && k !== 'idEquiv').join(', ') || '—';
          // Contexto auditoría
          const usuario = d.usuario ? `${d.usuario} (${d.rol || 'sin rol'})` : '— sin sesión —';
          const idSesion = d.idSesion || '—';
          const dispositivo = d.idDispositivo ? d.idDispositivo.slice(0, 16) + '…' : '— sin device ID —';
          const appOrigen = d.appOrigen || '—';
          // userAgent simplificado (extrae plataforma/browser)
          const ua = d.userAgent || '';
          const uaSimple = ua.match(/(iPhone|iPad|Android|Windows|Mac|Linux)[^;)]*/)?.[0]?.slice(0, 40) || (ua ? ua.slice(0, 40) : '—');
          const tsApp = d.timestampApp ? new Date(d.timestampApp).toLocaleString() : '—';
          detalleExtra = `
            <div class="mt-2 space-y-2">
              <!-- Qué intentó hacer -->
              <div class="text-[11px] font-mono space-y-0.5" style="background:rgba(244,63,94,.05);border-left:2px solid #f43f5e;padding:6px 8px;border-radius:4px">
                <div class="text-rose-300 font-semibold">⛔ Operación bloqueada</div>
                <div><span class="text-slate-500">Acción:</span> <span class="text-slate-300">${d.accion || '—'} en ${d.tabla || '—'}</span></div>
                <div><span class="text-slate-500">Origen reportado:</span> <span class="text-rose-300">${d.source || 'sin _source'}</span></div>
                <div><span class="text-slate-500">Producto/registro:</span> <span class="text-slate-300">${idProd}</span></div>
                <div><span class="text-slate-500">Campos:</span> <span class="text-slate-300">${camposEditados}</span></div>
              </div>
              <!-- Quién / Dónde / Cuándo -->
              <div class="text-[11px] font-mono space-y-0.5" style="background:rgba(99,102,241,.05);border-left:2px solid #6366f1;padding:6px 8px;border-radius:4px">
                <div class="text-indigo-300 font-semibold">🔎 Contexto del intento</div>
                <div><span class="text-slate-500">👤 Usuario:</span> <span class="text-slate-300">${usuario}</span></div>
                <div><span class="text-slate-500">🔑 idSesión:</span> <span class="text-slate-300">${idSesion}</span></div>
                <div><span class="text-slate-500">📱 Dispositivo:</span> <span class="text-slate-300">${dispositivo}</span></div>
                <div><span class="text-slate-500">🌐 App origen:</span> <span class="text-slate-300">${appOrigen}</span></div>
                <div><span class="text-slate-500">💻 Plataforma:</span> <span class="text-slate-300">${uaSimple}</span></div>
                <div><span class="text-slate-500">⏰ Hora cliente:</span> <span class="text-slate-300">${tsApp}</span></div>
              </div>
            </div>
            <div class="text-[10px] text-slate-600 mt-2 italic">💡 Si reconoces el usuario y la acción (cambió un precio, etc.) seguramente venga de una pestaña/dispositivo con la PWA antigua. Recárgala y marca la alerta como resuelta. Si NO reconoces nada, investigar.</div>
          `;
        } else if (a.datos && a.datos.primeras) {
          // AUDIT_INTEGRIDAD → primeras 5 anomalías
          detalleExtra = '<div class="text-[10px] text-slate-500 mt-2 font-mono whitespace-pre-wrap">'
            + (a.datos.primeras || []).slice(0, 5).map(p => '· ' + (p.detalle || JSON.stringify(p))).join('\n')
            + '</div>';
        }
        const fechaStr = a.fecha ? new Date(a.fecha).toLocaleString() : '';
        return `
          <div class="card-sm border ${colorBorder} p-3">
            <div class="flex items-start justify-between gap-2">
              <div class="min-w-0 flex-1">
                <div class="flex items-center gap-2">
                  <span class="text-xs font-bold ${colorTipo}">${a.urgencia}</span>
                  <span class="text-xs text-slate-500 font-mono">${a.tipo}</span>
                </div>
                <div class="text-sm text-slate-200 mt-1">${a.mensaje}</div>
                <div class="text-[10px] text-slate-600 mt-1">${fechaStr}</div>
                ${detalleExtra}
              </div>
              <button onclick="MOS.auditResolver('${a.idAlerta}')" class="btn-ghost text-xs px-2 py-1 shrink-0" title="Marcar como resuelta">✓</button>
            </div>
          </div>`;
      }).join('');
    } catch(e) {
      resumenEl.innerHTML = `<div class="text-rose-400 text-sm">Error: ${e.message}</div>`;
      cont.innerHTML = '';
    }
  }

  async function auditCorrer() {
    const resumenEl = $('auditResumen');
    if (resumenEl) resumenEl.innerHTML = '<span class="text-slate-500">Auditando…</span>';
    try {
      const r = await API.get('getAuditoriaIntegridad', { run: 'true' });
      const data = (r && r.data) ? r.data : r;
      const totalAnomalias = (data && data.anomalias) ? data.anomalias.length : 0;
      toast(totalAnomalias === 0 ? 'Auditoría limpia ✓' : totalAnomalias + ' anomalías detectadas', totalAnomalias === 0 ? 'ok' : 'error');
      await renderIntegridad();
      _auditCheckBanner();
    } catch(e) {
      toast('Error: ' + e.message, 'error');
      if (resumenEl) resumenEl.innerHTML = `<div class="text-rose-400 text-sm">Error: ${e.message}</div>`;
    }
  }

  async function auditResolver(idAlerta) {
    if (!idAlerta) return;
    try {
      await API.post('resolverAlertaAuditoria', { idAlerta });
      await renderIntegridad();
      _auditCheckBanner();
    } catch(e) { toast('Error: ' + e.message, 'error'); }
  }

  async function auditResolverTodas() {
    try {
      const r = await API.get('getAuditoriaIntegridad', {});
      const data = (r && r.data) ? r.data : r;
      const alertas = (data && data.alertas) || [];
      if (!alertas.length) { toast('No hay alertas activas', 'info'); return; }
      if (!await _modalConfirm('¿Marcar las ' + alertas.length + ' alertas como resueltas?', { titulo: 'Resolver alertas' })) return;
      await Promise.all(alertas.map(a => API.post('resolverAlertaAuditoria', { idAlerta: a.idAlerta }).catch(() => {})));
      toast(alertas.length + ' alertas archivadas', 'ok');
      await renderIntegridad();
      _auditCheckBanner();
    } catch(e) { toast('Error: ' + e.message, 'error'); }
  }

  // Banner de alertas en el catálogo
  async function _auditCheckBanner() {
    const banner = $('auditBannerCat');
    if (!banner) return;
    try {
      const r = await API.get('getAuditoriaIntegridad', {});
      const data = (r && r.data) ? r.data : r;
      const alertas = (data && data.alertas) || [];
      if (!alertas.length) { banner.classList.add('hidden'); banner.innerHTML = ''; return; }
      const criticas = alertas.filter(a => a.urgencia === 'CRITICA').length;
      const cls = criticas > 0 ? 'border-rose-500/40 bg-rose-500/5 text-rose-300' : 'border-amber-500/40 bg-amber-500/5 text-amber-300';
      const icon = criticas > 0 ? '🚨' : '⚠️';
      banner.classList.remove('hidden');
      banner.innerHTML = `
        <div class="card-sm border ${cls} p-3 flex items-center gap-3 cursor-pointer" onclick="MOS.nav('config');setTimeout(()=>MOS.setCfgTab('integridad'),50)">
          <span class="text-xl">${icon}</span>
          <div class="flex-1 min-w-0">
            <div class="text-sm font-semibold">${alertas.length} alerta${alertas.length === 1 ? '' : 's'} de integridad de catálogo</div>
            <div class="text-xs opacity-80">Click para ver detalle en Configuración → Integridad</div>
          </div>
          <span class="text-xl opacity-60">→</span>
        </div>`;
    } catch(_) { banner.classList.add('hidden'); }
  }

  // ════════════════════════════════════════════════════════════
  // INFRAESTRUCTURA — vista jerárquica Zona > Estación > Impresora
  // ════════════════════════════════════════════════════════════
  // ════════════════════════════════════════════════════════════════════
  // [REDISEÑO CONFIG · reconstrucción fiel al mockup config_modulo.html]
  // Sistema: .cmd (stats+buscador+filtro) → .zone.vip → .pend → .zone (series
  // .schip · política .pchip · .stations con .printer y fleet dibujado ·
  // 👥 .users con .ucard desplegables) → ciclo de vida → 🗄️ archivados.
  // Todos los handlers reales se conservan 1:1. Cero-GAS (solo pinta cfgData).
  // ════════════════════════════════════════════════════════════════════
  // [Realidad del heartbeat] device-auth late cada 10 MIN (verificar_dispositivo escribe
  // ultima_conexion=now()). "En línea" = último latido ≤12 min (10 + margen). El umbral viejo
  // de 5 min hacía que un equipo ACTIVO pareciera desconectado entre latidos (bug visto por el
  // dueño: él mismo salía "hace 8m" con el panel abierto). Además, el dispositivo de ESTE
  // navegador está en línea por definición (está renderizando esto).
  const _CFG_ONLINE_MIN = 12;
  function _esMiDispositivo(d) {
    try { return String(d.ID_Dispositivo) === String(localStorage.getItem('mos_device_id') || ''); } catch (_) { return false; }
  }
  // [PRESENCIA · tiempo real] estado del canal Supabase Realtime 'ecos-presencia'
  // (API.presencia() = { deviceId: [metas] }). Si un equipo está en el canal, está EN LÍNEA
  // AL SEGUNDO — sobreescribe el heartbeat de 10 min. Best-effort: canal caído ⇒ {}.
  function _presencia() {
    try { return (typeof API !== 'undefined' && API.presencia) ? (API.presencia() || {}) : {}; } catch (_) { return {}; }
  }
  function _presTieneDevice(id) {
    return Object.prototype.hasOwnProperty.call(_presencia(), String(id));
  }
  function _presNombres() {
    const out = [];
    const st = _presencia();
    for (const k in st) (st[k] || []).forEach(m => { if (m && m.nombre) out.push(_normNombre(m.nombre)); });
    return out;
  }
  function _dispEnLinea(d) {
    if (String(d.Estado || '').toUpperCase() !== 'ACTIVO') return false;
    if (_esMiDispositivo(d)) return true;
    if (_presTieneDevice(d.ID_Dispositivo)) return true;   // presencia WS = vivo al segundo
    return _dispActividad(d.Ultima_Conexion).minutos <= _CFG_ONLINE_MIN;
  }
  // Re-render suave de Infra cuando cambia la presencia (throttle 2s, solo si la tab está activa)
  let _presRenderT = 0;
  try {
    window.addEventListener('mos:presencia', () => {
      const ahora = Date.now();
      if (ahora - _presRenderT < 2000) return;
      _presRenderT = ahora;
      if (S.cfgTab === 'infra' && $('infraContenedor')) renderInfra();
    });
  } catch (_) {}

  let _cfgQ = '';           // buscador equipo/persona
  let _cfgVerTodos = false; // ⏸ suspendidos: ON = mostrar también susp>7d + inactivos
  let _cfgQTimer = null;
  const _CFG_7D_MIN = 7 * 24 * 60;
  const _cfgOpen = {};      // estado open/closed de cada <details> (sobrevive re-render del poll)

  function cfgBuscar(v) {
    _cfgQ = String(v || '').trim().toLowerCase();
    clearTimeout(_cfgQTimer);
    _cfgQTimer = setTimeout(() => {
      renderInfra();
      const s = $('cfgSearchInp');
      if (s) { s.focus(); try { s.setSelectionRange(s.value.length, s.value.length); } catch (_) {} }
    }, 380);
  }
  function cfgToggleSusp() { _cfgVerTodos = !_cfgVerTodos; renderInfra(); }
  function _cfgDetToggle(k, open) { _cfgOpen[k] = open; }
  function _cfgIsOpen(k, def) { return Object.prototype.hasOwnProperty.call(_cfgOpen, k) ? _cfgOpen[k] : def; }

  // Ciclo de vida en el fleet: ACTIVO siempre · SUSPENDIDO solo si ≤7d (los demás → Archivados).
  function _dispVisibleFleet(d) {
    const est = String(d.Estado || '').toUpperCase();
    if (est === 'ACTIVO') return true;
    // [635 · decisión dueño] un SUSPENDIDO jamás vive en una zona (VIP incluido):
    // ≤7 días → sección ⏸ Suspendidos · >7 días → Archivados. Las zonas quedan limpias.
    if (est === 'SUSPENDIDO') return _cfgVerTodos;
    if (est === 'INACTIVO') return _cfgVerTodos;
    return false; // PENDIENTE va en su sección · CANCELADO* en Archivados
  }
  // [635] suspendidos "frescos" (≤7 días) — sección propia con su duración
  function _dispSuspendidosFrescos() {
    return (cfgData.dispositivos || []).filter(d => {
      if (String(d.Estado || '').toUpperCase() !== 'SUSPENDIDO') return false;
      return _dispActividad(d.Ultima_Conexion).minutos <= _CFG_7D_MIN;
    });
  }
  function _fleetDe(devs) {
    return (devs || []).filter(_dispVisibleFleet).filter(d => {
      if (!_cfgQ) return true;
      return (String(d.Nombre_Equipo || '') + ' ' + String(d.Ultima_Sesion || '')).toLowerCase().includes(_cfgQ);
    });
  }

  // Rol de una persona por nombre (para la cara del dispositivo dibujado).
  function _rolDe(nombre) {
    const n = _normNombre(nombre);
    if (!n) return '';
    const full = p => _normNombre((p.nombre || '') + ' ' + (p.apellido || ''));
    const a = (cfgData.personalMOS || []).find(p => full(p) === n || _normNombre(p.nombre) === n);
    if (a) return String(a.rol || '').toLowerCase();
    const w = (cfgData.personal || []).find(p => full(p) === n || _normNombre(p.nombre) === n);
    if (w) return String(w.rol || '').toLowerCase();
    const { grupos } = { grupos: null }; // cajeros: buscar en cache liviano
    try {
      const raw = localStorage.getItem('mos_liq_pendientes');
      const per = raw ? (JSON.parse(raw).data || {}).personal : null;
      const c = (per || []).find(x => _normNombre(x.nombre) === n);
      if (c) return String(c.rol || 'cajero').toLowerCase();
    } catch (_) {}
    return '';
  }

  function _rolebadge(rol, opts) {
    opts = opts || {};
    const r = String(rol || '').toLowerCase();
    if (opts.ascendido) return `<span class="rolebadge" style="background:rgba(245,184,73,.16);color:#fcd34d;border:1px solid rgba(245,184,73,.4)">ascendido → admin</span>`;
    if (r === 'master') return `<span class="rolebadge master">master</span>`;
    if (r === 'admin' || r === 'administrador') return `<span class="rolebadge" style="background:rgba(167,139,250,.16);color:#c4b5fd;border:1px solid rgba(167,139,250,.4)">admin</span>`;
    if (r === 'cajero') return `<span class="rolebadge cajero">cajero</span>`;
    if (r === 'vendedor') return `<span class="rolebadge vend">vendedor</span>`;
    if (r) return `<span class="rolebadge alm">${r}</span>`;
    return '';
  }

  // Badge de estado PrintNode (11 diagnósticos, backend decide) — extraído para .printer.
  const _IMP_STATE_MAP = {
    ONLINE:          { cls: 'imp-on',       tx: 'online' },
    PC_OFFLINE:      { cls: 'imp-pc-off',   tx: 'PC apagada' },
    PRINTER_OFFLINE: { cls: 'imp-off',      tx: 'apagada' },
    SIN_PAPEL:       { cls: 'imp-warn',     tx: 'sin papel' },
    SIN_TINTA:       { cls: 'imp-warn',     tx: 'sin tinta' },
    ATASCO:          { cls: 'imp-err',      tx: 'atasco' },
    TAPA_ABIERTA:    { cls: 'imp-warn',     tx: 'tapa abierta' },
    PAUSED:          { cls: 'imp-paused',   tx: 'pausada' },
    DISABLED:        { cls: 'imp-disabled', tx: 'deshabilitada' },
    ERROR:           { cls: 'imp-err',      tx: 'error' },
    SIN_ID:          { cls: 'imp-noid',     tx: 'sin ID' },
    ID_INVALIDO:     { cls: 'imp-err',      tx: 'ID inválido' },
    UNKNOWN:         { cls: 'imp-noinfo',   tx: 'sin señal' }
  };
  function _impBadgeHTML(i) {
    if (!_impPNCargado) return '';
    const pnSt = _impPNEstado[String(i.printNodeId)];
    const st = (pnSt && pnSt.state) ? pnSt.state : (i.printNodeId ? 'UNKNOWN' : 'SIN_ID');
    const cfg = _IMP_STATE_MAP[st] || _IMP_STATE_MAP.UNKNOWN;
    const icon = (pnSt && pnSt.icon) || '❔';
    const reason = (pnSt && pnSt.reason) || cfg.tx;
    return `<span class="imp-estado ${cfg.cls}" title="${_escapeHtml(reason)}">${icon} ${cfg.tx}</span>`;
  }

  // ── Command bar: stats en vivo + buscador + filtro suspendidos ──
  function _cfgCmdBar() {
    const devs = cfgData.dispositivos || [];
    const activos = devs.filter(d => String(d.Estado).toUpperCase() === 'ACTIVO');
    const online = activos.filter(_dispEnLinea).length;
    const zonasN = (cfgData.zonas || []).filter(z => String(z.estado) === '1' || z.estado === 1).length;
    const estN = (cfgData.estaciones || []).filter(e => String(e.activo) === '1').length;
    return `<div class="cmd">
      <div class="stat"><span class="live-dot"${online ? '' : ' style="animation:none;background:#475569;box-shadow:none"'}></span><div><div class="big tnum" style="color:${online ? '#6ee7b7' : '#94a3b8'}">${online}</div><div class="cap">en línea</div></div></div>
      <div class="stat"><div><div class="big tnum">${activos.length}</div><div class="cap">dispositivos</div></div></div>
      <div class="stat"><div><div class="big tnum">${zonasN}</div><div class="cap">zonas</div></div></div>
      <div class="stat"><div><div class="big tnum">${estN}</div><div class="cap">estaciones</div></div></div>
      <div class="cmd-right">
        ${Object.keys(_presencia()).length ? '<span class="chip live" title="Canal Supabase Realtime activo: presencia al segundo"><span class="d" style="background:#10b981"></span>⚡ en vivo</span>' : ''}
        <input id="cfgSearchInp" class="search" placeholder="🔎 buscar equipo / persona…" value="${_escapeHtml(_cfgQ)}" oninput="MOS.cfgBuscar(this.value)">
        <button class="tbtn ${_cfgVerTodos ? 'on' : ''}" onclick="MOS.cfgToggleSusp()" title="Mostrar también suspendidos antiguos e inactivos">⏸ suspendidos</button>
      </div>
    </div>`;
  }

  function _cfgEyebrow(n, titulo) {
    return `<div class="eyebrow"><span class="n">${n}</span><h2>${titulo}</h2><span class="rule"></span></div>`;
  }

  // [Fix dueño] La actividad de PERSONAL_MASTER se queda vieja (Luis "hace 5h" estando EN el
  // panel). Verdad efectiva = lo más fresco entre su fila de personal y (a) su sesión viva en
  // este navegador, (b) el dispositivo más reciente donde figura su Ultima_Sesion.
  function _personaActEfectiva(p) {
    let act = _personaActividad(p.Ultima_Conexion || p.ultimaConexion);
    // (a) es el usuario logueado en ESTE panel → está en línea ahora mismo
    if (S.session && (String(S.session.idPersonal) === String(p.idPersonal) ||
        _normNombre(S.session.nombre) === _normNombre((p.nombre || '') + ' ' + (p.apellido || '')) ||
        _normNombre(S.session.nombre) === _normNombre(p.nombre))) {
      return { color: '#10b981', label: 'en línea · tú', dot: '🟢', minutos: 0 };
    }
    // (a2) su nombre está anunciado en el canal de PRESENCIA (tiempo real) → en línea al segundo
    const full = _normNombre((p.nombre || '') + ' ' + (p.apellido || ''));
    const solo = _normNombre(p.nombre);
    const pres = _presNombres();
    if (pres.includes(full) || pres.includes(solo)) {
      return { color: '#10b981', label: 'en línea', dot: '🟢', minutos: 0 };
    }
    // (b) dispositivo más fresco con su nombre en Ultima_Sesion
    (cfgData.dispositivos || []).forEach(d => {
      const n = _normNombre(d.Ultima_Sesion);
      if (!n || (n !== full && n !== solo)) return;
      const a2 = _dispActividad(d.Ultima_Conexion);
      if (a2.minutos < act.minutos) {
        act = (a2.minutos <= _CFG_ONLINE_MIN)
          ? { color: '#10b981', label: 'en línea', dot: '🟢', minutos: a2.minutos }
          : { color: a2.color, label: a2.label, dot: a2.dot, minutos: a2.minutos };
      }
    });
    return act;
  }

  // ── ucard: persona (admins/operadores) desplegable con acciones ──
  function _cfgUcardPersona(p, appOrigen, opts) {
    opts = opts || {};
    const act = _personaActEfectiva(p);
    const activo = String(p.estado) === '1';
    const safeId = String(p.idPersonal || '').replace(/'/g, '&#39;');
    const safeNombre = String(p.nombre || '').replace(/'/g, '&#39;');
    const ini = ((p.nombre || '?')[0] + (p.apellido || '')[0] || '').toUpperCase() || '?';
    const rolUp = String(p.rol || '').toUpperCase();
    const esAdmin = rolUp === 'MASTER' || rolUp === 'ADMIN' || rolUp === 'ADMINISTRADOR';
    // Última acción (solo admins, del audit cache)
    let ult = '';
    if ((esAdmin || opts.ascendido) && _personalAuditCache.length) {
      const propias = _personalAuditCache.filter(a => String(a.idPersonalAutoriza) === String(p.idPersonal));
      if (propias.length) {
        const u = propias[0];
        const f = u.fecha ? new Date(u.fecha) : null;
        const fmt = f ? f.toLocaleTimeString('es-PE', { hour: '2-digit', minute: '2-digit' }) : '';
        ult = ` · última: ${fmt} · ${u.accion || '—'}${u.refDocumento ? ' · ' + String(u.refDocumento).slice(0, 10) + '…' : ''}`;
      }
    }
    const subExtra = opts.ascendido
      ? ` · acceso_mos · rol real: <b>${String(p.rol || '').toLowerCase()}</b> (cobra como ${String(p.rol || '').toLowerCase()}) · también en Almacén ↑`
      : (p.montoBase ? ` · S/${parseFloat(p.montoBase).toFixed(2)}/día` : '');
    const key = 'u:' + safeId + (opts.ascendido ? ':vip' : '');
    const acciones = [
      !esAdmin ? `<span class="ubtn" onclick="MOS.abrirEspiaPorUsuario('${safeNombre}')">🕵️ espía</span>` : '',
      `<span class="ubtn" onclick="MOS.abrirModalEnviarPush('${safeId}','${safeNombre}')">💬 mensaje</span>`,
      `<span class="ubtn" onclick="MOS.cfgHistorialPersonal('${safeId}','${safeNombre}')">📜 historial</span>`,
      esAdmin ? `<span class="ubtn" onclick="MOS.abrirModalClaveGlobal('${safeId}')">🔑 permisos / clave</span>` : '',
      `<span class="ubtn" onclick="MOS.abrirModalHorarioCustom('${safeId}')">🕐 horario</span>`,
      `<span class="ubtn" onclick="MOS.abrirModalPersonal('${safeId}','${appOrigen}')">✏️ editar</span>`,
      opts.ascendido ? `<span class="ubtn danger" onclick="MOS.abrirModalPersonal('${safeId}','warehouseMos')">⬇ quitar acceso admin</span>` : '',
      `<label class="pers-switch" style="transform:scale(.8)" title="${activo ? 'Desactivar' : 'Activar'}"><input type="checkbox" ${activo ? 'checked' : ''} onchange="MOS.togglePersonalActivo('${safeId}','${appOrigen}', event)"><span class="pers-switch-slider"></span></label>`
    ].filter(Boolean).join('');
    return `<details class="ucard" ${_cfgIsOpen(key, false) ? 'open' : ''} ontoggle="MOS._cfgDetToggle('${key}',this.open)"><summary>
      <div class="uav" style="background:${p.color || _avatarGrad(p.nombre)}">${ini}</div>
      <div style="flex:1;min-width:0"><div class="uname">${p.nombre} ${p.apellido || ''} ${_rolebadge(p.rol, opts)}</div>
      <div class="usub" style="color:${act.color}">${act.dot} ${act.label}${subExtra}${ult}</div></div><span class="ucar">▾</span></summary>
      <div class="uactions">${acciones}</div></details>`;
  }

  // ── ucard: cajero/vendedor ME (por nombre) ──
  function _cfgUcardCajero(c, dispPorCajero, bloqMap) {
    const safeNombre = String(c.nombre || '').replace(/'/g, '&#39;');
    const disp = dispPorCajero[_normNombre(c.nombre)];
    const act = disp ? _personaActividad(disp.Ultima_Conexion) : { color: '#64748b', label: 'sin sesión', dot: '⚫', minutos: Infinity };
    const reg = bloqMap[_normNombre(c.nombre)];
    const bloqueado = !!(reg && reg.fechaBloqueo && !reg.unlockVigente);
    const ini = String(c.nombre || '?').split(/\s+/).map(s => s[0] || '').join('').slice(0, 2).toUpperCase();
    const monto = parseFloat(c.montoTotal) || 0;
    const dias = parseInt(c.diasPendientes) || 0;
    const aud = parseInt(c.diasAuditados) || 0;
    const lockBadge = bloqueado ? `<span class="rolebadge" style="background:rgba(239,68,68,.14);color:#fca5a5;border:1px solid rgba(239,68,68,.3)">🔒 bloqueado</span>` : '';
    const key = 'c:' + _normNombre(c.nombre);
    return `<details class="ucard" ${_cfgIsOpen(key, false) ? 'open' : ''} ontoggle="MOS._cfgDetToggle('${key}',this.open)"><summary>
      <div class="uav" style="background:${bloqueado ? '#3a4560' : _avatarGrad(c.nombre)}">${ini}</div>
      <div style="flex:1;min-width:0"><div class="uname">${c.nombre} ${_rolebadge(c.rol || 'cajero')} ${lockBadge}</div>
      <div class="usub" style="color:${act.color}">${act.dot} ${act.label} · ${aud}/${dias || '—'} aud · S/${monto.toFixed(2)} semana</div></div><span class="ucar">▾</span></summary>
      <div class="uactions">
        <span class="ubtn" onclick="MOS.abrirEspiaPorUsuario('${safeNombre}')">🕵️ espía</span>
        <span class="ubtn" onclick="MOS.abrirModalEnviarPush('','${safeNombre}')">💬 mensaje</span>
        <label class="pers-switch" style="transform:scale(.8)" title="${bloqueado ? 'Activar (quita candado)' : 'Bloquear (pantalla candado)'}"><input type="checkbox" ${bloqueado ? '' : 'checked'} onchange="MOS.toggleVendedorME('${safeNombre}', event)"><span class="pers-switch-slider"></span></label>
      </div></details>`;
  }

  // ── 👥 usuarios de una zona (fusión Personal) ──
  function _cfgUsersZona(z) {
    const esAlm = _esZonaAlmacen(z);
    let cards = [], n = 0, online = 0, addLabel, addApp;
    const qMatch = nom => !_cfgQ || _normNombre(nom).includes(_cfgQ);
    if (esAlm) {
      const ops = (cfgData.personal || []).filter(p => String(p.rol || '').toUpperCase() !== 'SUPERVISOR').filter(p => qMatch((p.nombre || '') + ' ' + (p.apellido || '')));
      n = ops.length;
      online = ops.filter(p => _personaActEfectiva(p).minutos <= _CFG_ONLINE_MIN).length;
      cards = ops.map(p => _cfgUcardPersona(p, 'warehouseMos'));
      addLabel = '＋ agregar almacenero / envasador'; addApp = 'warehouseMos';
    } else {
      const { grupos, dispPorCajero, bloqMap } = _cfgCajerosData();
      // Ultima_Zona del dispositivo puede traer el ID ("ZONA-02") o el NOMBRE ("Zona 02") → matchear ambos
      const kZona = Object.keys(grupos).find(k => {
        const kn = _normNombre(k);
        return kn === _normNombre(z.idZona) || kn === _normNombre(z.nombre);
      });
      const lista = (kZona ? grupos[kZona] : []).filter(c => qMatch(c.nombre));
      n = lista.length;
      online = lista.filter(c => { const d = dispPorCajero[_normNombre(c.nombre)]; return d && _dispEnLinea(d); }).length;
      cards = lista.map(c => _cfgUcardCajero(c, dispPorCajero, bloqMap));
      addLabel = '＋ agregar cajero / vendedor'; addApp = 'mosExpress';
    }
    const key = 'z:' + z.idZona;
    return `<details class="users" ${_cfgIsOpen(key, online > 0) ? 'open' : ''} ontoggle="MOS._cfgDetToggle('${key}',this.open)">
      <summary><span class="uic">👥</span>Usuarios de la zona <span class="cnt">${n}${online ? ` · ${online} en línea` : ''} ▾</span></summary>
      ${cards.join('')}
      <div class="add-row" style="margin:9px 13px 12px" onclick="MOS.abrirModalPersonal(null,'${addApp}')">${addLabel}</div>
    </details>`;
  }

  // ── serie chips (.schip) de una zona — Almacén NO factura ──
  function _cfgSeriesZona(z, estZona) {
    if (_esZonaAlmacen(z)) return '';
    const TIPOS = [{ t: 'NOTA_VENTA', ic: '📋' }, { t: 'BOLETA', ic: '🧾' }, { t: 'FACTURA', ic: '🧮' }];
    const series = (cfgData.series || []).filter(s => s.idZona === z.idZona);
    const chips = TIPOS.map(tp => {
      const st = series.filter(s => s.tipoDocumento === tp.t);
      if (!st.length) return `<span class="schip add" onclick="MOS.abrirModalSerieZona('${z.idZona}','${tp.t}')">${tp.ic} + ${tp.t.toLowerCase().replace('_', ' ')}</span>`;
      const nombres = [...new Set(st.map(s => s.serie))];
      const nombreShow = nombres.length > 1 ? '⚠ ' + nombres.join('/') : nombres[0];
      const corr = Math.max(...st.map(s => parseInt(s.correlativo, 10) || 0));
      const pausada = !st.every(s => String(s.activo) === '1');
      return `<span class="schip" onclick="MOS.abrirModalSerieZona('${z.idZona}','${tp.t}',true)" style="cursor:pointer${pausada ? ';opacity:.55' : ''}"><span class="ic">${tp.ic}</span><span class="tt">${nombreShow}</span><span class="cc">corr ${corr}${pausada ? ' · ⏸' : ''}</span></span>`;
    }).join('');
    return `<div class="srow"><span class="slab">📄 Series DCPE</span>${chips}</div>`;
  }

  // ── política chips (.pchip) — POS desde politicaJSON · Almacén editable inline ──
  function _cfgPoliticaZona(z) {
    const app = _zonaAppKey(z);
    const hoy = _horarioHoyTxt(app);
    const horChip = `<span class="pchip" style="cursor:pointer" onclick="MOS.abrirModalHorarioApp('${app}')" title="Horario de la app · toca para editar"><span>🕐</span><div><div class="pv">${hoy || '—'}</div><div class="pl">Horario</div></div></span>`;
    if (_esZonaAlmacen(z)) {
      const cfg = cfgData.config || {};
      // [Verdad efectiva] El chip muestra el valor QUE USA el cálculo (SQL 120/93: _cfg_num(clave, default)):
      // CONFIG_MOS manda; si la clave está vacía, rige el default de fábrica → se marca "def".
      const mk = (icon, key, raw, disp, lbl, unidad, esDef, titulo) => `<span class="pchip meta-chip" style="cursor:pointer" data-meta-key="${key}" data-meta-valor="${raw}" onclick="MOS.editarMetaChip('${key}', this)" title="${titulo || 'Click para editar'}"><span>${icon}</span><div><div class="pv">${disp !== '' ? disp : '—'}${esDef ? ' <span style="font-size:8px;color:#f5b849;font-weight:700">def</span>' : ''}</div><div class="pl">${lbl} <span class="pu">${unidad}</span></div></div></span>`;
      const rawT = cfg.evalTarifaEnvasadoPorUnidad != null ? String(cfg.evalTarifaEnvasadoPorUnidad) : '';
      const tieneT = rawT !== '' && !isNaN(parseFloat(rawT));
      const dispT = 'S/' + parseFloat(tieneT ? rawT : '0.10').toFixed(2); // default SQL: 0.10
      const rawA = String(cfg.evalMetaAuditorias || '');
      const dispA = rawA !== '' ? rawA : '30'; // default SQL: 30
      return `<div class="srow"><span class="slab">🎯 Política</span>
        ${mk('💵', 'evalTarifaEnvasadoPorUnidad', rawT, dispT, 'Envasado', '/und', !tieneT, 'Pago del envasador = unidades × esta tarifa (SQL _cfg_num, default 0.10) · click para editar')}
        ${mk('📦', 'evalMetaAlmacenero', cfg.evalMetaAlmacenero || '', cfg.evalMetaAlmacenero || '', 'Guías', '/día', false, 'Meta informativa de guías: NO entra al pago ni al score (paritario GAS/Supabase) · click para fijarla')}
        ${mk('📋', 'evalMetaAuditorias', rawA, dispA, 'Auditorías', '/día', rawA === '', 'Meta de auditorías del score (SQL _cfg_num, default 30) · click para editar')}
        ${horChip}</div>`;
    }
    let pol = {};
    try { pol = z.politicaJSON ? (typeof z.politicaJSON === 'string' ? JSON.parse(z.politicaJSON) : z.politicaJSON) : {}; } catch (_) {}
    const meta = parseFloat(pol.metaDiaria), pct = parseFloat(pol.comisionExcedentePct), aud = parseFloat(pol.metaAuditorias);
    // [846] La base diaria por rol la paga LA ZONA. Antes salía de un "usuario genérico" (el sueldo
    // más alto de cualquier otra persona con el mismo rol), un solo número para las dos zonas.
    const bCaj = parseFloat(pol.baseCajero), bVen = parseFloat(pol.baseVendedor);
    const mkz = (icon, val, lbl, unidad, tip) => `<span class="pchip" style="cursor:pointer" onclick="MOS.abrirModalZona('${z.idZona}')" title="${_escapeHtml(tip || 'Editar en la zona')}"><span>${icon}</span><div><div class="pv">${val}</div><div class="pl">${lbl}${unidad ? ` <span class="pu">${unidad}</span>` : ''}</div></div></span>`;
    const tipBase = r => 'Base diaria que esta zona paga a cada ' + r + '. Al cambiarla, las liquidaciones PENDIENTES desde la fecha de vigencia se recalculan solas; los días ya pagados no se tocan.';
    return `<div class="srow"><span class="slab">🎯 Política</span>
      ${mkz('💰', (!isNaN(meta) && meta > 0) ? 'S/' + meta.toFixed(0) : '—', 'Meta', '/día')}
      ${mkz('🎯', (!isNaN(pct) && pct >= 0) ? pct + '%' : '—', 'Comisión', '')}
      ${mkz('👤', (!isNaN(bCaj) && bCaj >= 0) ? 'S/' + _money(bCaj).toFixed(0) : '—', 'Base cajero', '/día', tipBase('cajero'))}
      ${mkz('🛒', (!isNaN(bVen) && bVen >= 0) ? 'S/' + _money(bVen).toFixed(0) : '—', 'Base vendedor', '/día', tipBase('vendedor'))}
      ${mkz('📋', (!isNaN(aud) && aud > 0) ? String(aud) : '—', 'Auditorías', '/día')}
      ${horChip}</div>`;
  }

  // ── estación (.station) con impresoras y fleet dibujado ──
  function _cfgStation(e, impresoras) {
    const activa = String(e.activo) === '1' || e.activo === 1 || e.activo === true;
    const imps = impresoras.filter(i => i.idEstacion === e.idEstacion);
    const tipoIcon = { CAJA: '🛒', ALMACEN: '🏭', ENVASADO: '🍶' }[e.tipo] || '📍';
    const appb = e.appOrigen === 'mosExpress' ? '<span class="appb me">ME</span>' : '<span class="appb wh">WH</span>';
    const safeId = String(e.idEstacion).replace(/'/g, '&#39;');
    const online = _dispOnlineEnEstacion(e.idEstacion) > 0;

    const impsHTML = imps.length ? imps.map(i => {
      const impActiva = String(i.activo) === '1' || i.activo === 1 || i.activo === true;
      const impIcon = { TICKET: '🖨️', ADHESIVO: '🏷️', ZPL: '📄' }[i.tipo] || '🖨️';
      const pnSt = _impPNEstado[String(i.printNodeId)];
      return `<div class="printer${impActiva ? '' : '" style="opacity:.5'}">
        <span class="pic">${impIcon}</span>
        <div style="flex:1;min-width:0"><div class="pn">${i.nombre} ${_impBadgeHTML(i)}</div>
        <div class="pmeta">PN ${i.printNodeId || '—'} · ${i.tipo}${pnSt && pnSt.computer ? ' · ' + pnSt.computer : ''}</div></div>
        <label class="pers-switch" style="transform:scale(.68)" onclick="event.stopPropagation()" title="${impActiva ? 'Desactivar' : 'Activar'}"><input type="checkbox" ${impActiva ? 'checked' : ''} onchange="MOS.toggleImpresoraActiva('${i.idImpresora}', event)"><span class="pers-switch-slider"></span></label>
        <span class="iconbtn" style="width:22px;height:22px;font-size:10px" onclick="MOS.abrirModalImpresora('${i.idImpresora}')">✏️</span>
      </div>`;
    }).join('') : `<div class="pmeta" style="color:#f5b849;padding:4px 2px">⚠ sin impresoras</div>`;

    const fleetDevs = _fleetDe(_dispEnEstacion(e.idEstacion));
    const fleetHTML = fleetDevs.length
      ? `<div class="assigned-h">📱 equipos en esta estación</div><div class="fleet">${fleetDevs.map(d => _dispDrawn(d)).join('')}</div>`
      : `<div class="assigned-h">📱 equipos</div><div class="fleet"><div class="addstat" style="width:132px;min-height:90px"><span class="plus">＋</span>sin equipos hoy</div></div>`;

    // Trail fantasma (se mudó de estación hace <5s) — feature viva, se conserva
    const fantasmas = _dispFantasmasDeEstacion(e.idEstacion);
    const fantasmaHTML = fantasmas.length ? `<div class="pmeta disp-fantasma" style="margin-top:6px;border:1px dashed rgba(99,102,241,.4);border-radius:8px;padding:5px 8px">${fantasmas.map(f => { const dest = (cfgData.estaciones || []).find(es => es.idEstacion === f.hacia); return `${f.ico} ${f.nombre} → <b style="color:#a5b4fc">${dest?.nombre || '…'}</b>`; }).join('<br>')}</div>` : '';

    return `<div class="station${online && activa ? ' online' : ''}${activa ? '' : '" style="opacity:.6'}">
      <div class="st-head"><span class="sic">${tipoIcon}</span>
        <div style="flex:1;min-width:0"><div class="snm">${e.nombre} ${appb}</div><div class="sid">${e.idEstacion}</div></div>
        <label class="pers-switch" style="transform:scale(.8)" onclick="event.stopPropagation()" title="${activa ? 'Desactivar estación' : 'Activar estación'}"><input type="checkbox" ${activa ? 'checked' : ''} onchange="MOS.toggleEstacionActiva('${safeId}', event)"><span class="pers-switch-slider"></span></label>
        <span class="iconbtn" onclick="MOS.abrirModalEstacion('${safeId}')">✏️</span></div>
      ${impsHTML}
      <span class="addln" onclick="MOS.abrirModalImpresora(null,'${safeId}')">+ impresora</span>
      ${fleetHTML}
      ${fantasmaHTML}
    </div>`;
  }

  // ── zona completa (.zone) ──
  function _cfgZona(z, estaciones, impresoras) {
    const estZona = estaciones.filter(e => e.idZona === z.idZona);
    const totalImp = impresoras.filter(i => estZona.some(e => e.idEstacion === i.idEstacion)).length;
    const zonaActiva = String(z.estado) === '1' || z.estado === 1;
    const online = estZona.reduce((a, e) => a + _dispOnlineEnEstacion(e.idEstacion), 0);
    const esAlm = _esZonaAlmacen(z);
    const app = _zonaAppKey(z);
    const appChip = esAlm ? `<span class="chip appwh">🏭 warehouseMos</span>` : `<span class="chip appme">🛒 MosExpress</span>`;
    const hoy = _horarioHoyTxt(app);
    const horChip = `<span class="chip hor" style="cursor:pointer" onclick="MOS.abrirModalHorarioApp('${app}')">🕐 ${hoy || 'horario'}</span>`;
    const liveChip = online ? `<span class="chip live"><span class="d" style="background:#10b981"></span>${online} en línea</span>` : '';
    const estsHTML = estZona.length
      ? `<div class="stations">${estZona.map(e => _cfgStation(e, impresoras)).join('')}</div>`
      : `<div class="pmeta" style="text-align:center;padding:14px;font-style:italic">Esta zona no tiene estaciones aún.</div>`;
    return `<div class="zone${online && zonaActiva ? ' online' : ''}${zonaActiva ? '' : ' dim'}">
      <div class="zhead"><div class="zbadge${esAlm ? ' wh' : ''}">${esAlm ? '🏭' : '🏬'}</div>
        <div class="zt"><div class="row1"><h3>${z.nombre}</h3>${liveChip}${appChip}${horChip}<span class="zid">${z.idZona}</span></div>
        <div class="zmeta">${estZona.length} estación${estZona.length === 1 ? '' : 'es'} · ${totalImp} impresora${totalImp === 1 ? '' : 's'}${z.responsable ? ' · resp. ' + z.responsable : ''}${z.direccion ? ' · 📍 ' + z.direccion : ''}</div></div>
        <div class="zctl"><label class="pers-switch" title="${zonaActiva ? 'Desactivar zona' : 'Activar zona'}" onclick="event.stopPropagation()"><input type="checkbox" ${zonaActiva ? 'checked' : ''} onchange="MOS.toggleZonaActiva('${z.idZona}', event)"><span class="pers-switch-slider"></span></label>
        <span class="iconbtn" onclick="MOS.abrirModalZona('${z.idZona}')">✏️</span></div></div>
      ${_cfgSeriesZona(z, estZona)}
      ${_cfgPoliticaZona(z)}
      ${estsHTML}
      ${_cfgUsersZona(z)}
      <span class="addln" style="margin-top:12px" onclick="MOS.abrirModalEstacion(null,'${z.idZona}')">+ estación a esta zona</span>
    </div>`;
  }

  // ── cajeros SIN zona asignada (bloqueados / sin sesión) — sección del mockup ──
  // [635] ⏸ Suspendidos (≤7 días) — fuera de TODAS las zonas, con su duración y reactivar.
  function _cfgSuspendidos() {
    const susp = _dispSuspendidosFrescos().filter(d => !_cfgQ || (String(d.Nombre_Equipo || '') + String(d.Ultima_Sesion || '')).toLowerCase().includes(_cfgQ));
    if (!susp.length) return '';
    const rows = susp.map(d => {
      const idAttr = String(d.ID_Dispositivo).replace(/'/g, '&#39;');
      const t = _dispSuspTxt(d) || _fmtHace(d.Ultima_Conexion).replace('hace ', '');
      return `<div class="printer" style="border-left:3px solid #f97316">
        <span class="pic" style="filter:grayscale(.35)">${_dispIcono(d.Nombre_Equipo)}</span>
        <div style="flex:1;min-width:0"><div class="pn">${d.Nombre_Equipo || 'Dispositivo'} ${_appBadge(d.App)}</div>
        <div class="pmeta" style="color:#fb923c">⏸ suspendido ${t ? 'hace ' + t : ''}${d.Ultima_Sesion ? ' · 👤 último: ' + d.Ultima_Sesion : ''}</div></div>
        <span class="act ghost" style="color:#34d399;border-color:#065f46" onclick="MOS.aprobarDispositivo('${idAttr}')">↺ Reactivar</span>
      </div>`;
    }).join('');
    return _cfgEyebrow('⏸', 'Suspendidos (2 días sin conectar · a los 7 pasan a Archivados)') + `<div class="pend">${rows}</div>`;
  }

  // [636] 🛵 Zona GO (MosGo) — MISMO lenguaje visual que las demás zonas (cards de
  // dispositivo dibujadas con halo/avatar/botonera vía _dispDrawn), en identidad violeta.
  function _cfgZonaGo() {
    // [805] La zona MosGo SIEMPRE existe (aunque no tenga equipos) — es una zona fija del negocio.
    // Antes desaparecía sin equipos (return ''), lo que confundía ("¿dónde está MosGo?").
    const devs = _fleetDe((cfgData.dispositivos || []).filter(d => String(d.App || '').toLowerCase() === 'mosgo'));
    const online = devs.filter(_dispEnLinea).length;
    const liveChip = online ? `<span class="chip live"><span class="d" style="background:#10b981"></span>${online} en línea</span>` : '';
    const cuerpo = devs.length
      ? `<div class="fleet">${devs.map(d => _dispDrawn(d)).join('')}</div>`
      : `<div class="callout" style="margin-top:12px;background:rgba(110,86,207,.08);border:1px dashed rgba(143,122,255,.35);color:#c4b5fd">Aún no hay equipos de MosGo en ruta. Cuando un equipo entre con la app MosGo, aparecerá aquí.</div>`;
    const meta = devs.length
      ? `${devs.length} equipo${devs.length === 1 ? '' : 's'} de preventa · venden contra stock de ALMACÉN · solo admins`
      : `Zona de preventa en ruta · venden contra stock de ALMACÉN · solo admins`;
    return `<div class="zone${online ? ' online' : ''}" style="border-color:rgba(143,122,255,.45);background:linear-gradient(160deg,rgba(110,86,207,.10),transparent 55%)">
      <div class="zhead"><div class="zbadge" style="background:linear-gradient(135deg,#6e56cf,#8f7aff)">🛵</div>
        <div class="zt"><div class="row1"><h3 style="color:#c4b5fd">MosGo · Ruta</h3>${liveChip}<span class="chip" style="background:rgba(110,86,207,.18);border-color:#8f7aff;color:#c4b5fd">🛵 MosGo</span><span class="zid">ZONA-GO</span></div>
        <div class="zmeta">${meta}</div></div>
      </div>
      ${cuerpo}
    </div>`;
  }

  function _cfgSinZona() {
    const { grupos, dispPorCajero, bloqMap } = _cfgCajerosData();
    const zonasNorm = (cfgData.zonas || []).flatMap(z => [_normNombre(z.idZona), _normNombre(z.nombre)]);
    const sueltos = Object.keys(grupos)
      .filter(k => k === '__SIN_ZONA__' || !zonasNorm.includes(_normNombre(k)))
      .flatMap(k => grupos[k])
      .filter(c => !_cfgQ || _normNombre(c.nombre).includes(_cfgQ));
    if (!sueltos.length) return '';
    return `<details class="users" ${_cfgIsOpen('z:__SINZONA__', false) ? 'open' : ''} ontoggle="MOS._cfgDetToggle('z:__SINZONA__',this.open)" style="margin-top:14px;border-style:dashed">
      <summary><span class="uic">🌫</span>Cajeros sin zona asignada <span class="cnt">${sueltos.length} · bloqueados / sin sesión ▾</span></summary>
      ${sueltos.map(c => _cfgUcardCajero(c, dispPorCajero, bloqMap)).join('')}
    </details>`;
  }

  // ── pendientes de aprobación (.pend) ──
  function _cfgPend() {
    // [635 · decisión dueño] Sección A agrupada por TIPO de solicitud, ambas con TTL 1 h:
    //   📱 acceso de dispositivo (UUID) · 🕐 extensión de horario. Cada fila dice hace
    //   cuánto se pidió y, si el equipo venía suspendido, hace cuánto lo estaba.
    const pendientes = _dispPendientes().filter(d => !_cfgQ || (String(d.Nombre_Equipo || '') + String(d.Ultima_Sesion || '')).toLowerCase().includes(_cfgQ));
    const horario = (cfgData.alertasHorario || []).filter(a =>
      String(a.estado || '').toUpperCase() === 'PENDIENTE'
      && (Date.now() - (Date.parse(a.fecha || '') || 0)) <= 3600e3
      && (!_cfgQ || String(a.descripcion || '').toLowerCase().includes(_cfgQ)));
    if (!pendientes.length && !horario.length) return '';

    const rowsDisp = pendientes.map(d => {
      const idAttr = String(d.ID_Dispositivo).replace(/'/g, '&#39;');
      const appL = String(d.App || '').toLowerCase();
      const appTxt = appL.indexOf('warehouse') >= 0 ? 'warehouseMos' : (appL === 'mos' ? 'MOS' : (appL === 'mosgo' ? 'MosGo 🛵' : 'mosExpress'));
      const hace = _fmtHace(d.Pendiente_Desde || d.Ultima_Conexion);
      const susp = _dispSuspTxt(d);
      return `<div class="pend-row" data-pend-card="${idAttr}">
        <div class="devt phone susp" style="transform:scale(.55);margin:-22px -10px -22px -14px"><div class="face"><div class="avatar" style="background:#4a5a75">${(d.Ultima_Sesion || d.Nombre_Equipo || '?')[0].toUpperCase()}</div></div></div>
        <div style="flex:1;min-width:0"><div class="nm">${d.Nombre_Equipo || 'Dispositivo nuevo'}</div>
          <div class="mt">nº ${String(d.ID_Dispositivo).slice(0, 8)} · ${appTxt}${hace ? ' · 📨 ' + hace : ''}</div>
          <div class="rq">👤 solicita: ${d.Ultima_Sesion || 'sin identificar'}${susp ? ` · <span style="color:#fb923c">⏸ venía suspendido ${susp}</span>` : ''}</div></div>
        <span class="act ok" onclick="MOS.aprobarDispositivo('${idAttr}')">✓ Aprobar</span>
        <span class="act ghost" onclick="MOS.aprobarDispositivoConNombre('${idAttr}')" title="Renombrar antes de aprobar">✎</span>
        <span class="act warn" onclick="MOS.rechazarDispositivo('${idAttr}')">✕</span>
      </div>`;
    }).join('');

    const rowsHor = horario.map(a => {
      const idAttr = String(a.idAlerta).replace(/'/g, '&#39;');
      const susp = (() => {
        const dev = (cfgData.dispositivos || []).find(d => d.ID_Dispositivo === a.idDispositivo);
        return dev ? _dispSuspTxt(dev) : '';
      })();
      return `<div class="pend-row" data-pend-card="${idAttr}" style="border-left:3px solid #f5b849">
        <span style="font-size:20px;margin:0 4px">🕐</span>
        <div style="flex:1;min-width:0"><div class="nm">Extensión de horario · 1 h</div>
          <div class="mt">📨 ${_fmtHace(a.fecha) || 'ahora'}${a.idDispositivo ? ' · nº ' + String(a.idDispositivo).slice(0, 8) : ''}${susp ? ` · <span style="color:#fb923c">⏸ venía suspendido ${susp}</span>` : ''}</div>
          <div class="rq" style="white-space:normal">${_escapeHtml(String(a.descripcion || '').slice(0, 160))}</div></div>
        <span class="act ok" onclick="MOS.aprobarExtHorario('${idAttr}')">✓ Dar 1 h</span>
        <span class="act warn" onclick="MOS.rechazarExtHorario('${idAttr}')">✕</span>
      </div>`;
    }).join('');

    const sub = (ic, txt, n) => `<div style="font-size:10.5px;font-weight:800;letter-spacing:.7px;text-transform:uppercase;color:#93a4c2;margin:10px 2px 4px;display:flex;align-items:center;gap:6px">${ic} ${txt} <span style="opacity:.6">(${n})</span></div>`;
    return _cfgEyebrow('A', 'Solicitudes de permiso · vencen a la hora') + `<div class="pend">
      ${pendientes.length ? sub('📱', 'Acceso de dispositivo (UUID)', pendientes.length) + rowsDisp : ''}
      ${horario.length ? sub('🕐', 'Extensión de horario', horario.length) + rowsHor : ''}
    </div>`;
  }

  // [635] aprobar/rechazar extensión de horario desde Infraestructura
  async function aprobarExtHorario(idAlerta) {
    try {
      await API.post('aprobarExtensionHorario', { idAlerta });
      toast('✅ Extensión de 1 h concedida', 'ok');
    } catch (e) { toast('⚠ ' + (e.message || e), 'error'); }
    cfgData.alertasHorario = (cfgData.alertasHorario || []).filter(a => a.idAlerta !== idAlerta);
    renderInfra();
  }
  async function rechazarExtHorario(idAlerta) {
    try {
      await API.post('rechazarExtensionHorario', { idAlerta });
      toast('⛔ Extensión rechazada', 'ok');
    } catch (e) { toast('⚠ ' + (e.message || e), 'error'); }
    cfgData.alertasHorario = (cfgData.alertasHorario || []).filter(a => a.idAlerta !== idAlerta);
    renderInfra();
  }

  // ── ciclo de vida (informativo, del mockup) ──
  function _cfgLife() {
    return `${_cfgEyebrow('C', 'Ciclo de vida + archivado')}
    <div class="life"><div class="flow">
      <div class="step"><div class="db" style="background:#10b981;box-shadow:0 0 10px rgba(16,185,129,.55)"></div><h4>En línea</h4><div class="whh">&lt;5 min</div><p>Opera ahora. Brillo verde + quién está.</p></div>
      <div class="step"><div class="db" style="background:#f5b849"></div><h4>Inactivo</h4><div class="whh">&lt;2 días</div><p>Chip "último: X · hace Yh". Visible.</p></div>
      <div class="step"><div class="db" style="background:#f97316"></div><h4>Suspendido</h4><div class="whh">2 días →</div><p>Sale de TODAS las zonas → vive en ⏸ Suspendidos con su duración. Reactivable 1 toque.</p></div>
      <div class="step"><div class="db" style="background:#64748b"></div><h4>Archivado</h4><div class="whh">7 días →</div><p>Sigue suspendido, pero lejos: vive en 🗄️ Archivados con su duración.</p></div>
    </div><div class="lifenote">🔑 <b>Archivado ≠ bloqueado.</b> El equipo real reconecta y vuelve a pedir acceso solo; el abandonado queda archivado sin ensuciar la vista.</div></div>`;
  }

  // ── archivados (.arch): INACTIVO + CANCELADO* + SUSPENDIDO>7d ──
  function _cfgArch() {
    const arch = _dispArchivados().filter(d => !_cfgQ || (String(d.Nombre_Equipo || '') + String(d.Ultima_Sesion || '')).toLowerCase().includes(_cfgQ));
    if (!arch.length) return '';
    const rows = arch.map(d => {
      const idAttr = String(d.ID_Dispositivo).replace(/'/g, '&#39;');
      const act = _dispActividad(d.Ultima_Conexion);
      const _suspT = /^(SUSPENDIDO|CANCELADO)/.test(String(d.Estado || '').toUpperCase()) ? _dispSuspTxt(d) : '';
      return `<div class="printer" style="opacity:.8">
        <span class="pic" style="filter:grayscale(.6)">${_dispIcono(d.Nombre_Equipo)}</span>
        <div style="flex:1;min-width:0"><div class="pn">${d.Nombre_Equipo || 'Dispositivo'} ${_appBadge(d.App)}</div>
        <div class="pmeta" style="color:${act.color}">${act.dot} ${act.label}${_suspT ? ' · <span style="color:#fb923c">⏸ suspendido hace ' + _suspT + '</span>' : ''}${d.Ultima_Sesion ? ' · 👤 ' + d.Ultima_Sesion : ''}</div></div>
        <span class="act ghost" style="color:#34d399;border-color:#065f46" onclick="MOS.aprobarDispositivo('${idAttr}')">↺ Reactivar</span>
      </div>`;
    }).join('');
    return `<details class="arch" ${_cfgIsOpen('arch', false) ? 'open' : ''} ontoggle="MOS._cfgDetToggle('arch',this.open)">
      <summary>🗄️ Archivados <span class="muted" style="font-weight:400">· sin conectar +7 días · reversibles</span> <span class="cnt">${arch.length} ▾</span></summary>
      <div style="display:flex;flex-direction:column;gap:6px;margin-top:10px">${rows}</div>
    </details>`;
  }

  function renderInfra() {
    const cont = $('infraContenedor');
    if (!cont) return;
    // Horarios para los chips (cache 5min); tras poblar, la condición es falsa → no re-loop.
    if (!S._horariosAppsCache) {
      _cargarHorariosApps(false).then(() => { if (S.cfgTab === 'infra') renderInfra(); }).catch(() => {});
    }
    const zonas = cfgData.zonas || [];
    const estaciones = cfgData.estaciones || [];
    const impresoras = cfgData.impresoras || [];
    const zonasHTML = zonas.length
      ? _cfgEyebrow('B', 'Zonas · estaciones · impresoras · equipos') + zonas.map(z => _cfgZona(z, estaciones, impresoras)).join('')
      : '';
    cont.innerHTML =
      _cfgCmdBar() +
      _cfgPend() +
      _cfgZonaVip() +
      _cfgZonaGo() +
      zonasHTML +
      _cfgSuspendidos() +
      _cfgSinZona() +
      `<span class="addln" style="margin-top:14px;padding:13px;font-size:12px" onclick="MOS.abrirModalZona(null)">🏬 + agregar nueva zona</span>` +
      _cfgLife() +
      _cfgArch();
    _dispActualizarMapa();
    // [636 · háptico] tap en cards de dispositivo / botoneras / toggles → vibración suave
    // (Android; iOS la ignora sin romper). Un solo listener delegado, pasivo.
    if (!cont._hapticsOn) {
      cont._hapticsOn = true;
      cont.addEventListener('pointerdown', (ev) => {
        if (ev.target.closest && ev.target.closest('.mbtn,.devt,.act,.iconbtn,.ubtn,.pers-switch')) {
          try { navigator.vibrate && navigator.vibrate(10); } catch (_) {}
        }
      }, { passive: true });
      // [637 · espacio del MASTER] spotlight + tilt 3D siguiendo el puntero (solo PC:
      // hover real). Delegado y pasivo — un listener para toda la flota.
      if (window.matchMedia && matchMedia('(hover:hover)').matches) {
        cont.addEventListener('pointermove', (ev) => {
          const card = ev.target.closest && ev.target.closest('.devt');
          if (!card) return;
          const r = card.getBoundingClientRect();
          if (!r.width || !r.height) return;
          const px = (ev.clientX - r.left) / r.width, py = (ev.clientY - r.top) / r.height;
          card.style.setProperty('--mx', (px * 100).toFixed(1) + '%');
          card.style.setProperty('--my', (py * 100).toFixed(1) + '%');
          card.style.setProperty('--ry', ((px - 0.5) * 12).toFixed(2) + 'deg');   // [684] ±6°: visible sin lupa
          card.style.setProperty('--rx', ((0.5 - py) * 12).toFixed(2) + 'deg');
        }, { passive: true });
        cont.addEventListener('pointerout', (ev) => {
          const card = ev.target.closest && ev.target.closest('.devt');
          if (card) { card.style.removeProperty('--rx'); card.style.removeProperty('--ry'); }
        }, { passive: true });
      }
    }
  }

  // ════════════════════════════════════════════════════════════
  // ZONA VIP · Panel MOS (Admins & Master) — fiel al mockup
  // ════════════════════════════════════════════════════════════
  function _isAppMOS(d) {
    const a = String(d.App || '').toLowerCase();
    return a === 'mos';
  }

  function _cfgZonaVip() {
    const dispMOS = (cfgData.dispositivos || []).filter(_isAppMOS);
    const activos = dispMOS.filter(d => String(d.Estado).toUpperCase() === 'ACTIVO');
    const onlineNow = activos.filter(_dispEnLinea).length;
    const visibles = _fleetDe(dispMOS);
    const ocultos = dispMOS.filter(d => !_dispVisibleFleet(d) && String(d.Estado).toUpperCase() !== 'PENDIENTE_APROBACION').length;

    // Series CPE que emite el panel (BOLETA/FACTURA compartidas con las zonas POS)
    const nombresB = [...new Set((cfgData.series || []).filter(s => s.tipoDocumento === 'BOLETA').map(s => s.serie))];
    const nombresF = [...new Set((cfgData.series || []).filter(s => s.tipoDocumento === 'FACTURA').map(s => s.serie))];
    const serieChip = (ic, noms, lbl) => noms.length ? `<span class="schip"><span class="ic">${ic}</span><span class="tt">${noms.join('/')}</span><span class="cc">${lbl}</span></span>` : '';
    const seriesRow = (nombresB.length || nombresF.length)
      ? `<div class="srow"><span class="slab">📄 Series DCPE · VIP</span>${serieChip('🧾', nombresB, 'boleta')}${serieChip('🧮', nombresF, 'factura')}<span class="chip occ" style="border-style:dashed">compartida con zonas</span></div>`
      : '';

    const fleetHTML = visibles.length
      ? `<div class="fleet">${visibles.map(d => _dispDrawn(d)).join('')}</div>`
      : `<div class="pmeta" style="padding:8px 2px">Sin equipos en línea ahora.</div>`;

    // Admins reales + ascendidos (accesoMos) del personal WH
    const adminsMOS = (cfgData.personalMOS || []).filter(p => {
      const r = String(p.rol || '').toUpperCase();
      return r === 'MASTER' || r === 'ADMIN' || r === 'ADMINISTRADOR';
    });
    const ascendidos = (cfgData.personal || []).filter(p => p.accesoMos === true || p.accesoMos === '1' || p.accesoMos === 1);
    const nAdm = adminsMOS.length + ascendidos.length;
    const onlineAdm = adminsMOS.concat(ascendidos).filter(p => _personaActEfectiva(p).minutos <= _CFG_ONLINE_MIN).length;
    const ucards = adminsMOS.filter(p => !_cfgQ || _normNombre((p.nombre || '') + ' ' + (p.apellido || '')).includes(_cfgQ)).map(p => _cfgUcardPersona(p, 'MOS'))
      .concat(ascendidos.filter(p => !_cfgQ || _normNombre((p.nombre || '') + ' ' + (p.apellido || '')).includes(_cfgQ)).map(p => _cfgUcardPersona(p, 'warehouseMos', { ascendido: true })));
    const adminsBlock = `<details class="users" ${_cfgIsOpen('z:__VIP__', true) ? 'open' : ''} ontoggle="MOS._cfgDetToggle('z:__VIP__',this.open)" style="border-color:rgba(245,184,73,.3)">
      <summary><span class="uic" style="border-color:rgba(245,184,73,.3)">👥</span>Administradores <span class="cnt">${nAdm} · MOS · gestión global${onlineAdm ? ` · ${onlineAdm} en línea` : ''} ▾</span></summary>
      ${ucards.join('')}
      <div class="add-row" style="margin:9px 13px 12px" onclick="MOS.abrirModalPersonal(null,'MOS')">＋ agregar / ascender admin</div>
    </details>`;

    return `${_cfgEyebrow('VIP', 'Panel MOS · Admins & Master')}
    <div class="zone vip">
      <div class="zhead"><div class="zbadge gold">🏆</div>
        <div class="zt"><div class="row1"><h3 class="gold">Admins & Master · VIP</h3><span class="chip appmos">🖥️ MOS</span>${onlineNow ? `<span class="chip live"><span class="d" style="background:#10b981"></span>${onlineNow} en línea</span>` : ''}</div>
        <div class="zmeta">Entran al panel con permisos y monitoreo · <b style="color:#fde3a7">también emite facturación (CPE)</b></div></div>
        <span class="iconbtn" onclick="MOS.abrirModalHorarioApp('MOS')" title="Horario del panel MOS">🕐</span></div>
      ${seriesRow}
      ${fleetHTML}
      ${adminsBlock}
      <div class="callout g" style="margin-top:12px">Hoy: <b>${onlineNow} en línea</b> · ${activos.length} activos · ${ocultos} apagados/antiguos → viven en 🗄️ Archivados (la zona VIP queda limpia).</div>
    </div>`;
  }

  // Mini-chips de permisos para preview en cards (4 más relevantes)

  // Render completo de chips (en modal de detalle): muestra todos los permisos con label
  function _renderDispPermisosChipsFull(permsJson, lastUpdate) {
    let p = {};
    if (permsJson) {
      try { p = (typeof permsJson === 'string') ? JSON.parse(permsJson) : permsJson; } catch(_) { p = {}; }
    }
    const labels = {
      notif:   { i: '🔔', n: 'Notificaciones',   d: 'Pickups, anulaciones, alertas y avisos del admin llegan al dispositivo aunque la app esté cerrada.' },
      cam:     { i: '📸', n: 'Cámara',           d: 'Escaneo de códigos de barra de productos y guías. Sin esto, hay que digitar manualmente.' },
      mic:     { i: '🎤', n: 'Micrófono',        d: 'Búsqueda por voz y escucha remota del admin (espía 🕵️). Sin esto, sólo búsqueda por texto.' },
      geo:     { i: '📍', n: 'Geolocalización',  d: 'Ubica el dispositivo en su zona y rastrea repartos. Útil para auditoría de ruta del cajero móvil.' },
      audio:   { i: '🔊', n: 'Audio',            d: 'Alertas sonoras (nueva venta, error, pickup listo) y voz sintética que anuncia eventos.' },
      install: { i: '📱', n: 'App instalada',    d: 'PWA instalada en el escritorio/inicio. Funciona offline, abre más rápido y sin barra del navegador.' },
      storage: { i: '💾', n: 'Almacenamiento',   d: 'El sistema no borra automáticamente tus ventas/datos offline aunque ande corto de espacio. Crítico para no perder pendingSales.' }
    };
    const orden = ['notif','cam','mic','geo','audio','install','storage'];
    const tieneDatos = Object.keys(p).length > 0;
    if (!tieneDatos) {
      return `<div class="rounded-lg p-3 text-center text-xs text-slate-500 italic" style="background:#0a1424;border:1px dashed #334155;">
        Aún no se han reportado permisos desde este dispositivo. <br>
        <span class="text-[10px]">Se reportarán automáticamente al abrir la app.</span>
      </div>`;
    }
    const ts = lastUpdate ? `<span class="text-[10px] text-slate-500 italic">Actualizado: ${_dispActividad(lastUpdate).label}</span>` : '';
    const cards = orden.map(k => {
      const st = p[k];
      const lab = labels[k];
      if (!lab) return '';
      let bg, border, color, txt;
      if (!st)                       { bg='rgba(100,116,139,0.10)'; border='#334155';                color='#64748b'; txt='—'; }
      else if (st === 'granted')     { bg='rgba(16,185,129,0.12)';  border='rgba(16,185,129,0.45)'; color='#6ee7b7'; txt='✓ activo'; }
      else if (st === 'denied')      { bg='rgba(248,113,113,0.12)'; border='rgba(248,113,113,0.45)';color='#fca5a5'; txt='✗ denegado'; }
      else if (st === 'unsupported') { bg='rgba(100,116,139,0.10)'; border='rgba(100,116,139,0.4)'; color='#94a3b8'; txt='no soportado'; }
      else                            { bg='rgba(251,191,36,0.12)';  border='rgba(251,191,36,0.45)'; color='#fcd34d'; txt='⏳ pendiente'; }
      const info = (lab.d || '').replace(/"/g, '&quot;');
      return `<div class="flex items-center gap-2 p-2 rounded-lg" style="background:${bg};border:1px solid ${border};">
        <span class="text-lg shrink-0">${lab.i}</span>
        <div class="flex-1 min-w-0">
          <div class="flex items-center gap-1">
            <div class="text-xs font-bold truncate" style="color:${color}">${lab.n}</div>
            ${info ? `<span title="${info}" class="cursor-help text-[10px] opacity-60 hover:opacity-100" style="color:${color}">ⓘ</span>` : ''}
          </div>
          <div class="text-[10px] opacity-80" style="color:${color}">${txt}</div>
        </div>
      </div>`;
    }).join('');
    return `<div>
      <div class="flex items-center justify-between mb-2">
        <span class="text-[10px] font-bold text-slate-500 uppercase tracking-wider">Permisos del dispositivo</span>
        ${ts}
      </div>
      <div class="grid grid-cols-2 gap-2">${cards}</div>
    </div>`;
  }

  // ════════════════════════════════════════════════════════════
  // MODAL DETALLE DISPOSITIVO — moderno con permisos + acciones
  // ════════════════════════════════════════════════════════════
  function abrirDetalleDispositivo(id) {
    const d = (cfgData.dispositivos || []).find(x => String(x.ID_Dispositivo) === String(id));
    if (!d) { toast('Dispositivo no encontrado', 'error'); return; }
    const ico = _dispIcono(d.Nombre_Equipo);
    const act = _dispActividad(d.Ultima_Conexion);
    const est = String(d.Estado || '').toUpperCase();
    const isMOS = _isAppMOS(d);
    const idAttr = String(d.ID_Dispositivo).replace(/'/g, '&#39;');

    const estChip = est === 'ACTIVO'
      ? '<span class="text-[10px] font-black px-2 py-1 rounded" style="background:rgba(16,185,129,0.20);color:#6ee7b7;border:1px solid rgba(16,185,129,0.5)">● ACTIVO</span>'
      : (est === 'PENDIENTE_APROBACION'
        ? '<span class="text-[10px] font-black px-2 py-1 rounded animate-pulse" style="background:rgba(251,191,36,0.20);color:#fcd34d;border:1px solid rgba(251,191,36,0.5)">⏳ PENDIENTE</span>'
        : (est === 'SUSPENDIDO'
          ? '<span class="text-[10px] font-black px-2 py-1 rounded" style="background:rgba(148,163,184,0.20);color:#e2e8f0;border:1px solid rgba(148,163,184,0.5)">💤 SUSPENDIDO</span>'
          : '<span class="text-[10px] font-black px-2 py-1 rounded" style="background:rgba(248,113,113,0.20);color:#fca5a5;border:1px solid rgba(248,113,113,0.5)">⛔ INACTIVO</span>'));

    const headerBg = isMOS
      ? 'linear-gradient(135deg,rgba(251,191,36,0.18),rgba(99,102,241,0.10))'
      : 'linear-gradient(135deg,rgba(99,102,241,0.10),transparent)';

    const html = `
      <div class="modal-box flex flex-col" style="max-width:560px;max-height:92vh">
        <div class="px-5 py-4 flex items-start gap-3 flex-shrink-0" style="border-bottom:1px solid #1e293b;background:${headerBg}">
          <div class="w-14 h-14 rounded-xl flex items-center justify-center text-3xl flex-shrink-0" style="background:${isMOS ? 'linear-gradient(135deg,#7c2d12,#f59e0b)' : 'linear-gradient(135deg,#1e3a8a,#6366f1)'};">
            ${ico}
          </div>
          <div class="min-w-0 flex-1">
            <div class="flex items-center gap-2 flex-wrap">
              <h2 class="font-bold text-base text-white truncate">${d.Nombre_Equipo || 'Sin nombre'}</h2>
              ${estChip}
            </div>
            <p class="text-[11px] text-slate-500 mt-1 font-mono truncate">${d.ID_Dispositivo}</p>
            <p class="text-[11px] mt-1" style="color:${act.color}">${act.dot} ${act.label}${d.Ultima_Sesion ? ' · 👤 ' + d.Ultima_Sesion : ''}</p>
          </div>
          <button onclick="MOS.cerrarDetalleDispositivo()" class="modal-close-x">×</button>
        </div>

        <div class="overflow-y-auto px-5 py-4 flex-1 space-y-4">
          <!-- App + Zona/Estación -->
          <div class="grid grid-cols-2 gap-2 text-xs">
            <div class="p-2.5 rounded-lg" style="background:#0a1424;border:1px solid #1e293b">
              <div class="text-[9px] uppercase text-slate-500 tracking-wider mb-1">App</div>
              <div class="font-bold text-slate-200">${(d.App || '—').toUpperCase()}</div>
            </div>
            <div class="p-2.5 rounded-lg" style="background:#0a1424;border:1px solid #1e293b">
              <div class="text-[9px] uppercase text-slate-500 tracking-wider mb-1">Última zona/estación</div>
              <div class="font-bold text-slate-200 truncate">${d.Ultima_Zona || '—'}${d.Ultima_Estacion ? ' · ' + d.Ultima_Estacion : ''}</div>
            </div>
          </div>

          <!-- Permisos -->
          ${_renderDispPermisosChipsFull(d.Permisos_JSON, d.Permisos_LastUpdate)}

          <!-- Acciones -->
          <div class="space-y-2">
            <div class="text-[10px] font-bold text-slate-500 uppercase tracking-wider">Acciones (requieren clave admin 8 dig)</div>
            <button onclick="MOS.forzarWizardRemoto('${idAttr}')"
              class="w-full flex items-center gap-3 p-3 rounded-lg text-left transition-all hover:scale-[1.01]"
              style="background:linear-gradient(135deg,rgba(99,102,241,0.10),rgba(168,85,247,0.08));border:1px solid rgba(99,102,241,0.4)">
              <span class="text-2xl">🪄</span>
              <div class="flex-1 min-w-0">
                <div class="text-sm font-black text-indigo-200">Forzar re-wizard</div>
                <div class="text-[10px] text-indigo-300/70">Al próximo arranque, mostrarle el wizard de permisos</div>
              </div>
            </button>
            <button onclick="MOS.forzarPushRemoto('${idAttr}')"
              class="w-full flex items-center gap-3 p-3 rounded-lg text-left transition-all hover:scale-[1.01]"
              style="background:linear-gradient(135deg,rgba(16,185,129,0.10),rgba(45,212,191,0.08));border:1px solid rgba(16,185,129,0.4)">
              <span class="text-2xl">🔄</span>
              <div class="flex-1 min-w-0">
                <div class="text-sm font-black text-emerald-200">Reforzar registro push</div>
                <div class="text-[10px] text-emerald-300/70">Si no le llegan notifs/comandos/espía, fuerza re-registro del FCM token</div>
              </div>
            </button>
            <button onclick="MOS.verUltimaUbicacionDispositivo('${idAttr}')"
              class="w-full flex items-center gap-3 p-3 rounded-lg text-left transition-all hover:scale-[1.01]"
              style="background:linear-gradient(135deg,rgba(59,130,246,0.10),rgba(14,165,233,0.08));border:1px solid rgba(59,130,246,0.4)">
              <span class="text-2xl">🗺️</span>
              <div class="flex-1 min-w-0">
                <div class="text-sm font-black text-blue-200">Ver última ubicación GPS</div>
                <div class="text-[10px] text-blue-300/70">Última posición conocida (no necesita espía activo) · abre en Google Maps</div>
              </div>
            </button>
            <button onclick="MOS.revocarDispositivoUUID('${idAttr}')"
              class="w-full flex items-center gap-3 p-3 rounded-lg text-left transition-all hover:scale-[1.01]"
              style="background:linear-gradient(135deg,rgba(248,113,113,0.10),rgba(220,38,38,0.08));border:1px solid rgba(248,113,113,0.4)">
              <span class="text-2xl">🚫</span>
              <div class="flex-1 min-w-0">
                <div class="text-sm font-black text-red-200">Revocar acceso (UUID)</div>
                <div class="text-[10px] text-red-300/70">Bloquea este dispositivo físico — el usuario no podrá usar la app</div>
              </div>
            </button>
            <button onclick="MOS.cerrarDetalleDispositivo();MOS.abrirModalDispositivo('${idAttr}')"
              class="w-full flex items-center gap-3 p-3 rounded-lg text-left transition-all hover:scale-[1.01]"
              style="background:#0a1424;border:1px solid #334155">
              <span class="text-2xl">✏️</span>
              <div class="flex-1 min-w-0">
                <div class="text-sm font-bold text-slate-200">Editar detalles</div>
                <div class="text-[10px] text-slate-400">Renombrar, cambiar app, estado…</div>
              </div>
            </button>
          </div>
        </div>
      </div>`;

    let backdrop = $('modalDispDetalle');
    if (!backdrop) {
      backdrop = document.createElement('div');
      backdrop.id = 'modalDispDetalle';
      backdrop.className = 'modal-backdrop';
      backdrop.onclick = (e) => { if (e.target === backdrop) cerrarDetalleDispositivo(); };
      document.body.appendChild(backdrop);
    }
    backdrop.innerHTML = html;
    // El CSS .modal-backdrop tiene display:none por defecto. Mostramos con .open
    // (no solo quitar .hidden). Antes el modal NUNCA aparecía por este bug.
    backdrop.classList.remove('hidden');
    backdrop.classList.add('open');
  }

  function cerrarDetalleDispositivo() {
    const bd = $('modalDispDetalle');
    if (bd) {
      bd.classList.add('hidden');
      bd.classList.remove('open');
    }
  }

  // [v2.41.83] DEPRECATED — usar pedirAuth(opts) en lugar de prompt()

  async function revocarDispositivoUUID(id) {
    const d = (cfgData.dispositivos || []).find(x => String(x.ID_Dispositivo) === String(id));
    if (!d) return;
    if (!await _modalConfirm(`¿Revocar el acceso de "${d.Nombre_Equipo}"?\n\nEl dispositivo quedará bloqueado y no podrá usar la app.`, { danger: true, titulo: 'Revocar dispositivo', okText: 'Sí, revocar' })) return;
    // [v2.41.83] AdminAuthModal universal (antes prompt() nativo)
    const auth = await pedirAuth({
      accion: 'REVOCAR_DISPOSITIVO',
      refDocumento: id,
      contexto: `Revocar "${d.Nombre_Equipo}" (${d.App}) · acción crítica`,
      allowCache: false  // tier 3 ya no cachea, pero forzamos por claridad
    });
    if (!auth) return;
    try {
      const r = await API.post('revocarDispositivo', { deviceId: id, claveAdmin: auth.clave, app: d.App });
      // [v2.42.00 fix] API.post devuelve data directo, no envuelto en r.data
      if (!r?.autorizado) {
        toast(r?.error || 'Clave incorrecta', 'error');
        return;
      }
      toast('Dispositivo revocado por ' + r.revocadoPor, 'ok');
      d.Estado = 'INACTIVO';
      cerrarDetalleDispositivo();
      renderInfra();
    } catch(e) { toast('Error: ' + e.message, 'error'); }
  }

  async function forzarWizardRemoto(id) {
    const d = (cfgData.dispositivos || []).find(x => String(x.ID_Dispositivo) === String(id));
    if (!d) return;
    if (!await _modalConfirm(`Al próximo arranque de "${d.Nombre_Equipo}" se mostrará el wizard de permisos.\n\n¿Continuar?`, { warning: true, titulo: 'Forzar wizard remoto' })) return;
    // [v2.41.83] AdminAuthModal universal
    const auth = await pedirAuth({
      accion: 'FORZAR_WIZARD',
      refDocumento: id,
      contexto: `Forzar wizard en "${d.Nombre_Equipo}" (${d.App})`
    });
    if (!auth) return;
    try {
      const r = await API.post('forzarWizardDispositivo', { deviceId: id, claveAdmin: auth.clave, app: d.App });
      // [v2.42.00 fix] API.post devuelve data directo, no envuelto en r.data
      if (!r?.autorizado) {
        toast(r?.error || 'Clave incorrecta', 'error');
        return;
      }
      toast('Wizard forzado por ' + r.forzadoPor, 'ok');
      cerrarDetalleDispositivo();
    } catch(e) { toast('Error: ' + e.message, 'error'); }
  }

  // [v2.43.71] Ver última ubicación GPS del dispositivo (sin necesidad
  // de espía activo). Útil cuando el device está bloqueado/cerrado pero
  // queremos saber dónde anduvo por última vez. Consulta la hoja
  // UBICACIONES_HISTORIAL que llenan _gpsRegistrarWH/_gpsRegistrar cada 5min.
  async function verUltimaUbicacionDispositivo(id) {
    const d = (cfgData.dispositivos || []).find(x => String(x.ID_Dispositivo) === String(id));
    if (!d) return;
    toast('🗺 Consultando última ubicación…', 'info', 2000);
    try {
      const r = await API.post('getUltimaUbicacionDispositivo', { deviceId: id });
      if (!r) {
        await _modalConfirm(`"${d.Nombre_Equipo}" no tiene ubicaciones registradas.\n\nEl device debe abrir la app y autorizar geolocalización para empezar a registrar (cada 5min auto).`, { warning: true, titulo: '🗺 Sin ubicaciones', okText: 'Entendido', cancelText: '' });
        return;
      }
      const lat = parseFloat(r.lat || r.latitude || 0);
      const lng = parseFloat(r.lng || r.longitude || 0);
      const acc = parseFloat(r.accuracy || r.acc || 0);
      const ts  = r.timestamp || r.ts || '';
      if (!lat || !lng) {
        toast('Última ubicación incompleta (sin lat/lng)', 'warn');
        return;
      }
      const cuandoMs = new Date(ts).getTime();
      const hace = isNaN(cuandoMs) ? '?' : (() => {
        const minutos = Math.round((Date.now() - cuandoMs) / 60000);
        if (minutos < 60) return 'hace ' + minutos + 'min';
        const horas = Math.round(minutos / 60);
        if (horas < 24) return 'hace ' + horas + 'h';
        return 'hace ' + Math.round(horas / 24) + 'd';
      })();
      const ok = await _modalConfirm(
        `📍 Última posición de "${d.Nombre_Equipo}":\n\n` +
        `🕐 ${hace} (${ts})\n` +
        `📍 ${lat.toFixed(6)}, ${lng.toFixed(6)}\n` +
        `🎯 Precisión: ±${Math.round(acc)} m`,
        { titulo: '🗺 Última ubicación GPS', okText: 'Abrir Google Maps', cancelText: 'Cerrar' }
      );
      if (ok) {
        const url = `https://www.google.com/maps?q=${lat},${lng}`;
        window.open(url, '_blank');
      }
    } catch(e) {
      toast('Error consultando ubicación: ' + e.message, 'error', 5000);
    }
  }

  // [v2.43.69] Forzar re-registro del FCM token remoto.
  // Usado cuando el device no aparece en PUSH_TOKENS y el espía/push directo
  // no le llega. Cliente al próximo poll consultarEstadoDispositivo verá
  // forzar_push=true y ejecuta _pushInit + limpia el flag.
  async function forzarPushRemoto(id) {
    const d = (cfgData.dispositivos || []).find(x => String(x.ID_Dispositivo) === String(id));
    if (!d) return;
    if (!await _modalConfirm(`"${d.Nombre_Equipo}" re-registrará su token de notificaciones en el próximo arranque.\n\nÚtil cuando el device no recibe pushes (espía no conecta, comandos no llegan).\n\n¿Continuar?`, { warning: true, titulo: 'Reforzar registro push' })) return;
    const auth = await pedirAuth({
      accion: 'FORZAR_PUSH',
      refDocumento: id,
      contexto: `Reforzar push en "${d.Nombre_Equipo}" (${d.App})`
    });
    if (!auth) return;
    try {
      const r = await API.post('forzarPushDispositivo', { deviceId: id, claveAdmin: auth.clave, app: d.App });
      if (!r?.autorizado) {
        toast(r?.error || 'Clave incorrecta', 'error');
        return;
      }
      toast('🔄 Push se re-registrará al próximo arranque del device · por ' + r.forzadoPor, 'ok', 6000);
      cerrarDetalleDispositivo();
    } catch(e) { toast('Error: ' + e.message, 'error'); }
  }

  // Toggles optimistas
  async function toggleZonaActiva(idZona, ev) {
    if (ev) ev.stopPropagation();
    const z = (cfgData.zonas || []).find(x => x.idZona === idZona);
    if (!z) return;
    const nuevo = String(z.estado) === '1' ? '0' : '1';
    const previo = z.estado;
    z.estado = nuevo;
    renderInfra();
    try {
      await API.post('actualizarZona', { idZona, estado: nuevo });
      toast(`Zona ${nuevo === '1' ? 'activada' : 'desactivada'}`, 'ok');
    } catch(e) {
      z.estado = previo;
      renderInfra();
      toast('Error: ' + e.message, 'error');
    }
  }

