  function _zonaActualizarPreview() {
    const sub = $('modalZonaSubtitle');
    if (!sub) return;
    const nom = ($('zonaNombre')?.value || '').trim();
    const tg = $('zonaEstadoToggle');
    const activo = tg ? tg.checked : true;
    sub.textContent = nom ? (activo ? '🟢 activa' : '🔴 inactiva') + ' · zona' : 'Punto de venta físico';
  }

  // ¿Es la zona de almacén? Detección heurística por id o nombre.
  // El almacén usa configuración global, no por zona — así que el modal
  // oculta la sección "Política de la zona" para evitar confusión.
  function _esZonaAlmacen(z) {
    if (!z) return false;
    const id = String(z.idZona || '').toUpperCase();
    const nm = String(z.nombre || '').toUpperCase();
    return id === 'ALMACEN' || id === 'ALMACÉN' || nm.indexOf('ALMACEN') >= 0 || nm.indexOf('ALMACÉN') >= 0;
  }

  function abrirModalZona(id) {
    ['Id','Nombre','Direccion','Responsable','Desc','MetaDiaria','ComisionPct','MetaAuditorias','BaseCajero','BaseVendedor'].forEach(f => {
      const el = $('zona' + f); if (el) el.value = '';
    });
    const estadoWrap = $('zonaEstadoWrap');
    const btnElim = $('zonaBtnEliminar');
    const tg = $('zonaEstadoToggle');
    if (id) {
      const z = cfgData.zonas.find(x => x.idZona === id);
      if (!z) return;
      $('modalZonaTitle').textContent = 'Editar Zona';
      $('zonaId').value          = z.idZona;
      $('zonaNombre').value      = z.nombre || '';
      $('zonaDireccion').value   = z.direccion || '';
      $('zonaResponsable').value = z.responsable || '';
      $('zonaEstado').value      = String(z.estado ?? '1');
      $('zonaDesc').value        = z.descripcion || '';
      // Parsear politicaJSON si existe
      try {
        const pol = z.politicaJSON
          ? (typeof z.politicaJSON === 'string' ? JSON.parse(z.politicaJSON) : z.politicaJSON)
          : {};
        if (pol.metaDiaria != null)            $('zonaMetaDiaria').value      = String(pol.metaDiaria);
        if (pol.comisionExcedentePct != null)  $('zonaComisionPct').value     = String(pol.comisionExcedentePct);
        if (pol.metaAuditorias != null)        $('zonaMetaAuditorias').value  = String(pol.metaAuditorias);
        // [846] base diaria por rol de la zona
        if (pol.baseCajero != null   && $('zonaBaseCajero'))   $('zonaBaseCajero').value   = String(pol.baseCajero);
        if (pol.baseVendedor != null && $('zonaBaseVendedor')) $('zonaBaseVendedor').value = String(pol.baseVendedor);
      } catch(_){}
      if (tg) tg.checked = String(z.estado) === '1' || z.estado === 1 || z.estado === true;
      if (estadoWrap) estadoWrap.classList.remove('hidden');
      if (btnElim)    btnElim.classList.remove('hidden');
    } else {
      $('modalZonaTitle').textContent = 'Nueva Zona';
      $('zonaId').value = '';
      $('zonaEstado').value = '1';
      if (tg) tg.checked = true;
      if (estadoWrap) estadoWrap.classList.add('hidden');
      if (btnElim)    btnElim.classList.add('hidden');
    }

    // [509] Vigencia de política: default HOY (Lima, UTC-5). Los cambios de meta/comisión aplican
    // desde esta fecha hacia adelante (no retroactivo). El admin puede fijar una fecha anterior.
    if ($('zonaPoliticaVigencia')) {
      $('zonaPoliticaVigencia').value = new Date(Date.now() - 5*3600*1000).toISOString().slice(0,10);
    }

    // Si es la zona de almacén, ocultar sección "Política de la zona" y
    // mostrar nota — su configuración va en CONFIG_MOS (chips de Operadores).
    const z2 = id ? cfgData.zonas.find(x => x.idZona === id) : null;
    const esAlmacen = _esZonaAlmacen(z2 || { idZona: id });
    const seccionPolitica = document.querySelector('#modalZona .pers-section:has(#zonaMetaDiaria)');
    let notaAlmacen = document.getElementById('zonaNotaAlmacen');
    if (esAlmacen) {
      if (seccionPolitica) seccionPolitica.style.display = 'none';
      if (!notaAlmacen) {
        notaAlmacen = document.createElement('div');
        notaAlmacen.id = 'zonaNotaAlmacen';
        notaAlmacen.className = 'pers-section';
        notaAlmacen.style.cssText = 'border-top:1px dashed #1e293b;padding-top:14px;margin-top:14px';
        notaAlmacen.innerHTML = `
          <div class="pers-section-title" style="display:flex;align-items:center;gap:6px;color:#fbbf24">
            <span>🏭 Zona de almacén</span>
          </div>
          <div class="text-[11px] text-slate-400 p-3 rounded leading-relaxed" style="background:rgba(251,191,36,.05);border:1px dashed rgba(251,191,36,.3)">
            <p>Esta zona es operativa del almacén central. No tiene meta de venta diaria ni comisión porque <b>aquí no se vende</b>.</p>
            <p class="mt-2">La configuración del almacén (tarifa de envasado + meta de auditorías) es <b>global</b> en CONFIG_MOS. Edítala desde:</p>
            <p class="mt-1 text-amber-400 font-bold">Configuración → Personal → sección "Operadores Almacén" (chips arriba a la derecha).</p>
          </div>`;
        const body = document.querySelector('#modalZona .overflow-y-auto');
        if (body) body.appendChild(notaAlmacen);
      } else {
        notaAlmacen.style.display = '';
      }
    } else {
      if (seccionPolitica) seccionPolitica.style.display = '';
      if (notaAlmacen) notaAlmacen.style.display = 'none';
    }

    _zonaActualizarPreview();
    openModal('modalZona');
  }

  async function guardarZona() {
    const nombre = $('zonaNombre')?.value.trim();
    if (!nombre) { toast('Nombre requerido', 'error'); return; }
    const idEdit = $('zonaId')?.value || undefined;
    const tg = $('zonaEstadoToggle');
    const estado = idEdit ? (tg && tg.checked ? '1' : '0') : '1';
    // Construir politicaJSON (meta de venta + % comisión + meta auditorías).
    // Cada campo vacío se omite del JSON (para distinguir "no configurado").
    const metaRaw    = parseFloat($('zonaMetaDiaria')?.value);
    const pctRaw     = parseFloat($('zonaComisionPct')?.value);
    const metaAudRaw = parseFloat($('zonaMetaAuditorias')?.value);
    // [846] base diaria por rol — viaja en la MISMA política versionada que meta y comisión, así
    // que hereda su vigencia por fecha y el recálculo automático de los días PENDIENTES.
    const bCajRaw    = parseFloat($('zonaBaseCajero')?.value);
    const bVenRaw    = parseFloat($('zonaBaseVendedor')?.value);
    const politica = {};
    if (!isNaN(metaRaw)    && metaRaw    >= 0)  politica.metaDiaria            = metaRaw;
    if (!isNaN(pctRaw)     && pctRaw     >= 0)  politica.comisionExcedentePct  = pctRaw;
    if (!isNaN(metaAudRaw) && metaAudRaw >= 0)  politica.metaAuditorias        = metaAudRaw;
    if (!isNaN(bCajRaw)    && bCajRaw    >= 0)  politica.baseCajero            = bCajRaw;
    if (!isNaN(bVenRaw)    && bVenRaw    >= 0)  politica.baseVendedor          = bVenRaw;
    const politicaJSON = Object.keys(politica).length ? JSON.stringify(politica) : '';

    const params = {
      idZona:        idEdit,
      nombre,
      descripcion:   $('zonaDesc')?.value || '',
      direccion:     $('zonaDireccion')?.value || '',
      responsable:   $('zonaResponsable')?.value || '',
      estado,
      politicaJSON:  politicaJSON,
      // [509] fecha desde la que aplican los cambios de meta/comisión (no retroactivo). Default hoy.
      politicaVigenteDesde: $('zonaPoliticaVigencia')?.value || ''
    };
    if (!params.idZona) delete params.idZona;
    // OPTIMISTA
    const list = cfgData.zonas;
    const backup = list.slice();
    if (idEdit) {
      const idx = list.findIndex(x => x.idZona === idEdit);
      if (idx >= 0) list[idx] = { ...list[idx], ...params };
    } else {
      list.push({ ...params, idZona: 'Z_TMP' + Date.now(), _tmp: true });
    }
    closeModal('modalZona');
    renderInfra();
    try {
      const res = await API.post(idEdit ? 'actualizarZona' : 'crearZona', params);
      if (!idEdit && res?.idZona) {
        const tmp = list.findIndex(x => x._tmp);
        if (tmp >= 0) { list[tmp].idZona = res.idZona; delete list[tmp]._tmp; }
      }
      toast('Zona guardada ✓', 'ok');
      renderInfra();
      // [847] Guardar la política de una zona hace que el SERVIDOR recalcule las liquidaciones
      // PENDIENTES desde la vigencia (SQL 731 para meta/comisión, 846 para la base). El panel de
      // Personal vive de un caché local, así que hay que releerlo o queda mostrando el pago viejo.
      if (idEdit && politicaJSON) _finRefrescarPersonalDia().catch(() => {});
    } catch(e) {
      cfgData.zonas = backup;
      renderInfra();
      toast('Error: ' + e.message, 'error');
    }
  }

  async function eliminarZona() {
    const id = $('zonaId')?.value;
    if (!id) return;
    const z = cfgData.zonas.find(x => x.idZona === id);
    if (!z) return;
    const numEst = cfgData.estaciones.filter(e => e.idZona === id).length;
    const msg = numEst > 0
      ? `¿Desactivar la zona "${z.nombre}"?\n\nTiene ${numEst} estación${numEst === 1 ? '' : 'es'} asociada${numEst === 1 ? '' : 's'} que dejarán de aparecer en las apps. Puedes reactivarla luego.`
      : `¿Desactivar la zona "${z.nombre}"?\n\nPodrás reactivarla cuando quieras.`;
    if (!await _modalConfirm(msg, { warning: true, titulo: 'Desactivar zona' })) return;
    closeModal('modalZona');
    // OPTIMISTA: marcar inactiva
    const previo = z.estado;
    z.estado = '0';
    renderInfra();
    try {
      await API.post('actualizarZona', { idZona: id, estado: '0' });
      toast('Zona desactivada', 'ok');
    } catch(e) {
      z.estado = previo;
      renderInfra();
      toast('Error: ' + e.message, 'error');
    }
  }

  // (renderEstaciones() obsoleto — usado renderInfra() para vista jerárquica)

  // (renderImpresoras() obsoleto — usado renderInfra() para vista jerárquica)

  // Helper: actividad del usuario igual que dispositivos
  // Parser defensivo de timestamps Ultima_Conexion / Ultima_Sesion del backend.
  // Caso 1: ISO con Z → JS Date lo parsea correcto.
  // Caso 2: ISO sin Z (legacy "2026-05-09 14:35:29") → SIN este helper JS lo
  //         parseaba como hora LOCAL del browser, dando mismatch de horas vs
  //         server. Aquí lo convertimos manualmente asumiendo UTC.
  // Caso 3: formato US "5/9/2026 9:35:29" → parsear con regex defensivo.
  function _parseTsUtc(raw) {
    if (!raw) return NaN;
    if (raw instanceof Date) return raw.getTime();
    const s = String(raw).trim();
    if (!s) return NaN;
    // ISO con T y Z (o con offset tipo +05:00) — JS lo parsea correctamente
    if (s.indexOf('T') >= 0 && (s.indexOf('Z') >= 0 || /[+-]\d{2}:?\d{2}$/.test(s))) {
      return new Date(s).getTime();
    }
    // ISO sin Z: "2026-05-09 14:35:29" o "2026-05-09T14:35:29" → tratar como UTC
    const isoNoZ = /^(\d{4})-(\d{2})-(\d{2})[T ](\d{1,2}):(\d{2}):(\d{2})/;
    const m1 = s.match(isoNoZ);
    if (m1) {
      return Date.UTC(+m1[1], +m1[2] - 1, +m1[3], +m1[4], +m1[5], +m1[6]);
    }
    // Formato US "5/9/2026 9:35:29" o "05/09/2026 09:35:29" → tratar como UTC
    const usFmt = /^(\d{1,2})\/(\d{1,2})\/(\d{4})\s+(\d{1,2}):(\d{2}):(\d{2})/;
    const m2 = s.match(usFmt);
    if (m2) {
      return Date.UTC(+m2[3], +m2[1] - 1, +m2[2], +m2[4], +m2[5], +m2[6]);
    }
    // Fallback: que JS intente
    const t = new Date(s).getTime();
    return isNaN(t) ? NaN : t;
  }

  function _personaActividad(ultimaConexion) {
    if (!ultimaConexion) return { color: '#64748b', label: 'sin conexión', dot: '⚫', minutos: Infinity };
    const t = _parseTsUtc(ultimaConexion);
    if (isNaN(t)) return { color: '#64748b', label: ultimaConexion, dot: '⚫', minutos: Infinity };
    const min = Math.floor((Date.now() - t) / 60000);
    if (min < 0)       return { color: '#10b981', label: 'online ahora',     dot: '🟢', minutos: 0 }; // server adelantado
    if (min < 5)       return { color: '#10b981', label: 'online ahora',     dot: '🟢', minutos: min };
    if (min < 60)      return { color: '#10b981', label: `hace ${min}m`,     dot: '🟢', minutos: min };
    if (min < 60*24)   return { color: '#fbbf24', label: `hace ${Math.floor(min/60)}h`, dot: '🟡', minutos: min };
    if (min < 60*24*7) return { color: '#f97316', label: `hace ${Math.floor(min/60/24)}d`, dot: '🟠', minutos: min };
    return { color: '#ef4444', label: `inactivo ${Math.floor(min/60/24)}d`, dot: '🔴', minutos: min };
  }

  // [v2.43.31] ═════════ BLOQUEO HORARIO PROPIO MOS ═══════════════════
  // Verifica si el admin logueado puede entrar (respeta horarioCustom).
  // Si fuera de horario → muestra overlay full-screen no-cerrable.
  S._mosHorarioInterval = null;
  async function _mosVerificarHorarioPropio() {
    if (!S.session || !S.session.idPersonal) return;
    try {
      const r = await API.post('resolverHorarioPersonal', {
        idPersonal: S.session.idPersonal,
        rol:        S.session.rol || '',
        app:        'MOS'
      });
      const d = (r && r.data) || r || {};
      if (d.permitido === false) {
        _mosMostrarBloqueoHorario(d);
      } else {
        const ex = document.getElementById('mosHorarioBloqueoOverlay');
        if (ex) ex.remove();
      }
    } catch(_) { /* offline → no bloquear */ }
  }
  function _mosVerificarHorarioMioInterval() {
    if (S._mosHorarioInterval) clearInterval(S._mosHorarioInterval);
    _mosVerificarHorarioPropio();
    S._mosHorarioInterval = setInterval(_mosVerificarHorarioPropio, 5 * 60 * 1000);
  }
  function _mosMostrarBloqueoHorario(info) {
    let ov = document.getElementById('mosHorarioBloqueoOverlay');
    if (!ov) {
      ov = document.createElement('div');
      ov.id = 'mosHorarioBloqueoOverlay';
      ov.style.cssText = 'position:fixed;inset:0;z-index:99999;display:flex;align-items:center;justify-content:center;padding:24px;backdrop-filter:blur(10px);background:linear-gradient(160deg,#3730a3 0%,#0f172a 60%,#3730a3 100%)';
      document.body.appendChild(ov);
    }
    const motivoTxt = info.motivo === 'antes_apertura' ? 'Aún no es hora de apertura'
                    : info.motivo === 'despues_cierre' ? 'Ya pasó la hora de cierre'
                    : info.motivo === 'dia_cerrado'    ? 'Hoy el panel está cerrado'
                    : 'Fuera de horario asignado';
    ov.innerHTML = `
      <div style="max-width:440px;text-align:center;color:#fff">
        <div style="font-size:80px;animation:mosHorPulse 1.8s ease-in-out infinite">🔒</div>
        <div style="font-size:1.75rem;font-weight:900;color:#a5b4fc;margin-top:8px">Panel cerrado</div>
        <div style="font-size:14px;color:#c7d2fe;margin-top:6px">${motivoTxt}</div>
        <div style="background:rgba(15,23,42,.8);border:1px solid rgba(165,180,252,.4);border-radius:14px;padding:14px;margin:18px 0;backdrop-filter:blur(8px)">
          <div style="font-size:10px;color:#a5b4fc;text-transform:uppercase;letter-spacing:.5px;font-weight:700;margin-bottom:6px">Tu horario asignado</div>
          <div style="font-size:22px;font-weight:900;color:#fff">${info.apertura || '--'} <span style="color:#64748b">→</span> ${info.cierre || '--'}</div>
          <div style="font-size:10px;color:#94a3b8;margin-top:6px">
            Día: <b style="color:#fbbf24">${info.dia || '?'}</b>
            ${info.fuente === 'custom' ? '<span style="margin-left:8px;color:#c4b5fd">🕐 horario personalizado</span>' : ''}
          </div>
        </div>
        <button onclick="MOS._mosCerrarBloqueoYsalir()" style="padding:10px 22px;background:linear-gradient(135deg,#6366f1,#4338ca);color:#fff;border:0;border-radius:10px;font-weight:900;cursor:pointer;font-size:13px;box-shadow:0 8px 20px -5px rgba(99,102,241,.5)">Cerrar sesión</button>
      </div>
      <style>@keyframes mosHorPulse{0%,100%{transform:scale(1);opacity:.85}50%{transform:scale(1.1);opacity:1}}</style>`;
  }
  function _mosCerrarBloqueoYsalir() {
    try {
      // Limpiar sesión y volver al login
      localStorage.removeItem('mos_session');
      location.reload();
    } catch(_) { location.reload(); }
  }

  // [v2.43.30] ═════════ HORARIOS APPS + CUSTOM USUARIO ═════════════
  S._horariosAppsCache = null; S._horariosAppsCacheTs = 0;
  const _DIAS_HOR = [
    { k:'lun', lbl:'Lun' }, { k:'mar', lbl:'Mar' }, { k:'mie', lbl:'Mie' },
    { k:'jue', lbl:'Jue' }, { k:'vie', lbl:'Vie' }, { k:'sab', lbl:'Sab' }, { k:'dom', lbl:'Dom' }
  ];
  // [v2.43.37] Carga la rotación semanal (8 semanas) de WH para todos los
  // productos. Pre-cargado al login para que el catálogo lo tenga listo.
  // Resultado: S._rotacionSemanalCache = { etiquetas: ['YYYY-Www',...],
  //                                         productos: { CB: [{semana,unidades}*8] } }
  // TTL 15 min (rotación cambia despacio).
  //
  // [v2.43.39] Manejo de errores robusto: si la API falla o el WH no tiene el
  // endpoint (deployment viejo), seteamos un cache vacío PERO VÁLIDO para que
  // el sparkline muestre "sin rotación" en vez de quedarse "cargando…" eterno.
  async function _cargarRotacionSemanal(force) {
    const TTL = 15 * 60 * 1000;
    // [catálogo v4] STALE-WHILE-REVALIDATE: hidratar del localStorage ANTES del
    // primer fetch — el chip de rotación pinta AL INSTANTE con el último valor
    // conocido y se refresca por detrás (el skeleton solo se ve la 1ª vez en la
    // vida del equipo). El server ya es cache precalculada (SQL 424, ~120ms).
    if (!S._rotacionSemanalCache || !S._rotacionSemanalCache.productos
        || !Object.keys(S._rotacionSemanalCache.productos).length) {
      try {
        const raw = localStorage.getItem('mos_rotacion_cache_v1');
        if (raw) {
          const st = JSON.parse(raw);
          if (st && st.data && st.data.productos && Object.keys(st.data.productos).length) {
            S._rotacionSemanalCache = st.data;
            // ts=0 → se considera VENCIDO: pinta ya, pero el fetch de fondo corre igual
            S._rotacionSemanalCacheTs = 0;
          }
        }
      } catch (_) {}
    }
    // [v2.43.55] Si el cache es bueno y reciente → retornar directo
    if (!force && S._rotacionSemanalCache && S._rotacionSemanalCache.productos
        && Object.keys(S._rotacionSemanalCache.productos).length > 0
        && (Date.now() - (S._rotacionSemanalCacheTs || 0)) < TTL) {
      return S._rotacionSemanalCache;
    }
    // Guard de "cargando in-flight" — abandonar si lleva >25s
    const tsAnterior = S._rotacionSemanalLoadingStart || 0;
    if (S._rotacionSemanalLoading && (Date.now() - tsAnterior) < 25000) {
      return S._rotacionSemanalLoading;
    }
    // [v2.43.55] FAILSAFE: si llegamos aquí con _loading colgado (>25s), forzar reset
    if (S._rotacionSemanalLoading) {
      console.warn('[rotacion] abandono promesa colgada (>25s)');
      S._rotacionSemanalLoading = null;
    }
    console.log('[rotacion] iniciando carga, force=', force);
    if (!S._rotacionSemanalCache || !S._rotacionSemanalCache.productos
        || Object.keys(S._rotacionSemanalCache.productos).length === 0) {
      S._rotacionSemanalCache = { etiquetas: [], productos: {}, _loading: true };
    }
    S._rotacionSemanalLoadingStart = Date.now();
    const setear = (d) => {
      // [v2.43.55] Garantizar que _loading no quede true accidentalmente
      const limpio = Object.assign({}, d);
      delete limpio._loading;
      S._rotacionSemanalCache = limpio;
      S._rotacionSemanalCacheTs = Date.now();
      S._rotacionSemanalLoading = null;
      S._rotacionSemanalLoadingStart = 0;
      // [catálogo v4] persistir para el arranque instantáneo de la próxima sesión
      try {
        if (limpio.productos && Object.keys(limpio.productos).length) {
          localStorage.setItem('mos_rotacion_cache_v1', JSON.stringify({ ts: Date.now(), data: limpio }));
        }
      } catch (_) {}
      console.log('[rotacion] setear ok. productos:',
                  Object.keys(limpio.productos || {}).length,
                  limpio._error ? 'error:' + limpio._error : '');
      if (S.tab === 'catalogo' && typeof renderCatalogo === 'function') {
        try { renderCatalogo(); } catch(_){}
      }
      return d;
    };
    let resolverApiCall;
    const apiCall = new Promise((res) => { resolverApiCall = res; });
    S._rotacionSemanalLoading = apiCall;

    // [v2.43.55] DOBLE failsafe: setTimeout absoluto de 25s que fuerza setear()
    // incluso si la API ni siquiera responde, ni rechaza, ni nada.
    let yaResolvio = false;
    const safetyTimer = setTimeout(() => {
      if (yaResolvio) return;
      yaResolvio = true;
      console.warn('[rotacion] SAFETY TIMER 25s — forzando estado vacio');
      resolverApiCall(setear({ etiquetas: [], productos: {}, _error: 'safety_timeout' }));
    }, 25000);

    (async () => {
      try {
        const r = await Promise.race([
          API.post('wh_getRotacionSemanal', { semanas: 8 }),
          new Promise((_, rej) => setTimeout(() => rej(new Error('timeout 20s')), 20000))
        ]);
        if (yaResolvio) return;
        yaResolvio = true;
        clearTimeout(safetyTimer);
        const d = (r && r.data && r.data.productos) ? r.data
                : (r && r.productos)                ? r
                : null;
        if (d) { resolverApiCall(setear(d)); return; }
        console.warn('[rotacion] respuesta sin productos:', r);
        resolverApiCall(setear({ etiquetas: [], productos: {}, _error: 'sin_data' }));
      } catch(e) {
        if (yaResolvio) return;
        yaResolvio = true;
        clearTimeout(safetyTimer);
        console.warn('[rotacion] error:', e && e.message);
        resolverApiCall(setear({ etiquetas: [], productos: {}, _error: String(e && e.message || e) }));
      }
    })();
    return apiCall;
  }

  async function _cargarHorariosApps(force) {
    if (!force && S._horariosAppsCache && (Date.now() - S._horariosAppsCacheTs) < 5 * 60000) {
      return S._horariosAppsCache;
    }
    try {
      const r = await API.post('getHorariosApps', {});
      const d = (r && r.data) || r || {};
      S._horariosAppsCache = d;
      S._horariosAppsCacheTs = Date.now();
      return d;
    } catch(_) { return {}; }
  }
  function _renderHorarioAppCard(app, color) {
    // [v2.43.33 FIX PARPADEO] Pintar desde cache si existe. Antes mostraba
    // "Cargando horario…" y cada renderPersonal reseteaba el texto → flicker
    // de 0-8s hasta que setInterval refrescara. Ahora si hay cache, se ve
    // estable desde el primer paint.
    const cache = (S && S._horariosAppsCache) || {};
    const conf  = cache[app];
    const ttl   = conf && conf.horario ? _resumirHorario(conf.horario) : 'Cargando horario…';
    const sub   = conf
      ? `${conf.admins_libres ? '👑 admins libres · ' : ''}actualizado por ${conf.actualizadoPor || '—'}`
      : '';
    return `<div class="hor-app-card" data-app="${app}">
      <div class="hor-app-row">
        <div class="hor-app-ico" style="background:${color}22;color:${color}">🕐</div>
        <div class="flex-1 min-w-0">
          <div class="hor-app-ttl" id="horAppTtl_${app}">${ttl}</div>
          <div class="hor-app-sub" id="horAppSub_${app}">${sub}</div>
        </div>
        <button class="hor-app-btn" onclick="MOS.abrirModalHorarioApp('${app}')">⚙ Editar</button>
      </div>
    </div>`;
  }
  // [v2.43.32] Resumen agrupado: días consecutivos con mismo horario se juntan
  function _resumirHorario(hor) {
    if (!hor) return 'No configurado';
    const grupos = [];
    let actual = null;
    _DIAS_HOR.forEach(d => {
      const c = hor[d.k] || {};
      const key = (c.activo === false) ? 'cerrado' : `${c.apertura}-${c.cierre}`;
      if (actual && actual.key === key) actual.dias.push(d.lbl);
      else {
        actual = { key, dias: [d.lbl], apertura: c.apertura, cierre: c.cierre, cerrado: c.activo === false };
        grupos.push(actual);
      }
    });
    return grupos.map(g => {
      const rango = g.dias.length === 1 ? g.dias[0] : `${g.dias[0]} a ${g.dias[g.dias.length-1]}`;
      if (g.cerrado) return `${rango}: cerrado`;
      // Mostrar horas redondas si los minutos son :00
      const ap = String(g.apertura || '').replace(':00', 'h');
      const ci = String(g.cierre   || '').replace(':00', 'h');
      return `${rango}: ${ap} → ${ci}`;
    }).join(' · ');
  }
  // Render asíncrono — actualiza el texto cuando llega la respuesta
  (async () => { /* warmup en boot */ try { await _cargarHorariosApps(); } catch(_){} })();

  async function _refrescarHorarioCard(app) {
    const data = await _cargarHorariosApps();
    const conf = data[app];
    const ttl  = $(`horAppTtl_${app}`);
    const sub  = $(`horAppSub_${app}`);
    if (!ttl || !conf) return;
    const nuevoTxt = _resumirHorario(conf.horario);
    // [v2.43.33 FIX PARPADEO] Solo escribir si cambió. Antes reasignaba textContent
    // cada vez aunque fuera idéntico → repaint innecesario percibido como "flash".
    if (ttl.textContent !== nuevoTxt) ttl.textContent = nuevoTxt;
    if (sub) {
      const nuevoSub = `${conf.admins_libres ? '👑 admins libres · ' : ''}actualizado por ${conf.actualizadoPor || '—'}`;
      if (sub.textContent !== nuevoSub) sub.textContent = nuevoSub;
    }
  }
  // [v2.43.33 FIX PARPADEO] Era cada 8s — muy agresivo. Bajado a 60s.
  // El refresh real ocurre cuando se guarda (via onGuardar callback) y al
  // navegar a la pestaña. Polling 60s es solo red de seguridad para que
  // otro admin que cambió el horario se vea reflejado eventualmente.
  setInterval(() => {
    if (S.cfgTab !== 'personal') return;
    ['mosExpress', 'warehouseMos', 'MOS'].forEach(app => {
      if ($(`horAppTtl_${app}`)) _refrescarHorarioCard(app);
    });
  }, 60000);

  // Render del CHIP de horario custom dentro de la card del operador
  // [v2.43.35] Chip de horario custom — ahora muestra SOLO los días que
  // DIFIEREN del horario base del app. Lógica del usuario:
  //   - Si Lun-Mar-Mie igual al base → no mostrar (es obvio que están abiertos)
  //   - Si Jue-Vie-Sab tienen horas distintas → mostrar EN ROJO con sus horas
  //   - Si un día está cerrado y en el base no → mostrar como "cerrado" en rojo
  // Esto reduce ruido visual y enfoca lo realmente "custom".
  function _renderChipHorarioCustom(p) {
    if (!p.horarioCustom) return '';
    let hc;
    try { hc = typeof p.horarioCustom === 'string' ? JSON.parse(p.horarioCustom) : p.horarioCustom; } catch(_) { return ''; }
    if (!hc || !hc.activo || !hc.dias) return '';

    // Resolver el horario base del app del operador
    const appPersona = _appDePersona(p);
    const base       = _horarioBaseDeApp(appPersona);
    // Calcular diferencias por día — incluir idx para agrupar consecutivos reales
    const difs = []; // [{ idx, lbl, txt, cerrado }]
    _DIAS_HOR.forEach((d, idx) => {
      const c = hc.dias[d.k] || {};
      const b = base[d.k]    || {};
      const cAct = c.activo !== false && c.activo !== 'false';  // [v2.43.36] tolera "false" string de Sheets
      const bAct = b.activo !== false && b.activo !== 'false';
      const cAp  = _hrOnly(c.apertura), cCi = _hrOnly(c.cierre);
      const bAp  = _hrOnly(b.apertura), bCi = _hrOnly(b.cierre);
      const iguales = cAct === bAct && (cAct === false || (cAp === bAp && cCi === bCi));
      if (iguales) return; // omitir días iguales al base
      if (!cAct) {
        difs.push({ idx, lbl: d.lbl, txt: 'cerrado', cerrado: true });
      } else {
        difs.push({ idx, lbl: d.lbl, txt: `${cAp}h → ${cCi}h`, cerrado: false });
      }
    });

    // Si NO hay diferencias → el custom es idéntico al base → no mostrar chip
    if (!difs.length) return '';

    // [v2.43.36 BUG AGRUPACIÓN FIX] Agrupar solo si los días son CONSECUTIVOS
    // en la semana (idx contiguos) y tienen el mismo texto. Antes:
    //   Lun 7→22, Mar cerrado, Mie 7→22 → "Lun a Mie 7→22" (falso, Mar no aplica)
    // Ahora: detecta el salto en idx y rompe el grupo.
    const grupos = [];
    let actual = null;
    difs.forEach(d => {
      if (actual && actual.txt === d.txt && d.idx === actual.endIdx + 1) {
        actual.dias.push(d.lbl);
        actual.endIdx = d.idx;
      } else {
        actual = { txt: d.txt, cerrado: d.cerrado, dias: [d.lbl], endIdx: d.idx };
        grupos.push(actual);
      }
    });
    // Diferencias de hora → ámbar suave. Días cerrados → rojo suave (rosa).
    // Sin negrita agresiva; el contraste de color es suficiente.
    const resumenDifs = grupos.map(g => {
      const rango = g.dias.length === 1 ? g.dias[0] : `${g.dias[0]} a ${g.dias[g.dias.length-1]}`;
      const color = g.cerrado ? '#fca5a5' : '#fcd34d';
      return `<span style="color:${color}"><span style="color:#cbd5e1">${rango}:</span> ${g.txt}</span>`;
    }).join(' &middot; ');

    // Diseño limpio: fondo sutil indigo + label discreto + spans coloreados solo
    // en los datos diferentes. Sin bordes agresivos. Hover suave para indicar
    // que es clickeable.
    const pendiente = p._horCustomPendiente
      ? '<span style="margin-left:6px;font-size:9px;color:#a5b4fc;font-weight:600">guardando…</span>'
      : '';
    const motivoTxt = hc.motivo
      ? `<span style="color:#94a3b8;font-style:italic">${_escapeHtml(hc.motivo)}</span>`
      : '';
    return `<div class="hor-custom-inline" onclick="event.stopPropagation();MOS.abrirModalHorarioCustom('${p.idPersonal}')"
                 style="margin-top:8px;padding:8px 10px;background:rgba(99,102,241,.07);border-left:2px solid #6366f1;border-radius:4px;cursor:pointer;transition:background .15s"
                 onmouseover="this.style.background='rgba(99,102,241,.14)'"
                 onmouseout="this.style.background='rgba(99,102,241,.07)'">
      <div style="display:flex;align-items:center;gap:6px;font-size:9px;color:#a5b4fc;font-weight:700;letter-spacing:.5px;text-transform:uppercase;margin-bottom:3px">
        <span style="font-size:11px">🕐</span>
        <span>Excepciones del general</span>
        ${pendiente}
        <button onclick="event.stopPropagation();MOS.eliminarHorarioCustom('${p.idPersonal}')"
                style="margin-left:auto;background:none;border:none;color:#64748b;cursor:pointer;font-size:13px;padding:0;line-height:1;opacity:.6"
                onmouseover="this.style.opacity='1';this.style.color='#f87171'"
                onmouseout="this.style.opacity='.6';this.style.color='#64748b'"
                title="Quitar horario custom">✕</button>
      </div>
      <div style="font-size:11px;line-height:1.4;color:#e0e7ff">${resumenDifs}</div>
      ${motivoTxt ? `<div style="font-size:10px;color:#94a3b8;margin-top:3px;line-height:1.3">${motivoTxt}</div>` : ''}
    </div>`;
  }

  // [v2.43.32] UX nueva: horario general + check 7 días + especiales opcionales
  // Optimismo: cierra modal inmediato + toast + API en background
  function abrirModalHorarioApp(app) {
    try { _opsBeep && _opsBeep('tac'); } catch(_){}
    const data = S._horariosAppsCache || {};
    const conf = data[app] || { horario: {}, admins_libres: true };
    const titulo = app === 'warehouseMos' ? '📦 warehouseMos'
                 : app === 'mosExpress'   ? '📱 mosExpress'
                 : '👑 MOS Admin';
    const accent = app === 'warehouseMos' ? '#ea580c'
                 : app === 'mosExpress'   ? '#f59e0b'
                 : '#6366f1';
    _renderModalHorario({
      titulo: `⚙ Horario ${titulo}`,
      subtitulo: 'Configura apertura/cierre general y excepciones por día',
      accent: accent,
      modoApp: true,
      horarioActual: conf.horario,
      adminsLibres: conf.admins_libres,
      onGuardar: (horario, adminsLibres) => {
        // Optimismo: actualizar cache local + cerrar modal + toast
        if (!S._horariosAppsCache) S._horariosAppsCache = {};
        S._horariosAppsCache[app] = { ...conf, horario, admins_libres: adminsLibres };
        cerrarModalHorario();
        toast('🕐 Horario actualizado', 'success', 2500);
        _refrescarHorarioCard(app);
        // API en background
        API.post('setHorarioApp', { app, horario, admins_libres: adminsLibres, actualizadoPor: S.session?.nombre || 'admin' })
          .then(() => { try { _opsBeep && _opsBeep('ok'); } catch(_){} })
          .catch(e => { toast('⚠ Error guardando: ' + e.message, 'error', 5000); });
      }
    });
  }
  // [v2.43.33] Helper: resuelve el app al que pertenece una persona.
  // - personalMOS → app 'MOS'
  // - resto → mirar appOrigen del registro; default 'warehouseMos'
  function _appDePersona(p) {
    if (!p) return 'warehouseMos';
    const enMOS = (cfgData.personalMOS || []).some(x => String(x.idPersonal) === String(p.idPersonal));
    if (enMOS) return 'MOS';
    const appOrig = String(p.appOrigen || '').toLowerCase();
    if (appOrig === 'mosexpress' || appOrig === 'me') return 'mosExpress';
    if (appOrig === 'warehousemos' || appOrig === 'wh') return 'warehouseMos';
    return 'warehouseMos';
  }
  // [v2.43.33] Default razonable cuando ni el cache ni nada existe: 7→19 todos los días
  function _horarioPorDefecto() {
    const dft = {};
    _DIAS_HOR.forEach(d => {
      dft[d.k] = { activo: true, apertura: '07:00', cierre: '19:00' };
    });
    return dft;
  }
  // [v2.43.33] Lee el horario base del app desde cache (no hardcoded 12→22).
  // Si el general cambia luego, la próxima vez que abras el modal personal,
  // verás el nuevo base — esa es la "inteligencia" que pedía el usuario.
  function _horarioBaseDeApp(app) {
    const cache = S._horariosAppsCache || {};
    const conf  = cache[app];
    if (conf && conf.horario && Object.keys(conf.horario).length) {
      // Clonar para que el modal no mute el cache
      const out = {};
      _DIAS_HOR.forEach(d => {
        const c = conf.horario[d.k] || {};
        out[d.k] = {
          activo:   c.activo !== false,
          apertura: c.apertura || '07:00',
          cierre:   c.cierre   || '19:00'
        };
      });
      return out;
    }
    return _horarioPorDefecto();
  }

  async function abrirModalHorarioCustom(idPersonal) {
    try { _opsBeep && _opsBeep('tac'); } catch(_){}
    const all = (cfgData.personal || []).concat(cfgData.personalMOS || []);
    const p = all.find(x => String(x.idPersonal) === String(idPersonal));
    if (!p) { toast('Persona no encontrada', 'error'); return; }

    let hc = { activo: false, dias: null, motivo: '' };
    try { if (p.horarioCustom) hc = typeof p.horarioCustom === 'string' ? JSON.parse(p.horarioCustom) : p.horarioCustom; } catch(_){}

    // Determinar app al que pertenece + leer su horario general como BASE
    const appPersona = _appDePersona(p);

    // [v2.43.34 BUG AUDITORIA FIX] Si el cache NO tiene el app de la persona,
    // ESPERAR el load antes de abrir modal. Antes era no-bloqueante → el banner
    // mostraba fallback "Lun a Vie 07h→19h" engañoso. Ahora si el cache está
    // vacío esperamos máx 3s; si no llega, abrimos con fallback marcado como
    // "Cargando…" para que el operador sepa que el base aún no se cargó.
    const cacheTieneApp = S._horariosAppsCache && S._horariosAppsCache[appPersona];
    if (!cacheTieneApp) {
      try {
        await Promise.race([
          _cargarHorariosApps(true),
          new Promise((_, rej) => setTimeout(() => rej(new Error('timeout')), 3000))
        ]);
      } catch(_) { /* abre igual con lo que haya */ }
    } else {
      // Cache OK → refrescar en background para cubrir "general fue editado hace 1m"
      _cargarHorariosApps(true).catch(() => {});
    }

    const baseApp     = _horarioBaseDeApp(appPersona);
    const cacheCargo  = !!(S._horariosAppsCache && S._horariosAppsCache[appPersona]);

    // [v2.43.33 BUG 2 FIX] Default = horario general del app (NO 12→22 hardcoded).
    // Si tiene custom previo → mantiene el custom.
    // Si no tiene → arranca igual al general del app para que el operador solo
    // ajuste lo que es distinto.
    const dias = hc.dias || baseApp;

    // [v2.43.33 BUG 4 FIX] Toggle por defecto ON cuando NO tiene custom previo.
    // El operador abrió el modal con intención de CREAR — no tiene sentido que
    // arranque OFF (eso provocaba el toast "Horario personal eliminado" al
    // guardar sin tocar el toggle).
    const toggleActivo = hc.dias ? hc.activo !== false : true;

    _renderModalHorario({
      titulo: `🕐 Horario personal`,
      subtitulo: `${p.nombre || ''} ${p.apellido || ''} · ${p.rol || ''} · base ${appPersona}`,
      accent: '#a855f7',
      modoApp: false,
      horarioActual: dias,
      activoToggle: toggleActivo,
      motivoActual: hc.motivo || '',
      // [v2.43.33] Guardar el app base para mostrarlo en el modal + permitir
      // "resetear al horario general" si el operador quiere
      appBase: appPersona,
      horarioBase: baseApp,
      horarioBaseCargado: cacheCargo,  // [v2.43.34] avisa al modal si el base es real o fallback
      teniaCustom: !!hc.dias,
      onGuardar: (horario, activo, motivo) => {
        const teniaCustom = !!hc.dias;
        const msg = activo
          ? (teniaCustom ? '🕐 Horario personal actualizado' : '🕐 Horario personal creado')
          : (teniaCustom ? '🕐 Horario personal eliminado' : '🕐 Sin cambios');

        // [v2.43.35 FIX OPTIMISMO REAL] Bug: el polling cada 30s reemplazaba
        // cfgData.personal entero, pisando la mutación local antes de que el
        // backend persistiera. Fix:
        //   1. Mutar p (referencia actual del modal)
        //   2. Buscar TAMBIÉN en cfgData.personal y personalMOS por idPersonal
        //      y mutarlos por si son arrays distintos
        //   3. Marcar _horCustomPendiente:true para que el polling lo respete
        //   4. Cuando API.post confirma → limpiar el flag y re-render
        //   5. Si falla → toast error + limpiar flag (queda con el dato local
        //      que el polling pisará en su próximo ciclo)
        const nuevoValor = activo ? JSON.stringify({ activo:true, dias: horario, motivo }) : '';
        const aplicarMutacion = (obj) => {
          if (!obj) return;
          obj.horarioCustom = nuevoValor;
          obj._horCustomPendiente = true;
        };
        aplicarMutacion(p);
        (cfgData.personal || []).forEach(x => {
          if (String(x.idPersonal) === String(idPersonal)) aplicarMutacion(x);
        });
        (cfgData.personalMOS || []).forEach(x => {
          if (String(x.idPersonal) === String(idPersonal)) aplicarMutacion(x);
        });

        cerrarModalHorario();
        toast(msg, 'success', 2500);
        if (typeof renderPersonal === 'function') renderPersonal();

        API.post('setHorarioCustomPersonal', {
          idPersonal, horarioCustom: { activo, dias: horario, motivo }
        })
          .then(() => {
            try { _opsBeep && _opsBeep('ok'); } catch(_){}
            // Limpiar flag pendiente en todas las referencias
            const limpiar = (obj) => { if (obj) delete obj._horCustomPendiente; };
            limpiar(p);
            (cfgData.personal || []).forEach(x => { if (String(x.idPersonal) === String(idPersonal)) limpiar(x); });
            (cfgData.personalMOS || []).forEach(x => { if (String(x.idPersonal) === String(idPersonal)) limpiar(x); });
            if (typeof renderPersonal === 'function') renderPersonal();
          })
          .catch(e => {
            // Limpiar flag aunque haya error (no queremos un fantasma "guardando…" eterno)
            const limpiar = (obj) => { if (obj) delete obj._horCustomPendiente; };
            limpiar(p);
            (cfgData.personal || []).forEach(x => { if (String(x.idPersonal) === String(idPersonal)) limpiar(x); });
            (cfgData.personalMOS || []).forEach(x => { if (String(x.idPersonal) === String(idPersonal)) limpiar(x); });
            toast('⚠ Error guardando: ' + e.message, 'error', 5000);
            if (typeof renderPersonal === 'function') renderPersonal();
          });
      }
    });
  }
  async function eliminarHorarioCustom(idPersonal) {
    if (!await _modalConfirm('¿Quitar el horario personal? Vuelve al horario general de la app.', { warning: true, titulo: 'Quitar horario' })) return;  // [Lote4 · M3-MOS]
    try { _opsBeep && _opsBeep('tac'); } catch(_){}
    const all = (cfgData.personal || []).concat(cfgData.personalMOS || []);
    const p = all.find(x => String(x.idPersonal) === String(idPersonal));
    if (p) p.horarioCustom = '';
    if (typeof renderPersonal === 'function') renderPersonal();
    toast('🕐 Horario personal eliminado', 'success', 2200);
    API.post('setHorarioCustomPersonal', { idPersonal, horarioCustom: { activo: false } })
      .then(() => { try { _opsBeep && _opsBeep('ok'); } catch(_){} })
      .catch(e => { toast('⚠ Error: ' + e.message, 'error'); });
  }

  // [v2.43.32] Modal con UX nueva: horario general + selector horas redondas
  // + 7 días con check + "horario especial" opcional para días específicos
  function _renderModalHorario(opts) {
    // Calcular horario general (el más común) y excepciones
    const horActual = opts.horarioActual || {};
    const dias = _DIAS_HOR.map(d => {
      const c = horActual[d.k] || { activo: true, apertura: '07', cierre: '19' };
      return { ...d, activo: c.activo !== false, apertura: _hrOnly(c.apertura), cierre: _hrOnly(c.cierre) };
    });
    // Detectar horario "general" (el más frecuente)
    const counts = {};
    dias.filter(d => d.activo).forEach(d => {
      const k = `${d.apertura}-${d.cierre}`;
      counts[k] = (counts[k] || 0) + 1;
    });
    let general = { apertura: '07', cierre: '19' };
    let bestCount = 0;
    Object.entries(counts).forEach(([k, n]) => {
      if (n > bestCount) {
        bestCount = n;
        const [a, c] = k.split('-');
        general = { apertura: a, cierre: c };
      }
    });
    // Cada día: activo + especial (true si su horario difiere del general)
    dias.forEach(d => {
      d.especial = d.activo && (d.apertura !== general.apertura || d.cierre !== general.cierre);
    });

    let html = `<div class="hor-modal-backdrop" id="modalHorarioWrap" onclick="if(event.target===this)MOS.cerrarModalHorario()">
      <div class="hor-modal" style="border-color:${opts.accent}80;box-shadow:0 25px 60px -15px rgba(0,0,0,.7),0 0 0 1px ${opts.accent}33">
        <div class="hor-modal-hdr" style="background:linear-gradient(135deg,${opts.accent}22,${opts.accent}05);border-bottom:1px solid ${opts.accent}40">
          <div>
            <div class="hor-modal-ttl" style="color:${opts.accent}">${opts.titulo}</div>
            <div class="hor-modal-sub">${opts.subtitulo || ''}</div>
          </div>
          <button class="hor-modal-x" onclick="MOS.cerrarModalHorario()">✕</button>
        </div>
        <div class="hor-modal-body">`;

    if (!opts.modoApp) {
      // [v2.43.33] Banner del horario base + botón reset.
      // El operador ve EXACTAMENTE qué horario está usando como base y puede
      // resetear al general del app con 1 click si lo modificó por error.
      if (opts.horarioBase) {
        const baseResumen = _resumirHorario(opts.horarioBase);
        const appLbl = opts.appBase === 'warehouseMos' ? '📦 warehouseMos'
                     : opts.appBase === 'mosExpress'   ? '📱 mosExpress'
                     : '👑 MOS Admin';
        // [v2.43.34] Si el cache NO cargó, marcar visualmente y deshabilitar
        // el botón para que el operador no copie un horario falso (07-19).
        const fallback = opts.horarioBaseCargado === false;
        const banColor = fallback ? '#7c2d12' : '#1e1b4b';
        const banBord  = fallback ? '#ea580c' : '#4f46e5';
        const banResum = fallback ? '⏳ Cargando horario real…' : baseResumen;
        const btnDisab = fallback ? 'disabled style="opacity:.4;cursor:not-allowed"' : '';
        html += `<div class="hor-base-banner" style="background:${banColor};border:1px solid ${banBord};border-radius:10px;padding:10px 12px;margin-bottom:12px;display:flex;align-items:center;gap:10px;flex-wrap:wrap">
          <span style="font-size:18px">${fallback ? '⚠' : '📋'}</span>
          <div style="flex:1;min-width:180px">
            <div style="font-size:10px;color:${fallback ? '#fed7aa' : '#a5b4fc'};font-weight:700;text-transform:uppercase;letter-spacing:.5px">Base: ${appLbl}${fallback ? ' · sin conexión' : ''}</div>
            <div style="font-size:12px;color:${fallback ? '#fde68a' : '#e0e7ff'};margin-top:2px">${banResum}</div>
          </div>
          <button onclick="MOS._horResetABase()" ${btnDisab}
                  style="background:${fallback ? '#9ca3af' : '#4f46e5'};color:#fff;border:none;border-radius:6px;padding:6px 10px;font-size:11px;font-weight:700;cursor:pointer"
                  title="${fallback ? 'Esperando que cargue el horario real del app' : 'Volver al horario general del app'}">↻ Usar este</button>
        </div>`;
      }
      html += `<label class="hor-toggle-row">
        <input type="checkbox" id="horCustomActivo" ${opts.activoToggle ? 'checked' : ''}>
        <span class="hor-toggle-track"><span class="hor-toggle-dot"></span></span>
        <span class="hor-toggle-lbl">Habilitar horario personal</span>
      </label>
      <div class="hor-toggle-hint">${opts.teniaCustom ? 'OFF = elimina el custom y vuelve al horario general' : 'OFF = se descarta este horario; queda usando el general'}</div>`;
    }

    // Bloque horario general
    html += `<div class="hor-general-box">
      <div class="hor-section-ttl">⏰ Horario general</div>
      <div class="hor-general-row">
        <div class="hor-general-field">
          <span class="hor-general-lbl">Apertura</span>
          <select class="hor-hr-select" id="horGenAp">${_hrOpts(general.apertura)}</select>
        </div>
        <span class="hor-arrow-big">→</span>
        <div class="hor-general-field">
          <span class="hor-general-lbl">Cierre</span>
          <select class="hor-hr-select" id="horGenCi">${_hrOpts(general.cierre)}</select>
        </div>
      </div>
    </div>`;

    // Días activos
    html += `<div class="hor-section-ttl">📅 Días activos</div>
      <div class="hor-dias-pills">`;
    dias.forEach((d, i) => {
      html += `<label class="hor-pill ${d.activo ? 'is-on' : ''}">
        <input type="checkbox" class="hor-pill-cb" data-i="${i}" ${d.activo ? 'checked' : ''} onchange="MOS._horTogglePill(${i}, this.checked)">
        <span>${d.lbl}</span>
      </label>`;
    });
    html += `</div>`;

    // Horarios especiales por día (toggle opcional)
    html += `<div class="hor-section-ttl" style="margin-top:14px">⭐ Horarios especiales <span class="hor-section-hint">(opcional, por día)</span></div>
      <div class="hor-esp-list" id="horEspList">`;
    dias.forEach((d, i) => {
      const especialChecked = d.especial ? 'checked' : '';
      const disabledAttr = d.activo ? '' : 'data-disabled="1"';
      html += `<div class="hor-esp-row ${d.especial ? 'is-esp' : ''}" data-i="${i}" ${disabledAttr}>
        <label class="hor-esp-check">
          <input type="checkbox" class="hor-esp-cb" data-i="${i}" ${especialChecked} ${d.activo ? '' : 'disabled'} onchange="MOS._horToggleEsp(${i}, this.checked)">
          <span class="hor-esp-lbl">${d.lbl}</span>
        </label>
        <div class="hor-esp-times" style="${d.especial ? '' : 'display:none'}">
          <select class="hor-hr-select hor-esp-ap" data-i="${i}">${_hrOpts(d.apertura)}</select>
          <span class="hor-arrow">→</span>
          <select class="hor-hr-select hor-esp-ci" data-i="${i}">${_hrOpts(d.cierre)}</select>
        </div>
        <span class="hor-esp-hint" style="${d.especial ? 'display:none' : ''}">${d.activo ? 'usa general' : 'cerrado'}</span>
      </div>`;
    });
    html += `</div>`;

    if (opts.modoApp) {
      html += `<label class="hor-toggle-row" style="margin-top:14px">
        <input type="checkbox" id="horAdminsLibres" ${opts.adminsLibres !== false ? 'checked' : ''}>
        <span class="hor-toggle-track"><span class="hor-toggle-dot"></span></span>
        <span class="hor-toggle-lbl">👑 MASTER/ADMIN sin restricción</span>
      </label>`;
    } else {
      html += `<div class="hor-motivo-wrap">
        <label class="hor-motivo-lbl">💬 Motivo (visible para admin)</label>
        <input type="text" id="horMotivo" class="hor-motivo-input" placeholder="Ej: Solo turno tarde" value="${_escapeHtml(opts.motivoActual || '')}">
      </div>`;
    }
    html += `<div class="hor-modal-footer">`;
    if (!opts.modoApp) {
      html += `<button class="hor-btn-del" onclick="MOS._horEliminarCustomDesdeModal()">Eliminar</button>`;
    }
    html += `<button class="hor-btn-cancel" onclick="MOS.cerrarModalHorario()">Cancelar</button>
        <button class="hor-btn-save" style="background:linear-gradient(135deg,${opts.accent},${opts.accent}cc)" onclick="MOS._horGuardarModal()">💾 Guardar</button>
      </div></div></div></div>`;
    const old = $('modalHorarioWrap');
    if (old) old.remove();
    document.body.insertAdjacentHTML('beforeend', html);
    window._horModalOpts = opts;
    window._horModalDiasState = dias;
  }
  // Helpers
  function _hrOnly(s) {
    if (!s) return '07';
    const m = String(s).match(/^(\d{1,2})/);
    return m ? String(parseInt(m[1], 10)).padStart(2, '0') : '07';
  }
  function _hrOpts(sel) {
    let h = '';
    for (let i = 0; i < 24; i++) {
      const v = String(i).padStart(2, '0');
      h += `<option value="${v}" ${v === sel ? 'selected' : ''}>${v} h</option>`;
    }
    return h;
  }
  function _horTogglePill(i, checked) {
    const dias = window._horModalDiasState || [];
    if (dias[i]) dias[i].activo = checked;
    document.querySelectorAll('.hor-pill')[i]?.classList.toggle('is-on', checked);
    // Sync con hor-esp-row
    const espRow = document.querySelector(`.hor-esp-row[data-i="${i}"]`);
    if (espRow) {
      const cb = espRow.querySelector('.hor-esp-cb');
      const hint = espRow.querySelector('.hor-esp-hint');
      if (!checked) {
        if (cb) { cb.checked = false; cb.disabled = true; }
        espRow.classList.remove('is-esp');
        espRow.querySelector('.hor-esp-times').style.display = 'none';
        if (hint) { hint.style.display = ''; hint.textContent = 'cerrado'; }
      } else {
        if (cb) cb.disabled = false;
        if (hint) { hint.textContent = 'usa general'; hint.style.display = ''; }
      }
    }
    try { _opsBeep && _opsBeep('tac'); } catch(_){}
  }
  function _horToggleEsp(i, checked) {
    const row = document.querySelector(`.hor-esp-row[data-i="${i}"]`);
    if (!row) return;
    row.classList.toggle('is-esp', checked);
    row.querySelector('.hor-esp-times').style.display = checked ? '' : 'none';
    const hint = row.querySelector('.hor-esp-hint');
    if (hint) hint.style.display = checked ? 'none' : '';
    try { _opsBeep && _opsBeep('tac'); } catch(_){}
  }

  // [v2.43.33] Reset al horario base del app — rehidrata todos los controles
  // del modal personal a partir del horarioBase guardado en opts.
  function _horResetABase() {
    const opts = window._horModalOpts;
    if (!opts || !opts.horarioBase) return;
    const base = opts.horarioBase;
    // Recalcular general más frecuente del base
    const counts = {};
    _DIAS_HOR.forEach(d => {
      const c = base[d.k] || {};
      if (c.activo === false) return;
      const ap = _hrOnly(c.apertura);
      const ci = _hrOnly(c.cierre);
      const k = `${ap}-${ci}`;
      counts[k] = (counts[k] || 0) + 1;
    });
    let general = { ap: '07', ci: '19' };
    let best = 0;
    Object.entries(counts).forEach(([k, n]) => {
      if (n > best) { best = n; const [a, c] = k.split('-'); general = { ap: a, ci: c }; }
    });
    // Aplicar general a los selects
    const gAp = document.getElementById('horGenAp');
    const gCi = document.getElementById('horGenCi');
    if (gAp) gAp.value = general.ap;
    if (gCi) gCi.value = general.ci;
    // Pills de días + estado especial por día
    const dias = window._horModalDiasState || [];
    _DIAS_HOR.forEach((d, i) => {
      const c = base[d.k] || { activo: true };
      const activo = c.activo !== false;
      const ap = _hrOnly(c.apertura);
      const ci = _hrOnly(c.cierre);
      const especial = activo && (ap !== general.ap || ci !== general.ci);
      // Actualizar estado interno
      if (dias[i]) { dias[i].activo = activo; dias[i].apertura = ap; dias[i].cierre = ci; dias[i].especial = especial; }
      // Pill
      const pillCb = document.querySelectorAll('.hor-pill-cb')[i];
      const pill   = document.querySelectorAll('.hor-pill')[i];
      if (pillCb) pillCb.checked = activo;
      if (pill)   pill.classList.toggle('is-on', activo);
      // Especial
      const espRow = document.querySelector(`.hor-esp-row[data-i="${i}"]`);
      if (espRow) {
        const espCb = espRow.querySelector('.hor-esp-cb');
        const espAp = espRow.querySelector('.hor-esp-ap');
        const espCi = espRow.querySelector('.hor-esp-ci');
        const espTimes = espRow.querySelector('.hor-esp-times');
        const espHint  = espRow.querySelector('.hor-esp-hint');
        if (espCb) { espCb.checked = especial; espCb.disabled = !activo; }
        if (espAp) espAp.value = ap;
        if (espCi) espCi.value = ci;
        espRow.classList.toggle('is-esp', especial);
        if (espTimes) espTimes.style.display = especial ? '' : 'none';
        if (espHint)  { espHint.style.display = especial ? 'none' : ''; espHint.textContent = activo ? 'usa general' : 'cerrado'; }
      }
    });
    try { _opsBeep && _opsBeep('ok'); } catch(_){}
    toast('🔄 Horario base aplicado', 'info', 1800);
  }
  function cerrarModalHorario() {
    const m = $('modalHorarioWrap');
    if (m) m.remove();
    window._horModalOpts = null;
    window._horModalDiasState = null;
  }
  // Legacy compat (botones viejos pueden llamarlo)
  function _horGuardarModal() {
    const opts = window._horModalOpts;
    if (!opts) return;
    const genAp = ($('horGenAp')?.value || '07') + ':00';
    const genCi = ($('horGenCi')?.value || '19') + ':00';
    const horario = {};
    _DIAS_HOR.forEach((d, i) => {
      const pillCb = document.querySelectorAll('.hor-pill-cb')[i];
      const activo = pillCb ? pillCb.checked : true;
      if (!activo) {
        horario[d.k] = { activo: false, apertura: genAp, cierre: genCi };
        return;
      }
      // Activo: ¿tiene especial?
      const espRow = document.querySelector(`.hor-esp-row[data-i="${i}"]`);
      const espCb  = espRow?.querySelector('.hor-esp-cb');
      const usaEsp = espCb && espCb.checked;
      if (usaEsp) {
        const ap = (espRow.querySelector('.hor-esp-ap').value || '07') + ':00';
        const ci = (espRow.querySelector('.hor-esp-ci').value || '19') + ':00';
        horario[d.k] = { activo: true, apertura: ap, cierre: ci };
      } else {
        horario[d.k] = { activo: true, apertura: genAp, cierre: genCi };
      }
    });
    if (opts.modoApp) {
      const adminsLibres = $('horAdminsLibres')?.checked !== false;
      opts.onGuardar(horario, adminsLibres);
    } else {
      const activo = $('horCustomActivo')?.checked === true;
      const motivo = $('horMotivo')?.value || '';
      opts.onGuardar(horario, activo, motivo);
    }
  }
  function _horEliminarCustomDesdeModal() {
    const opts = window._horModalOpts;
    if (!opts || opts.modoApp) return;
    if ($('horCustomActivo')) $('horCustomActivo').checked = false;
    _horGuardarModal();
  }

  // Render unificado de card de persona con avatar, indicador online, switch y click
  // Para admins/master: agrega botón 🔑 + sección expandible con auditoría hoy
  function _renderPersonaCard(p, appOrigen) {
    const ini = ((p.nombre || '?')[0] + (p.apellido || '?')[0]).toUpperCase();
    const activo = String(p.estado) === '1';
    const act = _personaActividad(p.Ultima_Conexion || p.ultimaConexion);
    const isFresh = act.minutos < 5;
    const safeId = String(p.idPersonal || '').replace(/'/g, '&#39;');
    const claseFresh = isFresh ? 'disp-chip-live' : '';
    const dotPulse = isFresh ? '<span class="disp-dot-pulse"></span>' : '';
    const opacityCls = (!activo || p._tmp) ? 'opacity-60' : '';
    const glowBg = isFresh ? 'rgba(16,185,129,0.06)' : '#0d1526';
    const glowBorder = isFresh ? 'rgba(16,185,129,0.5)' : '#1e293b';

    const rolUp = String(p.rol || '').toUpperCase();
    const esAdmin = rolUp === 'MASTER' || rolUp === 'ADMIN' || rolUp === 'ADMINISTRADOR';
    const esWH = appOrigen === 'warehouseMos';

    // Última acción para admins (del cache de audit)
    let ultAccion = '';
    if (esAdmin && _personalAuditCache.length) {
      const propias = _personalAuditCache.filter(a => String(a.idPersonalAutoriza) === String(p.idPersonal));
      if (propias.length) {
        const ult = propias[0];
        const f = ult.fecha ? new Date(ult.fecha) : null;
        const fmt = f ? f.toLocaleTimeString('es-PE', { hour: '2-digit', minute: '2-digit' }) : '';
        ultAccion = `<div class="text-[9px] text-indigo-300 mt-1 truncate"><span class="opacity-70">${fmt}</span> · <span class="font-bold uppercase">${ult.accion || '—'}</span>${ult.refDocumento ? ' · ' + ult.refDocumento : ''}</div>`;
      }
    }

    // Botón 🔑 visible solo para admins/master
    const llaveBtn = esAdmin
      ? `<button onclick="event.stopPropagation();MOS.abrirModalClaveGlobal('${safeId}')"
                 class="text-[14px] p-1 rounded hover:bg-amber-500/20 hover:scale-110 transition-all"
                 title="Ver clave global">🔑</button>`
      : '';

    // Botón 💬 SIEMPRE visible (todos pueden recibir push). Círculo azul.
    const safeNombre = String(p.nombre || '').replace(/'/g, '&#39;');
    const pushBtn = `<button onclick="event.stopPropagation();MOS.abrirModalEnviarPush('${safeId}','${safeNombre}')"
                             class="shrink-0 w-8 h-8 rounded-full flex items-center justify-center hover:scale-110 transition-all"
                             style="background:rgba(59,130,246,0.15);border:1px solid rgba(59,130,246,0.5);color:#60a5fa;font-size:13px;"
                             title="Enviar mensaje push a ${p.nombre}">💬</button>`;

    // Botón 📜 Historial JSON — siempre visible (PERSONAL_MASTER.historialCambios)
    const histBtn = `<button onclick="event.stopPropagation();MOS.cfgHistorialPersonal('${safeId}','${safeNombre}')"
                             class="shrink-0 w-8 h-8 rounded-full flex items-center justify-center hover:scale-110 transition-all"
                             style="background:rgba(168,85,247,0.15);border:1px solid rgba(168,85,247,0.5);color:#c084fc;font-size:13px;"
                             title="Ver historial de cambios de ${p.nombre}">📜</button>`;

    // Botón 🕵️ ESPÍA (audio + gps combinados) — siempre visible para no-admins.
    // Si el usuario no está logueado en ningún dispositivo, abrirEspiaPorUsuario muestra toast.
    // Para admins/master se oculta: ellos usan el panel web, no tablets.
    const audioBtn = !esAdmin
      ? `<button onclick="event.stopPropagation();MOS.abrirEspiaPorUsuario('${safeNombre}')"
                 class="shrink-0 w-8 h-8 rounded-full flex items-center justify-center hover:scale-110 transition-all"
                 style="background:rgba(99,102,241,0.18);border:1px solid rgba(99,102,241,0.5);color:#a5b4fc;font-size:13px;"
                 title="Espiar a ${_escapeHtml(p.nombre)} (audio + GPS)">🕵️</button>`
      : '';
    const gpsBtn = '';

    // Audit hoy (solo admins)
    const auditExpand = esAdmin
      ? `<div id="auditDetail_${safeId}" class="hidden mt-2 p-3 rounded-lg" style="background:#0a1424;border:1px solid #1e293b;">
          <div class="text-[10px] font-bold text-slate-500 uppercase tracking-wider mb-2">📋 Acciones de hoy</div>
          <div id="auditList_${safeId}" class="space-y-1 text-[11px] text-slate-400">Cargando...</div>
          <button onclick="event.stopPropagation();MOS.abrirModalHistorialAudit('${safeId}','${(p.nombre || '').replace(/'/g, '&#39;')}')"
            class="mt-2 w-full text-[10px] text-indigo-400 hover:text-white py-1 rounded border border-dashed border-indigo-700/50 hover:border-indigo-500 transition-colors">
            Ver historial completo →
          </button>
        </div>`
      : '';

    // [v2.43.36 FIX VISUAL] El chip de excepciones ahora vive DENTRO del card oscuro.
    // Antes estaba fuera del div con background → "flotaba" suelto debajo del card.
    // Cambio el card a flex-col (no flex items-center) y meto la row de contenido
    // como hijo interno, dejando el chip como segunda fila dentro del mismo card.
    return `<div class="pers-card-wrap">
      <div class="disp-chip pers-card-clickable p-3 rounded-lg cursor-pointer ${claseFresh} ${opacityCls}"
        onclick="${esAdmin ? `MOS._togglePersAudit('${safeId}')` : `MOS.abrirModalPersonal('${safeId}','${appOrigen}')`}"
        style="background:${glowBg};border:1px solid ${glowBorder};transition:all 0.2s;position:relative;display:flex;flex-direction:column"
        title="${esAdmin ? 'Click para ver auditoría' : 'Click para editar'}">
        <div style="display:flex;align-items:center;gap:12px">
          <div class="relative shrink-0">
            <div class="w-10 h-10 rounded-full flex items-center justify-center text-white text-sm font-bold"
                 style="background:${p.color || '#6366f1'}">${ini}</div>
            ${dotPulse}
          </div>
          <div class="flex-1 min-w-0">
            <div class="font-medium text-sm text-slate-200 truncate">${p.nombre} ${p.apellido || ''}</div>
            <div class="flex items-center gap-2 mt-0.5 flex-wrap">
              <span class="badge badge-gray text-[9px] uppercase">${p.rol || '—'}</span>
              ${p.montoBase ? `<span class="text-[9px] text-slate-500">S/.${parseFloat(p.montoBase).toFixed(2)}/día</span>` : ''}
              <span class="text-[9px]" style="color:${act.color};">${act.dot} ${act.label}</span>
            </div>
            ${ultAccion}
          </div>
          ${audioBtn}
          ${gpsBtn}
          ${pushBtn}
          ${histBtn}
          ${llaveBtn}
          <label class="pers-switch shrink-0" title="${activo ? 'Desactivar' : 'Activar'}" onclick="event.stopPropagation()">
            <input type="checkbox" ${activo ? 'checked' : ''} onchange="MOS.togglePersonalActivo('${safeId}','${appOrigen}', event)">
            <span class="pers-switch-slider"></span>
          </label>
          <button onclick="event.stopPropagation();MOS.abrirModalPersonal('${safeId}','${appOrigen}')"
                  class="text-[10px] text-slate-500 hover:text-white p-1" title="Editar">✏️</button>
          <button onclick="event.stopPropagation();MOS.abrirModalHorarioCustom('${safeId}')"
                  class="text-[12px] text-slate-500 hover:text-violet-300 p-1" title="Horario custom">🕐</button>
        </div>
        ${_renderChipHorarioCustom(p)}
      </div>
      ${auditExpand}
    </div>`;
  }

  // Cache de auditoría (compartido entre cards y modal historial)
  let _personalAuditCache = []; // últimas N entradas
  let _personalIntegCount = 0;
  let _personalNotifCount = 0;

  // Chip de meta editable inline (click → input)
  // Chips bonitos de política dentro de la card de cada zona en Infra.
  // Para zonas POS: meta diaria, comisión %, meta auditorías
  // Para almacén: tarifa envasado, meta guías, meta auditorías (de CONFIG_MOS)
  // [Fase2] App + horario por zona. La app se deriva: almacén→warehouseMos, resto→mosExpress.
  // (La zona Premium/MOS se renderiza aparte en _renderInfraPremium con su propia app MOS.)
  function _zonaAppKey(z) { return _esZonaAlmacen(z) ? 'warehouseMos' : 'mosExpress'; }
  // Horario de HOY (TZ Perú) resumido para el chip, o null si no hay cache/datos.
  function _horarioHoyTxt(app) {
    const conf = ((S && S._horariosAppsCache) || {})[app];
    if (!conf || !conf.horario) return null;
    let k = null;
    try {
      const wd = new Intl.DateTimeFormat('en-US', { timeZone: 'America/Lima', weekday: 'short' })
        .format(new Date()).toLowerCase().slice(0, 3);
      k = { mon: 'lun', tue: 'mar', wed: 'mie', thu: 'jue', fri: 'vie', sat: 'sab', sun: 'dom' }[wd];
    } catch (_) {}
    const c = (k && conf.horario[k]) || {};
    if (c.activo === false) return 'cerrado hoy';
    if (!c.apertura || !c.cierre) return null;
    return String(c.apertura).replace(':00', 'h') + '→' + String(c.cierre).replace(':00', 'h');
  }
  // ── Render compacto: meta + comisión POR ZONA ─────────────────
  // Reemplaza el chip global confuso. Cada zona se edita aparte abriendo
  // su modal de edición. Si no tiene política configurada → badge ⚠.
  function _renderMetasPorZona() {
    // Excluir zonas de almacén — no tienen política de venta. Sus reglas
    // (tarifa envasado + meta auditorías) viven en CONFIG_MOS global y se
    // editan desde la sección "Operadores Almacén".
    const zonas = (cfgData.zonas || []).filter(z => {
      const activa = String(z.estado) === '1' || z.estado === 1 || z.estado === true;
      return activa && !_esZonaAlmacen(z);
    });
    if (!zonas.length) {
      return `<div class="p-3 mb-3 rounded-lg text-[12px] text-slate-500 italic text-center"
                   style="background:#0a1424;border:1px dashed #334155">
        Sin zonas activas. Crea una zona en
        <a href="javascript:MOS.nav('config');setTimeout(()=>MOS.setCfgTab('infra'),50)"
           class="text-amber-400 hover:underline">Infraestructura</a> para configurar su meta diaria.
      </div>`;
    }
    const rows = zonas.map(z => {
      let pol = {};
      try {
        pol = z.politicaJSON ? (typeof z.politicaJSON === 'string' ? JSON.parse(z.politicaJSON) : z.politicaJSON) : {};
      } catch(_){}
      const meta    = parseFloat(pol.metaDiaria);
      const pct     = parseFloat(pol.comisionExcedentePct);
      const metaAud = parseFloat(pol.metaAuditorias);
      const hasMeta = !isNaN(meta) && meta > 0;
      const hasPct  = !isNaN(pct)  && pct  >= 0;
      const hasAud  = !isNaN(metaAud) && metaAud > 0;
      // [846] base diaria por rol que paga la zona
      const bCaj = parseFloat(pol.baseCajero), bVen = parseFloat(pol.baseVendedor);
      const hasBase = !isNaN(bCaj) && bCaj >= 0 && !isNaN(bVen) && bVen >= 0;
      const completa = hasMeta && hasPct;
      const idAttr = String(z.idZona).replace(/'/g, '&#39;');
      return `<div class="flex items-center gap-2 px-3 py-2 rounded-lg cursor-pointer transition-all hover:scale-[1.01]"
                   onclick="MOS.abrirModalZona('${idAttr}')"
                   style="background:rgba(245,158,11,0.06);border:1px solid ${completa ? 'rgba(245,158,11,0.3)' : 'rgba(248,113,113,0.4)'};">
        <span class="text-base flex-shrink-0">🏬</span>
        <div class="flex-1 min-w-0">
          <div class="text-[12px] font-bold text-amber-100 truncate">${String(z.nombre || z.idZona).replace(/[<>&]/g, c => ({'<':'&lt;','>':'&gt;','&':'&amp;'}[c]))}</div>
          <div class="flex flex-wrap items-center gap-x-3 gap-y-0.5 text-[11px] mt-0.5">
            <span class="${hasMeta ? 'text-amber-300' : 'text-red-400'}">
              <span class="opacity-70">Meta:</span>
              <span class="font-bold">${hasMeta ? 'S/ ' + meta.toFixed(0) : 'sin configurar'}</span>
            </span>
            <span class="${hasPct ? 'text-emerald-300' : 'text-red-400'}">
              <span class="opacity-70">Comisión:</span>
              <span class="font-bold">${hasPct ? pct + '%' : 'sin configurar'}</span>
            </span>
            <span class="${hasAud ? 'text-sky-300' : 'text-slate-500'}">
              <span class="opacity-70">Auditorías:</span>
              <span class="font-bold">${hasAud ? metaAud.toFixed(0) + '/día' : 'global'}</span>
            </span>
            <span class="${hasBase ? 'text-violet-300' : 'text-slate-500'}"
                  title="Base diaria que esta zona paga a cada persona según su rol">
              <span class="opacity-70">Base:</span>
              <span class="font-bold">${hasBase
                ? 'cajero S/ ' + _money(bCaj).toFixed(0) + ' · vendedor S/ ' + _money(bVen).toFixed(0)
                : 'global'}</span>
            </span>
          </div>
        </div>
        ${completa
          ? '<span class="text-[10px] opacity-50">✏️</span>'
          : '<span class="text-[10px] font-black text-red-400 px-2 py-0.5 rounded" style="background:rgba(248,113,113,0.15);border:1px solid rgba(248,113,113,0.4)">⚠ FALTA</span>'}
      </div>`;
    }).join('');
    return `<div class="mb-3 p-2.5 rounded-lg" style="background:rgba(0,0,0,0.18);border:1px dashed rgba(245,158,11,0.25)">
      <div class="text-[10px] uppercase tracking-wider text-amber-200/70 font-bold mb-2 px-1 flex items-center gap-1">
        <span>🎯</span><span>Metas y comisiones por zona</span>
      </div>
      <div class="space-y-1.5">${rows}</div>
    </div>`;
  }

  function _renderMetaChip(label, configKey, valor, unidad, color) {
    color = color || '#6366f1';
    const safeKey = String(configKey).replace(/'/g, '&#39;');
    return `<span class="meta-chip inline-flex items-center gap-2 px-3 py-1.5 rounded-lg cursor-pointer text-xs font-bold"
      onclick="MOS.editarMetaChip('${safeKey}', this)"
      data-meta-key="${safeKey}"
      data-meta-valor="${valor}"
      style="background:rgba(99,102,241,0.12);border:1px solid ${color};color:#c7d2fe;transition:all 0.2s;"
      title="Click para editar">
      <span class="text-[10px] opacity-80 uppercase">${label}</span>
      <span class="text-base font-black" style="color:${color}">${valor || '—'}</span>
      <span class="text-[10px] opacity-70">${unidad || ''}</span>
      <span class="text-[10px] opacity-50">✏️</span>
    </span>`;
  }

  function renderPersonal() {
    const cont = $('personalContenedor');
    if (!cont) return;

    const adminsMOS = (cfgData.personalMOS || []).filter(p => {
      const r = String(p.rol || '').toUpperCase();
      return r === 'MASTER' || r === 'ADMIN' || r === 'ADMINISTRADOR';
    });
    const operadoresWH = (cfgData.personal || []).filter(p =>
      String(p.rol || '').toUpperCase() !== 'SUPERVISOR'
    );

    // Contar online en cada grupo
    const _onlineCount = arr => arr.filter(p => _personaActividad(p.Ultima_Conexion || p.ultimaConexion).minutos < 5).length;
    const onlineMOS = _onlineCount(adminsMOS);
    const onlineWH  = _onlineCount(operadoresWH);
    // ME vendedores: contar dispositivos con sesión <5min cuyo Ultima_Sesion sea de un cajero
    const onlineME = (cfgData.dispositivos || []).filter(d => {
      if (String(d.Estado).toUpperCase() !== 'ACTIVO') return false;
      if (!d.Ultima_Sesion) return false;
      return _personaActividad(d.Ultima_Conexion).minutos < 5;
    }).length;

    // Metas (de cfgData.config si existe; si no, leerá vacío y guardará al editar)
    const cfg = (cfgData.config || {});
    // metaCajero ya no se muestra como chip global — cada zona se configura
    // por separado en _renderMetasPorZona (Infraestructura → modal Zona).
    const metaEnvasador  = cfg.evalMetaEnvasador  || '';
    const metaAlmacenero = cfg.evalMetaAlmacenero || '';
    const metaAuditorias = cfg.evalMetaAuditorias || '';
    const tarifaEnvasado = cfg.evalTarifaEnvasadoPorUnidad != null ? cfg.evalTarifaEnvasadoPorUnidad : '0.10';

    // ── Grupo 1: ADMIN/MASTER (MOS) ─────
    const grupoMOS = `<div class="card p-4" style="background:linear-gradient(135deg,#1e1b4b 0%,#0d1526 100%);border:1px solid #6366f1;">
      <div class="flex items-start justify-between gap-3 mb-3 flex-wrap">
        <div class="flex items-center gap-3">
          <span class="text-2xl">👑</span>
          <div>
            <div class="flex items-center gap-2">
              <h3 class="text-base font-black text-white">Administradores</h3>
              ${onlineMOS > 0 ? `<span class="badge text-[10px] disp-chip-live" style="background:rgba(16,185,129,0.18);color:#6ee7b7;border:1px solid rgba(16,185,129,0.5);">🟢 ${onlineMOS} online</span>` : ''}
            </div>
            <p class="text-[11px] text-slate-400 mt-0.5">MOS · acceso al panel · gestión global · ${adminsMOS.length} total</p>
          </div>
        </div>
        <button class="btn-primary text-xs px-3 py-1.5" onclick="MOS.abrirModalPersonal(null,'MOS')">+ admin</button>
      </div>
      <!-- [v2.43.31] Card horario app MOS -->
      ${_renderHorarioAppCard('MOS', '#6366f1')}
      ${adminsMOS.length === 0
        ? '<p class="text-center py-4 text-slate-500 text-sm">Sin admins/master registrados</p>'
        : `<div class="space-y-2">${adminsMOS.map(p => _renderPersonaCard(p, 'MOS')).join('')}</div>`}
    </div>`;

    // ── Grupo 2: VENDEDORES (ME) — usa el render de cajeros existente ─
    const grupoME = `<div class="card p-4" style="background:linear-gradient(135deg,#451a03 0%,#0d1526 100%);border:1px solid #f59e0b;">
      <div class="flex items-start justify-between gap-3 mb-3 flex-wrap">
        <div class="flex items-center gap-3">
          <span class="text-2xl">🛒</span>
          <div>
            <div class="flex items-center gap-2">
              <h3 class="text-base font-black text-white">Vendedores / Cajeros</h3>
              ${onlineME > 0 ? `<span class="badge text-[10px] disp-chip-live" style="background:rgba(16,185,129,0.18);color:#6ee7b7;border:1px solid rgba(16,185,129,0.5);">🟢 ${onlineME} online</span>` : ''}
            </div>
            <p class="text-[11px] text-slate-400 mt-0.5">MosExpress · cajeros que operan POS</p>
          </div>
        </div>
        <button class="btn-primary text-xs px-3 py-1.5" onclick="MOS.abrirModalPersonal(null,'mosExpress')">+ cajero/vendedor</button>
      </div>

      <!-- [v2.43.30] Card horario app ME -->
      ${_renderHorarioAppCard('mosExpress', '#f59e0b')}

      <!-- Metas y comisiones POR ZONA — cada zona se edita aparte (click → modal Zona) -->
      ${_renderMetasPorZona()}

      <div id="listMeCajeros" class="space-y-2"></div>
      <span id="cfgMeCajerosCount" class="hidden"></span>
    </div>`;

    // ── Grupo 3: OPERADORES WH (almacenero + envasador juntos) ─
    const grupoWH = `<div class="card p-4" style="background:linear-gradient(135deg,#0d1526 0%,#7c2d12 0%,#0d1526 100%);border:1px solid #ea580c;">
      <div class="flex items-start justify-between gap-3 mb-3 flex-wrap">
        <div class="flex items-center gap-3">
          <span class="text-2xl">🏭</span>
          <div>
            <div class="flex items-center gap-2">
              <h3 class="text-base font-black text-white">Operadores Almacén</h3>
              ${onlineWH > 0 ? `<span class="badge text-[10px] disp-chip-live" style="background:rgba(16,185,129,0.18);color:#6ee7b7;border:1px solid rgba(16,185,129,0.5);">🟢 ${onlineWH} online</span>` : ''}
            </div>
            <p class="text-[11px] text-slate-400 mt-0.5">warehouseMos · almaceneros + envasadores · ${operadoresWH.length} total</p>
          </div>
        </div>
        <div class="flex flex-wrap gap-1.5">
          ${_renderMetaChip('Meta guías', 'evalMetaAlmacenero', metaAlmacenero, '/día', '#ea580c')}
          ${_renderMetaChip('Tarifa envasado', 'evalTarifaEnvasadoPorUnidad', tarifaEnvasado, 'S/und', '#10b981')}
          ${_renderMetaChip('Auditorías almacén', 'evalMetaAuditorias', metaAuditorias, '/día', '#fbbf24')}
        </div>
        <button class="btn-primary text-xs px-3 py-1.5" onclick="MOS.abrirModalPersonal(null,'warehouseMos')">+ operador</button>
      </div>
      <!-- [v2.43.30] Card horario app WH -->
      ${_renderHorarioAppCard('warehouseMos', '#ea580c')}
      ${operadoresWH.length === 0
        ? '<p class="text-center py-4 text-slate-500 text-sm">Sin operadores registrados</p>'
        : `<div class="space-y-2">${operadoresWH.map(p => _renderPersonaCard(p, 'warehouseMos')).join('')}</div>`}
    </div>`;

    cont.innerHTML = grupoMOS + grupoME + grupoWH;

    // Renderizar cajeros ME (usa cache de liquidaciones existente)
    _cfgRenderMeCajeros();

    // Cargar audit log para mostrar última acción de cada admin (background)
    if (!_personalAuditCache.length) {
      API.get('getAuditoriaAdmin', { limit: 50 })
        .then(data => {
          if (Array.isArray(data)) {
            _personalAuditCache = data;
            renderPersonal(); // re-render para incluir últimas acciones
          }
        })
        .catch(_ => {});
    }
    // Actualizar badges
    _actualizarBadgesPersonal();

    // [Fase2] La pestaña Personal se fusionó en Infraestructura (usuarios por zona). Cualquier
    // mutación de persona (alta/edición/toggle) llama renderPersonal aunque el panel esté oculto;
    // si estamos viendo Infra, refrescamos esa vista para que el cambio aparezca en las zonas 👥.
    if (S.cfgTab === 'infra' && $('infraContenedor')) renderInfra();
  }

  // Editar meta inline (chip → input → guardar al blur/enter)
  function editarMetaChip(configKey, chipEl) {
    const valorActual = chipEl.dataset.metaValor || '';
    const label = chipEl.querySelector('span:first-child')?.textContent || configKey;
    chipEl.outerHTML = `<span class="inline-flex items-center gap-2 px-2 py-1 rounded-lg" style="background:rgba(99,102,241,0.12);border:1px solid #6366f1;">
      <span class="text-[10px] text-slate-300 uppercase">${label}</span>
      <input type="number" id="metaInput_${configKey}" value="${valorActual}" autofocus
        onblur="MOS.guardarMetaChip('${configKey}', this.value)"
        onkeydown="if(event.key==='Enter')this.blur(); if(event.key==='Escape'){this.value='${valorActual}';this.blur();}"
        class="bg-slate-900 text-white text-sm font-black px-2 py-0.5 rounded border border-indigo-500 outline-none w-24"
        style="-moz-appearance:textfield;">
    </span>`;
    setTimeout(() => $('metaInput_' + configKey)?.focus(), 50);
  }

  // ────────────────────────────────────────────────────────
  // MODAL CLAVE GLOBAL (abierto desde card master/admin con 🔑)
  // ────────────────────────────────────────────────────────
  let _cgDataActual = null;

  function abrirModalClaveGlobal(idPersonal) {
    const p = (cfgData.personalMOS || []).find(x => x.idPersonal === idPersonal);
    if (!p) return;
    $('claveGlobalIdPersonal').value = p.idPersonal;
    $('claveGlobalRol').value = String(p.rol || '').toUpperCase();
    $('claveGlobalSubtitle').textContent = `${p.nombre} (${p.rol})`;
    $('claveGlobalPin').value = '';
    $('claveGlobalError').textContent = '';
    $('claveGlobalLogin').classList.remove('hidden');
    $('claveGlobalRevelada').classList.add('hidden');
    // Si es admin (no master), ocultar botón rotar
    const esMaster = String(p.rol || '').toUpperCase() === 'MASTER';
    const btnRotar = $('claveGlobalBtnRotar');
    if (btnRotar) btnRotar.style.display = esMaster ? '' : 'none';
    openModal('modalClaveGlobal');
    setTimeout(() => $('claveGlobalPin')?.focus(), 100);
  }

  async function cgConsultar() {
    const pin = String($('claveGlobalPin')?.value || '').trim();
    const err = $('claveGlobalError');
    if (!/^\d{4}$/.test(pin)) {
      if (err) err.textContent = 'PIN debe ser de 4 dígitos';
      return;
    }
    if (err) err.textContent = '';

    // 🚀 OPTIMISTA: revelar el panel YA con skeleton shimmer mientras llega
    // el fetch. Si el PIN falla, volvemos al login.
    const loginBox = $('claveGlobalLogin');
    const revBox   = $('claveGlobalRevelada');
    const digEl    = $('claveGlobalDigits');
    if (loginBox && revBox) {
      loginBox.classList.add('hidden');
      revBox.classList.remove('hidden');
      if (digEl) digEl.innerHTML = '<span class="cg-skel-pin cg-skel-pin-lg"></span>';
    }

    try {
      const data = await API.get('getClaveAdminGlobal', { pinAdmin: pin });
      if (!data?.autorizado) {
        // PIN malo → volver al login con error
        if (revBox) revBox.classList.add('hidden');
        if (loginBox) loginBox.classList.remove('hidden');
        if (err) err.textContent = data?.error || 'PIN incorrecto';
        $('claveGlobalPin').value = '';
        return;
      }
      _cgDataActual = data;
      _cgPintar(data);
      // Actualizar caché global del avatar menú
      if (typeof _segActualizarCacheLocal === 'function') _segActualizarCacheLocal(data);
    } catch(e) {
      if (revBox) revBox.classList.add('hidden');
      if (loginBox) loginBox.classList.remove('hidden');
      if (err) err.textContent = e?.message || 'Sin conexión';
    }
  }

  function _cgPintar(data) {
    $('claveGlobalDigits').textContent = (data.pin || '----').split('').join(' ');
    const dias = data.diasParaProximaRotacion;
    const dr = $('claveGlobalDias');
    if (data.vencida) { dr.textContent = '⚠ Vencida'; dr.style.color = '#f87171'; }
    else if (dias <= 5) { dr.textContent = dias + ' días'; dr.style.color = '#fbbf24'; }
    else { dr.textContent = dias + ' días'; dr.style.color = '#10b981'; }
    const pct = Math.max(0, Math.min(100, ((30 - dias) / 30) * 100));
    $('claveGlobalProgreso').style.width = pct + '%';
    if (data.fechaProximaRotacion) {
      const f = new Date(data.fechaProximaRotacion);
      $('claveGlobalFechaProxima').textContent = 'Próxima: ' + f.toLocaleDateString('es-PE', { day: 'numeric', month: 'long', year: 'numeric' });
    }
    $('claveGlobalLogin').classList.add('hidden');
    $('claveGlobalRevelada').classList.remove('hidden');
  }

  async function cgRotar() {
    const pin = String($('claveGlobalPin')?.value || '').trim();
    if (!/^\d{4}$/.test(pin)) {
      toast('PIN inválido', 'error'); return;
    }
    if (!await _modalConfirm('¿Generar una nueva clave global aleatoria?\n\nLa clave actual dejará de funcionar inmediatamente en MosExpress y warehouseMos.', { danger: true, titulo: 'Rotar clave admin global', okText: 'Rotar ahora' })) return;
    try {
      const data = await API.post('rotarClaveAdminGlobal', { manual: true, pinAdmin: pin });
      if (!data?.autorizado && data?.error) { toast(data.error, 'error'); return; }
      _cgDataActual = {
        pin: data.pin, fechaUltimaRotacion: data.fechaUltimaRotacion,
        fechaProximaRotacion: data.fechaProximaRotacion,
        diasDesdeRotacion: 0, diasParaProximaRotacion: 30, vencida: false
      };
      _cgPintar(_cgDataActual);
      if (typeof _segActualizarCacheLocal === 'function') _segActualizarCacheLocal(_cgDataActual);
      toast('Clave rotada · ' + data.pin, 'ok');
    } catch(e) {
      toast(e?.message || 'Error', 'error');
    }
  }

  // ────────────────────────────────────────────────────────
  // AUDITORÍA EXPANDIBLE EN CARD ADMIN
  // ────────────────────────────────────────────────────────
  function _togglePersAudit(idPersonal) {
    const safeId = String(idPersonal).replace(/'/g, '&#39;');
    const det = $('auditDetail_' + safeId);
    if (!det) return;
    if (det.classList.contains('hidden')) {
      det.classList.remove('hidden');
      _cargarAuditDetail(idPersonal);
    } else {
      det.classList.add('hidden');
    }
  }

  async function _cargarAuditDetail(idPersonal) {
    const list = $('auditList_' + idPersonal);
    if (!list) return;
    // Filtrar de cache si hay; si no, cargar
    const propiasHoy = _personalAuditCache.filter(a => {
      if (String(a.idPersonalAutoriza) !== String(idPersonal)) return false;
      const f = new Date(a.fecha);
      const hoy = new Date();
      return f.toDateString() === hoy.toDateString();
    });
    if (!propiasHoy.length) {
      list.innerHTML = '<div class="text-[10px] text-slate-600 italic">Sin acciones registradas hoy.</div>';
      return;
    }
    list.innerHTML = propiasHoy.slice(0, 8).map(a => {
      const f = a.fecha ? new Date(a.fecha) : null;
      const hora = f ? f.toLocaleTimeString('es-PE', { hour: '2-digit', minute: '2-digit' }) : '—';
      const accColor = {
        'ANULACION': 'text-red-400', 'CREDITO': 'text-amber-400', 'CAMBIO_METODO': 'text-blue-400',
        'REABRIR_GUIA': 'text-purple-400', 'DESBLOQUEO_USUARIO': 'text-emerald-400', 'ROTACION_PIN_GLOBAL': 'text-pink-400'
      }[String(a.accion || '').toUpperCase()] || 'text-slate-400';
      return `<div class="flex items-center gap-2">
        <span class="text-slate-600 text-[10px]">${hora}</span>
        <span class="${accColor} font-bold uppercase tracking-wider text-[10px]">${a.accion || '—'}</span>
        <span class="text-slate-500 truncate flex-1">${a.refDocumento || ''}</span>
      </div>`;
    }).join('');
  }

  // ────────────────────────────────────────────────────────
  // MODAL HISTORIAL COMPLETO DE AUDITORÍA (agrupado por fecha)
  // ────────────────────────────────────────────────────────
  let _histAuditFiltroPersonal = null;

  function abrirModalHistorialAudit(idPersonal, nombre) {
    _histAuditFiltroPersonal = idPersonal || null;
    $('histAuditSubtitle').textContent = nombre ? `Acciones de ${nombre}` : 'Todas las acciones';
    $('histAuditFiltroAccion').value = '';
    openModal('modalHistorialAudit');
    histAuditCargar();
  }

  async function histAuditCargar() {
    const cont = $('histAuditContenido');
    if (!cont) return;
    cont.innerHTML = '<div class="text-center py-8 text-slate-500 text-sm">Cargando...</div>';
    try {
      const data = await API.get('getAuditoriaAdmin', { limit: 200 });
      _personalAuditCache = Array.isArray(data) ? data : [];
      histAuditFiltrar();
    } catch(e) {
      cont.innerHTML = '<div class="text-center py-6 text-red-400 text-sm">Error: ' + e.message + '</div>';
    }
  }

  function histAuditFiltrar() {
    const cont = $('histAuditContenido');
    if (!cont) return;
    let rows = _personalAuditCache.slice();
    if (_histAuditFiltroPersonal) {
      rows = rows.filter(a => String(a.idPersonalAutoriza) === String(_histAuditFiltroPersonal));
    }
    const filtroAcc = $('histAuditFiltroAccion')?.value || '';
    if (filtroAcc) rows = rows.filter(a => String(a.accion || '').toUpperCase() === filtroAcc);
    if (!rows.length) {
      cont.innerHTML = '<div class="text-center py-8 text-slate-500 text-sm">Sin registros para los filtros aplicados.</div>';
      return;
    }
    // Agrupar por fecha
    const grupos = {};
    rows.forEach(a => {
      const f = a.fecha ? new Date(a.fecha) : null;
      const key = f ? f.toISOString().substring(0, 10) : '—';
      if (!grupos[key]) grupos[key] = [];
      grupos[key].push(a);
    });
    const keys = Object.keys(grupos).sort().reverse();
    cont.innerHTML = keys.map(k => {
      const f = new Date(k);
      const lbl = isNaN(f.getTime()) ? k : f.toLocaleDateString('es-PE', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' });
      const acciones = grupos[k];
      return `<div class="card p-3" style="background:#0d1526;border:1px solid #1e293b;">
        <div class="flex items-center justify-between mb-2">
          <div class="text-xs font-bold text-white uppercase">${lbl}</div>
          <span class="badge badge-gray text-[9px]">${acciones.length} acción${acciones.length === 1 ? '' : 'es'}</span>
        </div>
        <div class="space-y-1.5">
          ${acciones.map(a => {
            const fa = a.fecha ? new Date(a.fecha) : null;
            const hora = fa ? fa.toLocaleTimeString('es-PE', { hour: '2-digit', minute: '2-digit' }) : '—';
            const accColor = {
              'ANULACION': '#f87171', 'CREDITO': '#fbbf24', 'CAMBIO_METODO': '#60a5fa',
              'REABRIR_GUIA': '#a78bfa', 'DESBLOQUEO_USUARIO': '#34d399', 'ROTACION_PIN_GLOBAL': '#f472b6'
            }[String(a.accion || '').toUpperCase()] || '#94a3b8';
            return `<div class="flex items-center gap-2 text-[11px] py-1 px-2 rounded" style="background:#0a1424;">
              <span class="text-slate-500 font-mono">${hora}</span>
              <span class="font-bold uppercase tracking-wider" style="color:${accColor}">${a.accion || '—'}</span>
              <span class="text-slate-300 flex-1 truncate">${a.nombreAutoriza || '—'}</span>
              <span class="text-slate-500 text-[10px] hidden sm:inline">${a.appOrigen || ''}</span>
              <span class="text-slate-500 text-[10px] font-mono truncate hidden md:inline" style="max-width:120px;">${a.refDocumento || ''}</span>
            </div>`;
          }).join('')}
        </div>
      </div>`;
    }).join('');
  }

  // ────────────────────────────────────────────────────────
  // MODAL INTEGRIDAD (alertas)
  // ────────────────────────────────────────────────────────
  function abrirModalIntegridad() {
    openModal('modalIntegridad');
    if (typeof renderIntegridad === 'function') renderIntegridad();
  }

  // ────────────────────────────────────────────────────────
  // MODAL NOTIFICACIONES UNIFICADAS
  // ────────────────────────────────────────────────────────
  function abrirModalNotificaciones() {
    openModal('modalNotificaciones');
    _renderNotificaciones();
  }

  function _renderNotificaciones() {
    const cont = $('notifContenido');
    if (!cont) return;
    const partes = [];
    let total = 0;

    // 1) Dispositivos pendientes
    const pendDisp = (cfgData.dispositivos || []).filter(d => String(d.Estado).toUpperCase() === 'PENDIENTE_APROBACION');
    if (pendDisp.length) {
      total += pendDisp.length;
      partes.push(`<div class="card p-3" style="background:#3b1010;border:1px solid #ef4444;">
        <div class="flex items-center gap-2 mb-2">
          <span class="text-xl">📱</span>
          <strong class="text-white text-sm">Dispositivos esperando aprobación</strong>
          <span class="badge badge-red text-[10px] ml-auto">${pendDisp.length}</span>
        </div>
        <div class="space-y-1.5">
          ${pendDisp.slice(0, 5).map(d => `<div class="text-[11px] text-slate-300 px-2 py-1 rounded flex items-center gap-1.5 flex-wrap" style="background:#0a1424;">
            <span>${_dispIcono(d.Nombre_Equipo)} ${d.Nombre_Equipo || 'Nuevo'}</span>
            ${_appBadge(d.App, { compact: false })}
            <span class="text-slate-600">·</span>
            <span class="text-slate-500 font-mono">${String(d.ID_Dispositivo).substring(0, 8)}...</span>
          </div>`).join('')}
        </div>
        <button onclick="MOS.closeModal('modalNotificaciones');MOS.nav('config');MOS.setCfgTab('infra')" class="mt-2 text-[10px] text-red-300 hover:text-red-200">Ver en Infraestructura →</button>
      </div>`);
    }

    // 2) Bloqueos vendedores ME activos
    const bloqs = (cfgData.bloqueosME || []).filter(b => b.fechaBloqueo && !b.unlockVigente);
    if (bloqs.length) {
      total += bloqs.length;
      partes.push(`<div class="card p-3" style="background:#3b2410;border:1px solid #f59e0b;">
        <div class="flex items-center gap-2 mb-2">
          <span class="text-xl">🔒</span>
          <strong class="text-white text-sm">Cajeros bloqueados</strong>
          <span class="badge badge-yellow text-[10px] ml-auto">${bloqs.length}</span>
        </div>
        <div class="space-y-1.5">
          ${bloqs.slice(0, 5).map(b => `<div class="text-[11px] text-slate-300 px-2 py-1 rounded" style="background:#0a1424;">
            👤 ${b.nombre} <span class="text-slate-600">·</span> <span class="text-slate-500">${b.motivo || ''}</span>
          </div>`).join('')}
        </div>
      </div>`);
    }

    // 3) Integridad alertas
    if (_personalIntegCount > 0) {
      total += _personalIntegCount;
      partes.push(`<div class="card p-3" style="background:#3b1010;border:1px solid #dc2626;">
        <div class="flex items-center gap-2 mb-2">
          <span class="text-xl">🛡️</span>
          <strong class="text-white text-sm">Integridad de catálogo</strong>
          <span class="badge badge-red text-[10px] ml-auto">${_personalIntegCount}</span>
        </div>
        <p class="text-[11px] text-slate-400">Hay alertas de seguridad en PRODUCTOS_MASTER o EQUIVALENCIAS.</p>
        <button onclick="MOS.closeModal('modalNotificaciones');MOS.abrirModalIntegridad()" class="mt-2 text-[10px] text-red-300 hover:text-red-200">Revisar →</button>
      </div>`);
    }

    if (total === 0) {
      cont.innerHTML = `<div class="text-center py-12 text-slate-500">
        <div class="text-5xl mb-3">✨</div>
        <p class="font-bold text-emerald-400">Todo en orden</p>
        <p class="text-xs">Sin notificaciones pendientes.</p>
      </div>`;
      $('notifSubtitle').textContent = 'Sin pendientes';
    } else {
      cont.innerHTML = partes.join('');
      $('notifSubtitle').textContent = `${total} pendiente${total === 1 ? '' : 's'}`;
    }
  }

  // ────────────────────────────────────────────────────────
  // MODAL ENVIAR PUSH a usuario
  // ────────────────────────────────────────────────────────
  function abrirModalEnviarPush(idPersonal, nombre) {
    $('pushDestinoUsuario').value = nombre || '';
    $('pushDestinoNombre').textContent = `a ${nombre || 'usuario'}`;
    $('pushTitulo').value = '📢 Mensaje del admin';
    $('pushCuerpo').value = '';
    openModal('modalEnviarPush');
    setTimeout(() => $('pushCuerpo')?.focus(), 100);
  }

  async function enviarPushUsuario() {
    const titulo = String($('pushTitulo')?.value || '').trim();
    const cuerpo = String($('pushCuerpo')?.value || '').trim();
    const dest = String($('pushDestinoUsuario')?.value || '').trim();
    if (!titulo || !cuerpo) { toast('Título y mensaje son requeridos', 'error'); return; }
    if (!dest) { toast('Destinatario no encontrado', 'error'); return; }
    closeModal('modalEnviarPush');
    try {
      // [CERO-GAS / CERO-FALLBACK] Solo Edge push (enviarPushSB resuelve audiencia + envía). Sin fallback GAS.
      const r = await API.enviarPushSB(titulo, cuerpo, { soloUsuarios: [dest], incluirCompanions: true });
      if (r?.tokensAlcanzados) {
        toast(`✓ Mensaje enviado a ${dest} (${r.tokensAlcanzados} dispositivo${r.tokensAlcanzados === 1 ? '' : 's'})`, 'ok');
      } else {
        toast(`✓ Mensaje enviado a ${dest}`, 'ok');
      }
    } catch(e) {
      // Si el usuario no tiene tokens, mostrar error claro
      const msg = e?.message || 'Error';
      if (msg.includes('no tiene dispositivos')) {
        toast(`⚠ ${dest} no tiene notificaciones activas. Pídele que las habilite al iniciar sesión.`, 'warn', 8000);
      } else {
        toast('Error: ' + msg, 'error');
      }
    }
  }

  // ────────────────────────────────────────────────────────
  // ACTUALIZAR BADGES (notif + integridad) en header de Personal
  // ────────────────────────────────────────────────────────
  async function _actualizarBadgesPersonal() {
    // Notificaciones unificadas
    const pendDisp = (cfgData.dispositivos || []).filter(d => String(d.Estado).toUpperCase() === 'PENDIENTE_APROBACION').length;
    const bloqs = (cfgData.bloqueosME || []).filter(b => b.fechaBloqueo && !b.unlockVigente).length;
    _personalNotifCount = pendDisp + bloqs + _personalIntegCount;
    const bN = $('personalNotifBadge');
    if (bN) {
      if (_personalNotifCount > 0) {
        bN.classList.remove('hidden');
        bN.textContent = _personalNotifCount;
      } else {
        bN.classList.add('hidden');
      }
    }
    // Integridad
    try {
      const r = await API.get('getAuditoriaIntegridad', {});
      const alertas = r?.alertas || r?.data || [];
      _personalIntegCount = Array.isArray(alertas) ? alertas.filter(a => !a.resuelto).length : 0;
    } catch(_) { _personalIntegCount = 0; }
    const bI = $('personalIntegBadge');
    if (bI) {
      if (_personalIntegCount > 0) {
        bI.classList.remove('hidden');
        bI.textContent = _personalIntegCount;
      } else {
        bI.classList.add('hidden');
      }
    }
  }

  async function guardarMetaChip(configKey, valor) {
    const v = String(valor || '').trim();
    if (!cfgData.config) cfgData.config = {};
    cfgData.config[configKey] = v;
    renderPersonal();
    // [Fase2] Las metas de Almacén también se editan desde Infraestructura → refrescar esa vista.
    if (S.cfgTab === 'infra') renderInfra();
    try {
      await API.post('setConfig', { clave: configKey, valor: v });
      toast(`Meta actualizada · ${configKey} = ${v}`, 'ok');
    } catch(e) {
      toast('Error al guardar meta: ' + e.message, 'error');
    }
  }

  // Pinta el card "🛒 Vendedores — MosExpress" en Config → Personal.
  // Lee del cache localStorage de liquidaciones pendientes (mismo source
  // que la pantalla de Liquidaciones, ya prefetcheado al login).
  // [Fase2] Normalizador de nombre compartido (cajeros ME viven por nombre, no por id).
  function _normNombre(s) { return String(s || '').trim().toLowerCase(); }

  // [Fase2] Datos de cajeros ME agrupados por zona — EXTRAÍDO de _cfgRenderMeCajeros para
  // reutilizar en la fusión usuarios-por-zona (Infraestructura) SIN duplicar la lógica.
  // La zona se infiere del dispositivo donde el cajero tiene Ultima_Sesion (Ultima_Zona).
  function _cfgCajerosData() {
    let pendientes = null;
    try {
      const raw = localStorage.getItem('mos_liq_pendientes');
      if (raw) { const p = JSON.parse(raw); pendientes = p && p.data; }
    } catch {}
    let cajeros = (pendientes && Array.isArray(pendientes.personal))
      ? pendientes.personal.filter(p => {
          const app = String(p.appOrigen || '').toLowerCase();
          return app === 'mosexpress' || app === 'mexpress' || app.indexOf('express') >= 0;
        })
      : [];
    // Agregar bloqueados que no aparecen en jornadas de la semana
    const yaListados = new Set(cajeros.map(c => _normNombre(c.nombre)));
    (cfgData.bloqueosME || []).forEach(b => {
      if (!yaListados.has(_normNombre(b.nombre))) {
        cajeros.push({ nombre: b.nombre, rol: 'CAJERO', appOrigen: 'mosExpress',
          montoTotal: 0, diasPendientes: 0, diasAuditados: 0, esVirtual: false });
      }
    });
    const bloqMap = {};
    (cfgData.bloqueosME || []).forEach(b => { bloqMap[_normNombre(b.nombre)] = b; });
    // Cruzar con DISPOSITIVOS: última conexión + zona principal del cajero.
    const dispPorCajero = {};
    (cfgData.dispositivos || []).forEach(d => {
      if (String(d.Estado).toUpperCase() !== 'ACTIVO') return;
      const sesNorm = _normNombre(d.Ultima_Sesion);
      if (!sesNorm) return;
      const t = new Date(d.Ultima_Conexion || 0).getTime() || 0;
      const prev = dispPorCajero[sesNorm];
      if (!prev || (new Date(prev.Ultima_Conexion || 0).getTime() || 0) < t) dispPorCajero[sesNorm] = d;
    });
    // Agrupar por zona inferida; sin dispositivo/zona → '__SIN_ZONA__'.
    const grupos = {};
    cajeros.forEach(c => {
      const disp = dispPorCajero[_normNombre(c.nombre)];
      const zonaId = String(disp?.Ultima_Zona || '').trim() || '__SIN_ZONA__';
      (grupos[zonaId] = grupos[zonaId] || []).push(c);
    });
    return { cajeros, grupos, dispPorCajero, bloqMap };
  }

  // [Fase2] Card de un cajero ME — EXTRAÍDA del closure renderPersona (reutilizable).
  function _renderCajeroCard(c, dispPorCajero, bloqMap) {
      const initials = String(c.nombre || '?').split(/\s+/).map(s => s[0] || '').join('').slice(0, 2).toUpperCase();
      const monto = parseFloat(c.montoTotal) || 0;
      const dias = parseInt(c.diasPendientes) || 0;
      const aud  = parseInt(c.diasAuditados) || 0;
      const virt = c.esVirtual
        ? '<span class="badge badge-yellow text-[9px] ml-1" title="Detectado de ventas (no en PERSONAL_MASTER)">virtual</span>'
        : '';
      const reg = bloqMap[_normNombre(c.nombre)];
      const bloqueado = !!(reg && reg.fechaBloqueo && !reg.unlockVigente);
      const safeNombre = String(c.nombre || '').replace(/'/g, '&#39;');
      // Indicador de actividad cruzando con DISPOSITIVOS
      const dispActivo = dispPorCajero[_normNombre(c.nombre)];
      const act = dispActivo ? _personaActividad(dispActivo.Ultima_Conexion) : { color: '#64748b', label: 'sin sesión', dot: '⚫', minutos: Infinity };
      const isFresh = act.minutos < 5;
      const opacity = bloqueado ? 'opacity:0.6;' : '';
      const borderCol = bloqueado ? '#7f1d1d' : (isFresh ? 'rgba(16,185,129,0.5)' : '#1e293b');
      const bgChip = isFresh ? 'rgba(16,185,129,0.06)' : '#0d1526';
      const dotPulse = isFresh ? '<span class="disp-dot-pulse"></span>' : '';
      const claseFresh = isFresh ? 'disp-chip-live' : '';
      const lockBadge = bloqueado
        ? '<span class="badge badge-red text-[9px] ml-1" title="Cajero bloqueado — al iniciar MosExpress con este nombre, ve pantalla de candado">🔒 bloqueado</span>'
        : '';
      return `<div class="flex items-center gap-3 p-3 rounded-lg ${claseFresh}" style="background:${bgChip};border:1px solid ${borderCol};${opacity}transition:all 0.2s;">
        <div class="relative shrink-0">
          <div class="w-10 h-10 rounded-full flex items-center justify-center text-sm font-bold"
               style="background:linear-gradient(135deg,#fbbf24,#f59e0b);color:#0b1220">${initials}</div>
          ${dotPulse}
        </div>
        <div class="flex-1 min-w-0">
          <div class="font-medium text-sm text-slate-200 truncate">${c.nombre}${virt}${lockBadge}</div>
          <div class="flex items-center gap-2 mt-0.5 flex-wrap">
            <span class="badge badge-gray text-[9px] uppercase">${c.rol || 'CAJERO'}</span>
            <span class="text-[9px]" style="color:${act.color};">${act.dot} ${act.label}</span>
            <span class="text-[9px] text-slate-500">${dias}d · ${aud}/${dias} aud</span>
          </div>
        </div>
        <div class="text-right shrink-0 mr-2">
          <div class="text-sm font-bold text-amber-400">S/ ${monto.toFixed(2)}</div>
          <div class="text-[10px] text-slate-500">esta semana</div>
        </div>
        <button onclick="event.stopPropagation();MOS.abrirEspiaPorUsuario('${safeNombre}')"
                class="shrink-0 w-8 h-8 rounded-full flex items-center justify-center hover:scale-110 transition-all"
                style="background:rgba(99,102,241,0.18);border:1px solid rgba(99,102,241,0.5);color:#a5b4fc;font-size:13px;"
                title="Espiar a ${c.nombre} (audio + GPS)">🕵️</button>
        <button onclick="event.stopPropagation();MOS.abrirModalEnviarPush('','${safeNombre}')"
                class="shrink-0 w-8 h-8 rounded-full flex items-center justify-center hover:scale-110 transition-all"
                style="background:rgba(59,130,246,0.15);border:1px solid rgba(59,130,246,0.5);color:#60a5fa;font-size:13px;"
                title="Enviar mensaje push a ${c.nombre}">💬</button>
        <label class="pers-switch shrink-0" title="${bloqueado ? 'Activar cajero — desbloquea pantalla de candado en su dispositivo' : 'Bloquear cajero — solo el dispositivo donde está logueado verá pantalla de candado'}">
          <input type="checkbox" ${bloqueado ? '' : 'checked'} onchange="MOS.toggleVendedorME('${safeNombre}', event)">
          <span class="pers-switch-slider"></span>
        </label>
      </div>`;
  }

  function _cfgRenderMeCajeros() {
    const cont = $('listMeCajeros');
    if (!cont) return;
    const { cajeros, grupos, dispPorCajero, bloqMap } = _cfgCajerosData();

    const cnt = $('cfgMeCajerosCount');
    if (cnt) {
      cnt.textContent = cajeros.length + (cajeros.length === 1 ? ' activo' : ' activos');
      cnt.className = 'badge ' + (cajeros.length ? 'badge-green' : 'badge-gray') + ' text-xs';
    }
    if (!cajeros.length) {
      cont.innerHTML = '<p class="text-xs text-slate-500 italic text-center py-3">Sin cajeros activos esta semana.</p>';
      return;
    }

    // Render por grupo (zona). Ordena las zonas alfabéticamente y deja
    // "Sin zona" al final.
    const zonaNombres = {};
    (cfgData.zonas || []).forEach(z => { zonaNombres[String(z.idZona)] = z.nombre || z.idZona; });
    const keys = Object.keys(grupos).sort((a,b) => {
      if (a === '__SIN_ZONA__') return 1;
      if (b === '__SIN_ZONA__') return -1;
      return (zonaNombres[a] || a).localeCompare(zonaNombres[b] || b);
    });
    cont.innerHTML = keys.map(zKey => {
      const lista = grupos[zKey];
      const nombreZona = zKey === '__SIN_ZONA__' ? '🌫 Sin zona asignada' : ('🏬 ' + (zonaNombres[zKey] || zKey));
      const rolesEnGrupo = {};
      lista.forEach(c => {
        const r = (c.rol || 'CAJERO').toUpperCase();
        rolesEnGrupo[r] = (rolesEnGrupo[r] || 0) + 1;
      });
      const desgloseRol = Object.keys(rolesEnGrupo)
        .map(r => `${rolesEnGrupo[r]} ${r.toLowerCase()}${rolesEnGrupo[r] !== 1 ? 's' : ''}`)
        .join(' · ');
      return `<div class="mb-3">
        <div class="flex items-center justify-between px-1 mb-1.5">
          <span class="text-[10px] uppercase tracking-wider text-amber-300/70 font-bold">${nombreZona}</span>
          <span class="text-[10px] text-slate-500">${desgloseRol}</span>
        </div>
        <div class="space-y-2">${lista.map(c => _renderCajeroCard(c, dispPorCajero, bloqMap)).join('')}</div>
      </div>`;
    }).join('');
  }

  // [Fase2] FUSIÓN usuarios-por-zona: bloque 👥 desplegable dentro de cada zona de
  // Infraestructura. Reutiliza _renderPersonaCard (operadores WH, personas reales) y
  // _renderCajeroCard (cajeros ME, por nombre). Los admins/master van en la zona Premium.
  // Activa/bloquea un vendedor ME por NOMBRE en BLOQUEOS_USUARIO
  // (no toca PERSONAL_MASTER — los cajeros ME comparten el usuario plantilla)
  async function toggleVendedorME(nombre, ev) {
    if (ev) ev.stopPropagation();
    const checked = ev?.target?.checked;
    // checked=true → activar (sin bloqueo) ; checked=false → bloquear
    const accion = checked ? 'activar' : 'BLOQUEAR (mostrar pantalla de candado en su dispositivo)';
    if (!await _modalConfirm(`¿${accion.charAt(0).toUpperCase() + accion.slice(1)} a ${nombre}?\n\nSolo afecta al dispositivo donde "${nombre}" esté logueado en MosExpress. Otros cajeros siguen vendiendo normal.`, { warning: !checked, titulo: checked ? 'Activar vendedor' : 'Bloquear vendedor' })) {
      if (ev?.target) ev.target.checked = !checked;
      return;
    }
    // [cero-caída · SQL 434/435] clave admin re-verificada server-side (bloquear_vendedor_me)
    const auth = await pedirAuth({ accion: 'BLOQUEAR_VENDEDOR', refDocumento: nombre,
      contexto: (checked ? 'Activar' : 'Bloquear') + ' vendedor ' + nombre });
    if (!auth) { if (ev?.target) ev.target.checked = !checked; return; }
    try {
      await API.post('bloquearVendedorME', {
        nombre: nombre,
        appOrigen: 'mosExpress',
        bloquear: !checked,
        bloqueadoPor: S.session?.nombre || 'admin',
        claveAdmin: auth.clave
      });
      toast(`${nombre} ${checked ? 'activado' : 'bloqueado'} ✓`, 'ok');
      // Refrescar lista de bloqueos
      const bloq = await API.get('getVendedoresMEBloqueados', {});
      cfgData.bloqueosME = bloq || [];
      _cfgRenderMeCajeros();
    } catch(e) {
      console.error('[toggleVendedorME]', e);
      toast('Error: ' + e.message, 'error');
      if (ev?.target) ev.target.checked = !checked;
    }
  }

  // (renderSeries() obsoleto — series ahora viven dentro de Infraestructura como chips)


  // ── Seguridad: Clave Admin Global ──────────────────────
  let _segDataActual = null;

  function seg_ocultar() {
    const login = $('segPanelLogin');
    const clave = $('segPanelClave');
    if (login) login.classList.remove('hidden');
    if (clave) clave.classList.add('hidden');
    const inp = $('segPinAdmin');
    if (inp) inp.value = '';
    const err = $('segError');
    if (err) err.textContent = '';
    _segDataActual = null;
  }

  async function seg_consultarClave() {
    const inp = $('segPinAdmin');
    const err = $('segError');
    const pin = String(inp?.value || '').trim();
    if (!/^\d{4}$/.test(pin)) {
      if (err) err.textContent = 'Ingresa tu PIN de 4 dígitos';
      return;
    }
    if (err) err.textContent = '';
    try {
      const data = await API.get('getClaveAdminGlobal', { pinAdmin: pin });
      if (!data?.autorizado) {
        if (err) err.textContent = data?.error || 'PIN incorrecto';
        if (inp) inp.value = '';
        return;
      }
      _segDataActual = data;
      _segActualizarCacheLocal(data);
      _segPintar(data);
      seg_cargarAuditoria();
    } catch(e) {
      console.error('[seg_consultarClave]', e);
      if (err) err.textContent = e?.message || 'Sin conexión';
    }
  }

  function _segPintar(data) {
    const claveDig = $('segClaveDigits');
    if (claveDig) claveDig.textContent = (data.pin || '----').split('').join(' ');
    const dr = $('segDiasRestantes');
    if (dr) {
      const dias = data.diasParaProximaRotacion;
      dr.textContent = data.vencida ? '⚠ Vencida — rota ahora'
                       : (dias === 0 ? 'Hoy' : (dias + ' días'));
      dr.style.color = data.vencida ? '#f87171' : (dias <= 5 ? '#fbbf24' : '#10b981');
    }
    const barra = $('segBarraProgreso');
    if (barra) {
      const pct = Math.max(0, Math.min(100, ((30 - data.diasParaProximaRotacion) / 30) * 100));
      barra.style.width = pct + '%';
      if (data.vencida) barra.style.background = '#ef4444';
    }
    const fp = $('segFechaProxima');
    if (fp && data.fechaProximaRotacion) {
      const f = new Date(data.fechaProximaRotacion);
      fp.textContent = 'Próxima rotación: ' + f.toLocaleDateString('es-PE', { day: 'numeric', month: 'long', year: 'numeric' });
    }
    $('segPanelLogin')?.classList.add('hidden');
    $('segPanelClave')?.classList.remove('hidden');
  }

  async function seg_rotarManual() {
    const inp = $('segPinAdmin');
    const pin = String(inp?.value || '').trim();
    let pinUsar = pin;
    if (!/^\d{4}$/.test(pinUsar)) {
      pinUsar = await _modalPrompt('Ingresa tu PIN admin (4 dígitos) para confirmar la rotación:', '', { titulo: '🔐 Confirmar rotación', inputType: 'tel', inputMode: 'numeric', maxlength: 4 });
      if (!pinUsar || !/^\d{4}$/.test(pinUsar.trim())) {
        toast('Rotación cancelada · PIN inválido', 'warn');
        return;
      }
      pinUsar = pinUsar.trim();
    }
    if (!await _modalConfirm('¿Generar una nueva clave global aleatoria?\n\nLa clave actual dejará de funcionar inmediatamente en MosExpress y warehouseMos.', { danger: true, titulo: 'Rotar clave admin global', okText: 'Rotar ahora' })) return;
    try {
      const data = await API.post('rotarClaveAdminGlobal', { manual: true, pinAdmin: pinUsar });
      if (!data?.autorizado && data?.error) { toast(data.error, 'danger'); return; }
      _segDataActual = {
        pin: data.pin,
        fechaUltimaRotacion: data.fechaUltimaRotacion,
        fechaProximaRotacion: data.fechaProximaRotacion,
        diasDesdeRotacion: 0,
        diasParaProximaRotacion: 30,
        vencida: false
      };
      _segActualizarCacheLocal(_segDataActual);
      _segPintar(_segDataActual);
      seg_cargarAuditoria();
      toast('Clave rotada · ' + data.pin, 'ok', 5000);
    } catch(e) {
      console.error('[seg_rotarManual]', e);
      toast(e?.message || 'Sin conexión', 'danger');
    }
  }

  async function seg_cargarAuditoria() {
    const tbody = $('tbodyAuditoria');
    if (!tbody) return;
    tbody.innerHTML = '<tr><td colspan="5" class="text-center py-4 text-slate-500">Cargando...</td></tr>';
    try {
      const data = await API.get('getAuditoriaAdmin', { limit: 30 });
      if (!Array.isArray(data)) {
        tbody.innerHTML = '<tr><td colspan="5" class="text-center py-4 text-slate-500">Sin auditoría disponible.</td></tr>';
        return;
      }
      if (!data.length) {
        tbody.innerHTML = '<tr><td colspan="5" class="text-center py-6 text-slate-500">Aún no hay acciones registradas.</td></tr>';
        return;
      }
      tbody.innerHTML = data.map(a => {
        const fecha = a.fecha ? new Date(a.fecha) : null;
        const fmtFecha = fecha ? fecha.toLocaleDateString('es-PE', { day: '2-digit', month: '2-digit' }) + ' ' + fecha.toLocaleTimeString('es-PE', { hour: '2-digit', minute: '2-digit' }) : '—';
        const accColor = {
          'ANULACION': 'text-red-400',
          'CREDITO': 'text-amber-400',
          'CAMBIO_METODO': 'text-blue-400',
          'REABRIR_GUIA': 'text-purple-400',
          'DESBLOQUEO_USUARIO': 'text-emerald-400',
          'ROTACION_PIN_GLOBAL': 'text-pink-400'
        }[String(a.accion || '').toUpperCase()] || 'text-slate-400';
        return `<tr>
          <td class="text-slate-500">${fmtFecha}</td>
          <td class="${accColor} font-semibold text-xs uppercase tracking-wider">${a.accion || '—'}</td>
          <td class="text-slate-200">${a.nombreAutoriza || '—'}</td>
          <td class="text-slate-500 text-xs">${a.appOrigen || '—'}</td>
          <td class="text-slate-500 text-xs hidden sm:table-cell font-mono">${a.refDocumento || '—'}</td>
        </tr>`;
      }).join('');
    } catch(e) {
      tbody.innerHTML = '<tr><td colspan="5" class="text-center py-4 text-slate-500">Sin conexión</td></tr>';
    }
  }

  // (renderDispositivos() obsoleto — ahora viven dentro de Infraestructura)
  // Helpers compartidos para iconos / actividad de dispositivos
  function _dispIcono(nombre) {
    const n = String(nombre || '').toLowerCase();
    if (n.includes('tablet') || n.includes('ipad'))      return '📲';
    if (n.includes('celular') || n.includes('movil') || n.includes('phone')) return '📱';
    if (n.includes('laptop') || n.includes('notebook'))  return '💻';
    if (n.includes('pc ') || n.startsWith('pc') || n.includes('desktop')) return '🖥️';
    return '📱';
  }

  // [Rediseño Config] Tipo VISUAL del dispositivo para dibujarlo (phone/tablet/laptop/pc).
  // Detecta por User_Agent si existe; cae a heurística por nombre/plataforma.
  function _dispTipoVisual(d) {
    const s = (String(d.User_Agent || d.UserAgent || d.userAgent || '') + ' ' +
               String(d.Nombre_Equipo || '') + ' ' + String(d.Plataforma || d.SO || '')).toLowerCase();
    if (/ipad|tablet/.test(s)) return 'tablet';
    if (/iphone|android|mobile|móvil|movil|celular|\bphone\b/.test(s)) return 'phone';
    if (/macbook|laptop|notebook/.test(s)) return 'laptop';
    if (/windows|desktop|linux|imac|\bmac\b|\bpc\b/.test(s)) return 'pc';
    return 'phone';
  }
  // Gradiente de avatar determinístico por nombre (mismo nombre → mismo color).
  function _avatarGrad(name) {
    const pares = [['#c4b5fd','#818cf8'],['#fcd34d','#f59e0b'],['#6ee7b7','#10b981'],['#7dd3fc','#0ea5e9'],['#fca5a5','#ef4444'],['#f0abfc','#c026d3'],['#fdba74','#f97316']];
    let h = 0; const t = String(name || '?'); for (let i = 0; i < t.length; i++) h = (h * 31 + t.charCodeAt(i)) >>> 0;
    const p = pares[h % pares.length];
    return `linear-gradient(135deg,${p[0]},${p[1]})`;
  }
  // [Rediseño Config] Dispositivo DIBUJADO (mockup config_modulo.html): silueta real por tipo,
  // halo verde si está en línea, cara con avatar+usuario, y la botonera 🛡️🕵️🛰️📼✏️ (mismos handlers).
  function _dispDrawn(d) {
    const tipo = _dispTipoVisual(d);
    const act = _dispActividad(d.Ultima_Conexion);
    const estado = String(d.Estado || '').toUpperCase();
    const isFresh = _dispEnLinea(d);
    const isSusp = estado === 'SUSPENDIDO' || estado.startsWith('CANCELADO');
    const stateCls = isFresh ? 'online' : (isSusp ? 'susp' : '');
    const idAttr = String(d.ID_Dispositivo).replace(/'/g, '&#39;');
    const appL = String(d.App || '').toLowerCase();
    const appCls = appL === 'mos' ? 'mos' : (appL.indexOf('express') >= 0 || appL === 'me' ? 'me' : (appL.indexOf('warehouse') >= 0 || appL === 'wh' ? 'wh' : ''));
    const appLbl = appCls === 'mos' ? 'MOS' : (appCls === 'me' ? 'ME' : (appCls === 'wh' ? 'WH' : ''));
    let user = d.Ultima_Sesion || '';
    // [Fix dueño] El panel MOS no estampa ultima_sesion en el dispositivo (solo ME/WH lo hacen
    // al loguear) → si este equipo ES el del navegador actual, el usuario es el de la sesión viva.
    if (!user && S.session?.nombre) {
      try { if (String(d.ID_Dispositivo) === String(localStorage.getItem('mos_device_id') || '')) user = S.session.nombre; } catch (_) {}
    }
    // Iniciales: 1ª letra del USUARIO; sin usuario, del nombre del equipo (nunca "?" salvo vacío total)
    const baseIni = String(user || d.Nombre_Equipo || '').trim();
    const ini = (baseIni.charAt(0) || '·').toUpperCase();
    const grad = user ? _avatarGrad(user) : '#33415a';
    const rol = user ? _rolDe(user) : '';
    const pill = isFresh
      ? `<span class="pill" style="background:rgba(16,185,129,.16);color:#6ee7b7">● live${_esMiDispositivo(d) ? ' · tú' : ''}</span>`
      : isSusp
        ? `<span class="pill" style="background:rgba(249,115,22,.16);color:#fdba74">⏸ ${estado.startsWith('CANCELADO') ? 'arch' : 'susp'}</span>`
        : `<span class="pill" style="background:rgba(245,184,73,.14);color:#fbd989">◐ ${act.label.replace('hace ', '')}</span>`;
    const appc = appLbl ? `<span class="appc appb ${appCls}">${appLbl}</span>` : '';
    // Cara del mockup: avatar + nombre del usuario + ROL (o "en línea"). El tiempo va SOLO en el cap
    // (antes, sin usuario, la cara repetía "hace Xm" y quedaba duplicado con el caption).
    const ust = rol || (isFresh ? 'en línea' : '');
    const face = `<div class="face"><div class="avatar" style="background:${grad}">${ini}</div>${user ? `<div class="uname">${user.split(/\s+/)[0]}</div>` : ''}${ust ? `<div class="ust" style="color:${isFresh ? '#6ee7b7' : act.color}">${ust}</div>` : ''}</div>`;
    let devt;
    if (tipo === 'phone')       devt = `<div class="devt phone ${stateCls}">${face}</div>`;
    else if (tipo === 'tablet') devt = `<div class="devt tablet ${stateCls}">${face}</div>`;
    else if (tipo === 'laptop') devt = `<div class="devt laptop ${stateCls}"><div class="lid">${face}</div><div class="base"></div></div>`;
    else                        devt = `<div class="devt pc ${stateCls}"><div class="screen">${face}</div><div class="stand"></div><div class="foot"></div></div>`;
    // Cap del mockup: "Desktop MOS / Luis · master · 8m"
    // [798 · tiempo real] Si el equipo está en el canal de PRESENCIA (conectado al segundo)
    // o es este mismo navegador, el texto dice "en vivo" — antes usaba solo el último latido
    // (ultima_conexion, hasta 10 min viejo) → un equipo LIVE mostraba "hace un día" en el texto
    // aunque el badge dijera live. Ahora badge y texto coinciden y reflejan la presencia real.
    const _liveReal = _esMiDispositivo(d) || _presTieneDevice(d.ID_Dispositivo);
    const tRel = _liveReal ? '🔴 en vivo' : act.label.replace('hace ', '').replace('inactivo ', '');
    const capS = user
      ? `${user.split(/\s+/)[0]}${rol ? ` · <b style="color:#fdba74">${rol}</b>` : ''} · ${tRel}`
      : (_liveReal ? '🔴 en vivo' : act.label);
    const cap = `<div class="cap"><div class="t">${d.Nombre_Equipo || '—'}</div><div class="s">${capS}</div></div>`;
    const master = _esMasterSession();
    const monitor = `<div class="monitor">`
      + `<span class="mbtn perm" onclick="event.stopPropagation();MOS.abrirDetalleDispositivo('${idAttr}')" title="Permisos y acciones del dispositivo">🛡️</span>`
      + `<span class="mbtn spy" onclick="event.stopPropagation();MOS.abrirEspiaDispositivo('${idAttr}')" title="Espiar (audio + GPS)">🕵️</span>`
      + (master && !isSusp ? `<span class="mbtn spy2" onclick="event.stopPropagation();MOS.abrirEspiaV2('${idAttr}')" title="Espía V2 · WebRTC live (Master)">🛰️</span>` : '')
      + (master && !isSusp ? `<span class="mbtn tl" onclick="event.stopPropagation();MOS.abrirTimelineBufferEspia('${idAttr}')" title="Timeline buffer (12h histórico)">📼</span>` : '')
      + (isSusp ? `<span class="mbtn" style="background:rgba(16,185,129,.14);border-color:rgba(16,185,129,.4);color:#6ee7b7" onclick="event.stopPropagation();MOS.aprobarDispositivo('${idAttr}')" title="Reactivar">↻</span>` : '')
      // [826] FIJAR: exime a este equipo de la suspensión por +2 días sin uso. Solo MASTER,
      // solo equipos de MOS. El ícono cambia de forma según el estado.
      + (master && _esDispMOS(d)
          ? `<span class="mbtn fij${d.Fijado ? ' on' : ''}" onclick="event.stopPropagation();MOS.dispToggleFijado('${idAttr}')" title="${d.Fijado ? 'FIJADO · no se suspende por inactividad. Tocar para soltar' : 'Fijar: que la inactividad no lo suspenda (pide clave master)'}">${d.Fijado ? '📍' : '📌'}</span>`
          : '')
      + `<span class="mbtn edit" onclick="event.stopPropagation();MOS.abrirModalDispositivo('${idAttr}')" title="Editar">✏️</span>`
      + `</div>`;
  // [786] Chip amo/esclavo (principal/extensión) — SOLO cuando el equipo forma parte de un par
    // en la MISMA app (caja ME con extensión, etc.). Misma persona en apps distintas (WH+ME+MosGo)
    // NO es amo-esclavo → sin chip. El mapa lo calcula el server (mos.dispositivos_amo_esclavo).
    const _rolAE = (cfgData.rolesAmoEsclavo || {})[String(d.ID_Dispositivo)];
    const aeChip = _rolAE === 'AMO'
      ? `<span class="chip" title="Equipo PRINCIPAL (amo) — tiene una extensión conectada a su caja" style="background:rgba(245,184,73,.16);border:1px solid rgba(245,184,73,.5);color:#fde3a7;font-size:9px;font-weight:800;padding:2px 7px;border-radius:20px">👑 amo</span>`
      : _rolAE === 'ESCLAVO'
        ? `<span class="chip" title="Equipo EXTENSIÓN (esclavo) — depende de un principal; no cierra caja" style="background:rgba(148,163,184,.14);border:1px solid rgba(148,163,184,.42);color:#cbd5e1;font-size:9px;font-weight:800;padding:2px 7px;border-radius:20px">🔗 esclavo</span>`
        : '';
    // [826] chip del fijado: se ve de un vistazo cuál equipo está exento
    const fijChip = d.Fijado
      ? `<span class="chip" title="Fijado por ${_escapeHtml(String(d.Fijado_Por || 'master'))} — la inactividad no lo suspende" style="background:rgba(56,189,248,.16);border:1px solid rgba(56,189,248,.5);color:#7dd3fc;font-size:9px;font-weight:800;padding:2px 7px;border-radius:20px">📍 fijado</span>`
      : '';
    return `<div class="dev ${isFresh ? 'online' : ''}">${pill}${appc}${aeChip}${fijChip}<div class="glass"><div class="halo"></div>${devt}</div>${cap}${_dispMiniPermChips(d)}${monitor}</div>`;
  }

  // ═══════════ [826] FIJAR / SOLTAR un dispositivo ═══════════
  // Un equipo FIJADO queda exento de la regla de inactividad (+2 días → SUSPENDIDO, +7 →
  // archivado). Nace de un caso real: la jefa no maneja claves y no tiene por qué pedir
  // reactivación cada vez. NO da permisos ni evita el bloqueo manual: si un equipo se pierde,
  // se bloquea a mano igual que siempre.
  function _esDispMOS(d) {
    const a = String((d && d.App) || '').trim().toUpperCase();
    return a === 'MOS' || a === '';
  }
  async function dispToggleFijado(id) {
    const d = (cfgData.dispositivos || []).find(x => String(x.ID_Dispositivo) === String(id));
    if (!d) return;
    const fijar = !d.Fijado;
    const nom = String(d.Nombre_Equipo || '').trim() || id.slice(0, 8);

    // [838] El servidor exige que el nombre lo haya puesto una persona. En vez de mandar al
    // editor completo y hacer volver, se pide el nombre acá mismo, se guarda y se sigue derecho
    // al fijado. Un solo gesto.
    if (fijar && !d.Nombre_Manual) {
      const propuesto = await _modalPrompt(
        'Nombre del equipo — para saber de quién es',
        '',
        { titulo: '✏️ Ponle nombre y lo fijo',
          okText: 'Guardar y fijar',
          placeholder: 'Ej: Jefa · oficina',
          maxlength: 40 });
      const limpio = String(propuesto == null ? '' : propuesto).trim();
      if (!limpio) return;                       // canceló o lo dejó vacío
      if (limpio.length < 3) { toast('Ponle un nombre de al menos 3 letras', 'warn'); return; }
      try {
        const rn = await API.post('actualizarDispositivo', {
          ID_Dispositivo: id, Nombre_Equipo: limpio, App: d.App || 'MOS', Estado: d.Estado || 'ACTIVO'
        });
        if (rn && rn.ok === false) throw new Error(rn.error || 'no se pudo guardar el nombre');
        d.Nombre_Equipo = limpio;
        d.Nombre_Manual = true;
        try { renderInfra(); } catch(_){}
      } catch (e) {
        toast('No se pudo guardar el nombre: ' + (e.message || e), 'error');
        return;
      }
      // el nombre ya está: se sigue al fijado sin hacer volver a empezar
    }
    if (!fijar) {
      const ok = await _modalConfirm(
        'Soltar "' + nom + '": vuelve a la regla general y se suspenderá solo si pasa 2 días sin conectarse. ¿Continuar?',
        { titulo: '📌 Soltar dispositivo', okText: 'Sí, soltar' });
      if (!ok) return;
    }

    const nomFinal = String(d.Nombre_Equipo || '').trim() || nom;
    const auth = await pedirAuth({
      accion: 'DISPOSITIVO_FIJAR',
      refDocumento: id,
      contexto: (fijar ? 'Fijar' : 'Soltar') + ' "' + nomFinal + '" · exención de la suspensión por inactividad',
      allowCache: false
    });
    if (!auth) return;

    try {
      const r = await API.post('dispositivoFijar', {
        idDispositivo: id, fijar: fijar, clave: auth.clave || '',
        usuario: (S.session && S.session.nombre) || ''
      });
      const dd = r && (r.data || r);
      if (!r || r.ok === false) {
        toast((r && (r.mensaje || r.error)) || 'No se pudo aplicar', 'error');
        return;
      }
      d.Fijado = !!(dd && dd.fijado);
      d.Fijado_Por = d.Fijado ? ((S.session && S.session.nombre) || '') : '';
      toast(d.Fijado ? ('📍 "' + nomFinal + '" fijado — la inactividad ya no lo suspende')
                     : ('📌 "' + nomFinal + '" soltado — vuelve a la regla general'), 'ok', 4000);
      try { renderInfra(); } catch(_) {}   // repinta la card con el icono nuevo
    } catch (e) {
      toast('Error: ' + (e.message || e), 'error');
    }
  }


  // [801] Mini-chips de permisos EN LA TARJETA (vistazo rápido: ¿este móvil se puede monitorear?).
  // Verde=concedido · rojo=denegado · ámbar=pendiente/sin pedir. Los 4 relevantes para vigilar:
  // 📷 cámara · 🎤 micrófono · 🔔 notificaciones (para despertarlo) · 📍 GPS. El detalle completo
  // sigue en el botón 🛡️. Si el equipo aún no reportó permisos, no muestra nada.
  function _dispMiniPermChips(d) {
    let p = {};
    try { p = (typeof d.Permisos_JSON === 'string') ? JSON.parse(d.Permisos_JSON) : (d.Permisos_JSON || {}); } catch (_) { p = {}; }
    if (!p || !Object.keys(p).length) return '';
    const col = (st) => st === 'granted' ? '#34d399' : (st === 'denied' ? '#f87171' : '#fbbf24');
    const lbl = (st) => st === 'granted' ? 'activo' : (st === 'denied' ? 'DENEGADO' : 'pendiente');
    const items = [['cam', '📷', 'Cámara'], ['mic', '🎤', 'Micrófono'], ['notif', '🔔', 'Notif.'], ['geo', '📍', 'GPS']];
    const chips = items.map(([k, ic, nm]) => {
      const st = p[k];
      if (st === undefined) return '';
      return `<span title="${nm}: ${lbl(st)}" style="display:inline-flex;align-items:center;gap:2px;font-size:10.5px;line-height:1;${st === 'granted' ? '' : 'opacity:.9'}">${ic}<span style="width:6px;height:6px;border-radius:50%;background:${col(st)};box-shadow:0 0 4px ${col(st)}88"></span></span>`;
    }).join('');
    if (!chips) return '';
    return `<div class="dev-perms" style="display:flex;gap:8px;justify-content:center;padding:3px 0 1px;flex-wrap:wrap">${chips}</div>`;
  }

  // Pill con la app de origen del dispositivo (ME / WH / MOS) — útil para que
  // el admin sepa de qué cliente viene la solicitud antes de aprobar.
  function _appBadge(appRaw, opts) {
    const app = String(appRaw || '').toLowerCase();
    let icon = '❓', label = 'desconocida', bg = 'rgba(148,163,184,0.15)', border = '#475569', fg = '#cbd5e1';
    if (app === 'mosexpress' || app === 'me' || app.indexOf('express') >= 0) {
      icon = '🛒'; label = 'MosExpress'; bg = 'rgba(16,185,129,0.15)'; border = '#10b981'; fg = '#6ee7b7';
    } else if (app === 'warehousemos' || app === 'wh' || app.indexOf('warehouse') >= 0) {
      icon = '📦'; label = 'warehouseMos'; bg = 'rgba(251,146,60,0.15)'; border = '#fb923c'; fg = '#fdba74';
    } else if (app === 'mosgo') {
      icon = '🛵'; label = 'MosGo'; bg = 'rgba(110,86,207,0.18)'; border = '#8f7aff'; fg = '#c4b5fd';
    } else if (app === 'mos') {
      icon = '👑'; label = 'MOS panel'; bg = 'rgba(168,85,247,0.15)'; border = '#a855f7'; fg = '#d8b4fe';
    } else if (!app || app === '') {
      icon = '❓'; label = '?';
    }
    const compact = opts && opts.compact;
    const cls = compact ? 'text-[9px] px-1.5 py-0.5' : 'text-[10px] px-2 py-0.5';
    return `<span class="${cls} rounded font-bold inline-flex items-center gap-1" style="background:${bg};border:1px solid ${border};color:${fg};white-space:nowrap;">${icon} ${compact ? '' : label}</span>`;
  }

  function _dispActividad(ultimaConexion) {
    if (!ultimaConexion) return { color: '#64748b', label: 'sin conexión', dot: '⚫', minutos: Infinity };
    const t = _parseTsUtc(ultimaConexion);
    if (isNaN(t)) return { color: '#64748b', label: ultimaConexion, dot: '⚫', minutos: Infinity };
    const seg = Math.floor((Date.now() - t) / 1000);
    const min = Math.floor(seg / 60);
    if (seg < 0)       return { color: '#10b981', label: '🔴 LIVE · ahora', dot: '🟢', minutos: 0 };
    if (seg < 90)      return { color: '#10b981', label: `🔴 LIVE · hace ${seg}s`, dot: '🟢', minutos: min };
    if (min < 5)       return { color: '#10b981', label: `online · hace ${min}m`,  dot: '🟢', minutos: min };
    if (min < 60)      return { color: '#10b981', label: `hace ${min}m`,     dot: '🟢', minutos: min };
    if (min < 60*24)   return { color: '#fbbf24', label: `hace ${Math.floor(min/60)}h`, dot: '🟡', minutos: min };
    if (min < 60*24*7) return { color: '#f97316', label: `hace ${Math.floor(min/60/24)}d`, dot: '🟠', minutos: min };
    return { color: '#ef4444', label: `inactivo ${Math.floor(min/60/24)}d`, dot: '🔴', minutos: min };
  }

  // Tracking de movimientos entre renders para animar transiciones
  let _dispUltimaEstacionMap = {};
  let _dispRenderCount = 0;
  // Trails: fantasmas que se quedan 5s en la estación de origen tras un movimiento
  let _dispFantasmas = {}; // { deviceId: { desde, hacia, ico, nombre, expira } }
  let _dispCleanupTimer = null;

  // Devuelve dispositivos cuya ÚLTIMA sesión fue en esta estación
  // (sin importar cuánto tiempo, mantiene "viviendo" donde estuvo último)
  function _dispEnEstacion(idEstacion) {
    return (cfgData.dispositivos || []).filter(d => {
      if (String(d.Estado).toUpperCase() !== 'ACTIVO') return false;
      return String(d.Ultima_Estacion || '') === String(idEstacion);
    });
  }

  // Detectar si el dispositivo se movió de estación entre renders

  function _dispActualizarMapa() {
    let huboMovimientos = false;
    (cfgData.dispositivos || []).forEach(d => {
      const prev = _dispUltimaEstacionMap[d.ID_Dispositivo];
      const ahora = String(d.Ultima_Estacion || '');
      // Detectar movimiento real (entre 2 renders, ambas estaciones definidas)
      if (_dispRenderCount > 0 && prev !== undefined && prev !== '' && prev !== ahora && ahora) {
        const ico = _dispIcono(d.Nombre_Equipo);
        const nombre = d.Nombre_Equipo || 'Dispositivo';
        _dispFantasmas[d.ID_Dispositivo] = {
          desde: prev,
          hacia: ahora,
          ico,
          nombre,
          expira: Date.now() + 5000
        };
        // E: Toast notif del movimiento
        const estDest = (cfgData.estaciones || []).find(e => e.idEstacion === ahora);
        const nombreDest = estDest?.nombre || ahora;
        try { toast(`📍 ${nombre} se movió a ${nombreDest}`, 'ok'); } catch(_) {}
        huboMovimientos = true;
      }
      _dispUltimaEstacionMap[d.ID_Dispositivo] = ahora;
    });
    _dispRenderCount++;
    // Programar re-render para que los fantasmas desaparezcan a los 5s
    if (huboMovimientos) {
      if (_dispCleanupTimer) clearTimeout(_dispCleanupTimer);
      _dispCleanupTimer = setTimeout(() => {
        _dispCleanupTimer = null;
        if (S.cfgTab === 'infra') renderInfra();
      }, 5200);
    }
  }

  // Devuelve fantasmas vigentes que partieron de esta estación
  function _dispFantasmasDeEstacion(idEstacion) {
    const ahora = Date.now();
    return Object.entries(_dispFantasmas)
      .filter(([id, f]) => f.desde === idEstacion && f.expira > ahora)
      .map(([id, f]) => ({ id, ...f }));
  }

  // Cuenta dispositivos online (ACTIVO + actividad <5 min) en una estación
  function _dispOnlineEnEstacion(idEstacion) {
    return _dispEnEstacion(idEstacion).filter(_dispEnLinea).length;
  }

  // [637] Sella en mos.dispositivos QUIÉN usa este equipo (ultima_sesion) — la misma RPC
  // heartbeat de ME/WH (mos.registrar_sesion). Sin esto los equipos del panel MOS salían
  // como "Mobile abbf2b · hace 4h" sin dueño en Infraestructura (reporte del dueño).
  function _registrarSesionDispositivo() {
    try {
      const dev = (window.DeviceAuth && typeof DeviceAuth.deviceId === 'function' && DeviceAuth.deviceId())
        || (window.__MOS_AUDIT && window.__MOS_AUDIT.deviceId) || '';
      const quien = S.session && S.session.nombre;
      if (!dev || !quien) return;
      if (window.DeviceAuth && DeviceAuth.rpc) {
        DeviceAuth.rpc('registrar_sesion', { deviceId: dev, vendedor: quien }).catch(() => {});
      }
    } catch (_) {}
  }

  function _dispPendientes() {
    return (cfgData.dispositivos || []).filter(d => {
      if (String(d.Estado).toUpperCase() !== 'PENDIENTE_APROBACION') return false;
      // [635 · decisión dueño] la solicitud VENCE a la 1 hora: no aparece más. Si el
      // equipo la reenvía (cooldown 5 min server-side), pendiente_desde se renueva y
      // vuelve a aparecer fresca.
      const pd = Date.parse(d.Pendiente_Desde || '') || Date.parse(d.Ultima_Conexion || '') || 0;
      return !pd || (Date.now() - pd) <= 3600e3;
    });
  }

  // "hace 4 min" / "hace 3 h" / "hace 2 d" — para solicitudes y suspensiones
  function _fmtHace(ts) {
    const ms = Date.now() - (Date.parse(ts || '') || 0);
    if (!isFinite(ms) || ms < 0 || !ts) return '';
    const m = Math.floor(ms / 60000);
    if (m < 60) return 'hace ' + Math.max(0, m) + ' min';
    const h = Math.floor(m / 60);
    if (h < 48) return 'hace ' + h + ' h';
    return 'hace ' + Math.floor(h / 24) + ' d';
  }
  // [635] ¿cuánto lleva/llevaba suspendido este equipo? '' si nunca.
  function _dispSuspTxt(d) {
    const sd = Date.parse(d.Suspendido_Desde || '');
    if (!sd) return '';
    return _fmtHace(d.Suspendido_Desde).replace('hace ', '');
  }

  // [Fase1] Archivados: equipos auto-cancelados por +7 días sin conectar.
  // NO es baneo — reversibles: al reconectar, verificar_dispositivo (SQL 100)
  // los reabre a PENDIENTE_APROBACION. Se muestran en una sección colapsable.
  // [Rediseño] Archivados = todo lo que NO va en el fleet: INACTIVO, CANCELADO*,
  // y SUSPENDIDO con +7 días sin conectar. Reversibles (reconexión o ↺ manual).
  function _dispArchivados() {
    return (cfgData.dispositivos || []).filter(d => {
      const est = String(d.Estado || '').toUpperCase();
      if (est === 'INACTIVO' || est.startsWith('CANCELADO')) return true;
      if (est === 'SUSPENDIDO') return _dispActividad(d.Ultima_Conexion).minutos > (7 * 24 * 60);
      return false;
    });
  }

  // Render compacto de un chip de dispositivo (dentro de estación o lista global)
  // Config CRUD
  function _estActualizarPreview() {
    const nom = ($('estNombre')?.value || '').trim();
    const tipo = $('estTipo')?.value || 'CAJA';
    const app = $('estApp')?.value || 'mosExpress';
    const idZona = $('estZona')?.value || '';
    const zonaName = idZona ? (cfgData.zonas.find(z => z.idZona === idZona)?.nombre || '—') : 'Sin zona';
    const tipoIcon = { CAJA: '🛒', ALMACEN: '🏭', ENVASADO: '🍶' }[tipo] || '📍';
    const appLbl = app === 'mosExpress' ? 'ME' : 'WH';
    const sub = $('modalEstSubtitle');
    if (sub) sub.textContent = nom ? `${tipo} · ${appLbl} · ${zonaName}` : 'Caja / almacén';
    const ico = $('estIconPreview');
    if (ico) ico.textContent = tipoIcon;
  }

  function abrirModalEstacion(id, presetIdZona) {
    ['Id','Nombre','Tipo','App','Pin','Desc'].forEach(f => {
      const el = $('est' + f); if (el && el.tagName !== 'SELECT') el.value = '';
    });
    // Poblar select de zonas dinámicamente
    const zonaSelect = $('estZona');
    if (zonaSelect) {
      zonaSelect.innerHTML = '<option value="">— Sin zona —</option>' +
        cfgData.zonas.filter(z => z.estado === '1' || z.estado === 1).map(z =>
          `<option value="${z.idZona}">${z.nombre}</option>`
        ).join('');
    }
    const estadoWrap = $('estEstadoWrap');
    const btnElim = $('estBtnEliminar');
    const tg = $('estEstadoToggle');
    if (id) {
      const e = cfgData.estaciones.find(x => x.idEstacion === id);
      if (!e) return;
      $('modalEstTitle').textContent = 'Editar Estación';
      $('estId').value     = e.idEstacion;
      $('estNombre').value = e.nombre || '';
      if (zonaSelect) zonaSelect.value = e.idZona || '';
      $('estTipo').value   = e.tipo || 'CAJA';
      $('estApp').value    = e.appOrigen || 'mosExpress';
      $('estDesc').value   = e.descripcion || '';
      if (tg) tg.checked = String(e.activo) === '1' || e.activo === 1 || e.activo === true;
      if (estadoWrap) estadoWrap.classList.remove('hidden');
      if (btnElim)    btnElim.classList.remove('hidden');
    } else {
      $('modalEstTitle').textContent = 'Nueva Estación';
      $('estId').value = '';
      $('estTipo').value = 'CAJA';
      $('estApp').value = 'mosExpress';
      if (tg) tg.checked = true;
      if (estadoWrap) estadoWrap.classList.add('hidden');
      if (btnElim)    btnElim.classList.add('hidden');
      // Preset de zona si se está creando desde dentro de una zona
      if (presetIdZona && zonaSelect) zonaSelect.value = presetIdZona;
    }
    _estActualizarPreview();
    openModal('modalEstacion');
  }

  async function guardarEstacion() {
    const idEdit = $('estId')?.value || undefined;
    const tg = $('estEstadoToggle');
    const params = {
      idEstacion:  idEdit,
      nombre:      ($('estNombre')?.value || '').trim(),
      idZona:      $('estZona')?.value || '',
      tipo:        $('estTipo')?.value || 'CAJA',
      appOrigen:   $('estApp')?.value || 'mosExpress',
      descripcion: $('estDesc')?.value || ''
    };
    if (idEdit) params.activo = (tg && tg.checked) ? '1' : '0';
    if (!params.nombre) { toast('Nombre requerido', 'error'); return; }
    if (!params.idEstacion) delete params.idEstacion;
    // OPTIMISTA
    const list = cfgData.estaciones;
    const backup = list.slice();
    if (idEdit) {
      const idx = list.findIndex(x => x.idEstacion === idEdit);
      if (idx >= 0) list[idx] = { ...list[idx], ...params };
    } else {
      list.push({ ...params, idEstacion: 'EST_TMP' + Date.now(), activo: '1', _tmp: true });
    }
    closeModal('modalEstacion');
    renderInfra();
    try {
      const res = await API.post(idEdit ? 'actualizarEstacion' : 'crearEstacion', params);
      if (!idEdit && res?.idEstacion) {
        const tmp = list.findIndex(x => x._tmp);
        if (tmp >= 0) { list[tmp].idEstacion = res.idEstacion; delete list[tmp]._tmp; }
      }
      toast('Estación guardada ✓', 'ok');
      renderInfra();
      // Auto-replicación: si es nueva y la zona ya tiene series, crearlas para esta estación
      if (!idEdit && res?.idEstacion && params.idZona) {
        await _replicarSeriesParaNuevaEstacion(res.idEstacion, params.idZona);
      }
    } catch(e) {
      cfgData.estaciones = backup;
      renderInfra();
      toast('Error: ' + e.message, 'error');
    }
  }

  // Si la zona ya tiene series configuradas, crear las filas correspondientes
  // para la nueva estación. Cada nueva fila empieza con correlativo=1.
  // El nombre de la serie se toma de la mayoría existente en la zona.
  async function _replicarSeriesParaNuevaEstacion(idEstacion, idZona) {
    if (!idEstacion || !idZona) return;
    const seriesZona = (cfgData.series || []).filter(s =>
      s.idZona === idZona && s.idEstacion !== idEstacion
    );
    if (!seriesZona.length) return; // zona sin series — no hay nada que replicar

    // Agrupar por tipoDocumento → escoger el nombre más frecuente
    const porTipo = {};
    seriesZona.forEach(s => {
      const k = s.tipoDocumento;
      if (!porTipo[k]) porTipo[k] = [];
      porTipo[k].push(s);
    });

    const nuevasFilas = [];
    Object.keys(porTipo).forEach(tipo => {
      const grupos = porTipo[tipo];
      const conteo = {};
      grupos.forEach(s => { conteo[s.serie] = (conteo[s.serie] || 0) + 1; });
      const nombreMasComun = Object.entries(conteo).sort((a, b) => b[1] - a[1])[0][0];
      // Verificar si ya existe (defensa contra duplicados)
      const yaExiste = (cfgData.series || []).some(s =>
        s.idEstacion === idEstacion && s.tipoDocumento === tipo
      );
      if (!yaExiste) {
        nuevasFilas.push({
          idEstacion,
          idZona,
          tipoDocumento: tipo,
          serie: nombreMasComun,
          correlativo: 1,
          activo: '1'
        });
      }
    });

    if (!nuevasFilas.length) return;

    // OPTIMISTA: agregar a cfgData.series con id temporal
    nuevasFilas.forEach(f => {
      cfgData.series.push({ ...f, idSerie: 'SER_TMP' + Date.now() + '_' + f.tipoDocumento, _tmp: true });
    });
    renderInfra();

    try {
      await Promise.all(nuevasFilas.map(f =>
        API.post('crearSerie', f).then(res => {
          if (res?.idSerie) {
            const tmp = cfgData.series.find(s => s._tmp && s.idEstacion === idEstacion && s.tipoDocumento === f.tipoDocumento);
            if (tmp) { tmp.idSerie = res.idSerie; delete tmp._tmp; }
          }
        })
      ));
      toast(`✓ Auto-replicadas ${nuevasFilas.length} serie${nuevasFilas.length === 1 ? '' : 's'} desde la zona`, 'ok');
      renderInfra();
    } catch(e) {
      console.error('[replicar series]', e);
      // Quitar las _tmp que no pudieron sincronizarse
      cfgData.series = cfgData.series.filter(s => !s._tmp);
      renderInfra();
      toast('La estación se creó pero falló la replicación de series', 'warn');
    }
  }

  async function eliminarEstacion() {
    const id = $('estId')?.value;
    if (!id) return;
    const e = cfgData.estaciones.find(x => x.idEstacion === id);
    if (!e) return;
    const numImp = cfgData.impresoras.filter(i => i.idEstacion === id).length;
    const msg = numImp > 0
      ? `¿Desactivar la estación "${e.nombre}"?\n\nTiene ${numImp} impresora${numImp === 1 ? '' : 's'} asociada${numImp === 1 ? '' : 's'}. Puedes reactivarla luego.`
      : `¿Desactivar la estación "${e.nombre}"?\n\nPodrás reactivarla cuando quieras.`;
    if (!await _modalConfirm(msg, { warning: true, titulo: 'Desactivar estación' })) return;
    closeModal('modalEstacion');
    const previo = e.activo;
    e.activo = '0';
    renderInfra();
    try {
      await API.post('actualizarEstacion', { idEstacion: id, activo: '0' });
      toast('Estación desactivada', 'ok');
    } catch(err) {
      e.activo = previo;
      renderInfra();
      toast('Error: ' + err.message, 'error');
    }
  }

  function _impActualizarPreview() {
    const nom = ($('impNombre')?.value || '').trim();
    const tipo = $('impTipo')?.value || 'TICKET';
    const app = $('impApp')?.value || 'mosExpress';
    const idEst = $('impEstacion')?.value || '';
    const estName = idEst ? (cfgData.estaciones.find(e => e.idEstacion === idEst)?.nombre || '—') : 'Sin estación';
    const tipoIcon = { TICKET: '🖨️', ADHESIVO: '🏷️', ZPL: '📄', AMBAS: '🖨️' }[tipo] || '🖨️';
    const appLbl = app === 'mosExpress' ? 'ME' : 'WH';
    const sub = $('modalImpSubtitle');
    if (sub) sub.textContent = nom ? `${tipo} · ${appLbl} · ${estName}` : 'PrintNode endpoint';
    const ico = $('impIconPreview');
    if (ico) ico.textContent = tipoIcon;
  }

  function abrirModalImpresora(id, presetIdEstacion) {
    ['Id','Nombre','PrintNodeId','Estacion','Zona','Desc'].forEach(f => {
      const el = $('imp' + f); if (el && el.tagName !== 'SELECT') el.value = '';
    });
    // Poblar select de estaciones dinámicamente
    const estSelect = $('impEstacion');
    if (estSelect) {
      estSelect.innerHTML = '<option value="">— Sin estación —</option>' +
        cfgData.estaciones.filter(e => String(e.activo) === '1').map(e => {
          const tipoIc = { CAJA: '🛒', ALMACEN: '🏭', ENVASADO: '🍶' }[e.tipo] || '📍';
          return `<option value="${e.idEstacion}">${tipoIc} ${e.nombre}</option>`;
        }).join('');
    }
    const estadoWrap = $('impEstadoWrap');
    const btnElim = $('impBtnEliminar');
    const tg = $('impEstadoToggle');
    if (id) {
      const imp = cfgData.impresoras.find(x => x.idImpresora === id);
      if (!imp) return;
      $('modalImpTitle').textContent = 'Editar Impresora';
      $('impId').value          = imp.idImpresora;
      $('impNombre').value      = imp.nombre || '';
      $('impPrintNodeId').value = imp.printNodeId || '';
      $('impTipo').value        = imp.tipo || 'TICKET';
      if (estSelect) estSelect.value = imp.idEstacion || '';
      $('impZona').value        = imp.idZona || '';
      $('impApp').value         = imp.appOrigen || 'mosExpress';
      $('impDesc').value        = imp.descripcion || '';
      if (tg) tg.checked = String(imp.activo) === '1' || imp.activo === 1 || imp.activo === true;
      if (estadoWrap) estadoWrap.classList.remove('hidden');
      if (btnElim)    btnElim.classList.remove('hidden');
    } else {
      $('modalImpTitle').textContent = 'Nueva Impresora';
      $('impId').value = '';
      $('impTipo').value = 'TICKET';
      $('impApp').value = 'mosExpress';
      if (tg) tg.checked = true;
      if (estadoWrap) estadoWrap.classList.add('hidden');
      if (btnElim)    btnElim.classList.add('hidden');
      // Preset desde la card de estación
      if (presetIdEstacion) {
        const e = cfgData.estaciones.find(x => x.idEstacion === presetIdEstacion);
        if (e) {
          if (estSelect)        estSelect.value         = e.idEstacion;
          if ($('impZona'))     $('impZona').value      = e.idZona || '';
          if ($('impApp'))      $('impApp').value       = e.appOrigen || 'mosExpress';
        }
      }
    }
    _impActualizarPreview();
    openModal('modalImpresora');
  }

  async function guardarImpresora() {
    const idEdit = $('impId')?.value || undefined;
    const tg = $('impEstadoToggle');
    const idEstSel = $('impEstacion')?.value || '';
    // Si seleccionó estación, deducir idZona y app
    let idZona = $('impZona')?.value || '';
    let appOrigen = $('impApp')?.value || 'mosExpress';
    if (idEstSel) {
      const e = cfgData.estaciones.find(x => x.idEstacion === idEstSel);
      if (e) { idZona = e.idZona || idZona; appOrigen = e.appOrigen || appOrigen; }
    }
    const params = {
      idImpresora:  idEdit,
      nombre:       ($('impNombre')?.value || '').trim(),
      printNodeId:  $('impPrintNodeId')?.value || '',
      tipo:         $('impTipo')?.value || 'TICKET',
      idEstacion:   idEstSel,
      idZona,
      appOrigen,
      descripcion:  $('impDesc')?.value || ''
    };
    if (idEdit) params.activo = (tg && tg.checked) ? '1' : '0';
    if (!params.nombre) { toast('Nombre requerido', 'error'); return; }
    if (!params.idImpresora) delete params.idImpresora;
    // OPTIMISTA
    const list = cfgData.impresoras;
    const backup = list.slice();
    if (idEdit) {
      const idx = list.findIndex(x => x.idImpresora === idEdit);
      if (idx >= 0) list[idx] = { ...list[idx], ...params };
    } else {
      list.push({ ...params, idImpresora: 'IMP_TMP' + Date.now(), activo: '1', _tmp: true });
    }
    closeModal('modalImpresora');
    renderInfra();
    try {
      const res = await API.post(idEdit ? 'actualizarImpresora' : 'crearImpresora', params);
      if (!idEdit && res?.idImpresora) {
        const tmp = list.findIndex(x => x._tmp);
        if (tmp >= 0) { list[tmp].idImpresora = res.idImpresora; delete list[tmp]._tmp; }
      }
      toast('Impresora guardada ✓', 'ok');
      renderInfra();
    } catch(e) {
      cfgData.impresoras = backup;
      renderInfra();
      toast('Error: ' + e.message, 'error');
    }
  }

  async function eliminarImpresora() {
    const id = $('impId')?.value;
    if (!id) return;
    const i = cfgData.impresoras.find(x => x.idImpresora === id);
    if (!i) return;
    if (!await _modalConfirm(`¿Desactivar la impresora "${i.nombre}"?\n\nDejará de recibir trabajos de impresión. Puedes reactivarla luego.`, { warning: true, titulo: 'Desactivar impresora' })) return;
    closeModal('modalImpresora');
    const previo = i.activo;
    i.activo = '0';
    renderInfra();
    try {
      await API.post('actualizarImpresora', { idImpresora: id, activo: '0' });
      toast('Impresora desactivada', 'ok');
    } catch(e) {
      i.activo = previo;
      renderInfra();
      toast('Error: ' + e.message, 'error');
    }
  }

  // Paleta de colores neón para avatares
  const _PERS_COLORS = [
    '#22c55e', '#10b981', '#06b6d4', '#0ea5e9', '#3b82f6',
    '#6366f1', '#8b5cf6', '#a855f7', '#d946ef', '#ec4899',
    '#f43f5e', '#ef4444', '#f97316', '#f59e0b', '#eab308',
    '#84cc16', '#14b8a6', '#22d3ee', '#fb7185', '#fbbf24'
  ];

  function _persColoresEnUso(excluirId) {
    const all = [...(cfgData.personalMOS || []), ...(cfgData.personal || [])];
    return new Set(
      all.filter(p => String(p.estado) === '1' && p.idPersonal !== excluirId)
         .map(p => String(p.color || '').toLowerCase())
    );
  }

  function _persRandomColor() {
    const enUso = _persColoresEnUso($('persId')?.value);
    const disponibles = _PERS_COLORS.filter(c => !enUso.has(c.toLowerCase()));
    const pool = disponibles.length ? disponibles : _PERS_COLORS;
    const elegido = pool[Math.floor(Math.random() * pool.length)];
    const hidden = $('persColor');
    if (hidden) hidden.value = elegido;
    _persRenderChips();
    _persActualizarPreview();
  }

  function _persSeleccionarColor(c) {
    const hidden = $('persColor');
    if (hidden) hidden.value = c;
    _persRenderChips();
    _persActualizarPreview();
  }

  function _persRenderChips() {
    const cont = $('persColorChips');
    if (!cont) return;
    const sel = String($('persColor')?.value || '').toLowerCase();
    const enUso = _persColoresEnUso($('persId')?.value);
    cont.innerHTML = _PERS_COLORS.map(c => {
      const isSel = c.toLowerCase() === sel;
      const ocupado = enUso.has(c.toLowerCase()) && !isSel;
      const cls = `inline-block w-6 h-6 rounded-full transition-all`;
      const ring = isSel ? 'box-shadow:0 0 0 2px #fff,0 0 12px ' + c + ';transform:scale(1.15);' : '';
      const dim  = ocupado ? 'opacity:0.25;' : '';
      const cursor = ocupado ? 'cursor:not-allowed;' : 'cursor:pointer;';
      return `<button type="button" class="${cls}" style="background:${c};${ring}${dim}${cursor}border:2px solid #0d1526;"
              ${ocupado ? 'disabled' : ''}
              title="${ocupado ? 'En uso por otro usuario activo' : c}"
              onclick="MOS._persSeleccionarColor('${c}')"></button>`;
    }).join('');
  }

  function _persRandomPin() {
    // [dueño] PIN único entre TODO el personal (WH + MOS): el login de WH es por PIN solo,
    // así que un PIN repetido loguearía a la persona equivocada.
    const excl = $('persId')?.value;
    const enUso = new Set(
      [].concat(cfgData.personalMOS || [], cfgData.personal || [])
        .filter(p => p.idPersonal !== excl)
        .map(p => String(p.pin || ''))
        .filter(Boolean)
    );
    let intentos = 0, pin;
    do {
      pin = String(Math.floor(1000 + Math.random() * 9000));
      intentos++;
    } while (enUso.has(pin) && intentos < 200);
    const inp = $('persPin');
    if (inp) { inp.type = 'text'; inp.value = pin; inp.dataset.prefilled = ''; }   // recién generado (no es clave existente) → visible; el ojito lo controla
    const eye = $('persPinEye'); if (eye) eye.textContent = '🙈';
  }

  // [dueño] ojito 👁 del PIN: muestra/oculta la clave de acceso.
  // Revelar una clave YA guardada (pre-cargada en edición) es solo para MASTER.
  function _persTogglePin() {
    const inp = $('persPin'); const eye = $('persPinEye'); if (!inp) return;
    if (inp.type === 'password' && inp.dataset.prefilled === '1' && !_esMasterSession()) {
      toast('Solo Master puede ver la clave', 'error'); return;
    }
    const mostrar = inp.type === 'password';
    inp.type = mostrar ? 'text' : 'password';
    if (eye) eye.textContent = mostrar ? '🙈' : '👁';
  }

  // [dueño] Compartir el acceso por WhatsApp: link(s) de la app + usuario + clave (PIN).
  const _WH_URL = 'https://levo19.github.io/warehouseMos-/';
  const _MOS_URL = 'https://levo19.github.io/MOS/';
  const _ME_URL = 'https://levo19.github.io/MosExpress/';
  function _persCompartirWhatsApp() {
    const nombre = ($('persNombre')?.value || '').trim();
    const apellido = ($('persApellido')?.value || '').trim();
    const appOrigen = $('persAppOrigen')?.value || '';
    const isMOS = (appOrigen === 'MOS');
    let pin = ($('persPin')?.value || '').trim();
    // [M1 · fix revisión 500x] Revelar el PIN GUARDADO (para compartirlo) es SOLO para Master — coherente con el
    // enmascarado del campo. Un admin no-master que dejó el campo en blanco NO puede sacar la clave existente por
    // el botón Compartir (antes era un bypass de un clic). Si no es Master, debe escribir/generar un PIN nuevo.
    if (!pin) {
      if (!_esMasterSession()) { toast('Solo Master comparte una clave existente · escribe o 🎲 genera un PIN', 'error'); return; }
      const idEdit = ($('persId')?.value || '').trim();
      if (idEdit) {
        const src = isMOS ? (cfgData.personalMOS || []) : (cfgData.personal || []);
        const p = src.find(x => x.idPersonal === idEdit);
        if (p && p.pin) pin = String(p.pin).trim();
      }
    }
    const rol = String($('persRol')?.value || '').toUpperCase();
    if (!nombre) { toast('Falta el nombre', 'error'); return; }
    if (!pin) { toast('Falta el PIN — genera uno con 🎲', 'error'); return; }
    const puedeMOS = isMOS || rol === 'ADMIN' || rol === 'MASTER' || !!($('persAccesoMos')?.checked);
    let msg = `👋 Hola ${nombre}${apellido ? ' ' + apellido : ''}! Este es tu acceso:\n\n`;
    // [M2 · fix revisión 500x] Link CORRECTO según la app del usuario (antes un cajero mosExpress recibía el
    // link del ALMACÉN). MOS-only recibe solo el link de MOS (abajo, por puedeMOS).
    if (appOrigen === 'warehouseMos')    msg += `📦 Almacén (WH): ${_WH_URL}\n`;
    else if (appOrigen === 'mosExpress') msg += `🛒 Caja (MosExpress): ${_ME_URL}\n`;
    if (puedeMOS) msg += `🖥️ MOS (panel admin): ${_MOS_URL}\n`;
    msg += `\n🔑 Tu clave (PIN): *${pin}*\n\n_Guárdala, es personal — no la compartas con nadie._`;
    window.open('https://wa.me/?text=' + encodeURIComponent(msg), '_blank');
    try { _opsBeep && _opsBeep('tac'); } catch(_){}
  }

  function _persActualizarPreview() {
    const ini = ($('persNombre')?.value || '').trim().charAt(0).toUpperCase()
              + ($('persApellido')?.value || '').trim().charAt(0).toUpperCase();
    const av = $('persAvatarPreview');
    if (av) {
      av.textContent = ini || '??';
      av.style.background = $('persColor')?.value || '#6366f1';
    }
    const sub = $('modalPersSubtitle');
    if (sub) {
      const rol = $('persRol')?.value || '';
      const app = $('persAppOrigen')?.value || '';
      sub.textContent = (rol || '—') + (app ? ' · ' + app : '');
    }
  }

  // Selecciona option case-insensitive — devuelve el value real del select
  function _selectOptionCI(selectEl, value) {
    if (!selectEl || !value) return false;
    const v = String(value).trim().toUpperCase();
    for (const opt of selectEl.options) {
      if (String(opt.value).trim().toUpperCase() === v) {
        selectEl.value = opt.value;
        return true;
      }
    }
    return false;
  }

  function abrirModalPersonal(id, appOrigen = 'warehouseMos') {
    ['Nombre','Apellido','Pin','Tarifa','Monto','Documento'].forEach(f => {
      const el = $('pers' + f); if (el && el.tagName !== 'SELECT') el.value = '';
    });
    // [419 · LOW10] al CREAR, prev='' → mandar documento solo si el admin escribe algo.
    if ($('persDocumento')) $('persDocumento').dataset.prev = '';
    $('persId').value = '';
    $('persAppOrigen').value = appOrigen;
    const isMOS = appOrigen === 'MOS';
    const pagoWrap = $('persPagoWrap'); if (pagoWrap) pagoWrap.style.display = isMOS ? 'none' : '';
    // [dueño] ascenso: el permiso admin a MOS solo aplica a operadores WH (los MOS ya son admin/master)
    const ascWrap = $('persAscensoWrap'); if (ascWrap) ascWrap.style.display = isMOS ? 'none' : '';
    // [Mockup modales] Acciones rápidas: solo al EDITAR (con id) — al crear no hay a quién apuntar
    const quickWrap = $('persQuickWrap'); if (quickWrap) quickWrap.classList.toggle('hidden', !id);
    if ($('persAccesoMos')) $('persAccesoMos').checked = false;
    // Set rol options based on app — todos en MAYÚSCULAS para coincidir con DB
    const rolSel = $('persRol');
    if (rolSel) {
      rolSel.innerHTML = isMOS
        ? '<option value="MASTER">MASTER (acceso total)</option><option value="ADMIN">ADMIN (sin configuración)</option>'
        : '<option value="ALMACENERO">ALMACENERO</option><option value="ENVASADOR">ENVASADOR</option>';
    }
    const pinInp = $('persPin');
    if (pinInp) pinInp.type = 'password';

    const source = isMOS ? cfgData.personalMOS : cfgData.personal;
    const estadoWrap = $('persEstadoWrap');
    const btnElim = $('persBtnEliminar');
    const pinHint = $('persPinHint');

    if (id) {
      const p = source.find(x => x.idPersonal === id);
      if (!p) return;
      $('modalPersTitle').textContent = isMOS ? 'Editar Usuario MOS' : 'Editar Operador';
      $('persId').value       = p.idPersonal;
      $('persNombre').value   = p.nombre || '';
      $('persApellido').value = p.apellido || '';
      if ($('persDocumento')) { const _d = p.documento || ''; $('persDocumento').value = _d; $('persDocumento').dataset.prev = _d; }   // [419] línea de crédito (prev = anti-wipe LOW10)
      // Match rol case-insensitive (la DB puede tener "MASTER" / "master" / "Admin"/etc.)
      if (rolSel && !_selectOptionCI(rolSel, p.rol)) {
        rolSel.value = isMOS ? 'ADMIN' : 'ALMACENERO';
      }
      $('persColor').value    = p.color || '#6366f1';
      if (!isMOS) {
        $('persMonto').value  = p.montoBase  || '';
        if ($('persAccesoMos')) $('persAccesoMos').checked = (p.accesoMos === true || p.accesoMos === '1' || p.accesoMos === 1);
      }
      // [dueño] PIN en edición: NO vacío → asteriscos. La clave real solo se pre-carga si
      // eres MASTER (un ADMIN no debe poder leerla ni inspeccionando el DOM). El ojo 👁 la revela
      // (gateado a Master en _persTogglePin). Otros roles: campo en blanco = deja el PIN actual al guardar.
      const pinEdit = $('persPin');
      if (pinEdit) {
        if (_esMasterSession() && p.pin) {
          pinEdit.type = 'password';           // muestra •••• (asteriscos)
          pinEdit.value = String(p.pin);        // clave real, oculta hasta tocar el ojo
          pinEdit.dataset.prefilled = '1';
        } else {
          pinEdit.type = 'password';
          pinEdit.value = '';
          pinEdit.dataset.prefilled = '';
        }
      }
      const pinEye0 = $('persPinEye'); if (pinEye0) pinEye0.textContent = '👁';
      // Toggle activo + botón eliminar visibles en edición
      if (estadoWrap) estadoWrap.classList.remove('hidden');
      if (btnElim)    btnElim.classList.remove('hidden');
      if (pinHint)    {
        pinHint.textContent = _esMasterSession() ? '(toca 👁 para ver · vacío = conservar)' : '(opcional al editar)';
        pinHint.className = 'text-slate-500 text-[10px]';
      }
      const tg = $('persEstadoToggle');
      if (tg) tg.checked = String(p.estado) === '1' || p.estado === true;
    } else {
      $('modalPersTitle').textContent = isMOS ? 'Nuevo Usuario MOS' : 'Nuevo Operador';
      if (rolSel) rolSel.value = isMOS ? 'ADMIN' : 'ALMACENERO';
      if (estadoWrap) estadoWrap.classList.add('hidden');
      if (btnElim)    btnElim.classList.add('hidden');
      if (pinHint)    { pinHint.textContent = 'requerido al crear', pinHint.className = 'text-amber-400 text-[10px]'; }
      // Auto: color random no-repetido + PIN random ÚNICO (WH y MOS) al crear.
      _persRandomColor();
      _persRandomPin();
    }
    _persRenderChips();
    _persActualizarPreview();
    openModal('modalPersonal');
  }

  async function guardarPersonal() {
    const appOrigen = $('persAppOrigen')?.value || 'warehouseMos';
    const isMOS = appOrigen === 'MOS';
    const idEdit = $('persId')?.value || undefined;
    const params = {
      idPersonal:  idEdit,
      nombre:      ($('persNombre')?.value || '').trim(),
      apellido:    ($('persApellido')?.value || '').trim(),
      rol:         $('persRol')?.value || (isMOS ? 'ADMIN' : 'ALMACENERO'),
      color:       $('persColor')?.value || '#6366f1',
      tipo:        'OPERADOR',
      appOrigen:   appOrigen
    };
    // [419 · review LOW10] documento = ID de TEXTO exacto (ceros a la izquierda cuentan).
    // Solo se manda si el input EXISTE y su valor CAMBIÓ respecto al prefill — así una
    // lista vieja en cache (sin documento) editada por otro campo NO borra la línea de
    // crédito con un '' silencioso (la RPC preserva cuando la clave está ausente).
    if ($('persDocumento')) {
      const _docNuevo = ($('persDocumento').value || '').trim();
      const _docPrev  = String($('persDocumento').dataset.prev ?? '');
      if (_docNuevo !== _docPrev) params.documento = _docNuevo;
    }
    if (!isMOS) {
      params.montoBase  = $('persMonto')?.value  || 0;
      // [dueño] ascenso dual: permiso admin a MOS (mantiene rol/pago de almacenero)
      params.accesoMos  = !!($('persAccesoMos')?.checked);
    }
    const pin = $('persPin')?.value;
    if (pin) params.pin = pin;
    // Estado del toggle (solo aplica al editar)
    if (idEdit) {
      const tg = $('persEstadoToggle');
      params.estado = (tg && tg.checked) ? '1' : '0';
    }
    if (!params.nombre) { toast('Nombre requerido', 'error'); return; }
    if (!params.idPersonal && !pin) { toast('PIN requerido al crear', 'error'); return; }

    // [v2.43.30] OPTIMISTA REFORZADO: card temp persiste hasta que el real llegue
    // Bug previo: loadConfig() sobrescribía la lista entera antes de que el real
    // llegara → la card temp se perdía y el user "no veía nada hasta salir/volver".
    // Fix: mergeamos la respuesta del API directo en la lista sin esperar loadConfig.
    const list = isMOS ? (cfgData.personalMOS || []) : (cfgData.personal || []);
    const backup = list.slice();
    const tmpId = 'TMP_' + Date.now();
    if (idEdit) {
      const idx = list.findIndex(x => x.idPersonal === idEdit);
      if (idx >= 0) list[idx] = { ...list[idx], ...params };
    } else {
      list.unshift({ idPersonal: tmpId, estado: '1', _tmp: true, ...params });
    }
    closeModal('modalPersonal');
    renderPersonal();
    toast(idEdit ? 'Actualizado ✓' : 'Creado ✓', 'ok');
    try {
      const r = await API.post(idEdit ? 'actualizarPersonalMaster' : 'crearPersonalMaster', params);
      const d = (r && r.data) || r || {};
      // Si el backend devuelve el idPersonal real, reemplazar el TMP localmente
      // sin esperar loadConfig (evita el flicker y la card vacía).
      if (!idEdit && d.idPersonal) {
        const idxTmp = list.findIndex(x => x.idPersonal === tmpId);
        if (idxTmp >= 0) {
          list[idxTmp] = { ...list[idxTmp], idPersonal: d.idPersonal, _tmp: false };
          renderPersonal();
        }
      }
      // Refresh en bg sin invalidar lo que tenemos
      setTimeout(() => { S.loaded['config'] = false; loadConfig().catch(() => {}); }, 1500);
    } catch(e) {
      // Revertir
      if (isMOS) cfgData.personalMOS = backup; else cfgData.personal = backup;
      renderPersonal();
      toast('Error: ' + e.message, 'error');
    }
  }

  // Toggle inline en card — activa/desactiva sin abrir modal
  async function togglePersonalActivo(idPersonal, appOrigen, ev) {
    if (ev) ev.stopPropagation();
    const isMOS = appOrigen === 'MOS';
    const list = isMOS ? (cfgData.personalMOS || []) : (cfgData.personal || []);
    const p = list.find(x => x.idPersonal === idPersonal);
    if (!p) return;
    const nuevoEstado = String(p.estado) === '1' ? '0' : '1';
    const accion = nuevoEstado === '1' ? 'activar' : 'desactivar';
    if (!await _modalConfirm(`¿${accion.charAt(0).toUpperCase() + accion.slice(1)} a ${p.nombre} ${p.apellido || ''}?`, { titulo: nuevoEstado === '1' ? 'Activar personal' : 'Desactivar personal' })) return;
    // OPTIMISTA
    const previo = p.estado;
    p.estado = nuevoEstado;
    renderPersonal();
    try {
      await API.post('actualizarPersonalMaster', {
        idPersonal: idPersonal,
        estado:     nuevoEstado,
        appOrigen:  appOrigen
      });
      toast(`${p.nombre} ${nuevoEstado === '1' ? 'activado' : 'desactivado'}`, 'ok');
    } catch(e) {
      p.estado = previo;
      renderPersonal();
      toast('Error: ' + e.message, 'error');
    }
  }

  async function eliminarPersonal() {
    const id = $('persId')?.value;
    const appOrigen = $('persAppOrigen')?.value || 'warehouseMos';
    if (!id) return;
    const isMOS = appOrigen === 'MOS';
    const list = isMOS ? cfgData.personalMOS : cfgData.personal;
    const p = (list || []).find(x => x.idPersonal === id);
    if (!p) return;
    if (!await _modalConfirm(`¿Eliminar a ${p.nombre} ${p.apellido || ''}?\n\nEsta acción no se puede deshacer.`, { danger: true, titulo: 'Eliminar personal', okText: 'Sí, eliminar' })) return;
    closeModal('modalPersonal');
    // OPTIMISTA
    const backup = list.slice();
    const idx = list.findIndex(x => x.idPersonal === id);
    if (idx >= 0) list.splice(idx, 1);
    renderPersonal();
    toast('Eliminado ✓', 'ok');
    try {
      await API.post('eliminarPersonalMaster', { idPersonal: id, appOrigen });
    } catch(e) {
      if (isMOS) cfgData.personalMOS = backup; else cfgData.personal = backup;
      renderPersonal();
      toast('Error: ' + e.message, 'error');
    }
  }

  function _serieActualizarPreview() {
    const tipo = $('serieTipo')?.value || 'NOTA_VENTA';
    const serie = ($('serieSerie')?.value || '').trim();
    const ico = { NOTA_VENTA: '📋', BOLETA: '🧾', FACTURA: '🧮' }[tipo] || '📋';
    const sub = $('modalSerieSubtitle');
    if (sub) sub.textContent = serie ? `${tipo} · ${serie}` : 'NubeFact / SUNAT';
    const ip = $('serieIconPreview');
    if (ip) ip.textContent = ico;
  }

  // Abre modal para crear/editar serie de una zona+tipoDocumento
  // Si edicion=true, pre-llena con la serie actual; si no, modo crear
  function abrirModalSerieZona(idZona, tipoDocumento, edicion) {
    const z = cfgData.zonas.find(x => x.idZona === idZona);
    if (!z) return;
    const estZona = (cfgData.estaciones || []).filter(e => e.idZona === idZona && String(e.activo) === '1');

    $('serieZonaId').value = idZona;
    $('serieTipo').value = tipoDocumento;
    $('serieTipoOriginal').value = tipoDocumento;
    $('serieZonaNombre').textContent = z.nombre;

    if (estZona.length === 0) {
      toast('Crea estaciones en esta zona antes de configurar series', 'warn');
      return;
    }

    // Lista de estaciones afectadas
    const tipoIc = { CAJA: '🛒', ALMACEN: '🏭', ENVASADO: '🍶' };
    $('serieEstacionesCount').textContent = estZona.length;
    $('serieEstacionesList').innerHTML = estZona.map(e =>
      `<div>${tipoIc[e.tipo] || '📍'} ${e.nombre} <span class="text-slate-600 font-mono text-[10px]">${e.idEstacion}</span></div>`
    ).join('');

    const wrap = $('serieEstadoWrap');
    const btnElim = $('serieBtnEliminar');
    const tg = $('serieEstadoToggle');

    if (edicion) {
      // Encontrar series existentes de este tipo en esta zona
      const seriesActuales = (cfgData.series || []).filter(s => s.idZona === idZona && s.tipoDocumento === tipoDocumento);
      $('modalSerieTitle').textContent = `Editar serie ${tipoDocumento}`;
      const nombre = seriesActuales[0]?.serie || '';
      const corrMax = Math.max(0, ...seriesActuales.map(s => parseInt(s.correlativo, 10) || 0));
      $('serieSerie').value = nombre;
      $('serieCorrelativo').value = corrMax;
      const todasActivas = seriesActuales.every(s => String(s.activo) === '1');
      if (tg) tg.checked = todasActivas;
      if (wrap) wrap.classList.remove('hidden');
      if (btnElim) btnElim.classList.remove('hidden');
    } else {
      $('modalSerieTitle').textContent = `Nueva serie ${tipoDocumento}`;
      $('serieSerie').value = '';
      $('serieCorrelativo').value = 1;
      if (tg) tg.checked = true;
      if (wrap) wrap.classList.add('hidden');
      if (btnElim) btnElim.classList.add('hidden');
    }

    _serieActualizarPreview();
    openModal('modalSerie');
  }

  async function guardarSerieZona() {
    const idZona = $('serieZonaId')?.value;
    const tipoDocumento = $('serieTipo')?.value;
    const tipoOrig = $('serieTipoOriginal')?.value;
    const nombre = ($('serieSerie')?.value || '').trim();
    const correlativo = parseInt($('serieCorrelativo')?.value || '1', 10) || 1;
    const tg = $('serieEstadoToggle');
    const activo = tg ? (tg.checked ? '1' : '0') : '1';

    if (!nombre) { toast('Nombre de serie requerido', 'error'); return; }
    if (!idZona) { toast('Zona no encontrada', 'error'); return; }

    const estZona = (cfgData.estaciones || []).filter(e => e.idZona === idZona && String(e.activo) === '1');
    if (!estZona.length) { toast('La zona no tiene estaciones activas', 'warn'); return; }

    const seriesExistentes = (cfgData.series || []).filter(s => s.idZona === idZona && s.tipoDocumento === tipoOrig);
    const esEdicion = seriesExistentes.length > 0;

    closeModal('modalSerie');
    toast('Guardando serie...', 'info');

    // OPTIMISTA: actualizar cfgData.series localmente
    const backup = (cfgData.series || []).slice();
    const promesas = [];

    let creadas = 0, actualizadas = 0;
    for (const e of estZona) {
      const existente = seriesExistentes.find(s => s.idEstacion === e.idEstacion);
      if (existente) {
        // Actualizar nombre/activo (NO sobreescribir correlativo si es mayor al ingresado)
        const nuevoCorr = parseInt(existente.correlativo, 10) >= correlativo
          ? existente.correlativo
          : correlativo;
        existente.serie = nombre;
        existente.tipoDocumento = tipoDocumento;
        existente.correlativo = nuevoCorr;
        existente.activo = activo;
        promesas.push(API.post('actualizarSerie', {
          idSerie: existente.idSerie,
          serie: nombre,
          tipoDocumento,
          correlativo: nuevoCorr,
          activo
        }));
        actualizadas++;
      } else {
        // Crear nueva fila para esta estación (también en modo edición:
        // completa la cobertura si la zona tiene estaciones sin esta serie)
        const tmp = {
          idSerie: 'SER_TMP' + Date.now() + '_' + e.idEstacion,
          idEstacion: e.idEstacion,
          idZona,
          tipoDocumento,
          serie: nombre,
          correlativo: esEdicion ? 1 : correlativo, // estación nueva siempre arranca en 1
          activo,
          _tmp: true
        };
        cfgData.series.push(tmp);
        promesas.push(API.post('crearSerie', {
          idEstacion: e.idEstacion,
          idZona,
          tipoDocumento,
          serie: nombre,
          correlativo: tmp.correlativo,
          activo
        }).then(res => {
          if (res?.idSerie) tmp.idSerie = res.idSerie;
          delete tmp._tmp;
        }));
        creadas++;
      }
    }

    renderInfra();

    try {
      await Promise.all(promesas);
      const partes = [];
      if (actualizadas) partes.push(`${actualizadas} actualizada${actualizadas === 1 ? '' : 's'}`);
      if (creadas)      partes.push(`${creadas} creada${creadas === 1 ? '' : 's'} (auto)`);
      toast(`Serie ${tipoDocumento}: ${partes.join(' · ')} ✓`, 'ok');
    } catch(e) {
      console.error('[guardarSerieZona]', e);
      cfgData.series = backup;
      renderInfra();
      toast('Error: ' + (e.message || 'falló sincronización'), 'error');
    }
  }

  async function eliminarSerieZona() {
    const idZona = $('serieZonaId')?.value;
    const tipoDocumento = $('serieTipoOriginal')?.value;
    if (!idZona || !tipoDocumento) return;
    const seriesActuales = (cfgData.series || []).filter(s => s.idZona === idZona && s.tipoDocumento === tipoDocumento);
    if (!seriesActuales.length) return;
    if (!await _modalConfirm(`¿Desactivar la serie ${tipoDocumento} en ${seriesActuales.length} estación(es) de esta zona?\n\nMosExpress dejará de emitir documentos de este tipo. Puedes reactivarla luego.`, { warning: true, titulo: 'Desactivar serie' })) return;
    closeModal('modalSerie');

    const backup = cfgData.series.slice();
    seriesActuales.forEach(s => { s.activo = '0'; });
    renderInfra();
    try {
      await Promise.all(seriesActuales.map(s =>
        API.post('actualizarSerie', { idSerie: s.idSerie, activo: '0' })
      ));
      toast('Serie desactivada', 'ok');
    } catch(e) {
      cfgData.series = backup;
      renderInfra();
      toast('Error: ' + e.message, 'error');
    }
  }



  // Close modal on backdrop click — usa _validBackdropClose para evitar
  // cierre al arrastrar selección de texto desde un input hasta el backdrop.
  // El handler inline de cada modal (onclick="...") usa la misma protección;
  // este handler global cubre los modales que no la tienen inline.
  document.addEventListener('click', e => {
    if (e.target.classList.contains('modal-backdrop')) {
      if (_validBackdropClose(e, e.target)) {
        e.target.classList.remove('open');
        e.target.classList.add('hidden');
      }
    }
  });

  // Wrapper compat — redirige al nuevo renderizado modernizado

  // ════════════════════════════════════════════════════════════
  // ║ MÓDULO CAJAS MODERNIZADO (estilo Bloomberg/trading)       ║
  // ════════════════════════════════════════════════════════════
  let _cjState = {
    fecha: null,
    calMes: null,
    expandido: new Set(),
    livePulseTimer: null,
    elapsedTimer: null,
    tvActivo: false,
    tvAutoTimer: null,
    tkFiltro: 'todos',
    tkCajaFiltro: '',
    tkBuscar: '',
    tkDoc: '',             // [rango] filtro tipo doc: '' | 'NV' | 'B' | 'F'
    tkZona: '',            // [zona] filtro por zona emisora
    tkDesde: '', tkHasta: '',  // [rango] rango de fechas del buscador de tickets
    tkRangoActivo: false,  // [rango] true = usa S._cjTkRangoData; false = día activo
    chunksAnteriores: new Map(),  // idCaja → cantidadTickets para detectar cambios
  };

  function _cjFecha() { return _cjState.fecha || $('cjFecha')?.value || today(); }

  function _cjActualizarFechaUI() {
    const fecha = _cjFecha();
    const lbl = $('cjFechaLabel');
    const badge = $('cjDayBadge');
    const hoy = today();
    const a = new Date(fecha + 'T00:00:00');
    const h = new Date(hoy + 'T00:00:00');
    const diff = Math.round((a - h) / 86400000);
    if (lbl) {
      const txt = a.toLocaleDateString('es-PE', { day:'2-digit', month:'short', year:'2-digit' });
      lbl.textContent = (diff === 0) ? `Hoy · ${txt}` : txt;
    }
    if (badge) {
      let txt = '';
      if (diff === 0)       txt = '🟢 Hoy';
      else if (diff === -1) txt = 'Ayer';
      else if (diff === 1)  txt = 'Mañana';
      else if (diff < 0)    txt = `Hace ${-diff} días`;
      else                  txt = `+${diff} días`;
      badge.textContent = txt;
    }
    // Banner archivo cuando no es hoy
    const banner = $('cjBannerArchivo');
    if (banner) banner.classList.toggle('hidden', diff === 0);
  }

  function cjDia(delta) {
    const cur = _cjFecha();
    const [y, m, d] = cur.split('-').map(Number);
    const dt = new Date(y, m - 1, d);
    dt.setDate(dt.getDate() + delta);
    const nueva = dt.getFullYear() + '-' + String(dt.getMonth()+1).padStart(2,'0') + '-' + String(dt.getDate()).padStart(2,'0');
    _cjState.fecha = nueva;
    const inp = $('cjFecha'); if (inp) inp.value = nueva;
    _finBeep('nav');
    _cjActualizarFechaUI();
    _cjRender();
    _cjAsegurarDia(nueva).then(c => { if (c) _cjRender(); });   // [historial] fuera de 30d → jala
  }
  function cjIrHoy() {
    _cjState.fecha = today();
    const inp = $('cjFecha'); if (inp) inp.value = _cjState.fecha;
    _finBeep('ok');
    _cjActualizarFechaUI();
    _cjRender();
  }
  function cjAbrirCalendario(btn) {
    const dp = $('cjDatepicker');
    if (!dp) return;
    if (!dp.classList.contains('hidden')) { dp.classList.add('hidden'); return; }
    const cur = _cjFecha();
    const d = new Date(cur + 'T00:00:00');
    _cjState.calMes = { y: d.getFullYear(), m: d.getMonth() };
    _cjCalRender();
    _cjCalCargarMes(d.getFullYear(), d.getMonth());   // [calendario] marca días con tickets
    const r = btn.getBoundingClientRect();
    dp.style.left = Math.max(8, Math.min(window.innerWidth - 250, r.left)) + 'px';
    dp.style.top  = (r.bottom + 6) + 'px';
    dp.classList.remove('hidden');
    _finBeep('click');
    setTimeout(() => {
      const closer = e => {
        if (!dp.contains(e.target) && !btn.contains(e.target)) {
          dp.classList.add('hidden');
          document.removeEventListener('click', closer);
        }
      };
      document.addEventListener('click', closer);
    }, 50);
  }
  function cjCalNavMes(delta) {
    if (!_cjState.calMes) return;
    let { y, m } = _cjState.calMes;
    m += delta;
    if (m < 0)  { m = 11; y--; }
    if (m > 11) { m = 0;  y++; }
    _cjState.calMes = { y, m };
    _cjCalRender();
    _cjCalCargarMes(y, m);   // [calendario] marca días con tickets del nuevo mes
  }
  function _cjCalRender() {
    const grid = $('cjCalGrid');
    const lbl  = $('cjCalMesAnio');
    if (!grid || !_cjState.calMes) return;
    const { y, m } = _cjState.calMes;
    const meses = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
    if (lbl) lbl.textContent = `${meses[m]} ${y}`;
    const primero = new Date(y, m, 1);
    let primerDow = primero.getDay();
    primerDow = primerDow === 0 ? 6 : primerDow - 1;
    const ultimo = new Date(y, m + 1, 0).getDate();
    const hoy = today();
    const sel = _cjFecha();
    const mesKey = `${y}-${String(m + 1).padStart(2, '0')}`;
    const diasT = (S._cjCalDias && S._cjCalDias[mesKey]) || {};
    let html = '';
    for (let i = 0; i < primerDow; i++) html += '<button class="log-cal-day empty"></button>';
    for (let dia = 1; dia <= ultimo; dia++) {
      const f = `${y}-${String(m + 1).padStart(2, '0')}-${String(dia).padStart(2, '0')}`;
      const cls = ['log-cal-day'];
      if (f === hoy) cls.push('today');
      if (f === sel) cls.push('selected');
      // [calendario] marca visual: borde si hay tickets ese día + punto ámbar si hay crédito
      const info = diasT[f];
      let extra = '', dot = '';
      if (info && info.n > 0) {
        cls.push('cj-cal-tick');
        if (info.credito) { cls.push('cj-cal-cred'); dot = '<span class="cj-cal-dot"></span>'; }
        const tot = (typeof info.total === 'number') ? info.total.toFixed(0) : info.total;
        extra = ` title="${info.n} ticket${info.n > 1 ? 's' : ''}${info.credito ? ' · con crédito' : ''} · S/ ${tot}"`;
      }
      html += `<button class="${cls.join(' ')}"${extra} onclick="MOS.cjElegirFecha('${f}')">${dia}${dot}</button>`;
    }
    grid.innerHTML = html;
  }
  function cjElegirFecha(f) {
    _cjState.fecha = f;
    const inp = $('cjFecha'); if (inp) inp.value = f;
    $('cjDatepicker')?.classList.add('hidden');
    _finBeep('click');
    _cjActualizarFechaUI();
    _cjRender();
    _cjAsegurarDia(f).then(c => { if (c) _cjRender(); });   // [historial] día fuera de 30d → jala y re-pinta
  }

  // [historial] resta N días a un 'YYYY-MM-DD'
  function _cjFechaMenosDias(fechaStr, n) {
    const [y, m, d] = String(fechaStr).split('-').map(Number);
    const dt = new Date(y, m - 1, d); dt.setDate(dt.getDate() - n);
    return dt.getFullYear() + '-' + String(dt.getMonth() + 1).padStart(2, '0') + '-' + String(dt.getDate()).padStart(2, '0');
  }
  // [historial] al viajar a un día FUERA de la ventana de 30d, jala sus tickets (mos.tickets_dia)
  // y los mergea en el cache. Devuelve true si trajo datos nuevos (para re-pintar).
  async function _cjAsegurarDia(fecha) {
    if (!fecha) return false;
    const limite = _cjFechaMenosDias(today(), 30);
    if (fecha >= limite) return false;                       // dentro de 30d → ya en cache
    if (!S._cjDiasExtra) S._cjDiasExtra = new Set();
    if (S._cjDiasExtra.has(fecha)) return false;             // ya jalado antes
    try {
      // [historial] día COMPLETO: cajas + tickets + KPIs (cierres_caja con fecha) → la vista entera carga
      const d = await API.get('getCierresDia', { fecha });
      S._cjDiasExtra.add(fecha);
      if (!d) return false;
      // [fix bug] guardar en el STORE PERSISTENTE (sobrevive a las recargas de 30d que pisan
      // S._todosTickets/S._todasCajas → antes el día viejo se vaciaba al re-renderizar).
      if (!S._cjHistTickets) S._cjHistTickets = [];
      if (!S._cjHistCajas)   S._cjHistCajas   = [];
      (d.todosTickets || []).forEach(t => S._cjHistTickets.push(t));
      [...(d.abiertas || []), ...(d.cerradas || [])].forEach(c => S._cjHistCajas.push(c));
      _cjMergeHist();
      return true;
    } catch (e) { console.warn('[cj] getCierresDia:', e?.message || e); return false; }
  }
  // [fix bug] re-inyecta el histórico (días fuera de 30d) en los caches vivos, sin duplicar.
  // Se llama tras _cjAsegurarDia y DESPUÉS de cada recarga de cierres_caja (que reescribe los caches).
  function _cjMergeHist() {
    if (S._cjHistTickets && S._cjHistTickets.length) {
      const cache = S._todosTickets || [];
      const ids = new Set(cache.map(t => String(t.idVenta)));
      S._cjHistTickets.forEach(t => { const k = String(t.idVenta); if (!ids.has(k)) { cache.push(t); ids.add(k); } });
      S._todosTickets = cache;
    }
    if (S._cjHistCajas && S._cjHistCajas.length) {
      const cajas = S._todasCajas || [];
      const ids = new Set(cajas.map(c => String(c.idCaja)));
      S._cjHistCajas.forEach(c => { const k = String(c.idCaja); if (!ids.has(k)) { cajas.push(c); ids.add(k); } });
      S._todasCajas = cajas;
    }
  }
  // [calendario] jala qué días del mes tienen tickets (mos.dias_con_tickets) y re-pinta con marcas
  async function _cjCalCargarMes(y, m) {
    const mes = y + '-' + String(m + 1).padStart(2, '0');
    if (!S._cjCalDias) S._cjCalDias = {};
    if (S._cjCalDias[mes]) return;                           // mes ya cacheado
    try {
      const r = await API.get('getDiasConTickets', { mes });
      S._cjCalDias[mes] = (r && r.dias) || (r && r.data && r.data.dias) || {};
      _cjCalRender();
    } catch (e) { console.warn('[cj] dias_con_tickets:', e?.message || e); }
  }

  // ── Render principal ───────────────────────────────────
  function _cjRender() {
    if (!_cjState.fecha) _cjState.fecha = today();
    const inp = $('cjFecha'); if (inp && !inp.value) inp.value = _cjState.fecha;
    _cjActualizarFechaUI();

    const fecha = _cjFecha();
    const esHoy = fecha === today();

    const todas = S._todasCajas || [];
    const tkAll = S._todosTickets || [];

    // Filtrar cajas según la fecha activa (estilo finanzas)
    const cajasDelDia = todas.filter(c => {
      const fa = (c.fechaApertura || '').substring(0, 10);
      const fc = (c.fechaCierre   || '').substring(0, 10);
      // Si es hoy: incluir todas las abiertas (sin cierre) + cerradas de hoy
      if (esHoy) {
        if (c.estado === 'ABIERTA') return true;
        return fc === fecha || fa === fecha;
      }
      // Días pasados: solo las que cerraron (o abrieron) en esa fecha
      return fc === fecha || fa === fecha;
    });
    const abiertas = cajasDelDia.filter(c => c.estado === 'ABIERTA');
    const cerradas = cajasDelDia.filter(c => c.estado !== 'ABIERTA');

    // Tickets del día: filtrar por fecha
    const tkDia = tkAll.filter(t => (t.fecha || '').substring(0, 10) === fecha);
    const tkMes = tkAll.filter(t => {
      const f = (t.fecha || '').substring(0, 10);
      const cutoff = _fechaOffset(fecha, -29);
      return f && f <= fecha && f >= cutoff;
    });

    // Identificar caja líder del día (corona 👑) — la de mayor totalVentas con tickets > 0
    const cajasConVentas = cajasDelDia
      .filter(c => (parseFloat(c.totalVentas) || 0) > 0 && (c.tickets || 0) > 0)
      .sort((a, b) => (parseFloat(b.totalVentas) || 0) - (parseFloat(a.totalVentas) || 0));
    const idCajaLider = cajasConVentas.length > 0 ? String(cajasConVentas[0].idCaja) : null;

    _cjRenderTicker(cajasDelDia, tkDia, esHoy);
    _cjRenderKPIs(cajasDelDia, tkDia, tkMes, fecha);
    _cjRenderCajas(abiertas, cerradas, fecha, esHoy, idCajaLider);
    _cjRenderActividad(tkDia, esHoy);
    _cjRender7d(fecha);
    // [v40.4] Cargar créditos (1 fetch trae 30 días, después renderiza la mano
    // de la fecha activa según el filtro). Cuando el usuario cambie la fecha,
    // _cjRenderManoDelDia se vuelve a invocar sin refetch.
    if (!_cjCreditosState.todosLosGrupos.length) _cjCargarCreditosPendientes();
    else _cjRenderManoDelDia();
    // [v2.41.87] Cargar cobros en vuelo (panel arriba de la baraja)
    _cjCargarEnVuelo(true);

    // Empty state
    const empty = $('cajasEmpty');
    if (empty) empty.classList.toggle('hidden', cajasDelDia.length > 0);

    // Reloj live elapsed (solo si es hoy y hay abiertas)
    _cjStartElapsedTimer(esHoy && abiertas.length > 0);
  }

  // ── TICKER ──────────────────────────────────────────────
  function _cjRenderTicker(cajas, tickets, esHoy) {
    const cont = $('cjTickerContent');
    if (!cont) return;
    const totalDia = cajas.reduce((s, c) => s + (parseFloat(c.totalVentas) || 0), 0);
    const tkCount = tickets.filter(t => t.estado !== 'ANULADO').length;
    const abiertas = cajas.filter(c => c.estado === 'ABIERTA').length;
    const cerradas = cajas.filter(c => c.estado !== 'ABIERTA').length;
    // Buscar última venta
    const tkOrd = tickets.slice().sort((a,b) => (b.fecha+b.hora||'').localeCompare(a.fecha+a.hora||''));
    const ultima = tkOrd[0];
    const ultimoTxt = ultima
      ? `Última venta: ${ultima.hora || '—'} · S/ ${parseFloat(ultima.total||0).toFixed(2)}`
      : 'Sin ventas';
    // Comparación con ayer (solo si esHoy)
    let tendencia = '';
    if (esHoy) {
      const ayer = _fechaOffset(today(), -1);
      const tkAyer = (S._todosTickets || []).filter(t => (t.fecha||'').substring(0,10) === ayer && t.estado !== 'ANULADO');
      const totalAyer = tkAyer.reduce((s,t)=>s+(parseFloat(t.total)||0), 0);
      if (totalAyer > 0) {
        const pct = ((totalDia - totalAyer) / totalAyer) * 100;
        tendencia = pct >= 0
          ? `<span class="cj-ticker-up">▲ ${Math.abs(pct).toFixed(0)}% vs ayer</span>`
          : `<span class="cj-ticker-down">▼ ${Math.abs(pct).toFixed(0)}% vs ayer</span>`;
      }
    }
    // Pieza única que se repite 2× para scroll continuo
    const pieza = `
      <span class="cj-ticker-item ${totalDia >= 0 ? 'cj-ticker-up':'cj-ticker-down'}">${totalDia >= 0 ? '▲':'▼'} S/ ${totalDia.toFixed(2)}</span>
      <span class="cj-ticker-sep">│</span>
      <span class="cj-ticker-item">🧾 ${tkCount} tickets</span>
      <span class="cj-ticker-sep">│</span>
      <span class="cj-ticker-item cj-ticker-up">🟢 ${abiertas} abiertas</span>
      <span class="cj-ticker-sep">│</span>
      <span class="cj-ticker-item">⚫ ${cerradas} cerradas</span>
      <span class="cj-ticker-sep">│</span>
      <span class="cj-ticker-item">${ultimoTxt}</span>
      ${tendencia ? '<span class="cj-ticker-sep">│</span>' + tendencia : ''}
      <span class="cj-ticker-sep">│</span>
    `;
    cont.innerHTML = pieza + pieza; // 2× para scroll continuo
  }

  // ── KPIs ─────────────────────────────────────────────────
  function _cjRenderKPIs(cajas, tkDia, tkMes, fecha) {
    const totalDia = cajas.reduce((s, c) => s + (parseFloat(c.totalVentas) || 0), 0);
    _animateCount('cajasKpiVentas', totalDia, { prefix: 'S/ ' });

    // Barra proporcional efectivo / virtual / mixto / crédito
    const ef = cajas.reduce((s, c) => s + (parseFloat(c.efectivo) || 0), 0);
    const vi = cajas.reduce((s, c) => {
      const bm = c.byMetodo || {};
      // Sumar todo lo que no sea EFECTIVO ni POR_COBRAR/CREDITO ni ANULADO
      let total = 0;
      Object.keys(bm).forEach(k => {
        const ku = String(k || '').toUpperCase();
        if (ku === 'EFECTIVO' || ku === 'POR_COBRAR' || ku === 'CREDITO' || ku === 'ANULADO') return;
        total = _money(total + (parseFloat(bm[k]) || 0));
      });
      return s + total;
    }, 0);
    const totalCobrado = ef + vi;
    const efPct = totalCobrado > 0 ? (ef / totalCobrado * 100) : 50;
    const viPct = totalCobrado > 0 ? (vi / totalCobrado * 100) : 50;
    const setW = (id, p) => { const el = $(id); if (el) el.style.width = p.toFixed(1) + '%'; };
    setW('cjPagoBarEf', efPct);
    setW('cjPagoBarVi', viPct);
    _setText('cjEfectivoMonto', 'S/ ' + ef.toFixed(2));
    _setText('cjVirtualMonto',  'S/ ' + vi.toFixed(2));
    _setText('cjEfectivoPct',   efPct.toFixed(0) + '%');
    _setText('cjVirtualPct',    viPct.toFixed(0) + '%');

    // Lógica basada en formaPago (definiciones selladas del negocio):
    //   EFECTIVO/VIRTUAL/MIXTO = COBRADO (dinero recibido)
    //   POR_COBRAR             = pendiente de cajero (vendedor emitió, no cobrado)
    //   CREDITO                = deuda formal aprobada por admin
    //   ANULADO                = descartado, no cuenta
    const fp = t => String(t.metodo || t.formaPago || '').toUpperCase();
    const esAnul    = t => fp(t) === 'ANULADO' || t.estado === 'ANULADO';
    const esPorCob  = t => fp(t) === 'POR_COBRAR' && !esAnul(t);
    const esCred    = t => fp(t) === 'CREDITO' && !esAnul(t);
    const esCobrado = t => !esAnul(t) && !esPorCob(t) && !esCred(t);

    const tkOk    = tkDia.filter(esCobrado).length;
    const tkPorCb = tkDia.filter(esPorCob).length;
    const tkCred  = tkDia.filter(esCred).length;
    const tkAnul  = tkDia.filter(esAnul).length;
    _setText('cjVentasSub',
      tkOk + ' cobrados · ' + tkPorCb + ' por cobrar · ' + tkCred + ' a crédito · ' + tkAnul + ' anulado' + (tkAnul !== 1 ? 's' : '')
    );
    _setText('cjTkCobrados',  tkOk);
    _setText('cjTkPorCobrar', tkPorCb);
    _setText('cjTkCredito',   tkCred);
    _setText('cjTkAnulados',  tkAnul);

    // Hoy / 30d (no contar anulados)
    const hoyTotal = tkDia.filter(t => !esAnul(t)).length;
    const mesTotal = tkMes.filter(t => !esAnul(t)).length;
    _setText('cajasKpiTicketsHoy', hoyTotal);
    _setText('cajasKpiTicketsMes', mesTotal);

    // Tipos doc (NV/B/F) — tipoDoc puede ser corto o largo
    let nvH = 0, bH = 0, fH = 0;
    tkDia.forEach(t => {
      if (esAnul(t)) return;
      const tp = String(t.tipo || t.tipoDoc || '').toUpperCase();
      if (tp === 'NV' || tp === 'NOTA_DE_VENTA') nvH++;
      else if (tp === 'B' || tp === 'BOLETA') bH++;
      else if (tp === 'F' || tp === 'FACTURA') fH++;
    });
    _setText('cajasKpiNV', nvH);
    _setText('cajasKpiBoleta', bH);
    _setText('cajasKpiFactura', fH);

    // Comparación vs ayer
    const ayer = _fechaOffset(fecha, -1);
    const tkAyer = (S._todosTickets || []).filter(t =>
      (t.fecha || '').substring(0, 10) === ayer && t.estado !== 'ANULADO');
    const totalAyer = tkAyer.reduce((s, t) => s + (parseFloat(t.total) || 0), 0);
    const cmp = $('cjVentasComparaAyer');
    if (cmp) {
      if (totalAyer > 0) {
        const pct = ((totalDia - totalAyer) / totalAyer) * 100;
        cmp.classList.remove('hidden');
        cmp.classList.toggle('up', pct >= 0);
        cmp.classList.toggle('down', pct < 0);
        cmp.innerHTML = (pct >= 0 ? '▲ +' : '▼ ') + Math.abs(pct).toFixed(0) + '% vs ayer';
      } else { cmp.classList.add('hidden'); }
    }
  }

  // ── CARDS DE CAJAS ───────────────────────────────────────
  function _cjRenderCajas(abiertas, cerradas, fecha, esHoy, idCajaLider) {
    const grid = $('cjCajasGrid');
    if (!grid) return;
    const sub = $('cjCajasSub');
    if (sub) {
      const total = abiertas.length + cerradas.length;
      sub.textContent = total > 0
        ? `${total} caja${total !== 1 ? 's' : ''} ${esHoy ? 'hoy' : 'en este día'}`
        : (esHoy ? 'Sin actividad todavía' : 'Sin actividad');
    }
    _setText('cjPillActivas',  '🟢 ' + abiertas.length + ' abiertas');
    _setText('cjPillCerradas', '⚫ ' + cerradas.length + ' cerradas');

    // [sin caja] tickets del día SIN caja asignada (artefactos de transición / errores) →
    // se agrupan en una "baraja cerrada" (pila apilada) al frente, para detectarlos de un vistazo.
    // [sin caja] tickets del día SIN caja asignada → baraja 3D rotatoria (al lado de créditos)
    const sinCaja = (S._todosTickets || []).filter(t =>
      (t.fecha || '').substring(0, 10) === fecha && !String(t.idCaja || '').trim() && String(t.estado || '') !== 'ANULADO');
    _cjRenderSinCajaDeck(sinCaja);

    if (!abiertas.length && !cerradas.length) {
      grid.innerHTML = '<p class="text-slate-500 text-xs text-center py-6 col-span-full">Sin cajas en esta fecha</p>';
      return;
    }
    // Activas primero, luego cerradas. Corona 👑 a la caja líder.
    grid.innerHTML = [
      ...abiertas.map(c => _cjBuildCajaCard(c, true,  fecha, String(c.idCaja) === idCajaLider)),
      ...cerradas.map(c => _cjBuildCajaCard(c, false, fecha, String(c.idCaja) === idCajaLider))
    ].join('');

    // Detectar tickets nuevos (flash en card de la caja correspondiente)
    if (esHoy) _cjDetectarTicketsNuevos(abiertas);

    // [v2.42.00] Pegar manojo de postits (cobros en vuelo) sobre el cuadro de
    // cada caja activa. Llamamos después del render porque necesita los nodos
    // .cj-caja-card en el DOM. _cjPintarPostitsManojos itera _cjCreditosState.enVuelo
    // y monta/desmonta el manojo según la caja destino.
    try { _cjPintarPostitsManojos(); } catch(_){}
  }

  // [sin caja] baraja 3D isométrica ROTATORIA (vista de esquina): pila de cartas; la del
  // frente muestra nombre+detalle y va rotando (la de encima baja, la siguiente aparece).
  const _cjSinCajaState = { tickets: [], idx: 0, timer: null };
  function _cjRenderSinCajaDeck(tickets) {
    const deck = $('cjSinCajaDeck');
    if (!deck) return;
    if (!tickets || !tickets.length) { deck.classList.add('hidden'); _cjSinCajaStop(); _cjSinCajaState.tickets = []; return; }
    deck.classList.remove('hidden');
    _cjSinCajaState.tickets = tickets;
    if (_cjSinCajaState.idx >= tickets.length) _cjSinCajaState.idx = 0;
    _setText('cjSinCajaN', String(tickets.length));
    _cjSinCajaPintar();
    _cjSinCajaStop();
    if (tickets.length > 1) _cjSinCajaState.timer = setInterval(_cjSinCajaShuffleStep, 3500);
  }
  function _cjSinCajaPintar() {
    const cont = $('cjSinCajaStack');
    if (!cont) return;
    const tks = _cjSinCajaState.tickets; const idx = _cjSinCajaState.idx; const N = tks.length;
    cont.innerHTML = tks.map((t, i) => {
      const pos = (i - idx + N) % N;
      const posAttr = pos >= 5 ? '5+' : String(pos);
      const cli = _esc((t.clienteNom || t.cliente || 'VARIOS').toUpperCase());
      const doc = (t.clienteDoc && t.clienteDoc !== '66666') ? `<div class="cj-scc-doc">${_esc(t.clienteDoc)}</div>` : '';
      const tipo = ({ NV: 'NV', B: 'BOLETA', F: 'FACTURA' })[t.tipo] || (t.tipoDoc || 'NV');
      const corr = t.correlativo || (t.idVenta || '').split('-').pop() || '—';
      return `<div class="cj-sincaja-carta" data-pos="${posAttr}">
        <span class="cj-scc-badge">⚠</span>
        <div class="cj-scc-head"><span class="cj-scc-cli">👤 ${cli}</span><span class="cj-scc-monto">S/${parseFloat(t.total || 0).toFixed(2)}</span></div>
        ${doc}
        <div class="cj-scc-sep"></div>
        <div class="cj-scc-corr">${_esc(tipo)} ${_esc(corr)}</div>
        <div class="cj-scc-meta"><span>${_esc(t.hora || '')}</span><span>sin caja</span></div>
      </div>`;
    }).join('');
  }
  function _cjSinCajaShuffleStep() {
    const tks = _cjSinCajaState.tickets;
    if (!tks || tks.length < 2) return;
    const m = $('cjModalTickets'); if (m && !m.classList.contains('hidden')) return;   // pausa si el visor está abierto
    _cjSinCajaState.idx = (_cjSinCajaState.idx + 1) % tks.length;
    _cjSinCajaPintar();
  }
  function _cjSinCajaStop() {
    if (_cjSinCajaState.timer) { clearInterval(_cjSinCajaState.timer); _cjSinCajaState.timer = null; }
  }
  function cjVerTicketsSinCaja() {
    _finBeep('click');
    _cjState.tkCajaFiltro = '__SINCAJA__';
    _cjState.tkFiltro = 'todos';
    _cjState.tkBuscar = '';
    const inp = $('cjTkBuscar'); if (inp) inp.value = '';
    _setText('cjModalTicketsTitulo', 'Tickets sin caja asignada');
    _setText('cjModalTicketsSubtitulo', _cjFecha() + ' · ⚠ sin caja (revisar)');
    _cjState.tkVendedor = '';
    _cjTkResetRango(_cjFecha());
    openModal('cjModalTickets');
    _cjTkRenderFiltrosBtns();
    _cjTkRenderVendedoresBtns();
    _cjTkRender();
  }

  // [v2.41.91] Bloque "Balance en vivo" — solo en cajas ABIERTAS.
  // Muestra el efectivo esperado calculado (lo que el cajero debería tener
  // en mano), separación virtual/crédito/por_cobrar, y celebra hitos.
  function _cjBuildBalanceLive(c) {
    const inicial = parseFloat(c.montoInicial) || 0;
    const efectivo = parseFloat(c.efectivo) || 0;
    const entradas = parseFloat(c.entradas) || 0;
    const salidas = parseFloat(c.salidas) || 0;
    const esperado = parseFloat(c.efectivoEsperado) || (inicial + efectivo + entradas - salidas);

    // Hitos S/ 500, 1k, 2k, 3k → emojis crecientes
    const hitos = [
      { mark: 3000, emoji: '🏆', label: '3K+' },
      { mark: 2000, emoji: '🔥', label: '2K+' },
      { mark: 1000, emoji: '⭐', label: '1K+' },
      { mark:  500, emoji: '💪', label: '500+' }
    ];
    const hitoAlcanzado = hitos.find(h => esperado >= h.mark);
    const proximoHito = hitos.slice().reverse().find(h => esperado < h.mark);
    const progresoPct = proximoHito ? Math.min(100, (esperado / proximoHito.mark) * 100) : 100;

    // Anomalías
    const totalVentas = parseFloat(c.totalVentas) || 0;
    const anulados = c.anulados || 0;
    const tickets = Math.max(1, c.tickets || 0);
    const ratioAnul = anulados / tickets;
    const alertas = [];
    if (ratioAnul >= 0.20 && anulados >= 3) alertas.push({ icon: '⚠', txt: anulados + ' anulaciones (' + Math.round(ratioAnul*100) + '%) — revisar' });
    if (salidas > entradas + 100) alertas.push({ icon: '💸', txt: 'Egresos > ingresos por S/ ' + (salidas - entradas).toFixed(0) });

    return `
    <div class="cj-balance-live">
      <div class="cj-balance-live-row">
        <span class="cj-balance-live-lbl">💚 ESPERADO EN CAJA</span>
        <span class="cj-balance-live-monto" data-monto="${esperado.toFixed(2)}">S/ ${esperado.toFixed(2)}</span>
      </div>
      <div class="cj-balance-live-detail">
        <span>S/ ${inicial.toFixed(0)} inicial</span>
        ${efectivo > 0 ? `<span>+ S/ ${efectivo.toFixed(0)} ventas</span>` : ''}
        ${entradas > 0 ? `<span>+ S/ ${entradas.toFixed(0)} ing</span>` : ''}
        ${salidas > 0 ? `<span>− S/ ${salidas.toFixed(0)} egr</span>` : ''}
      </div>
      ${hitoAlcanzado || proximoHito ? `
      <div class="cj-balance-hitos">
        ${hitoAlcanzado ? `<span class="cj-balance-hito-actual">${hitoAlcanzado.emoji} ${hitoAlcanzado.label}</span>` : ''}
        ${proximoHito ? `
          <div class="cj-balance-hito-progress" title="Próximo hito: S/ ${proximoHito.mark}">
            <div class="cj-balance-hito-progress-fill" style="width:${progresoPct}%"></div>
          </div>
          <span class="cj-balance-hito-prox">${proximoHito.emoji} ${proximoHito.label}</span>
        ` : ''}
      </div>` : ''}
      ${alertas.length ? `
      <div class="cj-balance-alertas">
        ${alertas.map(a => `<div class="cj-balance-alerta"><span>${a.icon}</span><span>${a.txt}</span></div>`).join('')}
      </div>` : ''}
    </div>`;
  }

  function _cjBuildCajaCard(c, esActiva, fecha, esLider) {
    const idAttr = String(c.idCaja).replace(/'/g, '&#39;');
    const elapsed = _cajaElapsed(c.fechaApertura);
    const total = parseFloat(c.totalVentas) || 0;
    const tickets = c.tickets || 0;
    const anulados = c.anulados || 0;
    const sinCobrar = c.sinCobrar || 0;
    const ef = parseFloat(c.efectivo) || 0;

    // Métodos: separar virtual / mixto / credito desde byMetodo
    const bm = c.byMetodo || {};
    let mVi = 0, mMx = 0, mCr = 0;
    Object.keys(bm).forEach(k => {
      const ku = String(k || '').toUpperCase();
      const v = parseFloat(bm[k]) || 0;
      if (ku === 'EFECTIVO' || ku === 'ANULADO') return;
      if (ku === 'POR_COBRAR' || ku === 'CREDITO') mCr += v;
      else if (ku.startsWith('MIXTO')) mMx += v;
      else mVi += v;
    });
    const totalCobrado = ef + mVi + mMx;
    const efPct = totalCobrado > 0 ? (ef / totalCobrado * 100) : 0;
    const viPct = totalCobrado > 0 ? (mVi / totalCobrado * 100) : 0;
    const mxPct = totalCobrado > 0 ? (mMx / totalCobrado * 100) : 0;
    const totalConCredito = totalCobrado + mCr;
    const crPct = totalConCredito > 0 ? (mCr / totalConCredito * 100) : 0;

    // Salud: 100 base, descuenta % anulados, % crédito alto, sin movimiento
    const tkSafe = Math.max(1, tickets);
    let salud = 100;
    salud -= Math.min(40, (anulados / tkSafe) * 100 * 2); // anulados: -2 por cada %
    if (total > 0 && mCr / Math.max(1, total) > 0.30) salud -= 15; // crédito > 30%
    salud = Math.max(0, Math.round(salud));
    const saludCls = salud >= 80 ? '' : (salud >= 60 ? 'warn' : 'bad');

    // Sparkline de tickets por hora (12 barras: 7am-19h)
    const tkList = c.ticketsList || [];
    const horas = new Array(13).fill(0);
    tkList.forEach(t => {
      if (t.estado === 'ANULADO') return;
      const h = parseInt(String(t.hora || '0').split(':')[0], 10);
      const idx = Math.max(0, Math.min(12, h - 7));
      horas[idx] += (parseFloat(t.total) || 0);
    });
    const maxH = Math.max.apply(null, horas.concat([1]));
    const horaActual = new Date().getHours();
    const sparkBars = horas.map((v, i) => {
      const h = Math.max(2, (v / maxH) * 28);
      const realHora = i + 7;
      const cls = v === 0 ? 'zero' : (esActiva && realHora === horaActual ? 'now' : '');
      return `<div class="cj-spark-bar ${cls}" style="height:${h}px" title="${realHora}h: S/ ${v.toFixed(2)}"></div>`;
    }).join('');

    // Iniciales del cajero
    const ini = (c.vendedor || '?').split(/\s+/).map(p => p[0] || '').slice(0, 2).join('').toUpperCase();
    const safeNombre = String(c.vendedor || '').replace(/'/g, '&#39;');

    // Banderas de alerta
    const sinMov = esActiva && tickets === 0 && _cajaMinutosDesdeApertura(c.fechaApertura) > 30;
    const claseEstado = esActiva
      ? (sinMov ? 'alerta' : 'activa')
      : 'cerrada';

    // Botones. [v41.3] Cierre forzado solo para admin/master en cajas ABIERTAS.
    const _esAdmin = _esAdminOMaster();
    const btnCerrarForzado = esActiva && _esAdmin
      ? `<button onclick="event.stopPropagation();MOS.cjCerrarCajaForzado('${idAttr}','${safeNombre}')" class="cj-caja-btn cj-caja-btn-danger" title="Cerrar caja forzadamente (admin)">🔒 Cerrar caja</button>`
      : '';
    // [798] "💸 Extras" — overlay con TODOS los movimientos extra de la caja (agregar/editar/eliminar
    // con PIN admin). Nace del incidente del 15-ago: dos egresos "Cierre de caja" duplicados dejaron
    // el arqueo en −1925.60 y desde MOS no había forma de corregirlos. Va en cajas ABIERTAS y CERRADAS
    // (el error se descubre casi siempre después del cierre). El badge = cuántos extras tiene; sin
    // extras el botón SIGUE ahí porque es la única puerta para AGREGAR uno.
    const nEx = (c.extrasList || []).length;
    const badgeEx = nEx
      ? ` <span style="display:inline-block;min-width:15px;padding:0 4px;border-radius:7px;background:#7c2d12;color:#fdba74;font-size:9px;font-weight:800;line-height:15px;text-align:center">${nEx}</span>`
      : '';
    const btnExtras = `<button onclick="event.stopPropagation();MOS.cjVerExtrasCaja('${idAttr}')" class="cj-caja-btn" title="Movimientos extra (ingresos/egresos) de esta caja">💸 Extras${badgeEx}</button>`;
    const btnActiva = esActiva ? `
      <button onclick="event.stopPropagation();MOS.cjVerTicketsCaja('${idAttr}')" class="cj-caja-btn cj-caja-btn-primary" title="Ver tickets de esta caja">🧾 Tickets</button>
      ${btnExtras}
      <button onclick="event.stopPropagation();MOS.cjAbrirTurno('${idAttr}')" class="cj-caja-btn" title="Ver turno completo">📊 Turno</button>
      ${btnCerrarForzado}` : `
      <button onclick="event.stopPropagation();MOS.cjVerTicketsCaja('${idAttr}')" class="cj-caja-btn cj-caja-btn-primary">🧾 Tickets del turno</button>
      ${btnExtras}
      <button onclick="event.stopPropagation();MOS.cjAbrirTurno('${idAttr}')" class="cj-caja-btn" title="Ver turno completo">📜 Ver cierre</button>`;

    return `
    <div class="cj-caja-card ${claseEstado} ${esLider ? 'cj-caja-card-lider' : ''}" id="cjcard-${idAttr}" data-idcaja="${idAttr}" data-tickets="${tickets}" onclick="MOS.cjToggleCajaDetail('${idAttr}')">
      ${esLider ? '<div class="cj-caja-corona" title="Líder del día — caja con mayor venta">👑</div>' : ''}
      <div class="cj-caja-head">
        <span class="cj-caja-status-dot ${esActiva ? 'live' : 'off'}"></span>
        <div class="cj-caja-titulo">${esLider ? '🏆' : '📍'} ${c.zona || c.estacion || c.idCaja}</div>
        <span class="cj-caja-badge ${esActiva ? 'live' : 'cerrada'}">${esActiva ? 'LIVE' : 'CERRADA'}</span>
        <button class="cj-caja-toggle ${_cjState.expandido.has(idAttr) ? 'open' : ''}" onclick="event.stopPropagation();MOS.cjToggleCajaDetail('${idAttr}')">▾</button>
      </div>
      <div class="cj-caja-meta">
        <div class="cj-caja-avatar">${ini}</div>
        <div class="cj-caja-meta-cuerpo">
          <div class="cj-caja-meta-nombre">${c.vendedor || '—'}</div>
          <div class="cj-caja-meta-sub">${(c.fechaApertura || '').substring(11, 16)} → ${esActiva ? 'ahora' : (c.fechaCierre || '').substring(11, 16)}</div>
        </div>
        <span class="cj-caja-elapsed" data-elapsed-id="${idAttr}" data-fecha="${c.fechaApertura}" data-cierre="${c.fechaCierre || ''}">${elapsed}</span>
      </div>
      <div class="cj-caja-hero">
        <div>
          <div class="cj-caja-hero-monto">S/ ${total.toFixed(2)}</div>
          <div class="cj-caja-hero-sub">${tickets} tickets · ${anulados > 0 ? `<span style="color:#fca5a5">${anulados} anul</span> · ` : ''}${sinCobrar > 0 ? `<span style="color:#fcd34d">${sinCobrar} créd</span>` : '0 créd'}</div>
        </div>
        <div class="cj-caja-salud" title="Salud de la caja: ${salud}/100">
          <div class="cj-caja-salud-num ${saludCls}">${salud}</div>
          <div class="cj-caja-salud-lbl">SALUD</div>
          <div class="cj-caja-salud-bar"><div class="cj-caja-salud-bar-fill" style="width:${salud}%"></div></div>
        </div>
      </div>
      ${esActiva ? _cjBuildBalanceLive(c) : ''}
      <div class="cj-caja-pago-bar">
        ${efPct > 0 ? `<div class="cj-caja-pago-bar-ef" style="width:${efPct}%">${efPct >= 12 ? '💵' : ''}</div>` : ''}
        ${viPct > 0 ? `<div class="cj-caja-pago-bar-vi" style="width:${viPct}%">${viPct >= 12 ? '📱' : ''}</div>` : ''}
        ${mxPct > 0 ? `<div class="cj-caja-pago-bar-mx" style="width:${mxPct}%">${mxPct >= 12 ? '🔀' : ''}</div>` : ''}
        ${crPct > 0 ? `<div class="cj-caja-pago-bar-cr" style="width:${crPct}%">${crPct >= 12 ? '📋' : ''}</div>` : ''}
      </div>
      <div class="cj-caja-pago-leg">
        ${ef > 0 ? `<span class="cj-caja-pago-leg-item"><span style="width:8px;height:8px;border-radius:50%;background:#34d399"></span>S/ ${ef.toFixed(0)}</span>` : ''}
        ${mVi > 0 ? `<span class="cj-caja-pago-leg-item"><span style="width:8px;height:8px;border-radius:50%;background:#22d3ee"></span>S/ ${mVi.toFixed(0)}</span>` : ''}
        ${mMx > 0 ? `<span class="cj-caja-pago-leg-item"><span style="width:8px;height:8px;border-radius:50%;background:#a5b4fc"></span>S/ ${mMx.toFixed(0)}</span>` : ''}
        ${mCr > 0 ? `<span class="cj-caja-pago-leg-item"><span style="width:8px;height:8px;border-radius:50%;background:#fb923c"></span>S/ ${mCr.toFixed(0)}</span>` : ''}
      </div>
      <div class="cj-spark">${sparkBars}</div>
      <div class="cj-spark-axis"><span>7h</span><span>13h</span><span>19h</span></div>
      <div class="cj-caja-actions">
        ${btnActiva}
        <button type="button" class="cj-caja-yape" title="Yapes capturados de esta caja: verificar, atar a mano o desverificar"
                onclick="event.stopPropagation();MOS.yapesCajaAbrir('${idAttr}')">💜 Yapes</button>
      </div>
      <div class="cj-caja-detail ${_cjState.expandido.has(idAttr) ? '' : 'hidden'}" id="cjdetail-${idAttr}">
        ${_cjBuildDetalleHtml(c)}
      </div>
    </div>`;
  }

  function _cjBuildDetalleHtml(c) {
    const tkList = (c.ticketsList || []).slice(0, 30);
    const exList = (c.extrasList || []);
    if (!tkList.length && !exList.length) return '<div class="text-xs text-slate-500 italic">Sin tickets ni movimientos</div>';
    const ticketsHtml = tkList.length ? `
      <div class="cj-caja-detail-head">${tkList.length} ticket${tkList.length!==1?'s':''}</div>
      ${tkList.map(t => {
        const an = t.estado === 'ANULADO';
        return `<div class="flex items-center gap-2 py-1.5 border-b border-slate-800/40 ${an?'opacity-50':''}">
          <span class="text-[10px] font-mono text-slate-400">${t.correlativo||'—'}</span>
          <span class="text-[10px] text-slate-500 flex-1 min-w-0 truncate">${t.clienteNom||t.clienteDoc||'—'}</span>
          <span class="text-[10px] ${an?'line-through text-slate-600':'text-slate-300 font-bold'}">S/ ${parseFloat(t.total||0).toFixed(2)}</span>
          <span class="text-[9px] text-slate-500">${(t.metodo||'').substring(0,3)}</span>
        </div>`;
      }).join('')}
    ` : '';
    const extrasHtml = exList.length ? `
      <div class="cj-caja-detail-head" style="margin-top:10px">Movimientos extra</div>
      ${exList.map(ex => {
        // [798] El 📜 suelto por fila MURIÓ acá: al dueño le resultaba inútil/confuso dentro de la card.
        // El historial (y editar/eliminar) vive ahora en el overlay "💸 Extras" (MOS.cjVerExtrasCaja).
        const colorCls = ex.tipo === 'INGRESO' || ex.tipo === 'INGRESO_VIRTUAL' ? 'text-emerald-400' : 'text-red-400';
        const sigArr = ex.tipo === 'INGRESO' || ex.tipo === 'INGRESO_VIRTUAL' ? '▲' : '▼';
        const sigMon = ex.tipo === 'INGRESO' || ex.tipo === 'INGRESO_VIRTUAL' ? '+' : '-';
        return `<div class="flex items-center justify-between gap-2 py-1 text-[10px]">
          <span class="${colorCls} flex-1 min-w-0 truncate">${sigArr} ${ex.concepto || ex.tipo}</span>
          <span class="${colorCls} font-bold">${sigMon}S/ ${parseFloat(ex.monto||0).toFixed(2)}</span>
        </div>`;
      }).join('')}
    ` : '';
    return ticketsHtml + extrasHtml;
  }

  function cjToggleCajaDetail(idCaja) {
    const id = String(idCaja);
    if (_cjState.expandido.has(id)) _cjState.expandido.delete(id);
    else _cjState.expandido.add(id);
    const safe = id.replace(/'/g, '&#39;');
    const det = document.getElementById('cjdetail-' + safe);
    const tog = document.querySelector(`#cjcard-${safe} .cj-caja-toggle`);
    if (det) det.classList.toggle('hidden');
    if (tog) tog.classList.toggle('open');
    _finBeep('click');
  }

  // Helper: minutos desde apertura
  function _cajaMinutosDesdeApertura(fechaApertura) {
    if (!fechaApertura) return 0;
    return Math.floor((Date.now() - new Date(fechaApertura).getTime()) / 60000);
  }

  // ── Reloj live: actualiza elapsed cada segundo ────────
  function _cjStartElapsedTimer(activar) {
    if (_cjState.elapsedTimer) {
      clearInterval(_cjState.elapsedTimer);
      _cjState.elapsedTimer = null;
    }
    if (!activar) return;
    _cjState.elapsedTimer = setInterval(() => {
      document.querySelectorAll('[data-elapsed-id]').forEach(el => {
        const fecha = el.dataset.fecha;
        const cierre = el.dataset.cierre;
        if (cierre) return; // solo activas
        if (fecha) el.textContent = _cajaElapsed(fecha);
      });
    }, 1000);
  }

  // ── Detectar tickets nuevos por caja → cha-ching + popup ───
  function _cjDetectarTicketsNuevos(abiertas) {
    abiertas.forEach(c => {
      const id = String(c.idCaja);
      const previo = _cjState.chunksAnteriores.get(id);
      const actualTk = c.tickets || 0;
      const actualMonto = parseFloat(c.totalVentas) || 0;
      if (previo !== undefined && actualTk > (previo.tk || 0)) {
        const deltaMonto = Math.max(0, actualMonto - (previo.monto || 0));
        const deltaTk = actualTk - (previo.tk || 0);
        _cjEfectoVentaNueva(id, deltaMonto, deltaTk);
      }
      _cjState.chunksAnteriores.set(id, { tk: actualTk, monto: actualMonto });
    });
  }

  // ── Efecto registradora ¡cha-ching! ──────────────────
  function _cjEfectoVentaNueva(idCaja, deltaMonto, deltaTk) {
    const safe = String(idCaja).replace(/'/g, '&#39;');
    const card = document.getElementById('cjcard-' + safe);
    if (!card) return;
    // 1) Sonido dinero
    _finBeep('dinero');
    // 2) Vibración + glow
    card.classList.remove('cj-vibrate');
    void card.offsetWidth;
    card.classList.add('cj-vibrate');
    setTimeout(() => card.classList.remove('cj-vibrate'), 700);
    // 3) Popup +S/ XX flotante saliendo del hero
    const hero = card.querySelector('.cj-caja-hero');
    if (hero) {
      const pop = document.createElement('div');
      pop.className = 'cj-pop-venta';
      const txt = deltaMonto > 0
        ? `+S/ ${deltaMonto.toFixed(2)}`
        : `+${deltaTk} ticket${deltaTk!==1?'s':''}`;
      pop.innerHTML = `<span class="cj-pop-emoji">💸</span><span>${txt}</span>`;
      hero.appendChild(pop);
      setTimeout(() => pop.remove(), 2000);
    }
    // 4) Pulso del monto del card (countup animado)
    const monto = card.querySelector('.cj-caja-hero-monto');
    if (monto) {
      monto.classList.remove('cj-monto-pulse');
      void monto.offsetWidth;
      monto.classList.add('cj-monto-pulse');
      setTimeout(() => monto.classList.remove('cj-monto-pulse'), 900);
    }
    // 5) Pulso del KPI grande del día también
    const kpi = $('cajasKpiVentas');
    if (kpi) {
      kpi.classList.remove('cj-monto-pulse');
      void kpi.offsetWidth;
      kpi.classList.add('cj-monto-pulse');
    }
    // 6) Pulso de la barra de pago global
    const pagoBar = document.querySelector('.fin-pago-bar');
    if (pagoBar) {
      pagoBar.classList.remove('cj-bar-pulse');
      void pagoBar.offsetWidth;
      pagoBar.classList.add('cj-bar-pulse');
    }
  }

  // ── Pulso del dot polling ──────────────────────
  function _cjPulsoPoll() {
    const dot = $('cjPollDot');
    if (!dot) return;
    dot.classList.add('active');
    setTimeout(() => dot.classList.remove('active'), 1300);
  }

  // ── RANKING: deprecado — la corona 👑 va al card de la caja líder ──
  // (Eliminado: el card de "Ranking del día" + duplicado en TV strip)


  // ── ACTIVIDAD POR HORA (timeline horizontal con barras) ─────
  function _cjRenderActividad(tickets, esHoy) {
    const cont = $('cjActividad');
    if (!cont) return;
    const fp2 = t => String(t.metodo || t.formaPago || '').toUpperCase();
    const esAnul2 = t => fp2(t) === 'ANULADO' || t.estado === 'ANULADO';

    // Acumular por hora (6h-22h = 17 filas)
    const horaIni = 6, horaFin = 22;
    const horas = {};
    for (let h = horaIni; h <= horaFin; h++) horas[h] = { total: 0, count: 0 };
    tickets.forEach(t => {
      if (esAnul2(t)) return;
      const h = parseInt(String(t.hora || '0').split(':')[0], 10);
      if (h >= horaIni && h <= horaFin) {
        horas[h].total += (parseFloat(t.total) || 0);
        horas[h].count += 1;
      }
    });
    const horasArr = Object.keys(horas).map(h => ({ h: parseInt(h, 10), ...horas[h] }));
    const max = Math.max.apply(null, horasArr.map(x => x.total).concat([1]));
    const totalGen = horasArr.reduce((s, x) => s + x.total, 0);
    if (totalGen === 0) {
      cont.innerHTML = '<p class="text-slate-500 text-xs italic text-center py-8">Sin actividad en esta fecha</p>';
      _setText('cjActividadPico', '—');
      return;
    }

    // Hora pico
    const pico = horasArr.slice().sort((a, b) => b.total - a.total)[0];
    const picoTxt = (pico && pico.total > 0)
      ? `🔥 Pico: ${String(pico.h).padStart(2, '0')}h · S/ ${pico.total.toFixed(0)}`
      : '—';
    _setText('cjActividadPico', picoTxt);
    _setText('cjActividadPicoTV', picoTxt);

    const horaActual = new Date().getHours();
    const html = `<div class="cj-actividad-grid">${
      horasArr.map(x => {
        const pct = x.total === 0 ? 0 : Math.max(2, (x.total / max) * 100);
        const isNow = esHoy && x.h === horaActual;
        const cls = x.total === 0 ? 'zero' : (isNow ? 'now' : '');
        const rowCls = isNow ? 'cj-actividad-row now' : 'cj-actividad-row';
        const horaCls = isNow ? 'cj-actividad-hora now' : 'cj-actividad-hora';
        const monto = x.total > 0 ? 'S/ ' + x.total.toFixed(0) : '';
        return `
          <div class="${horaCls}">${String(x.h).padStart(2, '0')}h</div>
          <div class="cj-actividad-bar-track">
            <div class="cj-actividad-bar-fill ${cls}" style="width:${pct}%">
              <span class="cj-actividad-bar-monto">${monto}</span>
            </div>
          </div>
          <div class="cj-actividad-tickets ${rowCls}">
            <span class="cj-actividad-tickets-num">${x.count}</span> tk
          </div>`;
      }).join('')
    }</div>`;
    cont.innerHTML = html;
    const tv = $('cjActividadTV');
    if (tv) tv.innerHTML = html;
  }

  // ── ÚLTIMOS 7 DÍAS (mini-row + chart) ───────────────────
  function _cjRender7d(fechaActiva) {
    const tkAll = S._todosTickets || [];
    const cajasAll = S._todasCajas || [];
    // 7 días terminando en fechaActiva
    const dias = [];
    for (let i = 6; i >= 0; i--) {
      const f = _fechaOffset(fechaActiva, -i);
      dias.push({ fecha: f, total: 0, count: 0, cajas: 0 });
    }
    const fp3 = t => String(t.metodo || t.formaPago || '').toUpperCase();
    const esAnul3 = t => fp3(t) === 'ANULADO' || t.estado === 'ANULADO';
    tkAll.forEach(t => {
      const f = (t.fecha || '').substring(0, 10);
      const dia = dias.find(d => d.fecha === f);
      if (!dia) return;
      if (esAnul3(t)) return;
      dia.total += (parseFloat(t.total) || 0);
      dia.count += 1;
    });
    cajasAll.forEach(c => {
      const fa = (c.fechaApertura || '').substring(0, 10);
      const fc = (c.fechaCierre   || '').substring(0, 10);
      const dia = dias.find(d => d.fecha === fa || d.fecha === fc);
      if (dia) dia.cajas++;
    });
    const totalSemana = dias.reduce((s, d) => s + d.total, 0);
    ['cj7dTotal', 'cj7dTotalTV'].forEach(id => {
      const pill = $(id);
      if (pill) {
        pill.textContent = totalSemana > 0 ? 'S/ ' + totalSemana.toFixed(0) : 'S/ 0';
        pill.classList.toggle('up', totalSemana > 0);
        pill.classList.remove('down');
      }
    });
    _setText('cj7dSubtitulo', `Total 7d: S/ ${totalSemana.toFixed(2)}`);

    const max = Math.max.apply(null, dias.map(d => d.total).concat([1]));
    const hoy = today();
    const miniHtml = dias.map(d => {
      const dt = new Date(d.fecha + 'T00:00:00');
      const dia = dt.toLocaleDateString('es-PE', { weekday: 'short' }).slice(0, 3);
      const h = Math.max(6, (d.total / max) * 30);
      const cls = ['cj-7d-mini-day'];
      if (d.fecha === hoy) cls.push('today');
      if (d.total > 0) cls.push('has-data');
      return `<button class="${cls.join(' ')}" onclick="MOS.cjElegirFecha('${d.fecha}')" title="${d.fecha} · S/ ${d.total.toFixed(2)} · ${d.count} tk">
        <div class="cj-7d-mini-bar" style="height:${h}px"></div>
        <div class="cj-7d-mini-lbl">${dia}</div>
      </button>`;
    }).join('');
    ['cj7dMiniRow', 'cj7dMiniRowTV'].forEach(id => {
      const el = $(id); if (el) el.innerHTML = miniHtml;
    });

    const labels = dias.map(d => {
      const dt = new Date(d.fecha + 'T00:00:00');
      return dt.toLocaleDateString('es-PE', { weekday: 'short', day: 'numeric' });
    });
    const opts = {
      type: 'bar',
      data: {
        labels,
        datasets: [
          { label: 'Ventas',  data: dias.map(d => d.total), backgroundColor: 'rgba(34,211,238,0.55)', borderRadius: 4 },
          { label: 'Tickets', data: dias.map(d => d.count), backgroundColor: 'rgba(168,85,247,0.55)', borderRadius: 4, yAxisID: 'y1' }
        ]
      },
      options: {
        responsive: true, maintainAspectRatio: false,
        plugins: { legend: { labels: { color: '#64748b', boxWidth: 10, font: { size: 9 } } } },
        scales: {
          x: { grid: { color: '#1e293b' }, ticks: { color: '#64748b', font: { size: 9 } } },
          y: { position: 'left', grid: { color: '#1e293b' }, ticks: { color: '#64748b', callback: v => 'S/' + v, font: { size: 9 } } },
          y1: { position: 'right', grid: { display: false }, ticks: { color: '#a855f7', font: { size: 9 } } }
        }
      }
    };
    try { renderChart('chartCajasBars', opts); } catch (_) {}
    if ($('chartCajasBarsTV')) {
      try { renderChart('chartCajasBarsTV', opts); } catch (_) {}
    }
  }

  // ════════════════════════════════════════════════════════
  // [v40.4] CRÉDITOS — MANO DE CARTAS estilo poker hand
  // Una sola mano de la fecha activa. Cartas peeking + shuffle ciclico.
  // Click → mesa overlay. Click carta → detalle con FAB enviar.
  // ════════════════════════════════════════════════════════
  let _cjCreditosState = {
    todosLosGrupos: [],            // [{fecha, tickets, ...}]  cache 30d desde backend
    ticketsActivos: [],            // tickets de la fecha actualmente visible
    fechaActiva:    null,          // fecha actualmente visible
    shuffleTimer:   null,          // setInterval para barajar
    shuffleIdx:     0,             // qué carta está al frente
    detalleTicket:  null,          // ticket en overlay detalle
    asignarCtx:     null,
    asignarCaja:    null,
    asignarMetodo:  'EFECTIVO',
    asignarTTL:     1,             // [v2.41.86] tiempo límite (1/2/4/6h)
    asignarMensaje: '',            // [v2.41.87] mensaje opcional al cajero
    // [v41] Set de idVenta ya vistos en renders previos. Las cartas con id que
    // no esté aquí se marcan como nuevas y se animan con cj-carta-nueva.
    idsVistos:      new Set(),
    // [v2.41.87] Cobros en vuelo + recientes para panel admin
    enVuelo:        [],
    recientes:      [],
    enVueloLastFetch: 0,
    enVueloTick:    0,             // forzar reactividad countdown live
    // [v2.42.00] Cache cajas abiertas para asignación instantánea
    cajasAbiertasCache:     [],
    cajasAbiertasCacheTs:   0      // ms epoch del último fetch (TTL 30s)
  };
  // [v2.41.87] Tick reactivo cada 30s para countdown en cobros en vuelo
  setInterval(() => {
    _cjCreditosState.enVueloTick++;
    const cont = document.getElementById('cjEnVueloPanel');
    if (cont && !cont.classList.contains('hidden')) {
      _cjRenderEnVuelo();
    }
  }, 30000);

  // ════════════════════════════════════════════════════════════
  // [v2.41.87] COBROS EN VUELO — Panel admin con countdown live,
  // cancelar y reasignar. Se renderiza arriba de la baraja de
  // créditos pendientes en Cajas.
  // ════════════════════════════════════════════════════════════
  async function _cjCargarEnVuelo(silent) {
    try {
      const r = await API.get('meCobrosEnVuelo', {});
      const d = (r && r.data) ? r.data : (r || {});
      _cjCreditosState.enVuelo = d.enVuelo || [];
      _cjCreditosState.recientes = d.recientes || [];
      _cjCreditosState.enVueloLastFetch = Date.now();
      _cjRenderEnVuelo();
      // [v2.42.00] Re-pintar postits encima de cada cuadro de caja
      try { _cjPintarPostitsManojos(); } catch(_){}
    } catch(e) {
      if (!silent) console.warn('[enVuelo] error:', e?.message || e);
    }
  }

  // [v2.42.00] Precarga cajas abiertas + cache 30s. Lo llamamos al abrir la
  // mesa de créditos para que cuando el admin haga click en "Asignar a caja"
  // los chips de cajeros aparezcan instantáneo. Sin esta precarga, el modal
  // muestra spinner ~1.5s mientras el GAS responde.
  async function _cjPrecargarCajasAbiertas(forzar) {
    const ahora = Date.now();
    const fresca = (ahora - (_cjCreditosState.cajasAbiertasCacheTs || 0)) < 30000;
    if (!forzar && fresca && _cjCreditosState.cajasAbiertasCache.length) {
      return _cjCreditosState.cajasAbiertasCache;
    }
    try {
      // [fix] GET (no POST): la RPC directa mos.me_cajas_abiertas (fresca, solo ABIERTA de la tabla VIVA
      // me.cajas) SOLO está cableada en el dispatcher GET. Con POST caía SIEMPRE a GAS → lista stale que
      // ofrecía cajas ya CERRADAS (bug: enviar cobro a caja cerrada). Con GET usa la directa correcta.
      const r = await API.get('meCajasAbiertas', {});
      const lista = (r && r.data) ? r.data : (Array.isArray(r) ? r : []);
      _cjCreditosState.cajasAbiertasCache    = Array.isArray(lista) ? lista : [];
      _cjCreditosState.cajasAbiertasCacheTs  = ahora;
      return _cjCreditosState.cajasAbiertasCache;
    } catch(e) {
      console.warn('[precargaCajas] error:', e?.message || e);
      return _cjCreditosState.cajasAbiertasCache || [];
    }
  }

  // ════════════════════════════════════════════════════════════
  // [v2.42.00] POSTITS MANOJO — los cobros en vuelo aparecen como
  // un manojo de postits rotados, pegados con un pin sobre el cuadro
  // de la caja activa del cajero asignado. Hover endereza + agranda,
  // click abre modal mini con acciones admin (Reasignar/Cancelar).
  // ════════════════════════════════════════════════════════════
  function _cjPostitColorClass(cobro) {
    try {
      const t = new Date(cobro.fechaVencimiento).getTime();
      const minMs = t - Date.now();
      if (isNaN(minMs)) return 'cj-postit-warn';
      if (minMs <= 30 * 60000)      return 'cj-postit-critical';  // <30min rojo
      if (minMs <= 2  * 60 * 60000) return 'cj-postit-warn';      // 30min-2h ámbar
      return 'cj-postit-ok';                                       // >2h verde
    } catch(_) { return 'cj-postit-warn'; }
  }

  function _cjPostitRestante(cobro) {
    try {
      const t = new Date(cobro.fechaVencimiento).getTime();
      const diffMin = Math.floor((t - Date.now()) / 60000);
      if (isNaN(diffMin)) return '';
      if (diffMin <= 0) return 'vencido';
      if (diffMin < 60) return diffMin + 'm';
      const h = Math.floor(diffMin / 60), m = diffMin % 60;
      return h + 'h' + (m > 0 ? ' ' + m + 'm' : '');
    } catch(_) { return ''; }
  }

  function _cjPintarPostitsManojos(opts) {
    opts = opts || {};
    const enVuelo = _cjCreditosState.enVuelo || [];
    // Agrupar por cajaDestino
    const porCaja = {};
    for (const c of enVuelo) {
      const id = String(c.cajaDestino || '');
      if (!id) continue;
      if (!porCaja[id]) porCaja[id] = [];
      porCaja[id].push(c);
    }
    // Iterar todos los cards de caja en pantalla y montar/desmontar el manojo
    const cards = document.querySelectorAll('.cj-caja-card');
    cards.forEach(card => {
      const idCaja = card.dataset.idcaja;
      if (!idCaja) return;
      // Asegurar contenedor manojo
      let manojo = card.querySelector('.cj-postit-manojo');
      const cobros = porCaja[idCaja] || [];
      if (!cobros.length) {
        if (manojo) { try { manojo.remove(); } catch(_){} }
        return;
      }
      if (!manojo) {
        manojo = document.createElement('div');
        manojo.className = 'cj-postit-manojo';
        manojo.setAttribute('aria-label', 'Cobros en vuelo asignados');
        card.appendChild(manojo);
        // El manojo no debe disparar el toggle del card
        manojo.addEventListener('click', (ev) => { ev.stopPropagation(); });
      }
      // Render postits: rotación variable + offset apilado tipo abanico
      const N = cobros.length;
      const _esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
      let html = `<div class="cj-postit-pin" title="${N} cobro${N>1?'s':''} en vuelo">📌</div>`;
      // Render del más reciente al fondo, primero arriba para que al hacer fan-out se vea
      cobros.forEach((c, i) => {
        const colorCls = _cjPostitColorClass(c);
        const restTxt  = _cjPostitRestante(c);
        // Ángulo y offset estables por idCobro (hash simple)
        const seed = (String(c.idCobro || i)).split('').reduce((a, ch) => a + ch.charCodeAt(0), 0);
        const rotDeg  = (seed % 13) - 6;             // -6..+6
        const offX    = (seed % 7);                  // 0..6 px
        const offY    = i * 8;                       // apilado vertical 8px
        const reasignBadge = (c.reasignaciones > 0) ? `<span class="cj-postit-reasig" title="Reasignado ${c.reasignaciones}×">↺${c.reasignaciones}</span>` : '';
        const optBadge = c._optimistic ? '<span class="cj-postit-opt" title="Enviando…">⌛</span>' : '';
        html += `<button type="button"
                   class="cj-postit ${colorCls} ${c._optimistic ? 'cj-postit-optimistic' : ''}"
                   data-idcobro="${_esc(c.idCobro)}"
                   data-idventa="${_esc(c.idVenta)}"
                   style="--rot:${rotDeg}deg; --offx:${offX}px; --offy:${offY}px; --zi:${100 - i};"
                   onclick="event.stopPropagation();MOS._cjAbrirPostitModal('${_esc(c.idCobro)}')"
                   title="${_esc(c.cliente || 'VARIOS')} · S/ ${parseFloat(c.monto || 0).toFixed(2)} → ${_esc(c.vendedorDest || '')}">
          <div class="cj-postit-cliente">${_esc((c.cliente || 'VARIOS').substring(0, 14))}</div>
          <div class="cj-postit-monto">S/ ${parseFloat(c.monto || 0).toFixed(2)}</div>
          <div class="cj-postit-foot">
            <span class="cj-postit-tiempo">⏱ ${_esc(restTxt)}</span>
            ${reasignBadge}${optBadge}
          </div>
        </button>`;
      });
      manojo.innerHTML = html;
      // Animación de aterrizaje si es nuevo (postit optimista nuevo)
      if (opts.optimisticId) {
        const nuevo = manojo.querySelector(`[data-idcobro="${opts.optimisticId}"]`);
        if (nuevo) {
          nuevo.classList.add('cj-postit-landing');
          try { _finBeep?.('whoosh') || _finBeep?.('tap'); } catch(_){}
          setTimeout(() => { try { nuevo.classList.remove('cj-postit-landing'); } catch(_){} }, 700);
        }
      }
    });
  }

  // Modal mini con acciones admin sobre un postit
  function _cjAbrirPostitModal(idCobro) {
    const cobro = (_cjCreditosState.enVuelo || []).find(c => String(c.idCobro) === String(idCobro));
    if (!cobro) { toast('Cobro no encontrado', 'warn'); return; }
    try { _finBeep?.('expand') || _finBeep?.('tap'); } catch(_){}
    let backdrop = document.getElementById('cjPostitModal');
    if (!backdrop) {
      backdrop = document.createElement('div');
      backdrop.id = 'cjPostitModal';
      backdrop.className = 'cj-postit-modal-backdrop';
      backdrop.addEventListener('click', (ev) => { if (ev.target === backdrop) _cjCerrarPostitModal(); });
      document.body.appendChild(backdrop);
    }
    const _esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
    const restTxt = _cjPostitRestante(cobro);
    const colorCls = _cjPostitColorClass(cobro);
    const msg = cobro.mensajeAdmin ? `<div class="cj-postit-modal-msg">💬 "${_esc(cobro.mensajeAdmin)}"</div>` : '';
    backdrop.innerHTML = `
      <div class="cj-postit-modal ${colorCls}" role="dialog" aria-modal="true">
        <div class="cj-postit-modal-head">
          <div class="cj-postit-modal-flecha">✈</div>
          <div class="cj-postit-modal-titulo">
            <strong>${_esc(cobro.cliente || 'VARIOS')}</strong>
            <span>→ ${_esc(cobro.vendedorDest || 'cajero')}</span>
          </div>
          <button class="cj-postit-modal-close" onclick="MOS._cjCerrarPostitModal()" aria-label="Cerrar">✕</button>
        </div>
        <div class="cj-postit-modal-monto">S/ ${parseFloat(cobro.monto || 0).toFixed(2)}</div>
        <div class="cj-postit-modal-meta">
          <span>📋 ${_esc(cobro.correlativo || '')}</span>
          <span>⏱ ${_esc(restTxt)}</span>
        </div>
        ${msg}
        <div class="cj-postit-modal-actions">
          <button class="cj-postit-modal-btn cj-postit-modal-btn-ghost" onclick="MOS._cjCerrarPostitModal()">Cerrar</button>
          <button class="cj-postit-modal-btn cj-postit-modal-btn-reasig" onclick="MOS.cjReasignarCobro('${_esc(cobro.idCobro)}')">
            <span>↺</span> Reasignar
          </button>
          <button class="cj-postit-modal-btn cj-postit-modal-btn-cancel" onclick="MOS.cjCancelarCobro('${_esc(cobro.idCobro)}')">
            <span>✕</span> Cancelar
          </button>
        </div>
      </div>`;
    requestAnimationFrame(() => backdrop.classList.add('is-open'));
  }

  function _cjCerrarPostitModal() {
    const b = document.getElementById('cjPostitModal');
    if (!b) return;
    b.classList.remove('is-open');
    setTimeout(() => { try { b.remove(); } catch(_){} }, 200);
    try { _finBeep?.('collapse') || _finBeep?.('tap'); } catch(_){}
  }

  // ════════════════════════════════════════════════════════════
  // [v2.42.00] MODAL CUSTOM Reasignar — reemplaza prompt() nativo
  // ════════════════════════════════════════════════════════════
  async function _cjModalReasignar(cobro) {
    return new Promise(async (resolve) => {
      const cajas = await _cjPrecargarCajasAbiertas();
      const validas = (cajas || []).filter(c => String(c.idCaja) !== String(cobro.cajaDestino));
      if (!validas.length) { resolve(null); toast('No hay otra caja abierta', 'warn'); return; }
      const _esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
      let backdrop = document.createElement('div');
      backdrop.className = 'cj-modal-action-backdrop';
      backdrop.innerHTML = `
        <div class="cj-modal-action cj-modal-action-reasig">
          <div class="cj-modal-action-head">
            <span class="cj-modal-action-ico">↺</span>
            <div class="cj-modal-action-titulo">
              <strong>Reasignar cobro</strong>
              <span>${_esc(cobro.cliente || 'VARIOS')} · S/ ${parseFloat(cobro.monto || 0).toFixed(2)}</span>
            </div>
            <button class="cj-modal-action-close" data-close>✕</button>
          </div>
          <div class="cj-modal-action-body">
            <div class="cj-modal-action-label">Mover de <strong>${_esc(cobro.vendedorDest || '')}</strong> a:</div>
            <div class="cj-modal-action-cajas">
              ${validas.map((c, i) => `
                <button class="cj-modal-action-caja" data-caja="${_esc(c.idCaja)}" style="animation-delay:${i*50}ms">
                  <div class="cj-modal-action-caja-avatar">👤</div>
                  <div class="cj-modal-action-caja-info">
                    <div class="cj-modal-action-caja-nom">${_esc(c.vendedor)}</div>
                    <div class="cj-modal-action-caja-sub">${_esc(c.estacion || '')}${c.zona ? ' · ' + _esc(c.zona) : ''}</div>
                  </div>
                  <span class="cj-modal-action-caja-check">→</span>
                </button>
              `).join('')}
            </div>
          </div>
          <div class="cj-modal-action-footer">
            <button class="cj-modal-action-btn cj-modal-action-btn-ghost" data-close>Cancelar</button>
          </div>
        </div>`;
      backdrop.addEventListener('click', (ev) => {
        const t = ev.target;
        if (t === backdrop || (t.closest && t.closest('[data-close]'))) {
          backdrop.classList.remove('is-open');
          setTimeout(() => { try { backdrop.remove(); } catch(_){} }, 200);
          resolve(null);
          return;
        }
        const cajaBtn = t.closest && t.closest('[data-caja]');
        if (cajaBtn) {
          const id = cajaBtn.dataset.caja;
          const elegida = validas.find(c => String(c.idCaja) === String(id));
          cajaBtn.classList.add('is-selected');
          try { _finBeep?.('success'); } catch(_){}
          setTimeout(() => {
            backdrop.classList.remove('is-open');
            setTimeout(() => { try { backdrop.remove(); } catch(_){} }, 200);
            resolve(elegida);
          }, 180);
        }
      });
      document.body.appendChild(backdrop);
      requestAnimationFrame(() => backdrop.classList.add('is-open'));
      try { _finBeep?.('expand') || _finBeep?.('tap'); } catch(_){}
    });
  }

  // ════════════════════════════════════════════════════════════
  // [v2.42.00] MODAL CUSTOM Cancelar — reemplaza prompt() nativo
  // ════════════════════════════════════════════════════════════
  function _cjModalCancelarCobro(cobro) {
    return new Promise((resolve) => {
      const _esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
      const backdrop = document.createElement('div');
      backdrop.className = 'cj-modal-action-backdrop';
      backdrop.innerHTML = `
        <div class="cj-modal-action cj-modal-action-cancel">
          <div class="cj-modal-action-head">
            <span class="cj-modal-action-ico">⊘</span>
            <div class="cj-modal-action-titulo">
              <strong>Cancelar cobro asignado</strong>
              <span>${_esc(cobro.cliente || 'VARIOS')} · S/ ${parseFloat(cobro.monto || 0).toFixed(2)}</span>
            </div>
            <button class="cj-modal-action-close" data-close>✕</button>
          </div>
          <div class="cj-modal-action-body">
            <div class="cj-modal-action-warn">
              ⚠ El ticket vuelve a estado <strong>CRÉDITO</strong> y el cajero pierde la asignación. Esta acción queda en auditoría.
            </div>
            <label class="cj-modal-action-label">Razón (opcional · queda en log)</label>
            <textarea class="cj-modal-action-textarea" maxlength="180" rows="3"
                      placeholder="Cliente ya no vendrá hoy / asignación errónea / etc."></textarea>
          </div>
          <div class="cj-modal-action-footer">
            <button class="cj-modal-action-btn cj-modal-action-btn-ghost" data-close>Cerrar</button>
            <button class="cj-modal-action-btn cj-modal-action-btn-danger" data-confirm>
              ⊘ Sí, cancelar
            </button>
          </div>
        </div>`;
      backdrop.addEventListener('click', (ev) => {
        const t = ev.target;
        if (t === backdrop || (t.closest && t.closest('[data-close]'))) {
          backdrop.classList.remove('is-open');
          setTimeout(() => { try { backdrop.remove(); } catch(_){} }, 200);
          resolve(null);
        } else if (t.closest && t.closest('[data-confirm]')) {
          const ta = backdrop.querySelector('.cj-modal-action-textarea');
          const razon = ta ? ta.value.trim() : '';
          try { _finBeep?.('warn') || _finBeep?.('tap'); } catch(_){}
          backdrop.classList.remove('is-open');
          setTimeout(() => { try { backdrop.remove(); } catch(_){} }, 200);
          resolve({ razon });
        }
      });
      document.body.appendChild(backdrop);
      requestAnimationFrame(() => backdrop.classList.add('is-open'));
      try { _finBeep?.('expand') || _finBeep?.('tap'); } catch(_){}
    });
  }

  function _cjRestanteTxt(cobro) {
    if (!cobro || !cobro.fechaVencimiento) return '';
    const t = new Date(cobro.fechaVencimiento).getTime();
    if (isNaN(t)) return '';
    const diffMs = t - Date.now();
    if (diffMs <= 0) return '⏰ vencido';
    const min = Math.floor(diffMs / 60000);
    if (min < 60) return min + ' min';
    const h = Math.floor(min / 60);
    const m = min % 60;
    return h + 'h ' + (m > 0 ? m + 'm' : '');
  }
  function _cjUrgenciaClase(cobro) {
    if (!cobro || !cobro.fechaVencimiento) return 'ok';
    const t = new Date(cobro.fechaVencimiento).getTime();
    if (isNaN(t)) return 'ok';
    const diffMin = (t - Date.now()) / 60000;
    if (diffMin <= 5) return 'critical';
    if (diffMin <= 15) return 'warn';
    return 'ok';
  }

  function _cjRenderEnVuelo() {
    // [rediseño] el panel "Cobros en vuelo" se reemplazó por el ✈ animado en la baraja de
    // créditos (indicador) + las cartas "enviado" dentro de la mesa. El panel queda oculto.
    const cont = document.getElementById('cjEnVueloPanel');
    if (cont) { cont.classList.add('hidden'); cont.innerHTML = ''; }
    _cjActualizarAvionMano();
    try { _cjRenderManoDelDia(); } catch (_) {}
    return;
    // ── código viejo del panel (inalcanzable, conservado por historial) ──
    const enVuelo = _cjCreditosState.enVuelo || [];
    const recientes = _cjCreditosState.recientes || [];
    if (!enVuelo.length && !recientes.length) {
      cont.classList.add('hidden');
      cont.innerHTML = '';
      return;
    }
    cont.classList.remove('hidden');
    const _esc = (s) => _escapeHtml(String(s || ''));
    const cardVuelo = (c) => {
      const u = _cjUrgenciaClase(c);
      const restante = _cjRestanteTxt(c);
      const reasignBadge = c.reasignaciones > 0 ? `<span class="cj-vuelo-reasignado" title="Reasignado ${c.reasignaciones} vez(es)">↺ ${c.reasignaciones}</span>` : '';
      const mensaje = c.mensajeAdmin ? `<div class="cj-vuelo-msg">💬 "${_esc(c.mensajeAdmin)}"</div>` : '';
      return `<div class="cj-vuelo-card cj-vuelo-${u}">
        <div class="cj-vuelo-head">
          <div class="cj-vuelo-cliente">
            <span class="cj-vuelo-flecha">✈</span>
            <strong>${_esc(c.cliente || 'VARIOS')}</strong>
            <span class="cj-vuelo-flecha-to">→</span>
            <span class="cj-vuelo-cajero">${_esc(c.vendedorDest)}</span>
            ${reasignBadge}
          </div>
          <span class="cj-vuelo-monto">S/ ${parseFloat(c.monto || 0).toFixed(2)}</span>
        </div>
        <div class="cj-vuelo-meta">
          <span class="cj-vuelo-metodo">${c.metodoSug === 'EFECTIVO' ? '💵' : c.metodoSug === 'VIRTUAL' ? '📱' : '🔀'} ${_esc(c.metodoSug)}</span>
          <span class="cj-vuelo-corr">${_esc(c.correlativo)}</span>
          <span class="cj-vuelo-tiempo cj-vuelo-tiempo-${u}">⏱ ${restante}</span>
        </div>
        ${mensaje}
        <div class="cj-vuelo-actions">
          <button onclick="MOS.cjReasignarCobro('${_esc(c.idCobro)}')" class="cj-vuelo-btn cj-vuelo-btn-reasignar">↺ Reasignar</button>
          <button onclick="MOS.cjCancelarCobro('${_esc(c.idCobro)}')" class="cj-vuelo-btn cj-vuelo-btn-cancelar">✕ Cancelar</button>
        </div>
      </div>`;
    };
    // [v2.41.90] Hora en formato HH:mm de la fecha de resolución
    const _horaRes = (iso) => {
      try {
        const d = new Date(iso);
        if (isNaN(d.getTime())) return '';
        return d.toLocaleTimeString('es-PE', { hour: '2-digit', minute: '2-digit', hour12: false });
      } catch(_) { return ''; }
    };
    // [v2.41.90] Cuánto hace que se resolvió ("hace 5min", "hace 1h 12min")
    const _haceCuanto = (iso) => {
      try {
        const ms = Date.now() - new Date(iso).getTime();
        if (isNaN(ms) || ms < 0) return '';
        const mins = Math.floor(ms / 60000);
        if (mins < 1) return 'ahora mismo';
        if (mins < 60) return 'hace ' + mins + 'min';
        const h = Math.floor(mins / 60);
        const m = mins % 60;
        return 'hace ' + h + 'h' + (m ? ' ' + m + 'min' : '');
      } catch(_) { return ''; }
    };
    const cardReciente = (c) => {
      const estTxt = c.estado === 'COBRADO' ? '✓ COBRADO'
        : c.estado === 'EXPIRADO' ? '⏰ Expirado'
        : c.estado === 'CANCELADO_ADMIN' ? '⊘ Cancelado'
        : c.estado === 'RECHAZADO' ? '✗ Rechazado'
        : c.estado === 'REASIGNADO' ? '↺ Reasignado'
        : c.estado;
      const estClass = c.estado === 'COBRADO' ? 'reciente-ok'
        : c.estado === 'EXPIRADO' || c.estado === 'CANCELADO_ADMIN' ? 'reciente-warn'
        : 'reciente-info';
      const hora = _horaRes(c.fechaRes);
      const hace = _haceCuanto(c.fechaRes);
      return `<div class="cj-vuelo-reciente ${estClass}">
        <span class="cj-vuelo-reciente-estado">${estTxt}</span>
        <strong>${_esc(c.cliente || 'VARIOS')}</strong>
        <span class="cj-vuelo-reciente-monto">S/ ${parseFloat(c.monto || 0).toFixed(2)}</span>
        <span class="cj-vuelo-reciente-cajero">👤 ${_esc(c.vendedorDest)}</span>
        ${hora ? `<span class="cj-vuelo-reciente-hora" title="${_esc(hace)}">🕐 ${hora}</span>` : ''}
      </div>`;
    };
    // [v2.41.90] Separar cobrados de últimas 4h del resto (no esconder en details)
    const ahora = Date.now();
    const _esCobroRecienteHoy = (c) => {
      try {
        const t = new Date(c.fechaRes).getTime();
        return c.estado === 'COBRADO' && (ahora - t) < 4 * 60 * 60 * 1000;
      } catch(_) { return false; }
    };
    const cobradosHoy = recientes.filter(_esCobroRecienteHoy);
    const otrosRecientes = recientes.filter(c => !_esCobroRecienteHoy(c));
    let html = '';
    if (enVuelo.length) {
      html += `<div class="cj-vuelo-section">
        <div class="cj-vuelo-section-titulo">
          ✈ Cobros en vuelo · <strong>${enVuelo.length}</strong>
          <button onclick="MOS._cjCargarEnVuelo()" class="cj-vuelo-refresh" title="Refrescar">↻</button>
        </div>
        <div class="cj-vuelo-list">
          ${enVuelo.map(cardVuelo).join('')}
        </div>
      </div>`;
    }
    // [v2.41.96] Cobrados hoy YA NO se muestran en este panel — el user pidió
    // que aparezcan en la mesa de póker (baraja de créditos) con sello visual
    // de "COBRADO" para que la auditoría sea natural sin un panel separado.
    // Exponemos un set de idVenta cobrados para que _cjPintarCartasMano los
    // marque con sello dorado.
    try {
      window._cjCobradosHoyIdsVenta = new Set(cobradosHoy.map(c => String(c.idVenta || '')));
      window._cjCobradosHoyData = {};
      cobradosHoy.forEach(c => {
        window._cjCobradosHoyData[String(c.idVenta || '')] = {
          cliente: c.cliente || 'VARIOS',
          cajero: c.vendedorDest,
          fechaRes: c.fechaRes,
          monto: c.monto,
          horaTxt: _horaRes(c.fechaRes)
        };
      });
      // Re-pintar la mesa si está abierta (para que aparezcan los nuevos cobrados)
      const mesa = document.getElementById('modalMesaCreditos');
      if (mesa && !mesa.classList.contains('hidden') && typeof cjRepartirMano === 'function') {
        setTimeout(() => { try { cjRepartirMano(); } catch(_) {} }, 100);
      }
    } catch(_) {}
    if (otrosRecientes.length) {
      html += `<div class="cj-vuelo-section">
        <details class="cj-vuelo-recientes-wrap">
          <summary class="cj-vuelo-section-titulo cj-vuelo-section-recientes">
            🕒 Otros recientes · ${otrosRecientes.length} <span class="cj-vuelo-section-hint">click para expandir</span>
          </summary>
          <div class="cj-vuelo-recientes-list">
            ${otrosRecientes.map(cardReciente).join('')}
          </div>
        </details>
      </div>`;
    }
    cont.innerHTML = html;
  }

  // [v2.42.00] Cancelar cobro asignado — modal custom moderno + auth admin.
  // Optimista: cierra modal inmediato, fire-and-forget al backend, rollback si falla.
  async function cjCancelarCobro(idCobro) {
    if (!idCobro) return;
    const cobro = (_cjCreditosState.enVuelo || []).find(c => String(c.idCobro) === String(idCobro));
    if (!cobro) { toast('Cobro no encontrado', 'error'); return; }
    // Cerrar modal del postit antes de abrir el custom
    try { _cjCerrarPostitModal(); } catch(_){}
    // Modal custom de razón (reemplaza prompt nativo)
    const res = await _cjModalCancelarCobro(cobro);
    if (!res) return;
    const auth = await pedirAuth({
      accion: 'CANCELAR_COBRO_ASIGNADO',
      refDocumento: idCobro,
      contexto: 'Cancelar cobro · vuelve a CRÉDITO'
    });
    if (!auth) return;
    // Optimista: quitar postit inmediato
    _cjCreditosState.enVuelo = (_cjCreditosState.enVuelo || []).filter(c => c.idCobro !== idCobro);
    try { _cjPintarPostitsManojos(); } catch(_){}
    try { _finBeep?.('remove') || _finBeep?.('tap'); } catch(_){}
    toast('⊘ Cobro cancelado · ticket vuelve a CRÉDITO', 'ok', 4000);
    try {
      const rCancel = await API.post('meCancelarCobroAsignado', {
        idCobro: idCobro,
        razon:   res.razon || '',
        adminAuth: { nombre: auth.nombre, rol: auth.rol, via: 'PIN_8DIG' }
      });
      // [cero-GAS] el directo NO manda el push server-side (a diferencia de GAS): lo dispara el front.
      try {
        if (rCancel && rCancel.via === 'directo' && rCancel.pushTitulo && rCancel.pushVendedor) {
          API.enviarPushSB(rCancel.pushTitulo, rCancel.pushCuerpo, { soloUsuarios: [rCancel.pushVendedor], incluirCompanions: true });
        }
      } catch(_){}
      // Refresh definitivo
      _cjCargarEnVuelo();
      _cjCargarCreditosPendientes();
    } catch(e) {
      toast('⚠ Error cancelando: ' + (e.message || e) + ' · refresca', 'error', 6000);
      _cjCargarEnVuelo();   // re-fetch para restaurar estado real
    }
  }

  // [v2.42.00] Reasignar cobro a otra caja — modal custom (sin prompt nativo)
  // + optimista + auth admin + rollback en error.
  async function cjReasignarCobro(idCobro) {
    if (!idCobro) return;
    const cobro = (_cjCreditosState.enVuelo || []).find(c => String(c.idCobro) === String(idCobro));
    if (!cobro) { toast('Cobro no encontrado', 'error'); return; }
    try { _cjCerrarPostitModal(); } catch(_){}
    // Modal custom selector de caja (reemplaza prompt nativo + lista numerada)
    const nuevaCaja = await _cjModalReasignar(cobro);
    if (!nuevaCaja) return;
    const auth = await pedirAuth({
      accion: 'REASIGNAR_COBRO_ASIGNADO',
      refDocumento: idCobro,
      contexto: `Reasignar a ${nuevaCaja.vendedor}`
    });
    if (!auth) return;
    // Optimista: actualizar el postit en memoria (cambia cajaDestino + vendedorDest)
    const cobroIdx = (_cjCreditosState.enVuelo || []).findIndex(c => c.idCobro === idCobro);
    const cobroSnap = cobroIdx >= 0 ? { ..._cjCreditosState.enVuelo[cobroIdx] } : null;
    if (cobroIdx >= 0) {
      _cjCreditosState.enVuelo[cobroIdx] = {
        ..._cjCreditosState.enVuelo[cobroIdx],
        cajaDestino:  nuevaCaja.idCaja,
        vendedorDest: nuevaCaja.vendedor,
        reasignaciones: (_cjCreditosState.enVuelo[cobroIdx].reasignaciones || 0) + 1
      };
      try { _cjPintarPostitsManojos({ optimisticId: idCobro }); } catch(_){}
    }
    try { _finBeep?.('success'); } catch(_){}
    toast('↺ Reasignado a ' + nuevaCaja.vendedor, 'ok', 4000);
    try {
      const rReasig = await API.post('meReasignarCobroAsignado', {
        idCobro:     idCobro,
        cajaDestino: nuevaCaja.idCaja,
        adminAuth:   { nombre: auth.nombre, rol: auth.rol, via: 'PIN_8DIG' }
      });
      // [cero-GAS] avisar al NUEVO cajero (el directo no manda push server-side como GAS).
      try {
        if (rReasig && rReasig.via === 'directo' && rReasig.pushTitulo && rReasig.cajeroDestino) {
          API.enviarPushSB(rReasig.pushTitulo, rReasig.pushCuerpo, { soloUsuarios: [rReasig.cajeroDestino], incluirCompanions: true });
        }
      } catch(_){}
      _cjCargarEnVuelo();
    } catch(e) {
      // Rollback al snapshot
      if (cobroSnap && cobroIdx >= 0) {
        _cjCreditosState.enVuelo[cobroIdx] = cobroSnap;
        try { _cjPintarPostitsManojos(); } catch(_){}
      }
      toast('⚠ Error reasignando: ' + (e.message || e), 'error', 6000);
      _cjCargarEnVuelo();
    }
  }

  async function _cjCargarCreditosPendientes() {
    // [v41.9] Mostrar skeleton mientras se carga si NO hay datos previos.
    // Si ya hay grupos cargados (refresh silencioso cada 20s), no perturbar la UI.
    const mano = $('cjCreditosMano');
    const yaHayData = _cjCreditosState.todosLosGrupos.length > 0;
    if (mano && !yaHayData) {
      mano.classList.remove('hidden');
      _cjPintarSkeleton();
    }
    try {
      const r = await API.post('meGetCreditosPendientes', { diasAtras: 365 });   // [créditos] no perder créditos viejos (mayo etc.)
      const d = (r && r.data) ? r.data : (r || {});
      _cjCreditosState.todosLosGrupos = d.grupos || [];
      _cjRenderManoDelDia();
    } catch(e) {
      console.warn('[creditos] error cargando:', e?.message || e);
      // Si falló y no había data previa, ocultar la baraja (mejor que dejar skeleton infinito)
      if (mano && !yaHayData) mano.classList.add('hidden');
    }
  }

  // [v41.9] Skeleton mientras carga: 3 cartas placeholder en abanico con shimmer.
  // Reusa las posiciones data-pos del fan-out real, así la transición a las cartas
  // reales es continua (sin "salto" de layout).
  function _cjPintarSkeleton() {
    const cont = $('cjManoContenedor');
    if (!cont) return;
    cont.innerHTML = [0, 1, 2].map(pos => `
      <div class="cj-carta-mano cj-carta-skeleton" data-pos="${pos}">
        <div class="cj-skel-head">
          <span class="cj-skel-line cj-skel-w60"></span>
          <span class="cj-skel-line cj-skel-w35 cj-skel-tall"></span>
        </div>
        <span class="cj-skel-line cj-skel-w30 cj-skel-thin"></span>
        <div class="cj-skel-sep"></div>
        <span class="cj-skel-line cj-skel-w90"></span>
        <span class="cj-skel-line cj-skel-w75"></span>
        <span class="cj-skel-line cj-skel-w85"></span>
        <span class="cj-skel-line cj-skel-w70"></span>
        <div class="cj-skel-spinner"></div>
      </div>
    `).join('');
  }

  function _cjFmtFechaCorta(yyyyMmDd) {
    if (!yyyyMmDd) return '—';
    // [v41.8 FIX] Antes usaba toISOString() (UTC) → en Lima (UTC-5), ventas
    // de las 19:00 quedaban marcadas como del día siguiente UTC y se veían
    // como "Ayer". Ahora usa today() global que computa fecha LOCAL.
    const hoyLoc = today();
    const z = n => String(n).padStart(2,'0');
    const dAyer = new Date(); dAyer.setDate(dAyer.getDate() - 1);
    const ayerLoc = `${dAyer.getFullYear()}-${z(dAyer.getMonth()+1)}-${z(dAyer.getDate())}`;
    if (yyyyMmDd === hoyLoc) return 'Hoy';
    if (yyyyMmDd === ayerLoc) return 'Ayer';
    const parts = yyyyMmDd.split('-');
    const meses = ['ene','feb','mar','abr','may','jun','jul','ago','sep','oct','nov','dic'];
    return parts[2] + ' ' + meses[parseInt(parts[1],10)-1];
  }

  // Renderiza la mano de cartas para la fecha que está activa en el filtro de cajas
  function _cjRenderManoDelDia() {
    const fechaActiva = $('cjFecha')?.value || today();
    const grupo = _cjCreditosState.todosLosGrupos.find(g => g.fecha === fechaActiva);
    const mano = $('cjCreditosMano');
    if (!mano) return;

    // [610] La baraja solo baraja VIVOS. Los saldados (CAJA/PLANILLA) viven en
    // la mesa con sello ✓ COBRADO, pero no giran en la mano ni suman pendiente.
    const vivos = grupo ? (grupo.tickets || []).filter(t => !t.estadoCobro || t.estadoCobro === 'VIVO') : [];

    if (!grupo || !vivos.length) {
      _cjCreditosState.ticketsActivos = [];
      _cjCreditosState.fechaActiva = null;
      _cjStopShuffle();
      // [rediseño] sin créditos pendientes pero CON cobros en vuelo → baraja visible solo
      // para el ✈ (sin cartas). Sin nada de ambos → ocultar.
      const hayVuelo = (_cjCreditosState.enVuelo || []).length > 0;
      const cont0 = $('cjManoContenedor'); if (cont0) cont0.innerHTML = '';
      mano.classList.toggle('hidden', !hayVuelo);
      _cjActualizarAvionMano();
      return;
    }
    mano.classList.remove('hidden');
    // [v41] Solo resetear shuffleIdx si cambió la fecha activa. Si solo es un
    // refresh (mismo día, nuevos tickets), preservar el progreso del shuffle.
    const fechaCambia = _cjCreditosState.fechaActiva !== fechaActiva;
    _cjCreditosState.fechaActiva = fechaActiva;
    _cjCreditosState.ticketsActivos = vivos;
    if (fechaCambia) _cjCreditosState.shuffleIdx = 0;
    // Si el idx quedó fuera de rango (porque desaparecieron cartas), normalizar
    if (_cjCreditosState.shuffleIdx >= vivos.length) {
      _cjCreditosState.shuffleIdx = 0;
    }

    _cjPintarCartasMano();
    _cjActualizarAvionMano();   // [rediseño] ✈ badge de cobros en vuelo

    // Arrancar shuffle automático cada 4s (solo si hay >= 2 cartas)
    _cjStopShuffle();
    if (vivos.length >= 2) {
      _cjCreditosState.shuffleTimer = setInterval(_cjShuffleStep, 4000);
    }
  }
  // [rediseño] actualiza el ✈ animado sobre la baraja de créditos (cobros en vuelo)
  function _cjActualizarAvionMano() {
    const av = $('cjManoAvion'); if (!av) return;
    const n = (_cjCreditosState.enVuelo || []).length;
    if (n > 0) { av.classList.remove('hidden'); const e = $('cjManoAvionN'); if (e) e.textContent = String(n); }
    else av.classList.add('hidden');
  }

  // Limpia el nombre de producto: quita la parte parentética redundante "(nombre repetido)"
  // que se ve en los datos (ej. "ALSABOR SALSA INGLESA (ALSABOR SALSA INGLESA)").
  function _cjLimpiarNombreItem(nombre) {
    const s = String(nombre || '').trim();
    return s.replace(/\s*\([^)]*\)\s*$/, '').trim();
  }

  // Genera el resumen voucher de items para mostrar en la cara de la carta.
  // Formato: "1× IDEAL LECHE CREMOSITA ........ S/ 4.20"
  // Trunca el nombre a 16 chars para que entre. Si hay más items, "+N más" al final.
  function _cjResumenItemsVoucher(items, max, nombreMaxChars) {
    if (!items || !items.length) {
      return `<div class="cj-carta-items"><div class="cj-carta-items-mas">sin productos</div></div>`;
    }
    const top = items.slice(0, max);
    const restantes = items.length - top.length;
    const filas = top.map(it => {
      const nombre = _esc(_cjLimpiarNombreItem(it.nombre).substring(0, nombreMaxChars || 16));
      const cant = parseFloat(it.cantidad) || 0;
      const sub = parseFloat(it.subtotal) || 0;
      // Formateo de cantidad: enteros sin decimales, granel con 1-2 decimales
      const cantStr = Number.isInteger(cant) ? String(cant) : cant.toFixed(2).replace(/\.?0+$/, '');
      return `<div class="cj-carta-items-item">
        <span class="cj-carta-items-cant">${cantStr}×</span>
        <span class="cj-carta-items-nom">${nombre}</span>
        <span class="cj-carta-items-sub">${sub.toFixed(2)}</span>
      </div>`;
    }).join('');
    const mas = restantes > 0
      ? `<div class="cj-carta-items-mas">+${restantes} más…</div>`
      : '';
    return `<div class="cj-carta-items">${filas}${mas}</div>`;
  }

  function _cjPintarCartasMano() {
    const cont = $('cjManoContenedor');
    if (!cont) return;
    const tickets = _cjCreditosState.ticketsActivos;
    const idxFront = _cjCreditosState.shuffleIdx;
    const N = tickets.length;
    const idsVistos = _cjCreditosState.idsVistos;
    const esPrimerRender = idsVistos.size === 0;
    const cartas = tickets.map((t, i) => {
      const pos = (i - idxFront + N) % N;
      const posAttr = pos >= 5 ? '5+' : String(pos);
      const asigBadge = t.asignado
        ? `<span class="cj-carta-asignado-badge">✈</span>`
        : '';
      const cliente = _esc((t.cliente || 'VARIOS').toUpperCase());
      const doc = t.clienteDoc && t.clienteDoc !== '66666'
        ? `<div class="cj-carta-doc">${_esc(t.clienteDoc)}</div>` : '';
      const esNuevo = !esPrimerRender && !idsVistos.has(t.idVenta);
      const claseNueva = esNuevo ? ' cj-carta-nueva' : '';
      return `<div class="cj-carta-mano${claseNueva}" data-pos="${posAttr}" data-idx="${i}">
        ${asigBadge}
        <div class="cj-carta-head">
          <span class="cj-carta-cliente">${cliente}</span>
          <span class="cj-carta-monto">S/${parseFloat(t.total).toFixed(2)}</span>
        </div>
        ${doc}
        <div class="cj-carta-sep"></div>
        ${_cjResumenItemsVoucher(t.items, 4, 15)}
        <div class="cj-carta-meta">${_esc(t.correlativo)}</div>
      </div>`;
    }).join('');
    cont.innerHTML = cartas;
    tickets.forEach(t => idsVistos.add(t.idVenta));
    if (!esPrimerRender && cont.querySelector('.cj-carta-nueva')) {
      try { _finBeep?.('alert'); } catch(_){}
      try { if (navigator.vibrate) navigator.vibrate([30, 60, 30]); } catch(_){}
    }
  }

  function _cjShuffleStep() {
    const tickets = _cjCreditosState.ticketsActivos;
    if (!tickets || tickets.length < 2) return;
    // Si el overlay de mesa o detalle está abierto, pausar shuffle
    const mesa = $('modalMesaCartas'); const det = $('modalDetalleCarta');
    if ((mesa && !mesa.classList.contains('hidden')) || (det && !det.classList.contains('hidden'))) return;
    _cjCreditosState.shuffleIdx = (_cjCreditosState.shuffleIdx + 1) % tickets.length;
    _cjPintarCartasMano();
  }

  function _cjStopShuffle() {
    if (_cjCreditosState.shuffleTimer) {
      clearInterval(_cjCreditosState.shuffleTimer);
      _cjCreditosState.shuffleTimer = null;
    }
  }

  // Click en la mano → repartir TODAS las cartas en la mesa, agrupadas por
  // fecha. La sección "Hoy" se destaca con badge brillante. Los días anteriores
  // van debajo en orden cronológico inverso, así el admin puede cobrar un
  // crédito viejo sin tener que cambiar el filtro de fecha del módulo.
  function cjRepartirMano() {
    const grupos = _cjCreditosState.todosLosGrupos || [];
    if (!grupos.length) return;
    _cjInyectarCSSTrabajador();   // [850] el botón ASIGNAR vive en cada carta de la mesa
    try { _finBeep?.('click'); } catch(_){}

    const hoyStr = today();
    // [610] cuenta/total del backend = SOLO vivos; los saldados van aparte con sello
    const totalTickets = grupos.reduce((s, g) => s + (g.cuenta != null ? (parseInt(g.cuenta, 10) || 0) : (g.tickets ? g.tickets.length : 0)), 0);
    const totalMonto = grupos.reduce((s, g) => s + (parseFloat(g.total) || 0), 0);
    const totalPagados = grupos.reduce((s, g) => s + (parseInt(g.cuentaPagados, 10) || 0), 0);

    const lblF = $('cjMesaFechaLabel');
    if (lblF) lblF.textContent = `Todos · ${totalTickets} pendiente${totalTickets === 1 ? '' : 's'}${totalPagados ? ` · ✓${totalPagados} cobrados` : ''}`;
    const lblS = $('cjMesaSubtitulo');
    if (lblS) lblS.textContent = `S/ ${totalMonto.toFixed(2)} pendientes en ${grupos.length} día${grupos.length === 1 ? '' : 's'} · toca una carta para ver detalle`;

    // Días ordenados: hoy primero, luego los más recientes
    const ordenados = grupos.slice().sort((a, b) => {
      if (a.fecha === hoyStr) return -1;
      if (b.fecha === hoyStr) return 1;
      return b.fecha.localeCompare(a.fecha);
    });

    const grid = $('cjMesaGrid');
    if (!grid) return;

    let cartaGlobalIdx = 0; // animation-delay continuo entre secciones

    // [v2.42.09] Cobrados hoy YA NO van en sección separada. En su lugar la
    // carta original (que SIGUE en el grupo "Hoy ACTIVOS") cambia de fondo
    // a verde + sello COBRADO encima. User pidió "mismo ticket, mismo lugar,
    // otro color de fondo y sello cobrado".
    const cobradosIds = window._cjCobradosHoyIdsVenta || new Set();
    const cobradosData = window._cjCobradosHoyData || {};

    grid.innerHTML = ordenados.map(g => {
      const esHoy = g.fecha === hoyStr;
      const fechaLbl = _cjFmtFechaCorta(g.fecha);
      const diasAtras = _cjDiasDesde(g.fecha);
      const subFecha = esHoy
        ? '🔥 ACTIVOS'
        : (diasAtras === 1 ? 'ayer' : `hace ${diasAtras} días`);
      const tickets = g.tickets || [];
      const totalDia = parseFloat(g.total || 0);

      const cartas = tickets.map(t => {
        const asig = t.asignado;
        const asigClass = asig ? 'is-asignada' : '';
        const asigBadge = asig
          ? `<span class="cj-carta-asignado-badge" style="position:relative; top:0; right:0; margin-bottom:8px; display:inline-block;">✈ Enviado a ${_esc(asig.vendedorDest)}</span>`
          : '';
        // [rediseño] ticket "enviado" (en vuelo) → botones reasignar/cancelar INLINE en la mesa
        // (reemplaza el panel). idCobro se toma del cobro en vuelo que matchea por idVenta.
        const cobroEV = asig ? (_cjCreditosState.enVuelo || []).find(cv => String(cv.idVenta) === String(t.idVenta)) : null;
        const asigActions = cobroEV
          ? `<div class="cj-mesa-carta-actions" onclick="event.stopPropagation()">
               <button onclick="MOS.cjReasignarCobro('${_esc(cobroEV.idCobro)}')" class="cj-vuelo-btn cj-vuelo-btn-reasignar">↺ Reasignar</button>
               <button onclick="MOS.cjCancelarCobro('${_esc(cobroEV.idCobro)}')" class="cj-vuelo-btn cj-vuelo-btn-cancelar">✕ Cancelar</button>
             </div>`
          : '';
        const cliente = _esc((t.cliente || 'VARIOS').toUpperCase());
        const delay = (cartaGlobalIdx++) * 60;
        // [v2.42.09] Si el ticket fue cobrado hoy via cobro asignado, aplicar
        // clase cobrada (fondo verde + sello) en su lugar original sin
        // separarlo del grupo. _cjCobradosHoyIdsVenta es Set poblado por
        // _cjCargarEnVuelo a partir de los recientes COBRADO de últimas 4h.
        // [610] Y ADEMÁS (permanente, verdad del server): estadoCobro CAJA /
        // PLANILLA → el ticket saldado sigue en la mesa con sello y su vía.
        const esCobradoSrv = !!(t.estadoCobro && t.estadoCobro !== 'VIVO');
        const esCobrado = esCobradoSrv || cobradosIds.has(String(t.idVenta));
        const cobrInfo = (!esCobradoSrv && esCobrado) ? cobradosData[String(t.idVenta)] : null;
        const cobradoClass = (esCobrado ? 'cj-mesa-carta-cobrada' : '')
          + ((t.trabajador && t.trabajador.nombre && !esCobrado) ? ' cj-mesa-carta-tk' : '');
        const selloCobrado = esCobrado
          ? `<div class="cj-carta-sello-cobrado">✓ COBRADO</div>`
          : '';
        const metaCobrado = esCobradoSrv
          ? ` · ${t.estadoCobro === 'PLANILLA' ? '🧾' : '💼'} ${_esc(t.cobradoDetalle || (t.estadoCobro === 'PLANILLA' ? 'Liquidación' : 'Caja'))}`
          : (esCobrado && cobrInfo
              ? ` · 👤 ${_esc(cobrInfo.cajero || '—')} · 🕐 ${_esc(cobrInfo.horaTxt || '')}`
              : '');
        return `<div class="cj-mesa-carta ${asigClass} ${cobradoClass}"
                     style="animation-delay: ${delay}ms"
                     data-tk="${_esc(t.idVenta)}"
                     onclick="MOS.cjAbrirDetalleCarta('${_esc(t.idVenta)}')">
          ${selloCobrado}
          ${asigBadge}
          ${_cjTkChipHTML(t)}
          <div class="cj-carta-head">
            <span class="cj-carta-cliente">${cliente}</span>
            <span class="cj-carta-monto">S/${parseFloat(t.total).toFixed(2)}</span>
          </div>
          ${t.clienteDoc && t.clienteDoc !== '66666' ? `<div class="cj-carta-doc">${_esc(t.clienteDoc)}</div>` : ''}
          <div class="cj-carta-sep"></div>
          ${_cjResumenItemsVoucher(t.items, 6, 22)}
          <div class="cj-carta-meta">${_esc(t.correlativo)} · ${_esc(t.vendedor)}${metaCobrado}</div>
          ${_cjTkMesaHTML(t)}
          ${asigActions}
        </div>`;
      }).join('');

      return `<section class="cj-mesa-grupo ${esHoy ? 'cj-mesa-grupo-hoy' : ''}">
        <header class="cj-mesa-grupo-head">
          <div class="cj-mesa-grupo-titulo">
            <span class="cj-mesa-grupo-emoji">${esHoy ? '🌟' : '📅'}</span>
            <span class="cj-mesa-grupo-fecha">${_esc(fechaLbl)}</span>
            <span class="cj-mesa-grupo-sub">${subFecha}</span>
          </div>
          <div class="cj-mesa-grupo-stats">
            <span class="cj-mesa-grupo-cuenta">${(() => {
              const pag = tickets.filter(x => x.estadoCobro && x.estadoCobro !== 'VIVO').length;
              const viv = tickets.length - pag;
              return `${viv} pend${pag ? ` · ✓${pag}` : ''}`;
            })()}</span>
            <span class="cj-mesa-grupo-monto">S/ ${totalDia.toFixed(2)}</span>
          </div>
        </header>
        <div class="cj-mesa-grupo-cartas">${cartas}</div>
      </section>`;
    }).join('');

    const modal = $('modalMesaCartas');
    if (modal) modal.classList.remove('hidden');
  }

  // Días enteros entre la fecha dada (yyyy-MM-dd) y hoy. >0 si es pasada.
  function _cjDiasDesde(yyyyMmDd) {
    if (!yyyyMmDd) return 0;
    try {
      const [y, m, d] = yyyyMmDd.split('-').map(Number);
      const ayer = new Date(y, m - 1, d);
      const hoy = new Date();
      const ms = (new Date(hoy.getFullYear(), hoy.getMonth(), hoy.getDate())) - ayer;
      return Math.round(ms / (1000 * 60 * 60 * 24));
    } catch(_) { return 0; }
  }

  function cjCerrarMesa(ev) {
    if (ev && ev.target && ev.target.id !== 'modalMesaCartas') return;
    const modal = $('modalMesaCartas');
    if (modal) modal.classList.add('hidden');
  }

  // Abre el detalle de una carta específica — busca por idVenta en todos los grupos
  // (la mesa ahora muestra cartas de varias fechas, no solo del día activo).
  // ══════════════════════════════════════════════════════════════════════
  // [848] CARGAR UN CRÉDITO A UN TRABAJADOR (rescate desde MOS)
  //
  // El camino normal es el POS: al dar el crédito, el cajero elige de una lista a quién de los
  // que trabajan HOY se le da. Esto es para lo que se escapó — un ticket que quedó sin dueño,
  // típicamente cargado a "VARIOS".
  //
  // El vínculo apunta a un TURNO (persona + día), no a un nombre. Un nombre se repite: la otra
  // semana puede entrar otro Marcelo y sería, literalmente, la misma identidad. Un turno ya
  // ocurrido es único para siempre. Por eso solo se ofrecen los turnos DEL MISMO DÍA del ticket:
  // se le carga a quien vino a trabajar ese día, no se arrastra al siguiente.
  // ══════════════════════════════════════════════════════════════════════
  // [850] Lo que se ve en la carta de la MESA (sin abrirla): el botón ASIGNAR si el consumo
  // todavía no tiene dueño, o el nombre de quién lo paga si ya lo tiene.
  // [851] El sello de asignación: ícono de usuario + nombre, arriba a la IZQUIERDA de la carta,
  // con una ✕ encima para deshacerlo de un toque si el admin se equivocó de persona.
  function _cjTkChipHTML(t) {
    const tr = t && t.trabajador;
    if (!tr || !tr.nombre) return '';
    const yaDesc = String(tr.estado || '') === 'DESCONTADO';
    return '<span class="cj-carta-tk-chip' + (yaDesc ? ' is-desc' : '') + '">' +
      (yaDesc ? '' : '<button type="button" class="cj-carta-tk-x" title="Quitar la asignación"' +
         ' onclick="event.stopPropagation();MOS.cjTrabajadorQuitar(\'' + _esc(String(t.idVenta)) + '\')">✕</button>') +
      '<span class="cj-carta-tk-ico">👤</span><b>' + _esc(String(tr.nombre)) + '</b>' +
      (yaDesc ? '<i>ya descontado</i>' : '') + '</span>';
  }

  function _cjTkMesaHTML(t) {
    if (!t) return '';
    const tr = t.trabajador;
    if (tr && tr.nombre) return '';   // [851] ya lo dice el chip de arriba
    // [880] Personal FIJO (documento en ficha): su consumo entra SOLO en su liquidación, sin
    // asignar nada. El botón ASIGNAR acá confundía (es para trabajadores de zona sin ficha).
    if (t.planillaAuto) {
      return '<span class="cj-carta-tk-chip" title="Su documento está en su ficha: este crédito se descuenta solo al pagar su liquidación">' +
        '<span class="cj-carta-tk-ico">💼</span><b>' + _esc(String(t.planillaAuto).split(' ')[0]) + '</b><i>planilla automática</i></span>';
    }
    if (t.estadoCobro && t.estadoCobro !== 'VIVO') return '';
    // [850] En un día ya liquidado no queda turno al que cargarlo: el servidor lo rechazaría.
    // Sin botón, así el admin no persigue una opción que no existe.
    if (t.turnosAbiertos === false) return '';
    return '<button type="button" class="cj-carta-tk-btn" title="Cargar este consumo a alguien que trabajó ese día"' +
      ' onclick="event.stopPropagation();MOS.cjTrabajadorAbrir(\'' + _esc(String(t.idVenta)) + '\')">👤 ASIGNAR</button>';
  }

  function _cjTrabajadorBloqueHTML(t) {
    const tr = t && t.trabajador;
    if (tr && tr.nombre) {
      const yaDesc = String(tr.estado || '') === 'DESCONTADO';
      return `<div class="cj-det-asignado-banner" style="background:rgba(56,189,248,.14);border-color:rgba(56,189,248,.45);color:#7dd3fc">
        👤 ${yaDesc ? 'Descontado a' : 'Se le descuenta a'} <strong>${_esc(tr.nombre)}</strong>
        ${tr.fechaDia ? ' · liquidación del ' + _esc(tr.fechaDia) : ''}
        ${yaDesc ? '' : `<button type="button" class="cj-det-tk-quitar" onclick="MOS.cjTrabajadorQuitar('${_esc(String(t.idVenta))}')">quitar</button>`}
      </div>`;
    }
    // [880] personal fijo: el descuento es automático al liquidar (por su documento), sin botón
    if (t && t.planillaAuto) {
      return `<div class="cj-det-asignado-banner" style="background:rgba(52,211,153,.12);border-color:rgba(52,211,153,.4);color:#6ee7b7">
        💼 Se descuenta solo en la liquidación de <strong>${_esc(String(t.planillaAuto))}</strong> (su documento está en su ficha)</div>`;
    }
    if (t && t.estadoCobro && t.estadoCobro !== 'VIVO') return '';
    // [850] día sin turnos abiertos: se dice por qué, en vez de ofrecer un botón que va a fallar
    if (t && t.turnosAbiertos === false) {
      return `<div class="cj-det-tk-nota">👤 Ese día ya no tiene turnos abiertos —
        sus liquidaciones están pagadas o vetadas, así que no se le puede cargar a nadie.</div>`;
    }
    return `<button type="button" class="cj-det-tk-btn" onclick="MOS.cjTrabajadorAbrir('${_esc(String(t.idVenta))}')">
      👤 ASIGNAR a un trabajador de ese día</button>`;
  }

  // [851] Repinta SOLO la carta tocada: color, chip y botón. Es lo que hace que la asignación
  // se sienta instantánea sin re-dibujar toda la mesa (y sin perder el scroll).
  function _cjPintarTk(idVenta, opts) {
    const t = _cjBuscarTicket(idVenta); if (!t) return;
    const asignado = !!(t.trabajador && t.trabajador.nombre);
    document.querySelectorAll('.cj-mesa-carta[data-tk="' + String(idVenta).replace(/"/g, '') + '"]').forEach(el => {
      el.classList.toggle('cj-mesa-carta-tk', asignado);
      const chip = el.querySelector('.cj-carta-tk-chip'); if (chip) chip.remove();
      const btn  = el.querySelector('.cj-carta-tk-btn');  if (btn)  btn.remove();
      if (asignado) {
        el.insertAdjacentHTML('afterbegin', _cjTkChipHTML(t));
        const c = el.querySelector('.cj-carta-tk-chip');
        if (c && !(opts && opts.silent)) { c.classList.add('tk-pop'); setTimeout(() => c.classList.remove('tk-pop'), 460); }
      } else {
        const meta = el.querySelector('.cj-carta-meta');
        const html = _cjTkMesaHTML(t);
        if (meta && html) meta.insertAdjacentHTML('afterend', html);
      }
      if (opts && opts.shake) { el.classList.add('tk-shake'); setTimeout(() => el.classList.remove('tk-shake'), 480); }
    });
    // si el detalle está abierto sobre este ticket, que cuente lo mismo
    const det = document.getElementById('modalDetalleCarta');
    if (det && !det.classList.contains('hidden') &&
        _cjCreditosState.detalleTicket && String(_cjCreditosState.detalleTicket.idVenta) === String(idVenta)) {
      cjAbrirDetalleCarta(idVenta);
    }
  }

  async function cjTrabajadorAbrir(idVenta) {
    const t = _cjBuscarTicket(idVenta);
    if (!t) { toast('No encontré ese ticket', 'warn'); return; }
    const fecha = String(t.fechaISO || '').slice(0, 10);
    _cjInyectarCSSTrabajador();
    const prev = document.getElementById('cjTkOvl'); if (prev) prev.remove();
    const ovl = document.createElement('div');
    ovl.id = 'cjTkOvl'; ovl.className = 'cjtk-back';
    ovl.onpointerdown = e => { if (e.target === ovl) MOS.cjTrabajadorCerrar(); };
    ovl.innerHTML = '<div class="cjtk-card" role="dialog" aria-label="Elegir trabajador">' +
      '<div class="cjtk-head"><div><b>👤 ¿A quién se le carga?</b>' +
        '<span>' + _escapeHtml(String(t.correlativo || '')) + ' · S/ ' + _money(t.total).toFixed(2) +
        ' · turnos del ' + _escapeHtml(fecha) + '</span></div>' +
        '<button class="cjtk-x" onclick="MOS.cjTrabajadorCerrar()" aria-label="Cerrar">✕</button></div>' +
      '<div class="cjtk-body"><div class="cjtk-load">◍ buscando quién trabajó ese día…</div></div></div>';
    document.body.appendChild(ovl);
    requestAnimationFrame(() => ovl.classList.add('in'));

    let turnos = [];
    try {
      const r = await API.post('turnosDelDia', { fecha });
      turnos = ((r && (r.data || r)) || {}).turnos || [];
    } catch (e) {
      const b = ovl.querySelector('.cjtk-body');
      if (b) b.innerHTML = '<div class="cjtk-load">No pude leer los turnos: ' + _escapeHtml(e.message || String(e)) + '</div>';
      return;
    }
    const body = ovl.querySelector('.cjtk-body'); if (!body) return;
    if (!turnos.length) {
      body.innerHTML = '<div class="cjtk-load">Ese día no quedó ningún turno abierto al que cargarle el consumo.<br>' +
        '<small>Los turnos ya pagados o vetados tienen el monto sellado.</small></div>';
      return;
    }
    _cjTkTurnos = {}; turnos.forEach(x => { _cjTkTurnos[String(x.idDia)] = x; });
    body.innerHTML = turnos.map(x =>
      '<button type="button" class="cjtk-row" onclick="MOS.cjTrabajadorElegir(\'' + _esc(String(idVenta)) + '\',\'' +
        _esc(String(x.idDia)) + '\')">' +
        '<span class="cjtk-ini">' + _escapeHtml((String(x.nombre || '?').trim()[0] || '?').toUpperCase()) + '</span>' +
        '<span class="cjtk-txt"><b>' + _escapeHtml(String(x.nombre || '')) + '</b>' +
          '<i>' + _escapeHtml(String(x.rol || '')) + (x.zona ? ' · ' + _escapeHtml(String(x.zona)) : '') +
          (x.horaIngreso ? ' · desde ' + _escapeHtml(String(x.horaIngreso)) : '') + '</i></span>' +
        (x.yaAsignado > 0 ? '<span class="cjtk-ya" title="Ya consumió ese día">S/ ' + _money(x.yaAsignado).toFixed(2) + '</span>' : '') +
      '</button>').join('');
  }

  let _cjTkTurnos = {};   // [851] idDia → turno, para no meter nombres en un onclick

  function _cjBuscarTicket(idVenta) {
    const idV = String(idVenta);
    for (const g of (_cjCreditosState.todosLosGrupos || [])) {
      const f = (g.tickets || []).find(x => String(x.idVenta) === idV);
      if (f) return f;
    }
    return (_cjCreditosState.ticketsActivos || []).find(x => String(x.idVenta) === idV) || null;
  }

  // [851] Asignar mueve dinero: le baja el pago del día a una persona. Por eso pide clave y queda
  // auditado (mismo camino que anular un pago). La pantalla no espera al servidor: pinta primero y,
  // si el servidor rechaza, vuelve sola con un temblor y un buzz — nunca se queda mintiendo.
  async function cjTrabajadorElegir(idVenta, idDia) {
    const t = _cjBuscarTicket(idVenta); if (!t) return;
    const turno = _cjTkTurnos[String(idDia)] || {};
    const nombre = String(turno.nombre || '');
    cjTrabajadorCerrar();
    const auth = await pedirAuth({
      accion: 'ASIGNAR_CREDITO_TRABAJADOR',
      refDocumento: t.correlativo || idVenta,
      contexto: 'Asignar el consumo de S/ ' + _money(t.total).toFixed(2) + ' a ' + (nombre || 'ese turno')
    });
    if (!auth) return;

    const previo = t.trabajador || null;
    t.trabajador = { nombre, idDia, estado: 'ASIGNADO', fechaDia: String(t.fechaISO || '').slice(0, 10) };
    _cjPintarTk(idVenta);
    try { _finBeep?.('agregar'); } catch(_){}
    toast('👤 Se le descuenta a ' + (nombre || 'ese turno'), 'ok', 3200);
    try {
      const r = await API.post('creditoAsignar', {
        idVenta, idDia, usuario: S.session?.nombre || '', claveAdmin: auth.clave || '' });
      if (!r || r.ok === false) throw new Error((r && r.error) || 'no se pudo asignar');
      const d = r.data || r;
      if (d && d.nombre) { t.trabajador.nombre = d.nombre; _cjPintarTk(idVenta, { silent: true }); }
    } catch (e) {
      t.trabajador = previo;
      _cjPintarTk(idVenta, { shake: true });
      try { _finBeep?.('error'); } catch(_){}
      toast('No se pudo asignar: ' + (e.message || e), 'error', 6000);
    }
  }

  async function cjTrabajadorQuitar(idVenta) {
    const t = _cjBuscarTicket(idVenta); if (!t) return;
    const previo = t.trabajador || null;
    const auth = await pedirAuth({
      accion: 'DESASIGNAR_CREDITO_TRABAJADOR',
      refDocumento: t.correlativo || idVenta,
      contexto: 'Quitarle el consumo de S/ ' + _money(t.total).toFixed(2) + ' a ' + ((previo && previo.nombre) || '?')
    });
    if (!auth) return;

    t.trabajador = null;
    _cjPintarTk(idVenta);
    try { _finBeep?.('eliminar'); } catch(_){}
    toast('Quitado — el ticket vuelve a quedar sin dueño', 'ok', 2800);
    try {
      const r = await API.post('creditoDesasignar', { idVenta, claveAdmin: auth.clave || '' });
      if (!r || r.ok === false) throw new Error((r && r.error) || 'no se pudo quitar');
    } catch (e) {
      t.trabajador = previo;
      _cjPintarTk(idVenta, { shake: true });
      try { _finBeep?.('error'); } catch(_){}
      toast('No se pudo quitar: ' + (e.message || e), 'error', 6000);
    }
  }

  function cjTrabajadorCerrar() {
    const o = document.getElementById('cjTkOvl'); if (!o) return;
    o.classList.remove('in');
    setTimeout(() => { try { o.remove(); } catch(_){} }, 180);
  }

  function _cjInyectarCSSTrabajador() {
    if (document.getElementById('cjTkCSS')) return;
    const st = document.createElement('style'); st.id = 'cjTkCSS';
    st.textContent =
      // [851] La carta de la MESA es ÁMBAR con texto marrón, no oscura: el botón va sólido y
      // azul para que se lea de lejos (antes era celeste translúcido = invisible sobre ámbar).
      '.cj-carta-tk-btn{display:block;width:100%;margin-top:9px;padding:9px 10px;border-radius:10px;' +
        'border:0;background:linear-gradient(135deg,#3b82f6,#2563eb);color:#fff;font-size:11px;' +
        'font-weight:900;letter-spacing:.08em;text-transform:uppercase;cursor:pointer;' +
        'box-shadow:0 3px 0 #1e40af,0 7px 16px -5px rgba(30,64,175,.7);' +
        'transition:transform .12s,box-shadow .12s,filter .12s}' +
      '.cj-carta-tk-btn:hover{filter:brightness(1.1)}' +
      '.cj-carta-tk-btn:active{transform:translateY(2px);box-shadow:0 1px 0 #1e40af}' +
      // sello de asignado: arriba a la IZQUIERDA, con la ✕ encima del nombre
      '.cj-carta-tk-chip{position:absolute;top:7px;left:7px;z-index:7;display:inline-flex;align-items:center;' +
        'gap:4px;max-width:calc(100% - 74px);padding:3px 9px 3px 6px;border-radius:999px;' +
        'background:linear-gradient(135deg,#2563eb,#1d4ed8);color:#fff;font-size:9.5px;font-weight:900;' +
        'box-shadow:0 3px 10px rgba(30,64,175,.55)}' +
      '.cj-carta-tk-chip b{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;letter-spacing:.02em}' +
      '.cj-carta-tk-chip i{font-style:normal;opacity:.75;font-weight:700}' +
      '.cj-carta-tk-chip.is-desc{background:linear-gradient(135deg,#059669,#047857)}' +
      '.cj-carta-tk-ico{font-size:11px;line-height:1}' +
      '.cj-carta-tk-x{position:absolute;top:-8px;right:-7px;width:19px;height:19px;padding:0;border-radius:50%;' +
        'border:2px solid #fff;background:#ef4444;color:#fff;font-size:10px;font-weight:900;line-height:1;' +
        'cursor:pointer;display:grid;place-items:center;box-shadow:0 2px 7px rgba(0,0,0,.45);transition:.15s}' +
      '.cj-carta-tk-x:hover{background:#dc2626;transform:scale(1.18)}' +
      // asignada = MISMO celeste que un ticket enviado a cobrar a una caja
      '.cj-mesa-carta-tk{background:linear-gradient(135deg,#dbeafe,#bfdbfe)!important;' +
        'border-color:#3b82f6!important;color:#1e3a8a!important}' +
      '@keyframes tkPop{0%{transform:scale(.4);opacity:0}60%{transform:scale(1.15);opacity:1}100%{transform:scale(1)}}' +
      '.cj-carta-tk-chip.tk-pop{animation:tkPop .42s cubic-bezier(.34,1.56,.64,1)}' +
      '@keyframes tkShake{0%,100%{transform:translateX(0)}20%{transform:translateX(-7px)}' +
        '40%{transform:translateX(6px)}60%{transform:translateX(-4px)}80%{transform:translateX(3px)}}' +
      '.cj-mesa-carta.tk-shake{animation:tkShake .45s ease-in-out}' +
      '.cj-det-tk-btn{display:block;width:100%;margin-top:11px;padding:11px 12px;border-radius:12px;' +
        'border:1px dashed rgba(56,189,248,.45);background:rgba(56,189,248,.08);color:#7dd3fc;' +
        'font-size:12px;font-weight:800;cursor:pointer;transition:.15s}' +
      '.cj-det-tk-btn:hover{background:rgba(56,189,248,.18);color:#e0f2fe}' +
      '.cj-det-tk-nota{margin-top:11px;padding:10px 12px;border-radius:12px;border:1px dashed #33415a;' +
        'background:rgba(148,163,184,.06);color:#7488a6;font-size:11px;line-height:1.55;font-weight:600}' +
      '.cj-det-tk-quitar{margin-left:8px;font-size:10px;font-weight:800;color:#93a4c2;background:transparent;' +
        'border:1px solid #33415a;border-radius:7px;padding:2px 7px;cursor:pointer}' +
      '.cj-det-tk-quitar:hover{color:#f0a6a6;border-color:rgba(248,113,113,.5)}' +
      '.cjtk-back{position:fixed;inset:0;z-index:100095;display:flex;align-items:center;justify-content:center;' +
        'padding:16px;background:rgba(3,7,15,.7);backdrop-filter:blur(5px);-webkit-backdrop-filter:blur(5px);opacity:0;transition:opacity .2s}' +
      '.cjtk-back.in{opacity:1}' +
      '.cjtk-card{width:min(460px,100%);max-height:82vh;display:flex;flex-direction:column;' +
        'background:linear-gradient(180deg,#111d31,#0a1120);border:1px solid #26344c;border-radius:16px;' +
        'box-shadow:0 26px 70px rgba(0,0,0,.66);overflow:hidden;transform:translateY(14px) scale(.98);opacity:0;' +
        'transition:transform .25s cubic-bezier(.22,1,.36,1),opacity .2s}' +
      '.cjtk-back.in .cjtk-card{transform:none;opacity:1}' +
      '.cjtk-head{display:flex;align-items:center;justify-content:space-between;gap:10px;padding:13px 15px;' +
        'border-bottom:1px solid #1a2740;flex:none}' +
      '.cjtk-head b{display:block;font-size:14px;color:#e2e8f0}' +
      '.cjtk-head span{display:block;font-size:10.5px;color:#7488a6;margin-top:2px}' +
      '.cjtk-x{flex:none;width:38px;height:38px;border-radius:10px;border:1px solid #26344c;background:#0c1626;color:#8296b5;cursor:pointer}' +
      '.cjtk-body{flex:1;overflow:auto;padding:11px 13px;display:flex;flex-direction:column;gap:7px;-webkit-overflow-scrolling:touch}' +
      '.cjtk-load{font-size:12px;color:#7488a6;text-align:center;padding:18px 6px;line-height:1.6}' +
      '.cjtk-row{display:flex;align-items:center;gap:10px;width:100%;text-align:left;padding:9px 11px;border-radius:12px;' +
        'border:1px solid #223049;background:#0c1626;cursor:pointer;transition:.15s;min-height:52px}' +
      '.cjtk-row:hover{border-color:rgba(56,189,248,.5);background:#132238}' +
      '.cjtk-ini{flex:none;width:34px;height:34px;border-radius:50%;display:grid;place-items:center;font-weight:800;' +
        'font-size:14px;color:#04121f;background:linear-gradient(135deg,#7dd3fc,#22d3ee)}' +
      '.cjtk-txt{flex:1;min-width:0;display:flex;flex-direction:column}' +
      '.cjtk-txt b{font-size:12.5px;color:#e2e8f0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}' +
      '.cjtk-txt i{font-style:normal;font-size:10px;color:#7488a6;margin-top:1px}' +
      '.cjtk-ya{flex:none;font-size:10px;font-weight:800;color:#fcd34d;background:rgba(251,191,36,.12);' +
        'border:1px solid rgba(251,191,36,.32);border-radius:7px;padding:2px 6px}' +
      '@media(max-width:560px){.cjtk-back{padding:0;align-items:flex-end}' +
        '.cjtk-card{width:100%;max-height:88vh;border-radius:18px 18px 0 0}}';
    document.head.appendChild(st);
  }

  function cjAbrirDetalleCarta(idVentaOrIdx) {
    let t = null;
    // Compatibilidad: si recibe número, asume idx del ticketsActivos viejo
    if (typeof idVentaOrIdx === 'number') {
      t = _cjCreditosState.ticketsActivos[idVentaOrIdx];
    } else {
      const idV = String(idVentaOrIdx);
      for (const g of (_cjCreditosState.todosLosGrupos || [])) {
        const found = (g.tickets || []).find(x => String(x.idVenta) === idV);
        if (found) { t = found; break; }
      }
      // Fallback al array de la fecha activa
      if (!t) t = (_cjCreditosState.ticketsActivos || []).find(x => String(x.idVenta) === idV);
    }
    if (!t) return;
    _cjCreditosState.detalleTicket = t;
    try { _finBeep?.('click'); } catch(_){}

    const cont = $('cjDetalleContenido');
    if (cont) {
      // [v41] Listado completo de items del ticket
      const itemsHtml = (t.items && t.items.length)
        ? `<div class="cj-det-items">
             <div class="cj-det-items-titulo">🛒 Productos (${t.items.length})</div>
             ${t.items.map(it => {
                const nombre = _esc((it.nombre || '').substring(0, 38));
                const cant = parseFloat(it.cantidad) || 0;
                const sub = parseFloat(it.subtotal) || 0;
                return `<div class="cj-det-item-row">
                  <span class="cj-det-item-cant">${cant}×</span>
                  <span class="cj-det-item-nombre">${nombre}</span>
                  <span class="cj-det-item-sub">S/ ${sub.toFixed(2)}</span>
                </div>`;
             }).join('')}
           </div>`
        : '';
      cont.innerHTML = `
        <span class="cj-detalle-corner">🃏</span>
        <span class="cj-detalle-corner-br">🃏</span>
        <div class="cj-det-cliente">${_esc((t.cliente || 'VARIOS').toUpperCase())}</div>
        ${t.clienteDoc ? `<div class="cj-det-doc">${_esc(t.clienteDoc)}</div>` : ''}
        <div class="cj-det-monto">S/ ${parseFloat(t.total).toFixed(2)}</div>
        <div class="cj-det-row">
          <span class="cj-det-row-label">📄 Ticket</span>
          <span class="cj-det-row-val">${_esc(t.correlativo)}</span>
        </div>
        <div class="cj-det-row">
          <span class="cj-det-row-label">🕐 Emitido</span>
          <span class="cj-det-row-val">${_esc(t.fechaISO)}</span>
        </div>
        <div class="cj-det-row">
          <span class="cj-det-row-label">👤 Cajero original</span>
          <span class="cj-det-row-val">${_esc(t.vendedor)}</span>
        </div>
        <div class="cj-det-row">
          <span class="cj-det-row-label">💼 Caja origen</span>
          <span class="cj-det-row-val">${_esc(t.idCaja || '—')}</span>
        </div>
        ${itemsHtml}
        ${t.obs ? `<div class="cj-det-obs">📝 ${_esc(t.obs)}</div>` : ''}
        ${(t.estadoCobro && t.estadoCobro !== 'VIVO') ? `<div class="cj-det-asignado-banner" style="background:rgba(16,185,129,.14);border-color:rgba(16,185,129,.45);color:#6ee7b7">
          ✅ Saldado — ${t.estadoCobro === 'PLANILLA' ? '🧾 descuento en ' : '💼 cobrado por '}<strong>${_esc(t.cobradoDetalle || (t.estadoCobro === 'PLANILLA' ? 'Liquidación' : 'Caja'))}</strong>
        </div>` : ''}
        ${t.asignado ? `<div class="cj-det-asignado-banner">
          ✈ Ya asignado a <strong>${_esc(t.asignado.vendedorDest)}</strong>
          (${_esc(t.asignado.cajaDestino)}) — esperando confirmación
        </div>` : ''}
        ${_cjTrabajadorBloqueHTML(t)}
      `;
    }
    // El botón FAB se oculta si ya está asignado — o si el ticket ya fue saldado [610]
    const fab = $('cjDetalleFloating');
    if (fab) fab.style.display = (t.asignado || (t.estadoCobro && t.estadoCobro !== 'VIVO')) ? 'none' : '';
    const modal = $('modalDetalleCarta');
    if (modal) modal.classList.remove('hidden');
  }

  function cjCerrarDetalleCarta(ev) {
    if (ev && ev.target && ev.target.id !== 'modalDetalleCarta') return;
    const modal = $('modalDetalleCarta');
    if (modal) modal.classList.add('hidden');
    _cjCreditosState.detalleTicket = null;
  }

  // [v2.41.56] Panel INLINE de asignar caja — se despliega DENTRO del modal
  // detalle (no modal apilado que quedaba atrás). Animación slide-down con
  // sonidos, cards de cajas con glow, optimismo al confirmar.
  function cjAbrirAsignarDesdeDetalle() {
    const t = _cjCreditosState.detalleTicket;
    if (!t) return;
    cjAbrirAsignar(t.idVenta);
  }

  async function cjAbrirAsignar(idVenta) {
    // Buscar el ticket en el state — busca en TODOS los grupos (no solo activo)
    let ticket = null;
    for (const g of (_cjCreditosState.todosLosGrupos || [])) {
      ticket = (g.tickets || []).find(t => String(t.idVenta) === String(idVenta));
      if (ticket) break;
    }
    if (!ticket) { toast('Ticket no encontrado', 'error'); return; }
    if (ticket.asignado) { toast('Este ticket ya está asignado', 'warn'); return; }
    // [610] Un ticket saldado (caja o liquidación) no puede mandarse a cobrar.
    // El server también lo bloquea (asignar_cobro_cajero exige CREDITO/POR_COBRAR).
    if (ticket.estadoCobro && ticket.estadoCobro !== 'VIVO') {
      toast(`✅ Este ticket ya fue cobrado (${ticket.cobradoDetalle || (ticket.estadoCobro === 'PLANILLA' ? 'liquidación' : 'caja')})`, 'warn');
      return;
    }

    _cjCreditosState.asignarCtx = ticket;
    _cjCreditosState.asignarCaja = null;
    _cjCreditosState.asignarMetodo = ''; // [v2.41.90] ya no se usa

    // Sonido apertura panel
    try { _finBeep?.('expand') || _finBeep?.('click'); } catch(_){}

    // Ocultar el FAB mientras el panel está abierto
    const fab = $('cjDetalleFloating');
    if (fab) fab.style.display = 'none';

    // Insertar panel inline dentro del modal detalle si no existe
    let panel = $('cjAsignarInlinePanel');
    if (!panel) {
      const card = document.querySelector('#modalDetalleCarta .cj-detalle-card');
      if (!card) return;
      panel = document.createElement('div');
      panel.id = 'cjAsignarInlinePanel';
      panel.className = 'cj-asignar-inline';
      card.appendChild(panel);
    }
    panel.innerHTML = `
      <div class="cj-asignar-inline-head">
        <span style="font-size:22px">✈</span>
        <div>
          <div class="cj-asignar-inline-titulo">Enviar cobro a caja</div>
          <div class="cj-asignar-inline-sub">${_esc(ticket.cliente || 'VARIOS')} · S/ ${parseFloat(ticket.total).toFixed(2)}</div>
        </div>
        <button onclick="MOS.cjCerrarAsignar()" class="cj-asignar-inline-close" title="Cerrar">✕</button>
      </div>
      <div class="cj-asignar-inline-section">
        <label class="cj-asignar-inline-label">
          <span class="cj-asignar-inline-step">1</span>
          <span>¿A qué caja enviar?</span>
        </label>
        <div id="cjAsignarCajas" class="cj-asignar-inline-cajas">
          <div class="cj-asignar-inline-loading">
            <div class="cj-asignar-inline-spin"></div>
            <span>Buscando cajas abiertas…</span>
          </div>
        </div>
      </div>
      <!-- [v2.41.90] Paso 2: tiempo límite (antes había selector de método
           pero el cajero igual lo elige al cobrar — quitamos para evitar
           confusión cuando el admin marca VIRTUAL y el cajero deja EFECTIVO) -->
      <div class="cj-asignar-inline-section">
        <label class="cj-asignar-inline-label">
          <span class="cj-asignar-inline-step">2</span>
          <span>Tiempo límite para cobrar</span>
        </label>
        <div class="cj-asignar-inline-ttls">
          <button data-ttl="1" onclick="MOS.cjSetTTLAsignar(1)" class="cj-asignar-ttl-btn is-active">
            <span class="cj-asignar-ttl-num">1h</span>
            <span class="cj-asignar-ttl-lbl">por defecto</span>
          </button>
          <button data-ttl="2" onclick="MOS.cjSetTTLAsignar(2)" class="cj-asignar-ttl-btn">
            <span class="cj-asignar-ttl-num">2h</span>
            <span class="cj-asignar-ttl-lbl">relajado</span>
          </button>
          <button data-ttl="4" onclick="MOS.cjSetTTLAsignar(4)" class="cj-asignar-ttl-btn">
            <span class="cj-asignar-ttl-num">4h</span>
            <span class="cj-asignar-ttl-lbl">media jornada</span>
          </button>
          <button data-ttl="6" onclick="MOS.cjSetTTLAsignar(6)" class="cj-asignar-ttl-btn">
            <span class="cj-asignar-ttl-num">6h</span>
            <span class="cj-asignar-ttl-lbl">todo el turno</span>
          </button>
        </div>
      </div>
      <!-- [v2.41.87] Mensaje opcional al cajero (140 chars) -->
      <div class="cj-asignar-inline-section">
        <label class="cj-asignar-inline-label">
          <span class="cj-asignar-inline-step">3</span>
          <span>Mensaje al cajero (opcional)</span>
        </label>
        <input id="cjAsignarMensaje" type="text" maxlength="140" placeholder="ej: cliente paga exacto, recoge antes de las 4pm..."
               oninput="MOS._cjOnMensajeAsignar(this.value)"
               class="cj-asignar-inline-msg" />
      </div>
      <p class="cj-asignar-inline-hint">💡 El cajero recibirá <strong>push + impresión física del ticket</strong> y elige al cobrar si es efectivo · virtual · mixto. El monto entra como <strong>INGRESO ADICIONAL</strong> a su caja. <strong>Si no se cobra en el tiempo elegido, el ticket vuelve automáticamente a estado CRÉDITO.</strong></p>
      <div class="cj-asignar-inline-footer">
        <button onclick="MOS.cjCerrarAsignar()" class="cj-btn cj-btn-secondary">Cancelar</button>
        <button id="cjAsignarOkBtn" onclick="MOS.cjConfirmarAsignar()" class="cj-btn cj-btn-primary" disabled>
          ✈ Enviar a cajero
        </button>
      </div>`;

    // Trigger animación entrar (force reflow)
    panel.classList.remove('is-open');
    void panel.offsetWidth;
    panel.classList.add('is-open');

    // [v2.42.00] Render desde cache si está caliente (instant). Si no hay cache,
    // mostrar skeleton + fetch en background. Refrescar siempre en background
    // para detectar cajeros que abrieron caja mientras tanto.
    const cajasDiv = $('cjAsignarCajas');
    const _pintarCajas = (lista) => {
      if (!cajasDiv) return;
      const abiertas = Array.isArray(lista) ? lista : [];
      const abIds = new Set(abiertas.map(c => String(c.idCaja)));
      // [diseño] cajas del día CERRADAS → mostrarlas grises con badge (NO enviables). Fuente: S._cajasHoy
      // (fresco, con estado). Solo se PUEDE enviar a las abiertas — el resto es informativo (evita "mandar al aire").
      const cerradas = (S._cajasHoy || S._todasCajas || [])
        .filter(c => c && String(c.estado || '').toUpperCase() !== 'ABIERTA' && !abIds.has(String(c.idCaja)))
        .filter((c, i, arr) => arr.findIndex(x => String(x.idCaja) === String(c.idCaja)) === i);

      if (!abiertas.length && !cerradas.length) {
        cajasDiv.innerHTML = '<div class="cj-asignar-inline-empty">⚠ No hay cajas hoy.<br><span class="text-xs opacity-70">Pide a un cajero que abra caja primero.</span></div>';
        return;
      }
      let html = '';
      if (!abiertas.length) {
        html += '<div class="cj-asignar-inline-empty" style="margin-bottom:10px">⚠ No hay cajas <b>abiertas</b> ahora. Solo se puede enviar a una caja abierta.</div>';
      }
      abiertas.forEach((c, i) => {
        html += `
          <button class="cj-asignar-caja-btn is-abierta"
                  style="animation-delay:${i*60}ms"
                  onclick="MOS.cjSetCajaAsignar('${_esc(c.idCaja)}')"
                  data-caja="${_esc(c.idCaja)}">
            <div class="cj-asignar-caja-avatar">👤</div>
            <div class="cj-asignar-caja-info">
              <div class="cj-asignar-caja-vendedor" title="${_esc(c.vendedor)}">${_esc(c.vendedor)}</div>
              <div class="cj-asignar-caja-meta">
                <span class="cj-asignar-caja-estado est-abierta">🟢 Abierta</span>
                <span class="cj-asignar-caja-loc">${_esc(c.estacion || '')}${c.zona ? ' · ' + _esc(c.zona) : ''}</span>
              </div>
            </div>
            <div class="cj-asignar-caja-check">✓</div>
          </button>`;
      });
      cerradas.forEach((c, i) => {
        html += `
          <div class="cj-asignar-caja-btn is-cerrada"
               style="animation-delay:${(abiertas.length + i) * 60}ms"
               data-caja="${_esc(c.idCaja)}"
               title="Caja cerrada — no se puede enviar cobro">
            <div class="cj-asignar-caja-avatar">🔒</div>
            <div class="cj-asignar-caja-info">
              <div class="cj-asignar-caja-vendedor" title="${_esc(c.vendedor)}">${_esc(c.vendedor)}</div>
              <div class="cj-asignar-caja-meta">
                <span class="cj-asignar-caja-estado est-cerrada">⚫ Cerrada</span>
                <span class="cj-asignar-caja-loc">${_esc(c.estacion || c.zona || '')}</span>
              </div>
            </div>
          </div>`;
      });
      cajasDiv.innerHTML = html;
    };
    if (cajasDiv) {
      const cache = _cjCreditosState.cajasAbiertasCache || [];
      const fresca = (Date.now() - (_cjCreditosState.cajasAbiertasCacheTs || 0)) < 30000;
      if (cache.length && fresca) {
        _pintarCajas(cache);                            // instantáneo
        _cjPrecargarCajasAbiertas(true).then(_pintarCajas).catch(()=>{}); // refresco background
      } else {
        _cjPrecargarCajasAbiertas(true).then(_pintarCajas).catch(e => {
          if (cajasDiv) cajasDiv.innerHTML = '<div class="cj-asignar-inline-empty" style="color:#fca5a5">⚠ Error: ' + _esc(e.message || e) + '</div>';
        });
      }
    }
    // [v2.41.90] Removido cjSetMetodoAsignar — el método lo elige el cajero
    cjSetTTLAsignar(1); // [v2.41.86] Default 1h
    _cjCreditosState.asignarMensaje = ''; // [v2.41.87] limpiar mensaje
    const inpMsg = document.getElementById('cjAsignarMensaje');
    if (inpMsg) inpMsg.value = '';
    _cjUpdAsignarOkBtn();

    // [v2.41.88] Scroll dentro de la carta (ahora tiene overflow-y) hasta el
    // footer del panel — así el botón "Enviar a cajero" queda visible aunque
    // el ticket tenga muchísimos productos.
    setTimeout(() => {
      try {
        const card = document.querySelector('#modalDetalleCarta .cj-detalle-card');
        if (card) {
          card.scrollTo({ top: card.scrollHeight, behavior: 'smooth' });
        } else {
          panel.scrollIntoView({ behavior: 'smooth', block: 'end' });
        }
      } catch(_){}
    }, 150);
  }

  function cjCerrarAsignar(ev) {
    // Soporta clicks fuera (legacy del modal viejo) y close button
    if (ev && ev.target && ev.target.id === 'modalAsignarCobro') {
      const oldModal = $('modalAsignarCobro');
      if (oldModal) oldModal.classList.add('hidden');
    }
    const panel = $('cjAsignarInlinePanel');
    if (panel) {
      panel.classList.remove('is-open');
      panel.classList.add('is-closing');
      setTimeout(() => { try { panel.remove(); } catch(_){} }, 320);
    }
    const fab = $('cjDetalleFloating');
    const t = _cjCreditosState.detalleTicket;
    if (fab && t && !t.asignado) fab.style.display = '';
    _cjCreditosState.asignarCtx = null;
    try { _finBeep?.('collapse') || _finBeep?.('tap'); } catch(_){}
  }

  function cjSetMetodoAsignar(metodo) {
    _cjCreditosState.asignarMetodo = metodo;
    document.querySelectorAll('.cj-asignar-metodo-btn').forEach(b => {
      b.classList.toggle('is-active', b.dataset.metodo === metodo);
    });
    _cjUpdAsignarOkBtn();
  }

  function cjSetCajaAsignar(idCaja) {
    _cjCreditosState.asignarCaja = idCaja;
    document.querySelectorAll('.cj-asignar-caja-btn').forEach(b => {
      b.classList.toggle('is-active', b.dataset.caja === idCaja);
    });
    _cjUpdAsignarOkBtn();
    try { _finBeep?.('tap'); } catch(_){}
  }

  function _cjUpdAsignarOkBtn() {
    const btn = $('cjAsignarOkBtn');
    if (!btn) return;
    // [v2.41.90] Solo requiere caja destino — el método ya no se elige aquí
    btn.disabled = !_cjCreditosState.asignarCaja;
  }

  // [v2.41.86] Setea el TTL del cobro (1h default · 2h · 4h · 6h)
  function cjSetTTLAsignar(horas) {
    _cjCreditosState.asignarTTL = parseInt(horas, 10) || 1;
    document.querySelectorAll('.cj-asignar-ttl-btn').forEach(b => {
      b.classList.toggle('is-active', parseInt(b.dataset.ttl, 10) === _cjCreditosState.asignarTTL);
    });
    try { _finBeep?.('tap'); } catch(_){}
  }

  // [v2.41.87] Captura mensaje opcional al cajero
  function _cjOnMensajeAsignar(v) {
    _cjCreditosState.asignarMensaje = String(v || '').substring(0, 140);
  }

  // [v2.42.00] Asignación OPTIMISTA — cerrar modal + volar carta + pegar
  // postit fantasma en el cuadro del cajero INSTANTE. Llamada en background.
  // Si el backend rechaza: rollback (devolver carta a la mesa) + toast rojo.
  async function cjConfirmarAsignar() {
    const ctx = _cjCreditosState.asignarCtx;
    const cajaDest = _cjCreditosState.asignarCaja;
    if (!ctx || !cajaDest) return;
    const horasTTL = parseInt(_cjCreditosState.asignarTTL, 10) || 1;
    const mensajeAdmin = (_cjCreditosState.asignarMensaje || '').trim();
    // Snapshot para rollback
    const cajaInfo = (_cjCreditosState.cajasAbiertasCache || []).find(c => String(c.idCaja) === String(cajaDest)) || {};
    const cajeroNom = cajaInfo.vendedor || 'cajero';
    // 1. Cerrar panel + modal detalle inmediato
    try { _finBeep?.('success'); } catch(_){}
    toast('✈ Enviado a ' + cajeroNom + ` · vence en ${horasTTL}h`, 'success', 3500);
    cjCerrarAsignar();
    setTimeout(() => {
      const det = $('modalDetalleCarta');
      if (det) det.classList.add('hidden');
      _cjCreditosState.detalleTicket = null;
    }, 200);
    // 2. Volar carta de la mesa + agregar postit OPTIMISTA al manojo del cajero
    const cartaEl = document.querySelector('.cj-mesa-carta[onclick*="' + ctx.idVenta + '"]');
    const optimisticId = 'CB-OPT-' + Date.now();
    const optimisticCobro = {
      idCobro: optimisticId,
      idVenta: ctx.idVenta,
      cajaDestino: cajaDest,
      vendedorDest: cajeroNom,
      cliente: ctx.cliente || 'VARIOS',
      monto: ctx.total,
      correlativo: ctx.correlativo || '',
      metodoSug: '',
      horasTTL: horasTTL,
      mensajeAdmin: mensajeAdmin,
      reasignaciones: 0,
      fechaVencimiento: new Date(Date.now() + horasTTL * 3600000).toISOString(),
      _optimistic: true
    };
    _cjCreditosState.enVuelo = [optimisticCobro, ...(_cjCreditosState.enVuelo || [])];
    try { _cjPintarPostitsManojos({ optimisticId, cartaOrigen: cartaEl }); } catch(_){}
    // [fix optimista SIN flicker] Antes se re-renderizaba TODA la mesa (todos los tickets del año) →
    // parpadeo + lentitud. Ahora: marcar t.asignado (para el próximo render natural) + update DIRIGIDO
    // de SOLO la carta enviada (celeste "✈ Enviado a X" en su lugar, sin tocar el resto de la mesa).
    try {
      (_cjCreditosState.todosLosGrupos || []).forEach(g => (g.tickets || []).forEach(t => {
        if (String(t.idVenta) === String(ctx.idVenta)) t.asignado = { vendedorDest: cajeroNom, cajaDestino: cajaDest };
      }));
      if (cartaEl) {
        cartaEl.classList.add('is-asignada');
        if (!cartaEl.querySelector('.cj-carta-asignado-badge')) {
          const _b = document.createElement('span');
          _b.className = 'cj-carta-asignado-badge';
          _b.style.cssText = 'position:relative;top:0;right:0;margin-bottom:8px;display:inline-block;';
          _b.textContent = '✈ Enviado a ' + cajeroNom;
          cartaEl.insertBefore(_b, cartaEl.firstChild);
        }
      }
      _cjActualizarAvionMano();   // ✈ badge de la baraja flotante (cobros en vuelo)
    } catch(_){}
    // 3. Fire-and-forget al backend
    try {
      const r = await API.post('meAsignarCobroCajero', {
        idVenta:        ctx.idVenta,
        cajaDestino:    cajaDest,
        metodoSugerido: '',
        horasTTL:       horasTTL,
        mensajeAdmin:   mensajeAdmin,
        localId:        optimisticId   // idempotencia anti-retry (path directo Supabase)
      });
      const d = (r && r.data) ? r.data : (r || {});
      // [cutover cobro-ME] en el path directo el push lo dispara el front (fan-out a los
      // equipos del cajero, principal+companion). En GAS el push ya lo hace el backend.
      if (d && d.via === 'directo' && d.cajeroDestino && !d.idempotente) {
        try { API.enviarPushSB(d.pushTitulo, d.pushCuerpo, { soloUsuarios: [d.cajeroDestino], incluirCompanions: true }); } catch(_) {}
      }
      // Reemplazar el postit optimista por el real (matchear por idVenta)
      _cjCreditosState.enVuelo = (_cjCreditosState.enVuelo || []).filter(c => c.idCobro !== optimisticId);
      // Refrescar para traer el cobro real con su idCobro definitivo
      setTimeout(() => {
        _cjCargarCreditosPendientes();
        _cjCargarEnVuelo();
      }, 400);
    } catch(e) {
      // ROLLBACK: quitar postit optimista + restaurar carta en mesa + toast rojo
      _cjCreditosState.enVuelo = (_cjCreditosState.enVuelo || []).filter(c => c.idCobro !== optimisticId);
      try { _cjPintarPostitsManojos(); } catch(_){}
      try { _finBeep?.('error') || _finBeep?.('tap'); } catch(_){}
      toast('⚠ No se pudo asignar: ' + (e.message || e) + ' · refresca y reintenta', 'error', 6500);
      setTimeout(() => _cjCargarCreditosPendientes(), 300);
    }
  }

  // Helper de escape (existe en MOS? si no, fallback)
  function _esc(s) { return String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])); }

  // ── MODAL TICKETS (compartido cajas + finanzas-style) ─
  function cjVerTodosTickets(filtroInicial) {
    _finBeep('click');
    _cjState.tkCajaFiltro = '';
    _cjState.tkFiltro = (filtroInicial === 'ventas') ? 'ventas' : 'todos';
    _cjState.tkBuscar = '';
    const inp = $('cjTkBuscar'); if (inp) inp.value = '';
    // [rename] el título refleja la fecha real (no siempre "del día")
    const f = _cjFecha();
    const dLabel = (f === today()) ? 'de hoy'
      : ('del ' + new Date(f + 'T00:00:00').toLocaleDateString('es-PE', { day: '2-digit', month: 'long' }));
    _setText('cjModalTicketsTitulo', 'Tickets ' + dLabel);
    _setText('cjModalTicketsSubtitulo', f + ' · buscá por rango de fechas, tipo o vendedor');
    // [rango] arranca en el día activo (desde=hasta=f); el usuario puede abrir un rango
    _cjTkResetRango(f);
    openModal('cjModalTickets');
    _cjTkRenderFiltrosBtns();
    _cjTkRenderVendedoresBtns();
    _cjTkRender();
    _cjAsegurarDia(f).then(c => { if (c) { _cjTkRenderVendedoresBtns(); _cjTkRender(); } });   // por si el día no estaba cargado
  }
  // [rango] resetea el buscador al día 'f' (desde=hasta=f, sin rango activo)
  function _cjTkResetRango(f) {
    _cjState.tkDesde = f; _cjState.tkHasta = f; _cjState.tkRangoActivo = false; _cjState.tkDoc = ''; _cjState.tkZona = '';
    const dd = $('cjTkDesde'), dh = $('cjTkHasta'), inf = $('cjTkRangoInfo');
    if (dd) dd.value = f; if (dh) dh.value = f; if (inf) inf.textContent = '';
    _cjTkRangoLabelUpd();
  }
  function _cjTkHoyRango() { _finBeep('click'); _cjTkResetRango(_cjFecha()); _cjTkRenderFiltrosBtns(); _cjTkRenderVendedoresBtns(); _cjTkRender(); }
  // [rango] aplica el rango de fechas: si desde≠hasta (o fuera del día activo) jala tickets_rango
  async function _cjTkAplicarRango() {
    const dd = $('cjTkDesde'), dh = $('cjTkHasta'), inf = $('cjTkRangoInfo');
    let desde = (dd && dd.value) || _cjFecha();
    let hasta = (dh && dh.value) || _cjFecha();
    if (hasta < desde) { const t = desde; desde = hasta; hasta = t; if (dd) dd.value = desde; if (dh) dh.value = hasta; }
    _cjState.tkDesde = desde; _cjState.tkHasta = hasta;
    _cjTkRangoLabelUpd();
    if (desde === hasta) {
      // un solo día → usa el cache (lo aseguramos) sin traer rango
      _cjState.tkRangoActivo = false;
      if (inf) inf.textContent = '';
      _cjState.fecha = desde; _cjActualizarFechaUI();
      const c = await _cjAsegurarDia(desde);
      _cjTkRenderVendedoresBtns(); _cjTkRender();
      if (c) { _cjTkRenderVendedoresBtns(); _cjTkRender(); }
      return;
    }
    // rango real → tickets_rango
    if (inf) inf.textContent = '⏳ buscando…';
    _finBeep('nav');
    try {
      const r = await API.get('getTicketsRango', { desde, hasta });
      const tks = (r && r.todosTickets) || (r && r.data && r.data.todosTickets) || [];
      S._cjTkRangoData = tks;
      _cjState.tkRangoActivo = true;
      if (inf) inf.textContent = `${tks.length} en el rango`;
      _cjTkRenderFiltrosBtns(); _cjTkRenderVendedoresBtns(); _cjTkRender();
    } catch (e) {
      // [500x] sin try/catch el label quedaba atascado en "buscando…" para siempre ante error de red
      if (inf) inf.textContent = '⚠ error al buscar · reintenta';
      try { _finBeep('error'); } catch(_){}
    }
  }
  // [rango] mini-calendario de rango con MARCAS (días con tickets) — sabés qué rango elegir.
  const _cjRangoCal = { y: 0, m: 0, desde: '', hasta: '' };
  function _cjTkRangoLabelUpd() {
    const el = $('cjTkRangoLabel'); if (!el) return;
    const d = _cjState.tkDesde, h = _cjState.tkHasta;
    if (!d) { el.textContent = 'Hoy'; return; }
    if (d === h) { el.textContent = (d === today()) ? 'Hoy' : new Date(d + 'T00:00:00').toLocaleDateString('es-PE', { day: '2-digit', month: 'short' }); return; }
    const f = s => new Date(s + 'T00:00:00').toLocaleDateString('es-PE', { day: '2-digit', month: 'short' });
    el.textContent = `${f(d)} → ${f(h)}`;
  }
  function _cjRangoCalAbrir(btn) {
    const cal = $('cjTkRangoCal'); if (!cal) return;
    if (!cal.classList.contains('hidden')) { cal.classList.add('hidden'); return; }
    _cjRangoCal.desde = _cjState.tkDesde || _cjFecha();
    _cjRangoCal.hasta = _cjState.tkHasta || _cjRangoCal.desde;
    const base = new Date((_cjRangoCal.hasta || today()) + 'T00:00:00');
    _cjRangoCal.y = base.getFullYear(); _cjRangoCal.m = base.getMonth();
    _cjRangoCalRender();
    _cjRangoCalCargarMes(_cjRangoCal.y, _cjRangoCal.m);
    cal.classList.remove('hidden');
    _finBeep('click');
    setTimeout(() => {
      const closer = e => { if (!cal.contains(e.target) && e.target !== btn && !(btn && btn.contains(e.target))) { cal.classList.add('hidden'); document.removeEventListener('click', closer); } };
      document.addEventListener('click', closer);
    }, 60);
  }
  function _cjRangoCalNavMes(delta) {
    let { y, m } = _cjRangoCal; m += delta;
    if (m < 0) { m = 11; y--; } if (m > 11) { m = 0; y++; }
    _cjRangoCal.y = y; _cjRangoCal.m = m;
    _cjRangoCalRender(); _cjRangoCalCargarMes(y, m);
  }
  async function _cjRangoCalCargarMes(y, m) {
    const mes = y + '-' + String(m + 1).padStart(2, '0');
    if (!S._cjCalDias) S._cjCalDias = {};
    if (S._cjCalDias[mes]) { _cjRangoCalRender(); return; }
    try { const r = await API.get('getDiasConTickets', { mes }); S._cjCalDias[mes] = (r && r.dias) || (r && r.data && r.data.dias) || {}; _cjRangoCalRender(); } catch (_) {}
  }
  function _cjRangoCalRender() {
    const grid = $('cjRangoCalGrid'); const lbl = $('cjRangoCalMesAnio'); const hint = $('cjRangoCalHint');
    if (!grid) return;
    const { y, m, desde, hasta } = _cjRangoCal;
    const meses = ['Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio', 'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'];
    if (lbl) lbl.textContent = `${meses[m]} ${y}`;
    const mesKey = `${y}-${String(m + 1).padStart(2, '0')}`;
    const diasT = (S._cjCalDias && S._cjCalDias[mesKey]) || {};
    const primero = new Date(y, m, 1); let dow = primero.getDay(); dow = dow === 0 ? 6 : dow - 1;
    const ultimo = new Date(y, m + 1, 0).getDate();
    const hoy = today();
    let html = '';
    for (let i = 0; i < dow; i++) html += '<button class="log-cal-day empty"></button>';
    for (let dia = 1; dia <= ultimo; dia++) {
      const f = `${y}-${String(m + 1).padStart(2, '0')}-${String(dia).padStart(2, '0')}`;
      const cls = ['log-cal-day'];
      if (f === hoy) cls.push('today');
      if (desde && hasta && f > desde && f < hasta) cls.push('cj-rango-in');
      if (f === desde) cls.push('cj-rango-ini');
      if (hasta && f === hasta) cls.push('cj-rango-fin');
      const info = diasT[f]; let dot = '';
      if (info && info.n > 0) { cls.push('cj-cal-tick'); if (info.credito) { cls.push('cj-cal-cred'); dot = '<span class="cj-cal-dot"></span>'; } }
      const ttl = info && info.n ? ` title="${info.n} tk${info.credito ? ' · crédito' : ''}"` : '';
      html += `<button class="${cls.join(' ')}"${ttl} onclick="MOS._cjRangoCalPick('${f}')">${dia}${dot}</button>`;
    }
    grid.innerHTML = html;
    if (hint) hint.textContent = (desde && !hasta) ? '📍 ahora el día final…' : (desde && hasta ? `${desde} → ${hasta}` : 'Toca el día de inicio…');
  }
  function _cjRangoCalPick(f) {
    _finBeep('nav');
    if (!_cjRangoCal.desde || _cjRangoCal.hasta) { _cjRangoCal.desde = f; _cjRangoCal.hasta = ''; _cjRangoCalRender(); return; }
    if (f < _cjRangoCal.desde) { _cjRangoCal.desde = f; _cjRangoCalRender(); return; }
    _cjRangoCal.hasta = f;
    _cjRangoCalRender();
    const dd = $('cjTkDesde'), dh = $('cjTkHasta');
    if (dd) dd.value = _cjRangoCal.desde; if (dh) dh.value = _cjRangoCal.hasta;
    setTimeout(() => { $('cjTkRangoCal')?.classList.add('hidden'); }, 220);
    _cjTkAplicarRango();
  }

  function cjVerTicketsCaja(idCaja) {
    _finBeep('click');
    const c = (S._todasCajas || []).find(x => String(x.idCaja) === String(idCaja));
    _cjState.tkCajaFiltro = String(idCaja);
    _cjState.tkFiltro = 'todos';
    _cjState.tkBuscar = '';
    const inp = $('cjTkBuscar'); if (inp) inp.value = '';
    _setText('cjModalTicketsTitulo', 'Tickets de Caja · ' + (c?.vendedor || '—'));
    _setText('cjModalTicketsSubtitulo', (c?.zona || c?.estacion || '') + ' · ' + (c?.idCaja || ''));
    _cjState.tkVendedor = '';   // [v2.43.387] reset del filtro de vendedor al abrir otra caja
    _cjTkResetRango(_cjFecha());
    openModal('cjModalTickets');
    _cjTkRenderFiltrosBtns();
    _cjTkRenderVendedoresBtns();
    _cjTkRender();
  }

  // ══════════════════════════════════════════════════════════════════════════════════════════════
  // [798] OVERLAY "💸 EXTRAS" DE LA CAJA — agregar / editar / eliminar movimientos extra con PIN admin.
  //
  // POR QUÉ EXISTE: el 15-ago una cajera registró dos egresos con concepto "Cierre de caja"
  // (Yape S/1964.40 + Efectivo S/1640.00). El cierre YA descuenta lo entregado, así que esos extras
  // duplicaron la salida: el arqueo quedó en −1925.60 cuando debía ser +1678.80, y desde MOS no había
  // forma de corregirlo. Acá el dueño ve TODOS los extras de la caja y los repara.
  //
  // BACKEND: RPCs me.extras_de_caja / me.extra_crear / me.extra_editar / me.extra_eliminar (SQL 798).
  // Toda escritura pasa ANTES por pedirAuth (EXTRA_CREAR/EXTRA_EDITAR tier 2 · EXTRA_ELIMINAR tier 3)
  // y manda su `claveAdmin`, que la RPC RE-VERIFICA en el servidor (mos.reverificar_clave_admin).
  // La auditoría queda en DOS lados: mos.auditoria_admin (quién autorizó qué) y el historial_cambios
  // del propio movimiento (📜 por fila). Eliminar es DELETE real + snapshot íntegro en auditoria_admin
  // (la tabla no tiene columna de anulado y 13 funciones la suman — ver cabecera del SQL 798).
  //
  // UX: optimista con reversión — se pinta el cambio al toque y si el servidor rechaza se restaura la
  // lista anterior con un toast. Cero prompt/confirm/alert (formulario propio + _modalConfirm).
  // ══════════════════════════════════════════════════════════════════════════════════════════════
  const _cjExState = { idCaja: '', caja: null, data: null, modo: 'crear', idExtra: '', busy: false };
  const _cjExTipoOk = ['INGRESO', 'EGRESO', 'INGRESO_VIRTUAL', 'EGRESO_VIRTUAL'];
  const _cjExEsIngreso = t => String(t || '').toUpperCase().startsWith('INGRESO');
  const _cjExEsVirtual = t => String(t || '').toUpperCase().endsWith('_VIRTUAL');
  const _cjExS = v => 'S/ ' + _money(v).toFixed(2);   // dinero SIEMPRE por _money()
  // ⚠ la trampa que motivó todo: un extra cuyo concepto/obs habla del "cierre" casi siempre está
  // duplicando lo que el cierre YA descuenta. Se pinta con aviso para que salte a la vista.
  const _cjExSospechoso = ex => /cierre/i.test(String(ex.concepto || '') + ' ' + String(ex.obs || ''));

  async function cjVerExtrasCaja(idCaja) {
    _finBeep('click');
    const c = (S._todasCajas || []).find(x => String(x.idCaja) === String(idCaja));
    _cjExState.idCaja = String(idCaja || '');
    _cjExState.caja   = c || null;
    _cjExState.data   = null;
    _setText('cjModalExtrasTitulo', 'Extras de Caja · ' + ((c && c.vendedor) || '—'));
    _setText('cjModalExtrasSubtitulo', ((c && (c.zona || c.estacion)) || '') + ' · ' + _cjExState.idCaja);
    const list = $('cjExList');
    if (list) list.innerHTML = '<div class="px-4 py-10 text-center text-slate-500 text-sm italic">Cargando movimientos…</div>';
    const tot = $('cjExTotales'); if (tot) tot.innerHTML = '';
    openModal('cjModalExtras');
    await _cjExCargar();
  }

  async function _cjExCargar() {
    const pedida = _cjExState.idCaja;   // anti-race: si el dueño abrió otra caja mientras cargaba, se descarta
    try {
      const r = await API.extrasDeCaja(pedida);
      if (pedida !== _cjExState.idCaja) return;
      _cjExState.data = r || { items: [] };
      _cjExRender();
    } catch (e) {
      if (pedida !== _cjExState.idCaja) return;
      const list = $('cjExList');
      if (list) list.innerHTML = `<div class="px-4 py-10 text-center text-rose-400 text-sm">⚠ ${_esc(e.message || e)}</div>`;
    }
  }

  // Recalcula los totales en el cliente (tras un cambio optimista los del servidor quedan viejos).
  function _cjExTotalesLocales(items) {
    const sum = f => _money((items || []).reduce((s, x) => s + (f(x) ? (parseFloat(x.monto) || 0) : 0), 0));
    const ti  = sum(x => x.tipo === 'INGRESO'), te  = sum(x => x.tipo === 'EGRESO');
    const tiv = sum(x => x.tipo === 'INGRESO_VIRTUAL'), tev = sum(x => x.tipo === 'EGRESO_VIRTUAL');
    return { ti, te, tiv, tev, netoEf: _money(ti - te), netoVi: _money(tiv - tev) };
  }

  function _cjExRender() {
    const items = (_cjExState.data && Array.isArray(_cjExState.data.items)) ? _cjExState.data.items : [];
    const t = _cjExTotalesLocales(items);

    const tot = $('cjExTotales');
    if (tot) {
      const chip = (lbl, val, color) => `
        <div style="flex:1;min-width:70px;text-align:center;padding:6px 4px;border-radius:9px;background:#070f1a;border:1px solid #1e293b">
          <div style="font-size:9px;font-weight:800;color:#64748b;letter-spacing:.4px">${lbl}</div>
          <div style="font-size:13px;font-weight:900;color:${color}">${_cjExS(val)}</div>
        </div>`;
      tot.innerHTML = `
        <div style="display:flex;gap:6px;flex-wrap:wrap">
          ${chip('INGRESOS 💵', t.ti, '#34d399')}
          ${chip('EGRESOS 💵', t.te, '#f87171')}
          ${chip('NETO EFECTIVO', t.netoEf, t.netoEf >= 0 ? '#34d399' : '#f87171')}
          ${chip('NETO VIRTUAL 📱', t.netoVi, t.netoVi >= 0 ? '#22d3ee' : '#f87171')}
        </div>
        <div style="margin-top:5px;font-size:10px;color:#64748b;text-align:center">${items.length} movimiento${items.length === 1 ? '' : 's'} · el signo lo da el tipo, el monto siempre es positivo</div>`;
    }

    const list = $('cjExList');
    if (!list) return;
    if (!items.length) {
      list.innerHTML = '<div class="px-4 py-10 text-center text-slate-500 text-sm italic">Esta caja no tiene movimientos extra</div>';
      return;
    }
    list.innerHTML = items.map(ex => {
      const id   = String(ex.idExtra || '');
      const idJs = id.replace(/'/g, '&#39;');
      const ing  = _cjExEsIngreso(ex.tipo);
      const vir  = _cjExEsVirtual(ex.tipo);
      const col  = ing ? '#34d399' : '#f87171';
      const hora = String(ex.ts || '').substring(11, 16) || '—';
      const sosp = _cjExSospechoso(ex);
      const chips = [
        vir ? '<span style="font-size:9px;font-weight:800;padding:1px 5px;border-radius:6px;background:#164e63;color:#67e8f9">📱 VIRTUAL</span>' : '',
        ex.editado ? '<span style="font-size:9px;font-weight:800;padding:1px 5px;border-radius:6px;background:#78350f;color:#fcd34d">✎ EDITADO</span>' : '',
        ex.creadoEnMos ? '<span style="font-size:9px;font-weight:800;padding:1px 5px;border-radius:6px;background:#312e81;color:#a5b4fc">MOS</span>' : ''
      ].filter(Boolean).join(' ');
      return `
      <div data-idextra="${_esc(id)}" style="display:flex;align-items:flex-start;gap:9px;padding:10px 14px;border-bottom:1px solid rgba(30,41,59,.55)">
        <div style="font-size:15px;font-weight:900;color:${col};line-height:1.2">${ing ? '▲' : '▼'}</div>
        <div style="flex:1;min-width:0">
          <div style="display:flex;align-items:center;gap:5px;flex-wrap:wrap">
            <span style="font-size:12px;font-weight:800;color:#e2e8f0">${_esc(ex.concepto || ex.tipo || '—')}</span>
            ${chips}
          </div>
          <div style="font-size:10px;color:#64748b;margin-top:2px">🕒 ${_esc(hora)} · ${_esc(ex.registradoPor || '—')}</div>
          ${ex.obs ? `<div style="font-size:10px;color:#94a3b8;margin-top:2px">📝 ${_esc(ex.obs)}</div>` : ''}
          ${sosp ? `<div style="font-size:10px;font-weight:700;color:#fcd34d;margin-top:3px;background:rgba(120,53,15,.35);border:1px solid #78350f;border-radius:7px;padding:4px 6px">⚠ el cierre ya descuenta lo entregado; esto puede estar duplicando</div>` : ''}
        </div>
        <div style="text-align:right;flex-shrink:0">
          <div style="font-size:13px;font-weight:900;color:${col};white-space:nowrap">${ing ? '+' : '−'}${_cjExS(ex.monto)}</div>
          <div style="display:flex;gap:3px;justify-content:flex-end;margin-top:4px">
            <button onclick="MOS.cjExEditar('${idJs}')" title="Editar este movimiento" style="border:1px solid #334155;background:#0f172a;color:#cbd5e1;border-radius:7px;padding:2px 6px;font-size:11px;cursor:pointer">✎</button>
            <button onclick="MOS.cjExEliminar('${idJs}')" title="Eliminar este movimiento" style="border:1px solid #7f1d1d;background:#1a0b0b;color:#fca5a5;border-radius:7px;padding:2px 6px;font-size:11px;cursor:pointer">🗑</button>
            <button onclick="MOS.cjHistorialExtra('${idJs}')" title="Ver historial de cambios" style="border:1px solid #334155;background:#0f172a;color:#cbd5e1;border-radius:7px;padding:2px 6px;font-size:11px;cursor:pointer">📜</button>
          </div>
        </div>
      </div>`;
    }).join('');
  }

  // ── Formulario (crear / editar) ───────────────────────────────────────────────────────────────
  function cjExNuevo() {
    if (!_cjExState.idCaja) return;
    _finBeep('click');
    _cjExState.modo = 'crear';
    _cjExState.idExtra = '';
    _setText('cjExFormTitulo', 'Nuevo movimiento extra');
    _setText('cjExFormSub', ((_cjExState.caja && _cjExState.caja.vendedor) || '—') + ' · ' + _cjExState.idCaja);
    _cjExFormSet({ tipo: 'EGRESO', monto: '', concepto: '', obs: '', motivo: '' });
    openModal('cjModalExtraForm');
    setTimeout(() => { const el = $('cjExFormMonto'); if (el) el.focus(); }, 90);
  }

  function cjExEditar(idExtra) {
    const items = (_cjExState.data && _cjExState.data.items) || [];
    const ex = items.find(x => String(x.idExtra) === String(idExtra));
    if (!ex) { toast('Movimiento no encontrado — recarga el listado', 'warning'); return; }
    _finBeep('click');
    _cjExState.modo = 'editar';
    _cjExState.idExtra = String(idExtra);
    _setText('cjExFormTitulo', 'Editar movimiento extra');
    _setText('cjExFormSub', String(ex.ts || '').replace('T', ' ') + ' · ' + (ex.registradoPor || '—'));
    _cjExFormSet({ tipo: ex.tipo, monto: _money(ex.monto).toFixed(2), concepto: ex.concepto || '', obs: ex.obs || '', motivo: '' });
    openModal('cjModalExtraForm');
    setTimeout(() => { const el = $('cjExFormMonto'); if (el) el.focus(); }, 90);
  }

  function _cjExFormSet(v) {
    const tipo = $('cjExFormTipo'); if (tipo) tipo.value = _cjExTipoOk.indexOf(String(v.tipo || '').toUpperCase()) >= 0 ? String(v.tipo).toUpperCase() : 'EGRESO';
    const mon  = $('cjExFormMonto'); if (mon) mon.value = v.monto || '';
    const con  = $('cjExFormConcepto'); if (con) con.value = v.concepto || '';
    const obs  = $('cjExFormObs'); if (obs) obs.value = v.obs || '';
    const mot  = $('cjExFormMotivo'); if (mot) mot.value = v.motivo || '';
    _cjExFormMsg('');
    _cjExFormPreview();
  }

  function _cjExFormMsg(txt) {
    const el = $('cjExFormMsg');
    if (!el) return;
    el.textContent = txt || '';
    el.classList.toggle('hidden', !txt);
  }

  // Vista previa del efecto en la caja (así el dueño ve el signo ANTES de guardar).
  function _cjExFormPreview() {
    const el = $('cjExFormPreview');
    if (!el) return;
    const tipo = ($('cjExFormTipo') || {}).value || 'EGRESO';
    const monto = _money(($('cjExFormMonto') || {}).value);
    const conc = String((($('cjExFormConcepto') || {}).value) || '').trim();
    const ing = _cjExEsIngreso(tipo), vir = _cjExEsVirtual(tipo);
    if (!(monto > 0)) { el.style.color = '#64748b'; el.textContent = 'Ingresa un monto mayor a 0'; return; }
    el.style.color = ing ? '#34d399' : '#f87171';
    el.textContent = `${ing ? '▲ suma' : '▼ resta'} ${_cjExS(monto)} ${vir ? 'al saldo VIRTUAL' : 'al efectivo de la caja'}${conc ? ' · ' + conc : ''}`;
    if (/cierre/i.test(conc)) {
      el.style.color = '#fcd34d';
      el.textContent += ' ⚠ el cierre ya descuenta lo entregado';
    }
  }

  function cjExFormCerrar() {
    closeModal('cjModalExtraForm');
    _cjExFormMsg('');
  }

  async function cjExFormGuardar() {
    if (_cjExState.busy) return;
    const esCrear = _cjExState.modo === 'crear';
    const tipo  = String((($('cjExFormTipo') || {}).value) || 'EGRESO').toUpperCase();
    const monto = _money(($('cjExFormMonto') || {}).value);
    const conc  = String((($('cjExFormConcepto') || {}).value) || '').trim();
    const obs   = String((($('cjExFormObs') || {}).value) || '').trim();
    const mot   = String((($('cjExFormMotivo') || {}).value) || '').trim();
    if (_cjExTipoOk.indexOf(tipo) < 0) { _cjExFormMsg('Tipo inválido'); return; }
    if (!(monto > 0)) { _cjExFormMsg('El monto debe ser mayor a 0 (el signo lo da el tipo)'); _finBeep('error'); return; }
    if (!conc) { _cjExFormMsg('Escribe un concepto (queda en el arqueo y en el ticket de turno)'); _finBeep('error'); return; }

    // AUTORIZACIÓN ANTES DE ESCRIBIR (el patrón vivo de la casa: pedirAuth → claveAdmin → RPC).
    const auth = await pedirAuth({
      accion: esCrear ? 'EXTRA_CREAR' : 'EXTRA_EDITAR',
      refDocumento: esCrear ? _cjExState.idCaja : _cjExState.idExtra,
      contexto: (esCrear ? 'Crear' : 'Editar') + ` movimiento extra · ${tipo} ${_cjExS(monto)} · ${conc}`
    });
    if (!auth) return;

    const items = (_cjExState.data && _cjExState.data.items) || [];
    const snapshot = items.slice();          // para revertir si el servidor rechaza
    _cjExState.busy = true;
    const btn = $('cjExFormGuardar');
    if (btn) { btn.disabled = true; btn.textContent = '⏳ Guardando…'; }

    // id generado en el cliente → el reintento NO duplica (la RPC es idempotente por id_extra).
    const idNuevo = esCrear
      ? 'EX-' + Date.now() + '-' + Math.random().toString(36).substring(2, 8)
      : _cjExState.idExtra;

    // Optimismo: pintar YA el cambio en la lista del overlay.
    const nuevos = esCrear
      ? items.concat([{ idExtra: idNuevo, ts: '', tipo, monto, concepto: conc, obs,
                        registradoPor: auth.nombre || 'MOS-admin', editado: false, creadoEnMos: true }])
      : items.map(x => String(x.idExtra) === String(idNuevo)
          ? Object.assign({}, x, { tipo, monto, concepto: conc, obs, editado: true }) : x);
    _cjExState.data = Object.assign({}, _cjExState.data || {}, { items: nuevos });
    _cjExRender();
    cjExFormCerrar();

    try {
      const payload = {
        idExtra: idNuevo, tipo, monto, concepto: conc, obs,
        usuario: auth.nombre || 'MOS-admin', rol: auth.rol || '',
        motivo: mot, claveAdmin: auth.clave || '', app: 'MOS'
      };
      if (esCrear) payload.idCaja = _cjExState.idCaja;
      const r = esCrear ? await API.extraCrear(payload) : await API.extraEditar(payload);
      _finBeep(esCrear ? 'agregar' : 'ok');
      toast(esCrear
        ? `✓ Extra agregado · ${tipo} ${_cjExS(monto)}`
        : (r && r.noop ? 'Sin cambios que guardar' : `✓ Movimiento actualizado · ${_cjExS(monto)}`), 'success');
      await _cjExCargar();                 // la verdad viene del servidor (ts, editado, totales)
      _cajasRefreshSilencioso();           // el badge 💸 y el arqueo de la card se re-pintan
    } catch (e) {
      _cjExState.data = Object.assign({}, _cjExState.data || {}, { items: snapshot });
      _cjExRender();
      _finBeep('error');
      toast('⚠ No se guardó: ' + (e.message || e), 'error', 6000);
    } finally {
      _cjExState.busy = false;
      if (btn) { btn.disabled = false; btn.textContent = '🔐 Guardar con PIN'; }
    }
  }

  async function cjExEliminar(idExtra) {
    if (_cjExState.busy) return;
    const items = (_cjExState.data && _cjExState.data.items) || [];
    const ex = items.find(x => String(x.idExtra) === String(idExtra));
    if (!ex) { toast('Movimiento no encontrado — recarga el listado', 'warning'); return; }
    const ing = _cjExEsIngreso(ex.tipo);
    const detalle = [
      `${ing ? '▲ INGRESO' : '▼ EGRESO'}${_cjExEsVirtual(ex.tipo) ? ' VIRTUAL' : ''} · ${_cjExS(ex.monto)}`,
      `Concepto: ${ex.concepto || '—'}`,
      `Registrado por: ${ex.registradoPor || '—'}${ex.ts ? ' · ' + String(ex.ts).replace('T', ' ') : ''}`,
      '',
      'Se elimina de la caja y el arqueo se recalcula sin él.',
      'Queda copia completa en la auditoría (quién, cuándo y por qué).'
    ].join('\n');
    const ok = await _modalConfirm(detalle, { danger: true, titulo: '🗑 Eliminar movimiento extra', okText: 'Sí, eliminar' });
    if (!ok) return;

    const auth = await pedirAuth({
      accion: 'EXTRA_ELIMINAR',
      refDocumento: String(idExtra),
      contexto: `Eliminar extra ${ex.tipo} ${_cjExS(ex.monto)} · ${ex.concepto || '—'} (caja ${_cjExState.idCaja})`
    });
    if (!auth) return;

    const snapshot = items.slice();
    _cjExState.busy = true;
    _cjExState.data = Object.assign({}, _cjExState.data || {}, {
      items: items.filter(x => String(x.idExtra) !== String(idExtra))
    });
    _cjExRender();
    try {
      await API.extraEliminar({
        idExtra: String(idExtra),
        usuario: auth.nombre || 'MOS-admin', rol: auth.rol || '',
        motivo: 'Eliminado desde MOS · ' + (ex.concepto || ''),
        claveAdmin: auth.clave || '', app: 'MOS'
      });
      _finBeep('eliminar');
      toast(`✓ Movimiento eliminado · ${_cjExS(ex.monto)}`, 'success');
      await _cjExCargar();
      _cajasRefreshSilencioso();
    } catch (e) {
      _cjExState.data = Object.assign({}, _cjExState.data || {}, { items: snapshot });
      _cjExRender();
      _finBeep('error');
      toast('⚠ No se eliminó: ' + (e.message || e), 'error', 6000);
    } finally {
      _cjExState.busy = false;
    }
  }

  function _cjTkRenderFiltrosBtns() {
    const wrap = $('cjTkFiltros');
    if (!wrap) return;
    const filtros = [
      { key: 'todos',      label: 'Todos' },
      { key: 'ventas',     label: '💰 Cobrado' },
      { key: 'efectivo',   label: '💵 Efectivo' },
      { key: 'virtual',    label: '📱 Virtual' },
      { key: 'mixto',      label: '🔀 Mixto' },
      { key: 'verif',      label: '✅ Verificado' },      // [877] virtual/mixto con su Yape
      { key: 'sinverif',   label: '◌ Sin verificar' },   // [877] virtual/mixto sin Yape
      { key: 'por_cobrar', label: '⏳ Por cobrar' },
      { key: 'credito',    label: '📋 Crédito' },
      { key: 'anulado',    label: '❌ Anulado' },
    ];
    let html = filtros.map(f => {
      const active = f.key === _cjState.tkFiltro;
      const cls = active ? 'log-icon-btn active' : 'log-icon-btn';
      return `<button onclick="MOS._cjTkSetFiltro('${f.key}')" class="${cls}" style="padding:5px 10px;font-size:11px;width:auto;height:auto">${f.label}</button>`;
    }).join('');
    // [tipo doc] chips NV / Boleta / Factura (eje independiente del método → se combinan)
    const docs = [{ k: 'NV', l: '📄 NV' }, { k: 'B', l: '🧾 Boleta' }, { k: 'F', l: '📑 Factura' }];
    html += '<span style="width:1px;height:18px;background:#1e293b;margin:0 4px;display:inline-block"></span>';
    html += docs.map(d => {
      const active = _cjState.tkDoc === d.k;
      return `<button onclick="MOS._cjTkSetDoc('${d.k}')" class="log-icon-btn ${active ? 'active' : ''}" style="padding:5px 10px;font-size:11px;width:auto;height:auto">${d.l}</button>`;
    }).join('');
    wrap.innerHTML = html;
  }
  function _cjTkSetFiltro(key) {
    _cjState.tkFiltro = key;
    _finBeep('click');
    _cjTkRenderFiltrosBtns();
    _cjTkRender();
  }

  // [v2.43.387] Chips por VENDEDOR — saber quién emitió cada ticket dentro de la caja
  // (una caja puede tener varios: p.ej. Sergio + Fernando). Se combina con el filtro de
  // método y la búsqueda; la suma viva (cjTkConteo) refleja la intersección. Si la caja
  // tiene un solo vendedor, la fila se oculta (no aporta).
  function _cjTkVendNombre(t) { return (String(t.vendedor || '').trim() || '—'); }
  function _cjTkRenderVendedoresBtns() {
    const wrap = $('cjTkVendedores');
    if (!wrap) return;
    let base = _cjTkFuente();   // [rango] respeta rango/día activo + caja + tipo doc
    const esAnul = t => String(t.metodo || t.formaPago || '').toUpperCase() === 'ANULADO' || t.estado === 'ANULADO';
    const map = new Map();
    base.forEach(t => {
      const v = _cjTkVendNombre(t);
      if (!map.has(v)) map.set(v, { n: 0, tot: 0 });
      const e = map.get(v); e.n++; if (!esAnul(t)) e.tot += parseFloat(t.total) || 0;
    });
    if (map.size <= 1) { wrap.classList.add('hidden'); _cjState.tkVendedor = ''; wrap.innerHTML = ''; _cjTkRenderZonasBtns(); return; }
    wrap.classList.remove('hidden');
    const vends = Array.from(map.entries()).sort((a, b) => b[1].tot - a[1].tot);
    const ini = n => (n && n !== '—' ? n.trim()[0].toUpperCase() : '?');
    const col = n => { let h = 0; for (let i = 0; i < n.length; i++) h = (h * 31 + n.charCodeAt(i)) & 0xffff; return `hsl(${h % 360},55%,45%)`; };
    const chip = (key, label, color, sub, active, icon) =>
      `<button onclick="MOS._cjTkSetVendedor(this.dataset.v)" data-v="${_escapeHtml(String(key))}" class="log-icon-btn ${active ? 'active' : ''}" style="padding:4px 9px 4px 4px;font-size:11px;width:auto;height:auto;display:inline-flex;align-items:center;gap:6px">
         <span style="width:20px;height:20px;border-radius:50%;background:${color};color:#fff;display:inline-flex;align-items:center;justify-content:center;font-size:10px;font-weight:700;flex-shrink:0">${icon}</span>
         <span>${_escapeHtml(label)}${sub ? ` <span style="opacity:.55">${sub}</span>` : ''}</span>
       </button>`;
    let html = chip('', 'Todos', '#475569', '', !_cjState.tkVendedor, '👥');
    html += vends.map(([v, e]) => chip(v, v, col(v), `S/${e.tot.toFixed(0)}`, _cjState.tkVendedor === v, ini(v))).join('');
    wrap.innerHTML = html;
    _cjTkRenderZonasBtns();   // [zona] siempre refrescar los chips de zona junto con vendedores
  }
  function _cjTkSetVendedor(v) {
    _cjState.tkVendedor = (_cjState.tkVendedor === v) ? '' : v;   // toggle → re-click deselecciona
    _finBeep('click');
    _cjTkRenderVendedoresBtns();
    _cjTkRender();
  }

  // [zona] chips por ZONA emisora — combinable con método/vendedor/tipo/búsqueda
  function _cjTkZonaNombre(t) { return (String(t.zona || '').trim() || '—'); }
  function _cjTkRenderZonasBtns() {
    const wrap = $('cjTkZonas');
    if (!wrap) return;
    let base = _cjTkFuente();   // respeta rango/día + caja + tipo doc
    const esAnul = t => String(t.metodo || t.formaPago || '').toUpperCase() === 'ANULADO' || t.estado === 'ANULADO';
    const map = new Map();
    base.forEach(t => {
      const z = _cjTkZonaNombre(t);
      if (!map.has(z)) map.set(z, { n: 0, tot: 0 });
      const e = map.get(z); e.n++; if (!esAnul(t)) e.tot += parseFloat(t.total) || 0;
    });
    // solo mostrar si hay ≥2 zonas reales (—, es decir sin zona, cuenta como una)
    if (map.size <= 1) { wrap.classList.add('hidden'); _cjState.tkZona = ''; wrap.innerHTML = ''; return; }
    wrap.classList.remove('hidden');
    const zonas = Array.from(map.entries()).sort((a, b) => b[1].tot - a[1].tot);
    const chip = (key, label, sub, active) =>
      `<button onclick="MOS._cjTkSetZona(this.dataset.z)" data-z="${_escapeHtml(String(key))}" class="log-icon-btn ${active ? 'active' : ''}" style="padding:4px 9px;font-size:11px;width:auto;height:auto;display:inline-flex;align-items:center;gap:5px">
         <span>📍 ${_escapeHtml(label)}${sub ? ` <span style="opacity:.55">${sub}</span>` : ''}</span>
       </button>`;
    let html = chip('', 'Todas', '', !_cjState.tkZona);
    html += zonas.map(([z, e]) => chip(z, z, `S/${e.tot.toFixed(0)}`, _cjState.tkZona === z)).join('');
    wrap.innerHTML = html;
  }
  function _cjTkSetZona(z) {
    _cjState.tkZona = (_cjState.tkZona === z) ? '' : z;
    _finBeep('click');
    _cjTkRenderZonasBtns();
    _cjTkRender();
  }

  // [rango] fuente base del buscador: rango de fechas (S._cjTkRangoData) o el día activo,
  // ya filtrada por caja (o __SINCAJA__) y por tipo de documento (NV/B/F). SIN vendedor/método/búsqueda.
  function _cjTkFuente() {
    let base;
    if (_cjState.tkRangoActivo && Array.isArray(S._cjTkRangoData)) {
      base = S._cjTkRangoData.slice();
    } else {
      const fecha = _cjFecha();
      base = (S._todosTickets || []).filter(t => (t.fecha || '').substring(0, 10) === fecha);
    }
    if (_cjState.tkCajaFiltro === '__SINCAJA__') base = base.filter(t => !String(t.idCaja || '').trim());
    else if (_cjState.tkCajaFiltro) base = base.filter(t => String(t.idCaja || '') === _cjState.tkCajaFiltro);
    if (_cjState.tkDoc) base = base.filter(t => String(t.tipo || '').toUpperCase() === _cjState.tkDoc);
    return base;
  }
  function _cjTkSetDoc(d) {
    _cjState.tkDoc = (_cjState.tkDoc === d) ? '' : d;   // toggle
    _finBeep('click');
    _cjTkRenderFiltrosBtns(); _cjTkRenderVendedoresBtns(); _cjTkRender();
  }

  function _cjTkApplyFiltro(tickets) {
    const f = _cjState.tkFiltro;
    const fp = t => String(t.metodo || t.formaPago || '').toUpperCase();
    const esAnul   = t => fp(t) === 'ANULADO' || t.estado === 'ANULADO';
    const esPorCob = t => fp(t) === 'POR_COBRAR' && !esAnul(t);
    const esCred   = t => fp(t) === 'CREDITO' && !esAnul(t);
    const esEf     = t => fp(t) === 'EFECTIVO';
    const esVi     = t => fp(t) === 'VIRTUAL';
    const esMx     = t => fp(t).startsWith('MIXTO');
    const esCob    = t => !esAnul(t) && !esPorCob(t) && !esCred(t);
    if (f === 'todos')      return tickets;
    if (f === 'ventas')     return tickets.filter(esCob);
    if (f === 'efectivo')   return tickets.filter(t => esEf(t) && !esAnul(t));
    if (f === 'virtual')    return tickets.filter(t => esVi(t) && !esAnul(t));
    if (f === 'mixto')      return tickets.filter(t => esMx(t) && !esAnul(t));
    // [877] verificación por Yape: solo aplica a lo virtual (VIRTUAL y MIXTO)
    const esVirt = t => (esVi(t) || esMx(t)) && !esAnul(t);
    const conYape = t => !!(t.yape && typeof t.yape === 'object');
    if (f === 'verif')      return tickets.filter(t => esVirt(t) && conYape(t));
    if (f === 'sinverif')   return tickets.filter(t => esVirt(t) && !conYape(t));
    if (f === 'por_cobrar') return tickets.filter(esPorCob);
    if (f === 'credito')    return tickets.filter(esCred);
    if (f === 'anulado')    return tickets.filter(esAnul);
    return tickets;
  }

  function _cjTkRender() {
    const list = $('cjTkList');
    const conteo = $('cjTkConteo');
    if (!list) return;
    let todos = _cjTkFuente();   // [rango] día activo o rango de fechas + filtro caja + tipo doc
    // [v2.43.387] Filtro por vendedor (chips de persona) — se combina con método + búsqueda
    if (_cjState.tkVendedor) {
      todos = todos.filter(t => _cjTkVendNombre(t) === _cjState.tkVendedor);
    }
    // [zona] filtro por zona emisora (chips de zona)
    if (_cjState.tkZona) {
      todos = todos.filter(t => _cjTkZonaNombre(t) === _cjState.tkZona);
    }
    // Buscar
    const q = ($('cjTkBuscar')?.value || _cjState.tkBuscar || '').trim().toLowerCase();
    if (q) {
      todos = todos.filter(t => {
        const cli = (t.clienteNom || t.cliente || '').toLowerCase();
        const doc = (t.clienteDoc || '').toLowerCase();
        const corr = (t.correlativo || '').toLowerCase();
        return cli.includes(q) || doc.includes(q) || corr.includes(q);
      });
    }
    // Filtro de método
    const lista = _cjTkApplyFiltro(todos);
    const esAnul2 = t => String(t.metodo || t.formaPago || '').toUpperCase() === 'ANULADO' || t.estado === 'ANULADO';
    const totalF = lista.reduce((s,t)=> s + (esAnul2(t) ? 0 : (parseFloat(t.total)||0)), 0);
    if (conteo) conteo.textContent = lista.length + ' tk · S/ ' + totalF.toFixed(2);
    if (!lista.length) {
      list.innerHTML = '<div class="px-4 py-10 text-center text-slate-500 text-sm italic">Sin tickets con este filtro</div>';
      return;
    }
    // [diseño senior] AGRUPAR por fecha de emisión → un header por día (sin leer letra chica)
    // con su total. Días en orden descendente. Dentro, tickets por hora desc (ya vienen así).
    const grupos = new Map();
    lista.forEach(t => { const f = (t.fecha || '').substring(0, 10) || '—'; if (!grupos.has(f)) grupos.set(f, []); grupos.get(f).push(t); });
    const fechas = [...grupos.keys()].sort((a, b) => b.localeCompare(a));
    let html = '';
    fechas.forEach(f => {
      const tks = grupos.get(f);
      const totD = tks.reduce((s, t) => s + (esAnul2(t) ? 0 : (parseFloat(t.total) || 0)), 0);
      html += `<div class="cj-tk-daysep"><span class="cj-tk-daysep-fecha">${_cjTkFechaHdr(f)}</span><span class="cj-tk-daysep-meta">${tks.length} tk · S/ ${totD.toFixed(2)}</span></div>`;
      html += tks.map(_cjTkRowHtml).join('');
    });
    list.innerHTML = html;
  }
  // [diseño] cabecera de día: "🟢 Hoy" / "Ayer · …" / "Mié 21 May"
  function _cjTkFechaHdr(f) {
    if (!f || f === '—') return 'Sin fecha';
    const hoy = today();
    if (f === hoy) return '🟢 Hoy';
    const d = new Date(f + 'T00:00:00');
    const diff = Math.round((d - new Date(hoy + 'T00:00:00')) / 86400000);
    let base = d.toLocaleDateString('es-PE', { weekday: 'short', day: '2-digit', month: 'short' });
    base = base.charAt(0).toUpperCase() + base.slice(1);
    return diff === -1 ? ('Ayer · ' + base) : base;
  }
  // [877] SELLO de verificación: un ticket VIRTUAL/MIXTO cobrado o tiene su Yape (verificado) o no.
  // Sin verificar NO significa impago (el Yape puede no haber llegado, u otra billetera): por eso
  // el sello dice "sin verificar", nunca "impago". Se verifica/desverifica en "💜 Yapes de la caja".
  function _cjTkSelloYape(t, anulado) {
    if (anulado) return '';
    const fp = String(t.metodo || t.formaPago || '').toUpperCase();
    if (!(fp === 'VIRTUAL' || fp.startsWith('MIXTO'))) return '';
    const y = t.yape && typeof t.yape === 'object' ? t.yape : null;
    if (y) {
      const quien = String(y.pagador || '').split(' ')[0];
      return `<span class="tk-sello tk-sello-ok" title="Yape de ${_escapeHtml(String(y.pagador || ''))} · ${_escapeHtml(String(y.hora || ''))}">✅ verificado${quien ? ' · ' + _escapeHtml(quien) : ''}</span>`;
    }
    return `<span class="tk-sello tk-sello-no" title="Ningún Yape capturado calza con este ticket (no significa impago)">◌ sin verificar</span>`;
  }
  // [diseño] fila de ticket (sin la fecha chica: ahora la da el header del grupo)
  function _cjTkRowHtml(t) {
    const an = String(t.metodo || t.formaPago || '').toUpperCase() === 'ANULADO' || t.estado === 'ANULADO';
    const fp = String(t.metodo || t.formaPago || '').toUpperCase();
    const met =
      fp === 'ANULADO'      ? { txt: 'ANULADO',      cls: 'tk-chip-anul' } :
      fp === 'EFECTIVO'     ? { txt: '💵 Efectivo',  cls: 'tk-chip-ef'   } :
      fp === 'VIRTUAL'      ? { txt: '📱 Virtual',   cls: 'tk-chip-vi'   } :
      fp === 'POR_COBRAR'   ? { txt: '⏳ Por cobrar', cls: 'tk-chip-pc'  } :
      fp === 'CREDITO'      ? { txt: '📋 Crédito',   cls: 'tk-chip-cr'   } :
      fp.startsWith('MIXTO')? { txt: '🔀 Mixto',     cls: 'tk-chip-mx'   } :
                              { txt: fp || '—',      cls: 'tk-chip-other' };
    const corr = t.correlativo || (t.idVenta || '').split('-').pop() || '—';
    const cliN = (t.clienteNom || t.cliente || '').trim();
    const cliD = (t.clienteDoc || '').trim();
    const cabecera = (cliN || cliD)
      ? `<div class="tk-cli-nombre">👤 ${_escapeHtml(cliN || 'Sin nombre')}</div>${cliD ? `<div class="tk-cli-doc">${_escapeHtml(cliD)}</div>` : ''}`
      : `<div class="tk-cli-nombre tk-cli-nombre-anon">— Cliente sin registrar —</div>`;
    const tipo = ({ 'BOLETA': 'BOL', 'NOTA_DE_VENTA': 'NV', 'FACTURA': 'FAC', 'NV': 'NV', 'B': 'BOL', 'F': 'FAC' })[t.tipo || t.tipoDoc] || (t.tipo || t.tipoDoc || '');
    const idVentaSafe = _escAttrJs(t.idVenta || '');
    const zona = String(t.zona || '').trim();
    return `<div class="tk-row tk-row-clickable ${an ? 'tk-row-anul' : ''} ${met.cls}" onclick="MOS.cjAbrirAccionesTicket('${idVentaSafe}')">
      <div class="tk-cli">${cabecera}</div>
      <div class="tk-meta">
        <span class="tk-meta-corr">${_escapeHtml(tipo)} ${_escapeHtml(corr)}</span>
        ${t.vendedor ? `<span class="tk-meta-vend">· ${_escapeHtml(t.vendedor)}</span>` : ''}
        ${zona ? `<span class="tk-meta-vend" style="color:#5eead4">· 📍 ${_escapeHtml(zona)}</span>` : ''}
        ${t.hora ? `<span class="tk-meta-hora">· ${t.hora}</span>` : ''}
      </div>
      <div class="tk-monto-col">
        <div class="tk-monto ${an ? 'tk-monto-anul' : ''}">S/ ${parseFloat(t.total || 0).toFixed(2)}</div>
        <span class="tk-chip ${met.cls}">${met.txt}</span>
        ${_cjTkSelloYape(t, an)}
      </div>
      <div class="tk-row-cog" title="Acciones">⚙️</div>
    </div>`;
  }

  // ════════════════════════════════════════════════════════════
  // ACCIONES SOBRE TICKETS — modal contextual editable
  // Estado, helpers, handlers de cada modal secundario.
  // ════════════════════════════════════════════════════════════
  const _tkAcc = {
    idVenta: null,
    ticket: null,
    cobrar: { metodo: 'EFECTIVO', cajaSel: '', cajas: [] },
    cambiarFP: { nueva: '' },
    convCPE: { tipo: 'BOLETA', clienteOK: false },
    baja: { motivo: '' }
  };

  // Buscar el ticket en cualquier estado (cajas o finanzas)
  function _tkBuscarTicket(idVenta) {
    const id = String(idVenta);
    // Cajas
    const enCajas = (S._todosTickets || []).find(t => String(t.idVenta) === id);
    if (enCajas) return _tkNormalizar(enCajas, 'cajas');
    // Finanzas
    const enFin = (_finPL?.detalleTickets || []).find(t => String(t.idVenta) === id);
    if (enFin) return _tkNormalizar(enFin, 'finanzas');
    return null;
  }

  // Normaliza para que ambos shapes (cajas vs finanzas) compartan campos
  function _tkNormalizar(t, fuente) {
    return {
      idVenta:    String(t.idVenta || ''),
      correlativo: t.correlativo || '',
      tipoDoc:    t.tipoDoc || t.tipo || '',
      formaPago:  String(t.formaPago || t.metodo || '').toUpperCase(),
      total:      parseFloat(t.total || 0),
      cliente:    (t.cliente || t.clienteNombre || t.clienteNom || '').trim(),
      clienteDoc: (t.clienteDoc || t.clienteDocumento || '').trim(),
      vendedor:   t.vendedor || '',
      hora:       t.hora || '',
      fecha:      t.fecha || '',
      idCaja:     t.idCaja || '',
      obs:        t.obs || '',
      nfEstado:   t.nfEstado || t.NF_Estado || '',
      _fuente:    fuente
    };
  }

  // Abre el menú contextual de acciones para un ticket
  async function cjAbrirAccionesTicket(idVenta) {
    const t = _tkBuscarTicket(idVenta);
    if (!t) { toast('Ticket no encontrado', 'error'); return; }

    const rol = (S.session?.rol || '').toLowerCase();
    if (rol !== 'master' && rol !== 'admin') {
      toast('Solo admin/master pueden editar tickets', 'error');
      return;
    }

    _tkAcc.idVenta = t.idVenta;
    _tkAcc.ticket  = t;

    const tit = $('tkAccTitulo');
    const sub = $('tkAccSubtitulo');
    if (tit) tit.textContent = (t.correlativo || t.idVenta) + ' · S/ ' + t.total.toFixed(2);
    if (sub) {
      const cli = t.cliente || (t.clienteDoc ? t.clienteDoc : '— sin cliente —');
      sub.textContent = `${t.tipoDoc || ''} · ${t.formaPago} · ${cli}`;
    }
    _tkAccBuildMenu(t);
    openModal('modalTkAcciones');
    _tkCargarDetalle(t.idVenta);   // [Rep#4] llena la sección de detalle (async, Supabase-first)
  }

  // Construye el menú según el estado del ticket
  function _tkAccBuildMenu(t) {
    const body = $('tkAccBody');
    if (!body) return;

    const fp = t.formaPago;
    const esAnulado = fp === 'ANULADO';
    const esPorCobrar = fp === 'POR_COBRAR';
    const esCredito   = fp === 'CREDITO';
    const esCobrado   = !esAnulado && !esPorCobrar && !esCredito;
    const esNV        = (t.tipoDoc === 'NOTA_DE_VENTA' || t.tipoDoc === 'NV');
    const esCPE       = (t.tipoDoc === 'BOLETA' || t.tipoDoc === 'FACTURA');
    const cpeEmitido  = esCPE && t.nfEstado === 'EMITIDO';

    const btns = [];
    const btn = (cls, emoji, tit, sub, accion) => {
      btns.push(`<button class="tk-acc-btn ${cls}" onclick="MOS._tkAccion('${accion}')">
        <span class="tk-acc-emoji">${emoji}</span>
        <span class="tk-acc-txt">
          <div class="tk-acc-tit">${tit}</div>
          <div class="tk-acc-sub">${sub}</div>
        </span>
      </button>`);
    };

    if (esAnulado) {
      btn('', '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-3px"><path d="M6 9V2h12v7"/><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><rect x="6" y="14" width="12" height="8" rx="1"/><circle cx="18" cy="11.5" r="1" fill="currentColor"/></svg>', 'Imprimir ticket', 'Reimprime el comprobante en la impresora que elijas', 'imprimir');
      if (esCPE) btn('', '📄', 'Ver / compartir PDF', 'Comprobante fiscal (aunque esté de baja)', 'pdf');
      btn('', '📜', 'Ver historial', 'Ver todos los cambios del ticket', 'historial');
      body.innerHTML = `<p class="text-[11px] text-slate-500 italic px-2 py-2">Ticket anulado · solo lectura.</p>${btns.join('')}${_tkDetalleContainerHtml()}`;
      return;
    }

    // 💵 Cobrar (si está pendiente o crédito)
    if (esPorCobrar || esCredito) {
      btn('tk-acc-btn-ok', '💵', 'Cobrar' + (esCredito ? ' deuda' : ' pendiente'),
          'Crea ingreso en caja receptora · marca como cobrado', 'cobrar');
    }

    // 📋 Aprobar como crédito (solo si está POR_COBRAR)
    if (esPorCobrar) {
      btn('tk-acc-btn-warn', '📋', 'Aprobar como crédito',
          'Pasa de "por cobrar" a "crédito formal"', 'aprobarCredito');
    }

    // 🔄 Cambiar forma de pago (corrección sin afectar caja)
    if (esCobrado) {
      btn('', '🔄', 'Cambiar forma de pago',
          'Corrige errores de tipeo · NO mueve dinero entre cajas', 'cambiarFP');
    }

    // 👤 Editar cliente — SOLO Nota de Venta. Un CPE (boleta/factura) NO cambia de titular fiscal tras
    // mintear el correlativo (regla SUNAT, me.editar_cliente SQL 271 H7) → para corregir: anular y reemitir.
    // Antes el botón salía con `!cpeEmitido` → aparecía en boletas PENDIENTES y el backend lo rechazaba (toast rojo).
    if (esNV) {
      btn('', '👤', 'Editar cliente', 'Cambiar DNI/RUC y nombre del NV', 'editarCliente');
    } else if (esCPE && !esAnulado) {
      btn('tk-acc-btn-warn', '🔒', 'Editar cliente — solo Nota de Venta',
          'Boleta/Factura no cambian de titular · para corregir: anula y reemite', 'editarClienteCPEInfo');
    }

    // 📑 Convertir NV → CPE (solo NV)
    if (esNV && !esAnulado) {
      btn('', '📑', 'Convertir a Boleta/Factura',
          'Emite CPE retroactivo en SUNAT', 'convertirCPE');
    }

    // 📋 Baja del CPE (solo CPE emitido)
    if (cpeEmitido) {
      btn('tk-acc-btn-danger', '📋', 'Baja del CPE',
          'Comunica baja a SUNAT (irreversible)', 'bajaCPE');
    }

    // ❌ Anular venta interna (siempre disponible si no anulado)
    btn('tk-acc-btn-danger', '❌', 'Anular venta',
        'Marca el ticket como anulado internamente', 'anular');

    // 📄 PDF del comprobante fiscal — SOLO boleta/factura (las que tienen PDF de NubeFact)
    if (esCPE) {
      btn('', '📄', 'Ver / compartir PDF',
          'Boleta o factura · previsualiza, comparte por WhatsApp o imprime', 'pdf');
    }

    // 🖨 Imprimir ticket — siempre (reimpresión por la impresora que elija el admin)
    btn('tk-acc-btn-ok', '<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" style="vertical-align:-3px"><path d="M6 9V2h12v7"/><path d="M6 18H4a2 2 0 0 1-2-2v-5a2 2 0 0 1 2-2h16a2 2 0 0 1 2 2v5a2 2 0 0 1-2 2h-2"/><rect x="6" y="14" width="12" height="8" rx="1"/><circle cx="18" cy="11.5" r="1" fill="currentColor"/></svg>', 'Imprimir ticket',
        'Reimprime el comprobante en la impresora que elijas', 'imprimir');

    // 📜 Historial — siempre
    btn('', '📜', 'Ver historial',
        'Ver todos los cambios de este ticket', 'historial');

    // 📜 Historial cliente — solo si hay clienteDoc
    if (t.clienteDoc) {
      btn('', '👥', 'Historial del cliente',
          (t.cliente || t.clienteDoc) + ' · cambios sobre este cliente', 'historialCli');
    }

    body.innerHTML = (btns.join('') || '<p class="text-xs text-slate-500 italic">Sin acciones disponibles.</p>') + _tkDetalleContainerHtml();
  }
  // [Reparación #4 · Etapa 1] Contenedor de la sección "detalle del ticket" (scrollable, se llena async).
  function _tkDetalleContainerHtml() {
    return `<div id="tkAccDetalle" class="tk-acc-detalle">
      <div class="tk-acc-det-hdr">🧾 Detalle del ticket</div>
      <div class="tk-acc-det-body"><div class="text-[11px] text-slate-400 px-1 py-2">Cargando…</div></div>
    </div>`;
  }

  // Routing del menú contextual
  function _tkAccion(accion) {
    const t = _tkAcc.ticket;
    if (!t) return;
    closeModal('modalTkAcciones');
    if (accion === 'cobrar')          return _tkCobrarOpen(t);
    if (accion === 'cambiarFP')       return _tkCambiarFPOpen(t);
    if (accion === 'aprobarCredito')  return _tkAprobarCredOpen(t);
    if (accion === 'convertirCPE')    return _tkConvertirOpen(t);
    if (accion === 'bajaCPE')         return _tkBajaOpen(t);
    if (accion === 'editarCliente')   return _tkEditarClienteOpen(t);
    if (accion === 'editarClienteCPEInfo') {
      _modalConfirm(
        'Una boleta o factura ya tiene su correlativo SUNAT minteado, por eso el titular fiscal (DNI/RUC + nombre) NO se puede cambiar.\n\nPara corregir el cliente: ANULA este comprobante (dar de baja en SUNAT) y emite uno nuevo con los datos correctos.\n\nLas Notas de Venta sí se editan libremente.',
        { warning: true, titulo: '🔒 Cliente de CPE no editable', okText: 'Entendido' }
      );
      return;
    }
    if (accion === 'anular')          return _tkAnularSimple(t);
    if (accion === 'pdf')             return _tkPdfOpen(t);
    if (accion === 'historial')       return _tkHistorialOpen(t);
    if (accion === 'historialCli')    return _tkHistorialClienteOpen(t);
    if (accion === 'imprimir')        return _tkImprimir(t);
  }

  function _tkNum(x) { const n = Number(x); return Number.isFinite(n) ? n : 0; }
  // [Reparación #4 · Etapa 1] Carga + render del DETALLE del ticket en la sección del modal.
  // Supabase-first (mos.me_detalle_venta) con fallback GAS. Cachea en _tkAcc.detalle para la impresión.
  async function _tkCargarDetalle(idVenta) {
    const host = document.getElementById('tkAccDetalle');
    if (!host) return;
    const body = host.querySelector('.tk-acc-det-body');
    try {
      const r = await API.get('meDetalleVenta', { idVenta });
      const data = (r && r.data) || r || {};
      const items = Array.isArray(data.items) ? data.items : [];
      _tkAcc.detalle = data;   // cache del detalle mostrado (la impresión va por el Edge ticket-comprobante)
      if (!body) return;
      if (!items.length) { body.innerHTML = `<div class="text-[11px] text-slate-400 px-1 py-2">Sin líneas para este ticket.</div>`; return; }
      const filas = items.map(it => {
        const cant = _tkNum(it.cantidad), sub = _tkNum(it.subtotal);
        const nom = _esc(String(it.nombre || it.sku || '—').replace(/\s*\(.*\)\s*$/, ''));   // recorta "(canónico)" duplicado
        return `<div class="tk-acc-det-row">
          <span class="tk-acc-det-q">${cant}×</span>
          <span class="tk-acc-det-n">${nom}</span>
          <span class="tk-acc-det-s">S/ ${sub.toFixed(2)}</span>
        </div>`;
      }).join('');
      const tot = _tkNum(data.total) || items.reduce((s, it) => s + _tkNum(it.subtotal), 0);  // [R1] fallback Σsubtotal (path GAS no trae total)
      body.innerHTML = `<div class="tk-acc-det-list">${filas}</div>
        <div class="tk-acc-det-tot"><span>Total (${items.length} ít.)</span><b>S/ ${tot.toFixed(2)}</b></div>`;
    } catch (e) {
      if (body) body.innerHTML = `<div class="text-[11px] text-rose-400 px-1 py-2">No se pudo cargar el detalle.</div>`;
    }
  }

  // [Reparación #4 · Etapa 1] Imprime (reimprime) el ticket: elige impresora + arma ESC/POS client-side +
  // lo manda por la Edge `imprimir` (PrintNode, cero GAS). Optimista con feedback.
  async function _tkImprimir(t) {
    try {
      const printerId = await abrirPrinterPicker({
        titulo: 'Imprimir ticket', subtitulo: (t.correlativo || t.idVenta),
        filtroTipo: 'TICKET', flowKey: 'venta_ticket'
      });
      if (!printerId) return;   // canceló
      toast('Enviando a impresora…', 'info', 1500);
      // [Reparación #9] Comprobante CENTRALIZADO por Edge ticket-comprobante (empresa + IGV + QR + leyenda),
      // mismo formato que el ticket original. Reemplaza el builder client-side pobre (_tkBuildEscPos).
      await API.imprimirComprobante(t.idVenta, printerId, { reimpresion: true });
      try { _opsBeep && _opsBeep('ok'); } catch (_) {}
      toast('🖨 Ticket enviado a impresión', 'success');
    } catch (e) {
      try { _opsBeep && _opsBeep('error'); } catch (_) {}
      toast('No se pudo imprimir: ' + (e && (e.message || e)), 'error');
    }
  }

  // ──────────────────────────────────────────────────────────
  // PDF DEL COMPROBANTE FISCAL (boleta/factura NubeFact)
  // Sin preview embebido: NubeFact bloquea el iframe (X-Frame-Options) y el fetch
  // directo (sin CORS). El PDF REAL se baja por el Edge proxy `cpe-pdf` (server-side)
  // → se DESCARGA como archivo y se ENVÍA por WhatsApp como archivo adjunto.
  // La RPC mos.me_cpe_pdf_por_venta (SQL 591) solo da metadata (estado/correlativo/enlace
  // oficial). On-demand, 0 generación, 0 escritura.
  // ──────────────────────────────────────────────────────────
  async function _tkPdfOpen(t) {
    _tkAcc.pdf = null;
    const tit = $('tkPdfTitulo'), sub = $('tkPdfSub'), body = $('tkPdfBody'), acc = $('tkPdfAcciones');
    if (tit)  tit.textContent = (t.correlativo || t.idVenta);
    if (sub)  sub.textContent = (t.tipoDoc || '') + ' · ' + (t.cliente || t.clienteDoc || '— sin cliente —');
    if (acc)  acc.classList.add('hidden');
    if (body) body.innerHTML = '<div style="text-align:center;color:#94a3b8;padding:34px 16px">Buscando comprobante…</div>';
    openModal('modalTkPdf');
    try {
      const r = await _facRpc('me_cpe_pdf_por_venta', { id_venta: t.idVenta, correlativo: t.correlativo });
      const d = (r && r.status === 'success') ? r : {};
      const pdf = (d && d.encontrado) ? d.pdf : null;
      if (!pdf) {
        if (body) body.innerHTML = `<div style="text-align:center;padding:30px 16px;color:#94a3b8">
          <div style="font-size:40px;margin-bottom:8px">📄</div>
          <div style="font-weight:700;color:#cbd5e1">Este ticket no tiene comprobante fiscal con PDF.</div>
          <div style="font-size:12px;margin-top:6px">Solo las boletas/facturas emitidas a SUNAT tienen PDF de NubeFact.${d && d.estado ? ' · Estado: ' + _escapeHtml(String(d.estado)) : ''}</div>
        </div>`;
        return;
      }
      _tkAcc.pdf = { url: pdf, correlativo: d.correlativo || t.correlativo, estado: d.estado, idVenta: t.idVenta, t: t, blob: null, fname: null };
      const est = String(d.estado || '').toUpperCase();
      // [621] BAJA se evalúa PRIMERO: un comprobante dado de baja ante SUNAT conserva
      // `aceptada = true` (fue aceptado ANTES de anularse), así que con el orden anterior
      // la rama BAJA era inalcanzable y se pintaba "🟢 Aceptado" sobre un documento
      // anulado — que además se ofrecía enviar al cliente por WhatsApp.
      const esBaja = (est === 'BAJA');
      const chip = esBaja
        ? '<span style="font-size:12px;font-weight:800;color:#fff;background:#64748b;padding:3px 10px;border-radius:8px">⛔ Dado de baja ante SUNAT</span>'
        : (est === 'EMITIDO' || d.aceptada === true)
        ? '<span style="font-size:12px;font-weight:800;color:#052e1c;background:#10b981;padding:3px 10px;border-radius:8px">🟢 Aceptado</span>'
        : est === 'RECHAZADO' ? '<span style="font-size:12px;font-weight:800;color:#fff;background:#ef4444;padding:3px 10px;border-radius:8px">✖ Rechazado por SUNAT</span>'
        : '<span style="font-size:12px;font-weight:800;color:#2a1c02;background:#f59e0b;padding:3px 10px;border-radius:8px">🟡 ' + _escapeHtml(String(d.estado || 'Pendiente SUNAT')) + '</span>';
      const url = _escapeHtml(String(pdf));
      if (body) body.innerHTML =
        `<div style="text-align:center;padding:6px 4px 2px">
           <div style="font-size:46px;line-height:1">🧾</div>
           <div style="margin:8px 0">${chip}</div>
           <div style="font-family:ui-monospace,monospace;font-size:16px;font-weight:800;color:#e2e8f0">${_escapeHtml(String(d.correlativo || t.correlativo || ''))}</div>
           <div style="font-size:12px;color:#64748b;margin-top:4px">${_escapeHtml(String(t.tipoDoc || ''))} · ${_escapeHtml(String(t.cliente || t.clienteDoc || '—'))}</div>
           ${esBaja
             ? '<div style="font-size:12px;color:#fca5a5;margin-top:14px;line-height:1.6;background:rgba(248,113,113,.1);border:1px solid rgba(248,113,113,.4);border-radius:10px;padding:9px 11px"><b>Este comprobante fue ANULADO ante SUNAT.</b><br>No se lo envíes al cliente: ya no tiene validez fiscal.</div>'
             : '<div style="font-size:11.5px;color:#64748b;margin-top:14px;line-height:1.6">El PDF oficial lo emite NubeFact.<br>Descárgalo o envíaselo al cliente como archivo 📎</div>'}
           <a href="${url}" target="_blank" rel="noopener" style="display:inline-block;margin-top:10px;font-size:12px;color:#818cf8;font-weight:700">Abrir el oficial en pestaña ↗</a>
         </div>`;
      // [621] con un comprobante dado de baja NO se ofrecen las acciones de envío/compartir.
      if (acc) acc.classList.toggle('hidden', esBaja);
    } catch (e) {
      if (body) body.innerHTML = '<div style="text-align:center;color:#fca5a5;padding:30px 16px">No se pudo cargar el comprobante.<br><span style="font-size:12px;color:#94a3b8">' + _escapeHtml(String(e && (e.message || e))) + '</span></div>';
    }
  }

  // Baja el PDF real (Edge cpe-pdf) UNA sola vez y lo cachea en _tkAcc.pdf.blob.
  async function _tkPdfBlob() {
    const p = _tkAcc.pdf; if (!p) return null;
    if (p.blob) return p;
    const r = await API.descargarCpePdf(p.idVenta);
    p.blob = r.blob; p.fname = r.filename;
    return p;
  }
  function _descargarBlob(blob, fname) {
    const u = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = u; a.download = fname || 'comprobante.pdf';
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(u), 5000);
  }

  async function _tkPdfDescargar() {
    if (!_tkAcc.pdf) return;
    try {
      toast('⏳ Descargando PDF…', 'info', 2000);
      const b = await _tkPdfBlob();
      _descargarBlob(b.blob, b.fname);
      toast('📥 PDF descargado', 'success');
    } catch (e) { toast('No se pudo descargar: ' + (e && (e.message || e)), 'error', 6000); }
  }

  // Enviar el ARCHIVO PDF real por WhatsApp (Web Share con archivo). Si el equipo no soporta
  // compartir archivos, descarga el PDF y abre WhatsApp con el enlace como respaldo.
  async function _tkPdfCompartir() {
    const p = _tkAcc.pdf; if (!p) return;
    try {
      toast('⏳ Preparando PDF…', 'info', 2000);
      const b = await _tkPdfBlob();
      const file = new File([b.blob], b.fname, { type: 'application/pdf' });
      if (navigator.canShare && navigator.canShare({ files: [file] })) {
        try { await navigator.share({ files: [file], title: p.correlativo || 'Comprobante', text: 'Comprobante ' + (p.correlativo || '') }); return; }
        catch (err) { if (err && err.name === 'AbortError') return; }
      }
      _descargarBlob(b.blob, b.fname);
      window.open('https://wa.me/?text=' + encodeURIComponent('Comprobante ' + (p.correlativo || '') + '\n' + p.url), '_blank');
      toast('📥 PDF descargado · adjúntalo en el chat', 'info', 6000);
    } catch (e) { toast('No se pudo compartir: ' + (e && (e.message || e)), 'error', 6000); }
  }

  // Imprimir = mismo camino que Reimprimir (selector de impresora + comprobante
  // centralizado por Edge, que ES la representación impresa fiscal con QR/leyenda).
  function _tkPdfImprimir() {
    const p = _tkAcc.pdf; if (!p || !p.t) return;
    closeModal('modalTkPdf');
    _tkImprimir(p.t);
  }

  // [Review R1] _tkBuildEscPos ELIMINADO — código muerto. La impresión del ticket va por API.imprimirComprobante
  // (Edge ticket-comprobante, formato centralizado con empresa/IGV/QR/leyenda). No re-cablear un builder inferior.

  // ──────────────────────────────────────────────────────────
  // COBRAR PENDIENTE / DEUDA
  // ──────────────────────────────────────────────────────────
  async function _tkCobrarOpen(t) {
    _tkAcc.cobrar = { metodo: 'EFECTIVO', cajaSel: '', cajas: [] };
    $('tkCobrarTitulo').textContent = (t.formaPago === 'CREDITO' ? 'Cobrar deuda' : 'Cobrar pendiente');
    $('tkCobrarSubtitulo').textContent = (t.correlativo || t.idVenta) + ' · ' + t.formaPago;
    $('tkCobrarCliente').textContent = t.cliente || '— sin cliente —';
    $('tkCobrarRef').textContent     = (t.tipoDoc || '') + ' ' + (t.correlativo || t.idVenta);
    $('tkCobrarMonto').textContent   = 'S/ ' + t.total.toFixed(2);
    $('tkCobrarObs').value           = '';
    $('tkCobrarMonEf').value = '';
    $('tkCobrarMonVi').value = '';
    $('tkCobrarMixto').classList.add('hidden');
    $('tkCobrarMixtoHint').textContent = '';
    $('tkCobrarCajas').innerHTML = '<div class="text-xs text-slate-500 italic px-2 py-3">Cargando cajas abiertas...</div>';

    // Marcar EFECTIVO por default
    _tkCobrarSetMetodo('EFECTIVO');
    openModal('modalTkCobrar');

    try {
      const data = await API.get('meCajasAbiertas');
      _tkAcc.cobrar.cajas = Array.isArray(data) ? data : [];
      _tkCobrarRenderCajas();
    } catch(e) {
      $('tkCobrarCajas').innerHTML = `<div class="text-xs text-rose-400 px-2 py-2">Error: ${e.message}</div>`;
    }
  }

  function _tkCobrarRenderCajas() {
    const c = $('tkCobrarCajas');
    if (!c) return;
    const cajas = _tkAcc.cobrar.cajas || [];
    if (!cajas.length) {
      c.innerHTML = '<div class="text-xs text-amber-400 italic px-2 py-2">No hay cajas abiertas. Abre una caja en MosExpress primero.</div>';
      return;
    }
    c.innerHTML = cajas.map(k => `
      <label class="tk-caja-radio" data-id="${k.idCaja}">
        <input type="radio" name="tkCobrarCaja" value="${k.idCaja}" onchange="MOS._tkCobrarSetCaja('${k.idCaja}')">
        <div class="tk-caja-vend">${k.vendedor || k.idCaja}</div>
        <div class="tk-caja-zona">${k.zona || ''}</div>
      </label>
    `).join('');
    // Auto-seleccionar la única caja si solo hay una
    if (cajas.length === 1) {
      const r = c.querySelector('input[type="radio"]');
      if (r) { r.checked = true; _tkCobrarSetCaja(cajas[0].idCaja); }
    }
  }

  function _tkCobrarSetCaja(id) {
    _tkAcc.cobrar.cajaSel = id;
    document.querySelectorAll('#tkCobrarCajas .tk-caja-radio').forEach(el => {
      el.classList.toggle('tk-caja-active', el.dataset.id === id);
    });
  }

  function _tkCobrarSetMetodo(met) {
    _tkAcc.cobrar.metodo = met;
    ['Ef','Vi','Mx'].forEach(k => {
      const b = $('tkCobrarBtn' + k);
      if (b) b.classList.remove('tk-cob-mbtn-active');
    });
    const map = { 'EFECTIVO':'Ef', 'VIRTUAL':'Vi', 'MIXTO':'Mx' };
    const b = $('tkCobrarBtn' + map[met]);
    if (b) b.classList.add('tk-cob-mbtn-active');
    $('tkCobrarMixto').classList.toggle('hidden', met !== 'MIXTO');
    if (met === 'MIXTO') _tkCobrarValidarMixto();
  }

  function _tkCobrarValidarMixto() {
    const t = _tkAcc.ticket;
    const ef = parseFloat($('tkCobrarMonEf').value || 0);
    const vi = parseFloat($('tkCobrarMonVi').value || 0);
    const total = t ? t.total : 0;
    const sum = ef + vi;
    const hint = $('tkCobrarMixtoHint');
    if (!hint) return;
    if (Math.abs(sum - total) < 0.01) {
      hint.textContent = `✓ Suma S/ ${sum.toFixed(2)} = total`;
      hint.style.color = '#6ee7b7';
    } else {
      hint.textContent = `Suma S/ ${sum.toFixed(2)} · falta/sobra S/ ${(total - sum).toFixed(2)}`;
      hint.style.color = '#fcd34d';
    }
  }

  async function _tkCobrarConfirmar() {
    const t = _tkAcc.ticket;
    if (!t) return;
    const c = _tkAcc.cobrar;
    if (!c.cajaSel)  { toast('Selecciona la caja receptora', 'error'); return; }
    if (!c.metodo)   { toast('Selecciona forma de pago', 'error'); return; }

    let metodoFinal = c.metodo;
    let monEf, monVi;
    if (c.metodo === 'MIXTO') {
      monEf = parseFloat($('tkCobrarMonEf').value || 0);
      monVi = parseFloat($('tkCobrarMonVi').value || 0);
      if (Math.abs((monEf + monVi) - t.total) > 0.01) {
        toast('La suma EFE+VIR debe igualar el total', 'error'); return;
      }
      metodoFinal = `MIXTO (EFE:${monEf.toFixed(2)}/VIR:${monVi.toFixed(2)})`;
    }

    const btn = $('tkCobrarBtnOK');
    if (btn) { btn.disabled = true; btn.textContent = 'Procesando...'; }
    try {
      const r = await API.post('meCobrarCredito', {
        idVenta:       t.idVenta,
        cajaReceptora: c.cajaSel,
        metodo:        metodoFinal,
        montoEfectivo: monEf,
        montoVirtual:  monVi,
        obs:           $('tkCobrarObs').value || ''
      });
      toast('✓ Cobrado · ingreso registrado', 'success');
      closeModal('modalTkCobrar');
      await _cajasRefreshSilencioso?.();
      if (S.view === 'finanzas') finCargar?.();
    } catch(e) {
      toast('Error: ' + e.message, 'error');
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = '✓ Confirmar cobro'; }
    }
  }

  // ──────────────────────────────────────────────────────────
  // CAMBIAR FORMA DE PAGO (corrección)
  // ──────────────────────────────────────────────────────────
  function _tkCambiarFPOpen(t) {
    _tkAcc.cambiarFP.nueva = '';
    $('tkCambiarFPSub').textContent  = (t.correlativo || t.idVenta);
    $('tkCambiarFPActual').textContent = t.formaPago;
    const _cpeNota = $('tkCambiarFPCpeNota');   // aclaración: en un CPE el modo de pago es interno
    if (_cpeNota) _cpeNota.classList.toggle('hidden', !(t.tipoDoc === 'BOLETA' || t.tipoDoc === 'FACTURA'));
    $('tkCambiarFPMotivo').value = '';

    // Opciones (excluye la actual)
    const opciones = [
      { v: 'EFECTIVO', txt: '💵 Efectivo' },
      { v: 'VIRTUAL',  txt: '📱 Virtual'  },
      { v: 'POR_COBRAR', txt: '⏳ Por cobrar' },
      { v: 'CREDITO',  txt: '📋 Crédito' }
    ].filter(o => o.v !== t.formaPago);
    $('tkCambiarFPOpciones').innerHTML = opciones.map(o =>
      `<button class="tk-cob-mbtn" onclick="MOS._tkCambiarFPSel('${o.v}')" id="tkCambiarFPOp_${o.v}">${o.txt}</button>`
    ).join('');
    openModal('modalTkCambiarFP');
    _tkCambiarFPValidar();   // arranca deshabilitado (sin forma ni motivo)
  }

  function _tkCambiarFPSel(v) {
    _tkAcc.cambiarFP.nueva = v;
    document.querySelectorAll('#tkCambiarFPOpciones .tk-cob-mbtn').forEach(b => b.classList.remove('tk-cob-mbtn-active'));
    const b = $('tkCambiarFPOp_' + v);
    if (b) b.classList.add('tk-cob-mbtn-active');
    _tkCambiarFPValidar();
  }

  // [UX 500x] Gate in-form: el botón solo se habilita con forma seleccionada + motivo>=3.
  // Evita el toast rojo post-submit "Motivo obligatorio" (no intuitivo).
  function _tkCambiarFPValidar() {
    const motivo = ($('tkCambiarFPMotivo')?.value || '').trim();
    const ok = !!_tkAcc.cambiarFP.nueva && motivo.length >= 3;
    const btn = $('tkCambiarFPBtn');
    if (btn) {
      btn.disabled = !ok;
      btn.classList.toggle('opacity-40', !ok);
      btn.classList.toggle('cursor-not-allowed', !ok);
    }
    return ok;
  }

  async function _tkCambiarFPConfirmar() {
    const t = _tkAcc.ticket;
    const nueva = _tkAcc.cambiarFP.nueva;
    if (!nueva) { toast('Selecciona la nueva forma de pago', 'error'); return; }
    const motivo = ($('tkCambiarFPMotivo').value || '').trim();
    if (motivo.length < 3) { toast('Motivo obligatorio (mín. 3 caracteres)', 'error'); return; }
    const auth = await pedirAuth({ accion: 'EDITAR_CLIENTE_VENTA', refDocumento: t.correlativo || t.idVenta,
      contexto: 'Cambiar forma de pago a ' + nueva });
    if (!auth) return;
    try {
      await API.post('meEditarFormaPago', {
        idVenta: t.idVenta, formaPagoNueva: nueva, motivo, claveAdmin: auth.clave
      });
      toast('✓ Forma de pago actualizada', 'success');
      closeModal('modalTkCambiarFP');
      await _cajasRefreshSilencioso?.();
      if (S.view === 'finanzas') finCargar?.();
    } catch(e) {
      toast('Error: ' + e.message, 'error');
    }
  }

  // ──────────────────────────────────────────────────────────
  // APROBAR COMO CREDITO (POR_COBRAR → CREDITO)
  // ──────────────────────────────────────────────────────────
  function _tkAprobarCredOpen(t) {
    $('tkAprobarCredSub').textContent = (t.correlativo || t.idVenta) + ' · S/ ' + t.total.toFixed(2);
    $('tkAprobarCredObs').value = '';
    openModal('modalTkAprobarCred');
  }

  async function _tkAprobarCredConfirmar() {
    const t = _tkAcc.ticket;
    const obs = ($('tkAprobarCredObs').value || '').trim();
    if (obs.length < 3) { toast('Motivo obligatorio (mín. 3 caracteres)', 'error'); return; }
    const auth = await pedirAuth({ accion: 'CREDITAR_VENTA', refDocumento: t.correlativo || t.idVenta,
      contexto: 'Aprobar como crédito ' + (t.correlativo || t.idVenta) });
    if (!auth) return;
    try {
      await API.post('meAprobarComoCredito', { idVenta: t.idVenta, motivo: obs, claveAdmin: auth.clave });
      toast('✓ Aprobado como crédito', 'success');
      closeModal('modalTkAprobarCred');
      await _cajasRefreshSilencioso?.();
      if (S.view === 'finanzas') finCargar?.();
    } catch(e) {
      toast('Error: ' + e.message, 'error');
    }
  }

  // ──────────────────────────────────────────────────────────
  // CONVERTIR NV → CPE (boleta/factura retroactivo)
  // ──────────────────────────────────────────────────────────
  function _tkConvertirOpen(t) {
    _tkAcc.convCPE = { tipo: 'BOLETA', clienteOK: false };
    $('tkConvSub').textContent = (t.correlativo || t.idVenta) + ' · S/ ' + t.total.toFixed(2);
    $('tkConvDoc').value      = t.clienteDoc || '';
    $('tkConvNombre').value   = t.cliente || '';
    $('tkConvDireccion').value = '';
    $('tkConvDireccion').readOnly = true;   // por defecto readonly; el lookup lo libera solo si el RUC no trae dirección
    // [786] serie automática por zona de la venta — informativo, ya no se tipea
    const _ser = $('tkConvSerie');
    if (_ser) { _ser.value = 'automática · según la zona de la venta'; _ser.disabled = true; }
    $('tkConvClienteInfo').classList.add('hidden');
    _tkConvSetTipo('BOLETA');
    openModal('modalTkConvertirCPE');
    // [929] Auto-identificar al abrir: trae nombre + dirección del RUC/DNI (sombra o SUNAT/RENIEC) sin que el
    //   admin tenga que tocar "Buscar", y deja la dirección lista (no editable). Silencioso si no hay doc.
    if ((t.clienteDoc || '').trim()) { try { _tkConvBuscarCliente(true); } catch (_) {} }
  }

  function _tkConvSetTipo(tipo) {
    _tkAcc.convCPE.tipo = tipo;
    ['Bol','Fac'].forEach(k => {
      const b = $('tkConvBtn' + k);
      if (b) b.classList.remove('tk-cob-mbtn-active');
    });
    const b = $('tkConvBtn' + (tipo === 'BOLETA' ? 'Bol' : 'Fac'));
    if (b) b.classList.add('tk-cob-mbtn-active');
    const seriePh = tipo === 'BOLETA' ? 'B001' : 'F001';
    $('tkConvSerie').placeholder = 'ej: ' + seriePh;
    _tkConvReglasRefresh();
  }

  function _tkConvDocChange() {
    _tkAcc.convCPE.clienteOK = false;
    $('tkConvClienteInfo').classList.add('hidden');
    _tkConvReglasRefresh();
  }
  // [reglas SUNAT en vivo · conversión NV→CPE en MOS] mismo checklist que ME + el panel VIP.
  function _tkConvReglasRefresh() {
    const box=$('tkConvReglas'); if(!box) return;
    const t=(_tkAcc&&_tkAcc.ticket)||{};
    const total=Number(t.total ?? t.monto ?? t.Total ?? 0);
    const medio=t.forma_pago || t.metodo || 'EFECTIVO';
    const doc=(($('tkConvDoc')||{}).value||'').replace(/\D/g,'');
    const nombre=(($('tkConvNombre')||{}).value||'').trim();
    const dir=(($('tkConvDireccion')||{}).value||'').trim();
    box.innerHTML = _cpeReglasHtml(_cpeReglas((_tkAcc&&_tkAcc.convCPE&&_tkAcc.convCPE.tipo)||'BOLETA', total, doc, nombre, dir, medio));
  }

  async function _tkConvBuscarCliente(auto) {
    const doc = ($('tkConvDoc').value || '').trim();
    if (!doc) { if (!auto) toast('Ingresa DNI o RUC', 'error'); return; }
    if (doc.length !== 8 && doc.length !== 11) {
      if (!auto) toast('DNI debe tener 8 dígitos · RUC 11 dígitos', 'error'); return;
    }
    const info = $('tkConvClienteInfo');
    if (info) {
      info.classList.remove('hidden');
      info.innerHTML = '<span class="text-slate-400">🔎 Consultando…</span>';
    }
    try {
      const r = await API.get('meConsultarCliente', { doc });
      // [929] lectura robusta del shape: la RPC/Edge devuelve el objeto plano, pero por si viene bajo .data.
      const o = (r && (r.nombre || r.razon_social || r.razonSocial)) ? r : ((r && r.data) || r || {});
      const nombre = o.nombre || o.razon_social || o.razonSocial || '';
      const direccion = o.direccion || o.direccionFiscal || '';
      if (!nombre) {
        // No en la sombra ni en SUNAT/RENIEC. La dirección NO es editable (se respeta la del RUC), así que
        // sin identificar no se puede completar. Mantiene lo que traía el ticket (nombre) por si sirve.
        if (info) info.innerHTML = '<span class="text-amber-400">⚠ No se pudo identificar el documento en SUNAT/RENIEC. Revisa el número o reintenta.</span>';
        _tkAcc.convCPE.clienteOK = false;
        _tkConvReglasRefresh();
        return;
      }
      $('tkConvNombre').value    = nombre;
      const _dirEl = $('tkConvDireccion');
      if (direccion) {
        _dirEl.value = direccion; _dirEl.readOnly = true;       // se respeta la dirección oficial del RUC
      } else if (_dirEl) {
        // [fix A1] el RUC/documento no trae dirección → permitir TIPEARLA (si queda readonly + vacía, la FACTURA
        // era imposible de emitir: el campo es obligatorio). Cuando sí hay dirección oficial, se respeta (readonly).
        _dirEl.readOnly = false;
        if (!_dirEl.value.trim()) _dirEl.setAttribute('placeholder', 'Escribe la dirección fiscal (no registrada en SUNAT)');
      }
      if (info) info.innerHTML = `<div class="text-emerald-400 font-bold">✓ ${_escapeHtml ? _escapeHtml(nombre) : nombre}</div>` +
                       (direccion ? `<div class="text-slate-400">${_escapeHtml ? _escapeHtml(direccion) : direccion}</div>` : '<div class="text-amber-400 text-[11px]">Sin dirección en SUNAT — escríbela abajo para emitir la factura.</div>');
      _tkAcc.convCPE.clienteOK = true;
      _tkConvReglasRefresh();
    } catch(e) {
      if (info) info.innerHTML = '<span class="text-rose-400">Error: ' + (e && e.message || e) + '</span>';
    }
  }

  async function _tkConvertirConfirmar() {
    const t = _tkAcc.ticket;
    const tipo = _tkAcc.convCPE.tipo;
    const doc  = ($('tkConvDoc').value || '').trim();
    const nom  = ($('tkConvNombre').value || '').trim();
    const dir  = ($('tkConvDireccion').value || '').trim();
    // [786] la serie ya NO se pide: la RPC la resuelve por la ZONA de la venta (regla 585)

    const _tkTotal = Number(t.total ?? t.monto ?? t.Total ?? 0);
    // [validaciones SUNAT · paridad ME/MOS — el backend fac.emitir_cpe las re-valida server-side]
    if (tipo === 'FACTURA') {
      if (doc.length !== 11) { toast('Factura requiere RUC de 11 dígitos', 'error'); return; }
      if (!nom) { toast('Factura requiere razón social', 'error'); return; }
      if (!dir) { toast('Factura requiere dirección', 'error'); return; }
    }
    if (tipo === 'BOLETA' && _tkTotal > 700) {
      if (!(doc.length === 8 || doc.length === 11)) { toast('Boleta > S/700: identifica al cliente (DNI 8 o RUC 11)', 'error'); return; }
      if (!nom) { toast('Boleta > S/700: ingresa el nombre', 'error'); return; }
    }

    if (!await _modalConfirm(`¿Emitir ${tipo} en SUNAT para ${nom}?\n\nLa NV original quedará anulada.`, { warning: true, titulo: 'Emitir CPE', okText: 'Emitir' })) return;

    const auth = await pedirAuth({ accion: 'CONVERTIR_NV_A_CPE', refDocumento: t.correlativo || t.idVenta,
      contexto: 'Convertir NV → ' + tipo + ' ' + (t.correlativo || t.idVenta) });
    if (!auth) return;
    const btn = $('tkConvBtnOK');
    if (btn) { btn.disabled = true; btn.textContent = 'Emitiendo...'; }
    try {
      const r = await API.post('meConvertirNVaCPE', {
        idVenta: t.idVenta, tipoDocNuevo: tipo,
        clienteDoc: doc, clienteNom: nom, direccion: dir, claveAdmin: auth.clave
      });
      const dd = (r && r.data) || {};
      // feedback honesto (paridad ME): con estado EMITIDO ya está firmado; PENDIENTE = en cola
      toast(`✓ ${tipo} ${dd.correlativo || ''} ` + (dd.nfEstado === 'EMITIDO' ? '· firmada por SUNAT' : '· en cola de SUNAT (se confirma sola)'), 'success', 5500);
      closeModal('modalTkConvertirCPE');
      await _cajasRefreshSilencioso?.();
      if (S.view === 'finanzas') finCargar?.();
    } catch(e) {
      toast('Error: ' + e.message, 'error');
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = '📤 Emitir CPE en SUNAT'; }
    }
  }

  // ──────────────────────────────────────────────────────────
  // BAJA DEL CPE (comunicación SUNAT)
  // ──────────────────────────────────────────────────────────
  function _tkBajaOpen(t) {
    _tkAcc.baja = { motivo: '' };
    $('tkBajaSub').textContent = (t.correlativo || t.idVenta) + ' · ' + (t.tipoDoc || '');
    document.querySelectorAll('input[name="tkBajaMotivo"]').forEach(r => r.checked = false);
    $('tkBajaMotivoTxt').value = '';
    $('tkBajaBtnOK').disabled = true;
    openModal('modalTkBajaCPE');
  }

  function _tkBajaSetMotivo(v) {
    _tkAcc.baja.motivo = v;
    if (v) $('tkBajaMotivoTxt').value = '';
    _tkBajaActualizarBoton();
  }

  function _tkBajaActualizarBoton() {
    const radio = _tkAcc.baja.motivo;
    const txt   = ($('tkBajaMotivoTxt').value || '').trim();
    const motivoFinal = radio || txt;
    $('tkBajaBtnOK').disabled = (motivoFinal.length < 3);
    _tkAcc.baja.motivoFinal = motivoFinal;
  }

  async function _tkBajaConfirmar() {
    const t = _tkAcc.ticket;
    const motivo = _tkAcc.baja.motivoFinal || _tkAcc.baja.motivo || ($('tkBajaMotivoTxt').value || '').trim();
    if (!motivo || motivo.length < 3) { toast('Motivo obligatorio', 'error'); return; }
    if (!await _modalConfirm(`¿Comunicar baja del ${t.tipoDoc} ${t.correlativo} a SUNAT?\n\nEsta acción es irreversible.`, { danger: true, titulo: 'Baja CPE SUNAT', okText: 'Enviar baja' })) return;
    // [cero-caída] BAJA_CPE es MASTER-only — re-verificada server-side en el Edge emitir-cpe
    const auth = await pedirAuth({ accion: 'BAJA_CPE', refDocumento: t.correlativo || t.idVenta,
      contexto: 'Baja CPE SUNAT ' + (t.tipoDoc || '') + ' ' + (t.correlativo || t.idVenta) });
    if (!auth) return;
    const btn = $('tkBajaBtnOK');
    if (btn) { btn.disabled = true; btn.textContent = 'Enviando...'; }
    try {
      const r = await API.post('meBajaCPE', { idVenta: t.idVenta, motivo, claveAdmin: auth.clave });
      toast('✓ Baja enviada · ' + (r?.nuevoEstado || 'aceptada'), 'success');
      closeModal('modalTkBajaCPE');
      await _cajasRefreshSilencioso?.();
      if (S.view === 'finanzas') finCargar?.();
    } catch(e) {
      toast('Error: ' + e.message, 'error');
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = '📤 Enviar baja a SUNAT'; }
    }
  }

  // ──────────────────────────────────────────────────────────
  // EDITAR CLIENTE (modo prompt rápido — solo NV o pre-CPE)
  // ──────────────────────────────────────────────────────────
  // [UX 500x] Modal ÚNICO de editar cliente (antes eran 3 _modalPrompt secuenciales + salía detrás
  // del layout por z-index). Un solo formulario: doc (auto-detecta DNI/RUC/C.E.) + lookup APISPeru
  // (vía Edge, solo DNI/RUC) + nombre + dirección + motivo. Devuelve {doc,nombre,direccion,motivo,tipoDoc} o null.
  function _modalEditarCliente(t) {
    return new Promise((resolve) => {
      const _esc = (s) => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
      const _tipoDe = (d) => {
        d = String(d || '').trim();
        if (!d) return { cod: 0, lbl: 'Sin doc' };
        if (/^\d{8}$/.test(d))  return { cod: 1, lbl: 'DNI' };
        if (/^\d{11}$/.test(d)) return { cod: 6, lbl: 'RUC' };
        return { cod: 4, lbl: 'C.E./Otro' };   // Carné de Extranjería / Pasaporte / otros
      };
      let ext = false;   // [replica ME] Perú (false) / Extranjero (true)
      let _tmr = null;
      const bd = document.createElement('div');
      bd.className = 'mos-modal-generic-backdrop';
      bd.innerHTML = `
        <div class="mos-modal-generic mos-modal-generic-primary" role="dialog" aria-modal="true">
          <div class="mos-modal-generic-head">
            <span class="mos-modal-generic-ico">👤</span><strong>Editar cliente</strong>
            <button class="mos-modal-generic-close" data-cancel>✕</button>
          </div>
          <div class="mos-modal-generic-body" style="display:flex;flex-direction:column;gap:12px;">
            <div style="display:flex;align-items:center;justify-content:space-between;gap:8px;">
              <label class="mos-modal-generic-label" style="margin:0;">Cliente <span id="ec-tipo" style="font-weight:800;color:#818cf8;"></span></label>
              <div style="display:inline-flex;background:#1e293b;border-radius:999px;padding:3px;font-size:11px;font-weight:800;">
                <button id="ec-pe" type="button" style="padding:4px 10px;border-radius:999px;border:0;cursor:pointer;background:#fff;color:#0f172a;">🇵🇪 Perú</button>
                <button id="ec-ex" type="button" style="padding:4px 10px;border-radius:999px;border:0;cursor:pointer;background:transparent;color:#94a3b8;">🌎 Extranjero</button>
              </div>
            </div>
            <div style="position:relative;">
              <label class="mos-modal-generic-label" id="ec-busq-lbl">Buscar: nombre, DNI (8) o RUC (11)</label>
              <div style="display:flex;gap:8px;">
                <div style="position:relative;flex:1;">
                  <input id="ec-busq" class="mos-modal-generic-input" inputmode="text" maxlength="120" value="" placeholder="nombre o documento" style="width:100%;padding-right:34px;" />
                  <button id="ec-x" type="button" title="Limpiar" style="position:absolute;right:6px;top:50%;transform:translateY(-50%);width:22px;height:22px;border:0;border-radius:999px;background:#334155;color:#cbd5e1;cursor:pointer;display:none;line-height:1;">×</button>
                </div>
                <button id="ec-buscar" type="button" class="mos-modal-generic-btn mos-modal-generic-btn-ghost" title="Buscar en RENIEC/SUNAT" style="white-space:nowrap;">🔎</button>
              </div>
              <div id="ec-sugs" style="display:none;position:absolute;left:0;right:0;top:100%;margin-top:4px;background:#0b1220;border:1px solid #1e293b;border-radius:10px;max-height:200px;overflow:auto;z-index:5;"></div>
            </div>
            <div>
              <label class="mos-modal-generic-label">Documento <span style="opacity:.55;">(DNI/RUC/C.E.)</span></label>
              <input id="ec-doc" class="mos-modal-generic-input" inputmode="text" maxlength="15" value="${_esc(t.clienteDoc || '')}" placeholder="documento" />
            </div>
            <div>
              <label class="mos-modal-generic-label">Nombre / Razón social</label>
              <input id="ec-nom" class="mos-modal-generic-input" maxlength="120" value="${_esc(t.cliente || '')}" placeholder="nombre del cliente" />
            </div>
            <div>
              <label class="mos-modal-generic-label">Dirección <span style="opacity:.55;">(opcional)</span></label>
              <input id="ec-dir" class="mos-modal-generic-input" maxlength="160" value="" placeholder="dirección fiscal" />
            </div>
            <div>
              <label class="mos-modal-generic-label">Motivo del cambio <span style="color:#fb7185;font-weight:700;">* (mín. 3)</span></label>
              <input id="ec-mot" class="mos-modal-generic-input" maxlength="180" value="" placeholder="motivo de la corrección" />
            </div>
          </div>
          <div class="mos-modal-generic-foot">
            <button class="mos-modal-generic-btn mos-modal-generic-btn-ghost" data-cancel>Cancelar</button>
            <button id="ec-ok" class="mos-modal-generic-btn mos-modal-generic-btn-ok mos-modal-generic-btn-primary" disabled style="opacity:.4;cursor:not-allowed;" data-ok>Guardar</button>
          </div>
        </div>`;
      const $$ = (id) => bd.querySelector('#' + id);
      const cerrar = (val) => { bd.classList.remove('is-open'); setTimeout(() => { try { bd.remove(); } catch(_){} }, 200); resolve(val); };
      const refTipo = () => { const ti = ext ? { cod:4, lbl:'C.E./Pasaporte' } : _tipoDe($$('ec-doc').value); $$('ec-tipo').textContent = ti.lbl ? '· ' + ti.lbl : ''; return ti; };
      const validar = () => {
        const mot = ($$('ec-mot').value || '').trim();
        const doc = ($$('ec-doc').value || '').trim();
        const nom = ($$('ec-nom').value || '').trim();
        const ok = mot.length >= 3 && (!!doc || !!nom);
        const b = $$('ec-ok'); b.disabled = !ok; b.style.opacity = ok ? '1' : '.4'; b.style.cursor = ok ? 'pointer' : 'not-allowed';
      };
      const cerrarSugs = () => { const s = $$('ec-sugs'); s.style.display = 'none'; s.innerHTML = ''; };
      const pintarSugs = (arr) => {
        const s = $$('ec-sugs');
        if (!arr || !arr.length) { cerrarSugs(); return; }
        s.innerHTML = arr.map(c => `<div class="ec-sug" data-doc="${_esc(c.documento)}" data-nom="${_esc(c.nombre)}" data-dir="${_esc(c.direccion||'')}" style="padding:8px 10px;cursor:pointer;border-bottom:1px solid #1e293b;display:flex;justify-content:space-between;gap:8px;align-items:center;">
            <span style="font-weight:700;color:#e2e8f0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;">${_esc(c.nombre||'(sin nombre)')}</span>
            <span style="font-family:monospace;font-size:11px;color:#64748b;flex-shrink:0;background:#1e293b;padding:1px 6px;border-radius:999px;">${_esc(c.documento)}</span>
          </div>`).join('');
        s.style.display = 'block';
      };
      const onBusq = () => {
        const v = ($$('ec-busq').value || '').trim();
        $$('ec-x').style.display = v ? 'block' : 'none';
        if (ext) { $$('ec-doc').value = v; refTipo(); cerrarSugs(); validar(); return; }   // extranjero: lo tipeado ES el doc
        if (/^\d{8}$/.test(v) || /^\d{11}$/.test(v)) { $$('ec-doc').value = v; refTipo(); cerrarSugs(); validar(); return; }
        if (v.length < 2) { cerrarSugs(); validar(); return; }
        if (_tmr) clearTimeout(_tmr);
        _tmr = setTimeout(async () => { try { pintarSugs(await API.buscarClientesFrecuentes(v)); } catch(_){ cerrarSugs(); } }, 280);
        validar();
      };
      const elegir = (doc, nom, dir) => {
        $$('ec-doc').value = String(doc||'').trim();
        $$('ec-nom').value = String(nom||'').trim();
        if (dir) $$('ec-dir').value = String(dir);
        $$('ec-busq').value = nom || doc; $$('ec-x').style.display = 'block';
        cerrarSugs(); refTipo(); validar();
      };
      const lookup = async () => {
        const doc = ($$('ec-doc').value || '').trim() || ($$('ec-busq').value || '').trim();
        const ti = _tipoDe(doc);
        if (ext || (ti.cod !== 1 && ti.cod !== 6)) return;   // lookup solo DNI/RUC (APISPeru)
        $$('ec-doc').value = doc;
        const bb = $$('ec-buscar'); const prev = bb.textContent; bb.textContent = '…'; bb.disabled = true;
        try {
          const r = await API.get('meConsultarCliente', { doc });
          const nom = r?.nombre || r?.razon_social || '';
          if (nom) { $$('ec-nom').value = nom; $$('ec-busq').value = nom; $$('ec-x').style.display = 'block'; }
          if (r?.direccion) $$('ec-dir').value = r.direccion;
        } catch(_) {}
        bb.textContent = prev; bb.disabled = false; cerrarSugs(); refTipo(); validar();
      };
      const setExt = (on) => {
        ext = on;
        $$('ec-pe').style.background = on ? 'transparent' : '#fff';  $$('ec-pe').style.color = on ? '#94a3b8' : '#0f172a';
        $$('ec-ex').style.background = on ? '#6366f1' : 'transparent'; $$('ec-ex').style.color = on ? '#fff' : '#94a3b8';
        $$('ec-busq-lbl').textContent = on ? 'C.E. / Pasaporte (alfanumérico)' : 'Buscar: nombre, DNI (8) o RUC (11)';
        $$('ec-busq').placeholder = on ? 'N° de C.E. o Pasaporte' : 'nombre o documento';
        $$('ec-buscar').style.display = on ? 'none' : '';
        $$('ec-busq').value = ''; $$('ec-doc').value = ''; $$('ec-nom').value = ''; $$('ec-dir').value = '';
        $$('ec-x').style.display = 'none'; cerrarSugs(); refTipo(); validar();
      };
      bd.addEventListener('click', (ev) => {
        const tt = ev.target;
        if (tt === bd || (tt.closest && tt.closest('[data-cancel]'))) { cerrar(null); return; }
        if (tt.closest && tt.closest('#ec-pe')) { setExt(false); return; }
        if (tt.closest && tt.closest('#ec-ex')) { setExt(true); return; }
        if (tt.closest && tt.closest('#ec-x')) { $$('ec-busq').value=''; $$('ec-doc').value=''; $$('ec-x').style.display='none'; cerrarSugs(); refTipo(); validar(); try{$$('ec-busq').focus();}catch(_){} return; }
        if (tt.closest && tt.closest('#ec-buscar')) { ev.preventDefault(); lookup(); return; }
        const sg = tt.closest && tt.closest('.ec-sug');
        if (sg) { elegir(sg.getAttribute('data-doc'), sg.getAttribute('data-nom'), sg.getAttribute('data-dir')); return; }
        if (tt.closest && tt.closest('[data-ok]')) {
          const ti = refTipo();
          const doc = ($$('ec-doc').value || '').trim(), nom = ($$('ec-nom').value || '').trim();
          const dir = ($$('ec-dir').value || '').trim(), mot = ($$('ec-mot').value || '').trim();
          if (mot.length < 3 || (!doc && !nom)) return;
          try { _finBeep?.('success'); } catch(_){}
          cerrar({ doc, nombre: nom, direccion: dir, motivo: mot, tipoDoc: ti.cod });
        }
      });
      bd.addEventListener('input', (ev) => {
        if (ev.target.id === 'ec-busq') onBusq();
        else { if (ev.target.id === 'ec-doc') refTipo(); validar(); }
      });
      bd.addEventListener('keydown', (ev) => { if (ev.key === 'Escape') cerrar(null); });
      bd.addEventListener('blur', (ev) => { if (!ext && ev.target.id === 'ec-doc') { const ti = _tipoDe(ev.target.value); if (ti.cod === 1 || ti.cod === 6) lookup(); } }, true);
      document.body.appendChild(bd);
      requestAnimationFrame(() => bd.classList.add('is-open'));
      try { _finBeep?.('tap'); } catch(_){}
      setTimeout(() => { refTipo(); validar(); try { $$('ec-busq').focus(); } catch(_){} }, 220);
    });
  }

