  // ── [v41.3] Cerrar caja forzadamente desde MOS (admin/master) ─────
  // Pide PIN admin 8 dígitos, ejecuta el endpoint atómico de ME que:
  //   1. Anula POR_COBRAR de esa caja
  //   2. Calcula montoFinal automático (apertura + efectivo + ingresos - egresos)
  //   3. Marca CERRADA + montoFinal + fechaCierre con LockService
  //   4. Notifica al cajero original que su caja fue cerrada por admin
  // Resuelve el bug histórico de cierres incompletos sin atomicidad.
  async function cjCerrarCajaForzado(idCaja, nombreCajero) {
    _finBeep('click');
    if (!_esAdminOMaster()) {
      toast('Solo admin/master pueden cerrar caja forzadamente', 'error');
      return;
    }
    // Preview rápida: monto inicial + tickets + por cobrar
    const c = (S._todasCajas || []).find(x => String(x.idCaja) === String(idCaja));
    if (!c) { toast('Caja no encontrada', 'error'); return; }
    const preview = [
      `🔒 CERRAR CAJA FORZADAMENTE`,
      ``,
      `Cajero:        ${c.vendedor || '—'}`,
      `Zona/Estación: ${c.zona || c.estacion || '—'}`,
      `Apertura:      ${c.fechaApertura || '—'}`,
      `Monto inicial: S/ ${parseFloat(c.montoInicial || 0).toFixed(2)}`,
      ``,
      `Tickets:       ${c.tickets || 0}`,
      `Efectivo:      S/ ${parseFloat(c.efectivo || 0).toFixed(2)}`,
      `Por cobrar:    ${c.sinCobrar || 0}  ← vuelven a mesa créditos`,
      ``,
      `Efectivo esperado: S/ ${parseFloat(c.efectivoEsperado || 0).toFixed(2)}`,
      ``,
      `Se cerrará en ME y el cajero recibirá un push.`
    ].join('\n');
    if (!await _modalConfirm(preview, { danger: true, titulo: '🔐 Cerrar caja forzado', okText: 'Cerrar caja' })) return;

    // [v2.41.83] AdminAuthModal universal — tier 3 (sin cache, crítico)
    const auth = await pedirAuth({
      accion: 'CIERRE_CAJA_FORZADO',
      refDocumento: idCaja,
      contexto: `Cerrar caja de ${c.vendedor || '?'} (${c.zona || c.estacion || '—'})`
    });
    if (!auth) return;
    const clave = auth.clave;
    // Loading visual: deshabilitar botón
    const cardBtn = document.querySelector(`#cjcard-${idCaja} .cj-caja-btn-danger`);
    if (cardBtn) { cardBtn.disabled = true; cardBtn.textContent = '⌛ Cerrando...'; }
    try {
      const r = await API.post('meCerrarCajaForzado', {
        idCaja:     idCaja,
        claveAdmin: clave,
        motivo:     'Cierre forzado desde MOS/Cajas'
      });
      const d = (r && r.data) ? r.data : (r || {});
      if (!d.autorizado) {
        toast(d.error || 'Clave incorrecta', 'error');
        return;
      }
      try { _finBeep?.('success'); } catch(_){}
      let msg;
      if (d.yaCerrada) {
        // Caja ya estaba cerrada — reportar si se reparó la guía
        msg = d.guiaRegenerada
          ? `✓ Caja ya cerrada · Guía SALIDA_VENTAS regenerada (faltaba del cierre original)`
          : `✓ Caja ya estaba cerrada · Guía ya existía`;
      } else {
        // [v2.42.00] devueltosACredito reemplaza al legacy "anulados"
        const devN = d.devueltosACredito !== undefined ? d.devueltosACredito : (d.anulados || 0);
        const cobN = d.cobrosLiberados || 0;
        msg = [
          `🔒 Caja cerrada por ${d.cerradoPor || 'admin'}`,
          `Monto final: S/ ${parseFloat(d.montoFinal || 0).toFixed(2)}`,
          devN > 0
            ? `${devN} ticket(s) → mesa créditos${cobN ? ` · ${cobN} cobro(s) liberados` : ''}`
            : 'Sin POR_COBRAR pendientes'
        ].join(' · ');
      }
      toast(msg, 'success');
      // [v41.7] Disparar impresión del Ticket Z en la impresora original de
      // la caja. PrintNode_ID quedó guardado al abrir caja en CAJAS col 10.
      // Si no hay impresora asociada o la impresora está offline, avisamos
      // pero el cierre lógico ya quedó hecho.
      if (d.printNodeId) {
        try {
          const rImp = await API.post('imprimirTicketZCierre', {
            idCaja:    d.idCaja || idCaja,
            printerId: d.printNodeId,
            estacion:  d.estacion || ''
          });
          const dImp = (rImp && rImp.data) ? rImp.data : (rImp || {});
          if (dImp.ok) {
            setTimeout(() => toast('🖨 Ticket Z enviado a impresora de ' + (d.estacion || 'la caja'), 'success'), 600);
          } else {
            setTimeout(() => toast('⚠ Cierre OK · impresión falló: ' + (dImp.error || 'PrintNode rechazó'), 'warn'), 600);
          }
        } catch(eImp) {
          setTimeout(() => toast('⚠ Cierre OK · impresión falló: ' + (eImp.message || eImp), 'warn'), 600);
        }
      } else {
        setTimeout(() => toast('⚠ Cierre OK · sin impresora asociada a esta caja', 'warn'), 600);
      }
      // Refrescar lista de cajas para que la caja pase a CERRADA en la UI
      setTimeout(() => _cajasRefreshSilencioso?.(), 400);
    } catch(e) {
      toast('Error: ' + (e.message || e), 'error');
    } finally {
      if (cardBtn) { cardBtn.disabled = false; cardBtn.textContent = '🔒 Cerrar caja'; }
    }
  }

  // ── MODO TV fullscreen ──────────────────────────
  function cjModoTV(activar) {
    if (typeof activar === 'undefined') activar = !_cjState.tvActivo;
    _cjState.tvActivo = activar;
    document.body.classList.toggle('cj-modo-tv', activar);
    if (activar) {
      _finBeep('breakeven');
      try { document.documentElement.requestFullscreen?.(); } catch {}
      // Re-render para llenar el strip TV (Ranking/7d/Actividad duplicados)
      _cjRender();
      // Auto-actualización cada 15s en TV (más agresivo)
      if (_cjState.tvAutoTimer) clearInterval(_cjState.tvAutoTimer);
      _cjState.tvAutoTimer = setInterval(() => {
        if (typeof _cajasRefreshSilencioso === 'function') _cajasRefreshSilencioso();
      }, 15000);
    } else {
      _finBeep('click');
      try { if (document.fullscreenElement) document.exitFullscreen?.(); } catch {}
      if (_cjState.tvAutoTimer) { clearInterval(_cjState.tvAutoTimer); _cjState.tvAutoTimer = null; }
    }
  }

  // Atajo ESC para salir TV
  document.addEventListener('keydown', e => {
    if (e.key === 'Escape' && _cjState.tvActivo) cjModoTV(false);
    if (S.view === 'cajas') {
      const tag = (document.activeElement?.tagName || '').toLowerCase();
      if (tag === 'input' || tag === 'textarea' || tag === 'select') return;
      if (e.key === 'ArrowLeft')  { e.preventDefault(); cjDia(-1); }
      if (e.key === 'ArrowRight') { e.preventDefault(); cjDia(+1); }
      if (e.key === ' ') { e.preventDefault(); cjIrHoy(); }
    }
  });

  // ── CAJAS ────────────────────────────────────────────────────
  async function loadCajas(force) {
    if (!force && S.loaded['cajas']) return;
    S.loaded['cajas'] = true;

    const loading  = $('cajasLoading');
    const content  = $('cajasContent');

    // Inicializar fecha del módulo si no está
    const inpF = $('cjFecha');
    if (inpF && !inpF.value) inpF.value = today();
    if (!_cjState.fecha) _cjState.fecha = inpF?.value || today();

    // Sonido al entrar al módulo
    _finBeep('nav');

    // [v41] Precarga de créditos pendientes en paralelo al fetch principal.
    // Así cuando se renderice la vista, las cartas ya están listas sin delay.
    if (!_cjCreditosState.todosLosGrupos.length) {
      _cjCargarCreditosPendientes();
    }

    // Datos en cache → render inmediato
    if (S._cajasLoaded && S._todasCajas) {
      loading?.classList.add('hidden');
      content?.classList.remove('hidden');
      _cjRender();
      if (force) _cajasRefreshSilencioso();
      return;
    }

    loading?.classList.remove('hidden');
    content?.classList.add('hidden');

    try {
      const res = await API.get('getCierresCaja', {});
      loading?.classList.add('hidden');
      content?.classList.remove('hidden');

      const { kpis, abiertas = [], cerradas = [], generadoEn, todosTickets: tkAll = [] } = res || {};
      const todayStr = today();
      S._cajasHoy = [
        ...abiertas,
        ...(cerradas || []).filter(c =>
          (c.fechaApertura || '').startsWith(todayStr) ||
          (c.fechaCierre   || '').startsWith(todayStr)
        )
      ];
      S._todasCajas = [...abiertas, ...cerradas];
      S._todosTickets = tkAll;
      _cjMergeHist();   // [fix bug] preservar días históricos jalados (no vaciar al recargar)
      S._cajasGenTs = generadoEn || '';
      S._cajasLoaded = true;

      _cjRender();
      _cjPulsoPoll();

    } catch(e) {
      loading?.classList.add('hidden');
      content?.classList.remove('hidden');
      const empty = $('cajasEmpty');
      empty?.classList.remove('hidden');
      if (empty) empty.innerHTML = `<div class="text-4xl mb-3">⚠️</div><div class="text-red-400 font-medium mb-1">Error al cargar</div><div class="text-xs text-slate-500">${e.message}</div>`;
      S.loaded['cajas'] = false;
    }
  }

  // ── Auto-refresh silencioso de cajas cada 60s ───────────────
  let _cajasRefreshTimer = null;

  // ── Construye el HTML de una card de caja abierta (LEGACY) ──
  // Reemplazado por _cjBuildCajaCard. Si algo aún llama a _buildCajaCard
  // (código viejo), redirigir al nuevo.
  function _buildCajaCard(c) {
    return _cjBuildCajaCard(c, c.estado === 'ABIERTA', _cjFecha());
  }

  // Helper: actualizar texto de un elemento solo si cambió, con flash opcional
  function _setVal(id, newVal, flash) {
    const el = $(id); if (!el) return;
    const str = String(newVal);
    if (el.textContent === str) return;
    el.textContent = str;
    if (flash) { el.classList.remove('val-flash'); el.offsetHeight; el.classList.add('val-flash'); }
  }

  // Smart update de una card de caja abierta (solo toca los valores que cambiaron)

  // Smart update del historial (filas cerradas)

  // [v2.41.91] Snapshot del esperado por caja para detectar cruces de hitos
  if (typeof window._cjBalancePrev === 'undefined') window._cjBalancePrev = {};
  const HITOS_MARKS = [500, 1000, 2000, 3000, 5000];

  function _cjDetectarHitos(abiertasActual) {
    abiertasActual.forEach(c => {
      const id = String(c.idCaja || '');
      if (!id) return;
      const actual = parseFloat(c.efectivoEsperado) || 0;
      const previo = window._cjBalancePrev[id] || 0;
      window._cjBalancePrev[id] = actual;
      // Detectar cruces de hito (sube de previo<H a actual>=H)
      HITOS_MARKS.forEach(mark => {
        if (previo > 0 && previo < mark && actual >= mark) {
          _cjCelebrarHito(c, mark);
        }
      });
      // Animar monto (clase .bump) si cambió
      if (Math.abs(actual - previo) >= 0.01 && previo > 0) {
        setTimeout(() => {
          const card = document.getElementById('cjcard-' + id.replace(/'/g, '&#39;'));
          if (card) {
            const monto = card.querySelector('.cj-balance-live-monto');
            if (monto) {
              monto.classList.remove('bump');
              void monto.offsetWidth; // force reflow
              monto.classList.add('bump');
            }
          }
        }, 100);
      }
    });
  }

  function _cjCelebrarHito(c, mark) {
    try { _finBeep && _finBeep('jackpot'); } catch(_) {
      try { _finBeep && _finBeep('success'); } catch(__) {}
    }
    // Confetti micro en la card del cajero
    setTimeout(() => {
      const card = document.getElementById('cjcard-' + String(c.idCaja || '').replace(/'/g, '&#39;'));
      if (!card) return;
      // 18 partículas de confetti animadas
      for (let i = 0; i < 18; i++) {
        const conf = document.createElement('div');
        conf.className = 'cj-confetti-particle';
        conf.style.left = (50 + (Math.random() - 0.5) * 60) + '%';
        conf.style.background = ['#fbbf24','#34d399','#22d3ee','#ec4899','#a78bfa','#f97316'][i % 6];
        conf.style.setProperty('--dx', ((Math.random() - 0.5) * 220) + 'px');
        conf.style.setProperty('--dy', (140 + Math.random() * 160) + 'px');
        conf.style.animationDelay = (Math.random() * .25) + 's';
        card.appendChild(conf);
        setTimeout(() => { try { conf.remove(); } catch(_){} }, 2400);
      }
    }, 100);
    if (typeof toast === 'function') {
      toast(`🎉 ${c.vendedor || 'Cajero'} cruzó S/ ${mark.toLocaleString('es-PE')}`, 'success');
    }
  }

  // [fix cascada] coalescing: al asignar/confirmar/vender se disparaban varios refrescos pesados a la vez
  // (optimista + en-vuelo + créditos + realtime ventas) → el _cjRender() reconstruía todo repetido =
  // "rallado" (animación reiniciada) + parpadeo de adeudados + postit destruido bajo el cursor. Ahora
  // como máximo 1 refresco en vuelo + 1 en cola, y throttle 2.5s. El poll de 20s y el realtime se coalescen.
  let _cjRefBusy = false, _cjRefPend = false, _cjRefTs = 0;
  async function _cajasRefreshSilencioso() {
    if (!API.isConfigured()) return;
    if (_cjRefBusy) { _cjRefPend = true; return; }          // ya hay uno corriendo → encolar UNO
    const since = Date.now() - _cjRefTs;
    if (since < 2500) {                                       // muy seguido → programar trailing coalescido
      if (!_cjRefPend) { _cjRefPend = true; setTimeout(() => { _cjRefPend = false; _cajasRefreshSilencioso(); }, 2500 - since); }
      return;
    }
    _cjRefBusy = true;
    iconBusy('cajas', true);
    try {
      const res = await API.get('getCierresCaja', {});
      const { abiertas = [], cerradas = [], todosTickets: tkAll = [], generadoEn } = res || {};
      const todayStr = today();
      // Detectar tickets nuevos comparando con cache previo
      const prevIds = new Set((S._todosTickets || []).map(t => t.idVenta));
      const nuevos = (tkAll || []).filter(t => !prevIds.has(t.idVenta));
      S._todosTickets = tkAll;
      S._cajasHoy = [...abiertas, ...(cerradas || []).filter(c =>
        (c.fechaApertura || '').startsWith(todayStr) || (c.fechaCierre || '').startsWith(todayStr))];
      S._todasCajas  = [...abiertas, ...cerradas];
      _cjMergeHist();   // [fix bug] re-inyectar histórico tras la recarga
      S._cajasLoaded = true;
      S._cajasGenTs  = generadoEn || '';
      // [v2.41.91] Detectar cruces de hitos antes de re-renderizar
      _cjDetectarHitos(abiertas);
      if (S.view === 'cajas') {
        _cjRender();
        _cjPulsoPoll();
        const modalTk = $('cjModalTickets');
        if (modalTk && !modalTk.classList.contains('hidden')) _cjTkRender();
        // Sonido sutil si hay tickets nuevos
        if (nuevos.length > 0 && prevIds.size > 0) _finBeep('click');
        // [v41] Refresh paralelo de créditos: si hay uno nuevo, _cjPintarCartasMano
        // lo detecta vía idsVistos y lo anima con cj-carta-nueva.
        _cjCargarCreditosPendientes();
      }
    } catch(e) { console.warn('[CajasRefresh]', e.message); }
    finally {
      _cjRefBusy = false; _cjRefTs = Date.now(); iconBusy('cajas', false);
      if (_cjRefPend) { _cjRefPend = false; setTimeout(_cajasRefreshSilencioso, 120); }  // corre el coalescido
    }
  }

  function _startCajasRefresh() {
    _stopCajasRefresh();
    _cajasRefreshSilencioso(); // fetch inmediato
    _cajasRefreshTimer = setInterval(_cajasRefreshSilencioso, 20000);
  }
  function _stopCajasRefresh() {
    if (_cajasRefreshTimer) { clearInterval(_cajasRefreshTimer); _cajasRefreshTimer = null; }
    try { _cjSinCajaStop(); } catch (_) {}   // [500x F1] frenar el giro del deck sin-caja al salir de Cajas
  }

  // ── Charts de cajas ─────────────────────────────────────────
  const _CHART_COLORES = ['#6366f1','#f59e0b','#0ea5e9','#a855f7','#ef4444','#14b8a6','#f97316'];
  let _chartCajasPeriodo      = 7;
  let _chartCajasModalPeriodo = 7;

  function _cajasFiltradas(dias) {
    const todas  = S._todasCajas || [];
    const desde  = _fechaOffset(today(), -dias);
    return todas.filter(c =>
      (c.fechaApertura || '').substring(0, 10) >= desde ||
      (c.fechaCierre   || '').substring(0, 10) >= desde
    );
  }

  // Chart compacto: barras verticales, eje X = cajeros, agrupado por vendedor
  function _renderChartCajasCompacto(dias) {
    const cajas    = _cajasFiltradas(dias);
    const hoy      = today();
    const byVend   = {};
    cajas.forEach(c => {
      const k = c.vendedor || c.idCaja;
      if (!byVend[k]) byVend[k] = { total: 0, active: false };
      byVend[k].total += c.totalVentas;
      if (c.estado === 'ABIERTA') byVend[k].active = true;
    });
    const labels = Object.keys(byVend);
    const data   = labels.map(k => Math.round(byVend[k].total * 100) / 100);
    const colors = labels.map(k => byVend[k].active ? '#22c55e' : '#6366f1');

    renderChart('chartCajasBars', {
      type: 'bar',
      data: { labels, datasets: [{ data, backgroundColor: colors, borderRadius: 5, barThickness: 32 }] },
      options: {
        responsive: true, maintainAspectRatio: false,
        plugins: {
          legend: { display: false },
          tooltip: {
            callbacks: {
              title: ctx => ctx[0].label,
              label: ctx => ` S/. ${ctx.raw.toFixed(2)}`,
              afterLabel: ctx => {
                const v    = labels[ctx.dataIndex];
                const cajs = _cajasFiltradas(dias).filter(c => (c.vendedor || c.idCaja) === v);
                const ef   = cajs.reduce((s,c) => s + c.efectivo, 0);
                const virt = cajs.reduce((s,c) => s + c.otros, 0);
                const tk   = cajs.reduce((s,c) => s + c.tickets, 0);
                return [` Efectivo: S/.${ef.toFixed(2)}`, ` Virtual:  S/.${virt.toFixed(2)}`, ` Tickets: ${tk}`];
              }
            }
          }
        },
        scales: {
          y: { ticks: { callback: v => 'S/' + v, font: { size: 10 }, color: '#64748b' }, grid: { color: '#1e293b' } },
          x: { ticks: { font: { size: 11 }, color: '#94a3b8' }, grid: { display: false } }
        }
      }
    });
  }

  // Chart modal: barras apiladas, eje X = fechas (días), por cajero
  function _renderChartCajasModal(dias) {
    const cajas  = _cajasFiltradas(dias);
    const hoy    = today();

    // Generar rango de fechas
    const dates = [];
    for (let d = dias - 1; d >= 0; d--) {
      dates.push(_fechaOffset(today(), -d));
    }

    // Cajas por fecha
    const cajasByDate = {};
    cajas.forEach(c => {
      const f = (c.fechaApertura || c.fechaCierre || '').substring(0, 10);
      if (!cajasByDate[f]) cajasByDate[f] = [];
      cajasByDate[f].push(c);
    });

    // Vendedores únicos
    const vendedores = [...new Set(cajas.map(c => c.vendedor || c.idCaja))];

    const datasets = vendedores.map((v, i) => ({
      label: v,
      data: dates.map(d => {
        const cs = (cajasByDate[d] || []).filter(c => (c.vendedor || c.idCaja) === v);
        return Math.round(cs.reduce((s,c) => s + c.totalVentas, 0) * 100) / 100;
      }),
      backgroundColor: dates.map(d => {
        if (d !== hoy) return _CHART_COLORES[i % _CHART_COLORES.length] + '99';
        const cs = (cajasByDate[d] || []).filter(c => (c.vendedor || c.idCaja) === v);
        return cs.some(c => c.estado === 'ABIERTA') ? '#22c55e' : _CHART_COLORES[i % _CHART_COLORES.length];
      }),
      borderRadius: 3,
      stack: 'cajas'
    }));

    renderChart('chartCajasModal', {
      type: 'bar',
      data: {
        labels: dates.map(d => {
          const day = parseInt(d.substring(8));
          return d === hoy ? day + '*' : String(day);
        }),
        datasets
      },
      options: {
        responsive: true, maintainAspectRatio: false,
        plugins: {
          legend: { position: 'bottom', labels: { font:{ size:10 }, padding:8, boxWidth:10, color:'#94a3b8' } },
          tooltip: {
            mode: 'index', intersect: false,
            callbacks: {
              title: ctx => {
                const d = dates[ctx[0].dataIndex];
                return d === hoy ? `Hoy ${d}` : d;
              },
              label: ctx => ctx.raw > 0 ? ` ${ctx.dataset.label}: ${fmtMoney(ctx.raw)}` : null,
              footer: ctx => {
                const total = ctx.reduce((s,c) => s + c.raw, 0);
                return total > 0 ? `Total del día: ${fmtMoney(total)}` : '';
              }
            }
          }
        },
        scales: {
          y: { stacked: true, ticks: { callback: v => 'S/' + v, font:{ size:10 }, color:'#64748b' }, grid:{ color:'#1e293b' } },
          x: { stacked: true, ticks: { font:{ size:11 }, color:'#94a3b8' }, grid:{ display:false } }
        }
      }
    });
  }



  function setChartCajasModalPeriodo(dias) {
    _chartCajasModalPeriodo = dias;
    [7, 30, 90].forEach(d => {
      const el = $('ccm' + d); if (el) el.classList.toggle('active', d === dias);
    });
    _renderChartCajasModal(dias);
  }


  function cerrarModalHistorialCajas() {
    const modal = $('modalHistorialCajas'); if (modal) modal.classList.add('hidden');
  }

  // ── Historial de tickets ────────────────────────────────────
  let _tkFiltroFecha  = 'hoy';
  let _tkFiltroEstado = '';
  let _tkFiltroTipo   = '';
  let _modalTicketId  = null;





  function _renderTicketList() {
    const container = $('cajasTicketsList');
    if (!container) return;
    const hoy    = today();
    const semana = _fechaOffset(today(), -7);
    const mes    = _fechaOffset(today(), -30);
    const desde  = _tkFiltroFecha === 'hoy' ? hoy : _tkFiltroFecha === 'semana' ? semana : _tkFiltroFecha === 'mes' ? mes : '0000-00-00';

    let lista = (S._todosTickets || []).filter(t => {
      if (t.fecha < desde) return false;
      if (_tkFiltroEstado && t.estado !== _tkFiltroEstado) return false;
      if (_tkFiltroTipo   && t.tipo   !== _tkFiltroTipo)   return false;
      return true;
    });

    if (!lista.length) {
      container.innerHTML = '<div class="text-xs text-slate-600 py-4 text-center">Sin tickets para los filtros seleccionados</div>';
      return;
    }

    const metodoBadge = m => {
      const cls = m === 'EFECTIVO' ? 'badge-green' : m === 'POR_COBRAR' ? 'badge-yellow' : m === 'ANULADO' ? 'badge-red' : 'badge-blue';
      return `<span class="badge ${cls}" style="font-size:10px">${m}</span>`;
    };
    const estadoIcon = s => s === 'ANULADO' ? '🚫' : s === 'POR_COBRAR' ? '⏳' : s === 'CREDITO' ? '💳' : '✅';
    const tipoIcon   = t => t === 'F' ? '📋' : t === 'B' ? '📄' : '🧾';

    container.innerHTML = lista.map(t => {
      const anulado = t.estado === 'ANULADO';
      const label   = t.correlativo || t.idVenta;
      const esHoy   = t.fecha === hoy;
      const fechaStr = esHoy ? `hoy ${t.hora}` : `${t.fecha} ${t.hora}`;
      return `
      <div data-ticket-id="${t.idVenta}" class="border-b border-slate-800/60 py-2.5 ${anulado ? 'opacity-50' : ''}">
        <div class="flex items-start justify-between gap-2">
          <div class="flex-1 min-w-0">
            <div class="flex items-center gap-1.5 flex-wrap">
              <span class="text-sm">${tipoIcon(t.tipo)}</span>
              <span class="text-xs font-mono font-semibold ${anulado ? 'line-through text-slate-500' : 'text-slate-200'}">${label}</span>
              <span class="text-xs text-slate-600">${fechaStr}</span>
            </div>
            <div class="text-xs text-slate-500 mt-0.5 truncate">
              ${estadoIcon(t.estado)} ${t.vendedor || '—'} · ${t.zona || '—'}
              ${t.clienteNom ? ' · ' + t.clienteNom : t.clienteDoc ? ' · ' + t.clienteDoc : ''}
            </div>
          </div>
          <div class="text-right shrink-0">
            <div class="text-sm font-bold ${anulado ? 'line-through text-slate-600' : 'text-white'}">${fmtMoney(t.total)}</div>
            <div class="mt-0.5">${metodoBadge(t.metodo)}</div>
          </div>
        </div>
        <!-- Botones de acción -->
        ${!anulado ? `
        <div class="flex gap-1.5 mt-1.5">
          <button onclick="MOS.confirmarAnularTicket('${t.idVenta}','${label}')"
            class="text-xs px-2.5 py-1 rounded-md border border-red-900/50 text-red-400 hover:bg-red-900/20 transition-colors">
            🚫 Anular
          </button>
          <button onclick="MOS.abrirModalMetodo('${t.idVenta}','${label}','${t.metodo}',${t.total})"
            class="text-xs px-2.5 py-1 rounded-md border border-slate-700 text-slate-400 hover:border-indigo-600 hover:text-indigo-400 transition-colors">
            💳 Cambiar método
          </button>
        </div>` : ''}
      </div>`;
    }).join('');
  }

  async function confirmarAnularTicket(idVenta, label, desdeModal) {
    if (!idVenta) { toast('ID de ticket inválido', 'error'); return; }
    if (!await _modalConfirm(`¿Anular el ticket ${label}?\n\nEsta acción no se puede deshacer.`, { danger: true, titulo: 'Anular ticket', okText: 'Anular' })) return;
    const auth = await pedirAuth({ accion: 'ANULACION', refDocumento: label || idVenta, contexto: 'Anular ticket ' + (label || idVenta) });
    if (!auth) return;
    if (desdeModal) cerrarModalMetodo();
    const id = String(idVenta).trim();
    try {
      await API.post('anularTicketME', { idVenta: id, claveAdmin: auth.clave });
      toast('Ticket anulado', 'ok');
      // Actualizar local inmediatamente
      if (S._todosTickets) {
        S._todosTickets.forEach(t => {
          if (String(t.idVenta).trim() === id) { t.metodo = 'ANULADO'; t.estado = 'ANULADO'; }
        });
      }
      _renderTicketList();
      setTimeout(() => _cajasRefreshSilencioso(), 1000);
    } catch(e) { toast(e.message, 'error'); }
  }

  // ── Modal cambiar método (replica flujo ME) ─────────────────
  let _modalTicketTotal  = 0;
  let _modalMetodoSel    = 'EFECTIVO';
  let _modalLabel        = '';

  function abrirModalMetodo(idVenta, label, metodoActual, total) {
    if (!idVenta) { toast('ID de ticket inválido', 'error'); return; }
    _modalTicketId    = String(idVenta).trim();
    _modalLabel       = label || idVenta;
    _modalTicketTotal = parseFloat(total) || 0;
    // Si no viene total buscar en S._todosTickets
    if (!_modalTicketTotal) {
      const tk = (S._todosTickets || []).find(t => String(t.idVenta).trim() === _modalTicketId);
      if (tk) _modalTicketTotal = tk.total;
    }
    _modalMetodoSel = metodoActual === 'POR_COBRAR' ? 'EFECTIVO' : (metodoActual || 'EFECTIVO');
    _renderModalMetodo();
    const modal = $('modalCambiarMetodo');
    if (modal) modal.classList.remove('hidden');
  }

  function _renderModalMetodo() {
    const box = $('modalCambiarMetodoBox');
    if (!box) return;
    const total = _modalTicketTotal;
    const sel   = _modalMetodoSel;

    // Sección dinámica según método seleccionado
    let seccion = '';
    if (sel === 'MIXTO') {
      const virt = parseFloat($('mmVirtual')?.value) || 0;
      const efec = Math.max(0, total - virt);
      const valido = virt > 0 && virt < total;
      seccion = `
        <div class="mt-3 space-y-2">
          <div>
            <label class="lbl text-sky-400">📲 Monto virtual (S/.)</label>
            <input id="mmVirtual" type="number" step="0.10" min="0.01" max="${(total - 0.01).toFixed(2)}"
              placeholder="0.00" value="${virt || ''}"
              oninput="MOS._onMixtoInput()"
              class="inp text-center text-xl font-bold" style="border-color:#7c3aed">
            ${virt > 0 && virt >= total ? '<p class="text-xs text-amber-400 mt-1">El monto virtual cubre el total — usa VIRTUAL</p>' : ''}
          </div>
          <div class="flex justify-between items-center px-1 py-1.5 rounded-lg" style="background:#0d1526">
            <span class="text-sm text-slate-400">💵 Efectivo</span>
            <span class="text-lg font-bold ${efec > 0 ? 'text-emerald-400' : 'text-slate-600'}">S/. ${efec.toFixed(2)}</span>
          </div>
          <button onclick="MOS.aplicarCambioMetodo('MIXTO')" ${!valido ? 'disabled' : ''}
            class="w-full py-3.5 rounded-xl font-bold text-sm transition-all ${valido ? 'bg-purple-600 hover:bg-purple-500 text-white' : 'bg-slate-800 text-slate-600 cursor-not-allowed'}">
            Confirmar MIXTO · S/. ${total.toFixed(2)}
          </button>
        </div>`;
    } else if (sel === 'EFECTIVO') {
      seccion = `
        <div class="mt-3">
          <div class="flex justify-between items-center px-3 py-3 rounded-xl mb-3" style="background:#0d1526">
            <span class="text-slate-400">💵 Cobrar en efectivo</span>
            <span class="text-xl font-bold text-emerald-400">S/. ${total.toFixed(2)}</span>
          </div>
          <button onclick="MOS.aplicarCambioMetodo('EFECTIVO')"
            class="w-full py-3.5 rounded-xl font-bold text-sm bg-emerald-700 hover:bg-emerald-600 text-white transition-all">
            Confirmar EFECTIVO · S/. ${total.toFixed(2)}
          </button>
        </div>`;
    } else { // VIRTUAL
      seccion = `
        <div class="mt-3">
          <div class="flex justify-between items-center px-3 py-3 rounded-xl mb-3" style="background:#0d1526">
            <span class="text-slate-400">📲 Cobro virtual</span>
            <span class="text-xl font-bold text-sky-400">S/. ${total.toFixed(2)}</span>
          </div>
          <button onclick="MOS.aplicarCambioMetodo('VIRTUAL')"
            class="w-full py-3.5 rounded-xl font-bold text-sm bg-sky-700 hover:bg-sky-600 text-white transition-all">
            Confirmar VIRTUAL · S/. ${total.toFixed(2)}
          </button>
        </div>`;
    }

    const metodoBtns = ['EFECTIVO','VIRTUAL','MIXTO'].map(m => {
      const cfg = { EFECTIVO:{icon:'💵',active:'border-emerald-500 text-emerald-400 bg-emerald-900/20'},
                    VIRTUAL: {icon:'📲',active:'border-sky-500 text-sky-400 bg-sky-900/20'},
                    MIXTO:   {icon:'🔀',active:'border-purple-500 text-purple-400 bg-purple-900/20'} }[m];
      const cls = (m === sel) ? cfg.active : 'border-slate-700 text-slate-500 hover:border-slate-500 hover:text-slate-300';
      return `<button onclick="MOS._selMetodo('${m}')"
        class="flex flex-col items-center justify-center gap-1.5 py-4 rounded-xl border-2 transition-all ${cls}">
        <span class="text-xl">${cfg.icon}</span>
        <span class="text-xs font-bold tracking-wide">${m}</span>
      </button>`;
    }).join('');

    box.innerHTML = `
      <div class="flex items-center justify-between mb-3">
        <div>
          <div class="font-semibold text-slate-200">Cambiar método de pago</div>
          <div class="text-xs text-slate-500 mt-0.5 font-mono">${_modalLabel}</div>
        </div>
        <button onclick="MOS.cerrarModalMetodo()" class="text-slate-600 hover:text-slate-300 text-xl leading-none">✕</button>
      </div>

      <!-- Total prominente -->
      <div class="rounded-xl p-3 mb-4 text-center" style="background:#0d1526;border:1px solid #1e293b">
        <div class="text-xs text-slate-500 uppercase tracking-widest mb-1">Total a cobrar</div>
        <div class="text-3xl font-black text-white">S/. ${total.toFixed(2)}</div>
      </div>

      <!-- 3 botones método -->
      <div class="grid grid-cols-3 gap-2">${metodoBtns}</div>

      <!-- Sección dinámica -->
      ${seccion}

      <!-- Anular -->
      <div class="mt-3 pt-3 border-t border-slate-800">
        <button onclick="MOS.confirmarAnularTicket('${_modalTicketId}','${_modalLabel}',true)"
          class="w-full py-2.5 rounded-xl text-sm font-semibold border border-red-900/50 text-red-400 hover:bg-red-900/20 transition-all">
          🚫 Anular ticket
        </button>
      </div>`;
  }

  function _selMetodo(m) {
    _modalMetodoSel = m;
    _renderModalMetodo();
    // Focus en input virtual si es MIXTO
    if (m === 'MIXTO') setTimeout(() => $('mmVirtual')?.focus(), 50);
  }

  function _onMixtoInput() { _renderModalMetodo(); }

  function cerrarModalMetodo() {
    const modal = $('modalCambiarMetodo'); if (modal) modal.classList.add('hidden');
    _modalTicketId = null;
  }

  async function aplicarCambioMetodo(metodo) {
    if (!_modalTicketId) return;
    const id = _modalTicketId;
    const auth = await pedirAuth({ accion: 'COBRAR_VENTA', refDocumento: id, contexto: 'Cambiar método de pago a ' + metodo });
    if (!auth) return;
    cerrarModalMetodo();
    try {
      await API.post('cambiarMetodoME', { idVenta: id, metodo, claveAdmin: auth.clave });
      toast('Método actualizado: ' + metodo, 'ok');
      if (S._todosTickets) {
        S._todosTickets.forEach(t => {
          if (String(t.idVenta).trim() === id) { t.metodo = metodo; t.estado = 'COMPLETADO'; }
        });
      }
      _renderTicketList();
      setTimeout(() => _cajasRefreshSilencioso(), 1200);
    } catch(e) { toast(e.message, 'error'); }
  }


  async function toggleCajaDetail(idCaja) {
    const detail    = $('cajadetail-' + idCaja);
    const iconEl    = $('cajabtn-icon-'  + idCaja);
    const labelEl   = $('cajabtn-label-' + idCaja);
    const headerLbl = $('cajatickets-label-' + idCaja);
    if (!detail) return;

    const opening = detail.classList.contains('hidden');
    detail.classList.toggle('hidden', !opening);

    if (!opening) {
      // Cerrando
      if (iconEl)  iconEl.textContent  = '▼';
      if (labelEl) {
        const rows = detail.querySelectorAll('[data-ticket-row]').length;
        labelEl.textContent = `Ver ${rows || ''} ticket${rows !== 1 ? 's' : ''}`;
      }
      return;
    }

    // Abriendo → refresh silencioso de esta caja
    if (iconEl) { iconEl.innerHTML = '<span class="spin" style="display:inline-block;font-size:13px">↻</span>'; iconEl.style.animation = ''; }
    if (labelEl) labelEl.textContent = 'Actualizando…';

    try {
      const res = await API.get('getCierresCaja', {});
      const { abiertas = [], cerradas = [], todosTickets: tkAll = [],
              kpis, kpisTickets = {}, generadoEn } = res || {};

      // Actualizar estado global silencioso
      S._todosTickets = tkAll;
      const todayStr  = today();
      S._todasCajas   = [...abiertas, ...cerradas];
      _cjMergeHist();   // [fix bug] re-inyectar histórico tras la recarga silenciosa
      S._cajasHoy     = [...abiertas, ...(cerradas || []).filter(c =>
        (c.fechaApertura || '').startsWith(todayStr) || (c.fechaCierre || '').startsWith(todayStr))];

      // KPIs
      const setQ = (id, v) => { const el=$(id); if(el) el.textContent = v; };
      setQ('cajasKpiVentas',     fmtMoney(kpis?.totalDia || 0));
      setQ('cajasKpiTicketsHoy', kpisTickets.hoy?.total || 0);
      setQ('cajasKpiTicketsMes', kpisTickets.mes?.total || 0);
      setQ('cajasKpiNV',         kpisTickets.hoy?.NV    || 0);
      setQ('cajasKpiBoleta',     kpisTickets.hoy?.B     || 0);
      setQ('cajasKpiFactura',    kpisTickets.hoy?.F     || 0);
      const ts = $('cajasTimestamp');
      if (ts) ts.textContent = 'Actualizado: ' + (generadoEn || '—');

      // Actualizar solo el contenido de ESTA caja
      const cajaDatos = [...abiertas, ...cerradas].find(c => c.idCaja === idCaja);
      if (cajaDatos) {
        const tkList = cajaDatos.ticketsList || [];
        const exList = cajaDatos.extrasList  || [];
        _renderCajaTicketRows(idCaja, tkList, exList, cajaDatos);
        const count = tkList.length;
        if (labelEl) labelEl.textContent = `${count} ticket${count !== 1 ? 's' : ''} ▲`;
        if (headerLbl) headerLbl.textContent = `Tickets (${count})`;
      } else {
        if (labelEl) labelEl.textContent = 'Sin datos ▲';
      }
    } catch(e) {
      if (labelEl) labelEl.textContent = 'Error · intentar de nuevo ▲';
      console.warn('[CajaDetail]', e.message);
    } finally {
      if (iconEl) { iconEl.innerHTML = ''; iconEl.style.animation = ''; }
    }
  }

  // Re-renderiza solo las filas de tickets de una caja abierta sin tocar el resto del DOM
  function _renderCajaTicketRows(idCaja, tkList, exList, cajaDatos) {
    const detail = $('cajadetail-' + idCaja);
    if (!detail) return;

    const estadoBadge = est => {
      if (est === 'ANULADO')    return '<span class="badge badge-red" style="font-size:10px">ANULADO</span>';
      if (est === 'POR_COBRAR') return '<span class="badge badge-yellow" style="font-size:10px">POR COBRAR</span>';
      if (est === 'CREDITO')    return '<span class="badge badge-blue" style="font-size:10px">CRÉDITO</span>';
      return '';
    };
    const metodoBadge = m => {
      const cls = m === 'EFECTIVO' ? 'badge-green' : m === 'ANULADO' ? 'badge-red' : m === 'POR_COBRAR' ? 'badge-yellow' : 'badge-blue';
      return `<span class="badge ${cls}" style="font-size:10px">${m}</span>`;
    };

    const ticketRowsHtml = tkList.map(t => {
      const anulado = t.estado === 'ANULADO';
      return `
      <div data-ticket-row="${t.idVenta}" class="flex items-center gap-2 py-1.5 border-b border-slate-800/60 ${anulado ? 'opacity-40' : ''}">
        <div class="flex-1 min-w-0">
          <div class="flex items-center gap-1.5 flex-wrap">
            <span class="text-xs font-mono ${anulado ? 'line-through text-slate-500' : 'text-slate-200'}">${t.correlativo || t.idVenta}</span>
            ${estadoBadge(t.estado)}
          </div>
          <div class="text-xs text-slate-500 truncate mt-0.5">${t.clienteNom || t.clienteDoc || 'Sin cliente'} · <span class="text-slate-600">${t.tipoDoc}</span>${t.hora ? ' · ' + t.hora : ''}</div>
        </div>
        <div class="text-right shrink-0">
          <div class="text-sm font-semibold ${anulado ? 'line-through text-slate-600' : 'text-white'}">${fmtMoney(t.total)}</div>
          <div class="mt-0.5">${metodoBadge(t.metodo)}</div>
        </div>
      </div>`;
    }).join('');

    // Buscar o crear contenedor de rows
    let rowsDiv = detail.querySelector('.caja-ticket-rows');
    if (!rowsDiv) {
      rowsDiv = document.createElement('div');
      rowsDiv.className = 'caja-ticket-rows mb-4';
      detail.insertBefore(rowsDiv, detail.firstChild.nextSibling);
    }

    if (tkList.length > 0) {
      rowsDiv.innerHTML = ticketRowsHtml;
      // Fade-in en toda la lista como confirmación visual
      rowsDiv.style.animation = 'none'; rowsDiv.offsetHeight;
      rowsDiv.style.animation = 'fadeIn .3s ease';
    } else {
      rowsDiv.innerHTML = '<div class="text-xs text-slate-600 mb-4">Sin tickets registrados aún</div>';
    }
  }

  function _cajaElapsed(fechaApertura) {
    if (!fechaApertura) return '—';
    try {
      const inicio = new Date(fechaApertura.replace(' ', 'T'));
      const mins   = Math.floor((Date.now() - inicio.getTime()) / 60000);
      if (mins < 60)  return mins + ' min';
      const h = Math.floor(mins / 60), m = mins % 60;
      return h + 'h ' + (m < 10 ? '0' : '') + m + 'm';
    } catch { return '—'; }
  }


  // ── DISPOSITIVOS CRUD ────────────────────────────────────────
  function _dispActualizarPreview() {
    const nom = ($('dispNombre')?.value || '').trim();
    const app = $('dispApp')?.value || 'mosExpress';
    const ico = _dispIcono(nom);
    const ip = $('dispIconPreview');
    if (ip) ip.textContent = ico;
    const sub = $('modalDispSubtitle');
    if (sub) sub.textContent = nom ? `${app === 'mosExpress' ? 'ME' : 'WH'} · equipo físico` : 'Equipo físico autorizado';
  }

  function _dispPoblarSelectZonas(idZonaSel) {
    const sel = $('dispUltimaZona');
    if (!sel) return;
    sel.innerHTML = '<option value="">— Sin asignar —</option>' +
      (cfgData.zonas || []).filter(z => z.estado === '1' || z.estado === 1)
        .map(z => `<option value="${z.idZona}">${z.nombre}</option>`).join('');
    if (idZonaSel) sel.value = idZonaSel;
  }

  function _dispPoblarSelectEstaciones(idZona, idEstacionSel) {
    const sel = $('dispUltimaEstacion');
    if (!sel) return;
    let estaciones = cfgData.estaciones || [];
    if (idZona) estaciones = estaciones.filter(e => e.idZona === idZona);
    estaciones = estaciones.filter(e => String(e.activo) === '1');
    sel.innerHTML = '<option value="">— Sin asignar —</option>' +
      estaciones.map(e => {
        const ico = { CAJA: '🛒', ALMACEN: '🏭', ENVASADO: '🍶' }[e.tipo] || '📍';
        return `<option value="${e.idEstacion}">${ico} ${e.nombre}</option>`;
      }).join('');
    if (idEstacionSel) sel.value = idEstacionSel;
  }

  function _dispZonaCambio() {
    const idZona = $('dispUltimaZona')?.value || '';
    _dispPoblarSelectEstaciones(idZona, ''); // resetear estación al cambiar zona
  }

  function abrirModalDispositivo(id) {
    const modal = $('modalDispositivo');
    if (!modal) return;
    $('dispId').value = '';
    $('dispIdVisible').value = '';
    $('dispNombre').value = '';
    $('dispApp').value = 'mosExpress';
    $('dispEstado').value = 'ACTIVO';

    const wrap = $('dispEstadoWrap');
    const tg = $('dispEstadoToggle');
    const btnElim = $('dispBtnEliminar');
    const ucWrap = $('dispUltimaConexion');

    if (id) {
      const d = cfgData.dispositivos.find(x => x.ID_Dispositivo === id);
      if (!d) return;
      $('modalDispTitle').textContent = 'Editar Dispositivo';
      $('dispId').value        = d.ID_Dispositivo;
      $('dispIdVisible').value = d.ID_Dispositivo;
      $('dispNombre').value    = d.Nombre_Equipo || '';
      $('dispApp').value       = d.App    || 'mosExpress';
      $('dispEstado').value    = d.Estado || 'ACTIVO';
      const activo = String(d.Estado).toUpperCase() === 'ACTIVO';
      if (tg) tg.checked = activo;
      if (wrap) wrap.classList.remove('hidden');
      if (btnElim) btnElim.classList.remove('hidden');
      $('dispIdVisible').readOnly = true; // no permite cambiar UUID al editar
      // Selectors de ubicación pre-llenados
      _dispPoblarSelectZonas(d.Ultima_Zona || '');
      _dispPoblarSelectEstaciones(d.Ultima_Zona || '', d.Ultima_Estacion || '');
      // Última conexión
      if (ucWrap) {
        ucWrap.classList.remove('hidden');
        const act = _dispActividad(d.Ultima_Conexion);
        $('dispUltimaConexionTexto').innerHTML = `<span style="color:${act.color}">${act.dot} ${act.label}</span>${d.Ultima_Conexion ? ` <span class="text-slate-600 text-[10px]">(${d.Ultima_Conexion})</span>` : ''}`;
        const detalles = [];
        if (d.Ultima_Sesion) detalles.push('👤 ' + d.Ultima_Sesion);
        if (d.Ultima_Zona) {
          const z = cfgData.zonas?.find(x => x.idZona === d.Ultima_Zona);
          detalles.push('🏬 ' + (z?.nombre || d.Ultima_Zona));
        }
        if (d.Ultima_Estacion) {
          const e = cfgData.estaciones?.find(x => x.idEstacion === d.Ultima_Estacion);
          detalles.push('📍 ' + (e?.nombre || d.Ultima_Estacion));
        }
        $('dispUltimaSesion').textContent = detalles.join(' · ');
      }
    } else {
      $('modalDispTitle').textContent = 'Nuevo Dispositivo';
      if (tg) tg.checked = true;
      if (wrap) wrap.classList.add('hidden');
      if (btnElim) btnElim.classList.add('hidden');
      if (ucWrap) ucWrap.classList.add('hidden');
      $('dispIdVisible').readOnly = false;
      _dispPoblarSelectZonas('');
      _dispPoblarSelectEstaciones('', '');
    }
    _dispActualizarPreview();
    openModal('modalDispositivo');
  }

  function cerrarModalDispositivo() {
    closeModal('modalDispositivo');
  }

  function dispCopiarUUID() {
    const uuid = String($('dispIdVisible')?.value || '').trim();
    if (!uuid) { toast('Sin UUID para copiar', 'warn'); return; }
    navigator.clipboard.writeText(uuid).then(() => toast('UUID copiado al portapapeles ✓', 'ok'))
      .catch(() => toast('No se pudo copiar', 'error'));
  }

  async function guardarDispositivo() {
    const idOriginal = $('dispId').value.trim();
    const idNuevo    = ($('dispIdVisible')?.value || '').trim();
    const nombre     = $('dispNombre').value.trim();
    const app        = $('dispApp').value;
    const tg         = $('dispEstadoToggle');
    const estado     = idOriginal ? (tg && tg.checked ? 'ACTIVO' : 'INACTIVO') : 'ACTIVO';
    const idZonaManual     = $('dispUltimaZona')?.value || '';
    const idEstacionManual = $('dispUltimaEstacion')?.value || '';
    if (!nombre) { toast('El nombre del equipo es obligatorio', 'warn'); return; }
    if (!idNuevo) { toast('Pega el UUID del dispositivo', 'warn'); return; }

    // OPTIMISTA
    const list = cfgData.dispositivos;
    const backup = list.slice();
    if (idOriginal) {
      const idx = list.findIndex(x => x.ID_Dispositivo === idOriginal);
      if (idx >= 0) list[idx] = {
        ...list[idx],
        Nombre_Equipo: nombre, App: app, Estado: estado,
        Ultima_Zona: idZonaManual,
        Ultima_Estacion: idEstacionManual
      };
    } else {
      list.push({
        ID_Dispositivo: idNuevo, Nombre_Equipo: nombre, App: app, Estado: estado,
        Ultima_Conexion: '', Ultima_Zona: idZonaManual, Ultima_Estacion: idEstacionManual
      });
    }
    cerrarModalDispositivo();
    renderInfra();

    try {
      if (idOriginal) {
        await API.post('actualizarDispositivo', {
          ID_Dispositivo: idOriginal, Nombre_Equipo: nombre, App: app, Estado: estado,
          Ultima_Zona: idZonaManual, Ultima_Estacion: idEstacionManual
        });
      } else {
        await API.post('crearDispositivo', {
          ID_Dispositivo: idNuevo, Nombre_Equipo: nombre, App: app, Estado: estado,
          Ultima_Zona: idZonaManual, Ultima_Estacion: idEstacionManual
        });
      }
      toast('Dispositivo guardado ✓', 'ok');
    } catch(e) {
      cfgData.dispositivos = backup;
      renderInfra();
      toast(e.message || 'Error al guardar', 'error');
    }
  }

  async function eliminarDispositivo() {
    // 'Eliminar' = bloquear (Estado=INACTIVO)
    const id = $('dispId')?.value;
    if (!id) return;
    const d = cfgData.dispositivos.find(x => x.ID_Dispositivo === id);
    if (!d) return;
    if (!await _modalConfirm(`¿Bloquear el dispositivo "${d.Nombre_Equipo}"?\n\nNo podrá iniciar sesión en ninguna app. Puedes reactivarlo cuando quieras.`, { warning: true, titulo: 'Bloquear dispositivo', okText: 'Bloquear' })) return;
    cerrarModalDispositivo();
    const previo = d.Estado;
    d.Estado = 'INACTIVO';
    renderInfra();
    try {
      await API.post('actualizarDispositivo', { ID_Dispositivo: id, Estado: 'INACTIVO' });
      toast('Dispositivo bloqueado', 'ok');
    } catch(e) {
      d.Estado = previo;
      renderInfra();
      toast(e.message || 'Error', 'error');
    }
  }

  // Aprobar dispositivo: optimista con feedback visual claro.
  // - Nombre por default = el que vino del User-Agent (ej "Windows · Chrome").
  // - Si pasamos { renombrar: true } abre prompt para editarlo.
  // - Animación slide-out del card + sonido + toast inmediato.
  // [v2.43.155] Shield optimista: protege el estado ACTIVO de un dispositivo
  // recién aprobado durante 10s contra el polling de getDispositivos que
  // podría traer aún el estado viejo PENDIENTE_APROBACION del backend.
  // Causa raíz reportada por el usuario: 'aprueba pero vuelve a por aprobar'.
  if (!S._dispShield) S._dispShield = {};

  async function aprobarDispositivo(id, opts) {
    opts = opts || {};
    const d = cfgData.dispositivos.find(x => x.ID_Dispositivo === id);
    if (!d) return;
    let nombre = (d.Nombre_Equipo || '').trim() || ('Dispositivo ' + id.substring(0, 8));
    if (opts.renombrar) {
      const nuevoNombre = await _modalPrompt('Nombre del dispositivo:', nombre, { titulo: 'Renombrar dispositivo', maxlength: 60 });
      if (nuevoNombre === null) return;
      const t = (nuevoNombre || '').trim();
      if (!t) { toast('El nombre no puede estar vacío', 'error'); return; }
      nombre = t;
    }
    // Animación slide-out del card que se está aprobando
    const safeId = String(id).replace(/'/g, '&#39;');
    const card = document.querySelector(`[data-pend-card="${safeId}"]`);
    if (card) {
      card.classList.add('disp-pend-aprobando');
    }
    // Sonido + toast inmediato (optimista)
    try { _finBeep?.('breakeven'); } catch(_){}
    toast(`✓ "${nombre}" aprobado`, 'ok');
    // Aplicar cambio en el modelo local
    const previo = d.Estado;
    d.Estado = 'ACTIVO';
    d.Nombre_Equipo = nombre;
    // [v2.43.155] Activar shield por 10s: el polling NO podrá pisar el estado
    // ACTIVO de este dispositivo hasta que el backend lo confirme.
    S._dispShield[id] = { estado: 'ACTIVO', nombre: nombre, hasta: Date.now() + 10000 };
    // Esperar la animación antes del re-render para que se vea desaparecer
    setTimeout(() => renderInfra(), 320);
    try {
      await API.post('aprobarDispositivoPendiente', {
        ID_Dispositivo: id,
        Nombre_Equipo: nombre
      });
      // [v2.43.345] Red de seguridad generosa (15s): el shield se libera ANTES por confirmación del backend
      // (ver _dispAplicarShield) — este timeout solo cubre el caso de que el backend nunca refleje el cambio.
      // Antes eran 3s fijos: con el dual-write a la sombra la llamada tarda un poco más y el poll podía llegar
      // tras el vencimiento con el valor viejo en vuelo → el card parpadeaba (reaparecía y se iba).
      if (S._dispShield[id]) S._dispShield[id].hasta = Date.now() + 15000;
    } catch(e) {
      // Rollback: quitar shield y restaurar estado previo
      delete S._dispShield[id];
      d.Estado = previo;
      renderInfra();
      toast(e.message || 'Error al aprobar', 'error');
    }
  }
  // [v2.43.155] Aplicar shield a la lista de dispositivos que llega del backend.
  // El polling llama getDispositivos y reemplaza cfgData.dispositivos completo;
  // pasamos el array por este helper antes de asignar para preservar los
  // recién aprobados en estado ACTIVO durante el shield window.
  function _dispAplicarShield(arr) {
    if (!Array.isArray(arr) || !S._dispShield) return arr;
    const ahora = Date.now();
    const expirados = [];
    Object.keys(S._dispShield).forEach(id => {
      const sh = S._dispShield[id];
      if (!sh) { expirados.push(id); return; }
      const idx = arr.findIndex(x => String(x.ID_Dispositivo) === String(id));
      // [v2.43.345] LIBERAR-AL-CONFIRMAR: si el backend YA trae el estado optimista, el cambio está
      // confirmado → soltar el shield (no seguir forzando). Esto evita el parpadeo: el card no reaparece
      // por una respuesta vieja en vuelo (esa NO confirma, así que el shield la sigue tapando) y se suelta
      // recién cuando llega la confirmación real. El timeout es solo red de seguridad.
      if (idx >= 0 && String(arr[idx].Estado).toUpperCase() === String(sh.estado).toUpperCase()) {
        expirados.push(id); return;
      }
      // Red de seguridad: si el backend nunca reflejó el cambio en la ventana, soltar por tiempo.
      if (sh.hasta < ahora) { expirados.push(id); return; }
      // Aún sin confirmar y dentro de ventana → preservar el estado + nombre optimistas.
      if (idx >= 0) arr[idx] = { ...arr[idx], Estado: sh.estado, Nombre_Equipo: sh.nombre };
    });
    expirados.forEach(id => delete S._dispShield[id]);
    return arr;
  }

  // Variante: aprobar pero pidiendo nombre antes (botón ✎ Renombrar).
  function aprobarDispositivoConNombre(id) {
    return aprobarDispositivo(id, { renombrar: true });
  }

  async function rechazarDispositivo(id) {
    const d = cfgData.dispositivos.find(x => x.ID_Dispositivo === id);
    if (!d) return;
    if (!await _modalConfirm(`¿Rechazar este dispositivo?\n\nQuedará bloqueado y no podrá conectarse.`, { danger: true, titulo: 'Rechazar dispositivo', okText: 'Rechazar' })) return;
    const safeId = String(id).replace(/'/g, '&#39;');
    const card = document.querySelector(`[data-pend-card="${safeId}"]`);
    if (card) {
      card.classList.add('disp-pend-rechazando');
    }
    try { _finBeep?.('click'); } catch(_){}
    toast('Dispositivo rechazado', 'warn');
    const previo = d.Estado;
    d.Estado = 'INACTIVO';
    setTimeout(() => renderInfra(), 320);
    try {
      await API.post('rechazarDispositivoPendiente', { ID_Dispositivo: id });
    } catch(e) {
      d.Estado = previo;
      renderInfra();
      toast(e.message || 'Error', 'error');
    }
  }

  // ────────────────────────────────────────────────────────
  // MODAL AUDIO — escucha remota
  // ────────────────────────────────────────────────────────
  let _audioPollTimer = null;
  let _audioReproduciendo = null; // { sesion, chunks, idx }

  async function abrirModalAudio(idDispositivo) {
    const d = (cfgData.dispositivos || []).find(x => x.ID_Dispositivo === idDispositivo);
    if (!d) return;
    $('audioModalDeviceId').value = idDispositivo;
    $('audioModalSubtitle').textContent = `${d.Nombre_Equipo || idDispositivo}${d.Ultima_Sesion ? ' · 👤 ' + d.Ultima_Sesion : ''}`;
    $('audioReproductor').classList.add('hidden');
    openModal('modalAudio');
    await audioRefrescarEstado();
    audioListarSesiones();
    if (_audioPollTimer) clearInterval(_audioPollTimer);
    _audioPollTimer = setInterval(audioRefrescarEstado, 10 * 1000);
  }

  // Cerrar modal cancela el poll
  document.addEventListener('mos:modal-cerrado', e => {
    if (e.detail === 'modalAudio' && _audioPollTimer) {
      clearInterval(_audioPollTimer); _audioPollTimer = null;
    }
  });

  async function audioRefrescarEstado() {
    const id = $('audioModalDeviceId')?.value;
    if (!id) return;
    const cont = $('audioEstadoActual');
    if (!cont) return;
    try {
      const data = await API.get('getEstadoAudio', { deviceId: id });
      if (data?.activa) {
        const sesionId = data.sesion.idSesion;
        const ini = data.sesion.inicio ? new Date(data.sesion.inicio) : null;
        const segs = ini ? Math.floor((Date.now() - ini.getTime()) / 1000) : 0;
        const mm = String(Math.floor(segs / 60)).padStart(2, '0');
        const ss = String(segs % 60).padStart(2, '0');
        cont.innerHTML = `<div class="card p-3" style="background:rgba(239,68,68,0.10);border:1px solid #dc2626;">
          <div class="flex items-center justify-between gap-2 flex-wrap">
            <div>
              <div class="text-sm font-bold text-red-300">🔴 Grabando ahora</div>
              <div class="text-[10px] text-slate-500 font-mono">sesión ${sesionId} · ${mm}:${ss}</div>
            </div>
            <button onclick="MOS.audioDetener('${sesionId}')" class="btn-primary text-xs px-3 py-1.5" style="background:#dc2626">⏹️ Detener</button>
          </div>
        </div>`;
      } else {
        cont.innerHTML = `<div class="card p-3" style="background:#0a1424;border:1px solid #1e293b;">
          <div class="flex items-center justify-between gap-2 flex-wrap">
            <div>
              <div class="text-sm font-bold text-slate-300">⏸ Sin grabación activa</div>
              <div class="text-[10px] text-slate-500">El dispositivo está en silencio</div>
            </div>
            <button onclick="MOS.audioIniciar('${id}')" class="btn-primary text-xs px-3 py-1.5" style="background:#dc2626">🎙️ Iniciar escucha</button>
          </div>
        </div>`;
      }
    } catch(_) {
      cont.innerHTML = '<div class="text-center py-3 text-red-400 text-sm">Error consultando estado</div>';
    }
  }

  async function audioIniciar(deviceId) {
    // Cerrar el modal de historial (si está abierto) y enrutar al flotante.
    // Sin confirm — el user ya hizo click en "🎙️ Iniciar escucha", confirmación redundante.
    try { closeModal('modalAudio'); } catch {}
    return _audioFlotanteIniciar(deviceId);
  }

  async function audioDetener(idSesion) {
    try {
      await API.post('detenerEscuchaAudio', { idSesion });
      toast('⏹️ Detenido', 'ok');
      setTimeout(audioRefrescarEstado, 1000);
      setTimeout(audioListarSesiones, 1500);
    } catch(e) {
      toast('Error: ' + e.message, 'error');
    }
  }

  async function audioListarSesiones() {
    const id = $('audioModalDeviceId')?.value;
    if (!id) return;
    const cont = $('audioListaSesiones');
    // Render INMEDIATO desde cache localStorage si existe (TTL 60s)
    const cacheKey = 'mos_audio_sesiones_' + id;
    try {
      const raw = localStorage.getItem(cacheKey);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (parsed && Array.isArray(parsed.data) && (Date.now() - parsed.ts) < 60000) {
          cont.innerHTML = _audioRenderSesiones(parsed.data);
        }
      }
    } catch {}
    try {
      const data = await API.get('getSesionesAudio', { deviceId: id, limit: 20 });
      try { localStorage.setItem(cacheKey, JSON.stringify({ ts: Date.now(), data })); } catch {}
      if (!Array.isArray(data) || !data.length) {
        cont.innerHTML = '<div class="text-center py-6 text-slate-500 text-sm italic">Sin sesiones todavía</div>';
        return;
      }
      cont.innerHTML = _audioRenderSesiones(data);
      return;
    } catch(e) {
      if (!cont.innerHTML.trim()) cont.innerHTML = '<div class="text-center py-3 text-red-400 text-sm">Error: ' + e.message + '</div>';
      return;
    }
  }

  function _audioRenderSesiones(data) {
    return data.map(s => {
        const fIni = s.inicio ? new Date(s.inicio) : null;
        const fmt = fIni ? fIni.toLocaleString('es-PE', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' }) : '—';
        const dur = s.duracionSeg ? Math.floor(s.duracionSeg / 60) + 'm' + (s.duracionSeg % 60) + 's' : '—';
        const estCl = s.estado === 'ACTIVA' ? 'text-red-400 animate-pulse'
                    : s.estado === 'CERRADA' ? 'text-emerald-400'
                    : 'text-slate-500';
        return `<div class="flex items-center gap-2 p-2 rounded" style="background:#0a1424;border:1px solid #1e293b;">
          <div class="flex-1 min-w-0">
            <div class="text-xs font-medium text-slate-200">${fmt} · <span class="${estCl} text-[10px] uppercase">${s.estado || '—'}</span></div>
            <div class="text-[10px] text-slate-500">por ${s.autorizadoPor || '—'} · ${dur}</div>
          </div>
          <button onclick="MOS.audioReproducir('${s.idSesion}','${(s.autorizadoPor || '').replace(/'/g,"\\'")}','${fmt.replace(/'/g,"\\'")}')"
            class="btn-ghost text-[10px] px-2 py-1" ${s.estado === 'ACTIVA' ? '' : ''}>▶ Reproducir</button>
        </div>`;
      }).join('');
  }

  async function audioReproducir(idSesion, autorizadoPor, fechaTxt) {
    const player = $('audioPlayer');
    const cont = $('audioReproductor');
    const titulo = $('audioReproductorTitulo');
    const info = $('audioReproductorInfo');
    if (!player || !cont) return;
    cont.classList.remove('hidden');
    titulo.textContent = `▶ Sesión ${fechaTxt} · ${autorizadoPor || ''}`;
    info.textContent = 'Cargando chunks...';
    try {
      const chunks = await API.get('getChunksAudioSesion', { idSesion });
      if (!Array.isArray(chunks) || !chunks.length) {
        info.textContent = '⚠ Sesión sin chunks (puede estar arrancando)';
        return;
      }
      info.textContent = `${chunks.length} chunks · cargando primero...`;
      _audioReproduciendo = { chunks, idx: 0, idSesion };
      await _audioCargarYReproducir();
    } catch(e) {
      info.textContent = 'Error: ' + e.message;
    }
  }

  async function _audioCargarYReproducir() {
    if (!_audioReproduciendo) return;
    const { chunks, idx } = _audioReproduciendo;
    if (idx >= chunks.length) {
      $('audioReproductorInfo').textContent = '✓ Reproducción finalizada';
      return;
    }
    const ch = chunks[idx];
    try {
      const data = await API.get('getChunkAudioContent', { fileId: ch.driveFileId });
      if (!data?.base64) throw new Error('Sin contenido');
      const blob = _b64ToBlob(data.base64, data.mimeType || 'audio/webm');
      const url = URL.createObjectURL(blob);
      const player = $('audioPlayer');
      player.src = url;
      player.play().catch(() => {});
      $('audioReproductorInfo').textContent = `Chunk ${idx + 1} / ${chunks.length}`;
      player.onended = () => {
        URL.revokeObjectURL(url);
        if (_audioReproduciendo) {
          _audioReproduciendo.idx++;
          _audioCargarYReproducir();
        }
      };
    } catch(e) {
      $('audioReproductorInfo').textContent = 'Error chunk ' + (idx + 1) + ': ' + e.message;
    }
  }

  function _b64ToBlob(b64, mime) {
    const bin = atob(b64);
    const len = bin.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) bytes[i] = bin.charCodeAt(i);
    return new Blob([bytes], { type: mime });
  }

  function audioCerrarReproductor() {
    _audioReproduciendo = null;
    const player = $('audioPlayer');
    if (player) { player.pause(); player.src = ''; }
    $('audioReproductor')?.classList.add('hidden');
  }

  // ────────────────────────────────────────────────────────
  // Audio LIVE (ADMIN) — sin historial, solo activar/detener
  // ────────────────────────────────────────────────────────
  let _audioLivePollTimer = null;

  function _esRolMaster() {
    return String(S.session?.rol || '').toUpperCase() === 'MASTER';
  }

  // Busca dispositivos donde el usuario tiene Ultima_Sesion (sin filtrar por
  // Estado — incluye los aprobados aunque estén offline ahora). Ordena por
  // Ultima_Conexion DESC para que el más reciente quede primero.
  function _buscarDispositivosDeUsuario(nombre) {
    const target = String(nombre || '').trim().toLowerCase();
    if (!target) return [];
    return (cfgData.dispositivos || [])
      .filter(d => {
        // Excluir solo los explícitamente INACTIVO o PENDIENTE
        const est = String(d.Estado || '').toUpperCase();
        if (est === 'INACTIVO' || est === 'PENDIENTE_APROBACION') return false;
        const sesion = String(d.Ultima_Sesion || '').trim().toLowerCase();
        return sesion === target;
      })
      .sort((a, b) => {
        const ta = new Date(a.Ultima_Conexion || 0).getTime() || 0;
        const tb = new Date(b.Ultima_Conexion || 0).getTime() || 0;
        return tb - ta;
      });
  }

  // Refresca cfgData.dispositivos antes de buscar — garantiza data fresh
  async function _refrescarDispositivosFresh() {
    try {
      const data = await API.get('getDispositivos', {});
      if (Array.isArray(data)) cfgData.dispositivos = _dispAplicarShield(data);   // [v2.43.348 fix] shield
    } catch(_) {}
  }

  // Punto de entrada cuando se hace click en 🎙️ desde Personal del Día


  function _selectorDispMostrar(nombre, devs, modo) {
    const sub = $('selectorDispSubtitle');
    const lista = $('selectorDispLista');
    const verboMap = { audio: 'escuchar', gps: 'ubicar', espia: 'espiar' };
    if (sub) sub.textContent = `${nombre} · ${devs.length} dispositivos · elige cuál ${verboMap[modo] || 'usar'}`;
    if (!lista) return;
    const accionMap = { audio: 'abrirModalAudioRouted', gps: 'abrirModalGps', espia: 'abrirEspiaDispositivo' };
    const icoMap = { audio: '🎙️', gps: '📍', espia: '🕵️' };
    const accentMap = { audio: '#dc2626', gps: '#10b981', espia: '#6366f1' };
    const accion = accionMap[modo] || 'abrirModalAudioRouted';
    const ico = icoMap[modo] || '🎙️';
    const accent = accentMap[modo] || '#dc2626';
    lista.innerHTML = devs.map(d => {
      const act = _personaActividad(d.Ultima_Conexion);
      const idAttr = String(d.ID_Dispositivo).replace(/'/g, '&#39;');
      const ico2 = String(d.Icono || '📱');
      return `<button onclick="MOS.closeModal('modalSelectorDispositivos');MOS.${accion}('${idAttr}')"
        class="w-full flex items-center gap-3 p-3 rounded-lg hover:scale-[1.01] transition-all text-left"
        style="background:#0a1424;border:1px solid #1e293b;">
        <span class="text-2xl shrink-0">${ico2}</span>
        <div class="flex-1 min-w-0">
          <div class="text-sm font-medium text-slate-200 truncate">${d.Nombre_Equipo || idAttr}</div>
          <div class="text-[10px]" style="color:${act.color};">${act.dot} ${act.label} · ${d.App || '—'}${d.Estacion ? ' · ' + d.Estacion : ''}</div>
        </div>
        <span class="shrink-0 w-8 h-8 rounded-full flex items-center justify-center" style="background:rgba(255,255,255,0.05);border:1px solid ${accent};color:${accent};">${ico}</span>
      </button>`;
    }).join('');
    openModal('modalSelectorDispositivos');
  }

  // Click en 🎙️ desde cualquier lado → entra DIRECTO al modo escucha en vivo
  // con widget flotante. Sin modal intrusivo. El historial completo (master)
  // queda accesible desde el flotante con el botón "📋".
  async function abrirModalAudioRouted(idDispositivo) {
    return _audioFlotanteIniciar(idDispositivo);
  }

  // Wrapper que enruta desde Configuración → Infraestructura al flotante

  // ════════════════════════════════════════════════════════════
  // WIDGET FLOTANTE de escucha en vivo
  // - Persiste entre módulos (mounted en <body>)
  // - Auto-iniciar sesión + auto-streaming de chunks
  // - Click en ⏹️ → detener escucha + remover flotante
  // - Click en 📋 → modal completo con historial (solo master)
  // ════════════════════════════════════════════════════════════
  let _audioFlot = null;
  // _audioFlot: { idSesion, deviceId, nombre, chunks[], idx, audioEl,
  //   inicio, polling, contadorTimer, chunksCargados:Set, prefetched:Map }

  async function _audioFlotanteIniciar(idDispositivo) {
    // Si ya hay un flotante para el mismo dispositivo, no hacer nada
    if (_audioFlot && _audioFlot.deviceId === idDispositivo) {
      toast('Ya estás escuchando este dispositivo', 'info');
      return;
    }
    // Si hay flotante de OTRO dispositivo → swap silencioso (sin confirm — el user clickeó otro)
    if (_audioFlot) await _audioFlotanteDetenerInterno(true);

    const d = (cfgData.dispositivos || []).find(x => x.ID_Dispositivo === idDispositivo);
    if (!d) { toast('Dispositivo no encontrado', 'error'); return; }
    const nombre = d.Nombre_Equipo + (d.Ultima_Sesion ? ' · ' + d.Ultima_Sesion : '');

    // Crear el flotante INMEDIATO (UI optimista — el user ve el widget al instante)
    _audioFlotanteCrearDOM(idDispositivo, nombre);
    const subEl = document.querySelector('#audioFlotante .audio-flot-sub');
    if (subEl) subEl.textContent = '⌛ conectando...';

    try {
      // Detectar sesión zombie: ACTIVA pero >35 min de antigüedad sin chunks → cerrar y abrir nueva
      const estado = await API.get('getEstadoAudio', { deviceId: idDispositivo });
      let idSesion = null;
      if (estado?.activa) {
        const ini = estado.sesion?.inicio ? new Date(estado.sesion.inicio).getTime() : 0;
        const edad = Date.now() - ini;
        const esZombie = edad > 35 * 60 * 1000; // 35 min (max es 30, esto da margen)
        if (esZombie) {
          // Cerrar zombie y abrir nueva
          try { await API.post('detenerEscuchaAudio', { idSesion: estado.sesion.idSesion }); } catch {}
          if (subEl) subEl.textContent = '⌛ sesión zombie cerrada · iniciando nueva...';
        } else {
          idSesion = estado.sesion.idSesion;
          if (subEl) subEl.textContent = '🔴 conectando a sesión activa...';
        }
      }
      if (!idSesion) {
        if (subEl && !subEl.textContent.includes('zombie')) subEl.textContent = '⌛ iniciando grabación...';
        const data = await API.post('iniciarEscuchaAudio', {
          deviceId: idDispositivo,
          autorizadoPor: S.session?.nombre || 'admin',
          motivo: 'Escucha en vivo desde MOS'
        });
        idSesion = data.idSesion;
      }
      if (!_audioFlot) return; // user cerró el flotante mientras esperaba
      _audioFlot.idSesion = idSesion;
      const subEl2 = document.querySelector('#audioFlotante .audio-flot-sub');
      if (subEl2) subEl2.textContent = '🔴 esperando primer chunk (~15s)...';

      // Arrancar polling y reproductor
      _audioFlotantePollChunks(); // primer poll inmediato
      _audioFlot.polling = setInterval(_audioFlotantePollChunks, 2500);
      // Watchdogs progresivos: 20s → primer aviso, 45s → recomendación, 90s → autodetener
      _audioFlot.watchdog20 = setTimeout(() => {
        if (!_audioFlot || _audioFlot.chunks.length > 0) return;
        const elS = document.querySelector('#audioFlotante .audio-flot-sub');
        if (elS) elS.innerHTML = '⌛ <span style="color:#fde68a">esperando dispositivo (~5-15s más)...</span>';
      }, 20000);
      _audioFlot.watchdog45 = setTimeout(() => {
        if (!_audioFlot || _audioFlot.chunks.length > 0) return;
        const elS = document.querySelector('#audioFlotante .audio-flot-sub');
        if (elS) elS.innerHTML = '⚠ <span style="color:#fbbf24">App cerrada o sin permiso mic — pedile que abra la app</span>';
      }, 45000);
      _audioFlot.watchdog90 = setTimeout(() => {
        if (!_audioFlot || _audioFlot.chunks.length > 0) return;
        toast('⚠ Sin respuesta del dispositivo · escucha cancelada', 'warn', 6000);
        _audioFlotanteDetenerInterno(true);
      }, 90000);
    } catch(e) {
      const subEl3 = document.querySelector('#audioFlotante .audio-flot-sub');
      if (subEl3) subEl3.textContent = '❌ ' + e.message;
      setTimeout(() => _audioFlotanteCerrarSinDetener(), 3000);
    }
  }

  function _audioFlotanteCrearDOM(deviceId, nombre) {
    if (document.getElementById('audioFlotante')) return;
    // Botón 📋 (ver historial completo) solo para MASTER. Admin no debería
    // ver sesiones pasadas — solo escucha en vivo.
    const btnHist = _esRolMaster()
      ? `<button class="audio-flot-btn" onclick="MOS.abrirModalAudio('${String(deviceId).replace(/'/g,"\\'")}')" title="Ver historial de sesiones">📋</button>`
      : '';
    const fl = document.createElement('div');
    fl.id = 'audioFlotante';
    fl.innerHTML = `
      <div class="audio-flot-mic">🎙️</div>
      <div class="audio-flot-info">
        <div class="audio-flot-nom">${nombre}</div>
        <div class="audio-flot-sub">⌛ iniciando...</div>
        <div class="audio-flot-time" id="audioFlotTime">00:00</div>
        <div class="audio-flot-chunks" id="audioFlotChunks">— chunks</div>
      </div>
      <div class="audio-flot-actions">
        ${btnHist}
        <button class="audio-flot-btn audio-flot-btn-stop" onclick="MOS._audioFlotanteDetener()" title="Detener escucha">⏹</button>
      </div>
      <audio id="audioFlotantePlayer"></audio>`;
    document.body.appendChild(fl);
    _audioFlot = {
      deviceId, nombre,
      idSesion: null,
      chunks: [], idx: 0,
      chunksCargados: new Set(),
      audioEl: document.getElementById('audioFlotantePlayer'),
      inicio: Date.now(),
      polling: null,
      contadorTimer: null,
      prefetched: new Map()
    };
    // Contador
    _audioFlot.contadorTimer = setInterval(() => {
      if (!_audioFlot) return;
      const segs = Math.floor((Date.now() - _audioFlot.inicio) / 1000);
      const mm = String(Math.floor(segs / 60)).padStart(2, '0');
      const ss = String(segs % 60).padStart(2, '0');
      const t = $('audioFlotTime');
      if (t) t.textContent = `${mm}:${ss}`;
    }, 1000);
    // Encadenado: cuando termina un chunk, ir al siguiente
    _audioFlot.audioEl.onended = () => {
      if (!_audioFlot) return;
      _audioFlot.idx++;
      _audioFlotanteReproducirSiguiente();
    };
    // Pre-warm autoplay policy: reproducir un blob silencioso de 100ms para
    // que el browser asocie el user gesture (click 🎙️) con el audio element.
    // Sin esto, cuando llega el primer chunk 15s después, autoplay falla.
    try {
      const silentWebm = 'data:audio/webm;base64,GkXfowEAAAAAAAAfQoaBAUL3gQFC8oEEQvOBCEKChHdlYm1Ch4EEQoWBAhhTgGcBAAAAAAAVkhFNm3RALE27i1OrhBVJqWZTrIHfTbuMU6uEFlSua1OsggEwTbuMU6uEHFO7a1OsggI+7AEAAAAAAACkAAAAAAAAAAAAAAAAAAA=';
      _audioFlot.audioEl.src = silentWebm;
      _audioFlot.audioEl.volume = 0;
      _audioFlot.audioEl.play().then(() => {
        if (_audioFlot && _audioFlot.audioEl) _audioFlot.audioEl.volume = 1;
      }).catch(() => {});
    } catch(_) {}
    // Drag (mover el flotante)
    _audioFlotanteDraggable(fl);
  }

  function _audioFlotanteDraggable(el) {
    let dragging = false, ox = 0, oy = 0, sl = 0, st = 0;
    // [perf/leak] Antes mousemove/mouseup eran listeners ANÓNIMOS en document, agregados cada vez que se
    // re-creaba el flotante y NUNCA removidos → se acumulaban (los viejos apuntando a nodos detached y
    // corriendo en cada movimiento del mouse en toda la app). Ahora se agregan SOLO durante el arrastre
    // (en mousedown) y se REMUEVEN al soltar (mouseup) con handlers nombrados → cero acumulación.
    const _onMove = (e) => {
      if (!dragging) return;
      el.style.left = (sl + e.clientX - ox) + 'px';
      el.style.top  = (st + e.clientY - oy) + 'px';
    };
    const _onUp = () => {
      dragging = false; el.classList.remove('dragging');
      document.removeEventListener('mousemove', _onMove);
      document.removeEventListener('mouseup', _onUp);
    };
    el.addEventListener('mousedown', e => {
      if (e.target.closest('.audio-flot-btn') || e.target.closest('audio')) return;
      dragging = true;
      const r = el.getBoundingClientRect();
      ox = e.clientX; oy = e.clientY; sl = r.left; st = r.top;
      el.classList.add('dragging');
      el.style.right = 'auto'; el.style.bottom = 'auto';
      document.addEventListener('mousemove', _onMove);
      document.addEventListener('mouseup', _onUp);
    });
  }

  async function _audioFlotantePollChunks() {
    if (!_audioFlot || !_audioFlot.idSesion) return;
    try {
      const newChunks = await API.get('getChunksAudioSesion', { idSesion: _audioFlot.idSesion });
      if (!Array.isArray(newChunks)) return;
      let added = 0;
      newChunks.forEach(c => {
        if (!_audioFlot.chunksCargados.has(c.driveFileId)) {
          _audioFlot.chunks.push(c);
          _audioFlot.chunksCargados.add(c.driveFileId);
          added++;
        }
      });
      const elC = $('audioFlotChunks');
      if (elC) elC.textContent = `${_audioFlot.chunks.length} chunks · idx ${_audioFlot.idx + 1}`;
      const elS = document.querySelector('#audioFlotante .audio-flot-sub');
      if (elS && _audioFlot.chunks.length > 0) elS.textContent = '🔴 escuchando en vivo';

      // Si el reproductor está pausado y hay chunks por reproducir, arrancar
      if (_audioFlot.audioEl.paused && _audioFlot.idx < _audioFlot.chunks.length) {
        _audioFlotanteReproducirSiguiente();
      }
      // Prefetch de los próximos 2 chunks (para evitar gap entre chunks)
      _audioFlotantePrefetch(_audioFlot.idx + 1);
      _audioFlotantePrefetch(_audioFlot.idx + 2);
    } catch (e) {
      const elS = document.querySelector('#audioFlotante .audio-flot-sub');
      if (elS) elS.textContent = '⚠ ' + e.message;
    }
  }

  async function _audioFlotantePrefetch(idx) {
    if (!_audioFlot) return;
    if (idx >= _audioFlot.chunks.length) return;
    const ch = _audioFlot.chunks[idx];
    if (!ch || _audioFlot.prefetched.has(ch.driveFileId)) return;
    _audioFlot.prefetched.set(ch.driveFileId, 'pending');
    // [perf/leak] Evicción por ventana deslizante: libera el base64 de los chunks ya reproducidos (idx-6 atrás)
    // para que el Map no retenga TODA la escucha (decenas de MB en sesiones largas). Si se busca atrás, se re-fetch.
    const _oldIdx = idx - 6;
    if (_oldIdx >= 0 && _audioFlot.chunks[_oldIdx]) _audioFlot.prefetched.delete(_audioFlot.chunks[_oldIdx].driveFileId);
    try {
      const data = await API.get('getChunkAudioContent', { fileId: ch.driveFileId });
      if (!data?.base64) throw new Error('vacío');
      _audioFlot.prefetched.set(ch.driveFileId, data);
    } catch {
      _audioFlot.prefetched.delete(ch.driveFileId);
    }
  }

  async function _audioFlotanteReproducirSiguiente() {
    if (!_audioFlot) return;
    const { chunks, idx, audioEl } = _audioFlot;
    if (idx >= chunks.length) {
      const elS = document.querySelector('#audioFlotante .audio-flot-sub');
      if (elS) elS.textContent = '⏳ esperando próximo chunk...';
      return;
    }
    const ch = chunks[idx];
    let data = _audioFlot.prefetched.get(ch.driveFileId);
    if (!data || data === 'pending') {
      try {
        data = await API.get('getChunkAudioContent', { fileId: ch.driveFileId });
        _audioFlot.prefetched.set(ch.driveFileId, data);
      } catch (e) {
        const elS = document.querySelector('#audioFlotante .audio-flot-sub');
        if (elS) elS.textContent = '⚠ chunk ' + (idx + 1) + ' falló';
        // intentar siguiente
        _audioFlot.idx++;
        setTimeout(() => _audioFlotanteReproducirSiguiente(), 500);
        return;
      }
    }
    if (!data?.base64) {
      _audioFlot.idx++;
      setTimeout(() => _audioFlotanteReproducirSiguiente(), 200);
      return;
    }
    const blob = _b64ToBlob(data.base64, data.mimeType || 'audio/webm');
    const url = URL.createObjectURL(blob);
    audioEl.src = url;
    try {
      await audioEl.play();
    } catch (e) {
      // Autoplay policy bloqueó: el usuario debe hacer click manualmente
      const elS = document.querySelector('#audioFlotante .audio-flot-sub');
      if (elS) elS.textContent = '🔇 click el mic para iniciar audio';
      const mic = document.querySelector('#audioFlotante .audio-flot-mic');
      if (mic) {
        mic.style.cursor = 'pointer';
        mic.onclick = () => audioEl.play().catch(() => {});
      }
    }
    URL.revokeObjectURL(url);
    // Iniciar prefetch del próximo
    _audioFlotantePrefetch(idx + 1);
  }

  async function _audioFlotanteDetener() {
    if (!_audioFlot) return;
    if (!await _modalConfirm('¿Detener escucha?', { titulo: 'Detener escucha' })) return;
    await _audioFlotanteDetenerInterno(true);
    toast('⏹️ Escucha detenida', 'ok');
  }

  // Detiene la sesión en server (si remoto=true) y limpia el widget
  async function _audioFlotanteDetenerInterno(remoto) {
    if (!_audioFlot) return;
    const idSesion = _audioFlot.idSesion;
    if (_audioFlot.polling) clearInterval(_audioFlot.polling);
    if (_audioFlot.contadorTimer) clearInterval(_audioFlot.contadorTimer);
    if (_audioFlot.watchdog20) clearTimeout(_audioFlot.watchdog20);
    if (_audioFlot.watchdog45) clearTimeout(_audioFlot.watchdog45);
    if (_audioFlot.watchdog90) clearTimeout(_audioFlot.watchdog90);
    if (_audioFlot.audioEl) { _audioFlot.audioEl.pause(); _audioFlot.audioEl.src = ''; _audioFlot.audioEl.onended = null; }
    const fl = document.getElementById('audioFlotante');
    if (fl) {
      fl.style.transition = 'all 0.3s ease-out';
      fl.style.transform = 'translateY(50px) scale(0.85)';
      fl.style.opacity = '0';
      setTimeout(() => fl.remove(), 320);
    }
    _audioFlot = null;
    if (remoto && idSesion) {
      try { await API.post('detenerEscuchaAudio', { idSesion }); } catch {}
    }
  }

  function _audioFlotanteCerrarSinDetener() {
    const fl = document.getElementById('audioFlotante');
    if (fl) fl.remove();
    if (_audioFlot) {
      if (_audioFlot.polling) clearInterval(_audioFlot.polling);
      if (_audioFlot.contadorTimer) clearInterval(_audioFlot.contadorTimer);
    }
    _audioFlot = null;
  }

  // ════════════════════════════════════════════════════════════
  // ESPÍA — orquestador audio + gps en modal grande + widget mini
  // ════════════════════════════════════════════════════════════
  // _espiaState:
  //   { deviceId, nombre, modalAbierto:bool, gpsPolling, gpsUlt, gpsRangoH }
  // Audio sigue manejado por _audioFlot (estado heredado), pero el widget
  // visible es #espiaFlotante (no #audioFlotante).
  let _espiaState = null;

  // Click en 🕵️ desde Personal del Día / Configuración Personal
  // Abre el modal INMEDIATAMENTE con datos en cache, refresca en background.
  async function abrirEspiaPorUsuario(nombre) {
    let devs = _buscarDispositivosDeUsuario(nombre);
    if (!devs.length) {
      // No hay en cache → buscar fresh (única vez que bloqueamos)
      await _refrescarDispositivosFresh();
      devs = _buscarDispositivosDeUsuario(nombre);
    }
    if (!devs.length) {
      toast(`⚠ ${nombre} no tiene dispositivos con su sesión`, 'warn', 5000);
      return;
    }
    if (devs.length === 1) {
      abrirEspiaDispositivo(devs[0].ID_Dispositivo);
      // Refrescar en background para próximas
      _refrescarDispositivosFresh().catch(() => {});
      return;
    }
    _selectorDispMostrar(nombre, devs, 'espia');
  }

  // ════════════════════════════════════════════════════════════════════
  // [v2.43.57] MODO ESPÍA V2 — WebRTC 4 streams (audio + cámara + screen + GPS)
  // ────────────────────────────────────────────────────────────────────
  // Layout: pantalla grande 70% + sidebar con audio/cámara/GPS.
  // Click cámara mini → swap con bounce. ⌖ → fullscreen.
  // Sincronización: badge color verde<2s, ámbar<5s, rojo>5s.
  // Efectos premium: glow halo, breathing LIVE, waveform real,
  // sonidos WebAudio sintetizados (pop/chime/shimmer/whoosh).
  // ════════════════════════════════════════════════════════════════════
  let _espiaV2 = null;  // { pc, sesionId, deviceId, masterId, streams:{}, pollTimer, focus:'pantalla', tsInicio }

  // Sonidos WebAudio sintetizados (sin samples)
  let _espiaAudioCtx = null;
  function _espiaSfx(tipo) {
    try {
      if (!_espiaAudioCtx) _espiaAudioCtx = new (window.AudioContext || window.webkitAudioContext)();
      const ctx = _espiaAudioCtx; const t = ctx.currentTime;
      function tone(freq, dur, gainVal, opts) {
        const o = ctx.createOscillator(); const g = ctx.createGain();
        o.type = (opts && opts.type) || 'sine';
        o.frequency.value = freq;
        g.gain.value = gainVal;
        o.connect(g); g.connect(ctx.destination);
        o.start(t + (opts && opts.delay || 0));
        g.gain.exponentialRampToValueAtTime(0.001, t + (opts && opts.delay || 0) + dur);
        o.stop(t + (opts && opts.delay || 0) + dur + .05);
      }
      if (tipo === 'pop')      { tone(440, .08, .12, {type:'triangle'}); }
      else if (tipo === 'chime') {
        tone(880, .15, .12, {type:'sine'});
        tone(1320, .18, .10, {type:'sine', delay:.06});
      }
      else if (tipo === 'shimmer') {
        tone(660, .12, .10, {type:'triangle'});
        tone(990, .15, .08, {type:'triangle', delay:.05});
        tone(1320, .18, .06, {type:'triangle', delay:.10});
      }
      else if (tipo === 'whoosh') {
        const o = ctx.createOscillator(); const g = ctx.createGain();
        o.type='sawtooth'; o.frequency.setValueAtTime(200,t); o.frequency.exponentialRampToValueAtTime(1200,t+.25);
        g.gain.setValueAtTime(.001,t); g.gain.exponentialRampToValueAtTime(.08,t+.05); g.gain.exponentialRampToValueAtTime(.001,t+.3);
        o.connect(g); g.connect(ctx.destination); o.start(t); o.stop(t+.32);
      }
      else if (tipo === 'fail') {
        tone(440, .12, .15, {type:'sawtooth'});
        tone(220, .15, .12, {type:'sawtooth', delay:.08});
      }
    } catch(_){}
  }

  // Punto de entrada — pide clave + crea sesión + abre modal optimista
  async function abrirEspiaV2(idDispositivo, esGuard, soloAudio) {
    if (!_esMasterSession()) { toast('Solo Master puede usar espía v2', 'error'); return; }
    let d = (cfgData.dispositivos || []).find(x => x.ID_Dispositivo === idDispositivo);
    // [MosGuard] los equipos de resguardo NO viven en mos.dispositivos: se arma un device sintético.
    // El equipo se entera de la sesión por el LATIDO (no por FCM), así que se salta el wake-push.
    if (!d && esGuard) d = { ID_Dispositivo: idDispositivo, Nombre_Equipo: idDispositivo, _guard: true };
    if (!d) { toast('Dispositivo no encontrado', 'error'); return; }
    // [v2.43.79] Limpiar zombis ANTES de mostrar prompt. Modal espiaV2Modal tiene
    // z-index 2147483646 (max int). Si quedó zombi de intento anterior, tapa
    // visualmente al modal de la clave (z-index 1500) y el master ve "nada
    // pasa" al click. Bug reproducido por el user en v2.43.77.
    const zombiModal = document.getElementById('espiaV2Modal');
    if (zombiModal) { console.warn('[espia master] limpiando modal zombi'); zombiModal.remove(); }
    if (_espiaV2 && _espiaV2.deviceId === idDispositivo) {
      toast('Ya estás conectado a este dispositivo', 'info');
      return;
    }
    if (_espiaV2) {
      const ok = await _modalConfirm(`Ya hay sesión activa con ${_espiaV2.nombre}. ¿Cerrarla y abrir nueva?`, { warning: true });
      if (!ok) return;
      _espiaV2Cerrar('cambio');
    }
    // [v2.43.64] Pedir clave admin tier 3 ANTES de crear sesión.
    // Bug histórico: v2.43.59 usaba _modalConfirm con promptInput, pero esa
    // función NO soporta inputs (es solo Sí/No), por eso devolvía true y el
    // regex /^\d{8}$/ fallaba → toast "Operación cancelada o clave inválida".
    // Fix: usar _modalPrompt que sí pinta input password.
    const claveAdmin = await _modalPrompt(
      `Para iniciar monitoreo en vivo de "${d.Nombre_Equipo || idDispositivo}":`,
      '',
      {
        titulo: '🛰️ Autorización Master',
        okText: 'Conectar',
        placeholder: '••••••••',
        inputType: 'password',
        inputMode: 'numeric',
        maxlength: 8
      }
    );
    if (claveAdmin === false || claveAdmin == null) {
      // Cancelado por el user — sin toast estridente
      return;
    }
    if (!/^\d{8}$/.test(String(claveAdmin))) {
      toast('La clave debe ser 8 dígitos (4 globales + 4 personales)', 'warn');
      return;
    }
    _espiaSfx('pop');
    const nombre = d.Ultima_Sesion || d.Nombre_Equipo || idDispositivo;
    _espiaV2 = {
      _claveAdmin: claveAdmin,
      sesionId: null,
      deviceId: idDispositivo,
      nombre: nombre,
      pc: null,
      streams: { audio: null, camara: null, camara2: null, pantalla: null },
      gpsUlt: null,
      pollTimer: null,
      pollIceDesde: 0,
      focus: 'pantalla',
      tsInicio: Date.now(),
      lagMs: 0,
      estado: 'conectando'
    };
    // [MosGuard] un celular = SOLO cámara + micrófono (no comparte pantalla). Fijamos las capabilities
    // YA, sin esperar el data-channel, para que el visor NUNCA muestre la UI de "compartir pantalla"
    // (era confuso: es un APK, no un navegador que elige qué compartir). El equipo igual reconfirma por el canal.
    if (esGuard) { _espiaV2.esGuard = true; _espiaV2.capabilities = { tienePantalla: false, esMobile: true, plataforma: 'mobile', camsTotales: 1 }; }
    _espiaV2RenderModal();
    // Crear sesión backend
    // [v2.43.66] API.post devuelve d.data DIRECTO (no {ok,data}). Bug histórico
    // documentado en memoria architecture_mos_api_shape.md — caí igual.
    console.log('[espia master] arrancando · deviceId=' + idDispositivo + ' master=' + (S.session?.idPersonal || S.session?.nombre || 'master'));
    try {
      console.log('[espia master] llamando espiaCrearSesion al backend...');
      const _masterId = S.session?.idPersonal || S.session?.nombre || 'master';
      let r = null;
      // [F6 espía · cero-GAS] Supabase-first: mos.espia_crear_sesion + wake push data-only por Edge. Fallback GAS.
      if (window.ESPIA_DIRECTO !== false && API.espiaRpc) {
        try {
          const cr = await API.espiaRpc('espia_crear_sesion', { masterId: _masterId, deviceId: idDispositivo, claveAdmin });
          if (cr && cr.ok && cr.data && cr.data.sesionId) {
            let pushOk = false;
            if (esGuard) {
              // [MosGuard] el equipo recoge la sesión en su latido (no hay FCM). Se deja pedida.
              try { await API.post('guardEspiaSet', { nombre: idDispositivo, sesionId: cr.data.sesionId, soloAudio: !!soloAudio }); } catch (_) {}
              pushOk = true;   // no dependemos del wake-push
            } else {
            try {
              const tk = await API.fcmTokenDispositivo(idDispositivo);
              const fcm = (tk && tk.data && tk.data.fcmToken) || '';
              if (fcm) {
                const pr = await API.pushEdge({ op: 'send', tokens: [fcm], silencioso: true,
                  data: { idNotif: 'MOS_ESPIA_INICIAR', action: 'MOS_ESPIA_INICIAR', sesionId: cr.data.sesionId, masterId: _masterId, ttl: String(cr.data.ttl || 600000) } });
                pushOk = !!(pr && pr.ok && pr.data && pr.data.enviados > 0);
              }
            } catch (_) { /* push best-effort */ }
            }
            r = { sesionId: cr.data.sesionId, token: 'sb:' + cr.data.sesionId, ttl: cr.data.ttl, pushOk };
          } else if (cr && cr.ok === false && !/APP_NO_AUTORIZADA/.test(String(cr.error || ''))) {
            // rechazo de negocio (clave mala / EN_VIVO otro master) → mostrar y NO ir a GAS (daría lo mismo).
            toast(cr.error || 'No se pudo iniciar el espía', 'error', 7000);
            _espiaV2Cerrar('error_init');
            return;
          }
        } catch (_) { /* [FUNERAL GAS] sin brazo de respaldo: r queda null y se avisa abajo */ }
      }
      if (!r) {
        // [FUNERAL GAS 14-ago] el brazo API.post('espiaCrearSesion') murió — el directo
        // (mos.espia_crear_sesion) es el ÚNICO camino; si no respondió, se reintenta.
        toast('No se pudo iniciar el espía (sin respuesta del servidor) — reintenta', 'error', 6000);
        _espiaV2Cerrar('error_init');
        return;
      }
      console.log('[espia master] respuesta backend:', r);
      if (!r || !r.sesionId) {
        toast('Backend no devolvió sesionId', 'error');
        _espiaV2Cerrar('error_init');
        return;
      }
      _espiaV2.sesionId = r.sesionId;
      _espiaV2.token    = r.token || null; // [v2.43.90] token HMAC
      _espiaV2.ttl      = r.ttl;
      // [v2.43.90] Si los 3 reintentos de FCM fallaron, avisar al master claramente
      // y NO crear el WebRTC — el device no se va a enterar de nada.
      if (r.pushOk === false) {
        // [800] Mensaje accionable: el fallo casi siempre es que el EQUIPO OBJETIVO no tiene la app
        // abierta o no dio permiso de notificaciones (sin token útil). No es un bug del panel.
        toast('No se pudo despertar el equipo. Debe tener su app ABIERTA y con notificaciones activadas. Si es una PC/laptop, el aviso remoto es poco fiable. (aviso falló ' + (r.pushIntentos || 3) + '×)', 'error', 10000);
        _espiaV2Cerrar('push_fallo');
        return;
      }
      _espiaV2IniciarPeerConnection();
    } catch(e) {
      // [v2.43.66] Si el backend devuelve 500, fetch ve "Failed to fetch" por CORS
      // (Apps Script no devuelve headers CORS en error). Diferenciamos por code.
      const msg = String(e?.message || 'Error desconocido');
      if (e?.code === 'NETWORK' || /Failed to fetch/i.test(msg)) {
        toast('⚠ Backend rechazó la petición (500). Revisa logs Apps Script o intentá de nuevo.', 'error', 8000);
      } else {
        toast('Error: ' + msg, 'error');
      }
      _espiaV2Cerrar('error_init');
    }
  }

  // [v2.43.90] Helper que inyecta token HMAC automáticamente en cada call.
  // Equivalente al _espiaCliWHPost del cliente. Todas las llamadas del módulo
  // espía pasan por acá.
  // [F6 espía · cero-GAS] acción→RPC Supabase (mos.espia_*). Supabase-first, fallback GAS. Mismo shape {ok,data}.
  const _ESPIA_RPC_MASTER = {
    espiaSync: 'espia_sync', espiaPushBatch: 'espia_push_batch', espiaSubirOferta: 'espia_subir_oferta',
    espiaSubirRespuesta: 'espia_subir_respuesta', espiaSubirRenegRespuesta: 'espia_subir_reneg_respuesta',
    espiaAgregarIce: 'espia_agregar_ice', espiaReportarStreams: 'espia_reportar_streams', espiaCerrarSesion: 'espia_cerrar_sesion'
  };
  async function _espiaApiPost(action, params) {
    const body = Object.assign({}, params || {});
    const rpc = _ESPIA_RPC_MASTER[action];
    if (rpc && window.ESPIA_DIRECTO !== false && API.espiaRpc) {
      // [40x fix] DESEMPAQUETAR .data: el loop master lee d.estado/sdpRespuesta/ice PLANO (GAS API.post ya
      // desempaqueta). Sin esto, vía Supabase quedaban undefined → master colgado (no aplica answer/ICE/cierre).
      try { const out = await API.espiaRpc(rpc, body); if (out) return (out.data !== undefined ? out.data : out); } catch (_) { /* → GAS */ }
    }
    const token = _espiaV2?.token;
    if (token && body.token === undefined) body.token = token;
    return await API.post(action, body);
  }

  async function _espiaV2IniciarPeerConnection() {
    if (!_espiaV2) return;
    // [v2.43.90] Pedir iceServers al backend (TURN si configurado).
    // Sin TURN, ~10% de redes con NAT simétrico no conectan jamás.
    let iceServers = [{ urls: ['stun:stun.l.google.com:19302', 'stun:stun1.l.google.com:19302'] }];
    try {
      const cfg = await API.post('espiaConfig', {});
      if (Array.isArray(cfg?.iceServers) && cfg.iceServers.length) {
        iceServers = cfg.iceServers;
        if (cfg.tieneTurn) console.log('[espia master] TURN disponible');
      }
    } catch(eC) { console.warn('[espia master] espiaConfig fallo (uso STUN local):', eC?.message); }
    if (!_espiaV2) return;
    const pc = new RTCPeerConnection({ iceServers });
    _espiaV2.pc = pc;
    // [v2.43.90] Watchdog ICE failed → cierre graceful tras 30s
    _espiaV2._iceFailedDesde = 0;
    _espiaV2._iceWatchdogTimer = setInterval(() => {
      if (!_espiaV2 || !_espiaV2._iceFailedDesde) return;
      if (Date.now() - _espiaV2._iceFailedDesde > 30000) {
        console.warn('[espia master] ICE failed >30s · cerrando');
        toast('Conexión perdida con el dispositivo', 'warn');
        _espiaV2Cerrar('ice_failed_persistente');
      }
    }, 5000);
    // [v2.43.90] Timeout 45s en estado "conectando" — si el device no acepta
    // permisos o el WebRTC no completa, mostrar mensaje claro en vez de spinner eterno.
    _espiaV2._timeoutConectando = setTimeout(() => {
      if (!_espiaV2) return;
      if (_espiaV2.estado === 'live' || pc.connectionState === 'connected') return;
      toast('El dispositivo no respondió en 45s. Posibles causas: permisos no aceptados, pantalla apagada, sin red.', 'warn', 10000);
      _espiaV2Cerrar('timeout_conectando');
    }, 45000);
    // Track recibido: asignar al video/audio element del modal
    // [v2.43.77] Identificación robusta de pantalla. Antes solo miraba si
    // track.label contenía 'screen'/'display' — falla cuando Chrome devuelve
    // labels como 'web-contents-media-stream://...' o nombre de ventana →
    // se trataba como cámara y 'pantalla' quedaba esperando para siempre.
    // Fix: usar track.getSettings().displaySurface (solo existe en
    // getDisplayMedia tracks) + fallback al label.
    // [v2.43.91] Identificación robusta de tracks. Tres niveles de evidencia:
    //   1. trackTipoMap recibido por DataChannel 'gps' (mensaje __meta)
    //   2. track.contentHint propagado vía SDP ('detail'=pantalla, 'motion'=cam)
    //   3. fallback heurístico por label (legacy)
    // El primer track que llega puede no tener mapping todavía → asignamos por
    // contentHint y reasignamos cuando llegue el __meta. Por eso guardamos
    // referencias a ev.streams[0] junto al trackId para poder rebalancear.
    _espiaV2._tracksRecibidos = _espiaV2._tracksRecibidos || [];
    pc.ontrack = (ev) => {
      const stream = ev.streams[0];
      const track  = ev.track;
      const info = { trackId: track.id, stream, kind: track.kind, contentHint: track.contentHint };
      // [v2.43.99] Dedup por trackId — si llega el mismo track 2 veces (raro
      // pero posible en renegs largas), actualizar en lugar de duplicar.
      const idx = _espiaV2._tracksRecibidos.findIndex(t => t.trackId === info.trackId);
      if (idx >= 0) _espiaV2._tracksRecibidos[idx] = info;
      else _espiaV2._tracksRecibidos.push(info);
      _espiaV2AsignarTrack(info);
      _espiaSfx('chime');
      _espiaV2RenderModal();
    };
    // [v2.43.81] DataChannel STUB del lado master para forzar m=application
    // en el SDP offer. Sin esto, el cliente WH creaba un DataChannel 'gps'
    // pero el SDP no lo negociaba → readyState quedaba 'connecting' eterno.
    try {
      const stubDc = pc.createDataChannel('master-stub', { negotiated: false, ordered: true });
      stubDc.onopen = () => console.log('[espia master] stub DC abierto');
    } catch(eS) { console.warn('[espia master] no se pudo crear stub DC:', eS.message); }
    // [v2.43.90] ICE recovery + tracking de failed para watchdog 30s
    pc.oniceconnectionstatechange = () => {
      console.log('[espia master] ICE state:', pc.iceConnectionState);
      if (!_espiaV2) return;
      if (pc.iceConnectionState === 'failed') {
        if (!_espiaV2._iceFailedDesde) _espiaV2._iceFailedDesde = Date.now();
        try { pc.restartIce(); } catch(eRi) { console.warn('[espia master] restartIce fallo:', eRi.message); }
      } else if (pc.iceConnectionState === 'connected' || pc.iceConnectionState === 'completed') {
        _espiaV2._iceFailedDesde = 0;
      }
    };
    // DataChannel para GPS (device → master)
    pc.ondatachannel = (ev) => {
      const dc = ev.channel;
      console.log('[espia master] datachannel recibido:', dc.label);
      if (dc.label === 'gps') {
        // [rotar-cam] El canal 'gps' es bidireccional una vez abierto. Guardamos la referencia para
        // poder MANDAR comandos al device (ej. ROTAR_CAM) además de recibir GPS/__meta.
        if (_espiaV2) _espiaV2.cmdCh = dc;
        dc.onmessage = (msg) => {
          try {
            const data = JSON.parse(msg.data);
            // [rotar-cam] ACKs del device ante el comando de rotar cámara.
            if (data && data.__ack) {
              if (data.__ack === 'ROTAR_OK') { try { _espiaSfx('shimmer'); toast('Cámara rotada ✓', 'ok', 2200); } catch(_){} }
              else if (data.__ack === 'ROTAR_FAIL') { try { toast('El equipo no pudo rotar la cámara', 'warn', 2600); } catch(_){} }
              return;
            }
            if (data && data.__meta === 'trackMap' && data.map) {
              _espiaV2AplicarTrackMap(data.map);
              return;
            }
            // [v2.43.100] Capabilities: el cliente describe su plataforma
            // (PC/móvil/tablet) para que el modal adapte UI sin adivinar.
            if (data && data.__meta === 'capabilities' && data.caps) {
              _espiaV2.capabilities = data.caps;
              console.log('[espia master] capabilities recibidas:', data.caps);
              _espiaV2AutoFocus();
              _espiaV2RenderModal();
              return;
            }
            // [v2.43.104] Visibility del cliente — pantalla bloqueada / desbloqueada
            if (data && data.__meta === 'visibility') {
              _espiaV2.deviceVisible = !!data.visible;
              _espiaV2._tsCambioVisibilidad = Date.now(); // usado para overlay timeout
              console.log('[espia master] device visibility:', data.visible ? 'visible' : 'hidden');
              _espiaV2RenderModal();
              return;
            }
            _espiaV2.gpsUlt = data;
            _espiaV2RenderGpsMini();
          } catch(_){}
        };
      }
    };
    // [v2.43.90] ICE batch — cola con flush cada 250ms vía espiaPushBatch
    _espiaV2._iceQueue = [];
    pc.onicecandidate = (ev) => {
      if (!_espiaV2 || !ev.candidate) return;
      const c = ev.candidate.toJSON ? ev.candidate.toJSON() : ev.candidate;
      _espiaV2._iceQueue.push(c);
    };
    _espiaV2._iceFlushTimer = setInterval(async () => {
      if (!_espiaV2 || !_espiaV2._iceQueue.length) return;
      const batch = _espiaV2._iceQueue.splice(0, _espiaV2._iceQueue.length);
      try {
        await _espiaApiPost('espiaPushBatch', {
          sesionId: _espiaV2.sesionId, lado: 'master',
          ice: batch.map(c => ({ ice: c }))
        });
      } catch(_){}
    }, 250);
    pc.onconnectionstatechange = () => {
      const st = pc.connectionState;
      if (!_espiaV2) return;
      _espiaV2.estado = st;
      if (st === 'connected') {
        _espiaSfx('chime');
        _espiaV2.estado = 'live';
        // [v2.43.90] Cancelar timeout 45s "conectando..." — ya conectó
        if (_espiaV2._timeoutConectando) {
          clearTimeout(_espiaV2._timeoutConectando);
          _espiaV2._timeoutConectando = null;
        }
        _espiaV2RenderModal();
      } else if (st === 'failed' || st === 'disconnected') {
        _espiaSfx('fail');
        _espiaV2.estado = st;
        _espiaV2RenderModal();
      }
    };
    // [v2.43.70] Guards defensivos contra cierre del modal durante awaits.
    const offer = await pc.createOffer({ offerToReceiveAudio: true, offerToReceiveVideo: true });
    if (!_espiaV2) return;
    await pc.setLocalDescription(offer);
    if (!_espiaV2) return;
    await _espiaApiPost('espiaSubirOferta', { sesionId: _espiaV2.sesionId, sdp: JSON.stringify(offer) });
    if (!_espiaV2) return;
    // Polling de respuesta + ICE del device
    _espiaV2.pollTimer = setInterval(_espiaV2Poll, 600);
    // [833] Repintado único al vencer la espera de streams: si a los 15s la pantalla no llegó,
    // su tile sale del mosaico y el placeholder explica por qué. Sin esto el visor no se
    // refresca hasta el próximo evento y el spinner se queda eterno.
    const _sesEspera = _espiaV2.sesionId;
    setTimeout(() => {
      if (_espiaV2 && _espiaV2.sesionId === _sesEspera) { try { _espiaV2RenderModal(); } catch(_){} }
    }, 15400);
  }

  // [v2.43.89 REFACTOR] BATCH SYNC — antes 3-4 round-trips Apps Script por tick,
  // ahora 1 con espiaSync. Devuelve respuesta inicial + reneg oferta + ICE del
  // device + estado en una sola llamada. Más rápido, menos cuota, menos races.
  async function _espiaV2Poll() {
    if (!_espiaV2 || !_espiaV2.sesionId) return;
    if (_espiaV2._pollEnCurso) return;
    _espiaV2._pollEnCurso = true;
    try {
      const t0 = Date.now();
      if (!_espiaV2.pc) return;

      const pc = _espiaV2.pc;
      const necesitaRespuesta = !pc.remoteDescription &&
                                !_espiaV2._settingAnswer &&
                                pc.signalingState === 'have-local-offer';
      const puedeReneg = pc.signalingState === 'stable' && !_espiaV2._renegEnCurso;

      // [v2.43.90] Backoff exponencial — saltamos ticks ante errores consecutivos
      if (_espiaV2._ticksAEsperar > 0) { _espiaV2._ticksAEsperar--; return; }

      // 1 sola llamada al backend que devuelve TODO lo que el master necesita
      let d;
      try {
        d = await _espiaApiPost('espiaSync', {
          sesionId: _espiaV2.sesionId,
          lado: 'master',
          iceDesde: _espiaV2.pollIceDesde || 0,
          necesito: {
            sdpRespuesta:    necesitaRespuesta,
            sdpRenegOferta:  puedeReneg,
            ice:             true
          }
        });
        if (_espiaV2 && _espiaV2._consErrores > 0) _espiaV2._consErrores = 0;
      } catch(eS) {
        if (_espiaV2) {
          _espiaV2._consErrores = (_espiaV2._consErrores || 0) + 1;
          _espiaV2._ticksAEsperar = Math.min(14, Math.pow(2, _espiaV2._consErrores) - 1);
        }
        throw eS;
      }
      if (!_espiaV2) return;
      if (!d) return;

      // (1) Cierre remoto — el device cerró por su lado o TTL expiró
      if (d.estado === 'CERRADA') {
        console.log('[espia master] backend reporta CERRADA · cerrando UI', d);
        // [v2.43.93] UX honesto — toast con causa probable antes de cerrar
        const motivo = d.motivoFin || 'desconocido';
        let mensaje = 'El equipo cerró la sesión de monitoreo';
        if (/ice_failed/i.test(motivo)) {
          mensaje = '⚠ No se pudo conectar (redes distintas sin TURN). Ponte en la misma wifi que el equipo, o configura TURN.';
        } else if (/sin_streams/i.test(motivo)) {
          // [800] causa MUY común: el equipo objetivo no pudo capturar cámara/mic.
          mensaje = 'El equipo no pudo abrir su cámara/micrófono. Debe estar DESBLOQUEADO, con la app al frente y con permiso de cámara. (Las PC de escritorio muchas veces no tienen cámara.)';
        } else if (/page_unload/i.test(motivo)) {
          mensaje = 'El usuario cerró la app en el equipo.';
        } else if (/connection_/i.test(motivo)) {
          mensaje = '⚠ La conexión se cayó (' + motivo + '). Probablemente redes distintas sin TURN.';
        }
        toast(mensaje, 'warn', 8000);
        _espiaV2Cerrar('device_cerro');
        return;
      }

      // (2) Respuesta del handshake inicial
      if (necesitaRespuesta && d.sdpRespuesta) {
        _espiaV2._settingAnswer = true;
        try {
          if (_espiaV2 && !pc.remoteDescription && pc.signalingState === 'have-local-offer') {
            await pc.setRemoteDescription(JSON.parse(d.sdpRespuesta));
          }
        } catch(e) { console.warn('[espia] respuesta inválida', e?.message); }
        finally { if (_espiaV2) _espiaV2._settingAnswer = false; }
      }
      if (!_espiaV2) return;

      // (3) ICE candidates del device (batched).
      // [v2.43.93] addIceCandidate requiere remoteDescription previo. Si el
      // cliente sube ICE antes que el answer (ICE gathering empieza apenas
      // setLocalDescription dispara), los candidates llegan acá pero pc.remoteDescription
      // es null → se PERDÍAN silenciosos. Encolamos hasta tener remoteDescription.
      if (d.ice?.length) {
        if (!pc.remoteDescription) {
          _espiaV2._iceQueueAplicar = (_espiaV2._iceQueueAplicar || []).concat(d.ice);
          console.log('[espia master] ICE encolado · ' + d.ice.length + ' (sin remoteDescription aún)');
        } else {
          for (const c of d.ice) {
            try { await pc.addIceCandidate(c.ice); }
            catch(eC) { console.warn('[espia master] addIceCandidate fallo:', eC?.message); }
          }
        }
        if (_espiaV2 && d.tsMax) _espiaV2.pollIceDesde = d.tsMax;
      }
      // Drenar cola si ya tenemos remoteDescription (fue seteada en esta iter o anterior)
      if (_espiaV2 && pc.remoteDescription && _espiaV2._iceQueueAplicar?.length) {
        const cola = _espiaV2._iceQueueAplicar;
        _espiaV2._iceQueueAplicar = [];
        for (const c of cola) {
          try { await pc.addIceCandidate(c.ice); }
          catch(eC) { console.warn('[espia master] addIceCandidate cola fallo:', eC?.message); }
        }
        console.log('[espia master] ICE drenado · ' + cola.length + ' aplicados tras setRemoteDescription');
      }

      // (4) Renegociación: device subió oferta nueva (ej. agregó pantalla)
      if (_espiaV2 && puedeReneg && d.sdpRenegOferta) {
        _espiaV2._renegEnCurso = true;
        try {
          if (pc.signalingState !== 'stable') {
            // state cambió mientras esperabamos — descartar
          } else {
            const ofertaStr = d.sdpRenegOferta;
            const yaProcesada = _espiaV2._ultimaOfertaProcesada === ofertaStr;
            if (yaProcesada && _espiaV2._ultimaAnswerSinSubir) {
              // Subida de respuesta falló antes → solo reintentar subida
              console.log('[espia master] retry subida answer (no reprocesar)');
              await _espiaApiPost('espiaSubirRenegRespuesta', {
                sesionId: _espiaV2.sesionId,
                sdp: _espiaV2._ultimaAnswerSinSubir
              });
              _espiaV2._ultimaAnswerSinSubir = null;
            } else if (!yaProcesada) {
              console.log('[espia master] reneg offer detectada · procesando');
              await pc.setRemoteDescription(JSON.parse(ofertaStr));
              const newAnswer = await pc.createAnswer();
              await pc.setLocalDescription(newAnswer);
              const answerStr = JSON.stringify(newAnswer);
              _espiaV2._ultimaOfertaProcesada = ofertaStr;
              _espiaV2._ultimaAnswerSinSubir = answerStr;
              await _espiaApiPost('espiaSubirRenegRespuesta', {
                sesionId: _espiaV2.sesionId, sdp: answerStr
              });
              _espiaV2._ultimaAnswerSinSubir = null;
              console.log('[espia master] reneg answer enviada · pantalla negociada ✓');
            }
          }
        } catch(eR) {
          console.warn('[espia master reneg]', eR?.message);
        } finally {
          if (_espiaV2) _espiaV2._renegEnCurso = false;
        }
      }

      // Tracking de lag visible en el badge
      if (_espiaV2) {
        _espiaV2.lagMs = Date.now() - t0;
        _espiaV2RenderSyncBadge();
      }
    } catch(e) {
      console.warn('[espia poll]', e?.message || e);
    } finally {
      if (_espiaV2) _espiaV2._pollEnCurso = false;
    }
  }

  // [v2.43.97] Asigna un track recibido a streams[tipo].
  // Tipos posibles: audio | pantalla | camara | camara2 (smartphone dual-cam)
  function _espiaV2AsignarTrack(info) {
    if (!_espiaV2) return;
    let tipo;
    if (info.kind === 'audio') {
      tipo = 'audio';
    } else {
      // 1) Mapping explícito del DataChannel (incluye 'camara2')
      const mapeado = _espiaV2._trackTipoMap?.[info.trackId];
      if (mapeado) tipo = mapeado;
      // 2) contentHint vía SDP
      else if (info.contentHint === 'detail') tipo = 'pantalla';
      else if (info.contentHint === 'motion') {
        // si ya hay camara, el siguiente motion es camara2 (dual smartphone)
        tipo = _espiaV2.streams.camara ? 'camara2' : 'camara';
      }
      // 3) Default
      else if (_espiaV2.streams.camara && !_espiaV2.streams.pantalla) tipo = 'pantalla';
      else if (_espiaV2.streams.camara) tipo = 'camara2';
      else tipo = 'camara';
    }
    _espiaV2.streams[tipo] = info.stream;
    console.log('[espia ontrack] trackId=' + String(info.trackId).substring(0,8) + ' contentHint=' + (info.contentHint || '?') + ' → tipo=' + tipo);
    _espiaV2ActualizarStream(tipo, info.stream);
    // [v2.43.98] Si focus actual no tiene stream y este sí, hacer focus
    if (tipo !== 'audio') _espiaV2AutoFocus();
    _espiaApiPost('espiaReportarStreams', {
      sesionId: _espiaV2.sesionId,
      streams: {
        audio:    !!_espiaV2.streams.audio,
        camara:   !!_espiaV2.streams.camara,
        camara2:  !!_espiaV2.streams.camara2,
        pantalla: !!_espiaV2.streams.pantalla
      }
    }).catch(()=>{});
  }

  // [v2.43.98 FIX BUG #1] Two-pass apply atómico (mejor que el de v2.43.92).
  // Antes el loop podía borrar un slot recién asignado por otro track:
  //   trackA → camara2 (limpia camara donde estaba)
  //   trackB → camara  (limpia camara2 que acabamos de poner a trackA)
  //   → trackA perdido.
  // Pass 1 construye state objetivo. Pass 2 asigna de una vez. Los tracks NO
  // mencionados en el map preservan su slot previo por heurística/contentHint.
  function _espiaV2AplicarTrackMap(map) {
    if (!_espiaV2 || !map) return;
    _espiaV2._trackTipoMap = Object.assign({}, _espiaV2._trackTipoMap, map);
    const videos = (_espiaV2._tracksRecibidos || []).filter(t => t.kind === 'video');
    if (!videos.length) return;

    // Early exit: map vacío → nada que aplicar
    if (Object.keys(map).length === 0) return;

    const nuevoEstado = { camara: null, camara2: null, pantalla: null };
    // Pass 1a: aplicar mapping explícito (tiene prioridad)
    videos.forEach(t => {
      const tipoNuevo = map[t.trackId];
      if (tipoNuevo && ['camara', 'camara2', 'pantalla'].indexOf(tipoNuevo) >= 0) {
        nuevoEstado[tipoNuevo] = t.stream;
      }
    });
    // Pass 1b: tracks sin mapping → preservar su slot previo si está libre
    videos.forEach(t => {
      if (map[t.trackId]) return;
      ['camara', 'camara2', 'pantalla'].forEach(slot => {
        if (_espiaV2.streams[slot] === t.stream && !nuevoEstado[slot]) {
          nuevoEstado[slot] = t.stream;
        }
      });
    });
    // Pass 1c: tracks sin mapping cuyo slot previo está ocupado → cualquier slot libre
    // Sin este pass, un map parcial que mueve trackA al slot de trackB perdía trackB.
    videos.forEach(t => {
      if (map[t.trackId]) return;
      if (['camara','camara2','pantalla'].some(slot => nuevoEstado[slot] === t.stream)) return;
      const slotLibre = ['camara2', 'camara', 'pantalla'].find(slot => !nuevoEstado[slot]);
      if (slotLibre) nuevoEstado[slotLibre] = t.stream;
    });

    const cambio = nuevoEstado.camara   !== _espiaV2.streams.camara   ||
                   nuevoEstado.camara2  !== _espiaV2.streams.camara2  ||
                   nuevoEstado.pantalla !== _espiaV2.streams.pantalla;
    if (cambio) {
      // Pass 2: asignación atómica
      _espiaV2.streams.camara   = nuevoEstado.camara;
      _espiaV2.streams.camara2  = nuevoEstado.camara2;
      _espiaV2.streams.pantalla = nuevoEstado.pantalla;
      _espiaV2AutoFocus();
      console.log('[espia trackMap] reasignado · camara=' + !!_espiaV2.streams.camara + ' camara2=' + !!_espiaV2.streams.camara2 + ' pantalla=' + !!_espiaV2.streams.pantalla);
      _espiaV2RenderModal();
    }
  }

  // [v2.43.100] AutoFocus respeta capabilities.
  // En móvil donde tienePantalla=false, jamás vamos a tener stream de pantalla,
  // así que no tiene sentido siquiera intentar dejar focus en 'pantalla'.
  function _espiaV2AutoFocus() {
    if (!_espiaV2) return;
    if (_espiaV2.streams[_espiaV2.focus]) return;
    const caps = _espiaV2.capabilities;
    const orden = (caps && caps.tienePantalla === false)
      ? ['camara', 'camara2'] // móvil: pantalla no aplica nunca
      : ['pantalla', 'camara', 'camara2'];
    const primero = orden.find(k => !!_espiaV2.streams[k]);
    if (primero && primero !== _espiaV2.focus) {
      console.log('[espia focus] auto-switch · ' + _espiaV2.focus + ' → ' + primero);
      _espiaV2.focus = primero;
    }
  }

  function _espiaV2Cerrar(motivo) {
    if (!_espiaV2) return;
    try { _espiaSfx('whoosh'); } catch(_){}
    if (_espiaV2.pollTimer) clearInterval(_espiaV2.pollTimer);
    // [v2.43.90] Limpiar TODOS los timers nuevos
    try { clearInterval(_espiaV2._iceFlushTimer); } catch(_){}
    try { clearInterval(_espiaV2._iceWatchdogTimer); } catch(_){}
    try { clearTimeout(_espiaV2._timeoutConectando); } catch(_){}
    try { clearTimeout(_espiaV2._renderTimeout); } catch(_){}
    try { clearTimeout(_espiaV2._ctrlTimer); } catch(_){} // [v2.44] timer auto-hide de controles
    // Flush final ICE pendientes
    if (_espiaV2._iceQueue?.length && _espiaV2.sesionId && _espiaV2.token) {
      _espiaApiPost('espiaPushBatch', {
        sesionId: _espiaV2.sesionId, lado: 'master',
        ice: _espiaV2._iceQueue.map(c => ({ ice: c }))
      }).catch(()=>{});
    }
    try { _espiaV2.pc?.close(); } catch(_){}
    Object.values(_espiaV2.streams).forEach(s => {
      try { s?.getTracks().forEach(t => t.stop()); } catch(_){}
    });
    if (_espiaV2.sesionId) {
      _espiaApiPost('espiaCerrarSesion', { sesionId: _espiaV2.sesionId, motivo: motivo || 'manual', lado: 'master' }).catch(()=>{});
    }
    const modal = document.getElementById('espiaV2Modal');
    if (modal) {
      modal.style.animation = 'espiaV2Out .3s ease-out forwards';
      setTimeout(() => modal.remove(), 300);
    }
    _espiaV2 = null;
  }

  // [v2.44] REDISEÑO INMERSIVO — visor edge-to-edge estilo consola de
  // seguridad: MOSAICO de todas las cámaras activas del equipo (trasera +
  // frontal + pantalla) a la vez, controles flotantes glass que se auto-ocultan,
  // tap para expandir un tile a solo-pantalla, screenshot por tile y toggle de
  // audio. Reusa las piezas vivas: live-dot, badge plataforma, badge sync/lag
  // (#espiaV2SyncBadge), overlay standby, spinner conectando, panel GPS + audio
  // (#espiaV2Wave/#espiaV2GpsInfo…). NO toca WebRTC/plumbing.
  function _espiaV2RenderModal() {
    if (!_espiaV2) return;
    // [v2.43.98] Auto-focus defensivo antes de render — por si llegamos acá
    // con focus en slot vacío (race entre RenderModal y AsignarTrack).
    _espiaV2AutoFocus();
    // Defaults de vista (el objeto _espiaV2 se crea sin estos campos)
    if (!_espiaV2.vista) _espiaV2.vista = 'mosaico';

    const orden = ['pantalla', 'camara', 'camara2'];
    const META = {
      pantalla: { icon: '🖥️', label: 'Pantalla', color: '16,185,129' },
      camara:   { icon: '📷', label: 'Trasera',  color: '99,102,241' },
      camara2:  { icon: '🤳', label: 'Frontal',  color: '244,114,182' }
    };
    const s = _espiaV2.streams;
    const caps = _espiaV2.capabilities;
    const live = _espiaV2.estado === 'live';

    // ── Qué tiles mostrar ──────────────────────────────────────────────
    // activos = streams ya recibidos. esperados = lo que las capabilities
    // predicen que llegará (para pintar placeholders con spinner mientras
    // conecta). Unión ordenada; si aún no hay nada, un solo tile placeholder.
    const activos = orden.filter(k => s[k]);
    // [833] Un stream ESPERADO solo reserva su tile mientras razonablemente puede estar llegando.
    // `tienePantalla` es true en toda PC con Chrome porque existe getDisplayMedia — pero esa API
    // exige que la PERSONA acepte el diálogo "Elige qué compartir", y una cajera nunca lo hace.
    // Sin este corte, el mosaico se quedaba con un tile de pantalla negro y un spinner eterno.
    const _espMs = Date.now() - (_espiaV2.tsInicio || Date.now());
    const _aunLlega = _espMs < 15000;
    const esperados = [];
    if (caps) {
      if (caps.tienePantalla === true && (s.pantalla || _aunLlega)) esperados.push('pantalla');
      if (((caps.camsTotales || 0) >= 1 || caps.esMobile) && (s.camara || _aunLlega)) esperados.push('camara');
      if ((caps.camsTotales || 0) >= 2 && (s.camara2 || _aunLlega)) esperados.push('camara2');
    }
    let visibles = orden.filter(k => activos.indexOf(k) >= 0 || esperados.indexOf(k) >= 0);
    if (!visibles.length) {
      visibles = [(caps && caps.tienePantalla === false) ? 'camara' : 'pantalla'];
    }

    // ── Modo solo (tile expandido) ─────────────────────────────────────
    const solo = _espiaV2.vista === 'solo' && _espiaV2.soloStream;
    let tiles = visibles;
    if (solo) {
      let k = _espiaV2.soloStream;
      if (orden.indexOf(k) < 0 || visibles.indexOf(k) < 0) k = visibles[0];
      _espiaV2.soloStream = k;
      tiles = [k];
    }
    const n = tiles.length;

    // ── Tiles del mosaico ──────────────────────────────────────────────
    const tilesHtml = tiles.map((k, i) => {
      const m = META[k] || META.camara;
      const stream = s[k];
      const activo = !!stream;
      return `<div class="espiaV2-tile" data-key="${k}" style="position:relative;background:#000;border-radius:${solo ? '0' : '14px'};overflow:hidden;border:${solo ? '0' : '1px solid rgba(' + m.color + ',.4)'};box-shadow:${solo ? 'none' : '0 12px 44px -14px rgba(' + m.color + ',.55),0 0 0 1px rgba(' + m.color + ',.08) inset'};${solo ? '' : 'cursor:pointer'};transition:border-color .3s,box-shadow .3s"
        ${solo ? '' : `onclick="MOS._espiaV2ExpandirTile('${k}')"`}>
        <video id="espiaV2Vid_${k}" autoplay playsinline muted style="width:100%;height:100%;object-fit:contain;background:#000;display:block"></video>
        <div class="espiaV2-chip" style="position:absolute;top:12px;left:12px;display:flex;align-items:center;gap:7px;font-size:11px;font-weight:800;color:#fff;background:rgba(10,15,25,.55);padding:5px 11px;border-radius:20px;backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);border:1px solid rgba(${m.color},.5);letter-spacing:.3px;z-index:4">
          <span style="font-size:13px">${m.icon}</span>${m.label}
          <span title="${activo ? 'stream activo' : 'sin señal'}" style="width:7px;height:7px;border-radius:50%;background:${activo ? '#10b981' : '#64748b'};${activo ? 'box-shadow:0 0 8px #10b981;animation:espiaBreath 1.6s ease-in-out infinite' : ''}"></span>
        </div>
        <button onclick="event.stopPropagation();MOS._espiaV2Captura('${k}')" title="Capturar imagen"
          style="position:absolute;top:10px;right:10px;background:rgba(10,15,25,.55);border:1px solid rgba(255,255,255,.18);color:#fff;border-radius:11px;width:36px;height:36px;font-size:15px;cursor:pointer;z-index:4;backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);display:flex;align-items:center;justify-content:center;transition:background .15s"
          onmouseover="this.style.background='rgba(99,102,241,.6)'" onmouseout="this.style.background='rgba(10,15,25,.55)'">📸</button>
        ${!solo ? `<div class="espiaV2-tile-hint" style="position:absolute;bottom:12px;right:12px;font-size:9px;font-weight:700;color:#e2e8f0;background:rgba(10,15,25,.5);padding:4px 9px;border-radius:14px;backdrop-filter:blur(8px);-webkit-backdrop-filter:blur(8px);border:1px solid rgba(255,255,255,.12);z-index:4;letter-spacing:.3px;opacity:.85">⤢ ampliar</div>` : ''}
        ${!activo ? `<div style="position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;background:radial-gradient(circle at 50% 40%,#0f172a,#05070d);color:#64748b;padding:20px;text-align:center">
            ${_aunLlega
              ? `<div style="width:46px;height:46px;border:3px solid rgba(${m.color},.25);border-top-color:rgba(${m.color},1);border-radius:50%;animation:espiaSpin 1s linear infinite"></div>
                 <div style="margin-top:14px;font-size:11px;color:#94a3b8;font-weight:600">Conectando ${m.label.toLowerCase()}…</div>`
              /* [833] Pasados los 15s ya no está "conectando": no llegó. Se dice por qué. */
              : `<div style="font-size:38px;opacity:.5">${k === 'pantalla' ? '🖥️' : '📷'}</div>
                 <div style="margin-top:10px;font-size:12.5px;color:#cbd5e1;font-weight:800">Sin ${m.label.toLowerCase()}</div>
                 <div style="margin-top:7px;font-size:10.5px;color:#7488a6;line-height:1.55;max-width:280px">${
                   k === 'pantalla'
                     ? 'El navegador NO comparte la pantalla solo: en ese equipo tiene que aparecer el aviso de Chrome «Elige qué compartir» y alguien debe aceptarlo. En celulares no existe esa opción.'
                     : 'El equipo no entregó la cámara: puede estar tapada, en uso por otra app o sin permiso concedido.'}</div>`}
          </div>` : ''}
      </div>`;
    }).join('');

    // ── Overlay STANDBY global (deviceVisible===false) ─────────────────
    const standbyHtml = (_espiaV2.deviceVisible === false) ? (() => {
      const hidd = _espiaV2._tsCambioVisibilidad ? (Date.now() - _espiaV2._tsCambioVisibilidad) : 0;
      const segs = Math.floor(hidd / 1000);
      const muyLargo = hidd > 120000; // 2 min
      return `<div style="position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;background:rgba(2,6,23,.82);backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);color:#e2e8f0;z-index:20">
        <div style="font-size:52px;margin-bottom:10px">${muyLargo ? '⚠️' : '🌙'}</div>
        <div style="font-size:17px;font-weight:800;color:${muyLargo ? '#f59e0b' : '#a5b4fc'};letter-spacing:.3px">${muyLargo ? 'STANDBY PROLONGADO' : 'DISPOSITIVO EN STANDBY'}</div>
        <div style="margin-top:10px;font-size:12px;color:#94a3b8;max-width:300px;text-align:center;line-height:1.5">${muyLargo
          ? 'Pantalla bloqueada hace +' + Math.floor(segs / 60) + 'min. Probablemente los tracks fueron liberados por el SO.<br>Tendrás que reiniciar el espía.'
          : 'El usuario bloqueó la pantalla o cambió de app.<br>El stream se reanudará al volver.'}</div>
        <div style="margin-top:14px;display:flex;align-items:center;gap:8px;font-size:10px;color:#64748b">
          <span style="width:6px;height:6px;border-radius:50%;background:${muyLargo ? '#ef4444' : '#f59e0b'};animation:espiaBreath 1.5s ease-in-out infinite"></span>
          ${muyLargo ? 'sin señal del device' : 'esperando reanudación (' + segs + 's)'}
        </div>
      </div>`;
    })() : '';

    // ── Badge de plataforma (reusa lógica existente) ───────────────────
    const badgePlataforma = (() => {
      const c = caps;
      if (!c) return '';
      const meta = c.plataforma === 'mobile' ? { icon: '📱', color: '244,114,182' }
                 : c.plataforma === 'tablet' ? { icon: '📲', color: '139,92,246' }
                 : { icon: '🖥️', color: '14,165,233' };
      return `<div style="font-size:10px;font-weight:800;padding:4px 10px;border-radius:20px;background:rgba(${meta.color},.15);color:rgba(${meta.color},1);border:1px solid rgba(${meta.color},.4);display:flex;align-items:center;gap:5px;white-space:nowrap"
          title="${_escapeHtml(c.modelo || '')} · ${c.camsTotales || 0} cam · pantalla=${c.tienePantalla ? 'sí' : 'no'}">
          ${meta.icon} ${_escapeHtml((c.modelo || c.plataforma).toUpperCase())}
        </div>`;
    })();

    // [802] Nota "los celulares no comparten pantalla" — evita la confusión de "¿por qué no veo la
    // pantalla?" al espiar un móvil (getDisplayMedia está bloqueado en navegadores móviles).
    const notaPantalla = (caps && caps.tienePantalla === false)
      ? `<div title="Es un celular: transmite cámara y micrófono en vivo. La pantalla no se comparte (no aplica a un teléfono)." style="font-size:9.5px;font-weight:700;padding:3px 9px;border-radius:20px;background:rgba(148,163,184,.14);color:#94a3b8;border:1px solid rgba(148,163,184,.3);display:flex;align-items:center;gap:4px;white-space:nowrap">📱 cámara + audio en vivo</div>`
      : '';

    // ── Botones de salto entre cámaras (solo modo solo Y si hay 2+ streams) ─────────
    // [798] Con UNA sola cámara (celular típico) NO hay entre qué saltar → el botón sobraba
    // y confundía junto al de "Rotar". Solo aparece si hay 2+ streams (ej. pantalla + cámara).
    const soloJumps = (solo && visibles.length > 1) ? `<div style="display:flex;gap:5px;align-items:center">
        ${visibles.map(k => {
          const m = META[k] || META.camara;
          const cur = k === _espiaV2.soloStream;
          const on = !!s[k];
          return `<button onclick="MOS._espiaV2SoloIr('${k}')" title="${m.label}"
            style="background:${cur ? 'rgba(' + m.color + ',.9)' : 'rgba(255,255,255,.06)'};border:1px solid ${cur ? 'rgba(' + m.color + ',1)' : 'rgba(255,255,255,.14)'};color:#fff;border-radius:10px;width:34px;height:34px;font-size:14px;cursor:pointer;display:flex;align-items:center;justify-content:center;opacity:${on ? '1' : '.45'};transition:background .15s">${m.icon}</button>`;
        }).join('')}
      </div>` : '';

    // Estilos base compartidos de los botones de la barra
    const btnCss = 'border:1px solid rgba(255,255,255,.14);color:#e2e8f0;border-radius:11px;width:40px;height:40px;font-size:16px;font-weight:700;cursor:pointer;display:flex;align-items:center;justify-content:center;transition:background .15s,transform .1s';

    // [rotar-cam] Botón "Rotar cámara": pide al DEVICE cambiar de cámara física (frontal ↔ trasera).
    // Distinto del salto entre streams ya existentes. Ícono = cámara con flechas de rotación + texto,
    // para que comunique "rotar cámara" sin ambigüedad. Se muestra si el device es móvil/tablet o si
    // ya hay algún stream de cámara (en desktop una webcam no rota, pero no molesta si aparece).
    const mostrarRotar = !!(s.camara || s.camara2 || (caps && (caps.esMobile || caps.plataforma === 'mobile' || caps.plataforma === 'tablet')));
    const rotarBtnHtml = mostrarRotar
      ? `<button onclick="MOS._espiaV2RotarCam()" title="Rotar cámara del equipo (frontal ↔ trasera)" style="background:rgba(244,114,182,.16);${btnCss};width:auto;padding:0 12px;gap:6px;font-size:12px;font-weight:800;color:#fbcfe8;border-color:rgba(244,114,182,.4)" onmouseover="this.style.background='rgba(244,114,182,.3)'" onmouseout="this.style.background='rgba(244,114,182,.16)'"><svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" style="flex-shrink:0"><rect x="2.5" y="7.5" width="19" height="12" rx="2.5"/><path d="M8.5 7.5 10 5h4l1.5 2.5"/><path d="M9 13.5a3 3 0 0 1 5-2.2"/><polyline points="14 9.4 14 11.5 11.9 11.5"/><path d="M15 13.5a3 3 0 0 1-5 2.2"/><polyline points="10 17.6 10 15.5 12.1 15.5"/></svg>Rotar</button>`
      : '';

    const html = `<div id="espiaV2Modal" style="position:fixed;inset:0;background:#000;z-index:2147483646;overflow:hidden;animation:espiaV2In .3s ease-out">
      <!-- STAGE: mosaico o solo -->
      <div id="espiaV2Grid" data-n="${n}" ${solo ? 'data-solo="1"' : ''} style="position:absolute;inset:0;display:grid;gap:${solo ? '0' : '8px'};padding:${solo ? '0' : '8px'};box-sizing:border-box">
        ${tilesHtml}
      </div>
      ${standbyHtml}
      <!-- BARRA SUPERIOR FLOTANTE (glass, auto-hide) -->
      <div id="espiaV2TopBar" class="espiaV2-ctl espiaV2-top" style="position:absolute;top:0;left:0;right:0;z-index:30;display:flex;align-items:flex-start;justify-content:space-between;gap:10px;padding:12px 14px;padding-top:calc(12px + env(safe-area-inset-top,0px));background:linear-gradient(180deg,rgba(3,6,13,.72),rgba(3,6,13,0))">
        <div style="display:flex;align-items:center;gap:11px;flex-wrap:wrap;background:rgba(12,17,28,.55);backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px);border:1px solid rgba(255,255,255,.08);border-radius:16px;padding:8px 13px;box-shadow:0 10px 34px -14px #000;min-width:0;max-width:calc(100% - 220px)">
          <div id="espiaV2Live" style="display:flex;align-items:center;gap:9px;flex-shrink:0">
            <span style="position:relative;width:11px;height:11px;display:inline-block">
              <span style="position:absolute;inset:0;border-radius:50%;background:${live ? '#10b981' : '#f59e0b'};box-shadow:0 0 12px ${live ? '#10b981' : '#f59e0b'};animation:espiaBreath 2s ease-in-out infinite"></span>
              ${live ? `<span style="position:absolute;inset:0;border-radius:50%;border:2px solid #10b981;animation:espiaPulse 1.8s ease-out infinite"></span>` : ''}
            </span>
            <span style="font-size:11px;font-weight:900;color:${live ? '#10b981' : '#f59e0b'};letter-spacing:.6px">${live ? 'EN VIVO' : 'CONECTANDO'}</span>
          </div>
          ${badgePlataforma}
          ${notaPantalla}
          <div style="min-width:0">
            <div style="font-size:13px;font-weight:700;color:#e2e8f0;display:flex;align-items:center;gap:6px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">👤 ${_escapeHtml(_espiaV2.nombre)}</div>
            <div style="font-size:10px;color:#94a3b8;margin-top:1px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${_escapeHtml(_espiaV2.deviceId)}</div>
          </div>
          <div id="espiaV2SyncBadge" style="font-size:10px;font-weight:700;padding:4px 10px;border-radius:20px;background:rgba(16,185,129,.15);color:#10b981;border:1px solid rgba(16,185,129,.4);white-space:nowrap;flex-shrink:0">sync OK · ${_espiaV2.lagMs}ms</div>
          ${soloJumps}
        </div>
        <div style="display:flex;align-items:center;gap:6px;background:rgba(12,17,28,.55);backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px);border:1px solid rgba(255,255,255,.08);border-radius:16px;padding:6px 8px;box-shadow:0 10px 34px -14px #000;flex-shrink:0">
          ${solo ? `<button onclick="MOS._espiaV2VolverMosaico()" title="Volver a ver todas las cámaras" style="background:rgba(99,102,241,.2);${btnCss};width:auto;padding:0 13px;gap:6px;font-size:12px;font-weight:800;color:#c7d2fe;border-color:rgba(99,102,241,.4)">← Volver</button>` : ''}
          <button onclick="MOS._espiaV2ToggleMute()" id="espiaV2MuteBtn" title="Silenciar audio" style="background:rgba(255,255,255,.06);${btnCss}"
            onmouseover="this.style.background='rgba(34,211,238,.25)'" onmouseout="this.style.background='rgba(255,255,255,.06)'">🔊</button>
          <button onclick="MOS._espiaV2Captura()" title="Capturar imagen" style="background:rgba(255,255,255,.06);${btnCss}"
            onmouseover="this.style.background='rgba(99,102,241,.3)'" onmouseout="this.style.background='rgba(255,255,255,.06)'">📸</button>
          ${rotarBtnHtml}
          <button onclick="MOS._espiaV2Fullscreen()" title="Pantalla completa" style="background:rgba(255,255,255,.06);${btnCss}"
            onmouseover="this.style.background='rgba(255,255,255,.14)'" onmouseout="this.style.background='rgba(255,255,255,.06)'">⛶</button>
          <button onclick="MOS.cerrarEspiaV2()" title="Cerrar" style="background:rgba(248,113,113,.18);${btnCss};color:#fca5a5;border-color:rgba(248,113,113,.4)"
            onmouseover="this.style.background='rgba(248,113,113,.32)'" onmouseout="this.style.background='rgba(248,113,113,.18)'">✕</button>
        </div>
      </div>
      <!-- TELEMETRÍA FLOTANTE bottom-left (audio + GPS, auto-hide) -->
      <div id="espiaV2Telemetry" class="espiaV2-ctl espiaV2-bot" style="position:absolute;left:14px;bottom:14px;width:230px;max-width:calc(100vw - 28px);display:flex;flex-direction:column;gap:8px;z-index:30;padding-bottom:env(safe-area-inset-bottom,0px)">
        <div style="background:rgba(10,15,25,.62);backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px);border:1px solid rgba(34,211,238,.25);border-radius:14px;padding:10px 11px;box-shadow:0 10px 34px -14px #000">
          <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:7px">
            <div style="font-size:9px;font-weight:800;color:#22d3ee;letter-spacing:.6px">🎤 AUDIO</div>
            <div id="espiaV2AudioInfo" style="font-size:8px;color:#94a3b8;font-family:monospace">esperando…</div>
          </div>
          <canvas id="espiaV2Wave" width="206" height="34" style="width:100%;height:34px;background:#03060d;border-radius:8px;display:block"></canvas>
        </div>
        <div style="background:rgba(10,15,25,.62);backdrop-filter:blur(18px);-webkit-backdrop-filter:blur(18px);border:1px solid rgba(236,72,153,.25);border-radius:14px;padding:10px 11px;box-shadow:0 10px 34px -14px #000">
          <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:6px">
            <div style="font-size:9px;font-weight:800;color:#ec4899;letter-spacing:.6px">📍 GPS</div>
            <span id="espiaV2GpsDot" style="width:6px;height:6px;border-radius:50%;background:#475569"></span>
          </div>
          <div id="espiaV2GpsInfo" style="font-size:9px;color:#94a3b8;font-family:monospace;line-height:1.5">esperando…</div>
          <div id="espiaV2GpsMap" style="margin-top:6px;height:80px;background:#03060d;border-radius:8px;display:flex;align-items:center;justify-content:center;color:#475569;font-size:20px">🗺️</div>
          <button onclick="MOS.verUltimaUbicacionDispositivo('${_espiaV2.deviceId}')"
            style="margin-top:8px;width:100%;background:linear-gradient(135deg,rgba(59,130,246,.15),rgba(14,165,233,.10));border:1px solid rgba(59,130,246,.45);color:#93c5fd;border-radius:8px;padding:6px 8px;font-size:9px;font-weight:800;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:4px;letter-spacing:.3px;transition:all .2s"
            onmouseover="this.style.background='linear-gradient(135deg,rgba(59,130,246,.25),rgba(14,165,233,.18))'"
            onmouseout="this.style.background='linear-gradient(135deg,rgba(59,130,246,.15),rgba(14,165,233,.10))'"
            title="Si el GPS en vivo no llega, mostrar la última ubicación conocida desde el historial">🗺 ÚLTIMA UBICACIÓN</button>
        </div>
        <audio id="espiaV2AudioEl" autoplay></audio>
      </div>
      <style>
        @keyframes espiaV2In { from { opacity:0 } to { opacity:1 } }
        @keyframes espiaV2Out { to { opacity:0 } }
        @keyframes espiaBreath { 0%,100% { transform:scale(1);opacity:.85 } 50% { transform:scale(1.3);opacity:1 } }
        @keyframes espiaSpin { to { transform:rotate(360deg) } }
        @keyframes espiaPulse { 0% { transform:scale(1);opacity:.7 } 100% { transform:scale(2.6);opacity:0 } }
        /* Auto-hide de controles flotantes (barra + telemetría) */
        #espiaV2Modal .espiaV2-ctl { transition:opacity .4s ease, transform .4s ease }
        #espiaV2Modal .espiaV2-top.espiaV2-oculto { opacity:0; transform:translateY(-115%); pointer-events:none }
        #espiaV2Modal .espiaV2-bot.espiaV2-oculto { opacity:0; transform:translateY(22px); pointer-events:none }
        /* Layout del mosaico según nº de tiles */
        #espiaV2Grid { }
        #espiaV2Grid[data-n="1"] { grid-template-columns:1fr; grid-template-rows:1fr }
        #espiaV2Grid[data-n="2"] { grid-template-columns:1fr 1fr; grid-template-rows:1fr }
        #espiaV2Grid[data-n="3"] { grid-template-columns:2fr 1fr; grid-template-rows:1fr 1fr }
        #espiaV2Grid[data-n="3"] .espiaV2-tile:first-child { grid-row:1 / span 2 }
        #espiaV2Grid[data-solo="1"] { grid-template-columns:1fr !important; grid-template-rows:1fr !important }
        #espiaV2Grid .espiaV2-tile:hover .espiaV2-tile-hint { opacity:1 }
        /* Vertical / pantallas angostas: apilar. Sin dvh (usa el fixed inset:0). */
        @media (max-width: 760px), (orientation: portrait) {
          #espiaV2Grid[data-n="2"] { grid-template-columns:1fr; grid-template-rows:1fr 1fr }
          #espiaV2Grid[data-n="3"] { grid-template-columns:1fr; grid-template-rows:1.5fr 1fr 1fr }
          #espiaV2Grid[data-n="3"] .espiaV2-tile:first-child { grid-row:auto }
          #espiaV2Telemetry { width:190px }
        }
        @media (max-width: 480px) {
          #espiaV2Telemetry #espiaV2GpsMap { height:64px }
        }
      </style>
    </div>`;
    const old = document.getElementById('espiaV2Modal');
    if (old) old.remove();
    document.body.insertAdjacentHTML('beforeend', html);
    // [v2.43.92] Cancelar setTimeout previo si renderModal corre múltiples veces
    // rápido (ej. cascada de ontrack + onconnectionstatechange + trackMap).
    if (_espiaV2._renderTimeout) clearTimeout(_espiaV2._renderTimeout);
    _espiaV2._renderTimeout = setTimeout(() => {
      if (!_espiaV2) return;
      _espiaV2CablearVideos();     // srcObject de CADA tile del mosaico
      _espiaV2VincularAudio();     // <audio> → stream de audio
      _espiaV2DibujarWaveform();   // waveform en #espiaV2Wave
      _espiaV2RenderGpsMini();     // panel GPS
      _espiaV2ArmarControles();    // auto-hide de barra + telemetría
    }, 30);
  }

  // Cablea el srcObject de cada <video> del mosaico a su MediaStream. Es el
  // reemplazo del cableado BigVideo/MiniVideo anterior, ahora por-tile.
  function _espiaV2CablearVideos() {
    if (!_espiaV2) return;
    ['pantalla', 'camara', 'camara2'].forEach(k => {
      const stream = _espiaV2.streams[k];
      const el = document.getElementById('espiaV2Vid_' + k);
      if (el && stream && el.srcObject !== stream) el.srcObject = stream;
    });
  }

  // Auto-hide de los controles flotantes: se ocultan tras 3s sin actividad y
  // reaparecen con mousemove/touch/pointer/teclado. Los listeners viven en el
  // nodo #espiaV2Modal, que se recrea en cada render (los viejos mueren con él);
  // por eso re-armamos aquí y solo hay que limpiar el timer pendiente.
  function _espiaV2ArmarControles() {
    if (!_espiaV2) return;
    const modal = document.getElementById('espiaV2Modal');
    if (!modal) return;
    try { clearTimeout(_espiaV2._ctrlTimer); } catch (_) {}
    const ctls = () => modal.querySelectorAll('.espiaV2-ctl');
    const mostrar = () => {
      ctls().forEach(el => el.classList.remove('espiaV2-oculto'));
      try { clearTimeout(_espiaV2._ctrlTimer); } catch (_) {}
      _espiaV2._ctrlTimer = setTimeout(() => {
        const m = document.getElementById('espiaV2Modal');
        if (m) m.querySelectorAll('.espiaV2-ctl').forEach(el => el.classList.add('espiaV2-oculto'));
      }, 3000);
    };
    _espiaV2._ctrlMostrar = mostrar;
    const handler = () => mostrar();
    ['mousemove', 'touchstart', 'pointerdown', 'keydown'].forEach(ev =>
      modal.addEventListener(ev, handler, { passive: true }));
    mostrar(); // arranca visible + arma el timer de ocultado
  }

  // Tap en un tile del mosaico → expandir a solo-pantalla inmersivo
  function _espiaV2ExpandirTile(k) {
    if (!_espiaV2) return;
    _espiaSfx('whoosh');
    _espiaV2.vista = 'solo';
    _espiaV2.soloStream = k;
    if (_espiaV2.streams[k]) _espiaV2.focus = k; // mantener focus coherente
    _espiaV2RenderModal();
  }
  // Volver del modo solo al mosaico
  function _espiaV2VolverMosaico() {
    if (!_espiaV2) return;
    _espiaSfx('pop');
    _espiaV2.vista = 'mosaico';
    _espiaV2RenderModal();
  }
  // Saltar a otra cámara dentro del modo solo
  function _espiaV2SoloIr(k) {
    if (!_espiaV2) return;
    _espiaSfx('shimmer');
    _espiaV2.soloStream = k;
    if (_espiaV2.streams[k]) _espiaV2.focus = k;
    _espiaV2RenderModal();
  }

  // [rotar-cam] Pide al DEVICE que CAMBIE físicamente de cámara (frontal ↔ trasera). Distinto de
  // _espiaV2SoloIr (que solo alterna entre streams YA existentes): esto viaja por el DataChannel
  // 'gps' y el device hace el switch con replaceTrack. El mismo tile 'camara' cambia de imagen.
  function _espiaV2RotarCam() {
    if (!_espiaV2) return;
    const ch = _espiaV2.cmdCh;
    if (!ch || ch.readyState !== 'open') {
      toast('Cámara del equipo no disponible aún', 'warn', 2600);
      return;
    }
    try {
      ch.send(JSON.stringify({ __cmd: 'ROTAR_CAM' }));
      _espiaSfx('pop');
      toast('Rotando cámara del equipo…', 'info', 2000);
    } catch (e) {
      toast('No se pudo enviar el comando de rotar', 'warn', 2600);
    }
  }

  // Captura de pantalla del tile indicado (o del solo/focus actual) → PNG.
  // Usa new Date() en runtime (permitido en navegador) para el nombre.
  function _espiaV2Captura(k) {
    if (!_espiaV2) return;
    if (!k) k = (_espiaV2.vista === 'solo' && _espiaV2.soloStream) ? _espiaV2.soloStream : _espiaV2.focus;
    let vid = document.getElementById('espiaV2Vid_' + k);
    // Fallback: si el tile pedido no tiene imagen, tomar cualquiera con señal
    if (!vid || !vid.videoWidth) {
      const alt = ['pantalla', 'camara', 'camara2']
        .map(x => document.getElementById('espiaV2Vid_' + x))
        .find(v => v && v.videoWidth);
      if (alt) vid = alt;
    }
    if (!vid || !vid.videoWidth) { toast('Sin imagen para capturar todavía', 'warn'); return; }
    try {
      const canvas = document.createElement('canvas');
      canvas.width = vid.videoWidth;
      canvas.height = vid.videoHeight;
      canvas.getContext('2d').drawImage(vid, 0, 0, canvas.width, canvas.height);
      const d = new Date();
      const p = (x) => String(x).padStart(2, '0');
      const ts = `${d.getFullYear()}${p(d.getMonth() + 1)}${p(d.getDate())}_${p(d.getHours())}${p(d.getMinutes())}${p(d.getSeconds())}`;
      const nombre = String(_espiaV2.nombre || 'equipo').replace(/[^\w\-]+/g, '_').slice(0, 40);
      const a = document.createElement('a');
      a.download = `espia_${nombre}_${ts}.png`;
      a.href = canvas.toDataURL('image/png');
      a.click();
      _espiaSfx('chime');
      toast('📸 Captura descargada', 'ok');
    } catch (e) {
      toast('No se pudo capturar: ' + (e?.message || e), 'error');
    }
  }

  function _espiaV2ActualizarStream(tipoFocus, stream, elementId) {
    if (!stream) return;
    const el = document.getElementById(elementId || 'espiaV2BigVideo');
    if (el && el.srcObject !== stream) el.srcObject = stream;
  }
  function _espiaV2VincularAudio() {
    if (!_espiaV2?.streams.audio) return;
    const a = document.getElementById('espiaV2AudioEl');
    if (a) a.srcObject = _espiaV2.streams.audio;
  }
  function _espiaV2DibujarWaveform() {
    if (!_espiaV2?.streams.audio) return;
    try {
      if (!_espiaAudioCtx) _espiaAudioCtx = new (window.AudioContext || window.webkitAudioContext)();
      const ctx = _espiaAudioCtx;
      const src = ctx.createMediaStreamSource(_espiaV2.streams.audio);
      const analyser = ctx.createAnalyser();
      analyser.fftSize = 256;
      src.connect(analyser);
      const canvas = document.getElementById('espiaV2Wave');
      if (!canvas) return;
      const cctx = canvas.getContext('2d');
      const buf = new Uint8Array(analyser.frequencyBinCount);
      function draw() {
        if (!_espiaV2 || !document.getElementById('espiaV2Wave')) return;
        analyser.getByteFrequencyData(buf);
        cctx.fillStyle = '#000';
        cctx.fillRect(0, 0, canvas.width, canvas.height);
        const barW = canvas.width / buf.length;
        for (let i = 0; i < buf.length; i++) {
          const h = (buf[i] / 255) * canvas.height;
          const grad = cctx.createLinearGradient(0, canvas.height, 0, 0);
          grad.addColorStop(0, '#06b6d4');
          grad.addColorStop(1, '#22d3ee');
          cctx.fillStyle = grad;
          cctx.fillRect(i * barW, canvas.height - h, barW - 1, h);
        }
        // dB approx
        const promedio = buf.reduce((s, v) => s + v, 0) / buf.length;
        const info = document.getElementById('espiaV2AudioInfo');
        if (info) info.textContent = `${Math.round(promedio)} dB · live`;
        requestAnimationFrame(draw);
      }
      draw();
    } catch(_){}
  }
  function _espiaV2RenderGpsMini() {
    const info = document.getElementById('espiaV2GpsInfo');
    const dot = document.getElementById('espiaV2GpsDot');
    const mapBox = document.getElementById('espiaV2GpsMap');
    if (!info) return;
    const g = _espiaV2?.gpsUlt;
    if (!g) { info.textContent = 'esperando…'; if (dot) dot.style.background = '#475569'; return; }
    info.innerHTML = `lat ${g.lat?.toFixed(5)}<br>lng ${g.lng?.toFixed(5)}<br>vel ${(g.speed*3.6 || 0).toFixed(1)} km/h<br>acc ${g.acc?.toFixed(0)}m`;
    if (dot) {
      dot.style.background = '#10b981';
      dot.style.animation = 'espiaBreath 1s';
      setTimeout(() => { if (dot) dot.style.animation = ''; }, 1000);
    }
    // [v2.43.94] Google Maps embed sin API key (output=embed). UI limpia,
    // sin chip de "reportar problema" que tapaba el croquis en OSM embed.
    // No requiere billing ni Script Properties extra.
    if (mapBox && g.lat != null && g.lng != null) {
      const lat = g.lat, lng = g.lng;
      const src = `https://maps.google.com/maps?q=${lat.toFixed(6)},${lng.toFixed(6)}&hl=es&z=17&output=embed`;
      const linkAmplio = `https://www.google.com/maps?q=${lat.toFixed(6)},${lng.toFixed(6)}&z=17`;
      const iframe = mapBox.querySelector('iframe');
      if (!iframe) {
        mapBox.innerHTML = `<iframe src="${src}" style="border:0;width:100%;height:100%;border-radius:6px" loading="lazy" referrerpolicy="no-referrer"></iframe>
          <a href="${linkAmplio}" target="_blank" rel="noopener"
             style="position:absolute;top:4px;right:4px;background:rgba(15,23,42,.92);color:#a5b4fc;font-size:9px;font-weight:700;padding:3px 7px;border-radius:5px;text-decoration:none;border:1px solid #1e293b;backdrop-filter:blur(4px);z-index:5">ampliar ↗</a>`;
        mapBox.style.position = 'relative';
        mapBox.style.height = '150px';   // más alto: 110 → 150
        mapBox.style.background = '#020617';
        mapBox.style.borderRadius = '6px';
        mapBox.style.overflow = 'hidden';
        mapBox.style.fontSize = '';
        mapBox.style.color = '';
      } else if (Math.abs(parseFloat(iframe.dataset.lastLat || 0) - lat) > 0.0002 ||
                 Math.abs(parseFloat(iframe.dataset.lastLng || 0) - lng) > 0.0002) {
        // Refrescar src solo si movió >20m (evita reload constante por jitter)
        iframe.src = src;
        iframe.dataset.lastLat = lat;
        iframe.dataset.lastLng = lng;
        // Actualizar también el link de ampliar
        const link = mapBox.querySelector('a');
        if (link) link.href = linkAmplio;
      }
    }
  }
  function _espiaV2RenderSyncBadge() {
    const b = document.getElementById('espiaV2SyncBadge');
    if (!b || !_espiaV2) return;
    const lag = _espiaV2.lagMs;
    let color = '#10b981', bg = 'rgba(16,185,129,.15)', border = 'rgba(16,185,129,.4)', txt = 'sync OK';
    if (lag > 2000) { color = '#f59e0b'; bg = 'rgba(245,158,11,.15)'; border = 'rgba(245,158,11,.4)'; txt = 'sync lento'; }
    if (lag > 5000) { color = '#ef4444'; bg = 'rgba(239,68,68,.15)'; border = 'rgba(239,68,68,.4)'; txt = 'sync mal'; }
    b.style.color = color; b.style.background = bg; b.style.borderColor = border;
    b.textContent = `${txt} · ${lag}ms`;
  }
  function _espiaV2Swap() {
    if (!_espiaV2) return;
    _espiaSfx('shimmer');
    const caps = _espiaV2.capabilities;
    const ordenBase = (caps && caps.tienePantalla === false)
      ? ['camara', 'camara2']
      : ['pantalla', 'camara', 'camara2'];
    const disponibles = ordenBase.filter(k => !!_espiaV2.streams[k]);
    if (disponibles.length <= 1) {
      _espiaV2RenderModal();
      return;
    }
    const idxActual = disponibles.indexOf(_espiaV2.focus);
    const siguiente = disponibles[(idxActual + 1) % disponibles.length];
    _espiaV2.focus = siguiente;
    _espiaV2RenderModal();
  }
  function _espiaV2ToggleMute() {
    const a = document.getElementById('espiaV2AudioEl');
    const btn = document.getElementById('espiaV2MuteBtn');
    if (!a) return;
    a.muted = !a.muted;
    if (btn) btn.textContent = a.muted ? '🔇' : '🔊';
    _espiaSfx('pop');
  }
  function _espiaV2Fullscreen() {
    _espiaSfx('whoosh');
    // [v2.44] Visor ya es edge-to-edge → fullscreen del contenedor raíz completo.
    const wrap = document.getElementById('espiaV2Modal') || document.getElementById('espiaV2Grid');
    if (!wrap) return;
    if (!document.fullscreenElement) {
      wrap.requestFullscreen?.().catch(() => {});
    } else {
      document.exitFullscreen?.();
    }
  }
  function cerrarEspiaV2() { _espiaV2Cerrar('manual'); }

  // ════════════════════════════════════════════════════════════════════
  // [v2.43.61] TIMELINE BUFFER HISTÓRICO — Reproduce chunks subidos del device
  // ════════════════════════════════════════════════════════════════════
  async function abrirTimelineBufferEspia(deviceId) {
    if (!_esMasterSession()) { toast('Solo Master', 'error'); return; }
    try { _opsBeep && _opsBeep('tac'); } catch(_){}
    const dispositivo = (cfgData.dispositivos || []).find(x => x.ID_Dispositivo === deviceId);
    const nombre = dispositivo?.Ultima_Sesion || dispositivo?.Nombre_Equipo || deviceId;
    // Modal optimista — abrir con loader y traer chunks
    const html = `<div id="espiaTimelineModal" style="position:fixed;inset:0;background:rgba(0,0,0,.75);backdrop-filter:blur(8px);z-index:2147483645;display:flex;align-items:center;justify-content:center;padding:24px;animation:espiaV2In .3s cubic-bezier(.34,1.56,.64,1)">
      <div style="width:100%;max-width:1100px;height:84vh;background:linear-gradient(180deg,#0a1424,#070d18);border:1px solid rgba(168,85,247,.4);border-radius:16px;display:flex;flex-direction:column;overflow:hidden;box-shadow:0 30px 70px -10px rgba(168,85,247,.35)"
           onclick="event.stopPropagation()">
        <div style="padding:14px 20px;border-bottom:1px solid #1e293b;background:linear-gradient(135deg,rgba(168,85,247,.15),rgba(168,85,247,.03));display:flex;align-items:center;gap:14px;flex-shrink:0">
          <div style="font-size:22px">📼</div>
          <div style="flex:1;min-width:0">
            <div style="font-size:14px;font-weight:800;color:#c084fc;letter-spacing:.5px">TIMELINE BUFFER HISTÓRICO</div>
            <div style="font-size:11px;color:#94a3b8;margin-top:2px">${_escapeHtml(nombre)} · últimas 12h</div>
          </div>
          <select id="espiaTimelineTipo" onchange="MOS._espiaTimelineRecargar()" style="background:#0f172a;border:1px solid #334155;color:#cbd5e1;border-radius:6px;padding:5px 8px;font-size:11px">
            <option value="">Todos</option>
            <option value="audio_video">Audio + Cámara</option>
            <option value="screen">Pantalla</option>
          </select>
          <button onclick="MOS.cerrarTimelineEspia()" style="background:rgba(248,113,113,.15);border:1px solid rgba(248,113,113,.4);color:#fca5a5;border-radius:8px;padding:6px 12px;font-size:14px;cursor:pointer">✕</button>
        </div>
        <div id="espiaTimelinePlayer" style="flex:1;display:flex;align-items:center;justify-content:center;background:#020617;position:relative">
          <video id="espiaTimelineVideo" controls autoplay style="max-width:100%;max-height:100%;display:none"></video>
          <div id="espiaTimelinePlaceholder" style="text-align:center;color:#475569">
            <div style="font-size:48px;margin-bottom:12px">📼</div>
            <div style="font-size:13px;color:#94a3b8">Selecciona un chunk del timeline ↓</div>
          </div>
        </div>
        <div style="background:#0f172a;border-top:1px solid #1e293b;padding:14px 20px;min-height:140px;max-height:160px;overflow-y:auto;flex-shrink:0">
          <div id="espiaTimelineLista" style="display:flex;gap:8px;flex-wrap:wrap;align-items:flex-start">
            <div style="color:#64748b;font-size:11px;display:flex;align-items:center;gap:8px">
              <span style="width:16px;height:16px;border:2px solid rgba(168,85,247,.3);border-top-color:#c084fc;border-radius:50%;animation:espiaSpin .8s linear infinite"></span>
              Cargando chunks…
            </div>
          </div>
        </div>
      </div>
    </div>`;
    document.body.insertAdjacentHTML('beforeend', html);
    window._espiaTimelineState = { deviceId, chunks: [], filtroTipo: '' };
    await _espiaTimelineCargar(deviceId, '');
  }
  function cerrarTimelineEspia() {
    const m = document.getElementById('espiaTimelineModal');
    if (m) { m.style.animation = 'espiaV2Out .25s ease-out forwards'; setTimeout(() => m.remove(), 250); }
    window._espiaTimelineState = null;
  }
  async function _espiaTimelineCargar(deviceId, tipoFiltro) {
    try {
      const r = await API.post('espiaListarChunks', {
        deviceId, tipo: tipoFiltro || '',
        desde: Date.now() - 12 * 3600000,
        hasta: Date.now()
      });
      // [v2.43.66] API.post desempaqueta — r es directo el data
      const chunks = (r && r.chunks) || [];
      window._espiaTimelineState.chunks = chunks;
      _espiaTimelineRenderLista();
    } catch(e) {
      const lista = document.getElementById('espiaTimelineLista');
      if (lista) lista.innerHTML = `<div style="color:#f87171;font-size:11px">⚠ Error: ${_escapeHtml(e.message)}</div>`;
    }
  }
  function _espiaTimelineRecargar() {
    const tipoEl = document.getElementById('espiaTimelineTipo');
    const tipo = tipoEl ? tipoEl.value : '';
    if (window._espiaTimelineState) {
      window._espiaTimelineState.filtroTipo = tipo;
      _espiaTimelineCargar(window._espiaTimelineState.deviceId, tipo);
    }
  }
  function _espiaTimelineRenderLista() {
    const lista = document.getElementById('espiaTimelineLista');
    if (!lista) return;
    const st = window._espiaTimelineState;
    if (!st || !st.chunks.length) {
      lista.innerHTML = `<div style="color:#475569;font-size:11px;display:flex;align-items:center;gap:8px">
        🌙 No hay chunks del rango. (¿El device tuvo sesión espía activa?)
      </div>`;
      return;
    }
    lista.innerHTML = st.chunks.map(c => {
      // [FIX 500x F4] Chunks nuevos vienen de Supabase Storage ({url,mime,tamBytes,ts epoch-ms}) — los legacy
      // de Drive traían {fileId,nombre,tamMB}. Tolerar AMBOS: ref = url Storage o fileId Drive; ts numérico.
      const ref = String(c.url || c.fileId || '');
      const nombre = c.nombre || ((c.tipo || 'audio') + '-' + (c.idx != null ? c.idx : '') + ' ' + (c.mime || ''));
      const tamMB = (c.tamMB != null) ? c.tamMB : (c.tamBytes ? (c.tamBytes / 1048576).toFixed(2) : '?');
      const fecha = new Date(Number(c.ts) || c.ts);
      const hh = String(fecha.getHours()).padStart(2,'0');
      const mm = String(fecha.getMinutes()).padStart(2,'0');
      const dd = String(fecha.getDate()).padStart(2,'0');
      const mo = String(fecha.getMonth()+1).padStart(2,'0');
      const icon = c.tipo === 'screen' ? '🖥️' : '🎤📷';
      const color = c.tipo === 'screen' ? '#a5b4fc' : '#22d3ee';
      return `<button onclick="MOS._espiaTimelineReproducir('${ref}','${_escapeHtml(nombre)}')"
        style="background:#1e293b;border:1px solid ${color}55;color:#cbd5e1;border-radius:8px;padding:8px 11px;font-size:10px;cursor:pointer;display:flex;flex-direction:column;align-items:flex-start;gap:3px;transition:all .15s;min-width:108px;text-align:left"
        onmouseover="this.style.background='${color}22';this.style.borderColor='${color}'"
        onmouseout="this.style.background='#1e293b';this.style.borderColor='${color}55'">
        <div style="font-size:13px">${icon}</div>
        <div style="font-weight:700;color:${color}">${dd}/${mo} ${hh}:${mm}</div>
        <div style="opacity:.7;font-size:9px">${tamMB}MB</div>
      </button>`;
    }).join('');
  }
  function _espiaTimelineReproducir(ref, nombre) {
    try { _opsBeep && _opsBeep('tac'); } catch(_){}
    const player = document.getElementById('espiaTimelinePlayer');
    if (!player) return;
    const overlay = `<div style="position:absolute;top:8px;left:12px;background:rgba(0,0,0,.65);color:#fff;padding:4px 10px;border-radius:6px;font-size:10px;backdrop-filter:blur(4px)">▶ ${_escapeHtml(nombre)}</div>`;
    // [FIX 500x F4] Chunks migrados a Supabase Storage: ref es una URL http pública → player NATIVO
    // (<video> reproduce también audio-webm). El iframe de Drive queda SOLO para fileIds legacy.
    if (/^https?:\/\//i.test(String(ref))) {
      player.innerHTML = `<video src="${ref}" controls autoplay playsinline
        style="width:100%;height:100%;background:#000;border:0;object-fit:contain"></video>` + overlay;
      return;
    }
    // Drive iframe preview (legacy, chunks pre-migración).
    player.innerHTML = `<iframe src="https://drive.google.com/file/d/${ref}/preview"
      style="width:100%;height:100%;border:0" allow="autoplay"></iframe>` + overlay;
  }

  // Inicia espía (audio + gps) y abre el modal grande SIN bloquear.
  async function abrirEspiaDispositivo(idDispositivo) {
    const d = (cfgData.dispositivos || []).find(x => x.ID_Dispositivo === idDispositivo);
    if (!d) { toast('Dispositivo no encontrado', 'error'); return; }
    const nombre = d.Ultima_Sesion || d.Nombre_Equipo || idDispositivo;

    // 1) Si ya hay otra sesión activa, confirmar switch
    if (_espiaState && _espiaState.deviceId !== idDispositivo) {
      if (!await _modalConfirm(`Ya estás espiando a ${_espiaState.nombre}.\n\n¿Detener esa sesión y empezar a espiar a ${nombre}?\n\nSi dices NO, seguirás espiando a ${_espiaState.nombre}.`, { warning: true, titulo: 'Cambiar de objetivo', okText: 'Sí, cambiar' })) return;
      _espiaDetenerTodo(true); // sin await — limpieza en background
    }

    // 2) Marcar state
    _espiaState = {
      deviceId: idDispositivo,
      nombre,
      modalAbierto: false,
      gpsPolling: null,
      gpsUlt: null,
      gpsRangoH: 24,
      _avisosTimers: []
    };

    // 3) Abrir modal INMEDIATO (feedback visual sin esperar API)
    _espiaModalAbrir();

    // 4) Mostrar avisos según diagnóstico inicial (conexión vieja, etc)
    _espiaActualizarAvisos();

    // 5) Iniciar audio + gps en paralelo (sin bloquear UI)
    _espiaIniciarAudio(idDispositivo);
    _espiaIniciarGps(idDispositivo);
  }

  // ── AVISOS dentro del modal: en lugar de confirms bloqueantes ──
  function _espiaActualizarAvisos() {
    if (!_espiaState) return;
    const cont = $('espiaAvisos');
    if (!cont) return;
    const avisos = [];
    const d = (cfgData.dispositivos || []).find(x => x.ID_Dispositivo === _espiaState.deviceId);
    // 1) Última conexión
    const ultMs = new Date(d?.Ultima_Conexion || 0).getTime() || 0;
    const mins = ultMs ? (Date.now() - ultMs) / 60000 : Infinity;
    if (!ultMs) {
      avisos.push({
        nivel: 'error', ico: '📡',
        titulo: 'Sin reportes de conexión',
        detalle: 'Este dispositivo nunca ha reportado heartbeat — puede no estar registrado correctamente.'
      });
    } else if (mins > 60) {
      const horas = Math.floor(mins / 60);
      avisos.push({
        nivel: 'error', ico: '📡',
        titulo: `App parece cerrada (hace ${horas}h)`,
        detalle: 'El comando de escucha puede no llegar hasta que abra la app o reciba un push.'
      });
    } else if (mins > 10) {
      avisos.push({
        nivel: 'warn', ico: '📡',
        titulo: `Última conexión hace ${Math.floor(mins)} min`,
        detalle: 'La app puede estar en background — el comando podría tardar.'
      });
    }
    // 2) Audio sin chunks tras 30s = sin permiso
    if (_audioFlot && _audioFlot.deviceId === _espiaState.deviceId &&
        _audioFlot.idSesion && _audioFlot.chunks.length === 0 &&
        (Date.now() - _audioFlot.inicio) > 30000) {
      avisos.push({
        nivel: 'warn', ico: '🎙️',
        titulo: 'Audio sin permiso o app cerrada',
        detalle: 'No se reciben chunks. Verifica que el dispositivo tenga permiso de micrófono concedido.'
      });
    }
    // 3) GPS sin reportes
    if (_espiaState.gpsRevisado && !_espiaState.gpsUlt) {
      avisos.push({
        nivel: 'warn', ico: '📍',
        titulo: 'GPS desconectado',
        detalle: 'El dispositivo no ha reportado ubicación todavía. Pídele que abra la app.'
      });
    }
    cont.innerHTML = avisos.map(a => `
      <div class="espia-aviso espia-aviso-${a.nivel}">
        <span class="espia-aviso-ico">${a.ico}</span>
        <div class="espia-aviso-cuerpo">
          <div class="espia-aviso-titulo">${a.titulo}</div>
          <div class="espia-aviso-detalle">${a.detalle}</div>
        </div>
      </div>`).join('');
    // Re-evaluar cada 10s mientras el modal está abierto
    if (_espiaState.modalAbierto) {
      clearTimeout(_espiaState._avisosNextTimer);
      _espiaState._avisosNextTimer = setTimeout(() => {
        if (_espiaState && _espiaState.modalAbierto) _espiaActualizarAvisos();
      }, 10000);
    }
  }

  function _espiaModalAbrir() {
    if (!_espiaState) return;
    const sub = $('espiaModalSubtitle');
    if (sub) {
      const d = (cfgData.dispositivos || []).find(x => x.ID_Dispositivo === _espiaState.deviceId);
      sub.textContent = `${_espiaState.nombre}${d?.Nombre_Equipo ? ' · ' + d.Nombre_Equipo : ''}`;
    }
    const dev = $('espiaModalDeviceId');
    if (dev) dev.value = _espiaState.deviceId;
    const btnHist = $('espiaModalBtnHist');
    if (btnHist) btnHist.classList.toggle('hidden', !_esRolMaster());
    // Esconder widget instantáneamente (sin animación de salida)
    const w = document.getElementById('espiaFlotante');
    if (w) w.style.display = 'none';
    openModal('modalEspia');
    _espiaState.modalAbierto = true;
    // Refrescar avisos cada vez que abrimos (puede haber cambiado el estado)
    _espiaActualizarAvisos();
  }

  // Cierra modal pero mantiene audio/gps corriendo → muestra widget
  function _espiaModalMinimizar() {
    if (!_espiaState) {
      try { closeModal('modalEspia'); } catch {}
      return;
    }
    closeModal('modalEspia');
    _espiaState.modalAbierto = false;
    clearTimeout(_espiaState._avisosNextTimer);
    _espiaWidgetMontar();
  }

  // Detiene audio + gps + remueve widget + cierra modal
  // Cierre INMEDIATO de UI; las llamadas API se hacen en background.
  async function _espiaDetenerTodo(silencioso) {
    if (!silencioso) {
      const nom = _espiaState?.nombre || 'el usuario';
      if (!await _modalConfirm(`🛑 DETENER el espionaje de ${nom}?\n\nSe cierra el audio y el rastreo GPS.\nEl indicador del widget desaparece.\n\nSi solo querés minimizar (seguir grabando en background), usá el botón ▾ del modal.`, { warning: true, titulo: 'Detener espionaje', okText: 'Detener todo' })) return;
    }
    if (!_espiaState && !document.getElementById('espiaFlotante') && !_audioFlot) return;

    const idSesion = _audioFlot?.idSesion;
    // 1) Limpiar estado / timers SÍNCRONO (UI responde de inmediato)
    if (_espiaState?.gpsPolling) clearInterval(_espiaState.gpsPolling);
    if (_espiaState?._avisosNextTimer) clearTimeout(_espiaState._avisosNextTimer);
    if (_audioFlot) {
      if (_audioFlot.polling) clearInterval(_audioFlot.polling);
      if (_audioFlot.contadorTimer) clearInterval(_audioFlot.contadorTimer);
      if (_audioFlot.watchdog20) clearTimeout(_audioFlot.watchdog20);
      if (_audioFlot.watchdog45) clearTimeout(_audioFlot.watchdog45);
      if (_audioFlot.watchdog90) clearTimeout(_audioFlot.watchdog90);
      if (_audioFlot.audioEl) { _audioFlot.audioEl.pause(); _audioFlot.audioEl.src = ''; _audioFlot.audioEl.onended = null; }
    }
    // 2) Cerrar modal y widget INMEDIATO
    try { closeModal('modalEspia'); } catch {}
    const w = document.getElementById('espiaFlotante');
    if (w) {
      w.style.transition = 'all 0.18s ease-out';
      w.style.transform = 'translateY(20px) scale(0.92)';
      w.style.opacity = '0';
      setTimeout(() => w.remove(), 180);
    }
    _audioFlot = null;
    _espiaState = null;
    if (!silencioso) toast('🛑 Espía detenido', 'ok');
    // 3) Avisar al server en background (sin bloquear UI)
    if (idSesion) {
      API.post('detenerEscuchaAudio', { idSesion }).catch(() => {});
    }
  }

  // ── Audio dentro del modal espía (sin crear el #audioFlotante viejo)
  async function _espiaIniciarAudio(idDispositivo) {
    // Reusar la maquinaria existente pero apuntar el audio al player del modal
    const dDisp = (cfgData.dispositivos || []).find(x => x.ID_Dispositivo === idDispositivo);
    if (!dDisp) return;
    const nombre = dDisp.Ultima_Sesion || dDisp.Nombre_Equipo || idDispositivo;

    // Si ya había _audioFlot de otro device, parar
    if (_audioFlot) await _audioFlotanteDetenerInterno(true);

    _espiaActualizarAudioSub('⌛ enviando comando...');

    let cmd;
    try {
      cmd = await API.post('iniciarEscuchaAudio', {
        deviceId: idDispositivo,
        autorizadoPor: S.session?.nombre || 'admin',
        razon: 'Espía remoto desde panel'
      });
    } catch(e) {
      _espiaActualizarAudioSub('⚠ ' + e.message);
      return;
    }
    if (!cmd?.idSesion) {
      _espiaActualizarAudioSub('⚠ Sin idSesion');
      return;
    }

    // Setup _audioFlot (mismo formato que el flotante viejo, pero el audio
    // element apunta al player del modal espía)
    const player = document.getElementById('espiaPlayerLive');
    _audioFlot = {
      deviceId: idDispositivo,
      nombre,
      idSesion: cmd.idSesion,
      chunks: [], idx: 0,
      chunksCargados: new Set(),
      audioEl: player,
      inicio: Date.now(),
      polling: null,
      contadorTimer: null,
      prefetched: new Map(),
      muted: false,
      origenEspia: true
    };
    // Encadenado al terminar
    if (player) {
      player.onended = () => {
        if (!_audioFlot) return;
        _audioFlot.idx++;
        _audioFlotanteReproducirSiguiente();
        _espiaActualizarAudioVista();
      };
    }
    // Pre-warm autoplay
    try {
      const silentWebm = 'data:audio/webm;base64,GkXfowEAAAAAAAAfQoaBAUL3gQFC8oEEQvOBCEKChHdlYm1Ch4EEQoWBAhhTgGcBAAAAAAAVkhFNm3RALE27i1OrhBVJqWZTrIHfTbuMU6uEFlSua1OsggEwTbuMU6uEHFO7a1OsggI+7AEAAAAAAACkAAAAAAAAAAAAAAAAAAA=';
      if (player) {
        player.src = silentWebm;
        player.volume = 0;
        player.play().then(() => {
          if (player) player.volume = _audioFlot?.muted ? 0 : 1;
        }).catch(() => {});
      }
    } catch(_) {}

    _espiaActualizarAudioSub('🔴 sesión iniciada · esperando chunks');
    _espiaActualizarAudioVista();

    // Contador
    _audioFlot.contadorTimer = setInterval(() => {
      if (!_audioFlot) return;
      const segs = Math.floor((Date.now() - _audioFlot.inicio) / 1000);
      const mm = String(Math.floor(segs / 60)).padStart(2, '0');
      const ss = String(segs % 60).padStart(2, '0');
      const t = $('espiaModalAudioTime');
      if (t) t.textContent = `${mm}:${ss}`;
      _espiaWidgetUpdate();
    }, 1000);

    // Polling de chunks
    setTimeout(_audioFlotantePollChunks, 800);
    _audioFlot.polling = setInterval(() => {
      _audioFlotantePollChunks();
      _espiaActualizarAudioVista();
    }, 2500);
  }

  function _espiaActualizarAudioSub(txt) {
    const el = $('espiaModalAudioSub');
    if (el) el.textContent = txt;
    const subW = document.querySelector('#espiaFlotante .espia-flot-sub');
    if (subW) subW.textContent = txt;
  }
  function _espiaActualizarAudioVista() {
    if (!_audioFlot) return;
    const c = $('espiaModalAudioChunks');
    if (c) c.textContent = `${_audioFlot.chunks.length} chunks · idx ${_audioFlot.idx + 1}`;
    if (_audioFlot.chunks.length > 0) {
      const sub = $('espiaModalAudioSub');
      if (sub) sub.textContent = _audioFlot.muted ? '🔇 muteado · grabación activa' : '🔴 escuchando en vivo';
    }
    _espiaWidgetUpdate();
    // Re-evaluar avisos: el primer chunk recibido limpia el aviso "sin permiso"
    if (_audioFlot.chunks.length === 1) _espiaActualizarAvisos();
  }

  // Toggle mute (no detiene grabación, solo silencia reproducción local)
  function _espiaToggleMute() {
    if (!_audioFlot || !_audioFlot.audioEl) return;
    _audioFlot.muted = !_audioFlot.muted;
    _audioFlot.audioEl.muted = _audioFlot.muted;
    const btn = $('espiaModalBtnMute');
    if (btn) btn.innerHTML = _audioFlot.muted ? '🔊 Quitar mute' : '🔇 Mutear';
    const ico = $('espiaModalMicIcon');
    if (ico) {
      ico.textContent = _audioFlot.muted ? '🔇' : '🎙️';
      ico.classList.toggle('muted', _audioFlot.muted);
    }
    _espiaActualizarAudioVista();
    _espiaWidgetUpdate();
  }

  // Abre el modal viejo de historial (solo master)
  function _espiaAbrirHistorial() {
    if (!_espiaState) return;
    abrirModalAudio(_espiaState.deviceId);
  }

  // ── GPS dentro del modal espía
  async function _espiaIniciarGps(idDispositivo) {
    if (_espiaState?.gpsPolling) clearInterval(_espiaState.gpsPolling);
    // Primer refresh sin bloquear; luego polling cada 15s
    _espiaGpsRefresh();
    if (!_espiaState) return;
    _espiaState.gpsPolling = setInterval(_espiaGpsRefresh, 15000);
  }

  async function _espiaGpsRefresh() {
    if (!_espiaState) return;
    const id = _espiaState.deviceId;
    const info = $('espiaModalGpsInfo');
    const mapa = $('espiaModalGpsMapa');
    const cantEl = $('espiaModalGpsPuntos');
    try {
      const ult = await API.get('getUltimaUbicacionDispositivo', { deviceId: id });
      const hist = await API.get('getUbicacionesDispositivo', { deviceId: id, horas: _espiaState.gpsRangoH });
      if (_espiaState) _espiaState.gpsRevisado = true;
      if (!ult) {
        if (info) info.innerHTML = '<span class="text-amber-400">⚠ Sin ubicación reportada</span>';
        const sub = $('espiaModalGpsSub');
        if (sub) sub.textContent = 'Sin reportes';
        _espiaActualizarAvisos();
        return;
      }
      _espiaState.gpsUlt = ult;
      const fecha = ult.timestamp ? new Date(ult.timestamp) : null;
      const mins = fecha ? Math.floor((Date.now() - fecha.getTime()) / 60000) : null;
      const fmt = fecha ? fecha.toLocaleString('es-PE', { hour:'2-digit', minute:'2-digit' }) : '—';
      const fresh = mins !== null && mins < 5;
      const dot = fresh ? '🟢' : (mins < 60 ? '🟡' : '🔴');
      const bat = ult.bateria !== '' && ult.bateria !== undefined ? ` · 🔋${ult.bateria}%` : '';
      if (info) {
        info.innerHTML = `<div class="text-white font-bold">${dot} ${fmt}${bat}</div>
          <div class="text-[10px] text-slate-400 mt-0.5">📍 ${parseFloat(ult.lat).toFixed(6)}, ${parseFloat(ult.lng).toFixed(6)} · ~${Math.round(ult.accuracy)}m</div>`;
      }
      const subM = $('espiaModalGpsSub');
      if (subM) {
        const txt = fresh ? '🟢 en vivo' : (mins < 60 ? `hace ${mins}min` : `hace ${Math.floor(mins/60)}h`);
        subM.textContent = txt;
      }
      const lnk = $('espiaModalGpsMaps');
      if (lnk) {
        lnk.href = `https://www.google.com/maps?q=${ult.lat},${ult.lng}`;
        lnk.classList.remove('hidden');
      }
      if (cantEl) cantEl.textContent = (Array.isArray(hist) ? hist.length : 0) + ' puntos · ' + _espiaState.gpsRangoH + 'h';
      if (mapa && (!mapa.dataset.lastLat || mapa.dataset.lastLat !== String(ult.lat) || mapa.dataset.lastLng !== String(ult.lng))) {
        mapa.innerHTML = `<iframe width="100%" height="100%" frameborder="0"
          src="https://maps.google.com/maps?q=${ult.lat},${ult.lng}&z=16&output=embed"
          style="border:none;"></iframe>`;
        mapa.dataset.lastLat = String(ult.lat);
        mapa.dataset.lastLng = String(ult.lng);
      }
      _espiaWidgetUpdate();
      _espiaActualizarAvisos();
    } catch(e) {
      if (info) info.innerHTML = '<span class="text-red-400">Error: ' + e.message + '</span>';
    }
  }

  function _espiaGpsRangoCambiar(horas) {
    if (!_espiaState) return;
    _espiaState.gpsRangoH = horas;
    _espiaGpsRefresh();
  }

  // ── Widget flotante mini ─────────────────────────────────
  function _espiaWidgetMontar() {
    if (!_espiaState) return;
    let w = document.getElementById('espiaFlotante');
    if (w) { w.style.display = 'flex'; _espiaWidgetUpdate(); return; }
    w = document.createElement('div');
    w.id = 'espiaFlotante';
    w.innerHTML = `
      <div class="espia-flot-emoji" data-open-modal="1">🕵️</div>
      <div class="espia-flot-info" data-open-modal="1">
        <div class="espia-flot-nom"></div>
        <div class="espia-flot-sub">⌛</div>
      </div>
      <div class="espia-flot-icons">
        <div class="espia-flot-ico espia-flot-ico-mic" title="Click: mutear / quitar mute (audio sigue grabando)">🎙️</div>
        <div class="espia-flot-ico espia-flot-ico-gps" title="Click: ver GPS en modal">📍</div>
        <button class="espia-flot-stop" title="Detener todo">×</button>
      </div>`;
    document.body.appendChild(w);

    // Handlers nativos de click para los controles (mic / gps / stop)
    w.querySelector('.espia-flot-ico-mic').addEventListener('click', e => {
      e.stopPropagation();
      _espiaToggleMute();
    });
    w.querySelector('.espia-flot-ico-gps').addEventListener('click', e => {
      e.stopPropagation();
      _espiaModalAbrir();
      setTimeout(() => {
        const sec = document.getElementById('espiaSecGps');
        if (sec) sec.scrollIntoView({ behavior: 'smooth', block: 'start' });
        _espiaGpsRefresh();
      }, 120);
    });
    w.querySelector('.espia-flot-stop').addEventListener('click', e => {
      e.stopPropagation();
      _espiaDetenerTodo(false);
    });

    // Drag SOLO sobre el cuerpo (no controles). Click sobre cuerpo abre modal.
    let pStart = null, moved = false;
    const onDown = e => {
      // Si el pointerdown fue sobre un control, no iniciar drag (sus handlers click nativos manejan)
      if (e.target.closest('.espia-flot-ico') || e.target.closest('.espia-flot-stop')) return;
      pStart = { x: e.clientX, y: e.clientY };
      moved = false;
      w.setPointerCapture?.(e.pointerId);
      w.classList.add('dragging');
      w.style.right = 'auto'; w.style.bottom = 'auto';
      const r = w.getBoundingClientRect();
      w.dataset._sl = String(r.left);
      w.dataset._st = String(r.top);
    };
    const onMove = e => {
      if (!pStart) return;
      const dx = e.clientX - pStart.x, dy = e.clientY - pStart.y;
      if (!moved && (Math.abs(dx) > 5 || Math.abs(dy) > 5)) moved = true;
      if (moved) {
        const sl = parseFloat(w.dataset._sl || 0);
        const st = parseFloat(w.dataset._st || 0);
        w.style.left = (sl + dx) + 'px';
        w.style.top  = (st + dy) + 'px';
      }
    };
    const onUp = () => {
      if (!pStart) return;
      const wasMoved = moved;
      pStart = null; moved = false;
      w.classList.remove('dragging');
      // Click puro sobre cuerpo (sin drag) → abre modal
      if (!wasMoved) _espiaModalAbrir();
    };
    w.addEventListener('pointerdown', onDown);
    w.addEventListener('pointermove', onMove);
    w.addEventListener('pointerup', onUp);
    w.addEventListener('pointercancel', () => { pStart = null; moved = false; w.classList.remove('dragging'); });

    _espiaWidgetUpdate();
  }

  function _espiaWidgetUpdate() {
    const w = document.getElementById('espiaFlotante');
    if (!w || !_espiaState) return;
    const nom = w.querySelector('.espia-flot-nom');
    if (nom) nom.textContent = _espiaState.nombre;
    const mic = w.querySelector('.espia-flot-ico-mic');
    if (mic) {
      const live = !!(_audioFlot && _audioFlot.chunks.length > 0);
      const muted = !!(_audioFlot && _audioFlot.muted);
      mic.classList.toggle('live', live && !muted);
      mic.classList.toggle('muted', muted);
      mic.textContent = muted ? '🔇' : '🎙️';
    }
    const gps = w.querySelector('.espia-flot-ico-gps');
    if (gps && _espiaState.gpsUlt) {
      const fecha = new Date(_espiaState.gpsUlt.timestamp || 0).getTime();
      const mins = (Date.now() - fecha) / 60000;
      gps.classList.toggle('fresh', mins < 5);
      gps.classList.toggle('stale', mins >= 60);
    }
    const sub = w.querySelector('.espia-flot-sub');
    if (sub) {
      const segs = _audioFlot ? Math.floor((Date.now() - _audioFlot.inicio) / 1000) : 0;
      const mm = String(Math.floor(segs / 60)).padStart(2, '0');
      const ss = String(segs % 60).padStart(2, '0');
      const gpsTxt = _espiaState.gpsUlt ? '· 📍' : '';
      sub.textContent = `${mm}:${ss} ${gpsTxt}`;
    }
  }

  // Cuando cierran el modal por backdrop o ESC y hay sesión activa, mantener
  // el flujo: el handler espiaModal ya llama a _espiaModalMinimizar.
  // Ningún cleanup adicional necesario — _espiaState se limpia en _espiaDetenerTodo.


  async function _audioLiveRefrescar() {
    const id = $('audioLiveDeviceId')?.value;
    if (!id) return;
    const cont = $('audioLiveEstadoActual');
    if (!cont) return;
    try {
      const data = await API.get('getEstadoAudio', { deviceId: id });
      if (data?.activa) {
        const sesionId = data.sesion.idSesion;
        const ini = data.sesion.inicio ? new Date(data.sesion.inicio) : null;
        const segs = ini ? Math.floor((Date.now() - ini.getTime()) / 1000) : 0;
        const mm = String(Math.floor(segs / 60)).padStart(2, '0');
        const ss = String(segs % 60).padStart(2, '0');
        cont.innerHTML = `<div class="card p-3" style="background:rgba(239,68,68,0.10);border:1px solid #dc2626;">
          <div class="flex items-center justify-between gap-2 flex-wrap">
            <div>
              <div class="text-sm font-bold text-red-300">🔴 Grabando ahora</div>
              <div class="text-[10px] text-slate-500 font-mono">${mm}:${ss} · auto-stop a 30:00</div>
            </div>
            <button onclick="MOS._audioLiveDetener('${sesionId}')" class="btn-primary text-xs px-3 py-1.5" style="background:#dc2626">⏹️ Detener</button>
          </div>
          <p class="text-[10px] text-slate-500 mt-2">El audio se está guardando para revisión posterior por el master.</p>
        </div>`;
      } else {
        cont.innerHTML = `<div class="card p-3" style="background:#0a1424;border:1px solid #1e293b;">
          <div class="flex items-center justify-between gap-2 flex-wrap">
            <div>
              <div class="text-sm font-bold text-slate-300">⏸ Sin grabación activa</div>
              <div class="text-[10px] text-slate-500">Inicia la escucha cuando lo necesites</div>
            </div>
            <button onclick="MOS._audioLiveIniciar('${id}')" class="btn-primary text-xs px-3 py-1.5" style="background:#dc2626">🎙️ Iniciar</button>
          </div>
        </div>`;
      }
    } catch(_) {
      cont.innerHTML = '<div class="text-center py-3 text-red-400 text-sm">Error consultando estado</div>';
    }
  }

  async function _audioLiveIniciar(deviceId) {
    if (!await _modalConfirm('¿Iniciar escucha?\n\nEl dispositivo grabará en chunks de 15s. Auto-detiene a los 30 min.', { warning: true, titulo: 'Iniciar escucha en vivo', okText: 'Iniciar' })) return;
    try {
      await API.post('iniciarEscuchaAudio', {
        deviceId,
        autorizadoPor: S.session?.nombre || 'admin',
        motivo: 'Escucha en vivo desde MOS'
      });
      toast('🎙️ Comando enviado', 'ok');
      setTimeout(_audioLiveRefrescar, 1500);
    } catch(e) {
      toast('Error: ' + e.message, 'error');
    }
  }

  async function _audioLiveDetener(idSesion) {
    try {
      await API.post('detenerEscuchaAudio', { idSesion });
      toast('⏹️ Detenido', 'ok');
      setTimeout(_audioLiveRefrescar, 1000);
    } catch(e) {
      toast('Error: ' + e.message, 'error');
    }
  }

  // Cancelar poll cuando se cierra el live
  document.addEventListener('mos:modal-cerrado', e => {
    if (e.detail === 'modalAudioLive' && _audioLivePollTimer) {
      clearInterval(_audioLivePollTimer); _audioLivePollTimer = null;
    }
  });

  // ────────────────────────────────────────────────────────
  // MODAL GPS — ubicación + mapa Google
  // ────────────────────────────────────────────────────────
  async function abrirModalGps(idDispositivo) {
    const d = (cfgData.dispositivos || []).find(x => x.ID_Dispositivo === idDispositivo);
    if (!d) return;
    $('gpsModalDeviceId').value = idDispositivo;
    $('gpsModalSubtitle').textContent = `${d.Nombre_Equipo || idDispositivo}${d.Ultima_Sesion ? ' · 👤 ' + d.Ultima_Sesion : ''}`;
    openModal('modalGps');
    await gpsCargar(24);
  }

  async function gpsCargar(horas) {
    const id = $('gpsModalDeviceId')?.value;
    if (!id) return;
    const info = $('gpsInfo');
    const mapa = $('gpsMapa');
    const cantEl = $('gpsCantidadPuntos');
    info.innerHTML = '<div class="text-center py-4 text-slate-500 text-sm">Cargando ubicación...</div>';
    mapa.innerHTML = '';
    try {
      const ult = await API.get('getUltimaUbicacionDispositivo', { deviceId: id });
      const hist = await API.get('getUbicacionesDispositivo', { deviceId: id, horas });
      if (!ult) {
        info.innerHTML = '<div class="text-center py-4 text-amber-400 text-sm">⚠ Este dispositivo nunca ha reportado ubicación</div>';
        return;
      }
      const fecha = ult.timestamp ? new Date(ult.timestamp) : null;
      const mins = fecha ? Math.floor((Date.now() - fecha.getTime()) / 60000) : null;
      const fmt = fecha ? fecha.toLocaleString('es-PE') : '—';
      const fresh = mins !== null && mins < 10;
      const dot = fresh ? '🟢' : (mins < 60 ? '🟢' : (mins < 60 * 24 ? '🟡' : '🔴'));
      const bat = ult.bateria !== '' && ult.bateria !== undefined ? `🔋 ${ult.bateria}%` : '';
      info.innerHTML = `<div class="flex items-center justify-between gap-2 flex-wrap">
        <div>
          <div class="text-sm font-bold text-white">${dot} Última ubicación · ${fmt}</div>
          <div class="text-[11px] text-slate-400 mt-1">📍 ${parseFloat(ult.lat).toFixed(6)}, ${parseFloat(ult.lng).toFixed(6)} · precisión ~${Math.round(ult.accuracy)}m ${bat}</div>
          ${ult.usuarioLogueado ? `<div class="text-[11px] text-slate-500 mt-0.5">👤 ${ult.usuarioLogueado}</div>` : ''}
        </div>
        <a href="https://www.google.com/maps?q=${ult.lat},${ult.lng}" target="_blank" class="btn-ghost text-xs">🗺️ Abrir en Maps</a>
      </div>`;

      cantEl.textContent = (Array.isArray(hist) ? hist.length : 0) + ' puntos en ' + horas + 'h';

      // Embed Google Maps con iframe (sin API key)
      const lat = parseFloat(ult.lat);
      const lng = parseFloat(ult.lng);
      mapa.innerHTML = `<iframe width="100%" height="100%" frameborder="0"
        src="https://maps.google.com/maps?q=${lat},${lng}&z=16&output=embed"
        style="border:none;"></iframe>`;
    } catch(e) {
      info.innerHTML = '<div class="text-center py-4 text-red-400 text-sm">Error: ' + e.message + '</div>';
    }
  }

  // Compat con código viejo (renderDispositivos eliminado)

  // ── PWA Install ──────────────────────────────────────────────
  let _installPrompt = null;
  window.addEventListener('beforeinstallprompt', e => {
    e.preventDefault();
    _installPrompt = e;
    const btn = document.getElementById('installAppBtn');
    if (btn) btn.classList.remove('hidden');
  });
  window.addEventListener('appinstalled', () => {
    _installPrompt = null;
    const btn = document.getElementById('installAppBtn');
    if (btn) btn.classList.add('hidden');
  });

  function installPWA() {
    if (!_installPrompt) { toast('La app ya está instalada o el navegador no lo permite', 'info'); return; }
    _installPrompt.prompt();
    _installPrompt.userChoice.then(r => {
      if (r.outcome === 'accepted') toast('App instalada correctamente', 'ok');
      _installPrompt = null;
    });
    closeAvatarMenu();
  }

  // ── Avatar dropdown (fixed, fuera del sidebar) ───────────────
  // ── SVG traveling border + dot en sidebar avatar ─────────
  function _initAvatarTrigSvg() {
    const outer   = document.getElementById('avatarTrigOuter');
    const svg     = document.getElementById('avatarTrigSvg');
    const bRect   = document.getElementById('avatarTrigBorderRect');
    const bBase   = document.getElementById('avatarTrigBaseRect');
    const dotPath = document.getElementById('avatarTrigRectPath');
    if (!outer || !svg || !bRect || !dotPath) return;

    const W = outer.offsetWidth;
    const H = outer.offsetHeight;
    if (!W || !H) return;

    const pad = 3, rx = 11;
    const svgW = W + pad * 2, svgH = H + pad * 2;
    svg.setAttribute('viewBox', `0 0 ${svgW} ${svgH}`);

    // Rect coords (button area offset by pad)
    [bRect, bBase].forEach(el => {
      el.setAttribute('x',      pad);
      el.setAttribute('y',      pad);
      el.setAttribute('width',  W);
      el.setAttribute('height', H);
      el.setAttribute('rx',     rx);
      el.setAttribute('ry',     rx);
    });

    // Perimeter → dasharray para segmento viajero
    const perim = Math.round(2 * (W + H) - 8 * rx + 2 * Math.PI * rx);
    const seg   = 72;
    bRect.style.strokeDasharray  = `${seg} ${perim - seg}`;
    bRect.style.strokeDashoffset = '0';

    // Inyectar keyframe con perimeter correcto
    const kfId = 'mos-trig-kf';
    let kfEl = document.getElementById(kfId);
    if (!kfEl) { kfEl = document.createElement('style'); kfEl.id = kfId; document.head.appendChild(kfEl); }
    kfEl.textContent = `@keyframes travelBorder{from{stroke-dashoffset:0}to{stroke-dashoffset:${-perim}}}`;
    bRect.style.animation = 'travelBorder 3s linear infinite';

    // Path para el punto verde (sigue el mismo rectángulo)
    const x = pad, y = pad;
    const d = `M ${x+rx} ${y} L ${x+W-rx} ${y} Q ${x+W} ${y} ${x+W} ${y+rx} ` +
              `L ${x+W} ${y+H-rx} Q ${x+W} ${y+H} ${x+W-rx} ${y+H} ` +
              `L ${x+rx} ${y+H} Q ${x} ${y+H} ${x} ${y+H-rx} ` +
              `L ${x} ${y+rx} Q ${x} ${y} ${x+rx} ${y} Z`;
    dotPath.setAttribute('d', d);
  }

  // Re-calcula al cambiar ancho del sidebar (hover tablet)
  (function _watchSidebarResize() {
    const sidebar = document.getElementById('sidebar');
    if (!sidebar || typeof ResizeObserver === 'undefined') return;
    let _trig;
    new ResizeObserver(() => {
      clearTimeout(_trig);
      _trig = setTimeout(_initAvatarTrigSvg, 60);
    }).observe(sidebar);
  })();

  // ── Clave admin global en avatar menu (sessionStorage) ──
  function _segEsAdmin(rol) {
    const r = String(rol || '').toUpperCase();
    return r === 'MASTER' || r === 'ADMIN' || r === 'ADMINISTRADOR';
  }
  async function _segCachearGlobalEnLogin(rol, pinAdmin) {
    if (!_segEsAdmin(rol)) return;
    try {
      const data = await API.get('getClaveAdminGlobal', { pinAdmin });
      if (data?.autorizado && data.pin) {
        sessionStorage.setItem('mos_admin_global_pin', data.pin);
        sessionStorage.setItem('mos_admin_global_dias', String(data.diasParaProximaRotacion ?? ''));
        sessionStorage.setItem('mos_admin_global_vencida', data.vencida ? '1' : '0');
      }
    } catch(_) { /* tolerar */ }
  }
  function _segActualizarCacheLocal(data) {
    if (!data || !data.pin) return;
    sessionStorage.setItem('mos_admin_global_pin', data.pin);
    sessionStorage.setItem('mos_admin_global_dias', String(data.diasParaProximaRotacion ?? ''));
    sessionStorage.setItem('mos_admin_global_vencida', data.vencida ? '1' : '0');
  }
  function _segLimpiarCacheLocal() {
    sessionStorage.removeItem('mos_admin_global_pin');
    sessionStorage.removeItem('mos_admin_global_dias');
    sessionStorage.removeItem('mos_admin_global_vencida');
  }
  function _segPintarEnAvatarMenu() {
    const box      = $('avMenuClaveBox');
    const loginBox = $('avMenuClaveLogin');
    if (!box || !loginBox) return;
    const rolOk = _segEsAdmin(S.session?.rol);
    const pin = sessionStorage.getItem('mos_admin_global_pin');
    if (!rolOk) {
      box.classList.add('hidden');
      loginBox.classList.add('hidden');
      return;
    }
    if (pin) {
      // Tenemos clave cacheada — mostrar bloque visible
      loginBox.classList.add('hidden');
      box.classList.remove('hidden');
      const elPin = $('avMenuClavePin');
      if (elPin) elPin.textContent = pin.split('').join(' ');
      const dias = parseInt(sessionStorage.getItem('mos_admin_global_dias') || '0', 10);
      const vencida = sessionStorage.getItem('mos_admin_global_vencida') === '1';
      const elDias = $('avMenuClaveDias');
      if (elDias) {
        if (vencida) {
          elDias.textContent = '⚠ Vencida';
          elDias.style.color = '#f87171';
        } else if (dias <= 5) {
          elDias.textContent = dias + 'd';
          elDias.style.color = '#fbbf24';
        } else {
          elDias.textContent = dias + 'd';
          elDias.style.color = '#94a3b8';
        }
      }
      // Click solo activo para MASTER (admin/administrador no tienen acceso a config)
      const esMaster = String(S.session?.rol || '').toUpperCase() === 'MASTER';
      box.onclick = esMaster
        ? () => { try { nav('config'); setCfgTab('seguridad'); } catch(_){} closeAvatarMenu(); }
        : null;
      box.style.cursor = esMaster ? 'pointer' : 'default';
      box.title = esMaster ? 'Tocar para ir al panel de seguridad' : 'Solo el master puede modificarla';
    } else {
      // Sin caché — mostrar input para autenticar
      box.classList.add('hidden');
      loginBox.classList.remove('hidden');
      const inp = $('avMenuClaveLoginPin');
      if (inp) inp.value = '';
      const err = $('avMenuClaveLoginErr');
      if (err) err.textContent = '';
    }
  }

  async function av_consultarClaveDesdeMenu() {
    const inp = $('avMenuClaveLoginPin');
    const err = $('avMenuClaveLoginErr');
    const pin = String(inp?.value || '').trim();
    if (!/^\d{4}$/.test(pin)) {
      if (err) err.textContent = 'PIN debe tener 4 dígitos';
      return;
    }
    if (err) err.textContent = '';

    // 🚀 OPTIMISTA: mostrar YA el bloque revelado con skeleton shimmer en
    // lugar de dejar al user mirando el botón sin respuesta. El fetch
    // corre en background; al llegar se reemplaza el skeleton por la clave.
    const box      = $('avMenuClaveBox');
    const loginBox = $('avMenuClaveLogin');
    const elPin    = $('avMenuClavePin');
    const elDias   = $('avMenuClaveDias');
    if (box && loginBox) {
      loginBox.classList.add('hidden');
      box.classList.remove('hidden');
      if (elPin)  elPin.innerHTML = '<span class="cg-skel-pin"></span>';
      if (elDias) { elDias.textContent = '···'; elDias.style.color = '#475569'; }
      box.onclick = null; box.style.cursor = 'default';
    }

    try {
      const data = await API.get('getClaveAdminGlobal', { pinAdmin: pin });
      if (!data?.autorizado) {
        // PIN malo → volver al input con error
        if (box) box.classList.add('hidden');
        if (loginBox) loginBox.classList.remove('hidden');
        if (err) err.textContent = data?.error || 'PIN incorrecto';
        if (inp) inp.value = '';
        return;
      }
      _segActualizarCacheLocal(data);
      _segPintarEnAvatarMenu();
    } catch(e) {
      console.error('[av_consultarClaveDesdeMenu]', e);
      // Error de red → volver al input con error
      if (box) box.classList.add('hidden');
      if (loginBox) loginBox.classList.remove('hidden');
      if (err) err.textContent = e?.message || 'Sin conexión';
    }
  }

  function toggleAvatarMenu() {
    const menu = $('avatarMenu');
    if (!menu) return;
    if (!menu.classList.contains('hidden')) {
      menu.classList.add('hidden');
      return;
    }
    // Pintar clave global si aplica
    _segPintarEnAvatarMenu();
    // [fix carrera] Re-aplicar visibilidad de Config: si init() corrió antes de que
    // #btnAvatarConfig existiera, el gate se saltó y quedó oculto. Al abrir el menú el DOM
    // ya está completo → se corrige aquí, siempre.
    try { _aplicarVisibilidadConfig(); } catch (_) {}
    // Buscar trigger visible: sidebar en desktop, botón mobile en móvil
    let trigger = document.querySelector('.avatar-trigger');
    if (!trigger || trigger.getBoundingClientRect().width === 0) {
      trigger = $('avatarMobBtn') || $('sessionAvatarMob');
    }
    if (trigger) {
      const rect   = trigger.getBoundingClientRect();
      const menuW  = 205;
      const midY   = window.innerHeight / 2;
      menu.style.top    = '0px'; // temporal para medir
      menu.style.left   = '0px';
      menu.style.right  = 'auto';
      menu.style.bottom = 'auto';
      menu.classList.remove('hidden');
      const menuH = menu.offsetHeight;
      if (rect.top < midY) {
        // trigger en mitad superior (header mobile) → abre DEBAJO alineado a la DERECHA del botón
        const rightOffset = window.innerWidth - rect.right;
        menu.style.right = Math.max(8, rightOffset) + 'px';
        menu.style.left  = 'auto';
        menu.style.top   = (rect.bottom + 8) + 'px';
      } else {
        // trigger en mitad inferior (sidebar) → abre ENCIMA alineado a la IZQUIERDA
        menu.style.left  = Math.max(8, rect.left) + 'px';
        menu.style.right = 'auto';
        menu.style.top   = Math.max(8, rect.top - menuH - 8) + 'px';
      }
    } else {
      menu.classList.remove('hidden');
    }
    setTimeout(() => document.addEventListener('click', _closeAvatarOnOutside, { once: true }), 0);
  }
  function closeAvatarMenu() {
    const menu = $('avatarMenu');
    if (menu) menu.classList.add('hidden');
  }
  function _closeAvatarOnOutside(e) {
    const menu = $('avatarMenu');
    const wrap = $('avatarWrap');
    const mobTrigger = $('sessionAvatarMob');
    if (menu && !menu.contains(e.target) &&
        (!wrap || !wrap.contains(e.target)) &&
        (!mobTrigger || !mobTrigger.contains(e.target))) {
      closeAvatarMenu();
    }
  }

  // ═══════════════════════════════════════════════════════════════
  // [v2.41.92] CENTRO TRIBUTARIO — IGV a favor + IGV emitido + Renta
  // ═══════════════════════════════════════════════════════════════
  const _tribState = { mes: null, anio: null, data: null, busy: false };

  // Nombres de mes en español neutral — el label del chip los usa en minúscula
  // y el <select> oculto en la forma corta (nunca se ve, pero queda legible).
  const _TRIB_MESES = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
  const _TRIB_MESES_CORTO = ['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];

  // Skeleton de carga. Se re-inyecta en cada carga porque el manejador de error
  // pisa el contenedor con el mensaje de fallo.
  const _TRIB_SK_HTML =
    '<div class="trib-sk trib-sk-hero"></div>' +
    '<div class="trib-sk-grid">' +
      '<div class="trib-sk trib-sk-card"></div><div class="trib-sk trib-sk-card"></div>' +
      '<div class="trib-sk trib-sk-card"></div><div class="trib-sk trib-sk-card"></div>' +
    '</div>' +
    '<div class="trib-sk trib-sk-panel"></div>';

  async function _loadTributario() {
    _finBeep && _finBeep('nav');
    // Inicializar selector de mes (12 meses hacia atrás). El <select> quedó
    // OCULTO pero sigue siendo la única fuente de verdad del mes elegido:
    // tribCargar() lee de él y los chips ‹ › solo mueven su selectedIndex.
    const sel = $('tribMesSelect');
    if (sel && !sel.options.length) {
      const hoy = new Date();
      for (let i = 0; i < 12; i++) {
        const d = new Date(hoy.getFullYear(), hoy.getMonth() - i, 1);
        const m = d.getMonth() + 1, a = d.getFullYear();
        const opt = document.createElement('option');
        opt.value = m + '|' + a;
        opt.textContent = _TRIB_MESES_CORTO[d.getMonth()] + ' ' + a;
        if (i === 0) opt.selected = true;
        sel.appendChild(opt);
      }
    }
    _tribPintarMes();
    await tribCargar();
    _tribCargarDeclaracion();   // [956] card de planificación de declaración SUNAT (cronograma por RUC)
    // El histórico son 12 RPCs SECUENCIALES (api.js 761): va en segundo plano y
    // alimenta tres consumidores de una sola vez — sparklines de las cards,
    // deltas vs mes anterior y el panel de 12 meses. Cache con TTL: entrar y
    // salir del módulo no lo vuelve a pedir.
    _tribHistCargar();
  }

  // [956] Card de planificación de declaración SUNAT: qué período toca, cuánto, cuándo vence
  //   (según el cronograma oficial por dígito de RUC) + cuenta regresiva con semáforo.
  function _declFecha(iso) { try { const p = String(iso).split('-'); return parseInt(p[2]) + ' ' + _TRIB_MESES_CORTO[parseInt(p[1]) - 1]; } catch (_) { return iso; } }
  let _tribDeclData = null;
  async function _tribCargarDeclaracion() {
    const cont = document.getElementById('tribDeclaracion'); if (!cont) return;
    let r = null; try { r = await API.post('sunatDeclaracion', {}); } catch (_) {}
    const d = (r && r.data) ? r.data : (r || {});
    _tribDeclData = d;
    const per = d.periodo;
    if (!per) { cont.innerHTML = ''; return; }
    const dias = parseInt(per.diasRestantes), vencido = !!per.vencido;
    const est = vencido ? 'venc' : dias === 0 ? 'hoy' : dias <= 2 ? 'urg' : dias <= 7 ? 'alerta' : 'ok';
    const estLbl = vencido ? '⚫ VENCIÓ' : { hoy: '🔴 VENCE HOY', urg: '🔴 URGENTE', alerta: '🟡 PRONTO', ok: '🟢 A TIEMPO' }[est];
    const mesNom = _TRIB_MESES[(per.mes || 1) - 1];
    const pct = vencido ? 100 : Math.max(5, Math.min(100, (30 - dias) / 30 * 100));
    const es = per.estimado || {}, dc = per.declarado || {};
    const igv = parseFloat(es.igv) || 0, renta = parseFloat(es.renta) || 0, plame = parseFloat(es.plame) || 0, afp = parseFloat(es.afp) || 0, tot = parseFloat(es.total) || 0;
    const nv = parseInt(dc.nVouchers) || 0, decTot = parseFloat(dc.total) || 0, dif = parseFloat(per.diferencia) || 0, difAbs = Math.abs(dif);
    const thr = Math.max(20, tot * 0.03);
    const difEst = !nv ? '' : difAbs <= thr ? 'ok' : difAbs <= tot * 0.1 ? 'mid' : 'bad';
    const difLbl = { ok: '✅ cuadra con tu estimado', mid: '🟡 hay diferencia, revisá', bad: '🔴 diferencia grande — ¿falta una factura o error del contador?' }[difEst] || '';
    const enc = d.enCurso, anual = d.anual;
    const vencTxt = vencido
      ? `venció el <b>${_declFecha(per.fechaVence)}</b> · hace ${Math.abs(dias)} día${Math.abs(dias) === 1 ? '' : 's'}`
      : dias === 0 ? `<b>vence hoy</b> (${_declFecha(per.fechaVence)})` : `vence el <b>${_declFecha(per.fechaVence)}</b> · faltan ${dias} días`;
    const row = (ic, nm, exp, val, cls) => `<div class="trib-decl-row ${cls || ''}"><span class="ic">${ic}</span><div class="cc"><b>${nm}</b>${exp ? `<small>${exp}</small>` : ''}</div><span class="mn">${_tribFmtSoles(val)}</span></div>`;
    cont.innerHTML = `<div class="trib-decl e-${est}">
      <div class="trib-decl-hd" onclick="MOS.tribDeclCal()" style="cursor:pointer" title="Ver el cronograma del año">
        <div class="trib-decl-ico">📋</div>
        <div class="trib-decl-ti"><b>Declaración SUNAT</b><span>RUC …${_esc(String(d.digito))} · lo que te toca pagar</span></div>
        <div class="trib-decl-badge">${estLbl}</div>
      </div>
      <div class="trib-decl-period">Declaras <b>${_esc(mesNom)} ${per.anio}</b> (mes cerrado) · ${vencTxt}</div>
      <div class="trib-decl-rows">
        ${row('🧾', 'IGV', igv > 0 ? 'IGV de tus ventas − IGV de tus compras con factura' : 'IGV de ventas − compras · este mes tu crédito cubrió todo', igv)}
        ${row('📊', 'Renta', '1.5% de tus ventas netas del mes (régimen MYPE)', renta)}
        ${row('🏥', 'EsSalud (PLAME)', '9% de la planilla · 5 personas en sueldo mínimo', plame)}
        ${row('🏦', 'AFP / ONP', '13% de pensiones retenido a la planilla · aprox', afp)}
        ${row('💰', 'Total estimado a pagar', vencido ? '' : 'se recalcula solo con cada cambio', tot, 'total')}
      </div>
      ${nv ? `<div class="trib-decl-cmp cmp-${difEst}"><span>Según tus vouchers declaraste <b>${_tribFmtSoles(decTot)}</b> (${nv})</span><span class="cmp-dif">${dif === 0 ? 'sin diferencia' : _tribFmtSoles(difAbs) + (dif > 0 ? ' menos' : ' más') + ' que mi estimado'} · ${difLbl}</span></div>` : ''}
      ${per.multa ? `<div class="trib-decl-alert">⚠ VENCIÓ sin voucher cargado. Declarar fuera de plazo genera <b>multa</b> (≈1 UIT, con rebaja hasta 90% si declaras y pagas voluntariamente) + intereses. Declara y sube el voucher cuanto antes.</div>` : ''}
      ${enc ? `<div class="trib-decl-anual">🗓️ En curso: <b>${_esc(_TRIB_MESES[(enc.mes || 1) - 1])}</b> — cierra en ${enc.diasCierre} día${enc.diasCierre === 1 ? '' : 's'} (${_declFecha(enc.finMes)}); ahí recién se declara, hasta el <b>${_declFecha(enc.fechaVence)}</b></div>` : ''}
      ${anual ? `<div class="trib-decl-anual">📅 Declaración <b>anual</b> de Renta: ${_declFecha(anual.fechaVence)} ${String(anual.fechaVence).slice(0, 4)} · en ${anual.diasRestantes} días${anual.verificado ? '' : ' <i>(estimado)</i>'}</div>` : ''}
      <div class="trib-decl-actions">
        <button type="button" class="trib-decl-btn" onclick="MOS.sunatBuzon(${per.mes},${per.anio})">📎 Buzón de vouchers${nv ? ' · ' + nv : ''}</button>
        <button type="button" class="trib-decl-btn ghost" onclick="MOS.sunatHistorial()">📊 Historial</button>
        <button type="button" class="trib-decl-btn ghost" onclick="MOS.tribDeclCal()">📅 Cronograma</button>
      </div>
    </div>
    <div id="tribDeclCalPanel" class="trib-declcal hidden"></div>
    <div id="tribBuzonPanel" class="trib-declcal hidden"></div>
    <div id="tribHistPanel" class="trib-declcal hidden"></div>`;
  }
  // Buzón de vouchers (una sola cola para todos los tributos). Multi-foto galería/cámara → OCR → confirmar → guardar.
  let _sunatBuzonMesAnio = { mes: 0, anio: 0 };
  async function sunatBuzon(mes, anio) {
    const panel = document.getElementById('tribBuzonPanel'); if (!panel) return;
    _sunatBuzonMesAnio = { mes: mes || _sunatBuzonMesAnio.mes, anio: anio || _sunatBuzonMesAnio.anio };
    if (!panel.classList.contains('hidden')) { panel.classList.add('hidden'); panel.innerHTML = ''; return; }
    document.getElementById('tribDeclCalPanel') && document.getElementById('tribDeclCalPanel').classList.add('hidden');
    document.getElementById('tribHistPanel') && document.getElementById('tribHistPanel').classList.add('hidden');
    panel.classList.remove('hidden');
    panel.innerHTML = `<div class="trib-cal-hd">📎 Buzón de vouchers · ${_esc(_TRIB_MESES_CORTO[(_sunatBuzonMesAnio.mes || 1) - 1])} ${_sunatBuzonMesAnio.anio}</div>
      <label class="trib-buz-drop"><input type="file" accept="image/*" multiple style="display:none" onchange="MOS.sunatBuzonFiles(this.files)">📷 Subir fotos (galería o cámara) — varias a la vez</label>
      <div id="tribBuzonPend"></div><div id="tribBuzonList"></div>`;
    _sunatBuzonListar();
  }
  async function _sunatBuzonListar() {
    const list = document.getElementById('tribBuzonList'); if (!list) return;
    let r = null; try { r = await API.post('sunatVoucherListar', _sunatBuzonMesAnio); } catch (_) {}
    const items = (r && r.items) || [];
    list.innerHTML = items.length ? items.map(v => {
      const t = v.tipo === 'PLAME' ? '👥 PLAME' : '📄 IGV-Renta';
      const montos = [v.igv > 0 ? 'IGV ' + _tribFmtSoles(v.igv) : '', v.renta > 0 ? 'Renta ' + _tribFmtSoles(v.renta) : '', v.essalud > 0 ? 'EsSalud ' + _tribFmtSoles(v.essalud) : '', v.afp > 0 ? 'AFP ' + _tribFmtSoles(v.afp) : ''].filter(Boolean).join(' · ');
      return `<div class="trib-buz-row"><span class="t">${t}</span><span class="m">${_esc(montos || '—')}${v.nroOrden ? ' · Nº ' + _esc(v.nroOrden) : ''}</span><button class="x" onclick="MOS.sunatVoucherBorrar('${_esc(v.id)}')">✕</button></div>`;
    }).join('') : '<div class="trib-cal-hd" style="opacity:.6">Sin vouchers cargados aún</div>';
  }
  async function sunatBuzonFiles(files) {
    const pend = document.getElementById('tribBuzonPend'); if (!pend || !files || !files.length) return;
    for (const file of Array.from(files)) {
      const row = document.createElement('div'); row.className = 'trib-buz-pend'; row.innerHTML = '◍ leyendo con OCR…';
      pend.appendChild(row);
      try {
        const img = await _catCompressImg(file, 1400, 0.82);
        let ocr = { tipo: 'IGV_RENTA', igv: 0, renta: 0, essalud: 0, afp: 0, nroOrden: '' };
        try { const r = await API.post('sunatVoucherOcr', { jpgB64: img.base64, mime: 'image/jpeg' }); if (r && r.data) ocr = r.data; } catch (_) {}
        row.dataset.b64 = img.base64;
        row.innerHTML = `<div class="trib-buz-form">
          <select class="tp">${['IGV_RENTA', 'PLAME'].map(t => `<option value="${t}" ${ocr.tipo === t ? 'selected' : ''}>${t === 'PLAME' ? '👥 PLAME (EsSalud/AFP/ONP)' : '📄 IGV-Renta'}</option>`).join('')}</select>
          <input class="ig" type="number" step="0.01" placeholder="IGV" value="${ocr.igv || ''}">
          <input class="re" type="number" step="0.01" placeholder="Renta" value="${ocr.renta || ''}">
          <input class="es" type="number" step="0.01" placeholder="EsSalud" value="${ocr.essalud || ''}">
          <input class="af" type="number" step="0.01" placeholder="AFP/ONP" value="${ocr.afp || ''}">
          <input class="no" type="text" placeholder="Nº orden" value="${_esc(ocr.nroOrden || '')}">
          <button class="ok" onclick="MOS.sunatBuzonGuardar(this)">Guardar ✓</button>
        </div>`;
      } catch (e) { row.innerHTML = '⚠ No se pudo leer la foto'; }
    }
  }
  async function sunatBuzonGuardar(btn) {
    const row = btn.closest('.trib-buz-pend'); if (!row) return;
    const g = s => row.querySelector(s);
    btn.disabled = true; btn.textContent = 'Guardando…';
    try {
      const r = await API.post('sunatVoucherSubir', {
        mes: _sunatBuzonMesAnio.mes, anio: _sunatBuzonMesAnio.anio, jpgB64: row.dataset.b64,
        tipo: g('.tp').value, igv: parseFloat(g('.ig').value) || 0, renta: parseFloat(g('.re').value) || 0,
        essalud: parseFloat(g('.es').value) || 0, afp: parseFloat(g('.af').value) || 0, nroOrden: g('.no').value || ''
      });
      if (r && r.status === 'success') { row.remove(); _sunatBuzonListar(); _tribCargarDeclaracion(); try { _finBeep && _finBeep('ok'); } catch (_) {} }
      else { btn.disabled = false; btn.textContent = 'Guardar ✓'; toast('No se pudo guardar el voucher', 'error'); }
    } catch (e) { btn.disabled = false; btn.textContent = 'Guardar ✓'; toast('Error: ' + (e.message || e), 'error'); }
  }
  async function sunatVoucherBorrar(id) {
    try { await API.post('sunatVoucherBorrar', { id }); _sunatBuzonListar(); _tribCargarDeclaracion(); } catch (_) {}
  }
  async function sunatHistorial() {
    const panel = document.getElementById('tribHistPanel'); if (!panel) return;
    if (!panel.classList.contains('hidden')) { panel.classList.add('hidden'); panel.innerHTML = ''; return; }
    document.getElementById('tribDeclCalPanel') && document.getElementById('tribDeclCalPanel').classList.add('hidden');
    document.getElementById('tribBuzonPanel') && document.getElementById('tribBuzonPanel').classList.add('hidden');
    panel.classList.remove('hidden');
    panel.innerHTML = '<div class="trib-cal-hd">◍ cargando historial…</div>';
    let r = null; try { r = await API.post('sunatHistorial', {}); } catch (_) {}
    const items = (r && r.items) || [];
    if (!items.length) { panel.innerHTML = '<div class="trib-cal-hd">Aún no hay meses cerrados este año</div>'; return; }
    panel.innerHTML = `<div class="trib-cal-hd">📊 Estimado vs declarado (meses cerrados)</div><div class="trib-hist">${items.map(x => {
      const dif = parseFloat(x.diferencia) || 0, nv = parseInt(x.nVouchers) || 0;
      const cls = !nv ? 'sin' : Math.abs(dif) <= Math.max(20, x.estimado * 0.03) ? 'ok' : 'bad';
      return `<div class="trib-hist-r cls-${cls}"><span class="hm">${_esc(_TRIB_MESES_CORTO[(x.mes || 1) - 1])}</span><span class="he">est ${_tribFmtSoles(x.estimado)}</span><span class="hd">${nv ? 'dec ' + _tribFmtSoles(x.declarado) : 'sin voucher'}</span><span class="hx">${nv ? (dif === 0 ? '✅' : (dif > 0 ? '▼' : '▲') + _tribFmtSoles(Math.abs(dif))) : '—'}</span></div>`;
    }).join('')}</div>`;
  }
  // mini-calendario: los 12 meses del cronograma SUNAT del año (período → vencimiento), con su estado
  function tribDeclCal() {
    const panel = document.getElementById('tribDeclCalPanel'); if (!panel) return;
    if (!panel.classList.contains('hidden')) { panel.classList.add('hidden'); panel.innerHTML = ''; return; }
    const cal = ((_tribDeclData || {}).calendario) || [];
    if (!cal.length) return;
    const cells = cal.map(x => {
      const mes = _TRIB_MESES_CORTO[(x.periodoMes || 1) - 1];
      const ic = x.estado === 'actual' ? '👉' : x.estado === 'pasado' ? '✓' : '';
      return `<div class="trib-cal-c est-${x.estado}"><span class="m">${_esc(mes)}</span><b>${_declFecha(x.fechaVence)}</b><small>${ic} ${x.estado === 'actual' ? 'a declarar' : x.estado === 'pasado' ? 'vencido' : 'por venir'}</small></div>`;
    }).join('');
    panel.innerHTML = `<div class="trib-cal-hd">Cronograma ${cal[0] ? cal[0].anio : ''} · RUC …${(_tribDeclData || {}).digito} — período que declaras → vence</div><div class="trib-cal-grid">${cells}</div>`;
    panel.classList.remove('hidden');
    try { _finBeep && _finBeep('pop'); } catch (_) {}
  }
  async function tribCargar() {
    if (_tribState.busy) return;
    const sel = $('tribMesSelect');
    const parts = (sel?.value || '').split('|');
    const mes  = parseInt(parts[0], 10) || (new Date().getMonth() + 1);
    const anio = parseInt(parts[1], 10) || new Date().getFullYear();
    const esMismoMes = _tribState.data && _tribState.mes === mes && _tribState.anio === anio;
    _tribState.mes = mes; _tribState.anio = anio;
    _tribState.busy = true;
    _tribPintarMes();

    // [v2.41.93] Si ya tenemos data precargada del mismo mes (de boot),
    // renderizar al instante y refrescar en background — sensación instantánea.
    if (esMismoMes) {
      _tribRender(_tribState.data, { sonar: true });
      $('tribLoading').classList.add('hidden');
      $('tribContent').classList.remove('hidden');
      // Refresh silencioso en bg
      iconBusy('tributario', true);
      _tribGirando(true);
      try {
        const res = await API.post('tribResumenMes', { mes, anio });
        const d = (res && res.data) ? res.data : (res || {});
        _tribState.data = d;
        _tribRender(d);   // sin sonido: es refresco silencioso, no una acción del usuario
      } catch(_) {}
      finally { iconBusy('tributario', false); _tribGirando(false); _tribState.busy = false; }
      return;
    }

    // Sin cache: skeletons visibles (se re-inyectan porque el handler de error
    // los reemplaza por el mensaje de fallo).
    $('tribLoading').innerHTML = _TRIB_SK_HTML;
    $('tribLoading').classList.remove('hidden');
    $('tribContent').classList.add('hidden');
    iconBusy('tributario', true);
    _tribGirando(true);

    try {
      const res = await API.post('tribResumenMes', { mes, anio });
      const d = (res && res.data) ? res.data : (res || {});
      _tribState.data = d;
      _tribRender(d, { sonar: true });
      $('tribLoading').classList.add('hidden');
      $('tribContent').classList.remove('hidden');
      // El histórico ya cacheado se re-pinta para mover el punto destacado de
      // las sparklines al mes recién elegido.
      _tribPintarDeltasYSparks();
      _tribPintarHistorico();
    } catch(e) {
      console.error('[Tributario] cargar:', e);
      $('tribLoading').innerHTML =
        '<div class="trib-vacio"><span class="trib-vacio-ico">⚠</span>No se pudo cargar el mes<br>' +
        '<span style="color:#fb7185">' + _escapeHtml(String(e && e.message ? e.message : e)) + '</span></div>';
    } finally {
      iconBusy('tributario', false);
      _tribGirando(false);
      _tribState.busy = false;
    }
  }

  // El botón ↻ gira mientras hay un fetch en vuelo (feedback sin bloquear).
  function _tribGirando(on) {
    const b = $('tribBtnRefrescar');
    if (b) b.classList.toggle('girando', !!on);
  }

  // ── Selector de mes en chips ‹ agosto 2026 › ────────────────────────
  // El <select> oculto manda; estas funciones solo lo mueven y repintan.
  function _tribPintarMes() {
    const sel = $('tribMesSelect');
    const lbl = $('tribMesLabel');
    if (!sel || !lbl || !sel.options.length) return;
    const parts = String(sel.value || '').split('|');
    const m = parseInt(parts[0], 10), a = parseInt(parts[1], 10);
    lbl.textContent = (m >= 1 && m <= 12) ? (_TRIB_MESES[m - 1] + ' ' + a) : (sel.selectedOptions[0]?.textContent || '—');
    // index 0 = mes actual; index 11 = el más antiguo de la ventana.
    const prev = $('tribMesPrev'), next = $('tribMesNext');
    if (prev) prev.disabled = sel.selectedIndex >= sel.options.length - 1;
    if (next) next.disabled = sel.selectedIndex <= 0;
  }

  // dir -1 = hacia atrás en el tiempo (el <select> está ordenado del más
  // reciente al más antiguo, por eso el índice va al revés que el calendario).
  function tribMesShift(dir) {
    const sel = $('tribMesSelect');
    if (!sel || !sel.options.length) return;
    const nuevo = sel.selectedIndex + (dir < 0 ? 1 : -1);
    if (nuevo < 0 || nuevo >= sel.options.length) return;
    sel.selectedIndex = nuevo;
    _finBeep && _finBeep('click');
    _tribPintarMes();
    tribCargar();
  }

  function tribMesMenu(ev) {
    const sel = $('tribMesSelect');
    if (!sel || !sel.options.length) return;
    const items = [];
    for (let i = 0; i < sel.options.length; i++) {
      const parts = String(sel.options[i].value).split('|');
      const m = parseInt(parts[0], 10), a = parts[1];
      items.push({
        ico: i === 0 ? '•' : '',
        txt: (m >= 1 && m <= 12 ? _TRIB_MESES[m - 1] : '?') + ' ' + a,
        activo: i === sel.selectedIndex,
        fn: () => { sel.selectedIndex = i; _tribPintarMes(); tribCargar(); }
      });
    }
    _tribPopover(ev, items, 'Elegir mes');
  }

  // Menú ⋯ del módulo: las acciones de siempre (OCR, reconciliar, huérfanas,
  // exportar) reubicadas fuera de la vista principal.
  function tribAccionesMenu(ev) {
    _tribPopover(ev, [
      { ico: '🤖', txt: 'Re-encolar OCR del mes',      fn: () => tribOCRMasivo() },
      { ico: '🔄', txt: 'Reconciliar CPE con SUNAT',   fn: () => tribReconciliarCPEs() },
      { ico: '📥', txt: 'Exportar Excel del mes',      fn: () => tribExportarExcel() },
      { sep: true },
      { ico: '📊', txt: 'Recargar histórico 12 meses', fn: () => { _tribHistCargar(true); toast('📊 Recalculando 12 meses...', 'info'); } },
      { ico: '🧹', txt: 'Limpiar ventas huérfanas',    fn: () => tribLimpiarHuerfanas() }
    ], 'Acciones');
  }

  // Popover genérico anclado al botón que lo disparó. Se cierra al primer
  // click fuera o con Escape (un solo popover vivo a la vez).
  let _tribPopEl = null;
  function _tribPopover(ev, items, titulo) {
    _tribPopCerrar();
    const ancla = ev && ev.currentTarget ? ev.currentTarget : (ev && ev.target);
    const pop = document.createElement('div');
    pop.className = 'trib-pop';
    _tribPopEl = pop;
    if (titulo) {
      const cap = document.createElement('div');
      cap.className = 'trib-pop-cap';
      cap.textContent = titulo;
      pop.appendChild(cap);
    }
    items.forEach(it => {
      if (it.sep) { const s = document.createElement('div'); s.className = 'trib-pop-sep'; pop.appendChild(s); return; }
      const b = document.createElement('button');
      b.type = 'button';
      b.className = 'trib-pop-item' + (it.activo ? ' activo' : '');
      const ico = document.createElement('span');
      ico.className = 'ico';
      ico.textContent = it.ico || '';
      const txt = document.createElement('span');
      txt.textContent = it.txt;
      b.appendChild(ico); b.appendChild(txt);
      b.onclick = () => { _tribPopCerrar(); _finBeep && _finBeep('click'); try { it.fn(); } catch (e) { console.warn('[Tributario menú]', e); } };
      pop.appendChild(b);
    });
    document.body.appendChild(pop);
    // Anclaje: bajo el botón, alineado a la derecha si no cabe.
    const r = ancla && ancla.getBoundingClientRect ? ancla.getBoundingClientRect() : { left: 12, bottom: 60, right: 200 };
    const w = pop.offsetWidth;
    let left = r.left;
    if (left + w > window.innerWidth - 12) left = Math.max(12, window.innerWidth - w - 12);
    pop.style.left = left + 'px';
    pop.style.top  = (r.bottom + window.scrollY + 8) + 'px';
    setTimeout(() => {
      document.addEventListener('click', _tribPopFuera, true);
      document.addEventListener('keydown', _tribPopEsc, true);
    }, 0);
  }
  function _tribPopFuera(e) { if (_tribPopEl && !_tribPopEl.contains(e.target)) _tribPopCerrar(); }
  function _tribPopEsc(e) { if (e.key === 'Escape') _tribPopCerrar(); }
  function _tribPopCerrar() {
    if (!_tribPopEl) return;
    _tribPopEl.remove(); _tribPopEl = null;
    document.removeEventListener('click', _tribPopFuera, true);
    document.removeEventListener('keydown', _tribPopEsc, true);
  }

  function _tribFmtSoles(n) {
    return 'S/ ' + (parseFloat(n) || 0).toLocaleString('es-PE', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }

  // Cuenta ascendente sobre un elemento. `fmt` permite formatear algo que no
  // sea dinero (por ejemplo un porcentaje); por defecto es soles.
  // Respeta prefers-reduced-motion: ahí escribe el valor final de una.
  function _tribCountUp(el, target, fmt) {
    if (!el) return;
    const f = fmt || _tribFmtSoles;
    const fin = Number(target) || 0;
    if (window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      el.textContent = f(fin); el.dataset.cur = fin; return;
    }
    const start = parseFloat(el.dataset.cur || 0);
    if (Math.abs(fin - start) < 0.005) { el.textContent = f(fin); el.dataset.cur = fin; return; }
    const duration = 780;
    const t0 = performance.now();
    function step(t) {
      const p = Math.min(1, (t - t0) / duration);
      const e = 1 - Math.pow(2, -9 * p);   // ease-out exponencial: arranca fuerte y frena
      const v = start + (fin - start) * e;
      el.textContent = f(p >= 1 ? fin : v);
      if (p < 1) requestAnimationFrame(step);
      else el.dataset.cur = fin;
    }
    requestAnimationFrame(step);
  }

  // Formato compacto para ejes y etiquetas del chart (S/ 12.4k). En las cards
  // y en el HERO siempre va el monto completo: acá solo se comprimen las
  // marcas del gráfico, donde el espacio manda.
  function _tribFmtCorto(n) {
    const v = Math.abs(Number(n) || 0);
    const signo = (Number(n) || 0) < 0 ? '-' : '';
    if (v >= 1000000) return signo + (v / 1000000).toFixed(v >= 10000000 ? 0 : 1).replace('.0', '') + 'M';
    if (v >= 1000)    return signo + (v / 1000).toFixed(v >= 10000 ? 0 : 1).replace('.0', '') + 'k';
    return signo + v.toFixed(0);
  }

  // ═══ HISTÓRICO 12 MESES · una sola descarga, tres consumidores ═══════
  // (sparklines de las cards · deltas vs mes anterior · panel de 12 meses)
  let _tribHist = null;
  let _tribHistTs = 0;
  let _tribHistBusy = false;

  async function _tribHistCargar(force) {
    if (_tribHistBusy) return _tribHist;
    if (!force && _tribHist && (Date.now() - _tribHistTs) < 600000) {
      _tribPintarHistorico(); _tribPintarDeltasYSparks(); return _tribHist;
    }
    _tribHistBusy = true;
    try {
      const res = await API.post('tribHistorico12meses', {});
      const arr = (res && res.data) ? res.data : res;
      if (Array.isArray(arr) && arr.length) {
        // Convención de signo del módulo: positivo = A FAVOR. El backend
        // devuelve `balance` como emitido − favor ("lo que debes"), así que
        // acá se calcula el complemento para que HERO, cards y chart hablen
        // todos el mismo idioma.
        _tribHist = arr.map(m => Object.assign({}, m, {
          balFavor: (Number(m.igvFavor) || 0) - (Number(m.igvEmitido) || 0)
        }));
        _tribHistTs = Date.now();
      }
    } catch (e) {
      console.warn('[Tributario histórico]', e && e.message ? e.message : e);
    } finally {
      _tribHistBusy = false;
    }
    _tribPintarHistorico();
    _tribPintarDeltasYSparks();
    return _tribHist;
  }

  // Índice del mes que está seleccionado dentro de la ventana del histórico.
  function _tribHistIdx() {
    if (!_tribHist) return -1;
    return _tribHist.findIndex(m => m.mes === _tribState.mes && m.anio === _tribState.anio);
  }

  // ── Micro-sparkline (SVG a mano, sin librerías) ─────────────────────
  // Serie ÚNICA → sin leyenda: el título de la card ya nombra qué se grafica.
  // preserveAspectRatio="none" estira el viewBox al ancho real; el trazo se
  // mantiene en 2px con vector-effect y el punto destacado va como elemento
  // HTML (un <circle> se deformaría en óvalo bajo ese estiramiento).
  function _tribSpark(el, serie, color, idxDestacado) {
    if (!el) return;
    const vals = (serie || []).map(v => Number(v) || 0);
    if (vals.length < 2) { el.innerHTML = ''; return; }
    const n = vals.length;
    const max = Math.max.apply(null, vals);
    const min = Math.min.apply(null, vals.concat([0]));
    const span = (max - min) || 1;
    const px = i => (i / (n - 1)) * 100;
    const py = v => 26 - ((v - min) / span) * 23;
    const pts = vals.map((v, i) => px(i).toFixed(2) + ',' + py(v).toFixed(2));
    const linea = 'M' + pts.join(' L');
    const area  = linea + ' L100,28 L0,28 Z';
    const idx = (idxDestacado != null && idxDestacado >= 0 && idxDestacado < n) ? idxDestacado : (n - 1);
    el.innerHTML =
      '<svg viewBox="0 0 100 28" preserveAspectRatio="none" aria-hidden="true" focusable="false">' +
        '<path d="' + area + '" fill="' + color + '" opacity=".10"></path>' +
        '<path d="' + linea + '" fill="none" stroke="' + color + '" stroke-width="2" stroke-linejoin="round" ' +
              'stroke-linecap="round" opacity=".6" vector-effect="non-scaling-stroke"></path>' +
      '</svg>' +
      '<span class="trib-stat-dot" style="left:' + px(idx).toFixed(2) + '%;top:' + ((py(vals[idx]) / 28) * 100).toFixed(2) + '%"></span>';
  }

  // ── Delta vs el mes anterior ────────────────────────────────────────
  // `masEsMejor` dice si subir es bueno (IGV a favor sí, IGV en contra no):
  // el color del chip sigue esa semántica, NUNCA el signo a secas. El texto
  // lleva flecha + porcentaje, así el color nunca carga solo el significado.
  function _tribDelta(el, actual, previo, masEsMejor) {
    if (!el) return;
    el.classList.remove('mejor', 'peor');
    if (previo == null || !isFinite(previo)) { el.textContent = '—'; el.title = 'Sin mes anterior con el que comparar'; return; }
    const a = Number(actual) || 0, p = Number(previo) || 0;
    const dif = a - p;
    if (Math.abs(dif) < 0.005) { el.textContent = '= igual'; el.title = 'Igual que el mes anterior'; return; }
    const pct = p !== 0 ? (dif / Math.abs(p)) * 100 : null;
    el.textContent = (dif > 0 ? '▲ ' : '▼ ') + (pct != null ? Math.abs(pct).toFixed(0) + '%' : _tribFmtCorto(Math.abs(dif)));
    el.title = 'vs mes anterior · ' + (dif > 0 ? '+' : '−') + _tribFmtSoles(Math.abs(dif));
    el.classList.add((dif > 0) === !!masEsMejor ? 'mejor' : 'peor');
  }

  // Pinta deltas + sparklines de las 4 cards a partir del histórico cacheado.
  // Si el histórico aún no llegó, deja los guiones: nunca inventa una tendencia.
  function _tribPintarDeltasYSparks() {
    if (!_tribHist || !_tribHist.length) return;
    const i = _tribHistIdx();
    const prev = (i > 0) ? _tribHist[i - 1] : null;
    const d = _tribState.data || {};
    _tribDelta($('tribFavorDelta'),   d.igvFavor,     prev ? prev.igvFavor   : null, true);
    _tribDelta($('tribEmitidoDelta'), d.igvEmitido,   prev ? prev.igvEmitido : null, false);
    _tribDelta($('tribRentaDelta'),   d.rentaMensual, prev ? prev.renta      : null, false);
    _tribDelta($('tribVentasDelta'),  d.totalVentas,  prev ? prev.ventas     : null, true);
    _tribSpark($('tribFavorSpark'),   _tribHist.map(m => m.igvFavor),   '#34d399', i);
    _tribSpark($('tribEmitidoSpark'), _tribHist.map(m => m.igvEmitido), '#fb7185', i);
    _tribSpark($('tribRentaSpark'),   _tribHist.map(m => m.renta),      '#a78bfa', i);
    _tribSpark($('tribVentasSpark'),  _tribHist.map(m => m.ventas),     '#60a5fa', i);
  }

  function _tribRender(d, opts) {
    if (!d) return;
    const o = opts || {};
    const mesNom = _TRIB_MESES[(d.mes || 1) - 1];
    $('tribSub').textContent = mesNom + ' ' + d.anio + ' · día ' + d.diaActual + ' de ' + d.ultimoDia;

    // ── HERO: cuánto está a favor y cuánto en contra ──────────────────
    // El backend entrega balanceNetoIGV = emitido − favor ("lo que debes").
    // El panel habla al revés a propósito, porque la pregunta del dueño es
    // "¿cuánto está a MI favor?": aFavor = favor − emitido.
    const aFavor = (d.igvFavor || 0) - (d.igvEmitido || 0);
    const esFavor = aFavor >= 0;
    const hero = $('tribHero');
    if (hero) {
      hero.classList.toggle('es-favor', esFavor);
      hero.classList.toggle('es-contra', !esFavor);
    }
    const numEl = $('tribBalanceNeto');
    _tribCountUp(numEl, Math.abs(aFavor));
    if (numEl) { numEl.classList.remove('bump'); void numEl.offsetWidth; numEl.classList.add('bump'); }
    $('tribHeroEyebrow').textContent = 'Balance de IGV · ' + mesNom + ' ' + d.anio;
    $('tribHeroVeredicto').innerHTML = esFavor
      ? '<span>✨</span> A tu favor · crédito fiscal arrastrable'
      : '<span>⚠</span> En contra · esto le debes a SUNAT';
    // Desglose: los montos salen de _tribFmtSoles (solo dígitos y S/) → seguro.
    $('tribHeroDesglose').innerHTML =
      '<span>IGV a favor <b style="color:var(--trib-favor)">' + _tribFmtSoles(d.igvFavor) + '</b></span>' +
      '<span class="op">−</span>' +
      '<span>IGV en contra <b style="color:var(--trib-contra)">' + _tribFmtSoles(d.igvEmitido) + '</b></span>';

    // Pie del hero: vencimiento SUNAT (solo tiene sentido si hay algo que pagar).
    if (esFavor) {
      $('tribBalanceSub').innerHTML = 'Se arrastra como crédito fiscal al mes siguiente · nada que pagar por IGV';
    } else {
      // [pro] cuánto comprar en facturas para cubrir el 100% del IGV que debes: neto/0.18×1.18 (base+IGV).
      // Va appendeado al pie del hero, justo donde se ve "esto le debes a SUNAT". No invasivo.
      const _netoDeuda = (d.igvEmitido || 0) - (d.igvFavor || 0);
      const _compraTxt = _netoDeuda > 0.5
        ? ' · 🎯 para no pagarlo, comprá ≈ <strong>' + _tribFmtSoles(_netoDeuda / 0.18 * 1.18) + '</strong> en facturas'
        : '';
      // [fix] guarda contra fecha ausente/mala del server → antes mostraba
      // "Vence: Invalid Date · faltan undefined días".
      const fecha = new Date(d.fechaVencimiento);
      const fechaOk = d.fechaVencimiento != null && d.fechaVencimiento !== '' && !isNaN(fecha.getTime());
      const dias = Number.isFinite(d.diasParaVencer) ? d.diasParaVencer : null;
      if (fechaOk) {
        const fStr = fecha.toLocaleDateString('es-PE', { day: 'numeric', month: 'short', year: 'numeric' });
        $('tribBalanceSub').innerHTML = 'Vence: <strong>' + _escapeHtml(fStr) + '</strong>' + (dias != null ? ' · faltan ' + dias + ' días' : '') + _compraTxt;
      } else {
        $('tribBalanceSub').innerHTML = 'Vence según el cronograma SUNAT del mes siguiente' + _compraTxt;
      }
    }
    $('tribPeriodoBar').style.width = (d.pctMes || 0) + '%';

    // ── Las 4 stat-cards ──────────────────────────────────────────────
    _tribCountUp($('tribIGVFavor'),  d.igvFavor);
    _tribCountUp($('tribIGVPagar'),  d.igvEmitido);
    _tribCountUp($('tribRenta'),     d.rentaMensual);
    _tribCountUp($('tribVentas'),    d.totalVentas);
    $('tribIGVFavorSub').textContent = (d.guiasConIGV || 0) + ' de ' + (d.guiasMes || 0) + ' guías con IGV recuperable' +
                                      (d.guiasSinFoto > 0 ? ' · ' + d.guiasSinFoto + ' sin foto' : '');
    $('tribIGVPagarSub').textContent = (d.cpeEmitidos || 0) + ' de ' + (d.cpeTotal || 0) + ' CPE emitidos' +
                                      (d.cpeErrores > 0 ? ' · ⚠ ' + d.cpeErrores + ' NO llegaron a SUNAT' : '') +
                                      (d.cpePendientes > 0 ? ' · ' + d.cpePendientes + ' en camino' : '');
    // La tarjeta entera se marca cuando hay comprobantes que no llegaron. Un número perdido
    // dentro de un subtítulo gris no se ve: con 56 trabados, la pantalla se veía normal.
    try {
      const _cardIGV = $('tribIGVPagar') && $('tribIGVPagar').closest('.trib-stat');
      if (_cardIGV) _cardIGV.classList.toggle('trib-stat-alerta', (d.cpeErrores || 0) > 0);
    } catch(_) {}
    // Tasa derivada del propio dato (no hardcodeada): si el backend cambiara
    // el régimen, el subtítulo lo dice solo.
    const tasaRenta = (d.totalVentas > 0) ? (d.rentaMensual / d.totalVentas) * 100 : 1.5;
    $('tribRentaSub').textContent = 'Pago a cuenta MYPE · ' + tasaRenta.toFixed(2).replace(/\.?0+$/, '') + '% de las ventas';
    $('tribVentasSub').textContent = 'Base de la renta · ' + (d.pctMes || 0) + '% del mes transcurrido';

    // ── Franja de alerta accionable ───────────────────────────────────
    const alertas = (d.cpeErrores || 0) + (d.guiasIlegibles || 0) + (d.guiasSinFoto || 0);
    if (alertas > 0) {
      $('tribAlertCard').style.display = '';
      $('tribAlertCount').textContent = alertas;
      const partes = [];
      // Estimación del IGV que se está perdiendo (proporcional al promedio del mes)
      const igvPromedioPorGuia = (d.guiasConIGV > 0) ? (d.igvFavor / d.guiasConIGV) : 0;
      if (d.cpeErrores > 0)     partes.push(d.cpeErrores + ' comprobante(s) que NO llegaron a SUNAT · tócalo para verlos');
      if (d.guiasIlegibles > 0) partes.push(d.guiasIlegibles + ' ilegibles · recuperables ~' + _tribFmtSoles(d.guiasIlegibles * igvPromedioPorGuia));
      if (d.guiasSinFoto > 0)   partes.push(d.guiasSinFoto + ' sin comprobante · ~' + _tribFmtSoles(d.guiasSinFoto * igvPromedioPorGuia) + ' en juego');
      $('tribAlertSub').textContent = partes.join(' · ');
      // Si el problema son los CPE, tocar la franja abre la lista YA filtrada a los que no
      // llegaron. Antes llevaba siempre a las guías, así que un CPE trabado avisaba y te
      // dejaba en otra pantalla.
      $('tribAlertCard').onclick = (d.cpeErrores > 0)
        ? function () { tribAbrirIGVEmitido('TRABADO'); }
        : function () { tribAbrirIGVFavor('PENDIENTES'); };
    } else {
      $('tribAlertCard').style.display = 'none';
    }

    // ── Proyección de cierre (solo si el mes sigue abierto) ───────────
    const proy = _tribCalcProyeccion(d);
    const proyEl = $('tribProyeccion');
    if (proyEl) {
      if (!proy || d.pctMes >= 95) {
        proyEl.style.display = 'none';
      } else {
        const favorProy = (proy.igvFavorProy || 0) - (proy.igvEmitidoProy || 0);
        const cierraFavor = favorProy >= 0;
        proyEl.style.display = '';
        proyEl.className = 'trib-alert';
        proyEl.style.background = 'linear-gradient(135deg, rgba(129,140,248,.13), rgba(129,140,248,.03))';
        proyEl.style.borderColor = 'rgba(129,140,248,.3)';
        proyEl.style.cursor = 'default';
        proyEl.innerHTML =
          '<span class="trib-alert-ico">🔮</span>' +
          '<span class="trib-alert-txt">' +
            '<span class="trib-alert-lbl" style="color:#a5b4fc">Proyección de cierre</span>' +
            '<span class="trib-alert-sub">Al ritmo de hoy (' + (d.pctMes || 0) + '% del mes) cierras con ' +
              '<b style="color:' + (cierraFavor ? 'var(--trib-favor)' : 'var(--trib-contra)') + '">' + _tribFmtSoles(Math.abs(favorProy)) + '</b> ' +
              (cierraFavor ? 'a favor' : 'en contra') +
              ' · faltan ' + proy.diasRestantes + ' día' + (proy.diasRestantes === 1 ? '' : 's') +
            '</span>' +
          '</span>';
      }
    }

    // Sonido: solo cuando el usuario pidió el mes (no en refrescos silenciosos).
    if (o.sonar) _finBeep && _finBeep(esFavor ? 'kpi-up' : 'kpi-down');

    _tribPintarDeltasYSparks();
  }

  // ═══════════════════════════════════════════════════════════════════
  // SHEET GENÉRICO DE DRILL-DOWN
  // Un solo componente para los 4 overlays del módulo. En escritorio es una
  // card centrada; en móvil (CSS ≤640px) baja como bottom-sheet con
  // drag-handle, respeta env(safe-area-inset-bottom) y su scroll interno lleva
  // overscroll-behavior:contain para no arrastrar el body.
  // ═══════════════════════════════════════════════════════════════════
  const _tribSheetsAbiertos = [];
  let _tribBodyOverflowPrev = null;

  function _tribBloquearScroll(bloquear) {
    if (bloquear) {
      if (_tribBodyOverflowPrev === null) _tribBodyOverflowPrev = document.body.style.overflow || '';
      document.body.style.overflow = 'hidden';
    } else if (_tribSheetsAbiertos.length === 0 && !document.getElementById('tribLightbox')) {
      document.body.style.overflow = _tribBodyOverflowPrev || '';
      _tribBodyOverflowPrev = null;
    }
  }

  function _tribSheetEl(id, sel) {
    const ov = document.getElementById(id);
    return ov ? ov.querySelector(sel) : null;
  }

  function _tribSheetAbrir(id, o) {
    // Si ya estaba abierto (por ejemplo un reintento que reabre la lista),
    // se reemplaza sin animación de cierre para que no parpadee.
    const viejo = document.getElementById(id);
    if (viejo) { viejo.remove(); const k = _tribSheetsAbiertos.indexOf(id); if (k >= 0) _tribSheetsAbiertos.splice(k, 1); }

    const ov = document.createElement('div');
    ov.className = 'trib-ov';
    ov.id = id;
    ov.setAttribute('role', 'dialog');
    ov.setAttribute('aria-modal', 'true');
    ov.setAttribute('aria-label', o.titulo || 'Detalle');
    ov.innerHTML =
      '<div class="trib-sheet">' +
        '<div class="trib-sheet-grab" data-trib-grab="1"></div>' +
        '<div class="trib-sheet-head">' +
          '<div class="trib-sheet-top">' +
            '<span class="trib-sheet-ico">' + (o.icono || '📄') + '</span>' +
            '<div class="trib-sheet-tt">' +
              '<div class="trib-sheet-title">' + _escapeHtml(o.titulo || '') + '</div>' +
              '<div class="trib-sheet-sub" data-trib-sub="1">' + (o.sub || '') + '</div>' +
            '</div>' +
            (o.totalLbl
              ? '<div class="trib-sheet-tot">' +
                  '<div class="trib-sheet-tot-lbl">' + _escapeHtml(o.totalLbl) + '</div>' +
                  '<div class="trib-sheet-tot-val" data-trib-tot="1" style="color:' + (o.totalColor || '#f1f5f9') + '">' + (o.totalVal || '—') + '</div>' +
                '</div>'
              : '') +
            '<button type="button" class="trib-sheet-close" data-trib-cerrar="1" aria-label="Cerrar">✕</button>' +
          '</div>' +
          (o.tools ? '<div data-trib-tools="1">' + o.tools + '</div>' : '') +
        '</div>' +
        '<div class="trib-sheet-body" data-trib-body="1">' + (o.body || '') + '</div>' +
      '</div>';
    document.body.appendChild(ov);
    _tribSheetsAbiertos.push(id);
    _tribBloquearScroll(true);

    // Cerrar: click en el backdrop, en la ✕, o Escape.
    ov.addEventListener('click', (e) => {
      if (e.target === ov || (e.target.closest && e.target.closest('[data-trib-cerrar]'))) {
        _tribSheetCerrar(id);
        return;
      }
      if (typeof o.onClick === 'function') o.onClick(e);
    });
    if (_tribSheetsAbiertos.length === 1) document.addEventListener('keydown', _tribSheetEsc, true);

    // Arrastre hacia abajo para descartar (solo donde el handle es visible: móvil).
    const grab = ov.querySelector('[data-trib-grab]');
    const sheet = ov.querySelector('.trib-sheet');
    if (grab && sheet) {
      let y0 = null;
      grab.addEventListener('pointerdown', (e) => {
        y0 = e.clientY;
        sheet.style.transition = 'none';
        try { grab.setPointerCapture(e.pointerId); } catch (_) {}
      });
      grab.addEventListener('pointermove', (e) => {
        if (y0 == null) return;
        const dy = Math.max(0, e.clientY - y0);
        sheet.style.transform = 'translateY(' + dy + 'px)';
        sheet.style.opacity = String(Math.max(.4, 1 - dy / 420));
      });
      const soltar = (e) => {
        if (y0 == null) return;
        const dy = Math.max(0, e.clientY - y0);
        y0 = null;
        sheet.style.transition = '';
        if (dy > 100) { _tribSheetCerrar(id); return; }
        sheet.style.transform = '';
        sheet.style.opacity = '';
      };
      grab.addEventListener('pointerup', soltar);
      grab.addEventListener('pointercancel', soltar);
    }

    _finBeep && _finBeep('click');
    return ov;
  }

  function _tribSheetEsc(e) {
    if (e.key !== 'Escape') return;
    // El lightbox está por encima: si está abierto, Escape lo cierra a él.
    if (document.getElementById('tribLightbox')) return;
    const ultimo = _tribSheetsAbiertos[_tribSheetsAbiertos.length - 1];
    if (ultimo) { e.stopPropagation(); _tribSheetCerrar(ultimo); }
  }

  function _tribSheetCerrar(id) {
    const ov = document.getElementById(id);
    const k = _tribSheetsAbiertos.indexOf(id);
    if (k >= 0) _tribSheetsAbiertos.splice(k, 1);
    if (_tribSheetsAbiertos.length === 0) document.removeEventListener('keydown', _tribSheetEsc, true);
    if (!ov) { _tribBloquearScroll(false); return; }
    ov.classList.add('cerrando');
    setTimeout(() => { ov.remove(); _tribBloquearScroll(false); }, 230);
  }

  // ═══════════════════════════════════════════════════════════════════
  // OVERLAY 1 · IGV A FAVOR — guía por guía, con la foto del comprobante
  // ═══════════════════════════════════════════════════════════════════
  // Filtros: TODOS · CON_IGV · SIN_IGV · ILEGIBLE · SIN_FOTO · PENDIENTES
  // (PENDIENTES = todo lo que aún puede convertirse en dinero recuperado;
  //  es a donde salta la franja de alerta de la vista principal).
  const _tribIGVFiltro = { estado: 'TODOS' };
  let _tribIGVBusq = '';

  // [v2.42.12] Precarga del IGV a favor — se llena al iniciar sesión Admin
  // o al cambiar de mes. Permite que el overlay abra sin esperar el roundtrip.
  let _tribIGVFavorPrecargado = null;
  let _tribIGVFavorListaCache = [];

  async function tribAbrirIGVFavor(filtroInicial) {
    _tribIGVFiltro.estado = filtroInicial || 'TODOS';
    _tribIGVBusq = '';
    const d = _tribState.data || {};
    const mesNom = _TRIB_MESES[(_tribState.mes || 1) - 1] + ' ' + (_tribState.anio || '');
    _tribSheetAbrir('tribOvFavor', {
      icono: '💚',
      titulo: 'IGV a favor · guía por guía',
      sub: 'Comprobantes de proveedor de ' + _escapeHtml(mesNom) + ' — ordenados por el IGV que recuperas',
      totalLbl: 'Total a favor',
      totalVal: _tribFmtSoles(d.igvFavor || 0),
      totalColor: 'var(--trib-favor)',
      tools: '<div id="tribCubrirIGV"></div>' +
             '<div class="trib-buzon" id="tribBuzonBox">' +
               '<div class="trib-buzon-top"><b>📥 Buzón de facturas</b>' +
                 '<label class="trib-buzon-btn">＋ Subir factura<input type="file" accept="image/*" id="tribBuzonFile" style="display:none"></label></div>' +
               '<div class="trib-buzon-ayuda">Facturas de compra a tu nombre que NO tienen guía de ingreso (van directo a zona). El OCR lee el IGV a tu favor; si ya está en una guía, se marca duplicada.</div>' +
               '<div id="tribBuzonLista"></div>' +
             '</div>' +
             '<div class="trib-chips" data-trib-chips="1"></div>' +
             '<input class="trib-search" id="tribBuscarFavor" type="search" inputmode="search" autocomplete="off" placeholder="Buscar por guía, serie o número...">',
      body: '<div class="trib-vacio"><span class="trib-vacio-ico">⏳</span>Cargando las guías del mes...</div>',
      onClick: _tribFavorClick
    });
    const _bf = $('tribBuzonFile');
    if (_bf) _bf.addEventListener('change', () => _tribBuzonSubir(_bf));
    _tribBuzonRender();
    const inp = $('tribBuscarFavor');
    if (inp) inp.addEventListener('input', () => {
      _tribIGVBusq = inp.value || '';
      _tribRenderIGVFavorDetalle(_tribIGVFavorListaCache);
    });

    // Instantáneo con la precarga del mes; refresco silencioso por detrás.
    if (_tribIGVFavorPrecargado && _tribIGVFavorPrecargado.mes === _tribState.mes
        && _tribIGVFavorPrecargado.anio === _tribState.anio) {
      _tribIGVFavorListaCache = _tribIGVFavorPrecargado.lista;
      _tribRenderIGVFavorDetalle(_tribIGVFavorPrecargado.lista);
      _tribFetchIGVFavor(true);
      return;
    }
    await _tribFetchIGVFavor(false);
  }

  // [v2.42.12] Fetch separado para reusar entre precarga y apertura manual.
  // El backend tribIGVFavorMes devuelve {ok,data:{guias:[]}} y API.post
  // desempaqueta d.data → acá llega {guias:[]} directo.
  async function _tribFetchIGVFavor(silent) {
    try {
      const res = await API.post('tribIGVFavorMes', { mes: _tribState.mes, anio: _tribState.anio });
      const lista = (res?.guias) || (res?.data?.guias) || [];
      _tribIGVFavorListaCache = lista;
      _tribIGVFavorPrecargado = { mes: _tribState.mes, anio: _tribState.anio, lista };
      if (document.getElementById('tribOvFavor')) _tribRenderIGVFavorDetalle(lista);
    } catch(e) {
      const cont = _tribSheetEl('tribOvFavor', '[data-trib-body]');
      if (!silent && cont) {
        cont.innerHTML = '<div class="trib-vacio"><span class="trib-vacio-ico">⚠</span>' +
                         _escapeHtml(String(e && e.message ? e.message : e)) + '</div>';
      }
    }
  }

  // Estado de una guía, con una sola regla en un solo lugar.
  function _tribClasifGuia(g) {
    if (!g.tieneFoto) {
      // [fix] Una guía puede tener el IGV YA LEÍDO (ocr PROCESADO, serie, total) y aun así no tener la foto
      // guardada (se borró/perdió después del OCR). NO es "sin comprobante/no analizable": ya se analizó, su
      // IGV es real y cuenta; lo que falta es reponer la imagen para el respaldo ante SUNAT.
      const eo = String(g.ocrEstado || '').toUpperCase();
      if (eo === 'PROCESADO' && (g.igvRecuperable || 0) > 0) return 'FOTO_PERDIDA';
      return 'SIN_FOTO';
    }
    const e = String(g.ocrEstado || '').toUpperCase();
    if (e === 'SIN_IGV') return 'SIN_IGV';
    if (e === 'ILEGIBLE' || e === 'NO_COMPROBANTE') return 'ILEGIBLE';
    if (e === 'PROCESADO') return ((g.igvRecuperable || 0) > 0) ? 'CON_IGV' : 'SIN_IGV';
    return 'PROCESANDO';   // foto subida, el pipeline aún no la leyó
  }

  function _tribRenderIGVFavorDetalle(lista) {
    const cont = _tribSheetEl('tribOvFavor', '[data-trib-body]');
    const chipsCont = _tribSheetEl('tribOvFavor', '[data-trib-chips]');
    if (!cont) return;
    // [pro] banner "cuánto comprar para cubrir el IGV" — va en tools (bajo el total del encabezado), siempre visible.
    const cub = document.getElementById('tribCubrirIGV');
    if (cub) cub.innerHTML = _tribCubrirIGVHtml();
    lista = Array.isArray(lista) ? lista : [];

    if (!lista.length) {
      if (chipsCont) chipsCont.innerHTML = '';
      cont.innerHTML = '<div class="trib-vacio"><span class="trib-vacio-ico">📭</span>' +
                       'Sin guías de ingreso de proveedor en este mes</div>';
      return;
    }

    // Contadores por estado (sobre la lista COMPLETA: los chips no dependen
    // del filtro activo, si no el usuario perdería la referencia).
    const cont_ = { TODOS: lista.length, CON_IGV: 0, SIN_IGV: 0, ILEGIBLE: 0, SIN_FOTO: 0, PROCESANDO: 0, FOTO_PERDIDA: 0 };
    lista.forEach(g => { cont_[_tribClasifGuia(g)]++; });
    cont_.PENDIENTES = cont_.ILEGIBLE + cont_.SIN_FOTO + cont_.PROCESANDO;

    if (chipsCont) {
      const mk = (key, label, n, color) =>
        '<button type="button" class="trib-chip' + (_tribIGVFiltro.estado === key ? ' on' : '') + '" data-filtro="' + key + '">' +
          (color ? '<span class="pip" style="background:' + color + '"></span>' : '') +
          _escapeHtml(label) + ' <b>' + n + '</b>' +
        '</button>';
      chipsCont.innerHTML =
        mk('TODOS',      'Todas',        cont_.TODOS,      '') +
        mk('CON_IGV',    'Con IGV',      cont_.CON_IGV,    '#34d399') +
        mk('SIN_IGV',    'Sin IGV',      cont_.SIN_IGV,    '#64748b') +
        mk('ILEGIBLE',   'Ilegibles',    cont_.ILEGIBLE,   '#fb7185') +
        mk('SIN_FOTO',   'Sin foto',     cont_.SIN_FOTO,   '#fbbf24') +
        (cont_.FOTO_PERDIDA > 0 ? mk('FOTO_PERDIDA', 'Falta foto', cont_.FOTO_PERDIDA, '#f59e0b') : '') +
        (cont_.PENDIENTES > 0 ? mk('PENDIENTES', 'Recuperables', cont_.PENDIENTES, '#f59e0b') : '');
    }

    // Filtro + búsqueda
    const f = _tribIGVFiltro.estado;
    const q = _tribIGVBusq.trim().toLowerCase();
    const filtrada = lista.filter(g => {
      const cls = _tribClasifGuia(g);
      const pasaF = (f === 'TODOS') || (f === 'PENDIENTES' ? (cls === 'ILEGIBLE' || cls === 'SIN_FOTO' || cls === 'PROCESANDO') : cls === f);
      if (!pasaF) return false;
      if (!q) return true;
      const heno = [g.idGuia, g.serie, g.numero, g.razonSocial, g.rucEmisor].map(v => String(v || '').toLowerCase()).join(' ');
      return heno.indexOf(q) >= 0;
    });

    if (!filtrada.length) {
      cont.innerHTML = '<div class="trib-vacio"><span class="trib-vacio-ico">🔍</span>Ninguna guía con este filtro</div>';
      return;
    }

    // Orden: primero el dinero. Dentro del mismo IGV, la más reciente arriba.
    const ordenada = filtrada.slice().sort((a, b) => {
      const dif = (b.igvRecuperable || 0) - (a.igvRecuperable || 0);
      if (Math.abs(dif) > 0.004) return dif;
      return String(b.fecha || '').localeCompare(String(a.fecha || ''));
    });

    // La RPC wh.igv_favor_mes NO devuelve proveedor (ni razón social ni RUC):
    // por eso la lista es plana. Si algún día el payload los trae, el
    // agrupador de abajo los usa sin tocar nada más.
    const conProveedor = ordenada.some(g => String(g.razonSocial || '').trim());
    let html = '';
    if (conProveedor) {
      const grupos = new Map();
      ordenada.forEach(g => {
        const key = String(g.razonSocial || '').trim() || 'Sin proveedor identificado';
        if (!grupos.has(key)) grupos.set(key, []);
        grupos.get(key).push(g);
      });
      let i = 0;
      grupos.forEach((items, nombre) => {
        const totIGV = items.reduce((s, g) => s + (g.igvRecuperable || 0), 0);
        html += '<div class="trib-grupo-cap">🏢 ' + _escapeHtml(nombre) + ' · ' + _tribFmtSoles(totIGV) + '</div>';
        items.forEach(g => { html += _tribGuiaCard(g, i++); });
      });
    } else {
      ordenada.forEach((g, i) => { html += _tribGuiaCard(g, i); });
    }

    const totalFiltrado = ordenada.reduce((s, g) => s + (g.igvRecuperable || 0), 0);
    html += '<div class="trib-nota">Mostrando <b style="color:var(--trib-ink1)">' + ordenada.length + '</b> de ' + lista.length +
            ' guías · IGV en pantalla <b style="color:var(--trib-favor)">' + _tribFmtSoles(totalFiltrado) + '</b>. ' +
            'El OCR corre solo: al subir la foto de un comprobante el pipeline la lee y suma el IGV. ' +
            'El botón ↻ vuelve a encolarla.</div>';
    cont.innerHTML = html;
    cont.scrollTop = 0;
  }

  // [pro] "¿Cuánto debo comprar en facturas para cubrir el 100% del IGV?" — banner chico arriba del detalle.
  function _tribCubrirIGVHtml() {
    const dd = _tribState.data || {};
    const emit = +dd.igvEmitido || 0, favor = +dd.igvFavor || 0;
    if (emit <= 0) return '';   // sin ventas del mes: nada que cubrir todavía
    const neto = emit - favor;
    if (neto > 0.5) {
      const compra = neto / 0.18 * 1.18;   // compra con IGV incluido que genera `neto` de crédito
      return '<div class="trib-cubrir">' +
        '<span class="tc-ic">🎯</span>' +
        '<div class="tc-tx"><b>Para no pagar IGV: comprá ≈ ' + _tribFmtSoles(compra) + ' en facturas</b>' +
          '<i>Te faltan ' + _tribFmtSoles(neto) + ' de crédito fiscal. Cada S/ 100 comprado con factura suma S/ 18. ' +
          'Estimado, asumiendo que todo es gravado al 18 %.</i></div></div>';
    }
    return '<div class="trib-cubrir ok">' +
      '<span class="tc-ic">✅</span>' +
      '<div class="tc-tx"><b>IGV del mes cubierto</b>' +
        '<i>Tu crédito (' + _tribFmtSoles(favor) + ') ya iguala o supera el IGV de tus ventas (' + _tribFmtSoles(emit) + '). ' +
        'No necesitás comprar más para no pagar IGV.</i></div></div>';
  }

  // Card de una guía. `i` solo sirve para el retraso escalonado de entrada.
  function _tribGuiaCard(g, i) {
    const cls = _tribClasifGuia(g);
    const igv = g.igvRecuperable || 0;
    const retraso = Math.min(i, 16) * 25;
    const id = _escapeHtml(String(g.idGuia || ''));

    const foto = g.urlFoto
      ? '<button type="button" class="trib-gthumb" data-foto="' + id + '" title="Ver el comprobante en grande">' +
          '<img src="' + _escapeHtml(g.urlFoto) + '" alt="Comprobante de ' + id + '" loading="lazy" ' +
               'onerror="this.style.display=\'none\';this.parentElement.textContent=\'📄\'">' +
          '<span class="lupa">🔍</span>' +
        '</button>'
      : '<span class="trib-gnofoto" aria-hidden="true">📵</span>';

    const estados = {
      CON_IGV:    ['ok',    '🟢 leído' + (g.confidence ? ' ' + g.confidence + '%' : '')],
      SIN_IGV:    ['info',  '⊘ sin IGV'],
      ILEGIBLE:   ['error', '🔴 ilegible'],
      SIN_FOTO:   ['warn',  '⚪ sin foto'],
      FOTO_PERDIDA: ['warn', '🟢 leído · 📎 falta foto'],
      PROCESANDO: ['warn',  '🟡 en cola']
    };
    const est = estados[cls] || estados.PROCESANDO;

    const chip = igv > 0
      ? '<span class="trib-gchip a-favor">' + _tribFmtSoles(igv) + ' a favor</span>'
      : '<span class="trib-gchip neutro">sin IGV</span>';

    const fechaCmp = g.fechaComprobante || (g.fecha ? new Date(g.fecha).toLocaleDateString('es-PE') : '');
    const serieNum = String(g.serie || '') + (g.numero ? '-' + g.numero : '');
    const meta = [];
    if (fechaCmp)  meta.push('<span>' + _escapeHtml(String(fechaCmp)) + '</span>');
    if (serieNum)  meta.push('<code>' + _escapeHtml(serieNum) + '</code>');
    if (g.total > 0) meta.push('<span>Doc ' + _tribFmtSoles(g.total) + '</span>');

    const aviso = (cls === 'SIN_FOTO')
      ? '<div class="trib-gaviso">⚠ Sin comprobante — no analizable. Sube la foto en la guía y el IGV entra solo.</div>'
      : (cls === 'FOTO_PERDIDA'
          ? '<div class="trib-gaviso ok">✓ IGV ya leído del comprobante ' + _escapeHtml(serieNum || '') + '. Pero la foto ya no está guardada — vuélvela a subir en la guía para tener el respaldo ante SUNAT.</div>'
      : (cls === 'ILEGIBLE' ? '<div class="trib-gaviso">⚠ La IA no pudo leer la foto — reencólala con ↻ o vuelve a fotografiarla.</div>' : ''));

    return '<div class="trib-gcard' + (cls === 'SIN_FOTO' ? ' sin-foto' : '') + '" data-guia="' + id + '" style="animation-delay:' + retraso + 'ms">' +
      foto +
      '<div class="trib-gmain">' +
        '<div class="trib-gid">' + id + '</div>' +
        '<div class="trib-gmeta">' + meta.join('<span>·</span>') + '</div>' +
        aviso +
      '</div>' +
      '<div class="trib-gright">' + chip + '<span class="trib-gocr ' + est[0] + '">' + est[1] + '</span></div>' +
      (g.tieneFoto ? '<button type="button" class="trib-gbtn" data-reocr="' + id + '" title="Volver a leer este comprobante">↻</button>' : '') +
    '</div>';
  }

  // Delegación de clicks del overlay (nada de onclick con URLs dentro: el id
  // de la guía viaja en el data-attr y la URL se busca en la caché).
  // [885] BUZÓN de IGV a favor: subir/listar/borrar facturas de compra sin guía.
  const _TRIB_BUZON_EST = {
    VALIDA:        { ico: '✅', txt: 'IGV a favor', cls: 'ok' },
    DUPLICADA:     { ico: '♻️', txt: 'ya está en una guía', cls: 'dup' },
    NO_ES_NUESTRA: { ico: '⚠️', txt: 'no está a tu RUC', cls: 'mal' },
    SIN_IGV:       { ico: '—',  txt: 'sin IGV recuperable', cls: 'gris' },
    ILEGIBLE:      { ico: '👁', txt: 'ilegible', cls: 'gris' },
    NO_COMPROBANTE:{ ico: '🚫', txt: 'no es un comprobante', cls: 'gris' },
    PENDIENTE:     { ico: '⏳', txt: 'procesando…', cls: 'gris' }
  };
  // [fix BAJO-2] tras subir/borrar una factura del buzón, el IGV a favor del mes cambia → refrescar _tribState.data
  // para que el "Total a favor", el hero "en contra" y el banner "cuánto comprar" NO queden stale hasta reabrir.
  async function _tribRefrescarResumen() {
    try {
      const rr = await API.post('tribResumenMes', { mes: _tribState.mes, anio: _tribState.anio });
      const dd = (rr && (rr.data || rr)) || null;
      if (!dd) return;
      _tribState.data = dd;
      try { _tribRender(dd, {}); } catch (_) {}                  // hero + banner del hero
      const cub = document.getElementById('tribCubrirIGV');      // banner del overlay si está abierto
      if (cub) cub.innerHTML = _tribCubrirIGVHtml();
    } catch (_) {}
  }
  async function _tribBuzonRender() {
    const cont = $('tribBuzonLista'); if (!cont) return;
    let items = [];
    try { const r = await API.post('buzonListar', { mes: _tribState.mes, anio: _tribState.anio });
      items = ((r && (r.data || r)) || {}).items || []; } catch (_) {}
    if (!items.length) { cont.innerHTML = '<div class="trib-buzon-vacio">Todavía no subiste ninguna factura este mes.</div>'; return; }
    cont.innerHTML = items.map(b => {
      const e = _TRIB_BUZON_EST[String(b.estado)] || _TRIB_BUZON_EST.PENDIENTE;
      const doc = (b.serie ? b.serie + '-' + (b.numero || '') : (b.razonSocial || 'factura'));
      return '<div class="trib-buzon-item is-' + e.cls + '">' +
        '<span class="trib-buzon-ico">' + e.ico + '</span>' +
        '<div class="trib-buzon-info"><b>' + _escapeHtml(String(b.razonSocial || b.rucEmisor || 'Factura')) + '</b>' +
          '<i>' + _escapeHtml(String(doc)) + (b.fecha ? ' · ' + _escapeHtml(String(b.fecha)) : '') + ' · ' + e.txt + '</i></div>' +
        '<span class="trib-buzon-igv">' + (b.estado === 'VALIDA' ? _tribFmtSoles(b.igv) : '—') + '</span>' +
        '<button type="button" class="trib-buzon-x" onclick="MOS.tribBuzonBorrar(\'' + _esc(String(b.idBuzon)) + '\')" title="Quitar del buzón">✕</button>' +
      '</div>';
    }).join('');
    // [939] si hay facturas PENDIENTE (esperando que el cron las lea), refrescar solo en 20s para ver el drenado en vivo.
    if (items.some(b => String(b.estado) === 'PENDIENTE')) {
      clearTimeout(_tribBuzonTimer);
      _tribBuzonTimer = setTimeout(() => { if (document.getElementById('tribBuzonLista')) _tribBuzonRender(); }, 20000);
    }
  }
  let _tribBuzonTimer = null;
  async function _tribBuzonSubir(inp) {
    const f = inp && inp.files && inp.files[0]; if (!f) return;
    if (!/^image\//.test(f.type)) { toast('Subí una imagen de la factura', 'warning'); return; }
    const lista = $('tribBuzonLista'); if (lista) lista.insertAdjacentHTML('afterbegin', '<div class="trib-buzon-item is-gris" id="tribBuzonSubiendo"><span class="trib-buzon-ico">⏳</span><div class="trib-buzon-info"><b>Leyendo la factura…</b><i>' + _escapeHtml(f.name) + '</i></div></div>');
    try {
      const b64 = await new Promise((res, rej) => { const r = new FileReader(); r.onload = () => res(String(r.result).replace(/^data:[^;]+;base64,/, '')); r.onerror = rej; r.readAsDataURL(f); });
      const r = await API.post('buzonSubir', { jpgB64: b64, mime: f.type, mes: _tribState.mes, anio: _tribState.anio, usuario: S.session?.nombre || '' });
      if (!r || r.status !== 'success') throw new Error((r && r.error) || 'no se pudo');
      // [939] la factura SIEMPRE quedó guardada; si no hubo cupo de IA, va como PENDIENTE y el cron la lee sola.
      if (r.pendiente) {
        toast(r.mensaje || 'Factura guardada ✓ Se leerá sola apenas haya cupo de IA.', 'info', 6000);
        _tribBuzonRender(); _tribFetchIGVFavor(true);
        try { inp.value = ''; } catch (_) {}
        return;
      }
      const est = (r.data && r.data.estado) || '';
      const msg = est === 'VALIDA' ? '✅ Factura agregada · IGV a favor'
                : est === 'DUPLICADA' ? '♻️ Esa factura ya estaba en una guía — marcada duplicada'
                : est === 'NO_ES_NUESTRA' ? '⚠️ Esa factura no está a tu RUC — no suma IGV'
                : est === 'SIN_IGV' ? 'Sin IGV recuperable' : est === 'NO_COMPROBANTE' ? '🚫 No parece un comprobante' : 'Procesada';
      toast(msg, est === 'VALIDA' ? 'success' : est === 'DUPLICADA' || est === 'NO_ES_NUESTRA' ? 'warning' : 'info', 5000);
      _tribBuzonRender(); _tribFetchIGVFavor(true); _tribRefrescarResumen();   // refresca lista + total + banner
    } catch (e) {
      toast('No se pudo leer la factura: ' + (e.message || e), 'error', 6000);
      const sub = $('tribBuzonSubiendo'); if (sub) sub.remove();
    }
    try { inp.value = ''; } catch (_) {}
  }
  async function tribBuzonBorrar(id) {
    if (!await _modalConfirm('¿Quitar esta factura del buzón?', { warning: true, titulo: 'Quitar del buzón', okText: 'Quitar' })) return;
    try { const r = await API.post('buzonBorrar', { idBuzon: id }); if (!r || r.status !== 'success') throw new Error((r && r.error) || 'no se pudo');
      _tribBuzonRender(); _tribFetchIGVFavor(true); _tribRefrescarResumen();
    } catch (e) { toast('No se pudo: ' + (e.message || e), 'error'); }
  }

  function _tribFavorClick(e) {
    const t = e.target;
    const chip = t.closest && t.closest('[data-filtro]');
    if (chip) { _tribSetIGVFiltro(chip.getAttribute('data-filtro')); return; }
    const thumb = t.closest && t.closest('[data-foto]');
    if (thumb) {
      const g = _tribIGVFavorListaCache.find(x => String(x.idGuia) === thumb.getAttribute('data-foto'));
      if (g) tribAbrirFotoComprobante(g.urlFoto, g.idGuia, g.igvRecuperable);
      return;
    }
    const re = t.closest && t.closest('[data-reocr]');
    if (re) { re.classList.add('girando'); tribReprocesarOCR(re.getAttribute('data-reocr')); return; }
  }

  function _tribSetIGVFiltro(estado) {
    _tribIGVFiltro.estado = estado;
    _finBeep && _finBeep('click');
    _tribRenderIGVFavorDetalle(_tribIGVFavorListaCache);
  }

  // ═══════════════════════════════════════════════════════════════════
  // LIGHTBOX del comprobante — análisis visual (zoom rueda/pinch/doble tap)
  // ═══════════════════════════════════════════════════════════════════
  const _tribLB = { escala: 1, tx: 0, ty: 0, punteros: new Map(), dist0: 0, esc0: 1, ultimoTap: 0, arrastre: null };

  function tribAbrirFotoComprobante(url, idGuia, igv) {
    if (!url) return;
    _finBeep && _finBeep('click');
    const viejo = document.getElementById('tribLightbox');
    if (viejo) viejo.remove();

    _tribLB.escala = 1; _tribLB.tx = 0; _tribLB.ty = 0; _tribLB.punteros.clear();

    const lb = document.createElement('div');
    lb.id = 'tribLightbox';
    lb.className = 'trib-lb';
    lb.innerHTML =
      '<div class="trib-lb-stage" data-lb-stage="1">' +
        '<img class="trib-lb-img" id="tribLightboxImg" alt="Comprobante de ' + _escapeHtml(String(idGuia || '')) + '" ' +
             'src="' + _escapeHtml(url) + '" draggable="false">' +
      '</div>' +
      '<div class="trib-lb-cap">' +
        '<span>📄 ' + _escapeHtml(String(idGuia || 'Comprobante')) + '</span>' +
        ((igv || 0) > 0 ? '<span class="igv">· ' + _tribFmtSoles(igv) + ' a favor</span>' : '') +
      '</div>' +
      '<button type="button" class="trib-lb-x" data-lb-cerrar="1" aria-label="Cerrar">✕</button>' +
      '<div class="trib-lb-tools">' +
        '<button type="button" class="trib-lb-btn" data-lb-zoom="-1" aria-label="Alejar">−</button>' +
        '<span class="trib-lb-zoom" id="tribLightboxZoom">100%</span>' +
        '<button type="button" class="trib-lb-btn" data-lb-zoom="1" aria-label="Acercar">+</button>' +
        '<button type="button" class="trib-lb-btn" data-lb-reset="1" aria-label="Restablecer">⟲</button>' +
        '<a class="trib-lb-btn" href="' + _escapeHtml(url) + '" target="_blank" rel="noopener" ' +
           'style="display:inline-flex;align-items:center;justify-content:center;text-decoration:none" aria-label="Abrir original">⧉</a>' +
      '</div>';
    document.body.appendChild(lb);
    _tribBloquearScroll(true);

    const img = document.getElementById('tribLightboxImg');
    img.addEventListener('error', () => {
      const st = lb.querySelector('[data-lb-stage]');
      if (st) st.innerHTML = '<div class="trib-lb-err">⚠ No se pudo cargar la foto del comprobante</div>';
    });

    lb.addEventListener('click', (e) => {
      if (e.target.closest('[data-lb-cerrar]')) { _tribCerrarLightbox(); return; }
      const z = e.target.closest('[data-lb-zoom]');
      if (z) { _tribLBZoom(parseInt(z.getAttribute('data-lb-zoom'), 10) > 0 ? 1.35 : 1 / 1.35); return; }
      if (e.target.closest('[data-lb-reset]')) { _tribLB.escala = 1; _tribLB.tx = 0; _tribLB.ty = 0; _tribLBAplicar(); return; }
      // Click en el fondo (no en la imagen ni en la barra) cierra.
      if (e.target === lb || e.target.hasAttribute('data-lb-stage')) _tribCerrarLightbox();
    });

    // Rueda del mouse = zoom continuo.
    lb.addEventListener('wheel', (e) => { e.preventDefault(); _tribLBZoom(e.deltaY < 0 ? 1.14 : 1 / 1.14); }, { passive: false });
    // Doble click (escritorio) alterna 1x ↔ 2.4x.
    img.addEventListener('dblclick', (e) => { e.preventDefault(); _tribLBDobleTap(); });

    // Pinch (2 dedos) y arrastre (1 dedo con zoom).
    img.addEventListener('pointerdown', (e) => {
      _tribLB.punteros.set(e.pointerId, { x: e.clientX, y: e.clientY });
      try { img.setPointerCapture(e.pointerId); } catch (_) {}
      if (_tribLB.punteros.size === 2) {
        const p = [..._tribLB.punteros.values()];
        _tribLB.dist0 = Math.hypot(p[0].x - p[1].x, p[0].y - p[1].y) || 1;
        _tribLB.esc0 = _tribLB.escala;
        _tribLB.arrastre = null;
      } else if (_tribLB.escala > 1.01) {
        _tribLB.arrastre = { x: e.clientX, y: e.clientY, tx: _tribLB.tx, ty: _tribLB.ty };
        img.classList.add('arrastrando');
      }
    });
    img.addEventListener('pointermove', (e) => {
      if (!_tribLB.punteros.has(e.pointerId)) return;
      _tribLB.punteros.set(e.pointerId, { x: e.clientX, y: e.clientY });
      if (_tribLB.punteros.size === 2) {
        const p = [..._tribLB.punteros.values()];
        const d = Math.hypot(p[0].x - p[1].x, p[0].y - p[1].y) || 1;
        _tribLB.escala = Math.min(6, Math.max(1, _tribLB.esc0 * (d / _tribLB.dist0)));
        _tribLBAplicar(true);
      } else if (_tribLB.arrastre) {
        _tribLB.tx = _tribLB.arrastre.tx + (e.clientX - _tribLB.arrastre.x);
        _tribLB.ty = _tribLB.arrastre.ty + (e.clientY - _tribLB.arrastre.y);
        _tribLBAplicar(true);
      }
    });
    const soltar = (e) => {
      _tribLB.punteros.delete(e.pointerId);
      if (_tribLB.punteros.size < 2) { _tribLB.arrastre = null; img.classList.remove('arrastrando'); }
      // Doble tap táctil: dos toques sueltos en menos de 300ms.
      if (e.pointerType === 'touch') {
        const ahora = Date.now();
        if (ahora - _tribLB.ultimoTap < 300) { _tribLBDobleTap(); _tribLB.ultimoTap = 0; }
        else _tribLB.ultimoTap = ahora;
      }
    };
    img.addEventListener('pointerup', soltar);
    img.addEventListener('pointercancel', soltar);

    document.addEventListener('keydown', _tribLBTecla, true);
  }

  function _tribLBTecla(e) {
    if (!document.getElementById('tribLightbox')) return;
    if (e.key === 'Escape') { e.stopPropagation(); _tribCerrarLightbox(); }
    else if (e.key === '+' || e.key === '=') _tribLBZoom(1.35);
    else if (e.key === '-' || e.key === '_') _tribLBZoom(1 / 1.35);
    else if (e.key === '0') { _tribLB.escala = 1; _tribLB.tx = 0; _tribLB.ty = 0; _tribLBAplicar(); }
  }

  function _tribLBDobleTap() {
    if (_tribLB.escala > 1.05) { _tribLB.escala = 1; _tribLB.tx = 0; _tribLB.ty = 0; }
    else _tribLB.escala = 2.4;
    _tribLBAplicar();
  }

  function _tribLBZoom(factor) {
    _tribLB.escala = Math.min(6, Math.max(1, _tribLB.escala * factor));
    if (_tribLB.escala <= 1.01) { _tribLB.tx = 0; _tribLB.ty = 0; }
    _tribLBAplicar();
  }

  function _tribLBAplicar(sinTransicion) {
    const img = document.getElementById('tribLightboxImg');
    if (!img) return;
    img.classList.toggle('arrastrando', !!sinTransicion);
    img.style.transform = 'translate(' + _tribLB.tx.toFixed(1) + 'px,' + _tribLB.ty.toFixed(1) + 'px) scale(' + _tribLB.escala.toFixed(3) + ')';
    img.style.cursor = _tribLB.escala > 1.01 ? 'grab' : 'zoom-in';
    const z = document.getElementById('tribLightboxZoom');
    if (z) z.textContent = Math.round(_tribLB.escala * 100) + '%';
  }

  function _tribCerrarLightbox() {
    const lb = document.getElementById('tribLightbox');
    document.removeEventListener('keydown', _tribLBTecla, true);
    if (lb) lb.remove();
    _tribBloquearScroll(false);
  }

  // ═══════════════════════════════════════════════════════════════════
  // OVERLAY 2 · IGV EN CONTRA — los CPE que emitiste (boletas y facturas)
  // ═══════════════════════════════════════════════════════════════════
  let _tribCPECache = [];
  let _tribCPEViaSupa = false;
  const _tribCPEFiltro = { estado: 'TODOS', tipo: 'TODOS', zona: 'TODAS' };
  let _tribCPEBusq = '';

  async function tribAbrirIGVEmitido(filtroInicial) {
    _tribCPEFiltro.estado = filtroInicial || 'TODOS';
    _tribCPEBusq = '';
    const d = _tribState.data || {};
    const mesNom = _TRIB_MESES[(_tribState.mes || 1) - 1] + ' ' + (_tribState.anio || '');
    _tribSheetAbrir('tribOvEmitido', {
      icono: '🧾',
      titulo: 'IGV en contra · comprobante por comprobante',
      sub: 'Boletas y facturas emitidas en ' + _escapeHtml(mesNom) + ' — con su estado real en SUNAT',
      totalLbl: 'Total en contra',
      totalVal: _tribFmtSoles(d.igvEmitido || 0),
      totalColor: 'var(--trib-contra)',
      tools: '<div class="trib-chips" data-trib-chips="1"></div>' +
             '<input class="trib-search" id="tribBuscarCPE" type="search" inputmode="search" autocomplete="off" placeholder="Buscar por correlativo o cliente...">',
      body: '<div class="trib-vacio"><span class="trib-vacio-ico">⏳</span>Cargando los comprobantes del mes...</div>',
      onClick: _tribCPEClick
    });
    const inp = $('tribBuscarCPE');
    if (inp) inp.addEventListener('input', () => { _tribCPEBusq = inp.value || ''; _tribRenderCPEDetalle(); });
    await _tribFetchCPE();
  }

  // Fetch de los CPE del mes. Sin cambios de ruta: PRIMERO Supabase
  // (me.cpe_trazabilidad, estado fiscal completo y cero-GAS); si no hay
  // token/red, cae al endpoint tribIGVEmitidoMes.
  async function _tribFetchCPE() {
    const cont = _tribSheetEl('tribOvEmitido', '[data-trib-body]');
    try {
      const _mm = String(_tribState.mes).padStart(2, '0');
      const _desde = `${_tribState.anio}-${_mm}-01`;
      const _ult = new Date(_tribState.anio, _tribState.mes, 0).getDate();
      const _hasta = `${_tribState.anio}-${_mm}-${String(_ult).padStart(2, '0')}`;
      let lista = null;
      _tribCPEViaSupa = false;
      try {
        const sup = await API.cpeTrazabilidad(_desde, _hasta);
        if (sup && sup.ok && Array.isArray(sup.cpe)) { lista = sup.cpe; _tribCPEViaSupa = true; }
      } catch (_) {}
      if (lista === null) {
        const res = await API.post('tribIGVEmitidoMes', { mes: _tribState.mes, anio: _tribState.anio });
        lista = (res?.cpe) || (res?.data?.cpe) || [];
      }
      _tribCPECache = lista;
      _tribRenderCPEDetalle();
    } catch(e) {
      if (cont) cont.innerHTML = '<div class="trib-vacio"><span class="trib-vacio-ico">⚠</span>' +
                                 _escapeHtml(String(e && e.message ? e.message : e)) + '</div>';
    }
  }

  // Estado fiscal de un CPE, con una sola regla en un solo lugar.
  function _tribClasifCPE(c) {
    const e = String(c.nfEstado || '').toUpperCase();
    // ANULADO va con las bajas: la venta se anuló, no hay nada que reclamar. Sin esto caía en
    // TRABADO por no tener hash y aparecía como "no llegó a SUNAT" — asustando por una venta
    // que ya no existe, y sumando su IGV en la lista aunque el encabezado no lo cuenta.
    if (e.indexOf('BAJA') === 0 || e.indexOf('ANULADO') === 0) return 'BAJA';
    if (e === 'RECHAZADO' || e === 'RECHAZADO_SUNAT' || e === 'ERROR') return 'RECHAZADO';
    if (c.aceptadoSunat) return 'ACEPTADO';
    // TRABADO: no llegó a NubeFact y ya se le pasó su ventana. Antes caía en "pendiente" y
    // se perdía entre los que están en camino — que es exactamente lo que dejó 56 comprobantes
    // fuera de SUNAT sin que nadie lo viera. Una factura se acepta en segundos; una boleta
    // viaja en el resumen diario, por eso la ventana es distinta.
    if (!c.aceptadoNubefact) {
      const ms = c.fecha ? (Date.now() - new Date(c.fecha).getTime()) : 0;
      const limite = (String(c.tipo || '').toUpperCase() === 'FACTURA') ? 20 * 60000 : 25 * 3600000;
      if (ms > limite) return 'TRABADO';
    }
    if (c.aceptadoNubefact || e === 'PENDIENTE' || e === 'EMITIDO') return 'PENDIENTE';
    return 'SIN_EMITIR';
  }

  // IGV incluido en el total del comprobante. me.cpe_trazabilidad NO devuelve
  // el IGV desagregado (solo `total`), así que se deriva con la misma fórmula
  // que ya usa tribExportarExcel: total × 18 / 118. Por eso el chip dice "≈".
  function _tribIGVdeCPE(c) {
    if (c.igv != null && isFinite(parseFloat(c.igv))) return _money(parseFloat(c.igv));
    return _money((parseFloat(c.total) || 0) * 0.18 / 1.18);
  }

  /* ══════════════════════════════════════════════════════════════════════════
     LOS SELLOS · el ciclo de un comprobante, etapa por etapa.
     Un CPE pasa por NubeFact (pre-valida y firma) → SUNAT (acepta o rechaza) → y, si la
     venta se anula, BAJA (comunicación de baja a SUNAT). El semáforo de antes mezclaba
     estado y momento en una sola luz; los sellos muestran hasta dónde llegó, y qué pasó
     en cada puerta. Lleno = pasó · contorno = espera · rojo = rechazó · tachado = baja.
     ══════════════════════════════════════════════════════════════════════════ */
  function _tribSellos(c, cls) {
    const desc = String(c.sunatDesc || '');
    const nuncaLlego = /NUNCA_EMITIDO|nunca llego|nunca llegó/i.test(String(c.sunatCode || '') + ' ' + desc);
    const rechNF = /^RECHAZO NubeFact/i.test(desc);
    const enNF = !!c.aceptadoNubefact;
    const S = (txt, estado, tip) => '<span class="trib-sello ' + estado + '" title="' + _escapeHtml(tip || '') + '">' + txt + '</span>';
    const flecha = '<i class="trib-sello-fl"></i>';
    let nf, su, ba = '';
    if (nuncaLlego || cls === 'TRABADO' || rechNF) {
      nf = S('NubeFact ✕', 'rechazo', nuncaLlego ? 'Nunca llegó a NubeFact' : (rechNF ? desc.slice(0, 160) : 'No llegó a NubeFact pasada su ventana'));
      su = S('SUNAT', 'apagado', 'No aplica: no llegó a NubeFact');
      if (cls === 'BAJA') ba = flecha + S('anulada', 'baja', 'La venta se anuló antes de emitirse: el número queda sin uso');
    } else if (cls === 'RECHAZADO') {
      nf = S('NubeFact ✓', 'ok', 'Aceptado por NubeFact');
      su = S('SUNAT ✕', 'rechazo', desc.slice(0, 160) || 'Rechazado por SUNAT');
    } else if (cls === 'ACEPTADO') {
      nf = S('NubeFact ✓', 'ok', 'Aceptado por NubeFact');
      su = S('SUNAT ✓', 'ok', 'Aceptado por SUNAT' + (c.sunatCode ? ' · código ' + c.sunatCode : ''));
    } else if (cls === 'BAJA') {
      nf = S('NubeFact ✓', 'ok', 'Se emitió y NubeFact la aceptó');
      su = S('SUNAT ✓', 'ok', 'SUNAT la aceptó');
      ba = flecha + S('baja ⊘', 'baja', 'La venta se anuló y se comunicó la baja a SUNAT');
    } else if (cls === 'PENDIENTE' && enNF) {
      nf = S('NubeFact ✓', 'ok', 'Aceptado por NubeFact');
      su = S('SUNAT ⏳', 'espera', String(c.tipo || '').toUpperCase() === 'BOLETA' ? 'Viaja en el resumen diario; SUNAT responde dentro del día' : 'Esperando la respuesta de SUNAT');
    } else if (cls === 'PENDIENTE') {
      nf = S('NubeFact ⏳', 'espera', 'Enviándose a NubeFact');
      su = S('SUNAT', 'apagado', 'Todavía no');
    } else {
      nf = S('NubeFact', 'apagado', 'Sin emitir');
      su = S('SUNAT', 'apagado', 'Sin emitir');
    }
    return '<span class="trib-sellos">' + nf + flecha + su + ba + '</span>';
  }

  /* ── el historial del comprobante: quién hizo qué, cuándo y por qué. Viene de la venta
        (historial_cambios): cobrar, anular, cambiar forma de pago, dar crédito. Plegado por
        defecto; un toque lo abre. Si no pasó nada después de emitirse, no se muestra. ── */
  function _tribHistorialHTML(c) {
    const h = Array.isArray(c.historial) ? c.historial : [];
    if (!h.length) return '';
    const nom = a => ({ cobrar_venta: '💵 cobró', anular_venta_interna: '⊘ anuló', anular_venta: '⊘ anuló',
                        editar_forma_pago: '✎ cambió la forma de pago', dar_credito: '📋 dio crédito',
                        cobrar_credito: '💵 cobró el crédito', asignar_credito: '👤 asignó el crédito',
                        convertir_cpe: '🧾 convirtió a comprobante' }[a] || ('· ' + String(a || '').replace(/_/g, ' ')));
    const filas = h.map(x => {
      const d = x.ts ? new Date(x.ts) : null;
      const cuando = d && !isNaN(d.getTime()) ? d.toLocaleString('es-PE', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' }) : '';
      return '<div class="trib-hist-f"><span class="trib-hist-t">' + _escapeHtml(cuando) + '</span>' +
        '<span class="trib-hist-q">' + _escapeHtml(String(x.usuario || '—')) + '</span>' +
        '<span class="trib-hist-a">' + nom(x.accion) +
          (x.de && x.a ? ' <code>' + _escapeHtml(String(x.de)) + ' → ' + _escapeHtml(String(x.a)) + '</code>' : '') +
          (x.autorizadoPor ? ' <i>autorizó ' + _escapeHtml(String(x.autorizadoPor)) + '</i>' : '') +
          (x.motivo ? '<em>“' + _escapeHtml(String(x.motivo)) + '”</em>' : '') + '</span></div>';
    }).join('');
    return '<details class="trib-hist"><summary>🕘 historial · ' + h.length + ' movimiento' + (h.length === 1 ? '' : 's') + '</summary>' + filas + '</details>';
  }

  function _tribRenderCPEDetalle() {
    const cont = _tribSheetEl('tribOvEmitido', '[data-trib-body]');
    const chipsCont = _tribSheetEl('tribOvEmitido', '[data-trib-chips]');
    if (!cont) return;
    const lista = Array.isArray(_tribCPECache) ? _tribCPECache : [];

    if (!lista.length) {
      if (chipsCont) chipsCont.innerHTML = '';
      cont.innerHTML = '<div class="trib-vacio"><span class="trib-vacio-ico">📭</span>Sin CPE emitidos este mes</div>';
      return;
    }

    const cnt = { TODOS: lista.length, ACEPTADO: 0, PENDIENTE: 0, RECHAZADO: 0, TRABADO: 0, SIN_EMITIR: 0, BAJA: 0 };
    lista.forEach(c => { cnt[_tribClasifCPE(c)]++; });

    if (chipsCont) {
      const mk = (key, label, n, color) => (n > 0 || key === 'TODOS')
        ? '<button type="button" class="trib-chip' + (_tribCPEFiltro.estado === key ? ' on' : '') + '" data-cpefiltro="' + key + '">' +
            (color ? '<span class="pip" style="background:' + color + '"></span>' : '') +
            _escapeHtml(label) + ' <b>' + n + '</b></button>'
        : '';
      chipsCont.innerHTML =
        mk('TODOS',      'Todos',            cnt.TODOS,      '') +
        mk('TRABADO',    '⚠ No llegó a SUNAT', cnt.TRABADO,  '#fb7185') +
        mk('ACEPTADO',   'Aceptados SUNAT',  cnt.ACEPTADO,   '#34d399') +
        mk('PENDIENTE',  'Pendientes',       cnt.PENDIENTE,  '#fbbf24') +
        mk('RECHAZADO',  'Rechazados',       cnt.RECHAZADO,  '#fb7185') +
        mk('SIN_EMITIR', 'Sin emitir',       cnt.SIN_EMITIR, '#64748b') +
        mk('BAJA',       'Dados de baja',    cnt.BAJA,       '#64748b');

      // Segunda fila: qué documento y de qué local. Las zonas salen de los propios datos —
      // si mañana VIP empieza a emitir, su chip aparece solo, sin tocar código.
      const nFac = lista.filter(c => String(c.tipo || '').toUpperCase() === 'FACTURA').length;
      const nBol = lista.length - nFac;
      const zonas = [...new Set(lista.map(c => String(c.zona || '').trim()).filter(Boolean))].sort();
      const zonaLbl = (z) => {
        const m = /^ZONA-?0*(\d+)$/i.exec(z);
        if (m) return 'Zona ' + m[1];
        return z.replace(/[_-]/g, ' ').replace(/\w/g, ch => ch.toUpperCase());
      };
      const mkT = (key, label, n) => n > 0 || key === 'TODOS'
        ? '<button type="button" class="trib-chip' + (_tribCPEFiltro.tipo === key ? ' on' : '') + '" data-cpetipo="' + key + '">' +
          _escapeHtml(label) + ' <b>' + n + '</b></button>' : '';
      const mkZ = (key, label, n) => '<button type="button" class="trib-chip' + (_tribCPEFiltro.zona === key ? ' on' : '') +
          '" data-cpezona="' + _escapeHtml(key) + '">' + _escapeHtml(label) + ' <b>' + n + '</b></button>';

      chipsCont.innerHTML +=
        '<span class="trib-chip-sep"></span>' +
        mkT('TODOS', 'Todo doc.', lista.length) +
        mkT('FACTURA', '📋 Facturas', nFac) +
        mkT('BOLETA', '🧾 Boletas', nBol) +
        (zonas.length > 1
          ? '<span class="trib-chip-sep"></span>' +
            mkZ('TODAS', 'Toda zona', lista.length) +
            zonas.map(z => mkZ(z, zonaLbl(z), lista.filter(c => String(c.zona || '').trim() === z).length)).join('')
          : '');
    }

    const f = _tribCPEFiltro.estado;
    const q = _tribCPEBusq.trim().toLowerCase();
    const filtrada = lista.filter(c => {
      if (f !== 'TODOS' && _tribClasifCPE(c) !== f) return false;
      if (_tribCPEFiltro.tipo !== 'TODOS' && String(c.tipo || '').toUpperCase() !== _tribCPEFiltro.tipo) return false;
      if (_tribCPEFiltro.zona !== 'TODAS' && String(c.zona || '').trim() !== _tribCPEFiltro.zona) return false;
      if (!q) return true;
      return [c.correlativo, c.cliente, c.clienteDoc, c.tipo].map(v => String(v || '').toLowerCase()).join(' ').indexOf(q) >= 0;
    });

    if (!filtrada.length) {
      cont.innerHTML = '<div class="trib-vacio"><span class="trib-vacio-ico">🔍</span>Ningún comprobante con este filtro</div>';
      return;
    }

    const estados = {
      ACEPTADO:   ['ok',    '🟢 aceptado SUNAT'],
      PENDIENTE:  ['warn',  '🟡 en NubeFact · pendiente SUNAT'],
      RECHAZADO:  ['error', '🔴 rechazado SUNAT'],
      TRABADO:    ['error', '⚠ no llegó a SUNAT'],
      SIN_EMITIR: ['info',  '⚪ sin emitir'],
      BAJA:       ['info',  '⊘ dado de baja']
    };

    let html = _tribCPEViaSupa
      ? '<div class="trib-nota" style="margin:0 0 6px">⚡ Estado fiscal trazado en directo desde Supabase (me.cpe_trazabilidad)</div>'
      : '';
    // La leyenda: qué significa cada sello. Un comprobante pasa por NubeFact → SUNAT → (baja).
    html += '<div class="trib-leyenda">' +
      '<span class="trib-leyenda-t">El ciclo</span>' +
      '<span class="trib-sello ok">NubeFact ✓</span><i class="trib-sello-fl"></i><span class="trib-sello ok">SUNAT ✓</span>' +
      '<span class="trib-leyenda-s">emitido y aceptado</span>' +
      '<span class="trib-leyenda-sep"></span>' +
      '<span class="trib-sello espera">SUNAT ⏳</span><span class="trib-leyenda-s">en camino (boletas: resumen diario)</span>' +
      '<span class="trib-leyenda-sep"></span>' +
      '<span class="trib-sello rechazo">✕</span><span class="trib-leyenda-s">rechazado en esa puerta</span>' +
      '<span class="trib-leyenda-sep"></span>' +
      '<span class="trib-sello baja">baja ⊘</span><span class="trib-leyenda-s">venta anulada, baja comunicada</span>' +
      '</div>';
    let totIGV = 0;

    // ── agrupado por DÍA. La fecha va en la cabecera del grupo, el card solo lleva la hora:
    //    con 450 comprobantes al mes repetir "18-ago." en cada uno era ruido, y buscar "qué
    //    pasó el viernes" obligaba a leer fila por fila.
    const _hoy = new Date(); _hoy.setHours(0, 0, 0, 0);
    const _diaKey = (d) => d ? (d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0')) : '';
    const _diaTitulo = (d) => {
      const dd = new Date(d); dd.setHours(0, 0, 0, 0);
      const diff = Math.round((_hoy - dd) / 86400000);
      const largo = d.toLocaleDateString('es-PE', { weekday: 'long', day: 'numeric', month: 'long' });
      const cap = largo.charAt(0).toUpperCase() + largo.slice(1);
      return diff === 0 ? 'Hoy · ' + cap : diff === 1 ? 'Ayer · ' + cap : cap;
    };
    let _grupoActual = null, _gN = 0, _gIGV = 0, _gDocs = 0;
    const _abrirGrupo = (fecha) => {
      _grupoActual = _diaKey(fecha); _gN = 0; _gIGV = 0; _gDocs = 0;
      const id = 'tribDia_' + _grupoActual;
      html += '<div class="trib-dia" id="' + id + '">' +
                '<div class="trib-dia-h"><span class="trib-dia-t">' + _escapeHtml(_diaTitulo(fecha)) + '</span>' +
                '<span class="trib-dia-s" data-diaresumen="' + id + '"></span></div>';
    };
    const _cerrarGrupo = () => {
      if (_grupoActual == null) return;
      html += '</div>';
      // el resumen del día se rellena al final, cuando ya se contó todo el grupo
      html = html.replace('data-diaresumen="tribDia_' + _grupoActual + '"></span>',
        'data-diaresumen="tribDia_' + _grupoActual + '">' + _gDocs + ' doc' + (_gDocs === 1 ? '' : 's') +
        ' · <b>' + _tribFmtSoles(_gIGV) + '</b> en contra</span>');
      _grupoActual = null;
    };

    filtrada.forEach((c, i) => {
      const cls = _tribClasifCPE(c);
      let est = estados[cls] || estados.SIN_EMITIR;
      // Un comprobante que NubeFact rechazó no es lo mismo que uno que todavía no se mandó:
      // el primero necesita que alguien lo mire, el segundo se resuelve solo. Se distinguen.
      if (cls !== 'ACEPTADO' && /^RECHAZO NubeFact/i.test(String(c.sunatDesc || '')))
        est = ['error', '⛔ NubeFact lo rechazó'];
      else if (cls !== 'ACEPTADO' && /^RECHAZO SUNAT/i.test(String(c.sunatDesc || '')))
        est = ['error', '🔴 SUNAT lo rechazó'];
      else if (cls !== 'ACEPTADO' && /^FUERA DE PLAZO/i.test(String(c.sunatDesc || '')))
        est = ['error', '⏳ fuera de plazo'];
      const esBaja = (cls === 'BAJA');
      const igv = _tribIGVdeCPE(c);
      // una baja no suma: la venta ya no existe. Mostrarla como "en contra" mentía en el
      // parcial de pantalla mientras el encabezado (backend) sí la excluía.
      if (!esBaja) totIGV = _money(totIGV + igv);
      const esFactura = String(c.tipo || '').toUpperCase() === 'FACTURA';
      const fecha = c.fecha ? new Date(c.fecha) : null;
      const fOk = fecha && !isNaN(fecha.getTime());
      if (fOk && _diaKey(fecha) !== _grupoActual) { _cerrarGrupo(); _abrirGrupo(fecha); }
      else if (!fOk && _grupoActual !== '') { _cerrarGrupo(); _grupoActual = ''; html += '<div class="trib-dia"><div class="trib-dia-h"><span class="trib-dia-t">Sin fecha</span></div>'; }
      _gDocs++; if (!esBaja) _gIGV = _money(_gIGV + igv);
      const hora = fOk ? fecha.toLocaleTimeString('es-PE', { hour: '2-digit', minute: '2-digit' }) : '';

      // El motivo se muestra SIEMPRE que exista y el comprobante no esté aceptado — antes solo
      // salía en los RECHAZADO por SUNAT, así que un rechazo de NubeFact (que ni siquiera llega
      // a SUNAT) se veía como un "⚪ sin emitir" mudo: no había forma de saber qué pasó.
      const _desc = String(c.sunatDesc || '').trim();
      const _esFalloNF = /^RECHAZO NubeFact|^FUERA DE PLAZO/i.test(_desc);
      let detSunat = '';
      if (esBaja) {
        // Una baja tiene DOS momentos y el card los mezclaba: guardaba "ha sido aceptada" (la
        // respuesta de SUNAT al EMITIRLA) y encima le ponía ⚠, al lado de "dado de baja". Se
        // leía como "¿aceptada para anularla?". Acá se cuenta la historia entera, en gris.
        const _nuncaEmitida = /NUNCA_EMITIDO|nunca llego/i.test(String(c.sunatCode || '') + ' ' + _desc);
        detSunat = _nuncaEmitida
          ? '<div class="trib-gaviso" style="color:#fbbf24">⚠ Anulada antes de emitirse: nunca llegó a NubeFact ni a SUNAT. El número queda sin uso.</div>'
          : '<div class="trib-gaviso" style="color:var(--trib-ink3);font-weight:600">🧾 Se emitió y SUNAT la aceptó · después la venta se anuló y se comunicó la baja a SUNAT ✓</div>';
      } else if (_desc && cls !== 'ACEPTADO') {
        detSunat = '<div class="trib-gaviso" style="color:' + (_esFalloNF ? '#fbbf24' : '#fb7185') + '">⚠ '
          + _escapeHtml(_desc.slice(0, 180)) + '</div>';
      }

      const cli = String(c.cliente || '').trim();
      const nombreCli = cli && !/^varios$/i.test(cli) ? cli : (esFactura ? 'Sin razón social' : 'Cliente varios');
      const docCli = c.clienteDoc && String(c.clienteDoc) !== '66666' ? String(c.clienteDoc) : '';

      html +=
        '<div class="trib-gcard cpe' + (esBaja ? ' baja' : '') + '" data-cpe="' + _escapeHtml(String(c.idVenta || c.refLocal || i)) + '" style="animation-delay:' + (Math.min(i, 16) * 25) + 'ms">' +
          '<span class="trib-gtipo ' + (esFactura ? 'fac' : 'bol') + '" title="' + (esFactura ? 'Factura' : 'Boleta') + '">' + (esFactura ? 'F' : 'B') + '</span>' +
          '<div class="trib-gmain">' +
            // 1 · el cliente, primero: es lo que se busca cuando alguien pregunta "mi factura"
            '<div class="trib-gcli">' + _escapeHtml(nombreCli) +
              (docCli ? ' <code>' + _escapeHtml(docCli) + '</code>' : '') + '</div>' +
            // 2 · el documento: correlativo · hora
            '<div class="trib-gmeta"><code class="trib-gcorr">' + _escapeHtml(String(c.correlativo || '(sin correlativo)')) + '</code>' +
              (hora ? '<span>·</span><span>' + _escapeHtml(hora) + '</span>' : '') +
              '<span>·</span><span>Total <b>' + _tribFmtSoles(c.total) + '</b></span>' +
              // quién lo emitió: el vendedor que hizo la venta (viene de la venta misma)
              (c.vendedor ? '<span>·</span><span title="Emitido por">👤 ' + _escapeHtml(String(c.vendedor).split(' ').slice(0, 2).join(' ')) + '</span>' : '') +
              (c.formaPago && !/ANULADO/i.test(String(c.formaPago)) ? '<span>·</span><span>' + _escapeHtml(String(c.formaPago).replace(/\s*\(.*$/, '')) + '</span>' : '') +
              '</div>' +
            detSunat +
            _tribHistorialHTML(c) +
          '</div>' +
          '<div class="trib-gright">' +
            (esBaja
              ? '<span class="trib-gchip neutro" title="La venta se anuló y el comprobante fue dado de baja: no cuenta en el IGV">anulada · no cuenta</span>'
              : '<span class="trib-gchip en-contra" title="IGV de la operación">' + _tribFmtSoles(igv) + ' en contra</span>') +
            _tribSellos(c, cls) +
          '</div>' +
          '<div class="trib-gacc">' +
          // Tres acciones: abrir el PDF · voucher-imagen · compartir PDF. El voucher se arma con
          // los datos de la venta (líneas, QR), así que existe aunque el PDF de NubeFact no esté
          // todavía; los dos del PDF sí dependen del enlace.
          (c.enlacePdf ? '<button type="button" class="trib-gbtn" data-pdf="' + _escapeHtml(String(c.enlacePdf)) + '" title="Abrir el PDF del comprobante">📄</button>' : '') +
          (cls !== 'BAJA'
            ? '<button type="button" class="trib-gbtn img" data-cpeimg="' + _escapeHtml(String(c.idVenta || '')) + '" title="Generar el voucher como imagen y compartir">' +
                '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="3"/><circle cx="8.5" cy="8.5" r="1.6"/><path d="M21 15l-5-5L5 21"/></svg></button>'
            : '') +
          (c.enlacePdf
            ? '<button type="button" class="trib-gbtn wa" data-cpewa="' + _escapeHtml(String(c.idVenta || '')) + '" title="Compartir el PDF fiscal (WhatsApp)">' +
                '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z"/><path d="M14 2v6h6"/><path d="M9 15h1.5a1.5 1.5 0 0 0 0-3H9v6"/></svg></button>'
            : '') +
          (cls !== 'ACEPTADO' && cls !== 'BAJA'
            ? '<button type="button" class="trib-gbtn" data-recpe="' + _escapeHtml(String(c.idVenta || '')) + '" ' +
              'data-corr="' + _escapeHtml(String(c.correlativo || '')) + '" data-tipo="' + _escapeHtml(String(c.tipo || '')) + '" ' +
              'data-ref="' + _escapeHtml(String(c.refLocal || '')) + '" title="Consultar el estado real en SUNAT">🔄</button>'
            : '') +
          '</div>' +
        '</div>';
    });
    _cerrarGrupo();

    html += '<div class="trib-nota">Mostrando <b style="color:var(--trib-ink1)">' + filtrada.length + '</b> de ' + lista.length +
            ' comprobantes · IGV en pantalla <b style="color:var(--trib-contra)">' + _tribFmtSoles(totIGV) + '</b> ' +
            '(solo lo gravado, línea por línea, como se declaró; las bajas no suman).</div>';
    cont.innerHTML = html;
    cont.scrollTop = 0;
  }

  /* ══════════════════════════════════════════════════════════════════════════
     COMPARTIR UN COMPROBANTE — dos caminos, porque sirven para cosas distintas:
       IMAGEN — se dibuja acá con los datos que ya están en pantalla. Sale al instante, se ve
         en la vista previa del chat sin abrir nada, y lleva el QR de SUNAT para que el cliente
         valide por su cuenta. Es lo que la gente quiere cuando dice "mándamelo".
       PDF    — el archivo fiscal de NubeFact, el que vale para su contabilidad.
     Los dos usan Web Share con archivo cuando el equipo lo soporta (en el celular abre
     WhatsApp con el adjunto puesto). Si no, descargan y abren el chat: nunca queda sin salida.
     ══════════════════════════════════════════════════════════════════════════ */
  function _tribCPEPorId(id) {
    const lista = Array.isArray(_tribCPECache) ? _tribCPECache : [];
    return lista.find(c => String(c.idVenta || '') === String(id)) || null;
  }

  // EL VOUCHER: la representación impresa entera, como el ticket que sale de la caja.
  // Cabecera de la empresa, tipo y número, cliente, fecha, CADA LÍNEA con cantidad · nombre ·
  // importe, el desglose gravada/exonerada/IGV, el total, quién atendió, el hash y el QR de
  // SUNAT. El alto se calcula por el contenido: un ticket de 3 líneas sale corto, uno de 14
  // sale largo — como el papel.
  async function _tribCPEImagenBlob(c) {
    const W = 720, R = 2, PAD = 44;
    const lineas = Array.isArray(c.lineas) ? c.lineas : [];
    const esFac = String(c.tipo || '').toUpperCase() === 'FACTURA';
    const total = parseFloat(c.total) || 0;
    // desglose desde las líneas (mismo criterio que el emisor); sin líneas, se estima
    let grav = 0, exo = 0, inaf = 0;
    lineas.forEach(l => { const t = parseInt(l.tipoIgv ?? 1, 10), st = parseFloat(l.subtotal) || 0;
      if (t === 1) grav += st; else if (t === 8 || (t === 9 && false)) exo += st; else if (t === 9 || t === 10 || t === 11) inaf += st; else exo += st; });
    // en la venta vieja (14-18 ago) el 9 era exonerado; para el voucher da igual: va a "exonerada/inafecta"
    const baseGrav = Math.round(grav / 1.18 * 100) / 100, igv = Math.round((grav - baseGrav) * 100) / 100;
    const noGrav = Math.round((exo + inaf) * 100) / 100;
    const tieneDesglose = lineas.length > 0;
    const igvEst = tieneDesglose ? igv : _tribIGVdeCPE(c);
    const baseEst = tieneDesglose ? baseGrav : _money(total - igvEst);

    // alto = cabecera + líneas + pie
    // alto exacto = lo que ocupa cada bloque (cabecera 380 · fila de línea 44 · desglose · QR y pie 330).
    // Antes sobraban ~300 px de papel en blanco abajo del QR.
    const H = 380 + lineas.length * 44 + (tieneDesglose && noGrav > 0 ? 24 : 0) + 140 + 330 + (c.vendedor ? 22 : 0) + (c.clienteDoc && String(c.clienteDoc) !== '66666' ? 22 : 0);
    const cv = document.createElement('canvas'); cv.width = W * R; cv.height = H * R;
    const x = cv.getContext('2d'); x.scale(R, R);
    x.fillStyle = '#0b1220'; x.fillRect(0, 0, W, H);
    // el "papel": claro, con borde dentado arriba y abajo como un ticket térmico
    const papel = '#f8f6f1';
    x.fillStyle = papel; x.fillRect(24, 28, W - 48, H - 56);
    x.fillStyle = '#0b1220';
    for (let i = 24; i < W - 24; i += 14) { x.beginPath(); x.moveTo(i, 28); x.lineTo(i + 7, 20); x.lineTo(i + 14, 28); x.fill();
                                           x.beginPath(); x.moveTo(i, H - 28); x.lineTo(i + 7, H - 20); x.lineTo(i + 14, H - 28); x.fill(); }
    const T = (t, px, y, col, size, peso, alin, fam) => {
      x.fillStyle = col; x.textAlign = alin || 'left';
      x.font = (peso || '600') + ' ' + size + 'px ' + (fam === 'mono' ? 'ui-monospace, "SF Mono", Menlo, Consolas, monospace' : 'ui-sans-serif, system-ui, "Segoe UI", sans-serif');
      x.fillText(String(t == null ? '' : t), px, y);
    };
    const linea = (y, dash) => { x.strokeStyle = '#b9b3a7'; x.lineWidth = 1; x.setLineDash(dash ? [4, 4] : []);
                                 x.beginPath(); x.moveTo(PAD, y); x.lineTo(W - PAD, y); x.stroke(); x.setLineDash([]); };
    const ink = '#161616', ink2 = '#4b4b4b', ink3 = '#7a7a7a';
    let y = 78;
    T('INVERSIONES MOS E.I.R.L.', W / 2, y, ink, 22, '800', 'center'); y += 26;
    T('RUC 20610714057', W / 2, y, ink2, 13, '700', 'center', 'mono'); y += 20;
    T('Pisco · Ica', W / 2, y, ink3, 12, '600', 'center'); y += 30;
    linea(y); y += 30;
    T(esFac ? 'FACTURA ELECTRÓNICA' : 'BOLETA DE VENTA ELECTRÓNICA', W / 2, y, ink, 17, '800', 'center'); y += 26;
    T(c.correlativo || '', W / 2, y, ink, 26, '800', 'center', 'mono'); y += 30;
    linea(y, true); y += 26;
    const f = c.fecha ? new Date(c.fecha) : null;
    const fStr = f && !isNaN(f.getTime()) ? f.toLocaleString('es-PE', { day: '2-digit', month: '2-digit', year: 'numeric', hour: '2-digit', minute: '2-digit' }) : '';
    T('Fecha', PAD, y, ink3, 11, '700'); T(fStr, W - PAD, y, ink, 13, '600', 'right', 'mono'); y += 22;
    const cli = String(c.cliente || '').trim();
    const nomCli = cli && !/^varios$/i.test(cli) ? cli : 'CLIENTE VARIOS';
    T('Cliente', PAD, y, ink3, 11, '700');
    // nombre largo: dos renglones
    const maxW = W - PAD * 2 - 70; x.font = '700 13px ui-sans-serif, system-ui, sans-serif';
    if (x.measureText(nomCli).width > maxW) { const mitad = Math.ceil(nomCli.length / 2); const cut = nomCli.lastIndexOf(' ', mitad); const a = nomCli.slice(0, cut > 0 ? cut : mitad), b = nomCli.slice(cut > 0 ? cut + 1 : mitad);
      T(a, W - PAD, y, ink, 13, '700', 'right'); y += 18; T(b, W - PAD, y, ink, 13, '700', 'right'); }
    else T(nomCli, W - PAD, y, ink, 13, '700', 'right');
    y += 22;
    const doc = c.clienteDoc && String(c.clienteDoc) !== '66666' ? String(c.clienteDoc) : '';
    if (doc) { T(doc.length === 11 ? 'RUC' : 'DNI', PAD, y, ink3, 11, '700'); T(doc, W - PAD, y, ink, 13, '600', 'right', 'mono'); y += 22; }
    if (c.vendedor) { T('Atendió', PAD, y, ink3, 11, '700'); T(String(c.vendedor).split(' ').slice(0, 2).join(' '), W - PAD, y, ink2, 12, '600', 'right'); y += 22; }
    y += 6; linea(y, true); y += 24;
    // líneas
    T('CANT', PAD, y, ink3, 10, '800'); T('DESCRIPCIÓN', PAD + 70, y, ink3, 10, '800'); T('IMPORTE', W - PAD, y, ink3, 10, '800', 'right'); y += 20;
    if (!lineas.length) { T('(detalle no disponible en esta vista)', W / 2, y + 6, ink3, 11, '600', 'center'); y += 40; }
    lineas.forEach(l => {
      const n = parseFloat(l.cantidad) || 0, um = String(l.um || 'NIU').toUpperCase();
      const cant = (Number.isInteger(n) ? n : n.toFixed(3).replace(/0+$/, '').replace(/[.]$/, '')) + (um === 'KGM' ? ' kg' : '');
      let nom = String(l.nombre || '').replace(/\s+/g, ' ').trim();
      x.font = '600 12.5px ui-sans-serif, system-ui, sans-serif';
      const maxN = W - PAD * 2 - 70 - 90;
      while (x.measureText(nom).width > maxN && nom.length > 8) nom = nom.slice(0, -2);
      if (nom !== String(l.nombre || '').replace(/\s+/g, ' ').trim()) nom += '…';
      T(cant, PAD, y, ink, 12.5, '700', 'left', 'mono');
      T(nom, PAD + 70, y, ink, 12.5, '600');
      T((parseFloat(l.subtotal) || 0).toFixed(2), W - PAD, y, ink, 13, '700', 'right', 'mono');
      // precio unitario debajo, chico
      if (n !== 1 && l.precio != null) { y += 15; T('a ' + (parseFloat(l.precio) || 0).toFixed(2) + (um === 'KGM' ? ' /kg' : ' c/u'), PAD + 70, y, ink3, 10, '600', 'left', 'mono'); y += 29; }
      else y += 44;
    });
    linea(y, true); y += 26;
    const fila = (k, v, peso, size) => { T(k, PAD, y, ink2, size || 12, '700'); T('S/ ' + (parseFloat(v) || 0).toFixed(2), W - PAD, y, ink, size || 13, peso || '700', 'right', 'mono'); y += 24; };
    fila('Op. gravada', baseEst);
    if (tieneDesglose && noGrav > 0) fila('Op. exonerada / inafecta', noGrav);
    fila('IGV 18%', igvEst);
    y += 6; linea(y); y += 34;
    T('TOTAL', PAD, y, ink, 18, '800'); T('S/ ' + total.toFixed(2), W - PAD, y, ink, 30, '800', 'right', 'mono'); y += 22;
    if (c.formaPago && !/ANULADO/i.test(String(c.formaPago))) { y += 14; T('Pago: ' + String(c.formaPago).replace(/\s*\(.*$/, ''), PAD, y, ink3, 11, '700'); }
    y += 30; linea(y, true); y += 26;
    // estado fiscal + QR + hash
    const cls = _tribClasifCPE(c);
    const est = { ACEPTADO: ['ACEPTADO POR SUNAT', '#0f9d58'], PENDIENTE: ['ENVIADO · EN PROCESO EN SUNAT', '#b8860b'], RECHAZADO: ['RECHAZADO POR SUNAT', '#c62828'],
                  TRABADO: ['NO LLEGÓ A SUNAT', '#c62828'], BAJA: ['ANULADO · BAJA COMUNICADA', '#6b6b6b'], SIN_EMITIR: ['SIN EMITIR', '#6b6b6b'] }[cls] || ['', '#6b6b6b'];
    T(est[0], W / 2, y, est[1], 12, '800', 'center'); y += 26;
    const cadena = String(c.qr || '').trim();
    if (cadena && typeof qrcode === 'function') {
      try { const q = qrcode(0, 'M'); q.addData(cadena); q.make();
        const n = q.getModuleCount(), lado = 150, cel = lado / n, ox = (W - lado) / 2, oy = y;
        x.fillStyle = '#000';
        for (let r = 0; r < n; r++) for (let col = 0; col < n; col++) if (q.isDark(r, col)) x.fillRect(ox + col * cel, oy + r * cel, cel + .5, cel + .5);
        y += lado + 22; } catch (_) {}
    }
    const hash = cadena ? (cadena.split('|').map(s => s.trim()).filter(Boolean).pop() || '') : '';
    if (hash && hash.length > 10) { T('Hash: ' + hash.slice(0, 28) + (hash.length > 28 ? '…' : ''), W / 2, y, ink3, 9.5, '600', 'center', 'mono'); y += 18; }
    T('Representación impresa del comprobante electrónico', W / 2, y, ink3, 10, '600', 'center'); y += 15;
    T('Consulte en www.sunat.gob.pe · ⚡ MOS', W / 2, y, ink3, 10, '600', 'center');
    return await new Promise(res => cv.toBlob(res, 'image/png'));
  }

  async function _tribCompartirArchivo(file, texto, enlace) {
    if (navigator.canShare && navigator.canShare({ files: [file] })) {
      try { await navigator.share({ files: [file], title: file.name, text: texto }); return true; }
      catch (err) { if (err && err.name === 'AbortError') return true; }
    }
    _descargarBlob(file, file.name);
    window.open('https://wa.me/?text=' + encodeURIComponent(texto + (enlace ? '\n' + enlace : '')), '_blank');
    toast('Descargado \u00b7 adjuntalo en el chat', 'info', 6000);
    return false;
  }
  const _tribTextoCPE = (c) => (String(c.tipo || '').toUpperCase() === 'FACTURA' ? 'Factura ' : 'Boleta ') +
        (c.correlativo || '') + ' \u00b7 S/ ' + (parseFloat(c.total) || 0).toFixed(2);

  async function _tribCompartirImagen(id) {
    const c = _tribCPEPorId(id);
    if (!c) { toast('No encontre ese comprobante', 'error'); return; }
    try {
      toast('Generando la imagen\u2026', 'info', 2000);
      const blob = await _tribCPEImagenBlob(c);
      if (!blob) throw new Error('no se pudo dibujar');
      await _tribCompartirArchivo(new File([blob], (c.correlativo || 'comprobante') + '.png', { type: 'image/png' }),
                                  _tribTextoCPE(c), '');
    } catch (e) { toast('No se pudo generar: ' + (e && (e.message || e)), 'error', 6000); }
  }

  async function _tribCompartirPDF(id) {
    const c = _tribCPEPorId(id);
    if (!c) { toast('No encontre ese comprobante', 'error'); return; }
    try {
      toast('Preparando el PDF\u2026', 'info', 2000);
      const r = await API.descargarCpePdf(c.idVenta);
      const fname = r.filename || ((c.correlativo || 'comprobante') + '.pdf');
      await _tribCompartirArchivo(new File([r.blob], fname, { type: 'application/pdf' }),
                                  _tribTextoCPE(c), c.enlacePdf || '');
    } catch (e) { toast('No se pudo compartir: ' + (e && (e.message || e)), 'error', 6000); }
  }

  function _tribCPEClick(e) {
    const t = e.target;
    const chip = t.closest && t.closest('[data-cpefiltro]');
    if (chip) { _tribCPEFiltro.estado = chip.getAttribute('data-cpefiltro'); _finBeep && _finBeep('click'); _tribRenderCPEDetalle(); return; }
    const chipT = t.closest && t.closest('[data-cpetipo]');
    if (chipT) { _tribCPEFiltro.tipo = chipT.getAttribute('data-cpetipo'); _finBeep && _finBeep('click'); _tribRenderCPEDetalle(); return; }
    const chipZ = t.closest && t.closest('[data-cpezona]');
    if (chipZ) { _tribCPEFiltro.zona = chipZ.getAttribute('data-cpezona'); _finBeep && _finBeep('click'); _tribRenderCPEDetalle(); return; }
    const bImg = t.closest && t.closest('[data-cpeimg]');
    if (bImg) { _tribCompartirImagen(bImg.getAttribute('data-cpeimg')); return; }
    const bWa = t.closest && t.closest('[data-cpewa]');
    if (bWa) { _tribCompartirPDF(bWa.getAttribute('data-cpewa')); return; }
    const pdf = t.closest && t.closest('[data-pdf]');
    if (pdf) { _finBeep && _finBeep('click'); window.open(pdf.getAttribute('data-pdf'), '_blank', 'noopener'); return; }
    const re = t.closest && t.closest('[data-recpe]');
    if (re) {
      re.classList.add('girando');
      tribReintentarCPE(re.getAttribute('data-recpe'), re.getAttribute('data-corr'), re.getAttribute('data-tipo'), re.getAttribute('data-ref'));
      return;
    }
  }

  // Refresco en sitio del overlay de CPE (sin cerrarlo y volverlo a abrir).
  function _tribRefrescarEmitido() {
    if (document.getElementById('tribOvEmitido')) _tribFetchCPE();
  }

  async function tribReprocesarOCR(idGuia) {
    const auth = await pedirAuth({ accion: 'TRIBUTARIO_REPROCESAR_OCR', refDocumento: idGuia });
    if (!auth) return;
    toast('🔄 Reprocesando OCR de ' + idGuia + '...', 'info');
    try {
      // [Lote3-A · fix A4-MOS] API.post lanza si ok:false → llegar acá ES éxito.
      // Antes exigía res.ok && res.data (ambos undefined tras desempaquetar) →
      // mostraba "OCR falló" en operaciones EXITOSAS. `res` ES el data ya desempaquetado.
      const res = await API.post('tribReprocesarOCR', { idGuia });
      const d = (res && res.data) ? res.data : (res || {});
      // [762] El botón ya no procesa: RE-ENCOLA. El pipeline server-side lee la
      // foto solo, así que el mensaje útil es data.nota (cuánto va a tardar).
      toast('✓ ' + (d.nota || ('OCR ' + (d.estado || 'reencolado'))) +
            (d.igvRecuperable > 0 ? ' · IGV ' + _tribFmtSoles(d.igvRecuperable) : ''), 'success', 6000);
      _finBeep && _finBeep('success');
    } catch(e) {
      toast('OCR falló: ' + (e.message || e), 'warn');
    } finally {
      tribCargar();                    // refresca los KPIs siempre
      _tribFetchIGVFavor(true);        // y la lista del overlay si está abierto
    }
  }

  async function tribReintentarCPE(idVenta, correlativo, tipoDoc, refLocal) {
    const auth = await pedirAuth({ accion: 'TRIBUTARIO_REINTENTAR_CPE', refDocumento: idVenta });
    if (!auth) return;
    toast('🔄 Consultando estado en SUNAT...', 'info');
    try {
      // [RECONCILIACIÓN cero-GAS] PRIMERO el Edge (operacion=consultar → me.set_cpe_nf): re-consulta el
      // estado SUNAT real y lo persiste, SIN GAS. Requiere correlativo+tipo+refLocal (los pasa la fila de
      // trazabilidad de Supabase). Si no vienen (fila vieja de GAS) o el Edge no responde → fallback GAS.
      let hecho = false;
      if (correlativo && tipoDoc && refLocal) {
        const r = await API.cpeReconciliar({ correlativo, tipoDoc, refLocal });
        if (r && r.ok) {
          toast('✓ CPE ' + (r.estado || 'consultado') + (r.aceptada ? ' · aceptado SUNAT' : (r.sunatDesc ? ' · ' + r.sunatDesc : '')), 'success');
          _finBeep && _finBeep('success'); hecho = true;
        } else if (r && r.ok === false && r.error) {
          toast('SUNAT/NubeFact: ' + r.error, 'warn'); hecho = true;
        }
        // r === null → infra (sin token/red) → avisar y reintentar (sin brazo GAS)
      }
      if (!hecho) {
        // [FUNERAL GAS 14-ago] el brazo API.post('tribReintentarCPE') murió — el camino
        // es API.cpeReconciliar (Edge consultar + set_cpe_nf); sin token/red se reintenta.
        toast('Sin respuesta del servidor — revisa conexión y reintenta', 'warn', 5000);
      }
    } catch(e) {
      toast('Reintento falló: ' + (e.message || e), 'warn');
    } finally {
      // Refresca la lista EN SITIO: antes se volvía a abrir el overlay entero
      // (parpadeo + se perdían filtro y búsqueda).
      _tribRefrescarEmitido();
    }
  }

  async function tribReconciliarCPEs() {
    const auth = await pedirAuth({ accion: 'TRIBUTARIO_RECONCILIAR_TODOS', refDocumento: 'mes-actual' });
    if (!auth) return;
    toast('🔄 Reconciliando todos los CPE pendientes con NubeFact/SUNAT...', 'info');
    try {
      // [500x-2b · cero-GAS] PRIMERO Supabase: jala los pendientes (cpe_trazabilidad) e itera el Edge
      // consultar por cada uno (API.cpeReconciliar → set_cpe_nf), sin GAS. Fallback a GAS si no hay token.
      const _mm = String(_tribState.mes).padStart(2, '0');
      const _desde = `${_tribState.anio}-${_mm}-01`;
      const _ult = new Date(_tribState.anio, _tribState.mes, 0).getDate();
      const _hasta = `${_tribState.anio}-${_mm}-${String(_ult).padStart(2, '0')}`;
      let viaSupa = false, emitidos = 0, rechazados = 0, sinCambio = 0;
      const sup = await API.cpeTrazabilidad(_desde, _hasta);
      if (sup && sup.ok && Array.isArray(sup.cpe)) {
        const pend = sup.cpe.filter(c => !c.aceptadoSunat && String(c.nfEstado || '').toUpperCase().indexOf('BAJA') !== 0 && c.nfEstado !== 'RECHAZADO' && c.refLocal && c.correlativo);
        for (const c of pend) {
          const r = await API.cpeReconciliar({ correlativo: c.correlativo, tipoDoc: c.tipo, refLocal: c.refLocal });
          if (r === null) { viaSupa = false; break; }          // sin token/red → caer a GAS
          viaSupa = true;
          if (r.ok && r.estado === 'EMITIDO') emitidos++;
          else if (r.ok && r.estado === 'RECHAZADO') rechazados++;
          else sinCambio++;
        }
        if (viaSupa || pend.length === 0) { viaSupa = true; }
      }
      if (!viaSupa) {
        // [FUNERAL GAS 14-ago] el brazo API.post('tribReconciliarCPEs') murió — el bucle
        // Supabase (cpeTrazabilidad + cpeReconciliar) es el único camino; además el cron
        // cpe-reconciliar corre cada hora solo.
        toast('Sin respuesta del servidor — el cron horario reconcilia solo; reintenta si urge', 'warn', 6000);
        return;
      }
      toast('✓ ' + emitidos + ' emitidos · ' + rechazados + ' rechazados · ' + sinCambio + ' sin cambio ⚡', 'success');
      _finBeep && _finBeep('success');
      tribCargar();
      _tribRefrescarEmitido();
    } catch(e) { toast('Error: ' + (e.message || e), 'error'); }
  }

  // [v2.42.11] Exportar a Excel — descarga CSV (compatible con Excel) con
  // 2 secciones: COMPRAS (IGV a favor del mes) y VENTAS (CPE emitidos).
  // Sin requerir librerías extras — genera el archivo en el cliente.
  async function tribExportarExcel() {
    if (!_tribState.mes || !_tribState.anio) {
      toast('Selecciona un mes primero', 'warning');
      return;
    }
    const nombreMes = ['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'][_tribState.mes - 1];
    toast('📥 Generando Excel...', 'info', 3000);
    try {
      _finBeep && _finBeep('tap');
      // Cargar compras (IGV a favor) y ventas (CPE emitidos) en paralelo
      const [resCompras, resVentas] = await Promise.all([
        API.post('tribIGVFavorMes',   { mes: _tribState.mes, anio: _tribState.anio }),
        API.post('tribIGVEmitidoMes', { mes: _tribState.mes, anio: _tribState.anio })
      ]);
      const compras = (resCompras?.data?.guias || []);
      const ventas  = (resVentas?.cpe || resVentas?.data?.cpe || []);
      // Construir CSV con BOM UTF-8 para que Excel respete acentos
      const sep = ';';   // Excel ES suele esperar punto y coma
      const esc = (v) => {
        const s = String(v == null ? '' : v).replace(/"/g, '""');
        return /[";\n]/.test(s) ? '"' + s + '"' : s;
      };
      let csv = '﻿'; // BOM UTF-8
      // Sección compras
      csv += 'COMPRAS - IGV A FAVOR · ' + nombreMes + ' ' + _tribState.anio + '\n';
      csv += ['Fecha','Guia','RUC Emisor','Razón Social','Serie','Número','Total Doc','IGV Recuperable','Estado OCR','Confidence'].map(esc).join(sep) + '\n';
      let totalCompras = 0, totalIGVFavor = 0;
      compras.forEach(g => {
        const fecha = g.fechaComprobante || (g.fecha ? new Date(g.fecha).toLocaleDateString('es-PE') : '');
        csv += [
          fecha, g.idGuia, g.rucEmisor, g.razonSocial,
          g.serie, g.numero, g.total, g.igvRecuperable,
          g.ocrEstado, g.confidence
        ].map(esc).join(sep) + '\n';
        totalCompras  += parseFloat(g.total) || 0;
        totalIGVFavor += parseFloat(g.igvRecuperable) || 0;
      });
      csv += ['','','','','','TOTAL', totalCompras.toFixed(2), totalIGVFavor.toFixed(2),'',''].map(esc).join(sep) + '\n';
      csv += '\n\n';
      // Sección ventas
      csv += 'VENTAS - CPE EMITIDOS · ' + nombreMes + ' ' + _tribState.anio + '\n';
      csv += ['Fecha','Tipo Doc','Correlativo','RUC/DNI Cliente','Razón Social','Total','IGV Emitido','Estado SUNAT','Vendedor'].map(esc).join(sep) + '\n';
      let totalVentas = 0, totalIGVEmitido = 0;
      ventas.forEach(v => {
        const fecha = v.fecha || '';
        const igvCalc = v.igv != null ? parseFloat(v.igv) : (parseFloat(v.total) || 0) * 0.18 / 1.18;
        csv += [
          fecha, v.tipoDoc, v.correlativo, v.docCliente,
          v.nombreCliente, v.total, igvCalc.toFixed(2),
          v.estadoSUNAT || v.nfEstado || '', v.vendedor
        ].map(esc).join(sep) + '\n';
        totalVentas    += parseFloat(v.total) || 0;
        totalIGVEmitido += igvCalc;
      });
      csv += ['','','','','TOTAL', totalVentas.toFixed(2), totalIGVEmitido.toFixed(2),'',''].map(esc).join(sep) + '\n';
      csv += '\n\n';
      // Resumen tributario
      csv += 'RESUMEN TRIBUTARIO\n';
      csv += ['IGV a favor (compras)','S/ ' + totalIGVFavor.toFixed(2)].map(esc).join(sep) + '\n';
      csv += ['IGV emitido (ventas)', 'S/ ' + totalIGVEmitido.toFixed(2)].map(esc).join(sep) + '\n';
      csv += ['IGV neto (a pagar)',   'S/ ' + (totalIGVEmitido - totalIGVFavor).toFixed(2)].map(esc).join(sep) + '\n';
      csv += ['Total compras',        'S/ ' + totalCompras.toFixed(2)].map(esc).join(sep) + '\n';
      csv += ['Total ventas',         'S/ ' + totalVentas.toFixed(2)].map(esc).join(sep) + '\n';
      csv += ['Renta MYPE 1.5%',      'S/ ' + (totalVentas * 0.015).toFixed(2)].map(esc).join(sep) + '\n';
      // Descargar
      const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `tributario_${_tribState.anio}-${String(_tribState.mes).padStart(2,'0')}.csv`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);
      _finBeep && _finBeep('success');
      toast(`✓ Excel listo · ${compras.length} compras · ${ventas.length} ventas`, 'success', 6000);
    } catch(e) {
      _finBeep && _finBeep('error');
      toast('Error generando Excel: ' + (e.message || e), 'error');
    }
  }

  // [v2.42.11] Proyección de cierre de mes basado en ritmo actual.
  // Si vamos al 71% del mes con S/ 1000 de IGV, proyectamos 1000/0.71 = 1408.
  function _tribCalcProyeccion(d) {
    if (!d || !d.pctMes || d.pctMes <= 0) return null;
    const factor = 100 / d.pctMes;
    return {
      igvFavorProy:    (d.igvFavor || 0)   * factor,
      igvEmitidoProy:  (d.igvEmitido || 0) * factor,
      balanceNetoProy: (d.balanceNetoIGV || 0) * factor,
      ventasProy:      (d.totalVentas || 0) * factor,
      pctMes:          d.pctMes,
      diasRestantes:   (d.ultimoDia || 30) - (d.diaActual || 0)
    };
  }

  // [v2.41.94] OCR masivo retroactivo del mes — procesa todas las fotos
  // de boletas/facturas de proveedor sin OCR. Muestra progress y stats.
  async function tribOCRMasivo() {
    const auth = await pedirAuth({ accion: 'TRIBUTARIO_OCR_MASIVO', refDocumento: _tribState.mes + '/' + _tribState.anio });
    if (!auth) return;
    if (!await _modalConfirm('¿Volver a encolar todas las fotos de boletas/facturas de proveedor SIN leer del mes ' + _tribState.mes + '/' + _tribState.anio + '?\n\nEl pipeline las procesa solo, en tandas cada 10 minutos.', { warning: true, titulo: 'Re-encolar OCR del mes', okText: 'Encolar' })) return;
    toast('🤖 Encolando las fotos del mes...', 'info');
    try {
      const res = await API.post('tribOCRMasivo', {
        mes: _tribState.mes, anio: _tribState.anio, soloSinProcesar: true
      });
      const s = res?.data || res || {};
      // [762] Ya no procesa en línea: re-encola y el cron server-side lee. La
      // respuesta útil es data.nota / data.encoladas.
      if (s.nota || s.encoladas !== undefined || s.procesadas !== undefined) {
        toast('✓ ' + (s.nota || ((s.encoladas != null ? s.encoladas : s.procesadas) + ' guías encoladas')), 'success', 7000);
        _finBeep && _finBeep('success');
      } else {
        toast('OCR masivo falló: ' + (res?.error || 'sin detalle'), 'warn');
      }
      tribCargar();                 // refresh de KPIs
      _tribFetchIGVFavor(true);     // y de la lista del overlay si está abierta
    } catch(e) { toast('Error: ' + (e.message || e), 'error'); }
  }

  async function tribLimpiarHuerfanas() {
    const auth = await pedirAuth({ accion: 'TRIBUTARIO_LIMPIAR_HUERFANAS', refDocumento: 'global' });
    if (!auth) return;
    if (!await _modalConfirm('¿Marcar las filas con correlativo "undefined-*" como HUERFANA_LIMPIADA?', { warning: true, titulo: 'Limpiar huérfanas' })) return;
    try {
      const res = await API.post('tribLimpiarVentasHuerfanas', {});
      const n = res?.limpiadas || res?.data?.limpiadas || 0;
      toast('🧹 ' + n + ' filas huérfanas marcadas', 'success');
      _finBeep && _finBeep('success');
    } catch(e) { toast('Error: ' + (e.message || e), 'error'); }
  }

  // ═══════════════════════════════════════════════════════════════════
  // HISTÓRICO 12 MESES · gráfico SVG a mano (sin librerías: CSP + peso)
  // ───────────────────────────────────────────────────────────────────
  // Forma elegida: columnas agrupadas favor/en-contra + línea del balance,
  // TODO sobre UN SOLO eje (mismas unidades, soles) — nunca dos escalas.
  // La renta va como franja aparte abajo: es otra magnitud y merece su
  // propio eje, que es exactamente por lo que NO se dibuja en el mismo plot.
  // El viewBox se genera al ancho medido del contenedor (1 unidad = 1 px)
  // para que los textos no se deformen al escalar.
  // ═══════════════════════════════════════════════════════════════════
  const _TRIB_C_FAVOR   = '#34d399';
  const _TRIB_C_CONTRA  = '#f43f5e';   // paso más profundo del rosa: ver nota CVD en el CSS
  const _TRIB_C_BALANCE = '#cbd5e1';   // derivado y acromático a propósito: no compite con las series
  const _TRIB_C_RENTA   = '#a78bfa';
  const _TRIB_C_GRID    = '#1e293b';
  const _TRIB_C_EJE     = '#475569';
  const _TRIB_C_TXT     = '#64748b';

  // Marcas de eje redondeadas (0 / 2k / 4k ...) que cubren [min,max].
  function _tribTicks(min, max, n) {
    const span = (max - min) || 1;
    const bruto = span / Math.max(1, n);
    const mag = Math.pow(10, Math.floor(Math.log10(bruto)));
    const paso = [1, 2, 2.5, 5, 10].map(k => k * mag).find(s => s >= bruto) || 10 * mag;
    const lo = Math.floor(min / paso) * paso;
    const hi = Math.ceil(max / paso) * paso;
    const marcas = [];
    for (let v = lo; v <= hi + paso * 0.001; v += paso) marcas.push(+v.toFixed(6));
    return { lo, hi: (hi === lo ? lo + paso : hi), marcas };
  }

  // Barra con el extremo de dato redondeado (4px) y escuadra en la línea base.
  function _tribBarPath(x, y, w, h, r) {
    if (!(h > 0.6)) return '';
    const rr = Math.min(r, w / 2, h);
    return 'M' + x + ',' + (y + h) +
           ' L' + x + ',' + (y + rr) +
           ' Q' + x + ',' + y + ' ' + (x + rr) + ',' + y +
           ' L' + (x + w - rr) + ',' + y +
           ' Q' + (x + w) + ',' + y + ' ' + (x + w) + ',' + (y + rr) +
           ' L' + (x + w) + ',' + (y + h) + ' Z';
  }

  let _tribHistRO = null;
  let _tribHistTimer = null;
  let _tribHistW = 0;   // ancho del último render: el chart solo se rehace si CAMBIA

  function _tribPintarHistorico() {
    const cont = $('tribHistBody');
    if (!cont) return;
    const data = _tribHist;
    const sub = $('tribHistSub');
    const resumen = $('tribHistResumen');

    if (!data || !data.length) {
      if (_tribHistBusy) return;   // sigue en vuelo: se queda el skeleton
      cont.innerHTML = '<div class="trib-vacio"><span class="trib-vacio-ico">📉</span>Sin histórico disponible</div>';
      if (sub) sub.textContent = 'No se pudo calcular el histórico';
      return;
    }

    const n = data.length;
    const totFavor  = data.reduce((s, m) => s + (m.igvFavor || 0), 0);
    const totContra = data.reduce((s, m) => s + (m.igvEmitido || 0), 0);
    const totRenta  = data.reduce((s, m) => s + (m.renta || 0), 0);
    const netoFavor = totFavor - totContra;
    if (sub) sub.textContent = data[0].label + ' ' + String(data[0].anio).slice(-2) + ' → ' +
                               data[n - 1].label + ' ' + String(data[n - 1].anio).slice(-2) + ' · IGV a favor vs en contra';
    if (resumen) {
      resumen.innerHTML = 'Acumulado: <b style="color:' + (netoFavor >= 0 ? 'var(--trib-favor)' : 'var(--trib-contra)') + '">' +
        _tribFmtSoles(Math.abs(netoFavor)) + '</b> ' + (netoFavor >= 0 ? 'a favor' : 'en contra') +
        ' · renta <b style="color:var(--trib-renta)">' + _tribFmtSoles(totRenta) + '</b>';
    }

    // ── Geometría ────────────────────────────────────────────────────
    const W = Math.max(280, Math.round(cont.clientWidth || 640));
    _tribHistW = W;
    const compacto = W < 560;
    const padL = compacto ? 38 : 46, padR = 10, padT = 12, padB = 22;
    const H = compacto ? 170 : 206;
    const plotW = W - padL - padR, plotH = H - padT - padB;
    const banda = plotW / n;

    let maxV = 1, minV = 0;
    data.forEach(m => {
      maxV = Math.max(maxV, m.igvFavor || 0, m.igvEmitido || 0, m.balFavor || 0);
      minV = Math.min(minV, m.balFavor || 0);
    });
    const t = _tribTicks(minV, maxV, compacto ? 3 : 4);
    const y = v => padT + ((t.hi - v) / (t.hi - t.lo)) * plotH;
    const y0 = y(0);

    // Grosor de columna: nunca llena la banda — el aire restante es del diseño.
    const bw = Math.max(4, Math.min(14, banda * 0.30));
    const hueco = 2;   // separador de 2px en color de superficie entre columnas vecinas

    let grid = '', barras = '', ejes = '', bandas = '', marcasX = '';
    t.marcas.forEach(v => {
      const yy = y(v).toFixed(1);
      grid += '<line x1="' + padL + '" y1="' + yy + '" x2="' + (W - padR) + '" y2="' + yy + '" stroke="' + _TRIB_C_GRID + '" stroke-width="1"></line>';
      ejes += '<text x="' + (padL - 7) + '" y="' + (y(v) + 3.5).toFixed(1) + '" text-anchor="end" font-size="9" fill="' + _TRIB_C_TXT + '" font-weight="700">' + _tribFmtCorto(v) + '</text>';
    });
    // Línea del cero, más marcada, si el dominio cruza a negativo.
    if (t.lo < 0) grid += '<line x1="' + padL + '" y1="' + y0.toFixed(1) + '" x2="' + (W - padR) + '" y2="' + y0.toFixed(1) + '" stroke="' + _TRIB_C_EJE + '" stroke-width="1"></line>';

    const puntos = [];
    data.forEach((m, i) => {
      const cx = padL + banda * i + banda / 2;
      const xF = cx - hueco / 2 - bw;
      const xC = cx + hueco / 2;
      const hF = Math.max(0, y0 - y(m.igvFavor || 0));
      const hC = Math.max(0, y0 - y(m.igvEmitido || 0));
      barras += '<path d="' + _tribBarPath(xF, y0 - hF, bw, hF, 4) + '" fill="' + _TRIB_C_FAVOR + '"></path>';
      barras += '<path d="' + _tribBarPath(xC, y0 - hC, bw, hC, 4) + '" fill="' + _TRIB_C_CONTRA + '"></path>';
      puntos.push([cx, y(m.balFavor || 0)]);
      // Etiqueta de mes: en pantalla angosta, una sí una no.
      if (!compacto || i % 2 === 1) {
        marcasX += '<text x="' + cx.toFixed(1) + '" y="' + (H - 6) + '" text-anchor="middle" font-size="9" fill="' + _TRIB_C_TXT + '" font-weight="700">' +
                   _escapeHtml(m.label) + '</text>';
      }
      bandas += '<rect class="trib-chart-band" data-mes="' + i + '" x="' + (padL + banda * i).toFixed(1) + '" y="' + padT + '" width="' + banda.toFixed(1) + '" height="' + plotH + '" rx="4"></rect>';
    });

    // Línea del balance (2px, mismas unidades y mismo eje que las columnas).
    const linea = '<path d="M' + puntos.map(p => p[0].toFixed(1) + ',' + p[1].toFixed(1)).join(' L') + '" fill="none" stroke="' +
                  _TRIB_C_BALANCE + '" stroke-width="2" stroke-linejoin="round" stroke-linecap="round" opacity=".9"></path>';
    // Marcadores + etiqueta directa SOLO en dos sitios: el extremo y el final
    // (etiquetar cada punto sería ruido; el resto lo cargan el tooltip y la tabla).
    let iExt = 0;
    data.forEach((m, i) => { if (Math.abs(m.balFavor || 0) > Math.abs(data[iExt].balFavor || 0)) iExt = i; });
    let marcasLinea = '';
    [iExt, n - 1].filter((v, i, a) => a.indexOf(v) === i).forEach(i => {
      const p = puntos[i];
      const col = (data[i].balFavor || 0) >= 0 ? _TRIB_C_FAVOR : _TRIB_C_CONTRA;
      marcasLinea += '<circle cx="' + p[0].toFixed(1) + '" cy="' + p[1].toFixed(1) + '" r="4.5" fill="' + col + '" stroke="#0b1322" stroke-width="2"></circle>';
    });
    const pFin = puntos[n - 1];
    const balFin = data[n - 1].balFavor || 0;
    const etiqFin = '<text x="' + (pFin[0] - 6).toFixed(1) + '" y="' + (pFin[1] - 9).toFixed(1) + '" text-anchor="end" font-size="10" font-weight="800" fill="#cbd5e1">' +
                    _tribFmtCorto(balFin) + '</text>';

    // ── Franja de renta (magnitud distinta → gráfico aparte, eje propio) ──
    const HR = 52, padTR = 14, plotHR = HR - padTR - 12;
    const maxR = Math.max(1, ...data.map(m => m.renta || 0));
    let barrasR = '', bandasR = '';
    data.forEach((m, i) => {
      const cx = padL + banda * i + banda / 2;
      const h = ((m.renta || 0) / maxR) * plotHR;
      const bwR = Math.max(4, Math.min(14, banda * 0.34));
      barrasR += '<path d="' + _tribBarPath(cx - bwR / 2, padTR + plotHR - h, bwR, h, 3) + '" fill="' + _TRIB_C_RENTA + '" opacity=".9">' +
                 '<title>' + _escapeHtml(m.label + ' ' + m.anio) + ' · renta ' + _tribFmtSoles(m.renta) + '</title></path>';
      bandasR += '';
    });

    // ── Tabla equivalente: ningún valor queda encerrado en el hover ──────
    let filas = '';
    data.forEach(m => {
      filas += '<tr><td>' + _escapeHtml(m.label + ' ' + String(m.anio).slice(-2)) + '</td>' +
               '<td>' + _tribFmtSoles(m.igvFavor) + '</td>' +
               '<td>' + _tribFmtSoles(m.igvEmitido) + '</td>' +
               '<td style="color:' + ((m.balFavor || 0) >= 0 ? _TRIB_C_FAVOR : '#fb7185') + '">' + _tribFmtSoles(m.balFavor) + '</td>' +
               '<td>' + _tribFmtSoles(m.ventas) + '</td>' +
               '<td>' + _tribFmtSoles(m.renta) + '</td></tr>';
    });

    cont.innerHTML =
      '<div class="trib-chart" id="tribChartWrap">' +
        '<svg viewBox="0 0 ' + W + ' ' + H + '" width="100%" height="' + H + '" role="img" ' +
             'aria-label="IGV a favor y en contra de los últimos 12 meses, con la línea del balance">' +
          grid + barras + linea + marcasLinea + etiqFin + ejes + marcasX + bandas +
        '</svg>' +
        '<div class="trib-panel-sub" style="margin-top:6px">Impuesto a la renta del mes (escala propia)</div>' +
        '<svg viewBox="0 0 ' + W + ' ' + HR + '" width="100%" height="' + HR + '" role="img" aria-label="Impuesto a la renta mes a mes">' +
          '<line x1="' + padL + '" y1="' + (padTR + plotHR) + '" x2="' + (W - padR) + '" y2="' + (padTR + plotHR) + '" stroke="' + _TRIB_C_GRID + '" stroke-width="1"></line>' +
          barrasR + bandasR +
        '</svg>' +
        '<div class="trib-tt" id="tribChartTT"></div>' +
      '</div>' +
      '<div class="trib-legend">' +
        '<span class="trib-legend-item"><span class="trib-swatch" style="background:' + _TRIB_C_FAVOR + '"></span>IGV a favor</span>' +
        '<span class="trib-legend-item"><span class="trib-swatch" style="background:' + _TRIB_C_CONTRA + '"></span>IGV en contra</span>' +
        '<span class="trib-legend-item"><span class="trib-linekey"></span>Balance del mes</span>' +
        '<span class="trib-legend-item"><span class="trib-swatch" style="background:' + _TRIB_C_RENTA + '"></span>Renta</span>' +
      '</div>' +
      '<details><summary class="trib-tabla-tog">Ver la tabla con los 12 meses</summary>' +
        '<div class="trib-tabla-wrap"><table class="trib-tabla">' +
          '<thead><tr><th>Mes</th><th>A favor</th><th>En contra</th><th>Balance</th><th>Ventas</th><th>Renta</th></tr></thead>' +
          '<tbody>' + filas + '</tbody>' +
        '</table></div>' +
      '</details>';

    // Tooltip: hover en escritorio, tap en táctil. El valor nunca vive solo
    // acá — la tabla de arriba es el gemelo accesible.
    const wrap = $('tribChartWrap');
    const tt = $('tribChartTT');
    if (wrap && tt) {
      const mostrar = (i, rect) => {
        const m = data[i];
        if (!m) return;
        tt.innerHTML =
          '<div class="trib-tt-mes">' + _escapeHtml(m.label + ' ' + m.anio) + '</div>' +
          '<div class="trib-tt-row"><span class="trib-swatch" style="background:' + _TRIB_C_FAVOR + '"></span>A favor<b>' + _tribFmtSoles(m.igvFavor) + '</b></div>' +
          '<div class="trib-tt-row"><span class="trib-swatch" style="background:' + _TRIB_C_CONTRA + '"></span>En contra<b>' + _tribFmtSoles(m.igvEmitido) + '</b></div>' +
          '<div class="trib-tt-row"><span class="trib-linekey"></span>Balance<b style="color:' + ((m.balFavor || 0) >= 0 ? _TRIB_C_FAVOR : '#fb7185') + '">' + _tribFmtSoles(m.balFavor) + '</b></div>' +
          '<div class="trib-tt-row"><span class="trib-swatch" style="background:' + _TRIB_C_RENTA + '"></span>Renta<b>' + _tribFmtSoles(m.renta) + '</b></div>' +
          '<div class="trib-tt-row" style="opacity:.75">Ventas<b>' + _tribFmtSoles(m.ventas) + '</b></div>';
        tt.classList.add('visible');
        const wr = wrap.getBoundingClientRect();
        const tw = tt.offsetWidth, th = tt.offsetHeight;
        let left = (rect.left - wr.left) + rect.width / 2 - tw / 2;
        left = Math.max(2, Math.min(left, wr.width - tw - 2));
        tt.style.left = left + 'px';
        tt.style.top = Math.max(2, (rect.top - wr.top) + rect.height / 2 - th / 2) + 'px';
      };
      wrap.querySelectorAll('.trib-chart-band').forEach(b => {
        const i = parseInt(b.getAttribute('data-mes'), 10);
        b.addEventListener('pointerenter', () => mostrar(i, b.getBoundingClientRect()));
        b.addEventListener('pointerdown',  () => mostrar(i, b.getBoundingClientRect()));
      });
      wrap.addEventListener('pointerleave', () => tt.classList.remove('visible'));
    }

    // Re-render al cambiar el ancho (el viewBox se genera en píxeles reales).
    if (!_tribHistRO && window.ResizeObserver) {
      const panel = $('tribHistPanel');
      if (panel) {
        _tribHistRO = new ResizeObserver(() => {
          clearTimeout(_tribHistTimer);
          _tribHistTimer = setTimeout(() => {
            // SOLO si cambió el ANCHO. Si se reaccionara también al alto, abrir
            // el <details> de la tabla crecería el panel → re-render → la tabla
            // se cerraría sola al instante.
            const c = $('tribHistBody');
            if (!c || S.view !== 'tributario') return;
            if (Math.abs(Math.round(c.clientWidth) - _tribHistW) < 2) return;
            _tribPintarHistorico();
          }, 160);
        });
        _tribHistRO.observe(panel);
      }
    }
  }

  // El botón "Histórico" del menú ⋯ ya no abre un modal: el gráfico vive en
  // la vista principal, así que lo lleva hasta él y lo resalta un instante.
  function tribAbrirHistorico() {
    const panel = $('tribHistPanel');
    if (!panel) return;
    panel.scrollIntoView({ behavior: 'smooth', block: 'center' });
    panel.style.transition = 'box-shadow .4s cubic-bezier(.16,1,.3,1)';
    panel.style.boxShadow = '0 0 0 2px rgba(129,140,248,.5)';
    setTimeout(() => { panel.style.boxShadow = ''; }, 1100);
    _finBeep && _finBeep('click');
  }

  // ═══════════════════════════════════════════════════════════════════
  // OVERLAY 3 · RENTA — de dónde sale la cifra, con honestidad
  // ═══════════════════════════════════════════════════════════════════
  function tribAbrirRenta() {
    const d = _tribState.data || {};
    const ventas = d.totalVentas || 0;
    const renta  = d.rentaMensual || 0;
    // La tasa se DERIVA del dato del backend (mos.trib_resumen_mes calcula
    // ventas × 0.015). Si algún día cambia el régimen, esto lo refleja solo.
    const tasa = ventas > 0 ? (renta / ventas) * 100 : 1.5;
    const mesNom = _TRIB_MESES[(_tribState.mes || 1) - 1] + ' ' + (_tribState.anio || '');

    // Acumulado del año calendario seleccionado, desde el histórico cacheado.
    let acumTxt = 'El acumulado del año aparece cuando termine de cargar el histórico de 12 meses.';
    if (_tribHist && _tribHist.length) {
      const delAnio = _tribHist.filter(m => m.anio === _tribState.anio);
      if (delAnio.length) {
        const acum = delAnio.reduce((s, m) => s + (m.renta || 0), 0);
        const ventasAcum = delAnio.reduce((s, m) => s + (m.ventas || 0), 0);
        acumTxt = 'En ' + _tribState.anio + ' llevas <b style="color:var(--trib-renta)">' + _tribFmtSoles(acum) + '</b> ' +
                  'de pagos a cuenta sobre <b>' + _tribFmtSoles(ventasAcum) + '</b> de ventas, en ' + delAnio.length +
                  ' mes' + (delAnio.length === 1 ? '' : 'es') + ' dentro de la ventana de 12 meses.';
      }
    }

    _tribSheetAbrir('tribOvRenta', {
      icono: '🏛️',
      titulo: 'Impuesto a la renta · ' + mesNom,
      sub: 'Pago a cuenta mensual del Régimen MYPE Tributario',
      totalLbl: 'Renta del mes',
      totalVal: _tribFmtSoles(renta),
      totalColor: 'var(--trib-renta)',
      body:
        '<div class="trib-calc">' +
          '<div class="trib-calc-row"><span>Base · ventas del mes registradas</span><b>' + _tribFmtSoles(ventas) + '</b></div>' +
          '<div class="trib-calc-row"><span>Tasa aplicada · pago a cuenta MYPE</span><b>' + tasa.toFixed(2).replace(/\.?0+$/, '') + '%</b></div>' +
          '<div class="trib-calc-row total"><span>Pago a cuenta del mes</span><b>' + _tribFmtSoles(renta) + '</b></div>' +
        '</div>' +
        '<div class="trib-nota">' + acumTxt + '</div>' +
        '<div class="trib-nota">' +
          '<b style="color:var(--trib-ink1)">Qué es y qué no es.</b> Esto es el <b>pago a cuenta</b> mensual: ' +
          'el ' + tasa.toFixed(2).replace(/\.?0+$/, '') + '% de los ingresos netos del mes, que se declara con el PDT 621 junto con el IGV. ' +
          '<b>No</b> es el impuesto anual definitivo: ese se calcula sobre la utilidad del ejercicio y en la ' +
          'declaración anual se descuentan estos pagos a cuenta. ' +
          'La base que usa el panel son las ventas del mes tal como quedaron registradas en el sistema ' +
          '(<code>totalVentas</code> de <code>mos.trib_resumen_mes</code>): no descuenta notas de crédito ' +
          'ni ajustes posteriores que no hayan pasado por ahí.' +
        '</div>' +
        '<div class="trib-nota">💡 A diferencia del IGV, la renta <b style="color:var(--trib-ink1)">no se compensa</b> ' +
          'con lo que le pagas a tus proveedores: sube cuando suben tus ventas. Por eso vive en su propia card ' +
          'y en su propia franja del gráfico, con escala aparte.</div>'
    });
  }

  // ═══════════════════════════════════════════════════════════════════
  // OVERLAY 4 · VENTAS — la base sobre la que se calcula todo lo demás
  // ═══════════════════════════════════════════════════════════════════
  function tribAbrirVentas() {
    const d = _tribState.data || {};
    const ventas = d.totalVentas || 0;
    const cpeTot = d.cpeTotal || 0;
    const ticket = cpeTot > 0 ? _money(ventas / cpeTot) : 0;
    const mesNom = _TRIB_MESES[(_tribState.mes || 1) - 1] + ' ' + (_tribState.anio || '');
    const proy = _tribCalcProyeccion(d);

    _tribSheetAbrir('tribOvVentas', {
      icono: '📈',
      titulo: 'Ventas · ' + mesNom,
      sub: 'De aquí salen el IGV en contra y el pago a cuenta de renta',
      totalLbl: 'Ventas del mes',
      totalVal: _tribFmtSoles(ventas),
      totalColor: 'var(--trib-ventas)',
      body:
        '<div class="trib-calc" style="background:rgba(96,165,250,.07);border-color:rgba(96,165,250,.24)">' +
          '<div class="trib-calc-row"><span>Comprobantes emitidos del mes</span><b>' + (d.cpeEmitidos || 0) + ' de ' + cpeTot + '</b></div>' +
          '<div class="trib-calc-row"><span>Pendientes en NubeFact</span><b>' + (d.cpePendientes || 0) + '</b></div>' +
          '<div class="trib-calc-row"><span>Con error · requieren atención</span><b style="color:' + ((d.cpeErrores || 0) > 0 ? 'var(--trib-contra)' : 'var(--trib-ink1)') + '">' + (d.cpeErrores || 0) + '</b></div>' +
          '<div class="trib-calc-row"><span>Ticket promedio del mes</span><b>' + _tribFmtSoles(ticket) + '</b></div>' +
          '<div class="trib-calc-row"><span>Mes transcurrido</span><b>' + (d.pctMes || 0) + '% · día ' + (d.diaActual || 0) + ' de ' + (d.ultimoDia || 0) + '</b></div>' +
          (proy && d.pctMes < 95
            ? '<div class="trib-calc-row total" style="border-top-color:rgba(96,165,250,.3)"><span>Proyección al cierre</span>' +
              '<b style="color:var(--trib-ventas)">' + _tribFmtSoles(proy.ventasProy) + '</b></div>'
            : '') +
        '</div>' +
        '<button type="button" class="trib-chip on" style="width:100%;justify-content:center;min-height:44px" ' +
          'onclick="MOS._tribSheetCerrar(\'tribOvVentas\');MOS.tribAbrirIGVEmitido()">🧾 Ver los comprobantes uno por uno</button>' +
        '<div class="trib-nota" style="margin-top:12px">' +
          'Las ventas del mes son el total facturado que quedó registrado en el sistema. Sobre esa base salen dos cosas: ' +
          'el <b style="color:var(--trib-contra)">IGV en contra</b> (el 18% incluido en cada comprobante) y el ' +
          '<b style="color:var(--trib-renta)">pago a cuenta de renta</b>. La proyección extrapola el ritmo del mes ' +
          'a los días que faltan — es una estimación, no un dato fiscal.' +
        '</div>'
    });
  }

  // [v2.41.93] Toggle panel ayuda
  function tribToggleAyuda() {
    const p = $('tribAyuda');
    if (p) p.classList.toggle('hidden');
    _finBeep && _finBeep('click');
  }

  // [v2.41.93] Pre-carga al boot — corre en background al login
  async function _tribPrecargarBoot() {
    try {
      iconBusy('tributario', true);
      const res = await API.post('tribResumenMes', {});
      // [Lote3-A · fix M0a-MOS] API.post YA desempaqueta d.data → res = {mes, anio, ...}.
      // Antes `if (res && res.data)` saltaba TODO el bloque → el badge de alertas
      // tributarias (CPE/OCR) nunca aparecía al login + se perdía la precarga.
      const d = (res && res.data) ? res.data : res;   // tolera ambas formas
      if (d && d.mes) {
        _tribState.data = d;
        _tribState.mes  = d.mes;
        _tribState.anio = d.anio;
        // [v2.42.12] Precargar también la lista de IGV a favor del mes para que
        // el detalle abra instantáneo (sin esperar el roundtrip a WH al hacer
        // click en "Ver detalle"). Silent + fire-and-forget: no bloquea el login.
        _tribFetchIGVFavor(true);
        // Badge: si hay alertas (errores CPE u OCR), mostrar en nav
        const alertas = (d.cpeErrores || 0) + (d.guiasIlegibles || 0);
        const badge = $('tribNavBadge');
        if (badge) {
          if (alertas > 0) {
            badge.textContent = String(alertas);
            badge.classList.remove('hidden');
            badge.title = alertas + ' CPE/OCR requieren atención';
          } else {
            badge.classList.add('hidden');
          }
        }
      }
    } catch(e) {
      console.warn('[Tributario precarga]', e.message);
    } finally {
      iconBusy('tributario', false);
    }
  }

  async function _loadFinanzas() {
    const inp = $('finFecha');
    const hoy = today();
    // Al ABRIR el módulo siempre arrancamos en hoy (la fecha quedaba
    // pegada al último día que vio el usuario y el label se mostraba
    // como "—" cuando _finPL traía datos de otro día).
    if (inp) inp.value = hoy;
    const fecha = hoy;
    _finBeep('nav');
    _finUpdateBadge(fecha);  // label "🟢 Hoy · ..." al instante
    // Si los datos precargados (_finPL) son del MISMO día que hoy, los
    // pintamos al vuelo. Si son de otro día, ignoramos y refrescamos.
    // _finPL viene marcado (ver finCargar). Si no coincide con hoy → refrescar.
    if (_finPL && (_finPL._fechaStamp === fecha || _finPL.fecha === fecha)) {
      _finRender(_finPL, fecha);
      const hasta  = fecha;
      const desde7 = _fechaOffset(fecha, -6);
      try {
        const rango = await API.get('getFinanzasRango', { desde: desde7, hasta });
        _finRender7d(rango);
      } catch(_) {}
      _finPrefetchAdyacentes(fecha);
      _finStartPolling();
      return;
    }
    await finCargar();
    _finStartPolling();
  }

  // [v2.41.78] POLLING UNIFICADO — un solo intervalo cada 30s mientras
  // estamos en vista Finanzas. Antes había DOS pollings (30s + 60s) que
  // causaban 3-4 requests/min innecesarios + el parpadeo característico.
  // Ahora 1 solo refresca P&L + dispara refresh side-effects (liq) solo
  // cada 2 ticks (60s) para mantener la misma cadencia de antes en lo
  // accesorio.
  let _finPollInt = null;
  let _finPollTickCount = 0;
  function _finStartPolling() {
    _finStopPolling();
    _finPollTickCount = 0;
    _finPollInt = setInterval(() => {
      if (S.view !== 'finanzas') { _finStopPolling(); return; }
      _finPollTickCount++;
      // Refresh silencioso del día visible — sin animación. finCargar usa
      // hash rápido para detectar cambios y _finRenderPersonal usa diff
      // minimal → no parpadea si nada cambió.
      try { finCargar({ animate: false, _silent: true }); } catch(_){}
      // Cada 2 ticks (60s) refresca también liquidaciones pendientes —
      // antes esto lo hacía _finanzasRefreshSilencioso a 60s, ahora se
      // hace en el mismo tren del polling 30s. Evita duplicar intervals.
      if (_finPollTickCount % 2 === 0) {
        try {
          API.get('getLiquidacionesPendientesSemana', {}).then(r => {
            if (r) {
              try { _liqSaveCache('pendientes', r); } catch(_){}
              if (S.view === 'config' && S.cfgTab === 'personal') {
                try { _cfgRenderMeCajeros(); } catch {}
              }
            }
          }).catch(() => {});
        } catch(_){}
      }
    }, 30000);
  }
  function _finStopPolling() {
    if (_finPollInt) { clearInterval(_finPollInt); _finPollInt = null; }
    _finPollTickCount = 0;
  }

  // ── Sync / Update ────────────────────────────────────────────
  function syncApp()           { if (window._SWControl) window._SWControl.sync(); }
  function applyPendingUpdate(){ if (window._SWControl) window._SWControl.applyPending(); }

  // ════════════════════════════════════════════════════════════
  // LIQUIDACIONES v2 — pagos acumulados día a día
  // Modelo: cada día con presencia es una liquidación pendiente.
  // Admin selecciona días → "Pagar" → genera batch LIQ-XXXX por persona.
  // ════════════════════════════════════════════════════════════
  // ── [v2.41.72] Constantes y helpers compartidos ──────────────
  const Z_MODAL_BACKDROP = 9400;   // .modal-backdrop (estándar)
  const Z_MODAL_OVERLAY  = 9500;   // modales sobre otro modal (anular sobre detalle)
  const Z_MODAL_CRITICAL = 9700;   // alertas críticas (sobre todo)

  // Parser unificado de respuestas API — algunas devuelven array directo,
  // otras { ok, data }. Centraliza el unwrap.
  function _liqParseResp(res) {
    if (Array.isArray(res)) return res;
    if (res && Array.isArray(res.data)) return res.data;
    if (res && res.data && typeof res.data === 'object') return res.data;
    return res || {};
  }

  // ── [780] JANITOR de localStorage ──────────────────────────────────────────
  // MOS acumula caches POR DÍA (mos_fin_pl_/rango_/resum_/evals_ + fecha) y POR GUÍA
  // (borradores P2, latch mos_costos_aplicada_) que jamás morían: tras meses el quota
  // de ~5MB revienta → "💾 No se pudo guardar cache local (QuotaExceededError)".
  // Barre al arrancar (y en modo agresivo cuando un setItem falla por quota).
  function _lsJanitor(agresivo) {
    let borradas = 0;
    const hoy = (function(){ try { return new Date().toISOString().slice(0, 10); } catch(_) { return ''; } })();
    const kill = [];
    try {
      for (let i = 0; i < localStorage.length; i++) {
        const k = localStorage.key(i) || '';
        try {
          const mFecha = k.match(/^mos_(?:fin_pl_|fin_rango_|fin_resum_|evals_)(\d{4}-\d{2}-\d{2})$/);
          if (mFecha) { if (mFecha[1] !== hoy) kill.push(k); continue; }        // fechadas: solo vive la de HOY
          if (k.indexOf('mos_costos_aplicada_') === 0) {                        // latch por guía: 30 días
            const ts = parseInt(localStorage.getItem(k), 10) || 0;
            if (Date.now() - ts > 30 * 864e5) kill.push(k); continue;
          }
          if (k.indexOf('mos_p2_draft_') === 0) {                               // borrador P2: 7 días
            const o = JSON.parse(localStorage.getItem(k) || '{}');
            if (!o.ts || Date.now() - o.ts > 7 * 864e5) kill.push(k); continue;
          }
          if (/^mos_(liq_|alm_|pn_cache)/.test(k)) {                            // caches {ts}: 24h (agresivo: todas)
            const o = JSON.parse(localStorage.getItem(k) || '{}');
            if (agresivo || !o.ts || Date.now() - o.ts > 864e5) kill.push(k); continue;
          }
          if (agresivo && (k === 'mos_ops_det_cache_v1' || k === 'MOS_CAT_CACHE')) kill.push(k);   // re-descargables
        } catch(_) { kill.push(k); }                                            // valor corrupto → fuera
      }
    } catch(_) {}
    kill.forEach(k => { try { localStorage.removeItem(k); borradas++; } catch(_){} });
    return borradas;
  }
  try { setTimeout(() => { const n = _lsJanitor(false); if (n) console.info('[janitor] localStorage: ' + n + ' clave(s) viejas barridas'); }, 2500); } catch(_){}

  // localStorage safe: si revienta el quota, barre agresivo y REINTENTA; toast solo si aún falla
  function _liqLsSet(key, val) {
    try { localStorage.setItem(key, val); return true; }
    catch(e) {
      try {
        const n = _lsJanitor(true);                    // [780] liberar espacio y reintentar
        localStorage.setItem(key, val);
        console.info('[janitor] quota lleno → ' + n + ' claves barridas y reintento OK');
        return true;
      } catch(_) {}
      try { toast('💾 No se pudo guardar cache local (' + (e.name || 'error') + ')', 'warn', 4000); } catch(_){}
      return false;
    }
  }

  // Formato fecha corta con guard (B9)
  function _liqFmtFechaCortaSafe(fecha) {
    if (typeof _liqFmtFechaCorta === 'function') return _liqFmtFechaCorta(fecha);
    return String(fecha || '—');
  }

  // Validación rango fechas (B3)
  function _liqValidarRango(desde, hasta) {
    const re = /^\d{4}-\d{2}-\d{2}$/;
    if (!re.test(String(desde)) || !re.test(String(hasta))) return false;
    if (desde > hasta) return false;
    return true;
  }

  // AbortController activo por petición (B1)
  let _liqAbortCtrl = null;

  const _liqState = {
    tab: 'pendientes',
    desde: null,
    hasta: null,
    pendientes: [],            // array de { idPersonal, dias[], total, ... }
    pagadas: [],               // array de batches
    seleccion: {},             // { idPersonal: Set<fecha> }
    expandidos: {},            // { idPersonal: bool }
    currentPagoDet: null
  };

  // ── Cache localStorage por pestaña ──────────────────────────
  const LIQ_CACHE_PFX = 'mos_liq_';
  const LIQ_CACHE_TTL = 30 * 60 * 1000;
  function _liqSaveCache(key, data) {
    // [v2.41.72-B8] Usar helper con toast si falla quota/private mode
    _liqLsSet(LIQ_CACHE_PFX + key, JSON.stringify({ ts: Date.now(), data }));
  }
  // Pre-cargar al iniciar sesión y persistir
  // Prefetch de TODAS las tablas del módulo Configuraciones para que
  // cualquier tab abra al instante. Se ejecuta al autenticar y guarda
  // los resultados en cfgData / state cache → cuando el usuario abre la
  // pestaña, renderCfgTab encuentra datos listos y solo refresca en bg.
  function _prefetchConfigModulos() {
    if (!S.session) return;
    // Notificaciones (catálogo)
    API.get('getNotificacionesConfig', {}).then(r => {
      const arr = Array.isArray(r) ? r : ((r && r.data) || []);
      _notifState.items = arr;
      _notifState.cargado = true;
    }).catch(() => {});
    // Taxonomía (guía de categorías IA)
    API.get('getTaxonomia', {}).then(r => {
      if (Array.isArray(r)) cfgData.taxonomia = r;
    }).catch(() => {});
    // Personal (de PERSONAL_MASTER)
    API.get('getPersonalMaster', {}).then(r => {
      if (Array.isArray(r)) cfgData.personalMaster = r;
    }).catch(() => {});
    // Dispositivos (infraestructura)
    API.get('getDispositivos', {}).then(r => {
      if (Array.isArray(r)) cfgData.dispositivos = _dispAplicarShield(r);
    }).catch(() => {});
    // Zonas + Estaciones + Impresoras (infra)
    API.get('getZonas',     {}).then(r => { if (Array.isArray(r)) cfgData.zonas = r; }).catch(() => {});
    API.get('getEstaciones',{}).then(r => { if (Array.isArray(r)) cfgData.estaciones = r; }).catch(() => {});
    API.get('getImpresoras',{}).then(r => { if (Array.isArray(r)) cfgData.impresoras = r; }).catch(() => {});
  }

  function _prefetchLiquidaciones() {
    if (!S.session) return;
    iconBusy('finanzas', true);
    // ── v2: precarga del nuevo modelo (Pendientes + Pagadas) ──
    // Guarda en localStorage (mos_liq2_*) para que liqOpen pinte al instante.
    // Inline el prefijo porque _LIQ_CACHE_PFX se declara más abajo (const en TDZ).
    try {
      API.get('getLiquidacionesPendientes', {}).then(r => {
        const arr = Array.isArray(r) ? r : ((r && r.data) || []);
        try { localStorage.setItem('mos_liq2_pendientes', JSON.stringify({ ts: Date.now(), data: arr })); } catch(_){}
      }).catch(() => {});
      API.get('getLiquidacionesPagadas', {}).then(r => {
        const arr = Array.isArray(r) ? r : ((r && r.data) || []);
        try { localStorage.setItem('mos_liq2_pagadas', JSON.stringify({ ts: Date.now(), data: arr })); } catch(_){}
      }).catch(() => {});
    } catch(_){}
    Promise.all([
      API.get('getLiquidacionesPendientesSemana', {}).then(r => {
        if (r) {
          _liqSaveCache('pendientes', r);
          // Encadenar prefetch de detalles de cada persona en background
          if (r.personal && r.personal.length) {
            setTimeout(() => _prefetchDetallesLiq(r.personal), 1500);
          }
        }
      }).catch(() => {}),
      API.get('getLiquidacionesEmitidas', { estado: 'PENDIENTE' }).then(r => {
        _liqSaveCache('emitidas', r || []);
      }).catch(() => {}),
      API.get('getLiquidacionesEmitidas', { estado: 'PAGADA' }).then(r => {
        _liqSaveCache('pagadas', r || []);
      }).catch(() => {}),
      // Histórico: sin filtro (todas las emitidas, paginadas server-side)
      API.get('getLiquidacionesEmitidas', {}).then(r => {
        _liqSaveCache('historico', r || []);
      }).catch(() => {})
    ]).finally(() => iconBusy('finanzas', false));
  }

  // ════════════════════════════════════════════════════════════
  // LIQUIDACIONES v2 — implementación
  // ════════════════════════════════════════════════════════════
  function _liqMoney(n) { return 'S/' + (parseFloat(n) || 0).toFixed(2); }
  function _liqFmtFechaLarga(s) {
    if (!s) return '';
    try {
      const d = new Date(String(s).substring(0, 10) + 'T12:00:00');
      return d.toLocaleDateString('es-PE', { weekday: 'short', day: '2-digit', month: 'short' });
    } catch { return String(s); }
  }
  function _liqRolIco(rol) {
    const r = String(rol || '').toUpperCase();
    if (r === 'CAJERO' || r === 'VENDEDOR') return '🛒';
    if (r === 'ALMACENERO')                  return '🏭';
    if (r === 'ENVASADOR')                   return '🏷';
    return '👤';
  }

  // SFX reusados — usa el motor del módulo Evaluación si está disponible
  function _liqSfx(tipo) {
    if (typeof _evalSfx === 'function') _evalSfx(tipo);
  }
  function _liqRipple(ev) {
    if (typeof _evalRipple === 'function') _evalRipple(ev);
  }
  function _liqConfetti(x, y, color) {
    if (typeof _evalConfetti === 'function') _evalConfetti(x, y, color);
  }

  // Cache localStorage para apertura optimista
  const _LIQ_CACHE_PFX = 'mos_liq2_';
  const _LIQ_CACHE_TTL = 30 * 60 * 1000;
  function _liqCacheKey(tab) { return _LIQ_CACHE_PFX + tab; }
  function _liqCacheLoad(tab) {
    try {
      const raw = localStorage.getItem(_liqCacheKey(tab));
      if (!raw) return null;
      const p = JSON.parse(raw);
      if (Date.now() - (p.ts || 0) > _LIQ_CACHE_TTL) return null;
      return p.data;
    } catch { return null; }
  }
  function _liqCacheSave(tab, data) {
    // [v2.41.72-B8] usar helper con feedback
    _liqLsSet(_liqCacheKey(tab), JSON.stringify({ ts: Date.now(), data }));
  }
  function _liqCacheClear() {
    try {
      localStorage.removeItem(_liqCacheKey('pendientes'));
      localStorage.removeItem(_liqCacheKey('pagadas'));
    } catch(_){}
  }

  async function liqOpen() {
    _liqState.tab = 'pendientes';
    // [dueño 2.43.632] SIEMPRE entra LIMPIO: no restaurar la selección persistida (evita
    // que al reabrir/refrescar quede marcado lo último y se cruce con datos viejos). La
    // selección vive solo en memoria durante la sesión (sobrevive el polling, no el reopen).
    _liqState.seleccion = {};
    try { localStorage.removeItem('mos_liq_seleccion'); } catch(_){}
    _liqState.filtroPersonas = _liqLoadFiltroPersonas();
    _liqState.expandidos = {};
    // ⚡ Materializado: backend lee directo de LIQUIDACIONES_DIA, podemos
    // pedir 30 días sin penalización
    var hoy = _liqHoy();
    _liqState.hasta = hoy;
    _liqState.desde = _liqOffset(hoy, -29);
    openModal('modalLiquidaciones');
    _liqSfx('open');
    _liqSetSyncState('idle');
    _liqRenderRangoPresets();
    // Pintar desde cache instantáneamente si existe
    const cached = _liqCacheLoad('pendientes');
    if (cached) {
      _liqState.pendientes = cached;
      _liqRenderPendientes();
      _liqUpdatePayBar();
    }
    await liqLoadCurrent();
    // 🚀 Prefetch Historial (pagadas) en background — al cambiar tab será
    // instantáneo. No bloquea la UI del tab actual.
    _liqPrefetchTab('pagadas');
    // [v2.41.58] Polling background cada 30s mientras el modal esté abierto
    _liqStartPolling();
  }

  // [v2.41.74] Indicador visual de sincronización (header dot)
  function _liqSetSyncState(estado) {
    const el = document.getElementById('liqSyncDot');
    if (!el) return;
    el.classList.remove('is-loading', 'is-error');
    if (estado === 'loading') { el.classList.add('is-loading'); el.textContent = 'sync'; el.title = 'Refrescando datos…'; }
    else if (estado === 'error') { el.classList.add('is-error'); el.textContent = 'err'; el.title = 'Error al sincronizar — reintenta con ↻'; }
    else { el.textContent = 'live'; el.title = 'Sincronizado · auto-refresh cada 30s'; }
  }

  // [v2.41.58] Polling bg 30s — refresca SOLO el tab actual sin parpadeo.
  // El render tiene guard interno por tab → si user cambió de tab durante
  // el fetch, la respuesta vieja se descarta. Cada respuesta repinta solo
  // si la firma de datos cambió (anti-flicker).
  let _liqPollInt = null;
  let _liqEscHandler = null;
  function _liqStartPolling() {
    _liqStopPolling();
    _liqPollInt = setInterval(() => {
      const modal = document.getElementById('modalLiquidaciones');
      if (!modal || modal.classList.contains('hidden')) {
        _liqStopPolling();
        return;
      }
      // Silent refresh: re-fetch tab actual sin animación
      liqLoadCurrent();
      // También refresh vetadas si está cargado
      if (_liqState.vetadas) _liqCargarVetadas();
    }, 30000);
    // [v2.41.72-B10] Escape key también para de polling sin esperar el check
    _liqEscHandler = (e) => {
      if (e.key === 'Escape' || e.keyCode === 27) {
        const modal = document.getElementById('modalLiquidaciones');
        if (modal && !modal.classList.contains('hidden')) {
          liqClose();
        }
      }
    };
    document.addEventListener('keydown', _liqEscHandler);
  }
  function _liqStopPolling() {
    if (_liqPollInt) { clearInterval(_liqPollInt); _liqPollInt = null; }
    if (_liqEscHandler) { document.removeEventListener('keydown', _liqEscHandler); _liqEscHandler = null; }
    if (_liqAbortCtrl) { try { _liqAbortCtrl.abort(); } catch(_){} _liqAbortCtrl = null; }
  }

  // Prefetch silencioso del tab no activo. Si ya hay cache fresh o state
  // poblado, no hace nada. Si falla, no muestra error — solo deja el tab
  // sin cache (cuando el user vaya, hará fetch normal).
  function _liqPrefetchTab(tab) {
    try {
      // Si ya tenemos el state poblado, no re-fetch
      if (tab === 'pendientes' && _liqState.pendientes && _liqState.pendientes.length) return;
      if (tab === 'pagadas'   && _liqState.pagadas    && _liqState.pagadas.length)    return;
      // Si hay cache fresh, hidratar state y no fetch
      const cached = _liqCacheLoad(tab);
      if (cached) {
        if (tab === 'pendientes') _liqState.pendientes = cached;
        else if (tab === 'pagadas') _liqState.pagadas = cached;
        return;
      }
      // Fetch silencioso — no bloquea
      const params = tab === 'pendientes'
        ? { desde: _liqState.desde, hasta: _liqState.hasta }
        : { desde: _liqOffset(_liqHoy(), -89), hasta: _liqHoy() };
      const endpoint = tab === 'pendientes' ? 'getLiquidacionesPendientes' : 'getLiquidacionesPagadas';
      const ms = tab === 'pendientes' ? 15000 : 30000;
      _liqFetchConTimeout(endpoint, params, ms).then(res => {
        const arr = _liqParseResp(res);
        const list = Array.isArray(arr) ? arr : (arr.data || []);
        if (tab === 'pendientes') _liqState.pendientes = list;
        else if (tab === 'pagadas') _liqState.pagadas = list;
        _liqCacheSave(tab, list);
      }).catch(err => {
        // [v2.41.72-B5] Log silencioso pero visible en consola — antes era
        // catch(()=>{}) y el prefetch fallaba sin rastro alguno.
        console.warn('[liqPrefetchTab ' + tab + '] fallo:', err && err.message || err);
      });
    } catch(_) { /* tolerar */ }
  }

  // Cargar más días: extender el rango hacia atrás (acumular días viejos)
  function _diff(d1, d2) {
    try {
      const a = new Date(d1 + 'T12:00:00').getTime();
      const b = new Date(d2 + 'T12:00:00').getTime();
      return Math.round((b - a) / 86400000);
    } catch { return 0; }
  }

  function liqClose() {
    _liqState.seleccion = {};
    _liqStopPolling();
    closeModal('modalLiquidaciones');
  }

  function liqSetTab(tab) {
    if (_liqState.tab === tab) return;
    _liqState.tab = tab;
    _liqState.seleccion = {};
    document.querySelectorAll('#modalLiquidaciones .liq-tab').forEach(el => {
      el.classList.toggle('active', el.dataset.liqtab === tab);
    });
    // [v2.41.38] Mostrar/ocultar barra de filtro por persona según tab
    const filtroBar = document.getElementById('liqFiltroBar');
    if (filtroBar) filtroBar.style.display = (tab === 'pendientes') ? 'block' : 'none';
    _liqUpdatePayBar();
    _liqSfx('switch');

    // 🚀 INSTANTÁNEO: si ya tenemos data en state (prefetched o cacheado),
    // pintar de una vez SIN esperar fetch. Antes el cambio de tab Historial→
    // Pendientes "se colgaba" 10-15s esperando getLiquidacionesPendientes
    // aunque la data ya estuviera en cache localStorage.
    const body = $('liqBody');
    if (body) body.dataset._hasCache = '';
    let pintadoInstantaneo = false;
    if (tab === 'pendientes') {
      const datos = (_liqState.pendientes && _liqState.pendientes.length)
        ? _liqState.pendientes
        : _liqCacheLoad('pendientes');
      if (datos) {
        _liqState.pendientes = datos;
        _liqRenderPendientes();
        if (body) body.dataset._hasCache = '1';
        pintadoInstantaneo = true;
      }
    } else if (tab === 'pagadas') {
      const datos = (_liqState.pagadas && _liqState.pagadas.length)
        ? _liqState.pagadas
        : _liqCacheLoad('pagadas');
      if (datos) {
        _liqState.pagadas = datos;
        _liqRenderPagadas();
        if (body) body.dataset._hasCache = '1';
        pintadoInstantaneo = true;
      }
    }

    // [v2.41.39] Si NO se pintó instantáneo, limpiar el body para evitar
    // que se vea data del tab anterior mientras se hace el fetch.
    if (!pintadoInstantaneo && body) {
      body.innerHTML = '<div class="text-xs text-slate-500 italic text-center py-6">Cargando...</div>';
    }

    // Fetch fresco (en background si pintamos instantáneamente, foreground si no)
    liqLoadCurrent();

    // Prefetch del tab opuesto para que la siguiente navegación también
    // sea instantánea.
    const opuesto = tab === 'pendientes' ? 'pagadas' : (tab === 'pagadas' ? 'pendientes' : null);
    if (opuesto) _liqPrefetchTab(opuesto);
  }

  function liqRefresh() {
    _liqSfx('tap');
    liqLoadCurrent();
  }

  // ── Rango de fechas ──
  function _liqHoy() {
    const d = new Date();
    return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
  }
  function _liqOffset(fecha, dias) {
    const d = new Date(fecha + 'T12:00:00');
    d.setDate(d.getDate() + dias);
    return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
  }
  function _liqLunes(fecha) {
    const d = new Date(fecha + 'T12:00:00');
    const dia = d.getDay() || 7; // dom=7
    d.setDate(d.getDate() - (dia - 1));
    return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
  }
  function _liqRangoPreset(preset, soloSetState) {
    const hoy = _liqHoy();
    let desde = hoy, hasta = hoy;
    if (preset === 'hoy') { desde = hoy; hasta = hoy; }
    else if (preset === 'semana')   { desde = _liqLunes(hoy); hasta = _liqOffset(desde, 6); }
    else if (preset === 'quincena') { desde = _liqOffset(hoy, -14); hasta = hoy; }
    else if (preset === 'mes') {
      const d = new Date(hoy + 'T12:00:00');
      desde = d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-01';
      hasta = hoy;
    }
    _liqState.desde = desde;
    _liqState.hasta = hasta;
    if (!soloSetState) {
      _liqSyncRangoInputs();
      _liqSfx('tap');
      liqLoadCurrent();
    }
  }
  function _liqSyncRangoInputs() {
    const d = $('liqRangoDesde'); if (d) d.value = _liqState.desde || '';
    const h = $('liqRangoHasta'); if (h) h.value = _liqState.hasta || '';
  }

  // Helper: race API.get contra un timeout para que la UI no se quede eternamente cargando
  function _liqFetchConTimeout(endpoint, params, ms) {
    return Promise.race([
      API.get(endpoint, params || {}),
      new Promise((_, reject) => setTimeout(() => reject(new Error('Timeout — el backend está tardando demasiado')), ms || 60000))
    ]);
  }

  // ── Carga + render ──
  async function liqLoadCurrent() {
    const body = $('liqBody');
    if (!body) return;
    const tabActual = _liqState.tab;
    // Si NO hay cache previo pintado, mostrar skeleton premium con shimmer.
    // Si SÍ hay → no parpadeo.
    if (!_liqState.pendientes || !_liqState.pendientes.length) {
      if (tabActual === 'pendientes' && !body.dataset._hasCache) {
        body.innerHTML = `
          <div class="liq-skel-stage">
            <div class="liq-skel-row"></div>
            <div class="liq-skel-row" style="animation-delay: 0.12s"></div>
            <div class="liq-skel-row" style="animation-delay: 0.24s"></div>
            <div class="liq-skel-row" style="animation-delay: 0.36s"></div>
            <div class="liq-skel-stage-hint">
              <span class="liq-skel-hint-dot"></span>
              Sincronizando liquidaciones...
            </div>
          </div>`;
      } else if (tabActual === 'pagadas' && !body.dataset._hasCache) {
        body.innerHTML = `
          <div class="liq-skel-stage">
            <div class="liq-skel-card"></div>
            <div class="liq-skel-card" style="animation-delay: 0.14s"></div>
            <div class="liq-skel-card" style="animation-delay: 0.28s"></div>
            <div class="liq-skel-stage-hint">
              <span class="liq-skel-hint-dot"></span>
              Cargando historial de pagos...
            </div>
          </div>`;
      }
    }
    // [v2.41.72-B1] Token único por llamada. Si otra llamada se dispara
    // (polling + click manual), solo la última gana — evita race conditions
    // donde una respuesta vieja pinta sobre datos frescos del mismo tab.
    const _myToken = (window._liqLoadToken = (window._liqLoadToken || 0) + 1);
    _liqSetSyncState('loading');
    try {
      if (tabActual === 'pendientes') {
        const res = await _liqFetchConTimeout('getLiquidacionesPendientes', { desde: _liqState.desde, hasta: _liqState.hasta }, 15000);
        if (_liqState.tab !== tabActual || _myToken !== window._liqLoadToken) return;
        const arr = _liqParseResp(res);
        const list = Array.isArray(arr) ? arr : (arr.data || []);
        _liqState.pendientes = list;
        _liqCacheSave('pendientes', list);
        body.dataset._hasCache = '1';
        _liqRenderPendientes();
      } else if (tabActual === 'pagadas') {
        const res = await _liqFetchConTimeout('getLiquidacionesPagadas', { desde: _liqOffset(_liqHoy(), -89), hasta: _liqHoy() }, 30000);
        if (_liqState.tab !== tabActual || _myToken !== window._liqLoadToken) return;
        const arr = _liqParseResp(res);
        const list = Array.isArray(arr) ? arr : (arr.data || []);
        _liqState.pagadas = list;
        _liqCacheSave('pagadas', list);
        _liqRenderPagadas();
      } else if (tabActual === 'resumen') {
        _liqRenderResumen();
      }
    } catch(e) {
      _liqSetSyncState('error');
      // Si ya había datos pintados (de cache), mantenerlos y solo mostrar toast
      if (body.dataset._hasCache) {
        toast('⚠ ' + (e.message || 'Error de red, mostrando cache'), 'error');
      } else {
        body.innerHTML = `<div class="text-center py-10">
          <div class="text-3xl mb-2 opacity-50">⚠</div>
          <div class="text-sm text-rose-400 mb-2">${e.message || e}</div>
          <button onclick="MOS.liqRefresh()" class="btn-primary btn-ripple text-xs px-4 py-2 mt-2">↻ Reintentar</button>
        </div>`;
      }
      _liqUpdatePayBar();
      return;
    }
    _liqSetSyncState('idle');
    _liqUpdatePayBar();
  }

  // ── Render PENDIENTES ──
  function _liqRenderPendientes() {
    const body = $('liqBody');
    if (!body) return;
    const all = _liqState.pendientes || [];
    // [v2.41.38] Renderizar chips de personas SIEMPRE (aunque haya 0 después de filtrar)
    _liqRenderFiltroChips(all);
    if (!all.length) {
      body.innerHTML = `<div class="liq-empty">
        <div class="liq-empty-emoji">🎉</div>
        <div class="text-sm">Todo al día</div>
        <div class="text-xs text-slate-600 mt-1">No hay liquidaciones pendientes.</div>
        <div class="text-[10px] text-slate-700 mt-3">¿Primera vez con el módulo? Ve a <strong>📊 Resumen</strong> → <strong>🔧 Inicializar Liquidación Diaria</strong></div>
      </div>`;
      return;
    }
    // [v2.41.38] Aplicar filtro de personas si hay activo
    const filtroSel = _liqState.filtroPersonas;
    const list = (filtroSel && filtroSel.size > 0)
      ? all.filter(p => filtroSel.has(p.idPersonal))
      : all;
    // [500x] contar nombres repetidos en TODO el set (no solo el filtrado) para el chip 🔗
    _liqDupNames = {};
    (all || []).forEach(p => {
      const n = String(p.nombre || '').toLowerCase().trim().normalize('NFD').replace(/[̀-ͯ]/g, '');
      if (n) _liqDupNames[n] = (_liqDupNames[n] || 0) + 1;
    });
    if (!list.length) {
      body.innerHTML = `<div class="liq-empty">
        <div class="liq-empty-emoji">🔍</div>
        <div class="text-sm">Sin resultados para el filtro</div>
        <div class="text-xs text-slate-600 mt-1">Toca el chip para quitar el filtro</div>
      </div>`;
      return;
    }
    const totalGeneral = list.reduce((s, p) => s + p.total, 0);
    const totalDias = list.reduce((s, p) => s + p.cantidadDias, 0);
    // [dueño] adeudado NETO = bruto − consumo de todos los días pendientes (líquido real)
    const consGeneral = Math.round(list.reduce((s, p) => s + (p.dias || []).reduce((a, d) => a + (parseFloat(d.consumoDia && d.consumoDia.total) || 0), 0), 0) * 100) / 100;
    const netoGeneral = Math.round((totalGeneral - consGeneral) * 100) / 100;
    // [v2.41.74] Estado de selección global → botón ☑ TODOS / ✕ Limpiar
    let totalSel = 0;
    list.forEach(p => {
      const sel = _liqState.seleccion[p.idPersonal];
      if (sel && sel.size) totalSel += sel.size;
    });
    const todoSeleccionado = totalSel === totalDias && totalDias > 0;
    const btnGlobal = todoSeleccionado
      ? `<button class="liq-select-all-global" onclick="MOS._liqDeseleccionarTodoRango()" title="Limpiar selección">✕ Limpiar selección (${totalSel})</button>`
      : `<button class="liq-select-all-global" onclick="MOS._liqSeleccionarTodoRango()" title="Seleccionar todos los días visibles">☑ Marcar TODOS los días (${totalDias})</button>`;
    body.innerHTML = `
      <div class="flex items-center justify-between gap-2 mb-3 pb-2 border-b border-slate-800 flex-wrap">
        <div class="text-xs text-slate-400">
          <strong class="text-amber-400">${list.length}</strong> persona${list.length !== 1 ? 's' : ''} ·
          <strong class="text-amber-400">${totalDias}</strong> día${totalDias !== 1 ? 's' : ''}
        </div>
        ${btnGlobal}
        <div class="text-right ml-auto">
          <div class="text-[10px] uppercase text-slate-400 tracking-wider">Adeudado neto</div>
          <div class="text-lg font-black" style="color:#34d399">${_liqMoney(netoGeneral)}</div>
          ${consGeneral > 0 ? `<div class="text-[9px] font-bold text-amber-400" title="Consumo a crédito de todo lo pendiente, ya descontado">−${_liqMoney(consGeneral)} consumo · de ${_liqMoney(totalGeneral)}</div>` : ''}
        </div>
      </div>
      ${list.map((p, i) => _liqCardPersona(p, i)).join('')}
    `;
  }

  // [v2.41.74] Selección global — marcar/limpiar TODOS los días visibles
  function _liqSeleccionarTodoRango() {
    const all = _liqState.pendientes || [];
    const filtroSel = _liqState.filtroPersonas;
    const list = (filtroSel && filtroSel.size > 0) ? all.filter(p => filtroSel.has(p.idPersonal)) : all;
    list.forEach(p => {
      _liqState.seleccion[p.idPersonal] = new Set(p.dias.map(d => d.fecha));
    });
    _liqSaveSeleccion();
    _liqSfx('add');
    _liqRenderPendientes();
    _liqUpdatePayBar();
  }
  function _liqDeseleccionarTodoRango() {
    _liqState.seleccion = {};
    _liqSaveSeleccion();
    _liqSfx('remove');
    _liqRenderPendientes();
    _liqUpdatePayBar();
  }

  // [v2.41.74] Render chips presets de rango (siempre visibles)
  function _liqRenderRangoPresets() {
    const cont = document.getElementById('liqRangoPresets');
    if (!cont) return;
    const hoy = _liqHoy();
    const presets = [
      { id: 'hoy',      label: '📅 Hoy',     desde: hoy, hasta: hoy },
      { id: 'semana',   label: '📆 Semana',  desde: _liqLunes(hoy), hasta: _liqOffset(_liqLunes(hoy), 6) },
      { id: 'quincena', label: '🗓 15 días', desde: _liqOffset(hoy, -14), hasta: hoy },
      { id: 'mes30',    label: '📊 30 días', desde: _liqOffset(hoy, -29), hasta: hoy },
      { id: 'mes',      label: '📅 Mes',     desde: (function(){ const d = new Date(hoy + 'T12:00:00'); return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-01'; })(), hasta: hoy }
    ];
    cont.innerHTML = presets.map(p => {
      const isAct = _liqState.desde === p.desde && _liqState.hasta === p.hasta;
      return `<div class="liq-rango-preset-chip${isAct ? ' is-active' : ''}"
                   onclick="MOS._liqAplicarRangoPreset('${p.id}')">${p.label}</div>`;
    }).join('');
  }
  function _liqAplicarRangoPreset(id) {
    const hoy = _liqHoy();
    let desde = hoy, hasta = hoy;
    if (id === 'hoy') { desde = hoy; hasta = hoy; }
    else if (id === 'semana')   { desde = _liqLunes(hoy); hasta = _liqOffset(desde, 6); }
    else if (id === 'quincena') { desde = _liqOffset(hoy, -14); hasta = hoy; }
    else if (id === 'mes30')    { desde = _liqOffset(hoy, -29); hasta = hoy; }
    else if (id === 'mes') {
      const d = new Date(hoy + 'T12:00:00');
      desde = d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-01';
      hasta = hoy;
    }
    if (_liqState.desde === desde && _liqState.hasta === hasta) return;
    _liqState.desde = desde; _liqState.hasta = hasta;
    _liqSfx('tap');
    try { _liqCacheClear(); } catch(_){}
    _liqRenderRangoPresets();
    liqLoadCurrent();
  }

  // [v2.41.38] Render chips de filtro por persona — multi-select.
  // Muestra avatar (iniciales) + nombre + badge con N días.
  function _liqRenderFiltroChips(all) {
    // [v2.41.74] Re-render rango presets si cambió
    _liqRenderRangoPresets();
    const cont = document.getElementById('liqFiltroChips');
    if (!cont) return;
    if (_liqState.tab !== 'pendientes' || !all.length) {
      cont.innerHTML = '';
      cont.style.display = 'none';
      return;
    }
    cont.style.display = 'flex';
    _liqState.filtroPersonas = _liqState.filtroPersonas || new Set();
    const sel = _liqState.filtroPersonas;
    // Ordenar por mayor cantidad de días primero
    const ordenadas = [...all].sort((a, b) => b.cantidadDias - a.cantidadDias);
    const iniciales = (nom) => {
      const partes = String(nom || '').trim().split(/\s+/);
      return ((partes[0]?.[0] || '?') + (partes[1]?.[0] || '')).toUpperCase();
    };
    const chips = ordenadas.map(p => {
      const isAct = sel.has(p.idPersonal);
      const idEsc = _escapeHtml(p.idPersonal).replace(/'/g, "\\'");
      return `<div class="liq-chip-persona${isAct ? ' is-active' : ''}"
                   onclick="MOS._liqToggleFiltroPersona('${idEsc}')"
                   title="${_escapeHtml(p.nombre)} · ${p.cantidadDias} día(s) · ${_liqMoney(p.total)}">
                <span class="liq-chip-avatar">${_escapeHtml(iniciales(p.nombre))}</span>
                <span class="liq-chip-nombre">${_escapeHtml(p.nombre.split(' ')[0] || p.nombre)}</span>
                <span class="liq-chip-badge">${p.cantidadDias}</span>
              </div>`;
    }).join('');
    const clearBtn = sel.size > 0
      ? `<div class="liq-chip-clear" onclick="MOS._liqLimpiarFiltroPersonas()" title="Quitar filtro">✕ limpiar (${sel.size})</div>`
      : '';
    cont.innerHTML = chips + clearBtn;
  }

  // [B7] Persistir filtroPersonas en localStorage para sobrevivir polling
  function _liqSaveFiltroPersonas() {
    try {
      const arr = Array.from(_liqState.filtroPersonas || []);
      _liqLsSet('mos_liq_filtro_personas', JSON.stringify(arr));
    } catch(_){}
  }
  function _liqLoadFiltroPersonas() {
    try {
      const raw = localStorage.getItem('mos_liq_filtro_personas');
      if (!raw) return new Set();
      return new Set(JSON.parse(raw));
    } catch(_) { return new Set(); }
  }
  function _liqToggleFiltroPersona(idPersonal) {
    _liqState.filtroPersonas = _liqState.filtroPersonas || new Set();
    if (_liqState.filtroPersonas.has(idPersonal)) {
      _liqState.filtroPersonas.delete(idPersonal);
    } else {
      _liqState.filtroPersonas.add(idPersonal);
    }
    _liqSaveFiltroPersonas();
    try { _liqSfx('tap'); } catch(_){}
    _liqRenderPendientes();
  }

  function _liqLimpiarFiltroPersonas() {
    _liqState.filtroPersonas = new Set();
    _liqSaveFiltroPersonas();
    try { _liqSfx('tap'); } catch(_){}
    _liqRenderPendientes();
  }

  let _liqDupNames = {};   // [500x] nombre normalizado → # de filas, para el chip 🔗 en Liquidaciones
  function _liqCardPersona(p, idx) {
    const expandido = _liqState.expandidos[p.idPersonal] !== false; // default abierto
    const sel = _liqState.seleccion[p.idPersonal] || new Set();
    // [dueño 2.43.632] contar SOLO los días válidos (que existen en pendientes), no la
    // selección cruda → si un día se pagó/cambió, el conteo no queda inflado.
    const selDias = p.dias.filter(d => sel.has(d.fecha)).length;
    const todoSelec = selDias === p.dias.length && selDias > 0;
    const subtotalSel = p.dias.filter(d => sel.has(d.fecha)).reduce((s,d) => s + d.totalDia, 0);
    // [422] consumo a crédito de los días SELECCIONADOS (o de todos si no hay selección)
    // → el admin ve el neto que realmente saldrá de caja antes de confirmar.
    const _consSel = (selDias > 0 ? p.dias.filter(d => sel.has(d.fecha)) : p.dias)
      .reduce((s, d) => s + (parseFloat(d.consumoDia && d.consumoDia.total) || 0), 0);
    const _consR = Math.round(_consSel * 100) / 100;
    const ico = _liqRolIco(p.rol);
    const cardCls = selDias > 0 ? ' has-selection' : '';
    // [500x · chip 🔗 en Liquidaciones] el mismo nombre en >1 fila (mismo movido de zona / dos
    // personas) → el admin decide antes de pagar. Nombre escapado (XSS).
    const _lqNorm = String(p.nombre || '').toLowerCase().trim().normalize('NFD').replace(/[̀-ͯ]/g, '');
    const _lqN = _liqDupNames[_lqNorm] || 0;
    const dupChip = _lqN > 1
      ? `<span class="badge-rol" style="background:rgba(245,158,11,.14);color:#fbbf24;border:1px solid rgba(245,158,11,.4)" title="⚠ &quot;${_escapeHtml(p.nombre)}&quot; aparece en ${_lqN} filas (¿mismo movido de zona? ¿dos personas?). Decide antes de pagar: sanción-base o pagar ambas.">🔗 ${_lqN}× ⚠</span>`
      : '';
    return `
      <div class="liq-pers-card${cardCls}" data-pers="${p.idPersonal}" style="--i:${Math.min(idx, 18)}">
        <div class="flex items-center gap-3 cursor-pointer" onclick="MOS._liqTogglePersona('${p.idPersonal}', event)">
          <span style="font-size:22px">${ico}</span>
          <div class="flex-1 min-w-0">
            <div class="flex items-center gap-2 flex-wrap">
              <div class="font-semibold text-slate-100 text-sm truncate">${_escapeHtml(p.nombre)}</div>
              <span class="text-[10px] uppercase tracking-wider text-slate-500">${_escapeHtml(p.rol)}</span>
              ${dupChip}
            </div>
            <div class="text-xs text-slate-500 mt-0.5">
              <strong class="text-amber-400">${p.cantidadDias}</strong> día(s) sin pagar
              ${selDias > 0 ? ` · <strong style="color:#34d399">${selDias} seleccionado(s)</strong>` : ''}
            </div>
          </div>
          <div class="text-right">
            ${selDias > 0
              ? `<div class="text-[10px] uppercase text-emerald-400 font-bold tracking-wider">Neto a pagar</div>
                 <div class="text-lg font-black" style="color:#34d399">${_liqMoney(Math.round((subtotalSel - _consR) * 100) / 100)}</div>
                 ${_consR > 0 ? `<div class="text-[9px] font-bold" style="color:#fbbf24" title="Consumo a crédito de los días seleccionados, ya descontado del neto">−${_liqMoney(_consR)} consumo · de ${_liqMoney(subtotalSel)}</div>` : `<div class="text-[9px] text-slate-400">${selDias} día(s)</div>`}`
              : `<div class="text-[10px] uppercase ${_consR > 0 ? 'text-emerald-400' : 'text-slate-400'} font-bold tracking-wider">${_consR > 0 ? 'Neto' : 'Total'}</div>
                 <div class="text-lg font-black" style="color:${_consR > 0 ? '#34d399' : '#fbbf24'}">${_liqMoney(Math.round((p.total - _consR) * 100) / 100)}</div>
                 ${_consR > 0 ? `<div class="text-[9px] font-bold" style="color:#fbbf24" title="Consumo a crédito del período, ya descontado del neto">−${_liqMoney(_consR)} consumo · de ${_liqMoney(p.total)}</div>` : ''}`
            }
          </div>
          <span style="color:#64748b;font-size:14px;transition:transform .25s">${expandido ? '▾' : '▸'}</span>
        </div>
        ${expandido ? `
          <div class="mt-2 pt-2 border-t border-slate-800">
            <label class="flex items-center gap-2 text-xs text-slate-400 cursor-pointer mb-2 select-none">
              <input type="checkbox" class="liq-check-master" ${todoSelec ? 'checked' : ''}
                     onchange="MOS._liqToggleAll('${p.idPersonal}', this.checked)">
              <span>Seleccionar todos los días</span>
            </label>
            ${p.dias.map(d => _liqDiaRow(p.idPersonal, d, sel.has(d.fecha))).join('')}
          </div>
        ` : ''}
      </div>`;
  }

  function _liqDiaRow(idPersonal, d, isSelected) {
    const fechaCorta = _liqFmtFechaLarga(d.fecha);
    const audCls = d.auditado ? 'aud-ok' : 'no-aud';
    const sel = isSelected ? ' selected' : '';
    // Línea sub: componentes del totalDia
    // [572] CADA CONCEPTO en su propio chip, separado en ingresos (+) y descuentos (−).
    // Incluye la bonificación manual (antes NO se mostraba en la fila).
    const _chip = (txt, col, bg, title) => `<span ${title ? `title="${_escapeHtml(title)}"` : ''} style="display:inline-block;padding:1px 6px;border-radius:5px;font-size:9.5px;font-weight:600;color:${col};background:${bg};white-space:nowrap">${txt}</span>`;
    const _ing = [], _des = [];
    if (d.montoBase    > 0) _ing.push(_chip(`jornal ${d.montoBase.toFixed(2)}`,      '#93c5fd', 'rgba(59,130,246,.12)'));
    if (d.pagoEnvasado > 0) {
      // [572] 🤝 si hay parte colaborativa (pago_envasado_colab>0) el envasado es COMPARTIDO
      // (colaboración 50/50). Tooltip con el/los nombre(s) del colaborador si el backend los trae.
      const _envColab = parseFloat(d.pagoEnvasadoColab) || 0;
      const _colabNom = Array.isArray(d.envasadoColaboradores) ? d.envasadoColaboradores.filter(Boolean) : [];
      const _envTxt = _envColab > 0 ? `+envasar ${d.pagoEnvasado.toFixed(2)} 🤝` : `+envasar ${d.pagoEnvasado.toFixed(2)}`;
      const _envTit = _envColab > 0 ? ('Envasado compartido (colaboración 50/50)' + (_colabNom.length ? ' · con ' + _colabNom.join(', ') : '')) : '';
      _ing.push(_chip(_envTxt, '#c4b5fd', 'rgba(139,92,246,.14)', _envTit));
    }
    if (d.bonoMeta     > 0) _ing.push(_chip(`+meta ${d.bonoMeta.toFixed(2)}`,        '#6ee7b7', 'rgba(16,185,129,.14)'));
    if (d.bonificacion > 0) _ing.push(_chip(`+bono ${d.bonificacion.toFixed(2)}`,    '#6ee7b7', 'rgba(16,185,129,.14)'));
    if (d.sancion      > 0) _des.push(_chip(`−sanción ${d.sancion.toFixed(2)}`,      '#fca5a5', 'rgba(239,68,68,.14)'));
    // [422/572] consumo a crédito de ESE día → se descuenta AUTOMÁTICO al confirmar (server-truth, autoConsumos).
    const _cons = parseFloat(d.consumoDia && d.consumoDia.total) || 0;
    if (_cons > 0) _des.push(_chip(`−consumo ${_cons.toFixed(2)} 🤖`, '#fcd34d', 'rgba(245,158,11,.14)'));
    const _netoDia = Math.round((d.totalDia - _cons) * 100) / 100;
    const _chips = _ing.concat(_des);
    return `
      <div class="liq-dia-row ${audCls}${sel}" data-row-key="${idPersonal}|${d.fecha}">
        <input type="checkbox" class="liq-check" ${isSelected ? 'checked' : ''}
               onchange="MOS._liqToggleDia('${idPersonal}', '${d.fecha}', this.checked, event)">
        <div class="flex-1 min-w-0">
          <div class="text-xs text-slate-200 font-medium">${fechaCorta}
            ${d.auditado ? '<span class="text-[9px] text-emerald-400 ml-1">✓ auditado</span>' : '<span class="text-[9px] text-amber-400 ml-1">⚠ sin auditar</span>'}
          </div>
          ${_chips.length ? `<div class="mt-1 flex flex-wrap gap-1">${_chips.join('')}</div>` : ''}
        </div>
        <div class="text-right shrink-0">
          ${_des.length
            ? `<div class="text-sm font-bold" style="color:#34d399">${_liqMoney(_netoDia)}</div>
               <div class="text-[9px] text-slate-400" title="Total del día antes de descuentos">de ${_liqMoney(d.totalDia)}</div>`
            : `<div class="text-sm font-bold text-amber-400">${_liqMoney(d.totalDia)}</div>`}
        </div>
        <button onclick="event.stopPropagation();MOS._liqEditarDia('${idPersonal}', '${d.fecha}')"
                class="text-[11px] font-semibold px-3 py-1.5 rounded-lg transition-all hover:opacity-80 shrink-0"
                style="background:#3f8cff;color:#fff;border:none"
                aria-label="Auditar: registrar bonos y descuentos, ver progreso">Auditar</button>
        <button onclick="event.stopPropagation();MOS._liqConfirmarVetar('${idPersonal}', '${d.fecha}')"
                class="text-[11px] font-semibold px-3 py-1.5 rounded-lg transition-all hover:opacity-80 shrink-0"
                style="background:transparent;color:#f87171;border:1px solid rgba(248,113,113,.45)"
                title="Vetar: marca este día NO pagable (reversible con Desvetar)">Vetar</button>
      </div>`;
  }

  function _liqTogglePersona(idPersonal, ev) {
    // Si el click fue en un input/button interno, no togglear
    if (ev && ev.target.closest('input, button')) return;
    _liqState.expandidos[idPersonal] = !(_liqState.expandidos[idPersonal] !== false); // toggle
    _liqSfx(_liqState.expandidos[idPersonal] ? 'expand' : 'collapse');
    _liqRenderPendientes();
  }

  // [B2] Persistir selección en localStorage para sobrevivir polling 30s
  function _liqSaveSeleccion() {
    try {
      const obj = {};
      Object.keys(_liqState.seleccion || {}).forEach(k => {
        obj[k] = Array.from(_liqState.seleccion[k] || []);
      });
      _liqLsSet('mos_liq_seleccion', JSON.stringify(obj));
    } catch(_){}
  }
  function _liqLoadSeleccion() {
    try {
      const raw = localStorage.getItem('mos_liq_seleccion');
      if (!raw) return {};
      const obj = JSON.parse(raw);
      const out = {};
      Object.keys(obj).forEach(k => { out[k] = new Set(obj[k] || []); });
      return out;
    } catch(_) { return {}; }
  }
  function _liqToggleDia(idPersonal, fecha, checked, ev) {
    if (!_liqState.seleccion[idPersonal]) _liqState.seleccion[idPersonal] = new Set();
    const set = _liqState.seleccion[idPersonal];
    if (checked) set.add(fecha); else set.delete(fecha);
    _liqSaveSeleccion();
    if (set.size === 0) delete _liqState.seleccion[idPersonal];
    _liqSfx('tap');
    _liqRenderPendientes();
    _liqUpdatePayBar();
  }

  function _liqToggleAll(idPersonal, checked) {
    const p = _liqState.pendientes.find(x => x.idPersonal === idPersonal);
    if (!p) return;
    if (checked) {
      _liqState.seleccion[idPersonal] = new Set(p.dias.map(d => d.fecha));
    } else {
      delete _liqState.seleccion[idPersonal];
    }
    _liqSfx(checked ? 'add' : 'remove');
    _liqRenderPendientes();
    _liqUpdatePayBar();
  }

  function _liqUpdatePayBar() {
    const bar = $('liqPayBar');
    if (!bar) return;
    if (_liqState.tab !== 'pendientes') { bar.classList.add('hidden'); return; }
    let totalSel = 0;   // bruto (jornal + bonos + envasado)
    let netoSel = 0;    // [dueño] NETO = suma de subnetos (bruto − consumo del día)
    let personasSel = 0;
    let diasSel = 0;
    Object.keys(_liqState.seleccion).forEach(idP => {
      const sel = _liqState.seleccion[idP];
      if (!sel || !sel.size) return;
      const p = _liqState.pendientes.find(x => x.idPersonal === idP);
      if (!p) return;
      personasSel++;
      p.dias.forEach(d => { if (sel.has(d.fecha)) { const cc = parseFloat(d.consumoDia && d.consumoDia.total) || 0; totalSel += d.totalDia; netoSel += (d.totalDia - cc); diasSel++; } });
    });
    if (diasSel === 0) { bar.classList.add('hidden'); return; }
    bar.classList.remove('hidden');
    totalSel = Math.round(totalSel * 100) / 100; netoSel = Math.round(netoSel * 100) / 100;
    const consSel = Math.round((totalSel - netoSel) * 100) / 100;
    $('liqPaySubtitle').textContent = `${diasSel} día(s) · ${personasSel} persona(s)` + (consSel > 0 ? ` · −${_liqMoney(consSel)} consumo` : '');
    $('liqPayTotal').textContent = _liqMoney(netoSel);
  }

  // ── Editar día (re-auditar) ──
  // OPTIMISTA: abrimos el modal Auditar al instante usando los datos que ya
  // tenemos del state (pendiente). Después fetch real en background y
  // re-renderizamos las secciones del modal con la data fresca.
  // [v2.43.386] UNIFICADO con Personal del día: el ÚNICO gate de vetar es la clave
  // admin (pedirAuth dentro de _liqVetarDia, sin cache). Se quitó el mini-modal de
  // confirmación previo para que AMBOS lados muestren exactamente lo mismo: un solo
  // modal de clave. (Antes: box "¿Vetar?" + clave = doble paso, inconsistente con
  // Finanzas que solo confirmaba sin clave.)
  function _liqConfirmarVetar(idPersonal, fecha) {
    return _liqVetarDia(idPersonal, fecha);
  }

  // [v2.41.31] Vetar/Desvetar inline desde lista pendientes ─────────
  // Optimista: la fila se desintegra al instante. Backend marca VETADA.
  // Si falla, restauramos local + warn.
  async function _liqVetarDia(idPersonal, fecha) {
    _liqSfx('tap');
    // [v2.41.83] AdminAuthModal (antes solo confirm()) — tier 2 cache 5min
    const persona = (_liqState.pendientes || []).find(x => x.idPersonal === idPersonal);
    const nomP = persona ? persona.nombre : idPersonal;
    const auth = await pedirAuth({
      accion: 'VETAR_LIQUIDACION',
      allowCache: false,   // [v2.43.386] clave SIEMPRE (sin el cache 5min que la saltaba)
      refDocumento: idPersonal + '|' + fecha,
      contexto: `Vetar día de ${nomP} · ${fecha}`
    });
    if (!auth) return;
    // Animación de salida en la fila
    const row = document.querySelector(`.liq-dia-row[data-row-key="${idPersonal}|${fecha}"]`);
    if (row) {
      row.classList.add('liq-row-vetando');
    }
    // Optimista: quitar del state local
    const p = (_liqState.pendientes || []).find(x => x.idPersonal === idPersonal);
    if (!p) return;
    const diaIdx = p.dias.findIndex(d => d.fecha === fecha);
    if (diaIdx < 0) return;
    const diaSnapshot = p.dias[diaIdx];
    const personaIdx = _liqState.pendientes.indexOf(p);

    setTimeout(() => {
      p.dias.splice(diaIdx, 1);
      p.total = Math.round(p.dias.reduce((s, d) => s + d.totalDia, 0) * 100) / 100;
      p.cantidadDias = p.dias.length;
      if (!p.dias.length) {
        _liqState.pendientes.splice(personaIdx, 1);
      }
      _liqRenderPendientes();
    }, 280);

    // [v2.41.50] FIX: API.post devuelve d.data (no d). Si vetarLiquidacionDia
    // responde {ok:true}, API.post resuelve con undefined → la rama
    // "if(!res||!res.ok)" lanzaba falso negativo "Backend no respondió".
    // Solución: confiar en que API.post resuelve → éxito; .catch → error real
    // (e.message trae el error key del backend: YA_PAGADA, NO_ENCONTRADA…).
    // [B1] Marcar mutación reciente (60s) — el polling chequea esto y pasa
    // _refresh=true para no traer cache stale del backend.
    window._liqLastMutationTs = Date.now();
    try {
      await API.post('vetarLiquidacionDia', {
        idPersonal, fecha, claveAdmin: (auth && auth.clave) || '',
        localId: 'L' + Date.now() + Math.random().toString(36).slice(2, 8)
      });
      toast(`💸 Vetada · ${_liqFmtFechaCortaSafe(fecha)}`, 'info', 2500);
      // [B15] Invalidar cache cruzado de Finanzas
      try { localStorage.removeItem('mos_fin_resum_' + fecha); } catch(_){}
      if (S.view === 'finanzas' && typeof finCargar === 'function') {
        try { finCargar({ animate: false, _silent: true }); } catch(_){}
      }
    } catch(e) {
      const errKey = (e && e.message) || 'sin_respuesta';
      let msg;
      if (errKey === 'YA_PAGADA') msg = 'Esta liquidación ya está PAGADA — no se puede vetar.';
      else if (errKey === 'NO_ENCONTRADA') msg = `No encontrada en hoja: ${fecha} para ${idPersonal}. Toca el lápiz primero para materializar.`;
      else msg = `No se pudo vetar: ${errKey}`;
      toast(msg, 'warn', 6000);
      // Rollback
      if (!_liqState.pendientes.includes(p)) _liqState.pendientes.push(p);
      if (!p.dias.find(d => d.fecha === fecha)) p.dias.push(diaSnapshot);
      p.total = Math.round(p.dias.reduce((s, d) => s + d.totalDia, 0) * 100) / 100;
      p.cantidadDias = p.dias.length;
      _liqRenderPendientes();
    }
  }

  async function _liqDesvetarDia(idPersonal, fecha) {
    _liqSfx('tap');
    // [v2.41.83] AdminAuthModal (antes click directo sin clave) — tier 1 cache 10min
    const vetada = (_liqState.vetadas || []).find(v => v.idPersonal === idPersonal && v.fecha === fecha);
    const auth = await pedirAuth({
      accion: 'DESVETAR_LIQUIDACION',
      allowCache: false,   // [v2.43.386] clave SIEMPRE (consistente con vetar)
      refDocumento: idPersonal + '|' + fecha,
      contexto: `Desvetar ${vetada ? vetada.nombre : idPersonal} · ${fecha}`
    });
    if (!auth) return;
    try {
      await API.post('desvetarLiquidacionDia', {
        idPersonal, fecha, claveAdmin: (auth && auth.clave) || '',
        localId: 'L' + Date.now() + Math.random().toString(36).slice(2, 8)
      });
      toast(`💵 Desvetada · ${fecha}`, 'ok', 2500);
      _liqState.vetadas = (_liqState.vetadas || []).filter(v =>
        !(v.idPersonal === idPersonal && v.fecha === fecha));
      _liqRenderVetadas();
      // [B5] Invalidar TODOS los caches + forzar refresh pendientes para que
      // la persona desvetada vuelva a aparecer al instante (sin esperar polling).
      try { _liqCacheClear(); } catch(_){}
      try { localStorage.removeItem('mos_fin_resum_' + fecha); } catch(_){}
      try { liqLoadCurrent(); } catch(_){}
      // [B14] Notificar a Finanzas si está abierto
      if (S.view === 'finanzas' && typeof finCargar === 'function') {
        try { finCargar({ animate: false, _silent: true }); } catch(_){}
      }
    } catch(e) {
      toast('No se pudo desvetar: ' + ((e && e.message) || 'error'), 'warn', 4000);
    }
  }

  async function _liqCargarVetadas() {
    // [B6] Mostrar loading mientras carga vetadas (antes silencioso)
    const cont = document.getElementById('liqVetadasBody');
    if (cont && !_liqState.vetadas?.length) {
      cont.innerHTML = '<div class="text-xs text-slate-500 italic text-center py-4"><span class="inline-block animate-spin">⌛</span> Cargando vetadas…</div>';
    }
    try {
      const res = await API.get('getLiquidacionesVetadas', {});
      if (res?.ok) {
        _liqState.vetadas = res.data || [];
        _liqRenderVetadas();
      } else if (cont) {
        cont.innerHTML = '<div class="text-xs text-rose-400 italic text-center py-4">Error cargando vetadas</div>';
      }
    } catch(e) {
      if (cont) cont.innerHTML = '<div class="text-xs text-rose-400 italic text-center py-4">⚠ ' + (e.message || 'error') + '</div>';
    }
  }

  function _liqRenderVetadas() {
    const cont = document.getElementById('liqVetadasBody');
    if (!cont) return;
    const list = _liqState.vetadas || [];
    if (!list.length) {
      cont.innerHTML = '<div class="text-xs text-slate-500 italic text-center py-4">Sin liquidaciones vetadas</div>';
      return;
    }
    cont.innerHTML = list.map(v => {
      const fechaCorta = _liqFmtFechaLarga ? _liqFmtFechaLarga(v.fecha) : v.fecha;
      return `
        <div class="liq-dia-row" style="opacity:.75;position:relative">
          <span class="liq-stamp vetado" style="top:50%;right:60px">Vetado</span>
          <span style="font-size:18px;flex-shrink:0">🚫</span>
          <div class="flex-1 min-w-0">
            <div class="text-xs text-slate-300 font-medium">${_esc(v.nombre)}</div>
            <div class="text-[10px] text-slate-500 mt-0.5">${_esc(v.rol)} · ${fechaCorta}</div>
          </div>
          <div class="text-right shrink-0">
            <div class="text-sm font-bold text-slate-500" style="text-decoration:line-through">${_liqMoney(v.totalDia)}</div>
          </div>
          <button onclick="MOS._liqDesvetarDia('${v.idPersonal}', '${v.fecha}')"
                  class="liq-btn-desvetar"
                  title="Desvetar — vuelve a la lista de pendientes">🔓</button>
        </div>`;
    }).join('');
  }

  function _liqToggleVetadasPanel() {
    const panel = document.getElementById('liqVetadasPanel');
    if (!panel) return;
    const abierto = panel.style.display !== 'none';
    if (abierto) {
      panel.style.display = 'none';
    } else {
      panel.style.display = 'block';
      _liqCargarVetadas();
    }
  }

  async function _liqEditarDia(idPersonal, fecha) {
    _liqSfx('tap');
    _evalState.fecha = fecha;

    // 1. Construir resumen sintético desde _liqState.pendientes (instantáneo)
    const p = _liqState.pendientes.find(x => x.idPersonal === idPersonal);
    const dia = p ? p.dias.find(d => d.fecha === fecha) : null;
    if (p && dia) {
      const tarifa = parseFloat(dia.tarifaEnvasado) || 0.10;
      const envasados = tarifa > 0 ? Math.round(dia.pagoEnvasado / tarifa) : 0;
      const synth = {
        idPersonal: p.idPersonal,
        nombre:     p.nombre,
        rol:        p.rol,
        appOrigen:  p.appOrigen,
        fecha:      fecha,
        presente:   true,
        auditado:   !!dia.auditado,
        evaluacionesCount: dia.evaluacionesCount || 0,
        montoBase:    dia.montoBase || 0,
        pagoEnvasado: dia.pagoEnvasado || 0,
        bonoMeta:     dia.bonoMeta || 0,
        sancion:      dia.sancion || 0,
        totalDia:     dia.totalDia || 0,
        scoreFinal:   dia.scoreFinal || 0,
        tarifaEnvasado: tarifa,
        unidadesEnvasadas: envasados,
        kpis: {
          auditoriasHechas: 0,
          metaAuditorias: 30,
          envasados: envasados,
          ventasReales: 0,
          metaVenta: 0,
          auditPct: 0
        },
        manual: { limpiezaPct: 0, limpiezaProfPct: 0, checksAcum: {} },
        sancionesDetalle: [],
        aplicaComision: true,
        aplicaBonoMeta: true,
        bonusScore: 0
      };
      // Reemplazar resumenes con el sintético + cualquier otro previo
      const otros = (_evalState.resumenes || []).filter(r => r.idPersonal !== idPersonal);
      _evalState.resumenes = [...otros, synth];
    }

    // 2. Abrir modal Auditar AL INSTANTE (sin esperar fetch)
    abrirAuditar(idPersonal);

    // 3. Fetch real en background → reemplazar datos sintéticos
    try {
      const res = await API.get('getResumenTodosDia', { fecha });
      if (Array.isArray(res)) {
        _evalState.resumenes = res;
        const r = res.find(x => x.idPersonal === idPersonal);
        if (r) {
          _evalState.auditR = r;
          _evalState.auditFechaModal = fecha;   // [RONDA 7] re-congelar al día del lápiz (no el global)
          // Re-pintar las secciones internas del modal Auditar
          try { if (typeof _renderAuditKpis === 'function') _renderAuditKpis(r); } catch(_){}
          try { if (typeof _renderAuditChecklist === 'function') _renderAuditChecklist(r.rol); } catch(_){}
          try { if (typeof _renderAuditLiquidacion === 'function') _renderAuditLiquidacion(); } catch(_){}
          // [v2.41.32] SYNC: recomputar la fila en LIQUIDACIONES_DIA y reflejar
          // en _liqState.pendientes para que el lápiz, pendientes y resumen
          // de personal del día muestren EL MISMO monto siempre.
          try {
            await API.post('recomputarLiquidacionDia', {
              idPersonal, fecha,
              localId: 'L' + Date.now() + Math.random().toString(36).slice(2, 8)
            });
            // Actualizar la fila local con los valores correctos del resumen vivo
            const pLocal = (_liqState.pendientes || []).find(x => x.idPersonal === idPersonal);
            if (pLocal) {
              const diaLocal = pLocal.dias.find(d => d.fecha === fecha);
              if (diaLocal) {
                diaLocal.montoBase    = parseFloat(r.montoBase)    || 0;
                diaLocal.pagoEnvasado = parseFloat(r.pagoEnvasado) || 0;
                diaLocal.bonoMeta     = parseFloat(r.bonoMeta)     || 0;
                diaLocal.sancion      = parseFloat(r.sancion)      || 0;
                diaLocal.totalDia     = parseFloat(r.totalDia)     || 0;
                diaLocal.auditado     = !!r.auditado;
                diaLocal.evaluacionesCount = parseInt(r.evaluacionesCount) || 0;
                diaLocal.tarifaEnvasado    = parseFloat(r.tarifaEnvasado)  || 0;
                // Recalcular total persona
                pLocal.total = Math.round(pLocal.dias.reduce((s, d) => s + d.totalDia, 0) * 100) / 100;
                _liqRenderPendientes();
              }
            }
            // [B14] Notificar a Finanzas si está abierto + invalidar su cache
            try { localStorage.removeItem('mos_fin_resum_' + fecha); } catch(_){}
            if (S.view === 'finanzas' && typeof finCargar === 'function') {
              try { finCargar({ animate: false, _silent: true }); } catch(_){}
            }
          } catch(eRec) {
            // [B13] Toast claro si recompute falla (antes era silencioso)
            toast('⚠ No se pudo recomputar el día: ' + ((eRec && eRec.message) || 'error'), 'warn', 5000);
          }
        }
      }
    } catch(_){}
  }

  // [v2.41.32] Recalcular liquidaciones de los últimos N días (backfill).
  // Útil cuando hay desincronización vieja entre la hoja LIQUIDACIONES_DIA
  // y los cálculos en vivo (ej: por un fix de lógica posterior a la creación).
  async function liqRecalcularRango() {
    if (!await _modalConfirm('¿Recalcular liquidaciones de los últimos 30 días?\n\nPuede tardar 20-60 segundos.', { titulo: 'Recalcular 30 días', okText: 'Recalcular' })) return;
    toast('🔄 Recalculando 30 días... esto demora', 'info', 30000);
    try {
      const res = await API.post('backfillLiquidacionesDia', {
        dias: 30,
        localId: 'L' + Date.now() + Math.random().toString(36).slice(2, 8)
      });
      if (res?.ok) {
        toast(`✓ Recalculadas — refrescando lista...`, 'ok', 3000);
        setTimeout(() => liqRefresh && liqRefresh(), 800);
      } else {
        toast('Error recalculando: ' + (res?.error || 'sin respuesta'), 'warn');
      }
    } catch(e) {
      toast('Sin conexión o timeout', 'warn');
    }
  }

  // ── Confirmar pago (modal) ──
  function liqAbrirConfirmacion() {
    // Validar selección
    const items = [];
    let total = 0;
    Object.keys(_liqState.seleccion).forEach(idP => {
      const sel = _liqState.seleccion[idP];
      if (!sel || !sel.size) return;
      const p = _liqState.pendientes.find(x => x.idPersonal === idP);
      if (!p) return;
      const dias = p.dias.filter(d => sel.has(d.fecha));
      if (!dias.length) return;   // [dueño 2.43.632] sin días válidos (selección vieja) → NO incluir (evita fantasma S/0.00)
      const subtotal = dias.reduce((s,d) => s + d.totalDia, 0);
      items.push({ idPersonal: idP, nombre: p.nombre, rol: p.rol, dias, subtotal });
      total += subtotal;
    });
    if (!items.length) { toast('Selecciona al menos un día', 'error'); _liqSfx('error'); return; }
    // Render desglose
    $('liqConfirmSubtitle').textContent = `${items.length} persona(s) · 1 batch por persona`;
    $('liqConfirmTotal').textContent = _liqMoney(total);
    _liqState.confirmItems = items;
    $('liqConfirmDetalle').innerHTML = items.map(it => _liqComprobanteCard(it, null)).join('');
    $('liqConfirmComentario').value = '';
    // [419] 🧾 notas de crédito: fetch async por persona (no bloquea abrir el modal);
    // checks default MARCADOS (regla del dueño: al liquidar se descuenta la deuda).
    _liqState.creditosSel  = {};
    _liqState.creditosData = {};
    _liqState.confirmTotal = total;
    // [421b] fechas seleccionadas por persona → los créditos se filtran POR DÍA:
    // por defecto solo se descuenta lo consumido en los días que se están liquidando.
    _liqState.creditosFechas = {};
    items.forEach(it => { _liqState.creditosFechas[it.idPersonal] = new Set((it.dias || []).map(d => d.fecha)); });
    _liqCargarCreditos(items.map(it => it.idPersonal));
    openModal('modalLiqConfirmar');
    _liqSfx('open');
  }

  // ── [419] Créditos del personal en el modal de pago ────────────────────────
  let _liqCredGen = 0;   // [review MED6] epoch: descarta respuestas de un modal anterior
  async function _liqCargarCreditos(idPersonales) {
    const cont = $('liqConfirmDetalle');
    if (!cont) return;
    const gen = ++_liqCredGen;
    let sec = document.getElementById('liqCredSection');
    if (!sec) { sec = document.createElement('div'); sec.id = 'liqCredSection'; cont.appendChild(sec); }
    // [review MED5] mientras cargan los créditos, BLOQUEAR el botón + aviso: sin esto
    // un admin rápido confirmaba con creditos:[] → pagaba bruto sin descontar la deuda.
    sec.innerHTML = '<p class="text-[11px] text-slate-400 py-2">🧾 Buscando notas de crédito…</p>';
    const btn = $('liqConfirmBtn');
    if (btn) { btn.disabled = true; btn.dataset.credLoading = '1'; }
    const res = await Promise.allSettled(idPersonales.map(idP =>
      API.get('getCreditosPersonal', { idPersonal: idP }).then(r => ({ idP, r }))));
    if (gen !== _liqCredGen) return;   // [MED6] otro modal se abrió: descartar
    res.forEach(x => {
      if (x.status !== 'fulfilled') return;
      const { idP, r } = x.value;
      if (!r || r.ok !== true || !Array.isArray(r.tickets) || !r.tickets.length) return;
      _liqState.creditosData[idP] = r.tickets;
      // [421b · regla del dueño] default MARCADOS solo los tickets cuya fecha está
      // en los DÍAS SELECCIONADOS de esta liquidación ("si liquido solo el jueves,
      // solo jala lo del jueves"). La deuda de otras fechas se lista aparte,
      // DESMARCADA (opcional) — sin ella, los tickets de días ya liquidados antes
      // quedarían huérfanos para siempre (nunca descontables por planilla).
      const fechasSel = _liqState.creditosFechas?.[idP] || new Set();
      _liqState.creditosSel[idP] = new Set(r.tickets.filter(t => fechasSel.has(String(t.fecha || '').slice(0, 10))).map(t => t.idVenta));
    });
    if (btn) { btn.disabled = false; delete btn.dataset.credLoading; }
    _liqRenderCreditos();
  }
  // [dueño 2.43.626] El consumo es PARTE del día (dinámico, como envasado/bono), NO un
  // satélite. Se descuenta desde consumoDia (robusto = lo que paga el server, autoConsumos)
  // y se muestra YA RESTADO en cada día del comprobante, con detalle por ticket si el fetch
  // los trajo. Sin bloque separado ni "otras fechas". Solo recomputa el neto + re-render.
  function _liqRenderCreditos() {
    const sec = document.getElementById('liqCredSection');
    const items = _liqState.confirmItems || [];
    const data = _liqState.creditosData || {};
    let descGlobal = 0;
    items.forEach(it => (it.dias || []).forEach(d => { descGlobal += parseFloat(d.consumoDia && d.consumoDia.total) || 0; }));
    descGlobal = Math.round(descGlobal * 100) / 100;
    // re-render de los comprobantes con el detalle por ticket (consumos del período)
    const detEl = document.getElementById('liqConfirmDetalle');
    if (detEl && items.length) {
      detEl.innerHTML = items.map(it => {
        const fechasSel = (_liqState.creditosFechas && _liqState.creditosFechas[it.idPersonal]) || new Set((it.dias || []).map(d => d.fecha));
        const tks = (data[it.idPersonal] || []).filter(t => fechasSel.has(String(t.fecha || '').slice(0, 10)));
        const byF = {};
        tks.forEach(t => { const f = String(t.fecha || '').slice(0, 10); (byF[f] = byF[f] || []).push(t); });
        return _liqComprobanteCard(it, Object.keys(byF).length ? byF : null);
      }).join('');
    }
    if (sec) sec.innerHTML = descGlobal > 0
      ? '<div class="text-[10.5px] mt-2 mb-2 px-1" style="color:#6ee7b7">✓ El consumo ya está restado en cada día. El neto es el líquido a pagar.</div>'
      : '';
    const bruto = _liqState.confirmTotal || 0;
    const neto = Math.round((bruto - descGlobal) * 100) / 100;
    const totalEl = document.getElementById('liqConfirmTotal');
    if (totalEl) totalEl.innerHTML = descGlobal > 0
      ? _liqMoney(neto) + ' <span style="font-size:.5em;color:#94a3b8;font-weight:600">neto · de ' + _liqMoney(bruto) + '</span>'
      : _liqMoney(bruto);
  }
  // [572] colapsar/expandir la deuda de otras fechas (opcional) por persona.
  function _liqToggleOtras(idP) {
    _liqState.credOtrasOpen = _liqState.credOtrasOpen || {};
    _liqState.credOtrasOpen[idP] = !_liqState.credOtrasOpen[idP];
    _liqRenderCreditos();
    _liqSfx(_liqState.credOtrasOpen[idP] ? 'expand' : 'collapse');
  }
  // [572] ver/ocultar el detalle de los consumos del período (colapsado = modal limpio).
  function _liqTogglePeriodo(idP) {
    _liqState.credPerOpen = _liqState.credPerOpen || {};
    _liqState.credPerOpen[idP] = !_liqState.credPerOpen[idP];
    _liqRenderCreditos();
    _liqSfx(_liqState.credPerOpen[idP] ? 'expand' : 'collapse');
  }
  // [2.43.625] Comprobante ELEGANTE (tipo imagen, estilo guía WH) para el preview de pago.
  // Calcula el neto al vuelo desde consumoDia de los días — coincide con lo que paga el server.
  function _liqComprobanteCard(it, ticketsByFecha) {
    const dd = it.dias || [];
    const M = _liqMoney;
    const fCorta = f => { const s = String(f || ''); return s.slice(8) + '/' + s.slice(5, 7); };
    // [dueño] cada día = CARPETA con TODOS sus conceptos como sub-líneas (ingresos +
    // verde, descuentos − rojo). El consumo va acá adentro, por ticket. El neto del día
    // = suma de sus conceptos. El neto final = suma de netos diarios (NO hay resumen aparte).
    const sub = (lbl, amt, neg) => '<div style="display:flex;justify-content:space-between;font-size:10px;padding:1.5px 0 1.5px 14px"><span style="color:#64748b">' + lbl + '</span><span style="color:' + (neg ? '#c2410c' : '#0f766e') + ';font-weight:600">' + (neg ? '−' : '+') + M(amt) + '</span></div>';
    let neto = 0;
    const rows = dd.map(d => {
      const base = parseFloat(d.montoBase) || 0;
      const env  = parseFloat(d.pagoEnvasado) || 0;
      const meta = parseFloat(d.bonoMeta) || 0;
      const bono = parseFloat(d.bonificacion) || 0;
      const san  = parseFloat(d.sancion) || 0;
      const colab = (parseFloat(d.pagoEnvasadoColab) || 0) > 0;
      const tks = (ticketsByFecha && ticketsByFecha[d.fecha]) || null;
      const consDia = parseFloat(d.consumoDia && d.consumoDia.total) || 0;
      const tksSum = (tks && tks.length) ? Math.round(tks.reduce((s, x) => s + (parseFloat(x.total) || 0), 0) * 100) / 100 : null;
      // [50x] CANÓNICO: el consumo del día = consumoDia (= barra/header/server). El detalle
      // por ticket SOLO se muestra si RECONCILIA con consumoDia (nunca 2 netos distintos).
      const cons = consDia;
      const showTks = (tksSum !== null) && Math.abs(tksSum - consDia) < 0.005;
      // neto del día = totalDia − consumo (IDÉNTICO a la barra/header/server; totalDia ya
      // aplica greatest(0, base+env+meta+bono−san), así no diverge si la sanción supera lo ganado).
      const nd = Math.round(((parseFloat(d.totalDia) || 0) - cons) * 100) / 100;
      neto += nd;
      const lines = [];
      if (base > 0) lines.push(sub('Jornal base', base, false));
      if (meta > 0) lines.push(sub('Comisión por ventas', meta, false));
      if (env  > 0) lines.push(sub('Envasado' + (colab ? ' 🤝 (compartido)' : ''), env, false));
      if (bono > 0) lines.push(sub('Bonificación', bono, false));
      if (san  > 0) lines.push(sub('Sanción', san, true));
      if (cons > 0) {
        if (showTks) tks.forEach(x => lines.push(sub('Consumo · ' + _escapeHtml(x.correlativo || x.idVenta || ''), parseFloat(x.total) || 0, true)));
        else lines.push(sub('Consumo a crédito', cons, true));
      }
      return '<div style="padding:6px 0;border-bottom:1px dashed rgba(15,23,42,.1)">'
        + '<div style="display:flex;justify-content:space-between;font-size:11.5px"><b style="color:#0f172a;text-transform:capitalize">' + _liqFmtFechaLarga(d.fecha) + '</b><b style="color:#0f766e">' + M(nd) + '</b></div>'
        + lines.join('') + '</div>';
    }).join('');
    neto = Math.round(neto * 100) / 100;
    const f0 = dd.length ? fCorta(dd[0].fecha) : '';
    const f1 = dd.length ? fCorta(dd[dd.length - 1].fecha) : '';
    return '<div style="background:linear-gradient(160deg,#ffffff,#f0fdf9);border-radius:16px;padding:18px;color:#1e293b;margin-bottom:12px;box-shadow:0 6px 22px rgba(0,0,0,.28)">'
      + '<div style="text-align:center;border-bottom:2px solid #0f766e;padding-bottom:10px;margin-bottom:10px"><div style="font-size:15px;font-weight:900;color:#0f766e;letter-spacing:.5px">INVERSIONES MOS</div><div style="font-size:10px;color:#64748b;font-weight:600">Comprobante de liquidación</div></div>'
      + '<div style="display:flex;justify-content:space-between;font-size:11px;margin-bottom:10px"><div><div style="font-weight:800;font-size:13px">' + _escapeHtml(it.nombre || '') + '</div><div style="color:#64748b;text-transform:capitalize">' + _escapeHtml(String(it.rol || '').toLowerCase()) + '</div></div><div style="text-align:right"><div style="color:#64748b">' + f0 + ' – ' + f1 + '</div><div style="font-weight:700">' + dd.length + ' día(s)</div></div></div>'
      + rows
      + '<div style="margin-top:10px;background:#0f766e;border-radius:11px;padding:11px 14px;display:flex;justify-content:space-between;align-items:center;color:#fff"><div><div style="font-size:10px;font-weight:700;opacity:.85">NETO A PAGAR</div><div style="font-size:9px;opacity:.7">' + dd.length + ' día(s) · suma de netos diarios</div></div><div style="font-size:23px;font-weight:900">' + M(neto) + '</div></div>'
      + '</div>';
  }

  // [v2.41.72-B11] Lock anti-doble-click: si ya se está procesando un pago,
  // no permitir disparar otro.
  let _liqPayLock = 0;
  async function liqConfirmarPago(ev) {
    // [FIX 500x BUG-4] lock con auto-expiración 30s: el release (34082) no está en finally; si algo lanza en
    // medio, un lock booleano quedaba trabado para siempre. Timestamp → se auto-libera pasados 30s.
    if (_liqPayLock && Date.now() - _liqPayLock < 30000) { try { toast('⏳ Ya se está procesando el pago…', 'info', 2000); } catch(_){} return; }
    _liqPayLock = Date.now();
    if (ev) _liqRipple(ev);
    const btn = $('liqConfirmBtn');
    if (btn) { btn.disabled = true; btn.textContent = '⏳ Procesando...'; }
    const imprimir = $('liqConfirmImprimir').checked;
    const comentario = $('liqConfirmComentario').value || '';
    const pagadoPor = (S.session && S.session.nombre) || 'admin';

    // Acumular pagos por persona (1 batch por persona)
    const personas = Object.keys(_liqState.seleccion)
      .map(idP => {
        const sel = _liqState.seleccion[idP];
        if (!sel || !sel.size) return null;
        const p = _liqState.pendientes.find(x => x.idPersonal === idP);
        if (!p) return null;
        const fechas = p.dias.filter(d => sel.has(d.fecha)).map(d => d.fecha);
        return {
          idPersonal: idP,
          nombre: p.nombre,
          rol: p.rol,
          appOrigen: p.appOrigen,
          fechas,
          // [419] 🧾 créditos marcados → la RPC los descuenta EN LA MISMA TX del pago
          creditos: Array.from(_liqState.creditosSel?.[idP] || [])
        };
      })
      .filter(Boolean);

    if (!personas.length) { toast('Selección vacía', 'error'); if (btn) { btn.disabled = false; btn.textContent = '💸 Confirmar y pagar'; } return; }

    // Si va a imprimir → primero PREVIEW del ticket, luego pedir impresora
    let printerId = null;
    if (imprimir) {
      closeModal('modalLiqConfirmar');
      // [dueño 2.43.630] El comprobante del modal YA es el preview → SIN paso extra de
      // preview ASCII 80mm. Va directo a elegir impresora (luego imprime 2 copias jefa+empleado).
      printerId = await _liqElegirImpresora();
      if (!printerId) toast('Pago se registró sin imprimir', 'info');
    }
    // [dueño 2026-07-14] Snapshot POR PERSONA del ticket (pendientes AÚN intactos = montos correctos): se GUARDA
    // tras el pago (guardarTicketPago) para que Reimprimir sea IDÉNTICO, y se imprime en 2 copias (jefa+empleado).
    const _liqPerTicket = {};
    try { personas.forEach(p => { _liqPerTicket[p.idPersonal] = _liqGenerarTicketAscii([p], comentario, pagadoPor); }); } catch (_) {}

    // [v2.41.71] OPTIMISTA INMEDIATO — antes del loop:
    //   1. Quitar días pagados del state local + repaint
    //   2. Cerrar modal
    //   3. Sonido + confetti
    //   4. POSTs en PARALELO (Promise.allSettled) no en serie → 3x más rápido
    //   5. Toast final con resumen
    const personasSnap = JSON.parse(JSON.stringify(personas)); // por si revert
    personas.forEach(persona => {
      const pLocal = _liqState.pendientes.find(x => x.idPersonal === persona.idPersonal);
      if (!pLocal) return;
      const setFechas = new Set(persona.fechas);
      pLocal.dias = pLocal.dias.filter(d => !setFechas.has(d.fecha));
      pLocal.cantidadDias = pLocal.dias.length;
      pLocal.total = Math.round(pLocal.dias.reduce((s, d) => s + d.totalDia, 0) * 100) / 100;
    });
    _liqState.pendientes = _liqState.pendientes.filter(p => p.cantidadDias > 0);
    _liqState.seleccion = {};
    _liqRenderPendientes();
    closeModal('modalLiqConfirmar');
    // [v2.41.74] Sonido cash distintivo (sustituye success genérico) + animación ticket si se imprimió
    _liqSfx('cash');
    try {
      const r = btn?.getBoundingClientRect();
      const cx = r ? r.left + r.width/2 : window.innerWidth/2;
      const cy = r ? r.top  + r.height/2 : window.innerHeight/2;
      _liqConfetti(cx, cy, '#fbbf24');
      if (printerId) _liqTicketFly(cx, cy, Math.min(personas.length, 3));
    } catch(_){}
    toast(`💸 Procesando ${personas.length} pago(s)…`, 'info', 3000);

    // POSTs PARALELOS — Promise.allSettled para no abortar si uno falla
    const results = await Promise.allSettled(personas.map(persona =>
      API.post('marcarPagos', {
        idPersonal: persona.idPersonal,
        fechas: persona.fechas,
        nombre: persona.nombre,
        rol: persona.rol,
        appOrigen: persona.appOrigen,
        creditos: persona.creditos,   // [419] extras opcionales (deuda de otras fechas) que el admin marcó
        autoConsumos: true,           // [572] 🤖 el servidor descuenta AUTO todos los consumos de los días pagados
        pagadoPor,
        comentario,
        // [v2.43.377] El front imprime por la Edge `imprimir` (cero-GAS, preview==print).
        // marcarPagos ya NO imprime (evita ticket GAS distinto + fallos silenciosos).
        imprimir: false,
        printerId: ''
      }).then(res => ({ ok: true, persona, res }))
        .catch(e => ({ ok: false, persona, error: e.message || String(e) }))
    ));

    const okList  = results.filter(r => r.status === 'fulfilled' && r.value.ok).map(r => r.value);
    const errList = results.filter(r => r.status === 'fulfilled' && !r.value.ok).map(r => r.value);
    const totalPagado = okList.reduce((s, r) => s + (parseFloat(r.res.total) || 0), 0);

    if (okList.length) {
      toast(`✓ ${okList.length} pago(s) registrado(s) · ${_liqMoney(totalPagado)}`, 'ok', 5000);
      // [dueño 2026-07-14] Por cada pago OK: (1) GUARDAR el ticket snapshot con su idPago → Reimprimir será
      // IDÉNTICO (cero-GAS, RPC guardar_ticket_pago); (2) imprimir 2 COPIAS (jefa/tesorería + empleado) por la Edge.
      for (const { persona, res } of okList) {
        const asciiP = _liqPerTicket[persona.idPersonal];
        const idPago = res && (res.idPago || (res.data && res.data.idPago));
        if (asciiP && idPago) {
          try { await API.post('guardarTicketPago', { idPago, ticketEscPos: asciiP }); } catch (_) {}
        }
        if (printerId && asciiP) {
          try { await _liqPrint2Copias(printerId, asciiP, 'Comprobante de pago'); }
          catch (ePr) { toast('⚠ Pago OK de ' + persona.nombre + ', pero no imprimió: ' + ((ePr && ePr.message) || ePr), 'warn', 6000); }
        }
      }
      if (printerId) toast('🖨 Comprobantes enviados (2 copias c/u)', 'ok', 3000);
    }
    if (errList.length) {
      // Restaurar al state los que fallaron
      errList.forEach(({ persona, error }) => {
        toast(`Error con ${persona.nombre}: ${error}`, 'error', 6000);
        const snap = personasSnap.find(p => p.idPersonal === persona.idPersonal);
        if (snap) {
          let pLocal = _liqState.pendientes.find(x => x.idPersonal === snap.idPersonal);
          if (!pLocal) {
            pLocal = { idPersonal: snap.idPersonal, nombre: snap.nombre, rol: snap.rol,
                       appOrigen: snap.appOrigen, dias: [], total: 0, cantidadDias: 0 };
            _liqState.pendientes.push(pLocal);
          }
          snap.fechas.forEach(f => {
            if (!pLocal.dias.find(d => d.fecha === f)) {
              pLocal.dias.push({ fecha: f, totalDia: 0, montoBase: 0, pagoEnvasado: 0 });
            }
          });
          pLocal.cantidadDias = pLocal.dias.length;
        }
      });
      _liqRenderPendientes();
    }

    // Invalidar cache + fetch fresco en bg
    _liqCacheClear();
    liqLoadCurrent();

    if (btn) { btn.disabled = false; btn.textContent = '💸 Confirmar y pagar'; }
    _liqPayLock = 0;
  }

  // [v2.41.74] Preview ASCII del ticket — abre modal con texto monoespaciado
  // que aproxima cómo se imprimirá. Devuelve Promise<boolean>.
  let _liqPreviewResolve = null;
  function _liqAbrirPreviewTicket(personas, comentario, pagadoPor) {
    return new Promise(resolve => {
      _liqPreviewResolve = resolve;
      const pre = document.getElementById('liqPreviewTicketContent');
      const sub = document.getElementById('liqPreviewSubtitle');
      if (pre) pre.textContent = _liqGenerarTicketAscii(personas, comentario, pagadoPor);
      if (sub) {
        const n = personas.length;
        const td = personas.reduce((s, p) => s + (p.fechas?.length || 0), 0);
        sub.textContent = `${n} ticket(s) · ${td} día(s)`;
      }
      openModal('modalLiqPreviewTicket');
      _liqSfx('open');
    });
  }
  function _liqCerrarPreview(seguir) {
    closeModal('modalLiqPreviewTicket');
    _liqSfx(seguir ? 'tap' : 'tap');
    if (_liqPreviewResolve) {
      const r = _liqPreviewResolve;
      _liqPreviewResolve = null;
      r(!!seguir);
    }
  }
  // [v2.43.380] Comprobante de pago 80mm (W=48) con DESGLOSE REAL por día:
  // base · comisión por ventas · envasado · +bono · −descuento → total. Lo que ves en el
  // preview es EXACTO lo que se imprime (la Edge `imprimir` recibe este mismo texto).
  function _liqGenerarTicketAscii(personas, comentario, pagadoPor) {
    const W = 48; // 80mm
    const linea = (c) => (c || '-').repeat(W);
    const centrar = (s) => { s = String(s || ''); if (s.length >= W) return s.slice(0, W); return ' '.repeat(Math.floor((W - s.length) / 2)) + s; };
    const dosCol = (izq, der) => {
      izq = String(izq || ''); der = String(der || '');
      const max = W - der.length - 1;
      if (izq.length > max) izq = izq.slice(0, max);
      return izq + ' '.repeat(Math.max(1, W - izq.length - der.length)) + der;
    };
    const fmtMon = (n) => 'S/' + (Math.round((n || 0) * 100) / 100).toFixed(2);
    const num = (n) => (Math.round((parseFloat(n) || 0) * 100) / 100).toFixed(2);
    const fmtFecha = (f) => { try { const d = new Date(f + 'T12:00:00'); return d.toLocaleDateString('es-PE', { weekday:'short', day:'2-digit', month:'2-digit' }); } catch { return f; } };
    let out = '';
    personas.forEach((per, idx) => {
      if (idx > 0) out += '\n' + linea('=') + '\n\n';
      out += centrar('INVERSIONES MOS') + '\n';
      out += centrar('Comprobante de pago') + '\n';
      out += linea('=') + '\n';
      out += dosCol('Persona:', per.nombre || '') + '\n';
      out += dosCol('Rol:', per.rol || '') + '\n';
      out += dosCol('Pagado por:', pagadoPor || '-') + '\n';
      out += dosCol('Emitido:', new Date().toLocaleString('es-PE', { day:'2-digit', month:'2-digit', year:'2-digit', hour:'2-digit', minute:'2-digit' })) + '\n';
      out += linea('-') + '\n';
      out += 'DETALLE POR DIA:\n';
      // cada concepto en SU línea (solo si existe); comentario debajo, multilínea.
      const num0 = (n) => { n = parseFloat(n) || 0; return Number.isInteger(n) ? ('' + n) : num(n); };
      const compLine = (label, monto, signo) => dosCol('  ' + label, (signo || '') + 'S/' + num(monto)) + '\n';
      const motivoLines = (motivo) => {
        const t = String(motivo || '').trim(); if (!t) return '';
        const palabras = t.split(/\s+/); let buf = '', out2 = '';
        palabras.forEach(w => { if (buf && (buf + ' ' + w).length > (W - 4)) { out2 += '    ' + buf + '\n'; buf = w; } else buf += (buf ? ' ' : '') + w; });
        if (buf) out2 += '    ' + buf + '\n';
        return out2;
      };
      const pState = _liqState.pendientes.find(x => x.idPersonal === per.idPersonal);
      // [dueño 2026-07-14] Créditos SELECCIONADOS agrupados por su fecha → se muestran DENTRO del día en que
      // ocurrieron y bajan el SUBNETO de ESE día (antes iban en un bloque separado al final). Los que caen fuera
      // del rango pagado van en un bloque residual "otros días". El neto total PUEDE ser negativo (regla dueño).
      const _credSel  = (_liqState.creditosSel  && _liqState.creditosSel[per.idPersonal])  || null;
      const _credData = (_liqState.creditosData && _liqState.creditosData[per.idPersonal]) || [];
      const _marcados = _credSel ? _credData.filter(t => _credSel.has(t.idVenta)) : [];
      const _credByFecha = {};
      _marcados.forEach(t => { const ff = String(t.fecha || '').slice(0, 10); (_credByFecha[ff] = _credByFecha[ff] || []).push(t); });
      const _fechasPag = new Set(per.fechas || []);
      let subtotal = 0, descTotal = 0;
      (per.fechas || []).forEach(f => {
        const d = pState ? pState.dias.find(x => x.fecha === f) : null;
        const mJor = d ? (parseFloat(d.totalDia) || 0) : 0;
        subtotal += mJor;
        out += '\n' + dosCol(fmtFecha(f), fmtMon(mJor)) + '\n';
        if (d) {
          const base = parseFloat(d.montoBase) || 0, env = parseFloat(d.pagoEnvasado) || 0, com = parseFloat(d.bonoMeta) || 0;
          const bon = parseFloat(d.bonificacion) || 0, san = parseFloat(d.sancion) || 0, uds = parseFloat(d.productosEnvasados) || 0;
          const envColab = parseFloat(d.pagoEnvasadoColab) || 0, udsColab = parseFloat(d.envasadosColab) || 0;
          const envPropio = Math.round((env - envColab) * 100) / 100;
          if (base > 0) out += compLine('Base diaria', base);
          if (envPropio > 0) out += compLine('Envasado propio' + (uds > 0 ? ' (' + num0(uds) + ' uds)' : ''), envPropio);
          if (envColab > 0)  out += compLine('Envasado colab 50%' + (udsColab > 0 ? ' (' + num0(udsColab) + ' uds)' : ''), envColab);
          if (com > 0)  out += compLine('Comision por ventas', com);
          if (bon > 0)  { out += compLine('Bonificacion', bon, '+'); out += motivoLines(d.bonificacionMotivo); }
          if (san > 0)  { out += compLine('Descuento', san, '-');     out += motivoLines(d.sancionMotivo); }
          // [dueño 2026-07-14] Reporte de auditoría vs meta del día (informativo, no afecta el total).
          // Solo cuando el rol tiene meta (>0): dice cuántas hizo y si LOGRÓ o NO la meta (30/día).
          const audH = parseInt(d.auditoriasHechas) || 0, audM = parseInt(d.metaAuditorias) || 0, audOK = !!d.cumplioAuditorias;
          if (audM > 0) out += dosCol('  Auditorias: ' + audH + '/' + audM, audOK ? 'META OK' : 'NO cumplio') + '\n';
        }
        // 🧾 créditos de ESTE día → integrados en el detalle + subneto del día
        const credDia = _credByFecha[f] || [];
        if (credDia.length) {
          let descDia = 0;
          credDia.forEach(t => { const mm = parseFloat(t.total) || 0; descDia += mm; descTotal += mm; out += compLine('Credito ' + String(t.correlativo || t.idVenta).slice(0, 14), mm, '-'); });
          descDia = Math.round(descDia * 100) / 100;
          const netoDia = Math.round((mJor - descDia) * 100) / 100;
          out += dosCol('  Subneto del dia', (netoDia < 0 ? '-S/' : 'S/') + num(Math.abs(netoDia))) + '\n';
        } else if (d) {
          // [572] fallback comprobante: si el modal de créditos no cargó sus tickets pero el
          // día tiene consumo, el servidor igual lo descuenta AUTO (autoConsumos) → reflejarlo
          // para que el ticket cuadre EXACTO con lo que sale de caja (evita comprobante que miente).
          const _cd = Math.round((parseFloat(d.consumoDia && d.consumoDia.total) || 0) * 100) / 100;
          if (_cd > 0) {
            descTotal += _cd;
            out += compLine('Consumo a credito del dia', _cd, '-');
            const netoDia = Math.round((mJor - _cd) * 100) / 100;
            out += dosCol('  Subneto del dia', (netoDia < 0 ? '-S/' : 'S/') + num(Math.abs(netoDia))) + '\n';
          }
        }
      });
      // créditos de días FUERA del rango pagado (no caen en ningún día del ticket) → bloque residual
      const _residual = _marcados.filter(t => !_fechasPag.has(String(t.fecha || '').slice(0, 10)));
      if (_residual.length) {
        out += '\n' + 'Notas de credito (otros dias):\n';
        _residual.forEach(t => { const mm = parseFloat(t.total) || 0; descTotal += mm; out += dosCol('  ' + String(t.correlativo || t.idVenta).slice(0, 18) + ' ' + String(t.fecha || '').slice(5, 10), '-S/' + num(mm)) + '\n'; });
      }
      descTotal = Math.round(descTotal * 100) / 100;
      out += linea('=') + '\n';
      // [dueño 2.43.628] NETO FINAL bien RESALTADO: etiqueta centrada + el monto solo, en
      // DOBLE tamaño, en su propia línea. El consumo ya va restado en el subneto de cada día.
      const netoFinal = Math.round((subtotal - descTotal) * 100) / 100;
      out += centrar(descTotal > 0 ? '>>> NETO A PAGAR (liquido) <<<' : '>>> TOTAL A PAGAR <<<') + '\n';
      const _amt = (netoFinal < 0 ? '-' : '') + fmtMon(Math.abs(netoFinal));
      const _half = Math.floor(W / 2);
      out += '\x1b\x21\x30' + ' '.repeat(Math.max(0, Math.floor((_half - _amt.length) / 2))) + _amt.slice(0, _half) + '\x1b\x21\x00\n';
      if (comentario) {
        out += linea('-') + '\n' + 'Comentario:\n';
        const words = String(comentario).split(/\s+/); let buf = '  ';
        words.forEach(w => { if ((buf + ' ' + w).length > W) { out += buf + '\n'; buf = '  ' + w; } else buf += (buf.trim() ? ' ' : '') + w; });
        if (buf.trim()) out += buf + '\n';
      }
      out += linea('=') + '\n';
      out += centrar('Gracias') + '\n';
    });
    return out;
  }

  // [dueño 2026-07-14] Imprime el comprobante en 2 COPIAS por la Edge (cero-GAS): una JEFA/TESORERIA y otra
  // EMPLEADO. `baseAscii` es el ticket base (sin cabecera de copia); acá se antepone la etiqueta de cada copia.
  async function _liqPrint2Copias(printerId, baseAscii, titulo) {
    const W = 48;
    const centrar = (s) => { s = String(s || ''); if (s.length >= W) return s.slice(0, W); return ' '.repeat(Math.floor((W - s.length) / 2)) + s; };
    const armar = (label) => '\x1b\x40\x1b\x74\x10' + centrar('*** ' + label + ' ***') + '\n' + '-'.repeat(W) + '\n' + baseAscii + '\n\n\n\n\x1d\x56\x00';
    await API.imprimirTicketEdge(parseInt(printerId, 10), (titulo || 'Comprobante de pago') + ' (Jefa/Tesoreria)', armar('COPIA: JEFA / TESORERIA'));
    await API.imprimirTicketEdge(parseInt(printerId, 10), (titulo || 'Comprobante de pago') + ' (Empleado)', armar('COPIA: EMPLEADO'));
  }

  // [v2.41.74] Animación "ticket impreso" — papel sale flotando del centro
  function _liqTicketFly(originX, originY, count) {
    count = count || 1;
    for (let i = 0; i < count; i++) {
      const el = document.createElement('div');
      el.className = 'liq-ticket-fly';
      const x = (originX != null ? originX : window.innerWidth / 2) - 45 + (i * 12 - count * 6);
      const y = (originY != null ? originY : window.innerHeight / 2) - 65;
      el.style.left = x + 'px';
      el.style.top  = y + 'px';
      el.style.animationDelay = (i * 0.12) + 's';
      document.body.appendChild(el);
      setTimeout(() => { try { el.remove(); } catch(_){} }, 1700 + i * 120);
    }
  }

  // ── Elegir impresora — reusa el modal modalSelPrinterLiq del audit ──
  function _liqElegirImpresora() {
    // [dueño 2.43.632] SIEMPRE deja elegir la impresora (no reusar la última). El único
    // paso que se quitó es el preview ASCII (el comprobante del modal ya es el preview).
    return abrirPrinterPicker({
      titulo: '🖨 Imprimir liquidación',
      subtitulo: `Pago de liquidación · ${(_liqState.tab === 'pendientes' ? 'pendientes' : 'reimpresión')}`,
      filtroTipo: 'TICKET'
    });
  }

  // [v2.41.82] PrinterPicker UNIVERSAL — selector de impresora reusable
  // por todos los flujos (liquidación, costos guía, etiquetas, batches).
  // Devuelve una Promise<printerId | null>. Verifica el estado fresh
  // antes de resolver (verificarImpresoraAhora) para evitar enviar jobs
  // a impresoras que cambiaron de estado entre listar y elegir.
  //
  // opts:
  //   titulo:    string  ('🖨 Imprimir X')
  //   subtitulo: string  (contexto del job: 'Guía G-0042 · S/450')
  //   filtroTipo: 'TICKET' | 'ADHESIVO' | 'ZPL' | undefined (todos)
  //   filtroZona: idZona  (si undefined, usa zona del admin si está set)
  //   verify:    bool (true por default — verifica antes de resolver)
var _pPickState = { filtroZona: null, filtroTipo: null, mostrarTodas: false };
  async function abrirPrinterPicker(opts) {
    opts = opts || {};
    // [v2.43.3] Memoria de última impresora por tipo de flow.
    // Si opts.flowKey está dado y hay impresora cacheada online → usar directo.
    // Si opts.flowKey === '__skipCache' → ignorar memoria (admin quiere elegir).
    const _LSKEY = opts.flowKey ? 'mos_lastPrinter_' + opts.flowKey : null;
    // [Reparación picker] MOS es el panel admin y puede estar REMOTO (lejos de la impresora, ej. en casa) →
    // SIEMPRE mostrar el picker para que el admin elija. Solo se reusa la última impresora si un flow lo pide
    // explícitamente con opts.autoUsarUltima (hoy ninguno lo hace → todos los flujos muestran el picker).
    if (_LSKEY && opts.autoUsarUltima === true && opts.flowKey !== '__skipCache') {
      try {
        const cachedId = localStorage.getItem(_LSKEY);
        if (cachedId) {
          // [2026-06-18 fix] BLOQUEANTE: verificar que la impresora cacheada siga ONLINE
          // ANTES de reusarla. Antes esto era fire-and-forget (en bg) y además leía el
          // campo equivocado (r.data.estado, que no existe → la condición nunca cumplía),
          // así que una impresora cacheada rota/desactivada (ej. el duplicado "POS-80C (copy 1)"
          // de ZONA-02) recibía el job igual y quedaba en error. Ahora: si no está ONLINE
          // (offline, error, ID_INVALIDO porque se desactivó del catálogo, etc.) limpiamos
          // la caché y caemos al picker — que solo muestra impresoras activas.
          // API.get desempaqueta d.data → r ES el estado {state,online,reason,...} de la Edge `printers`.
          let okOnline = false, razon = '';
          try {
            const r = await API.get('verificarImpresoraAhora', { printerId: cachedId });
            const d = r || {};
            okOnline = (d.online === true) || (String(d.state || '').toUpperCase() === 'ONLINE');
            razon = d.reason || '';
          } catch (_) { okOnline = false; razon = 'no se pudo verificar'; }
          if (okOnline) {
            // Toast optimista + retornar (ya verificada ONLINE).
            try { _toast?.('info', '🖨 Usando última impresora · tap para cambiar'); } catch(_){}
            try { _opsBeep?.('tac'); } catch(_){}
            return cachedId;
          }
          // Cacheada NO disponible → olvidarla y forzar elección manual.
          try { localStorage.removeItem(_LSKEY); } catch(_){}
          try { _toast?.('info', '🖨 La última impresora no está lista — elige otra' + (razon ? ' (' + razon + ')' : '')); } catch(_){}
        }
      } catch(_){}
    }
    return new Promise(resolve => {
      // Setear título/subtítulo dinámicos
      const tit = document.getElementById('liqPrintTitle');
      const sub = document.getElementById('liqPrintSubtitle');
      if (tit) tit.textContent = opts.titulo || '🖨 Elegir impresora';
      if (sub) sub.textContent = opts.subtitulo || '—';

      // Setear filtros iniciales
      _pPickState.filtroTipo = opts.filtroTipo || null;
      _pPickState.filtroZona = opts.filtroZona !== undefined
        ? opts.filtroZona
        : ((S.session && S.session.idZona) || null);
      _pPickState.mostrarTodas = !_pPickState.filtroZona;

      // Botón filtro tipo visible solo si NO se está forzando uno específico
      const btnTipo = document.getElementById('ppFiltTipoBtn');
      if (btnTipo) btnTipo.classList.toggle('hidden', !!opts.filtroTipo);

      _pPickActualizarBotones();

      // Hook: el resolve se llama cuando _liqEnviarPrint es invocado o se cierra
      const prevSend = MOS._liqEnviarPrint;
      MOS._liqEnviarPrint = async function(printerId, btnEl, ev) {
        // Verify on-click — fresh state antes de cerrar el modal
        if (opts.verify !== false) {
          if (btnEl) { btnEl.classList.add('sending'); }
          try {
            const r = await API.get('verificarImpresoraAhora', { printerId });
            // [v2.42.04 fix] API.get devuelve d.data — r ya es el estado
            const d = r || {};
            if (d.state && d.state !== 'ONLINE') {
              // Estado cambió entre listar y elegir — bloquear
              try { _evalSfx && _evalSfx('error'); } catch(_){}
              if (btnEl) btnEl.classList.remove('sending');
              toast(`🖨 ${d.reason || 'No disponible'} · refrescando…`, 'error', 5000);
              if (typeof _liqLoadPrinters === 'function') _liqLoadPrinters(true);
              return;
            }
          } catch(eV) {
            console.warn('[PrinterPicker] verify falló — siguiendo con la elección:', eV);
          }
        }
        MOS._liqEnviarPrint = prevSend;
        closeModal('modalSelPrinterLiq');
        // [v2.43.3] Guardar elección para recordar próxima vez si flowKey existe
        if (_LSKEY) {
          try { localStorage.setItem(_LSKEY, String(printerId)); } catch(_){}
        }
        resolve(parseInt(printerId, 10));
      };
      // Listener cancelación
      const backdrop = document.getElementById('modalSelPrinterLiq');
      const closeBtns = backdrop ? backdrop.querySelectorAll('button[onclick*="closeModal"]') : [];
      closeBtns.forEach(b => b.addEventListener('click', function once() {
        MOS._liqEnviarPrint = prevSend;
        resolve(null);
        b.removeEventListener('click', once);
      }, { once: true }));
      openModal('modalSelPrinterLiq');
      if (typeof _liqLoadPrinters === 'function') _liqLoadPrinters(false);
    });
  }

  // Toggle filtro zona (mi zona ↔ todas)
  function _pPickToggleFiltroZona() {
    _pPickState.mostrarTodas = !_pPickState.mostrarTodas;
    _pPickActualizarBotones();
    if (typeof _liqLoadPrinters === 'function') _liqLoadPrinters(false);
  }
  function _pPickToggleFiltroTipo() {
    // Cycle: null → TICKET → ADHESIVO → ZPL → null
    const tipos = [null, 'TICKET', 'ADHESIVO', 'ZPL'];
    const idx = tipos.indexOf(_pPickState.filtroTipo);
    _pPickState.filtroTipo = tipos[(idx + 1) % tipos.length];
    _pPickActualizarBotones();
    if (typeof _liqLoadPrinters === 'function') _liqLoadPrinters(false);
  }
  function _pPickActualizarBotones() {
    const btnZ = document.getElementById('ppFiltZonaBtn');
    const btnT = document.getElementById('ppFiltTipoBtn');
    if (btnZ) {
      btnZ.textContent = _pPickState.mostrarTodas ? '🌐 todas las zonas' : '📍 mi zona';
      btnZ.style.background = _pPickState.mostrarTodas ? 'rgba(168,85,247,.18)' : 'rgba(99,102,241,.18)';
      btnZ.style.borderColor = _pPickState.mostrarTodas ? 'rgba(168,85,247,.4)' : 'rgba(99,102,241,.4)';
      btnZ.style.color = _pPickState.mostrarTodas ? '#d8b4fe' : '#c4b5fd';
    }
    if (btnT) {
      btnT.textContent = _pPickState.filtroTipo
        ? (_pPickState.filtroTipo === 'TICKET' ? '🧾 tickets'
         : _pPickState.filtroTipo === 'ADHESIVO' ? '🏷 adhesivos'
         : '📄 ZPL')
        : '🧾 todos los tipos';
    }
  }
  // Filtra una lista de impresoras según _pPickState. La consume _liqRenderPrinters.
  function _pPickAplicarFiltros(lista) {
    if (!Array.isArray(lista)) return [];
    return lista.filter(p => {
      if (_pPickState.filtroTipo && String(p.tipo || '').toUpperCase() !== _pPickState.filtroTipo) return false;
      if (!_pPickState.mostrarTodas && _pPickState.filtroZona && p.idZona !== _pPickState.filtroZona) return false;
      return true;
    });
  }

  // ── Render PAGADAS ──
  function _liqRenderPagadas() {
    const body = $('liqBody');
    if (!body) return;
    const list = _liqState.pagadas || [];
    if (!list.length) {
      body.innerHTML = `<div class="liq-empty">
        <div class="liq-empty-emoji">💰</div>
        <div class="text-sm">Sin pagos en este rango</div>
      </div>`;
      return;
    }
    const total = list.reduce((s, b) => s + b.total, 0);
    body.innerHTML = `
      <div class="flex items-center justify-between mb-3 pb-2 border-b border-slate-800">
        <div class="text-xs text-slate-400"><strong class="text-emerald-400">${list.length}</strong> pago(s) registrados</div>
        <div class="text-right">
          <div class="text-[10px] uppercase text-slate-500 tracking-wider">Total pagado</div>
          <div class="text-lg font-bold" style="color:#34d399">${_liqMoney(total)}</div>
        </div>
      </div>
      ${list.map((b, i) => _liqCardBatch(b, i)).join('')}
    `;
  }
  function _liqCardBatch(b, idx) {
    const fecha = b.pagadoTs ? new Date(b.pagadoTs).toLocaleString('es-PE', { day:'2-digit', month:'short', hour:'2-digit', minute:'2-digit' }) : '—';
    const ico = _liqRolIco(b.rol);
    // [v2.41.74] Sello visual según estado
    const anulada = !!b.anulada;
    const stamp = anulada
      ? '<span class="liq-stamp anulado">Anulado</span>'
      : '<span class="liq-stamp pagado">Pagado</span>';
    const cardCls = anulada ? 'liq-batch-card anulada' : 'liq-batch-card';
    return `
      <div class="${cardCls}" style="--i:${Math.min(idx,15)}" onclick="MOS._liqAbrirPagoDet('${b.idPago}', ${idx})">
        ${stamp}
        <div class="flex items-center gap-3">
          <span style="font-size:18px">${ico}</span>
          <div class="flex-1 min-w-0">
            <div class="flex items-center gap-2 flex-wrap">
              <span class="text-sm font-semibold text-slate-200">${b.nombre}</span>
              <span class="text-[10px] font-mono text-slate-500">${b.idPago}</span>
            </div>
            <div class="text-[10px] text-slate-500 mt-0.5">
              ${b.cantidadDias} día(s) · ${fecha} · pagó <strong>${b.pagadoPor}</strong>
            </div>
          </div>
          <div class="text-right">
            <div class="text-base font-bold" style="color:#34d399">${_liqMoney(b.total)}</div>
          </div>
        </div>
      </div>`;
  }

  // [v2.41.55] OPTIMISTA: abrir modal al instante con datos del listado local,
  // pintar skeleton para días, y completar al llegar el fetch. Antes el await
  // bloqueaba el openModal → percibido como lentitud.
  async function _liqAbrirPagoDet(idPago, idx) {
    _liqSfx('open');
    // 1) Datos optimistas desde el listado local de pagadas
    const local = (typeof idx === 'number' ? (_liqState.pagadas || [])[idx] : null)
              || (_liqState.pagadas || []).find(p => p.idPago === idPago);
    const cantDias = local ? local.cantidadDias : 0;
    const titleEl = $('liqPagoDetTitle');
    const subEl   = $('liqPagoDetSubtitle');
    const bodyEl  = $('liqPagoDetBody');
    if (titleEl) titleEl.textContent = local
      ? `${_liqRolIco(local.rol)} ${local.nombre} · ${local.idPago}`
      : `Cargando · ${idPago}`;
    if (subEl) subEl.textContent = local
      ? `${cantDias} día(s) · pagó ${local.pagadoPor} · ${new Date(local.pagadoTs).toLocaleString('es-PE')}`
      : 'Cargando detalle…';
    if (bodyEl) {
      const skeleton = Array.from({ length: Math.max(cantDias, 3) }, () =>
        `<div class="rounded-lg p-2" style="background:rgba(15,23,42,.4);border:1px solid #1e293b">
          <div class="flex items-center justify-between">
            <div class="alm-skel-line w-50" style="height:14px"></div>
            <div class="alm-skel-line w-30" style="height:14px"></div>
          </div>
          <div class="alm-skel-line w-75 mt-2" style="height:10px"></div>
        </div>`
      ).join('');
      bodyEl.innerHTML = skeleton + (local ? `
        <div class="mt-2 pt-2 border-t border-slate-800 flex items-center justify-between">
          <span class="text-sm font-bold text-slate-300">TOTAL</span>
          <span class="text-lg font-bold" style="color:#fbbf24">${_liqMoney(local.total)}</span>
        </div>` : '');
    }
    openModal('modalLiqPagoDet');

    // 2) Fetch real en background y reemplaza el body
    try {
      const res = await API.get('getPagoDetalle', { idPago });
      const d = res && res.data ? res.data : res;
      if (!d) return;
      _liqState.currentPagoDet = d;
      if (titleEl) titleEl.textContent = `${_liqRolIco(d.rol)} ${d.nombre} · ${d.idPago}`;
      if (subEl)   subEl.textContent = `${d.cantidadDias} día(s) · pagó ${d.pagadoPor} · ${new Date(d.pagadoTs).toLocaleString('es-PE')}`;
      if (bodyEl) {
        bodyEl.innerHTML = d.dias.map(dia => {
          const partes = [];
          if (dia.montoBase    > 0) partes.push(`base ${dia.montoBase.toFixed(2)}`);
          if (dia.pagoEnvasado > 0) partes.push(`env ${dia.pagoEnvasado.toFixed(2)}`);
          if (dia.bonoMeta     > 0) partes.push(`+meta ${dia.bonoMeta.toFixed(2)}`);
          if (dia.bonificacion > 0) partes.push(`+bono ${dia.bonificacion.toFixed(2)}`);
          if (dia.sancion      > 0) partes.push(`−san ${dia.sancion.toFixed(2)}`);
          return `<div class="rounded-lg p-2" style="background:rgba(15,23,42,.4);border:1px solid #1e293b">
            <div class="flex items-center justify-between">
              <span class="text-sm text-slate-200">${_liqFmtFechaLarga(dia.fecha)}</span>
              <span class="text-sm font-bold text-amber-400">${_liqMoney(dia.totalDia)}</span>
            </div>
            ${partes.length ? `<div class="text-[10px] text-slate-500 mt-0.5">${partes.join(' · ')}</div>` : ''}
          </div>`;
        }).join('') + `<div class="mt-2 pt-2 border-t border-slate-800 flex items-center justify-between">
          <span class="text-sm font-bold text-slate-300">TOTAL</span>
          <span class="text-lg font-bold" style="color:#fbbf24">${_liqMoney(d.total)}</span>
        </div>`;
      }
    } catch(e) {
      if (bodyEl) bodyEl.innerHTML = `<div class="text-rose-400 text-sm py-4">Error cargando detalle: ${e.message}</div>`;
    }
  }

  // [v2.41.73-B10] Lock anti-doble-click en reimpresión
  let _liqReimpLock = false;
  async function liqReimprimirPago() {
    if (_liqReimpLock) { try { toast('⏳ Ya se está reimprimiendo…', 'info', 2000); } catch(_){} return; }
    _liqReimpLock = true;
    const d = _liqState.currentPagoDet;
    if (!d) { _liqReimpLock = false; return; }
    closeModal('modalLiqPagoDet');
    const printerId = await _liqElegirImpresora();
    if (!printerId) { _liqReimpLock = false; return; }
    try {
      // [dueño 2026-07-14] Reimpresión FIEL: usa el ticket SNAPSHOT guardado al pagar (idéntico al original) e
      // imprime 2 copias (jefa/tesorería + empleado). Si no hay snapshot (pagos viejos, antes de esta versión),
      // cae al builder server `imprimirTicketPago` (que puede diferir — solo para históricos sin snapshot).
      if (d.ticketEscPos) {
        await _liqPrint2Copias(printerId, d.ticketEscPos, 'Comprobante de pago (reimpresion)');
        _liqSfx('success');
        toast('✓ Reimpresión fiel enviada (2 copias)', 'ok');
      } else {
        const res = await API.post('imprimirTicketPago', { idPago: d.idPago, printerId });
        _liqSfx('success');
        toast('✓ Reimpresión enviada (histórico sin snapshot) · job ' + (res.printJobId || ''), 'ok');
      }
    } catch(e) {
      _liqSfx('error');
      toast('Error: ' + e.message, 'error');
    } finally {
      _liqReimpLock = false;
    }
  }

  // [v2.41.83] Migrado a AdminAuthModal universal — antes usaba un modal
  // custom modalLiqAnular con keypad propio. Ahora un solo modal unificado.
  // Reusa _liqEjecutarAnular pero ya con la clave validada.
  async function liqAnularPago() {
    const d = _liqState.currentPagoDet;
    if (!d) return;
    _liqSfx('open');
    const auth = await pedirAuth({
      accion: 'ANULAR_PAGO',
      refDocumento: d.idPago,
      contexto: `Anular pago ${d.idPago} · ${d.nombre} · ${_liqMoney(d.total)}`
    });
    if (!auth) return;
    await _liqEjecutarAnular(d.idPago, auth.clave);
  }

  function _liqCerrarModalAnular() {
    const m = document.getElementById('modalLiqAnular');
    if (m) { m.style.display = 'none'; m.classList.add('hidden'); }
  }
  async function _liqConfirmarAnular() {
    const d = _liqState.currentPagoDet;
    if (!d) return;
    const inp = document.getElementById('liqAnularInput');
    const err = document.getElementById('liqAnularError');
    if (!inp) return;
    const clave = String(inp.value || '').trim();
    if (!clave || clave.length < 4) {
      if (err) err.textContent = 'Ingresa la clave (mín 4 dígitos)';
      inp.focus();
      return;
    }
    if (err) err.textContent = '';
    const btn = document.getElementById('liqAnularOk');
    if (btn) { btn.disabled = true; btn.textContent = '⏳ Anulando...'; }
    await _liqEjecutarAnular(d.idPago, clave);
  }

  async function _liqEjecutarAnular(idPago, claveAdmin) {
    // [v2.41.58] OPTIMISTA: mover el batch de pagadas → quitar visual al instante.
    // Si falla, revertir.
    const pagSnap = (_liqState.pagadas || []).find(p => p.idPago === idPago);
    const idxSnap = pagSnap ? (_liqState.pagadas || []).indexOf(pagSnap) : -1;
    const fechaAfectada = pagSnap?.pagadoTs ? new Date(pagSnap.pagadoTs).toISOString().slice(0, 10) : null;
    if (pagSnap) {
      _liqState.pagadas = (_liqState.pagadas || []).filter(p => p.idPago !== idPago);
      if (_liqState.tab === 'pagadas') _liqRenderPagadas();
    }
    try {
      const res = await API.post('anularPago', { idPago, claveAdmin });
      if (res && res.autorizado === false) {
        // Revertir
        if (pagSnap && idxSnap >= 0) {
          _liqState.pagadas.splice(idxSnap, 0, pagSnap);
          if (_liqState.tab === 'pagadas') _liqRenderPagadas();
        }
        const err = document.getElementById('liqAnularError');
        if (err) err.textContent = res.error || 'Clave incorrecta';
        const btn = document.getElementById('liqAnularOk');
        if (btn) { btn.disabled = false; btn.textContent = '↺ Anular'; }
        _liqSfx('error');
        return;
      }
      _liqSfx('remove');
      _liqCerrarModalAnular();
      closeModal('modalLiqPagoDet');
      toast(`↺ Pago ${idPago} anulado · ${res.anuladas || 0} día(s) volvieron a Pendientes`, 'ok', 4500);
      // Invalidar cache Liq + Finanzas para forzar fetch fresco
      try { _liqCacheClear(); } catch(_){}
      if (fechaAfectada) {
        try { localStorage.removeItem('mos_fin_resum_' + fechaAfectada); } catch(_){}
      }
      // Refresh ambas listas en bg
      await liqLoadCurrent();
      _liqPrefetchTab('pendientes');
      // Notificar a Finanzas si está abierto → repaint del Personal del Día
      if (S.view === 'finanzas' && typeof finCargar === 'function') {
        try { finCargar({ animate: false }); } catch(_){}
      }
    } catch(e) {
      // Revertir
      if (pagSnap && idxSnap >= 0) {
        _liqState.pagadas.splice(idxSnap, 0, pagSnap);
        if (_liqState.tab === 'pagadas') _liqRenderPagadas();
      }
      const err = document.getElementById('liqAnularError');
      if (err) err.textContent = 'Error: ' + (e.message || e);
      const btn = document.getElementById('liqAnularOk');
      if (btn) { btn.disabled = false; btn.textContent = '↺ Anular'; }
      _liqSfx('error');
    }
  }

  // ── Render RESUMEN ──
  // [v2.41.75] Resumen ahora usa state local primero → INSTANT.
  // Fetch en background solo si el state está vacío o cache localStorage está stale.
  function _liqRenderResumen() {
    const body = $('liqBody');
    if (!body) return;
    // 1) Pintar inmediato desde state local o cache
    function pintar(pendArr, pagArr) {
      const totalPend = pendArr.reduce((s,p) => s + p.total, 0);
      const totalPag  = pagArr.reduce( (s,b) => s + b.total, 0);
      const personasPend = pendArr.length;
      const totalDiasPend = pendArr.reduce((s,p) => s + p.cantidadDias, 0);
      const totalBatches  = pagArr.length;
      body.innerHTML = `
        <div class="grid grid-cols-2 gap-3 mb-4">
          <div class="rounded-xl p-4" style="background:linear-gradient(135deg,rgba(251,191,36,.08),rgba(251,191,36,.02));border:1px solid rgba(251,191,36,.3)">
            <div class="text-[10px] uppercase tracking-wider text-amber-400 font-bold">📋 Pendientes</div>
            <div class="text-2xl font-bold mt-1" style="color:#fbbf24">${_liqMoney(totalPend)}</div>
            <div class="text-xs text-slate-500 mt-1">${personasPend} persona(s) · ${totalDiasPend} día(s)</div>
          </div>
          <div class="rounded-xl p-4" style="background:linear-gradient(135deg,rgba(34,197,94,.08),rgba(34,197,94,.02));border:1px solid rgba(34,197,94,.3)">
            <div class="text-[10px] uppercase tracking-wider text-emerald-400 font-bold">💰 Pagadas</div>
            <div class="text-2xl font-bold mt-1" style="color:#34d399">${_liqMoney(totalPag)}</div>
            <div class="text-xs text-slate-500 mt-1">${totalBatches} batch(es)</div>
          </div>
        </div>`;
    }
    const pendLocal = _liqState.pendientes || _liqCacheLoad('pendientes') || null;
    const pagLocal  = _liqState.pagadas    || _liqCacheLoad('pagadas')    || null;
    if (pendLocal && pagLocal) {
      pintar(pendLocal, pagLocal);
    } else {
      // Sin state ni cache → skeleton mientras llega
      body.innerHTML = `<div class="liq-skel-stage">
        <div class="liq-skel-card"></div>
        <div class="liq-skel-card" style="animation-delay:.12s"></div>
      </div>`;
    }
    // 2) Refresh silencioso en bg si state está vacío o cache vieja
    if (!pendLocal || !pagLocal) {
      _liqSetSyncState('loading');
      Promise.all([
        _liqFetchConTimeout('getLiquidacionesPendientes', { desde: _liqState.desde, hasta: _liqState.hasta }, 15000).catch(() => []),
        _liqFetchConTimeout('getLiquidacionesPagadas',    { desde: _liqOffset(_liqHoy(), -89), hasta: _liqHoy() }, 30000).catch(() => [])
      ]).then(([pend, pag]) => {
        const pendArr = Array.isArray(pend) ? pend : ((pend && pend.data) || []);
        const pagArr  = Array.isArray(pag)  ? pag  : ((pag  && pag.data)  || []);
        _liqState.pendientes = pendArr;
        _liqState.pagadas    = pagArr;
        _liqCacheSave('pendientes', pendArr);
        _liqCacheSave('pagadas',    pagArr);
        if (_liqState.tab === 'resumen') pintar(pendArr, pagArr);
        _liqSetSyncState('idle');
      }).catch(() => _liqSetSyncState('error'));
    }
  }

  // Backfill / Inicializar LIQUIDACIONES_DIA
  async function _liqBackfillDia(ev) {
    if (ev && typeof _liqRipple === 'function') _liqRipple(ev);
    const btn = ev?.target?.closest('button');
    if (btn) { btn.disabled = true; btn.textContent = '⏳ Procesando 30 días... (~90s)'; }
    try {
      const res = await Promise.race([
        API.post('backfillLiquidacionesDia', { dias: 30 }),
        new Promise((_, rej) => setTimeout(() => rej(new Error('Timeout — vuelve a intentar, los días que se alcanzaron ya están guardados')), 120000))
      ]);
      _liqSfx('success');
      try {
        const r = btn?.getBoundingClientRect();
        if (r) _liqConfetti(r.left + r.width/2, r.top + r.height/2, '#a78bfa');
      } catch(_){}
      toast(res?.msg || '✓ Inicialización completada', 'ok');
      _liqCacheClear();
      // Recarga pendientes con los datos materializados
      if (_liqState.tab === 'pendientes' || _liqState.tab === 'resumen') {
        await liqLoadCurrent();
      }
    } catch(e) {
      _liqSfx('error');
      toast('Error: ' + (e.message || e), 'error');
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = '🔧 Inicializar / Reconstruir Liquidación Diaria'; }
    }
  }


  // Helper de impresión rápida (legacy compat — no se usa en v2)
  function liqCerrarDetalle() { closeModal('modalLiqDetalle'); }

  // ════════════════════════════════════════════════════════════
  // MÓDULO FINANZAS
  // ════════════════════════════════════════════════════════════
  let _finPL = null;  // último P&L cargado
  let _finBloqueados = { porNombre: {}, fecha: null };  // {nombre.lower: {dispositivos:[...]}} para overlay de rejas persistente
  let _finanzasRefreshTimer = null;

  // ── Cache localStorage ────────────────────────────────────
  const FIN_CACHE_PFX = 'mos_fin_';
  const FIN_CACHE_TTL = 30 * 60 * 1000;  // 30 min
  function _finLoadCache(key) {
    try {
      const raw = localStorage.getItem(FIN_CACHE_PFX + key);
      if (!raw) return null;
      const p = JSON.parse(raw);
      if (Date.now() - (p.ts || 0) > FIN_CACHE_TTL) return null;
      return p.data;
    } catch { return null; }
  }
  function _finSaveCache(key, data) {
    try { localStorage.setItem(FIN_CACHE_PFX + key, JSON.stringify({ ts: Date.now(), data })); } catch {}
  }
  function _finFlash() {
    const v = $('view-finanzas');
    if (!v) return;
    v.classList.remove('alm-flash');
    void v.offsetWidth;
    v.classList.add('alm-flash');
  }

  // [v2.41.78] Actualiza badges del nav Finanzas según estado del día:
  //   • Cajas abiertas → rojo (alerta)
  //   • Liquidaciones pendientes (>0) → amarillo (default)
  //   • Sin pendientes, alguien LIVE → verde con pulso
  //   • Nada → oculto
  function _finUpdateNavBadge(opts) {
    opts = opts || {};
    const sels = ['#finNavBadgeSidebar', '#finNavBadgeBnav'];
    const cajasAbiertas = parseInt(opts.cajasAbiertas) || 0;
    const liqPend       = parseInt(opts.liqPendientes) || 0;
    const live          = !!opts.live;
    sels.forEach(s => {
      const el = document.querySelector(s);
      if (!el) return;
      el.classList.remove('is-live', 'is-alert', 'is-info');
      if (cajasAbiertas > 0) {
        el.textContent = cajasAbiertas > 99 ? '99+' : String(cajasAbiertas);
        el.classList.add('is-alert');
        el.classList.remove('hidden');
        el.title = `${cajasAbiertas} caja(s) abiertas`;
      } else if (liqPend > 0) {
        el.textContent = liqPend > 99 ? '99+' : String(liqPend);
        el.classList.add('is-info');
        el.classList.remove('hidden');
        el.title = `${liqPend} liquidación(es) pendiente(s)`;
      } else if (live) {
        el.textContent = '●';
        el.classList.add('is-live');
        el.classList.remove('hidden');
        el.title = 'Operadores activos ahora';
      } else {
        el.classList.add('hidden');
      }
    });
  }

  // [v2.41.78] Lazy-render de charts Chart.js para evitar bloquear el
  // main thread. Antes renderChart() era síncrono → 200-400ms de freeze
  // al cargar Finanzas (charts 7d + waterfall). Ahora difiere a
  // requestIdleCallback (o setTimeout fallback) → el resto del UI pinta
  // primero, charts aparecen 1-2 frames después sin bloquear.
  // Dedup por id: si llega otra config para el mismo chart antes de
  // que se renderice, gana la última (cancela la previa pendiente).
  const _finChartPending = {};
  function _finChartDeferred(id, config) {
    if (_finChartPending[id]) {
      try { (_finChartPending[id].cancel || (() => {}))(); } catch(_){}
    }
    const run = () => {
      delete _finChartPending[id];
      try { renderChart(id, config); } catch(_){}
    };
    if (typeof window.requestIdleCallback === 'function') {
      const handle = window.requestIdleCallback(run, { timeout: 800 });
      _finChartPending[id] = { cancel: () => window.cancelIdleCallback && window.cancelIdleCallback(handle) };
    } else {
      const t = setTimeout(run, 16);
      _finChartPending[id] = { cancel: () => clearTimeout(t) };
    }
  }
  // Hidratar PL del día actual al cargar el script
  (function _finHidratar() {
    const f = today();
    const cached = _finLoadCache('pl_' + f);
    if (cached) { cached._fechaStamp = f; _finPL = cached; }
  })();

  // [v2.41.78] DEPRECATED el setInterval 60s — ahora todo polling vive
  // en _finStartPolling (30s, único, activo solo en vista Finanzas).
  // Mantenemos la función para el "fetch inmediato al autenticar" que
  // hidrata _finPL desde el login (precarga). Si el user entra a Finanzas
  // antes de que llegue, ya tiene cache; si no, el polling 30s lo
  // refrescará al entrar.
  function _startFinanzasRefresh() {
    _stopFinanzasRefresh();
    _finanzasRefreshSilencioso(); // fetch inmediato post-login (hidrata _finPL)
    // ANTES: setInterval cada 60s — eliminado. _finStartPolling (30s) cubre el rol.
  }
  function _stopFinanzasRefresh() {
    if (_finanzasRefreshTimer) { clearInterval(_finanzasRefreshTimer); _finanzasRefreshTimer = null; }
  }
  // [v2.41.78] Hash rápido de P&L — sustituye JSON.stringify (10KB+ por
  // llamada → CPU spike cada polling). Solo combina los campos que
  // realmente importan para detectar "cambio relevante".
  function _finHashPL(pl) {
    if (!pl) return '';
    const k = [
      pl.ventasNetas, pl.ventasBrutas, pl.tickets, pl.ticketsAnulados,
      pl.efectivo, pl.virtual, pl.credito,
      pl.costoVentas, pl.margenBruto, pl.utilidadNeta,
      pl.unidades, pl.skus, pl.ticketProm, pl.margenProm,
      pl.gastoPersonal, pl.gastoOtros, pl.gastoFijo, pl.gastoVariable,
      (pl.personalDetalle || []).length,
      (pl.gastos || []).length
    ];
    // Sumar también una huella de personalDetalle (suma de totales y
    // nombres) para captar cambios en cards individuales.
    let pdSig = 0;
    (pl.personalDetalle || []).forEach((p, i) => {
      pdSig += (parseFloat(p.totalDia) || 0) * (i + 1);
    });
    k.push(Math.round(pdSig * 100));
    return k.join('|');
  }

  // [v2.41.78] Detección de cambios relevantes entre dos P&L —
  // dispara efectos visuales/sonoros cuando algo importante pasa
  // (venta nueva, ticket anulado, caja nueva, gasto agregado).
  function _finDetectarCambios(plOld, plNew) {
    if (!plOld || !plNew) return null;
    const out = {};
    const dVentas = (parseFloat(plNew.ventasNetas) || 0) - (parseFloat(plOld.ventasNetas) || 0);
    const dTickets = (parseInt(plNew.tickets) || 0) - (parseInt(plOld.tickets) || 0);
    const dAnulados = (parseInt(plNew.anulados) || 0) - (parseInt(plOld.anulados) || 0);
    const dCajas = (parseInt(plNew.cajasAbiertas) || 0) - (parseInt(plOld.cajasAbiertas) || 0);
    if (dVentas > 0.01 && dTickets > 0) { out.ventaNueva = { monto: dVentas, count: dTickets }; }
    if (dAnulados > 0) out.ticketAnulado = { count: dAnulados };
    if (dCajas > 0) out.cajaAbierta = { count: dCajas };
    if (dCajas < 0) out.cajaCerrada = { count: -dCajas };
    return Object.keys(out).length ? out : null;
  }
  function _finCelebrarCambios(cambios) {
    if (!cambios || S.view !== 'finanzas') return;
    if (cambios.ventaNueva) {
      // Flash + bounce del KPI ventas + sonido cash
      const card = document.getElementById('finKpiVentas')?.closest('.alm-card') ||
                   document.getElementById('finKpiVentas');
      if (card) {
        card.classList.remove('fin-kpi-flash');
        void card.offsetWidth;
        card.classList.add('fin-kpi-flash');
        setTimeout(() => card.classList.remove('fin-kpi-flash'), 1200);
      }
      try { _finBeep('agregar'); } catch(_){}
      try {
        toast(`💸 +${cambios.ventaNueva.count} venta${cambios.ventaNueva.count > 1 ? 's' : ''} · S/${cambios.ventaNueva.monto.toFixed(2)}`, 'ok', 3000);
      } catch(_){}
    }
    if (cambios.ticketAnulado) {
      try { _finBeep('eliminar'); } catch(_){}
    }
    if (cambios.cajaAbierta) {
      try { _finBeep('importar'); } catch(_){}
      try { toast(`🛒 ${cambios.cajaAbierta.count} caja${cambios.cajaAbierta.count > 1 ? 's' : ''} abierta${cambios.cajaAbierta.count > 1 ? 's' : ''}`, 'info', 3000); } catch(_){}
    }
    if (cambios.cajaCerrada) {
      try { _finBeep('ok'); } catch(_){}
    }
  }

  async function _finanzasRefreshSilencioso() {
    if (!S.session) return;
    if (document.visibilityState !== 'visible') return;
    iconBusy('finanzas', true);
    try {
      const fecha  = $('finFecha')?.value || today();
      const pl     = await API.get('getFinanzasDia', { fecha });
      // [v2.41.78] Hash rápido en vez de JSON.stringify costoso
      const changedPL = _finHashPL(pl) !== _finHashPL(_finPL);
      // Detectar y celebrar cambios relevantes (venta nueva, caja, anulado)
      const cambios = _finDetectarCambios(_finPL, pl);
      if (pl) pl._fechaStamp = fecha;
      _finPL = pl;
      _finSaveCache('pl_' + fecha, pl);
      if (S.view === 'finanzas') {
        // Pulso del dot indicando refresh silencioso exitoso
        _finPulsoPoll();
        if (changedPL) { _finRender(pl, fecha); _finFlash(); }
        // [v2.41.78] Celebrar cambios DESPUÉS del render (cards ya pintados)
        if (cambios) _finCelebrarCambios(cambios);
        const hasta  = fecha;
        const desde7 = _fechaOffset(fecha, -6);
        const rango  = await API.get('getFinanzasRango', { desde: desde7, hasta });
        _finSaveCache('rango_' + fecha, rango);
        _finRender7d(rango);
      }
      // Refresh también las liquidaciones pendientes (cambian con jornadas auto)
      API.get('getLiquidacionesPendientesSemana', {}).then(r => {
        if (r) {
          _liqSaveCache('pendientes', r);
          // Si el user está en Config → Personal, refrescar el card ME
          if (S.view === 'config' && S.cfgTab === 'personal') {
            try { _cfgRenderMeCajeros(); } catch {}
          }
        }
      }).catch(() => {});
    } catch(_) { /* silencioso */ }
    iconBusy('finanzas', false);
  }

  // ════════════════════════════════════════════════════════════
  // Race-safe token: invalida respuestas obsoletas si el user
  // navega rápido entre días. Solo la última request gana.
  // ════════════════════════════════════════════════════════════
  let _finGenId = 0;
  let _finUltimaFecha = null;

  async function finCargar(opts) {
    opts = opts || {};
    const inpF = $('finFecha');
    if (inpF && !inpF.value) inpF.value = today();
    const fecha = inpF?.value || today();
    const myGen = ++_finGenId;
    const fechaPrev = _finUltimaFecha;
    _finUltimaFecha = fecha;

    // Animar slide si se pidió y hay cambio real de fecha
    const dir = opts.dir;
    const animate = !!opts.animate;
    const slide = $('finSlideContent');
    if (animate && slide && fechaPrev && fechaPrev !== fecha) {
      slide.classList.remove('fin-slide-snap');
      slide.classList.add(dir > 0 ? 'fin-slide-out-left' : 'fin-slide-out-right');
      _finBeep('nav');
      // esperar fade-out antes de pintar lo nuevo
      await new Promise(r => setTimeout(r, 220));
      slide.classList.add('fin-slide-snap');
      slide.classList.remove('fin-slide-out-left', 'fin-slide-out-right');
      slide.classList.add(dir > 0 ? 'fin-slide-in-right' : 'fin-slide-in-left');
      // forzar reflow para que el snap aplique
      void slide.offsetWidth;
      slide.classList.remove('fin-slide-snap');
      requestAnimationFrame(() => {
        slide.classList.remove('fin-slide-in-left', 'fin-slide-in-right');
      });
    }

    _finUpdateBadge(fecha);

    // Marcar inmediatamente la fecha del listado de Personal para que
    // cualquier paint async pendiente (de la fecha previa) sea ignorado.
    // Si la fecha CAMBIÓ, además limpiar el DOM ya — no queremos que el
    // usuario vea el personal del día anterior parado mientras carga.
    const personalCont = $('finPersonalList');
    if (personalCont) {
      const prevFecha = personalCont.dataset.fecha;
      personalCont.dataset.fecha = fecha;
      if (prevFecha && prevFecha !== fecha) {
        personalCont.dataset._lastHtml = ''; // reset anti-flicker
        // [v2.41.58] Skeleton SIEMPRE al cambiar fecha — no dejar info stale.
        // Antes solo mostraba 2 cards skeleton, ahora algo más informativo.
        personalCont.innerHTML = `
          <div class="text-center text-xs text-slate-500 py-3" style="opacity:.7">
            <div class="inline-block animate-spin" style="font-size:14px">⌛</div>
            Cargando ${_formatFechaCorta(fecha)}…
          </div>
          <div class="fin-skel" style="height: 64px;"></div>
          <div class="fin-skel" style="height: 64px;"></div>
          <div class="fin-skel" style="height: 64px;"></div>`;
      }
    }

    // [v2.41.58] Si es refresh silencioso del polling 30s y la fecha NO cambió,
    // NO mostrar skeleton ni invalidar cache — actualizar in-place al final.
    const esSilent = !!opts._silent;

    // 1. Pintar desde cache local si existe (instantáneo) — sino, RESET visual
    //    completo. Evita que el user vea datos del día anterior mezclados con
    //    el nuevo (Personal, Gastos, break-even bar quedaban stale).
    if (!esSilent) {
      const cachedPL = _finLoadCache('pl_' + fecha);
      if (cachedPL) {
        cachedPL._fechaStamp = fecha;
        _finPL = cachedPL;
        try { _finRender(cachedPL, fecha); } catch {}
      } else {
        _finMostrarSkeleton(true);
        _finPL = null;
      }
      const cachedRango = _finLoadCache('rango_' + fecha);
      if (cachedRango) { try { _finRender7d(cachedRango); } catch {} }
    }

    // 2. Fetch fresco en background — actualiza cuando responda
    if (!esSilent) iconBusy('finanzas', true);
    try {
      const pl = await API.get('getFinanzasDia', { fecha });
      // Race check: si el user navegó a otra fecha, descartar esta respuesta
      if (myGen !== _finGenId) return;
      if (pl) pl._fechaStamp = fecha; // stamp para detectar mismatch al reabrir
      _finPL = pl;
      _finSaveCache('pl_' + fecha, pl);

      // Cargar lista de dispositivos bloqueados (encarcelados) para pintar
      // overlay persistente de rejas en cards. Fallback silencioso si falla.
      try {
        const rB = await API.get('getDispositivosBloqueados', { agruparPorNombre: true });
        if (myGen !== _finGenId) return;
        // [Lote3-A · fix A3-MOS] API.get YA desempaqueta d.data → rB = {lista, porNombre}.
        // Antes se exigía rB.ok && rB.data (ambos undefined) → el overlay de rejas NUNCA
        // se pintaba: el admin no veía qué dispositivos estaban bloqueados.
        _finBloqueados = { porNombre: (rB && rB.porNombre) || {}, fecha };
      } catch(_) { _finBloqueados = { porNombre: {}, fecha }; }

      if (!esSilent) _finMostrarSkeleton(false);
      _finRender(pl, fecha);
      if (!esSilent) _finBeep('ok');

      const hasta  = fecha;
      const desde7 = _fechaOffset(fecha, -6);
      const rango  = await API.get('getFinanzasRango', { desde: desde7, hasta });
      if (myGen !== _finGenId) return;
      _finSaveCache('rango_' + fecha, rango);
      _finRender7d(rango);

      // Prefetch ±1 día en background (idle) — para navegación instantánea
      _finPrefetchAdyacentes(fecha);
    } catch(e) {
      if (myGen !== _finGenId) return; // race: ya no nos importa este error
      if (!esSilent) _finMostrarSkeleton(false);
      // Silencioso: no toast en polling background (evita spam si red flota)
      if (!esSilent && !_finPL) toast('Error Finanzas: ' + e.message, 'error');
    } finally {
      if (myGen === _finGenId && !esSilent) iconBusy('finanzas', false);
    }
  }

  // [v2.41.78] Debounce navegación de días — evita salto múltiple en double-click
  let _finDiaLock = false;
  function finDia(delta) {
    if (_finDiaLock) return;
    _finDiaLock = true;
    setTimeout(() => { _finDiaLock = false; }, 260); // tiempo del slide
    const inp = $('finFecha');
    if (!inp) return;
    const cur = inp.value || today();
    const d = new Date(cur + 'T00:00:00');
    d.setDate(d.getDate() + delta);
    inp.value = d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0');
    finCargar({ animate: true, dir: delta });
  }

  function finIrHoy() {
    const inp = $('finFecha');
    if (!inp) return;
    const cur = inp.value;
    const hoy = today();
    if (cur === hoy) {
      // pulso del badge
      const b = $('finDayBadge');
      if (b) { b.classList.add('fin-day-pulse'); setTimeout(() => b.classList.remove('fin-day-pulse'), 280); }
      return;
    }
    const dir = (cur && cur > hoy) ? -1 : 1;
    inp.value = hoy;
    finCargar({ animate: true, dir });
  }

  // ── Badge "Hoy / Ayer / Hace N días / +N días" ──
  function _finUpdateBadge(fecha) {
    const el = $('finDayBadge');
    const lbl = $('finFechaLabel');
    const hoy = today();
    const a = new Date(fecha + 'T00:00:00');
    const h = new Date(hoy + 'T00:00:00');
    const diff = Math.round((a - h) / 86400000);
    if (el) {
      el.classList.remove('fin-day-hoy', 'fin-day-ayer', 'fin-day-past', 'fin-day-futuro');
      let txt = '';
      if (diff === 0)       { txt = '🟢 Hoy';        el.classList.add('fin-day-hoy'); }
      else if (diff === -1) { txt = 'Ayer';          el.classList.add('fin-day-ayer'); }
      else if (diff === 1)  { txt = 'Mañana';        el.classList.add('fin-day-futuro'); }
      else if (diff < 0)    { txt = `Hace ${-diff} días`;   el.classList.add('fin-day-past'); }
      else                  { txt = `+${diff} días`; el.classList.add('fin-day-futuro'); }
      el.textContent = txt;
      el.classList.add('fin-day-pulse');
      setTimeout(() => el.classList.remove('fin-day-pulse'), 280);
    }
    if (lbl) {
      const d = new Date(fecha + 'T00:00:00');
      const txt = d.toLocaleDateString('es-PE', { day:'2-digit', month:'short', year:'2-digit' });
      lbl.textContent = (diff === 0) ? `Hoy · ${txt}` : txt;
    }
  }

  // ── Comparación vs ayer (para el card de Ventas) ────────────
  function _finRenderComparaAyer(pl, fecha) {
    if (!pl || typeof pl !== 'object') return;   // [FIX 500x BUG-2] tolerar null
    const el = $('finVentasComparaAyer');
    if (!el) return;
    try {
      const ayer = _fechaOffset(fecha, -1);
      const cached = _finLoadCache('pl_' + ayer);
      const ventasAyer = cached ? parseFloat(cached.ventasNetas || 0) : 0;
      const ventasHoy = parseFloat(pl.ventasNetas || 0);
      if (!ventasAyer || !cached) {
        el.classList.add('hidden');
        return;
      }
      const diff = ventasHoy - ventasAyer;
      const pct = ventasAyer > 0 ? (diff / ventasAyer * 100) : 0;
      el.classList.remove('hidden', 'up', 'down');
      if (diff >= 0) {
        el.classList.add('up');
        el.innerHTML = '▲ +' + Math.abs(pct).toFixed(0) + '% vs ayer';
      } else {
        el.classList.add('down');
        el.innerHTML = '▼ ' + Math.abs(pct).toFixed(0) + '% vs ayer';
      }
    } catch { el.classList.add('hidden'); }
  }

  // ── Confetti al cruzar break-even ─────────────────────────
  function _finConfetiBE() {
    const canvas = $('finBEConfetti');
    const card = $('finBECardWrap');
    if (!canvas || !card) return;
    const rect = card.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = rect.height;
    canvas.classList.remove('hidden');
    const ctx = canvas.getContext('2d');
    const colores = ['#34d399', '#fbbf24', '#a5b4fc', '#22d3ee', '#f472b6', '#facc15'];
    const piezas = [];
    for (let i = 0; i < 80; i++) {
      piezas.push({
        x: Math.random() * canvas.width,
        y: -10 - Math.random() * 40,
        vx: (Math.random() - 0.5) * 4,
        vy: 2 + Math.random() * 4,
        rot: Math.random() * 360,
        vRot: (Math.random() - 0.5) * 12,
        size: 6 + Math.random() * 6,
        color: colores[Math.floor(Math.random() * colores.length)],
        forma: Math.random() > 0.5 ? 'rect' : 'circle'
      });
    }
    let frames = 0;
    const tick = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      piezas.forEach(p => {
        p.vy += 0.15; // gravedad
        p.x += p.vx;
        p.y += p.vy;
        p.rot += p.vRot;
        ctx.save();
        ctx.translate(p.x, p.y);
        ctx.rotate((p.rot * Math.PI) / 180);
        ctx.fillStyle = p.color;
        if (p.forma === 'rect') ctx.fillRect(-p.size/2, -p.size/2, p.size, p.size * 0.4);
        else { ctx.beginPath(); ctx.arc(0, 0, p.size/2, 0, Math.PI*2); ctx.fill(); }
        ctx.restore();
      });
      frames++;
      if (frames < 180) requestAnimationFrame(tick);
      else { ctx.clearRect(0, 0, canvas.width, canvas.height); canvas.classList.add('hidden'); }
    };
    tick();
  }

  // ── Datepicker del header de Finanzas ─────────────────────
  let _finCalState = null;
  function finAbrirCalendario(btn) {
    const dp = $('finDatepicker');
    if (!dp) return;
    if (!dp.classList.contains('hidden')) { dp.classList.add('hidden'); return; }
    const cur = $('finFecha')?.value || today();
    const d = new Date(cur + 'T00:00:00');
    _finCalState = { y: d.getFullYear(), m: d.getMonth() };
    _finCalRender();
    const r = btn.getBoundingClientRect();
    dp.style.left = Math.max(8, Math.min(window.innerWidth - 250, r.left)) + 'px';
    dp.style.top  = (r.bottom + 6) + 'px';
    dp.classList.remove('hidden');
    setTimeout(() => {
      const closer = e => {
        if (!dp.contains(e.target) && !btn.contains(e.target)) {
          dp.classList.add('hidden');
          document.removeEventListener('click', closer);
        }
      };
      document.addEventListener('click', closer);
    }, 50);
  }
  function finCalNavMes(delta) {
    if (!_finCalState) return;
    let { y, m } = _finCalState;
    m += delta;
    if (m < 0)  { m = 11; y--; }
    if (m > 11) { m = 0; y++; }
    _finCalState = { y, m };
    _finCalRender();
  }
  function _finCalRender() {
    const grid = $('finCalGrid');
    const lbl  = $('finCalMesAnio');
    if (!grid || !_finCalState) return;
    const { y, m } = _finCalState;
    const meses = ['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'];
    if (lbl) lbl.textContent = `${meses[m]} ${y}`;
    const primero = new Date(y, m, 1);
    let primerDow = primero.getDay();
    primerDow = primerDow === 0 ? 6 : primerDow - 1;
    const ultimo = new Date(y, m + 1, 0).getDate();
    const hoy = today();
    const sel = $('finFecha')?.value || hoy;
    let html = '';
    for (let i = 0; i < primerDow; i++) html += '<button class="log-cal-day empty"></button>';
    for (let dia = 1; dia <= ultimo; dia++) {
      const f = `${y}-${String(m + 1).padStart(2, '0')}-${String(dia).padStart(2, '0')}`;
      const cls = ['log-cal-day'];
      if (f === hoy) cls.push('today');
      if (f === sel) cls.push('selected');
      html += `<button class="${cls.join(' ')}" onclick="MOS.finElegirFecha('${f}')">${dia}</button>`;
    }
    grid.innerHTML = html;
  }
  function finElegirFecha(f) {
    const inp = $('finFecha');
    if (!inp) return;
    const prev = inp.value;
    inp.value = f;
    $('finDatepicker')?.classList.add('hidden');
    finCargar({ animate: true, dir: f > prev ? 1 : -1 });
  }

  // Ir a una fecha específica desde el mini-row de 7 días
  function finIrAFecha(f) {
    const inp = $('finFecha');
    if (!inp) return;
    const prev = inp.value || today();
    if (f === prev) return;
    inp.value = f;
    finCargar({ animate: true, dir: f > prev ? 1 : -1 });
  }

  // ── Indicador visual del polling silencioso ─────────────
  function _finPulsoPoll() {
    const dot = $('finPollDot');
    if (!dot) return;
    dot.classList.add('active');
    setTimeout(() => dot.classList.remove('active'), 1300);
  }

  // ── Skeleton on/off — reset visual completo de TODO ──
  // Cuando el user navega a un día sin caché, evita ver datos del día anterior.
  // Pinta shimmer en KPIs + Personal + Gastos + break-even bar.
  function _finMostrarSkeleton(on) {
    const slide = $('finSlideContent');
    if (slide) slide.classList.toggle('fin-skel-on', !!on);
    if (!on) return;

    // Lists
    const pl = $('finPersonalList');
    if (pl) pl.innerHTML = `
      <div class="fin-skel" style="height: 64px;"></div>
      <div class="fin-skel" style="height: 64px;"></div>
      <div class="fin-skel" style="height: 64px;"></div>`;
    const gl = $('finGastosList');
    if (gl) gl.innerHTML = `
      <div class="fin-skel" style="height: 28px;"></div>
      <div class="fin-skel" style="height: 28px;"></div>`;
    const cat = $('finGastosCateg');
    if (cat) cat.innerHTML = '';

    // Totales que se actualizan fuera del countup (textContent directo)
    const totGastos = $('finGastosTotal');
    if (totGastos) totGastos.textContent = 'S/ —';
    const totPer = $('finPersonalTotal');
    if (totPer) { totPer.textContent = 'S/ —'; totPer.dataset._anim = '0'; }

    // Reset data-attrs de los KPIs con countup → próxima animación arranca de 0
    ['finKpiVentas','finKpiCosto','finKpiGastos','finKpiUtil','finBECostosFijos']
      .forEach(id => { const el = $(id); if (el) { el.dataset._anim = '0'; el.textContent = 'S/ —'; } });

    // Break-even bar y línea — colapsar a 0
    const bar = $('finBEBarVentas');
    if (bar) { bar.style.width = '0%'; bar.dataset._beAnim = '0'; }
    const lin = $('finBELinea');
    if (lin) lin.style.left = '0%';
    const beMeta = $('finBEMeta');
    if (beMeta) beMeta.innerHTML = 'Meta: <span class="_beNum">—</span>';
    const beVent = $('finBEVentas');
    if (beVent) beVent.innerHTML = 'Ventas: <span class="_bevNum">—</span>';
    const beMC = $('finBEMargenC');
    if (beMC) beMC.textContent = '—%';
    const beBadge = $('finBEBadge');
    if (beBadge) {
      beBadge.textContent = '...';
      beBadge.className = 'text-xs font-bold px-2 py-0.5 rounded-full bg-slate-800 text-slate-500';
    }

    // KPI textos no-numéricos
    const tk = $('finKpiTickets');     if (tk) tk.textContent = '— tickets';
    const mb = $('finKpiMargenB');     if (mb) mb.textContent = 'Margen bruto —%';
    const pe = $('finKpiPersonas');    if (pe) pe.textContent = '— personas';
    const mn = $('finKpiMargenN');     if (mn) mn.textContent = 'Margen neto —%';
    const ef = $('finKpiEfectivo');    if (ef) ef.textContent = 'S/ —';
    const vi = $('finKpiVirtual');     if (vi) vi.textContent = 'S/ —';
    const cr = $('finKpiCredito');     if (cr) cr.textContent = 'S/ —';
    const cs = $('finKpiCreditoSub');  if (cs) cs.textContent = '— tickets POR_COBRAR';
    const an = $('finKpiAnulados');    if (an) an.textContent = '— tickets';
    const un = $('finKpiUnidades');    if (un) un.textContent = '—';
    const sk = $('finKpiSkus');        if (sk) sk.textContent = '—';
    const tp = $('finKpiTicketProm');  if (tp) tp.textContent = '—';
    const mp = $('finKpiMargenProm');  if (mp) mp.textContent = '—';
    const me = $('finKpiMargenEstim'); if (me) me.textContent = '';
  }

  // ── Prefetch ±1 día en background (no espera) ──
  function _finPrefetchAdyacentes(fecha) {
    const target = [
      _fechaOffset(fecha, -1),
      _fechaOffset(fecha, +1),
    ];
    // setTimeout para esperar que el navegador esté idle
    setTimeout(() => {
      target.forEach(f => {
        if (_finLoadCache('pl_' + f)) return; // ya cacheado
        API.get('getFinanzasDia', { fecha: f })
          .then(pl => _finSaveCache('pl_' + f, pl))
          .catch(() => {});
      });
    }, 800);
  }

  // ════════════════════════════════════════════════════════════
  // Sonidos de Finanzas — SIEMPRE suenan (efectos de UI son parte
  // de la interacción, no se mutean desde la app).
  // ════════════════════════════════════════════════════════════
  let _finAudioCtx = null;

  function _finBeep(tipo) {
    try {
      if (!_finAudioCtx) _finAudioCtx = new (window.AudioContext || window.webkitAudioContext)();
      const ctx = _finAudioCtx;
      const t0 = ctx.currentTime;
      const tone = (freq, dur, gain, type, t) => {
        const o = ctx.createOscillator();
        const g = ctx.createGain();
        o.connect(g); g.connect(ctx.destination);
        o.type = type || 'sine';
        o.frequency.setValueAtTime(freq, t);
        g.gain.setValueAtTime(gain, t);
        g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
        o.start(t); o.stop(t + dur + 0.02);
      };
      const sweep = (f1, f2, dur, gain, type, t) => {
        const o = ctx.createOscillator();
        const g = ctx.createGain();
        o.connect(g); g.connect(ctx.destination);
        o.type = type || 'sine';
        o.frequency.setValueAtTime(f1, t);
        o.frequency.exponentialRampToValueAtTime(f2, t + dur);
        g.gain.setValueAtTime(gain, t);
        g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
        o.start(t); o.stop(t + dur + 0.02);
      };
      switch (tipo) {
        case 'nav':         // tic agudo (cambio día)
          sweep(1800, 900, 0.05, 0.05, 'sine', t0);
          break;
        case 'ok':          // ding suave (acción confirmada)
          tone(1320, 0.18, 0.04, 'sine', t0);
          break;
        case 'veto':        // tono grave descendente + eco (rejas cayendo)
          sweep(880, 220, 0.32, 0.10, 'sawtooth', t0);
          tone(160, 0.30, 0.06, 'sine', t0 + 0.10);
          break;
        case 'rehab':       // tres notas ascendentes (campana liberadora)
          [523.25, 659.25, 783.99].forEach((f, i) =>
            tone(f, 0.20, 0.08, 'triangle', t0 + i * 0.08));
          break;
        case 'bloquear':    // chasquido de cerrojo: dos thuds graves rápidos
          sweep(420, 90, 0.08, 0.12, 'square', t0);
          sweep(380, 80, 0.10, 0.10, 'square', t0 + 0.09);
          break;
        case 'desbloquear': // cerrojo abriéndose: thud + ascenso ligero
          sweep(180, 90, 0.08, 0.10, 'square', t0);
          sweep(440, 880, 0.12, 0.06, 'triangle', t0 + 0.10);
          break;
        case 'agregar':     // chink moneda (gasto/jornada agregado)
          tone(880, 0.06, 0.06, 'triangle', t0);
          tone(1320, 0.12, 0.05, 'triangle', t0 + 0.04);
          break;
        case 'eliminar':    // whoosh corto descendente
          sweep(660, 220, 0.14, 0.06, 'sine', t0);
          break;
        case 'importar':    // cascada: 5 chinks rápidos ascendentes
          [659, 740, 880, 988, 1175].forEach((f, i) =>
            tone(f, 0.07, 0.045, 'triangle', t0 + i * 0.045));
          break;
        case 'audit':       // dos notas estables (auditando)
          tone(880, 0.10, 0.05, 'sine', t0);
          tone(1108, 0.14, 0.05, 'sine', t0 + 0.10);
          break;
        case 'breakeven':   // ¡fanfare! C-E-G-C celebración
          [523.25, 659.25, 783.99, 1046.5].forEach((f, i) =>
            tone(f, 0.28, 0.09, 'triangle', t0 + i * 0.10));
          break;
        case 'kpi-up':      // sutil tono ascendente (KPI mejora)
          sweep(660, 990, 0.10, 0.04, 'sine', t0);
          break;
        case 'kpi-down':    // sutil tono descendente (KPI empeora)
          sweep(660, 440, 0.12, 0.04, 'sine', t0);
          break;
        case 'error':       // buzz grave (acción bloqueada/falló)
          tone(220, 0.14, 0.10, 'square', t0);
          tone(180, 0.16, 0.08, 'square', t0 + 0.10);
          break;
        case 'click':       // click neutral
          tone(2000, 0.025, 0.04, 'sine', t0);
          break;
        case 'dinero':      // ¡cha-ching! caja registradora
          // Pulso metálico + 3 notas brillantes ascendentes
          tone(2400, 0.04, 0.08, 'square', t0);           // klick metálico
          tone(1046.5, 0.10, 0.10, 'triangle', t0 + 0.02); // C6
          tone(1318.5, 0.12, 0.10, 'triangle', t0 + 0.08); // E6
          tone(1568.0, 0.18, 0.12, 'triangle', t0 + 0.14); // G6
          // Cola sutil aguda como el "ting" de cajón
          tone(2637.0, 0.20, 0.05, 'sine', t0 + 0.18);    // E7 alto
          break;
        default:
          tone(1320, 0.18, 0.04, 'sine', t0);
      }
    } catch {}
  }

  // Reemplaza el HTML de un card específico tras una acción (vetar/rehabilitar)
  // sin tocar el resto. Evita parpadeo y mantiene el botón actualizado a su
  // nuevo estado (💸 ↔ 💵).
  function _finReemplazarCardJornada(idJornada, fecha, idMega) {
    if (!_finPL || !Array.isArray(_finPL.personalDetalle)) return;
    // [100x · A4b] localizar por idMega (único). idJornada está VACÍO en las filas de la
    // mega tabla → find/selector por idJornada matcheaba la PRIMERA card → reemplazaba la
    // equivocada. El mismo criterio que finVetarPago (v2.43.382).
    const clave = idMega || idJornada || '__nope__';
    const p = _finPL.personalDetalle.find(x =>
      (idMega && String(x.idPersonal) === String(idMega)) || (idJornada && String(x.idJornada) === String(idJornada)));
    if (!p) return;
    let ev = null;
    try {
      const raw = localStorage.getItem('mos_fin_resum_' + fecha);
      if (raw) {
        const parsed = JSON.parse(raw);
        if (Array.isArray(parsed.data)) {
          ev = parsed.data.find(r =>
            (r.idPersonal && r.idPersonal === p.idPersonal) ||
            (String(r.nombre || '').toLowerCase().trim() === String(p.nombre || '').toLowerCase().trim())
          );
        }
      }
    } catch {}
    const cards = document.querySelectorAll('.eval-card');
    for (const c of cards) {
      // Match por botón vetar O rehabilitar que contenga la clave (idMega)
      if (c.querySelector(`button[onclick*="finVetarPago"][onclick*="${clave}"]`) ||
          c.querySelector(`button[onclick*="finRehabilitarPago"][onclick*="${clave}"]`)) {
        const wrap = document.createElement('div');
        wrap.innerHTML = _finRenderPersonalCard(p, ev || null, fecha).trim();
        const nuevo = wrap.firstElementChild;
        if (nuevo) c.replaceWith(nuevo);
        return;
      }
    }
  }


  // ── Atajos de teclado en la vista Finanzas ──
  document.addEventListener('keydown', e => {
    // Ignorar si el foco está en input/textarea
    const tag = (document.activeElement?.tagName || '').toLowerCase();
    if (tag === 'input' || tag === 'textarea' || tag === 'select') return;
    // Solo si la vista Finanzas está visible
    const view = $('view-finanzas');
    if (!view || view.classList.contains('hidden')) return;
    if (e.key === 'ArrowLeft')  { e.preventDefault(); finDia(-1); }
    else if (e.key === 'ArrowRight') { e.preventDefault(); finDia(1); }
    else if (e.key === ' ') { e.preventDefault(); finIrHoy(); }
  });

  function _finRender(pl, fecha, opts) {
    // [FIX 500x BUG-2] getFinanzasDia puede resolver null (hipo transitorio; _conFallbackMOS ya no cae a GAS).
    // No renderizar con null (crashea en pl.ventasNetas fuera de try) → conservar el dashboard actual.
    if (!pl || typeof pl !== 'object') return;
    opts = opts || {};
    const skipPersonal = !!opts.skipPersonal;
    const fmt  = v => 'S/ ' + parseFloat(v || 0).toFixed(2);
    const pct  = v => parseFloat(v || 0).toFixed(1) + '%';

    // [v2.41.78] Actualizar badge del nav Finanzas con datos en vivo.
    // Solo cuando pintamos HOY (no días pasados/futuros).
    try {
      const hoy = today();
      if (fecha === hoy) {
        const cajasAbiertas = parseInt(pl.cajasAbiertas) || 0;
        // Liq pendientes lo leemos del cache si está
        let liqPend = 0;
        try {
          const raw = localStorage.getItem('mos_liq2_pendientes');
          if (raw) {
            const p = JSON.parse(raw);
            liqPend = ((p.data && p.data.length) || 0);
          }
        } catch(_){}
        // "live" si alguien tiene Ultima_Conexion en últimos 5min
        let live = false;
        try {
          if (Array.isArray(pl.personalDetalle)) {
            for (const p of pl.personalDetalle) {
              const ultCx = _finBuscarActividadPersonal(p, null);
              if (ultCx) {
                const t = _parseTsUtc(ultCx);
                if (!isNaN(t) && Date.now() - t < 5 * 60 * 1000) { live = true; break; }
              }
            }
          }
        } catch(_){}
        _finUpdateNavBadge({ cajasAbiertas, liqPendientes: liqPend, live });
      } else {
        _finUpdateNavBadge({}); // ocultar si vemos días pasados
      }
    } catch(_){}

    // KPI cards — los montos animan countup
    _animateCount('finKpiVentas', pl.ventasNetas, { prefix: 'S/ ' });
    _setText('finKpiTickets', pl.tickets + ' ticket' + (pl.tickets !== 1 ? 's' : '') +
             (pl.anulados ? ' · ' + pl.anulados + ' anulado' + (pl.anulados > 1 ? 's' : '') : ''));
    _animateCount('finKpiCosto', pl.costoVentas, { prefix: 'S/ ' });
    _setText('finKpiMargenB', 'Margen bruto ' + pct(pl.margenBrutoPct));
    // Barra del margen bruto (visual)
    const margenBarFill = $('finMargenBarFill');
    if (margenBarFill) {
      const mb = Math.max(0, Math.min(parseFloat(pl.margenBrutoPct || 0), 100));
      margenBarFill.style.width = mb.toFixed(1) + '%';
      margenBarFill.style.background = mb >= 30
        ? 'linear-gradient(90deg, #10b981, #34d399)'
        : (mb >= 15 ? 'linear-gradient(90deg, #f59e0b, #fbbf24)'
                    : 'linear-gradient(90deg, #dc2626, #f87171)');
    }
    _animateCount('finKpiGastos', pl.totalGastos, { prefix: 'S/ ' });
    _setText('finKpiPersonas', pl.personas + ' persona' + (pl.personas !== 1 ? 's' : ''));
    _animateCount('finKpiUtil', pl.utilidadNeta, { prefix: 'S/ ' });
    _setText('finKpiMargenN', 'Margen neto ' + pct(pl.margenNetoPct));

    // ── Métodos de pago: barra proporcional efectivo/virtual ──
    const ef = parseFloat(pl.cobradoEfectivo || 0);
    const vi = parseFloat(pl.cobradoVirtual || 0);
    const totalCobrado = ef + vi;
    _setText('finKpiEfectivo', fmt(ef));
    _setText('finKpiVirtual',  fmt(vi));
    const efPct = totalCobrado > 0 ? (ef / totalCobrado * 100) : 50;
    const viPct = totalCobrado > 0 ? (vi / totalCobrado * 100) : 50;
    const barEf = $('finPagoBarEf');
    const barVi = $('finPagoBarVi');
    if (barEf) barEf.style.width = efPct.toFixed(1) + '%';
    if (barVi) barVi.style.width = viPct.toFixed(1) + '%';
    _setText('finPagoPctEf', efPct.toFixed(0) + '%');
    _setText('finPagoPctVi', viPct.toFixed(0) + '%');

    // Crédito + Anulados (slim)
    _setText('finKpiCredito',  fmt(pl.creditoOtorgado || 0));
    _setText('finKpiCreditoSub', (pl.creditos || 0) + ' ticket' + (pl.creditos === 1 ? '' : 's') + ' por cobrar');
    _setText('finKpiAnulados', (pl.anulados || 0) + ' ticket' + (pl.anulados === 1 ? '' : 's'));

    // Comparación vs ayer (Ventas)
    _finRenderComparaAyer(pl, fecha);

    // KPI Productos vendidos
    _setText('finKpiUnidades',   pl.unidadesVendidas ?? '—');
    _setText('finKpiSkus',       pl.skusDistintos    ?? '—');
    _setText('finKpiTicketProm', pl.ticketPromedio   ? 'S/ ' + parseFloat(pl.ticketPromedio).toFixed(2) : '—');

    // Margen Promedio + estimados
    const margenProm = parseFloat(pl.margenPromedioPct || 0);
    const defaultMargen = parseFloat(pl.defaultMargenUsado || 20);
    const cantEstim = parseInt(pl.cantidadEstimados || 0);
    const margenEl = $('finKpiMargenProm');
    if (margenEl) {
      margenEl.textContent = (pl.itemsVendidos > 0 ? margenProm.toFixed(1) + '%' : '—');
      // Color: si margen >= default → emerald; si < default → ámbar
      margenEl.style.color = pl.itemsVendidos > 0
        ? (margenProm >= defaultMargen ? '#34d399' : '#fbbf24')
        : '#475569';
    }
    const estimEl = $('finKpiMargenEstim');
    if (estimEl) {
      if (cantEstim > 0) {
        estimEl.textContent = `${cantEstim} SKU${cantEstim === 1 ? '' : 's'} estim. al ${defaultMargen}%`;
      } else {
        estimEl.textContent = pl.itemsVendidos > 0 ? '✓ todos con costo real' : '';
      }
    }

    // ⚠ inline junto a "Productos Vendidos" si hay SKUs sin costo
    const sinCostoIcon = $('finSinCostoAlerta');
    if (sinCostoIcon) sinCostoIcon.classList.toggle('hidden', !(pl.productosSinCosto?.length));

    // ── BREAK-EVEN dramático ─────────────────────────────
    const beCard  = $('finBECardWrap');
    const beMeta  = $('finBEMeta');
    const beVent  = $('finBEVentas');
    const beFalta = $('finBEFaltaTxt');
    const beEmoji = $('finBEEmoji');
    const beEstado = $('finBEEstado');
    const beResLabel = $('finBEResultadoLabel');
    if (pl.breakEvenVentas) {
      if (beMeta) beMeta.textContent = 'Meta: S/ ' + parseFloat(pl.breakEvenVentas).toFixed(2);
    } else {
      if (beMeta) beMeta.textContent = 'Meta: —';
    }
    if (beVent) beVent.textContent = 'Ventas: S/ ' + parseFloat(pl.ventasNetas || 0).toFixed(2);
    _animateCount('finBECostosFijos', pl.costosFijos, { prefix: 'S/ ' });
    _setText('finBEMargenC', pct(pl.margenContribPct));

    // Barra: ventas como % de la meta. Si supera, llena al 100% y el marker
    // cae más allá del meta-line. Si no, marker en proporción.
    const barV = $('finBEBarVentas');
    const linBE = $('finBELinea');
    const marker = $('finBEMarker');
    const ventasN = parseFloat(pl.ventasNetas || 0);
    const meta = parseFloat(pl.breakEvenVentas || 0);
    const escala = Math.max(meta * 1.2, ventasN * 1.05, 1); // escala dinámica para que el marker se vea
    const fillPctNew = Math.min((ventasN / escala) * 100, 100);
    const metaPct    = meta > 0 ? Math.min((meta / escala) * 100, 100) : 0;
    const oldFillPct = parseFloat(barV?.dataset?._beAnim) || 0;
    if (barV) {
      barV.style.width = fillPctNew.toFixed(1) + '%';
      barV.dataset._beAnim = String(fillPctNew);
    }
    if (linBE) linBE.style.left = metaPct.toFixed(1) + '%';
    if (marker) marker.style.left = fillPctNew.toFixed(1) + '%';

    // Estado dramático: alcanzado / cerca / lejos
    if (beCard) {
      beCard.classList.toggle('alcanzado', !!pl.superaBreakEven);
      beCard.classList.toggle('lejos', !pl.superaBreakEven && ventasN < meta * 0.5 && meta > 0);
    }
    if (beEmoji) beEmoji.textContent = pl.superaBreakEven ? '🎉' : (ventasN < meta * 0.5 ? '⚠️' : '⚖️');
    if (beEstado) {
      if (!meta) beEstado.textContent = 'Sin datos suficientes';
      else if (pl.superaBreakEven) beEstado.textContent = '🚀 Cubriste costos · ¡estás ganando!';
      else if (ventasN < meta * 0.5) beEstado.textContent = '⚠ Falta mucho · ' + (Math.round((ventasN/meta)*100)) + '% de la meta';
      else beEstado.textContent = '⏳ A buen ritmo · ' + (Math.round((ventasN/meta)*100)) + '% de la meta';
    }
    if (beFalta) {
      const falta = Math.max(0, meta - ventasN);
      if (pl.superaBreakEven) beFalta.textContent = '✓ Excedente: S/ ' + (ventasN - meta).toFixed(2);
      else if (meta > 0) beFalta.textContent = 'Faltan S/ ' + falta.toFixed(2);
      else beFalta.textContent = '—';
    }
    if (beResLabel) beResLabel.textContent = pl.utilidadNeta >= 0 ? '✓ UTILIDAD NETA' : '✗ PÉRDIDA NETA';

    // Confetti + sonido al CRUZAR break-even (de no superar a superar)
    if (beCard && pl.superaBreakEven && oldFillPct > 0 && fillPctNew >= 100 &&
        !beCard.dataset._celebrado) {
      // Marcar para no repetir confetti hasta nuevo render con cambio
      beCard.dataset._celebrado = '1';
      _finBeep('breakeven');
      _finConfetiBE();
      setTimeout(() => { delete beCard.dataset._celebrado; }, 8000);
    }
    // Pulso de atención al moverse significativamente
    if (Math.abs(fillPctNew - oldFillPct) > 2 && oldFillPct > 0 && beCard) {
      beCard.style.transition = 'box-shadow 0.4s ease-out';
      beCard.style.boxShadow = pl.superaBreakEven
        ? '0 0 32px rgba(52,211,153,0.55)'
        : '0 0 32px rgba(251,191,36,0.45)';
      setTimeout(() => { beCard.style.boxShadow = ''; }, 700);
    }

    // Waterfall + pill de Utilidad Neta
    _finRenderWaterfall(pl);
    const wPill = $('finWaterUtil');
    if (wPill) {
      wPill.textContent = (pl.utilidadNeta >= 0 ? '+' : '') + 'S/ ' + parseFloat(pl.utilidadNeta || 0).toFixed(2);
      wPill.classList.toggle('up', pl.utilidadNeta >= 0);
      wPill.classList.toggle('down', pl.utilidadNeta < 0);
    }

    // Personal list
    if (!skipPersonal) {
      _finRenderPersonal(pl, fecha);
    } else {
      const tot = $('finPersonalTotal');
      if (tot) _animateCount(tot, pl.gastoPersonal || 0, { prefix: 'S/ ' });
    }
    // Subtítulo del card Personal
    const persSub = $('finPersonalSub');
    if (persSub) {
      const n = pl.personas || 0;
      // [738] Dos verdades en una línea: el pill es el GASTO (lo que la empresa debe);
      // si hubo consumo a crédito, aquí se dice cuánto de eso sale de verdad en efectivo.
      const _consDia = parseFloat(pl._consumoPersonalDia) || 0;
      const _base = n > 0 ? `${n} persona${n !== 1 ? 's' : ''} hoy` : 'Sin personal todavía';
      const _caja = (_consDia > 0 && n > 0)
        ? ` · S/ ${((parseFloat(pl.gastoPersonal) || 0) - _consDia).toFixed(2)} sale de caja`
        : '';
      persSub.textContent = _base + _caja;
      persSub.title = _consDia > 0
        ? `Gasto de personal S/ ${(parseFloat(pl.gastoPersonal) || 0).toFixed(2)} − consumo a crédito S/ ${_consDia.toFixed(2)} (se cobra en la liquidación) = efectivo S/ ${((parseFloat(pl.gastoPersonal) || 0) - _consDia).toFixed(2)}`
        : '';
    }

    // Gastos list (con modo slim cuando no hay)
    _finRenderGastos(pl, fecha);
  }

  function _finRenderWaterfall(pl) {
    const labels = ['Ventas', 'Costo V.', 'Util. Bruta', 'Personal', 'Gastos', 'Util. Neta'];
    // Floating bars [min, max]
    const utilBruta = pl.utilidadBruta;
    const utilNeta  = pl.utilidadNeta;
    const gastosOtros = pl.gastoOtros;
    const gastoPer  = pl.gastoPersonal;

    const data = [
      [0, pl.ventasNetas],                               // Ventas
      [utilBruta, pl.ventasNetas],                        // Costo V. (baja desde ventas)
      [0, utilBruta],                                     // Util Bruta (resultado)
      [utilBruta - gastoPer, utilBruta],                  // Personal (baja)
      [utilBruta - gastoPer - gastosOtros, utilBruta - gastoPer], // Gastos (baja)
      [0, utilNeta]                                       // Util Neta (resultado final)
    ];
    const colors = [
      '#10b981','#f87171','#34d399','#f59e0b','#fb923c',
      utilNeta >= 0 ? '#818cf8' : '#f87171'
    ];

    _finChartDeferred('finChartWaterfall', {
      type: 'bar',
      data: {
        labels,
        datasets: [{ data, backgroundColor: colors, borderRadius: 5, borderSkipped: false }]
      },
      options: {
        responsive: true, maintainAspectRatio: false,
        plugins: { legend: { display: false },
          tooltip: {
            callbacks: {
              label: ctx => {
                const [min, max] = ctx.raw;
                return 'S/ ' + Math.abs(max - min).toFixed(2);
              }
            }
          }
        },
        scales: {
          x: { grid: { color: '#1e293b' }, ticks: { color: '#64748b', font: { size: 11 } } },
          y: { grid: { color: '#1e293b' }, ticks: { color: '#64748b',
               callback: v => 'S/' + v.toFixed(0) } }
        }
      }
    });
  }

  function _finRender7d(rango) {
    if (!rango || !rango.serie) return;
    const labels = rango.serie.map(d => {
      const dt = new Date(d.fecha + 'T00:00:00');
      return dt.toLocaleDateString('es-PE', { weekday:'short', day:'numeric' });
    });
    const ventas  = rango.serie.map(d => d.ventasNetas);
    const costos  = rango.serie.map(d => d.costoVentas);
    const gastos  = rango.serie.map(d => d.totalGastos);
    const util    = rango.serie.map(d => d.utilidadNeta);

    const totalUtil = rango.totales?.utilidadNeta || 0;
    const pill = $('fin7dTotal');
    if (pill) {
      pill.textContent = (totalUtil >= 0 ? '+' : '') + 'S/ ' + totalUtil.toFixed(2);
      pill.classList.toggle('up', totalUtil >= 0);
      pill.classList.toggle('down', totalUtil < 0);
    }
    _setText('fin7dSubtitulo', `Tendencia · S/ ${rango.totales?.ventasNetas?.toFixed(2) || '0'} en ventas`);

    // Mini bars row (drill-down rápido por día)
    const miniRow = $('fin7dMiniRow');
    if (miniRow) {
      const hoy = today();
      const maxAbs = Math.max.apply(null, util.map(u => Math.abs(u || 0)).concat([1]));
      miniRow.innerHTML = rango.serie.map((d, i) => {
        const u = d.utilidadNeta || 0;
        const h = Math.max(8, Math.min(28, Math.abs(u) / maxAbs * 28));
        const dt = new Date(d.fecha + 'T00:00:00');
        const dia = dt.toLocaleDateString('es-PE', { weekday:'short' });
        const cls = ['fin-7d-mini-day'];
        if (d.fecha === hoy) cls.push('today');
        if (u > 0) cls.push('profit-up');
        else if (u < 0) cls.push('profit-down');
        return `<button class="${cls.join(' ')}" onclick="MOS.finIrAFecha('${d.fecha}')" title="${d.fecha} · S/ ${u.toFixed(2)}">
          <div class="fin-7d-mini-bar" style="height:${h}px"></div>
          <div class="fin-7d-mini-lbl">${dia.slice(0,3)}</div>
        </button>`;
      }).join('');
    }

    _finChartDeferred('finChart7d', {
      type: 'bar',
      data: {
        labels,
        datasets: [
          { label: 'Ventas',    data: ventas, backgroundColor: 'rgba(16,185,129,.5)',  borderRadius: 4 },
          { label: 'Costo V.',  data: costos, backgroundColor: 'rgba(248,113,113,.5)', borderRadius: 4 },
          { label: 'Gastos',    data: gastos, backgroundColor: 'rgba(245,158,11,.5)',  borderRadius: 4 },
          { label: 'Util.Neta', data: util,   backgroundColor: 'rgba(129,140,248,.85)',borderRadius: 4, type: 'line', tension: 0.35, pointRadius: 4, fill: false }
        ]
      },
      options: {
        responsive: true, maintainAspectRatio: false,
        plugins: { legend: { labels: { color: '#64748b', boxWidth: 10, font: { size: 11 } } } },
        scales: {
          x: { stacked: false, grid: { color: '#1e293b' }, ticks: { color: '#64748b', font: { size: 10 } } },
          y: { grid: { color: '#1e293b' }, ticks: { color: '#64748b', callback: v => 'S/'+v } }
        }
      }
    });
  }

  // Clasifica rol en POS (cajero/vendedor) vs ALMACEN (almacenero/envasador) vs OTRO
  function _finClasificarRol(rol) {
    const r = String(rol || '').toUpperCase().trim();
    if (r === 'CAJERO' || r === 'VENDEDOR') return 'POS';
    if (r === 'ALMACENERO' || r === 'ENVASADOR') return 'ALMACEN';
    return 'OTRO';
  }

  // ── [734 · zona] Personal del día agrupado POR ZONA (pedido del dueño) ─────
  // Los cajeros/vendedores de POS salían mezclados: no se veía a qué grupo
  // pertenece cada quien ni con qué reglas se le paga. Ahora cada zona abre su
  // propio bucket con encabezado: nombre bonito + cuántos son + meta/comisión
  // VIGENTES de esa zona + la venta de zona del día.
  // Fuentes (ninguna consulta nueva):
  //   · nombre bonito + meta + comisión → cfgData.zonas (getZonas → mos.zonas_lista,
  //     campo politicaJSON = mos.zonas.politica_json, la MISMA fuente que paga el bono
  //     tras el SQL 729: sin política ⇒ meta NULL y comisión 0, y aquí se ve el aviso).
  //   · venta de la zona del día → ev.kpis.ventaZona, que ya viene en personal_dia_lista.
  // Esto es SOLO agrupación y presentación: no toca un solo cálculo de pago.
  let _finZonasPidiendo = false;
  function _finZonaKey(s) { return String(s == null ? '' : s).trim().toUpperCase(); }
  function _finMiles(n) {
    const v = parseFloat(n);
    if (!isFinite(v)) return '—';
    try { return Math.round(v).toLocaleString('es-PE'); } catch(_) { return String(Math.round(v)); }
  }
  // politicaJSON llega como TEXTO (zonas_lista devuelve politica_json::text) y,
  // por el defecto histórico del 728, pudo quedar doble-codificado. Se desenvuelve
  // hasta 3 veces; si no resulta un objeto, se trata como "sin política".
  function _finZonaPolitica(raw) {
    let v = raw;
    for (let i = 0; i < 3 && typeof v === 'string'; i++) {
      const t = v.trim();
      if (!t) return null;
      try { v = JSON.parse(t); } catch(_) { return null; }
    }
    return (v && typeof v === 'object' && !Array.isArray(v)) ? v : null;
  }
  function _finZonaInfo(idZona) {
    const k = _finZonaKey(idZona);
    const z = (cfgData.zonas || []).find(x => _finZonaKey(x.idZona) === k || _finZonaKey(x.nombre) === k) || null;
    const pol  = z ? _finZonaPolitica(z.politicaJSON) : null;
    const meta = pol ? parseFloat(pol.metaDiaria) : NaN;
    const pct  = pol ? parseFloat(pol.comisionExcedentePct) : NaN;
    return {
      conocida: !!z,
      nombre:   (z && z.nombre) ? String(z.nombre) : String(idZona || ''),
      meta:     (isFinite(meta) && meta > 0) ? meta : null,
      pct:      (isFinite(pct)  && pct  >= 0) ? pct  : null
    };
  }
  // Encabezado compacto de un bucket de zona (una sola fila que envuelve en 390px).
  function _finZonaHdr(info, nPersonas, ventaZona) {
    const sinZona = !!info.sinZona;
    let reglas;
    if (sinZona) {
      reglas = '<span class="fin-zgrp-warn">sin zona en la sesión del día</span>';
    } else if (!info.conocida) {
      reglas = '<span class="fin-zgrp-warn">zona no encontrada en Infraestructura</span>';
    } else if (info.meta === null && info.pct === null) {
      reglas = '<span class="fin-zgrp-warn" title="mos.zonas.politica_json vacía: el bono de esta zona sale 0 (SQL 729). Configúrala en Config → Infraestructura.">⚠ sin política configurada</span>';
    } else {
      const m = info.meta === null
        ? '<b class="fin-zgrp-falta">sin meta</b>'
        : '<b>S/ ' + _finMiles(info.meta) + '</b>';
      const c = info.pct === null
        ? '<b class="fin-zgrp-falta">sin %</b>'
        : '<b>' + info.pct + '%</b>';
      reglas = '<span class="fin-zgrp-regla" title="Meta diaria y comisión sobre el excedente vigentes para esta zona (Config → Infraestructura).">🎯 ' + m + ' <i>meta</i> · 💸 ' + c + ' <i>comisión</i></span>';
    }
    let venta = '';
    if (!sinZona) {
      const v = parseFloat(ventaZona);
      const vOk = isFinite(v) ? v : 0;
      const avance = (info.meta && info.meta > 0) ? Math.round(vOk / info.meta * 100) : null;
      venta = '<span class="fin-zgrp-venta' + (avance !== null && avance >= 100 ? ' ok' : '') + '"'
            + ' title="Venta de la zona en el día (kpis.ventaZona de la mega tabla)">'
            + 'S/ ' + _finMiles(vOk)
            + (avance !== null ? ' <i>' + avance + '%</i>' : '')
            + '</span>';
    }
    return '<div class="fin-zgrp"' + (sinZona ? ' data-sinzona="1"' : '') + '>'
         + '<span class="fin-zgrp-ico">' + (sinZona ? '❔' : '📍') + '</span>'
         + '<span class="fin-zgrp-nom">' + _escapeHtml(info.nombre) + '</span>'
         + '<span class="fin-zgrp-n" title="personas en esta zona">' + nPersonas + '</span>'
         + reglas + venta
         + '</div>';
  }

  // [847] Releer el personal del día desde el servidor, saltándose el caché local.
  // Hace falta cada vez que el SERVIDOR recalcula por su cuenta: cambiar la base, la meta o la
  // comisión de una zona dispara el recompute de las liquidaciones PENDIENTES (SQL 731/846), y sin
  // esto la card seguía mostrando el pago viejo aunque en la base ya estuviera el nuevo — justo la
  // incoherencia que vio el dueño: "puse 60 al cajero de Zona 1, la card dice 50 y Auditar dice 60".
  async function _finRefrescarPersonalDia(fecha) {
    const cont = document.getElementById('finPersonalList');
    const f = fecha || (cont && cont.dataset.fecha) ||
              new Date(Date.now() - 5 * 3600 * 1000).toISOString().slice(0, 10);
    try { localStorage.removeItem('mos_fin_resum_' + f); } catch {}
    try { localStorage.removeItem('mos_evals_' + f); } catch {}
    let arr = [];
    try {
      const fresh = await API.get('getPersonalDiaFast', { fecha: f, _refresh: 'true' });
      arr = Array.isArray(fresh) ? fresh : ((fresh && fresh.data) || []);
    } catch (_) { return; }
    if (!arr.length) return;
    try { localStorage.setItem('mos_fin_resum_' + f, JSON.stringify({ ts: Date.now(), data: arr })); } catch {}
    try { _evalState.resumenes = arr; } catch (_) {}
    if (cont && _finPL) { cont.dataset._lastHtml = ''; _finRenderPersonal(_finPL, f); }
  }

  function _finRenderPersonal(pl, fecha) {
    const cont = $('finPersonalList');
    const tot  = $('finPersonalTotal');
    if (!cont) return;
    // Guard de fecha: si pl es para otro día que el currently displayed,
    // descartamos. Pasaba que el render con datos cached del día previo
    // se aplicaba arriba del fresh, dejando cards stale por una visita.
    if (pl && pl._fechaStamp && pl._fechaStamp !== fecha) return;
    // Stamp del contenedor: cualquier pint posterior verifica que aún
    // estemos en la misma fecha antes de tocar el DOM.
    cont.dataset.fecha = fecha;
    if (typeof _evalState !== 'undefined' && _evalState && fecha) {
      _evalState.fecha = fecha;
    }
    if (tot) _animateCount(tot, pl.gastoPersonal || 0, { prefix: 'S/ ' });
    if (!pl.personalDetalle || !pl.personalDetalle.length) {
      cont.innerHTML = '<p class="text-slate-500 text-xs">Sin registros — usa "+ Jornada" o "⬇ Cajas"</p>';
      return;
    }

    // Agrupar por área (POS / ALMACEN / OTRO) — no confunde los KPIs
    const grupos = { POS: [], ALMACEN: [], OTRO: [] };
    pl.personalDetalle.forEach(p => {
      grupos[_finClasificarRol(p.rol)].push(p);
    });

    // [734 · zona] El nombre bonito y la política salen de cfgData.zonas, que
    // normalmente ya viene del prefetch de Config. Si por lo que sea aún no está,
    // se pide UNA vez por la misma vía que usa el panel (getZonas) y se repinta:
    // así el encabezado no miente diciendo "sin política" cuando solo faltaba el cache.
    if (!Array.isArray(cfgData.zonas) || !cfgData.zonas.length) {
      if (!_finZonasPidiendo) {
        _finZonasPidiendo = true;
        API.get('getZonas', {}).then(r => {
          _finZonasPidiendo = false;
          if (Array.isArray(r) && r.length) {
            cfgData.zonas = r;
            try { if (cont.dataset.fecha === fecha) _pintarConResumenes(_evalState.resumenes || cachedResumenes || []); } catch(_) {}
          }
        }).catch(() => { _finZonasPidiendo = false; });
      }
    }

    const cacheKey = 'mos_fin_resum_' + fecha;
    let cachedResumenes = null;
    try {
      const raw = localStorage.getItem(cacheKey);
      if (raw) {
        const pCache = JSON.parse(raw);
        if (Date.now() - (pCache.ts || 0) < 30 * 60 * 1000) cachedResumenes = pCache.data;
      }
    } catch {}

    function _renderGrupo(arr, titulo, icono, area, byNombre, byIdPersonal) {
      if (!arr.length) return '';
      // Subtotal REAL = totalDia del resumen si existe (incluye envasado +
      // bono meta − sanción). Fallback a p.monto (jornal base) cuando no
      // hay resumen todavía. Así el header del grupo cuadra con las cards.
      // VETADOS quedan FUERA (no reciben pago).
      const subtotal = arr.reduce((s, p) => {
        if (p.vetada) return s;
        const ev = byIdPersonal[p.idPersonal] || byNombre[String(p.nombre || '').toLowerCase().trim()] || null;
        // [738] El GASTO del área es el BRUTO: lo que la empresa debe por el trabajo
        // (sueldo + comisión + envasado). El consumo a crédito es una VENTA ya cobrada
        // por planilla: baja el EFECTIVO que sale de caja, no el costo laboral → dos números.
        const _cons = (ev && ev.creditosDia && parseFloat(ev.creditosDia.total)) || 0;
        const real = ((ev && typeof ev.totalDia === 'number') ? ev.totalDia : (parseFloat(p.monto) || 0));
        s.bruto += real; s.cons += _cons; return s;
      }, { bruto: 0, cons: 0 });
      // [739] El chip de conteo no puede contradecir al dinero: los vetados salen
      // del subtotal pero seguian contando en el numero, y quedaba "8" al lado de
      // un total que era de 5 personas. Se dice cuantos son y cuantos no cobran.
      const _vet = arr.reduce((n, p) => n + (p.vetada ? 1 : 0), 0);
      return `
        <div class="fin-pers-group" data-area="${area}">
          <div class="fin-pers-group-hdr">
            <span class="fin-pers-group-ico">${icono}</span>
            <span class="fin-pers-group-tit">${titulo}</span>
            <span class="fin-pers-group-count"${_vet > 0 ? ' style="background:rgba(239,68,68,.14);color:#fca5a5" title="' + _vet + ' vetada(s) no cobran: quedan ' + (arr.length - _vet) + ' de ' + arr.length + ' en el gasto"' : ''}>${_vet > 0 ? (arr.length - _vet) + '/' + arr.length : arr.length}</span>
            <span class="fin-pers-group-sub" title="Gasto de personal del área: lo que la empresa debe por el trabajo de hoy">S/ ${subtotal.bruto.toFixed(2)}</span>
            ${subtotal.cons > 0 ? '<span class="fin-pers-group-caja" title="Lo que realmente sale de caja: el consumo a crédito se cobra descontándolo del sueldo">· caja S/ ' + (subtotal.bruto - subtotal.cons).toFixed(2) + '</span>' : ''}
          </div>
          <div class="fin-pers-group-list">
            ${_finRenderZonaBuckets(arr, area, byNombre, byIdPersonal, fecha)}
          </div>
        </div>`;
    }

    // [734 · zona] Reparte a las personas del área en buckets por zona.
    // Orden: zonas por nombre; dentro de cada zona, personas por nombre;
    // "Sin zona asignada" SIEMPRE al final y visible (nunca escondido).
    // Si en el área nadie tiene zona (Almacén / Otros) se pinta plano: el
    // encabezado no debe robarle espacio a las filas cuando no aporta nada.
    function _finRenderZonaBuckets(arr, area, byNombre, byIdPersonal, fecha) {
      const evDe = (p) => byIdPersonal[p.idPersonal] || byNombre[String(p.nombre || '').toLowerCase().trim()] || null;
      // La zona real del día vive en la mega tabla (liquidaciones_dia.zona →
      // zonaSesion / kpis.zonaPrincipal). p.zona de finanzas_dia llega SIEMPRE vacío,
      // por eso el separador viejo no se activaba nunca y todo salía mezclado.
      const zonaDe = (p) => {
        const ev = evDe(p);
        const z = (ev && (ev.zonaSesion || (ev.kpis && ev.kpis.zonaPrincipal))) || p.zona || (ev && ev.zona) || '';
        return String(z).trim();
      };
      const porNombre = (a, b) => String(a.nombre || '').localeCompare(String(b.nombre || ''), 'es', { sensitivity: 'base' });
      const pintar = (p) => _finRenderPersonalCard(p, evDe(p), fecha, area);
      // Solo POS (cajeros/vendedores) se agrupa por zona: es donde la zona manda el pago.
      // En Almacén / Otros la zona no paga nada — pintar su encabezado sería ruido (y peor:
      // insinuaría que a un almacenero le aplica la meta/comisión de una zona de venta).
      if (area !== 'POS' || !arr.some(p => zonaDe(p))) return arr.slice().sort(porNombre).map(pintar).join('');

      const buckets = new Map();
      arr.forEach(p => {
        const z = zonaDe(p);
        const k = z ? _finZonaKey(z) : '__SINZONA__';
        if (!buckets.has(k)) buckets.set(k, { id: z, personas: [], venta: 0 });
        const b = buckets.get(k);
        b.personas.push(p);
        // La venta es de la ZONA (misma para todas sus filas); si alguna fila viene
        // sin recomputar todavía trae 0 → gana la mayor, que es la del recompute vivo.
        const ev = evDe(p);
        const v = (ev && ev.kpis) ? parseFloat(ev.kpis.ventaZona) : NaN;
        if (isFinite(v) && v > b.venta) b.venta = v;
      });

      const lista = Array.from(buckets.entries()).map(([k, b]) => ({
        b,
        info: (k === '__SINZONA__')
          ? { conocida: true, sinZona: true, nombre: 'Sin zona asignada', meta: null, pct: null }
          : _finZonaInfo(b.id)
      }));
      lista.sort((x, y) => {
        if (x.info.sinZona !== y.info.sinZona) return x.info.sinZona ? 1 : -1;
        return String(x.info.nombre).localeCompare(String(y.info.nombre), 'es', { sensitivity: 'base' });
      });
      return lista.map(({ b, info }) =>
        _finZonaHdr(info, b.personas.length, b.venta)
        + b.personas.slice().sort(porNombre).map(pintar).join('')
      ).join('');
    }

    function _pintarConResumenes(resumenes) {
      // Si la fecha cambió mientras este paint estaba pendiente, abortar.
      if (cont.dataset.fecha !== fecha) return;
      const byNombre = {};
      const byIdPersonal = {};
      const arr = Array.isArray(resumenes) ? resumenes : [];
      // [732] Dos personas distintas con el mismo nombre (hay dos "Jesus") hacían que una tarjeta
      // mostrara el pago de la OTRA: el último con ese nombre pisaba al resto en byNombre. Ahora un
      // nombre solo sirve de atajo si lo usa una sola persona; si no, no se cruza (mejor sin dato
      // que con el dato de otro). El cruce por idPersonal sigue siendo el camino principal.
      const _nomIds = {}, _nomUnico = {};
      arr.forEach(r => { const n = String(r.nombre || '').toLowerCase().trim(); if (!n) return;
        (_nomIds[n] = _nomIds[n] || {})[String(r.idPersonal || '')] = 1; });
      Object.keys(_nomIds).forEach(n => { _nomUnico[n] = Object.keys(_nomIds[n]).length === 1; });
      arr.forEach(r => {
        const n = String(r.nombre || '').toLowerCase().trim();
        if (n && _nomUnico[n]) byNombre[n] = r;   // [732] solo si el nombre es INEQUÍVOCO
        if (r.idPersonal) byIdPersonal[r.idPersonal] = r;
      });

      _evalState.resumenes = arr;
      _evalState.fecha = fecha;
      _evalState.byNombre = byNombre;
      _evalState.byIdPersonal = byIdPersonal;

      // [v2.41.46] Propagar VETADA desde LIQUIDACIONES_DIA → personalDetalle.
      // ÚNICA fuente de verdad: ev.liqEstado. Si no es 'VETADA', el card
      // NO debe estar enmallado, sin importar marcas históricas en
      // p.fuente='ELIMINADA' (legacy de cuando vetar llamaba eliminarJornada).
      pl.personalDetalle.forEach(p => {
        const ev = byIdPersonal[p.idPersonal] || byNombre[String(p.nombre || '').toLowerCase().trim()] || null;
        if (ev && ev.liqEstado) {
          // Backend tiene liqEstado → es autoritativo
          p.vetada = (ev.liqEstado === 'VETADA');
          if (!p.vetada && p.fuente === 'ELIMINADA') {
            // Limpiar marca histórica para que el render no la mire
            p.fuente = 'AUTO_RECOV';
          }
        }
      });

      // ── Total general REAL + propagación a KPIs del P&L ──
      // Antes pl.gastoPersonal venía del backend basado solo en JORNADAS.
      // Aquí re-calculamos totalReal con totalDia de los resúmenes (incluye
      // envasado + bono meta − sanción, excluye vetados) y ESCALAMOS hacia
      // arriba: Gasto Personal, Gastos totales, Costos Fijos, Utilidad
      // Neta, Margen Neto y Punto de Equilibrio TODOS se reconectan al
      // valor en vivo. Sin esto el break-even quedaba "frío".
      if (arr.length > 0) {
        let totalReal = 0, totalConsumo = 0;
        ['POS','ALMACEN','OTRO'].forEach(area => {
          (grupos[area] || []).forEach(p => {
            if (p.vetada) return; // vetados no cuentan
            const ev = byIdPersonal[p.idPersonal] || byNombre[String(p.nombre || '').toLowerCase().trim()] || null;
            // [738] BRUTO: el gasto de personal del P&L es lo que la empresa DEBE pagar
            // por el trabajo. El consumo a crédito NO lo abarata: es una venta cobrada por
            // planilla. Restarlo aquí hacía que el Punto de Equilibrio saliera más bajo del real.
            const _cons = (ev && ev.creditosDia && parseFloat(ev.creditosDia.total)) || 0;
            const real = ((ev && typeof ev.totalDia === 'number') ? ev.totalDia : (parseFloat(p.monto) || 0));
            totalReal += real;
            totalConsumo += _cons;
          });
        });
        if (tot) _animateCount(tot, totalReal, { prefix: 'S/ ' });
        // [738] El consumo viaja en el objeto para que el subtítulo diga cuánto sale de caja.
        try { if (typeof _finPL !== 'undefined' && _finPL) _finPL._consumoPersonalDia = Math.round(totalConsumo * 100) / 100; } catch(_){}

        // Propagar al objeto pl + re-render de los KPIs dependientes
        try {
          if (typeof _finPL !== 'undefined' && _finPL && pl === _finPL) {
            const r2 = n => Math.round(n * 100) / 100;
            const gastosFijos = parseFloat(_finPL.gastosFijos) || 0;
            const gastosVariables = parseFloat(_finPL.totalGastos) - (parseFloat(_finPL.gastoPersonal) || 0) - (parseFloat(_finPL.gastosFijos) || 0);
            const otrosGastos = parseFloat(_finPL.totalGastos || 0) - (parseFloat(_finPL.gastoPersonal) || 0);
            // ── Actualizar campos derivados ──
            _finPL.gastoPersonal = r2(totalReal);
            _finPL.totalGastos   = r2(totalReal + otrosGastos);
            _finPL.costosFijos   = r2(totalReal + gastosFijos);
            const ventasNetas = parseFloat(_finPL.ventasNetas) || 0;
            const utilidadBruta = parseFloat(_finPL.utilidadBruta);
            _finPL.utilidadNeta  = r2((isFinite(utilidadBruta) ? utilidadBruta : 0) - _finPL.totalGastos);
            _finPL.margenNetoPct = ventasNetas > 0 ? r2(_finPL.utilidadNeta / ventasNetas * 100) : 0;
            const costoVentas = parseFloat(_finPL.costoVentas) || 0;
            const margenContrib = ventasNetas > 0 ? (ventasNetas - costoVentas) / ventasNetas : 0;
            _finPL.breakEvenVentas = margenContrib > 0 ? r2(_finPL.costosFijos / margenContrib) : null;
            _finPL.breakEvenPct = (_finPL.breakEvenVentas && ventasNetas > 0)
              ? r2(Math.min(_finPL.breakEvenVentas / ventasNetas * 100, 100)) : 0;
            _finPL.superaBreakEven = _finPL.breakEvenVentas !== null && ventasNetas >= _finPL.breakEvenVentas;

            // Re-render solo KPIs (skipPersonal preserva los cards que ya pintamos)
            try { _finRender(_finPL, fecha, { skipPersonal: true }); } catch(_){}
          }
        } catch(_){}
      }

      let html = '';
      html += _renderGrupo(grupos.POS,     'POS · Cajeros',        '🛒', 'POS',     byNombre, byIdPersonal);
      html += _renderGrupo(grupos.ALMACEN, 'Almacén',              '🏭', 'ALMACEN', byNombre, byIdPersonal);
      html += _renderGrupo(grupos.OTRO,    'Otros',                '👤', 'OTRO',    byNombre, byIdPersonal);
      const finalHtml = html || '<p class="text-slate-500 text-xs">Sin registros</p>';
      // Anti-flicker: si el HTML es idéntico al ya pintado, no re-escribir
      // el DOM (evita el "parpadeo" en navegación de fechas y al re-paint
      // cuando cache==fresh).
      if (cont.dataset._lastHtml === finalHtml) return;
      cont.dataset._lastHtml = finalHtml;
      cont.innerHTML = finalHtml;
    }

    _pintarConResumenes(cachedResumenes);

    // [v2.41.62] FAST: lectura plana de LIQUIDACIONES_DIA (10-20× más rápido
    // que getResumenTodosDia que recompute todo). La UI muestra los valores
    // YA persistidos (totalDia, bonificacion, sancion, estado, etc.) sin
    // depender del recompute pesado. El recompute completo (con kpis live)
    // solo se hace al abrir auditoría individual.
    // [v2.41.78] Hash rápido en vez de JSON.stringify de los resúmenes.
    API.get('getPersonalDiaFast', { fecha: fecha }).then(resumenes => {
      if (cont.dataset.fecha !== fecha) return; // ya no estamos en esta fecha
      const arr = Array.isArray(resumenes) ? resumenes : ((resumenes && resumenes.data) || []);
      try { localStorage.setItem(cacheKey, JSON.stringify({ ts: Date.now(), data: arr })); } catch {}
      // [ext] cargar duplicados (mismo nombre en >1 zona hoy) para el chip 🔗; re-pinta una vez si hay.
      try {
        API.accesosDuplicados && API.accesosDuplicados({ fecha }).then(d => {
          const nd = (d && typeof d === 'object' && !Array.isArray(d)) ? d : {};
          const changed = JSON.stringify(nd) !== JSON.stringify(_finDuplicados);
          _finDuplicados = nd;
          if (changed && Object.keys(nd).length && cont.dataset.fecha === fecha) {
            try { _pintarConResumenes(_evalState.resumenes || arr); } catch(_){}
          }
        }).catch(() => {});
      } catch(_){}
      const _hashRes = (xs) => {
        if (!Array.isArray(xs)) return '';
        return xs.map(r => [r.idPersonal || r.nombre, r.totalDia, r.bonificacion, r.sancion, r.liqEstado, r.evaluacionesCount].join(',')).join('|');
      };
      if (_hashRes(cachedResumenes) !== _hashRes(arr)) {
        _pintarConResumenes(arr);
      } else {
        _evalState.resumenes = arr;
        _evalState.fecha = fecha;
      }
    }).catch(() => { /* si falla, queda lo del cache o sin score */ });
  }

  // Busca la Ultima_Conexion para una persona del Día (vendedor ME virtual o operador real).
  // Estrategia: probar todas las fuentes y devolver la fecha MÁS RECIENTE encontrada.
  // Un usuario puede tener varios dispositivos (laptop + móvil + tablet) — la idea
  // es ver su "live" general sin importar en qué dispositivo esté activo.
  //
  // Fuentes consultadas (todas se evalúan, gana la más reciente):
  //   A. PERSONAL_MASTER (personalMOS + personal) por idPersonal o nombre
  //   B. DISPOSITIVOS por Ultima_Sesion === nombre (cualquier match)
  //   C. DISPOSITIVOS por Ultima_Sesion contains primer nombre (Javier matchea "Javier Vasquez")
  function _finBuscarActividadPersonal(p, ev) {
    const idP = (ev && ev.idPersonal) || p.idPersonal || '';
    const nomBruto = String(p.nombre || (ev && ev.nombre) || '').trim();
    if (!nomBruto && !idP) return null;

    // Normalizador: lowercase + collapse múltiples espacios + trim
    const norm = s => String(s || '').toLowerCase().replace(/\s+/g, ' ').trim();
    const nomNorm = norm(nomBruto);
    const primerNombre = nomNorm.split(' ')[0]; // "javier" de "javier vasquez"

    const personasMaster = [
      ...(cfgData.personalMOS || []),
      ...(cfgData.personal || [])
    ];

    // Acumulador del timestamp más reciente encontrado (en cualquier fuente)
    let mejorIso = null;
    let mejorMs  = -Infinity;
    const _consider = (iso) => {
      if (!iso) return;
      const t = _parseTsUtc(iso);
      if (!isNaN(t) && t > mejorMs) { mejorMs = t; mejorIso = iso; }
    };

    // 0. [FIX seguimiento] La MEGATABLA (liquidaciones_dia via personal_dia_lista) trae la ultima_conexion
    //    REAL del día (heartbeat del device). Es la fuente autoritativa y fresca — antes se ignoraba y el
    //    "hace Xh" salía de matchear nombres contra PERSONAL_MASTER/DISPOSITIVOS (stale). Gana el más reciente.
    _consider(p.ultimaConexion || p.ultima_conexion || (ev && (ev.ultimaConexion || ev.ultima_conexion)) || null);

    // A. PERSONAL_MASTER por idPersonal
    if (idP) {
      const m = personasMaster.find(x => String(x.idPersonal) === String(idP));
      if (m) _consider(m.Ultima_Conexion || m.ultimaConexion || null);
    }

    // A2. PERSONAL_MASTER por nombre (combinado o solo) con tolerancia
    if (nomNorm) {
      const matches = personasMaster.filter(x => {
        const nomCompleto = norm((x.nombre || '') + ' ' + (x.apellido || ''));
        const soloNombre  = norm(x.nombre || '');
        if (!nomCompleto && !soloNombre) return false;
        return nomCompleto === nomNorm
            || soloNombre  === nomNorm
            || nomCompleto.startsWith(nomNorm + ' ')
            || nomNorm.startsWith(soloNombre + ' ')
            || nomCompleto === primerNombre
            || soloNombre  === primerNombre;
      });
      matches.forEach(m => _consider(m.Ultima_Conexion || m.ultimaConexion || null));
    }

    // B. DISPOSITIVOS por Ultima_Sesion — cualquier dispositivo cuyo último login
    //    matchee con el nombre buscado. Tomamos cualquiera que matchee, gana el más reciente.
    if (nomNorm && Array.isArray(cfgData.dispositivos)) {
      for (const d of cfgData.dispositivos) {
        const sesNorm = norm(d.Ultima_Sesion || '');
        if (!sesNorm) continue;
        const matchea =
          sesNorm === nomNorm ||                         // match exacto
          sesNorm.startsWith(nomNorm + ' ') ||           // "javier vasquez" empieza con "javier "
          nomNorm.startsWith(sesNorm + ' ') ||           // "javier vasquez" buscado, sesion "javier"
          (primerNombre && sesNorm === primerNombre) ||  // sesion === primer nombre buscado
          (primerNombre && sesNorm.startsWith(primerNombre + ' ')); // sesion empieza con primer nombre
        if (!matchea) continue;
        _consider(d.Ultima_Conexion);
      }
    }

    return mejorIso;
  }

  // [ext] duplicados del día (mismo nombre normalizado en >1 fila/zona) → data del chip 🔗
  let _finDuplicados = {};
  function _finRenderPersonalCard(p, ev, fecha, area) {
    // [v2.41.46] Única fuente de verdad: LIQUIDACIONES_DIA.estado (propagado
    // a p.vetada en _pintarConResumenes). Si por fallback no hay liqEstado
    // todavía, usar p.vetada del backend. NO mirar p.fuente='ELIMINADA'
    // (marca histórica del flujo viejo eliminarJornada).
    const esVetada = !!p.vetada;
    // ¿Tiene dispositivos encarcelados? Lookup por nombre (lowercased + trim).
    const nLowCard = String(p.nombre || '').toLowerCase().trim();
    const bloqInfo = (_finBloqueados && _finBloqueados.porNombre)
      ? _finBloqueados.porNombre[nLowCard] : null;
    const esBloqueado = !!(bloqInfo && bloqInfo.dispositivos && bloqInfo.dispositivos.length);
    // [ext] chip 🔗: el mismo nombre aparece en >1 fila/zona hoy → el admin decide
    // (fantasma / mismo movido → sanción-base / dos personas → pagar ambas).
    // [100x] clave SIN tildes para casar con mos._norm_nom del backend (lower+trim+unaccent);
    // si no, "Andrés" (JS) ≠ "andres" (SQL) → el chip no aparecía.
    const _dupKey  = nLowCard.normalize('NFD').replace(/[̀-ͯ]/g, '');
    const _dupInfo = _finDuplicados && (_finDuplicados[_dupKey] || _finDuplicados[nLowCard]);
    const dupChip = (_dupInfo && _dupInfo.length > 1)
      ? `<span class="badge-rol" style="background:rgba(245,158,11,.14);color:#fbbf24;border:1px solid rgba(245,158,11,.4);animation:finPillPulse 2s ease-in-out infinite" title="⚠ &quot;${_escapeHtml(p.nombre)}&quot; está en ${_dupInfo.length} filas hoy (${_dupInfo.map(d => _escapeHtml(d.zona || '—') + ' S/' + (parseFloat(d.venta) || 0).toFixed(0)).join(' · ')}). Decide: ¿fantasma? ¿mismo movido (sanción-base)? ¿dos personas (pagar ambas)?">🔗 ${_dupInfo.length} zonas ⚠</span>`
      : '';
    const esPOS = (area || _finClasificarRol(p.rol)) === 'POS';
    const score = ev ? (ev.scoreFinal || 0) : null;
    const scoreClass = score !== null ? _evalScoreClass(score) : '';
    const rolClass = _evalRolBadgeClass(p.rol || (ev && ev.rol));
    const evalCount = ev ? (ev.evaluacionesCount || 0) : 0;
    const kpiTxt = ev ? _evalKpiSummary(ev, p.rol) : '';
    // Vetado: NO recibe pago, NO se audita, NO entra a la liquidación
    const totalDia = esVetada ? 0 : ((ev && ev.totalDia) ? ev.totalDia : (parseFloat(p.monto) || 0));
    const idForEval = esVetada ? '' : ((ev && ev.idPersonal) || p.idPersonal || '');
    // [v2.43.376 · una sola fuente] id_personal de la MEGA TABLA (mos.liquidaciones_dia, vía
    // getPersonalDiaFast) para vetar/desvetar — el MISMO que usa la pestaña Liquidación.
    const idMega = (ev && ev.idPersonal) || p.idPersonal || '';
    const fuenteTag = p.fuente === 'AUTO_VENTA' ? '<span class="fin-tag fin-tag-green ml-1" title="Detectado por venta">auto</span>'
                    : p.fuente === 'AUTO_LOGIN' ? '<span class="fin-tag fin-tag-green ml-1" title="Detectado por sesión">auto</span>'
                    : p.fuente === 'AUTO_CAJAS' ? '<span class="fin-tag fin-tag-green ml-1" title="Importado de cajas">auto</span>'
                    : '';
    // Indicador online: dot pulsante sobre el avatar si Ultima_Conexion < 5min
    const ultCx = _finBuscarActividadPersonal(p, ev);
    const act = _personaActividad(ultCx);
    const isFresh = act.minutos < 5;
    const dotPulse = isFresh ? '<span class="fin-pers-dot-pulse" title="🔴 LIVE — '+act.label+'"></span>' : '';
    const ringCls = isFresh ? ' fin-pers-avatar-live' : '';
    const innerScore = score !== null
      ? `<div class="eval-score-circle ${scoreClass}" style="--score:${score};"><span>${score}%</span></div>`
      : `<div class="w-9 h-9 rounded-full flex items-center justify-center text-xs font-bold" style="background:rgba(100,116,139,.15);color:#94a3b8">—</div>`;
    const scoreCircle = `<div class="fin-pers-avatar-wrap${ringCls}" style="position:relative;flex-shrink:0;"
      title="${isFresh ? '🟢 ' + act.label : (ultCx ? '⚫ ' + act.label : '')}"
      >${innerScore}${dotPulse}</div>`;
    // [v2.41.50] PAGADA = liquidación ya cerrada → sello verde no editable
    const esPagada = !esVetada && (ev && ev.liqEstado === 'PAGADA') || (p.liqEstado === 'PAGADA');
    const vetadaCls = esVetada ? ' fin-vetada-card' : '';
    const pagadaCls = esPagada ? ' fin-pagada-card' : '';
    const bloqCls   = esBloqueado ? ' fin-bloq-card' : '';
    const vetadaOverlay = esVetada
      ? `<div class="fin-vetada-overlay">
           <div class="fin-vetada-stripe"></div>
           <div class="fin-vetada-badge">💸 VETADA · S/ 0.00</div>
         </div>`
      : '';
    const pagadaOverlay = esPagada
      ? `<div class="fin-pagada-overlay">
           <div class="fin-pagada-stripe"></div>
           <div class="fin-pagada-sello">✓ PAGADA · S/ ${parseFloat((ev && ev.totalDia) || p.monto || 0).toFixed(2)}</div>
         </div>`
      : '';
    // Overlay de rejas persistente: si el usuario tiene devices encarcelados.
    // Se renderiza dentro del template (no como inyección DOM temporal) para
    // sobrevivir cualquier re-render del card. Combinable con veto.
    const bloqOverlay = esBloqueado
      ? `<div class="fin-rejas-overlay fin-rejas-persist">
           <div class="fin-rejas-bars">
             <div class="fin-rejas-bar"></div>
             <div class="fin-rejas-bar"></div>
             <div class="fin-rejas-bar"></div>
             <div class="fin-rejas-bar"></div>
             <div class="fin-rejas-bar"></div>
             <div class="fin-rejas-bar"></div>
           </div>
           <div class="fin-rejas-badge">🔒 BLOQUEADO · ${bloqInfo.dispositivos.length} disp.</div>
           <div class="fin-rejas-sub">${_escapeHtml(p.nombre)}</div>
         </div>`
      : '';
    return `
      <div class="eval-card${vetadaCls}${pagadaCls}${bloqCls}" data-id="${idForEval}" style="position:relative;">
        ${vetadaOverlay}
        ${pagadaOverlay}
        ${bloqOverlay}
        <div class="flex items-center gap-3">
          ${scoreCircle}
          <div class="flex-1 min-w-0">
            <div class="flex items-center gap-2 mb-1 flex-wrap">
              <div class="font-semibold text-slate-100 text-sm truncate">${_escapeHtml(p.nombre)}</div>
              <span class="badge-rol ${rolClass}">${_escapeHtml(p.rol || (ev && ev.rol) || '—')}</span>
              ${ev && ev.virtual ? '<span class="badge-rol badge-rol-default" title="Detectado del sistema">⚡ del sistema</span>' : ''}
              ${fuenteTag}
              ${dupChip}
            </div>
            ${kpiTxt ? `<div class="text-xs text-slate-500 mb-1">${kpiTxt}</div>` : ''}
            <div class="flex items-center gap-2 flex-wrap">
              ${evalCount > 0
                ? `<span class="audit-count-pill">${evalCount} auditoría${evalCount !== 1 ? 's' : ''}</span>`
                : `<span class="audit-count-pill" style="background:rgba(245,158,11,.12);color:#fbbf24;border-color:rgba(245,158,11,.3)">⚠ Sin auditar</span>`}
              ${(() => {
                // [v2.41.77] Pill de última actividad visible siempre.
                // Verde <5min (LIVE), verde claro <60min, amarillo <24h, naranja <7d, rojo +7d.
                if (!ultCx) return '<span class="audit-count-pill" style="background:rgba(100,116,139,.12);color:#94a3b8;border-color:rgba(100,116,139,.3)" title="Sin actividad registrada">⚫ sin actividad</span>';
                const bg = `rgba(${act.color === '#10b981' ? '16,185,129' : act.color === '#fbbf24' ? '251,191,36' : act.color === '#f97316' ? '249,115,22' : '239,68,68'},.14)`;
                const bd = `rgba(${act.color === '#10b981' ? '16,185,129' : act.color === '#fbbf24' ? '251,191,36' : act.color === '#f97316' ? '249,115,22' : '239,68,68'},.4)`;
                const pulse = isFresh ? ' style="animation:finPillPulse 1.4s ease-in-out infinite"' : '';
                return `<span class="audit-count-pill"${pulse} style="background:${bg};color:${act.color};border-color:${bd}" title="Última actividad detectada">${act.dot} ${_escapeHtml(act.label)}</span>`;
              })()}
              <span class="text-xs text-slate-400">Pago día: <strong class="text-amber-400">S/ ${parseFloat(totalDia).toFixed(2)}</strong></span>
            </div>
            ${(() => {
              // [FIX seguimiento] Línea de asistencia REAL desde la megatabla (liquidaciones_dia via personal_dia_lista):
              // hora de ingreso · tiempo activo · app · reconexiones · si se cerró forzado a las 11pm.
              const ing   = p.horaIngreso   || (ev && ev.horaIngreso)   || '';
              const app   = (ev && ev.appOrigen) || p.appOrigen || '';
              const min   = parseInt(p.minutosActivos || (ev && ev.minutosActivos) || 0, 10);
              const recon = parseInt(p.reconexiones   || (ev && ev.reconexiones)   || 0, 10);
              const ses   = p.estadoSesion  || (ev && ev.estadoSesion)  || '';
              if (!ing && !min && !app) return '';
              const fmtH = t => { try { return new Date(_parseTsUtc(t)).toLocaleTimeString('es-PE', { timeZone: 'America/Lima', hour: '2-digit', minute: '2-digit' }); } catch(_) { return ''; } };
              const partes = [];
              if (ing)      partes.push('🕐 ' + fmtH(ing));
              if (min > 0)  partes.push('⏱ ' + (min >= 60 ? Math.floor(min / 60) + 'h ' + (min % 60) + 'm' : min + 'm'));
              if (app)      partes.push('📱 ' + (app === 'mosExpress' ? 'ME' : app === 'warehouseMos' ? 'WH' : app));
              if (recon > 0) partes.push('🔄 ' + recon + ' reconex');
              if (String(ses).indexOf('FORZADA') === 0) partes.push('🌙 cerrada 11pm');
              return partes.length ? `<div class="text-[11px] text-slate-500 mt-0.5" title="Ingreso · tiempo activo · app · reconexiones">${partes.join(' · ')}</div>` : '';
            })()}
            ${(() => {
              // [418/421] Card LIMPIA (feedback dueño): solo lo DEL DÍA, sin números de
              // ticket y SIN deuda total (el detalle ticket×monto vive en el modal Auditar).
              const colabU = parseFloat(p.envasadosColab || (ev && ev.envasadosColab) || 0);
              const colabS = parseFloat(p.pagoEnvasadoColab || (ev && ev.pagoEnvasadoColab) || 0);
              const cdia   = p.creditosDia || (ev && ev.creditosDia) || {};
              const cdT    = parseFloat(cdia.total || 0), cdN = parseInt(cdia.n || 0, 10);
              const partes = [];
              if (colabU > 0) partes.push(`<span style="color:#a5b4fc;font-weight:700" title="Envasado colaborativo: el pago se divide 50/50">🤝 ${colabU} u colab · S/${colabS.toFixed(2)}</span>`);
              if (cdN > 0) partes.push(`<span style="color:#fbbf24;font-weight:700" title="Consumo a crédito de este día — detalle en Auditar">🧾 consumió este día S/${cdT.toFixed(2)}</span>`);
              return partes.length ? `<div class="text-[11px] mt-0.5" style="line-height:1.5">${partes.join(' · ')}</div>` : '';
            })()}
            ${(() => {
              // [v2.41.66] Mostrar motivos de bonificación/sanción debajo del pago
              const bon = ev && parseFloat(ev.bonificacion) || 0;
              const san = ev && parseFloat(ev.sancion) || 0;
              const bonMot = (ev && ev.bonificacionMotivo) || '';
              const sanMot = (ev && ev.sancionMotivo) || '';
              const partes = [];
              if (bon > 0) partes.push(`<span style="color:#34d399;font-weight:700">🎁 +S/${bon.toFixed(2)}</span>${bonMot ? `<span style="color:#94a3b8"> · ${_escapeHtml(bonMot.substring(0, 60))}</span>` : ''}`);
              if (san > 0) partes.push(`<span style="color:#f87171;font-weight:700">⚠ -S/${san.toFixed(2)}</span>${sanMot ? `<span style="color:#94a3b8"> · ${_escapeHtml(sanMot.substring(0, 60))}</span>` : ''}`);
              return partes.length
                ? `<div class="text-[11px] mt-1" style="line-height:1.3">${partes.join(' · ')}</div>`
                : '';
            })()}
          </div>
          <div class="flex flex-col gap-1 shrink-0 items-end">
            <div class="flex gap-1 mb-0.5">
              <button onclick="event.stopPropagation();MOS.abrirEspiaPorUsuario('${_escAttrJs(p.nombre || '')}')"
                class="w-7 h-7 rounded-full flex items-center justify-center hover:scale-110 transition-all"
                style="background:rgba(99,102,241,0.18);border:1px solid rgba(99,102,241,0.5);color:#a5b4fc;font-size:11px;"
                title="Espiar a ${_escapeHtml(p.nombre)} (audio + GPS)">🕵️</button>
            </div>
            ${idForEval ? `<button onclick="MOS.abrirAuditar('${idForEval}', this)" class="btn-primary text-xs whitespace-nowrap px-3 py-1.5">Auditar</button>` : ''}
            <div class="flex gap-1 mt-1">
              ${esBloqueado
                ? `<button onclick="event.stopPropagation();MOS.finLiberarDispositivosUsuario('${_escAttrJs(p.nombre || '')}')"
                    class="w-7 h-7 rounded-md flex items-center justify-center hover:scale-110 transition-all"
                    style="background:rgba(34,197,94,0.18);border:1px solid rgba(34,197,94,0.55);color:#86efac;font-size:12px;position:relative;z-index:10;"
                    title="🔓 Liberar dispositivo(s) bloqueado(s) — requiere clave admin">🔓</button>`
                : `<button onclick="event.stopPropagation();MOS.finBloquearUsuario('${_escAttrJs(p.nombre || '')}','${(ev && ev.appOrigen) || p.appOrigen || ''}','${(ev && ev.idPersonal) || p.idPersonal || ''}')"
                    class="w-7 h-7 rounded-md flex items-center justify-center hover:scale-110 transition-all"
                    style="background:rgba(245,158,11,0.12);border:1px solid rgba(245,158,11,0.5);color:#fbbf24;font-size:12px;position:relative;z-index:10;"
                    title="🔒 Bloquear dispositivo (pantalla de candado en su tablet/celular)">🔒</button>`}
              ${esVetada
                ? `<button onclick="event.stopPropagation();MOS.finRehabilitarPago('${p.idJornada || ''}','${fecha}','${_escAttrJs(p.nombre || '')}','${idMega}')"
                    class="w-7 h-7 rounded-md flex items-center justify-center hover:scale-110 transition-all"
                    style="background:rgba(34,197,94,0.15);border:1px solid rgba(34,197,94,0.55);color:#86efac;font-size:12px;position:relative;z-index:10;"
                    title="💵 Rehabilitar pago (revierte el veto y restaura el monto)">💵</button>`
                : `<button onclick="event.stopPropagation();MOS.finVetarPago('${p.idJornada || ''}','${fecha}','${_escAttrJs(p.nombre || '')}','${idMega}')"
                    class="w-7 h-7 rounded-md flex items-center justify-center hover:scale-110 transition-all"
                    style="background:rgba(168,85,247,0.12);border:1px solid rgba(168,85,247,0.5);color:#c084fc;font-size:12px;position:relative;z-index:10;"
                    title="💸 Vetar del pago de hoy (sigue operando, pero no se contará en gastos)">💸</button>`}
            </div>
          </div>
        </div>
      </div>`;
  }

  function _finRenderGastos(pl, fecha) {
    const listEl  = $('finGastosList');
    const categEl = $('finGastosCateg');
    const totEl   = $('finGastosTotal');
    const subEl   = $('finGastosSub');
    if (!listEl) return;
    const totalGastos = parseFloat(pl.gastoOtros || 0);
    if (totEl) totEl.textContent = 'S/ ' + totalGastos.toFixed(2);

    const cantidad = (pl.gastosDetalle || []).length;
    const tieneGastos = cantidad > 0;

    // Modo SLIM cuando no hay gastos: card mínimo, sub-text invitando
    if (!tieneGastos) {
      if (subEl) subEl.textContent = 'Sin gastos hoy · click en + para agregar';
      listEl.classList.add('hidden');
      categEl?.classList.add('hidden');
      listEl.innerHTML = '';
      if (categEl) categEl.innerHTML = '';
      return;
    }

    // Modo EXPANDIDO con gastos
    if (subEl) subEl.textContent = `${cantidad} gasto${cantidad !== 1 ? 's' : ''} registrado${cantidad !== 1 ? 's' : ''}`;
    listEl.classList.remove('hidden');
    categEl?.classList.remove('hidden');

    if (categEl) {
      const cats = pl.gastosByCategoria || {};
      const keys = Object.keys(cats);
      categEl.innerHTML = keys.length ? keys.map(cat => `
        <div class="flex justify-between text-xs">
          <span class="text-slate-400">${cat}</span>
          <span class="text-slate-200 font-semibold">S/ ${cats[cat].toFixed(2)}</span>
        </div>`).join('') : '';
    }
    const tagColor = t => t === 'FIJO' ? 'fin-tag-amber' : 'fin-tag-green';
    listEl.innerHTML = '<div class="border-t border-slate-800 pt-2 mt-1">' +
      pl.gastosDetalle.map(g => `
        <div class="fin-row">
          <div>
            <div class="text-slate-200 text-sm">${g.descripcion || '—'}</div>
            <div class="text-xs text-slate-500">${g.categoria || ''} <span class="fin-tag ${tagColor(g.tipo)} ml-1">${g.tipo||'VAR'}</span> ${g.comprobante ? '· ' + g.comprobante : ''}</div>
          </div>
          <div class="flex items-center gap-2 shrink-0">
            <span class="text-amber-400 font-semibold text-sm">S/ ${parseFloat(g.monto||0).toFixed(2)}</span>
            <button class="fin-del" onclick="MOS.finEliminarGasto('${g.idGasto || ''}','${fecha}')" title="Eliminar">×</button>
          </div>
        </div>`).join('') +
      '</div>';
  }

  // ── Modales ──────────────────────────────────────────────────
  function finAbrirModalGasto() {
    const f = $('finFecha')?.value || today();
    const inp = $('finGastoFecha'); if (inp) inp.value = f;
    const m = $('modalFinGasto'); if (m) { m.classList.remove('hidden'); m.classList.add('open'); }
  }


  function cerrarModalFin(id) {
    const m = $(id); if (m) { m.classList.add('hidden'); m.classList.remove('open'); }
  }

  async function finGuardarGasto() {
    const monto = parseFloat($('finGastoMonto')?.value);
    const desc  = $('finGastoDesc')?.value?.trim();
    const categ = $('finGastoCateg')?.value;
    const tipo  = $('finGastoTipo')?.value;
    const fecha = $('finGastoFecha')?.value;
    const comp  = $('finGastoComp')?.value?.trim();
    if (!monto || monto <= 0) { _finBeep('error'); toast('Ingresa un monto válido', 'error'); return; }
    if (!desc)                { _finBeep('error'); toast('Ingresa una descripción', 'error'); return; }
    // Sonido optimista al click confirmar
    _finBeep('agregar');
    // [FIX 500x BUG-3] guard de reentrada + localId estable: registrarGasto no dedupea server-side por sí;
    // sin esto un doble-tap = dos filas de dinero.
    if (finGuardarGasto._lock) return;
    finGuardarGasto._lock = true;
    const _lidG = 'GST' + Date.now() + Math.random().toString(36).slice(2, 8);
    try {
      await API.post('registrarGasto', {
        fecha, categoria: categ, tipo, descripcion: desc,
        monto, comprobante: comp, registradoPor: S.session?.nombre || '', localId: _lidG
      });
      cerrarModalFin('modalFinGasto');
      toast(`💰 Gasto registrado · S/ ${parseFloat(monto).toFixed(2)} · ${desc}`, 'ok', 4000);
      finCargar();
    } catch(e) {
      _finBeep('error');
      toast('Error: ' + e.message, 'error');
    } finally { finGuardarGasto._lock = false; }
  }

  async function finGuardarJornada() {
    const nombre = $('finJorNombre')?.value?.trim();
    const monto  = parseFloat($('finJorMonto')?.value);
    const fecha  = $('finJorFecha')?.value;
    const rol    = $('finJorRol')?.value?.trim();
    const zona   = $('finJorZona')?.value?.trim();
    const obs    = $('finJorObs')?.value?.trim();
    if (!nombre)             { toast('Ingresa el nombre del trabajador', 'error'); return; }
    if (!monto || monto <= 0){ toast('Ingresa un jornal válido', 'error'); return; }
    // [FIX 500x BUG-3] guard reentrada + localId estable (registrarJornada sin dedup server-side → doble-tap = 2 jornales).
    if (finGuardarJornada._lock) return;
    finGuardarJornada._lock = true;
    const _lidJ = 'JOR' + Date.now() + Math.random().toString(36).slice(2, 8);
    try {
      await API.post('registrarJornada', {
        fecha, nombre, rol, zona, montoJornal: monto, observacion: obs,
        appOrigen: 'MOS', registradoPor: S.session?.nombre || '', localId: _lidJ
      });
      cerrarModalFin('modalFinJornada');
      toast('Jornada registrada', 'ok');
      finCargar();
    } catch(e) { toast('Error: ' + e.message, 'error'); }
    finally { finGuardarJornada._lock = false; }
  }

  async function finEliminarGasto(idGasto, fecha) {
    if (!idGasto) return;
    if (!await _modalConfirm('¿Eliminar este gasto?', { danger: true, titulo: 'Eliminar gasto', okText: 'Eliminar' })) return;
    try {
      await API.post('eliminarGasto', { idGasto });
      toast('Gasto eliminado', 'ok');
      finCargar();
    } catch(e) { toast('Error: ' + e.message, 'error'); }
  }

  // Veto de pago — la persona sigue operando, pero no se cuenta su jornada en esta fecha.
  // El card NO se elimina: queda con efecto vetada (violeta + tachado + badge). Si el sistema
  // detecta actividad POSTERIOR al veto (nuevo ticket/sesión), reaparece automáticamente.
  // [v2.41.45] SIMPLIFICADO — vetar = SOLO cambiar estado en LIQUIDACIONES_DIA.
  // Antes había 2 flujos confusos (eliminarJornada + vetarLiquidacionDia).
  // Ahora ambos botones (🚫 Liquidaciones y 💸 Personal Día) hacen exactamente
  // lo mismo: marcar VETADA en la hoja. Una fuente de verdad. Cero confusión.
  async function finVetarPago(idJornada, fecha, nombre, idMega) {
    const fechaTxt = _formatFechaCorta(fecha);
    // [v2.43.386] Vetar = retiene pago (DINERO) → exige clave admin SIEMPRE (sin cache),
    // EL MISMO gate que el lado de Liquidaciones. Antes era _modalConfirm sin clave →
    // inconsistente ("uno pide clave y otro no").
    const _vAuth = await pedirAuth({
      accion: 'VETAR_LIQUIDACION', allowCache: false,
      refDocumento: (idMega || idJornada || '') + '|' + fecha,
      contexto: `Vetar pago de ${nombre || 'esta persona'} · ${fechaTxt}`
    });
    if (!_vAuth) return;

    // SONIDO OPTIMISTA: dispara INMEDIATO al confirmar (sincronizado con el click).
    // Si después falla el back, sonará 'error'.
    _finBeep('veto');

    // [v2.43.382] Localizar la card por idMega (confiable y único). idJornada está vacío en
    // estas filas → [onclick*=""] matcheaba cualquier card (cruce de overlay).
    const _claveCardV = idMega || idJornada || '__nope__';
    const card = Array.from(document.querySelectorAll('.eval-card')).find(el => {
      return !!el.querySelector(`button[onclick*="finVetarPago"][onclick*="${_claveCardV}"]`);
    });

    let pagoEliminado = 0;
    if (_finPL && Array.isArray(_finPL.personalDetalle)) {
      const idx = _finPL.personalDetalle.findIndex(p => (idMega && String(p.idPersonal) === String(idMega)) || (idJornada && String(p.idJornada) === String(idJornada)));
      if (idx >= 0) {
        const p = _finPL.personalDetalle[idx];
        const resKey = 'mos_fin_resum_' + fecha;
        let ev = null;
        try {
          const raw = localStorage.getItem(resKey);
          if (raw) {
            const parsed = JSON.parse(raw);
            if (Array.isArray(parsed.data)) {
              ev = parsed.data.find(r =>
                (r.idPersonal && r.idPersonal === p.idPersonal) ||
                (String(r.nombre || '').toLowerCase().trim() === String(p.nombre || '').toLowerCase().trim())
              );
            }
          }
        } catch {}
        pagoEliminado = (ev && ev.totalDia) ? parseFloat(ev.totalDia) : (parseFloat(p.monto) || 0);
        // Marcar como vetada en _finPL (no remover del array → el card persiste en próximos render)
        p.vetada = true;
        p.monto = 0;
        p.fuente = 'ELIMINADA';
        p.vetoTs = Date.now();
        // Recalcular P&L local
        _finPL.personas = Math.max(0, (_finPL.personas || 1) - 1);
        _finPL.gastoPersonal = Math.max(0, (parseFloat(_finPL.gastoPersonal) || 0) - pagoEliminado);
        _finPL.totalGastos   = Math.max(0, (parseFloat(_finPL.totalGastos) || 0) - pagoEliminado);
        _finPL.utilidadNeta  = (parseFloat(_finPL.utilidadNeta) || 0) + pagoEliminado;
        _finPL.costosFijos   = Math.max(0, (parseFloat(_finPL.costosFijos) || 0) - pagoEliminado);
        const ventas = parseFloat(_finPL.ventasNetas) || 0;
        const costoV = parseFloat(_finPL.costoVentas) || 0;
        const mc = ventas > 0 ? (ventas - costoV) / ventas : 0;
        _finPL.margenContribPct = ventas > 0 ? +(mc * 100).toFixed(2) : 0;
        _finPL.breakEvenVentas  = mc > 0 ? +(_finPL.costosFijos / mc).toFixed(2) : null;
        _finPL.breakEvenPct     = (_finPL.breakEvenVentas && ventas > 0)
          ? +Math.min(_finPL.breakEvenVentas / ventas * 100, 100).toFixed(2) : 0;
        _finPL.superaBreakEven  = _finPL.breakEvenVentas !== null && ventas >= _finPL.breakEvenVentas;
        _finPL.margenNetoPct    = ventas > 0 ? +(_finPL.utilidadNeta / ventas * 100).toFixed(2) : 0;
      }
    }

    // Aplicar efecto vetada al card (in-place, sin re-render)
    if (card) _aplicarVetadaOverlay(card, nombre, pagoEliminado);

    // Re-render solo KPIs (skipPersonal preserva el card y su animación)
    if (_finPL) {
      try { _finRender(_finPL, fecha, { skipPersonal: true }); } catch {}
    }

    // [v2.41.45] ÚNICA acción: vetar en LIQUIDACIONES_DIA. Sin eliminarJornada.
    // El render del Personal del Día lee el estado VETADA desde la hoja
    // (cruce backend en getResumenTodosDia) → overlay aparece consistente.
    const persona = (_finPL?.personalDetalle || []).find(p => (idMega && String(p.idPersonal) === String(idMega)) || (idJornada && String(p.idJornada) === String(idJornada)));
    // [v2.43.376 · una sola fuente] idPersonal de la MEGA TABLA (lo pasa la card desde
    // ev.idPersonal = getPersonalDiaFast/liquidaciones_dia) — el MISMO id que usa Liquidación.
    const idPersonal = idMega || persona?.idPersonal;
    if (!idPersonal) {
      toast('No se puede vetar: persona sin idPersonal', 'warn');
      _finBeep('error');
      return;
    }
    // [v2.41.52] FIX OPTIMISMO: API.post devuelve d.data (undefined si backend
    // retorna {ok:true} sin data). El check viejo "if(!r||r.ok===false)" caía
    // en falso negativo, revertía el overlay y daba sensación de no-optimista.
    // Ahora: si await resuelve = éxito. Errores reales caen al catch(e) via
    // _fetch que tira throw cuando d.ok=false. (e.message = error key).
    try {
      await API.post('vetarLiquidacionDia', {
        idPersonal: idPersonal,
        fecha: fecha, claveAdmin: (_vAuth && _vAuth.clave) || '',
        localId: 'L' + Date.now() + Math.random().toString(36).slice(2, 8)
      });
      // Mantener el overlay aplicado y P&L local
      if (persona) persona.vetada = true;
      // Invalidar cache local del Personal Día y Liquidaciones
      try {
        const resKey = 'mos_fin_resum_' + fecha;
        const raw = localStorage.getItem(resKey);
        if (raw) {
          const parsed = JSON.parse(raw);
          if (Array.isArray(parsed.data)) {
            parsed.data.forEach(rr => {
              if (rr.idPersonal === idPersonal) rr.vetada = true;
            });
            localStorage.setItem(resKey, JSON.stringify(parsed));
          }
        }
      } catch(_){}
      try { _liqCacheClear && _liqCacheClear(); } catch(_){}
      // Optimista en liq state
      try {
        if (_liqState && Array.isArray(_liqState.pendientes)) {
          const pLocal = _liqState.pendientes.find(x => x.idPersonal === idPersonal);
          if (pLocal) {
            pLocal.dias = pLocal.dias.filter(d => d.fecha !== fecha);
            pLocal.cantidadDias = pLocal.dias.length;
            pLocal.total = Math.round(pLocal.dias.reduce((s, d) => s + d.totalDia, 0) * 100) / 100;
            if (!pLocal.dias.length) {
              _liqState.pendientes = _liqState.pendientes.filter(p => p !== pLocal);
            }
          }
        }
      } catch(_){}
      toast(`💸 Vetado · ${nombre || ''} · -S/ ${pagoEliminado.toFixed(2)} · ahora aparece 💵 para rehabilitar`, 'ok', 4500);
      // Reemplazar card tras animación
      setTimeout(() => _finReemplazarCardJornada(idJornada, fecha, idMega), 720);
    } catch(e) {
      _finBeep('error');
      if (card) {
        const ov = card.querySelector('.fin-vetada-overlay');
        if (ov) ov.remove();
        card.classList.remove('fin-vetada-card');
      }
      const errKey = (e && e.message) || 'error';
      let msg;
      if (errKey === 'YA_PAGADA') msg = 'Esta liquidación ya está PAGADA — no se puede vetar.';
      else msg = 'No se pudo vetar: ' + errKey;
      toast(msg, 'error', 5000);
      // Rollback del P&L local (revertir el descuento ya aplicado)
      if (persona) {
        persona.vetada = false;
        persona.monto = pagoEliminado;
        persona.fuente = persona.fuente === 'ELIMINADA' ? 'MANUAL' : persona.fuente;
        delete persona.vetoTs;
        if (_finPL) {
          _finPL.personas = (_finPL.personas || 0) + 1;
          _finPL.gastoPersonal = (parseFloat(_finPL.gastoPersonal) || 0) + pagoEliminado;
          _finPL.totalGastos   = (parseFloat(_finPL.totalGastos) || 0) + pagoEliminado;
          _finPL.utilidadNeta  = (parseFloat(_finPL.utilidadNeta) || 0) - pagoEliminado;
          _finPL.costosFijos   = (parseFloat(_finPL.costosFijos) || 0) + pagoEliminado;
          try { _finRender(_finPL, fecha, { skipPersonal: true }); } catch {}
        }
      }
    }
  }

  function _formatFechaCorta(fecha) {
    if (!fecha) return 'hoy';
    const hoy = (typeof today === 'function') ? today() : new Date().toISOString().slice(0, 10);
    if (fecha === hoy) return 'hoy (' + fecha + ')';
    try {
      const d = new Date(fecha + 'T00:00:00');
      return d.toLocaleDateString('es-PE', { day: '2-digit', month: 'long', year: 'numeric' });
    } catch { return fecha; }
  }

  // Aplica overlay vetada al card (violeta + tachado + badge "💸 VETADA")
  function _aplicarVetadaOverlay(card, nombre, monto) {
    if (!card || card.querySelector('.fin-vetada-overlay')) return;
    card.classList.add('fin-vetada-card');
    card.style.position = 'relative';
    const ov = document.createElement('div');
    ov.className = 'fin-vetada-overlay';
    ov.innerHTML = `
      <div class="fin-vetada-stripe"></div>
      <div class="fin-vetada-badge">💸 VETADA · -S/ ${parseFloat(monto || 0).toFixed(2)}</div>`;
    card.appendChild(ov);
    // Pulso violeta breve
    card.style.transition = 'box-shadow 0.4s, transform 0.4s';
    card.style.boxShadow = '0 0 24px rgba(168,85,247,0.45)';
    setTimeout(() => { card.style.boxShadow = ''; }, 700);
  }

  // Alias por compatibilidad con código viejo

  // Rehabilita el veto: animación de "rejas suben" del overlay vetada,
  // restaura monto, recalcula KPIs locales, y persiste en GAS.
  async function finRehabilitarPago(idJornada, fecha, nombre, idMega) {
    const fechaTxt = _formatFechaCorta(fecha);
    // [v2.43.386] Rehabilitar = restituye pago (DINERO) → clave admin SIEMPRE, EL MISMO
    // gate que Liquidaciones (antes _modalConfirm sin clave).
    const _dAuth = await pedirAuth({
      accion: 'DESVETAR_LIQUIDACION', allowCache: false,
      refDocumento: (idMega || idJornada || '') + '|' + fecha,
      contexto: `Rehabilitar pago de ${nombre || 'esta persona'} · ${fechaTxt}`
    });
    if (!_dAuth) return;

    // SONIDO OPTIMISTA: dispara INMEDIATO al confirmar.
    _finBeep('rehab');

    // [v2.43.382] Localizar la card por idMega (id de la mega tabla, confiable y único por
    // persona). Antes usaba idJornada que en estas filas está VACÍO → [onclick*=""] matcheaba
    // CUALQUIER card → quitaba el enmallado de la equivocada (Jorgenis seguía enmallado).
    const _claveCard = idMega || idJornada || '__nope__';
    const card = Array.from(document.querySelectorAll('.eval-card')).find(el => {
      return !!el.querySelector(`button[onclick*="finRehabilitarPago"][onclick*="${_claveCard}"]`);
    });

    // Calcular monto a restaurar (mejor desde PERSONAL_MASTER cache, fallback p.monto)
    let montoRestaurar = 0;
    let pTarget = null;
    if (_finPL && Array.isArray(_finPL.personalDetalle)) {
      pTarget = _finPL.personalDetalle.find(p => (idMega && String(p.idPersonal) === String(idMega)) || (idJornada && String(p.idJornada) === String(idJornada)));
      if (pTarget) {
        // Si el cache tiene resumen con totalDia, usarlo
        const resKey = 'mos_fin_resum_' + fecha;
        try {
          const raw = localStorage.getItem(resKey);
          if (raw) {
            const parsed = JSON.parse(raw);
            if (Array.isArray(parsed.data)) {
              const ev = parsed.data.find(r =>
                (r.idPersonal && r.idPersonal === pTarget.idPersonal) ||
                (String(r.nombre || '').toLowerCase().trim() === String(pTarget.nombre || '').toLowerCase().trim())
              );
              if (ev && ev.totalDia) montoRestaurar = parseFloat(ev.totalDia);
            }
          }
        } catch {}
        if (!montoRestaurar) {
          // Buscar montoBase en personal (cfgData o S._cajeros)
          try {
            const personal = (S._personal || []).concat(cfgData?.personal || []);
            const match = personal.find(x =>
              (x.idPersonal && x.idPersonal === pTarget.idPersonal) ||
              String(x.nombre || '').toLowerCase().trim() === String(pTarget.nombre || '').toLowerCase().trim()
            );
            if (match) montoRestaurar = parseFloat(match.montoBase || 0);
          } catch {}
        }
      }
    }

    // Animación: rejas/overlay suben con fade-out
    if (card) {
      const ov = card.querySelector('.fin-vetada-overlay');
      if (ov) {
        ov.style.transition = 'transform 0.45s cubic-bezier(0.4,0,0.2,1), opacity 0.4s ease-out, filter 0.4s';
        ov.style.transform = 'translateY(-100%)';
        ov.style.opacity = '0';
        ov.style.filter = 'blur(3px)';
        setTimeout(() => ov.remove(), 460);
      }
      card.classList.remove('fin-vetada-card');
      // Pulso verde breve indica rehabilitación
      card.style.transition = 'box-shadow 0.4s, transform 0.4s';
      card.style.boxShadow = '0 0 28px rgba(34,197,94,0.5)';
      setTimeout(() => { card.style.boxShadow = ''; }, 800);
    }

    // Update _finPL en memoria (revertir veto)
    if (pTarget) {
      pTarget.vetada = false;
      pTarget.fuente = 'MANUAL';
      pTarget.monto = montoRestaurar || pTarget.monto || 0;
      delete pTarget.vetoTs;
      // Recalcular P&L local (suma de vuelta el monto)
      const m = parseFloat(pTarget.monto) || 0;
      _finPL.personas = (parseInt(_finPL.personas, 10) || 0) + 1;
      _finPL.gastoPersonal = (parseFloat(_finPL.gastoPersonal) || 0) + m;
      _finPL.totalGastos   = (parseFloat(_finPL.totalGastos) || 0) + m;
      _finPL.utilidadNeta  = (parseFloat(_finPL.utilidadNeta) || 0) - m;
      _finPL.costosFijos   = (parseFloat(_finPL.costosFijos) || 0) + m;
      const ventas = parseFloat(_finPL.ventasNetas) || 0;
      const costoV = parseFloat(_finPL.costoVentas) || 0;
      const mc = ventas > 0 ? (ventas - costoV) / ventas : 0;
      _finPL.margenContribPct = ventas > 0 ? +(mc * 100).toFixed(2) : 0;
      _finPL.breakEvenVentas  = mc > 0 ? +(_finPL.costosFijos / mc).toFixed(2) : null;
      _finPL.breakEvenPct     = (_finPL.breakEvenVentas && ventas > 0)
        ? +Math.min(_finPL.breakEvenVentas / ventas * 100, 100).toFixed(2) : 0;
      _finPL.superaBreakEven  = _finPL.breakEvenVentas !== null && ventas >= _finPL.breakEvenVentas;
      _finPL.margenNetoPct    = ventas > 0 ? +(_finPL.utilidadNeta / ventas * 100).toFixed(2) : 0;
    }

    // Re-render KPIs sin tocar el card (preserva animación)
    if (_finPL) {
      try { _finRender(_finPL, fecha, { skipPersonal: true }); } catch {}
    }

    // [v2.41.45] ÚNICA acción: desvetar en LIQUIDACIONES_DIA.
    // [v2.43.376 · una sola fuente] idPersonal de la MEGA TABLA (lo pasa la card).
    const persona = (_finPL?.personalDetalle || []).find(p => (idMega && String(p.idPersonal) === String(idMega)) || (idJornada && String(p.idJornada) === String(idJornada)));
    const idPersonal = idMega || persona?.idPersonal;
    if (!idPersonal) {
      toast('No se puede rehabilitar: persona sin idPersonal', 'warn');
      _finBeep('error');
      return;
    }
    // [v2.41.52] Mismo fix: confiar en resolve = éxito.
    try {
      await API.post('desvetarLiquidacionDia', {
        idPersonal: idPersonal,
        fecha: fecha, claveAdmin: (_dAuth && _dAuth.clave) || '',
        localId: 'L' + Date.now() + Math.random().toString(36).slice(2, 8)
      });
      if (persona) persona.vetada = false;
      // Invalidar cache local
      try {
        const resKey = 'mos_fin_resum_' + fecha;
        const raw = localStorage.getItem(resKey);
        if (raw) {
          const parsed = JSON.parse(raw);
          if (Array.isArray(parsed.data)) {
            parsed.data.forEach(rr => {
              if (rr.idPersonal === idPersonal) rr.vetada = false;
            });
            localStorage.setItem(resKey, JSON.stringify(parsed));
          }
        }
      } catch(_){}
      try { _liqCacheClear && _liqCacheClear(); } catch(_){}
      toast(`💵 Rehabilitado · ${nombre || ''} · +S/ ${parseFloat(montoRestaurar || 0).toFixed(2)} · ahora aparece 💸 para vetar`, 'ok', 4500);
      setTimeout(() => _finReemplazarCardJornada(idJornada, fecha, idMega), 480);
    } catch(e) {
      _finBeep('error');
      toast('Error: ' + e.message + ' — recargando...', 'error');
      finCargar();
    }
  }

  // ════════════════════════════════════════════════════════════
  // BLOQUEO DE DISPOSITIVO — pantalla de candado en ME / WH
  // Visualmente: efecto de rejas cayendo sobre la card.
  // ════════════════════════════════════════════════════════════
  async function finBloquearUsuario(nombre, appOrigen, idPersonal) {
    if (!nombre) return;
    const apoyo = (appOrigen || '').toLowerCase().indexOf('warehouse') >= 0
      ? 'tablet/celular WH'
      : 'POS de MosExpress';
    // [v2.41.83] AdminAuthModal (antes solo confirm()) — tier 2 cache 5min
    const auth = await pedirAuth({
      accion: 'BLOQUEAR_DISPOSITIVO',
      refDocumento: nombre,
      contexto: `Encarcelar dispositivos de ${nombre} (${apoyo}). Aparecerá candado en <30s.`
    });
    if (!auth) return;

    _finBeep('bloquear');

    // Aplicar overlay temporal inmediato (luego el re-render lo hace persistente)
    const allCards = document.querySelectorAll('.eval-card');
    const cardsTarget = Array.from(allCards).filter(el => {
      const btn = el.querySelector(`button[onclick*="finBloquearUsuario"][onclick*="${nombre.replace(/'/g, '&#39;')}"]`);
      return !!btn;
    });
    cardsTarget.forEach(c => _aplicarRejasOverlay(c, nombre));

    try {
      const r = await API.post('bloquearDispositivosDeUsuario', {
        nombre,
        appOrigen: appOrigen || 'mosExpress',
        bloqueadoPor: auth.nombre || S.session?.nombre || 'admin',
        claveAdmin: auth.clave,
        motivo: 'bloqueo_desde_personal_dia'
      });
      if (r && r.ok !== false) {
        const n = r.data?.cantidad || 0;
        if (n > 0) {
          toast(`🔒 ${nombre} · ${n} dispositivo(s) encarcelado(s) · pantalla candado en <30s`, 'ok', 5000);
          // Actualizar state local inmediatamente para que el re-render persista
          const nLow = String(nombre).toLowerCase().trim();
          _finBloqueados.porNombre = _finBloqueados.porNombre || {};
          _finBloqueados.porNombre[nLow] = {
            nombre,
            // [v2.42.04 fix] r ya es data desempaquetado (API.post)
            dispositivos: r?.bloqueados || []
          };
          // Re-render del personal para pintar overlay persistente
          if (_finPL) _finRenderPersonal(_finPL, _finPL._fechaStamp || $('finFecha')?.value || today());
        } else {
          toast(`⚠ ${nombre} no tenía dispositivos activos para encarcelar`, 'warning');
          cardsTarget.forEach(c => {
            const ov = c.querySelector('.fin-rejas-overlay:not(.fin-rejas-persist)');
            if (ov) ov.remove();
          });
        }
      } else {
        throw new Error(r?.error || 'No se pudo bloquear');
      }
    } catch(e) {
      _finBeep('error');
      cardsTarget.forEach(c => {
        const ov = c.querySelector('.fin-rejas-overlay:not(.fin-rejas-persist)');
        if (ov) ov.remove();
      });
      toast('Error: ' + e.message, 'error');
    }
  }

  // Libera todos los dispositivos encarcelados de un usuario. Requiere clave
  // admin de 8 dígitos por cada dispositivo (más seguro: cada UUID es una
  // decisión independiente). En la práctica son 1-2 devices máximo por
  // usuario, así que la fricción es aceptable.
  async function finLiberarDispositivosUsuario(nombre) {
    if (!nombre) return;
    const nLow = String(nombre).toLowerCase().trim();
    const info = _finBloqueados?.porNombre?.[nLow];
    if (!info || !info.dispositivos?.length) {
      toast('No hay dispositivos bloqueados para ' + nombre, 'warning');
      return;
    }
    const devices = info.dispositivos;
    // [v2.41.83] AdminAuthModal universal (antes prompt() nativo).
    // Una sola clave para liberar todos los devices del usuario (la clave
    // se reutiliza en el loop interno).
    const auth = await pedirAuth({
      accion: 'LIBERAR_DISPOSITIVO_BLOQUEADO',
      refDocumento: nombre,
      contexto: `Liberar ${devices.length} dispositivo(s) de ${nombre}`
    });
    if (!auth) return;
    _finBeep('bloquear');
    let liberados = 0, fallados = 0, errMsg = '';
    for (const d of devices) {
      try {
        const r = await API.post('liberarDispositivoBloqueado', {
          deviceId: d.deviceId,
          claveAdmin: auth.clave,
          motivo: 'liberacion_desde_personal_dia'
        });
        if (r?.ok && r.data?.autorizado && !r.data?.error) {
          liberados++;
        } else {
          fallados++;
          errMsg = r?.data?.error || r?.error || 'desconocido';
        }
      } catch(e) { fallados++; errMsg = e.message; }
    }
    if (liberados > 0) {
      toast(`🔓 ${liberados} dispositivo(s) liberado(s) · pueden operar en <30s`, 'ok', 5000);
      // Limpiar state local y re-render
      delete _finBloqueados.porNombre[nLow];
      if (_finPL) _finRenderPersonal(_finPL, _finPL._fechaStamp || $('finFecha')?.value || today());
    }
    if (fallados > 0) {
      toast(`❌ ${fallados} no se pudo liberar: ${errMsg}`, 'error', 6000);
    }
  }

  // Pinta el overlay de rejas sobre un card (con animación de caída)
  function _aplicarRejasOverlay(card, nombre) {
    if (!card || card.querySelector('.fin-rejas-overlay')) return;
    const rect = card.getBoundingClientRect();
    const ov = document.createElement('div');
    ov.className = 'fin-rejas-overlay';
    ov.innerHTML = `
      <div class="fin-rejas-bars">
        <div class="fin-rejas-bar"></div>
        <div class="fin-rejas-bar" style="animation-delay:60ms"></div>
        <div class="fin-rejas-bar" style="animation-delay:120ms"></div>
        <div class="fin-rejas-bar" style="animation-delay:180ms"></div>
        <div class="fin-rejas-bar" style="animation-delay:240ms"></div>
        <div class="fin-rejas-bar" style="animation-delay:300ms"></div>
      </div>
      <div class="fin-rejas-badge">🔒 BLOQUEADO</div>
      <div class="fin-rejas-sub">${nombre}</div>`;
    card.style.position = 'relative';
    card.appendChild(ov);
    // Pulso del card
    card.style.transition = 'box-shadow 0.4s, transform 0.4s';
    card.style.boxShadow = '0 0 24px rgba(245,158,11,0.55)';
    setTimeout(() => { card.style.boxShadow = ''; }, 800);
  }


  // ── Editor de costo inline (desde alerta sin costo) ─────────
  let _finEditSku = null;


  function finCerrarCostoEditor() {
    _finEditSku = null;
    $('finCostoEditorWrap')?.classList.add('hidden');
  }

  // ── Editor de margen default global ──────────────────────
  function finAbrirEditorMargenDefault() {
    const inp = $('finMargenDefaultInput');
    const cur = parseFloat(_finPL?.defaultMargenUsado) || 20;
    if (inp) inp.value = cur;
    // Mostrar impacto del día actual
    const impEl = $('finMargenDefaultImpacto');
    if (impEl && _finPL) {
      const estim = parseFloat(_finPL.costoVentasEstimado || 0);
      const real  = parseFloat(_finPL.costoVentasReal || 0);
      const cantEstim = parseInt(_finPL.cantidadEstimados || 0);
      if (cantEstim === 0) {
        impEl.textContent = '✅ Hoy todos los productos vendidos tienen costo real asignado. Este default no afectó nada.';
      } else {
        impEl.innerHTML = `Hoy hay <b>${cantEstim} SKU${cantEstim === 1 ? '' : 's'}</b> sin precio costo. Se estimó <b class="text-amber-400">S/ ${estim.toFixed(2)}</b> de costo de venta usando este margen (vs <b>S/ ${real.toFixed(2)}</b> real). Cambiar el % afectará la utilidad mostrada inmediatamente al guardar.`;
      }
    }
    openModal('modalMargenDefault');
  }
  function finCerrarEditorMargenDefault() { closeModal('modalMargenDefault'); }

  async function finGuardarMargenDefault() {
    const v = parseFloat($('finMargenDefaultInput')?.value);
    if (isNaN(v) || v < 0 || v >= 100) {
      toast('Margen debe ser 0-99', 'error');
      if (typeof _evalSfx === 'function') _evalSfx('error');
      return;
    }
    // OPTIMISTA: feedback inmediato
    if (typeof _evalSfx === 'function') _evalSfx('success');
    try {
      const btn = $('finMargenDefaultSaveBtn');
      if (btn && typeof _evalConfetti === 'function') {
        const r = btn.getBoundingClientRect();
        _evalConfetti(r.left + r.width/2, r.top + r.height/2, '#fbbf24');
      }
    } catch(_){}
    toast(`Margen default ${v}% guardado ✓`, 'ok');
    finCerrarEditorMargenDefault();
    // Patch local _finPL.defaultMargenUsado y re-render solo el KPI de margen
    // (sin esperar a finCargar completo, que tarda 3-5s).
    try {
      if (_finPL) {
        _finPL.defaultMargenUsado = v;
        // Re-pintar el KPI de margen promedio si está visible
        const estimEl = $('finKpiMargenEstim');
        if (estimEl && _finPL.cantidadEstimados) {
          estimEl.textContent = `${_finPL.cantidadEstimados} SKU${_finPL.cantidadEstimados === 1 ? '' : 's'} estim. al ${v}%`;
        }
        // Refrescar el badge de color comparando margen real vs nuevo default
        const margenEl = $('finKpiMargenProm');
        if (margenEl && typeof _finPL.margenPromedioPct === 'number') {
          const real = parseFloat(_finPL.margenPromedioPct);
          margenEl.style.color = real >= v ? '#34d399' : '#fbbf24';
        }
      }
    } catch(_){}
    // Backend: el setConfig YA se guardó. Pidamos un refresh suave en bg
    // (sin animaciones de skeleton, solo actualiza si difiere).
    try {
      API.post('setConfig', { clave: 'finMargenDefault', valor: String(v) }).catch(() => {});
    } catch(_){}
    // Fetch fresh en bg para validar (Finanzas recalcula con el nuevo margen)
    setTimeout(() => {
      try {
        const fecha = $('finFecha')?.value || today();
        API.get('getFinanzasDia', { fecha }).then(pl => {
          if (pl) {
            pl._fechaStamp = fecha;
            _finPL = pl;
            _finSaveCache && _finSaveCache('pl_' + fecha, pl);
            if (S.view === 'finanzas' && typeof _finRender === 'function') {
              _finRender(pl, fecha);
            }
          }
        }).catch(() => {});
      } catch(_){}
    }, 100);
  }


  // ── Modal Productos Vendidos ─────────────────────────────────
  // [796] REDISEÑO pedido por el dueño. Antes la tabla mostraba Cant · Precio · Costo u. ·
  // Costo total · ✎: puro costo, sin NADA contra qué compararlo. El 14-ago un solo SKU con
  // el costo mal cargado (AJINOMOTO GLUTAMATO 90GR / LEV1564: costo S/320, precio S/2.50)
  // hundió el margen del día a −17.4% cuando el real era +16.8%, y estuvo 4 días invisible
  // porque nadie podía ver "cobré X y me costó Y" en la misma fila. Ahora: se cobró · costó ·
  // chip de margen (rojo si negativo) y la fila entera en rojo si el costo supera la venta.
  // El ✎ de editar costo se fue: los costos se cargan desde el catálogo, no desde Finanzas.
  let _finProdFiltroSinCosto = false;
  let _finProdBusca = '';
  let _finProdOrden = 'ingreso';   // [796] por defecto manda la plata, no la cantidad
  let _finProdDir   = -1;          // -1 = descendente

  function finAbrirModalProductos() {
    const m = $('finModalProductos');
    if (!m) return;
    m.classList.remove('hidden'); m.classList.add('open');
    _finProdFiltroSinCosto = false;
    _finProdBusca = '';
    _finProdOrden = 'ingreso'; _finProdDir = -1;
    const inp = $('finProdBuscar'); if (inp) inp.value = '';
    _finRenderProductos();
  }


  // ══════════════════════════════════════════════════════════════════════
  // [852] GESTIÓN DE IA — la constancia de uso que pidió el dueño.
  //
  // "he hecho muchas recargas en Anthropic… quiero ver día por día cuántos tokens se usaron en
  //  tal función, en tal app, cuántos dólares representa y con qué modelo, para saber si vale
  //  la pena".
  //
  // Anthropic cobra POR TOKEN, y cada respuesta de la API trae su bloque `usage`. Las cuatro
  // Edge Functions que hablan con Claude ahora lo anotan (SQL 852). Acá solo se lee y se pinta.
  // Los precios NO están en este archivo: viven en mos.ia_precios con fecha de vigencia, así un
  // día viejo conserva lo que costó de verdad aunque Anthropic cambie la lista mañana.
  // ══════════════════════════════════════════════════════════════════════
  let _iaDias = 30;
  let _iaData = null;

  function iaSetRango(d) { _iaDias = parseInt(d, 10) || 30; renderIaPanel(); }

  async function renderIaPanel() {
    _iaInyectarCSS();
    const cont = $('iaBody'); if (!cont) return;
    if (!_iaData) cont.innerHTML = '<div class="ia-load">◍ leyendo el consumo de IA…</div>';
    let d = null;
    try {
      const r = await API.post('iaUsoResumen', { dias: _iaDias });
      d = (r && (r.data || r)) || null;
    } catch (e) {
      cont.innerHTML = '<div class="ia-load">No pude leer el consumo: ' + _escapeHtml(e.message || String(e)) + '</div>';
      return;
    }
    if (!d) { cont.innerHTML = '<div class="ia-load">Sin datos</div>'; return; }
    _iaData = d;
    cont.innerHTML = _iaPanelHTML(d);
    _iaPendCargar();   // [937] llena la card de pendientes y arranca el refresco en tiempo real
  }

  // [937] COLA DE PENDIENTES DE IA — "cuánto falta por hacer" en tiempo real, para decidir si el cupo
  // GRATIS de Gemini alcanza o hay que recargar Anthropic. Se refresca solo cada 30 s mientras el panel
  // está a la vista. Los pendientes se retoman solos en cada corrida del cron (se auto-concilian).
  let _iaPendTimer = null;
  async function _iaPendCargar() {
    const card = document.getElementById('iaPendCard');
    if (!card) { if (_iaPendTimer) { clearTimeout(_iaPendTimer); _iaPendTimer = null; } return; }
    const visible = card.offsetParent !== null && document.visibilityState !== 'hidden';
    if (visible) {
      let pd = null;
      try { const r = await API.post('iaPendientes', {}); pd = (r && (r.data || r)) || null; } catch (_) {}
      const c2 = document.getElementById('iaPendCard');
      if (!c2) return;
      if (pd) c2.innerHTML = _iaPendientesHTML(pd);
    }
    if (_iaPendTimer) clearTimeout(_iaPendTimer);
    _iaPendTimer = setTimeout(() => _iaPendCargar(), 30000);
  }

  function _iaPendHace(iso) {
    if (!iso) return '';
    try {
      const dif = (Date.now() - new Date(iso).getTime()) / 60000;   // minutos
      if (dif < 1) return 'recién'; if (dif < 60) return Math.round(dif) + ' min';
      if (dif < 1440) return Math.round(dif / 60) + ' h'; return Math.round(dif / 1440) + ' d';
    } catch (_) { return ''; }
  }
  function _iaPendMotChip(mot) {
    const M = { ok: ['🟢', 'al día'], sin_cupo: ['🟡', 'esperando cupo'], error: ['🔴', 'error'] };
    const m = M[mot] || ['⚪', 'sin actividad hoy'];
    return '<span class="iap-chip iap-' + (mot || 'nada') + '">' + m[0] + ' ' + m[1] + '</span>';
  }
  function _iaPendientesHTML(pd) {
    const colas = Array.isArray(pd.colas) ? pd.colas : [];
    const crit = +pd.criticos_pendientes || 0;
    const tot = +pd.total_pendientes || 0;
    const R = pd.resumen_hoy || {};
    // Veredicto: ¿alcanza Gemini gratis?
    let vClass, vTit, vSub;
    if (crit === 0) {
      vClass = 'is-ok'; vTit = '✓ Al día — el cupo gratis de Gemini alcanza';
      vSub = 'No hay nada crítico pendiente (OCR de guías ni tributos). Por ahora no hace falta recargar Anthropic.'
        + (tot > 0 ? ' Quedan ' + tot + ' de fondo (no urgentes), se resuelven solos.' : '');
    } else {
      vClass = 'is-warn'; vTit = '⏳ ' + crit + ' pendiente' + (crit === 1 ? '' : 's') + ' crítico' + (crit === 1 ? '' : 's');
      vSub = 'OCR/tributos esperando ser procesados. Si no bajan en un rato, el cupo gratis se está quedando corto → conviene recargar Anthropic para que cubra cuando Gemini se llena.';
    }
    const filas = colas.map(c => {
      const h = c.hoy || {};
      const n = +c.pendientes || 0;
      const viejo = (c.mas_viejo_h != null && n > 0) ? ('<i class="iap-viejo">más viejo: ' + c.mas_viejo_h + ' h</i>') : '';
      const atasco = (+c.reintentos_max > 200) ? ('<i class="iap-atasco">⚠ 1 ítem atascado (' + c.reintentos_max + ' intentos)</i>') : '';
      const hoyLbl = (h && (h.ok_hoy != null))
        ? ('<i class="iap-hoy">hoy: ' + (h.ok_hoy || 0) + ' hechos'
            + ((h.cupo_hoy || 0) > 0 ? ' · ' + h.cupo_hoy + ' esperaron cupo' : '')
            + ((h.err_hoy || 0) > 0 ? ' · ' + h.err_hoy + ' error' : '') + '</i>')
        : '';
      const ult = (h && h.ultimo_ts) ? ('<i class="iap-ult">último intento ' + _iaPendHace(h.ultimo_ts) + '</i>') : '';
      return '<div class="iap-row' + (c.critico ? ' is-crit' : '') + '">' +
        '<div class="iap-n' + (n > 0 ? (c.critico ? ' is-crit' : ' is-pend') : ' is-cero') + '">' + n + '</div>' +
        '<div class="iap-mid">' +
          '<b>' + _escapeHtml(String(c.label)) + (c.critico ? ' <span class="iap-star">★</span>' : '') + '</b>' +
          '<span class="iap-sub">' + hoyLbl + ' ' + viejo + ' ' + atasco + ' ' + ult + '</span>' +
          '<span class="iap-cron">' + _escapeHtml(String(c.cron || '')) + '</span>' +
        '</div>' +
        '<div class="iap-mot">' + _iaPendMotChip(h && h.ultimo_motivo) + '</div>' +
      '</div>';
    }).join('');
    return '<div class="ia-card-h">🔄 Pendientes de IA<span>cuánto falta por hacer · se actualiza solo</span></div>' +
      '<div class="iap-veredicto ' + vClass + '"><b>' + vTit + '</b><span>' + vSub + '</span></div>' +
      '<div class="iap-rows">' + filas + '</div>' +
      '<div class="iap-resumen">Hoy: <b>' + (R.llamadas || 0) + '</b> llamadas · <b class="iap-g">' + (R.ok || 0) + '</b> ok · ' +
        '<b class="iap-y">' + (R.sin_cupo || 0) + '</b> esperaron cupo · ' +
        ((R.fallos || 0) - (R.sin_cupo || 0) > 0 ? '<b class="iap-r">' + ((R.fallos || 0) - (R.sin_cupo || 0)) + '</b> error · ' : '') +
        '<b>' + _iaUsd(R.costo_usd) + '</b></div>' +
      '<div class="iap-nota">🟡 <b>Esperando cupo</b> no es un error: Gemini gratis permite 5 llamadas/minuto por modelo; lo que se pasa se <b>reintenta solo</b> en la próxima corrida hasta resolverse. Solo si los <b>críticos ★</b> (OCR/tributos) se estancan conviene recargar Anthropic.</div>';
  }

  const _iaUsd = v => '$' + (Math.round((+v || 0) * 10000) / 10000).toFixed(4).replace(/0+$/, '').replace(/\.$/, '.00');
  const _iaUsd2 = v => '$' + (+v || 0).toFixed(2);
  function _iaTok(n) {
    n = +n || 0;
    if (n >= 1e6) return (n / 1e6).toFixed(2) + 'M';
    if (n >= 1e3) return (n / 1e3).toFixed(1) + 'k';
    return String(n);
  }
  function _iaFechaCorta(iso) {
    try {
      const [y, m, dd] = String(iso).split('-').map(Number);
      const MES = ['ene','feb','mar','abr','may','jun','jul','ago','set','oct','nov','dic'];
      return dd + ' ' + MES[(m || 1) - 1];
    } catch (_) { return String(iso); }
  }

  function _iaPanelHTML(d) {
    const t = d.total || {};
    const dias = d.porDia || [];
    const hayDatos = (t.llamadas || 0) > 0;

    // proyección del mes: promedio diario × días del mes (solo informativa, se dice que lo es)
    const hoy = new Date(Date.now() - 5 * 3600 * 1000);
    const diasMes = new Date(hoy.getUTCFullYear(), hoy.getUTCMonth() + 1, 0).getUTCDate();
    const diaHoy = hoy.getUTCDate();
    const proy = (+t.usdMes || 0) / Math.max(1, diaHoy) * diasMes;

    const maxDia = Math.max(0.000001, ...dias.map(x => +x.usd || 0));
    const barras = dias.slice().reverse().map(x => {
      const h = Math.max(3, Math.round((+x.usd || 0) / maxDia * 100));
      const esHoy = x.dia === d.hasta;
      return '<button type="button" class="ia-bar' + (esHoy ? ' is-hoy' : '') + '" style="--h:' + h + '%"' +
        ' onclick="MOS.iaVerDia(\'' + _esc(x.dia) + '\')"' +
        ' title="' + _esc(_iaFechaCorta(x.dia)) + ' · ' + _iaUsd(x.usd) + ' · ' + x.llamadas + ' llamadas">' +
        '<i></i><span>' + _esc(String(_iaFechaCorta(x.dia)).split(' ')[0]) + '</span></button>';
    }).join('');

    const totalFun = (d.porFuncion || []).reduce((a, f) => a + (+f.usd || 0), 0) || 1;
    const funciones = (d.porFuncion || []).map(f => {
      const pct = Math.round((+f.usd || 0) / totalFun * 100);
      return '<div class="ia-fn">' +
        '<div class="ia-fn-top"><b>' + _escapeHtml(String(f.funcion)) + '</b>' +
          '<span class="ia-fn-usd">' + _iaUsd(f.usd) + '</span></div>' +
        '<div class="ia-fn-bar"><i style="width:' + pct + '%"></i></div>' +
        '<div class="ia-fn-sub">' + pct + '% del gasto · ' + f.llamadas + ' llamada' + (f.llamadas === 1 ? '' : 's') +
          ' · ' + _iaTok(f.tokens) + ' tokens · <b>' + _iaUsd(f.usdPorLlamada) + ' cada una</b></div>' +
      '</div>';
    }).join('') || '<div class="ia-vacio">Todavía no hay llamadas registradas en este período.</div>';

    const modelos = (d.porModelo || []).map(m =>
      '<div class="ia-chip"><span class="ia-chip-k">' + _escapeHtml(String(m.modelo)) + '</span>' +
      '<b>' + _iaUsd(m.usd) + '</b><i>' + m.llamadas + ' · ' + _iaTok(m.tokens) + ' tok</i></div>').join('')
      || '<div class="ia-vacio">—</div>';

    const apps = (d.porApp || []).map(a =>
      '<div class="ia-chip"><span class="ia-chip-k">' + _escapeHtml(String(a.app)) + '</span>' +
      '<b>' + _iaUsd(a.usd) + '</b><i>' + a.llamadas + ' llamadas</i></div>').join('')
      || '<div class="ia-vacio">—</div>';

    const tarifas = (d.tarifas || []).map(x =>
      '<tr><td>' + _escapeHtml(String(x.etiqueta)) + '</td>' +
      '<td class="ia-num">$' + (+x.usdIn).toFixed(2) + '</td>' +
      '<td class="ia-num">$' + (+x.usdOut).toFixed(2) + '</td>' +
      '<td class="ia-num">$' + (+(x.usdCacheR || 0)).toFixed(2) + '</td></tr>').join('');

    // [853] ESTADO DE CRÉDITOS — lo primero de la pantalla.
    // Anthropic NO publica el saldo por API (su Admin API solo da costo histórico), así que esto
    // no se estima: se lee de lo que la API responde de verdad. Cuando el crédito se acaba, cada
    // llamada vuelve con "credit balance is too low" — el momento exacto en que hay que recargar.
    const E = d.estado || {};
    const _iaEstadoHTML = () => {
      if (!E.estado || E.estado === 'SIN_DATOS') {
        return '<div class="ia-estado is-gris"><span class="ia-est-luz"></span>' +
          '<div><b>Sin datos todavía</b><span>El estado aparece con la primera llamada a la IA.</span></div></div>';
      }
      if (E.estado === 'OPERATIVA') {
        return '<div class="ia-estado is-ok"><span class="ia-est-luz"></span>' +
          '<div><b>IA operativa</b>' +
          '<span>Última llamada ' + _escapeHtml(String(E.ultimaLlamada || '')) +
          (+E.gastoDesdeRecarga > 0 ? ' · llevás <b>' + _iaUsd(E.gastoDesdeRecarga) + '</b> gastados desde la última recarga' : '') +
          '</span></div>' +
          '<a class="ia-est-btn" href="https://platform.claude.com/settings/billing" target="_blank" rel="noopener">Ver saldo ↗</a></div>';
      }
      const sinSaldo = E.motivo === 'SIN_SALDO';
      const tit = sinSaldo ? 'La IA está SIN SALDO' :
                  (E.motivo === 'API_KEY' ? 'La clave de API fue rechazada' : 'La IA está fallando');
      const sub = sinSaldo
        ? 'Anthropic rechaza cada llamada. El OCR de guías, las listas del almacén, las descripciones y los sustitutos están <b>apagados</b>. Hay que recargar créditos.'
        : (E.motivo === 'API_KEY'
            ? 'Hay que renovar el secret <code>ANTHROPIC_API_KEY</code>.'
            : 'Mirá el detalle para entender qué está pasando.');
      return '<div class="ia-estado is-mal' + (sinSaldo ? ' is-grave' : '') + '">' +
        '<span class="ia-est-luz"></span>' +
        '<div><b>' + _escapeHtml(tit) + '</b><span>' + sub + '</span>' +
        '<i>Sin funcionar desde las ' + _escapeHtml(String(E.caidaDesde || '?')) +
          (E.horasSinIa != null ? ' · ' + E.horasSinIa + ' h' : '') +
          ' · ' + (E.fallos || 0) + ' llamada' + ((E.fallos || 0) === 1 ? '' : 's') + ' rechazada' + ((E.fallos || 0) === 1 ? '' : 's') + '</i></div>' +
        (sinSaldo ? '<a class="ia-est-btn is-cta" href="https://platform.claude.com/settings/billing" target="_blank" rel="noopener">Recargar ↗</a>' : '') +
      '</div>';
    };

    // [852b] Si la IA está fallando, el panel lo dice en la cara y con el motivo traducido.
    // Fue lo primero que apareció al encender la contabilidad: el saldo de Anthropic agotado,
    // con los tres crones disparando cada 10 minutos contra una cuenta sin crédito.
    const F = d.fallaTop;
    const MOTIVOS = {
      SIN_SALDO:          ['🔴', 'Sin saldo en Anthropic', 'La IA está APAGADA de hecho: las llamadas se rechazan. Recargá créditos en Plans & Billing para que vuelva a funcionar.'],
      LIMITE_TASA:        ['🟠', 'Límite de velocidad', 'Se están mandando más llamadas por minuto de las permitidas. Los crones reintentan solos.'],
      ANTHROPIC_SATURADO: ['🟡', 'Anthropic saturado', 'Problema del lado de ellos. Se reintenta solo; no hay nada que hacer acá.'],
      API_KEY:            ['🔴', 'Clave de API rechazada', 'El secret ANTHROPIC_API_KEY venció o cambió. Hay que renovarlo.'],
      TIEMPO_AGOTADO:     ['🟡', 'Tiempo agotado', 'La respuesta tardó más de lo permitido. Suele ser por archivos pesados.'],
      OTRO:               ['🟠', 'Fallas en las llamadas', 'Mirá el detalle para entender qué está pasando.']
    };
    const avisoFalla = (F && F.n > 0) ? (() => {
      const m = MOTIVOS[F.motivo] || MOTIVOS.OTRO;
      return '<div class="ia-alerta' + (F.motivo === 'SIN_SALDO' || F.motivo === 'API_KEY' ? ' is-grave' : '') + '">' +
        '<span class="ia-alerta-ico">' + m[0] + '</span>' +
        '<div><b>' + _escapeHtml(m[1]) + '</b>' +
          '<span>' + _escapeHtml(m[2]) + '</span>' +
          '<i>' + F.n + ' llamada' + (F.n === 1 ? '' : 's') + ' rechazada' + (F.n === 1 ? '' : 's') +
          ' · última ' + _escapeHtml(String(F.ultima || '')) + '</i>' +
        '</div></div>';
    })() : '';

    const avisoSinTarifa = (d.sinTarifa > 0)
      ? '<div class="ia-warn">⚠ ' + d.sinTarifa + ' llamada(s) usaron un modelo sin precio configurado: su costo no está contado. ' +
        'Agregá su tarifa en <code>mos.ia_precios</code> para que aparezca.</div>' : '';

    const desdeCuando = d.primerRegistro
      ? 'El registro empieza el <b>' + _escapeHtml(_iaFechaCorta(d.primerRegistro)) + '</b>: lo gastado antes no quedó anotado y no se puede reconstruir.'
      : 'Todavía no hay ninguna llamada registrada. El contador arranca con la primera que ocurra.';

    return '' +
      '<div class="ia-wrap">' +
        _iaEstadoHTML() +
        '<div id="iaPendCard" class="ia-card ia-pend"><div class="ia-load">◍ contando pendientes…</div></div>' +
        '<div class="ia-hero">' +
          '<div class="ia-hero-main">' +
            '<span class="ia-hero-lbl">Gasto de este mes</span>' +
            '<span class="ia-hero-usd">' + _iaUsd2(t.usdMes) + '</span>' +
            '<span class="ia-hero-sub">proyección a fin de mes ≈ <b>' + _iaUsd2(proy) + '</b> ' +
              '<i class="ia-hint" title="Promedio diario del mes × días del mes. Es una estimación, no un cobro.">?</i></span>' +
          '</div>' +
          '<div class="ia-kpis">' +
            '<div class="ia-kpi"><i>hoy</i><b>' + _iaUsd2(t.usdHoy) + '</b></div>' +
            '<div class="ia-kpi"><i>promedio/día</i><b>' + _iaUsd2(t.promDia) + '</b></div>' +
            '<div class="ia-kpi"><i>llamadas</i><b>' + (t.llamadas || 0) + '</b></div>' +
            '<div class="ia-kpi"><i>tokens</i><b>' + _iaTok(t.tokens) + '</b></div>' +
            (t.errores > 0 ? '<div class="ia-kpi is-err"><i>fallidas</i><b>' + t.errores + '</b></div>' : '') +
          '</div>' +
        '</div>' +
        ((E.estado && E.estado !== 'OPERATIVA' && F && F.motivo === E.motivo) ? '' : avisoFalla) +
        avisoSinTarifa +
        '<div class="ia-rango">' +
          [7, 30, 90].map(n => '<button type="button" class="ia-rb' + (_iaDias === n ? ' is-on' : '') +
            '" onclick="MOS.iaSetRango(' + n + ')">' + n + ' días</button>').join('') +
          '<span class="ia-rango-nota">' + _escapeHtml(d.desde) + ' → ' + _escapeHtml(d.hasta) + '</span>' +
        '</div>' +

        (hayDatos ? '<div class="ia-card"><div class="ia-card-h">📅 Día por día<span>tocá una barra para ver el detalle</span></div>' +
          '<div class="ia-bars">' + barras + '</div></div>' : '') +

        '<div class="ia-card"><div class="ia-card-h">🎯 En qué se gasta<span>ordenado por costo</span></div>' +
          '<div class="ia-fns">' + funciones + '</div></div>' +

        '<div class="ia-grid2">' +
          '<div class="ia-card"><div class="ia-card-h">🤖 Por modelo</div><div class="ia-chips">' + modelos + '</div></div>' +
          '<div class="ia-card"><div class="ia-card-h">📱 Por app</div><div class="ia-chips">' + apps + '</div></div>' +
        '</div>' +

        '<details class="ia-card ia-det"><summary>💵 Tarifario vigente <span>USD por millón de tokens</span></summary>' +
          '<div class="ia-tabla-wrap"><table class="ia-tabla"><thead><tr><th>Modelo</th><th class="ia-num">Entrada</th>' +
          '<th class="ia-num">Salida</th><th class="ia-num">Caché leída</th></tr></thead><tbody>' + tarifas + '</tbody></table></div>' +
          '<p class="ia-nota">Precios oficiales de Anthropic. Escribir en caché cuesta 1.25× la entrada y leerla 0.1×. ' +
          'Viven en la tabla <code>mos.ia_precios</code> con fecha de vigencia: si cambian, los días anteriores conservan su costo real.</p>' +
        '</details>' +

        '<div class="ia-pie">🧾 <b>Dónde se usa IA hoy:</b> lista sombra de almacén (foto, PDF y texto), ' +
          'OCR de comprobantes de proveedor, descripción automática de productos, sugerencia de sustitutos ' +
          'y el chat de almacén. Los tres crones corren cada 10 minutos.<br>' + desdeCuando +
          '<br><b>Sobre el saldo:</b> Anthropic no publica el crédito restante por API — su Admin API solo da costo histórico. ' +
          'Por eso el estado de arriba no es una estimación: sale de lo que la API responde de verdad en cada llamada, ' +
          'que es exactamente el momento en que hay que recargar.</div>' +
      '</div>';
  }

  // Detalle de un día: qué función gastó qué, con qué modelo.
  function iaVerDia(dia) {
    const d = _iaData; if (!d) return;
    const row = (d.porDia || []).find(x => String(x.dia) === String(dia));
    if (!row) return;
    try { _finBeep && _finBeep('click'); } catch (_) {}
    const prev = document.getElementById('iaDiaOvl'); if (prev) prev.remove();
    const filas = (row.funciones || []).map(f =>
      '<div class="iad-row">' +
        '<div class="iad-n"><b>' + _escapeHtml(String(f.funcion)) + '</b>' +
          '<i>' + _escapeHtml(String(f.modelos || '')) + ' · ' + _escapeHtml(String(f.app || '')) + '</i></div>' +
        '<div class="iad-t">' + _iaTok(f.tokens) + '<i>tokens</i></div>' +
        '<div class="iad-c">' + f.llamadas + '<i>llamadas</i></div>' +
        '<div class="iad-u">' + _iaUsd(f.usd) + '</div>' +
      '</div>').join('') || '<div class="ia-vacio">Sin detalle</div>';
    const ovl = document.createElement('div');
    ovl.id = 'iaDiaOvl'; ovl.className = 'iad-back';
    ovl.onpointerdown = e => { if (e.target === ovl) MOS.iaCerrarDia(); };
    ovl.innerHTML = '<div class="iad-card" role="dialog" aria-label="Consumo de IA del día">' +
      '<div class="iad-head"><div><b>🧠 ' + _escapeHtml(_iaFechaCorta(row.dia)) + '</b>' +
        '<span>' + row.llamadas + ' llamadas · ' + _iaTok(row.tokens) + ' tokens · entrada ' + _iaTok(row.tokIn) +
        ' / salida ' + _iaTok(row.tokOut) + (row.tokCacheR > 0 ? ' · caché ' + _iaTok(row.tokCacheR) : '') + '</span></div>' +
        '<div class="iad-usd">' + _iaUsd(row.usd) + '</div>' +
        '<button class="iad-x" onclick="MOS.iaCerrarDia()" aria-label="Cerrar">✕</button></div>' +
      '<div class="iad-body">' + filas + '</div></div>';
    document.body.appendChild(ovl);
    requestAnimationFrame(() => ovl.classList.add('in'));
  }
  function iaCerrarDia() {
    const o = document.getElementById('iaDiaOvl'); if (!o) return;
    o.classList.remove('in');
    setTimeout(() => { try { o.remove(); } catch (_) {} }, 180);
  }

