  async function guardarConfigEval() {
    const btn = $('cfgEvalSaveBtn');
    if (btn) { btn.disabled = true; btn.textContent = 'Guardando...'; }
    const pares = [
      ['evalMetaCajero',     $('cfgMetaCajero').value],
      ['evalMetaEnvasador',  $('cfgMetaEnvasador').value],
      ['evalMetaAlmacenero', $('cfgMetaAlmacenero').value],
      ['evalMetaAuditorias', $('cfgMetaAuditorias').value],
      ['evalBonoMetaBase',   $('cfgBonoMetaBase').value],
      ['evalBonoMetaDoble',  $('cfgBonoMetaDoble').value]
    ];
    try {
      await Promise.all(pares.map(([clave, valor]) =>
        API.post('setConfig', { clave, valor: String(valor || '') })
      ));
      toast('Configuración guardada ✓', 'ok');
      closeModal('modalConfigEval');
      refreshEvaluacion().catch(() => {});
    } catch(e) {
      toast('Error: ' + e.message, 'error');
    } finally {
      if (btn) { btn.disabled = false; btn.textContent = 'Guardar'; }
    }
  }


  // ============================================================
  // ── MODAL Producto-Proveedor (cotización) ─────────────────────
  // ============================================================
  const _ppState = { editando: null };

  function abrirModalProvProducto(idPP) {
    const idProv = S.provSelId;
    if (!idProv) { toast('Selecciona primero un proveedor', 'error'); return; }
    const elModal = $('modalProvProducto');
    if (!elModal) { toast('Modal no disponible — recarga la app', 'error'); return; }
    _ppState.editando = idPP;
    const setVal = (id, v) => { const el = $(id); if (el) el.value = v; };
    const setTxt = (id, v) => { const el = $(id); if (el) el.textContent = v; };
    setTxt('ppModalTitle', idPP ? '📦 Editar cotización' : '📦 Nueva cotización');
    setVal('ppId', idPP || '');
    setVal('ppBuscar', '');
    setVal('ppSkuBase', '');
    setVal('ppCodigoBarra', '');
    if ($('ppBuscarRes')) $('ppBuscarRes').style.display = 'none';
    $('ppSeleccionado')?.classList.add('hidden');
    setVal('ppPrecio', '');
    setVal('ppMinimo', '');
    setVal('ppDiasEntrega', '');
    setVal('ppUnidadesBulto', '');
    setVal('ppNotas', '');
    $('ppBtnEliminar')?.classList.toggle('hidden', !idPP);

    // Pre-poblar desde cache local (ya está enriquecido) ANTES de abrir → evita parpadeo
    if (idPP) {
      const cache = (S.provProductos && S.provProductos[idProv]) || [];
      const pp = cache.find(x => x.idPP === idPP);
      if (pp) {
        $('ppSkuBase').value     = pp.skuBase || '';
        $('ppCodigoBarra').value = pp.codigoBarra || '';
        $('ppPrecio').value      = pp.precioReferencia || '';
        $('ppMinimo').value         = pp.minimoCompra || '';
        $('ppDiasEntrega').value    = pp.diasEntrega || '';
        if ($('ppUnidadesBulto')) $('ppUnidadesBulto').value = pp.unidadesPorBulto || '';
        $('ppNotas').value       = pp.notas || '';
        $('ppSeleccionado').textContent = `${pp.descripcion || pp.skuBase} (SKU ${pp.skuBase}${pp.codigoBarra ? ' · ▌' + pp.codigoBarra : ''})`;
        $('ppSeleccionado').classList.remove('hidden');
      }
    }
    openModal('modalProvProducto');
  }

  // Búsqueda de productos: debounced + persistente (no muestra/oculta en cada tecla)
  let _ppBuscarTimer = null;
  function ppBuscar() {
    if (_ppBuscarTimer) clearTimeout(_ppBuscarTimer);
    _ppBuscarTimer = setTimeout(_ppBuscarRender, 180);
  }
  function _ppBuscarRender() {
    const raw = ($('ppBuscar').value || '').trim();
    const resBox = $('ppBuscarRes');
    if (!resBox) return;
    if (!raw) { resBox.style.display = 'none'; resBox.innerHTML = ''; return; }
    const qn = _norm(raw);
    const palabras = qn.split(/\s+/).filter(Boolean);
    const canonicos = (S.productos || []).filter(p => {
      const f = parseFloat(p.factorConversion);
      return !p.factorConversion || f === 1;
    });
    const scored = canonicos.map(p => {
      const haystack = _norm((p.descripcion || '') + ' ' + (p.codigoBarra || '') + ' ' + (p.skuBase || p.idProducto || '') + ' ' + (p.marca || ''));
      let s = 0, ok = true;
      palabras.forEach(w => { if (haystack.indexOf(w) >= 0) s++; else ok = false; });
      return { p, score: s, ok };
    }).filter(x => x.ok).sort((a, b) => b.score - a.score).slice(0, 10);
    // Mantener resBox VISIBLE (no togglear display) — solo cambiar contenido para evitar reflow visible
    resBox.style.display = 'block';
    if (!scored.length) {
      resBox.innerHTML = '<div class="pn-result text-slate-500 italic">Sin resultados</div>';
      return;
    }
    resBox.innerHTML = scored.map(({ p }) => {
      const sku = p.skuBase || p.idProducto;
      const cb  = p.codigoBarra || '';
      const safeDesc = (p.descripcion || sku).replace(/'/g, "\\'");
      return `<div class="pn-result" onclick="MOS.ppSeleccionar('${sku}', '${cb}', '${safeDesc}')">
        <div class="text-slate-200 font-medium">${p.descripcion || sku}</div>
        <div class="text-slate-500 text-xs" style="font-family:monospace">SKU ${sku}${cb ? ' · ▌' + cb : ''}</div>
      </div>`;
    }).join('');
  }

  function ppSeleccionar(sku, cb, desc) {
    $('ppSkuBase').value     = sku;
    $('ppCodigoBarra').value = cb;
    $('ppSeleccionado').textContent = `${desc} (SKU ${sku}${cb ? ' · ▌' + cb : ''})`;
    $('ppSeleccionado').classList.remove('hidden');
    $('ppBuscarRes').style.display = 'none';
    $('ppBuscar').value = desc;
  }

  async function guardarProvProducto() {
    const idProveedor = S.provSelId;
    const idPP        = $('ppId').value;
    const skuBase     = $('ppSkuBase').value;
    const codigoBarra = $('ppCodigoBarra').value;
    if (!skuBase) { toast('Selecciona un producto', 'error'); return; }
    const params = {
      idProveedor,
      skuBase,
      codigoBarra,
      descripcion: ($('ppSeleccionado').textContent || '').split(' (')[0],
      precioReferencia: parseFloat($('ppPrecio').value) || 0,
      minimoCompra:     parseFloat($('ppMinimo').value) || 0,
      diasEntrega:      parseInt($('ppDiasEntrega').value) || 0,
      unidadesPorBulto: parseInt($('ppUnidadesBulto')?.value) || 1,
      notas:            $('ppNotas').value
    };

    // OPTIMISTIC: actualizar cache local + cerrar modal de inmediato
    S.provProductos = S.provProductos || {};
    if (!S.provProductos[idProveedor]) S.provProductos[idProveedor] = [];
    if (idPP) {
      const idx = S.provProductos[idProveedor].findIndex(x => x.idPP === idPP);
      if (idx >= 0) Object.assign(S.provProductos[idProveedor][idx], params, { idPP });
    } else {
      const tmpId = 'PP_TMP_' + Date.now();
      S.provProductos[idProveedor].push(Object.assign({ idPP: tmpId, _tmp: true }, params));
    }
    closeModal('modalProvProducto');
    toast(idPP ? 'Cotización actualizada ✓' : 'Cotización agregada ✓', 'ok');
    _renderProvProductos();

    // Sync en background
    try {
      if (idPP) {
        await API.post('actualizarProductoProveedor', Object.assign({ idPP }, params));
      } else {
        await API.post('agregarProductoProveedor', params);
        // Refrescar para obtener idPP real del servidor
        const lista = await API.get('getProveedorProductos', { idProveedor });
        const items = Array.isArray(lista) ? lista : (lista && lista.data) || [];
        S.provProductos[idProveedor] = items;
        _renderProvProductos();
      }
    } catch(e) {
      toast('Error de sincronización: ' + e.message, 'error');
      // Revertir: re-fetch
      try {
        const lista = await API.get('getProveedorProductos', { idProveedor });
        const items = Array.isArray(lista) ? lista : (lista && lista.data) || [];
        S.provProductos[idProveedor] = items;
        _renderProvProductos();
      } catch(_){}
    }
  }

  // Eliminar desde el botón 🗑️ de cada card (sin abrir modal)
  async function eliminarProvProductoRapido(idPP) {
    if (!idPP) return;
    if (!await _modalConfirm('¿Eliminar este producto del catálogo del proveedor?', { danger: true, titulo: 'Eliminar del catálogo', okText: 'Eliminar' })) return;
    const idProveedor = S.provSelId;
    // OPTIMISTIC
    if (S.provProductos && S.provProductos[idProveedor]) {
      S.provProductos[idProveedor] = S.provProductos[idProveedor].filter(x => x.idPP !== idPP);
    }
    _renderProvProductos();
    toast('Eliminado', 'ok');
    try {
      await API.post('eliminarProductoProveedor', { idPP });
    } catch(e) { toast('Error de sincronización: ' + e.message, 'error'); }
  }

  // Jalar productos del proveedor desde el histórico de guías de WH
  // [v2.43.592 · pv2] jalarProductosProveedor ELIMINADA (UI v1 rehecha — módulo Proveedores v2)


  async function eliminarProvProducto() {
    const idPP = $('ppId').value;
    if (!idPP) return;
    if (!await _modalConfirm('¿Eliminar esta cotización?', { danger: true, titulo: 'Eliminar cotización', okText: 'Eliminar' })) return;
    const idProveedor = S.provSelId;

    // OPTIMISTIC
    if (S.provProductos && S.provProductos[idProveedor]) {
      S.provProductos[idProveedor] = S.provProductos[idProveedor].filter(x => x.idPP !== idPP);
    }
    closeModal('modalProvProducto');
    toast('Eliminada', 'ok');
    _renderProvProductos();

    try {
      await API.post('eliminarProductoProveedor', { idPP });
    } catch(e) { toast('Error de sincronización: ' + e.message, 'error'); }
  }

  // ============================================================
  // ── PROMOCIONES (vista completa, no modal) ────────────────────
  // ============================================================
  const _promoState = { lista: [], editando: null, comboItems: [] };

  // Helper: stepper +/- para inputs numéricos
  function numStep(id, delta, step) {
    const el = $(id);
    if (!el) return;
    const stp = step || 1;
    const cur = parseFloat(el.value) || 0;
    let nuevo = cur + (delta * stp);
    if (nuevo < 0) nuevo = 0;
    // Redondear según el step para evitar errores de floating point
    if (stp < 1) nuevo = Math.round(nuevo * 100) / 100;
    el.value = nuevo;
    el.dispatchEvent(new Event('input', { bubbles: true }));
  }

  const PROMO_CACHE_KEY = 'mos_promo_cache';
  function _promoLoadCache() {
    try {
      const raw = localStorage.getItem(PROMO_CACHE_KEY);
      if (!raw) return null;
      const parsed = JSON.parse(raw);
      if (Date.now() - (parsed.ts || 0) > 86400000) return null; // 24h
      return parsed.data;
    } catch { return null; }
  }
  function _promoSaveCache(data) {
    try { localStorage.setItem(PROMO_CACHE_KEY, JSON.stringify({ ts: Date.now(), data })); } catch {}
  }

  async function loadPromociones() {
    // [666] la vista #view-promociones ya no existe: esto solo refresca datos.
    // Render cache primero (instantáneo) — usa cache si existe, sino lista actual del estado
    const cached = _promoLoadCache();
    if (cached) {
      _promoState.lista = cached;
    }
    // Render SIEMPRE al entrar a la vista (incluso si lista ya tenía data del init startup)
    _renderPromoLista();
    // Fetch fresco
    _promoState.lastError = null;
    try {
      const lista = await API.get('getPromociones', {});
      const fresh = Array.isArray(lista) ? lista : (lista && lista.data) || [];
      console.log('[loadPromociones] Supabase:', fresh.length, 'promociones');
      _promoState.lista = fresh;
      _promoState.lastFetch = Date.now();
      _promoSaveCache(fresh);
      _renderPromoLista();  // SIEMPRE re-renderizar después del fetch
    } catch(e) {
      console.error('[loadPromociones] error API:', e);
      _promoState.lastError = e && e.message ? e.message : String(e);
      toast('Error cargando promociones: ' + _promoState.lastError, 'error');
      if (!cached) _promoState.lista = [];
      _renderPromoLista();
    }
  }

  // Forzar refetch limpiando cache local
  function _promoForzarRefresh() {
    try { localStorage.removeItem(PROMO_CACHE_KEY); } catch {}
    _promoState.lista = [];
    toast('Cache limpiado, recargando…', 'info');
    loadPromociones();
  }

  // Refresh silencioso periódico
  let _promoRefreshTimer = null;

  // Compat: si alguien llama el viejo método, redirige a nav

  // [666] la vista aparte murió: pintar la lista = repintar el overlay único.
  function _renderPromoLista() { if (document.getElementById('promoCentro')) _pcPinta(); }

  // Toggle inline: activar/desactivar promoción sin abrir form (optimista)
  async function promoToggleActiva(idRef) {
    const p = _promoState.lista.find(x => (x.idPromo === idRef) || (x.skuBase === idRef));
    if (!p) return;
    const nuevoEstado = !p.activa;

    // OPTIMISTIC: cambiar en cache local + re-render
    p.activa = nuevoEstado;
    _promoSaveCache(_promoState.lista);
    _renderPromoLista();
    toast(nuevoEstado ? 'Promoción activada ✓' : 'Promoción desactivada', 'ok');

    // Sync en background
    try {
      await API.post('actualizarPromocion', {
        idPromo: p.idPromo,
        skuBase: p.skuBase,
        activa: nuevoEstado
      });
    } catch(e) {
      // Revertir
      p.activa = !nuevoEstado;
      _promoSaveCache(_promoState.lista);
      _renderPromoLista();
      toast('Error: ' + e.message, 'error');
    }
  }

  function _hoyISO() {
    const d = new Date();
    return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
  }

  // ════════════════════════════════════════════════════════════════
  // [666] FORM DE PROMOCIÓN — 3 caminos: sugerencia aceptada · manual guiado
  //   por estrategia (paso cero) · manual libre. Con vigencia por fechas + horario,
  //   panel de margen en vivo y guarda la jugada usada (mos.promociones.estrategia).
  // ════════════════════════════════════════════════════════════════
  function promoPintaEstrategias() {
    const g = $('promoEstrGrid');
    if (!g) return;
    const cur = _promoState.estrategia || '';
    g.innerHTML = PROMO_JUGADAS.filter(j => !j.guia).map(j => `
      <button type="button" class="promo-estr ${cur === j.k ? 'on' : ''}" onclick="MOS.promoSetEstrategia('${j.k}')">
        <span class="pe-ico">${j.ico}</span>
        <span class="pe-nom">${j.nom}</span>
        <span class="pe-cua">${j.cuando}</span>
      </button>`).join('')
      + `<button type="button" class="promo-estr ${cur === '' ? 'on' : ''}" onclick="MOS.promoSetEstrategia('')">
        <span class="pe-ico">✏️</span><span class="pe-nom">Libre</span>
        <span class="pe-cua">Arma la promo desde cero, sin plantilla.</span></button>`;
    const chip = $('promoEstrChip');
    if (chip) {
      const j = _PJ(cur);
      chip.innerHTML = j ? `<span class="pc-chip" style="background:rgba(99,102,241,.14);color:#a5b4fc;border-color:rgba(99,102,241,.4)">${j.ico} ${j.nom}</span>
        <button type="button" class="pc-mini" style="margin-left:6px" onclick="MOS.promoVerJugadas()">cambiar</button>` : '';
    }
  }
  function promoVerJugadas() {
    const g = $('promoEstrGrid');
    if (g) g.classList.remove('hidden');
    promoPintaEstrategias();
  }

  // Elegir jugada = pre-configurar el form para esa jugada
  function promoSetEstrategia(k) {
    _promoState.estrategia = k || '';
    const j = _PJ(k);
    const g = $('promoEstrGrid');
    if (g && k !== null) g.classList.add('hidden');
    promoPintaEstrategias();
    if (j && j.tipo) {
      const radio = document.querySelector('input[name="promoTipo"][value="' + j.tipo + '"]');
      if (radio) { radio.checked = true; promoSetTipo(j.tipo); }
      if (j.tipo === 'GRUPO') {
        promoSetModo('TOTAL');
        const cm = $('promoCantMin'); if (cm) cm.value = j.cant || 2;
      } else if (j.cant) {
        const cm = $('promoCantMin'); if (cm) cm.value = j.cant;
      }
    }
    if (j && j.hora) promoPresetHora('custom', j.hora[0], j.hora[1]);
    // sugerencia de descuento según el margen del producto ya elegido
    promoSugerirValor();
    promoRecalcMargen();
    promoActualizarEjemplo();
  }

  function _promoProdSel() {
    const sku = ($('promoSkuBase') || {}).value || '';
    if (!sku) return null;
    return (S.productos || []).find(pr => (pr.skuBase || pr.idProducto) === sku) || null;
  }
  // .90 / .50 hacia abajo (mismo criterio que mos._promo_psico del SQL 665)
  function _promoPsico(x) {
    const v = +x || 0;
    if (v <= 0.60) return 0.50;
    const f = Math.floor(v), d = v - f;
    return Math.max(0.50, f + (d >= 0.70 ? 0.90 : (d >= 0.40 ? 0.50 : -0.10)));
  }

  // Descuento sugerido según margen real del producto y la jugada elegida
  function promoSugerirValor() {
    const p = _promoProdSel();
    if (!p) return;
    const tipo = document.querySelector('input[name="promoTipo"]:checked')?.value;
    const pv = parseFloat(p.precioVenta) || 0, pc = parseFloat(p.precioCosto) || 0;
    if (pv <= 0) return;
    const mg = (pc > 0) ? ((pv - pc) / pv) * 100 : null;
    const k = _promoState.estrategia || '';
    let pct;
    if (k === 'escalera' || k === 'remate') pct = mg != null ? Math.min(45, Math.max(20, Math.floor(mg))) : 20;
    else if (k === 'sustitutos')            pct = 15;
    else                                    pct = mg != null ? Math.min(30, Math.max(10, Math.floor(mg) - 12)) : 10;
    const val = $('promoValor');
    if (!val || (val.value && parseFloat(val.value) > 0)) return;   // no pisar lo que el dueño ya escribió
    if (tipo === 'PORCENTAJE') val.value = pct;
    else if (tipo === 'GRUPO') {
      const n = parseFloat(($('promoCantMin') || {}).value) || 2;
      const total = _promoPsico(pv * (n - 1) + pv * (1 - pct / 100));
      val.value = _money(total).toFixed(2);
    }
  }

  // ════════════════════════════════════════════════════════════════
  // [667] EL PISO — nunca poner el % a ciegas. Panel SIEMPRE visible junto al
  //   campo: costo · precio actual · margen actual; y EN VIVO al tipear:
  //   precio resultante → margen resultante con semáforo + piso y % máximo.
  //   Sin costo cargado → aviso ámbar + carga rápida del costo ahí mismo.
  // ════════════════════════════════════════════════════════════════
  const _PROMO_MG_MIN = 12;   // margen mínimo sano (misma regla que el radar del SQL 665)

  function _promoSemaforo(mg, perdida) {
    if (perdida) return { col: '#f87171', ico: '🔴', txt: 'PÉRDIDA' };
    if (mg == null) return { col: '#94a3b8', ico: '⚪', txt: 'sin dato' };
    if (mg >= 20) return { col: '#34d399', ico: '🟢', txt: 'sano' };
    if (mg >= _PROMO_MG_MIN) return { col: '#fbbf24', ico: '🟡', txt: 'fino' };
    if (mg > 0) return { col: '#fb923c', ico: '🟠', txt: 'muy fino' };
    return { col: '#f87171', ico: '🔴', txt: 'PÉRDIDA' };
  }

  // el % que todavía respeta el margen mínimo (piso = costo · 1.12)
  function _promoPctMax(pv, pc) {
    if (!(pv > 0) || !(pc > 0)) return null;
    const pisoSano = pc * (1 + _PROMO_MG_MIN / 100);
    if (pisoSano >= pv) return 0;
    return Math.floor((1 - pisoSano / pv) * 100);
  }

  function promoPisoPinta() {
    const box = $('promoPisoPanel');
    if (!box) return;
    const tipo = document.querySelector('input[name="promoTipo"]:checked')?.value || 'GRUPO';
    if (tipo === 'COMBO') { box.innerHTML = ''; box.classList.add('hidden'); return; }
    box.classList.remove('hidden');

    const p = _promoProdSel();
    if (!p) {
      box.innerHTML = `<div class="promo-piso promo-piso-vacio">🧮 Elige el producto y acá te muestro su costo, tu margen de hoy y hasta dónde puedes bajar sin perder plata.</div>`;
      return;
    }
    const pv = parseFloat(p.precioVenta) || 0;
    const pc = parseFloat(p.precioCosto) || 0;
    const sku = p.skuBase || p.idProducto || '';
    const mgHoy = (pv > 0 && pc > 0) ? ((pv - pc) / pv) * 100 : null;
    const n = Math.max(1, parseFloat(($('promoCantMin') || {}).value) || 1);
    const val = parseFloat(($('promoValor') || {}).value) || 0;

    // precio unitario que resulta de lo tipeado
    let unit = 0;
    if (tipo === 'PORCENTAJE') unit = pv > 0 ? pv * (1 - val / 100) : 0;
    else {
      const esTotal = $('promoModoTotal')?.classList.contains('active');
      unit = esTotal ? (n > 0 ? val / n : 0) : val;
    }
    const mgRes = (unit > 0 && pc > 0) ? ((unit - pc) / unit) * 100 : null;
    const mgSol = (unit > 0 && pc > 0) ? _money(unit - pc) : null;
    const perdida = pc > 0 && unit > 0 && unit < pc;
    const sem = _promoSemaforo(mgRes, perdida);
    const pctMax = _promoPctMax(pv, pc);
    const pctActual = pv > 0 && unit > 0 ? Math.max(0, (1 - unit / pv) * 100) : 0;

    const filas = `<div class="pp-grid">
      <div class="pp-c"><span>tu costo</span><b>${pc > 0 ? _S(pc) : '—'}</b></div>
      <div class="pp-c"><span>precio actual</span><b>${_S(pv)}</b></div>
      <div class="pp-c"><span>margen hoy</span><b style="color:${mgHoy == null ? '#94a3b8' : (mgHoy >= 20 ? '#34d399' : '#fbbf24')}">${mgHoy == null ? '—' : mgHoy.toFixed(1) + '%'}</b></div>
    </div>`;

    const slider = (tipo === 'PORCENTAJE')
      ? `<div class="pp-slider">
           <input id="promoPctSlider" type="range" min="0" max="50" step="1" value="${Math.round(Math.min(50, val || 0))}"
             oninput="MOS.promoPctSlider(this.value)" aria-label="Porcentaje de descuento">
           <div class="pp-slider-lbl"><span>0%</span><span>${pctMax != null ? 'máx sano ' + pctMax + '%' : ''}</span><span>50%</span></div>
         </div>` : '';

    const vivo = (unit > 0)
      ? `<div class="pp-vivo" style="--sem:${sem.col}">
           <div class="pp-vivo-l"><span>c/u sale</span><b>${_S(unit)}</b></div>
           <span class="pp-flecha">→</span>
           <div class="pp-vivo-l"><span>te queda</span><b style="color:${sem.col}">${mgRes == null ? 'sin costo' : mgRes.toFixed(1) + '% · ' + _S(mgSol)}</b></div>
           <span class="pp-sem" style="background:${sem.col}22;color:${sem.col};border-color:${sem.col}66">${sem.ico} ${sem.txt}</span>
         </div>`
      : `<div class="pp-vivo pp-vivo-off">Escribe el valor y acá aparece cuánto te queda por unidad.</div>`;

    const piso = pc > 0
      ? `<div class="pp-piso">🧱 piso: ${_S(pc)} (tu costo) · % máximo recomendado: <b style="color:#fbbf24">${pctMax != null ? pctMax + '%' : '—'}</b> <span style="color:#64748b">(deja ${_PROMO_MG_MIN}% de margen)</span>${pctActual > 0 ? ` · vas en <b style="color:${sem.col}">${pctActual.toFixed(0)}%</b>` : ''}</div>`
      : `<div class="pp-sincosto">
           <div>⚠ sin costo cargado: vas a ciegas. No puedo decirte dónde está tu piso.</div>
           <div id="promoCostoRapido" class="hidden" style="margin-top:7px;display:flex;gap:6px;align-items:center">
             <input id="promoCostoInput" type="number" step="0.01" min="0" inputmode="decimal" class="inp" style="flex:1;padding:6px 9px;font-size:12px" placeholder="costo con IGV">
             <button type="button" class="pc-mini pc-mini-ok" onclick="MOS.promoGuardarCostoRapido('${_escAttrJs(sku)}')">Guardar</button>
           </div>
           <button type="button" class="pc-mini" style="margin-top:7px" onclick="MOS.promoAbrirCargarCosto()">💲 Cargar el costo ahora</button>
         </div>`;

    box.innerHTML = `<div class="promo-piso ${perdida ? 'bad' : ''}">
      <div class="pp-h">🧮 Tu piso y tu margen <span>· ${_escapeHtml(p.descripcion || sku)}</span></div>
      ${filas}${slider}${vivo}${piso}
    </div>`;
  }

  // slider 0-50% sincronizado con el input de %
  function promoPctSlider(v) {
    const el = $('promoValor');
    if (!el) return;
    el.value = Math.max(0, parseInt(v, 10) || 0);
    promoActualizarEjemplo();
    promoRecalcMargen();
  }

  function promoAbrirCargarCosto() {
    $('promoCostoRapido')?.classList.remove('hidden');
    setTimeout(() => { try { $('promoCostoInput')?.focus(); } catch (_) {} }, 30);
  }

  async function promoGuardarCostoRapido(sku) {
    const costo = parseFloat(($('promoCostoInput') || {}).value);
    if (!costo || costo <= 0) { toast('Escribe un costo válido', 'error'); return; }
    const prod = _pcProd(sku);
    const previo = prod ? prod.precioCosto : null;
    if (prod) prod.precioCosto = costo;   // optimista: el panel ya deja de estar a ciegas
    promoPisoPinta(); promoRecalcMargen();
    try {
      await API.post('actualizarCostoPorSku', { sku, precioCosto: costo });
      toast('Costo cargado ✓ ahora sí ves tu piso', 'ok');
      try { _opsBeep && _opsBeep('ok'); } catch (_) {}
    } catch (e) {
      if (prod) prod.precioCosto = previo;
      promoPisoPinta(); promoRecalcMargen();
      toast('No se pudo guardar el costo: ' + e.message, 'error');
    }
  }

  // Panel de margen en vivo: precio normal → precio promo → margen % y en S/
  function promoRecalcMargen() {
    promoPisoPinta();
    const box = $('promoMargenBox');
    if (!box) return;
    const tipo = document.querySelector('input[name="promoTipo"]:checked')?.value;
    const p = _promoProdSel();
    const pintar = (html) => { box.innerHTML = html; };
    if (tipo === 'COMBO') {
      const total = parseFloat(($('promoComboPrecio') || {}).value) || 0;
      let sumaPv = 0, sumaPc = 0, faltaCosto = false;
      (_promoState.comboItems || []).forEach(it => {
        const pr = (S.productos || []).find(x => (x.skuBase || x.idProducto) === it.skuBase);
        const c = parseFloat(it.cantidad) || 1;
        if (!pr) { faltaCosto = true; return; }
        sumaPv += (parseFloat(pr.precioVenta) || 0) * c;
        const pc = parseFloat(pr.precioCosto) || 0;
        if (pc > 0) sumaPc += pc * c; else faltaCosto = true;
      });
      if (!total || !sumaPv) { pintar(''); return; }
      const mg = (!faltaCosto && sumaPc > 0) ? ((total - sumaPc) / total) * 100 : null;
      pintar(_promoMargenHtml(sumaPv, total, mg, (!faltaCosto && sumaPc > 0) ? _money(total - sumaPc) : null, total < sumaPc && !faltaCosto, 'suelto', 'combo'));
      return;
    }
    if (!p) { pintar(''); return; }
    const pv = parseFloat(p.precioVenta) || 0, pc = parseFloat(p.precioCosto) || 0;
    const n  = Math.max(1, parseFloat(($('promoCantMin') || {}).value) || 1);
    const val = parseFloat(($('promoValor') || {}).value) || 0;
    if (!pv || !val) { pintar(''); return; }
    let totalPromo, totalNormal, unidades;
    if (tipo === 'PORCENTAJE') { unidades = 1; totalNormal = pv; totalPromo = pv * (1 - val / 100); }
    else {
      unidades = n;
      totalNormal = pv * n;
      const esTotal = $('promoModoTotal')?.classList.contains('active');
      totalPromo = esTotal ? val : val * n;
    }
    const costoTot = pc > 0 ? pc * unidades : 0;
    const mg = costoTot > 0 ? ((totalPromo - costoTot) / totalPromo) * 100 : null;
    pintar(_promoMargenHtml(totalNormal, totalPromo, mg, costoTot > 0 ? _money(totalPromo - costoTot) : null,
      costoTot > 0 && totalPromo < costoTot, unidades > 1 ? ('x' + unidades) : 'unidad', tipo === 'PORCENTAJE' ? 'unidad' : 'pack'));
  }

  function _promoMargenHtml(normal, promo, mgPct, mgSoles, perdida, escala, modo) {
    const dto = normal > 0 ? Math.max(0, (1 - promo / normal) * 100) : 0;
    const col = perdida ? '#f87171' : (mgPct == null ? '#94a3b8' : (mgPct >= 20 ? '#34d399' : (mgPct >= 10 ? '#fbbf24' : '#fb923c')));
    const txt = perdida ? '⚠ VENDE A PÉRDIDA'
      : (mgPct == null ? 'margen no verificable (producto sin costo cargado)'
        : `margen ${mgPct.toFixed(1)}% · S/ ${_money(mgSoles).toFixed(2)}`);
    return `<div class="promo-mg ${perdida ? 'bad' : ''}">
      <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap">
        <div><div class="pc-precio-lbl">normal ${escala}</div><div class="pc-precio-old">S/ ${_money(normal).toFixed(2)}</div></div>
        <div style="color:#475569">→</div>
        <div><div class="pc-precio-lbl">${modo === 'combo' ? 'combo' : (modo === 'pack' ? 'pack' : 'promo')}</div>
             <div class="pc-precio-new">S/ ${_money(promo).toFixed(2)}</div></div>
        <div style="flex:1;text-align:right">
          <span class="pc-chip" style="background:rgba(167,139,250,.14);color:#c4b5fd;border-color:rgba(167,139,250,.4)">−${dto.toFixed(0)}%</span>
          <div style="margin-top:4px"><span class="pc-chip" style="background:${col}1f;color:${col};border-color:${col}55">${txt}</span></div>
        </div>
      </div>
      ${perdida ? '<div style="font-size:10.5px;color:#fca5a5;margin-top:6px">Estás vendiendo por debajo de tu costo. Si es un remate a propósito, tendrás que confirmarlo dos veces.</div>' : ''}
    </div>`;
  }

  // ── Vigencia: presets ────────────────────────────────────────────
  function promoPresetVig(dias) {
    const d = new Date();
    const desde = _hoyISO();
    const h = new Date(d.getTime() + (dias * 86400000));
    const hasta = h.getFullYear() + '-' + String(h.getMonth() + 1).padStart(2, '0') + '-' + String(h.getDate()).padStart(2, '0');
    if ($('promoFDesde')) $('promoFDesde').value = desde;
    if ($('promoFHasta')) $('promoFHasta').value = hasta;
    document.querySelectorAll('#promoVigPresets .promo-modo-btn').forEach(b => b.classList.toggle('active', +b.dataset.d === dias));
  }

  // ── Horario: presets (null = todo el día) ────────────────────────
  function promoPresetHora(k, hd, hh) {
    const dd = $('promoHDesde'), hhEl = $('promoHHasta'), box = $('promoHoraCustom');
    const set = (a, b) => { if (dd) dd.value = a || ''; if (hhEl) hhEl.value = b || ''; };
    if (k === 'todo')        set('', '');
    else if (k === 'manana') set('06:00', '12:00');
    else if (k === 'tarde')  set('14:00', '18:00');
    else                     set(hd || (dd && dd.value) || '14:00', hh || (hhEl && hhEl.value) || '18:00');
    if (box) box.classList.toggle('hidden', k === 'todo');
    document.querySelectorAll('#promoHoraPresets .promo-modo-btn').forEach(b => b.classList.toggle('active', b.dataset.h === k));
    _promoState.horaPreset = k;
  }

  // ── Abrir el form (3 caminos) ────────────────────────────────────
  function promoAbrirNueva(estrategia, sug) {
    promoNuevoForm();
    _promoState.sugRef = sug || null;
    _promoState.estrategia = estrategia || '';
    const g = $('promoEstrGrid');
    if (g) g.classList.toggle('hidden', !!estrategia || !!sug);
    promoPintaEstrategias();
    if (estrategia) promoSetEstrategia(estrategia);
    if (sug) promoPrefill(sug);
    else promoRecalcMargen();
  }

  // Precargar el form desde una sugerencia del radar (el dueño ajusta y confirma)
  function promoPrefill(s) {
    const radio = document.querySelector('input[name="promoTipo"][value="' + s.tipo + '"]');
    if (radio) { radio.checked = true; promoSetTipo(s.tipo); }
    if (s.tipo === 'COMBO') {
      _promoState.comboItems = (s.items || []).map(i => ({ skuBase: i.skuBase, descripcion: i.descripcion, cantidad: i.cantidad || 1 }));
      _renderPromoComboItems();
      if ($('promoComboPrecio')) $('promoComboPrecio').value = _money(s.precioSugerido).toFixed(2);
    } else {
      if ($('promoSkuBase')) $('promoSkuBase').value = s.skuBase || '';
      if ($('promoSeleccionadoNombre')) $('promoSeleccionadoNombre').textContent = `${s.descripcion} (${s.skuBase})`;
      $('promoSeleccionado')?.classList.remove('hidden');
      if ($('promoBuscar')) $('promoBuscar').value = s.descripcion || '';
      if ($('promoCantMin')) $('promoCantMin').value = s.cantMin || 1;
      if (s.tipo === 'GRUPO') { promoSetModo('TOTAL'); if ($('promoValor')) $('promoValor').value = _money(s.precioSugerido).toFixed(2); }
      else { promoSetModo('UNITARIO'); if ($('promoValor')) $('promoValor').value = s.valorPromo; }
    }
    if ($('promoDesc')) $('promoDesc').value = s.descripcionSugerida || '';
    promoPresetVig(s.regla === 'REMATE' ? 14 : 30);
    if (s.horaDesde && s.horaHasta) promoPresetHora('custom', s.horaDesde, s.horaHasta);
    else promoPresetHora('todo');
    const nota = $('promoSugNota');
    if (nota) {
      nota.classList.remove('hidden');
      nota.innerHTML = `<div style="font-size:10.5px;color:#a5b4fc;font-weight:700;margin-bottom:3px">${s.emoji} ${s.etiqueta} · por qué esta jugada</div>
        <div style="font-size:11px;color:#94a3b8;line-height:1.5">${_escapeHtml(s.porqueDetalle || s.porque || '')}</div>`;
    }
    promoActualizarEjemplo();
    promoRecalcMargen();
  }

  function promoNuevoForm() {
    _promoState.editando = null;
    _promoState.comboItems = [];
    // Abrir modal flotante
    openModal('modalPromoEdit');
    $('promoBtnEliminar').classList.add('hidden');
    $('promoIdEdit').value = '';
    $('promoBuscar').value = '';
    $('promoSkuBase').value = '';
    $('promoBuscarRes').style.display = 'none';
    $('promoBuscarRes').innerHTML = '';
    $('promoSeleccionado').classList.add('hidden');
    $('promoComboBuscar').value = '';
    $('promoComboRes').style.display = 'none';
    $('promoComboItems').innerHTML = '';
    document.querySelector('input[name="promoTipo"][value="GRUPO"]').checked = true;
    promoSetTipo('GRUPO');
    $('promoCantMin').value = '';
    $('promoValor').value = '';
    const cp = $('promoComboPrecio'); if (cp) cp.value = '';
    $('promoDesc').value = '';
    // Vigencia por defecto: hoy
    $('promoFDesde').value = _hoyISO();
    $('promoFHasta').value = '';
    $('promoTogActiva').classList.add('on');
    $('promoError').style.display = 'none';
    // [666] campos nuevos: jugada, horario y notas de la sugerencia
    _promoState.estrategia = '';
    _promoState.sugRef = null;
    $('promoSugNota')?.classList.add('hidden');
    const mb = $('promoMargenBox'); if (mb) mb.innerHTML = '';
    promoPresetHora('todo');
    promoPresetVig(30);
    promoPintaEstrategias();
    promoPisoPinta();   // [667] panel del piso visible desde el primer segundo
  }

  function promoEditar(idRef) {
    const p = _promoState.lista.find(x => (x.idPromo === idRef) || (x.skuBase === idRef));
    if (!p) return;
    _promoState.editando = p.idPromo || p.skuBase;
    promoNuevoForm();
    $('promoBtnEliminar').classList.remove('hidden');
    $('promoIdEdit').value = p.idPromo || p.skuBase;
    document.querySelector('input[name="promoTipo"][value="' + p.tipo + '"]').checked = true;
    promoSetTipo(p.tipo);

    if (p.tipo === 'COMBO') {
      _promoState.comboItems = (p.items || []).slice();
      _renderPromoComboItems();
      $('promoComboPrecio').value = p.valorPromo || 0;
    } else {
      $('promoSkuBase').value = p.skuBase;
      const prod = (S.productos || []).find(pr => (pr.skuBase || pr.idProducto) === p.skuBase);
      $('promoSeleccionadoNombre').textContent = prod ? `${prod.descripcion} (${p.skuBase})` : p.skuBase;
      $('promoSeleccionado').classList.remove('hidden');
      $('promoCantMin').value = p.cantMin;
      // Modo: si TOTAL, mostrar cantMin × valorPromo (lo que el usuario originalmente escribió)
      const modo = String(p.valorModo || 'UNITARIO').toUpperCase();
      if (p.tipo === 'GRUPO' && modo === 'TOTAL') {
        $('promoValor').value = (p.cantMin * p.valorPromo).toFixed(2);
        promoSetModo('TOTAL');
      } else {
        $('promoValor').value = p.valorPromo;
        if (p.tipo === 'GRUPO') promoSetModo('UNITARIO');
      }
    }
    $('promoDesc').value    = p.descripcion || '';
    $('promoFDesde').value  = p.vigenciaDesde ? String(p.vigenciaDesde).substring(0, 10) : '';
    $('promoFHasta').value  = p.vigenciaHasta ? String(p.vigenciaHasta).substring(0, 10) : '';
    $('promoTogActiva').classList.toggle('on', !!p.activa);
    // [666] jugada guardada + ventana horaria
    _promoState.estrategia = p.estrategia || '';
    promoPintaEstrategias();
    $('promoEstrGrid')?.classList.add('hidden');
    if (p.horaDesde && p.horaHasta) promoPresetHora('custom', p.horaDesde, p.horaHasta);
    else promoPresetHora('todo');
    promoActualizarEjemplo();
    promoRecalcMargen();
  }

  function promoVolverLista() {
    closeModal('modalPromoEdit');
  }

  function promoSetTipo(tipo) {
    const esCombo = tipo === 'COMBO';
    const esGrupo = tipo === 'GRUPO';
    $('promoSeccionUnico').classList.toggle('hidden', esCombo);
    $('promoSeccionCombo').classList.toggle('hidden', !esCombo);
    $('promoSeccionValor').classList.toggle('hidden', esCombo);
    $('promoSeccionPrecioCombo').classList.toggle('hidden', !esCombo);
    // Toggle modo solo visible en GRUPO
    const modoBox = $('promoModoBox');
    if (modoBox) modoBox.style.display = esGrupo ? '' : 'none';
    // Chips rápidos según tipo
    ['GRUPO','PORCENTAJE','COMBO'].forEach(t => {
      const row = $('promoQuick' + t);
      if (row) row.classList.toggle('hidden', t !== tipo);
    });
    if (tipo === 'GRUPO') {
      const modo = $('promoModoUnit')?.classList.contains('active') ? 'UNITARIO' : 'TOTAL';
      $('promoValorLbl').textContent = modo === 'TOTAL' ? 'Precio TOTAL del grupo *' : 'Precio UNITARIO en promo *';
    } else if (tipo === 'PORCENTAJE') {
      $('promoValorLbl').textContent = '% Descuento *';
    }
    promoActualizarEjemplo();
  }

  // Auto-llena descripción y opcionalmente cantidad mínima desde un chip
  function promoQuickFill(label, descripcion, cantMin) {
    const descEl = $('promoDesc');
    if (descEl) descEl.value = descripcion;
    if (typeof cantMin === 'number' && cantMin > 0) {
      const cm = $('promoCantMin');
      if (cm) {
        cm.value = cantMin;
        cm.dispatchEvent(new Event('input', { bubbles: true }));
      }
    }
    promoActualizarEjemplo();
  }

  function promoSetModo(modo) {
    const esTotal = modo === 'TOTAL';
    $('promoModoUnit').classList.toggle('active', !esTotal);
    $('promoModoTotal').classList.toggle('active', esTotal);
    $('promoValorLbl').textContent = esTotal ? 'Precio TOTAL del grupo *' : 'Precio UNITARIO en promo *';
    promoActualizarEjemplo();
  }

  function promoActualizarEjemplo() {
    const tipo = document.querySelector('input[name="promoTipo"]:checked')?.value;
    promoPisoPinta();   // [667] el piso se pinta SIEMPRE, aunque falten datos
    const ej = $('promoEjemplo');
    if (!ej) return;
    if (tipo === 'COMBO') {
      const precio = parseFloat($('promoComboPrecio').value) || 0;
      const items = _promoState.comboItems || [];
      if (!items.length || !precio) { ej.textContent = ''; return; }
      ej.textContent = `Ejemplo: ${items.length} producto${items.length !== 1 ? 's' : ''} juntos = S/${precio.toFixed(2)}`;
      return;
    }
    const cant = parseFloat($('promoCantMin').value) || 0;
    const val  = parseFloat($('promoValor').value) || 0;
    if (!cant || !val) { ej.textContent = ''; return; }
    if (tipo === 'GRUPO') {
      const modoTotal = $('promoModoTotal')?.classList.contains('active');
      const total = modoTotal ? val : (cant * val);
      const unit  = modoTotal ? (cant > 0 ? val / cant : 0) : val;
      ej.textContent = `Ejemplo: lleva ${cant} y paga S/${total.toFixed(2)} en total (S/${unit.toFixed(2)} c/u)`;
    } else {
      ej.textContent = `Ejemplo: comprando ${cant}+ unidades, ${val}% de descuento sobre el subtotal`;
    }
    promoRecalcMargen();   // [666] margen en vivo junto al ejemplo
  }

  // ── COMBO: agregar productos ─────────────────────────────────
  function promoComboBuscar() {
    const raw = ($('promoComboBuscar').value || '').trim();
    const resBox = $('promoComboRes');
    if (!raw) { resBox.style.display = 'none'; resBox.innerHTML = ''; return; }
    const qn = _norm(raw);
    const palabras = qn.split(/\s+/).filter(Boolean);
    const canonicos = (S.productos || []).filter(p => {
      const f = parseFloat(p.factorConversion);
      return !p.factorConversion || f === 1;
    });
    const scored = canonicos.map(p => {
      const haystack = _norm((p.descripcion || '') + ' ' + (p.codigoBarra || '') + ' ' + (p.skuBase || p.idProducto || '') + ' ' + (p.marca || ''));
      let s = 0, ok = true;
      palabras.forEach(w => { if (haystack.indexOf(w) >= 0) s++; else ok = false; });
      return { p, score: s, ok };
    }).filter(x => x.ok).sort((a, b) => b.score - a.score).slice(0, 8);
    if (!scored.length) {
      resBox.innerHTML = '<div class="pn-result text-slate-500 italic">Sin resultados</div>';
      resBox.style.display = 'block';
      return;
    }
    resBox.innerHTML = scored.map(({ p }) => {
      const sku = p.skuBase || p.idProducto;
      const safeDesc = (p.descripcion || sku).replace(/'/g, "\\'");
      return `<div class="pn-result" onclick="MOS.promoComboAgregar('${sku}', '${safeDesc}')">
        <div class="text-slate-200 font-medium">${p.descripcion || sku}</div>
        <div class="text-slate-500 text-xs" style="font-family:monospace">SKU ${sku}</div>
      </div>`;
    }).join('');
    resBox.style.display = 'block';
  }

  function promoComboAgregar(sku, descripcion) {
    const existing = _promoState.comboItems.find(x => x.skuBase === sku);
    if (existing) { existing.cantidad = (parseFloat(existing.cantidad) || 0) + 1; }
    else _promoState.comboItems.push({ skuBase: sku, descripcion, cantidad: 1 });
    _renderPromoComboItems();
    $('promoComboBuscar').value = '';
    $('promoComboRes').style.display = 'none';
    promoActualizarEjemplo();
  }

  function promoComboCerrarRes() {
    $('promoComboRes').style.display = 'none';
  }

  function _renderPromoComboItems() {
    const cont = $('promoComboItems');
    if (!cont) return;
    if (!_promoState.comboItems.length) {
      cont.innerHTML = '<p class="text-xs text-slate-500 italic py-2">Aún no hay productos. Búscalos arriba.</p>';
      return;
    }
    cont.innerHTML = _promoState.comboItems.map((it, i) => `
      <div class="promo-combo-item">
        <span class="desc">${it.descripcion}</span>
        <input class="qty" type="number" min="1" step="1" value="${it.cantidad}" onchange="MOS.promoComboCambiarQty(${i}, this.value)">
        <span class="rm" onclick="MOS.promoComboQuitar(${i})" title="Quitar">×</span>
      </div>
    `).join('');
  }

  function promoComboCambiarQty(idx, val) {
    if (!_promoState.comboItems[idx]) return;
    _promoState.comboItems[idx].cantidad = Math.max(1, parseInt(val) || 1);
  }

  function promoComboQuitar(idx) {
    _promoState.comboItems.splice(idx, 1);
    _renderPromoComboItems();
    promoActualizarEjemplo();
  }

  function promoBuscarBase() {
    const raw = ($('promoBuscar').value || '').trim();
    const resBox = $('promoBuscarRes');
    if (!raw) { resBox.style.display = 'none'; resBox.innerHTML = ''; return; }
    const qn = _norm(raw);
    const palabras = qn.split(/\s+/).filter(Boolean);
    const canonicos = (S.productos || []).filter(p => {
      const f = parseFloat(p.factorConversion);
      return !p.factorConversion || f === 1;
    });
    const scored = canonicos.map(p => {
      const haystack = _norm((p.descripcion || '') + ' ' + (p.codigoBarra || '') + ' ' + (p.skuBase || p.idProducto || '') + ' ' + (p.marca || ''));
      let s = 0, ok = true;
      palabras.forEach(w => { if (haystack.indexOf(w) >= 0) s++; else ok = false; });
      return { p, score: s, ok };
    }).filter(x => x.ok).sort((a, b) => b.score - a.score).slice(0, 10);
    if (!scored.length) {
      resBox.innerHTML = '<div class="pn-result text-slate-500 italic">Sin resultados</div>';
      resBox.style.display = 'block';
      return;
    }
    resBox.innerHTML = scored.map(({ p }) => {
      const sku = p.skuBase || p.idProducto;
      const safeDesc = (p.descripcion || p.idProducto).replace(/'/g, "\\'");
      return `<div class="pn-result" onclick="MOS.promoSeleccionarBase('${sku}', '${safeDesc}')">
        <div class="text-slate-200 font-medium">${p.descripcion || p.idProducto}</div>
        <div class="text-slate-500 text-xs" style="font-family:monospace">SKU ${sku}</div>
      </div>`;
    }).join('');
    resBox.style.display = 'block';
  }

  function promoSeleccionarBase(sku, descripcion) {
    $('promoSkuBase').value = sku;
    $('promoSeleccionadoNombre').textContent = `${descripcion} (${sku})`;
    $('promoSeleccionado').classList.remove('hidden');
    $('promoBuscarRes').style.display = 'none';
    $('promoBuscar').value = descripcion;
    promoSugerirValor();   // [666] descuento sugerido según el margen real
    promoRecalcMargen();
  }

  // [666] ¿el precio propuesto queda bajo el costo del producto (o del combo)?
  function _promoPierdePlata(params) {
    try {
      if (params.tipo === 'COMBO') {
        let costo = 0, ok = false;
        (params.items || []).forEach(it => {
          const pr = (S.productos || []).find(x => (x.skuBase || x.idProducto) === it.skuBase);
          const pc = pr ? (parseFloat(pr.precioCosto) || 0) : 0;
          if (pc > 0) { costo += pc * (parseFloat(it.cantidad) || 1); ok = true; }
        });
        return ok && costo > 0 && (parseFloat(params.valorPromo) || 0) < costo;
      }
      const pr = (S.productos || []).find(x => (x.skuBase || x.idProducto) === params.skuBase);
      if (!pr) return false;
      const pc = parseFloat(pr.precioCosto) || 0, pv = parseFloat(pr.precioVenta) || 0;
      if (pc <= 0) return false;
      const n = Math.max(1, parseFloat(params.cantMin) || 1);
      let unit;
      if (params.tipo === 'PORCENTAJE') unit = pv * (1 - (parseFloat(params.valorPromo) || 0) / 100);
      else unit = (String(params.valorModo).toUpperCase() === 'TOTAL')
                  ? (parseFloat(params.valorPromo) || 0) / n
                  : (parseFloat(params.valorPromo) || 0);
      return unit < pc;
    } catch (_) { return false; }
  }

  async function promoGuardar() {
    const errEl = $('promoError'); errEl.style.display = 'none';
    const tipo = document.querySelector('input[name="promoTipo"]:checked')?.value;
    let params;
    if (tipo === 'COMBO') {
      if (!_promoState.comboItems.length) { errEl.textContent = 'Agrega al menos 1 producto al combo'; errEl.style.display = 'block'; return; }
      const precio = parseFloat($('promoComboPrecio').value) || 0;
      if (precio <= 0) { errEl.textContent = 'Precio del combo inválido'; errEl.style.display = 'block'; return; }
      params = {
        tipo,
        items: _promoState.comboItems.map(it => ({ skuBase: it.skuBase, cantidad: parseInt(it.cantidad) || 1, descripcion: it.descripcion })),
        valorPromo: precio,
        cantMin: 1,
        descripcion:   $('promoDesc').value,
        vigenciaDesde: $('promoFDesde').value,
        vigenciaHasta: $('promoFHasta').value,
        activa:        $('promoTogActiva').classList.contains('on')
      };
    } else {
      const skuBase = $('promoSkuBase').value;
      if (!skuBase) { errEl.textContent = 'Selecciona un producto'; errEl.style.display = 'block'; return; }
      const cantMin = parseFloat($('promoCantMin').value) || 0;
      const valor   = parseFloat($('promoValor').value) || 0;
      if (!cantMin || cantMin < 1) { errEl.textContent = 'Cantidad mínima ≥ 1'; errEl.style.display = 'block'; return; }
      if (valor <= 0) { errEl.textContent = 'Valor inválido'; errEl.style.display = 'block'; return; }
      // Solo GRUPO usa el modo (UNITARIO/TOTAL); PORCENTAJE siempre es directo
      const valorModo = (tipo === 'GRUPO' && $('promoModoTotal')?.classList.contains('active')) ? 'TOTAL' : 'UNITARIO';
      params = {
        skuBase, tipo,
        cantMin, valorPromo: valor, valorModo,
        descripcion:   $('promoDesc').value,
        vigenciaDesde: $('promoFDesde').value,
        vigenciaHasta: $('promoFHasta').value,
        activa:        $('promoTogActiva').classList.contains('on')
      };
    }
    // [666] ventana horaria (null = todo el día) + jugada del playbook
    const _hd = ($('promoHDesde') || {}).value || '';
    const _hh = ($('promoHHasta') || {}).value || '';
    if ((!!_hd) !== (!!_hh)) { errEl.textContent = 'Horario incompleto: define hora de inicio y de fin'; errEl.style.display = 'block'; return; }
    if (_hd && _hd === _hh) { errEl.textContent = 'El horario de inicio y fin no pueden ser iguales'; errEl.style.display = 'block'; return; }
    params.horaDesde = _hd;
    params.horaHasta = _hh;
    if (_promoState.estrategia) params.estrategia = _promoState.estrategia;

    // [666] jamás por debajo del costo sin que el dueño lo confirme dos veces
    if (_promoPierdePlata(params)) {
      const ok = await _modalConfirm('El precio queda POR DEBAJO de tu costo: cada unidad vendida te resta plata. Solo tiene sentido si es un remate a propósito.',
        { danger: true, titulo: '⚠ Vas a vender a pérdida', okText: 'Sí, es un remate' });
      if (!ok) return;
      const ok2 = await _modalConfirm('Confirmación final: la promo se publica al POS a pérdida.',
        { danger: true, titulo: '¿Seguro?', okText: 'Publicar igual' });
      if (!ok2) return;
    }

    const isEdit = !!_promoState.editando;
    if (isEdit) params.idPromo = _promoState.editando;

    // OPTIMISTIC: actualizar lista local + cerrar modal de inmediato
    // Para GRUPO con modo TOTAL, convertir a unitario en local (igual que el server)
    let valorPromoLocal = params.valorPromo || 0;
    if (params.tipo === 'GRUPO' && params.valorModo === 'TOTAL' && params.cantMin > 0 && valorPromoLocal > 0) {
      valorPromoLocal = valorPromoLocal / params.cantMin;
    }
    const tmpId = isEdit ? params.idPromo : ('PROMO_TMP_' + Date.now());
    const localPromo = {
      idPromo:       tmpId,
      skuBase:       params.skuBase || '',
      tipo:          params.tipo,
      cantMin:       params.cantMin || 0,
      valorPromo:    valorPromoLocal,
      valorModo:     params.valorModo || 'UNITARIO',
      items:         params.items || [],
      descripcion:   params.descripcion || '',
      vigenciaDesde: params.vigenciaDesde || '',
      vigenciaHasta: params.vigenciaHasta || '',
      activa:        !!params.activa,
      horaDesde:     params.horaDesde || null,
      horaHasta:     params.horaHasta || null,
      estrategia:    params.estrategia || (_promoState.sugRef && _promoState.sugRef.estrategia) || '',
      actualizado:   new Date().toISOString().slice(0, 16).replace('T', ' '),
      notas:         '',
      _tmp:          !isEdit
    };
    if (isEdit) {
      const idx = _promoState.lista.findIndex(p => p.idPromo === params.idPromo);
      if (idx >= 0) _promoState.lista[idx] = Object.assign({}, _promoState.lista[idx], localPromo);
    } else {
      _promoState.lista.unshift(localPromo);
    }
    _promoSaveCache(_promoState.lista);
    _renderPromoLista();
    promoVolverLista();   // cierra modal
    toast(isEdit ? 'Promoción actualizada ✓' : 'Promoción creada ✓', 'ok');

    // Sync en background
    try {
      const action = isEdit ? 'actualizarPromocion' : 'crearPromocion';
      const res = await API.post(action, params);
      // Server devuelve idPromo real → actualizar el tmp en cache
      if (!isEdit && res && res.idPromo) {
        const item = _promoState.lista.find(p => p.idPromo === tmpId);
        if (item) { item.idPromo = res.idPromo; item._tmp = false; _promoSaveCache(_promoState.lista); }
      }
      // Refresh fresco en background (sin bloquear UI)
      loadPromociones().catch(() => {});
    } catch(e) {
      toast('Error de sincronización: ' + e.message, 'error');
      // Revertir
      if (!isEdit) {
        _promoState.lista = _promoState.lista.filter(p => p.idPromo !== tmpId);
      }
      _promoSaveCache(_promoState.lista);
      _renderPromoLista();
      // Reabrir el modal para que pueda corregir
      if (!isEdit) promoNuevoForm();
    }
  }

  async function promoEliminar() {
    if (!_promoState.editando) return;
    if (!await _modalConfirm('¿Eliminar esta promoción?', { danger: true, titulo: 'Eliminar promoción', okText: 'Eliminar' })) return;
    const idPromo = _promoState.editando;
    // OPTIMISTIC: cerrar modal + remover de lista local
    const backup = _promoState.lista.slice();
    _promoState.lista = _promoState.lista.filter(p => p.idPromo !== idPromo && p.skuBase !== idPromo);
    _promoSaveCache(_promoState.lista);
    _renderPromoLista();
    promoVolverLista();
    toast('Promoción eliminada', 'ok');
    try {
      await API.post('eliminarPromocion', { idPromo, skuBase: idPromo });
      loadPromociones().catch(() => {});
    } catch(e) {
      // Revertir
      _promoState.lista = backup;
      _promoSaveCache(_promoState.lista);
      _renderPromoLista();
      toast('Error de sincronización: ' + e.message, 'error');
    }
  }

