  // [FUNERAL GAS 14-ago] cronReinstalarTrigger y cronEjecutarAhora MURIERON: gobernaban
  // TRIGGERS de Apps Script (setupCierreNocturnoTrigger / cierreNocturnoTodos). El cierre
  // nocturno vive en pg_cron. Se conservan como no-op informativo por si algún acceso viejo
  // (bookmark/atajo) los invoca — jamás vuelven a hablar con GAS.
  async function cronReinstalarTrigger() {
    toast('⏱ El cierre nocturno ya no usa triggers de Apps Script — corre solo en pg_cron (Supabase)', 'info', 5000);
  }
  async function cronEjecutarAhora() {
    toast('⏱ El cierre nocturno corre solo en pg_cron — no hay ejecución manual por GAS', 'info', 5000);
  }

  // ═══════════════════════════════════════════════════════════════════════
  // [RIZ · CAPA 4] MÓDULO ZONA (Reposición Inteligente por Zona) — FRONTEND
  // 100% Supabase (RPCs me.zona_* vía API.zona.*). Gated por flag mos_zona_modulo:
  // loadZona() solo se invoca al navegar a 'zona', y el nav que la abre está oculto
  // si el flag está OFF (default) → con el flag OFF la app es IDÉNTICA a hoy.
  //
  // PLACEHOLDERS Capa 5: la sugerencia IA del card es texto local determinista
  // (la IA real del Edge /functions/ia llega en Capa 5); la impresión 80mm del
  // ticket diario / lista de compras también es Capa 5.
  // ═══════════════════════════════════════════════════════════════════════

  // WebAudio iOS-safe — reusa el patrón _catSfx pero dedicado a Zona (resume en gesto).
  let _zonaAudioCtx = null;
  function _zonaSfx(tipo) {
    try {
      if (!_zonaAudioCtx) _zonaAudioCtx = new (window.AudioContext || window.webkitAudioContext)();
      const ctx = _zonaAudioCtx;
      if (ctx.state === 'suspended') { try { ctx.resume(); } catch(_){} }   // iOS: requiere gesto
      const t = ctx.currentTime;
      function tone(freq, dur, gainVal, opts) {
        const o = ctx.createOscillator(); const g = ctx.createGain();
        o.type = (opts && opts.type) || 'sine';
        o.frequency.setValueAtTime(freq, t + (opts && opts.delay || 0));
        if (opts && opts.glide) o.frequency.exponentialRampToValueAtTime(opts.glide, t + (opts.delay || 0) + dur);
        g.gain.setValueAtTime(gainVal, t + (opts && opts.delay || 0));
        g.gain.exponentialRampToValueAtTime(0.0001, t + (opts && opts.delay || 0) + dur);
        o.connect(g); g.connect(ctx.destination);
        o.start(t + (opts && opts.delay || 0)); o.stop(t + (opts && opts.delay || 0) + dur + 0.01);
      }
      switch (tipo) {
        case 'tick':    tone(1300, .035, .035, { type:'triangle' }); break;
        case 'ok':      tone(660, .08, .06); tone(990, .09, .06, { delay:.08 }); break;
        case 'error':   tone(220, .22, .07, { type:'square', glide:140 }); break;
        case 'pop':     tone(880, .05, .04, { type:'triangle' }); break;
      }
    } catch(_){}
  }
  function _zonaVibrar(patron) { if (_zonaReduce()) return; if (navigator.vibrate) { try { navigator.vibrate(patron); } catch(_){} } }
  // [RIZ UX] ¿el usuario pidió menos movimiento? → no animar ni vibrar.
  function _zonaReduce() {
    try { return !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches); } catch (_) { return false; }
  }
  // [RIZ UX] Ripple táctil sutil en una card/botón de zona (transform/opacity → 60fps).
  function _zonaRipple(ev, host) {
    if (_zonaReduce()) return;
    try {
      const h = host || (ev && ev.currentTarget);
      if (!h) return;
      const rect = h.getBoundingClientRect();
      const size = Math.max(rect.width, rect.height) * 0.65;
      const x = (ev && ev.clientX != null) ? ev.clientX : (rect.left + rect.width / 2);
      const y = (ev && ev.clientY != null) ? ev.clientY : (rect.top + rect.height / 2);
      const r = document.createElement('span');
      r.className = 'zona-ripple';
      r.style.width = r.style.height = size + 'px';
      r.style.left = (x - rect.left - size / 2) + 'px';
      r.style.top  = (y - rect.top  - size / 2) + 'px';
      if (getComputedStyle(h).position === 'static') h.style.position = 'relative';
      h.appendChild(r);
      setTimeout(() => { try { r.remove(); } catch (_) {} }, 620);
    } catch (_) {}
  }
  // [RIZ UX] Count-up de un KPI (de 0 → valor) usando rAF. Respeta reduced-motion (pinta directo).
  function _zonaCountUp(el, target) {
    if (!el) return;
    const end = Number(target);
    if (!isFinite(end)) { el.textContent = (target == null ? '—' : target); return; }
    if (_zonaReduce() || end === 0) { el.textContent = String(end); return; }
    const dur = 620, t0 = (performance && performance.now) ? performance.now() : Date.now();
    const ease = (x) => 1 - Math.pow(1 - x, 3);   // easeOutCubic
    function frame(now) {
      const p = Math.min(1, ((now || Date.now()) - t0) / dur);
      el.textContent = String(Math.round(end * ease(p)));
      if (p < 1) requestAnimationFrame(frame);
      else el.textContent = String(end);
    }
    requestAnimationFrame(frame);
  }

  // Helpers de presentación
  function _zonaNum(v) { const n = Number(v); return isFinite(n) ? n : 0; }

  // [MEJORA 2] Formato de cantidad según unidad/granel del item.
  //  · esGranel → admite decimales y usa la unidad legible (ej. "12.5 kg").
  //  · NO granel → entero + "un" (ej. "12 un").
  // El segundo arg es el item (o {esGranel,unidad}); el tercero opcional oculta el sufijo (solo número).
  const _ZONA_UNI_LBL = { KGM:'kg', GRM:'g', LTR:'L', MLT:'ml', NIU:'un', UND:'un', UN:'un', '':'un' };
  function _zonaUniLbl(item) {
    if (!item) return 'un';
    const u = String(item.unidad || '').toUpperCase().trim();
    if (_ZONA_UNI_LBL[u] != null) return _ZONA_UNI_LBL[u];
    return u ? u.toLowerCase() : 'un';
  }
  // Redondea/formatea un número crudo: granel → hasta 2 decimales sin ceros sobrantes; entero → redondeo.
  function _zonaFmtNumRaw(valor, esGranel) {
    // [522] También los NO-granel pueden tener fracción real (insumos por MILLAR: celofán 3.16).
    // Antes Math.round() los aplastaba a entero y el kardex/stock de zona mentía. Ahora ambos
    // caminos muestran hasta 3 decimales, solo si existen (entero se ve entero).
    const n = _zonaNum(valor);
    const r = Math.round(n * 1000) / 1000;
    return (Math.abs(r % 1) < 1e-9) ? String(Math.round(r)) : String(r);
  }
  // Devuelve "valor unidad" (ej. "12.5 kg" / "12 un"). soloNum=true → solo el número formateado.
  function _zonaFmtCant(valor, item, soloNum) {
    const esGranel = !!(item && item.esGranel);
    const num = _zonaFmtNumRaw(valor, esGranel);
    if (soloNum) return num;
    return num + ' ' + _zonaUniLbl(item);
  }
  // step de input/stepper según granel (0.1 para granel, 1 para unidades enteras).
  function _zonaStepAttr(item) { return (item && item.esGranel) ? '0.1' : '1'; }
  // Parser tolerante del input manual (acepta coma decimal); entero si no es granel; nunca negativo.
  function _zonaParseCant(raw, esGranel) {
    let n = parseFloat(String(raw == null ? '' : raw).replace(',', '.'));
    if (!isFinite(n)) n = 0;
    if (!esGranel) n = Math.round(n);
    else n = Math.round(n * 100) / 100;
    return Math.max(0, n);
  }
  // Clasificación BCG → estilos. clase: 'estrella'|'vaca'|'interro'|'perro'.
  const _ZONA_BCG = {
    estrella: { ico:'⭐', cls:'bcg-estrella', tendLbl:'▲ subiendo', tendCls:'zt-asc' },
    vaca:     { ico:'🐄', cls:'bcg-vaca',     tendLbl:'≈ estable',  tendCls:'zt-est' },
    interro:  { ico:'❓', cls:'bcg-interro',  tendLbl:'▲ subiendo', tendCls:'zt-asc' },
    perro:    { ico:'🐕', cls:'bcg-perro',    tendLbl:'▼ bajando',  tendCls:'zt-desc' }
  };
  // Mapea tendencia cruda ('asc'|'desc'|'est'|'nula') a etiqueta/clase de badge.
  function _zonaTendBadge(tend) {
    switch (String(tend || '').toLowerCase()) {
      case 'asc':  case 'ascendente':  return { lbl:'↑ ASCENDENTE', cls:'zt-asc' };
      case 'desc': case 'descendente': return { lbl:'↓ DESCENDENTE', cls:'zt-desc' };
      case 'nula': case 'cero':        return { lbl:'∅ SIN ROTAR',   cls:'zt-nula' };
      default:                          return { lbl:'≈ ESTABLE',     cls:'zt-est' };
    }
  }
  // Deriva el cuadrante BCG si el backend no lo manda (informativo): crecimiento × volumen.
  function _zonaBCGClase(p) {
    if (p.bcg) return String(p.bcg).toLowerCase();
    const tend = String(p.tendencia || '').toLowerCase();
    const volAlto = !!p._volAlto;   // el panel marca _volAlto vs mediana de la zona
    if (tend === 'nula' || tend === 'cero') return 'perro';
    const sube = (tend === 'asc' || tend === 'ascendente');
    if (sube) return volAlto ? 'estrella' : 'interro';
    if (tend === 'desc' || tend === 'descendente') return volAlto ? 'vaca' : 'perro';
    return volAlto ? 'vaca' : 'interro';   // estable
  }
  // Normaliza un item crudo del backend (me.zona_panel) al shape que consume el render.
  // El backend emite tendencia/bcg en MAYÚSCULAS (CRECIENTE/DECRECIENTE/ESTABLE/NULA ·
  // ESTRELLA/VACA/INTERROGANTE/PERRO) y el vencimiento como objeto {fecha,dias}. El render usa
  // tendencia normalizada (asc/desc/est/nula), clave BCG corta (interro, no interrogante) y
  // diasVencimiento plano. Mapeamos aquí (una sola fuente) en lugar de salpicar el render con ??.
  const _ZONA_TEND_MAP = { CRECIENTE:'asc', DECRECIENTE:'desc', ESTABLE:'est', NULA:'nula',
                           ASCENDENTE:'asc', DESCENDENTE:'desc', CERO:'nula' };
  const _ZONA_BCG_MAP  = { ESTRELLA:'estrella', VACA:'vaca', INTERROGANTE:'interro', PERRO:'perro' };
  function _zonaNormItem(it) {
    if (!it || typeof it !== 'object') return it;
    const p = Object.assign({}, it);
    const tUp = String(p.tendencia || '').toUpperCase();
    p.tendencia = _ZONA_TEND_MAP[tUp] || (p.tendencia != null ? String(p.tendencia).toLowerCase() : 'est');
    const bUp = String(p.bcg || '').toUpperCase();
    p.bcg = _ZONA_BCG_MAP[bUp] || (p.bcg != null ? String(p.bcg).toLowerCase() : '');
    // vencimientoProximo:{fecha,dias} → diasVencimiento plano (lo que lee _zonaVencBadge).
    if (p.vencimientoProximo && p.vencimientoProximo.dias != null) p.diasVencimiento = p.vencimientoProximo.dias;
    // El panel no trae volumen; rotacion (sort/BCG bubbles) = volumen si vino, si no 0. Marcamos _volAlto solo si hay dato.
    p.rotacion = (p.volumen != null) ? _zonaNum(p.volumen) : (p.rotacion != null ? _zonaNum(p.rotacion) : 0);
    // [MEJORA 4] rotacionCero del backend → boolean limpio (acepta bool/'1'/'true'/1).
    if (p.rotacionCero != null) {
      const rc = p.rotacionCero;
      p.rotacionCero = (rc === true || rc === 1 || rc === '1' || String(rc).toLowerCase() === 'true');
    }
    return p;
  }

  // Badge de vencimiento por días restantes (criterio de alertas_operativas).
  function _zonaVencBadge(dias) {
    if (dias == null || !isFinite(Number(dias))) return null;
    const d = Number(dias);
    if (d > 30) return { dot:'ok',   txt:'Vence en ' + d + ' días' };
    if (d >= 8) return { dot:'warn', txt:'Vence en ' + d + ' días' };
    return { dot:'crit', txt:'Vence en ' + d + ' días ⚠' };
  }

  // ── Carga del módulo ──────────────────────────────────────────────────
  async function loadZona(force) {
    // Guard duro: si el flag está OFF, NO cargar nada (defensa extra al gate del nav).
    let on = false;
    try { on = !!(API.zona && API.zona.moduloOn && API.zona.moduloOn()); } catch (_) { on = false; }
    if (!on) {
      const lista = $('zonaLista');
      if (lista) lista.innerHTML = '<div class="text-center py-16 text-slate-500">Módulo no habilitado</div>';
      return;
    }
    // 1) Cargar el selector de zonas (reusa getZonas → array {idZona,nombre,activo})
    try {
      if (!S.zonaList.length) {
        const zs = await API.get('getZonas', {}).catch(() => []);
        S.zonaList = Array.isArray(zs) ? zs.filter(z => z && (z.activo === '1' || z.activo === true || z.activo == null)) : [];
      }
    } catch (_) { S.zonaList = S.zonaList || []; }
    _zonaPoblarSelector();
    if (!S.zonaActual && S.zonaList.length) S.zonaActual = S.zonaList[0].idZona || S.zonaList[0].id || S.zonaList[0].nombre;
    // [891] Hub de puestos: restaurar el puesto ANCLADO (persistido) si sigue existiendo.
    try {
      const _ancla = _zonaAnclaGet();
      if (_ancla && S.zonaList.some(z => (z.idZona || z.id || z.nombre) === _ancla)) S.zonaActual = _ancla;
      _zonaHubActualizarChip(S.zonaActual);
    } catch (_) {}
    // [ASEGURAR DATA] "Log de errores" SOLO visible para master (read-only, diagnóstico de stock).
    try {
      const esMaster = (S.session && (S.session.rol || '').toLowerCase() === 'master');
      const btn = $('zonaBtnLogErrores');
      if (btn) btn.classList.toggle('hidden', !esMaster);
    } catch (_) {}
    _zonaInstalarRipple();
    // [808] 🎯 Considerados: badge al entrar + poll de 60s (se apaga al salir de la vista Zona).
    // _consPollIniciar ya dispara la primera lectura (y es idempotente: limpia el timer previo).
    _consPollIniciar();
    await _zonaCargarPanel(force);
    // [891] Primera vez sin puesto anclado → abrir el hub para que ELIJA (tipo Netflix).
    try { if (!_zonaAnclaGet()) zonaAbrirHub(); } catch (_) {}
  }
  // [RIZ UX] Delegado único: ripple táctil al presionar cards/botones de la lista (no rompe onclicks).
  let _zonaRippleInstalado = false;
  function _zonaInstalarRipple() {
    if (_zonaRippleInstalado) return;
    const cont = $('zonaLista');
    if (!cont) return;
    _zonaRippleInstalado = true;
    cont.addEventListener('pointerdown', (ev) => {
      try {
        const t = ev.target && ev.target.closest('.zona-btn-pedir,.zona-btn-sec,.zona-card');
        if (t && !t.disabled) _zonaRipple(ev, t);
      } catch (_) {}
    }, { passive: true });
  }

  function _zonaPoblarSelector() {
    const sel = $('zonaSelector');
    if (!sel) return;
    if (!S.zonaList.length) { sel.innerHTML = '<option value="">(sin zonas)</option>'; return; }
    sel.innerHTML = S.zonaList.map(z => {
      const id = z.idZona || z.id || z.nombre;
      const nm = z.nombre || id;
      return `<option value="${_esc(String(id))}">${_esc(String(nm))}</option>`;
    }).join('');
    if (S.zonaActual) sel.value = S.zonaActual;
  }

  // Escape simple para atributos/texto en templates (reusa CSS.escape donde haga falta).
  // [621] Esta era la SEGUNDA definición de `_esc` en el mismo scope: por hoisting ganaba
  // sobre la de la línea ~26015 y NO escapa la comilla simple, dejando sin proteger 15
  // `onclick="…('${_esc(x)}')"` (un skuBase/idCobro con apóstrofo cierra el literal JS).
  // Se unifica: ahora también escapa `'`, igual que la otra.
  function _esc(s) { return String(s == null ? '' : s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;'); }

  async function _zonaCargarPanel(force) {
    _zonaToggleAlmacenBtns();   // [Sorpresas/Mermas] Guías ↔ 🎯/♻️ según la zona activa
    const lista = $('zonaLista');
    if (lista && (force || !S.zonaProductos.length)) {
      // [RIZ UX] Skeleton de cards con shimmer (en vez de spinner pelado): silueta real de una zona-card.
      lista.innerHTML = _zonaSkelCards(4);
    }
    try {
      const r = await API.zona.panel({ zona: S.zonaActual });
      if (!r || r.ok === false) throw new Error((r && r.error) || 'Panel sin datos');
      const data = r.data || r;
      // El backend (mos.zona_panel → me.zona_panel) devuelve { items:[...] } (NO `productos`) y NO trae kpis.
      // Normalizamos cada item al shape que consume el render y derivamos los KPIs de los items (única fuente).
      const items = Array.isArray(data.items) ? data.items : (Array.isArray(data.productos) ? data.productos : (Array.isArray(data) ? data : []));
      S.zonaProductos = items.map(_zonaNormItem);
      S.zonaKpis = null;   // sin kpis del backend → _zonaPintarKpis los deriva de los items
      // [RIZ live] El panel lee TABLAS VIVAS (me.stock_zonas / wh.stock) en cada fetch. La frescura HONESTA
      // es el momento de ESTE fetch exitoso — NO el heartbeat del sync GAS de respaldo (r._fresh), que mide
      // la sombra y puede estar ~1.5h viejo aunque el dato mostrado sea de hace 1s. Ignoramos r._fresh para el chip.
      S.zonaFresh = (r._fresh !== false);   // (legacy, solo informativo; no gobierna el chip)
      S.zonaUltimoFetch = Date.now();
      _zonaPintarFresh();
      _zonaPintarKpis(true);   // count-up animado al cargar
      renderZona();
      // [976] precarga SILENCIOSA de los huecos "Por activar" de esta zona → mantiene vivo el badge del 5º tab
      //   sin abrirlo. force=true (la zona pudo cambiar); silent=true (solo cache+badge, no toca la lista salvo
      //   que el 5º tab ya esté activo). Best-effort: un fallo no rompe el panel.
      try { _zonaPorActivarCargar(true, true); } catch (_) {}
      // [RIZ · TRASLADO VERIFICADO] refrescar el badge del botón "🚚 Guías" (pendientes) + cache de verificadas.
      _trasCargarBadge();
      _trasCargarResumen();
    } catch (e) {
      if (lista) lista.innerHTML = `<div class="text-center py-12 text-red-400 text-sm">No se pudo cargar el panel de zona.<br><span class="text-slate-500">${_esc(e.message || String(e))}</span></div>`;
      // No relanzar: loadView ya marca loaded=false vía su catch si throw; acá preferimos no romper.
    }
  }

  // ── [RIZ live] AUTO-REFRESH del panel (comunicación casi instantánea) ────────
  // DECISIÓN: POLLING (no Supabase Realtime). Es el patrón ya probado en MOS (almacén/config/finanzas),
  // robusto, sin canales/RLS-realtime/reconexión que mantener, y suficiente para "casi al instante".
  // Realtime sobre me.stock_zonas/wh.stock daría latencia menor pero a cambio de complejidad y otra
  // superficie de fallo — no lo justifica el caso (admin mirando un panel). Documentado aquí a propósito.
  //
  // El loop:
  //   · corre SOLO en la vista 'zona' (loadView lo arranca/detiene) y SOLO con la pestaña visible;
  //   · cada ZONA_AUTO_MS re-fetcha API.zona.panel y hace un DIFF SUAVE (solo re-renderiza si cambió algo),
  //     preservando scroll y SIN parpadeo (no toca el skeleton; no resetea filtros/búsqueda);
  //   · se PAUSA si hay un modal de zona abierto o un ajuste inline en curso (no pisar lo que el admin escribe);
  //   · al volver el foco (visibilitychange→visible) dispara un refresco inmediato.
  const ZONA_AUTO_MS = 25 * 1000;
  let _zonaAutoTimer = null;
  let _zonaVisHandler = null;
  let _zonaRefrescando = false;
  function _zonaIniciarAutoRefresh() {
    _zonaTickFreshStart();
    if (_zonaAutoTimer) clearInterval(_zonaAutoTimer);
    _zonaAutoTimer = setInterval(() => { _zonaAutoRefrescar(); }, ZONA_AUTO_MS);
    if (!_zonaVisHandler) {
      _zonaVisHandler = () => {
        if (document.visibilityState === 'visible' && S.view === 'zona') _zonaAutoRefrescar();
      };
      document.addEventListener('visibilitychange', _zonaVisHandler);
    }
    _consPollIniciar();   // [808] el badge de 🎯 Considerados vive mientras dure la vista Zona
  }
  function _zonaDetenerAutoRefresh() {
    if (_zonaAutoTimer) { clearInterval(_zonaAutoTimer); _zonaAutoTimer = null; }
    _consPollDetener();   // [808] al salir de Zona el poll de considerados muere (sin timers huérfanos)
    _zonaTickFreshStop();
    // El visibilitychange handler es barato y chequea S.view==='zona' → lo dejamos registrado una vez.
  }
  // ¿Hay un modal de zona abierto o un ajuste inline activo? → no auto-refrescar (no pisar edición).
  function _zonaHayEdicionAbierta() {
    try {
      const ids = ['modalZonaBCG','modalZonaLotes','modalZonaSug','modalZonaEsp','modalZonaGuias','modalZonaLog','modalZonaKardex','modalZona','modalZonaCart'];
      for (const id of ids) { const el = $(id); if (el && el.classList.contains('open')) return true; }
      // Ajuste inline (stepper): el input solo existe en el DOM mientras la celda está en edición.
      if (document.querySelector('.zona-step-input')) return true;
      // Edición por código de barra: el disclosure colapsado deja el body con display:none pero NO borra
      // su innerHTML → no basta con la presencia del input. Pedimos un .zona-cod-body VISIBLE (offsetParent).
      const bodies = document.querySelectorAll('.zona-cod-body');
      for (let i = 0; i < bodies.length; i++) {
        const b = bodies[i];
        if (b.offsetParent !== null && b.querySelector('.zona-cod-input')) return true;
      }
    } catch (_) {}
    return false;
  }
  // Refresco silencioso: re-fetcha el panel y aplica diff suave. NO muestra skeleton, NO resetea filtros.
  async function _zonaAutoRefrescar() {
    if (!S.session) return;
    if (S.view !== 'zona') return;
    if (document.visibilityState !== 'visible') return;
    if (_zonaRefrescando) return;
    if (_zonaHayEdicionAbierta()) return;   // pausa mientras el admin edita
    let on = false;
    try { on = !!(API.zona && API.zona.moduloOn && API.zona.moduloOn()); } catch (_) { on = false; }
    if (!on) return;
    _zonaRefrescando = true;
    try {
      const r = await API.zona.panel({ zona: S.zonaActual });
      if (!r || r.ok === false) return;   // silencioso: no romper la vista por un fallo de polling
      // El admin pudo haber cambiado de zona / abierto un modal mientras esperabamos → descartar.
      if (S.view !== 'zona' || _zonaHayEdicionAbierta()) return;
      const data = r.data || r;
      const items = Array.isArray(data.items) ? data.items : (Array.isArray(data.productos) ? data.productos : (Array.isArray(data) ? data : []));
      const nuevos = items.map(_zonaNormItem);
      // Frescura SIEMPRE se actualiza ante un fetch exitoso (el dato es de AHORA, haya cambiado o no).
      S.zonaUltimoFetch = Date.now();
      S.zonaFresh = (r._fresh !== false);
      const cambio = JSON.stringify(nuevos) !== JSON.stringify(S.zonaProductos);
      if (cambio) {
        S.zonaProductos = nuevos;
        S.zonaKpis = null;
        renderZona();               // diff barato: innerHTML completo pero solo si HUBO cambio → sin parpadeo en el caso común
        _zonaPintarKpis(false);     // sin count-up en el refresco (evita "saltos" de número)
        _zonaPulsoRefresco();       // pulso sutil de "se actualizó"
        _trasCargarBadge();         // el badge de guías también puede haber cambiado
        _trasCargarResumen();
      }
      _zonaPintarFresh();           // siempre repintar el chip "actualizado hace Xs"
    } catch (_) {
      // silencioso — el próximo tick reintenta; el chip seguirá mostrando la última hora buena
    } finally {
      _zonaRefrescando = false;
    }
  }
  // Pulso sutil al refrescar (anillo en el chip de frescura). Respeta reduced-motion.
  function _zonaPulsoRefresco() {
    if (_zonaReduce()) return;
    const dot = $('zonaFreshDot');
    if (!dot) return;
    try { dot.classList.remove('zona-fresh-pulse'); void dot.offsetWidth; dot.classList.add('zona-fresh-pulse'); } catch (_) {}
  }

  // [RIZ live] Chip de frescura HONESTO: mide la antigüedad del último fetch EXITOSO del panel
  // (que lee tablas vivas), NO el heartbeat del sync GAS de respaldo. Verde si el dato es de hace
  // <2 min (live), ámbar si está envejeciendo (>2 min, p.ej. tab en background largo). Texto humano
  // "actualizado hace Xs/Xm". Se repinta cada 5s mediante _zonaTickFreshStart (sin re-fetchar).
  function _zonaPintarFresh() {
    const dot = $('zonaFreshDot'), lbl = $('zonaFreshLbl');
    const ts = S.zonaUltimoFetch || 0;
    if (!ts) {
      if (dot) dot.className = 'zona-fresh-dot';
      if (lbl) lbl.textContent = '—';
      return;
    }
    const seg = Math.max(0, Math.round((Date.now() - ts) / 1000));
    const stale = seg > 120;   // >2 min sin refresco exitoso → ámbar (no "retraso", solo "envejeciendo")
    if (dot) dot.className = 'zona-fresh-dot' + (stale ? ' stale' : '');
    if (lbl) lbl.textContent = 'actualizado ' + _zonaHaceLbl(seg);
  }
  // "hace Xs / hace Xm / hace Xh" humano y corto.
  function _zonaHaceLbl(seg) {
    if (seg < 5)   return 'recién';
    if (seg < 60)  return 'hace ' + seg + 's';
    const m = Math.round(seg / 60);
    if (m < 60)    return 'hace ' + m + ' min';
    const h = Math.round(m / 60);
    return 'hace ' + h + ' h';
  }
  // Tick visual del chip (solo texto/color, sin red). Arranca con el auto-refresh y muere al salir de zona.
  // [LOG ERRORES] Estado del módulo: items cargados + filtro de TIPO activo (chips clickeables).
  //   _zonaLogState.tipo: null = todos · '0' = Otro (sin clasificar) · '1'..'5' = taxonomía.
  let _zonaLogState = { items: [], tipo: null, tab: null };
  // [LOG ERRORES · PESTAÑAS] Dos vistas que reparten las filas según QUIÉN ACTÚA (no por tipo):
  //   · SIS (🔧 Sistémico)  = requiere intervención de CÓDIGO/CONFIG del master →
  //        fila VIVA (esVivo===true · regresión activa, fuga de HOY) OR TIPO 5 (factor, config que él setea).
  //   · OPE (📋 Operativo)  = se resuelve CONTANDO/AUDITANDO (trabajo del operador) → todo lo demás:
  //        cicatrices históricas T1/T2/T3 (esVivo=false, ya sellado en código), T4 (sin ancla), y Otro/null.
  //   NOTA: el reparto por tipo (legacy) quedó OBSOLETO; ahora la pestaña la decide _zonaLogTabDeItem por fila.
  const ZONA_LOG_TABS = {
    SIS: { lbl: '🔧 Sistémico', cls: 'sis' },
    OPE: { lbl: '📋 Operativo', cls: 'ope' }
  };
  const _ZONA_LOG_TAB_LS = 'mosZonaLogTab';
  // [REGLA DE PESTAÑA · por fila] Sistémico = fuga VIVA (regresión activa) O config (factor, T5);
  //   Operativo = todo lo demás (histórico ya sellado + ancla + sin clasificar). Espeja la decisión del dueño.
  function _zonaLogTabDeItem(it) {
    if (!it) return 'OPE';
    if (it.esVivo === true) return 'SIS';
    if (_zonaLogTipoKey(it) === 5) return 'SIS';
    return 'OPE';
  }
  // Taxonomía de TIPOS — única fuente de verdad para color/nombre/glifo en el frontend (espeja mos._recon_tipo_etiqueta).
  //   cat: categoría de quién lo resuelve → 'SIS' (sistémico/código, lo persigue el master) ·
  //        'OPE' (operativo, se arregla contando/auditando) · 'CFG' (config, se setea una vez).
  //   def: leyenda explicativa (definición · causa · quién lo arregla · qué hacer). Español neutral peruano.
  const ZONA_LOG_TIPOS = {
    1: { nombre: 'Stock congelado',        glifo: '🧊', cls: 't1', cat: 'SIS',
         def: 'El stock guardado se quedó pegado en un valor viejo: el kardex registró movimientos pero el saldo no los siguió. Causa: una escritura de stock que no se aplicó. Lo persigue el master; si reincide, hay que hallar qué escritura falló en el código.' },
    2: { nombre: 'Kardex inconsistente',   glifo: '📕', cls: 't2', cat: 'SIS',
         def: 'La suma de los movimientos del kardex no cuadra con el saldo guardado. Causa: un movimiento mal escrito o un saldo recalculado fuera de orden. Lo persigue el master; se corrige en el código (no recontando).' },
    3: { nombre: 'Salida sin descuento',   glifo: '🚚', cls: 't3', cat: 'SIS',
         def: 'Salió producto del origen (una guía/despacho) pero el stock del origen no se descontó. Causa: una salida que no disparó el descuento. Es crítico (suele reincidir); lo persigue el master y se corrige en el código.' },
    4: { nombre: 'Sin ancla',              glifo: '⚓', cls: 't4', cat: 'OPE',
         def: 'El producto nunca fue auditado (contado físicamente), así que no hay un punto de partida confiable para validar el stock. Lo arregla el operador: cuenta físico y ancla ese conteo. No es un error de código.' },
    5: { nombre: 'Factor sin configurar',  glifo: '⚙️', cls: 't5', cat: 'CFG',
         def: 'Falta configurar el factor de conversión del producto (ej. cuántas unidades trae una caja), por eso no se puede calcular el stock teórico. Se setea una sola vez en el catálogo y deja de aparecer.' },
    0: { nombre: 'Otro',                   glifo: '•',  cls: 't0', cat: 'OPE',
         def: 'Diferencia común o saldo negativo sin un patrón claro de las categorías anteriores. Suele ser operativo: revisar el conteo físico y el historial del producto. Si se repite con el mismo producto, avisar al master.' }
  };
  // Etiqueta legible de la categoría (para badges y leyenda).
  const ZONA_LOG_CAT = {
    SIS: { lbl: 'SISTÉMICO · código',  cls: 'cat-sis', quien: 'Lo persigue el master (no debe reincidir)' },
    OPE: { lbl: 'OPERATIVO · contar',  cls: 'cat-ope', quien: 'Lo arregla el operador auditando' },
    CFG: { lbl: 'CONFIG · una vez',    cls: 'cat-cfg', quien: 'Se setea una sola vez en el catálogo' }
  };
  function _zonaLogTipoKey(it) { const t = (it && it.tipoError != null) ? Number(it.tipoError) : 0; return (t >= 1 && t <= 5) ? t : 0; }

  let _zonaTickFreshTimer = null;
  function _zonaTickFreshStart() {
    if (_zonaTickFreshTimer) clearInterval(_zonaTickFreshTimer);
    _zonaTickFreshTimer = setInterval(() => {
      if (S.view !== 'zona') return;   // defensa: no tocar el DOM fuera de la vista
      _zonaPintarFresh();
    }, 5000);
  }
  function _zonaTickFreshStop() {
    if (_zonaTickFreshTimer) { clearInterval(_zonaTickFreshTimer); _zonaTickFreshTimer = null; }
  }

  // [RIZ UX] Pinta los KPIs con count-up (0→valor). animar=false (re-pintado tras ajuste) → directo.
  // [896] Las 4 vitales = conteo por CUADRANTE (mismo _zonaCuadDe que las cards y los grupos).
  //   Todas son CUENTAS enteras (adiós al bug del float "240.14000000000001" que era una suma).
  function _zonaPintarKpis(animar) {
    const arr = S.zonaProductos || [];
    let pedir = 0, muerto = 0, sobra = 0, orden = 0;
    for (const p of arr) { const c = _zonaCuadDe(p); if (c === 'pedir') pedir++; else if (c === 'muerto') muerto++; else if (c === 'sobra') sobra++; else orden++; }
    const set = (id, v) => { const el = $(id); if (!el) return; if (animar) _zonaCountUp(el, v); else el.textContent = v; };
    set('zKpiFaltan', pedir); set('zKpiCero', muerto); set('zKpiSobra', sobra); set('zKpiOrden', orden);
    // [899] marcar la pestaña activa (las vitales son pestañas: una siempre encendida)
    try { const fk = (S._zonaFiltros || {}).kpi; document.querySelectorAll('#zonaKpis .zona-kpi').forEach(el => el.classList.toggle('active', el.dataset.kpi === fk)); } catch (_) {}
    // [976] mantener el badge de la 5ª pestaña "Por activar" en sincronía en cada pintado de vitales.
    try { _zonaPaActualizarBadge(); } catch (_) {}
  }
  // [RIZ UX] HTML de N cards skeleton con shimmer (silueta de una zona-card real).
  function _zonaSkelCards(n) {
    let out = '';
    for (let i = 0; i < n; i++) {
      out += `<div class="zona-skel-card" style="--i:${i}">
        <div class="zona-skel-row"><span class="skel zona-skel-title"></span><span class="skel zona-skel-badge"></span></div>
        <div class="zona-skel-metrics"><span class="skel"></span><span class="skel"></span><span class="skel"></span><span class="skel"></span></div>
        <div class="skel zona-skel-line"></div>
        <div class="zona-skel-row"><span class="skel zona-skel-btn"></span><span class="skel zona-skel-btn2"></span></div>
      </div>`;
    }
    return out;
  }
  function _zonaContar(fn) { try { return S.zonaProductos.filter(fn).length; } catch(_) { return 0; } }
  function _zonaSumar(fn)  { try { return S.zonaProductos.reduce((a,p)=>a+Math.max(0,fn(p)),0); } catch(_) { return 0; } }

  // ── Render de cards ────────────────────────────────────────────────────
  // ════════════════════════════════════════════════════════════════════
  // [🎯 SORPRESAS + ♻️ MERMAS] Paneles MOS (módulo Zona · card ALMACÉN)
  // Diseño: DISENO_SORPRESAS_MERMAS.md · backend SQL 516/517 (wh.*)
  // En ALMACÉN el botón Guías se reemplaza por 🎯 (solo admins) y ♻️.
  // ════════════════════════════════════════════════════════════════════
  function _esAdminSesion() {
    const r = String(S.session?.rol || '').toUpperCase();
    return r === 'MASTER' || r === 'ADMIN' || r === 'ADMINISTRADOR';
  }
  function _zonaToggleAlmacenBtns() {
    const esAlm = _esZonaAlmacen({ idZona: S.zonaActual,
      nombre: ((S.zonaList || []).find(x => (x.idZona || x.id || x.nombre) === S.zonaActual) || {}).nombre });
    const bg = $('zonaBtnGuias'), bs = $('zonaBtnSorpresas'), bm = $('zonaBtnMermas'), bv = $('zonaBtnVenc');
    if (bg) bg.classList.toggle('hidden', esAlm);
    if (bm) bm.classList.toggle('hidden', !esAlm);
    // [891] "🏠 Abrir Almacén" no tiene sentido cuando YA estás en el puesto Almacén → ocultar ahí.
    const ba = $('zonaBtnAbrirAlm'); if (ba) ba.classList.toggle('hidden', esAlm);
    // [Fase 2 FEFO] 📅 Por vencer en TODAS las zonas: almacén = lotes WH; zonas = libro me.zona_lotes
    if (bv) bv.classList.remove('hidden');
    if (bs) bs.classList.toggle('hidden', !esAlm || !_esAdminSesion());
    if (esAlm) _mermasBadgeRefrescar();
    _vencBadgeRefrescar(esAlm ? null : S.zonaActual);
  }
  // Badge rojo = lotes VENCIDOS + CRÍTICOS (≤7d) del alcance activo (almacén o zona)
  async function _vencBadgeRefrescar(zona) {
    try {
      const r = await API.rpcWH('vencimientos_lista', zona ? { zona } : {});
      const rows = (r && r.ok && Array.isArray(r.data)) ? r.data : [];
      const n = rows.filter(l => l.severidad === 'VENCIDO' || l.severidad === 'CRITICO').length;
      const b = $('zonaVencBadge');
      if (b) { b.textContent = String(n); b.style.display = n > 0 ? '' : 'none'; }
    } catch (_) {}
  }
  // Badge rojo = mermas VENCIDAS (>3 días corridos sin procesar)
  async function _mermasBadgeRefrescar() {
    try {
      const r = await API.rpcWH('mermas_lista', { alcance: 'wh' });
      const rows = (r && r.ok && Array.isArray(r.data)) ? r.data : [];
      const n = rows.filter(m => m.vencida).length;
      const b = $('zonaMermasBadge');
      if (b) { b.textContent = String(n); b.style.display = n > 0 ? '' : 'none'; }
    } catch (_) {}
  }

  // ── ♻️ MERMAS · panel auditoría (historial completo alcance=mos) ──
  let _mermasData = [];
  let _mermasFiltro = 'TODAS';
  async function abrirMermasPanel() {
    openModal('modalMermas');
    $('mermasLista').innerHTML = '<div class="muted" style="text-align:center;padding:20px">Cargando…</div>';
    try {
      const r = await API.rpcWH('mermas_lista', { alcance: 'mos', dias: 365 });
      _mermasData = (r && r.ok && Array.isArray(r.data)) ? r.data : [];
    } catch (e) { _mermasData = []; }
    _mermasRender();
  }
  // ── 📅 POR VENCER · panel de solo-visualización (semáforo unificado con WH, SQL 526) ──
  let _vencData = [];
  let _vencFiltro = 'RIESGO';
  let _vencDetalle = null;   // codigoProducto en vista detalle (FIFO + historial), null = lista
  async function abrirVencimientosPanel() {
    const esAlm = _esZonaAlmacen({ idZona: S.zonaActual,
      nombre: ((S.zonaList || []).find(x => (x.idZona || x.id || x.nombre) === S.zonaActual) || {}).nombre });
    const zona = esAlm ? null : S.zonaActual;
    const t = document.getElementById('vencTituloMos');
    if (t) t.textContent = 'Por vencer · ' + (zona || 'almacén');
    _vencDetalle = null;
    openModal('modalVencimientos');
    $('vencListaMos').innerHTML = '<div class="muted" style="text-align:center;padding:20px">Cargando…</div>';
    try {
      const r = await API.rpcWH('vencimientos_lista', zona ? { zona } : {});
      _vencData = (r && r.ok && Array.isArray(r.data)) ? r.data : [];
    } catch (e) { _vencData = []; }
    _vencRender();
  }
  function vencSetFiltro(f) { _vencFiltro = f; _vencDetalle = null; _vencRender(); }
  function vencVerProducto(cod) { _vencDetalle = String(cod); _vencRender(); }
  function vencVolver() { _vencDetalle = null; _vencRender(); }
  // Historial del lote (wh.get_historial_lote — gate ampliado a MOS en SQL 530). Toggle inline.
  async function vencHistLote(idLote) {
    const box = document.getElementById('vencHist_' + idLote);
    if (!box) return;
    if (box.dataset.abierto === '1') { box.style.display = 'none'; box.dataset.abierto = '0'; return; }
    box.style.display = ''; box.dataset.abierto = '1';
    if (box.dataset.cargado === '1') return;
    box.innerHTML = '<div class="muted" style="font-size:11px;padding:6px">Cargando historial…</div>';
    try {
      const r = await API.rpcWH('get_historial_lote', { idLote });
      const rows = (r && r.ok && Array.isArray(r.data)) ? r.data : [];
      box.dataset.cargado = '1';
      if (!rows.length) { box.innerHTML = '<div class="muted" style="font-size:11px;padding:6px">Sin movimientos registrados</div>'; return; }
      const ACC = { INGRESO: ['#34d399','↑'], CONSUMO: ['#fca5a5','↓'], MERMA: ['#f87171','♻'], CREACION: ['#34d399','↑'] };
      box.innerHTML = rows.map(m => {
        const [col, ico] = ACC[String(m.accion || '').toUpperCase()] || ['#94a3b8','·'];
        const ts = m.ts ? new Date(m.ts).toLocaleString('es-PE', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' }) : '—';
        return '<div style="display:flex;gap:8px;align-items:center;padding:5px 8px;border-top:1px solid #16233d;font-size:11px">' +
          '<span style="color:' + col + ';font-weight:900;width:14px">' + ico + '</span>' +
          '<span style="color:' + col + ';font-weight:800;white-space:nowrap">' + (m.accion || '?') + ' ' + (m.cantidad || 0) + 'u</span>' +
          '<span class="muted" style="flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis">' + _esc(m.motivo || '') + '</span>' +
          '<span class="muted" style="white-space:nowrap">' + ts + (m.idGuia ? ' · ' + _esc(m.idGuia) : '') + '</span></div>';
      }).join('');
    } catch (e) {
      box.innerHTML = '<div style="color:#fca5a5;font-size:11px;padding:6px">No se pudo cargar el historial</div>';
    }
  }
  function _vencRender() {
    const rows = _vencData;
    const nomProdV = cod => {
      const p2 = (S.productos || []).find(x => String(x.codigoBarra) === String(cod));
      return p2 ? (p2.descripcion || cod) : cod;
    };
    const COLSV = {
      VENCIDO: ['rgba(220,38,38,.18)', '#fca5a5', 'rgba(239,68,68,.45)', '#dc2626'],
      CRITICO: ['rgba(249,115,22,.16)', '#fdba74', 'rgba(249,115,22,.4)', '#f97316'],
      ALERTA:  ['rgba(245,158,11,.13)', '#fcd34d', 'rgba(245,158,11,.35)', '#f59e0b'],
      URGENTE: ['rgba(234,179,8,.11)', '#fde047', 'rgba(234,179,8,.3)', '#eab308'],
      SANO:    ['rgba(71,85,105,.25)', '#cbd5e1', 'rgba(148,163,184,.2)', '#334155']
    };
    // ── DETALLE de producto: FIFO activos (vence primero arriba) + historial por lote ──
    if (_vencDetalle) {
      const lotes = rows.filter(l => String(l.codigoProducto) === _vencDetalle)
        .slice().sort((a, b) => (a.diasRestantes ?? 999) - (b.diasRestantes ?? 999));
      $('vencKpisMos').innerHTML = '';
      $('vencFiltrosMos').innerHTML = `<button class="chip" style="cursor:pointer" onclick="MOS.vencVolver()">← Volver a la lista</button>`;
      $('vencListaMos').innerHTML = `
        <div style="margin-bottom:10px"><b style="color:#eaf1fb;font-size:14px">${_esc(nomProdV(_vencDetalle))}</b>
        <div class="muted" style="font-size:10px">${_esc(_vencDetalle)} · 🎯 FIFO: vence primero, sale primero · ${lotes.length} lote${lotes.length === 1 ? '' : 's'} activo${lotes.length === 1 ? '' : 's'}</div></div>` +
        (lotes.length ? lotes.map(l => {
          const [bg, col, bor, borde] = COLSV[l.severidad] || COLSV.SANO;
          const d = l.diasRestantes;
          const fv = l.fechaVencimiento ? new Date(l.fechaVencimiento + 'T12:00:00').toLocaleDateString('es-PE', { day: '2-digit', month: 'short', year: 'numeric' }) : '—';
          return `<div class="prow" style="border-left:4px solid ${borde};gap:10px;flex-wrap:wrap">
            <div style="width:52px;height:52px;border-radius:12px;flex-shrink:0;display:flex;flex-direction:column;align-items:center;justify-content:center;font-weight:900;background:${bg};color:${col};border:1px solid ${bor}">
              <span style="font-size:17px;line-height:1">${d < 0 ? Math.abs(d) : d}</span>
              <span style="font-size:7px;letter-spacing:.04em;opacity:.85;margin-top:2px">${d < 0 ? 'D VENCIDO' : 'DÍAS'}</span></div>
            <div style="flex:1;min-width:130px"><b style="color:#eaf1fb;font-family:monospace;font-size:12px">${_esc(l.idLote)}</b>
            <div class="muted" style="font-size:10px">📅 vence ${_esc(fv)} · 📋 guía ${_esc(l.idGuia || '—')}</div></div>
            <span class="mono" style="white-space:nowrap;font-weight:800;color:#eaf1fb">${l.cantidadActual} <span class="muted" style="font-size:9px">uds</span></span>
            <button class="chip" style="cursor:pointer" onclick="MOS.vencHistLote('${_esc(l.idLote)}')">📜 Historial</button>
            <div id="vencHist_${_esc(l.idLote)}" data-abierto="0" style="display:none;flex-basis:100%;background:#0a1424;border-radius:10px;border:1px solid #16233d;margin-top:6px"></div>
          </div>`;
        }).join('') : '<div class="muted" style="text-align:center;padding:20px">Sin lotes activos</div>');
      return;
    }
    const grupos = { VENCIDO: [], CRITICO: [], ALERTA: [], URGENTE: [], SANO: [] };
    rows.forEach(l => (grupos[l.severidad] = grupos[l.severidad] || []).push(l));
    const KP = [
      ['VENCIDO', grupos.VENCIDO.length, '#fca5a5', 'Vencidos'],
      ['CRITICO', grupos.CRITICO.length, '#fdba74', 'Críticos'],
      ['ALERTA',  grupos.ALERTA.length,  '#fcd34d', '≤30 días'],
      ['URGENTE', grupos.URGENTE.length, '#fde047', '≤90 días'],
      ['SANO',    grupos.SANO.length,    '#86efac', 'Sanos']
    ];
    $('vencKpisMos').innerHTML = KP.map(([k, n, col, lbl]) =>
      `<div onclick="MOS.vencSetFiltro('${k}')" style="cursor:pointer;text-align:center;padding:9px 4px;border-radius:12px;background:${_vencFiltro === k ? 'rgba(59,130,246,.12)' : 'rgba(30,41,59,.55)'};border:1px solid ${_vencFiltro === k ? 'rgba(96,165,250,.55)' : 'rgba(148,163,184,.16)'}">
        <div style="font-size:19px;font-weight:900;color:${col}">${n}</div>
        <div style="font-size:9px;font-weight:800;color:#94a3b8;text-transform:uppercase;letter-spacing:.04em">${lbl}</div></div>`).join('');
    const FIL = [['RIESGO', '⚠ En riesgo'], ['TODOS', 'Todos'], ['VENCIDO', 'Vencidos'], ['CRITICO', 'Críticos'], ['ALERTA', '≤30d'], ['URGENTE', '≤90d'], ['SANO', 'Sanos']];
    $('vencFiltrosMos').innerHTML = FIL.map(([k, l]) =>
      `<span class="chip ${_vencFiltro === k ? 'gold' : ''}" style="cursor:pointer" onclick="MOS.vencSetFiltro('${k}')">${l}</span>`).join('');
    let vis;
    if (_vencFiltro === 'TODOS') vis = rows;
    else if (_vencFiltro === 'RIESGO') vis = [...grupos.VENCIDO, ...grupos.CRITICO, ...grupos.ALERTA, ...grupos.URGENTE];
    else vis = grupos[_vencFiltro] || [];
    if (!vis.length) {
      $('vencListaMos').innerHTML = `<div class="muted" style="text-align:center;padding:24px">${_vencFiltro === 'RIESGO' ? 'Nada en riesgo 🎉' : 'Sin lotes en este filtro'}</div>`;
      return;
    }
    const nomProd = cod => {
      const p2 = (S.productos || []).find(x => String(x.codigoBarra) === String(cod));
      return p2 ? (p2.descripcion || cod) : cod;
    };
    const COLS = {
      VENCIDO: ['rgba(220,38,38,.18)', '#fca5a5', 'rgba(239,68,68,.45)', '#dc2626'],
      CRITICO: ['rgba(249,115,22,.16)', '#fdba74', 'rgba(249,115,22,.4)', '#f97316'],
      ALERTA:  ['rgba(245,158,11,.13)', '#fcd34d', 'rgba(245,158,11,.35)', '#f59e0b'],
      URGENTE: ['rgba(234,179,8,.11)', '#fde047', 'rgba(234,179,8,.3)', '#eab308'],
      SANO:    ['rgba(71,85,105,.25)', '#cbd5e1', 'rgba(148,163,184,.2)', '#334155']
    };
    $('vencListaMos').innerHTML = vis.slice(0, 300).map(l => {
      const [bg, col, bor, borde] = COLS[l.severidad] || COLS.SANO;
      const d = l.diasRestantes;
      const tile = l.severidad === 'VENCIDO'
        ? `<div style="width:56px;height:56px;border-radius:12px;flex-shrink:0;display:flex;flex-direction:column;align-items:center;justify-content:center;font-weight:900;background:${bg};color:${col};border:1px solid ${bor}"><span style="font-size:19px;line-height:1">${Math.abs(d)}</span><span style="font-size:7.5px;letter-spacing:.04em;opacity:.85;margin-top:2px">D VENCIDO</span></div>`
        : `<div style="width:56px;height:56px;border-radius:12px;flex-shrink:0;display:flex;flex-direction:column;align-items:center;justify-content:center;font-weight:900;background:${bg};color:${col};border:1px solid ${bor}"><span style="font-size:19px;line-height:1">${d}</span><span style="font-size:7.5px;letter-spacing:.04em;opacity:.85;margin-top:2px">DÍAS</span></div>`;
      const fv = l.fechaVencimiento ? new Date(l.fechaVencimiento + 'T12:00:00').toLocaleDateString('es-PE', { day: '2-digit', month: 'short', year: 'numeric' }) : '—';
      return `<div class="prow" style="border-left:4px solid ${borde};gap:10px;cursor:pointer" onclick="MOS.vencVerProducto('${_esc(l.codigoProducto)}')" title="Ver lotes FIFO + historial">
        ${tile}
        <div style="flex:1;min-width:140px"><b style="color:#eaf1fb">${_esc(nomProd(l.codigoProducto))}</b>
        <div class="muted" style="font-size:10px">vence ${_esc(fv)} · lote ${_esc(l.idLote)} · guía ${_esc(l.idGuia || '—')}</div></div>
        <span class="mono" style="white-space:nowrap;font-weight:800;color:#eaf1fb">${l.cantidadActual} <span class="muted" style="font-size:9px">uds</span></span>
        <span class="muted" style="font-size:14px">›</span>
      </div>`;
    }).join('');
  }

  function mermasSetFiltro(f) { _mermasFiltro = f; _mermasRender(); }
  let _mermasAgrupar = 'FECHA';   // FECHA | ESTADO (pedido dueño: organizar por fechas y estados)
  function mermasSetAgrupar(a) { _mermasAgrupar = a; _mermasRender(); }
  // Lightbox simple para la foto de la merma (click en el thumbnail)
  function mermasVerFoto(url) {
    if (!url) return;
    let ov = document.getElementById('mermasFotoOv');
    if (!ov) { ov = document.createElement('div'); ov.id = 'mermasFotoOv'; document.body.appendChild(ov); }
    ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.88);z-index:9700;display:grid;place-items:center;padding:16px;cursor:zoom-out';
    ov.onclick = () => ov.remove();
    ov.innerHTML = `<img src="${_esc(url)}" style="max-width:96vw;max-height:92vh;border-radius:14px;box-shadow:0 20px 60px rgba(0,0,0,.6)" onerror="this.replaceWith(Object.assign(document.createElement('div'),{textContent:'No se pudo cargar la foto',style:'color:#fca5a5'}))">`;
  }
  function _mermasRender() {
    const rows = _mermasData;
    // KPIs de dinero (costo × cantidades) — mes actual
    const mesIni = new Date(); mesIni.setDate(1); mesIni.setHours(0, 0, 0, 0);
    const delMes = rows.filter(m => new Date(m.fechaIngreso) >= mesIni);
    const sMermado = delMes.reduce((a, m) => a + (m.costoUnitario || 0) * (m.cantidadOriginal || 0), 0);
    const sRec = delMes.reduce((a, m) => a + (m.costoUnitario || 0) * (m.cantidadReparada || 0), 0);
    const pend = rows.filter(m => (m.cantidadPendiente || 0) > 0);
    const venc = pend.filter(m => m.vencida);
    // culpa por zona (estadística)
    const porCulpa = {};
    delMes.forEach(m => { const c = m.culpa || '—'; porCulpa[c] = (porCulpa[c] || 0) + 1; });
    const topCulpa = Object.entries(porCulpa).sort((a, b) => b[1] - a[1])[0];
    $('mermasKpis').innerHTML = `<div class="kpi">
      <div class="k"><div class="kv" style="color:#fca5a5">S/ ${sMermado.toFixed(0)}</div><div class="kl">mermado (mes)</div></div>
      <div class="k"><div class="kv" style="color:#7ff0c4">S/ ${sRec.toFixed(0)}</div><div class="kl">recuperado ${sMermado > 0 ? Math.round(sRec / sMermado * 100) + '%' : '—'}</div></div>
      <div class="k"><div class="kv">${pend.length}</div><div class="kl">pendientes</div></div>
      <div class="k"><div class="kv" style="color:${venc.length ? '#fca5a5' : '#7ff0c4'}">${venc.length}</div><div class="kl">vencidas 🔴</div></div>
      ${topCulpa ? `<div class="k"><div class="kv" style="font-size:14px">${topCulpa[0]}</div><div class="kl">más culpa (${topCulpa[1]})</div></div>` : ''}
    </div>`;
    const FILTROS = [['TODAS', 'Todas'], ['PENDIENTES', 'Pendientes'], ['VENCIDAS', 'Vencidas'], ['RECUPERADAS', 'Recuperadas'], ['ELIMINADAS', 'Eliminadas'], ['TRANSFORMADAS', 'Transformadas']];
    $('mermasFiltros').innerHTML = FILTROS.map(([k, l]) =>
      `<span class="chip ${_mermasFiltro === k ? 'gold' : ''}" style="cursor:pointer" onclick="MOS.mermasSetFiltro('${k}')">${l}</span>`).join('') +
      `<span class="muted" style="font-size:10px;align-self:center;margin-left:6px">agrupar:</span>` +
      ['FECHA', 'ESTADO'].map(a => `<span class="chip ${_mermasAgrupar === a ? 'ok' : ''}" style="cursor:pointer" onclick="MOS.mermasSetAgrupar('${a}')">${a === 'FECHA' ? '📅 Fecha' : '🧭 Estado'}</span>`).join('');
    let vis = rows;
    if (_mermasFiltro === 'PENDIENTES') vis = rows.filter(m => (m.cantidadPendiente || 0) > 0);
    else if (_mermasFiltro === 'VENCIDAS') vis = rows.filter(m => m.vencida);
    else if (_mermasFiltro === 'RECUPERADAS') vis = rows.filter(m => (m.cantidadReparada || 0) > 0);
    else if (_mermasFiltro === 'ELIMINADAS') vis = rows.filter(m => (m.cantidadDesechada || 0) > 0 && (m.cantidadPendiente || 0) === 0);
    else if (_mermasFiltro === 'TRANSFORMADAS') vis = rows.filter(m => m.idGuiaTransformacion);
    if (!vis.length) { $('mermasLista').innerHTML = '<div class="muted" style="text-align:center;padding:24px">Sin mermas en este filtro.</div>'; return; }
    const nomProd = cod => {
      const p = (S.productos || []).find(x => String(x.codigoBarra) === String(cod));
      return p ? (p.descripcion || cod) : cod;
    };
    // ── fila con thumbnail de foto (click → lightbox) ──
    const fila = m => {
      const pendN = m.cantidadPendiente || 0;
      const sla = pendN > 0
        ? (m.vencida ? `<span class="chip bad sla">🔴 VENCIDA${m.diasPendiente != null ? ' · ' + m.diasPendiente + 'd' : ''}</span>`
                     : `<span class="chip warn sla">⏳ ${Math.max(0, 3 - (m.diasPendiente || 0))}d restantes</span>`)
        : '';
      const est = pendN > 0 ? (m.cantidadReparada > 0 ? '<span class="chip warn">parcial</span>' : '<span class="chip">pendiente</span>')
        : (m.estado === 'DESECHADA' ? '<span class="chip">eliminada</span>' : '<span class="chip ok">resuelta</span>');
      const trans = m.idGuiaTransformacion ? `<span class="chip" style="background:rgba(167,139,250,.15);color:#c4b5fd;border-color:rgba(167,139,250,.4)">🔄 ${m.idGuiaTransformacion}</span>` : '';
      const dinero = (m.costoUnitario || 0) > 0
        ? `<span class="mono" style="color:${m.cantidadReparada > 0 ? '#7ff0c4' : '#fca5a5'};white-space:nowrap">S/ ${((m.costoUnitario || 0) * (m.cantidadReparada > 0 ? m.cantidadReparada : m.cantidadOriginal)).toFixed(2)}${m.cantidadReparada > 0 ? ' rec.' : ''}</span>` : '';
      const thumb = m.foto
        ? `<div onclick="MOS.mermasVerFoto('${_esc(m.foto)}')" style="width:46px;height:46px;border-radius:10px;overflow:hidden;flex-shrink:0;cursor:zoom-in;border:1px solid #26375a;background:#0a1424"><img src="${_esc(m.foto)}" loading="lazy" style="width:100%;height:100%;object-fit:cover" onerror="this.parentNode.textContent='📷';this.parentNode.style.display='grid';this.parentNode.style.placeItems='center'"></div>`
        : `<div style="width:46px;height:46px;border-radius:10px;flex-shrink:0;display:grid;place-items:center;border:1px dashed #26375a;color:#5f7290;font-size:15px">🧺</div>`;
      const guias = [m.idGuia ? 'de ' + m.idGuia : '', m.idGuiaSalida ? 'salida ' + m.idGuiaSalida : ''].filter(Boolean).join(' · ');
      const bordeVenc = m.vencida ? 'border-color:rgba(239,68,68,.5);background:rgba(239,68,68,.04)' : '';
      return `<div class="prow" style="${bordeVenc}">
        ${thumb}
        <div style="flex:1;min-width:150px"><b style="color:#eaf1fb">${_esc(nomProd(m.codProducto))} · ${m.cantidadOriginal}</b> ${est} ${sla} ${trans}
        <div class="muted" style="font-size:10px">ingresó ${_esc(m.usuario || '—')} · culpa <b>${_esc(m.culpa || '—')}</b>${m.cantidadReparada ? ' · rec. ' + m.cantidadReparada : ''}${m.cantidadDesechada ? ' · elim. ' + m.cantidadDesechada : ''}${pendN ? ' · pend. ' + pendN : ''}${guias ? ' · ' + guias : ''}</div></div>
        ${dinero}</div>`;
    };
    // ── agrupación: por FECHA (Hoy/Ayer/día) o por ESTADO ──
    const _diaLblM = ts => {
      const d = new Date(ts); const hoy = new Date();
      if (d.toDateString() === hoy.toDateString()) return 'Hoy';
      if (d.toDateString() === new Date(hoy.getTime() - 864e5).toDateString()) return 'Ayer';
      return d.toLocaleDateString('es-PE', { weekday: 'short', day: '2-digit', month: 'short', year: d.getFullYear() !== hoy.getFullYear() ? '2-digit' : undefined });
    };
    const _estadoLblM = m => {
      const pendN = m.cantidadPendiente || 0;
      if (pendN > 0 && m.vencida) return '🔴 Vencidas';
      if (pendN > 0 && (m.cantidadReparada || 0) > 0) return '◐ Parciales';
      if (pendN > 0) return '🟡 Pendientes';
      if (m.idGuiaTransformacion) return '🔄 Transformadas';
      if (m.estado === 'DESECHADA') return '🗑 Eliminadas';
      return '✅ Recuperadas';
    };
    const ORDEN_EST = ['🔴 Vencidas', '🟡 Pendientes', '◐ Parciales', '🔄 Transformadas', '✅ Recuperadas', '🗑 Eliminadas'];
    // [Dueño] la ÚLTIMA fecha SIEMPRE primero (descendente estricto) — también dentro de cada grupo
    const ordenadas = vis.slice(0, 250).sort((a, b) => new Date(b.fechaIngreso) - new Date(a.fechaIngreso));
    const grupos = {};
    ordenadas.forEach(m => {
      const k = _mermasAgrupar === 'ESTADO' ? _estadoLblM(m) : _diaLblM(m.fechaIngreso);
      (grupos[k] = grupos[k] || []).push(m);
    });
    const claves = _mermasAgrupar === 'ESTADO'
      ? ORDEN_EST.filter(k => grupos[k])
      : Object.keys(grupos);   // ya vienen ordenadas por fecha desc del server
    $('mermasLista').innerHTML = claves.map(k =>
      `<div class="card" style="margin-top:10px"><div class="slab" style="margin-bottom:8px">${k} · ${grupos[k].length}</div>${grupos[k].map(fila).join('')}</div>`).join('');
  }

  // ── 🎯 SORPRESAS · SOLO SEGUIMIENTO (el registro vive en WH — decisión dueño) ──
  async function abrirSorpresasPanel() {
    openModal('modalSorpresas');
    _sorpCargar();
  }
  async function _sorpCargar() {
    $('sorpLista').innerHTML = '<div class="muted" style="text-align:center;padding:16px">Cargando…</div>';
    let rows = [];
    try {
      const r = await API.rpcWH('sorpresas_lista', { dias: 30 });
      rows = (r && r.ok && Array.isArray(r.data)) ? r.data : [];
    } catch (_) {}
    _sorpRender(rows);
  }
  function _sorpRender(rows) {
    const semana = rows.filter(s => (Date.now() - new Date(s.ts).getTime()) < 7 * 864e5);
    const conRes = rows.filter(s => s.estado !== 'ESPERANDO');
    const pasadas = conRes.filter(s => s.estado === 'PASO').length;
    $('sorpKpis').innerHTML = `<div class="kpi" style="margin-top:12px">
      <div class="k"><div class="kv" style="color:#fcd34d">${semana.length}</div><div class="kl">esta semana</div></div>
      <div class="k"><div class="kv" style="color:#7ff0c4">${pasadas}/${conRes.length}</div><div class="kl">pasadas (30d)</div></div>
      <div class="k"><div class="kv" style="color:#fca5a5">${conRes.length - pasadas}</div><div class="kl">falladas/disc.</div></div>
      <div class="k"><div class="kv">${conRes.length ? Math.round(pasadas / conRes.length * 100) + '%' : '—'}</div><div class="kl">confiabilidad</div></div>
    </div>`;
    // score por operador (30d)
    const porOp = {};
    conRes.forEach(s => {
      const op = s.operador || '—';
      porOp[op] = porOp[op] || { t: 0, p: 0 };
      porOp[op].t++; if (s.estado === 'PASO') porOp[op].p++;
    });
    const ops = Object.entries(porOp).sort((a, b) => b[1].t - a[1].t);
    $('sorpScore').innerHTML = ops.length ? `<div class="card"><div class="slab" style="margin-bottom:8px">Score por operador (30d)</div>` +
      ops.map(([op, v]) => {
        const pct = Math.round(v.p / v.t * 100);
        return `<div class="prow" style="padding:8px 12px"><b style="color:#eaf1fb">${_esc(op)}</b><span style="margin-left:auto" class="chip ${pct >= 80 ? 'ok' : (pct >= 50 ? 'warn' : 'bad')}">${v.p}/${v.t} · ${pct}%${pct < 80 ? ' ⚠' : ''}</span></div>`;
      }).join('') + `</div>` : '';
    // historial AGRUPADO POR FECHA (seguimiento) con alertas visuales por estado
    const _diaLbl = ts => {
      const d = new Date(ts); const hoy = new Date();
      const d0 = d.toDateString(), h0 = hoy.toDateString();
      const ayer = new Date(hoy.getTime() - 864e5).toDateString();
      if (d0 === h0) return 'Hoy';
      if (d0 === ayer) return 'Ayer';
      return d.toLocaleDateString('es-PE', { weekday: 'short', day: '2-digit', month: 'short' });
    };
    const grupos = {};
    rows.slice().sort((a, b) => new Date(b.ts) - new Date(a.ts))
      .forEach(x => { const k = _diaLbl(x.ts); (grupos[k] = grupos[k] || []).push(x); });
    const fila = s => {
      const esFallo = s.estado === 'FALLO';
      const esDisc = s.estado === 'DISCREPANCIA';
      const chip = s.estado === 'PASO' ? `<span class="chip ok">✅ PASÓ${s.operador ? ' · ' + _esc(s.operador) : ''}</span>`
        : esFallo ? `<span class="chip bad">❌ FALLÓ${s.operador ? ' · ' + _esc(s.operador) + ' copió el papel (' + (s.cantRegistrada ?? '—') + ')' : ''}</span>`
        : esDisc ? `<span class="chip warn">⚠️ discrepancia (${s.cantRegistrada ?? '—'})</span>`
        : '<span class="chip warn">⏳ esperando recepción</span>';
      const monto = (s.costo || 0) > 0 ? ` · S/${(Math.abs(s.delta) * s.costo).toFixed(2)}` : '';
      const borde = esFallo ? 'border-color:rgba(239,68,68,.5);background:rgba(239,68,68,.05)'
        : esDisc ? 'border-color:rgba(245,184,73,.4)' : '';
      return `<div class="prow" style="padding:9px 12px;${borde}">
        <div style="flex:1;min-width:160px"><b style="color:#eaf1fb">${_esc(s.codProducto)}</b> <span class="chip gold">${s.delta > 0 ? '+' : ''}${s.delta}</span>
        <div class="muted" style="font-size:10px">${_esc(s.idGuia)} · ${_esc(s.idZona || '')} · ${new Date(s.ts).toLocaleTimeString('es-PE', { hour: '2-digit', minute: '2-digit' })} · admin ${_esc(s.admin || '—')} · papel ${s.cantOriginal} → real ${s.cantCorregida}${monto}</div></div>
        ${chip}</div>`;
    };
    $('sorpLista').innerHTML = rows.length
      ? Object.entries(grupos).map(([dia, lista]) => `<div class="card"><div class="slab" style="margin-bottom:8px">${dia} · ${lista.length}</div>${lista.map(fila).join('')}</div>`).join('')
      : '<div class="card"><div class="muted" style="text-align:center;padding:14px">Sin sorpresas en 30 días.</div></div>';
  }
  function renderZona() {
    const cont = $('zonaLista');
    if (!cont) return;
    // [976] 5ª pestaña "🆕 Por activar": ruta de render PROPIA (huecos de surtido), NO el panel normal.
    //   Corta acá y delega en _zonaRenderPorActivar (que consume S._zonaPorActivar, no S.zonaProductos).
    if ((S._zonaFiltros || {}).kpi === 'c_activar') { _zonaRenderPorActivar(); return; }
    const f = S._zonaFiltros;
    // [927] Asegura la meta demand-flow del grupo almacén (deuda → Pedir ya). Async + cacheado: la 1ª vez
    //   repinta cuando llega; luego usa cache. No bloquea el render actual.
    try { _zonaAlmDemAsegurar(); } catch (_) {}
    let arr = S.zonaProductos.slice();
    // [924] I-11: las presentaciones-huérfanas de granel (fracción sin canónico) las representa su granel;
    //   no se listan como ítem de reposición aparte (evita doble conteo / "muerto" fantasma).
    arr = arr.filter(x => !_zonaEsPresentacionGranel(x));

    // Filtros
    if (f.q) {
      const q = f.q.toLowerCase();
      arr = arr.filter(p => (String(p.descripcion||p.nombre||'').toLowerCase().indexOf(q) >= 0) || (String(p.skuBase||'').toLowerCase().indexOf(q) >= 0));
    }
    if (f.brecha) arr = arr.filter(p => _zonaNum(p.brecha) > 0);
    const tendActivas = Object.keys(f.tend).filter(k => f.tend[k]);
    if (tendActivas.length) {
      arr = arr.filter(p => {
        // [MEJORA 4] La chip "∅ Sin rotar" (nula) filtra por item.rotacionCero (no por tendencia).
        if (_zonaEsRotCero(p)) return tendActivas.indexOf('nula') >= 0;
        const t = String(p.tendencia||'').toLowerCase();
        const norm = (t === 'ascendente') ? 'asc' : (t === 'descendente') ? 'desc' : (t === 'estable') ? 'est' : (t === 'cero') ? 'nula' : t;
        return tendActivas.indexOf(norm) >= 0;
      });
    }
    // [899] la vital ACTIVA es la pestaña: se muestra ese cuadrante. Al buscar (q), se ignora el
    //   cuadrante y se busca en TODO (para encontrar el producto donde sea que esté).
    const _cuadActivo = { c_pedir: 'pedir', c_muerto: 'muerto', c_sobra: 'sobra', c_orden: 'orden' }[f.kpi];
    // [913] Modo "recontar negativos": muestra TODOS los negativos (ignora cuadrante y búsqueda de tab).
    if (S._zonaSoloNeg) arr = arr.filter(_zonaTieneNeg);
    else if (!f.q && _cuadActivo) arr = arr.filter(p => _zonaCuadDe(p) === _cuadActivo);

    // Orden
    if (f.orden === 'brecha')  { const _pc = f.q ? null : _cuadActivo; arr.sort((a,b) => _zonaPrioridad(b, _pc) - _zonaPrioridad(a, _pc)); }   // [912] prioridad por cuadrante
    else if (f.orden === 'rotacion') arr.sort((a,b) => _zonaNum(b.rotacion) - _zonaNum(a.rotacion));
    else if (f.orden === 'az')    arr.sort((a,b) => String(a.descripcion||a.nombre||'').localeCompare(String(b.descripcion||b.nombre||'')));
    else if (f.orden === 'tendencia') arr.sort((a,b) => _zonaTendRank(b.tendencia) - _zonaTendRank(a.tendencia));

    const stats = $('zonaStats');
    if (stats) stats.textContent = `${arr.length} de ${S.zonaProductos.length} productos`;

    const _CUAD_VACIO = {
      c_pedir:  ['🎉', '¡Nada por pedir!', 'Todo tu stock accionable está cubierto.'],
      c_muerto: ['✨', 'Sin muertos', 'No hay stock parado sin rotación.'],
      c_sobra:  ['👌', 'Nada te sobra', 'Ningún producto con exceso de stock.'],
      c_orden:  ['—', 'Nada aquí', 'Sin productos en este estado.'],
    };
    if (!arr.length) {
      const v = _CUAD_VACIO[f.kpi] || ['🏪', 'Sin productos', f.q ? 'Prueba otra búsqueda.' : 'Nada en este estado.'];
      cont.innerHTML = `<div class="zona-empty"><div class="zona-empty-ic">${v[0]}</div><div class="zona-empty-t">${v[1]}</div><div class="zona-empty-s">${v[2]}</div></div>`;
      try { _zonaCacheVitales(); } catch (_) {}
      try { _zonaNegBannerRender(); } catch (_) {}
      return;
    }

    // [899] Las VITALES mandan: se muestra UN cuadrante a la vez (la pestaña activa), sin grupos apilados.
    //   arr ya viene filtrado al cuadrante activo (o a la búsqueda). Render plano y limpio; muere el
    //   control Todos/Día + el botón imprimir (eran del modelo viejo de 2 grupos).
    const esAlmacen = _esZonaAlmacen({ idZona: S.zonaActual,
      nombre: ((S.zonaList || []).find(x => (x.idZona || x.id || x.nombre) === S.zonaActual) || {}).nombre });
    cont.innerHTML = arr.map(_zonaCardHtml).join('');
    try { _zonaCacheVitales(); } catch (_) {}   // [893] cachear conteo de cuadrantes para el hub
    try { _zonaNegBannerRender(); } catch (_) {}   // [913] banner "recontar negativos"
    try { _zonaCruzadoEnsure(); } catch (_) {}   // [921] carga (lazy) el stock de la otra zona (foquito)
    // [RIZ UX] Stagger de entrada: solo las primeras ~20 cards reciben delay incremental
    // (cap para no demorar con 800 items; el resto aparece directo vía CSS nth-child).
    // Recorremos solo .zona-card (el separador no anima) para que el índice de delay sea correcto.
    if (!_zonaReduce()) {
      const cards = cont.querySelectorAll('.zona-card'), cap = Math.min(20, cards.length);
      for (let i = 0; i < cap; i++) { try { cards[i].style.setProperty('--i', i); } catch (_) {} }
    }
    // [RIZ CARRITO] el FAB/badge reflejan el carrito de la zona tras cada render (cards reconstruidos).
    try { _zonaCarritoSync(); } catch (_) {}
    // [RIZ #4] En ALMACEN, completar las cards con sus proveedores reales (1 RPC batch, no bloqueante).
    if (esAlmacen) { try { _zonaProvCargarVisibles(); } catch (_) {} try { _zonaGranelCargarVisibles(); } catch (_) {} }
  }
  // ════════════════════════════════════════════════════════════════════
  // [976] 🆕 POR ACTIVAR — 5ª pestaña del módulo Zona.
  //   HUECOS DE SURTIDO: productos del catálogo SIN stock en la zona activa pero con presencia en otra
  //   zona o en el almacén (para ALMACEN: con demanda de las zonas = hueco de compra). El admin les pone
  //   un stock inicial (→ ajuste) para activarlos, o los descarta por zona ("no aplica aquí").
  //   Backend (contrato fijo): mos.zona_por_activar (lectura) / mos.zona_por_activar_descartar (escritura).
  //   Fuente de verdad de la lista = S._zonaPorActivar (cache por zona); mutaciones OPTIMISTAS con rollback.
  //   renderZona corta hacia _zonaRenderPorActivar cuando la pestaña activa es 'c_activar'.
  // ════════════════════════════════════════════════════════════════════
  // Prioridad → clase de color reutilizada de los cuadrantes (P3 verde=orden · P2 ámbar=sobra · P1 gris=muerto).
  function _zonaPaCuadClase(prio) {
    const p = _zonaNum(prio);
    return p >= 3 ? 'zona-cuad-orden' : (p === 2 ? 'zona-cuad-sobra' : 'zona-cuad-muerto');
  }
  // Refresca SOLO el badge de conteo del 5º tab = huecos ACTIVOS (no descartados) de la zona en cache.
  //   Se calcula desde los items (robusto ante la semántica de total/nDescartados del RPC). '—' si no hay cache.
  function _zonaPaActualizarBadge() {
    const el = $('zKpiActivar');
    if (!el) return;
    const pa = S._zonaPorActivar || {};
    if (!(pa._cargado && pa.zona === S.zonaActual)) { el.textContent = '—'; return; }
    el.textContent = String((pa.items || []).filter(x => !x.descartado).length);
  }
  // Carga (o recarga) los huecos de la zona activa. silent=true → solo actualiza cache+badge (precarga al abrir
  //   el panel, sin tocar la lista salvo que el 5º tab ya esté activo). Respeta el toggle "Ver descartados".
  async function _zonaPorActivarCargar(force, silent) {
    const zona = S.zonaActual;
    const pa = S._zonaPorActivar || (S._zonaPorActivar = { zona:null, items:[], nDescartados:0, cargando:false, verDescartados:false, _cargado:false, _verCargado:false });
    if (pa.cargando) return;
    const modoOk = pa._cargado && pa.zona === zona && (!!pa._verCargado === !!pa.verDescartados);
    if (!force && modoOk) { if (!silent) _zonaRenderPorActivar(); return; }
    pa.cargando = true;
    if (!silent && S._zonaFiltros.kpi === 'c_activar') _zonaRenderPorActivar();   // pinta skeleton
    try {
      const r = await API.zona.porActivar({ zona, incluirDescartados: !!pa.verDescartados });
      // La zona pudo cambiar mientras esperábamos → descartar respuesta vieja.
      if (S.zonaActual !== zona) { pa.cargando = false; return; }
      const data = (r && r.data) || {};
      pa.zona = zona;
      pa.items = Array.isArray(data.items) ? data.items : [];
      pa.nDescartados = _zonaNum(data.nDescartados);
      pa._cargado = true;
      pa._verCargado = !!pa.verDescartados;
      pa.cargando = false;
      _zonaPaActualizarBadge();
      if (S._zonaFiltros.kpi === 'c_activar') _zonaRenderPorActivar();
    } catch (e) {
      pa.cargando = false;
      if (!silent && S._zonaFiltros.kpi === 'c_activar') {
        const cont = $('zonaLista');
        if (cont) cont.innerHTML = `<div class="zona-empty"><div class="zona-empty-ic">⚠️</div><div class="zona-empty-t">No se pudo cargar</div><div class="zona-empty-s">${_esc(e.message || String(e))}</div></div>`;
      }
    }
  }
  // Render de la lista "Por activar" (reemplaza el listado normal del panel mientras el 5º tab está activo).
  function _zonaRenderPorActivar() {
    const cont = $('zonaLista');
    if (!cont) return;
    const pa = S._zonaPorActivar || {};
    _zonaPaActualizarBadge();
    const stats = $('zonaStats');
    // Aún no cargado para esta zona → dispara la carga y muestra skeleton.
    if (!pa._cargado || pa.zona !== S.zonaActual || pa.cargando) {
      if (!pa.cargando) _zonaPorActivarCargar(false);
      cont.innerHTML = _zonaSkelCards(3);
      if (stats) stats.textContent = 'Buscando huecos de surtido…';
      return;
    }
    const items = Array.isArray(pa.items) ? pa.items : [];
    const activos = items.filter(x => !x.descartado).length;
    const desc = items.filter(x => x.descartado).length;
    if (stats) stats.textContent = `${activos} ${activos === 1 ? 'hueco' : 'huecos'} por activar${pa.verDescartados ? ' · ' + desc + ' descartados' : ''}`;
    const head = `<div class="zona-pa-head">
        <div class="zona-pa-intro">🆕 Productos del catálogo <b>sin stock en esta zona</b> pero con presencia en otra zona o el almacén. Ponles un stock inicial para activarlos aquí.</div>
        <button class="zona-btn-sec zona-pa-toggle${pa.verDescartados ? ' zona-accion-on' : ''}" onclick="MOS.zonaPorActivarVerDescartados()">${pa.verDescartados ? 'Ocultar descartados' : 'Ver descartados'}</button>
      </div>`;
    if (!items.length) {
      cont.innerHTML = head + `<div class="zona-empty"><div class="zona-empty-ic">✅</div><div class="zona-empty-t">Sin huecos por activar</div><div class="zona-empty-s">Esta zona ya tiene todo su surtido con stock.</div></div>`;
      return;
    }
    cont.innerHTML = head + items.map(_zonaPaCardHtml).join('');
    // Stagger de entrada (igual que las cards del panel): solo las primeras ~20.
    if (!_zonaReduce()) {
      const cards = cont.querySelectorAll('.zona-card'), cap = Math.min(20, cards.length);
      for (let i = 0; i < cap; i++) { try { cards[i].style.setProperty('--i', i); } catch (_) {} }
    }
  }
  // HTML de una card "Por activar". Reutiliza el look de las cards de zona (.zona-card + color por cuadrante),
  //   badges .zona-rotcero-chip para las señales y los botones .zona-btn-pedir/.zona-btn-sec para las acciones.
  function _zonaPaCardHtml(item) {
    const sku  = String(item.skuBase || '');
    const safe = _esc(sku);
    const e    = _zonaEsc(sku);
    const nm   = _esc(item.descripcion || sku);
    const uni  = _esc(item.unidad || '');
    const cuadCls = _zonaPaCuadClase(item.prioridad);
    const descartado = !!item.descartado;
    const esAlm = _zonaEsAlmacen();
    // Chips de señales (cantidades con _zonaFmtNumRaw = hasta 3 decimales solo si existen; NUNCA _money).
    let chips = '';
    if (item.enAlmacen) chips += `<span class="zona-rotcero-chip" style="background:rgba(99,102,241,.14);border-color:rgba(129,140,248,.5);color:#a5b4fc" title="Hay stock en el almacén">📦 Almacén: ${_esc(_zonaFmtNumRaw(item.stockAlmacen))}</span>`;
    if (_zonaNum(item.rotaOtras) > 0) chips += `<span class="zona-rotcero-chip" style="background:rgba(56,189,248,.14);border-color:rgba(56,189,248,.5);color:#7dd3fc" title="${esAlm ? 'Ventas de las zonas (hueco de compra)' : 'Rota en otras zonas'}">🔁 ${esAlm ? 'Zonas' : 'Otras zonas'}: ${_esc(_zonaFmtNumRaw(item.rotaOtras))}</span>`;
    if (item.enOtraZona) chips += `<span class="zona-rotcero-chip" title="El producto ya tiene stock en otra zona">también en otra zona</span>`;
    if (!chips) chips = '<span class="zona-rotcero-chip">nuevo en catálogo</span>';
    // Acciones: descartado → Restaurar; activo → Poner stock inicial + No aplica aquí.
    const acciones = descartado
      ? `<button class="zona-btn-sec" onclick="MOS.zonaPaRestaurar('${e}')">↩ Restaurar</button>`
      : `<div class="zona-pa-acc" id="zPaAcc-${safe}">
          <button class="zona-btn-pedir" onclick="MOS.zonaPaAjuste('${e}')">➕ Poner stock inicial</button>
          <button class="zona-btn-sec" onclick="MOS.zonaPaDescartar('${e}')">No aplica aquí</button>
        </div>`;
    return `<div class="zona-card zona-pa-card ${cuadCls}${descartado ? ' zona-pa-desc' : ''}" id="zPaCard-${safe}" data-sku="${safe}">
        <div class="zona-card-top-row"><div class="zona-card-name">${nm}${uni ? ` <span class="zona-pa-uni">· ${uni}</span>` : ''}</div></div>
        <div class="zona-pa-chips">${chips}</div>
        <div class="zona-pa-actions">${acciones}</div>
      </div>`;
  }
  // Toggle de cabecera "Ver descartados" → recarga con incluirDescartados on/off.
  function zonaPorActivarVerDescartados() {
    const pa = S._zonaPorActivar || (S._zonaPorActivar = { zona:null, items:[], nDescartados:0, cargando:false, verDescartados:false, _cargado:false, _verCargado:false });
    pa.verDescartados = !pa.verDescartados;
    try { _zonaSfx('tick'); _zonaVibrar(15); } catch (_) {}
    _zonaPorActivarCargar(true);
  }
  // Despliega el input inline para poner el stock inicial (reemplaza los botones de acción del card).
  //   Usa la clase .zona-step-input → el auto-refresh se pausa mientras el admin escribe (no pisa la edición).
  function zonaPaAjuste(sku) {
    const pa = S._zonaPorActivar || {};
    const item = (pa.items || []).find(x => String(x.skuBase) === String(sku));
    if (!item) return;
    const acc = $('zPaAcc-' + sku);
    if (!acc) return;
    const e = _zonaEsc(sku);
    const step = item.esGranel ? '0.1' : '1';
    acc.innerHTML = `<span class="zona-stepper zona-pa-stepper">
        <input type="number" inputmode="decimal" step="${step}" min="0" class="zona-step-input" id="zPaStep-${_esc(sku)}" placeholder="cantidad" onkeydown="if(event.key==='Enter')MOS.zonaPaConfirmar('${e}')">
        <button class="zona-step-btn" style="background:#16a34a;border-color:#16a34a" onclick="MOS.zonaPaConfirmar('${e}')" title="Guardar stock inicial">✓</button>
        <button class="zona-step-btn zona-step-cero" onclick="MOS.zonaPaCancelarAjuste('${e}')" title="Cancelar">✕</button>
      </span>`;
    const inp = $('zPaStep-' + sku);
    if (inp) { try { inp.focus(); } catch (_) {} }
    try { _zonaSfx('tick'); _zonaVibrar(15); } catch (_) {}
  }
  // Cancela el input inline (re-render barato restaura los botones de acción).
  function zonaPaCancelarAjuste(sku) {
    _zonaRenderPorActivar();
    try { _zonaSfx('tick'); _zonaVibrar(10); } catch (_) {}
  }
  // Confirma el stock inicial: ZONA → me.stock_zonas (set-absoluto por skuBase) · ALMACEN → wh.stock (por código).
  //   OPTIMISTA: quita el hueco de la lista al instante; rollback si el backend no commitea.
  async function zonaPaConfirmar(sku) {
    const pa = S._zonaPorActivar || {};
    const item = (pa.items || []).find(x => String(x.skuBase) === String(sku));
    if (!item) return;
    const inp = $('zPaStep-' + sku);
    const nuevo = _zonaParseCant(inp ? inp.value : 0, !!item.esGranel);
    if (!(nuevo > 0)) {
      try { _zonaSfx('error'); _zonaVibrar([80,30,80]); } catch (_) {}
      toast('Escribe una cantidad mayor a 0 para activar el producto.', 'info');
      if (inp) { try { inp.focus(); } catch (_) {} }
      return;
    }
    const zona = S.zonaActual;
    const usuario = S.session?.nombre || '';
    // localId ESTABLE por gesto (idempotencia dura en backend): un doble-tap reusa el id → no duplica el ajuste.
    const localId = 'RIZPA_' + (_zonaEsAlmacen() ? 'ALM' : (zona || 'Z')) + '_' + String(sku).replace(/[^A-Za-z0-9]/g, '') + '_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 7);
    const idx = pa.items.indexOf(item);
    if (idx >= 0) pa.items.splice(idx, 1);   // OPTIMISTA: fuera de la lista (pasará a los 4 cuadrantes en el próximo panel)
    _zonaRenderPorActivar();
    try { _zonaSfx('ok'); _zonaVibrar(30); } catch (_) {}
    toast('Stock inicial de "' + (item.descripcion || sku) + '" puesto en ' + _zonaFmtNumRaw(nuevo, item.esGranel), 'ok');
    try {
      let r;
      if (_zonaEsAlmacen()) {
        // ALMACÉN: ajuste del stock real (wh.stock) por código; el hueco trae su codBarra.
        const cod = String(item.codBarra != null ? item.codBarra : '');
        if (!cod) throw new Error('Sin código de almacén para ajustar');
        r = await API.zona.almacenAjustar({ zona, codProducto: cod, conteo: nuevo, idAjuste: localId, usuario });
      } else {
        // ZONA: set-absoluto en me.stock_zonas; el backend resuelve el canónico del skuBase.
        r = await API.zona.ajustarStock({ zona, skuBase: sku, nuevo, usuario, localId });
      }
      if (r == null || r.ok === false) throw new Error((r && r.error) || 'sin commit');
      // Éxito: refresco SILENCIOSO del panel (sin skeleton) para que el producto aparezca ya en su cuadrante.
      try { _zonaAutoRefrescar(); } catch (_) {}
    } catch (e) {
      // ROLLBACK: devolver el hueco a la lista.
      if (idx >= 0) pa.items.splice(Math.min(idx, pa.items.length), 0, item); else pa.items.push(item);
      _zonaRenderPorActivar();
      try { _zonaSfx('error'); _zonaVibrar([120,40,120]); } catch (_) {}
      toast('No se pudo activar: ' + (e.message || e), 'error');
    }
  }
  // "No aplica aquí" → descarta el hueco por zona (mos.zona_por_activar_descartar). OPTIMISTA + rollback.
  async function zonaPaDescartar(sku) {
    const pa = S._zonaPorActivar || {};
    const item = (pa.items || []).find(x => String(x.skuBase) === String(sku));
    if (!item) return;
    const zona = S.zonaActual, usuario = S.session?.nombre || '';
    const idx = pa.items.indexOf(item);
    // Mostrando descartados → marcar; si no, sacarlo de la lista.
    if (pa.verDescartados) { item.descartado = true; }
    else if (idx >= 0) { pa.items.splice(idx, 1); }
    pa.nDescartados = _zonaNum(pa.nDescartados) + 1;
    _zonaRenderPorActivar();
    try { _zonaSfx('tick'); _zonaVibrar(15); } catch (_) {}
    toast('"' + (item.descripcion || sku) + '" marcado como "no aplica aquí".', 'info');
    try {
      const r = await API.zona.porActivarDescartar({ zona, skuBase: sku, usuario });
      if (r == null || r.ok === false) throw new Error((r && r.error) || 'sin commit');
    } catch (e) {
      // ROLLBACK
      if (pa.verDescartados) { item.descartado = false; }
      else if (idx >= 0) { pa.items.splice(Math.min(idx, pa.items.length), 0, item); } else { pa.items.push(item); }
      pa.nDescartados = Math.max(0, _zonaNum(pa.nDescartados) - 1);
      _zonaRenderPorActivar();
      try { _zonaSfx('error'); _zonaVibrar([120,40,120]); } catch (_) {}
      toast('No se pudo descartar: ' + (e.message || e), 'error');
    }
  }
  // "Restaurar" (visible solo con "Ver descartados") → revierte el descarte. OPTIMISTA + rollback.
  async function zonaPaRestaurar(sku) {
    const pa = S._zonaPorActivar || {};
    const item = (pa.items || []).find(x => String(x.skuBase) === String(sku));
    if (!item) return;
    const zona = S.zonaActual, usuario = S.session?.nombre || '';
    item.descartado = false;   // OPTIMISTA
    pa.nDescartados = Math.max(0, _zonaNum(pa.nDescartados) - 1);
    _zonaRenderPorActivar();
    try { _zonaSfx('ok'); _zonaVibrar(20); } catch (_) {}
    toast('"' + (item.descripcion || sku) + '" restaurado a los huecos por activar.', 'ok');
    try {
      const r = await API.zona.porActivarDescartar({ zona, skuBase: sku, usuario, revertir: true });
      if (r == null || r.ok === false) throw new Error((r && r.error) || 'sin commit');
    } catch (e) {
      item.descartado = true;   // ROLLBACK
      pa.nDescartados = _zonaNum(pa.nDescartados) + 1;
      _zonaRenderPorActivar();
      try { _zonaSfx('error'); _zonaVibrar([120,40,120]); } catch (_) {}
      toast('No se pudo restaurar: ' + (e.message || e), 'error');
    }
  }

  // ¿El item es "rotación cero"? Fuente de verdad = backend item.rotacionCero (bool).
  // Fallback tolerante (datos viejos sin el campo): rotacion===0.
  function _zonaEsRotCero(p) {
    if (p && p.grupo != null) return String(p.grupo).toUpperCase() === 'PARADO';   // fuente nueva (176): grupo
    if (p && p.rotacionCero != null) return !!p.rotacionCero;
    // sin grupo ni rotacionCero: usa volumen (176) o rotacion (legado) — 0 ⇒ no rotó.
    const vol = (p && p.volumen != null) ? _zonaNum(p.volumen) : _zonaNum(p && p.rotacion);
    return vol === 0;
  }
  // ── [GRUPOS COLAPSABLES] ──────────────────────────────────────────────────
  // ¿El item va al grupo PARADO? Fuente de verdad = item.grupo del backend ('ROTADO'/'PARADO').
  // Fallback tolerante a datos viejos: usa rotacionCero/rotacion (la antigua semántica "sin rotación").
  function _zonaEsGrupoParado(p) {
    if (p && p.grupo != null) return String(p.grupo).toUpperCase() === 'PARADO';
    return _zonaEsRotCero(p);
  }
  // Clave de localStorage del estado colapsado por (zona, grupo) — recuerda la preferencia entre refrescos.
  function _zonaGrpLsKey(grpKey) { return 'rizGrp_' + (S.zonaActual || '_') + '_' + grpKey; }
  function _zonaGrupoColapsado(grpKey, def) {
    try { const v = localStorage.getItem(_zonaGrpLsKey(grpKey)); if (v === '1') return true; if (v === '0') return false; return !!def; } catch (_) { return !!def; }
  }
  // HTML de un grupo (encabezado clickeable + cuerpo con sus cards). Si está vacío tras filtros → se colapsa
  // y muestra "0" elegante. El chevron rota al colapsar (clase .collapsed en head y body).
  function _zonaGrupoHtml(g) {
    const n = g.arr.length;
    // Un grupo vacío arranca colapsado siempre (no estorba); si tiene items respeta la preferencia guardada.
    const colapsado = (n === 0) ? true : _zonaGrupoColapsado(g.key, g.defColapsado);
    const colCls = colapsado ? ' collapsed' : '';
    const chev = `<svg class="zona-grp-chev" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><polyline points="6 9 12 15 18 9"></polyline></svg>`;
    const body = n
      ? g.arr.map(_zonaCardHtml).join('')
      : `<div class="zona-grp-empty">Sin productos en este grupo</div>`;
    // [RIZ #1+#2] El grupo ROTADO lleva el control "Todos | Día" + flechas + ícono imprimir, al lado del contador.
    const ctrl = g.esRotado ? _zonaDiaControlHtml() : '';
    return `<div class="zona-grp" data-grp="${g.key}">`
      + `<div class="zona-grp-head ${g.cls}${colCls}" role="button" tabindex="0" aria-expanded="${colapsado ? 'false' : 'true'}" `
      +      `onclick="MOS.zonaToggleGrupo('${g.key}')" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();MOS.zonaToggleGrupo('${g.key}');}">`
      +   chev
      +   `<span class="zona-grp-ico" aria-hidden="true">${g.ico}</span>`
      +   `<span class="zona-grp-lbl">${_esc(g.lbl)}</span>`
      +   `<span class="zona-grp-count">${n}</span>`
      +   ctrl
      + `</div>`
      + `<div class="zona-grp-body${colCls}">${body}</div>`
      + `</div>`;
  }
  // [RIZ #1+#2] Control del grupo ROTADO: segmento "Todos | Día" + flechas ◀ ▶ + día activo + ícono imprimir.
  //   Todos los onclick hacen stopPropagation para NO disparar el colapso del grupo. Triple feedback en cada acción.
  function _zonaDiaControlHtml() {
    const modo = (S._zonaDiaFiltro && S._zonaDiaFiltro.modo) || 'todos';
    const enDia = modo === 'dia';
    const stop = 'event.stopPropagation();';
    const seg = `<div class="zona-dia-seg" role="group" aria-label="Filtro del día">`
      + `<button type="button" class="zona-dia-segbtn${enDia ? '' : ' on'}" aria-pressed="${enDia ? 'false' : 'true'}" `
      +   `onclick="${stop}MOS.zonaDiaModo('todos')" title="Mostrar todo el grupo">Todos</button>`
      + `<button type="button" class="zona-dia-segbtn${enDia ? ' on' : ''}" aria-pressed="${enDia ? 'true' : 'false'}" `
      +   `onclick="${stop}MOS.zonaDiaModo('dia')" title="Solo la tanda de un día (igual que el ticket)">Día</button>`
      + `</div>`;
    const nav = enDia
      ? `<div class="zona-dia-nav">`
        + `<button type="button" class="zona-dia-arrow" aria-label="Día anterior" onclick="${stop}MOS.zonaDiaNav(-1)" title="Día anterior">◀</button>`
        + `<span class="zona-dia-lbl" title="Día activo de la partición (anclado al lunes)">${_esc(_zonaDiaLabel())}</span>`
        + `<button type="button" class="zona-dia-arrow" aria-label="Día siguiente" onclick="${stop}MOS.zonaDiaNav(1)" title="Día siguiente">▶</button>`
        + `</div>`
      : '';
    const print = `<button type="button" class="zona-dia-print" aria-label="Imprimir ticket" `
      + `onclick="${stop}MOS.zonaImprimirTicketGrupo()" title="${enDia ? 'Imprimir el ticket de este día (80mm)' : 'Imprimir el ticket de hoy (80mm)'}">🖨️</button>`;
    return `<div class="zona-dia-ctrl" onclick="event.stopPropagation();">${seg}${nav}${print}</div>`;
  }
  // [RIZ #1] Cambiar modo Todos/Día. En 'dia' cargamos la tanda del backend (coincide con el ticket) y re-render.
  async function zonaDiaModo(modo) {
    if (!S._zonaDiaFiltro) S._zonaDiaFiltro = { modo: 'todos', offset: 0 };
    if (S._zonaDiaFiltro.modo === modo) { _zonaSfx('tick'); _zonaVibrar(10); return; }
    S._zonaDiaFiltro.modo = modo;
    if (modo === 'todos') S._zonaDiaFiltro.offset = 0;   // resetear al salir
    _zonaSfx('pop'); _zonaVibrar(15);
    if (modo === 'dia') { await _zonaDiaCargarSet(); }
    renderZona();
  }
  // [RIZ #1] Navegar días (◀ −1 / ▶ +1). Recarga la tanda de la nueva fecha y re-render.
  //   Límites razonables: la ventana del panel es "últimas 4 semanas" (28d) → permitimos −28..0
  //   (no hay tanda histórica más vieja que eso, ni futura: mañana+ no tiene ventas/despachos aún).
  //   Si el offset ya está en el tope y se intenta pasar → tick + no-op (no recarga ni re-render inútil).
  async function zonaDiaNav(delta) {
    if (!S._zonaDiaFiltro) S._zonaDiaFiltro = { modo: 'dia', offset: 0 };
    const MIN = -28, MAX = 0;
    const cur = S._zonaDiaFiltro.offset || 0;
    const next = Math.max(MIN, Math.min(MAX, cur + (delta < 0 ? -1 : 1)));
    if (next === cur) { try { _zonaSfx('tick'); _zonaVibrar(8); } catch (_) {} return; }   // ya en el tope
    S._zonaDiaFiltro.offset = next;
    _zonaSfx('tick'); _zonaVibrar(delta < 0 ? [12, 8] : 14);
    await _zonaDiaCargarSet();
    renderZona();
  }
  // Colapsa/expande un grupo (acordeón). Persiste en localStorage. Triple feedback táctil (SFX + vibración).
  function zonaToggleGrupo(grpKey) {
    const wrap = document.querySelector('.zona-grp[data-grp="' + grpKey + '"]');
    if (!wrap) return;
    const head = wrap.querySelector('.zona-grp-head');
    const bodyEl = wrap.querySelector('.zona-grp-body');
    if (!head || !bodyEl) return;
    const colapsar = !head.classList.contains('collapsed');
    head.classList.toggle('collapsed', colapsar);
    bodyEl.classList.toggle('collapsed', colapsar);
    head.setAttribute('aria-expanded', colapsar ? 'false' : 'true');
    try { localStorage.setItem(_zonaGrpLsKey(grpKey), colapsar ? '1' : '0'); } catch (_) {}
    try { _zonaSfx('tick'); _zonaVibrar(12); } catch (_) {}
  }
  function _zonaTendRank(t) { t = String(t||'').toLowerCase(); if (t==='asc'||t==='ascendente') return 3; if (t==='est'||t==='estable') return 2; if (t==='desc'||t==='descendente') return 1; return 0; }

  // [893] Cuadrante de un producto (única fuente para card Y vitales del hub → nunca se desincronizan).
  const _CUAD_META = { pedir: ['🔴', 'Pedir ya'], orden: ['🟢', 'Al día'], sobra: ['🟡', 'Te sobra'], muerto: ['⚫', 'Muerto · no rota'] };
  // [916] META INTELIGENTE: proyecta la semana que viene mirando la TENDENCIA de las 4 semanas, no solo
  //   el pico de la última. Peso mayor a lo reciente; si sube proyecta hacia arriba, si baja usa el
  //   promedio ponderado (para no sobre-stockear un producto que muere). + colchón. Devuelve 0 si no hay data.
  function _zonaMetaSmart(picos, colchon) {
    const p = (Array.isArray(picos) ? picos : []).map(_zonaNum);
    if (!p.length) return 0;
    const col = (colchon == null ? 0.20 : colchon);
    const last = p[p.length - 1];
    // Sin historial REAL (menos de 2 semanas con venta) → como antes: último pico × colchón. Evita
    //   sobre-proyectar la venta mayorista en picos (ej. 0,0,0,48 no debe volverse 77).
    if (p.filter(v => v > 0).length < 2) return Math.ceil(Math.max(0, last) * (1 + col));
    let wsum = 0, w = 0; p.forEach((v, i) => { const wi = i + 1; wsum += v * wi; w += wi; });
    const avgPond = w > 0 ? wsum / w : last;
    const maxPk = Math.max(...p);
    const slope = (last - p[0]) / (p.length - 1);
    let base = Math.min(maxPk, Math.max(last, avgPond));                       // nunca por debajo de lo que vendes
    if (slope > 0.05 * Math.max(1, last)) base = Math.min(maxPk * 1.25, Math.max(base, last + Math.max(0, slope))); // sube: proyecta, capeado
    else if (slope < -0.05 * Math.max(1, last)) base = Math.max(last, avgPond * 0.9);                                // baja: no sobre-stockear
    return Math.ceil(Math.max(0, base) * (1 + col));
  }
  // [925] Espejo EXACTO de _zonaMetaSmart que además devuelve el desglose para EXPLICARLO en el gráfico
  //   (el "¿Por qué?" mostraba la regla VIEJA "última × 1.2"; ahora dice lo que de verdad hace).
  function _zonaMetaExplain(picos, colchon) {
    const p = (Array.isArray(picos) ? picos : []).map(_zonaNum);
    const col = (colchon == null ? 0.20 : colchon);
    if (!p.length) return { meta: 0, modo: 'sin' };
    const last = p[p.length - 1];
    const nz = p.filter(v => v > 0).length;
    if (nz < 2) return { meta: Math.ceil(Math.max(0, last) * (1 + col)), modo: 'pobre', last, col };
    let wsum = 0, w = 0; p.forEach((v, i) => { const wi = i + 1; wsum += v * wi; w += wi; });
    const avgPond = w > 0 ? wsum / w : last;
    const maxPk = Math.max(...p);
    const slope = (last - p[0]) / (p.length - 1);
    let base = Math.min(maxPk, Math.max(last, avgPond)), modo = 'est';
    if (slope > 0.05 * Math.max(1, last)) { base = Math.min(maxPk * 1.25, Math.max(base, last + Math.max(0, slope))); modo = 'asc'; }
    else if (slope < -0.05 * Math.max(1, last)) { base = Math.max(last, avgPond * 0.9); modo = 'desc'; }
    return { meta: Math.ceil(Math.max(0, base) * (1 + col)), modo, last, avgPond, maxPk, base, col };
  }
  // Texto humano del cálculo de la meta, fiel al método (promedio ponderado + tendencia + colchón).
  function _zonaMetaExplicaHtml(p, esp) {
    const ex = _zonaMetaExplain(p && p.picos, 0.20);
    const f = (v) => _esc(_zonaFmtNumRaw(v, p && p.esGranel));
    const pc = Math.round((ex.col != null ? ex.col : 0.20) * 100);
    let tend;
    if (ex.modo === 'pobre') tend = `Aún hay <b>menos de 2 semanas</b> con movimiento → tomamos la <b>última</b> (${f(ex.last)}) y le sumamos ${pc}% de colchón.`;
    else if (ex.modo === 'asc') tend = `📈 <b>Va en subida.</b> Promedio ponderado de las 4 semanas (lo reciente pesa más) = <b>${f(ex.avgPond)}</b>; como sube, <b>proyectamos hacia arriba</b> hasta <b>${f(ex.base)}</b> (tope: pico×1.25 = ${f(ex.maxPk * 1.25)}).`;
    else if (ex.modo === 'desc') tend = `📉 <b>Va en bajada.</b> Usamos el promedio reciente ×0.9 = <b>${f(ex.base)}</b> (para no sobre-stockear algo que cae), nunca por debajo de lo último (${f(ex.last)}).`;
    else tend = `➡️ <b>Estable.</b> Tomamos lo mayor entre lo que vendes (${f(ex.last)}) y el promedio ponderado (${f(ex.avgPond)}), sin pasar el pico → <b>${f(ex.base)}</b>.`;
    return `<div class="esp-tend">${tend}</div><div class="esp-nums">Meta = redondear(${ex.modo === 'pobre' ? 'última' : 'base'} × ${(1 + (ex.col != null ? ex.col : 0.20)).toFixed(1).replace(/\.0$/, '')}) = <b class="esp-res">${_esc(_zonaFmtCant(esp, p, true))}</b></div>`;
  }
  // Meta efectiva del producto. En ALMACÉN = demand-flow (despacho+envasado+deuda propia+deuda derivados,
  //   RPC 927 bulk, proyección de 1 semana). En ZONAS = la inteligente por picos (venta diaria).
  function _zonaMetaDe(p) {
    if (_zonaActualEsAlmacen()) {
      const d = (S._zonaAlmDem || {})[String((p && (p.skuBase || p.idProducto)) || '').toUpperCase()];
      // [931] META de almacén = smart(DEMANDA SEMANAL). `sem` ya trae, por semana, despacho + envasado +
      //   deuda propia + deuda de derivados → el smart analiza el comportamiento (la deuda vieja pesa
      //   menos sola, por estar en semanas viejas). No se suma la deuda total de golpe.
      if (d) return _zonaMetaSmart(d.sem, 0.20);
    }
    const m = _zonaMetaSmart(p && p.picos, 0.20);
    return m > 0 ? m : _zonaNum(p && (p.esperada != null ? p.esperada : p.esperado));
  }
  // ¿El producto de almacén tiene DEMANDA INSATISFECHA (deuda rezagada, propia o de derivados)?
  function _zonaAlmTieneDeuda(p) {
    if (!_zonaActualEsAlmacen()) return false;
    const d = (S._zonaAlmDem || {})[String((p && (p.skuBase || p.idProducto)) || '').toUpperCase()];
    return !!(d && (_zonaNum(d.pend) + _zonaNum(d.pendDeriv)) > 0);
  }
  // [911] Stock EFECTIVO = suma de códigos en positivo (un código negativo cuenta 0, NO resta).
  function _zonaEffStock(p) {
    const cods = Array.isArray(p.codigos) ? p.codigos : [];
    return cods.length ? cods.reduce((a, c) => a + Math.max(0, _zonaNum(c.stock)), 0) : Math.max(0, _zonaNum(p.stockZona != null ? p.stockZona : p.stock));
  }
  // [924] DETECCIÓN (backlog #1): ¿el producto se alimenta por ENVASADO?
  //   - Granel ENVASABLE = alguien lo tiene como codigoProductoBase con factorConversionBase>0 (es padre de un derivado).
  //   - INSUMO = esInsumo (celofanes). Ambos casi no rotan por despacho, pero SE CONSUMEN al envasar.
  //   Fuente: catálogo ya cargado (S.productos), memoizado por tamaño.
  let _zonaEnvSet = null, _zonaEnvLen = -1, _zonaInsSet = null, _zonaInsLen = -1;
  function _zonaEnvasableSet() {
    const ps = Array.isArray(S.productos) ? S.productos : [];
    if (_zonaEnvSet && _zonaEnvLen === ps.length) return _zonaEnvSet;
    const set = new Set();
    ps.forEach(d => { const b = String(d.codigoProductoBase || '').trim().toUpperCase(); if (b && (parseFloat(d.factorConversionBase) || 0) > 0) set.add(b); });
    _zonaEnvSet = set; _zonaEnvLen = ps.length; return set;
  }
  function _zonaInsumoSet() {
    const ps = Array.isArray(S.productos) ? S.productos : [];
    if (_zonaInsSet && _zonaInsLen === ps.length) return _zonaInsSet;
    const set = new Set();
    ps.forEach(x => { if (x.esInsumo == '1' || x.esInsumo === true) { const a = String(x.skuBase || '').trim().toUpperCase(); if (a) set.add(a); const b = String(x.idProducto || '').trim().toUpperCase(); if (b) set.add(b); } });
    _zonaInsSet = set; _zonaInsLen = ps.length; return set;
  }
  function _zonaEsGranelEnvasable(p) {
    const set = _zonaEnvasableSet();
    const a = String(p && p.skuBase || '').trim().toUpperCase();
    const b = String(p && p.idProducto || '').trim().toUpperCase();
    return (!!a && set.has(a)) || (!!b && set.has(b));
  }
  // [930] ¿Es un DERIVADO? (se ENVASA del granel padre, NO se compra al proveedor). Tiene codigoProductoBase.
  function _zonaEsDerivado(p) { return !!(p && p.codigoProductoBase && String(p.codigoProductoBase).trim()); }
  function _zonaGranelPadreNombre(p) {
    const base = String(p && p.codigoProductoBase || '').trim().toUpperCase(); if (!base) return '';
    const ps = Array.isArray(S.productos) ? S.productos : [];
    const g = ps.find(x => (String(x.skuBase || '').trim().toUpperCase() === base || String(x.idProducto || '').trim().toUpperCase() === base)
      && (parseFloat(x.factorConversion) || 1) === 1 && !String(x.codigoProductoBase || '').trim());
    return g ? (g.descripcion || g.nombre || '') : '';
  }
  function _zonaEsInsumo(p) {
    const set = _zonaInsumoSet();
    const a = String(p && p.skuBase || '').trim().toUpperCase();
    const b = String(p && p.idProducto || '').trim().toUpperCase();
    return (!!a && set.has(a)) || (!!b && set.has(b));
  }
  function _zonaSeEnvasa(p) { return _zonaEsGranelEnvasable(p) || _zonaEsInsumo(p); }
  function _zonaActualEsAlmacen() {
    return _esZonaAlmacen({ idZona: S.zonaActual, nombre: ((S.zonaList || []).find(x => (x.idZona || x.id || x.nombre) === S.zonaActual) || {}).nombre });
  }
  // [927] Carga (una vez, cache 2 min) la META demand-flow de TODO el grupo almacén → reclasifica: un
  //   producto con demanda insatisfecha (deuda) sale de "Muertos" y entra a "Pedir ya". Al llegar, re-render.
  async function _zonaAlmDemAsegurar(force) {
    try {
      if (!_zonaActualEsAlmacen()) return;
      const fresh = S._zonaAlmDemTs && (Date.now() - S._zonaAlmDemTs) < 120000;
      if (S._zonaAlmDem && fresh && !force) return;
      if (S._zonaAlmDemLoading) return;
      S._zonaAlmDemLoading = true;
      try {
        const r = await API.zona.demandaBulk({});
        const items = (r && (r.data || r) && (r.data || r).items) || [];
        const m = {};
        items.forEach(it => { m[String(it.sku).toUpperCase()] = it; });
        const cambio = JSON.stringify(Object.keys(m).sort()) !== JSON.stringify(Object.keys(S._zonaAlmDem || {}).sort());
        S._zonaAlmDem = m; S._zonaAlmDemTs = Date.now();
        if (cambio || force) renderZona();   // repinta con los cuadrantes/metas corregidos
      } catch (_) { if (!S._zonaAlmDem) S._zonaAlmDem = {}; }
      finally { S._zonaAlmDemLoading = false; }
    } catch (_) {}
  }
  // [924] I-11: presentación-huérfana de granel (comparte sku con el granel pero SIN canónico propio) →
  //   la representa su granel, no se lista aparte. Set de skus que SÍ tienen canónico (factor=1, sin base).
  let _zonaCanonSet = null, _zonaCanonLen = -1;
  function _zonaCanonSkuSet() {
    const ps = Array.isArray(S.productos) ? S.productos : [];
    if (_zonaCanonSet && _zonaCanonLen === ps.length) return _zonaCanonSet;
    const set = new Set();
    ps.forEach(x => { if ((parseFloat(x.factorConversion) || 1) === 1 && !String(x.codigoProductoBase || '').trim()) { const k = String(x.skuBase || '').trim().toUpperCase(); if (k) set.add(k); } });
    _zonaCanonSet = set; _zonaCanonLen = ps.length; return set;
  }
  function _zonaEsPresentacionGranel(p) {
    const sku = String(p && p.skuBase || '').trim().toUpperCase(); if (!sku) return false;
    if (_zonaCanonSkuSet().has(sku)) return false;            // tiene canónico → item legítimo
    const ps = Array.isArray(S.productos) ? S.productos : [];
    return ps.some(x => String(x.skuBase || '').trim().toUpperCase() === sku && (parseFloat(x.factorConversion) || 1) !== 1);
  }
  function _zonaCuadDe(p) {
    const esp = _zonaMetaDe(p);
    const eff = _zonaEffStock(p);
    const brecha = Math.max(0, esp - eff);
    if (_zonaActualEsAlmacen()) {
      // [931] En ALMACÉN la meta es la DEMANDA SEMANAL inteligente (incluye la deuda por semana). Si la meta
      //   supera el stock → "Pedir ya". La deuda vieja YA NO fuerza pedir (si la demanda se apagó, el smart
      //   la deja baja → no urge). Pero un producto CON deuda visible no cae a "Muertos": va a 'orden'.
      if (brecha > 0) return 'pedir';
      if (_zonaEsRotCero(p) && eff > 0 && esp <= 0) return (_zonaSeEnvasa(p) || _zonaAlmTieneDeuda(p)) ? 'orden' : 'muerto';
      if (esp > 0 && eff > esp * 3) return 'sobra';
      return 'orden';
    }
    // ZONAS (venta diaria): comportamiento original por picos.
    if (_zonaEsRotCero(p) && eff > 0) return 'muerto';
    if (brecha > 0) return 'pedir';
    if (esp > 0 && eff > esp * 3) return 'sobra';
    return 'orden';
  }
  // [912] Prioridad DENTRO de un cuadrante (mayor = más arriba). Pedir: el que más % falta.
  //   Sobra: el que más le sobra. Muerto: el que más stock parado tiene. Orden: sin urgencia.
  function _zonaPrioridad(p, cuad) {
    const esp = _zonaMetaDe(p);   // [916] meta inteligente
    const eff = _zonaEffStock(p);
    const c = cuad || _zonaCuadDe(p);
    if (c === 'pedir') {
      let s = esp > 0 ? (esp - eff) / esp : 1;      // % faltante (0..1)
      // [913] Prioridad DINÁMICA: si ya lo pediste (carrito o pedido registrado), baja al fondo del grupo
      //   → te libera para atender el siguiente más urgente. Al llegar la mercadería, el realtime lo re-ordena.
      let yaPedido = !!(p.pedidoEstado && p.pedidoEstado.etiqueta);
      try { if (!yaPedido && _zonaCarritoCant(String(p.skuBase || p.idProducto || '')) > 0) yaPedido = true; } catch (_) {}
      if (yaPedido) s -= 2;                          // lo manda debajo de todos los no-pedidos
      // [924] I-10: en ZONA un granel envasable es solo mostrario (para eso se envasa) → baja prioridad.
      if (!_zonaActualEsAlmacen() && _zonaEsGranelEnvasable(p)) s -= 1;
      return s;
    }
    if (c === 'sobra')  return esp > 0 ? eff / esp : (eff || 0);     // cuánto sobra respecto a la meta
    if (c === 'muerto') return eff;                                  // más stock parado primero
    return -(esp || 0);                                             // "en orden": sin urgencia
  }
  // Cachea el conteo de cuadrantes de la zona activa (para las vitales del hub, sin queries pesadas).
  function _zonaCacheVitales() {
    const arr = S.zonaProductos || []; if (!arr.length) return;
    let pedir = 0, muerto = 0, sobra = 0, orden = 0;
    for (const p of arr) { const c = _zonaCuadDe(p); if (c === 'pedir') pedir++; else if (c === 'muerto') muerto++; else if (c === 'sobra') sobra++; else orden++; }
    const v = { pedir, muerto, sobra, orden, ts: Date.now() };
    try { localStorage.setItem('mos_zona_vit_' + S.zonaActual, JSON.stringify(v)); } catch (_) {}
    S._zonaVitCuad = S._zonaVitCuad || {}; S._zonaVitCuad[S.zonaActual] = v;
  }
  function _zonaVitCuadGet(id) { try { const s = localStorage.getItem('mos_zona_vit_' + id); return s ? JSON.parse(s) : null; } catch (_) { return null; } }
  // [913] ¿el producto tiene algún código (o total) en negativo? (para el modo "recontar negativos").
  function _zonaTieneNeg(p) {
    const c = Array.isArray(p.codigos) ? p.codigos : [];
    return !!p.stockNegativo || (c.length ? c.some(x => _zonaNum(x.stock) < 0) : _zonaNum(p.stockZona != null ? p.stockZona : p.stock) < 0);
  }
  function zonaSoloNegToggle() { S._zonaSoloNeg = !S._zonaSoloNeg; try { _zonaSfx('pop'); _zonaVibrar(15); } catch (_) {} renderZona(); }
  function _zonaNegBannerRender() {
    const el = $('zonaNegBanner'); if (!el) return;
    const n = (S.zonaProductos || []).filter(_zonaTieneNeg).length;
    if (!n && !S._zonaSoloNeg) { el.innerHTML = ''; el.style.display = 'none'; return; }
    el.style.display = '';
    el.className = 'zona-neg-banner' + (S._zonaSoloNeg ? ' active' : '');
    el.innerHTML = S._zonaSoloNeg
      ? `<span class="znb-txt">⚠ Recontando ${n} en negativo — toca ✏️ Ajustar en cada uno</span><button class="znb-btn" onclick="MOS.zonaSoloNegToggle()">✓ Ver todo</button>`
      : `<span class="znb-txt">⚠ ${n} producto${n === 1 ? '' : 's'} con stock en negativo</span><button class="znb-btn" onclick="MOS.zonaSoloNegToggle()">Recontar →</button>`;
  }

  function _zonaCardHtml(p) {
    const sku   = String(p.skuBase || p.idProducto || '');
    const safe  = _esc(sku);
    const nm    = _esc(p.descripcion || p.nombre || sku);
    const stockRaw = _zonaNum(p.stockZona != null ? p.stockZona : p.stock);
    const esp   = _zonaMetaDe(p);   // [916] meta inteligente (tendencia de 4 semanas), no solo el último pico
    // [911] Stock EFECTIVO = suma de códigos en POSITIVO. Un código negativo cuenta como 0 (error de
    //   conteo), NO como resta. Ej. MAGGI: −203 (→0) + 145 = 145 disponible, no −58.
    const _cods0 = Array.isArray(p.codigos) ? p.codigos : [];
    const _effStock = _cods0.length ? _cods0.reduce((a, c) => a + Math.max(0, _zonaNum(c.stock)), 0) : Math.max(0, stockRaw);
    const negativo = !!p.stockNegativo || stockRaw < 0 || _cods0.some(c => _zonaNum(c.stock) < 0);
    const brecha = Math.max(0, esp - _effStock);   // brecha contra el stock efectivo
    const alm   = _zonaNum(p.stockAlmacen != null ? p.stockAlmacen : p.almacen);
    const bcg   = _zonaBCGClase(p);
    const bcgInfo = _ZONA_BCG[bcg] || _ZONA_BCG.vaca;
    const tend  = _zonaTendBadge(p.tendencia);
    const picos = Array.isArray(p.picos) ? p.picos.slice(-4) : [];
    // [FIX] stock negativo (almacén o zona) = ERROR → cuenta como 0 para pedido/compra.
    // El display de `alm` sigue mostrando el valor real (negativo incluido), pero NO infla la compra.
    const almPos   = Math.max(0, alm);
    const pedirAlm = Math.min(brecha, almPos);
    const externo  = Math.max(0, brecha - almPos);
    const uni      = _zonaUniLbl(p);
    // [MEJORA 2] cantidades formateadas según granel/unidad.
    const fStock  = _zonaFmtCant(stockRaw, p, true);
    const fEsp    = _zonaFmtCant(esp, p, true);
    const fAlm    = _zonaFmtCant(alm, p, true);
    const fBrecha = _zonaFmtCant(brecha, p, true);
    // [RIZ #4] En ámbito ALMACEN la 4ª métrica "Almacén" es REDUNDANTE (ya estás viendo el almacén): se
    //   reemplaza por la lista de proveedores REALES del canónico (lazy-load por card vía mos.zona_proveedores).
    const esAlmacenCard = _esZonaAlmacen({ idZona: S.zonaActual,
      nombre: ((S.zonaList || []).find(x => (x.idZona || x.id || x.nombre) === S.zonaActual) || {}).nombre });
    // [MEJORA 5] multi-código de barra.
    const codigos = Array.isArray(p.codigos) ? p.codigos : [];
    // [SPLIT/ROTCERO] códigos del almacén (solo lectura) + flag rotación-cero.
    const codigosAlm = Array.isArray(p.codigosAlmacen) ? p.codigosAlmacen : [];
    const rotCero = _zonaEsRotCero(p);
    // [924] En almacén, granel envasable / insumo NO es "perro": se consume al ENVASAR (no se despacha).
    const seEnvasa = esAlmacenCard && _zonaSeEnvasa(p);
    const tieneDeudaAlm = esAlmacenCard && _zonaAlmTieneDeuda(p);   // [929] demanda insatisfecha (rezagado)
    const esDerivadoAlm = esAlmacenCard && _zonaEsDerivado(p);      // [930] se ENVASA del granel, no se compra

    // [MEJORA 1] Sparkline CLICKABLE → modal "¿por qué esperado=X?"
    const maxP = Math.max(1, ...picos.map(_zonaNum));
    const spark = picos.length
      ? `<div class="zona-spark zona-spark-click" onclick="MOS.zonaVerEsperado('${safe}')" title="¿Por qué esperado = ${_esc(fEsp)}? (toca para ver)">${picos.map((v,i) => `<div class="zona-spark-bar${i === picos.length-1 ? ' last' : ''}" style="height:${Math.max(3, Math.round(_zonaNum(v)/maxP*24))}px" title="${_zonaFmtCant(v, p)}"></div>`).join('')}<span class="zona-spark-lbl">${picos.map(v => _zonaFmtNumRaw(v, p.esGranel)).join(' ')} →</span></div>`
      : '';

    // Vencimiento
    const venc = _zonaVencBadge(p.diasVencimiento != null ? p.diasVencimiento : p.dias_venc);
    const vencHtml = venc
      ? `<div class="zona-venc"><span class="zona-venc-dot ${venc.dot}"></span>${_esc(venc.txt)}<span class="zona-venc-link" onclick="MOS.zonaVerLotes('${safe}')">ver historial lotes</span></div>`
      : '';

    // [MEJORA 3] Badge rojo de alerta si el stock es negativo.
    const alertaNeg = negativo
      ? `<div class="zona-alerta-neg">⚠ Stock negativo — corregir/contar</div>`
      : '';

    // Sugerencia IA (placeholder Capa 5 — texto local determinista)
    // [MEJORA 3] Con negativo NO decir "te faltan N" (eso es un error de conteo, no una compra).
    let ia = '';
    if (negativo) {
      ia = `⚠ Stock negativo (revisar dónde se originó). Para estar listo necesitas ${fEsp}.`;
    } else if (esDerivadoAlm) {
      // [930] Un DERIVADO se ENVASA del granel padre — NUNCA se compra a un proveedor.
      const _gp = _zonaGranelPadreNombre(p);
      ia = brecha > 0
        ? `🏭 Se <b>envasa</b> del granel${_gp ? ' (' + _esc(_gp) + ')' : ''}, no se compra. Faltan ${fBrecha} → <b>envasar ${fBrecha}</b>.`
        : (tieneDeudaAlm ? '🟡 Demanda insatisfecha: tienes stock → <b>despacha lo que debes</b>.' : 'Stock al día. Se envasa del granel cuando falte.');
    } else if (esAlmacenCard && brecha > 0) {
      // [902] Almacén NO pide a almacén: compra a PROVEEDOR para cubrir su semana.
      ia = `Te faltan ${fBrecha} para tu semana. Cómpralos a un proveedor.`;
    } else if (brecha > 0) {
      ia = `Te faltan ${fBrecha} para estar listo.`;
      if (pedirAlm > 0) ia += ` Almacén cubre ${_zonaFmtCant(pedirAlm, p)} → pídelos.`;
      if (externo > 0)  ia += ` Los ${_zonaFmtCant(externo, p)} restantes van a tu lista del lunes.`;
    } else if (tieneDeudaAlm) {
      // [929] Deuda cubierta por stock: no hay que COMPRAR, hay que DESPACHAR lo que se debe.
      ia = '🟡 Demanda insatisfecha: se pidió y no se despachó, pero tienes stock → <b>despacha lo que debes</b> (mira las zonas en 📊 ¿Por qué?).';
    } else if (seEnvasa) {
      // [924] granel envasable / insumo: su demanda vive en las guías de envasado, no en el despacho.
      ia = _zonaEsInsumo(p)
        ? '🧷 Insumo de envasado: no se despacha a zona, se consume al envasar (se pide por millares al proveedor). Mira su salida en 📊 ¿Por qué?'
        : '🏭 Granel para ENVASAR: casi no se despacha, pero se consume al envasar. Su salida real está en 📊 ¿Por qué?';
    } else if (bcg === 'perro') {
      ia = 'Sin rotación: considera promocionar, mover a góndola o rematar.';
    } else {
      ia = 'Stock al día. Sin acción necesaria.';
    }

    // Acciones según cuadrante
    let acciones;
    if (bcg === 'perro' && brecha <= 0 && !negativo && !seEnvasa) {
      // [RIZ · CAPA 5] Acciones reales (decisión auditable, NO mutan stock/dinero). El botón de la decisión
      // vigente queda resaltado (data del panel: p.accionPerro). Optimista + idempotente backend.
      const acc = String(p.accionPerro || '').toUpperCase();
      const on = (k) => acc === k ? ' zona-accion-on' : '';
      acciones = `<button class="zona-btn-sec${on('PROMOCIONAR')}" onclick="MOS.zonaAccionPerro('${safe}','PROMOCIONAR')">Promocionar</button>
                  <button class="zona-btn-sec${on('GONDOLA')}" onclick="MOS.zonaAccionPerro('${safe}','GONDOLA')">Mover a góndola</button>
                  <button class="zona-btn-sec${on('REMATAR')}" onclick="MOS.zonaAccionPerro('${safe}','REMATAR')">Rematar</button>`;
    } else {
      // [RIZ CARRITO] "Pedir" YA NO envía de inmediato: AGREGA al carrito flotante de la zona. La cantidad
      // sugerida inicial = brecha (lo que falta); el admin la ajusta con +/− en el carrito. Re-agregar un
      // ya-pedido está permitido (requisito D). Cantidad sugerida = brecha (no limitada por almacén; el
      // almacén puede no cubrir y se pide igual — el ticket de almacén marca el "debe").
      const sugerir = brecha > 0 ? brecha : 0;
      const enCarrito = _zonaCarritoCant(sku);
      // [RIZ CARRITO · FIX D] El botón refleja 3 estados VISUALMENTE distintos:
      //   1) en carrito (aún no enviado)  → "🛒 En carrito (N) · +"  (clase zona-en-carrito)
      //   2) ya pedido hoy/ayer (persistido en me.zona_pedido_log, llega en p.pedidoEstado) → "✓ Pedido hoy · re-pedir"
      //      (clase zona-pedido-ok) — DISTINTO de no-pedido, pero un tap RE-AGREGA al carrito (re-pedir permitido).
      //   3) sin pedir → "Pedir N a almacén" / "Agregar al pedido".
      const pedLbl = (p.pedidoEstado && p.pedidoEstado.etiqueta) ? String(p.pedidoEstado.etiqueta) : '';
      let btnLbl, btnCls;
      if (enCarrito > 0) {
        btnLbl = '🛒 En carrito (' + _esc(_zonaFmtCant(enCarrito, p)) + ') · +';
        btnCls = ' zona-en-carrito';
      } else if (pedLbl) {
        btnLbl = '✓ ' + _esc(pedLbl) + ' · re-pedir';
        btnCls = ' zona-pedido-ok';
      } else {
        btnLbl = sugerir > 0 ? 'Pedir ' + _esc(_zonaFmtCant(sugerir, p)) + ' a almacén' : 'Agregar al pedido';
        btnCls = '';
      }
      acciones = `<button class="zona-btn-pedir${btnCls}" id="zPedir-${safe}" onclick="MOS.zonaPedirAlmacen('${safe}', ${sugerir})">${btnLbl}</button>
                  <button class="zona-btn-sec" ${externo > 0 ? '' : 'disabled'} onclick="MOS.zonaAgregarLista('${safe}', ${externo})">+ Lista compras${externo > 0 ? ' (' + _esc(_zonaFmtCant(externo, p)) + ')' : ''}</button>`;
    }
    // [902] En ALMACÉN la acción es COMPRAR a proveedor (almacén no se pide a sí mismo). Reemplaza el pedir.
    // [924] granel envasable / insumo entra aquí (no es perro): se compra al proveedor para poder envasar.
    if (esAlmacenCard && (seEnvasa || !(bcg === 'perro' && brecha <= 0 && !negativo))) {
      const falta = brecha > 0 ? brecha : 0;
      if (esDerivadoAlm) {
        // [930] Derivado: se ENVASA del granel, no se compra. El botón lleva a Considerados (despachar) —
        //   la compra real es del GRANEL padre (su card la calcula).
        acciones = falta > 0
          ? `<button class="zona-btn-pedir" onclick="MOS.zonaAbrirConsiderados()">🏭 Envasar ${_esc(_zonaFmtCant(falta, p))} · del granel</button>`
          : (tieneDeudaAlm ? `<button class="zona-btn-pedir" onclick="MOS.zonaAbrirConsiderados()">📦 Despachar lo que debes</button>` : `<button class="zona-btn-pedir" disabled>✓ Semana cubierta</button>`);
      } else if (seEnvasa) {
        // [926] La compra del envasable (granel o insumo) = meta(demanda semanal) − stock; la calcula el
        //   RPC (async). Placeholder hasta que _zonaGranelCargarVisibles lo rellene.
        acciones = `<button class="zona-btn-pedir" id="zGbuy-${_zonaSkuId(sku)}" disabled>🧾 Calculando envasado…</button>`;
      } else if (falta <= 0 && tieneDeudaAlm) {
        // [929] Se debe pero el stock alcanza: no se compra, se DESPACHA. Botón lleva a Considerados.
        acciones = `<button class="zona-btn-pedir" onclick="MOS.zonaAbrirConsiderados()">📦 Despachar lo que debes</button>`;
      } else {
        acciones = `<button class="zona-btn-pedir" ${falta > 0 ? '' : 'disabled'} onclick="MOS.zonaAgregarLista('${safe}', ${falta})">${falta > 0 ? '🧾 Comprar ' + _esc(_zonaFmtCant(falta, p)) + ' a proveedor' : '✓ Semana cubierta'}</button>`;
      }
    }

    // [RIZ CARRITO] estado "Pedido hoy/ayer" persistido (me.zona_pedido_log, ventana 7 días). El panel lo
    // devuelve en p.pedidoEstado:{etiqueta,...}; lo mostramos como chip en el card (sobrevive a refrescos).
    const pedEstado = (p.pedidoEstado && p.pedidoEstado.etiqueta)
      ? `<div class="zona-ped-estado"><span class="zona-ped-ico">📦</span>${_esc(p.pedidoEstado.etiqueta)}</div>`
      : '';

    // [MEJORA 5] disclosure "ver códigos (N)" → expande item.codigos[] (zona, editable).
    const codDisc = codigos.length
      ? `<div class="zona-cod-disc" id="zCodDisc-${safe}" onclick="MOS.zonaToggleCodigos('${safe}')"><span class="zona-cod-caret" id="zCodCaret-${safe}">▸</span> ver códigos (${codigos.length})</div>
         <div class="zona-cod-body" id="zCodBody-${safe}" style="display:none"></div>`
      : '';

    // [MEJORA 3] disclosure "ver códigos almacén (N)" → expande item.codigosAlmacen[] (solo lectura).
    const codAlmDisc = codigosAlm.length
      ? `<div class="zona-cod-disc zona-cod-disc-alm" id="zAlmDisc-${safe}" onclick="MOS.zonaToggleCodigosAlmacen('${safe}')"><span class="zona-cod-caret" id="zAlmCaret-${safe}">▸</span> ver códigos almacén (${codigosAlm.length})</div>
         <div class="zona-cod-body" id="zAlmBody-${safe}" style="display:none"></div>`
      : '';

    // [889] CUADRANTE + DÍAS DE COBERTURA — la métrica que el admin entiende ("¿cuánto me dura?").
    //   Rotación diaria = "día fuerte" (último pico no-cero): la realidad mayorista es venta en picos,
    //   no diaria pareja; si no hay pico, volumen/28. Objetivo de zona = cubrir 1 día fuerte.
    //   Deriva 100% de lo que el panel ya trae (NO toca el backend money-safe).
    const _picN = picos.map(_zonaNum);
    const _picoFuerte = _picN.length ? Math.max(0, ..._picN) : 0;
    const _rotDia = _picoFuerte > 0 ? _picoFuerte : (_zonaNum(p.volumen) > 0 ? _zonaNum(p.volumen) / 28 : 0);
    const _stockEff = _effStock;   // [911] efectivo = suma de códigos en positivo (negativo=0, no resta)
    const _diasCob = _rotDia > 0 ? (_stockEff / _rotDia) : (_stockEff > 0 ? Infinity : 0);
    const _cuad = _zonaCuadDe(p);
    const _cuadIco = _CUAD_META[_cuad][0], _cuadLbl = _CUAD_META[_cuad][1];
    // [892] Objetivo por NIVEL (regla del dueño): almacén = 1 semana (7 días), zona = 1 día.
    const _objDias = esAlmacenCard ? 7 : 1;
    const _diasTxt = (_cuad === 'muerto') ? 'no rota'
      : (_diasCob === Infinity ? 'de sobra'
      : (_rotDia <= 0 ? '—'
      : (_diasCob >= 10 ? Math.round(_diasCob) + ' días' : (_diasCob.toFixed(1).replace(/\.0$/, '')) + ' días')));
    // [902] Almacén mide rotación SEMANAL (despachos); zona mide el día fuerte (venta en picos).
    const _rotTxt = esAlmacenCard
      ? (_zonaNum(p.volumen) > 0 ? ('despacha ~' + _zonaFmtNumRaw(Math.round(_zonaNum(p.volumen) / 4), p.esGranel) + '/sem') : 'sin despacho en 4 sem')
      : (_rotDia > 0 ? ('vende ~' + _zonaFmtNumRaw(_picoFuerte > 0 ? _picoFuerte : _rotDia, p.esGranel) + '/día fuerte') : 'sin venta en 4 sem');
    // Medidor circular (instrumento): anillo = cobertura respecto al objetivo del nivel. Centro = días.
    const _ringFrac = (_rotDia <= 0 ? (_stockEff > 0 ? 1 : 0) : Math.max(0, Math.min(1, _diasCob / _objDias)));
    const _dash = Math.round(_ringFrac * 113);
    const _ringNum = (_cuad === 'muerto') ? '0'
      : (_diasCob === Infinity ? '∞'
      : (_rotDia <= 0 ? '—'
      : (_diasCob >= 10 ? String(Math.round(_diasCob)) : _diasCob.toFixed(1).replace(/\.0$/, ''))));
    const _ringUni = (_cuad === 'muerto' || _rotDia <= 0 || _diasCob === Infinity) ? '' : 'd';
    const _gaugeHtml = `<div class="zona-gauge">
        <svg viewBox="0 0 44 44" aria-hidden="true"><circle class="zg-track" cx="22" cy="22" r="18"></circle><circle class="zg-fill" cx="22" cy="22" r="18" style="stroke-dasharray:${_dash} 113"></circle></svg>
        <span class="zg-orbit" aria-hidden="true"></span>
        <div class="zg-c"><b>${_ringNum}</b>${_ringUni ? `<span>${_ringUni}</span>` : ''}</div>
      </div>`;
    const _porque = picos.length
      ? `<span class="zona-porque" onclick="MOS.zonaVerEsperado('${safe}')" title="¿Por qué necesitas ${_esc(fEsp)}? (toca para ver los picos)">📊 ¿por qué ${_esc(fEsp)}?</span>`
      : '';

    // [ROTCERO] Chip + hint para cards sin rotación (secundarias, no "rotas").
    // [924] Si se ENVASA (granel envasable / insumo), no es "sin rotación": el chip y el hint lo dicen.
    // [927] En almacén, un producto con DEUDA (demanda insatisfecha) no es "sin rotación → anular":
    //   se pidió y no se despachó, hay que reponerlo. El chip/hint lo dice y ya vive en "Pedir ya".
    const rotCeroChip = seEnvasa
      ? `<span class="zona-rotcero-chip" style="background:rgba(139,92,246,.14);border-color:rgba(167,139,250,.5);color:#c4b5fd" title="Se consume al envasar">🏭 se envasa</span>`
      : tieneDeudaAlm
      ? `<span class="zona-rotcero-chip" style="background:rgba(251,191,36,.14);border-color:rgba(251,191,36,.5);color:#fcd34d" title="Se pidió y no se despachó: hay que reponer">🟡 demanda insatisfecha</span>`
      : rotCero
      ? `<span class="zona-rotcero-chip" title="Sin rotación en la ventana">∅ sin rotación</span>`
      : '';
    const rotCeroHint = seEnvasa
      ? `<div class="zona-rotcero-hint" style="color:#a78bfa">${_zonaEsInsumo(p) ? 'Insumo de envasado: se compra por millares para envasar.' : 'Granel base: se compra para envasarlo en sus derivados.'}</div>`
      : tieneDeudaAlm
      ? `<div class="zona-rotcero-hint" style="color:#fbbf24">Hay <b>demanda insatisfecha</b>: se pidió y no se despachó → hay que reponerlo.</div>`
      : (rotCero && !negativo)
      ? `<div class="zona-rotcero-hint">Considera <b>anular</b> o <b>promocionar</b> este producto.</div>`
      : '';

    // [904] Info limpia y explícita (no todo en una línea; sin el redundante "Pedir ya" ni "meta 7d").
    const _rotNum = esAlmacenCard ? Math.round(_zonaNum(p.volumen) / 4) : (_picoFuerte > 0 ? _picoFuerte : Math.round(_zonaNum(p.volumen) / 28));
    const _rotLbl = esAlmacenCard ? 'Despacha' : 'Vende';
    const _rotUniTxt = esAlmacenCard ? 'semana' : 'día';
    const _duraTxt = (_cuad === 'muerto') ? 'No rota hace 4 semanas'
      : (negativo ? ('En negativo · ' + _esc(fStock))
      : (_rotDia <= 0 ? '—' : ('Dura ' + _diasTxt)));
    const _covPctBar = (_cuad === 'muerto') ? 100 : (_rotDia <= 0 ? (_stockEff > 0 ? 100 : 0) : Math.max(0, Math.min(100, Math.round(_diasCob / _objDias * 100))));
    // [906] Foto del producto (reemplaza el círculo) + protagonista = barra "Dura".
    const _foto = _zonaFotoUrl(p);
    const _duraBig = _ringNum;   // días (el negativo cuenta como 0 stock efectivo)
    const _duraCap = (_cuad === 'muerto') ? 'sin rotar' : (negativo ? 'sin stock · ⚠ contar' : (_rotDia <= 0 ? 'sin dato' : 'te dura'));
    // [910] La barra va en UNIDADES: pintado = lo que TIENES (stock efectivo), el fin = la META (esperada).
    //   Así 49 de 58 se ve ~84% (falta 9), no lleno. La rotación (🔄) va aparte, y "te dura X días" abajo.
    const _have = _stockEff;
    const _meta = esp;
    const _barPct = (_cuad === 'muerto') ? 100 : (_meta > 0 ? Math.min(100, Math.round(_have / _meta * 100)) : (_have > 0 ? 100 : 0));
    const _haveTxt = _esc(_zonaFmtNumRaw(_have, p.esGranel));
    const _metaTxt = (_cuad !== 'muerto' && _meta > 0) ? ('meta ' + _esc(_zonaFmtNumRaw(_meta, p.esGranel))) : '';
    const _rotShow = (_rotDia > 0) || (esAlmacenCard && _zonaNum(p.volumen) > 0);
    const _rotLine = _rotShow ? `🔄 ${esAlmacenCard ? 'Despacha' : 'Vende'} <b>${_esc(_zonaFmtNumRaw(_rotNum, p.esGranel))}</b>/${_rotUniTxt}` : '🔄 sin rotación';
    const _diasSub = (_cuad === 'muerto') ? 'no rota hace 4 semanas' : (_rotDia <= 0 ? '' : ('te dura ~' + _diasTxt));
    // [913] Plata inmovilizada (el dueño piensa en soles): muerto = todo parado; sobra = el exceso.
    const _costoU = (_cuad === 'muerto' || _cuad === 'sobra') ? _zonaCostoUnit(p) : 0;
    const _plataTxt = (_costoU > 0)
      ? (_cuad === 'muerto' ? ('S/ ' + _money(_stockEff * _costoU).toFixed(2) + ' parado')
        : ((_meta > 0 && _stockEff > _meta) ? ('S/ ' + _money((_stockEff - _meta) * _costoU).toFixed(2) + ' de más') : ''))
      : '';
    // [921] Foquito: si es zona, está en "Pedir" y almacén NO cubre (externo>0), ¿la otra zona tiene?
    const _cruz = (!esAlmacenCard && _cuad === 'pedir' && externo > 0) ? _zonaCruzadoDe(p) : null;
    const _codChips = _zonaCodChipsHtml(sku, p);
    return `<div class="zona-card zona-cuad-${_cuad} ${bcgInfo.cls}${negativo ? ' zona-neg' : ''}${rotCero ? ' zona-rotcero' : ''}" id="zcard-${safe}" data-sku="${safe}" data-cuad="${_cuad}">
      <div class="zona-card-hero zona-cov-${_cuad}">
        <div class="zona-foto">${_foto ? `<img src="${_esc(_foto)}" loading="lazy" alt="" onerror="this.parentNode.classList.add('noimg')">` : ''}<span class="zona-foto-ph">📦</span></div>
        <div class="zona-hero-txt">
          <div class="zona-card-top-row">
            <div class="zona-card-name">${nm}</div>
            <div class="zona-hero-badges">${rotCeroChip}${(!esAlmacenCard && _zonaEsGranelEnvasable(p)) ? '<span class="zona-rotcero-chip" style="background:rgba(139,92,246,.14);border-color:rgba(167,139,250,.5);color:#c4b5fd" title="Granel para mostrario; se envasa en almacén. El exceso se devuelve a almacén.">🏭 mostrario</span>' : ''}<span class="zona-tend-badge ${tend.cls}">${tend.lbl}</span><span class="zona-bcg-badge" title="BCG: ${bcg}">${bcgInfo.ico}</span></div>
          </div>
          <div class="zona-meter">
            <div class="zona-meter-rota">${_rotLine}</div>
            <div class="zona-meter-bar" title="Tienes ${_haveTxt}${_metaTxt ? ' · ' + _metaTxt : ''}"><i style="width:${_barPct}%"></i></div>
            <div class="zona-meter-nums"><span class="zm-have"><b>${_haveTxt}</b> tienes</span>${_metaTxt ? `<span class="zm-meta">${_metaTxt}</span>` : ''}${_plataTxt ? `<span class="zm-plata">💸 ${_plataTxt}</span>` : ''}${_diasSub ? `<span class="zm-sub">${_diasSub}</span>` : ''}</div>
          </div>
          <div class="zc-chips" id="zChips-${safe}">${_codChips}</div>
        </div>
      </div>
      ${alertaNeg}
      ${esAlmacenCard
        ? `<div class="zona-prov" id="zProv-${safe}" data-sku="${safe}">${_zonaProvBlockHtml(sku)}</div>`
        : `<div class="zona-almline"><span class="zml-l">En almacén hay</span> <b class="${alm < 0 ? 'brecha-pos' : ''}">${_esc(fAlm)}</b> <span class="zml-l">para pedir</span></div>`}
      ${_cruz ? `<div class="zona-foquito">🔦 En <b>${_esc(_zonaNombreZona(_cruz.zona))}</b> hay <b>${_esc(_zonaFmtNumRaw(_cruz.cant, p.esGranel))}</b> <span>· solo si almacén no cubre (no choques las zonas)</span></div>` : ''}
      ${vencHtml}
      ${rotCeroHint}
      ${pedEstado}
      <div class="zona-accion zona-cov-${_cuad}">
        <div class="zona-ia">💡 ${_esc(ia)}</div>
        <div class="zona-actions">${acciones}</div>
      </div>
      <div class="zona-tool-btns">
        <button class="ztbtn" id="zAjBtn-${safe}" onclick="MOS.zonaAjustarToggle('${safe}')">✏️ Ajustar</button>
        <button class="ztbtn" onclick="MOS.zonaSecToggle('${safe}','pq')">📊 ¿Por qué ${_esc(fEsp)}?</button>
        <button class="ztbtn" onclick="MOS.zonaSecToggle('${safe}','hx')">🕘 Historial</button>
      </div>
      <div class="zt-panel" id="ztPq-wrap-${safe}" style="display:none"><div id="ztPq-${safe}"><div class="esp-loading"><span class="esp-spin"></span></div></div></div>
      <div class="zt-panel" id="ztHx-wrap-${safe}" style="display:none"><div id="ztHx-${safe}"><div class="esp-loading"><span class="esp-spin"></span></div></div></div>
    </div>`;
  }
  // [906] Foto del producto canónico: la busca en el catálogo por cualquiera de sus códigos (o por sku).
  function _zonaFotoUrl(item) {
    try {
      const idx = _prodIndex();
      const cods = Array.isArray(item.codigos) ? item.codigos : [];
      for (const c of cods) {
        const cb = String(c.codBarra != null ? c.codBarra : (c.codigoBarra != null ? c.codigoBarra : '')).trim();
        if (cb && idx.byCod.has(cb)) { const pr = idx.byCod.get(cb); const u = String(pr.fotoUrl || pr.logoUrl || '').trim(); if (u) return u; }
      }
      const sku = String(item.skuBase || item.idProducto || '');
      if (sku && idx.byId.has(sku)) { const pr = idx.byId.get(sku); const u = String(pr.fotoUrl || pr.logoUrl || '').trim(); if (u) return u; }
    } catch (_) {}
    return '';
  }
  // ══ [907] KARDEX GENERAL — overlay con el stock de TODOS los productos (canónico → códigos),
  //   con kardex por código y exportación (Excel/XML/PDF). Usa S.zonaProductos (ya viene agrupado). ══
  function zonaAbrirKardexGeneral() {
    const box = $('zonaKgOvl'); if (!box) return;
    S._zonaKgQ = ''; const inp = $('zonaKgSearch'); if (inp) inp.value = '';
    box.classList.remove('hidden'); requestAnimationFrame(() => box.classList.add('open'));
    _zonaKgRender();
    try { _zonaSfx('pop'); _zonaVibrar(15); } catch (_) {}
  }
  function zonaCerrarKardexGeneral() {
    const box = $('zonaKgOvl'); if (!box) return;
    box.classList.remove('open'); setTimeout(() => { const b = $('zonaKgOvl'); if (b && !b.classList.contains('open')) b.classList.add('hidden'); }, 220);
  }
  function _zonaKgProductos() {
    const q = String(S._zonaKgQ || '').toLowerCase().trim();
    let arr = (S.zonaProductos || []).slice();
    if (q) arr = arr.filter(p => String(p.descripcion || p.nombre || '').toLowerCase().indexOf(q) >= 0 || (Array.isArray(p.codigos) && p.codigos.some(c => String(c.codBarra || '').indexOf(q) >= 0)));
    arr.sort((a, b) => String(a.descripcion || a.nombre || '').localeCompare(String(b.descripcion || b.nombre || '')));
    return arr;
  }
  function _zonaKgRender() {
    const body = $('zonaKgBody'); if (!body) return;
    const arr = _zonaKgProductos();
    const sub = $('zonaKgSub'); if (sub) sub.textContent = arr.length + ' productos';
    if (!arr.length) { body.innerHTML = '<div class="kg-empty">Sin productos.</div>'; return; }
    body.innerHTML = arr.map(p => {
      const sku = String(p.skuBase || p.idProducto || ''); const safe = _esc(sku);
      const cods = Array.isArray(p.codigos) ? p.codigos : [];
      const tot = _zonaNum(p.stockZona != null ? p.stockZona : p.stock);
      const neg = tot < 0 || cods.some(c => _zonaNum(c.stock) < 0);
      const nm = _esc(p.descripcion || p.nombre || sku);
      const rows = cods.map(c => {
        const cb = String(c.codBarra != null ? c.codBarra : (c.codigoBarra || '')); const cbSafe = _zonaEsc(cb);
        const st = _zonaNum(c.stock); const nn = st < 0;
        return `<div class="kg-cod" onclick="MOS.zonaKgVerCodigo('${cbSafe}','${safe}')">
          <span class="kg-cod-cb">${_esc(cb)} <i>${c.esEquivalente ? '≈ equiv' : 'canónico'}</i></span>
          <span class="kg-cod-st ${nn ? 'neg' : ''}">${nn ? '⚠ ' : ''}${_esc(_zonaFmtNumRaw(st, p.esGranel))}</span>
          <span class="kg-cod-go">ver kardex →</span></div>`;
      }).join('');
      return `<div class="kg-row${neg ? ' has-neg' : ''}">
        <div class="kg-head" onclick="MOS.zonaKgToggle('${safe}')">
          <span class="kg-caret" id="kgC-${safe}">▸</span>
          <span class="kg-nm">${nm}</span>
          ${neg ? '<span class="kg-negbadge" title="Tiene un código en negativo">⚠</span>' : ''}
          <span class="kg-tot ${tot < 0 ? 'neg' : ''}">${_esc(_zonaFmtNumRaw(tot, p.esGranel))}</span>
          <span class="kg-codn">${cods.length} cód</span>
        </div>
        <div class="kg-cods" id="kgB-${safe}" style="display:none">${rows || '<div class="kg-cod-empty">Sin códigos.</div>'}</div>
      </div>`;
    }).join('');
  }
  function zonaKgToggle(sku) { const b = $('kgB-' + _zonaSkuId(sku)), c = $('kgC-' + _zonaSkuId(sku)); if (!b) return; const open = b.style.display !== 'none'; b.style.display = open ? 'none' : ''; if (c) c.textContent = open ? '▸' : '▾'; try { _zonaSfx('tick'); _zonaVibrar(8); } catch (_) {} }
  function zonaKgBuscar(v) { S._zonaKgQ = v || ''; _zonaKgRender(); }
  function zonaKgVerCodigo(cb, sku) {
    const p = (S.zonaProductos || []).find(x => String(x.skuBase || x.idProducto) === sku);
    const nm = (p && (p.descripcion || p.nombre)) || cb;
    const esAlm = _esZonaAlmacen({ idZona: S.zonaActual, nombre: ((S.zonaList || []).find(x => (x.idZona || x.id || x.nombre) === S.zonaActual) || {}).nombre });
    _zonaVerKardexCore(esAlm ? 'ALMACEN' : 'ZONA', esAlm ? { codBarra: cb, _nombre: nm } : { codBarra: cb, zona: S.zonaActual, _nombre: nm });
  }
  // Exportación: aplana producto→código→stock y baja CSV(Excel) / XML / PDF(imprimir).
  function _zonaKgFilas() {
    const out = [];
    _zonaKgProductos().forEach(p => {
      const nm = String(p.descripcion || p.nombre || p.skuBase || '');
      const cods = Array.isArray(p.codigos) ? p.codigos : [];
      if (!cods.length) { out.push({ producto: nm, codigo: '', tipo: '', stock: _zonaNum(p.stockZona != null ? p.stockZona : p.stock) }); }
      cods.forEach(c => out.push({ producto: nm, codigo: String(c.codBarra || ''), tipo: c.esEquivalente ? 'equivalente' : 'canónico', stock: _zonaNum(c.stock) }));
    });
    return out;
  }
  function zonaKgExport(fmt) {
    const filas = _zonaKgFilas();
    const zona = String(S.zonaActual || 'zona'); const fname = 'kardex_' + zona + '_' + _zonaHoyStr();
    if (fmt === 'csv') {
      const esc = s => '"' + String(s).replace(/"/g, '""') + '"';
      const body = filas.map(f => [esc(f.producto), esc(f.codigo), esc(f.tipo), f.stock].join(',')).join('\r\n');
      _zonaDescargar('﻿Producto,Codigo,Tipo,Stock\r\n' + body, fname + '.csv', 'text/csv;charset=utf-8');
    } else if (fmt === 'xml') {
      const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
      const xml = '<?xml version="1.0" encoding="UTF-8"?>\n<kardex zona="' + esc(zona) + '">\n' + filas.map(f => `  <item producto="${esc(f.producto)}" codigo="${esc(f.codigo)}" tipo="${esc(f.tipo)}" stock="${f.stock}"/>`).join('\n') + '\n</kardex>';
      _zonaDescargar(xml, fname + '.xml', 'application/xml;charset=utf-8');
    } else if (fmt === 'pdf') { _zonaKgImprimirPDF(filas, zona); }
    try { _zonaSfx('ok'); _zonaVibrar(20); } catch (_) {}
  }
  function _zonaDescargar(content, filename, mime) {
    try {
      const blob = new Blob([content], { type: mime }); const url = URL.createObjectURL(blob);
      const a = document.createElement('a'); a.href = url; a.download = filename; document.body.appendChild(a); a.click();
      setTimeout(() => { try { document.body.removeChild(a); URL.revokeObjectURL(url); } catch (_) {} }, 300);
      toast('Descargando ' + filename, 'ok');
    } catch (e) { toast('No se pudo descargar: ' + (e.message || e), 'error'); }
  }
  function _zonaKgImprimirPDF(filas, zona) {
    const w = window.open('', '_blank'); if (!w) { toast('Habilita las ventanas emergentes para el PDF', 'error'); return; }
    const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    const rows = filas.map(f => `<tr class="${f.stock < 0 ? 'neg' : ''}"><td>${esc(f.producto)}</td><td>${esc(f.codigo)}</td><td>${esc(f.tipo)}</td><td style="text-align:right">${f.stock}</td></tr>`).join('');
    w.document.write('<html><head><title>Kardex ' + esc(zona) + '</title><style>body{font-family:Arial,sans-serif;padding:18px;color:#111}h1{font-size:18px;margin:0 0 4px}table{width:100%;border-collapse:collapse;font-size:12px;margin-top:10px}th,td{border:1px solid #ccc;padding:5px 7px}th{background:#f0f0f0;text-align:left}tr.neg td{color:#c00;font-weight:bold}</style></head><body><h1>Kardex de stock &middot; ' + esc(zona) + '</h1><div style="font-size:12px;color:#555">' + esc(new Date().toLocaleString()) + '</div><table><thead><tr><th>Producto</th><th>C&oacute;digo</th><th>Tipo</th><th>Stock</th></tr></thead><tbody>' + rows + '</tbody></table><scr' + 'ipt>window.onload=function(){setTimeout(function(){window.print();},250);}</scr' + 'ipt></body></html>');
    w.document.close();
  }
  function _zonaHoyStr() { try { return new Date().toISOString().slice(0, 10); } catch (_) { return 'hoy'; } }
  // [908] Exporta EL kardex abierto (movimientos del tab/código activo) a Excel(CSV)/XML/PDF.
  function zonaKardexExport(fmt) {
    const st = _zonaKardexEstado;
    if (!st || !st.data) { toast('Abre un kardex primero', 'error'); return; }
    const tab = (st.tabs || []).find(t => t.id === st.activa) || (st.tabs || [])[0] || {};
    const d = (tab && tab.data) || st.data || {};
    const movs = Array.isArray(d.movimientos) ? d.movimientos : [];
    if (!movs.length) { toast('Este kardex no tiene movimientos', 'error'); return; }
    const nombre = ($('zonaKardexTitulo') && $('zonaKardexTitulo').textContent) || 'kardex';
    const cual = tab.esTotal ? 'total' : String(tab.id || '');
    const fname = 'kardex_' + String(nombre).replace(/[^\w]+/g, '_').slice(0, 30) + (cual ? '_' + cual : '') + '_' + _zonaHoyStr();
    const filas = movs.map(m => ({ fecha: String(m.fecha || '').slice(0, 16), tipo: String(m.tipo || ''), delta: _zonaNum(m.delta), saldo: (m.saldo_despues != null ? _zonaNum(m.saldo_despues) : ''), usuario: String(m.usuario || ''), codigo: String(m.cod_barra || '') }));
    if (fmt === 'csv') {
      const e = s => '"' + String(s).replace(/"/g, '""') + '"';
      const body = filas.map(f => [e(f.fecha), e(f.tipo), f.delta, f.saldo, e(f.usuario), e(f.codigo)].join(',')).join('\r\n');
      _zonaDescargar('﻿Fecha,Tipo,Delta,Saldo,Usuario,Codigo\r\n' + body, fname + '.csv', 'text/csv;charset=utf-8');
    } else if (fmt === 'xml') {
      const e = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
      const xml = '<?xml version="1.0" encoding="UTF-8"?>\n<kardex producto="' + e(nombre) + '" alcance="' + e(cual) + '">\n' + filas.map(f => `  <mov fecha="${e(f.fecha)}" tipo="${e(f.tipo)}" delta="${f.delta}" saldo="${f.saldo}" usuario="${e(f.usuario)}" codigo="${e(f.codigo)}"/>`).join('\n') + '\n</kardex>';
      _zonaDescargar(xml, fname + '.xml', 'application/xml;charset=utf-8');
    } else if (fmt === 'pdf') {
      const w = window.open('', '_blank'); if (!w) { toast('Habilita las ventanas emergentes para el PDF', 'error'); return; }
      const e = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
      const rows = filas.map(f => `<tr class="${f.delta < 0 ? 'neg' : ''}"><td>${e(f.fecha)}</td><td>${e(f.tipo)}</td><td style="text-align:right">${f.delta}</td><td style="text-align:right">${f.saldo}</td><td>${e(f.usuario)}</td><td>${e(f.codigo)}</td></tr>`).join('');
      w.document.write('<html><head><title>Kardex ' + e(nombre) + '</title><style>body{font-family:Arial,sans-serif;padding:18px;color:#111}h1{font-size:16px;margin:0 0 4px}table{width:100%;border-collapse:collapse;font-size:11px;margin-top:8px}th,td{border:1px solid #ccc;padding:4px 6px}th{background:#f0f0f0;text-align:left}tr.neg td{color:#c00;font-weight:bold}</style></head><body><h1>Kardex &middot; ' + e(nombre) + (cual ? ' (' + e(cual) + ')' : '') + '</h1><div style="font-size:11px;color:#555">' + e(new Date().toLocaleString()) + '</div><table><thead><tr><th>Fecha</th><th>Tipo</th><th>Delta</th><th>Saldo</th><th>Usuario</th><th>C&oacute;digo</th></tr></thead><tbody>' + rows + '</tbody></table><scr' + 'ipt>window.onload=function(){setTimeout(function(){window.print();},250);}</scr' + 'ipt></body></html>');
      w.document.close();
    }
    try { _zonaSfx('ok'); _zonaVibrar(20); } catch (_) {}
  }

  // [913] Costo unitario del producto (del catálogo, por cualquiera de sus códigos) — para "S/ inmovilizado".
  function _zonaCostoUnit(item) {
    try {
      const idx = _prodIndex();
      const cods = Array.isArray(item.codigos) ? item.codigos : [];
      for (const c of cods) {
        const cb = String(c.codBarra != null ? c.codBarra : (c.codigoBarra != null ? c.codigoBarra : '')).trim();
        if (cb && idx.byCod.has(cb)) { const pr = idx.byCod.get(cb); const cost = _zonaNum(pr.precioCosto || pr.costo || pr.costoUnitario); if (cost > 0) return cost; }
      }
      const sku = String(item.skuBase || item.idProducto || '');
      if (sku && idx.byId.has(sku)) { const pr = idx.byId.get(sku); const cost = _zonaNum(pr.precioCosto || pr.costo || pr.costoUnitario); if (cost > 0) return cost; }
    } catch (_) {}
    return 0;
  }
  // [921] Foquito "en la otra zona hay": carga (lazy, cache por zona) el stock de las OTRAS zonas retail.
  async function _zonaCruzadoEnsure() {
    if (S._zonaCruzadoZona === S.zonaActual && S._zonaCruzado) return;
    if (S._zonaCruzadoLoading) return;
    S._zonaCruzadoLoading = true;
    try {
      const r = await API.zona.stockCruzado({ zona: S.zonaActual });
      const items = (r && (r.data || r) && ((r.data || r).items)) || [];
      // solo zonas RETAIL (no almacén). En este ecosistema me.stock_zonas ya es solo retail.
      const map = {};
      items.forEach(x => { const cod = String(x.cod); if (!map[cod]) map[cod] = { zona: x.zona, cant: 0 }; map[cod].cant += _zonaNum(x.cant); });
      S._zonaCruzado = map; S._zonaCruzadoZona = S.zonaActual;
    } catch (_) { S._zonaCruzado = {}; S._zonaCruzadoZona = S.zonaActual; }
    S._zonaCruzadoLoading = false;
    try { if (S.view === 'zona') renderZona(); } catch (_) {}
  }
  function _zonaCruzadoDe(item) {
    const map = S._zonaCruzado; if (!map) return null;
    const cods = Array.isArray(item.codigos) ? item.codigos : [];
    let cant = 0, zona = '';
    cods.forEach(c => { const cb = String(c.codBarra != null ? c.codBarra : (c.codigoBarra || '')); const e = map[cb]; if (e) { cant += e.cant; zona = e.zona; } });
    return cant > 0 ? { cant, zona } : null;
  }
  function _zonaNombreZona(id) {
    const z = (S.zonaList || []).find(x => (x.idZona || x.id || x.nombre) === id || String(x.idZona || x.id || '').toUpperCase() === String(id).toUpperCase());
    return (z && z.nombre) || id;
  }
  // [902] Chips de código (canónico + equivalentes) con su stock; editables (autoguardado) en modo Ajustar.
  function _zonaCodChipsHtml(sku, item) {
    const safe = _esc(sku);
    const step = _zonaStepAttr(item);
    const cods = Array.isArray(item.codigos) ? item.codigos : [];
    const chip = (cb, stockRaw, esEq) => {
      const cbSafe = _zonaEsc(String(cb));
      const st = _zonaFmtCant(_zonaNum(stockRaw), item, true);
      const neg = _zonaNum(stockRaw) < 0;
      const lbl = String(cb) === '__GLOBAL__' ? 'stock' : String(cb);   // [904] código de barra COMPLETO (no truncado: hay que distinguir el con/sin cero)
      const gran = !!item.esGranel;
      return `<span class="zc-chip${esEq ? ' is-eq' : ''}${neg ? ' is-neg' : ''}" title="${_esc(String(cb))}${esEq ? ' · equivalente' : ''}${neg ? ' · STOCK NEGATIVO: ajustar' : ''}">
        ${neg ? '<span class="zc-chip-warn" title="Stock negativo — toca Ajustar para corregir">⚠</span>' : ''}
        <span class="zc-chip-cod">${_esc(lbl)}${esEq ? ' ≈' : ''}</span>
        <span class="zc-chip-st"><b>${_esc(st)}</b>${gran ? ' <i>kg</i>' : ''}</span>
        <input class="zc-chip-in" type="number" step="${gran ? 'any' : step}" inputmode="decimal" value="${_esc(st)}" data-unit="kg"
          onchange="MOS.zonaChipSave('${safe}','${cbSafe}',this)" onkeydown="if(event.key==='Enter'){this.blur();}">${gran ? `<button type="button" class="zc-chip-uni" onclick="MOS.zonaChipUnidad(this)" title="Cambiar entre kilos y gramos (se guarda en kg)">kg</button>` : ''}</span>`;
    };
    if (!cods.length) return chip('__GLOBAL__', item.stockZona != null ? item.stockZona : item.stock, false);
    return cods.map(c => chip(c.codBarra != null ? c.codBarra : (c.codigoBarra != null ? c.codigoBarra : ''), c.stock, !!c.esEquivalente)).join('');
  }
  // Alterna modo edición de los chips (autoguardado). Al salir, refresca el card (gauge/cuadrante).
  function zonaAjustarToggle(sku) {
    const box = $('zChips-' + _zonaSkuId(sku));
    const btn = $('zAjBtn-' + _zonaSkuId(sku));
    if (!box) return;
    const editing = box.classList.toggle('editing');
    if (btn) { btn.textContent = editing ? '✓ Listo' : '✏️ Ajustar'; btn.classList.toggle('is-on', editing); }
    try { _zonaSfx('pop'); _zonaVibrar(15); } catch (_) {}
    if (editing) {
      const inp = box.querySelector('.zc-chip-in'); if (inp) { try { inp.focus(); inp.select(); } catch (_) {} }
      // [905] Tocar AFUERA = dar por guardado y cerrar. Antes de salir, forzamos el blur del input
      //   activo (dispara su onchange/autoguardado) para no perder el último valor.
      setTimeout(() => {
        const onDoc = (ev) => {
          if (box.contains(ev.target)) return;                 // dentro de los chips → sigue editando
          if (btn && btn.contains(ev.target)) return;           // el botón "✓ Listo" hace su propio toggle
          const ae = document.activeElement;
          if (ae && ae.classList && ae.classList.contains('zc-chip-in')) { try { ae.blur(); } catch (_) {} }
          document.removeEventListener('pointerdown', onDoc, true);
          box._offClick = null;
          if (box.classList.contains('editing')) zonaAjustarToggle(sku);
        };
        box._offClick = onDoc;
        document.addEventListener('pointerdown', onDoc, true);
      }, 0);
    } else {
      if (box._offClick) { try { document.removeEventListener('pointerdown', box._offClick, true); } catch (_) {} box._offClick = null; }
      renderZona();
    }
  }
  // Autoguarda un chip (un código, o el global si el producto no tiene desglose). Optimista + rollback.
  // [913] Granel: alterna la unidad de captura entre kg y g (se guarda SIEMPRE en kg → kardex en kg).
  function zonaChipUnidad(btn) {
    const chip = btn.parentNode; const inp = chip && chip.querySelector('.zc-chip-in'); if (!inp) return;
    const cur = inp.dataset.unit || 'kg'; const val = parseFloat(inp.value) || 0;
    if (cur === 'kg') { inp.dataset.unit = 'g'; inp.value = String(Math.round(val * 1000)); btn.textContent = 'g'; inp.step = '1'; }
    else { inp.dataset.unit = 'kg'; inp.value = String(_money(val / 1000)); btn.textContent = 'kg'; inp.step = 'any'; }
    try { inp.focus(); inp.select(); } catch (_) {}
    try { _zonaSfx('tick'); _zonaVibrar(8); } catch (_) {}
  }
  async function zonaChipSave(sku, cb, el) {
    const p = S.zonaProductos.find(x => String(x.skuBase || x.idProducto) === sku);
    if (!p || !el) return;
    let nuevo = _zonaParseCant(el.value, !!p.esGranel);
    if (el.dataset && el.dataset.unit === 'g') nuevo = _money(nuevo / 1000);   // gramos → kilos
    const esGlobal = (cb === '__GLOBAL__');
    const c = esGlobal ? null : _zonaCodFind(p, cb);
    const antes = esGlobal ? _zonaNum(p.stockZona != null ? p.stockZona : p.stock) : (c ? _zonaNum(c.stock) : 0);
    if (!esGlobal && !c) return;
    if (nuevo === antes) return;
    // optimista
    if (esGlobal) { if (p.stockZona != null) p.stockZona = nuevo; else p.stock = nuevo; } else { c.stock = nuevo; }
    _zonaRecalcGlobal(p); _zonaPintarKpis();
    try { _zonaSfx('ok'); _zonaVibrar(20); } catch (_) {}
    toast((esGlobal ? 'Stock' : 'Código') + ' ajustado a ' + _zonaFmtCant(nuevo, p), 'ok');
    try {
      let r;
      if (esGlobal) { const lid = p._ajLocalId || (p._ajLocalId = _zonaAjusteLocalId('GLOBAL')); r = await API.zona.ajustarStock({ zona: S.zonaActual, skuBase: sku, nuevo, localId: lid }); delete p._ajLocalId; }
      else { const lid = c._ajLocalId || (c._ajLocalId = _zonaAjusteLocalId(cb)); r = await _zonaAplicarAjusteCodigo(String(cb), nuevo, lid); delete c._ajLocalId; }
      if (r == null || r.ok === false) throw new Error((r && r.error) || 'sin commit');
    } catch (e) {
      if (esGlobal) { if (p.stockZona != null) p.stockZona = antes; else p.stock = antes; } else { c.stock = antes; }
      _zonaRecalcGlobal(p); try { el.value = _zonaFmtCant(antes, p, true); } catch (_) {}
      try { _zonaSfx('error'); _zonaVibrar([120, 40, 120]); } catch (_) {}
      toast('No se guardó: ' + (e.message || e), 'error');
    }
  }
  // Abre/cierra una sección del card (Por qué / Historial), tipo "el card se abre en datos". Lazy-load.
  function zonaSecToggle(sku, which) {
    const id = 'zt' + (which === 'pq' ? 'Pq' : 'Hx') + '-wrap-' + _zonaSkuId(sku);
    const wrap = $(id);
    if (!wrap) return;
    const open = wrap.style.display !== 'none';
    if (open) { wrap.style.display = 'none'; try { _zonaSfx('tick'); _zonaVibrar(8); } catch (_) {} return; }
    wrap.style.display = '';
    try { _zonaSfx('pop'); _zonaVibrar([14, 8]); } catch (_) {}
    if (wrap.dataset.cargado !== '1') { wrap.dataset.cargado = '1'; (which === 'pq' ? _zonaSecCargarPq : _zonaSecCargarHx)(sku); }
  }
  // [920] Gráfico de DEMANDA en almacén: despachado (azul) + DEUDA (ámbar = demanda insatisfecha).
  // [926] Metadatos de cada SERIE (color) del gráfico de demanda de almacén. Barras LADO A LADO por semana;
  //   cada barra es CLICKEABLE y explica de dónde sale su monto (super intuitivo, sin texto gigante arriba).
  const _ZBAR = {
    despacho:       { cls:'dbz-desp', ico:'🔵', lbl:'Despachado a zona',  desc:'salió como producto a las zonas' },
    envasado:       { cls:'dbz-env',  ico:'🟣', lbl:'Envasado',           desc:'se usó para hacer sus derivados' },
    deudaPropia:    { cls:'dbz-dp',   ico:'🟡', lbl:'Deuda propia',       desc:'lo que pidieron y aún no se despacha' },
    deudaDerivados: { cls:'dbz-dd',   ico:'🟠', lbl:'Deuda de derivados', desc:'lo que deben sus derivados (convertido)' },
  };
  function _dbzAttr(s) { return String(s).replace(/"/g, '&quot;'); }
  // Descripción de cada barra según sea GRANEL o INSUMO (el celofán se despacha, se gasta al envasar,
  //   se debe por sí mismo, y se debe por los productos que lo usan). Super claro al clickear.
  function _dbzDesc(k, esInsumo) {
    if (k === 'despacho')    return esInsumo ? 'se despachó este insumo a las zonas' : 'salió como producto a las zonas';
    if (k === 'envasado')    return esInsumo ? 'se gastó como bolsa/insumo al envasar' : 'se usó para hacer sus derivados';
    if (k === 'deudaPropia') return 'se pidió y aún no se despacha (deuda del propio producto)';
    if (k === 'deudaDerivados') return esInsumo ? 'el insumo que necesitan los productos que lo usan y se deben' : 'lo que deben sus derivados, convertido a granel';
    return _ZBAR[k].desc;
  }
  // [928] Gráfico de demanda de almacén (granel/insumo/regular): columnas semanales de ROTACIÓN
  //   (🔵 despacho + 🟣 envasado) + columna "se debe" (🟡 deuda propia rezagada, por zona) + columna
  //   "derivados" (🟠 lo que deben sus derivados). Barras clickeables; el tip explica de dónde sale.
  //   META = smart(rotación semanal) + deuda propia + deuda de derivados. Compra = meta − stock.
  function _zonaNombreZonaSafe(id) { try { return _zonaNombreZona(id) || id; } catch (_) { return id; } }
  // [929] Gráfico SEMANA POR SEMANA: 4 columnas (una por semana), y DENTRO de cada semana varias barras de
  //   color según corresponda: 🔵 despacho · 🟡 deuda insatisfecha (por zona) · 🟣 envasado · 🟠 deuda de
  //   derivados. Cada barra es clickeable y explica de dónde sale (la 🟡 dice la zona, la 🟠 el derivado).
  function _zonaDemandaRezRender(p, data) {
    const sem = (data && data.semanas) || [];
    const esInsumo = !!(data && data.esInsumo), uni = !esInsumo;
    const hijos = (data && data.hijos) || [];
    const stock = _zonaNum(data && data.stock);
    const vals = sem.reduce((a, s) => a.concat([_zonaNum(s.despacho), _zonaNum(s.deuda), _zonaNum(s.envasado), _zonaNum(s.deudaDeriv)]), []);
    if (!vals.some(v => v > 0))
      return `<div class="dbz-empty">Sin movimiento ni deuda en las últimas 4 semanas.<br><small>Tienes ${_esc(_zonaFmtCant(stock, p, true))} en stock.</small></div>`;
    const maxV = Math.max(1, ...vals);
    const h = (v) => Math.max(8, Math.round(v / maxV * 70));
    const fmt = (v) => _esc(_zonaFmtNumRaw(v, uni)) + (esInsumo ? ' MIL' : '');
    const LBL = ['hace 4 sem', 'hace 3 sem', 'hace 2 sem', 'última'];
    const A = _dbzAttr;
    const bar = (v, cls, exp) => v > 0 ? `<div class="dbz-bar ${cls}" style="height:${h(v)}px" data-exp="${A(exp)}" onclick="MOS.zonaDbzTip(this)"></div>` : '';
    const cols = sem.map((s, i) => {
      const d = _zonaNum(s.despacho), du = _zonaNum(s.deuda), e = _zonaNum(s.envasado), dd = _zonaNum(s.deudaDeriv);
      const zExp = ((s.deudaZonas || []).length) ? `<br><span class="dbz-sub">${(s.deudaZonas).map(z => `${_esc(_zonaNombreZonaSafe(z.zona))}: ${_esc(_zonaFmtNumRaw(_zonaNum(z.pend), uni))}`).join('<br>')}</span>` : '';
      let hExp = '';
      if (dd > 0) {
        const parts = hijos.map(x => { const ap = _zonaNum((x.aporteSem || [])[i]); return ap > 0 ? `${_esc(x.nombre || x.cod)}: ${_esc(_zonaFmtNumRaw(ap, uni))}${esInsumo ? ' MIL' : ''}` : ''; }).filter(Boolean);
        if (parts.length) hExp = `<br><span class="dbz-sub">${esInsumo ? 'lo usan y se deben:' : 'derivados que se deben:'}<br>${parts.join('<br>')}</span>`;
      }
      const bars = bar(d, 'dbz-desp', `🔵 <b>Despachado a zona</b> · ${LBL[i]}<br><b>${fmt(d)}</b> — ${_dbzDesc('despacho', esInsumo)}`)
                 + bar(du, 'dbz-dp', `🟡 <b>Se debe</b> · ${LBL[i]}<br><b>${fmt(du)}</b> — lo que se pidió y no se despachó${zExp}`)
                 + bar(e, 'dbz-env', `🟣 <b>Envasado</b> · ${LBL[i]}<br><b>${fmt(e)}</b> — ${_dbzDesc('envasado', esInsumo)}`)
                 + bar(dd, 'dbz-dd', `🟠 <b>Derivados deben</b> · ${LBL[i]}<br><b>${fmt(dd)}</b> — ${_dbzDesc('deudaDerivados', esInsumo)}${hExp}`);
      return `<div class="dbz-wk"><div class="dbz-bars">${bars || '<div class="dbz-none"></div>'}</div><div class="dbz-wklbl">${LBL[i] || ''}</div></div>`;
    }).join('');
    // [931] Meta INTELIGENTE = smart(DEMANDA SEMANAL). Cada semana = despacho+deuda+envasado+deudaDeriv;
    //   el smart analiza el comportamiento (si cae, proyecta bajo → la deuda vieja no infla). Compra = meta − stock.
    const demandaSem = sem.map(s => _zonaNum(s.despacho) + _zonaNum(s.deuda) + _zonaNum(s.envasado) + _zonaNum(s.deudaDeriv));
    const deudaTot = sem.reduce((a, s) => a + _zonaNum(s.deuda) + _zonaNum(s.deudaDeriv), 0);
    const meta = _zonaMetaSmart(demandaSem, 0.20), comprar = Math.max(0, meta - stock);
    return `<div class="dbz-chart">
      <div class="dbz-weeks">${cols}</div>
      <div class="dbz-tip">👆 Toca una barra para ver de dónde sale (la 🟡 dice a qué zona se debe)</div>
      <div class="dbz-calc">Meta <b class="dbz-res">${_esc(_zonaFmtCant(meta, p, true))}</b> · tienes <b>${_esc(_zonaFmtCant(stock, p, true))}</b> → ${comprar > 0 ? ('comprar <b class="dbz-buy">' + _esc(_zonaFmtCant(comprar, p, true)) + '</b> al proveedor') : (deudaTot > 0 ? '<b class="dbz-ok">tienes stock ✓ — despacha lo que debes</b>' : '<b class="dbz-ok">cubierto ✓</b>')}</div>
    </div>`;
  }
  // Al tocar una barra, el tip muestra su explicación (de dónde sale ese monto).
  function zonaDbzTip(el) {
    try {
      const chart = el.closest('.dbz-chart'); if (!chart) return;
      const tip = chart.querySelector('.dbz-tip'); if (!tip) return;
      tip.innerHTML = el.getAttribute('data-exp') || '';
      tip.classList.add('on');
      chart.querySelectorAll('.dbz-bar.on').forEach(b => b.classList.remove('on'));
      el.classList.add('on');
      try { _zonaSfx('tick'); _zonaVibrar(8); } catch (_) {}
    } catch (_) {}
  }
  // [931] Meta y compra a partir del item BULK ({sem[4]=demanda semanal, stock}). meta = smart(demanda_sem).
  function _zonaEnvMetaCompra(it) {
    const meta = _zonaMetaSmart((it && it.sem) || [], 0.20);
    const stock = _zonaNum(it && it.stock);
    return { meta, stock, comprar: Math.max(0, meta - stock) };
  }
  async function _zonaSecCargarPq(sku) {
    const p = S.zonaProductos.find(x => String(x.skuBase || x.idProducto) === sku); if (!p) return;
    const el = $('ztPq-' + _zonaSkuId(sku)); if (!el) return;
    const esAlm = _esZonaAlmacen({ idZona: S.zonaActual, nombre: ((S.zonaList || []).find(x => (x.idZona || x.id || x.nombre) === S.zonaActual) || {}).nombre });
    if (esAlm) {
      // [928] Almacén (granel/insumo/regular): rotación semanal + deuda REZAGADA (propia + de derivados).
      let dem = (S._zonaRezDem || {})[String(sku).toUpperCase()];
      if (!dem) {
        try {
          const rg = await API.zona.demandaRez({ skus: [sku] });
          const it = ((rg && (rg.data || rg) && (rg.data || rg).items) || [])[0];
          if (it) { S._zonaRezDem = S._zonaRezDem || {}; dem = S._zonaRezDem[String(sku).toUpperCase()] = Object.assign({}, it, { _ts: Date.now() }); }
        } catch (_) {}
      }
      el.innerHTML = dem ? _zonaDemandaRezRender(p, dem) : '<div class="dbz-empty">No se pudo calcular la demanda.</div>';
    } else {
      const dias = await _zonaDiasFetch(sku);   // zona: detalle diario (venta)
      el.innerHTML = _zonaEsperadoRender(p, dias);
    }
  }
  async function _zonaSecCargarHx(sku) {
    const p = S.zonaProductos.find(x => String(x.skuBase || x.idProducto) === sku); if (!p) return;
    const el = $('ztHx-' + _zonaSkuId(sku)); if (!el) return;
    // [903] Hay DOS kardex: el de ALMACÉN (WH) y el de ZONA (me.stock_movimientos zona1/zona2).
    //   Según el puesto activo se pide el correcto (antes siempre pedía el de zona → vacío en almacén).
    const esAlm = _esZonaAlmacen({ idZona: S.zonaActual, nombre: ((S.zonaList || []).find(x => (x.idZona || x.id || x.nombre) === S.zonaActual) || {}).nombre });
    try {
      const r = esAlm ? await API.zona.almacenKardex({ skuBase: sku }) : await API.zona.kardexHistorial({ skuBase: sku, zona: S.zonaActual });
      el.innerHTML = _zonaKardexInlineHtml((r && r.data) || r || {}, p);
    } catch (e) { el.innerHTML = '<div class="zt-mut">No se pudo cargar el historial.</div>'; }
  }

  // ══ [RIZ #4 · PROVEEDORES POR CANÓNICO] (solo ALMACEN) ════════════════════════════════════════════════════
  // Reemplaza la métrica redundante "Almacén" por la lista de proveedores REALES del canónico (sku_base),
  // agrupando todos los códigos del grupo y ocultando "PROVEEDOR DESCONOCIDO". Lazy: el render pinta el estado
  // del cache (cargando / lista / hint "sin proveedor"); _zonaProvCargarVisibles dispara UNA sola RPC batch
  // por todos los skus visibles tras el render (no encarece el panel: 1 llamada para todas las cards).
  function _zonaProvBlockHtml(sku) {
    const entry = S._zonaProvCache && S._zonaProvCache[sku];
    if (entry === undefined) {
      // aún no cargado → placeholder discreto (se completa solo tras _zonaProvCargarVisibles).
      return `<span class="zona-prov-lbl">🏷 Proveedores</span><span class="zona-prov-loading">cargando…</span>`;
    }
    return _zonaProvListHtml(entry);
  }
  function _zonaProvListHtml(lista) {
    const arr = Array.isArray(lista) ? lista : [];
    if (!arr.length) {
      return `<span class="zona-prov-lbl">🏷 Proveedores</span><span class="zona-prov-none">sin proveedor registrado</span>`;
    }
    const chips = arr.map(pv => {
      const nm = _esc(String(pv.nombre || '').trim());
      const pr = _zonaNum(pv.precioRef);
      const de = _zonaNum(pv.diasEntrega);
      const extras = [];
      if (pr > 0) extras.push('S/ ' + _zonaFmtNumRaw(pr, false));
      if (de > 0) extras.push(de + 'd');
      const tip = extras.length ? ` title="${_esc(extras.join(' · '))}"` : '';
      const extraHtml = extras.length ? `<span class="zona-prov-extra">${_esc(extras.join(' · '))}</span>` : '';
      return `<span class="zona-prov-chip"${tip}>${nm}${extraHtml}</span>`;
    }).join('');
    return `<span class="zona-prov-lbl">🏷 Proveedores</span><span class="zona-prov-chips">${chips}</span>`;
  }
  // Carga (batch, 1 RPC) los proveedores de todos los skus de ALMACEN visibles que aún no estén en cache,
  // y refresca solo sus bloques en el DOM (sin re-render completo). Tolerante: si falla, deja los placeholders.
  async function _zonaProvCargarVisibles() {
    try {
      const nodes = Array.prototype.slice.call(document.querySelectorAll('.zona-prov[data-sku]'));
      if (!nodes.length) return;
      if (!S._zonaProvCache) S._zonaProvCache = {};
      const pend = [];
      nodes.forEach(n => { const sk = n.getAttribute('data-sku'); if (sk && S._zonaProvCache[sk] === undefined && pend.indexOf(sk) < 0) pend.push(sk); });
      if (!pend.length) return;   // todo cacheado → nada que pedir
      const r = await API.zona.proveedores({ skus: pend });
      const data = (r && r.data) || r || {};
      const provs = (data && data.proveedores) || {};
      // Marcar todos los pedidos como resueltos (los que no vinieron → [] = sin proveedor).
      pend.forEach(sk => { S._zonaProvCache[sk] = Array.isArray(provs[sk]) ? provs[sk] : []; });
      // Refrescar solo los bloques en el DOM (las cards pueden haber cambiado; consultamos por sku actual).
      Array.prototype.slice.call(document.querySelectorAll('.zona-prov[data-sku]')).forEach(n => {
        const sk = n.getAttribute('data-sku');
        if (sk && S._zonaProvCache[sk] !== undefined) n.innerHTML = _zonaProvListHtml(S._zonaProvCache[sk]);
      });
    } catch (e) {
      try { console.warn('[RIZ] _zonaProvCargarVisibles:', e && (e.message || e)); } catch (_) {}
    }
  }
  // [925] Meta del GRANEL envasable = Σ(faltante_derivado × fcb). Para los graneles visibles en ALMACÉN,
  //   pide al RPC la cantidad a COMPRAR (necesario − stock) y rellena su botón "🧾 Comprar N a proveedor".
  //   Cachea por sku (5 min) en S._zonaGranelDem (también lo usa el "¿Por qué?").
  // [928] Rellena el botón "Comprar N a proveedor" de graneles/insumos desde el BULK ya cargado
  //   (S._zonaAlmDem: sem+pend+pendDeriv+stock). Sin fetch extra: reusa lo que trajo _zonaAlmDemAsegurar.
  async function _zonaGranelCargarVisibles() {
    try {
      if (!_zonaActualEsAlmacen()) return;
      const cont = $('zonaLista'); if (!cont) return;
      Array.prototype.slice.call(cont.querySelectorAll('.zona-card[data-sku]')).forEach(el => {
        const sku = el.getAttribute('data-sku');
        const btn = document.getElementById('zGbuy-' + _zonaSkuId(sku)); if (!btn) return;
        const dem = (S._zonaAlmDem || {})[String(sku).toUpperCase()];
        const p = (S.zonaProductos || []).find(x => String(x.skuBase || x.idProducto) === sku);
        if (!dem) { btn.disabled = true; btn.textContent = '🧾 Calculando…'; return; }
        const mc = _zonaEnvMetaCompra(dem);
        if (mc.comprar > 0) {
          btn.disabled = false;
          btn.textContent = '🧾 Comprar ' + _zonaFmtCant(mc.comprar, p) + ' a proveedor';
          btn.onclick = () => { try { MOS.zonaAgregarLista(sku, mc.comprar); } catch (_) {} };
        } else {
          btn.disabled = true;
          btn.textContent = '✓ Cubierto (nada por comprar)';
          btn.onclick = null;
        }
        btn.title = 'Meta = ' + _zonaFmtCant(mc.meta, p) + ' · tienes ' + _zonaFmtCant(mc.stock, p);
      });
    } catch (e) {
      try { console.warn('[RIZ] _zonaGranelCargarVisibles:', e && (e.message || e)); } catch (_) {}
    }
  }
  // Compat / re-tap manual: recarga proveedores de un sku puntual (fuerza refetch) y repinta su bloque.

  // [MEJORA 5] Renderiza la fila de un código dentro del disclosure (lista + editar por código).
  // [192] Fila minimal por código: SOLO el código + su stock + input set-absoluto. SIN nombres/descripciones
  // (la card ya tiene el nombre grande; muchos equivalentes no tienen nombre propio → ruido). Chip "equiv"
  // discreto para distinguir el código equivalente del canónico.
  function _zonaCodRowHtml(sku, c, item) {
    const safe = _esc(sku);
    const cb   = String(c.codBarra != null ? c.codBarra : (c.codigoBarra != null ? c.codigoBarra : ''));
    const cbSafe = _zonaEsc(cb);
    const cbAttr = _esc(cb);
    const st   = _zonaFmtCant(c.stock, item, true);
    const equiv = c.esEquivalente ? '<span class="zona-cod-equiv" title="Código equivalente">equiv</span>' : '';
    const step = _zonaStepAttr(item);
    const cid = 'zCodIn-' + safe + '-' + _zonaCodKey(cb);
    return `<div class="zona-cod-row">
      <div class="zona-cod-info">
        <div class="zona-cod-cb">${cbAttr} ${equiv}</div>
        <div class="zona-cod-st">stock <b>${_esc(st)}</b></div>
      </div>
      <div class="zona-cod-edit">
        <input type="number" inputmode="decimal" step="${step}" class="zona-cod-input" id="${cid}" value="${_esc(_zonaFmtCant(c.stock, item, true))}">
        <button class="zona-mini-btn zona-mini-cero" onclick="MOS.zonaCodCero('${safe}','${cbSafe}')" title="Poner en cero">Cero</button>
        <button class="zona-mini-btn zona-mini-ok" onclick="MOS.zonaCodGuardar('${safe}','${cbSafe}')" title="Guardar">✓</button>
      </div>
    </div>`;
  }
  // Clave DOM-safe para un código de barra (puede traer caracteres raros).
  function _zonaCodKey(cb) { return String(cb).replace(/[^A-Za-z0-9]/g, '_'); }

  // ── Selector / filtros / orden ─────────────────────────────────────────
  function zonaCambiarZona(idZona) {
    S.zonaActual = idZona; S.zonaProductos = [];
    try { _zonaAnclaSet(idZona); _zonaHubActualizarChip(idZona); } catch (_) {}   // [891] persistir el puesto anclado
    // [RIZ #1] Resetear el filtro "del día" al cambiar de ámbito (el set cacheado es por zona+fecha).
    S._zonaDiaFiltro = { modo: 'todos', offset: 0 }; S._zonaDiaSet = null; S._zonaDiaSetKey = null;
    // [976] Invalidar el cache de "Por activar" (es POR ZONA): se recarga limpio en el nuevo puesto (sin descartados).
    S._zonaPorActivar = { zona: null, items: [], nDescartados: 0, cargando: false, verDescartados: false, _cargado: false, _verCargado: false };
    _zonaCargarPanel(true);
  }

  // ══ [891] HUB DE PUESTOS (selector tipo Netflix) — el admin elige su puesto (Almacén / Zona 1 /
  //    Zona 2), se ANCLA (localStorage), y cambia tocando el chip del encabezado (como cambiar de
  //    usuario). Reusa zonaCambiarZona; las vitales finas viven dentro del puesto. ════════════════
  const _ZONA_ANCLA_KEY = 'mos_zona_ancla_v1';
  function _zonaAnclaGet() { try { return localStorage.getItem(_ZONA_ANCLA_KEY) || ''; } catch (_) { return ''; } }
  function _zonaAnclaSet(id) { try { localStorage.setItem(_ZONA_ANCLA_KEY, String(id || '')); } catch (_) {} }
  function _zonaEsMock(id, nm) { const s = (String(id || '') + String(nm || '')).toUpperCase(); return s.indexOf('MOCK') >= 0 || s.indexOf('FALLBACK') >= 0; }

  function _zonaHubStationsHtml() {
    const anchored = S.zonaActual;
    const vit = S._zonaHubVit || {};
    const zonas = (S.zonaList || []).filter(z => !_zonaEsMock(z.idZona || z.id || z.nombre, z.nombre));
    if (!zonas.length) return '<div class="zhub-empty">Sin puestos disponibles</div>';
    return zonas.map(z => {
      const id = z.idZona || z.id || z.nombre;
      const nm = z.nombre || id;
      const esAlm = _esZonaAlmacen({ idZona: id, nombre: nm });
      const v = vit[id] || null;
      const prod = v ? v.productos : null;
      const neg = v ? v.negativos : null;
      const isAnc = id === anchored;
      const safeId = _esc(String(id));
      // Vitales: si ya visitaste el puesto, mostramos los cuadrantes reales (pedir/muertos) desde el
      // cache; si no, caemos a productos+negativos (baratos, de la RPC). Se enriquece al entrar.
      const cq = _zonaVitCuadGet(id);
      let vitalsHtml = '';
      if (cq && (cq.pedir || cq.muerto || cq.sobra)) {
        vitalsHtml = `<span class="zhub-vpill neg">🔴 ${cq.pedir} pedir</span><span class="zhub-vpill dead">⚫ ${cq.muerto} muertos</span>`;
      } else if (neg > 0) {
        vitalsHtml = `<span class="zhub-vpill neg">⚠ ${neg} en negativo</span>`;
      } else if (v) {
        vitalsHtml = `<span class="zhub-vpill ok">✓ listo</span>`;
      }
      return `<button type="button" class="zhub-st${esAlm ? ' is-alm' : ''}${isAnc ? ' is-anchored' : ''}" onclick="MOS.zonaElegirPuesto('${safeId}')">
        ${isAnc ? '<span class="zhub-st-anc">● aquí estás</span>' : ''}
        <div class="zhub-st-ico">${esAlm ? '🏪' : '🏬'}</div>
        <div class="zhub-st-role">${esAlm ? 'Surte a las zonas' : 'Vende al público'}</div>
        <div class="zhub-st-name">${_esc(nm)}</div>
        <div class="zhub-st-count">${prod != null ? prod + ' productos con stock' : 'cargando…'}</div>
        <div class="zhub-st-vitals">${vitalsHtml}</div>
        <div class="zhub-st-enter">Entrar al puesto <span class="zhub-arw">→</span></div>
      </button>`;
    }).join('');
  }
  function zonaAbrirHub() {
    const box = $('zonaHub');
    if (!box) return;
    const cont = $('zonaHubStations');
    if (cont) cont.innerHTML = _zonaHubStationsHtml();
    box.classList.remove('hidden');
    requestAnimationFrame(() => box.classList.add('open'));
    try { _zonaSfx('pop'); _zonaVibrar(15); } catch (_) {}
    _zonaHubCargarVitales();
  }
  function zonaCerrarHub() {
    const box = $('zonaHub');
    if (!box) return;
    if (!_zonaAnclaGet() && !S.zonaActual) return;   // no cerrar sin haber elegido nunca
    box.classList.remove('open');
    setTimeout(() => { const b = $('zonaHub'); if (b && !b.classList.contains('open')) b.classList.add('hidden'); }, 240);
  }
  async function _zonaHubCargarVitales() {
    try {
      const r = await API.zona.resumen();
      const arr = (r && (r.data || r) && ((r.data || r).zonas)) || [];
      const map = {};
      arr.forEach(x => { map[x.zonaId] = { productos: _zonaNum(x.productos), negativos: _zonaNum(x.negativos) }; });
      S._zonaHubVit = map;
      const box = $('zonaHub'), cont = $('zonaHubStations');
      if (cont && box && !box.classList.contains('hidden')) cont.innerHTML = _zonaHubStationsHtml();
    } catch (_) {}
  }
  function zonaElegirPuesto(id) {
    if (!id) return;
    _zonaAnclaSet(id);
    _zonaHubActualizarChip(id);
    zonaCerrarHub();
    if (id !== S.zonaActual) zonaCambiarZona(id);
    else _zonaCargarPanel(false);
    try { _zonaSfx('pop'); _zonaVibrar([15, 10, 20]); } catch (_) {}
  }
  function _zonaHubActualizarChip(id) {
    id = id || S.zonaActual;
    const chip = $('zonaPuestoChipNom');
    if (!chip) return;
    const z = (S.zonaList || []).find(x => (x.idZona || x.id || x.nombre) === id);
    const nm = (z && z.nombre) || id || 'Puesto';
    const esAlm = _esZonaAlmacen({ idZona: id, nombre: nm });
    chip.textContent = (esAlm ? '🏪 ' : '🏬 ') + nm;
  }
  // [rev100 2.43.584] zonaRefrescar eliminado (su botón ⟳ se retiró; el panel se refresca solo).
  function zonaSetOrden(v) { S._zonaFiltros.orden = v; renderZona(); }
  function zonaFiltrar()   { S._zonaFiltros.q = ($('zonaSearch') && $('zonaSearch').value || '').trim(); renderZona(); }
  function zonaToggleKpi(kpi) {
    const f = S._zonaFiltros;
    if (f.kpi === kpi) { try { _zonaSfx('tick'); _zonaVibrar(8); } catch (_) {} return; }   // [899] ya es la pestaña activa
    f.kpi = kpi;
    document.querySelectorAll('#zonaKpis .zona-kpi').forEach(el => el.classList.toggle('active', el.dataset.kpi === f.kpi));
    try { _zonaSfx('pop'); _zonaVibrar(15); } catch (_) {}
    renderZona();
    // [902] barrido de luz al cambiar de cuadrante ("haz de luz a su listado")
    try {
      const l = $('zonaLista');
      if (l && !_zonaReduce()) { l.classList.remove('zona-lista-sweep'); void l.offsetWidth; l.classList.add('zona-lista-sweep'); setTimeout(() => { try { l.classList.remove('zona-lista-sweep'); } catch (_) {} }, 650); }
    } catch (_) {}
  }
  function zonaToggleTend(t) {
    const f = S._zonaFiltros;
    f.tend[t] = !f.tend[t];
    document.querySelectorAll('.zona-chip-f[data-tend]').forEach(el => el.classList.toggle('active', !!f.tend[el.dataset.tend]));
    _zonaSfx('tick'); _zonaVibrar(15);
    renderZona();
  }
  function zonaToggleFiltro(name) {
    const f = S._zonaFiltros;
    if (name === 'brecha') f.brecha = !f.brecha;
    document.querySelectorAll('.zona-chip-f[data-filtro]').forEach(el => { if (el.dataset.filtro === name) el.classList.toggle('active', f[name]); });
    _zonaSfx('tick'); _zonaVibrar(15);
    renderZona();
  }

  // ── Ajuste inline de stock (✎) — [MEJORA 4] input manual + "Cero" + stepper ──
  //   optimista + dual-write + revertir+shake. Decimales si esGranel.
  function zonaAjusteInline(sku) {
    const p = S.zonaProductos.find(x => String(x.skuBase || x.idProducto) === sku);
    if (!p) return;
    // [192 · MULTI-CÓDIGO] Si el producto tiene >1 código en el grupo (canónico + equivalentes), editar un
    // "total global" es ilógico (el set-absoluto único corrompería la suma → escribiría sólo un código). El ✎
    // NO abre el stepper global: despliega DIRECTO el ajuste por código (set-absoluto por cada barra).
    const codigosG = Array.isArray(p.codigos) ? p.codigos : [];
    if (codigosG.length > 1) {
      _zonaSfx('tick'); _zonaVibrar(15);
      _zonaAbrirCodigos(sku);   // abre el desglose (no togglea: siempre lo deja abierto)
      try { const body = $('zCodBody-' + _zonaSkuId(sku)); if (body) body.scrollIntoView({ behavior: 'smooth', block: 'nearest' }); } catch (_) {}
      return;
    }
    const cell = $('zStock-' + _zonaSkuId(sku));
    if (!cell) return;
    const cur = _zonaNum(p.stockZona != null ? p.stockZona : p.stock);
    const step = _zonaStepAttr(p);
    const val  = _zonaFmtCant(cur, p, true);
    const e    = _zonaEsc(sku);
    // Stepper + input numérico manual + botón "Cero" + confirmar. El input es la fuente de verdad.
    cell.innerHTML = `<span class="zona-stepper">
        <button class="zona-step-btn" onclick="MOS.zonaStep('${e}',-1)">−</button>
        <input type="number" inputmode="decimal" step="${step}" min="0" class="zona-step-input" id="zStep-${e}" value="${_esc(val)}" onkeydown="if(event.key==='Enter')MOS.zonaConfirmarAjuste('${e}')">
        <button class="zona-step-btn" onclick="MOS.zonaStep('${e}',1)">+</button>
        <button class="zona-step-btn zona-step-cero" onclick="MOS.zonaCero('${e}')" title="Poner en cero">0</button>
        <button class="zona-step-btn" style="background:#16a34a;border-color:#16a34a" onclick="MOS.zonaConfirmarAjuste('${e}')">✓</button>
      </span>`;
    const inp = $('zStep-' + sku);
    if (inp) { try { inp.focus(); inp.select(); } catch(_){} }
    _zonaSfx('tick'); _zonaVibrar(15);
  }
  function _zonaSkuId(sku) { return String(sku); }
  function _zonaEsc(s) { return String(s).replace(/'/g, "\\'"); }
  function _zonaLeerStep(sku, p) {
    const v = $('zStep-' + sku);
    return v ? _zonaParseCant(v.value, !!(p && p.esGranel)) : 0;
  }
  function zonaStep(sku, delta) {
    const p = S.zonaProductos.find(x => String(x.skuBase || x.idProducto) === sku);
    const v = $('zStep-' + sku);
    if (!v) return;
    const esGranel = !!(p && p.esGranel);
    let n = _zonaParseCant(v.value, esGranel);
    const paso = esGranel ? 0.5 : 1;
    n = Math.max(0, esGranel ? Math.round((n + delta * paso) * 100) / 100 : n + delta);
    v.value = _zonaFmtNumRaw(n, esGranel);
    _zonaSfx('tick');
    _zonaVibrar(20);
  }
  // [MEJORA 4] botón "Cero": setea 0 al instante en el input del stepper.
  function zonaCero(sku) {
    const v = $('zStep-' + sku);
    if (v) { v.value = '0'; try { v.focus(); } catch(_){} }
    _zonaSfx('tick'); _zonaVibrar(20);
  }
  // ¿La zona activa es el ALMACÉN? (ajuste → wh.stock vía mos.almacen_crear_ajuste; ZONA → me.stock_zonas).
  function _zonaEsAlmacen() {
    return _esZonaAlmacen({ idZona: S.zonaActual,
      nombre: ((S.zonaList || []).find(x => (x.idZona || x.id || x.nombre) === S.zonaActual) || {}).nombre });
  }
  // localId/idAjuste ESTABLE por gesto de ajuste de un código (idempotencia dura en backend).
  function _zonaAjusteLocalId(cb) {
    const amb = _zonaEsAlmacen() ? 'ALM' : (S.zonaActual || 'Z');
    return 'RIZAJ_' + amb + '_' + String(cb).replace(/[^A-Za-z0-9]/g, '') + '_' +
      Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8);
  }
  // Aplica el ajuste de UN código según el ámbito (ZONA → SET-ABSOLUTO me.stock_zonas ; ALMACEN → DELTA wh.stock).
  // Devuelve la respuesta cruda de la RPC (o null/throw si falló). El conteo `nuevo` es ABS en la unidad de ESE código.
  async function _zonaAplicarAjusteCodigo(cb, nuevo, localId) {
    if (_zonaEsAlmacen()) {
      return API.zona.almacenAjustar({ zona: S.zonaActual, codProducto: String(cb), conteo: nuevo, idAjuste: localId });
    }
    return API.zona.ajustarStock({ zona: S.zonaActual, codBarra: String(cb), nuevo, localId });
  }
  async function zonaConfirmarAjuste(sku) {
    const p = S.zonaProductos.find(x => String(x.skuBase || x.idProducto) === sku);
    if (!p) return;
    // [MULTI-CÓDIGO] Si el producto tiene >1 código en esta zona/almacén, el stepper único corrompería la suma
    // (escribiría sólo el canónico). Abrir el desglose por código para que el admin cuente cada uno en persona.
    const codigos = Array.isArray(p.codigos) ? p.codigos : [];
    if (codigos.length > 1) {
      _zonaSfx('tick'); _zonaVibrar(20);
      toast('Este producto tiene ' + codigos.length + ' códigos. Cuenta cada uno por separado.', 'info');
      zonaToggleCodigos(sku);   // expande el desglose (abre si está cerrado); inputs por código + ✓ por código
      // re-pintar el stepper a su valor original (no aplicar el set único que rompería la suma).
      _zonaActualizarBotonCard(sku);
      renderZona();
      try { const body = $('zCodBody-' + _zonaSkuId(sku)); if (body) body.scrollIntoView({ behavior: 'smooth', block: 'nearest' }); } catch (_) {}
      return;
    }
    const nuevo = _zonaLeerStep(sku, p);
    const antes = _zonaNum(p.stockZona != null ? p.stockZona : p.stock);
    const card  = $('zcard-' + sku);
    // El código a tocar: si hay 1 código en el desglose, ese; si no, se deja que el backend resuelva el canónico
    // (ZONA) — para ALMACÉN necesitamos el código concreto, así que usamos el único de codigos[] si existe.
    const cbUnico = codigos.length === 1
      ? String(codigos[0].codBarra != null ? codigos[0].codBarra : codigos[0].codigoBarra)
      : null;
    // localId ESTABLE por gesto en vuelo (idempotencia dura backend): un doble-tap / reintento del MISMO ajuste
    // reusa el id → el backend dedupea (no duplica fila de ajuste/movimiento). Se libera al confirmar.
    const localId = p._ajLocalId || (p._ajLocalId = _zonaAjusteLocalId(cbUnico || sku));
    // OPTIMISTA: actualizar memoria + re-render del card al instante
    if (codigos.length === 1) codigos[0].stock = nuevo;
    if (p.stockZona != null) p.stockZona = nuevo; else p.stock = nuevo;
    p.stockNegativo = (nuevo < 0);   // editar a >=0 limpia la alerta (ya no es negativo)
    if (p.esperada != null || p.esperado != null) {
      const esp = _zonaNum(p.esperada != null ? p.esperada : p.esperado);
      p.brecha = Math.max(0, esp - nuevo);
    }
    renderZona();
    _zonaSfx('ok'); _zonaVibrar(30);
    toast('Stock ajustado a ' + _zonaFmtCant(nuevo, p), 'ok');
    // BACKGROUND: ZONA → SET-ABSOLUTO me.stock_zonas ; ALMACEN → DELTA wh.stock (ver api.js cabecera RIZ).
    try {
      let r;
      if (cbUnico) {
        // código concreto conocido (único del desglose) → ruta por código (ZONA o ALMACEN).
        r = await _zonaAplicarAjusteCodigo(cbUnico, nuevo, localId);
      } else if (_zonaEsAlmacen()) {
        // ALMACÉN sin código en el desglose: no podemos resolver el canónico server-side de WH → no aplicar.
        throw new Error('Sin código de almacén para ajustar');
      } else {
        // ZONA sin desglose: el backend resuelve el canónico del skuBase (comportamiento histórico).
        r = await API.zona.ajustarStock({ zona: S.zonaActual, skuBase: sku, nuevo, localId });
      }
      if (r == null || r.ok === false) throw new Error((r && r.error) || 'sin commit');
      delete p._ajLocalId;   // gesto confirmado → liberar el id (un nuevo conteo usará otro)
      _zonaPintarKpis();
    } catch (e) {
      // ROLLBACK + shake
      delete p._ajLocalId;   // fallo → liberar el id; un reintento manual cuenta como gesto nuevo
      if (codigos.length === 1) codigos[0].stock = antes;
      if (p.stockZona != null) p.stockZona = antes; else p.stock = antes;
      p.stockNegativo = (antes < 0);
      if (p.esperada != null || p.esperado != null) {
        const esp = _zonaNum(p.esperada != null ? p.esperada : p.esperado);
        p.brecha = Math.max(0, esp - antes);
      }
      renderZona();
      const c2 = $('zcard-' + sku);
      if (c2) { c2.classList.remove('shake'); void c2.offsetWidth; c2.classList.add('shake'); }
      _zonaSfx('error'); _zonaVibrar([120,40,120]);
      toast('No se pudo ajustar: ' + (e.message || e), 'error');
    }
  }

  // ── [MEJORA 5] Multi-código: disclosure + editar stock por codBarra ───────
  // Abre el desglose por código SIEMPRE (no togglea). Usado por el ✎ en multi-código → muestra el ajuste por
  // código directo (sin stepper global). Idempotente: si ya está abierto, lo deja abierto (re-pinta).
  function _zonaAbrirCodigos(sku) {
    const body = $('zCodBody-' + _zonaSkuId(sku));
    if (!body) return;
    const abierto = body.style.display !== 'none' && body.innerHTML.trim() !== '';
    if (!abierto) zonaToggleCodigos(sku);
  }
  function zonaToggleCodigos(sku) {
    const p = S.zonaProductos.find(x => String(x.skuBase || x.idProducto) === sku);
    if (!p) return;
    const body  = $('zCodBody-' + _zonaSkuId(sku));
    const caret = $('zCodCaret-' + _zonaSkuId(sku));
    if (!body) return;
    const abierto = body.style.display !== 'none' && body.innerHTML.trim() !== '';
    if (abierto) {
      body.style.display = 'none';
      if (caret) caret.textContent = '▸';
      _zonaSfx('tick');
      return;
    }
    const codigos = Array.isArray(p.codigos) ? p.codigos : [];
    body.innerHTML = codigos.length
      ? `<div class="zona-cod-hint">El <b>Esperado ${_esc(_zonaFmtCant(_zonaNum(p.esperada != null ? p.esperada : p.esperado), p, true))}</b> es global del producto (no por código).</div>`
        + codigos.map(c => _zonaCodRowHtml(sku, c, p)).join('')
      : '<div class="zona-cod-hint">Sin códigos individuales.</div>';
    body.style.display = '';
    if (caret) caret.textContent = '▾';
    _zonaSfx('pop'); _zonaVibrar(20);
  }
  // [MEJORA 3] disclosure de códigos del ALMACÉN (solo lectura — el stock de almacén es de WH).
  function zonaToggleCodigosAlmacen(sku) {
    const p = S.zonaProductos.find(x => String(x.skuBase || x.idProducto) === sku);
    if (!p) return;
    const body  = $('zAlmBody-' + _zonaSkuId(sku));
    const caret = $('zAlmCaret-' + _zonaSkuId(sku));
    if (!body) return;
    const abierto = body.style.display !== 'none' && body.innerHTML.trim() !== '';
    if (abierto) {
      body.style.display = 'none';
      if (caret) caret.textContent = '▸';
      _zonaSfx('tick');
      return;
    }
    const cods = Array.isArray(p.codigosAlmacen) ? p.codigosAlmacen : [];
    body.innerHTML = cods.length
      ? `<div class="zona-cod-hint">Stock en <b>almacén central</b> (solo lectura — se gestiona desde WH).</div>`
        + cods.map(c => _zonaAlmRowHtml(c, p)).join('')
      : '<div class="zona-cod-hint">Sin códigos en almacén.</div>';
    body.style.display = '';
    if (caret) caret.textContent = '▾';
    _zonaSfx('pop'); _zonaVibrar(20);
  }
  // [MEJORA 3] Fila de un código de almacén (solo lectura, sin inputs de edición).
  function _zonaAlmRowHtml(c, item) {
    const cb   = String(c.codBarra != null ? c.codBarra : (c.codigoBarra != null ? c.codigoBarra : ''));
    const cbAttr = _esc(cb);
    const desc = _esc(c.descripcion || cb);
    const st   = _zonaFmtCant(c.stock, item, true);
    const equiv = c.esEquivalente ? '<span class="zona-cod-equiv" title="Código equivalente">equiv</span>' : '';
    return `<div class="zona-cod-row zona-cod-row-ro">
      <div class="zona-cod-info">
        <div class="zona-cod-desc">${desc} ${equiv}</div>
        <div class="zona-cod-cb">${cbAttr}</div>
      </div>
      <div class="zona-cod-alm-st"><span class="zona-cod-alm-lbl">almacén</span><b>${_esc(st)}</b></div>
    </div>`;
  }
  function _zonaCodFind(p, cb) {
    const codigos = Array.isArray(p.codigos) ? p.codigos : [];
    return codigos.find(c => String(c.codBarra != null ? c.codBarra : c.codigoBarra) === String(cb));
  }
  function zonaCodCero(sku, cb) {
    const inp = $('zCodIn-' + _zonaSkuId(sku) + '-' + _zonaCodKey(cb));
    if (inp) { inp.value = '0'; try { inp.focus(); } catch(_){} }
    _zonaSfx('tick'); _zonaVibrar(20);
  }
  async function zonaCodGuardar(sku, cb) {
    const p = S.zonaProductos.find(x => String(x.skuBase || x.idProducto) === sku);
    if (!p) return;
    const c = _zonaCodFind(p, cb);
    if (!c) return;
    const inp = $('zCodIn-' + _zonaSkuId(sku) + '-' + _zonaCodKey(cb));
    const nuevo = inp ? _zonaParseCant(inp.value, !!p.esGranel) : 0;
    const antes = _zonaNum(c.stock);
    const card  = $('zcard-' + sku);
    // OPTIMISTA: actualizar el código + recomputar el global (suma de códigos) + re-render.
    c.stock = nuevo;
    _zonaRecalcGlobal(p);
    renderZona();
    // re-abrir el disclosure (renderZona lo cierra) para que se vea el efecto.
    zonaToggleCodigos(sku);
    _zonaSfx('ok'); _zonaVibrar(30);
    toast('Código ajustado a ' + _zonaFmtCant(nuevo, p), 'ok');
    // localId estampado en el código mientras dura el gesto → un reintento del MISMO gesto reusa el id (idempotente).
    const localId = c._ajLocalId || (c._ajLocalId = _zonaAjusteLocalId(cb));
    try {
      // ZONA → SET-ABSOLUTO me.stock_zonas (por código) ; ALMACEN → DELTA wh.stock (por código). Idempotente.
      const r = await _zonaAplicarAjusteCodigo(String(cb), nuevo, localId);
      if (r == null || r.ok === false) throw new Error((r && r.error) || 'sin commit');
      delete c._ajLocalId;   // gesto confirmado → liberar el id (un nuevo conteo del mismo código usará otro)
      _zonaPintarKpis();
    } catch (e) {
      // ROLLBACK + shake
      c.stock = antes;
      _zonaRecalcGlobal(p);
      renderZona();
      const c2 = $('zcard-' + sku);
      if (c2) { c2.classList.remove('shake'); void c2.offsetWidth; c2.classList.add('shake'); }
      _zonaSfx('error'); _zonaVibrar([120,40,120]);
      toast('No se pudo ajustar el código: ' + (e.message || e), 'error');
    }
  }
  // Recalcula el stock global del producto (suma de sus códigos) + brecha/negativo derivados.
  function _zonaRecalcGlobal(p) {
    const codigos = Array.isArray(p.codigos) ? p.codigos : [];
    if (codigos.length) {
      const suma = codigos.reduce((a, c) => a + _zonaNum(c.stock), 0);
      const round = p.esGranel ? Math.round(suma * 100) / 100 : Math.round(suma);
      if (p.stockZona != null) p.stockZona = round; else p.stock = round;
    }
    const stock = _zonaNum(p.stockZona != null ? p.stockZona : p.stock);
    p.stockNegativo = (stock < 0);
    if (p.esperada != null || p.esperado != null) {
      const esp = _zonaNum(p.esperada != null ? p.esperada : p.esperado);
      p.brecha = Math.max(0, esp - stock);
    }
  }

  // ── [MEJORA 1] Modal "¿Por qué esperado = X?" (explica picos × 1.2) ───────
  // [900] "¿Por qué esta cantidad?" — ahora con el DETALLE DIARIO real (4 semanas × 7 días).
  //   Muestra lo vendido cada día, resalta el PICO (día más fuerte) de cada semana, y marca cuál se
  //   usa (el de la última). Datos de mos.zona_dias_producto (misma fuente que el pico del panel).
  // Render puro del gráfico (lo usan el modal Y el panel inline de herramientas).
  function _zonaEsperadoRender(p, dias) {
    const esp = _zonaMetaDe(p);   // [916] meta inteligente
    // [925] Explicación FIEL al método real (_zonaMetaSmart): promedio ponderado + tendencia + colchón.
    //   Antes decía "última × 1.2" (regla vieja) aunque el número ya salía del método inteligente.
    const _metaExpl = _zonaMetaExplicaHtml(p, esp);
    if (!Array.isArray(dias) || !dias.length) {
      // Sin ventas diarias (ALMACÉN: es despacho, no venta) → gráfico por SEMANA usando los picos del panel.
      const picos = Array.isArray(p.picos) ? p.picos.slice(-4).map(_zonaNum) : [];
      if (!picos.length) return `<div class="esp-calc"><div class="esp-nums">objetivo <b class="esp-res">${_esc(_zonaFmtCant(esp, p, true))}</b></div></div>`;
      const pu = picos[picos.length - 1];
      const maxP = Math.max(1, ...picos);
      const LBL = ['hace 4 sem', 'hace 3 sem', 'hace 2 sem', 'última sem'].slice(Math.max(0, 4 - picos.length));
      const cols = picos.map((v, i) => {
        const isU = (i === picos.length - 1);
        const h = Math.max(4, Math.round(v / maxP * 88));
        return `<div class="esp-wk${isU ? ' is-used' : ''}${v <= 0 ? ' is-empty' : ''}">
          <div class="esp-wk-bars" style="justify-content:center"><div class="esp-day pk"><div class="esp-day-v">${v > 0 ? _esc(_zonaFmtNumRaw(v, p.esGranel)) : ''}</div><div class="esp-day-bar" style="height:${h}px;width:56%"></div><div class="esp-day-d">sem</div></div></div>
          <div class="esp-wk-foot"><span class="esp-wk-lbl">${LBL[i] || ''}</span><span class="esp-wk-pico">pico ${_esc(_zonaFmtNumRaw(v, p.esGranel))}</span></div>
          ${isU ? '<div class="esp-wk-flag">última</div>' : ''}</div>`;
      }).join('');
      return `<div class="esp-help">Es despacho de almacén (no venta diaria). Cada barra = el <b>pico</b> de esa semana. La meta mira las <b>4 semanas + la tendencia</b>, no solo la última.</div>
        <div class="esp-weeks">${cols}</div>
        <div class="esp-calc">${_metaExpl}</div>`;
    }
    const DOW = ['', 'L', 'M', 'M', 'J', 'V', 'S', 'D'];
    const LBL = ['hace 4 sem', 'hace 3 sem', 'hace 2 sem', 'última sem'];
    const wks = [[], [], [], []];
    dias.forEach(d => { const s = Math.max(0, Math.min(3, d.sem | 0)); wks[s].push(d); });
    const maxAll = Math.max(1, ...dias.map(d => _zonaNum(d.u)));
    const picoUlt = Math.max(0, ...wks[3].map(d => _zonaNum(d.u)));
    let semHtml = '';
    wks.forEach((wk, s) => {
      wk.sort((a, b) => (a.dow | 0) - (b.dow | 0));
      const picoW = Math.max(0, ...wk.map(d => _zonaNum(d.u)));
      const isUsed = (s === 3);
      const bars = wk.map(d => {
        const u = _zonaNum(d.u);
        const h = Math.max(3, Math.round(u / maxAll * 84));
        const isPk = (u > 0 && u === picoW);
        return `<div class="esp-day${isPk ? ' pk' : ''}" title="${DOW[d.dow] || ''} · ${_esc(_zonaFmtNumRaw(u, p.esGranel))}">
          <div class="esp-day-v">${u > 0 ? _esc(_zonaFmtNumRaw(u, p.esGranel)) : ''}</div>
          <div class="esp-day-bar" style="height:${h}px"></div>
          <div class="esp-day-d">${DOW[d.dow] || ''}</div></div>`;
      }).join('');
      semHtml += `<div class="esp-wk${isUsed ? ' is-used' : ''}${picoW <= 0 ? ' is-empty' : ''}">
        <div class="esp-wk-bars">${bars}</div>
        <div class="esp-wk-foot"><span class="esp-wk-lbl">${LBL[s]}</span><span class="esp-wk-pico">pico ${_esc(_zonaFmtNumRaw(picoW, p.esGranel))}</span></div>
        ${isUsed ? '<div class="esp-wk-flag">última</div>' : ''}</div>`;
    });
    return `<div class="esp-help">Cada barra = lo que vendiste ese día. En cada semana marcamos su <b>día más fuerte</b> (el pico). La meta mira las <b>4 semanas + la tendencia</b> (no solo la última).</div>
      <div class="esp-weeks">${semHtml}</div>
      <div class="esp-calc">${_metaExpl}</div>`;
  }
  async function _zonaDiasFetch(sku) {
    try { const r = await API.zona.diasProducto({ zona: S.zonaActual, sku }); return (r && (r.data || r) && (r.data || r).dias) || null; } catch (_) { return null; }
  }
  async function zonaVerEsperado(sku) {
    const p = S.zonaProductos.find(x => String(x.skuBase || x.idProducto) === sku);
    if (!p) return;
    const tit = $('zonaEspTitulo');
    if (tit) tit.textContent = (p.descripcion || p.nombre || sku);
    const body = $('zonaEspBody');
    openModal('modalZonaEsp');
    _zonaSfx('pop'); _zonaVibrar(20);
    if (body) body.innerHTML = '<div class="esp-loading"><span class="esp-spin"></span> Leyendo tus ventas, día por día…</div>';
    const dias = await _zonaDiasFetch(sku);
    if (body) body.innerHTML = _zonaEsperadoRender(p, dias);
  }

  // [901] PANEL INLINE de herramientas: al tocar "🛠 Herramientas" en una card, se despliega abajo con
  //   Ajustar (códigos ±) · ¿Por qué? (gráfico diario) · Historial (kardex compacto). Lazy-load.
  function zonaToggleTools(sku) {
    const wrap = $('zt-' + _zonaSkuId(sku));
    const caret = $('ztCaret-' + _zonaSkuId(sku));
    if (!wrap) return;
    const abierto = wrap.style.display !== 'none' && wrap.dataset.cargado === '1';
    if (abierto) { wrap.style.display = 'none'; if (caret) caret.textContent = '▸'; _zonaSfx('tick'); _zonaVibrar(8); return; }
    wrap.style.display = '';
    if (caret) caret.textContent = '▾';
    _zonaSfx('pop'); _zonaVibrar([15, 10]);
    if (wrap.dataset.cargado !== '1') { wrap.dataset.cargado = '1'; _zonaToolsCargar(sku); }
  }
  async function _zonaToolsCargar(sku) {
    const p = S.zonaProductos.find(x => String(x.skuBase || x.idProducto) === sku);
    if (!p) return;
    const safe = _zonaSkuId(sku);
    // 1) Ajustar códigos (inmediato: data en p.codigos)
    const codBox = $('ztCod-' + safe);
    if (codBox) {
      const cods = Array.isArray(p.codigos) ? p.codigos : [];
      codBox.innerHTML = cods.length ? cods.map(c => _zonaCodRowHtml(sku, c, p)).join('') : '<div class="zona-cod-hint">Un solo código.</div>';
    }
    // 2) ¿Por qué? (gráfico diario, lazy)
    _zonaDiasFetch(sku).then(dias => { const el = $('ztPq-' + safe); if (el) el.innerHTML = _zonaEsperadoRender(p, dias); });
    // 3) Historial (kardex compacto, lazy)
    const hxBox = $('ztHx-' + safe);
    if (hxBox) {
      try {
        const r = await API.zona.kardexHistorial({ skuBase: sku, zona: S.zonaActual });
        const data = (r && r.data) || r || {};
        hxBox.innerHTML = _zonaKardexInlineHtml(data, p);
      } catch (e) { hxBox.innerHTML = '<div class="zt-mut">No se pudo cargar el historial.</div>'; }
    }
  }
  // Lista compacta de movimientos (para el panel inline; el modal completo con pestañas sigue en 🕘).
  function _zonaKardexInlineHtml(data, p) {
    let movs = Array.isArray(data && data.movimientos) ? data.movimientos.slice() : [];
    // [903] multi-código: si el total no trae movimientos, agregamos los de cada código (porCodigo).
    if (!movs.length && data && data.porCodigo && typeof data.porCodigo === 'object') {
      for (const k of Object.keys(data.porCodigo)) { const e = data.porCodigo[k]; if (Array.isArray(e && e.movimientos)) movs = movs.concat(e.movimientos); }
      movs.sort((a, b) => String(b.fecha || '').localeCompare(String(a.fecha || '')));
    }
    movs = movs.slice(0, 8);
    if (!movs.length) return '<div class="zt-mut">Sin movimientos registrados.</div>';
    // [905] Traducción a lenguaje HUMANO (nada de "idem"/jerga). Tipo → etiqueta clara; usuario → persona o "sistema".
    const TIPO = {
      SALIDA_VENTA: ['🛒', 'out', 'Venta'], VENTA: ['🛒', 'out', 'Venta'],
      SALIDA_ZONA: ['🚚', 'out', 'Despacho a zona'], SALIDA_JEFATURA: ['🚚', 'out', 'Despacho'],
      TRASLADO_IN: ['🚚', 'in', 'Llegó de almacén'], TRASLADO_OUT: ['🚚', 'out', 'Salió a zona'], TRASLADO: ['🚚', 'in', 'Traslado'],
      INGRESO_PROVEEDOR: ['📥', 'in', 'Ingreso de proveedor'], INGRESO: ['📥', 'in', 'Ingreso de mercadería'],
      AUDITORIA: ['📋', 'aud', 'Conteo (auditoría)'], AJUSTE: ['✏️', 'aud', 'Ajuste manual'], SALIDA: ['📤', 'out', 'Salida']
    };
    const meses = ['', 'ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'set', 'oct', 'nov', 'dic'];
    const fCorta = (f) => { const s = String(f || '').slice(0, 10); const m = s.match(/^(\d{4})-(\d{2})-(\d{2})/); return m ? (parseInt(m[3], 10) + ' ' + (meses[parseInt(m[2], 10)] || m[2])) : s; };
    const quienDe = (u) => { const s = String(u || '').toLowerCase(); if (!u || u === '—') return 'sistema'; if (s.indexOf('cierre') >= 0 || s.indexOf('idem') >= 0) return 'cierre automático'; if (s.indexOf('sistema') >= 0) return 'sistema'; return u; };
    let rows = movs.map(m => {
      const t = String(m.tipo || '').toUpperCase();
      let meta = TIPO[t]; if (!meta) { for (const k in TIPO) { if (t.indexOf(k) === 0) { meta = TIPO[k]; break; } } }
      meta = meta || ['•', 'aud', (t.replace(/_/g, ' ').toLowerCase() || 'movimiento')];
      let [ic, cls, lbl] = meta;
      const usr = String(m.usuario || '');
      if (usr.toLowerCase().indexOf('cierre') >= 0 || usr.toLowerCase().indexOf('idem') >= 0) { ic = '🌙'; lbl = 'Cierre del día'; cls = 'aud'; }
      const quien = quienDe(usr);
      // [935] Delta robusto para AMBOS kardex: el de ZONA trae `delta`/`saldo_despues`; el de ALMACÉN trae
      //   `cantidad`+`esIngreso`+`saldo` (antes → undefined `delta` → salía "sin cambio" aunque sí cambió).
      let delta = (m.delta != null) ? _zonaNum(m.delta) : null;
      if (delta == null) {
        const cant = _zonaNum(m.cantidad);
        if (m.esIngreso === true) delta = cant;
        else if (m.esIngreso === false) delta = -cant;
        else if (m.saldo != null && m.stockAntes != null) delta = _zonaNum(m.saldo) - _zonaNum(m.stockAntes);
        else delta = 0;
      }
      const saldo = (m.saldo_despues != null) ? _zonaNum(m.saldo_despues) : (m.saldo != null ? _zonaNum(m.saldo) : null);
      const dTxt = delta === 0 ? 'sin cambio' : ((delta > 0 ? '+' : '−') + _esc(_zonaFmtNumRaw(Math.abs(delta), p && p.esGranel)));
      const dCls = delta < 0 ? 'neg' : (delta > 0 ? 'pos' : 'zero');
      const queda = (saldo != null && delta !== 0) ? ` <small>queda ${_esc(_zonaFmtNumRaw(saldo, p && p.esGranel))}</small>` : '';
      const cod = m.cod_barra ? ` <span class="zt-hx-cod">${_esc(String(m.cod_barra))}</span>` : '';
      return `<div class="zt-hx-row${delta === 0 ? ' is-zero' : ''}">
        <span class="zt-hx-ic ${cls}">${ic}</span>
        <span class="zt-hx-lbl">${_esc(lbl)} <small>· ${_esc(quien)}</small>${cod}</span>
        <span class="zt-hx-delta ${dCls}">${dTxt}${queda}</span>
        <span class="zt-hx-date">${_esc(fCorta(m.fecha))}</span>
      </div>`;
    }).join('');
    const hayCierre = movs.some(m => String(m.usuario || '').toLowerCase().indexOf('cierre') >= 0 || String(m.usuario || '').toLowerCase().indexOf('idem') >= 0);
    return rows + (hayCierre ? '<div class="zt-hx-note">🌙 «Cierre del día» = corte automático de fin de jornada (no cambia el stock).</div>' : '');
  }
  function zonaCerrarEsperado() { closeModal('modalZonaEsp'); }

  // ══ [RIZ CARRITO] Pedido a almacén por CARRITO (un paquete = un pickup con N líneas) ════════════════════
  //   "Pedir" en el card YA NO envía: AGREGA al carrito flotante de la zona. El carrito (modal) permite
  //   editar cantidad (+/−), quitar, vaciar y "Enviar pedido" (manda TODO en un solo paquete idempotente).
  //   El estado "Pedido hoy/ayer" persiste en Supabase (me.zona_pedido_log) y el panel lo devuelve.

  // mapa carrito de la zona activa (se crea perezosamente). Clave = skuBase.
  function _zonaCart() {
    const z = S.zonaActual || '_';
    if (!S._zonaCarrito[z]) S._zonaCarrito[z] = {};
    return S._zonaCarrito[z];
  }
  function _zonaCarritoCant(sku) { const c = _zonaCart()[String(sku)]; return c ? _zonaNum(c.cantidad) : 0; }
  function _zonaCarritoNItems() { return Object.keys(_zonaCart()).length; }

  // AGREGAR (o sumar la sugerencia a) un producto al carrito. cantidad = brecha sugerida (puede ser 0 → mete 1
  // como mínimo accionable para que el admin lo vea en el carrito y ajuste). Re-agregar suma la sugerencia.
  function zonaPedirAlmacen(sku, cantidad) {
    sku = String(sku);
    const p = S.zonaProductos.find(x => String(x.skuBase || x.idProducto) === sku);
    if (!p) return;
    const esGranel = !!p.esGranel;
    let add = _zonaNum(cantidad);
    if (!(add > 0)) add = esGranel ? 0.5 : 1;   // si no hay brecha, agrega 1 unidad accionable
    const cart = _zonaCart();
    const ya = cart[sku] ? _zonaNum(cart[sku].cantidad) : 0;
    const nueva = esGranel ? Math.round((ya + add) * 100) / 100 : (ya + add);
    cart[sku] = { sku, nombre: String(p.descripcion || p.nombre || sku), cantidad: nueva, esGranel };
    // feedback inmediato + actualizar SOLO el botón de este card (sin re-render completo, preserva scroll).
    _zonaSfx('pop'); _zonaVibrar([40,30,40]);
    const btn = $('zPedir-' + sku);
    const card = $('zcard-' + sku);
    if (btn) {
      btn.classList.remove('zona-pedido-ok');
      btn.classList.add('zona-en-carrito');
      btn.innerHTML = '🛒 En carrito (' + _esc(_zonaFmtCant(nueva, p)) + ') · +';
      btn.setAttribute('onclick', `MOS.zonaPedirAlmacen('${_zonaEsc(sku)}', ${(p.brecha != null ? _zonaNum(p.brecha) : 0)})`);
    }
    if (card) { card.classList.remove('pulse-ok'); void card.offsetWidth; card.classList.add('pulse-ok'); }
    toast('Agregado al pedido', 'ok');
    _zonaCarritoSync();   // refrescar FAB/badge + (si está abierto) el cuerpo del carrito
  }

  // Refresca el FAB flotante (visible solo con >=1 ítem) + badge + cuerpo del modal si está abierto.
  function _zonaCarritoSync() {
    const n = _zonaCarritoNItems();
    const fab = $('zonaCartFab'), badge = $('zonaCartBadge');
    if (fab) {
      fab.classList.toggle('hidden', !(n > 0 && S.view === 'zona'));
      if (n > 0) { fab.classList.remove('zona-cart-bump'); void fab.offsetWidth; fab.classList.add('zona-cart-bump'); }
    }
    if (badge) badge.textContent = String(n);
    const modal = $('modalZonaCart');
    if (modal && modal.classList.contains('open')) _zonaCarritoRender();
  }

  function zonaCarritoAbrir() {
    if (!_zonaCarritoNItems()) { toast('Carrito vacío', 'info'); return; }
    const zt = $('zonaCartZona');
    if (zt) { const zo = (S.zonaList || []).find(x => (x.idZona || x.id || x.nombre) === S.zonaActual); zt.textContent = 'Zona ' + ((zo && zo.nombre) || S.zonaActual || ''); }
    _zonaCarritoRender();
    openModal('modalZonaCart');
    _zonaSfx('pop'); _zonaVibrar(20);
  }
  function zonaCarritoCerrar() { closeModal('modalZonaCart'); }

  function _zonaCarritoRender() {
    const body = $('zonaCartBody');
    if (!body) return;
    const cart = _zonaCart();
    const skus = Object.keys(cart);
    const enviar = $('zonaCartEnviar'), vaciar = $('zonaCartVaciar');
    if (!skus.length) {
      body.innerHTML = '<div class="zona-cart-empty">🛒 Tu pedido está vacío.<br>Agrega productos desde los cards.</div>';
      if (enviar) enviar.disabled = true;
      if (vaciar) vaciar.disabled = true;
      return;
    }
    if (enviar) enviar.disabled = false;
    if (vaciar) vaciar.disabled = false;
    body.innerHTML = skus.map(sku => {
      const it = cart[sku];
      const e = _zonaEsc(sku);
      const step = it.esGranel ? '0.5' : '1';
      const val = _zonaFmtNumRaw(_zonaNum(it.cantidad), it.esGranel);
      return `<div class="zona-cart-row" id="zCartRow-${_esc(sku)}">
        <button class="zona-cart-del" onclick="MOS.zonaCarritoQuitar('${e}')" title="Quitar">🗑</button>
        <div class="zona-cart-info">
          <div class="zona-cart-nm">${_esc(it.nombre)}</div>
          <div class="zona-cart-hint">${_esc(sku)}</div>
        </div>
        <div class="zona-cart-stepper">
          <button class="zona-cart-step" onclick="MOS.zonaCarritoStep('${e}',-1)">−</button>
          <input type="number" inputmode="decimal" step="${step}" min="0" class="zona-cart-qty" id="zCartQty-${_esc(sku)}" value="${_esc(val)}" onchange="MOS.zonaCarritoSet('${e}', this.value)">
          <button class="zona-cart-step" onclick="MOS.zonaCarritoStep('${e}',1)">+</button>
        </div>
      </div>`;
    }).join('');
  }

  function zonaCarritoStep(sku, delta) {
    sku = String(sku);
    const cart = _zonaCart();
    const it = cart[sku];
    if (!it) return;
    const paso = it.esGranel ? 0.5 : 1;
    let n = _zonaNum(it.cantidad) + delta * paso;
    n = Math.max(0, it.esGranel ? Math.round(n * 100) / 100 : n);
    if (n <= 0) { zonaCarritoQuitar(sku); return; }   // bajar a 0 = quitar
    it.cantidad = n;
    const inp = $('zCartQty-' + sku);
    if (inp) inp.value = _zonaFmtNumRaw(n, it.esGranel);
    _zonaSfx('tick'); _zonaVibrar(15);
    _zonaActualizarBotonCard(sku);
  }
  function zonaCarritoSet(sku, valor) {
    sku = String(sku);
    const cart = _zonaCart();
    const it = cart[sku];
    if (!it) return;
    let n = _zonaParseCant(valor, !!it.esGranel);
    n = Math.max(0, n);
    if (n <= 0) { zonaCarritoQuitar(sku); return; }
    it.cantidad = n;
    _zonaSfx('tick'); _zonaVibrar(15);
    _zonaActualizarBotonCard(sku);
  }
  function zonaCarritoQuitar(sku) {
    sku = String(sku);
    const cart = _zonaCart();
    delete cart[sku];
    _zonaSfx('tick'); _zonaVibrar([20,20]);
    const row = $('zCartRow-' + sku);
    if (row) row.remove();
    _zonaActualizarBotonCard(sku);
    _zonaCarritoSync();
  }
  function zonaCarritoVaciar() {
    const cart = _zonaCart();
    const skus = Object.keys(cart);
    skus.forEach(s => delete cart[s]);
    _zonaSfx('tick'); _zonaVibrar([30,30]);
    skus.forEach(_zonaActualizarBotonCard);
    _zonaCarritoSync();
    toast('Pedido vaciado', 'info');
  }
  // Repinta el botón del card de un sku según su estado actual en el carrito (sin re-render completo).
  function _zonaActualizarBotonCard(sku) {
    sku = String(sku);
    const btn = $('zPedir-' + sku);
    if (!btn) return;
    const p = S.zonaProductos.find(x => String(x.skuBase || x.idProducto) === sku);
    const enCarrito = _zonaCarritoCant(sku);
    const brecha = p ? (p.brecha != null ? _zonaNum(p.brecha) : 0) : 0;
    const pedLbl = (p && p.pedidoEstado && p.pedidoEstado.etiqueta) ? String(p.pedidoEstado.etiqueta) : '';
    btn.classList.remove('zona-en-carrito', 'zona-pedido-ok');
    if (enCarrito > 0) {
      btn.classList.add('zona-en-carrito');
      btn.innerHTML = '🛒 En carrito (' + _esc(p ? _zonaFmtCant(enCarrito, p) : enCarrito) + ') · +';
    } else if (pedLbl) {
      // ya pedido (persistido) y sin nada en el carrito → estado "Pedido hoy/ayer", re-pedir con un tap.
      btn.classList.add('zona-pedido-ok');
      btn.innerHTML = '✓ ' + _esc(pedLbl) + ' · re-pedir';
    } else {
      btn.innerHTML = brecha > 0 ? 'Pedir ' + _esc(p ? _zonaFmtCant(brecha, p) : brecha) + ' a almacén' : 'Agregar al pedido';
    }
    btn.setAttribute('onclick', `MOS.zonaPedirAlmacen('${_zonaEsc(sku)}', ${brecha})`);
  }

  // ENVIAR el carrito = UN paquete (un pickup con N líneas). Idempotente por localId del paquete (el reenvío
  // del MISMO carrito no duplica en wh.pickups). Optimista: cierra el modal + toast; si falla, reabre.
  async function zonaCarritoEnviar() {
    if (S._zonaCarritoEnviando) return;       // lock anti doble-tap
    const cart = _zonaCart();
    const skus = Object.keys(cart);
    if (!skus.length) { toast('Carrito vacío', 'info'); return; }
    const items = skus.map(s => ({ skuBase: s, cantidad: _zonaNum(cart[s].cantidad) })).filter(x => x.cantidad > 0);
    if (!items.length) { toast('Sin cantidades válidas', 'error'); return; }
    // localId estable del PAQUETE → idempotencia (reenvío = mismo pickup, no duplica).
    const localId = 'RIZCART_' + (S.zonaActual || 'Z') + '_' + Date.now().toString(36) + '_' + Math.random().toString(36).slice(2, 8);
    S._zonaCarritoEnviando = true;
    const enviar = $('zonaCartEnviar');
    if (enviar) { enviar.disabled = true; enviar.textContent = 'Enviando…'; }
    _zonaSfx('ok'); _zonaVibrar([80,60,80]);
    try {
      const r = await API.zona.pedirAlmacen({ zona: S.zonaActual, items, localId });
      if (r == null || r.ok === false) throw new Error((r && r.error) || 'sin commit');
      // ÉXITO: vaciar carrito de la zona + cerrar modal + refrescar panel (trae pedidoEstado persistido).
      skus.forEach(s => delete cart[s]);
      closeModal('modalZonaCart');
      toast('Pedido enviado a almacén (' + items.length + ' producto' + (items.length > 1 ? 's' : '') + ')', 'ok');
      _zonaCarritoSync();
      skus.forEach(_zonaActualizarBotonCard);
      setTimeout(() => { _zonaAutoRefrescar(); }, 700);
    } catch (e) {
      _zonaSfx('error'); _zonaVibrar([120,40,120]);
      toast('No se pudo enviar, reintenta', 'error');
    } finally {
      S._zonaCarritoEnviando = false;
      if (enviar) { enviar.disabled = false; enviar.textContent = 'Enviar pedido'; }
    }
  }

  // + Lista compras: [Capa 5] cableado a mos.zona_lista_compras (lectura). La RPC arma/lee la lista
  // de compra externa de la semana; mostramos confirmación con el conteo real. Optimista + rollback de toast.
  // Semana ISO-8601 en formato `IYYY-"W"IW` (idéntico al to_char de Postgres que espera me.zona_lista_compras).
  // Week 1 = la que contiene el primer jueves del año; lunes es el primer día. Devuelve p.ej. "2026-W25".
  function _zonaSemanaISO(d) {
    const dt = new Date(d || Date.now());
    // normalizar a medianoche UTC del día (evita corrimientos por TZ/horario)
    const t = new Date(Date.UTC(dt.getFullYear(), dt.getMonth(), dt.getDate()));
    // jueves de esta semana (ISO: lunes=1..domingo=7); el año del jueves es el año ISO
    const day = t.getUTCDay() || 7;            // domingo(0) → 7
    t.setUTCDate(t.getUTCDate() + 4 - day);     // mover al jueves de la semana
    const isoYear = t.getUTCFullYear();
    const yearStart = new Date(Date.UTC(isoYear, 0, 1));
    const week = Math.ceil((((t - yearStart) / 86400000) + 1) / 7);
    return isoYear + '-W' + String(week).padStart(2, '0');
  }

  async function zonaAgregarLista(sku, cantidad) {
    _zonaSfx('pop'); _zonaVibrar(20);
    toast('Agregado a lista de compras (' + _zonaNum(cantidad) + ')', 'ok');
    // BACKGROUND: confirmar contra la lista real de la semana (lectura). Si falla, solo logueamos (el optimista ya cerró).
    try {
      // ⚠ me.zona_lista_compras EXIGE `semana` en formato ISO `IYYY-"W"IW` (== to_char de Postgres);
      //   sin él devolvía ok:false y la lista nunca se armaba/persistía. Lo calculamos aquí.
      const r = await API.zona.listaCompras({ zona: S.zonaActual, semana: _zonaSemanaISO() });
      const data = (r && r.data) || r || {};
      const items = Array.isArray(data.items) ? data.items : (Array.isArray(data.productos) ? data.productos : (Array.isArray(data) ? data : []));
      if (items.length) toast('Lista del lunes: ' + items.length + ' producto(s) por comprar', 'info');
    } catch (e) {
      try { console.warn('[RIZ] zonaAgregarLista listaCompras:', e && (e.message || e)); } catch (_) {}
    }
  }

  // ══ [RIZ · CAPA 5] IMPRESIÓN 80mm (Edge riz-print → PrintNode) ══════════
  // Reusa el PrinterPicker universal para elegir impresora (memoria por flowKey), luego dispara la
  // Edge. Optimista: toast "enviado a impresora" + sonido print. Si falla, toast rojo + shake del botón.
  // Fecha de HOY en TZ Perú como 'YYYY-MM-DD' (NO toISOString → eso es UTC y a las <19:00 local
  // devolvería el día equivocado). en-CA + timeZone:'America/Lima' produce 'YYYY-MM-DD' nativo.
  function _zonaFechaHoy() {
    try { return new Date().toLocaleDateString('en-CA', { timeZone: 'America/Lima' }); }
    catch (_) { const d = new Date(); return d.getFullYear() + '-' + String(d.getMonth()+1).padStart(2,'0') + '-' + String(d.getDate()).padStart(2,'0'); }
  }

  // ══ [RIZ #1 · FILTRO "DEL DÍA"] partición diaria del ticket (espeja me.zona_ticket_dia) ══════════════════
  // La fecha activa = HOY (TZ Perú) + offset días. Trabajamos siempre con un Date "calendario" (medianoche
  // local Perú) para evitar corrimientos UTC: tomamos los componentes Y/M/D de Perú y construimos un Date
  // local con esos números (NO new Date(isoString), que interpretaría UTC).
  function _zonaHoyPeru() {
    // 'YYYY-MM-DD' en TZ Lima → Date local con esos componentes (medianoche local, sin corrimiento UTC).
    const s = _zonaFechaHoy();                       // 'YYYY-MM-DD' (Perú)
    const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s);
    if (m) return new Date(+m[1], +m[2] - 1, +m[3]);
    const d = new Date(); return new Date(d.getFullYear(), d.getMonth(), d.getDate());
  }
  // Fecha activa del filtro = hoy Perú + offset días (Date calendario local).
  function _zonaDiaActiva() {
    const base = _zonaHoyPeru();
    const off = (S._zonaDiaFiltro && S._zonaDiaFiltro.offset) || 0;
    return new Date(base.getFullYear(), base.getMonth(), base.getDate() + off);
  }
  // 'YYYY-MM-DD' de un Date calendario (sin TZ — ya son componentes locales Perú).
  function _zonaFechaStr(d) {
    return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
  }
  // Etiqueta amable del día activo, ej. "vie 19 jun". Si offset 0 → "hoy", −1 → "ayer", +1 → "mañana".
  function _zonaDiaLabel() {
    const d = _zonaDiaActiva();
    const off = (S._zonaDiaFiltro && S._zonaDiaFiltro.offset) || 0;
    const dias = ['dom', 'lun', 'mar', 'mié', 'jue', 'vie', 'sáb'];
    const mes  = ['ene', 'feb', 'mar', 'abr', 'may', 'jun', 'jul', 'ago', 'sep', 'oct', 'nov', 'dic'];
    const base = dias[d.getDay()] + ' ' + d.getDate() + ' ' + mes[d.getMonth()];
    if (off === 0) return base + ' · hoy';
    if (off === -1) return base + ' · ayer';
    if (off === 1) return base + ' · mañana';
    return base;
  }
  // Set de skuBase (Set<string>) de la TANDA del día activo, traída del backend (me.zona_ticket_dia) para que
  // el filtro COINCIDA EXACTAMENTE con lo que imprime el ticket de ese día (misma partición anclada al lunes).
  // Cache por (zona, fecha). Devuelve null si no se pudo cargar (el render entonces no filtra → muestra todo).
  async function _zonaDiaCargarSet() {
    const zona = S.zonaActual, fecha = _zonaFechaStr(_zonaDiaActiva());
    const key = String(zona) + '|' + fecha;
    if (S._zonaDiaSetKey === key && S._zonaDiaSet) return S._zonaDiaSet;
    try {
      const r = await API.zona.ticketDia({ zona, fecha });
      const data = (r && r.data) || r || {};
      const set = new Set();
      const lotes = Array.isArray(data.lotes) ? data.lotes : [];
      lotes.forEach(lo => (Array.isArray(lo.items) ? lo.items : []).forEach(it => {
        const sk = String(it.skuBase || it.sku || '');
        if (sk) set.add(sk);
      }));
      S._zonaDiaSetKey = key; S._zonaDiaSet = set;
      return set;
    } catch (e) {
      try { console.warn('[RIZ] _zonaDiaCargarSet:', e && (e.message || e)); } catch (_) {}
      return null;
    }
  }

  async function _zonaImprimirFlow(tipo, label, fechaExplicita) {
    // [RIZ #2 · doble-tap] Guard de re-entrancia: el ícono 🖨️ del grupo (y los botones de lista) son
    //   pequeños y táctiles → un doble-tap rápido podía disparar DOS jobs (sobre todo cuando la impresora
    //   está cacheada online y abrirPrinterPicker resuelve sin abrir modal). Bloqueamos hasta que el flujo
    //   actual termine. No es dinero, pero evita doble ticket / desperdicio de papel y confusión.
    if (S._zonaPrintBusy) { try { _zonaSfx('tick'); } catch (_) {} return; }
    S._zonaPrintBusy = true;
    try {
    let printerId = null;
    // [2026-06-19 fix impresora-por-ámbito] La memoria de "última impresora" DEBE ser por ZONA,
    // no global por tipo de flow. Antes flowKey='riz_'+tipo era único para todo el ecosistema:
    // si estabas en ALMACÉN imprimías a la impresora que quedó cacheada de ZONA-02 (y como estaba
    // online, abrirPrinterPicker la reusaba sin preguntar). Ahora la clave incluye la zona activa
    // → cada ámbito (ALMACÉN, ZONA-01, ZONA-02…) recuerda SU propia impresora; al cambiar de zona
    // se vuelve a preguntar (o se preselecciona la de esa zona).
    const zonaKey = String(S.zonaActual || 'sin-zona');
    try {
      printerId = await abrirPrinterPicker({
        titulo: '🖨 ' + label,
        subtitulo: 'Zona ' + (S.zonaActual || ''),
        filtroTipo: 'TICKET',
        filtroZona: S.zonaActual,
        flowKey: 'riz_' + tipo + '_' + zonaKey
      });
    } catch (_) { printerId = null; }
    if (!printerId) return;   // usuario canceló
    // OPTIMISTA
    _zonaSfx('ok'); _zonaVibrar(30);
    toast('🖨️ ' + label + ' enviado a impresora', 'ok');
    try {
      // [2026-06-19 fix ticket vacío] Reforzar pasando fecha/semana de HOY (TZ Perú). El RPC ya defaultea
      // a hoy si falta (supabase/184), pero mandarlo explícito evita depender del default y es a prueba de
      // futuros cambios de la Edge. ticket_diario → fecha; lista_compras → semana ISO actual.
      // [RIZ #2] ticket_diario: si el filtro está en "Día X" se imprime ESE día (fechaExplicita); en "Todos"
      //   se imprime HOY por defecto (NO los 177 — evita desperdicio de papel). lista_compras → semana actual.
      const extra = tipo === 'ticket_diario'
        ? { fecha: fechaExplicita || _zonaFechaHoy() }
        : { semana: _zonaSemanaISO() };
      const r = await API.zona.imprimir({ tipo, zona: S.zonaActual, printerId, ...extra });
      if (!r || r.ok === false) throw new Error((r && r.error) || 'sin respuesta');
    } catch (e) {
      _zonaSfx('error'); _zonaVibrar([120,40,120]);
      toast('No se pudo imprimir: ' + (e && (e.message || e)), 'error');
    }
    } finally { S._zonaPrintBusy = false; }
  }
  // [894] zonaImprimirLista ELIMINADA (botón "🖨️ Lista compras" de barra retirado; _zonaImprimirFlow sigue vivo para el ticket del día).

  // ════════════ [P1d] VISTA PICKUP ACUMULADO POR ZONA + HISTORIAL POR DÍA ════════════
  // Lee wh.zona_pickup_detalle (100% Supabase) → la lista única de la zona con, por producto,
  // lo pendiente + el desglose por día (cuánto pidió cada cierre). En vivo.
  function _zpkNum(n){ n = parseFloat(n) || 0; return Number.isInteger(n) ? (''+n) : (''+(Math.round(n*1000)/1000)); }
  function _zpkDiaLbl(f){ try { const d = new Date(String(f).slice(0,10)+'T12:00:00'); return d.toLocaleDateString('es-PE',{weekday:'short',day:'2-digit',timeZone:'America/Lima'}); } catch(_) { return String(f||''); } }
  // [607] día + HORA cuando el evento la trae (el backend ahora manda "YYYY-MM-DDTHH:MM" hora Lima)
  function _zpkFechaLbl(f){
    const s = String(f || '');
    const dia = _zpkDiaLbl(s);
    return (s.length >= 16 && s.charAt(10) === 'T') ? dia + ' · ' + s.slice(11, 16) : dia;
  }
  // [C9] tsDespacho llega ISO con Z (lo sella el front de WH al escanear) → convertir a Lima;
  // tsSolicitud llega naive-Lima ("YYYY-MM-DDTHH:MM") → el slice de _zpkFechaLbl ya es correcto.
  function _zpkTsLbl(f){
    const s = String(f || '');
    if (!s) return '';
    if (s.length > 16 && /(Z|[+-]\d{2}:?\d{2})$/.test(s)) {
      try {
        const d = new Date(s);
        if (!isNaN(d.getTime())) {
          const dia = d.toLocaleDateString('es-PE', { weekday:'short', day:'2-digit', timeZone:'America/Lima' });
          const hm  = d.toLocaleTimeString('es-PE', { hour:'2-digit', minute:'2-digit', hour12:false, timeZone:'America/Lima' });
          return dia + ' · ' + hm;
        }
      } catch(_){}
    }
    return _zpkFechaLbl(s);
  }
  // [790] "hoy / ayer / hace Nd" para el chip de ingreso reciente.
  function _zpkHaceIngLbl(ts){
    try {
      const d = Math.floor((Date.now() - new Date(String(ts).slice(0, 16)).getTime()) / 86400000);
      return d <= 0 ? 'hoy' : d === 1 ? 'ayer' : 'hace ' + d + 'd';
    } catch (_) { return ''; }
  }
  let _zpkLast = { zona: '', modo: 'pickup', data: null };   // [v2.43.379] para imprimir el rezagado
  // [multi-zona] En ALMACÉN el pickup propio no existe (el almacén no se pide a sí mismo:
  // las ZONAS le piden a él). Ahí el overlay abre con PESTAÑAS, una por zona, mostrando
  // la deuda de cada una — el jefe de almacén ve todo el reclamo desde un solo lugar.
  let _zpkTabs = null;   // [{id, nombre, pend?}] o null = modo una-zona normal
  function _zpkEsAlmacen(id){
    const nom = ((S.zonaList || []).find(x => (x.idZona || x.id || x.nombre) === id) || {}).nombre;
    return _esZonaAlmacen({ idZona: id, nombre: nom });
  }
  // [790] PRIORIZADO: mapa sku → ingreso reciente (últimos 3 días, caché 5 min).
  // Si un producto ADEUDADO acaba de ingresar al almacén, el semáforo lo sube y
  // lo pinta con el matiz violeta "🆕 ingresó" — hay mercadería fresca, que salga ya.
  let _zpkIng = null, _zpkIngTs = 0;
  async function _zpkIngAsegurar(){
    if (_zpkIng && (Date.now() - _zpkIngTs) < 300000) return;
    try {
      const r = await API.zona.ingresosRecientes({ dias: 3 });
      const m = {};
      (((r && r.items) || [])).forEach(i => { m[String(i.sku)] = i; });
      _zpkIng = m; _zpkIngTs = Date.now();
    } catch (_) { if (!_zpkIng) _zpkIng = {}; }
  }
  // ── [808] OVERLAY EN VIVO (pedido del dueño) ───────────────────────────────
  // Antes el overlay era una FOTO FIJA: se cargaba una vez y nunca más. Si WH emitía una guía
  // de salida con el overlay abierto, MOS seguía mostrando la deuda vieja → el semáforo de
  // urgencia y el ORDEN de la lista quedaban desactualizados justo cuando importan. Ahora:
  //   · poll cada ZPK_POLL_MS de la zona/pestaña ACTIVA + refresco inmediato al recuperar foco;
  //   · SILENCIOSO: el esqueleto solo aparece en la apertura y al cambiar de pestaña;
  //   · repinta SOLO si la firma del contenido cambió (skuBase+pendiente+despachado + total),
  //     y preserva scroll / desglose abierto / texto del buscador alrededor del repintado;
  //   · guarda de GENERACIÓN: una respuesta vieja (cambio de pestaña / cierre) nunca pinta;
  //   · TODO se corta en zonaCerrarPickup (cero timers y cero listeners huérfanos).
  const ZPK_POLL_MS  = 20 * 1000;   // refresco en vivo del overlay abierto
  const ZPK_FRESH_MS = 10 * 1000;   // tick chico que solo reescribe "actualizado hace Ns"
  let _zpkPollTimer = null, _zpkFreshTimer = null, _zpkFocoHandler = null;
  let _zpkGen = 0;                  // contador de generación (anti respuesta-vieja)
  let _zpkSig = '';                 // firma del último contenido PINTADO
  let _zpkOkTs = 0;                 // ts del último refresco EXITOSO (para el indicador honesto)
  let _zpkSinConexion = false;      // el último refresco falló → el dato viejo sigue en pantalla
  let _zpkRefrescando = false;
  // Qué está REALMENTE abierto ahora. No se puede usar _zpkLast para esto: _zpkLast solo se
  // actualiza ante una carga EXITOSA, así que si la apertura falla seguiría apuntando a la
  // zona anterior y el poll refrescaría la zona equivocada bajo el header nuevo.
  let _zpkZonaViva = '', _zpkModoVivo = 'pickup';
  // Firma del contenido: si no cambia, el DOM no se toca (cero parpadeo, cero scroll perdido).
  function _zpkFirma(r){
    const items = (r && r.items) || [];
    return items.map(it => String(it.skuBase || '') + ':' + _zpkNum(it.pendiente) + ':' + _zpkNum(it.despachado)).join('|')
      + '#' + _zpkNum((r && r.total_pendiente) || 0);
  }
  // Indicador honesto junto al chip "en vivo". Sin conexión = el dato es viejo, se dice.
  function _zpkFreshLbl(){
    if (!_zpkOkTs) return _zpkSinConexion ? '· sin conexión' : '';
    const s = Math.max(0, Math.round((Date.now() - _zpkOkTs) / 1000));
    const base = s < 60 ? ('actualizado hace ' + s + 's') : ('actualizado hace ' + Math.floor(s / 60) + ' min');
    return '· ' + base + (_zpkSinConexion ? ' · sin conexión' : '');
  }
  function _zpkPintarFresh(){
    try {
      const el = document.getElementById('zpkFresh');
      if (el) el.textContent = _zpkFreshLbl();
    } catch (_) {}
  }
  function _zpkPollIniciar(){
    _zpkPollDetener();
    _zpkPollTimer  = setInterval(_zpkPollTick, ZPK_POLL_MS);
    _zpkFreshTimer = setInterval(_zpkPintarFresh, ZPK_FRESH_MS);
    _zpkFocoHandler = () => { if (document.visibilityState === 'visible') _zpkPollTick(); };
    window.addEventListener('focus', _zpkFocoHandler);
    document.addEventListener('visibilitychange', _zpkFocoHandler);
  }
  function _zpkPollDetener(){
    if (_zpkPollTimer)  { clearInterval(_zpkPollTimer);  _zpkPollTimer  = null; }
    if (_zpkFreshTimer) { clearInterval(_zpkFreshTimer); _zpkFreshTimer = null; }
    if (_zpkFocoHandler) {
      window.removeEventListener('focus', _zpkFocoHandler);
      document.removeEventListener('visibilitychange', _zpkFocoHandler);
      _zpkFocoHandler = null;
    }
  }
  function _zpkPollTick(){
    // Red de seguridad: si el overlay ya no está en el DOM, el poll se apaga solo.
    if (!document.getElementById('zonaPickupOverlay')) { _zpkPollDetener(); return; }
    if (document.visibilityState !== 'visible') return;
    if (_zpkRefrescando) return;
    if (_zpkModoVivo !== 'pickup' || !_zpkZonaViva) return;   // en rezagado no se poll-ea
    _zpkCargar(_zpkZonaViva, true);
  }
  // silencioso=true → refresco automático: sin esqueleto y sin borrar la vista si falla.
  async function _zpkCargar(zona, silencioso){
    const gen = ++_zpkGen;
    if (!silencioso) {
      _zpkSig = ''; _zpkOkTs = 0; _zpkSinConexion = false;
      _zpkZonaViva = zona; _zpkModoVivo = 'pickup';
      _zpkRender(zona, null, true, 'pickup');
    }
    _zpkRefrescando = true;
    try {
      await _zpkIngAsegurar();
      const r = await API.zona.pickupDetalle({ zona });
      if (gen !== _zpkGen) return;   // cambió de pestaña / se cerró mientras viajaba: NO pintar
      if (!r || r.ok === false) throw new Error((r && r.error) || 'sin datos');
      _zpkLast = { zona, modo: 'pickup', data: r };
      // El badge de la pestaña se actualiza con el dato fresco recién cargado.
      if (_zpkTabs) { const t = _zpkTabs.find(x => x.id === zona); if (t) t.pend = r.total_pendiente || 0; }
      _zpkOkTs = Date.now(); _zpkSinConexion = false;
      const sig = _zpkFirma(r);
      // Nada cambió de verdad → no se toca el DOM (el operador sigue leyendo tranquilo).
      if (silencioso && sig === _zpkSig) { _zpkPintarFresh(); return; }
      _zpkSig = sig;
      _zpkRender(zona, r, false, 'pickup');
    } catch (e) {
      if (gen !== _zpkGen) return;
      // En el refresco automático NUNCA se borra la vista: queda el dato viejo + "sin conexión".
      if (silencioso) { _zpkSinConexion = true; _zpkPintarFresh(); return; }
      _zpkRender(zona, { _error: String(e && e.message || e) }, false, 'pickup');
    } finally { _zpkRefrescando = false; }
  }
  async function zonaAbrirPickup(){
    let zona = S.zonaActual;
    if (!zona) return;
    if (_zpkEsAlmacen(zona)) {
      _zpkTabs = (S.zonaList || [])
        .map(z => ({ id: z.idZona || z.id || z.nombre, nombre: z.nombre || z.idZona || z.id }))
        .filter(z => z.id && !_zpkEsAlmacen(z.id));
      if (!_zpkTabs.length) { toast('Sin zonas para mostrar', 'warn'); return; }
      zona = (_zpkLast && _zpkLast.zona && _zpkTabs.some(t => t.id === _zpkLast.zona))
        ? _zpkLast.zona : _zpkTabs[0].id;
      _zpkPrefetchTabs();
    } else {
      _zpkTabs = null;
    }
    _zpkPollIniciar();   // [808] el overlay queda vivo mientras esté abierto
    await _zpkCargar(zona);
  }
  // Cambio de pestaña (solo existe en modo ALMACÉN). Es una APERTURA: sí muestra esqueleto.
  function zonaPickupTab(z){
    if (!_zpkTabs || !_zpkTabs.some(t => t.id === z)) return;
    _zpkPollIniciar();   // reinicia el reloj del poll sobre la pestaña recién elegida
    _zpkCargar(z);
  }
  // Badges de pendientes por pestaña, en segundo plano y de a una (no martillar la RPC).
  async function _zpkPrefetchTabs(){
    const tabs = _zpkTabs;
    if (!tabs) return;
    for (const t of tabs) {
      if (_zpkTabs !== tabs) return;               // se cerró/reabrió el overlay
      if (t.pend != null) continue;
      try {
        const r = await API.zona.pickupDetalle({ zona: t.id });
        if (r && r.ok !== false) t.pend = r.total_pendiente || 0;
      } catch (_) {}
      const el = document.querySelector('#zonaPickupOverlay .zpk-tab[data-z="' + (window.CSS && CSS.escape ? CSS.escape(String(t.id)) : String(t.id)) + '"] i');
      if (el && t.pend != null) { el.textContent = _zpkNum(t.pend); el.style.display = ''; }
    }
  }
  // [v2.43.379] Rezagado de la semana pasada (lo NO despachado) — misma vista detallada
  // con historial, para reclamos + botón de imprimir (80mm).
  async function zonaAbrirRezagado(zonaArg){
    const zona = zonaArg || S.zonaActual || (_zpkLast && _zpkLast.zona);
    if (!zona) return;
    // [808] El rezagado es una FOTO de la semana pasada (no cambia sola): se corta el poll en vivo
    // y se consume una generación para que un refresco de pickup en vuelo no pise esta vista.
    _zpkPollDetener();
    const gen = ++_zpkGen;
    _zpkSig = ''; _zpkOkTs = 0; _zpkSinConexion = false;
    _zpkZonaViva = zona; _zpkModoVivo = 'rezagado';
    _zpkRender(zona, null, true, 'rezagado');
    try {
      const r = await API.zona.rezagadoDetalle({ zona });
      if (gen !== _zpkGen) return;
      if (!r || r.ok === false) throw new Error((r && r.error) || 'sin datos');
      _zpkLast = { zona, modo: 'rezagado', data: r };
      _zpkRender(zona, r, false, 'rezagado');
    } catch (e) {
      if (gen !== _zpkGen) return;
      _zpkRender(zona, { _error: String(e && e.message || e) }, false, 'rezagado');
    }
  }
  function zonaCerrarPickup(){
    _zpkTabs = null;   // [multi-zona] al cerrar, el prefetch en curso se detiene solo
    _zpkPollDetener(); // [808] cero timers y cero listeners huérfanos
    _zpkGen++;         //        y ninguna respuesta en vuelo puede repintar un overlay muerto
    _zpkSig = ''; _zpkOkTs = 0; _zpkSinConexion = false;
    _zpkZonaViva = ''; _zpkModoVivo = 'pickup';
    const ov = document.getElementById('zonaPickupOverlay');
    if (ov) { ov.classList.remove('zpk-in'); setTimeout(() => { try { ov.remove(); } catch(_){} }, 220); }
  }
  // ── [924] INSIGHTS: leyenda in-app de CÓMO se decide la prioridad, POR PUESTO. ────────────
  // El dueño no quiere los insights escondidos en un doc: un botón junto a Control los muestra en
